-- Reviewed SaaS Grove catalog. Restore into a NEW empty database only.
BEGIN TRANSACTION;
CREATE TABLE application (id TEXT PRIMARY KEY, name TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE application_track (
                  app_id TEXT NOT NULL REFERENCES application(id), track TEXT NOT NULL,
                  PRIMARY KEY(app_id,track), CHECK(track IN ('open_source','commercial')));
CREATE TABLE leaf_application (
                  leaf TEXT NOT NULL, app_id TEXT NOT NULL REFERENCES application(id), PRIMARY KEY(leaf,app_id));
COMMIT;
