INSERT INTO "application" VALUES('github:43160685','Zulip','{"deployment": ["Ubuntu 或 Debian 服务器/虚拟机", "Docker", "DigitalOcean 或 Render 预构建部署"], "features": ["按频道和主题组织持久团队对话，兼顾实时与异步沟通", "以组织、访客角色和自定义权限管理成员与会话空间", "提供原生集成，并支持在 Ubuntu/Debian 或 Docker 环境自托管"], "github_repository_id": 43160685, "homepage": "https://zulip.com", "id": "github:43160685", "leaf_matches": [{"reason": "Zulip 的 README 将产品定义为团队聊天应用，以 topic-based threading 支持实时和异步组织协作；官方部署说明展示可自托管组织服务器，因此与该团队消息工作流直接匹配。", "slug": "team-messaging-application", "source_urls": ["https://raw.githubusercontent.com/zulip/zulip/main/README.md", "https://raw.githubusercontent.com/zulip/zulip/main/docs/production/requirements.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/zulip/zulip/license", "name": "Zulip", "repository_url": "https://github.com/zulip/zulip", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:23.161578+08:00", "kind": "repository_metadata", "sha256": "c5a63c8fb3683fa464b078e8311358dfdf04302dcf6e3ce2027f0b92b8a9748e", "snapshot_path": "sources/c5a63c8fb3683fa464b078e8311358dfdf04302dcf6e3ce2027f0b92b8a9748e.txt", "url": "https://api.github.com/repos/zulip/zulip"}, {"fetched_at": "2026-10-23T16:41:24.981164+08:00", "kind": "license", "sha256": "8039d9ab15ed3e9b85bb50bc9c7978b3b1d667ce7eb3422691bf391d0cf8dabf", "snapshot_path": "sources/8039d9ab15ed3e9b85bb50bc9c7978b3b1d667ce7eb3422691bf391d0cf8dabf.txt", "url": "https://api.github.com/repos/zulip/zulip/license"}, {"fetched_at": "2026-10-23T16:41:27.485162+08:00", "kind": "readme", "sha256": "797053375431ea51df3c156d114ab7fbfdbe8398a0bb8a2d2dc076612b70f34b", "snapshot_path": "sources/797053375431ea51df3c156d114ab7fbfdbe8398a0bb8a2d2dc076612b70f34b.txt", "url": "https://raw.githubusercontent.com/zulip/zulip/main/README.md"}, {"fetched_at": "2026-10-23T16:46:15.699817+08:00", "kind": "documentation", "sha256": "84c7d8f0aa13c7c2591470d34e572771f0212c32e6daed5d72a336c11cc55b32", "snapshot_path": "sources/84c7d8f0aa13c7c2591470d34e572771f0212c32e6daed5d72a336c11cc55b32.txt", "url": "https://raw.githubusercontent.com/zulip/zulip/main/docs/production/requirements.md"}], "summary": "以频道和主题组织团队对话，兼顾实时交流与异步协作；可自托管，也有官方云服务。", "technology_stack": ["Python", "Django", "PostgreSQL", "Redis", "RabbitMQ", "Memcached", "Nginx"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:7569578','Discourse','{"deployment": ["官方 Docker 自托管安装器（生产部署遵循官方安装指南）"], "features": ["创建按主题组织并保留讨论记录的社区论坛", "支持实时聊天、主题和社区成员讨论", "通过主题、插件和自定义主题扩展社区体验"], "github_repository_id": 7569578, "homepage": "https://www.discourse.org", "id": "github:7569578", "leaf_matches": [{"reason": "README 强调运营者可掌控自己的社区站点，并管理主题、插件和外观；这对应组织运营自有成员社区的软件，而非 Discourse 自营的公共消费社交网络。", "slug": "community-platform", "source_urls": ["https://raw.githubusercontent.com/discourse/discourse/main/README.md"]}, {"reason": "Discourse 官方 README 把 “Create discussion topics” 列为用户可执行的操作；官方功能页说明它是扁平论坛、回复沿页面成线排布并可展开上下文，并列出自动/自定义头像与帖子修订历史；官方界面文案给出 “Create Topic” 与 “Posted by <a ...>%{user}</a>”。成员可开启主题、他人随时间异步追加回复、线程持久可读，帖子带显示作者与修订记录，符合在线讨论板。", "slug": "discussion-board", "source_urls": ["https://www.discourse.org/features", "https://raw.githubusercontent.com/discourse/discourse/main/README.md", "https://raw.githubusercontent.com/discourse/discourse/main/config/locales/client.en.yml"]}, {"reason": "README 将 Discourse 描述为可由运营者控制部署位置的 online community platform，并明确列出创建 discussion topics；它提供独立站点和持久主题讨论，符合在线论坛的核心对象。", "slug": "online-forum", "source_urls": ["https://raw.githubusercontent.com/discourse/discourse/main/README.md"]}, {"reason": "Discourse 官方设置文案对 login required 的说明是 “Require authentication to read content on this site, disallow anonymous access”，即整站内容要求登录后才能阅读；同一文案说明 invite only 下新用户必须由受信用户或员工明确邀请、公开注册关闭。整站禁止匿名阅读、仅受邀可加入，加上成员在主题空间内发帖，构成场所层面的成员/非成员边界。", "slug": "private-community-platform", "source_urls": ["https://www.discourse.org/features", "https://raw.githubusercontent.com/discourse/discourse/main/config/locales/server.en.yml"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/discourse/discourse/license", "name": "Discourse", "repository_url": "https://github.com/discourse/discourse", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:24.596158+08:00", "kind": "repository_metadata", "sha256": "4caf8789476d32b29ca9996a72ce9d28a805e132532545a21173e6209c62cc43", "snapshot_path": "sources/4caf8789476d32b29ca9996a72ce9d28a805e132532545a21173e6209c62cc43.txt", "url": "https://api.github.com/repos/discourse/discourse"}, {"fetched_at": "2026-10-23T16:41:26.187053+08:00", "kind": "license", "sha256": "231af2809f1ec2900b5285baf76959f0e6720adc8fc24037b9ce0ed3e97b78d3", "snapshot_path": "sources/231af2809f1ec2900b5285baf76959f0e6720adc8fc24037b9ce0ed3e97b78d3.txt", "url": "https://api.github.com/repos/discourse/discourse/license"}, {"fetched_at": "2026-10-23T16:41:27.478316+08:00", "kind": "readme", "sha256": "7c30c4fae1be0f39526bc6c86c902cd11425611b3c34215f7a1411d6acdbc7f2", "snapshot_path": "sources/7c30c4fae1be0f39526bc6c86c902cd11425611b3c34215f7a1411d6acdbc7f2.txt", "url": "https://raw.githubusercontent.com/discourse/discourse/main/README.md"}, {"fetched_at": "2026-10-24T12:11:46.189053+08:00", "kind": "documentation", "sha256": "afb1f91bb935f9875ef5e9ed6dc20987761963f69ec77492d5fe9d4c4f5392f7", "snapshot_path": "sources/afb1f91bb935f9875ef5e9ed6dc20987761963f69ec77492d5fe9d4c4f5392f7.txt", "url": "https://raw.githubusercontent.com/discourse/discourse/main/config/locales/client.en.yml"}, {"fetched_at": "2026-10-24T12:11:13.136731+08:00", "kind": "documentation", "sha256": "ca75fb2e1dc069781ede88c751635dc09c2284119a5cc264afcfc48fd339b7bc", "snapshot_path": "sources/ca75fb2e1dc069781ede88c751635dc09c2284119a5cc264afcfc48fd339b7bc.txt", "url": "https://raw.githubusercontent.com/discourse/discourse/main/config/locales/server.en.yml"}, {"fetched_at": "2026-10-23T19:32:57.471812+08:00", "kind": "homepage", "sha256": "39819e997b79d7971b100b6dbbbb9b98470193fdc6cca736306b3e90cd74ce32", "snapshot_path": "sources/39819e997b79d7971b100b6dbbbb9b98470193fdc6cca736306b3e90cd74ce32.txt", "url": "https://www.discourse.org/features"}], "summary": "供组织运营自有论坛和讨论社区的开源软件，支持自托管及官方托管。", "technology_stack": ["Ruby on Rails", "Ember.js", "PostgreSQL", "Redis", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:674295265','Docmost','{"deployment": ["Docker（官方推荐）", "Docker Compose 多容器部署", "持久化 PostgreSQL、Redis 与附件存储"], "features": ["多人实时协作编辑页面，并以空间组织文档", "提供权限、群组、评论和页面历史", "支持全文搜索、文件附件及 Draw.io/Excalidraw/Mermaid 图表"], "github_repository_id": 674295265, "homepage": "https://docmost.com", "id": "github:674295265", "leaf_matches": [{"reason": "README 明确称 Docmost 为 collaborative wiki and documentation software，并列出可共同编辑的页面与历史记录；该核心功能与维护可编辑、持久页面知识库的 Wiki 类型一致。", "slug": "wiki-application", "source_urls": ["https://raw.githubusercontent.com/docmost/docmost/main/README.md", "https://docmost.com/docs/installation"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/docmost/docmost/license", "name": "Docmost", "repository_url": "https://github.com/docmost/docmost", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:27.748131+08:00", "kind": "repository_metadata", "sha256": "0ec75610c111aa53b48383099b24dd62cc81b08507d1c0ad643cc71408fcbc64", "snapshot_path": "sources/0ec75610c111aa53b48383099b24dd62cc81b08507d1c0ad643cc71408fcbc64.txt", "url": "https://api.github.com/repos/docmost/docmost"}, {"fetched_at": "2026-10-23T16:41:30.057616+08:00", "kind": "license", "sha256": "c80da8c900b7d3f1f16f0bd37abd9c108cacb23f3f3be31f5b7647d94fb03095", "snapshot_path": "sources/c80da8c900b7d3f1f16f0bd37abd9c108cacb23f3f3be31f5b7647d94fb03095.txt", "url": "https://api.github.com/repos/docmost/docmost/license"}, {"fetched_at": "2026-10-23T16:41:31.969689+08:00", "kind": "readme", "sha256": "dd05f459978695449638d22d53315dfd4cde1f481b3bb48ec50a6f6523f54828", "snapshot_path": "sources/dd05f459978695449638d22d53315dfd4cde1f481b3bb48ec50a6f6523f54828.txt", "url": "https://raw.githubusercontent.com/docmost/docmost/main/README.md"}, {"fetched_at": "2026-10-23T16:45:16.029757+08:00", "kind": "documentation", "sha256": "19581ba828acbe6387583d2c050db8d8772df04ba5408e698903aeadaccc68c9", "snapshot_path": "sources/19581ba828acbe6387583d2c050db8d8772df04ba5408e698903aeadaccc68c9.txt", "url": "https://docmost.com/docs/installation"}], "summary": "协作式 Wiki 与文档应用，支持共同编辑和知识整理。AGPL 适用于开源核心；SSO、AI 等企业功能另行许可。", "technology_stack": ["TypeScript", "Docker", "PostgreSQL", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:568098118','Plane','{"deployment": ["Docker Compose", "Kubernetes/Helm", "自托管服务器或 Plane Cloud（云服务不等同于开源仓库）"], "features": ["创建和跟踪工作项、任务及关联问题", "用 Cycles 管理迭代并查看燃尽进度", "以模块、保存视图和文档页面组织项目工作"], "github_repository_id": 568098118, "homepage": "http://plane.so", "id": "github:568098118", "leaf_matches": [{"reason": "README 明确提供 cycles、work-item 进度与 burn-down charts，并支持产品路线图；这些迭代计划和团队执行视图是敏捷项目管理的直接工作流。", "slug": "agile-project-management-application", "source_urls": ["https://developers.plane.so/self-hosting/overview", "https://raw.githubusercontent.com/makeplane/plane/preview/README.md"]}, {"reason": "官方仓库元数据与README说明Plane创建工作项、任务及关联问题，并支持迭代与项目组织，符合统一问题记录与生命周期。", "slug": "issue-tracker", "source_urls": ["https://api.github.com/repos/makeplane/plane", "https://raw.githubusercontent.com/makeplane/plane/preview/README.md"]}, {"reason": "README 将 Plane 描述为管理任务、sprints/cycles、roadmaps 的项目管理工具；工作项、模块和分析功能使团队能持续规划并跟踪项目工作，直接符合项目管理应用。", "slug": "project-management-application", "source_urls": ["https://developers.plane.so/self-hosting/overview", "https://raw.githubusercontent.com/makeplane/plane/preview/README.md"]}, {"reason": "官方文档 Markdown 源（.md）与仓库资料可证：Work Item States 正文说明每个项目默认自建状态并归入 Backlog/Unstarted/Started/Completed/Cancelled 五组，状态组驱动完成度、周期/模块进度与自动归档（Enterprise Grid 下改为工作区共享状态）；Your Work 正文说明跨项目汇总指派/创建/订阅的工作项，并按状态与优先级分布；Automations 正文说明每个项目内置自动归档与自动关闭，到期提醒标为 Business；Intake 正文说明项目级 Intake 以应用内、公开表单、邮件收集，进入 Triage 后接受/拒绝，其中 Intake responsibility 与 Intake Forms 标为 Business；README 与仓库元数据说明自托管及 Work Items/Cycles/Modules/Views/Pages，许可证为 AGPL-3.0。社区版的自定义自动化、审批链及 Workflows and Approvals 套餐边界未从现有快照核实，不作断言。", "slug": "work-management-platform", "source_urls": ["https://docs.plane.so/core-concepts/issues/states.md", "https://docs.plane.so/your-work.md", "https://docs.plane.so/automations/overview.md", "https://docs.plane.so/intake/overview.md", "https://docs.plane.so/intake/intake-forms.md", "https://developers.plane.so/self-hosting/overview.md", "https://raw.githubusercontent.com/makeplane/plane/preview/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/makeplane/plane/license", "name": "Plane", "repository_url": "https://github.com/makeplane/plane", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:29.038116+08:00", "kind": "repository_metadata", "sha256": "6e9c679a631d2e6ec4b857676792e3af478936db11b188c69ba0d0b92a050aae", "snapshot_path": "sources/6e9c679a631d2e6ec4b857676792e3af478936db11b188c69ba0d0b92a050aae.txt", "url": "https://api.github.com/repos/makeplane/plane"}, {"fetched_at": "2026-10-23T16:41:30.820055+08:00", "kind": "license", "sha256": "29c1503c26ffcb2eaf56c0f06dcbc97667f2f636677fda8149e100be9d656d56", "snapshot_path": "sources/29c1503c26ffcb2eaf56c0f06dcbc97667f2f636677fda8149e100be9d656d56.txt", "url": "https://api.github.com/repos/makeplane/plane/license"}, {"fetched_at": "2026-10-23T16:45:10.062538+08:00", "kind": "documentation", "sha256": "bbb870438eb1ed4609f4654515f84c2ea0844bbec20281e38007eeee61cbc066", "snapshot_path": "sources/bbb870438eb1ed4609f4654515f84c2ea0844bbec20281e38007eeee61cbc066.txt", "url": "https://developers.plane.so/self-hosting/overview"}, {"fetched_at": "2026-10-25T22:44:09.960980+08:00", "kind": "documentation", "sha256": "8095094ee9884538db90098028cd3d2b481ce01265d90d55af5258b86dfb0df8", "snapshot_path": "sources/8095094ee9884538db90098028cd3d2b481ce01265d90d55af5258b86dfb0df8.txt", "url": "https://developers.plane.so/self-hosting/overview.md"}, {"fetched_at": "2026-10-24T12:31:25.509294+08:00", "kind": "documentation", "sha256": "43d3d9ee4fc852587d64de20eb0847b694dc3eb1e0efc556e28888f73a6f4c40", "snapshot_path": "sources/43d3d9ee4fc852587d64de20eb0847b694dc3eb1e0efc556e28888f73a6f4c40.txt", "url": "https://docs.plane.so/automations/overview"}, {"fetched_at": "2026-10-25T22:44:04.899136+08:00", "kind": "documentation", "sha256": "6640f04f2fc7826fbface7677313053e7520d743897f3c0506c7c506647f20e1", "snapshot_path": "sources/6640f04f2fc7826fbface7677313053e7520d743897f3c0506c7c506647f20e1.txt", "url": "https://docs.plane.so/automations/overview.md"}, {"fetched_at": "2026-10-24T11:41:26.950872+08:00", "kind": "documentation", "sha256": "c86c9ffc39f635175ae09779e8bcfcccd706a20b4b0727232735d1c96597b287", "snapshot_path": "sources/c86c9ffc39f635175ae09779e8bcfcccd706a20b4b0727232735d1c96597b287.txt", "url": "https://docs.plane.so/core-concepts/issues/layouts"}, {"fetched_at": "2026-10-24T11:45:02.767802+08:00", "kind": "documentation", "sha256": "61dd8b18fb3cdb2296129ff33b8764db505f084ee5af619a318d84b610237cc6", "snapshot_path": "sources/61dd8b18fb3cdb2296129ff33b8764db505f084ee5af619a318d84b610237cc6.txt", "url": "https://docs.plane.so/core-concepts/issues/states"}, {"fetched_at": "2026-10-25T22:44:00.736513+08:00", "kind": "documentation", "sha256": "b28130bd89ad551c1564d588899ef918a1d2b112047c2854845e1342c5d05798", "snapshot_path": "sources/b28130bd89ad551c1564d588899ef918a1d2b112047c2854845e1342c5d05798.txt", "url": "https://docs.plane.so/core-concepts/issues/states.md"}, {"fetched_at": "2026-10-23T19:34:41.296250+08:00", "kind": "documentation", "sha256": "825d7de2ac6b98cce0c1bf671a6800a2593940ca5f3c00b70ff3ca30cb14aef7", "snapshot_path": "sources/825d7de2ac6b98cce0c1bf671a6800a2593940ca5f3c00b70ff3ca30cb14aef7.txt", "url": "https://docs.plane.so/core-concepts/modules"}, {"fetched_at": "2026-10-24T12:48:01.682312+08:00", "kind": "documentation", "sha256": "c8a75dddd34935ff149a82c53431e9fc4dcc86d484bcfb80c1c3630c9269e5ad", "snapshot_path": "sources/c8a75dddd34935ff149a82c53431e9fc4dcc86d484bcfb80c1c3630c9269e5ad.txt", "url": "https://docs.plane.so/intake/intake-forms"}, {"fetched_at": "2026-10-25T22:44:07.417730+08:00", "kind": "documentation", "sha256": "4433b473786f8b2c972c495c82ff406231c3a9ec1bcaf7c23a41ef446b2f7a8e", "snapshot_path": "sources/4433b473786f8b2c972c495c82ff406231c3a9ec1bcaf7c23a41ef446b2f7a8e.txt", "url": "https://docs.plane.so/intake/intake-forms.md"}, {"fetched_at": "2026-10-24T12:31:27.357551+08:00", "kind": "documentation", "sha256": "0e0650d7dced5951e8810d92c61d473b1026450b0051f5a1218f1f8c5088f71c", "snapshot_path": "sources/0e0650d7dced5951e8810d92c61d473b1026450b0051f5a1218f1f8c5088f71c.txt", "url": "https://docs.plane.so/intake/overview"}, {"fetched_at": "2026-10-25T22:44:06.167969+08:00", "kind": "documentation", "sha256": "e97f2f9b0b3b6b7fb57073a4f302d6d4dc517d6b2d32b8f2d74dcecaf855b78a", "snapshot_path": "sources/e97f2f9b0b3b6b7fb57073a4f302d6d4dc517d6b2d32b8f2d74dcecaf855b78a.txt", "url": "https://docs.plane.so/intake/overview.md"}, {"fetched_at": "2026-10-24T11:42:20.669417+08:00", "kind": "documentation", "sha256": "5fba79160338be0d61ed5eb2fd4a2fe1c67dd756de145319f85c3d44742ccbe6", "snapshot_path": "sources/5fba79160338be0d61ed5eb2fd4a2fe1c67dd756de145319f85c3d44742ccbe6.txt", "url": "https://docs.plane.so/your-work"}, {"fetched_at": "2026-10-25T22:44:03.492114+08:00", "kind": "documentation", "sha256": "f4b1baed698895b7e1ff01d79952bc019693c0a1c057003a9312ac84f41c4482", "snapshot_path": "sources/f4b1baed698895b7e1ff01d79952bc019693c0a1c057003a9312ac84f41c4482.txt", "url": "https://docs.plane.so/your-work.md"}, {"fetched_at": "2026-10-24T11:46:15.504064+08:00", "kind": "documentation", "sha256": "acd9946cbcaaf13e2a572af29a25b0ff4662fe4414462c726ba0a835195becc9", "snapshot_path": "sources/acd9946cbcaaf13e2a572af29a25b0ff4662fe4414462c726ba0a835195becc9.txt", "url": "https://raw.githubusercontent.com/makeplane/plane/master/apps/web/core/components/issues/issue-layouts/kanban/kanban-group.tsx"}, {"fetched_at": "2026-10-23T16:41:32.159762+08:00", "kind": "readme", "sha256": "1527e5cd40ef95906faebb6f795e1260321e8296f97b9cc6365a77983197d677", "snapshot_path": "sources/1527e5cd40ef95906faebb6f795e1260321e8296f97b9cc6365a77983197d677.txt", "url": "https://raw.githubusercontent.com/makeplane/plane/preview/README.md"}], "summary": "用工作项、迭代和文档组织项目的开源社区版应用。商业版与云服务的能力和许可另计。", "technology_stack": ["Typ