INSERT INTO "application" VALUES('github:6899875','OpenProject','{"deployment": ["Linux DEB/RPM 安装", "Docker/Docker Compose", "Kubernetes Helm Chart", "社区版本地或自有服务器部署"], "features": ["管理项目、任务、缺陷和工作包", "使用路线图与甘特图安排和跟踪进度", "记录工时并支持团队协作"], "github_repository_id": 6899875, "homepage": "https://www.openproject.org", "id": "github:6899875", "leaf_matches": [{"reason": "官方README与文档说明OpenProject管理项目、任务、缺陷、版本、里程碑与代码关联，覆盖软件交付工作项与交付容器。", "slug": "engineering-project-management-platform", "source_urls": ["https://api.github.com/repos/opf/openproject", "https://raw.githubusercontent.com/opf/openproject/dev/README.md"]}, {"reason": "官方会议文档正文说明：每一次性/周期性会议是有标题、地点、起止时间与受邀参与者的已识别会议；用户可在草稿模式创建结构化议程（分节与议程项、每项可写备注），会议置为进行中后可对每个议程项人工撰写 outcome（正文明确为 decision、short summary 或 meeting notes，可多条、可编辑与删除），并可关联已有或新建工作包作为后续行动项；会议经草稿—打开—进行中—关闭生命周期，关闭后锁定只读，会议记录可按项目/参与状态筛选并导出 PDF。该会议对象、人工撰写的议程与决定记录及生命周期闭环构成会议记录应用核心；会议模块属社区版基础功能，会议模板为 Enterprise 附加项，不影响核心。", "slug": "meeting-notes-application", "source_urls": ["https://www.openproject.org/docs/user-guide/meetings/", "https://www.openproject.org/docs/user-guide/meetings/one-time-meetings/", "https://www.openproject.org/collaboration-software-features/meeting-management/", "https://www.openproject.org/press/press-release-openproject-16-0-meeting-backlogs/"]}, {"reason": "README 明确列出项目、任务、缺陷、路线图及协作，并称 Community Edition 可自托管；这些是客户持续规划和跟踪自己项目的软件工作流。", "slug": "project-management-application", "source_urls": ["https://raw.githubusercontent.com/opf/openproject/dev/README.md", "https://www.openproject.org/docs/installation-and-operations/installation/docker-compose/", "https://www.openproject.org/docs/installation-and-operations/system-requirements/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/opf/openproject/license", "name": "OpenProject", "repository_url": "https://github.com/opf/openproject", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:40:35.518567+08:00", "kind": "repository_metadata", "sha256": "a9276c52fa9cbd9a9a1cd774eac764ce0fa059721fe101ecd2e4779f2a574d75", "snapshot_path": "sources/a9276c52fa9cbd9a9a1cd774eac764ce0fa059721fe101ecd2e4779f2a574d75.txt", "url": "https://api.github.com/repos/opf/openproject"}, {"fetched_at": "2026-10-23T16:41:29.024615+08:00", "kind": "repository_metadata", "sha256": "e964e78485e428d8018f423b3c33c9070f4667d04d421ca18cb8b81f188a48c9", "snapshot_path": "sources/e964e78485e428d8018f423b3c33c9070f4667d04d421ca18cb8b81f188a48c9.txt", "url": "https://api.github.com/repos/opf/openproject"}, {"fetched_at": "2026-10-23T16:41:31.172531+08:00", "kind": "license", "sha256": "5434a1434d46e5d0e3d78144a424e17579607690cfb774bcaa741abf747781e1", "snapshot_path": "sources/5434a1434d46e5d0e3d78144a424e17579607690cfb774bcaa741abf747781e1.txt", "url": "https://api.github.com/repos/opf/openproject/license"}, {"fetched_at": "2026-10-23T16:41:32.767981+08:00", "kind": "readme", "sha256": "869895442c909b22fc57fd985be5ddc222efc702c2f708bb7d83d41c0522d115", "snapshot_path": "sources/869895442c909b22fc57fd985be5ddc222efc702c2f708bb7d83d41c0522d115.txt", "url": "https://raw.githubusercontent.com/opf/openproject/dev/README.md"}, {"fetched_at": "2026-10-28T09:44:14.543750+08:00", "kind": "documentation", "sha256": "b3439d1e2abd65bd8b1f65531622bcfc7cbb86f10c32a25463e55905468a9c46", "snapshot_path": "sources/b3439d1e2abd65bd8b1f65531622bcfc7cbb86f10c32a25463e55905468a9c46.txt", "url": "https://www.openproject.org/collaboration-software-features/meeting-management/"}, {"fetched_at": "2026-10-28T09:37:31.376417+08:00", "kind": "homepage", "sha256": "e86fc18a7390ef0359af171d6692b4e194ff1c31e70947dadb779af910eb44ac", "snapshot_path": "sources/e86fc18a7390ef0359af171d6692b4e194ff1c31e70947dadb779af910eb44ac.txt", "url": "https://www.openproject.org/community-edition/"}, {"fetched_at": "2026-10-23T16:45:15.920933+08:00", "kind": "documentation", "sha256": "958713df5acada1679a1efc9394f43c63aa9f641a93ef6504fbee1c095ff79e3", "snapshot_path": "sources/958713df5acada1679a1efc9394f43c63aa9f641a93ef6504fbee1c095ff79e3.txt", "url": "https://www.openproject.org/docs/installation-and-operations/installation/docker-compose/"}, {"fetched_at": "2026-10-23T16:45:13.962052+08:00", "kind": "documentation", "sha256": "3f1f5b26826e6fa5ccfc8027fefa676dbc47dc8fc7be8d39b057604f592db0db", "snapshot_path": "sources/3f1f5b26826e6fa5ccfc8027fefa676dbc47dc8fc7be8d39b057604f592db0db.txt", "url": "https://www.openproject.org/docs/installation-and-operations/system-requirements/"}, {"fetched_at": "2026-10-28T09:36:13.349550+08:00", "kind": "documentation", "sha256": "16afc76bd425030a87046df4c146dc09474db4da869568c3d1f75f71f2535297", "snapshot_path": "sources/16afc76bd425030a87046df4c146dc09474db4da869568c3d1f75f71f2535297.txt", "url": "https://www.openproject.org/docs/user-guide/meetings/"}, {"fetched_at": "2026-10-28T09:36:13.586871+08:00", "kind": "documentation", "sha256": "fb85c8e222d4b2b224c1d010d95755ad4477e44cec2b22de5d5d87c7b61cb27c", "snapshot_path": "sources/fb85c8e222d4b2b224c1d010d95755ad4477e44cec2b22de5d5d87c7b61cb27c.txt", "url": "https://www.openproject.org/docs/user-guide/meetings/one-time-meetings/"}, {"fetched_at": "2026-10-28T09:40:00.952990+08:00", "kind": "documentation", "sha256": "48cdb40de1ff51a1c3985c91e9faa61bef777916431a38fb7edfc5e38d0e79c5", "snapshot_path": "sources/48cdb40de1ff51a1c3985c91e9faa61bef777916431a38fb7edfc5e38d0e79c5.txt", "url": "https://www.openproject.org/press/press-release-openproject-16-0-meeting-backlogs/"}], "summary": "面向团队任务、进度与项目协作的开源社区版应用，可自托管；企业附加组件另行提供。", "technology_stack": ["Ruby", "Puma", "Apache", "PostgreSQL", "Docker", "Kubernetes/Helm"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1864233','ERPNext','{"deployment": ["Frappe Cloud 托管", "Docker Compose 自托管（README 快速示例用于试用，生产配置需遵循完整文档）"], "features": ["记录会计交易并生成现金流等财务报表", "跟踪库存、补货、销售订单、客户与供应商及发货履约", "管理生产周期、物料消耗、产能计划与外包制造"], "github_repository_id": 1864233, "homepage": "https://frappe.io/erpnext", "id": "github:1864233", "leaf_matches": [{"reason": "官方 Blanket Order 文档说明该记录承载客户长期承诺：客户、生效与失效日期、逐行承诺数量、谈定费率与条款；同一协议可多次生成销售订单，并累计已订购数量、对比剩余承诺量，仪表盘可下钻关联单据。协议本身不发货、不开票，符合常设商业协议、承诺约束下单与消耗核算的核心。", "slug": "contract-to-order-platform", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/blanket-order"]}, {"reason": "官方README将其明确描述为ERP，并列出同一业务系统中的会计、订单/库存及制造流程，支持财务与运营多功能覆盖的ERP定位。", "slug": "enterprise-resource-planning-erp", "source_urls": ["https://raw.githubusercontent.com/frappe/erpnext/develop/README.md"]}, {"reason": "ERPNext 官方 BOM 文档说明物料清单是制造系统的核心主数据，列出成品所需原料与数量并可多层展开，已提交 BOM 只能取消后新建；batch 文档说明批次物料每笔库存交易都须携带批号并可用保质期状态；Serial No and Batch Traceability Report 支持从成品反查原料批次、从原料批次正查成品去向，财务、采购销售、库存与制造同属一个 ERP 数据核心。", "slug": "food-manufacturing-erp", "source_urls": ["https://docs.frappe.io/erpnext/bill-of-materials", "https://docs.frappe.io/erpnext/serial-and-batch-traceability-report", "https://docs.frappe.io/erpnext/user/manual/en/batch", "https://raw.githubusercontent.com/frappe/erpnext/develop/README.md"]}, {"reason": "官方 README 将会计、库存与制造列在同一 ERP 中；官方 Work Order 文档说明工单由 BOM、Operation、Workstation 生成并连接原材料、WIP、成品仓库事务，符合集成后台+生产定义+生产订单的核心结构。", "slug": "manufacturing-erp", "source_urls": ["https://raw.githubusercontent.com/frappe/erpnext/develop/README.md", "https://docs.frappe.io/erpnext/user/manual/en/manufacturing/work-order"]}, {"reason": "官方 Buying 与 Purchase Order 文档给出申请（可选）→采购订单→收货→采购发票→付款分录的标准链，并说明订单/收货/开票数量匹配与部分收货开票，匹配采购到付款核心。", "slug": "procure-to-pay-platform", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/buying", "https://docs.frappe.io/erpnext/user/manual/en/purchase-order"]}, {"reason": "官方 Buying 文档说明供应商主数据、可选采购申请、采购订单与收货跟踪，Buying workspace 管理待收货/待开票订单，匹配采购管理平台的受控供应商与采购运营核心。", "slug": "procurement-management-platform", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/buying"]}, {"reason": "ERPNext 官方 Purchase Order 文档说明采购订单是正式的商业承诺，包含审批/提交、收货与开票状态、关闭/取消及修订流程，匹配以订单为受控承诺对象的采购订单管理核心；该功能属于 ERP 原生采购模块。", "slug": "purchase-order-management", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/buying", "https://docs.frappe.io/erpnext/user/manual/en/purchase-order"]}, {"reason": "官方 Stock 手册列出仓库设置、收货/交货/调拨等库存事务、Stock Reconciliation 定期盘点对账、序列号与批次、库存估值与报表；配合仓库级库存与物料移动记录，覆盖按地点记录库存、仅经记录变动更改、盘点对账三项核心。", "slug": "retail-inventory-management", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/stock", "https://raw.githubusercontent.com/frappe/erpnext/develop/README.md"]}, {"reason": "官方销售订单手册明确销售订单记录客户承诺：保存为草稿、提交后确认，跟踪已交付与已开票百分比，支持部分交付/开票、客户采购订单号、暂停/恢复，并区分关闭（不再履约）与取消（冲销交易）；符合卖方侧销售订单捕获的核心与生命周期语义。", "slug": "sales-order-capture", "source_urls": ["https://docs.frappe.io/erpnext/user/manual/en/sales-order", "https://raw.githubusercontent.com/frappe/erpnext/develop/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/frappe/erpnext/license", "name": "ERPNext", "repository_url": "https://github.com/frappe/erpnext", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:03.686476+08:00", "kind": "repository_metadata", "sha256": "18d8d79b2ecb719af639ae58fdfe9bde8021ef0752ff2f2d6417eb8358716e30", "snapshot_path": "sources/18d8d79b2ecb719af639ae58fdfe9bde8021ef0752ff2f2d6417eb8358716e30.txt", "url": "https://api.github.com/repos/frappe/erpnext"}, {"fetched_at": "2026-10-23T16:41:36.188837+08:00", "kind": "repository_metadata", "sha256": "b5ea571ad8d6cf4f02c602f1ad5dd94d3fd47dd4348b6b6851afd1b4f2e5e542", "snapshot_path": "sources/b5ea571ad8d6cf4f02c602f1ad5dd94d3fd47dd4348b6b6851afd1b4f2e5e542.txt", "url": "https://api.github.com/repos/frappe/erpnext"}, {"fetched_at": "2026-10-24T22:12:35.226685+08:00", "kind": "repository_metadata", "sha256": "fc60315fba01ca776c83f0d7fa2b261f8fae96238ace235adcbe6d0d3e806f37", "snapshot_path": "sources/fc60315fba01ca776c83f0d7fa2b261f8fae96238ace235adcbe6d0d3e806f37.txt", "url": "https://api.github.com/repos/frappe/erpnext"}, {"fetched_at": "2026-10-23T16:41:37.921886+08:00", "kind": "license", "sha256": "ec31fbeaa841d1ffca36d84e3f1834827a34d639c769f9bc1966b2c39bf53e9c", "snapshot_path": "sources/ec31fbeaa841d1ffca36d84e3f1834827a34d639c769f9bc1966b2c39bf53e9c.txt", "url": "https://api.github.com/repos/frappe/erpnext/license"}, {"fetched_at": "2026-10-26T22:13:50.476868+08:00", "kind": "documentation", "sha256": "ea4008175e2c23f39136bada87c2236af1d691e6dc1c5f88ce1f6fa1db8c071a", "snapshot_path": "sources/ea4008175e2c23f39136bada87c2236af1d691e6dc1c5f88ce1f6fa1db8c071a.txt", "url": "https://docs.frappe.io/erpnext/bill-of-materials"}, {"fetched_at": "2026-10-26T22:11:05.005592+08:00", "kind": "documentation", "sha256": "cd86ac709468a555d08d4d6ae63d1df43fcce536ee3119c07d44f2da24c3d7f5", "snapshot_path": "sources/cd86ac709468a555d08d4d6ae63d1df43fcce536ee3119c07d44f2da24c3d7f5.txt", "url": "https://docs.frappe.io/erpnext/serial-and-batch-traceability-report"}, {"fetched_at": "2026-10-26T22:10:14.759569+08:00", "kind": "documentation", "sha256": "8ad574ee09dda909d0606b4884c466a743d685b57e39c66f36945684e57936da", "snapshot_path": "sources/8ad574ee09dda909d0606b4884c466a743d685b57e39c66f36945684e57936da.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/batch"}, {"fetched_at": "2026-10-24T15:34:49.517596+08:00", "kind": "documentation", "sha256": "0d385d4c4ee526ac91aad7d54935193f9b19222fcad82a019c36ba7a5dc00af3", "snapshot_path": "sources/0d385d4c4ee526ac91aad7d54935193f9b19222fcad82a019c36ba7a5dc00af3.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/blanket-order"}, {"fetched_at": "2026-10-24T21:40:18.488764+08:00", "kind": "documentation", "sha256": "d0290fba07a45d022717be66768cbaf802c8f24e557aaae237cbcd3ee543b1d5", "snapshot_path": "sources/d0290fba07a45d022717be66768cbaf802c8f24e557aaae237cbcd3ee543b1d5.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/buying"}, {"fetched_at": "2026-10-26T19:52:20.601214+08:00", "kind": "documentation", "sha256": "5dc6ae6166c96c205e91a09f88dce0cfd370e6506b600bb96cffcbc8580d2da7", "snapshot_path": "sources/5dc6ae6166c96c205e91a09f88dce0cfd370e6506b600bb96cffcbc8580d2da7.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/manufacturing/work-order"}, {"fetched_at": "2026-10-24T21:35:34.070396+08:00", "kind": "documentation", "sha256": "269283768c6bb713ed6b9628bf80a8b298c73b5d556d3b14d2ecc178eb34e25f", "snapshot_path": "sources/269283768c6bb713ed6b9628bf80a8b298c73b5d556d3b14d2ecc178eb34e25f.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/purchase-order"}, {"fetched_at": "2026-10-26T16:35:04.641981+08:00", "kind": "documentation", "sha256": "1e0b84221386a2a99213ca671fa1e9798b6837deac4c87d607378841ae9bea2c", "snapshot_path": "sources/1e0b84221386a2a99213ca671fa1e9798b6837deac4c87d607378841ae9bea2c.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/sales-order"}, {"fetched_at": "2026-10-24T14:31:13.400804+08:00", "kind": "documentation", "sha256": "81da31e6593764eff799003bbc957d4ad4d8dbe76aaec6102c938cd4388da908", "snapshot_path": "sources/81da31e6593764eff799003bbc957d4ad4d8dbe76aaec6102c938cd4388da908.txt", "url": "https://docs.frappe.io/erpnext/user/manual/en/stock"}, {"fetched_at": "2026-10-23T16:41:40.377244+08:00", "kind": "readme", "sha256": "c7d12496fddc6771a44d9c84dcaa6868eea52ef32aca5a6a68d5b59d88a7022b", "snapshot_path": "sources/c7d12496fddc6771a44d9c84dcaa6868eea52ef32aca5a6a68d5b59d88a7022b.txt", "url": "https://raw.githubusercontent.com/frappe/erpnext/develop/README.md"}], "summary": "整合财务、采购销售、库存与制造流程的开源 ERP，支持自托管和 Frappe Cloud 托管。", "technology_stack": ["Python / JavaScript（Frappe Framework）", "Vue（Frappe UI）", "MariaDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:48769241','Penpot','{"deployment": ["官方云服务 design.penpot.app", "Docker / Kubernetes 自托管"], "features": ["多人实时协作设计，支持浏览器使用与自托管", "使用设计令牌、组件与变体构建设计系统", "通过 Inspect 查看 SVG、CSS 和 HTML，并使用 API、Webhook 与插件集成"], "github_repository_id": 48769241, "homepage": "https://penpot.app", "id": "github:48769241", "leaf_matches": [{"reason": "官方README明确说明团队实时协作、共享设计环境及浏览器或自托管使用方式，符合以多人协作设计文件为工作场所的类型。", "slug": "collaborative-design-platform", "source_urls": ["https://raw.githubusercontent.com/penpot/penpot/develop/README.md"]}, {"reason": "官方帮助中心 Prototyping 章节说明 Penpot 通过连接画板构建交互原型，可添加触发器与动作、定义多流程，并在 View 模式运行和通过链接分享，覆盖屏幕集、交互、运行模式与设计制品定位。", "slug": "interactive-prototype-builder", "source_urls": ["https://help.penpot.app/user-guide/prototyping/"]}, {"reason": "官方README将产品定位为数字产品团队的设计平台，并提供设计系统、组件和开发者Inspect输出，支持界面设计工作流。", "slug": "ui-design-application", "source_urls": ["https://raw.githubusercontent.com/penpot/penpot/develop/README.md"]}], "license": "MPL-2.0", "license_evidence_url": "https://api.github.com/repos/penpot/penpot/license", "name": "Penpot", "repository_url": "https://github.com/penpot/penpot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:41.793964+08:00", "kind": "repository_metadata", "sha256": "a0ea40cd244f5b68c8cabc871b680fa46cb09b247b36f4a5e3f95e787fb96962", "snapshot_path": "sources/a0ea40cd244f5b68c8cabc871b680fa46cb09b247b36f4a5e3f95e787fb96962.txt", "url": "https://api.github.com/repos/penpot/penpot"}, {"fetched_at": "2026-10-24T14:33:42.275360+08:00", "kind": "repository_metadata", "sha256": "d51cd09e7f2fb460b5e8dcc7e757e1b7532c36d54eced3bfd7e68aa2081a0de9", "snapshot_path": "sources/d51cd09e7f2fb460b5e8dcc7e757e1b7532c36d54eced3bfd7e68aa2081a0de9.txt", "url": "https://api.github.com/repos/penpot/penpot"}, {"fetched_at": "2026-10-23T16:41:43.441230+08:00", "kind": "license", "sha256": "a4c9469648ba47bdf09072fe7b426c13d893a0da53a9b8ae69d9d48207b1c8be", "snapshot_path": "sources/a4c9469648ba47bdf09072fe7b426c13d893a0da53a9b8ae69d9d48207b1c8be.txt", "url": "https://api.github.com/repos/penpot/penpot/license"}, {"fetched_at": "2026-10-24T13:46:09.259897+08:00", "kind": "documentation", "sha256": "0b40de1548678a136668f1759a8b6b03cbca868c1eacaf13a6667fb943f3d50d", "snapshot_path": "sources/0b40de1548678a136668f1759a8b6b03cbca868c1eacaf13a6667fb943f3d50d.txt", "url": "https://help.penpot.app/user-guide/prototyping/"}, {"fetched_at": "2026-10-23T16:41:45.151457+08:00", "kind": "readme", "sha256": "8c79712fea5fb2d98462817e65f5eba37ef66f652611da23bc64275ac008ad53", "snapshot_path": "sources/8c79712fea5fb2d98462817e65f5eba37ef66f652611da23bc64275ac008ad53.txt", "url": "https://raw.githubusercontent.com/penpot/penpot/develop/README.md"}], "summary": "面向产品团队的开源协作设计平台，支持浏览器内共同设计、组件与设计系统，并提供开发交付视图。", "technology_stack": ["Clojure", "SVG / CSS / HTML 等 Web 标准"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:71485542','Kimai','{"deployment": ["Kimai Cloud 托管", "Docker 自托管，或通过 SSH、Git 与 Composer 安装"], "features": ["将工时关联客户与项目，并按用户、客户或项目设置费率", "支持多计时器、上下班打卡、标签与多用户协作", "生成工时报表、发票与数据导出"], "github_repository_id": 71485542, "homepage": "https://www.kimai.org", "id": "github:71485542", "leaf_matches": [{"reason": "官方README明确描述按项目记录工作时间，支持多计时器、客户/项目费率及报告，和用户形成并归因工作时间记录的核心相符。", "slug": "time-tracking-application", "source_urls": ["https://raw.githubusercontent.com/kimai/kimai/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/kimai/kimai/license", "name": "Kimai", "repository_url": "https://github.com/kimai/kimai", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:43.061826+08:00", "kind": "repository_metadata", "sha256": "1390ec00ddfc1f413876b4013056c5d5147c8b0696952fb42919f4c595e2937a", "snapshot_path": "sources/1390ec00ddfc1f413876b4013056c5d5147c8b0696952fb42919f4c595e2937a.txt", "url": "https://api.github.com/repos/kimai/kimai"}, {"fetched_at": "2026-10-23T16:41:45.062993+08:00", "kind": "license", "sha256": "e5da88a61d0e1482c1e919af3ea649a4421e0b30a44079d0c03be0d214cad472", "snapshot_path": "sources/e5da88a61d0e1482c1e919af3ea649a4421e0b30a44079d0c03be0d214cad472.txt", "url": "https://api.github.com/repos/kimai/kimai/license"}, {"fetched_at": "2026-10-23T16:41:46.326844+08:00", "kind": "readme", "sha256": "c149b1087ac06e94cbdd71b5e6b75d1e473b7f32a442de73b806e7dcf1e0a2ca", "snapshot_path": "sources/c149b1087ac06e94cbdd71b5e6b75d1e473b7f32a442de73b806e7dcf1e0a2ca.txt", "url": "https://raw.githubusercontent.com/kimai/kimai/main/README.md"}], "summary": "围绕客户和项目记录工时、生成报表与开票的开源应用，支持多用户和自托管，也有云服务。", "technology_stack": ["PHP / Symfony", "Doctrine", "MariaDB / MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:slack','Slack','{"homepage": "https://slack.com/", "id": "commercial:slack", "leaf_matches": [{"reason": "官方产品页明确以团队和项目频道组织可搜索的对话及历史，符合团队消息应用。", "slug": "team-messaging-application", "source_urls": ["https://slack.com/features"]}, {"reason": "官方功能页正文把频道、Huddles 音视频、Canvas、Lists、文件分享、Workflow Builder 与集成共同列为团队协作平台能力，频道可按团队或项目配置。", "slug": "team-workspace-platform", "source_urls": ["https://slack.com/features", "https://slack.com/features/canvas"]}], "name": "Slack", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:44:50.844026+08:00", "kind": "homepage", "sha256": "0b4d7b8d45f5c98a8aba572ec80b0d686cdd68deb136f895874f85b5661a6721", "snapshot_path": "sources/0b4d7b8d45f5c98a8aba572ec80b0d686cdd68deb136f895874f85b5661a6721.txt", "url": "https://slack.com/features"}, {"fetched_at": "2026-10-23T19:35:38.023942+08:00", "kind": "documentation", "sha256": "824d11aba8f0799ca8d3d3f8f3ce4c0d45a3d4f14aa9d635c64bbe0d9dacc390", "snapshot_path": "sources/824d11aba8f0799ca8d3d3f8f3ce4c0d45a3d4f14aa9d635c64bbe0d9dacc390.txt", "url": "https://slack.com/features"}, {"fetched_at": "2026-10-23T19:35:38.314828+08:00", "kind": "documentation", "sha256": "8e53aaf9dda54235bab820c13ce14f587fef57d6d0bff1d14e477798bfeff6ba", "snapshot_path": "sources/8e53aaf9dda54235bab820c13ce14f587fef57d6d0bff1d14e477798bfeff6ba.txt", "url": "https://slack.com/features/canvas"}], "summary": "通过频道组织团队对话、共享资料与协作记录的在线团队通讯产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:notion','Notion','{"homepage": "https://www.notion.com/", "id": "commercial:notion", "leaf_matches": [{"reason": "Notion 官方 Wiki 产品页正文把 Notion 描述为团队集中维护知识的共享 workspace：侧边栏组织 workspace，页面可用拖放方式整理，成员可直接更新页面并用 @ 链接其他页面，搜索可跨团队查找内容；Fine-grained admin roles 管理 workspace membership，Advanced permissions 指定谁可以做什么和创建什么。页面/文档是容器内的主要内容对象，成员资格与分级权限、原生创作、容器内组织与检索四项均成立。本条只按官方商业页面作基本类型记录，不据此推断自托管或开源许可。", "slug": "collaborative-workspace", "source_urls": ["https://www.notion.com/product/wikis"]}, {"reason": "官方Wiki产品页描述团队共同维护公司知识、组织页面和验证内容，符合企业维基。", "slug": "enterprise-wiki", "source_urls": ["https://www.notion.com/product/wikis"]}, {"reason": "官方页面展示集中知识库、搜索和持续更新内容的工作区，符合知识库应用。", "slug": "knowledge-base-application", "source_urls": ["https://www.notion.com/product/wikis"]}], "name": "Notion", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:44:50.674980+08:00", "kind": "homepage", "sha256": "58ac897b9f4c5087325454dae58acfdea54e33fbbc571cf64df28abe4bd6d812", "snapshot_path": "sources/58ac897b9f4c5087325454dae58acfdea54e33fbbc571cf64df28abe4bd6d812.txt", "url": "https://www.notion.com/product/wikis"}], "summary": "将团队文档与知识页面集中组织在共享工作区中的在线协作产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:asana','Asana','{"homepage": "https://asana.com/", "id": "commercial:asana", "leaf_matches": [{"reason": "官方产品资料说明组织项目与任务、安排负责人和截止日期并跟踪项目进展，符合项目管理。", "slug": "project-management-application", "source_urls": ["https://asana.com/"]}, {"reason": "官方 project intake 页说明以统一表单及 Slack/Microsoft 365/Google Workspace 集成收集请求，用标签与规则辅助优先级、自动分配、排期和跟进；页内 FAQ 把 reviewed/scored/approved/scheduled 作为 intake 流程的一般说明，未证明 Asana 内的批准链或按团队产能排期，故不再写成已证能力。portfolios 页说明一键把项目加入组合、按 priority/type 打标签、指派 owner、查看 on-track 状态，并汇总各项目 time spent 与 available budget、用自定义 dashboard 和 workload 视图跟踪与重排。timesheets-budgets 页说明按项目设 user rate，比较估算与实际工时/成本、forecast 项目预算，提供 timesheet approvals 与预算可见性限制。以上仅按商业条目的基本类型匹配记录，不并入开源产品；组合/预算/资源能力的具体套餐归属来自页面方案说明与 FAQ，未在正文逐句核验，故不作确定断言。", "slug": "project-portfolio-management-application", "source_urls": ["https://asana.com/uses/project-intake", "https://asana.com/features/goals-reporting/portfolios", "https://asana.com/features/resource-management/timesheets-budgets"]}, {"reason": "官方正文说明任务是带负责人和截止日期的记录，项目提供 list、calendar、timeline、Gantt、board 等执行视图，My Tasks 汇总指派给个人的工作项，Inbox 汇总指派、截止日期变更与更新；项目作为共享容器，任务更新会同步到其所属的全部项目。", "slug": "task-management-application", "source_urls": ["https://asana.com/features", "https://asana.com/features/project-management"]}, {"reason": "Asana 官方功能页正文把任务、项目、目标、表单请求、规则与工作流描述为跨团队集中管理工作的平台，并说明视图是同一批记录的不同读取方式。", "slug": "work-management-platform", "source_urls": ["https://asana.com/features", "https://asana.com/features/project-management"]}], "name": "Asana", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:46:07.163128+08:00", "kind": "homepage", "sha256": "404d73951717f1e46a8fd05bb01a3d5dd11294d16ca7e69b08ce9f468b9035c6", "snapshot_path": "sources/404d73951717f1e46a8fd05bb01a3d5dd11294d16ca7e69b08ce9f468b9035c6.txt", "url": "https://asana.com/"}, {"fetched_at": "2026-10-23T19:35:36.854090+08:00", "kind": "documentation", "sha256": "a8a71c07cc085435b4b21f28e042285889e0bd4c988fb4f03887273c2f1c1e86", "snapshot_path": "sources/a8a71c07cc085435b4b21f28e042285889e0bd4c988fb4f03887273c2f1c1e86.txt", "url": "https://asana.com/features"}, {"fetched_at": "2026-10-24T11:43:30.720581+08:00", "kind": "documentation", "sha256": "5246bfa6fa3f4e523820478e0d5fd0de09e77c10cfae4e450b36063e9b477e75", "snapshot_path": "sources/5246bfa6fa3f4e523820478e0d5fd0de09e77c10cfae4e450b36063e9b477e75.txt", "url": "https://asana.com/features/goals-reporting/portfolios"}, {"fetched_at": "2026-10-23T19:35:39.613841+08:00", "kind": "documentation", "sha256": "672030f84e4b53b0ceaba3d7d42461a8061d9af7854a19fe371dbec5b152003b", "snapshot_path": "sources/672030f84e4b53b0ceaba3d7d42461a8061d9af7854a19fe371dbec5b152003b.txt", "url": "https://asana.com/features/project-management"}, {"fetched_at": "2026-10-24T11:51:05.779440+08:00", "kind": "documentation", "sha256": "d115d550d3fa28b5428750cf4c619cd03ad1b82f43d941968acc8e3d9d6d1be0", "snapshot_path": "sources/d115d550d3fa28b5428750cf4c619cd03ad1b82f43d941968acc8e3d9d6d1be0.txt", "url": "https://asana.com/features/resource-management/timesheets-budgets"}, {"fetched_at": "2026-10-24T11:46:44.833749+08:00", "kind": "documentation", "sha256": "4d1d76c668c19bb074ec63a5a6b70c812d7f0b95c66fe820cb47cc3791b618a5", "snapshot_path": "sources/4d1d76c668c19bb074ec63a5a6b70c812d7f0b95c66fe820cb47cc3791b618a5.txt", "url": "https://asana.com/uses/project-intake"}], "summary": "围绕项目、任务、责任人与进度组织团队工作的在线项目管理产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:salesforce','Salesforce Sales Cloud','{"homepage": "https://www.salesforce.com/sales/cloud/", "id": "commercial:salesforce", "leaf_matches": [{"reason": "官方Sales Cloud产品页明确管理线索、联系人、客户和商机，符合持续客户关系与销售记录。", "slug": "customer-relationship-management-crm", "source_urls": ["https://www.salesforce.com/sales/cloud/"]}], "name": "Salesforce Sales Cloud", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:44:54.776993+08:00", "kind": "homepage", "sha256": "83874e80047a37f65102b25e3baa041e1c50cadad9069e288b7448f16ecf1a4e", "snapshot_path": "sources/83874e80047a37f65102b25e3baa041e1c50cadad9069e288b7448f16ecf1a4e.txt", "url": "https://www.salesforce.com/sales/cloud/"}], "summary": "集中管理客户、销售线索与商机流程的商业 CRM 产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:typeform','Typeform','{"homepage": "https://www.typeform.com/", "id": "commercial:typeform", "leaf_matches": [{"reason": "官方页面提供在线表单构建器入口及问卷创建、发布与回答收集，符合在线表单应用。", "slug": "online-form-builder", "source_urls": ["https://www.typeform.com/surveys/"]}, {"reason": "Typeform 官方问卷页正文列出问卷/表单构建器、题型与逻辑、发布收集与结果分析入口，覆盖问卷创建与响应闭环。", "slug": "questionnaire-application", "source_urls": ["https://www.typeform.com/surveys/"]}, {"reason": "官方问卷产品页明确创建客户或员工问卷、收集回答并分析结果，符合问卷调查平台。", "slug": "survey-platform", "source_urls": ["https://www.typeform.com/surveys/"]}], "name": "Typeform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:44:53.802442+08:00", "kind": "homepage", "sha256": "2aa255c61fd3a3aa5b212728450771c87106f03cb0b20d85b163e354ca83de5c", "snapshot_path": "sources/2aa255c61fd3a3aa5b212728450771c87106f03cb0b20d85b163e354ca83de5c.txt", "url": "https://www.typeform.com/surveys/"}], "summary": "通过在线表单和问卷收集、整理用户回答的商业产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:calendly','Calendly','{"homepage": "https://calendly.com/", "id": "commercial:calendly", "leaf_matches": [{"reason": "官方产品页明确分享预约链接、由受邀人选择时间并形成会议预约，符合预约管理闭环。", "slug": "appointment-scheduling-application", "source_urls": ["https://calendly.com/"]}], "name": "Calendly", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:44:54.196947+08:00", "kind": "homepage", "sha256": "49249af4ca43f0d605fa27dc98293f498c57cdf304e0643b167eb8da1dc70ec8", "snapshot_path": "sources/49249af4ca43f0d605fa27dc98293f498c57cdf304e0643b167eb8da1dc70ec8.txt", "url": "https://calendly.com/"}], "summary": "通过可分享的预约链接协调可用时间并安排会议的在线预约产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:542931741','Apache Answer','{"deployment": ["Docker 容器自托管；官方安装文档另列服务器安装方式"], "features": ["创建常设问题与回答记录并支持社区参与", "通过投票、采纳与声望机制组织社区问答质量", "提供插件扩展点与 Docker 快速部署"], "github_repository_id": 542931741, "homepage": "https://answer.apache.org", "id": "github:542931741", "leaf_matches": [{"reason": "官方 README 将 Apache Answer 定位为 Q&A platform，可构建 community forum 或 help center，并提供安装文档；其完整社区问答产品直接承载持久问题、回答与社区评价，边界是运营者部署/管理的问答站点。", "slug": "q-a-community", "source_urls": ["https://raw.githubusercontent.com/apache/answer/main/README.md", "https://answer.apache.org/docs/installation", "https://answer.apache.org/docs/questions/", "https://answer.apache.org/docs/reputation/"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/apache/answer/main/LICENSE", "license_review": {"rationale": "已逐字核对仓库完整 LICENSE 文本中的 Apache License, Version 2.0 条款，并以原始许可证文件作为证据。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/apache/answer/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Apache Answer", "repository_url": "https://github.com/apache/answer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "repository_metadata", "sha256": "df96ed9f8837e4b201699cf9df723a6b3ea07ea9ea5b7f33435d188b706c434c", "snapshot_path": "sources/df96ed9f8837e4b201699cf9df723a6b3ea07ea9ea5b7f33435d188b706c434c.txt", "url": "https://github.com/apache/answer"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "readme", "sha256": "73cfb128c13080a437f0a27b4c1f1edc26fa00a658e6ba3493032af297b990fb", "snapshot_path": "sources/73cfb128c13080a437f0a27b4c1f1edc26fa00a658e6ba3493032af297b990fb.txt", "url": "https://raw.githubusercontent.com/apache/answer/main/README.md"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "license", "sha256": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4", "snapshot_path": "sources/c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4.txt", "url": "https://raw.githubusercontent.com/apache/answer/main/LICENSE"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "documentation", "sha256": "2257a713a2b625585347ffd355666dd170cd4865834e7d2a054c33812de32627", "snapshot_path": "sources/2257a713a2b625585347ffd355666dd170cd4865834e7d2a054c33812de32627.txt", "url": "https://answer.apache.org/docs/installation"}, {"fetched_at": "2026-10-23T17:29:32.515252+08:00", "kind": "documentation", "sha256": "c8e4df742669b96e238622d1f03e91ffb1f6ecf0b6f8fd43968f7337e76c486a", "snapshot_path": "sources/c8e4df742669b96e238622d1f03e91ffb1f6ecf0b6f8fd43968f7337e76c486a.txt", "url": "https://answer.apache.org/docs/questions/"}, {"fetched_at": "2026-10-23T17:33:23.977937+08:00", "kind": "documentation", "sha256": "fbc6ae883f574e958c3ab10936e43a1dffc56fa7b77650856883f9a30951c7e9", "snapshot_path": "sources/fbc6ae883f574e958c3ab10936e43a1dffc56fa7b77650856883f9a30951c7e9.txt", "url": "https://answer.apache.org/docs/reputation/"}], "summary": "Apache Answer 为开源问答社区程序；明确其为社区论坛、帮助中心或知识管理应用的核心，未把第三方插件服务纳入许可陈述。", "technology_stack": ["Go", "React/TypeScript", "SQLite（默认安装存储；可按文档配置）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:60243197','Nextcloud Server','{"deployment": ["可自选硬件安装服务器；官方管理文档提供安装指引；也可选择第三方托管商"], "features": ["用户可在自选服务器存储文件并从网页访问", "同步客户端使文件在多台设备间保持一致", "可与他人共享文件并安装额外协作应用"], "github_repository_id": 60243197, "homepage": "https://nextcloud.com", "id": "github:60243197", "leaf_matches": [{"reason": "官方 README 明确提供多设备文件同步，且可自行安装服务器；该产品有可管理用户数据、共享和服务设置的服务器工作台，超出单纯本地同步客户端，适合作为托管/自托管服务实例。", "slug": "file-sync-application", "source_urls": ["https://docs.nextcloud.com/server/latest/admin_manual/installation/index.html", "https://docs.nextcloud.com/server/latest/user_manual/en/files/desktop_mobile_sync.html", "https://raw.githubusercontent.com/nextcloud/server/master/README.md"]}, {"reason": "沿用共享库已有 Nextcloud Server 条目：官方 README 说明可在自选服务器存放文件并从网页访问、用桌面/移动客户端保持多设备一致；官方用户手册的存储配额页说明账户配额如何计算、共享文件计入所有者配额，桌面与移动同步页列出 Windows/macOS/Linux 桌面客户端、Android/iOS 移动客户端及 Web 界面；网页界面页说明可在 Web 端创建文件夹、上传文件/文件夹、下载、重命名、移动、复制、删除与分享。远程主副本、设备无关可达与完整文件操作循环均有官方正文；文件目录索引页仅为导航，不再作为核心工作流证据引用。仓库身份已核，README 的 SPDX 头与贡献条款均写 AGPL-3.0-or-later，COPYING 提供 AGPL v3 全文。", "slug": "personal-cloud-drive", "source_urls": ["https://raw.githubusercontent.com/nextcloud/server/master/README.md", "https://docs.nextcloud.com/server/latest/user_manual/en/files/quota.html", "https://docs.nextcloud.com/server/latest/user_manual/en/files/desktop_mobile_sync.html", "https://docs.nextcloud.com/server/latest/user_manual/en/files/access_webgui.html"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/nextcloud/server/master/COPYING", "license_review": {"rationale": "已核对仓库 COPYING 中 GNU Affero General Public License Version 3 全文与许可条款，SPDX 按 AGPL-3.0 记录。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/nextcloud/server/master/COPYING", "spdx_id": "AGPL-3.0"}, "name": "Nextcloud Server", "repository_url": "https://github.com/nextcloud/server", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "documentation", "sha256": "665a5650a434f638f5cdd4285fca46ef6a4572eb0c51726d5174e40764e02f29", "snapshot_path": "sources/665a5650a434f638f5cdd4285fca46ef6a4572eb0c51726d5174e40764e02f29.txt", "url": "https://docs.nextcloud.com/server/latest/admin_manual/installation/index.html"}, {"fetched_at": "2026-10-27T11:58:07.134294+08:00", "kind": "documentation", "sha256": "82fe75f9f2fbdc332a09b529985b4f500132cb9c4e11e2288b28b8e3fe809a50", "snapshot_path": "sources/82fe75f9f2fbdc332a09b529985b4f500132cb9c4e11e2288b28b8e3fe809a50.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/files/access_webgui.html"}, {"fetched_at": "2026-10-23T17:33:25.192508+08:00", "kind": "documentation", "sha256": "115e92d7f1aa51b647b31bb54b96b96344daee67bfaffe0c9f832cbbeb4f783e", "snapshot_path": "sources/115e92d7f1aa51b647b31bb54b96b96344daee67bfaffe0c9f832cbbeb4f783e.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/files/desktop_mobile_sync.html"}, {"fetched_at": "2026-10-24T12:25:43.497917+08:00", "kind": "documentation", "sha256": "4c7bffcd5a91767646864d16d88ef88c33d42e4efd4b9d85e497af546fda0780", "snapshot_path": "sources/4c7bffcd5a91767646864d16d88ef88c33d42e4efd4b9d85e497af546fda0780.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/files/index.html"}, {"fetched_at": "2026-10-24T12:12:46.805678+08:00", "kind": "documentation", "sha256": "9d4b87407fc0befd505e1b9dbfc47595c73dad5676d62acfdfc595e371c110f7", "snapshot_path": "sources/9d4b87407fc0befd505e1b9dbfc47595c73dad5676d62acfdfc595e371c110f7.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/files/quota.html"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "repository_metadata", "sha256": "52c9fa238b17a11cc6f4935c976ed5908a6e2998de4517759655a09a319f6e58", "snapshot_path": "sources/52c9fa238b17a11cc6f4935c976ed5908a6e2998de4517759655a09a319f6e58.txt", "url": "https://github.com/nextcloud/server"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "license", "sha256": "57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6", "snapshot_path": "sources/57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6.txt", "url": "https://raw.githubusercontent.com/nextcloud/server/master/COPYING"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "readme", "sha256": "694e8653a25b8f50d3bc772bd84b088e72ac56b2477f38134996189f8ab26a2c", "snapshot_path": "sources/694e8653a25b8f50d3bc772bd84b088e72ac56b2477f38134996189f8ab26a2c.txt", "url": "https://raw.githubusercontent.com/nextcloud/server/master/README.md"}], "summary": "开源核心提供个人及组织自托管文件与协作服务；README提到的额外应用/企业订阅不作为该仓库开源范围的泛化保证。", "technology_stack": ["PHP", "JavaScript", "数据库/缓存等按安装部署文档配置"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:357241735','SearXNG','{"deployment": ["官方文档提供自托管安装与配置；本次未执行部署"], "features": ["向多个外部搜索引擎分发查询并聚合结果", "提供网页搜索界面与可配置搜索引擎", "支持部署为可由用户访问的自托管搜索实例"], "github_repository_id": 357241735, "homepage": "https://docs.searxng.org", "id": "github:357241735", "leaf_matches": [{"reason": "官方 README 将 SearXNG 描述为可自托管的 metasearch engine，向多个搜索服务转发请求并聚合结果；它证明无需自有索引也存在完整的元搜索应用，但实际客户工作台与公共搜索中继的边界仍需结合服务运营模式确认。", "slug": "metasearch-engine", "source_urls": ["https://raw.githubusercontent.com/searxng/searxng/master/README.rst"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/searxng/searxng/master/LICENSE", "license_review": {"rationale": "已核对官方仓库完整 LICENSE 的 GNU Affero General Public License Version 3 条款，SPDX 按 AGPL-3.0 记录。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/searxng/searxng/master/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "SearXNG", "repository_url": "https://github.com/searxng/searxng", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "repository_metadata", "sha256": "04c3696c3bba92ac5d9c6548af972670bff6371f7d0aaad2261760ba1c5c0edd", "snapshot_path": "sources/04c3696c3bba92ac5d9c6548af972670bff6371f7d0aaad2261760ba1c5c0edd.txt", "url": "https://github.com/searxng/searxng"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "readme", "sha256": "6a78fb798e890f75c99d2637f83dcdc90bebfdfdc563d24b59b38ef8a673e2ab", "snapshot_path": "sources/6a78fb798e890f75c99d2637f83dcdc90bebfdfdc563d24b59b38ef8a673e2ab.txt", "url": "https://raw.githubusercontent.com/searxng/searxng/master/README.rst"}, {"fetched_at": "2026-10-23T17:15:00+08:00", "kind": "license", "sha256": "57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6", "snapshot_path": "sources/57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6.txt", "url": "https://raw.githubusercontent.com/searxng/searxng/master/LICENSE"}], "summary": "SearXNG 仓库采用 AGPL-3.0；作为元搜索软件核心记录，未将其转发查询所访问的外部搜索服务视为仓库资产。", "technology_stack": ["Python", "Flask", "Redis（可选/部署配置）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1191433381','CommonPub','{"deployment": ["Docker Compose 部署到 VPS，配置 Caddy 与 PostgreSQL", "支持 Docker 主机部署；README描述其自托管实例"], "features": ["运营独立社区空间，包含内容信息流、角色、邀请和审核", "支持活动报名/候补、竞赛评审、学习路径与版本化文档", "通过 ActivityPub 与其他实例联邦交流，同时保留各社区独立性"], "github_repository_id": 1191433381, "homepage": "https://commonpub.io", "id": "github:1191433381", "leaf_matches": [{"reason": "CommonPub README 明确支持运营者拥有的多个独立社区空间，各自有内容、角色、审核、活动和联邦边界，并提供完整Nuxt应用及Docker自托管部署；与客户运营兴趣社群的工作台边界直接相符。", "slug": "interest-community-platform", "source_urls": ["https://raw.githubusercontent.com/commonpub/commonpub/main/README.md"]}], "license": "AGPL-3.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/commonpub/commonpub/main/LICENSE", "license_review": {"rationale": "已核对仓库完整 AGPL-3.0-or-later LICENSE 文本，含 GNU Affero GPL v3 条款，并与 README 标示的版本一致。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/commonpub/commonpub/main/LICENSE", "spdx_id": "AGPL-3.0-or-later"}, "name": "CommonPub", "repository_url": "https://github.com/commonpub/commonpub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T17:17:00+08:00", "kind": "repository_metadata", "sha256": "c85796a095e6e3b1b35d1bcef23fb9b7f38d4e994592026bfe2c8e7fdabb46e4", "snapshot_path": "sources/c85796a095e6e3b1b35d1bcef23fb9b7f38d4e994592026bfe2c8e7fdabb46e4.txt", "url": "https://github.com/commonpub/commonpub"}, {"fetched_at": "2026-10-23T17:17:00+08:00", "kind": "readme", "sha256": "f9f902e360ce5a483777725e03698df3d2a7f7f9013c355c7aed6334118d2cd3", "snapshot_path": "sources/f9f902e360ce5a483777725e03698df3d2a7f7f9013c355c7aed6334118d2cd3.txt", "url": "https://raw.githubusercontent.com/commonpub/commonpub/main/README.md"}, {"fetched_at": "2026-10-23T17:17:00+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/commonpub/commonpub/main/LICENSE"}], "summary": "为创客兴趣组织提供自营社区空间，管理成员角色、持久内容、活动、审核和跨实例联邦；支持以完整Nuxt应用自托管。", "technology_stack": ["TypeScript", "Nuxt 3", "Vue 3", "PostgreSQL 16", "Drizzle ORM", "Redis", "Meilisearch"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:51344082','The Lounge','{"deployment": ["README提供Node.js/Yarn自托管安装与运行方式；官方文档列出稳定版安装选项"], "features": ["以浏览器登录自托管实例并连接IRC网络", "IRC频道提供命名实时对话房间，用户进入/离开频道参与共享消息流", "即使用户离线仍保持IRC连接，并在设备间同步恢复体验"], "github_repository_id": 51344082, "homepage": "https://thelounge.chat", "id": "github:51344082", "leaf_matches": [{"reason": "The Lounge README明确是自托管Web IRC client，并说明总是保持IRC连接、客户端支持跨设备继续会话；IRC频道是可寻址命名房间，参与者加入/离开后向房间共享实时消息，因此符合定义的房间优先聊天结构，client实现形式本身不排除在线Web应用。", "slug": "chat-room-application", "source_urls": ["https://raw.githubusercontent.com/thelounge/thelounge/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/thelounge/thelounge/master/LICENSE", "license_review": {"rationale": "已核对官方仓库完整 MIT License 文本，包括许可授予、保留版权和免责声明条款。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/thelounge/thelounge/master/LICENSE", "spdx_id": "MIT"}, "name": "The Lounge", "repository_url": "https://github.com/thelounge/thelounge", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T17:21:59.853556+08:00", "kind": "repository_metadata", "sha256": "b502db87c27aaf459a4128e5c18078c1b5611d95439e4eca03e8977995707af4", "snapshot_path": "sources/b502db87c27aaf459a4128e5c18078c1b5611d95439e4eca03e8977995707af4.txt", "url": "https://github.com/thelounge/thelounge"}, {"fetched_at": "2026-10-23T17:22:01.235100+08:00", "kind": "readme", "sha256": "54a3627465ef4fde9b8e7efe2258924956ff2c9c9284ef5d7585422879a2b73a", "snapshot_path": "sources/54a3627465ef4fde9b8e7efe2258924956ff2c9c9284ef5d7585422879a2b73a.txt", "url": "https://raw.githubusercontent.com/thelounge/thelounge/master/README.md"}, {"fetched_at": "2026-10-23T17:22:02.507470+08:00", "kind": "license", "sha256": "cf224dcc7deab48cfc3f0dee7cec4ba0132f17feca6b625e1e9eb640e3ef2cb2", "snapshot_path": "sources/cf224dcc7deab48cfc3f0dee7cec4ba0132f17feca6b625e1e9eb640e3ef2cb2.txt", "url": "https://raw.githubusercontent.com/thelounge/thelounge/master/LICENSE"}], "summary": "可自托管的IRC Web应用，持续连接IRC网络并以频道/房间呈现实时对话；客户端界面不改变房间作为用户主要参与对象的核心。", "technology_stack": ["Node.js", "JavaScript", "Vue.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:202291859','Chatwoot','{"deployment": ["官方文档提供自托管部署；README列出Heroku与DigitalOcean部署方式"], "features": ["集中网站实时聊天、邮件和社交渠道中的客户对话到统一收件箱", "维护联系人资料、互动历史、客户分群与支持团队工作区", "发布帮助中心文章和常见问题，支持客服自助分流"], "github_repository_id": 202291859, "homepage": "https://www.chatwoot.com/help-center", "id": "github:202291859", "leaf_matches": [{"reason": "Chatwoot 官方共享收件箱页面展示企业统一收件箱承载网站聊天、邮件、WhatsApp、Instagram 等客户会话，并提供团队私密备注、分配与共享上下文；组织作为会话一方并保留线程记录，符合商业消息应用。仅计 MIT 社区核心。", "slug": "business-messaging-application", "source_urls": ["https://www.chatwoot.com/features/shared-inbox", "https://www.chatwoot.com/hc/user-guide/articles/1677580558-website-live-chat-settings-explained", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md"]}, {"reason": "Chatwoot README明确称其为开源、自托管的客户支持平台，并展示统一多渠道收件箱、联系人记录及帮助中心工作流；仅记录社区核心能力，未把 Captain AI 或 enterprise 目录计入本例。", "slug": "customer-service-platform", "source_urls": ["https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md"]}, {"reason": "Chatwoot 官方网站聊天设置文档说明企业在自有网站发布实时聊天组件，客户发起会话后由企业团队在共享收件箱中处理；企业身份、客户主动入口、双向会话与企业端持久记录成立。仅计 MIT 社区核心。", "slug": "customer-to-business-messaging-application", "source_urls": ["https://www.chatwoot.com/hc/user-guide/articles/1677580558-website-live-chat-settings-explained", "https://www.chatwoot.com/features/shared-inbox", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md"]}, {"reason": "Chatwoot 用户指南说明可创建面向客户的自助帮助中心门户，配置分类与文章并发布；组织撰写语料、读者自助站点与集成编写端三项成立。官方仓库 develop 分支的门户 CRUD 控制器位于 app/（enterprise/ 之外），公开控制器仅在 ChatwootApp.chatwoot_cloud? 为真时检查 help_center 功能开关；enterprise/ 覆盖文件只新增 ssl_status（自定义域名 SSL 检查），未覆盖或移除社区门户 CRUD，因此仅计 MIT 社区核心。", "slug": "help-center", "source_urls": ["https://www.chatwoot.com/hc/user-guide/en/categories/help-center", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/app/controllers/api/v1/accounts/portals_controller.rb", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/app/controllers/public_controller.rb", "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/enterprise/app/controllers/enterprise/api/v1/accounts/portals_controller.rb"]}, {"reason": "README 将 Chatwoot 定位为开源自托管客服平台，统一收件箱覆盖网站聊天、邮件、Facebook、Instagram、WhatsApp、Telegram、SMS 等渠道，并含联系人历史、团队路由与帮助中心；对话记录跨渠道集中，符合全渠道统一工作单元。", "slug": "omnichannel-customer-service-platform", "source_urls": ["https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/chatwoot/chatwoot/license", "license_review": {"rationale": "已解析 GitHub NOASSERTION 许可证快照并核对 LICENSE：enterprise/ 使用独立许可证，第三方组件按原许可；其余仓库核心明确采用 MIT Expat。", "reviewer": "source_research", "scope": "community_core", "source_url": "https://api.github.com/repos/chatwoot/chatwoot/license", "spdx_id": "MIT"}, "name": "Chatwoot", "repository_url": "https://github.com/chatwoot/chatwoot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:23.152371+08:00", "kind": "repository_metadata", "sha256": "743551fd2bb46350802f7032b237aece5cf7c85bb34d827479b92e33ec587b26", "snapshot_path": "sources/743551fd2bb46350802f7032b237aece5cf7c85bb34d827479b92e33ec587b26.txt", "url": "https://api.github.com/repos/chatwoot/chatwoot"}, {"fetched_at": "2026-10-26T16:40:17.726506+08:00", "kind": "repository_metadata", "sha256": "81b95f0f46294f4998a6459294447a116498c7cf52c1b254e60ddc4ccc243e2e", "snapshot_path": "sources/81b95f0f46294f4998a6459294447a116498c7cf52c1b254e60ddc4ccc243e2e.txt", "url": "https://api.github.com/repos/chatwoot/chatwoot"}, {"fetched_at": "2026-10-23T16:41:24.960426+08:00", "kind": "license", "sha256": "473f5cee9673af5417878ac9e7c47fbe5de980387fa114b871dcbbb96b7a00cb", "snapshot_path": "sources/473f5cee9673af5417878ac9e7c47fbe5de980387fa114b871dcbbb96b7a00cb.txt", "url": "https://api.github.com/repos/chatwoot/chatwoot/license"}, {"fetched_at": "2026-10-23T16:41:26.244662+08:00", "kind": "readme", "sha256": "00b1867b3e486325ff35a8d5194e937974a02cab39cbbc0a0d9846e3c1ff1ac7", "snapshot_path": "sources/00b1867b3e486325ff35a8d5194e937974a02cab39cbbc0a0d9846e3c1ff1ac7.txt", "url": "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/README.md"}, {"fetched_at": "2026-10-25T21:14:28.626131+08:00", "kind": "documentation", "sha256": "cba4c8c023d6097c153e5265ded66e30428d0e4e6016c273aa3d48157f604374", "snapshot_path": "sources/cba4c8c023d6097c153e5265ded66e30428d0e4e6016c273aa3d48157f604374.txt", "url": "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/app/controllers/api/v1/accounts/portals_controller.rb"}, {"fetched_at": "2026-10-25T21:14:28.285321+08:00", "kind": "documentation", "sha256": "e307a8b0c1947f1f7346fbf896083fddd94012d9bd15469dcb7da727796d00fe", "snapshot_path": "sources/e307a8b0c1947f1f7346fbf896083fddd94012d9bd15469dcb7da727796d00fe.txt", "url": "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/app/controllers/public_controller.rb"}, {"fetched_at": "2026-10-25T22:23:57.010271+08:00", "kind": "documentation", "sha256": "b4164645fa31069dfe4fb1f4f1473f6340c50d917d9bfe158b253e978c814551", "snapshot_path": "sources/b4164645fa31069dfe4fb1f4f1473f6340c50d917d9bfe158b253e978c814551.txt", "url": "https://raw.githubusercontent.com/chatwoot/chatwoot/develop/enterprise/app/controllers/enterprise/api/v1/accounts/portals_controller.rb"}, {"fetched_at": "2026-10-23T19:31:54.376424+08:00", "kind": "homepage", "sha256": "ea935840cdf3740ec9c949984698771add813020ded8c3a92103453ffc7b846a", "snapshot_path": "sources/ea935840cdf3740ec9c949984698771add813020ded8c3a92103453ffc7b846a.txt", "url": "https://www.chatwoot.com/features/shared-inbox"}, {"fetched_at": "2026-10-23T20:06:13.082534+08:00", "kind": "documentation", "sha256": "c71873de7324728ebc43fd95a8f6e7d1e51a83dba6699e7b14a0de84abff2d47", "snapshot_path": "sources/c71873de7324728ebc43fd95a8f6e7d1e51a83dba6699e7b14a0de84abff2d47.txt", "url": "https://www.chatwoot.com/hc/user-guide/articles/1677580558-website-live-chat-settings-explained"}, {"fetched_at": "2026-10-23T19:31:56.169816+08:00", "kind": "documentation", "sha256": "e8a31ad2933c7fbc78627712a63d234b23ae9b7b72ff5ac544114f3cf4dfc66d", "snapshot_path": "sources/e8a31ad2933c7fbc78627712a63d234b23ae9b7b72ff5ac544114f3cf4dfc66d.txt", "url": "https://www.chatwoot.com/hc/user-guide/en/categories/help-center"}], "summary": "Chatwoot 开源核心以 MIT 许可提供全渠道客户支持工作台；排除 enterprise/ 目录及其独立许可证内容。", "technology_stack": ["Ruby（仓库metadata列出的主要语言）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:500289888','Formbricks','{"deployment": ["README明确提供Docker自托管，无需订阅；另有官方托管云服务"], "features": ["用无代码编辑器创建多题型调查问卷", "在站点、应用内、链接或邮件触达受访者并可针对用户群投放", "由组织成员协作设计问卷并分析收集到的回答"], "github_repository_id": 500289888, "homepage": "https://formbricks.com", "id": "github:500289888", "leaf_matches": [{"reason": "Formbricks 官方 README 描述无代码创建问卷、在应用内/网站/链接/邮件分发并收集分析回答；此处限于问卷设计与响应闭环。", "slug": "questionnaire-application", "source_urls": ["https://raw.githubusercontent.com/formbricks/formbricks/main/README.md"]}, {"reason": "Formbricks README 将其定位为可自托管的 survey platform，展示调查编辑、应用内/网站/链接/邮件分发、组织协作与预构建分析；此匹配是问卷创建和反馈管理，不把它当作招募受访者或完整研究样本库。", "slug": "survey-platform", "source_urls": ["https://raw.githubusercontent.com/formbricks/formbricks/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/formbricks/formbricks/license", "license_review": {"rationale": "已解码并核对 GitHub NOASSERTION 对应 LICENSE 原文：ee 子树采用独立企业许可证，列明的 JS/Android/iOS/API/surveys SDK 包按 MIT，其余核心按 AGPLv3。", "reviewer": "source_research", "scope": "community_core", "source_url": "https://api.github.com/repos/formbricks/formbricks/license", "spdx_id": "AGPL-3.0"}, "name": "Formbricks", "repository_url": "https://github.com/formbricks/formbricks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:30.502647+08:00", "kind": "repository_metadata", "sha256": "85aed5a3c0b0aeb1d6aec15d59c64ce5673e523b75d2c6496f1a3e8c2a9a060d", "snapshot_path": "sources/85aed5a3c0b0aeb1d6aec15d59c64ce5673e523b75d2c6496f1a3e8c2a9a060d.txt", "url": "https://api.github.com/repos/formbricks/formbricks"}, {"fetched_at": "2026-10-23T16:41:33.389348+08:00", "kind": "license", "sha256": "8cecdf5fa9daa290709ff376d9595eef2b31cea5f26ddf77a1bc059432518815", "snapshot_path": "sources/8cecdf5fa9daa290709ff376d9595eef2b31cea5f26ddf77a1bc059432518815.txt", "url": "https://api.github.com/repos/formbricks/formbricks/license"}, {"fetched_at": "2026-10-23T16:41:34.710823+08:00", "kind": "readme", "sha256": "048c85541d709d334e5c4a67def86a9c89932576c30fcb99bceaf85f5be036c9", "snapshot_path": "sources/048c85541d709d334e5c4a67def86a9c89932576c30fcb99bceaf85f5be036c9.txt", "url": "https://raw.githubusercontent.com/formbricks/formbricks/main/README.md"}], "summary": "Formbricks 开源核心以 AGPLv3 提供组织设计和运行体验调查的应用；排除 apps/web/modules/ee 企业功能，多个独立 SDK/package 依 MIT 许可。", "technology_stack": ["TypeScript", "Next.js", "Prisma", "PostgreSQL", "SpiceDB", "Valkey"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:572984571','Twenty','{"deployment": ["README明确支持Docker Compose自托管；另可使用官方云端产品"], "features": ["以组织可定制对象维护联系人、公司和销售记录", "用视图和关系字段整理客户信息并跟踪机会", "借助工作流/自动化将CRM记录连接到销售任务"], "github_repository_id": 572984571, "homepage": "https://twenty.com", "id": "github:572984571", "leaf_matches": [{"reason": "Twenty README 将其明确定位为 CRM，并列出自定义对象、视图和工作流等持久客户关系工作区能力；Docker Compose自托管说明证实它是完整服务器应用，而非CRM SDK或单一数据库。", "slug": "customer-relationship-management-crm", "source_urls": ["https://raw.githubusercontent.com/twentyhq/twenty/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/twentyhq/twenty/license", "license_review": {"rationale": "已解码核对 NOASSERTION 许可证原文：主仓库核心采用 GNU AGPLv3 并附有额外许可说明；SDK分别有 MIT 许可，enterprise 标注路径的特殊内容不纳入核心范围。", "reviewer": "source_research", "scope": "community_core", "source_url": "https://api.github.com/repos/twentyhq/twenty/license", "spdx_id": "AGPL-3.0"}, "name": "Twenty", "repository_url": "https://github.com/twentyhq/twenty", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:34.249045+08:00", "kind": "repository_metadata", "sha256": "822b0c7d1d37dff2441c0e49bb7078e15de922f01e4adcdcb01e49f740676e97", "snapshot_path": "sources/822b0c7d1d37dff2441c0e49bb7078e15de922f01e4adcdcb01e49f740676e97.txt", "url": "https://api.github.com/repos/twentyhq/twenty"}, {"fetched_at": "2026-10-23T16:41:37.449950+08:00", "kind": "license", "sha256": "cbd4ad37770c988603e08975100609eab46e2b5f3748e8d5a602912ba2bbb289", "snapshot_path": "sources/cbd4ad37770c988603e08975100609eab46e2b5f3748e8d5a602912ba2bbb289.txt", "url": "https://api.github.com/repos/twentyhq/twenty/license"}, {"fetched_at": "2026-10-23T16:41:39.911320+08:00", "kind": "readme", "sha256": "5c8dc531b01f1bedddb73acba2181252042d0fc663595bda9214c447617627bb", "snapshot_path": "sources/5c8dc531b01f1bedddb73acba2181252042d0fc663595bda9214c447617627bb.txt", "url": "https://raw.githubusercontent.com/twentyhq/twenty/main/README.md"}], "summary": "Twenty CRM 的开源核心用于客户数据和销售关系流程管理；AGPLv3附带仓库特定额外许可，排除 enterprise 标注部分，MIT SDK 也不代表主应用许可。", "technology_stack": ["TypeScript", "Nx", "NestJS", "PostgreSQL", "Redis", "React"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12204147','Mautic','{"deployment": ["生产安装推荐Composer或官方打包下载；支持DDEV本地启动和Web安装流程"], "features": ["建立并运行跨渠道营销活动", "按联系人属性建立细分受众并配置自动化", "提供邮件与多渠道触达及活动效果管理"], "github_repository_id": 12204147, "homepage": "https://www.mautic.org", "id": "github:12204147", "leaf_matches": [{"reason": "Mautic README 明确称其为开源营销自动化产品，支持组织自建活动、受众分群与多渠道营销，并给出Composer/打包安装路径；因此匹配客户管理营销流程的应用，不是单纯邮件投递服务。", "slug": "marketing-automation-platform", "source_urls": ["https://raw.githubusercontent.com/mautic/mautic/7.x/README.md"]}], "license": "GPL-3.0-or-later", "license_evidence_url": "https://api.github.com/repos/mautic/mautic/license", "license_review": {"rationale": "已解码核对 GitHub NOASSERTION 对应的 LICENSE.txt 原文，包含 GNU GPL v3 条款及“version 3 or any later version”授权表述；按 GPL-3.0-or-later 记录。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/mautic/mautic/license", "spdx_id": "GPL-3.0-or-later"}, "name": "Mautic", "repository_url": "https://github.com/mautic/mautic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T16:41:41.755288+08:00", "kind": "repository_metadata", "sha256": "528698717fe3d66049be373ab6c31e370e3ab27103b68689645fcf81efc2ff06", "snapshot_path": "sources/528698717fe3d66049be373ab6c31e370e3ab27103b68689645fcf81efc2ff06.txt", "url": "https://api.github.com/repos/mautic/mautic"}, {"fetched_at": "2026-10-23T16:41:46.228810+08:00", "kind": "license", "sha256": "d597ae4f93e0649fe540473f0ef28dbc801223eee68a671c40899b68a39186d8", "snapshot_path": "sources/d597ae4f93e0649fe540473f0ef28dbc801223eee68a671c40899b68a39186d8.txt", "url": "https://api.github.com/repos/mautic/mautic/license"}, {"fetched_at": "2026-10-23T16:41:48.913894+08:00", "kind": "readme", "sha256": "83564fa47934221cb511453db9927694e52d86d0526f95d0958f40a5a73c20b0", "snapshot_path": "sources/83564fa47934221cb511453db9927694e52d86d0526f95d0958f40a5a73c20b0.txt", "url": "https://raw.githubusercontent.com/mautic/mautic/7.x/README