INSERT INTO "application" VALUES('commercial:simcorp-one','SimCorp One','{"homepage": "https://simcorp.com", "id": "commercial:simcorp-one", "leaf_matches": [{"reason": "官方One、Operations及Accounting资料明确同一live data foundation贯通front office、交易结算、投资会计和报告，支持完整前后生命周期；记录软件平台，不扩展为供应商代运营投资会计服务。", "slug": "investment-management-platform", "source_urls": ["https://www.simcorp.com/solutions/simcorp-one", "https://www.simcorp.com/solutions/simcorp-one/accounting", "https://www.simcorp.com/solutions/simcorp-one/operations"]}, {"reason": "官方Portfolio Management页说明其为跨资产组合数据提供单一数据源，实时呈现头寸、分析与表现指标，并提供组合构建、订单生成与交易前合规检查，下单前可模拟头寸、现金与风险影响；覆盖组合记录—管理意图—前瞻管理循环。未延伸为托管或业绩归因。", "slug": "portfolio-management-system", "source_urls": ["https://www.simcorp.com/solutions/simcorp-one/portfolio-management"]}], "name": "SimCorp One", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:20:51.759436+08:00", "kind": "documentation", "sha256": "dca3e976bf2861c6aa7f4c317b90f76e6f0e388c9dd86504f98b0a5c4559fa03", "snapshot_path": "sources/dca3e976bf2861c6aa7f4c317b90f76e6f0e388c9dd86504f98b0a5c4559fa03.txt", "url": "https://www.simcorp.com/solutions/simcorp-one"}, {"fetched_at": "2026-10-23T18:20:51.894676+08:00", "kind": "documentation", "sha256": "f343d1364b6bb10d4fe0db6a60ca72a129a501ebb8a7a9fa8d5fd7d9f19017ba", "snapshot_path": "sources/f343d1364b6bb10d4fe0db6a60ca72a129a501ebb8a7a9fa8d5fd7d9f19017ba.txt", "url": "https://www.simcorp.com/solutions/simcorp-one/accounting"}, {"fetched_at": "2026-10-23T18:20:51.692305+08:00", "kind": "documentation", "sha256": "09d383849939cebe3e1c11b2184822aa90b552d07ef8fd8221699f6172d57496", "snapshot_path": "sources/09d383849939cebe3e1c11b2184822aa90b552d07ef8fd8221699f6172d57496.txt", "url": "https://www.simcorp.com/solutions/simcorp-one/operations"}, {"fetched_at": "2026-10-24T20:26:54.252551+08:00", "kind": "documentation", "sha256": "e713b57d5df4612b42244c73e185fa2e60d0cf2862feedde665b21ef744dee71", "snapshot_path": "sources/e713b57d5df4612b42244c73e18