INSERT INTO "application" VALUES('commercial:adyen','Adyen Payments','{"homepage": "https://adyen.com", "id": "commercial:adyen", "leaf_matches": [{"reason": "Customer Area、Payments Lifecycle和Getting Paid官方文档关联同一商户的支付请求、授权/捕获/结算、退款及银行到账记录；软件工作台是本条收录边界，资金处理通道本身不自动纳入。", "slug": "merchant-payment-platform", "source_urls": ["https://www.adyen.com/en_GB/customer-area", "https://docs.adyen.com/account/payments-lifecycle/", "https://docs.adyen.com/account/getting-paid/"]}, {"reason": "官方支付生命周期说明商户提交支付、向外部金融生态授权并跟踪授权/捕获/结算和退款；Customer Area提供持续交易记录操作，不将裸网关端点单独作为完整软件。", "slug": "payment-gateway", "source_urls": ["https://www.adyen.com/en_GB/customer-area", "https://docs.adyen.com/account/payments-lifecycle/", "https://docs.adyen.com/account/getting-paid/"]}], "name": "Adyen Payments", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:20:55.437708+08:00", "kind": "documentation", "sha256": "48bcd4121643592509e01937c610ca0b2d0e344426bf76df8580822538828252", "snapshot_path": "sources/48bcd4121643592509e01937c610ca0b2d0e344426bf76df8580822538828252.txt", "url": "https://www.adyen.com/en_GB/customer-area"}, {"fetched_at": "2026-10-23T18:20:53.756696+08:00", "kind": "documentation", "sha256": "917586f4d2beb88bf44f7095fc5d1b2d91d08b965b29945ac188acbd58aee104", "snapshot_path": "sources/917586f4d2beb88bf44f7095fc5d1b2d91d08b965b29945ac188acbd58aee104.txt", "url": "https://docs.adyen.com/account/payments-lifecycle/"}, {"fetched_at": "2026-10-23T18:20:54.772862+08:00", "kind": "documentation", "sha256": "997b9616dfef82c216a8e2201e3e3068a5283e23969e11121f793f0ec9ee5998", "snapshot_path": "sources/997b9616dfef82c216a8e2201e3e3068a5283e23969e11121f793f0ec9ee5998.txt", "url": "https://docs.adyen.com/account/getting-paid/"}], "summary": "结合商户支付受理、交易生命周期、退款和到账对账的商业平台，提供持续商户运营后台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:blend-mortgage','Blend Mortgage Suite','{"homepage": "https://blend.com", "id": "commercial:blend-mortgage", "leaf_matches": [{"reason": "官方Lender Tools和Borrower Upload文档说明机构配置申请空间，借款人可回到自己的申请上传材料并回写贷款文件，贷款结束后空间在清理前仍可访问；对应发放阶段的持续借款人门户。", "slug": "mortgage-borrower-portal", "source_urls": ["https://blend.com/products/mortgage-suite/lender-tools/", "https://help.blend.com/support/solutions/articles/156000319431-uploading-documents-as-a-borrower"]}], "name": "Blend Mortgage Suite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:20:55.026605+08:00", "kind": "documentation", "sha256": "e682908a60e24b86e3de514f290e539f5decb5c7d599b813840c66c72399abab", "snapshot_path": "sources/e682908a60e24b86e3de514f290e539f5decb5c7d599b813840c66c72399abab.txt", "url": "https://blend.com/products/mortgage-suite/lender-tools/"}, {"fetched_at": "2026-10-23T18:20:54.564220+08:00", "kind": "documentation", "sha256": "5efea2148298ed1f2a73f39fd84ad0c53704c4c03b6116180ce768230f418671", "snapshot_path": "sources/5efea2148298ed1f2a73f39fd84ad0c53704c4c03b6116180ce768230f418671.txt", "url": "https://help.blend.com/support/solutions/articles/156000319431-uploading-documents-as-a-borrower"}], "summary": "贷款机构向借款人提供的抵押贷款申请自助门户，连接申请、材料提交和贷款进度。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:equro-totalis','Equro Totalis','{"homepage": "https://equro.com", "id": "commercial:equro-totalis", "leaf_matches": [{"reason": "官方Infrastructure明确云SaaS和同一股东登记记录；Totalis/Financial Institutions及Issuer资料描述客户机构的登记、交易和由持仓驱动的股息/报表/通知。仅记录软件使用形态，不将Equro代登记服务泛化为软件交付。", "slug": "transfer-agency-platform", "source_urls": ["https://www.equro.com/infrastructure.html", "https://www.equro.com/financial-institutions.html", "https://www.equro.com/issuer-services.html"]}], "name": "Equro Totalis", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:20:54.572871+08:00", "kind": "documentation", "sha256": "ea62548e565803b857249da05985580e9649afa7d0d7e840d56a88e8fcb23fbe", "snapshot_path": "sources/ea62548e565803b857249da05985580e9649afa7d0d7e840d56a88e8fcb23fbe.txt", "url": "https://www.equro.com/infrastructure.html"}, {"fetched_at": "2026-10-23T18:27:50.438684+08:00", "kind": "documentation", "sha256": "01c40121caf4a5e012a5dfe7383496cf41bd924795958758a26bae8f85695672", "snapshot_path": "sources/01c40121caf4a5e012a5dfe7383496cf41bd924795958758a26bae8f85695672.txt", "url": "https://www.equro.com/financial-institutions.html"}, {"fetched_at": "2026-10-23T18:22:55.822342+08:00", "kind": "documentation", "sha256": "e5dd96202fcda5815b912d923af1f0adfa5bc5ce5f9f05ad35514b181d0a1635", "snapshot_path": "sources/e5dd96202fcda5815b912d923af1f0adfa5bc5ce5f9f05ad35514b181d0a1635.txt", "url": "https://www.equro.com/issuer-services.html"}], "summary": "供机构管理发行人和证券持有人登记、所有权交易、公司行动及投资者通知的软件平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:spellbook','Spellbook','{"homepage": "https://spellbook.com", "id": "commercial:spellbook", "leaf_matches": [{"reason": "官方 Draft 功能说明其识别当前文档并起草相关语言，可从空白文档起草，也支持把建议直接应用到文档；官方 About 说明产品在 Word 内工作，匹配律师持续处理中的可编辑文书工作流。", "slug": "legal-drafting-platform", "source_urls": ["https://spellbook.com/", "https://spellbook.com/features/draft", "https://spellbook.com/about"]}], "name": "Spellbook", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:52:41.592398+08:00", "kind": "homepage", "sha256": "e0f6274bbcb394dd617d5ad4a2f1e6818e82138a9435cdf36a5ba45bfd6b09ec", "snapshot_path": "sources/e0f6274bbcb394dd617d5ad4a2f1e6818e82138a9435cdf36a5ba45bfd6b09ec.txt", "url": "https://spellbook.com/"}, {"fetched_at": "2026-10-23T18:52:45.468978+08:00", "kind": "documentation", "sha256": "c207ddd6bad5268edf772f731bad69952a532b27898032b9dd105b5f715decb5", "snapshot_path": "sources/c207ddd6bad5268edf772f731bad69952a532b27898032b9dd105b5f715decb5.txt", "url": "https://spellbook.com/features/draft"}, {"fetched_at": "2026-10-23T18:52:50.712144+08:00", "kind": "documentation", "sha256": "da5b6b01ba080df0a8e2b85bdac5ae8342b87be655286300c41e885d27bb4330", "snapshot_path": "sources/da5b6b01ba080df0a8e2b85bdac5ae8342b87be655286300c41e885d27bb4330.txt", "url": "https://spellbook.com/about"}], "summary": "面向律师的 AI 法律起草与合同审阅工具，集成在 Microsoft Word 中，支持起草新条款、复用文档库语言及直接修改当前文档。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:github-copilot','GitHub Copilot','{"homepage": "https://github.com/features/copilot", "id": "commercial:github-copilot", "leaf_matches": [{"reason": "GitHub 官方 Chat 文档说明 Copilot Chat 在仓库、文件或代码片段上下文中回答问题、解释代码、提出改进或生成测试；用户从聊天获得建议后自行审阅和应用。此匹配仅针对建议/问答功能，不依据云代理代执行任务。", "slug": "ai-coding-assistant", "source_urls": ["https://docs.github.com/en/copilot/how-tos/copilot-on-github/chat-with-copilot/get-started-with-chat"]}], "name": "GitHub Copilot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:53:23.070093+08:00", "kind": "homepage", "sha256": "2f026e0222a8f38d6f641cb8a56ee83540906d8b6429fce76521f901c869713a", "snapshot_path": "sources/2f026e0222a8f38d6f641cb8a56ee83540906d8b6429fce76521f901c869713a.txt", "url": "https://github.com/features/copilot"}, {"fetched_at": "2026-10-23T18:51:41.559423+08:00", "kind": "documentation", "sha256": "2f73c41a2c10752e4d639db47071986aba308c8dbe019bf2e11517493eed5792", "snapshot_path": "sources/2f73c41a2c10752e4d639db47071986aba308c8dbe019bf2e11517493eed5792.txt", "url": "https://docs.github.com/en/copilot/concepts/copilot-surfaces/copilot-on-github"}, {"fetched_at": "2026-10-23T18:57:22.064084+08:00", "kind": "documentation", "sha256": "d2655bcfb1afb6fcc5fede351595ead7e135372a7fbe936c88dc28f439017926", "snapshot_path": "sources/d2655bcfb1afb6fcc5fede351595ead7e135372a7fbe936c88dc28f439017926.txt", "url": "https://docs.github.com/en/copilot/how-tos/copilot-on-github/chat-with-copilot/get-started-with-chat"}], "summary": "GitHub Copilot 提供 GitHub.com 上的聊天与云端编码代理，可理解代码仓库、计划和实现多步代码任务、运行测试并发起拉取请求。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:moderne','Moderne Platform','{"homepage": "https://docs.moderne.io/", "id": "commercial:moderne", "leaf_matches": [{"reason": "Moderne 官方资料明确描述企业级 SaaS 可跨组织多仓库运行自动化代码转换 recipes，查看变更结果并选择提交或创建 PR；因此属于代码迁移和现代化的可管理服务工作流。", "slug": "code-migration-platform", "source_urls": ["https://docs.moderne.io/", "https://docs.moderne.io/user-documentation/moderne-platform/getting-started/running-your-first-recipe/", "https://docs.moderne.io/administrator-documentation/moderne-platform/references/architecture/"]}], "name": "Moderne Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:51.296020+08:00", "kind": "homepage", "sha256": "c67a7686241f0d2bb7dc16946b0a94f027db16a9ea07586afa2daf31e98500a1", "snapshot_path": "sources/c67a7686241f0d2bb7dc16946b0a94f027db16a9ea07586afa2daf31e98500a1.txt", "url": "https://docs.moderne.io/"}, {"fetched_at": "2026-10-23T18:51:55.125598+08:00", "kind": "documentation", "sha256": "09eed256b3d101dfb40c7c554d00ee843860985db8c96262d0bb6b1c837c3f7b", "snapshot_path": "sources/09eed256b3d101dfb40c7c554d00ee843860985db8c96262d0bb6b1c837c3f7b.txt", "url": "https://docs.moderne.io/user-documentation/moderne-platform/getting-started/running-your-first-recipe/"}, {"fetched_at": "2026-10-23T18:51:58.505496+08:00", "kind": "documentation", "sha256": "7f6bbdbce4ef7f2a56a9950a7a5aac43443e6f8df7508716d212165e9f1fc9f0", "snapshot_path": "sources/7f6bbdbce4ef7f2a56a9950a7a5aac43443e6f8df7508716d212165e9f1fc9f0.txt", "url": "https://docs.moderne.io/administrator-documentation/moderne-platform/references/architecture/"}], "summary": "Moderne 是面向企业多仓库代码现代化的私有 SaaS 平台，可跨组织仓库运行迁移/重构 recipes、检查结果并提交变更或创建拉取请求。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:amazon-aurora-dsql-playground','Amazon Aurora DSQL Playground','{"homepage": "https://aws.amazon.com/aurora/dsql/", "id": "commercial:amazon-aurora-dsql-playground", "leaf_matches": [{"reason": "AWS 官方公告明确描述即开即用、临时的数据库环境，以及浏览器内建 schema、数据和查询实验工作流，直接符合数据库沙箱子工作流。", "slug": "database-sandbox-platform", "source_urls": ["https://aws.amazon.com/aurora/dsql/", "https://aws.amazon.com/about-aws/whats-new/2026/02/amazon-aurora-dsql-launches-playground/"]}], "name": "Amazon Aurora DSQL Playground", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:54:06.384662+08:00", "kind": "homepage", "sha256": "cbcc133f497de2dc5e30e658a48614e81c1f6dd27ad4b98d8a26ee2ac0278ec2", "snapshot_path": "sources/cbcc133f497de2dc5e30e658a48614e81c1f6dd27ad4b98d8a26ee2ac0278ec2.txt", "url": "https://aws.amazon.com/aurora/dsql/"}, {"fetched_at": "2026-10-23T18:54:02.515400+08:00", "kind": "documentation", "sha256": "7b17fa1d06cde96593944beb96cf52404a950012f62dc81ef6ab35c09b4fb440", "snapshot_path": "sources/7b17fa1d06cde96593944beb96cf52404a950012f62dc81ef6ab35c09b4fb440.txt", "url": "https://aws.amazon.com/about-aws/whats-new/2026/02/amazon-aurora-dsql-launches-playground/"}], "summary": "Amazon Aurora DSQL 提供免 AWS 账户的浏览器 playground，开发者可在临时数据库环境中创建 schema、载入样例数据并执行 SQL 查询，用于交互式试用与学习。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:github-dependabot','GitHub Dependabot','{"homepage": "https://github.com/features/security", "id": "commercial:github-dependabot", "leaf_matches": [{"reason": "官方 Dependabot options reference 明确说明版本更新 PR 修改 manifest 与 lock files 中记录的版本，versioning-strategy 可 increase/widen 约束；安全更新覆盖 lock files 中的脆弱依赖，并可更新 transitive dependency（例如升级 parent 以允许修复 child）。因此证据覆盖约束、锁文件及传递依赖维护，而不只是通知。", "slug": "dependency-management-application", "source_urls": ["https://github.com/features/security", "https://docs.github.com/en/code-security/concepts/supply-chain-security/dependabot-version-updates?learn=dependency_version_updates&learnproduct=code-security", "https://docs.github.com/en/code-security/reference/supply-chain-security/dependabot-options-reference?learn=dependency_version_updates", "https://docs.github.com/en/code-security/reference/supply-chain-security/supported-ecosystems-and-repositories"]}], "name": "GitHub Dependabot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:57:31.559038+08:00", "kind": "homepage", "sha256": "75b12fff147a9bac0cae9cdbdb897ca30590aa074affb007890c015664adb4ad", "snapshot_path": "sources/75b12fff147a9bac0cae9cdbdb897ca30590aa074affb007890c015664adb4ad.txt", "url": "https://github.com/features/security"}, {"fetched_at": "2026-10-23T18:56:04.357923+08:00", "kind": "documentation", "sha256": "e851f16b1a0747f1b40d883e9cfe1b7f153eaf3292dace799e56daef38ce04ab", "snapshot_path": "sources/e851f16b1a0747f1b40d883e9cfe1b7f153eaf3292dace799e56daef38ce04ab.txt", "url": "https://docs.github.com/en/code-security/concepts/supply-chain-security/dependabot-version-updates?learn=dependency_version_updates&learnproduct=code-security"}, {"fetched_at": "2026-10-23T19:07:21.500496+08:00", "kind": "documentation", "sha256": "35347c380725b0e40c5c852088e1741f5e23974b27b02b6c3e72f5d634c07012", "snapshot_path": "sources/35347c380725b0e40c5c852088e1741f5e23974b27b02b6c3e72f5d634c07012.txt", "url": "https://docs.github.com/en/code-security/reference/supply-chain-security/dependabot-options-reference?learn=dependency_version_updates"}, {"fetched_at": "2026-10-23T19:07:09.728191+08:00", "kind": "documentation", "sha256": "18c467d71341609340602d90ad12dcf10a9d4d5ac819d574ff25a553ca75a69e", "snapshot_path": "sources/18c467d71341609340602d90ad12dcf10a9d4d5ac819d574ff25a553ca75a69e.txt", "url": "https://docs.github.com/en/code-security/reference/supply-chain-security/supported-ecosystems-and-repositories"}], "summary": "GitHub Dependabot tracks declared project dependencies and creates pull requests for configured version updates and security fixes.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:renesas-quickconnect','Renesas QuickConnect Studio','{"homepage": "https://www.renesas.com/en/software-tool/quickconnect-platform", "id": "commercial:renesas-quickconnect", "leaf_matches": [{"reason": "Renesas 官方 QuickConnect 文档将 Studio 描述为在浏览器内创建、配置、编译和调试嵌入式应用的平台，并提供远程调试目标板工作流，符合固件 IDE 子类型。", "slug": "embedded-firmware-development-ide", "source_urls": ["https://www.renesas.com/en/software-tool/quickconnect-platform"]}], "name": "Renesas QuickConnect Studio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:56:36.111497+08:00", "kind": "homepage", "sha256": "c89c379921bdeaa651ae28869dbd515275e35d35a0fe8abce354de4b74bb8082", "snapshot_path": "sources/c89c379921bdeaa651ae28869dbd515275e35d35a0fe8abce354de4b74bb8082.txt", "url": "https://www.renesas.com/en/software-tool/quickconnect-platform"}], "summary": "Renesas QuickConnect Studio 是浏览器内的嵌入式软硬件开发环境，支持构建、配置与调试 MCU 应用并连接远程开发板。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:expo','Expo Application Services','{"homepage": "https://expo.dev/", "id": "commercial:expo", "leaf_matches": [{"reason": "Expo 官方开发流程说明 Expo 是 React Native 开源框架（CLI、Router、SDK等）并与托管 EAS Build/Submit/Update、Workflows 整合；项目创建文档确认 Android/iOS framework/UI开发及原生模块，EAS资料覆盖云构建签名、测试分发、更新和上架。该匹配是 framework + EAS 套件整体，不把单独 EAS Build 当完整平台。", "slug": "mobile-app-development-platform", "source_urls": ["https://expo.dev/", "https://docs.expo.dev/build/introduction/", "https://docs.expo.dev/", "https://docs.expo.dev/workflow/overview/", "https://docs.expo.dev/get-started/create-a-project/"]}], "name": "Expo Application Services", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:56:46.660316+08:00", "kind": "homepage", "sha256": "f18006c2b527f32fe11051f03e15a585132854675797c1126bf031eca011485c", "snapshot_path": "sources/f18006c2b527f32fe11051f03e15a585132854675797c1126bf031eca011485c.txt", "url": "https://expo.dev/"}, {"fetched_at": "2026-10-23T18:56:12.105721+08:00", "kind": "documentation", "sha256": "1aae31a913bd5ba4897855daf80209bfc20154fa80f49dda0b39b41b432de9eb", "snapshot_path": "sources/1aae31a913bd5ba4897855daf80209bfc20154fa80f49dda0b39b41b432de9eb.txt", "url": "https://docs.expo.dev/build/introduction/"}, {"fetched_at": "2026-10-23T18:56:08.361850+08:00", "kind": "documentation", "sha256": "fd18221a8905df8243346c0e303dc1e8f69655a5e8c6b5cce6fc7ea77ef22d3c", "snapshot_path": "sources/fd18221a8905df8243346c0e303dc1e8f69655a5e8c6b5cce6fc7ea77ef22d3c.txt", "url": "https://docs.expo.dev/"}, {"fetched_at": "2026-10-23T19:07:11.680948+08:00", "kind": "documentation", "sha256": "4aa6b611a4b8a367d1abb1c19e57050bfc26f970f091c1d63a7c3eed990d36da", "snapshot_path": "sources/4aa6b611a4b8a367d1abb1c19e57050bfc26f970f091c1d63a7c3eed990d36da.txt", "url": "https://docs.expo.dev/workflow/overview/"}, {"fetched_at": "2026-10-23T19:07:14.391003+08:00", "kind": "documentation", "sha256": "5f6e1dcdc6168317ac614d67eb63446ca98bcb2e9d00b111884b6d343d985a1a", "snapshot_path": "sources/5f6e1dcdc6168317ac614d67eb63446ca98bcb2e9d00b111884b6d343d985a1a.txt", "url": "https://docs.expo.dev/get-started/create-a-project/"}], "summary": "Expo 提供 React Native 移动应用框架及云端 EAS Build/Submit 服务，支持构建、签名并向 TestFlight、App Store 和 Google Play 分发应用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:google-cloud-profiler','Google Cloud Profiler','{"homepage": "https://docs.cloud.google.com/profiler/docs/about-profiler", "id": "commercial:google-cloud-profiler", "leaf_matches": [{"reason": "Google Cloud 官方文档说明代理持续采样程序运行时资源开销，控制台把 CPU/内存指标归因到源代码并提供 profile 分析界面，符合运行测量、代码归因和持久 profile 探查核心。", "slug": "profiler", "source_urls": ["https://docs.cloud.google.com/profiler/docs/about-profiler"]}], "name": "Google Cloud Profiler", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:55:04.580858+08:00", "kind": "homepage", "sha256": "82de3c38edd00b0045af3a96e9777d0c8d5904e2999f0f6838b7a2032ef61383", "snapshot_path": "sources/82de3c38edd00b0045af3a96e9777d0c8d5904e2999f0f6838b7a2032ef61383.txt", "url": "https://docs.cloud.google.com/profiler/docs/about-profiler"}], "summary": "Google Cloud Profiler 持续收集生产程序的 CPU 与内存分配数据，并在 Google Cloud 控制台按代码位置查看和分析性能 profile。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:browserstack','BrowserStack Automate','{"homepage": "https://www.browserstack.com/", "id": "commercial:browserstack", "leaf_matches": [{"reason": "BrowserStack 官方 Automated Website Testing 页面正文写明：可即时使用含 3000+ 桌面浏览器与真实移动设备的 Cloud Selenium Grid，在选定的桌面/移动浏览器上自动化团队自己的网站测试，支持并行运行、CI 插件/框架集成及开发环境或防火墙后站点测试；同站导航将 Live 标为 Manual cross-browser testing、Automate 标为 Browser automation cloud，二者是同一平台的手动与自动化入口。对应按需选择浏览器环境并运行团队自身应用/测试的核心工作流；商业条目仅记录基本产品信息。", "slug": "browser-compatibility-testing-platform", "source_urls": ["https://www.browserstack.com/automated-website-testing", "https://www.browserstack.com/"]}, {"reason": "BrowserStack 官方产品页描述自动化测试运行网格、跨浏览器/设备的并行执行和结果反馈；与网页声明的测试管理及报告能力组合，构成自动化测试平台工作流。", "slug": "test-automation-platform", "source_urls": ["https://www.browserstack.com/", "https://www.browserstack.com/automated-website-testing"]}], "name": "BrowserStack Automate", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:55:10.394160+08:00", "kind": "homepage", "sha256": "8c40279532f07553ed25cb5cc09cc807c15de13f0a125a2463965d493f954c98", "snapshot_path": "sources/8c40279532f07553ed25cb5cc09cc807c15de13f0a125a2463965d493f954c98.txt", "url": "https://www.browserstack.com/"}, {"fetched_at": "2026-10-23T18:55:15.573887+08:00", "kind": "documentation", "sha256": "8b254f6f56079055494b1292193f69bbbdadaf1d6e73ce26fb6037227d2ead34", "snapshot_path": "sources/8b254f6f56079055494b1292193f69bbbdadaf1d6e73ce26fb6037227d2ead34.txt", "url": "https://www.browserstack.com/automated-website-testing"}, {"fetched_at": "2026-10-27T16:44:12.090442+08:00", "kind": "documentation", "sha256": "8e03d0e0d20b04d1812dc281fd518560a4919fde9047b13ce51b96d02134d045", "snapshot_path": "sources/8e03d0e0d20b04d1812dc281fd518560a4919fde9047b13ce51b96d02134d045.txt", "url": "https://www.browserstack.com/automated-website-testing"}], "summary": "BrowserStack 提供托管真实浏览器与移动设备测试云，可在 Selenium 等自动化框架上并行执行网站测试并查看结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:replit','Replit','{"homepage": "https://replit.com/build", "id": "commercial:replit", "leaf_matches": [{"reason": "Replit Agent 官方文档说明可由自然语言描述创建 web app、编写代码并设置基础设施；Project Editor 文档确认可打开和编辑项目文件；Publishing 文档说明在工作台发布并为应用分配 .replit.app 网址，部署类型文档覆盖云端 web app/API 运行。因此 Replit 提供从提示构建、编辑到发布可访问 web 应用的完整子工作流。", "slug": "web-application-builder", "source_urls": ["https://docs.replit.com/features/agent/overview", "https://docs.replit.com/features/editor/editor-and-tools", "https://docs.replit.com/features/publishing/overview", "https://docs.replit.com/features/publishing/deployment-types"]}], "name": "Replit", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:56:27.895252+08:00", "kind": "homepage", "sha256": "0fc65a0ae471d156be0a199a2e71fbeec9a638331f38f62c3a3365831b342a1b", "snapshot_path": "sources/0fc65a0ae471d156be0a199a2e71fbeec9a638331f38f62c3a3365831b342a1b.txt", "url": "https://replit.com/build"}, {"fetched_at": "2026-10-23T19:16:28.377855+08:00", "kind": "documentation", "sha256": "0c443f443eb710375e5bf57f642c1019f3934d6982500396f2e565cb53b70664", "snapshot_path": "sources/0c443f443eb710375e5bf57f642c1019f3934d6982500396f2e565cb53b70664.txt", "url": "https://docs.replit.com/features/agent/overview"}, {"fetched_at": "2026-10-23T19:16:07.001830+08:00", "kind": "documentation", "sha256": "ae8f75337503773a99e2f586edd638623da475280de69da67e267d06dabeb532", "snapshot_path": "sources/ae8f75337503773a99e2f586edd638623da475280de69da67e267d06dabeb532.txt", "url": "https://docs.replit.com/features/editor/editor-and-tools"}, {"fetched_at": "2026-10-23T19:16:06.849374+08:00", "kind": "documentation", "sha256": "f0d891b1f77c03941d6676b408b200207a5f4bb4a3e8edf367131d345bc5589a", "snapshot_path": "sources/f0d891b1f77c03941d6676b408b200207a5f4bb4a3e8edf367131d345bc5589a.txt", "url": "https://docs.replit.com/features/publishing/overview"}, {"fetched_at": "2026-10-23T19:16:05.124436+08:00", "kind": "documentation", "sha256": "471aad9035227baec04a19041e107053ddee38431d137429f4e645edc5402273", "snapshot_path": "sources/471aad9035227baec04a19041e107053ddee38431d137429f4e645edc5402273.txt", "url": "https://docs.replit.com/features/publishing/deployment-types"}], "summary": "Replit Agent 通过浏览器工作台从提示生成网站或 web app，提供即时预览并支持将完成应用部署为公开网址。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:huggingface-inference-endpoints','Hugging Face Inference Endpoints','{"homepage": "https://huggingface.co", "id": "commercial:huggingface-inference-endpoints", "leaf_matches": [{"reason": "官方配置文档说明从 Hub 选择模型、由平台管理 AWS/Azure/GCP compute 部署，提供端点访问控制、GPU选择和自动伸缩。", "slug": "ai-model-hosting-platform", "source_urls": ["https://huggingface.co/docs/inference-endpoints/guides/configuration"]}], "name": "Hugging Face Inference Endpoints", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:59:57.567107+08:00", "kind": "documentation", "sha256": "06aadcf75d02d5dd74c09d8ca1cf2856b89e86a238fbb6b89bffe0358cdb6266", "snapshot_path": "sources/06aadcf75d02d5dd74c09d8ca1cf2856b89e86a238fbb6b89bffe0358cdb6266.txt", "url": "https://huggingface.co/docs/inference-endpoints/guides/configuration"}], "summary": "Hugging Face 托管专用推理端点，可部署 Hub 模型到其管理的云计算资源并提供受控 API。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lakera-guard','Check Point AI Guardrails (Lakera Guard)','{"homepage": "https://lakera.ai", "id": "commercial:lakera-guard", "leaf_matches": [{"reason": "官方资料描述在 LLM 应用路径中对提示注入、数据泄漏和内容违规进行实时检测并返回处理结果；符合 API 请求 screening 子工作流。", "slug": "ai-safety-guardrail-platform", "source_urls": ["https://docs.lakera.ai/guard"]}], "name": "Check Point AI Guardrails (Lakera Guard)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:00:21.849967+08:00", "kind": "documentation", "sha256": "8a31b6bf8986cc65d312c44e7f15dffefff5657a6c7d8276f0186e16252e9201", "snapshot_path": "sources/8a31b6bf8986cc65d312c44e7f15dffefff5657a6c7d8276f0186e16252e9201.txt", "url": "https://docs.lakera.ai/guard"}], "summary": "Lakera Guard 提供面向生成式 AI 请求的运行时安全检测 API 和策略管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aws-dms','AWS Database Migration Service','{"homepage": "https://aws.amazon.com/dms/", "id": "commercial:aws-dms", "leaf_matches": [{"reason": "官方文档说明 DMS 从数据库原生变更日志持续捕获变化并交付至目标；与 CDC 核心匹配。", "slug": "change-data-capture-platform", "source_urls": ["https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Task.CDC.html"]}, {"reason": "官方文档明确 full load + CDC 和 CDC-only 两类任务可把现有状态及后续变化持续应用到目标数据库。", "slug": "data-replication-platform", "source_urls": ["https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Task.CDC.html"]}], "name": "AWS Database Migration Service", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:00:52.505668+08:00", "kind": "documentation", "sha256": "a50912e67086020899b2df4f047d811fb6d5869e6ec11a43bbc1607aac755e6a", "snapshot_path": "sources/a50912e67086020899b2df4f047d811fb6d5869e6ec11a43bbc1607aac755e6a.txt", "url": "https://docs.aws.amazon.com/dms/latest/userguide/CHAP_Task.CDC.html"}], "summary": "AWS DMS 提供数据库全量加载和持续变更捕获/复制任务，将源端变化应用到目标端。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:snowflake','Snowflake','{"homepage": "https://snowflake.com", "id": "commercial:snowflake", "leaf_matches": [{"reason": "官方架构文档说明持久化数据存储、平台提供的虚拟仓库集群和 SQL 分析服务，符合托管数据仓库核心。", "slug": "data-warehouse-platform", "source_urls": ["https://docs.snowflake.com/en/user-guide/intro-key-concepts?lang=us"]}], "name": "Snowflake", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:00:50.824098+08:00", "kind": "documentation", "sha256": "dd4d6940f0e9ee503f4a08b1d690e16368c14e0687793de0d3929a7c75ec2c85", "snapshot_path": "sources/dd4d6940f0e9ee503f4a08b1d690e16368c14e0687793de0d3929a7c75ec2c85.txt", "url": "https://docs.snowflake.com/en/user-guide/intro-key-concepts?lang=us"}], "summary": "Snowflake 是由平台管理存储与弹性 SQL compute 的云数据分析平台，支持集中存储、查询和治理分析数据。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:databricks','Databricks Lakehouse','{"homepage": "https://www.databricks.com/product/lakehouse-storage", "id": "commercial:databricks", "leaf_matches": [{"reason": "官方产品页正文明确描述开放表格式的湖存储、Unity Catalog 统一目录与细粒度治理、以及任意引擎/开放 API 访问，覆盖数据湖平台的存储、目录和受治理多引擎访问核心。", "slug": "data-lake-platform", "source_urls": ["https://www.databricks.com/product/lakehouse-storage", "https://www.databricks.com/product/unity-catalog"]}, {"reason": "官方产品页说明单一 Delta/Iceberg 数据副本、集中目录治理，并支持流批和交互式分析查询。", "slug": "lakehouse-platform", "source_urls": ["https://www.databricks.com/product/lakehouse-storage"]}], "name": "Databricks Lakehouse", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:02:33.613047+08:00", "kind": "homepage", "sha256": "6cb2bb245911a242b9785021c4a124332136aead3416ae80e397dabd56cdc8ed", "snapshot_path": "sources/6cb2bb245911a242b9785021c4a124332136aead3416ae80e397dabd56cdc8ed.txt", "url": "https://www.databricks.com/product/lakehouse-storage"}, {"fetched_at": "2026-10-23T19:00:55.046811+08:00", "kind": "homepage", "sha256": "6e17dac4458beccff734ff25c18a4e70d3449e210fb8e090957da8cc89b5e56f", "snapshot_path": "sources/6e17dac4458beccff734ff25c18a4e70d3449e210fb8e090957da8cc89b5e56f.txt", "url": "https://www.databricks.com/product/lakehouse-storage"}, {"fetched_at": "2026-10-26T18:02:51.463726+08:00", "kind": "documentation", "sha256": "a2254a3d287f0e50baa8bef9b494d820d1dc428bdbfa95196609c303ba041eaf", "snapshot_path": "sources/a2254a3d287f0e50baa8bef9b494d820d1dc428bdbfa95196609c303ba041eaf.txt", "url": "https://www.databricks.com/product/unity-catalog"}], "summary": "Databricks 提供基于 Delta Lake 与 Apache Iceberg 表的受管 lakehouse 存储、目录治理和分析工作负载。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pinecone','Pinecone','{"homepage": "https://www.pinecone.io/", "id": "commercial:pinecone", "leaf_matches": [{"reason": "官方教程呈现文本 query embedding、向量检索及按语义相似度排序结果的闭环。", "slug": "semantic-search-platform", "source_urls": ["https://www.pinecone.io/learn/search-with-pinecone/"]}, {"reason": "官方资料说明 Pinecone 是托管向量数据库，通过 API 查询向量并返回相似度排名结果。", "slug": "vector-retrieval-platform", "source_urls": ["https://www.pinecone.io/learn/search-with-pinecone/"]}], "name": "Pinecone", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:00:56.869028+08:00", "kind": "documentation", "sha256": "24425f3a6f1df6f5e4e54ab3da6730747f55cbdbfd49396646b341fc1f2bebce", "snapshot_path": "sources/24425f3a6f1df6f5e4e54ab3da6730747f55cbdbfd49396646b341fc1f2bebce.txt", "url": "https://www.pinecone.io/learn/search-with-pinecone/"}], "summary": "Pinecone 是托管向量检索平台，支持通过 REST API/客户端进行向量相似度查询并返回排序结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:stardog','Stardog Semantic AI Platform','{"homepage": "https://www.stardog.com/platform/", "id": "commercial:stardog", "leaf_matches": [{"reason": "官方产品资料明确覆盖跨数据源图谱构建、语义关系、治理/质量和 SPARQL/GraphQL 查询服务。", "slug": "knowledge-graph-platform", "source_urls": ["https://www.stardog.com/platform/"]}], "name": "Stardog Semantic AI Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:01:15.603940+08:00", "kind": "homepage", "sha256": "ff5f994347b7a347c212a4b9ca31483189532a8220a45c495df904b246505669", "snapshot_path": "sources/ff5f994347b7a347c212a4b9ca31483189532a8220a45c495df904b246505669.txt", "url": "https://www.stardog.com/platform/"}], "summary": "Stardog 提供企业知识图谱建模、数据虚拟化/物化、质量约束和图查询应用平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dify','Dify','{"homepage": "https://www.dify.ai/rag", "id": "commercial:dify", "leaf_matches": [{"reason": "Dify 官方知识管线产品页描述从文件/数据源建立维护知识库，再由 AI 应用检索并使用引用，覆盖 RAG 的摄取、检索和生成集成工作流。", "slug": "rag-development-platform", "source_urls": ["https://www.dify.ai/rag"]}], "name": "Dify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:01:17.241520+08:00", "kind": "homepage", "sha256": "77a322376e50a812468b8fd22c61f9d63d9642ea58f33bf1f38b456dde34ab3b", "snapshot_path": "sources/77a322376e50a812468b8fd22c61f9d63d9642ea58f33bf1f38b456dde34ab3b.txt", "url": "https://www.dify.ai/rag"}], "summary": "Dify 是 AI 应用与 RAG 工作流平台，提供可管理知识管线并供工作流/聊天/agent应用检索。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:n8n-cloud','n8n Cloud','{"homepage": "https://docs.n8n.io/", "id": "commercial:n8n-cloud", "leaf_matches": [{"reason": "n8n 官方 AI Agent 节点文档说明用户在工作流画布配置 agent，并连接 Chat Model、Memory 和 Tool 子节点；n8n 官方产品文档记录 Cloud 托管版本，形成定义、测试及运行 agent 的完整子工作流。", "slug": "agent-development-platform", "source_urls": ["https://docs.n8n.io/integrations/builtin/cluster-nodes/root-nodes/n8n-nodes-langchain.agent/", "https://docs.n8n.io/"]}, {"reason": "n8n 官方 AI Agent Tool 节点文档说明根 agent 可把其他 agent 作为 tools 调用，用于多 agent orchestration；workflow canvas 执行协调结构。", "slug": "agent-orchestration-platform", "source_urls": ["https://docs.n8n.io/integrations/builtin/cluster-nodes/sub-nodes/n8n-nodes-langchain.toolaiagent/", "https://docs.n8n.io/"]}], "name": "n8n Cloud", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:06:38.911647+08:00", "kind": "documentation", "sha256": "63f1df2cccb583b45b9382f4a927ac1466c8810bf6d40a08992c0429c5d719fa", "snapshot_path": "sources/63f1df2cccb583b45b9382f4a927ac1466c8810bf6d40a08992c0429c5d719fa.txt", "url": "https://docs.n8n.io/"}, {"fetched_at": "2026-10-23T19:06:33.077105+08:00", "kind": "documentation", "sha256": "810bfb9fcbe7a01f858e7ac879445ab17d39f49c6d2f3b7cef1f45ea39b51681", "snapshot_path": "sources/810bfb9fcbe7a01f858e7ac879445ab17d39f49c6d2f3b7cef1f45ea39b51681.txt", "url": "https://docs.n8n.io/integrations/builtin/cluster-nodes/root-nodes/n8n-nodes-langchain.agent/"}, {"fetched_at": "2026-10-23T19:06:36.528104+08:00", "kind": "documentation", "sha256": "24143094a6ec0437b2f1e8c4b2c61bd6bffa7b2895e71c2933eca365835681bf", "snapshot_path": "sources/24143094a6ec0437b2f1e8c4b2c61bd6bffa7b2895e71c2933eca365835681bf.txt", "url": "https://docs.n8n.io/integrations/builtin/cluster-nodes/sub-nodes/n8n-nodes-langchain.toolaiagent/"}], "summary": "n8n Cloud 提供可视化工作流编辑器及 AI Agent 节点，用户可定义 agent 提示、模型和工具，并构建由 agent 调用其他 agent 的工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:730534580','RAGFlow','{"deployment": ["README documents Docker Compose deployment for production/evaluation and source deployment for development; Docker path starts server services and dependencies (MySQL, object store, message bus, vector/document engine). No code was executed."], "features": ["Ingests heterogeneous documents and performs document understanding, template-based chunking, and knowledge compilation.", "Provides multi-step agentic retrieval with evidence verification, grounded citations and configurable LLM/embedding models.", "Exposes APIs for integrating maintained knowledge and retrieval workflows into applications."], "github_repository_id": 730534580, "homepage": "https://ragflow.io", "id": "github:730534580", "leaf_matches": [{"reason": "RAGFlow README identifies an open-source RAG engine/application and directly documents document ingestion/understanding, chunking, configurable LLM and embedding, multi-step retrieval, evidence-grounded citations and application APIs; deployment section documents Docker Compose production deployment. This is the full RAG development workflow, not a vector database component.", "slug": "rag-development-platform", "source_urls": ["https://api.github.com/repos/infiniflow/ragflow", "https://api.github.com/repos/infiniflow/ragflow/license", "https://raw.githubusercontent.com/infiniflow/ragflow/main/LICENSE", "https://raw.githubusercontent.com/infiniflow/ragflow/main/README.md", "https://api.github.com/repos/infiniflow/ragflow/languages"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/infiniflow/ragflow/license", "license_review": {"rationale": "GitHub repository metadata reports repository SPDX Apache-2.0; official raw LICENSE snapshot is the full Apache License 2.0 text (11,357 bytes).", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/infiniflow/ragflow/license", "spdx_id": "Apache-2.0"}, "name": "RAGFlow", "repository_url": "https://github.com/infiniflow/ragflow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:22.773842+08:00", "kind": "repository_metadata", "sha256": "18fd802cad2a6c98e33d9de94539141b547cb3ec94def900a1677fb555ab02b5", "snapshot_path": "sources/18fd802cad2a6c98e33d9de94539141b547cb3ec94def900a1677fb555ab02b5.txt", "url": "https://api.github.com/repos/infiniflow/ragflow"}, {"fetched_at": "2026-10-23T19:05:24.466625+08:00", "kind": "license", "sha256": "a9d9511ba8251ccd9b322cec591bb8700348b2b1d3ea4e8abb7c7c22222d56be", "snapshot_path": "sources/a9d9511ba8251ccd9b322cec591bb8700348b2b1d3ea4e8abb7c7c22222d56be.txt", "url": "https://api.github.com/repos/infiniflow/ragflow/license"}, {"fetched_at": "2026-10-23T19:06:01.736392+08:00", "kind": "license", "sha256": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4", "snapshot_path": "sources/c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4.txt", "url": "https://raw.githubusercontent.com/infiniflow/ragflow/main/LICENSE"}, {"fetched_at": "2026-10-23T19:05:25.798895+08:00", "kind": "readme", "sha256": "22bcc2881978416c6eac909be53d69869c3001424227440758ee8fc309362f3c", "snapshot_path": "sources/22bcc2881978416c6eac909be53d69869c3001424227440758ee8fc309362f3c.txt", "url": "https://raw.githubusercontent.com/infiniflow/ragflow/main/README.md"}, {"fetched_at": "2026-10-23T19:06:03.072039+08:00", "kind": "repository_metadata", "sha256": "a6d9bdc590f92fa432ffa1401689756f3d047b0185702cb908bb3302cec2449b", "snapshot_path": "sources/a6d9bdc590f92fa432ffa1401689756f3d047b0185702cb908bb3302cec2449b.txt", "url": "https://api.github.com/repos/infiniflow/ragflow/languages"}], "summary": "RAGFlow is a full self-hostable RAG application and engine for document ingestion, knowledge compilation, retrieval and grounded-answer workflows.", "technology_stack": ["Go backend services; GitHub language statistics list Go, TypeScript, C++, Python, C.", "README documents React frontend development with Node.js/npm and Go services; GitHub API languages additionally show TypeScript and C++ as substantial repository languages."], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:325724738','Grafana Pyroscope','{"deployment": ["README documents running the server with Docker (`docker run -p 4040:4040 grafana/pyroscope`) and links to Kubernetes deployment documentation; no code was executed."], "features": ["Collects continuous profiling data from application SDKs or profiling agents.", "Stores and processes profiles and serves profile queries; users can compare profiles and inspect flame graphs/line-level performance findings.", "Supports production continuous profiling across application services and multiple supported languages."], "github_repository_id": 325724738, "homepage": "https://grafana.com/oss/pyroscope/", "id": "github:325724738", "leaf_matches": [{"reason": "GitHub README describes Pyroscope as a continuous profiling platform for CPU, memory and I/O, with server-side profile storage/query and line-level performance drilldown; it documents running server via Docker. This matches runtime profiling and profile exploration rather than logs or traces.", "slug": "profiler", "source_urls": ["https://api.github.com/repos/grafana/pyroscope", "https://api.github.com/repos/grafana/pyroscope/license", "https://raw.githubusercontent.com/grafana/pyroscope/main/LICENSE", "https://raw.githubusercontent.com/grafana/pyroscope/main/README.md", "https://api.github.com/repos/grafana/pyroscope/languages"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/grafana/pyroscope/license", "license_review": {"rationale": "GitHub metadata identifies GNU Affero GPL v3.0; the official raw LICENSE snapshot contains the full AGPL v3 text (34,523 bytes).", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/grafana/pyroscope/license", "spdx_id": "AGPL-3.0"}, "name": "Grafana Pyroscope", "repository_url": "https://github.com/grafana/pyroscope", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:27.239089+08:00", "kind": "repository_metadata", "sha256": "23cc9a53cccbacb195fff3f858a9d26c41481e1a70dcfacd0430ea801c988ae4", "snapshot_path": "sources/23cc9a53cccbacb195fff3f858a9d26c41481e1a70dcfacd0430ea801c988ae4.txt", "url": "https://api.github.com/repos/grafana/pyroscope"}, {"fetched_at": "2026-10-23T19:05:28.884458+08:00", "kind": "license", "sha256": "b660c06d5a84fd5f4ebdcaefc0dd35f0a49a0f431b4f86eaee4061983e207b06", "snapshot_path": "sources/b660c06d5a84fd5f4ebdcaefc0dd35f0a49a0f431b4f86eaee4061983e207b06.txt", "url": "https://api.github.com/repos/grafana/pyroscope/license"}, {"fetched_at": "2026-10-23T19:06:05.245912+08:00", "kind": "license", "sha256": "8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef", "snapshot_path": "sources/8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef.txt", "url": "https://raw.githubusercontent.com/grafana/pyroscope/main/LICENSE"}, {"fetched_at": "2026-10-23T19:05:30.313404+08:00", "kind": "readme", "sha256": "85587a114f0fcdfc7472f89de29cf7aa68c5a66a6b3fe00578eadf8a508565c6", "snapshot_path": "sources/85587a114f0fcdfc7472f89de29cf7aa68c5a66a6b3fe00578eadf8a508565c6.txt", "url": "https://raw.githubusercontent.com/grafana/pyroscope/main/README.md"}, {"fetched_at": "2026-10-23T19:06:06.562199+08:00", "kind": "repository_metadata", "sha256": "f78cb8a9185e3100e7730d4e2cfe708d70415f09abb367309a25b6a1c3069e5c", "snapshot_path": "sources/f78cb8a9185e3100e7730d4e2cfe708d70415f09abb367309a25b6a1c3069e5c.txt", "url": "https://api.github.com/repos/grafana/pyroscope/languages"}], "summary": "Grafana Pyroscope is an open-source continuous profiling platform that stores and queries application profiles and exposes line-level CPU, memory, and I/O performance analysis.", "technology_stack": ["Go server and agents; GitHub language statistics report Go as the dominant language, plus TypeScript/JavaScript frontend assets.", "Profiles can be sent by Pyroscope SDKs, Grafana Alloy, or OpenTelemetry-compatible sources per README."], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:portkey-ai-gateway','Portkey AI Gateway (PRISMA AIRS)','{"homepage": "https://portkey.ai/", "id": "commercial:portkey-ai-gateway", "leaf_matches": [{"reason": "Portkey official product page says its gateway dynamically switches models, distributes workloads and configures failover rules, uses virtual keys to control provider access, and provides centralized monitoring/governance. Product docs fetch had TLS EOF; the official product-page snapshot itself supplies the route/failover/control evidence.", "slug": "ai-gateway-model-routing-platform", "source_urls": ["https://portkey.ai/features/ai-gateway"]}], "name": "Portkey AI Gateway (PRISMA AIRS)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:07:45.917686+08:00", "kind": "homepage", "sha256": "16cb7107da06a227748539f47d339ac40d0cdfd0290d7238e8d7c43674394ab0", "snapshot_path": "sources/16cb7107da06a227748539f47d339ac40d0cdfd0290d7238e8d7c43674394ab0.txt", "url": "https://portkey.ai/features/ai-gateway"}], "summary": "Portkey provides a managed AI Gateway for routing requests across model providers, configurable failover, caching, virtual-key management, monitoring and governance.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:161133770','Feast','{"deployment": ["README documents pip installation and end-to-end local feature-store workflow, and lists Kubernetes production deployment plus Python feature server options; users deploy/configure their online/offline backing stores. No code was executed."], "features": ["Maintains version-controlled feature definitions and registry metadata.", "Builds point-in-time-correct historical training datasets from the offline store and serves latest entity-keyed feature values from the online store.", "Provides Python SDK/CLI and a deployable REST feature server; supports batch and streaming ingestion patterns."], "github_repository_id": 161133770, "homepage": "https://feast.dev/", "id": "github:161133770", "leaf_matches": [{"reason": "Official README and components docs describe a registry for feature definitions, historical offline store for point-in-time-correct training data, low-latency online serving and feature server returning entity feature values. README also describes install/deploy workflows, including Kubernetes and API serving. This is the feature-store loop, not just a transformation library.", "slug": "feature-store", "source_urls": ["https://api.github.com/repos/feast-dev/feast", "https://api.github.com/repos/feast-dev/feast/license", "https://raw.githubusercontent.com/feast-dev/feast/master/README.md", "https://raw.githubusercontent.com/feast-dev/feast/master/LICENSE", "https://api.github.com/repos/feast-dev/feast/languages", "https://docs.feast.dev/getting-started/components/overview"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/feast-dev/feast/license", "license_review": {"rationale": "GitHub metadata declares Apache-2.0; official raw LICENSE snapshot is the complete Apache License Version 2.0 text (11,358 bytes).", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/feast-dev/feast/license", "spdx_id": "Apache-2.0"}, "name": "Feast", "repository_url": "https://github.com/feast-dev/feast", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:08:29.773899+08:00", "kind": "repository_metadata", "sha256": "37982b1b5dd44857acf5f4d6e9feaf39e2dbe4e2ddc6e585bf3a10d9d36f04cd", "snapshot_path": "sources/37982b1b5dd44857acf5f4d6e9feaf39e2dbe4e2ddc6e585bf3a10d9d36f04cd.txt", "url": "https://api.github.com/repos/feast-dev/feast"}, {"fetched_at": "2026-10-23T19:08:31.433004+08:00", "kind": "license", "sha256": "ea34f4d661b150b2f2f32355e46ac73d4a622466a5a9aa1236c7b73fdd25b083", "snapshot_path": "sources/ea34f4d661b150b2f2f32355e46ac73d4a622466a5a9aa1236c7b73fdd25b083.txt", "url": "https://api.github.com/repos/feast-dev/feast/license"}, {"fetched_at": "2026-10-23T19:08:32.847595+08:00", "kind": "readme", "sha256": "05cec5b98aecbe9d3883f4c01354caeae0fba5b459ffcf2c489c576481b17a03", "snapshot_path": "sources/05cec5b98aecbe9d3883f4c01354caeae0fba5b459ffcf2c489c576481b17a03.txt", "url": "https://raw.githubusercontent.com/feast-dev/feast/master/README.md"}, {"fetched_at": "2026-10-23T19:08:34.000094+08:00", "kind": "license", "sha256": "cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30", "snapshot_path": "sources/cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30.txt", "url": "https://raw.githubusercontent.com/feast-dev/feast/master/LICENSE"}, {"fetched_at": "2026-10-23T19:08:35.392608+08:00", "kind": "repository_metadata", "sha256": "0b0f5b3330fde211c4217fd020dd3d577ae6feca19cbacd72ef429c362138997", "snapshot_path": "sources/0b0f5b3330fde211c4217fd020dd3d577ae6feca19cbacd72ef429c362138997.txt", "url": "https://api.github.com/repos/feast-dev/feast/languages"}, {"fetched_at": "2026-10-23T19:07:45.661277+08:00", "kind": "documentation", "sha256": "ed55436b5839ec26102d55824e0c8e86ab277a547e63049f99ee50ac62ed106c", "snapshot_path": "sources/ed55436b5839ec26102d55824e0c8e86ab277a547e63049f99ee50ac62ed106c.txt", "url": "https://docs.feast.dev/getting-started/components/overview"}], "summary": "Feast is an open-source feature store that catalogs feature definitions, supports point-in-time-correct training datasets, and serves online feature values through its feature server.", "technology_stack": ["Python SDK/CLI and feature server; GitHub API language statistics show Python as primary, with Go, TypeScript and Java for additional components.", "Backs registry/online/offline stores with external infrastructure configured by the operator."], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aws-managed-apache-flink','Amazon Managed Service for Apache Flink','{"homepage": "https://aws.amazon.com/managed-service-apache-flink/", "id": "commercial:aws-managed-apache-flink", "leaf_matches": [{"reason": "AWS official docs describe applications reading unbounded streams, applying user code/SQL transformations and continuously writing results to destinations; AWS hosts the runtime, scaling and durable state.", "slug": "event-stream-processing-platform", "source_urls": ["https://docs.aws.amazon.com/managed-flink/latest/java/", "https://docs.aws.amazon.com/managed-flink/latest/java/how-notebook-durable.html"]}, {"reason": "AWS official docs describe interactive real-time stream queries and dashboards/metrics, plus deploying Studio code into a long-running application that continuously reads streams, writes destinations and retains state. This matches a continuous analytics workflow rather than a generic event broker.", "slug": "stream-analytics-platform", "source_urls": ["https://docs.aws.amazon.com/managed-flink/latest/java/", "https://docs.aws.amazon.com/managed-flink/latest/java/how-notebook-durable.html"]}], "name": "Amazon Managed Service for Apache Flink", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:09:28.879385+08:00", "kind": "documentation", "sha256": "23df73992df44d0b96afb24d9a20ae4b69d80c7f883b31404d5b4ba2172620ed", "snapshot_path": "sources/23df73992df44d0b96afb24d9a20ae4b69d80c7f883b31404d5b4ba2172620ed.txt", "url": "https://docs.aws.amazon.com/managed-flink/latest/java/"}, {"fetched_at": "2026-10-23T19:09:30.114679+08:00", "kind": "documentation", "sha256": "fb9706374010b98fd930b97bf5f279175b328d1dccb4f4d8837764d601c57df2", "snapshot_path": "sources/fb9706374010b98fd930b97bf5f279175b328d1dccb4f4d8837764d601c57df2.txt", "url": "https://docs.aws.amazon.com/managed-flink/latest/java/how-notebook-durable.html"}], "summary": "AWS Managed Service for Apache Flink runs continuous streaming applications and provides hosted infrastructure for SQL, Python, Scala or Java stream analytics.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:elastic-search','Elasticsearch','{"homepage": "https://www.elastic.co/", "id": "commercial:elastic-search", "leaf_matches": [{"reason": "Elastic official Search documentation describes indexing content and querying it through the search API; Elasticsearch returns ranked hits and functions as a platform for applications to embed search.", "slug": "search-platform", "source_urls": ["https://www.elastic.co/docs/solutions/search"]}], "name": "Elasticsearch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:09:18.520835+08:00", "kind": "documentation", "sha256": "405b580fee14f31775ad269248c50dc357dcac9fee412083b4a5c36f01f518c7", "snapshot_path": "sources/405b580fee14f31775ad269248c50dc357dcac9fee412083b4a5c36f01f518c7.txt", "url": "https://www.elastic.co/docs/solutions/search"}], "summary": "Elasticsearch is a search platform that indexes supplied content and serves programmatic search queries with relevance-ranked results.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:nutanix-prism','Nutanix Prism','{"homepage": "https://www.nutanix.com/products/prism", "id": "commercial:nutanix-prism", "leaf_matches": [{"reason": "Nutanix 官方 Prism 页面将其描述为企业控制与混合云管理界面；结合官方资料中 Prism 为 HCI 控制平面/管理控制台，支持此叶子的管理软件匹配。", "slug": "hyperconverged-infrastructure-management", "source_urls": ["https://www.nutanix.com/products/prism"]}], "name": "Nutanix Prism", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:01.381659+08:00", "kind": "homepage", "sha256": "47d67b4572de8d14e7fa2275dd686df5559e2103a1b822c884d65aed73706fa4", "snapshot_path": "sources/47d67b4572de8d14e7fa2275dd686df5559e2103a1b822c884d65aed73706fa4.txt", "url": "https://www.nutanix.com/products/prism"}], "summary": "Nutanix Prism 是管理 Nutanix 集群及混合云环境的控制平台；本条索引其 HCI 集群管理软件用途。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sift-account-defense','Sift Platform (including Account Defense)','{"homepage": "https://sift.com/platform/account-defense/", "id": "commercial:sift-account-defense", "leaf_matches": [{"reason": "Sift 官方说明其平台用行为、设备、速度和网络信号检测账户接管，并支持登录决策与调查；该功能直接覆盖账户滥用防护。", "slug": "account-abuse-protection", "source_urls": ["https://sift.com/platform/account-defense/"]}, {"reason": "Sift 官网明确将产品定义为 fraud prevention platform，并说明以实时机器学习识别欺诈，持续覆盖支付欺诈、账户接管和账户滥用；客户可在消费旅程多个阶段执行风险决策。", "slug": "fraud-prevention-platform", "source_urls": ["https://sift.com/"]}], "name": "Sift Platform (including Account Defense)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:12.521516+08:00", "kind": "homepage", "sha256": "ce5de3692c9b9d85dbd3464d93f23c0269af9783bab29eac793989bbfc04f290", "snapshot_path": "sources/ce5de3692c9b9d85dbd3464d93f23c0269af9783bab29eac793989bbfc04f290.txt", "url": "https://sift.com/platform/account-defense/"}, {"fetched_at": "2026-10-23T19:05:06.764013+08:00", "kind": "documentation", "sha256": "1a83fcd6d09e27f3eec0cc41ad454d0e4505287395fe9ba3f4936dfdf143cb9f", "snapshot_path": "sources/1a83fcd6d09e27f3eec0cc41ad454d0e4505287395fe9ba3f4936dfdf143cb9f.txt", "url": "https://sift.com/"}], "summary": "面向企业的反欺诈平台，结合账户风险与交易风险信号，支持调查、决策和风险处置；此处同时记录其Account Defense子产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cloudflare-security-platform','Cloudflare Security Platform','{"homepage": "https://cloudflare.com/", "id": "commercial:cloudflare-security-platform", "leaf_matches": [{"reason": "Cloudflare 官方产品与配置文档说明管理员在 Gateway HTTP policy 中创建 Isolate/Do Not Isolate 策略、设置访问和文件/剪贴板控制，并验证隔离状态，构成可管理的浏览器安全工作流。", "slug": "browser-security-platform", "source_urls": ["https://www.cloudflare.com/sase/products/browser-isolation/", "https://developers.cloudflare.com/cloudflare-one/remote-browser-isolation/setup/"]}, {"reason": "Cloudflare 官方文档展示账户用户在 Dashboard 配置 HTTP DDoS ruleset 的 scope、action、sensitivity 与自定义表达式，并可在 Security Events/Network Analytics 查看缓解事件和流量。软件工作流及客户配置主体可核验。", "slug": "ddos-protection-platform", "source_urls": ["https://developers.cloudflare.com/ddos-protection/managed-rulesets/http/http-overrides/configure-dashboard/", "https://developers.cloudflare.com/ddos-protection/reference/analytics/"]}, {"reason": "Cloudflare WAF 文档支持 dashboard 配置 WAF rules，Security Events 展示受阻/标记请求、按服务过滤并用于调查误报与调整规则，构成客户运营控制台工作流。", "slug": "web-application-firewall-waf", "source_urls": ["https://www.cloudflare.com/products/waf/", "https://developers.cloudflare.com/waf/analytics/security-events/"]}], "name": "Cloudflare Security Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:17.063197+08:00", "kind": "homepage", "sha256": "3a76a68629f6284ea0b6030948fd4e7d740d2dd0fcfde11688fb0b9277481852", "snapshot_path": "sources/3a76a68629f6284ea0b6030948fd4e7d740d2dd0fcfde11688fb0b9277481852.txt", "url": "https://www.cloudflare.com/sase/products/browser-isolation/"}, {"fetched_at": "2026-10-23T18:51:22.727698+08:00", "kind": "homepage", "sha256": "98c7720ea94e164bed0b8ba9e1d200ec0c50b11800a07ca6c82baf7c0b2fb25d", "snapshot_path": "sources/98c7720ea94e164bed0b8ba9e1d200ec0c50b11800a07ca6c82baf7c0b2fb25d.txt", "url": "https://www.cloudflare.com/ddos/"}, {"fetched_at": "2026-10-23T18:49:36.956071+08:00", "kind": "homepage", "sha256": "2d5460d278cf04c64120f415f8446040dca4d1f58bbe09574501c6f83ece3ffd", "snapshot_path": "sources/2d5460d278cf04c64120f415f8446040dca4d1f58bbe09574501c6f83ece3ffd.txt", "url": "https://www.cloudflare.com/products/waf/"}, {"fetched_at": "2026-10-23T18:56:00.387614+08:00", "kind": "documentation", "sha256": "3522b1f4dd1c5f11937411bcbfb897a8856f61ae7eb328e2f230ec3c457e5c9a", "snapshot_path": "sources/3522b1f4dd1c5f11937411bcbfb897a8856f61ae7eb328e2f230ec3c457e5c9a.txt", "url": "https://developers.cloudflare.com/ddos-protection/managed-rulesets/http/http-overrides/configure-dashboard/"}, {"fetched_at": "2026-10-23T18:55:58.806823+08:00", "kind": "documentation", "sha256": "2a97322c7b1ada81285450c96b2b3d6ab842f7817fac1e143620a8d38838eb3e", "snapshot_path": "sources/2a97322c7b1ada81285450c96b2b3d6ab842f7817fac1e143620a8d38838eb3e.txt", "url": "https://developers.cloudflare.com/ddos-protection/reference/analytics/"}, {"fetched_at": "2026-10-23T18:57:03.931073+08:00", "kind": "documentation", "sha256": "f56cef2fb6394a03aacb87084966e89c243b3225fc0bbbedc7e08f7fb97b5731", "snapshot_path": "sources/f56cef2fb6394a03aacb87084966e89c243b3225fc0bbbedc7e08f7fb97b5731.txt", "url": "https://developers.cloudflare.com/cloudflare-one/remote-browser-isolation/setup/"}, {"fetched_at": "2026-10-23T18:57:03.673608+08:00", "kind": "documentation", "sha256": "8826bfbc9a7a9df91cc9e9bd50dfc752dfc405972b5dc5a9e7b5a4a69506b60c", "snapshot_path": "sources/8826bfbc9a7a9df91cc9e9bd50dfc752dfc405972b5dc5a9e7b5a4a69506b60c.txt", "url": "https://developers.cloudflare.com/waf/analytics/security-events/"}], "summary": "Cloudflare 提供云端安全服务组合，本条索引其 Browser Isolation、DDoS 防护和 WAF 软件能力。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:proofpoint-email-protection','Proofpoint Core Email Protection','{"homepage": "https://www.proofpoint.com/us/products/email-protection", "id": "commercial:proofpoint-email-protection", "leaf_matches": [{"reason": "Proofpoint 官方产品页明确覆盖 secure email gateway（SEG）部署及邮件威胁检测，可作为企业邮件安全网关产品索引。", "slug": "email-security-gateway", "source_urls": ["https://www.proofpoint.com/us/products/email-protection"]}], "name": "Proofpoint Core Email Protection", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:58.649207+08:00", "kind": "homepage", "sha256": "bffa71a6796cdb6305d859e0b8602eff4d74d68d3dce456d0c331561ab005157", "snapshot_path": "sources/bffa71a6796cdb6305d859e0b8602eff4d74d68d3dce456d0c331561ab005157.txt", "url": "https://www.proofpoint.com/us/products/email-protection"}], "summary": "Proofpoint Core Email Protection 为组织提供邮件威胁检测与防护，支持网关和 API 部署方式。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hashicorp-vault','HashiCorp Vault','{"homepage": "https://hashicorp.com/", "id": "commercial:hashicorp-vault", "leaf_matches": [{"reason": "HashiCorp 官方 Key Management 文档明确企业版引擎供授权用户生成密钥、分发到 AWS KMS/Azure Key Vault/GCP Cloud KMS 并管理生命周期；此记录仅指该商业企业版能力，不将 Vault 本身存储屏障误作客户 KMS。", "slug": "encryption-key-management", "source_urls": ["https://developer.hashicorp.com/vault/docs/secrets/key-management"]}], "name": "HashiCorp Vault", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:51:56.206338+08:00", "kind": "homepage", "sha256": "1398aa44d8905ac464e46104d720adf4423f97730bc134cb0db6c92a1ede37f2", "snapshot_path": "sources/1398aa44d8905ac464e46104d720adf4423f97730bc134cb0db6c92a1ede37f2.txt", "url": "https://developer.hashicorp.com/vault/docs/about-vault/how-vault-works"}, {"fetched_at": "2026-10-23T18:57:05.241126+08:00", "kind": "documentation", "sha256": "99be26e35c19d6ff86ea63f15a953f02fe16e088ea9b522fef6dfb1463f8d845", "snapshot_path": "sources/99be26e35c19d6ff86ea63f15a953f02fe16e088ea9b522fef6dfb1463f8d845.txt", "url": "https://developer.hashicorp.com/vault/docs/secrets/key-management"}], "summary": "HashiCorp Vault 企业 Key Management secrets engine 提供跨云 KMS 的密钥生成、分发和生命周期管理；该能力需 Vault Enterprise Advanced Data Protection。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:279592699','Harvester','{"deployment": ["从 ISO 在裸机服务器安装并建立或加入 Harvester 集群", "生产部署需要满足官方列出的服务器硬件、存储和网络要求"], "features": ["虚拟机创建、编辑、克隆、删除与迁移", "分布式块存储、备份、快照与恢复", "集群网络管理", "通过 Rancher 管理虚拟机和 Kubernetes 集群"], "github_repository_id": 279592699, "homepage": "https://harvesterhci.io/", "id": "github:279592699", "leaf_matches": [{"reason": "Harvester 官方 README 将项目定义为 Kubernetes 上的 HCI 方案，明确覆盖集群虚拟机生命周期、每节点本地存储组成的分布式存储池、集群网络和裸机节点扩缩集群，直接匹配该叶子。", "slug": "hyperconverged-infrastructure-management", "source_urls": ["https://raw.githubusercontent.com/harvester/harvester/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/harvester/harvester/license", "name": "Harvester", "repository_url": "https://github.com/harvester/harvester", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:53:25.592871+08:00", "kind": "repository_metadata", "sha256": "d57c15486cb6196cebe858e0b3b519961df1267a8206e77b6284d3504c512682", "snapshot_path": "sources/d57c15486cb6196cebe858e0b3b519961df1267a8206e77b6284d3504c512682.txt", "url": "https://api.github.com/repos/harvester/harvester"}, {"fetched_at": "2026-10-23T18:53:21.698736+08:00", "kind": "readme", "sha256": "d418eed16817435b250e772b85b6d2e318c25bbfbb4d9c59e638d5310baf3a4f", "snapshot_path": "sources/d418eed16817435b250e772b85b6d2e318c25bbfbb4d9c59e638d5310baf3a4f.txt", "url": "https://raw.githubusercontent.com/harvester/harvester/master/README.md"}, {"fetched_at": "2026-10-23T18:53:24.625458+08:00", "kind": "license", "sha256": "696f17ad58875de9f695d0000c42f69e7b9055f287615c74a0aa6b59e1fdbdfd", "snapshot_path": "sources/696f17ad58875de9f695d0000c42f69e7b9055f287615c74a0aa6b59e1fdbdfd.txt", "url": "https://api.github.com/repos/harvester/harvester/license"}], "summary": "Harvester 是基于 Kubernetes 的开源 HCI 软件平台，提供虚拟机、分布式存储和网络的集群管理；需在裸机服务器集群部署。", "technology_stack": ["Kubernetes", "KubeVirt", "Longhorn", "Go (GitHub metadata primary language)"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fortinet-fortideceptor','Fortinet FortiDeceptor','{"homepage": "https://www.fortinet.com/products/fortideceptor", "id": "commercial:fortinet-fortideceptor", "leaf_matches": [{"reason": "Fortinet 官方产品页明确称其为 deception platform，说明可动态部署 IT/OT/IoT 诱饵、监控攻击活动并分析事件，另有 FortiDeceptor-as-a-Service 云托管方案。", "slug": "deception-platform", "source_urls": ["https://www.fortinet.com/products/fortideceptor"]}], "name": "Fortinet FortiDeceptor", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:54:01.486059+08:00", "kind": "homepage", "sha256": "86175c76f3165a1449e1ab9ade06844fced8b3135f3fc407076746178703d24b", "snapshot_path": "sources/86175c76f3165a1449e1ab9ade06844fced8b3135f3fc407076746178703d24b.txt", "url": "https://www.fortinet.com/products/fortideceptor"}], "summary": "FortiDeceptor 通过部署诱饵资产引导并识别攻击者，提供攻击活动分析和响应能力，含 SaaS 云托管方案。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:anyrun-interactive-sandbox','ANY.RUN Interactive Sandbox','{"homepage": "https://any.run/", "id": "commercial:anyrun-interactive-sandbox", "leaf_matches": [{"reason": "ANY.RUN 官方站点描述上传文件或提交链接后，在云端交互式隔离虚拟机中观察恶意软件行为、IOC 和网络活动并生成报告，符合恶意软件分析沙箱。", "slug": "malware-analysis-sandbox", "source_urls": ["https://any.run/"]}], "name": "ANY.RUN Interactive Sandbox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:54:18.471664+08:00", "kind": "homepage", "sha256": "b18578fc8a2b7564cb8332d1262bc7c75b36c56fcf6c081312b469c398d28331", "snapshot_path": "sources/b18578fc8a2b7564cb8332d1262bc7c75b36c56fcf6c081312b469c398d28331.txt", "url": "https://any.run/"}], "summary": "ANY.RUN 提供云端交互式恶意软件分析沙箱，安全团队可运行样本、观察行为并查看分析报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:securityscorecard-ratings','SecurityScorecard Ratings','{"homepage": "https://securityscorecard.com/", "id": "commercial:securityscorecard-ratings", "leaf_matches": [{"reason": "SecurityScorecard 官方 Ratings 支持页说明其按公开信息生成 scorecard，组织可创建账号、监测自身态势、管理 Digital Footprint、处理评分 findings；Global/Portfolio Search 支持对 Scorecards、Portfolio 和标签搜索与风险组合审阅。", "slug": "security-ratings-platform", "source_urls": ["https://support.securityscorecard.com/hc/en-us/articles/34553563610011-Ability-to-remove-a-scorecard-from-the-Ratings-Platform", "https://support.securityscorecard.com/hc/en-us/articles/5480238771739-Find-what-you-need-quickly-with-Global-and-Portfolio-Searches"]}], "name": "SecurityScorecard Ratings", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:53:59.606853+08:00", "kind": "homepage", "sha256": "644286c94ea376a3b01b2e5088eeab5f6981bf2561858c7b7535673e9f37a303", "snapshot_path": "sources/644286c94ea376a3b01b2e5088eeab5f6981bf2561858c7b7535673e9f37a303.txt", "url": "https://securityscorecard.com/"}, {"fetched_at": "2026-10-23T18:57:03.099900+08:00", "kind": "documentation", "sha256": "541a73565958637f2ca3d18f8e2816e31ab16e3cc559ea46f16f7567c54ffc27", "snapshot_path": "sources/541a73565958637f2ca3d18f8e2816e31ab16e3cc559ea46f16f7567c54ffc27.txt", "url": "https://support.securityscorecard.com/hc/en-us/articles/34553563610011-Ability-to-remove-a-scorecard-from-the-Ratings-Platform"}, {"fetched_at": "2026-10-23T18:57:03.806734+08:00", "kind": "documentation", "sha256": "0d4a9afd2d819379cab1405aa990187bcf8de093e3d333415000bc6423fdcb42", "snapshot_path": "sources/0d4a9afd2d819379cab1405aa990187bcf8de093e3d333415000bc6423fdcb42.txt", "url": "https://support.securityscorecard.com/hc/en-us/articles/5480238771739-Find-what-you-need-quickly-with-Global-and-Portfolio-Searches"}], "summary": "SecurityScorecard Ratings 为组织持续评估、跟踪和沟通网络安全风险评级，支持自我监测及第三方风险工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:azure-digital-twins','Azure Digital Twins','{"homepage": "https://learn.microsoft.com/en-us/azure/digital-twins/", "id": "commercial:azure-digital-twins", "leaf_matches": [{"reason": "官方文档明确说明客户用 DTDL 定义可复用模型，再按模型创建具名数字孪生实例；孪生实例持久保存在服务图中，可连接成关系图；管理文档展示创建、读取、JSON Patch 更新实例及查询 API，状态属性可带 lastUpdateTime/sourceTime。满足模型、实例、状态同步接口和查询核心。", "slug": "digital-twin-platform", "source_urls": ["https://learn.microsoft.com/en-us/azure/digital-twins/concepts-models", "https://learn.microsoft.com/en-us/azure/digital-twins/concepts-twins-graph", "https://learn.microsoft.com/en-us/azure/digital-twins/how-to-manage-twin", "https://learn.microsoft.com/en-us/azure/digital-twins/concepts-query-language"]}], "name": "Azure Digital Twins", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:13:05.596365+08:00", "kind": "documentation", "sha256": "3a5e521ce0081e03357b6a76251cb0174ad9121dc7ff3d73e9f4eedc22b95fa7", "snapshot_path": "sources/3a5e521ce0081e03357b6a76251cb0174ad9121dc7ff3d73e9f4eedc22b95fa7.txt", "url": "https://learn.microsoft.com/en-us/azure/digital-twins/concepts-models"}, {"fetched_at": "2026-10-23T19:13:06.654382+08:00", "kind": "documentation", "sha256": "5a1e47f0c09c20ae5dcf5cf5f2051633a02611ede9d4d534585fb4a8fe718257", "snapshot_path": "sources/5a1e47f0c09c20ae5dcf5cf5f2051633a02611ede9d4d534585fb4a8fe718257.txt", "url": "https://learn.microsoft.com/en-us/azure/digital-twins/concepts-twins-graph"}, {"fetched_at": "2026-10-23T19:13:07.062118+08:00", "kind": "documentation", "sha256": "6e1c4f130b39f1d46be15768a7fa277a631ef7777bf56f3fa23ca663cc06e405", "snapshot_path": "sources/6e1c4f130b39f1d46be15768a7fa277a631ef7777bf56f3fa23ca663cc06e405.txt", "url": "https://learn.microsoft.com/en-us/azure/digital-twins/how-to-manage-twin"}, {"fetched_at": "2026-10-23T19:13:06.240956+08:00", "kind": "documentation", "sha256": "3573b17f84cf8ff75f69590c9e9d03f74fe5f1fac429beaf9cbadf8610f34dc3", "snapshot_path": "sources/3573b17f84cf8ff75f69590c9e9d03f74fe5f1fac429beaf9cbadf8610f34dc3.txt", "url": "https://learn.microsoft.com/en-us/azure/digital-twins/concepts-query-language"}], "summary": "Azure Digital Twins 是用于建立和查询数字孪生图的云服务：客户定义 DTDL 模型、创建具名孪生实例及关系，并通过 API 更新和查询实例状态。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:siemens-insights-hub','Siemens Insights Hub','{"homepage": "https://siemens.com/en-gb/products/insights-hub/capabilities/", "id": "commercial:siemens-insights-hub", "leaf_matches": [{"reason": "官方Asset Management与MindConnect agent正文支持持久设备/agent资产、ID、类型属性和凭据配置；官方FAQ明确Asset Manager可查看每个已接入agent/device的连接状态，并支持MQTT、S7、OPC UA双向通信，覆盖设备注册和双向运营软件核心。", "slug": "industrial-iot-platform", "source_urls": ["https://developer.siemens.com/insights-hub/docs/apis/advanced-assetmanagement/api-assetmanagement-overview.html", "https://developer.siemens.com/industrial-iot-open-source/mindconnect-nodejs/agent-development/index.html", "https://www.siemens.com/en-gb/products/insights-hub/resources/faq/"]}], "name": "Siemens Insights Hub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:55:14.448468+08:00", "kind": "homepage", "sha256": "cf600624ffbab44d2ec913b72de7be67345ad05a849a3dc5b7412d7ecf58a741", "snapshot_path": "sources/cf600624ffbab44d2ec913b72de7be67345ad05a849a3dc5b7412d7ecf58a741.txt", "url": "https://www.siemens.com/en-gb/products/insights-hub/capabilities/"}, {"fetched_at": "2026-10-23T19:13:45.623165+08:00", "kind": "documentation", "sha256": "02f7cbcaa573d90745189b4111e45b9501c3e1306c127e240b4ba64a8bec1816", "snapshot_path": "sources/02f7cbcaa573d90745189b4111e45b9501c3e1306c127e240b4ba64a8bec1816.txt", "url": "https://www.siemens.com/en-gb/products/insights-hub/resources/faq/"}, {"fetched_at": "2026-10-23T19:13:42.374171+08:00", "kind": "documentation", "sha256": "e9bef28de424546f848b50fe6750f49c8fdc4461d4cf9592c844effc7bb2552c", "snapshot_path": "sources/e9bef28de424546f848b50fe6750f49c8fdc4461d4cf9592c844effc7bb2552c.txt", "url": "https://developer.siemens.com/insights-hub/docs/apis/advanced-assetmanagement/api-assetmanagement-overview.html"}, {"fetched_at": "2026-10-23T19:14:14.795050+08:00", "kind": "documentation", "sha256": "7a41f41da76b23b88d24e6908bf99a14378750105af2cb1b854814267b95a998", "snapshot_path": "sources/7a41f41da76b23b88d24e6908bf99a14378750105af2cb1b854814267b95a998.txt", "url": "https://developer.siemens.com/industrial-iot-open-source/mindconnect-nodejs/agent-development/index.html"}], "summary": "Siemens Insights Hub 提供工业资产和设备管理、连接状态查看、数据建模以及面向现场设备的双向通信和命令接口。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aveva-pi-system','AVEVA PI System','{"homepage": "https://aveva.com/", "id": "commercial:aveva-pi-system", "leaf_matches": [{"reason": "AVEVA 官方说明 PI System 用于采集、清洗、存储、丰富并可视化工业实时运营数据，覆盖工业历史数据库核心用途。", "slug": "industrial-historian", "source_urls": ["https://www.aveva.com/en/products/aveva-pi-system/"]}], "name": "AVEVA PI System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:55:15.788513+08:00", "kind": "homepage", "sha256": "d7d63254d3faf5fedea8d31f894d2d88b626d5a837d22fb08dae69a4143c01a8", "snapshot_path": "sources/d7d63254d3faf5fedea8d31f894d2d88b626d5a837d22fb08dae69a4143c01a8.txt", "url": "https://www.aveva.com/en/products/aveva-pi-system/"}], "summary": "AVEVA PI System 为工业组织提供运营数据的采集、清洗、存储、丰富和可视化能力，是工业历史数据管理软件套件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:autodesk-forma-model-coordination','Autodesk BIM Model Coordination','{"homepage": "https://autodesk.com/", "id": "commercial:autodesk-forma-model-coordination", "leaf_matches": [{"reason": "官方静态正文直接描述协调空间关联持久Document Management文件夹，聚合多方模型，版本上传触发自动碰撞检查；团队可创建问题并管理协调空间和访问权限，符合云端BIM协调工作流。", "slug": "bim-coordination", "source_urls": ["https://help.autodesk.com/cloudhelp/ENU/BIM360D-Model-Coordination/files/BIM360D_Model_Coordination_Model_Coordination_FAQs_html.html", "https://help.autodesk.com/cloudhelp/ENU/BIM360D-Design-Collaboration/files/About-Managing-Teams-and-Team/Design_Collaboration_Coordination_Spaces.html"]}], "name": "Autodesk BIM Model Coordination", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:12:39.027562+08:00", "kind": "documentation", "sha256": "d0bd07f4ca9be341f82711739def99a40839a146519c3683f8353503e62ef4b6", "snapshot_path": "sources/d0bd07f4ca9be341f82711739def99a40839a146519c3683f8353503e62ef4b6.txt", "url": "https://help.autodesk.com/cloudhelp/ENU/BIM360D-Model-Coordination/files/BIM360D_Model_Coordination_Model_Coordination_FAQs_html.html"}, {"fetched_at": "2026-10-23T19:12:40.380779+08:00", "kind": "documentation", "sha256": "f45645e0cc5267c84629965ff8480cb13490ae0fba71b5627e9b9dbc621eceef", "snapshot_path": "sources/f45645e0cc5267c84629965ff8480cb13490ae0fba71b5627e9b9dbc621eceef.txt", "url": "https://help.autodesk.com/cloudhelp/ENU/BIM360D-Design-Collaboration/files/About-Managing-Teams-and-Team/Design_Collaboration_Coordination_Spaces.html"}], "summary": "面向建设项目团队的云端模型协调软件，维护协调空间、聚合模型和版本，执行碰撞检测并支持问题创建。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:materialise-co-am','Materialise CO-AM','{"homepage": "https://www.materialise.com/", "id": "commercial:materialise-co-am", "leaf_matches": [{"reason": "CO-AM源页将应用覆盖从订单管理、构建准备到质量和交付；Magics源页证明用户可导入/编辑/修复/嵌套/切片及准备3D打印构建。服务与生产设备集成不影响其软件完整工作流。", "slug": "additive-manufacturing-software", "source_urls": ["https://www.materialise.com/en/industrial/software/co-am-software-platform", "https://www.materialise.com/en/industrial/software/magics-data-build-preparation"]}], "name": "Materialise CO-AM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:36.808004+08:00", "kind": "documentation", "sha256": "48a221ae0f0b053cf8336276c7450cd75c20c8ba5f691cb5fc67b70b6de2032f", "snapshot_path": "sources/48a221ae0f0b053cf8336276c7450cd75c20c8ba5f691cb5fc67b70b6de2032f.txt", "url": "https://www.materialise.com/en/industrial/software/co-am-software-platform"}, {"fetched_at": "2026-10-23T19:03:35.967564+08:00", "kind": "documentation", "sha256": "6658d85f919c5851bf59be1fa769cffc5dc7d6f2f81a692dc2cc8f79caf2b862", "snapshot_path": "sources/6658d85f919c5851bf59be1fa769cffc5dc7d6f2f81a692dc2cc8f79caf2b862.txt", "url": "https://www.materialise.com/en/industrial/software/magics-data-build-preparation"}], "summary": "Materialise CO-AM 是增材制造生产软件平台，连接订单管理、构建准备、质量和交付工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:autodesk-revit','Autodesk Revit + Cloud Worksharing','{"homepage": "https://autodesk.com/", "id": "commercial:autodesk-revit", "leaf_matches": [{"reason": "官方帮助文档说明用户在建筑模型中创建机械风管、电气回路及管道系统，布置、路由与检查系统连接；该套件能力覆盖MEP设计工作流。 官方Cloud Worksharing正文另明确Autodesk Docs项目、邀请成员、并发修改云模型、与中央模型同步及向外部成员发布；只确认这一实际在线协作形态。", "slug": "mep-design", "source_urls": ["https://help.autodesk.com/cloudhelp/2024/ENU/Revit-MEPEng/files/GUID-195C2C6C-5E2C-422E-A44D-FB3FDFDE276A.htm", "https://help.autodesk.com/cloudhelp/2024/ENU/Revit-Cloud/files/GUID-ABFFFEE6-2C6D-4779-B508-A1C4BC0C4885.htm"]}], "name": "Autodesk Revit + Cloud Worksharing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:06.176667+08:00", "kind": "documentation", "sha256": "574bc5aaf8dc4e58b9acdc22a865d995571f70d456aeaec958af931d0d5011c2", "snapshot_path": "sources/574bc5aaf8dc4e58b9acdc22a865d995571f70d456aeaec958af931d0d5011c2.txt", "url": "https://help.autodesk.com/cloudhelp/2024/ENU/Revit-MEPEng/files/GUID-195C2C6C-5E2C-422E-A44D-FB3FDFDE276A.htm"}, {"fetched_at": "2026-10-23T19:10:44.756568+08:00", "kind": "documentation", "sha256": "c59dcfa61fadf31b3572a99189960b00ec9c4db4c1d9acc2080b6e36bf53c2ca", "snapshot_path": "sources/c59dcfa61fadf31b3572a99189960b00ec9c4db4c1d9acc2080b6e36bf53c2ca.txt", "url": "https://help.autodesk.com/cloudhelp/2024/ENU/Revit-Cloud/files/GUID-ABFFFEE6-2C6D-4779-B508-A1C4BC0C4885.htm"}], "summary": "面向MEP团队的模型设计软件；本条确认结合Cloud Worksharing共享云端中央模型、并发修改及同步的协作形态，仍使用Revit原生客户端。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:transunion-smartmove','TransUnion SmartMove','{"homepage": "https://www.mysmartmove.com/", "id": "commercial:transunion-smartmove", "leaf_matches": [{"reason": "官方页面展示房东建账户、邀请申请人、由申请人同意并完成筛查、报告回到房东的闭环，并提供信用、刑事、驱逐等报告。", "slug": "tenant-screening-platform", "source_urls": ["https://www.mysmartmove.com/"]}], "name": "TransUnion SmartMove", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:34.783781+08:00", "kind": "documentation", "sha256": "fb29a61b0e6210725367fa19e38ac8665f753781980f2a5a913f917395284fa8", "snapshot_path": "sources/fb29a61b0e6210725367fa19e38ac8665f753781980f2a5a913f917395284fa8.txt", "url": "https://www.mysmartmove.com/"}], "summary": "SmartMove 为房东提供线上租客筛查申请、授权及报告流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:navionix-flight-planning','Navionix Flight Planning','{"homepage": "https://www.navionix.com/", "id": "commercial:navionix-flight-planning", "leaf_matches": [{"reason": "官方产品原文称其为 airline flight planning and dispatch solution，并说明天气/NOTAM/空域/机型性能输入、航路规划、成本优化与派遣操作。", "slug": "flight-planning-application", "source_urls": ["https://www.navionix.com/"]}], "name": "Navionix Flight Planning", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:36.224615+08:00", "kind": "documentation", "sha256": "470183d25cfd9dd259a951db56da5873b0c972ca6bef2382424c2aa9d6b63082", "snapshot_path": "sources/470183d25cfd9dd259a951db56da5873b0c972ca6bef2382424c2aa9d6b63082.txt", "url": "https://www.navionix.com/"}], "summary": "Navionix 为航空公司运营控制与派遣团队提供航班计划、实时优化和合规工作区。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:solonport-terminal-operating-system','SOLONPORT Terminal Operating System','{"homepage": "https://solonport.com/", "id": "commercial:solonport-terminal-operating-system", "leaf_matches": [{"reason": "官方产品原文将船舶靠泊、堆场/货物、闸口称重、计费及现场移动事件置于共享操作视图；符合港口终端运营工作流。", "slug": "port-terminal-operating-system", "source_urls": ["https://solonport.com/products/terminal-operating-system"]}], "name": "SOLONPORT Terminal Operating System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:36.401650+08:00", "kind": "documentation", "sha256": "4121985dad8ba4b6a962c873ebffe80dbc07950e952f750e9d7aaf6021d021c3", "snapshot_path": "sources/4121985dad8ba4b6a962c873ebffe80dbc07950e952f750e9d7aaf6021d021c3.txt", "url": "https://solonport.com/products/terminal-operating-system"}], "summary": "SOLONPORT TOS 将港口的计划、现场执行、自动化和商业流程连接在统一操作系统中。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zeronorth-propel','ZeroNorth Propel','{"homepage": "https://zeronorth.com/propel", "id": "commercial:zeronorth-propel", "leaf_matches": [{"reason": "官方 Propel 正文说明系统生成可供审核的航次计划、向船长发送计划并处理船长回复形成更新计划，条件变化时重新规划；Plan Ahead 页面补充可提前规划航次腿、比较/分享计划并在激活后执行。覆盖客户航次计划、船岸指令/反馈和偏差响应工作流。产品标注 Early Access，因此这是官方证明的软件能力，不代表一般可购买状态。", "slug": "vessel-operations-platform", "source_urls": ["https://www.zeronorth.com/propel", "https://info.zeronorth.com/plan_ahead_and_share_voyage_plan"]}], "name": "ZeroNorth Propel", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:13:05.600385+08:00", "kind": "documentation", "sha256": "ffe1d5b23ed30c851b11b0ef38d091eb162972005af6dd002c2477ee099f5773", "snapshot_path": "sources/ffe1d5b23ed30c851b11b0ef38d091eb162972005af6dd002c2477ee099f5773.txt", "url": "https://www.zeronorth.com/propel"}, {"fetched_at": "2026-10-23T19:13:05.437151+08:00", "kind": "documentation", "sha256": "9607573f6148ebcabeef501a4d49d32dcee4779dbb4081e91581428f0ceb53d0", "snapshot_path": "sources/9607573f6148ebcabeef501a4d49d32dcee4779dbb4081e91581428f0ceb53d0.txt", "url": "https://info.zeronorth.com/plan_ahead_and_share_voyage_plan"}], "summary": "ZeroNorth Propel 是面向船舶运营团队的航次优化软件：生成和审核航次计划、与船长交换计划反馈，并在条件变化时重新优化。该产品页面标注 Early Access。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:enerzolve-hes','Enerzolve Head End System','{"homepage": "https://enerzolve.com/", "id": "commercial:enerzolve-hes", "leaf_matches": [{"reason": "官方原文称HES是AMI操作软件层，支持定时读数采集、设备通信会话、远程固件与命令、仪表集群健康监控；可作为AMI平台软件匹配。", "slug": "advanced-metering-infrastructure-ami", "source_urls": ["https://enerzolve.com/smart-grid/hes"]}], "name": "Enerzolve Head End System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:38.445707+08:00", "kind": "documentation", "sha256": "b09fa5ab6836dbefc33234e6e85d0e2ae41ebfb5b14c47b41a931a02d5e4435c", "snapshot_path": "sources/b09fa5ab6836dbefc33234e6e85d0e2ae41ebfb5b14c47b41a931a02d5e4435c.txt", "url": "https://enerzolve.com/smart-grid/hes"}], "summary": "Enerzolve HES 与智能电表通信，采集读数、管理设备、推送固件并监控资产群健康。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fraunhofer-ad-net-heat','Fraunhofer AD Net Heat','{"homepage": "https://www.itwm.fraunhofer.de/", "id": "commercial:fraunhofer-ad-net-heat", "leaf_matches": [{"reason": "Fraunhofer官方产品资料说明软件运行区域热网数字孪生，可观察网络温度/流量、进行动态仿真和运行优化；机构研发与咨询属性不改变软件功能。", "slug": "district-energy-management", "source_urls": ["https://www.itwm.fraunhofer.de/en/departments/processes-materials/products-services/software-ad-net-heat-district-heating.html"]}], "name": "Fraunhofer AD Net Heat", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:40.717588+08:00", "kind": "documentation", "sha256": "579011a0c48f87ae57728704e3b3ae73fb0c1969b9106a128e52910a9779834b", "snapshot_path": "sources/579011a0c48f87ae57728704e3b3ae73fb0c1969b9106a128e52910a9779834b.txt", "url": "https://www.itwm.fraunhofer.de/en/departments/processes-materials/products-services/software-ad-net-heat-district-heating.html"}], "summary": "AD Net Heat 用动态仿真和数字孪生支持区域供热网络监控与运行优化。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
