INSERT INTO "application" VALUES('github:290688105','MOSIP','{"deployment": ["官方文档说明服务以微服务部署在Kubernetes，可由政府/实施方自有数据中心或云环境托管；本次未部署"], "features": ["创建政府颁发的居民身份并管理注册/身份生命周期", "IDA/eSignet支持外部依赖服务对居民进行认证和e-KYC", "通过伙伴管理门户接入依赖方并管理策略/客户端"], "github_repository_id": 290688105, "homepage": "https://mosip.io", "id": "github:290688105", "leaf_matches": [{"reason": "MOSIP官方ID Authentication文档证明外部政府/私营依赖方可重复调用居民认证，eSignet提供OIDC接入，Partner Management处理服务方接入与策略；基础登记之外明确具备跨服务验证能力。", "slug": "government-digital-identity", "source_urls": ["https://docs.mosip.io/1.2.0/id-lifecycle-management/identity-verification/id-authentication", "https://docs.mosip.io/1.2.0/interoperability/integrations/e-signet", "https://docs.mosip.io/1.2.0/interoperability/integrations/e-signet/partner-management", "https://docs.mosip.io/1.2.0/setup/deploymentnew/v3-installation/1.2.0.2/overview-and-architecture"]}], "license": "MPL-2.0", "license_evidence_url": "https://api.github.com/repos/mosip/mosip/license", "name": "MOSIP", "repository_url": "https://github.com/mosip/mosip", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T18:55:41.855808+08:00", "kind": "repository_metadata", "sha256": "073641e54d5756eead7f65787de118d823c65a5be98f80cd9a3271d0717dc9d9", "snapshot_path": "sources/073641e54d5756eead7f65787de118d823c65a5be98f80cd9a3271d0717dc9d9.txt", "url": "https://api.github.com/repos/mosip/mosip"}, {"fetched_at": "2026-10-23T18:55:43.674886+08:00", "kind": "license", "sha256": "bfda7ef256c65b2522f2bb9d4f4d21c691e3379737fd4cbfc08244e75963d137", "snapshot_path": "sources/bfda7ef256c65b2522f2bb9d4f4d21c691e3379737fd4cbfc08244e75963d137.txt", "url": "https://api.github.com/repos/mosip/mosip/license"}, {"fetched_at": "2026-10-23T18:55:44.755539+08:00", "kind": "readme", "sha256": "2a17a343f3456c0972eff18ba95956b202a0b746e3b19fcaf12b015b5f7ea489", "snapshot_path": "sources/2a17a343f3456c0972eff18ba95956b202a0b746e3b19fcaf12b015b5f7ea489.txt", "url": "https://raw.githubusercontent.com/mosip/mosip/master/README.md"}, {"fetched_at": "2026-10-23T18:55:47.373056+08:00", "kind": "documentation", "sha256": "1af4a4d8af4c9c52b0aa8facc61b7b74472ff834b1a8cf55c3126df38bf02da2", "snapshot_path": "sources/1af4a4d8af4c9c52b0aa8facc61b7b74472ff834b1a8cf55c3126df38bf02da2.txt", "url": "https://docs.mosip.io/1.2.0/id-lifecycle-management/identity-verification/id-authentication"}, {"fetched_at": "2026-10-23T18:55:50.258180+08:00", "kind": "documentation", "sha256": "31248409e7e03081029bfa69c48e5c5e5a50deb6663c0f727dc05537e2f00f8e", "snapshot_path": "sources/31248409e7e03081029bfa69c48e5c5e5a50deb6663c0f727dc05537e2f00f8e.txt", "url": "https://docs.mosip.io/1.2.0/interoperability/integrations/e-signet"}, {"fetched_at": "2026-10-23T18:55:53.165327+08:00", "kind": "documentation", "sha256": "036eacc4178484daf38624f5e7125643f1b543b64cd46071746ae6226ea797b7", "snapshot_path": "sources/036eacc4178484daf38624f5e7125643f1b543b64cd46071746ae6226ea797b7.txt", "url": "https://docs.mosip.io/1.2.0/interoperability/integrations/e-signet/partner-management"}, {"fetched_at": "2026-10-23T18:55:55.896125+08:00", "kind": "documentation", "sha256": "822935e7a441d786d35133815aa25ded723e2917198be6a4ad09dea965fe425f", "snapshot_path": "sources/822935e7a441d786d35133815aa25ded723e2917198be6a4ad09dea965fe425f.txt", "url": "https://docs.mosip.io/1.2.0/setup/deploymentnew/v3-installation/1.2.0.2/overview-and-architecture"}], "summary": "为政府和国际组织构建基础数字身份系统的模块化开源平台。", "technology_stack": ["微服务架构；官方部署说明为Kubernetes集群", "API优先身份认证服务与eSignet OIDC relying-party 集成"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:multiop-animal-control','MultiOp Animal Control Software','{"homepage": "https://multiop.com/animal-control-software.html", "id": "commercial:multiop-animal-control", "leaf_matches": [{"reason": "MultiOp官方产品页把投诉、现场响应、人员派遣、案件记录、罚单/引用和执法跟进明确放在面向动物管制机构的系统内，直接匹配本叶核心工作闭环。", "slug": "animal-control-management", "source_urls": ["https://multiop.com/animal-control-software.html"]}], "name": "MultiOp Animal Control Software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:03:59.836037+08:00", "kind": "homepage", "sha256": "3c6dc74f2ad02856798266ec570b63fc244ac125c3f3ca9c7e2f00d0e3ef8dff", "snapshot_path": "sources/3c6dc74f2ad02856798266ec570b63fc244ac125c3f3ca9c7e2f00d0e3ef8dff.txt", "url": "https://multiop.com/animal-control-software.html"}], "summary": "供政府动物管制部门管理投诉、派遣现场人员、案件处置及执法跟进的在线业务软件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:philjobnet','PhilJobNet','{"homepage": "https://philjobnet.gov.ph/default.aspx", "id": "commercial:philjobnet", "leaf_matches": [{"reason": "官方页面说明PhilJobNet是劳工部就业服务设施：求职者注册、查找职位和接受邀请，雇主发布职位、匹配申请人并管理申请/提交安置报告，公共就业机构负责雇主认证；符合政府作为劳动力市场中介的定义。", "slug": "public-employment-service-platform", "source_urls": ["https://philjobnet.gov.ph/default.aspx"]}], "name": "PhilJobNet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:04:03.997544+08:00", "kind": "homepage", "sha256": "9e2b744f21199aaa5ff97d785d8138c53248b83dd8193ec6c3942ce0c73eb96d", "snapshot_path": "sources/9e2b744f21199aaa5ff97d785d8138c53248b83dd8193ec6c3942ce0c73eb96d.txt", "url": "https://philjobnet.gov.ph/default.aspx"}], "summary": "菲律宾劳工与就业部运营的求职者与雇主岗位匹配服务，包含岗位发布、求职注册、匹配邀请及招聘报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:city-as-a-platform','City as a Platform','{"homepage": "https://www.city-platform.com/", "id": "commercial:city-as-a-platform", "leaf_matches": [{"reason": "官方主页将其标为Web BusinessApplication，描述跨部门与跨域数据、实时传感器、现场运营和统一实时视图，并称50多个市政组织日常用于关键运营，符合城市级共享运营图景。", "slug": "smart-city-operations-platform", "source_urls": ["https://www.city-platform.com/"]}], "name": "City as a Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:04:01.616313+08:00", "kind": "homepage", "sha256": "8048bae16261de3d34228f0b5b20940b5c4e4ae19ba0369adae84a75ac563eb4", "snapshot_path": "sources/8048bae16261de3d34228f0b5b20940b5c4e4ae19ba0369adae84a75ac563eb4.txt", "url": "https://www.city-platform.com/"}], "summary": "面向市政运营者的跨部门城市运营平台，连接实时数据、传感器、现场工作流与统一城市运行视图。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cast-it-systems','Cast It Talent / Cast It Pro','{"homepage": "https://app.castittalent.com/", "id": "commercial:cast-it-systems", "leaf_matches": [{"reason": "CITFunctions 正文说明 Cast It Pro 在项目内创建角色、添加演员、上传和查看试镜/reel，维护名单、排期、报名、备注与可用时间，并通过访问级别、评论/反馈及 selects/approvals 推进选角；覆盖按角色候选、试镜材料、多人评估与选角结果留存。", "slug": "audition-management", "source_urls": ["https://app.castittalent.com/", "https://app.castittalent.com/CITFunctions.aspx"]}, {"reason": "官方资料明确制作/选角团队发布角色与管理名单，人才维护档案并按具体角色提交，平台在线保存/检索试镜视频、报名、可用时间与协作访问；报名交换和双方档案均被覆盖。", "slug": "casting-platform", "source_urls": ["https://app.castittalent.com/", "https://app.castittalent.com/CITFunctions.aspx"]}], "name": "Cast It Talent / Cast It Pro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:10:18.001359+08:00", "kind": "homepage", "sha256": "2134a55caa774358c1ca69983144a89bbf4906e87b701c66e53ef897755fedcc", "snapshot_path": "sources/2134a55caa774358c1ca69983144a89bbf4906e87b701c66e53ef897755fedcc.txt", "url": "https://app.castittalent.com/"}, {"fetched_at": "2026-10-23T19:03:58.424206+08:00", "kind": "documentation", "sha256": "e0d8aaa100b4823d6bac3249a4ca2a1dbd8193b70ba9f75435273619ce741468", "snapshot_path": "sources/e0d8aaa100b4823d6bac3249a4ca2a1dbd8193b70ba9f75435273619ce741468.txt", "url": "https://app.castittalent.com/CITFunctions.aspx"}], "summary": "为选角办公室、制作方与演艺人才提供角色发布、人才档案、报名提交及在线试镜协作的选角套件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:chi-cashless','CHI Event Operating System','{"homepage": "https://chi.app/", "id": "commercial:chi-cashless", "leaf_matches": [{"reason": "CHI官方页展示组织者Backstage工作台可从头创建和管理活动、配置现金less支付、管理工作人员并查看交易和访客CRM，同时提供访客QR/NFC支付账户；覆盖场馆支付运营工作流。", "slug": "cashless-venue-platform", "source_urls": ["https://chi.app/"]}], "name": "CHI Event Operating System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:04:59.706457+08:00", "kind": "homepage", "sha256": "b272127b213068ff9449e4ede469dffc0422e974c676b68b21af795341ef9aec", "snapshot_path": "sources/b272127b213068ff9449e4ede469dffc0422e974c676b68b21af795341ef9aec.txt", "url": "https://chi.app/"}], "summary": "为场馆和活动运营方提供活动配置、人员管理、现金less支付及实时交易/CRM工作台，并关联访客电子钱包。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:humanz-creator-marketplace','Humanz Creator Platform','{"homepage": "https://www.humanz.com/platform/", "id": "commercial:humanz-creator-marketplace", "leaf_matches": [{"reason": "官方平台页不仅提供公开创作者发现，还描述品牌CRM与campaign工作区、按品牌保留合作历史、brief/提交/审阅/批准、合同和平台付款，并有创作者侧应用；因此存在可持续客户操作流程，不只是公开撮合目录。", "slug": "brand-creator-marketplace", "source_urls": ["https://www.humanz.com/platform/"]}], "name": "Humanz Creator Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:03.483500+08:00", "kind": "homepage", "sha256": "7cdefd9162548e1992a4ab0bc00b83a77e83a09908eccf605589b26e6ec61791", "snapshot_path": "sources/7cdefd9162548e1992a4ab0bc00b83a77e83a09908eccf605589b26e6ec61791.txt", "url": "https://www.humanz.com/platform/"}], "summary": "品牌与创作者在同一平台完成创作者发现、campaign建档、内容提交/审阅、合同、付款及效果跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ko-fi','Ko-fi','{"homepage": "https://ko-fi.com/features", "id": "commercial:ko-fi", "leaf_matches": [{"reason": "官方页面明确支持无前置收费的creator页面与一次性tips，并可扩展会员/商品等其他收入方式；tips是清晰的独立产品工作流。Ko-fi把款项直付至创作者关联的PayPal/Stripe，不声称自己托管资金。", "slug": "creator-tip-platform", "source_urls": ["https://ko-fi.com/features"]}, {"reason": "Official Ko-fi homepage and features page state that creators can launch memberships with tiers and exclusive content, while fans support the same creator through recurring payments made directly to that creator.", "slug": "fan-membership-platform", "source_urls": ["https://ko-fi.com/features", "https://ko-fi.com"]}], "name": "Ko-fi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:41:49.092876+08:00", "kind": "homepage", "sha256": "ae2653910fe0afbb018b9379a27ac5def0fd8eeaadd91715fcd8e9034b9b38d2", "snapshot_path": "sources/ae2653910fe0afbb018b9379a27ac5def0fd8eeaadd91715fcd8e9034b9b38d2.txt", "url": "https://ko-fi.com"}, {"fetched_at": "2026-10-23T19:05:00.018169+08:00", "kind": "homepage", "sha256": "943ebbaa887fa782372973c47ff1f2a3f26c756da1c709869929ee07af06aca9", "snapshot_path": "sources/943ebbaa887fa782372973c47ff1f2a3f26c756da1c709869929ee07af06aca9.txt", "url": "https://ko-fi.com/features"}], "summary": "创作者建立个人支持页面，通过一次性自愿tips接收粉丝支持，并管理创作者侧支持和收益。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ugcollab','UGCollab','{"homepage": "https://ugcollab.ai/", "id": "commercial:ugcollab", "leaf_matches": [{"reason": "官方产品资料说明品牌自助申请与campaign流程，brief成为记录基线，创作者提交版本保留历史、审批带时间戳，品牌支付后由平台结算给创作者；匹配所需的brief→交付→审核→付款链条明确。", "slug": "ugc-creator-marketplace", "source_urls": ["https://ugcollab.ai/", "https://ugcollab.ai/about"]}], "name": "UGCollab", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:02.553213+08:00", "kind": "homepage", "sha256": "92ef2c410aeb28b43b0801a5c7f9b2eabd92c28fef80e0a45566c6f10f75ff28", "snapshot_path": "sources/92ef2c410aeb28b43b0801a5c7f9b2eabd92c28fef80e0a45566c6f10f75ff28.txt", "url": "https://ugcollab.ai/"}, {"fetched_at": "2026-10-23T19:05:01.826920+08:00", "kind": "documentation", "sha256": "8ed43ac5d6d54b1fc4f3f856a0a441987ab2110f7cda089a31e96c77e7f04d7e", "snapshot_path": "sources/8ed43ac5d6d54b1fc4f3f856a0a441987ab2110f7cda089a31e96c77e7f04d7e.txt", "url": "https://ugcollab.ai/about"}], "summary": "品牌通过自助UGC campaign发布brief、接收并审查版本化内容、确认批准并向创作者付款的在线工作区。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sportsrecruits','SportsRecruits','{"homepage": "https://sportsrecruits.com/", "id": "commercial:sportsrecruits", "leaf_matches": [{"reason": "官方运动员工作台保存可搜索档案、目标院校、影片、教练查看/消息活动与下一步任务；教练侧说明可按运动、毕业年份、位置、学业和地理条件搜索与关注运动员，符合招募导向的双边网络。", "slug": "athlete-recruiting-marketplace", "source_urls": ["https://help.sportsrecruits.com/hc/en-us/articles/43008400714381-Athlete-Dashboard", "https://help.sportsrecruits.com/hc/en-us/articles/40154044530317-The-College-Coach-Experience-on-SportsRecruits"]}], "name": "SportsRecruits", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:03.498884+08:00", "kind": "documentation", "sha256": "1501ce3b051104d2a720b168c716cb089d4891bf89f723958d88e6c6f4409473", "snapshot_path": "sources/1501ce3b051104d2a720b168c716cb089d4891bf89f723958d88e6c6f4409473.txt", "url": "https://help.sportsrecruits.com/hc/en-us/articles/43008400714381-Athlete-Dashboard"}, {"fetched_at": "2026-10-23T19:08:57.811460+08:00", "kind": "documentation", "sha256": "20e1060d576392e48d9b2b194d038db367857cbebae1f5ecd8151a3aa4ef1b7a", "snapshot_path": "sources/20e1060d576392e48d9b2b194d038db367857cbebae1f5ecd8151a3aa4ef1b7a.txt", "url": "https://help.sportsrecruits.com/hc/en-us/articles/40154044530317-The-College-Coach-Experience-on-SportsRecruits"}], "summary": "面向学生运动员、家庭、俱乐部及高校教练的在线招募网络，提供运动员资料、目标院校、视频与教练互动/招募记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:alltrails','AllTrails','{"homepage": "https://alltrails.com/", "id": "commercial:alltrails", "leaf_matches": [{"reason": "官网首页正文显示可按城市、公园或步道名搜索步道指南，提供地图与离线下载、实时跟踪和转弯提示，覆盖步道对象、地形地图与实地导航。", "slug": "hiking-trail-application", "source_urls": ["https://www.alltrails.com/"]}, {"reason": "官方入门帮助中心说明用户通过Explore发现路线；帮助中心链接到国家/地区/城市/公园/步道目录，以及个人地图创建/管理；官方订阅页另说明离线地图、路线预览、分享活动等持续在线功能。属于个人使用的地图目录/发现应用，非仅公共场所列表。", "slug": "outdoor-recreation-discovery", "source_urls": ["https://support.alltrails.com/hc/en-us/articles/37200401098516-Getting-started-on-AllTrails"]}], "name": "AllTrails", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:36.602138+08:00", "kind": "documentation", "sha256": "6847d8435de4bfa7f5f48b989e18ea6a27050fd5afecced6fcc97b88f4d51046", "snapshot_path": "sources/6847d8435de4bfa7f5f48b989e18ea6a27050fd5afecced6fcc97b88f4d51046.txt", "url": "https://support.alltrails.com/hc/en-us/articles/37200401098516-Getting-started-on-AllTrails"}, {"fetched_at": "2026-10-27T02:12:06.949364+08:00", "kind": "homepage", "sha256": "c9d6022ef88e3aeecc90ee0ab6094864377e3bdc42584b2df9d1d4aa6e23c38d", "snapshot_path": "sources/c9d6022ef88e3aeecc90ee0ab6094864377e3bdc42584b2df9d1d4aa6e23c38d.txt", "url": "https://www.alltrails.com/"}], "summary": "面向徒步者的户外地点与路线发现服务，提供地图目录、路线浏览、个人地图及导航/活动功能。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:thredbo-resort-app','Thredbo Resort App','{"homepage": "https://www.thredbo.com.au/thredbo-mobile-app/", "id": "commercial:thredbo-resort-app", "leaf_matches": [{"reason": "度假区官方App页面将实时山地/缆车/雪道状态、游客收藏、个人按天垂直滑行记录、在线商店通行证/余额登录放在同一旅客工作流程中，直接满足雪场空间、运行状态和客人当天记录三部分。", "slug": "ski-resort-recreation-application", "source_urls": ["https://www.thredbo.com.au/thredbo-mobile-app/"]}], "name": "Thredbo Resort App", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:02.631515+08:00", "kind": "homepage", "sha256": "e8ff329b62cfaf149a3a90bda26fea496c1c527726d6df47d08786420ec37986", "snapshot_path": "sources/e8ff329b62cfaf149a3a90bda26fea496c1c527726d6df47d08786420ec37986.txt", "url": "https://www.thredbo.com.au/thredbo-mobile-app/"}], "summary": "山地访客使用的度假区伴游应用，结合实时雪场运营、地图、个人垂直滑行记录、通行证及同行游玩信息。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vtobeauty','VTOBeauty','{"homepage": "https://vtobeauty.com/en/", "id": "commercial:vtobeauty", "leaf_matches": [{"reason": "官方页面说明商家端管理面板与消费者端嵌入式试妆组件，读取商品SKU/变体并提供美妆品类实时虚拟试用；该软件实现了零售端部署和消费者从商品页试妆/比较的完整子流程，按叶子工作流收录。", "slug": "virtual-beauty-try-on-application", "source_urls": ["https://vtobeauty.com/en/"]}], "name": "VTOBeauty", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:05:38.340292+08:00", "kind": "homepage", "sha256": "8b4c1809a0d374551c867d4b739594f1d89984ccc6fb75bbf361910ac645f52e", "snapshot_path": "sources/8b4c1809a0d374551c867d4b739594f1d89984ccc6fb75bbf361910ac645f52e.txt", "url": "https://vtobeauty.com/en/"}], "summary": "为零售商提供美妆目录配置与网页试妆组件，让消费者在产品页使用实时虚拟美妆预览。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:408868487','Bigcapital','{"deployment": ["Docker / Docker Compose 自托管", "Bigcapital Cloud 托管选项"], "features": ["按科目表记录复式借贷分录（README 称可通过 API 在 double-entry system 中组织交易）", "提供资产负债表等财务报表（README 截图展示 Accounts Chart、Balance Sheet，并称生成 financial statements and reports）", "发票与库存等小企业会计外围流程（截图 New Invoice；README 自述 accounting and inventory software）"], "github_repository_id": 408868487, "homepage": "https://bigcapital.app", "id": "github:408868487", "leaf_matches": [{"reason": "README 明确称其为 “accounting and inventory software”，截图标题为 Accounts Chart、Balance Sheet 与 New Invoice，并说明可通过 API 在 “double-entry system” 中组织交易，且会生成 “financial statements and reports”。据此可证科目表、复式过账与由账簿衍生的资产负债表三个结构；利润表、账单与支付流程在该 README 中没有对应表述，故未写入 features。", "slug": "accounting-software", "source_urls": ["https://api.github.com/repos/bigcapitalhq/bigcapital", "https://api.github.com/repos/bigcapitalhq/bigcapital/license", "https://raw.githubusercontent.com/bigcapitalhq/bigcapital/HEAD/README.md"]}, {"reason": "官方 API 文档给出三条核心证据：账户创建接口（name/code/accountType/parentAccountId/active）与账户类型接口（rootType 示例 asset、parentType 示例 current-asset、normal 示例 debit、balanceSheet/incomeSheet 归属）证明账户结构与分类；手工日记账以日期+借贷行(accountId/credit/debit)+编号/附件/发布状态登记交易，证明带日期的交易记录；总账报表按账户输出 opening_balance、逐笔 running_balance、closing_balance，且可按 cash/accrual 会计基础取数，证明持续累积的账簿与历史。官方 Docker 文档给出 docker-compose 自托管完整 Web 应用的部署路径，AGPL-3.0，仓库 id 408868487 与 full_name bigcapitalhq/bigcapital 已核对。未采用 README 中仅以截图呈现的 Balance Sheet/New Invoice 作为核心证据。", "slug": "bookkeeping-application", "source_urls": ["https://api.github.com/repos/bigcapitalhq/bigcapital", "https://api.github.com/repos/bigcapitalhq/bigcapital/license", "https://raw.githubusercontent.com/bigcapitalhq/bigcapital/HEAD/README.md", "https://docs.bigcapital.app/", "https://docs.bigcapital.app/deployment/docker.md", "https://docs.bigcapital.app/api-reference/accounts/create-an-account.md", "https://docs.bigcapital.app/api-reference/accounts/retrieves-the-account-types.md", "https://docs.bigcapital.app/api-reference/manual-journals/create-a-new-manual-journal.md", "https://docs.bigcapital.app/api-reference/reports/get-general-ledger-report.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/bigcapitalhq/bigcapital/license", "name": "Bigcapital", "repository_url": "https://github.com/bigcapitalhq/bigcapital", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:57:14.495794+08:00", "kind": "repository_metadata", "sha256": "663b06914b3fd369c54a4fd8274228a6e48235870ad3824f1c09b92216474f10", "snapshot_path": "sources/663b06914b3fd369c54a4fd8274228a6e48235870ad3824f1c09b92216474f10.txt", "url": "https://api.github.com/repos/bigcapitalhq/bigcapital"}, {"fetched_at": "2026-10-24T20:22:20.080681+08:00", "kind": "repository_metadata", "sha256": "7102c50019750b7d50a21828f2b515be26fdb748351c5bd00b91f501cc0355d7", "snapshot_path": "sources/7102c50019750b7d50a21828f2b515be26fdb748351c5bd00b91f501cc0355d7.txt", "url": "https://api.github.com/repos/bigcapitalhq/bigcapital"}, {"fetched_at": "2026-10-24T20:22:22.046766+08:00", "kind": "license", "sha256": "0ec886dbc4e5a9f57fd443e7ccad8cea01f8d617c8f20fa7702fbd70635d0dc2", "snapshot_path": "sources/0ec886dbc4e5a9f57fd443e7ccad8cea01f8d617c8f20fa7702fbd70635d0dc2.txt", "url": "https://api.github.com/repos/bigcapitalhq/bigcapital/license"}, {"fetched_at": "2026-10-28T15:54:49.033551+08:00", "kind": "documentation", "sha256": "6d62520dbfba0ad01b81c24fc4520ed75f3e060451fe9533966f280110a22c5a", "snapshot_path": "sources/6d62520dbfba0ad01b81c24fc4520ed75f3e060451fe9533966f280110a22c5a.txt", "url": "https://docs.bigcapital.app/"}, {"fetched_at": "2026-10-28T15:56:34.912593+08:00", "kind": "documentation", "sha256": "f114606fc84c76b70a4ad28fd2f406f8ec805fdc0d4bf9e230466332bd92ab0a", "snapshot_path": "sources/f114606fc84c76b70a4ad28fd2f406f8ec805fdc0d4bf9e230466332bd92ab0a.txt", "url": "https://docs.bigcapital.app/api-reference/accounts/create-an-account.md"}, {"fetched_at": "2026-10-28T15:56:34.745879+08:00", "kind": "documentation", "sha256": "8bdb101a60c415857329e40e929504de513be6072b621beb3516c4082cc1ae8a", "snapshot_path": "sources/8bdb101a60c415857329e40e929504de513be6072b621beb3516c4082cc1ae8a.txt", "url": "https://docs.bigcapital.app/api-reference/accounts/retrieves-the-account-types.md"}, {"fetched_at": "2026-10-28T15:55:45.720413+08:00", "kind": "documentation", "sha256": "1e35d8c7c5378a3181d6d5d3031e89aae0641a14ba0654e83ba33b2659355237", "snapshot_path": "sources/1e35d8c7c5378a3181d6d5d3031e89aae0641a14ba0654e83ba33b2659355237.txt", "url": "https://docs.bigcapital.app/api-reference/manual-journals/create-a-new-manual-journal.md"}, {"fetched_at": "2026-10-28T15:55:46.198270+08:00", "kind": "documentation", "sha256": "11ef21409a71a0c4df3147e802fb44d3dbdb0d576d9208a2afed41fae541b4a6", "snapshot_path": "sources/11ef21409a71a0c4df3147e802fb44d3dbdb0d576d9208a2afed41fae541b4a6.txt", "url": "https://docs.bigcapital.app/api-reference/reports/get-general-ledger-report.md"}, {"fetched_at": "2026-10-28T16:00:22.690704+08:00", "kind": "documentation", "sha256": "7b5179ee436cc2180e1f2b4cd2da59c1200a099e8ff30e14cd26b903f7eb202a", "snapshot_path": "sources/7b5179ee436cc2180e1f2b4cd2da59c1200a099e8ff30e14cd26b903f7eb202a.txt", "url": "https://docs.bigcapital.app/deployment/docker.md"}, {"fetched_at": "2026-10-24T20:22:23.251341+08:00", "kind": "readme", "sha256": "4c76d10d1e627a5b6bbfcc9ea3952221ee709eb2b946961205caef347a1b523b", "snapshot_path": "sources/4c76d10d1e627a5b6bbfcc9ea3952221ee709eb2b946961205caef347a1b523b.txt", "url": "https://raw.githubusercontent.com/bigcapitalhq/bigcapital/HEAD/README.md"}], "summary": "开源复式记账与库存软件，面向中小企业提供科目表、分录、发票与财务报表，支持 Docker 自托管。", "technology_stack": ["TypeScript", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:486815039','Actual Budget','{"deployment": ["Docker 自托管", "Windows/macOS/Linux 桌面应用", "可选托管部署"], "features": ["按信封预算法为每月类别分配金额并显示剩余/超支", "导入或记录交易并与预算比对", "数据本地优先，可选自托管同步"], "github_repository_id": 486815039, "homepage": "https://actualbudget.org", "id": "github:486815039", "leaf_matches": [{"reason": "官方文档说明按信封/类别为每月分配金额、以 To Budget 归零、并处理超支与类别间调拨；README 说明设备间数据同步与本地优先部署。对应计划—分配—实际—剩余比对四个定义性属性。", "slug": "budgeting-application", "source_urls": ["https://api.github.com/repos/actualbudget/actual", "https://api.github.com/repos/actualbudget/actual/license", "https://raw.githubusercontent.com/actualbudget/actual/HEAD/README.md", "https://actualbudget.org/docs/getting-started/envelope-budgeting"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/actualbudget/actual/license", "name": "Actual Budget", "repository_url": "https://github.com/actualbudget/actual", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:41.293599+08:00", "kind": "repository_metadata", "sha256": "c4c8d65067d0fc8415d230d0c2322fe2f45d7f925ec92235492f77284f580ccd", "snapshot_path": "sources/c4c8d65067d0fc8415d230d0c2322fe2f45d7f925ec92235492f77284f580ccd.txt", "url": "https://api.github.com/repos/actualbudget/actual"}, {"fetched_at": "2026-10-24T20:22:42.765012+08:00", "kind": "license", "sha256": "c93241cae6a431f626682678fb5cbf452b5e0f76e992a23062869212166b818f", "snapshot_path": "sources/c93241cae6a431f626682678fb5cbf452b5e0f76e992a23062869212166b818f.txt", "url": "https://api.github.com/repos/actualbudget/actual/license"}, {"fetched_at": "2026-10-24T20:22:43.998003+08:00", "kind": "readme", "sha256": "fd174335284daa65ef6345dc139649fb3f4926fd57f26b0cbf98f5bfaab4485d", "snapshot_path": "sources/fd174335284daa65ef6345dc139649fb3f4926fd57f26b0cbf98f5bfaab4485d.txt", "url": "https://raw.githubusercontent.com/actualbudget/actual/HEAD/README.md"}, {"fetched_at": "2026-10-24T20:22:48.037134+08:00", "kind": "documentation", "sha256": "480e9e486a18e8b4b11573852928f966de2f64b465771ee52db86da9f305dfee", "snapshot_path": "sources/480e9e486a18e8b4b11573852928f966de2f64b465771ee52db86da9f305dfee.txt", "url": "https://actualbudget.org/docs/getting-started/envelope-budgeting"}], "summary": "本地优先的开源预算应用，按信封/类别为每月分配金额，并用实际交易显示剩余与超支。", "technology_stack": ["TypeScript", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1096694850','Billzzz','{"deployment": ["Docker Compose 或 docker run 自托管，SQLite 数据卷持久化"], "features": ["登记多笔债务的余额、利率与最低还款额", "按雪球、雪崩或自定义顺序计算还款计划与预计还清日期", "记录还款并联动账单，提供策略对比与进度时间线"], "github_repository_id": 1096694850, "homepage": "https://github.com/c-rw/billzzz", "id": "github:1096694850", "leaf_matches": [{"reason": "README 的 Debt Calculator 章节列出多笔债务的余额、利率与最低还款，雪球/雪崩/自定义顺序，策略变更后实时重算的月度时间线，以及债务与还款记录；对应负债记录、还款计划与跟踪循环三个核心。", "slug": "debt-management-application", "source_urls": ["https://api.github.com/repos/c-rw/billzzz", "https://api.github.com/repos/c-rw/billzzz/license", "https://raw.githubusercontent.com/c-rw/billzzz/HEAD/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/c-rw/billzzz/license", "name": "Billzzz", "repository_url": "https://github.com/c-rw/billzzz", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:49.581581+08:00", "kind": "repository_metadata", "sha256": "2eef7d8642462f7d20b5361f2cb5c12de5e0b1829a8724ce7d328583ce551549", "snapshot_path": "sources/2eef7d8642462f7d20b5361f2cb5c12de5e0b1829a8724ce7d328583ce551549.txt", "url": "https://api.github.com/repos/c-rw/billzzz"}, {"fetched_at": "2026-10-24T20:22:51.072804+08:00", "kind": "license", "sha256": "03225be18c33b89495f2c1bdd0f109b73bf1519d579b81f82ea0134469d3d508", "snapshot_path": "sources/03225be18c33b89495f2c1bdd0f109b73bf1519d579b81f82ea0134469d3d508.txt", "url": "https://api.github.com/repos/c-rw/billzzz/license"}, {"fetched_at": "2026-10-24T20:22:52.263394+08:00", "kind": "readme", "sha256": "2c436717653a095c662abe181d4a0f75eff47a18fcb19684400a1063ecbd8ae2", "snapshot_path": "sources/2c436717653a095c662abe181d4a0f75eff47a18fcb19684400a1063ecbd8ae2.txt", "url": "https://raw.githubusercontent.com/c-rw/billzzz/HEAD/README.md"}], "summary": "自托管个人财务应用，含债务清单、雪球/雪崩/自定义还款顺序、还款记录与还清时间线。", "technology_stack": ["SvelteKit", "SQLite", "TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:887597422','ExpenseOwl','{"deployment": ["Docker 容器自托管", "单二进制运行"], "features": ["快速记录金额、日期与自定义类别的支出/收入", "按月类别饼图与现金流汇总", "自定义类别、标签与 CSV 导入导出"], "github_repository_id": 887597422, "homepage": "https://github.com/Tanq16/ExpenseOwl", "id": "github:887597422", "leaf_matches": [{"reason": "README 说明只需日期、金额与类别即可记录支出，提供自定义类别、按月类别饼图与现金流汇总，并明确“不是预算应用”；正好落在支出记录—类别—期间汇总三个核心，未主张账户或银行同步。", "slug": "expense-tracking-application", "source_urls": ["https://api.github.com/repos/Tanq16/ExpenseOwl", "https://api.github.com/repos/Tanq16/ExpenseOwl/license", "https://raw.githubusercontent.com/Tanq16/ExpenseOwl/HEAD/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Tanq16/ExpenseOwl/license", "name": "ExpenseOwl", "repository_url": "https://github.com/Tanq16/ExpenseOwl", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:53.899135+08:00", "kind": "repository_metadata", "sha256": "3dd40fd95b848840d30eaf71aba92da74969b4783003ef2a2a3968c0d3df6228", "snapshot_path": "sources/3dd40fd95b848840d30eaf71aba92da74969b4783003ef2a2a3968c0d3df6228.txt", "url": "https://api.github.com/repos/Tanq16/ExpenseOwl"}, {"fetched_at": "2026-10-24T20:22:55.370953+08:00", "kind": "license", "sha256": "05cb0bdd936d995034e34841516a061cd1d3d9b7b773a95e4e123ac1d02e2690", "snapshot_path": "sources/05cb0bdd936d995034e34841516a061cd1d3d9b7b773a95e4e123ac1d02e2690.txt", "url": "https://api.github.com/repos/Tanq16/ExpenseOwl/license"}, {"fetched_at": "2026-10-24T20:22:56.791566+08:00", "kind": "readme", "sha256": "82be809c754bdaccc52868ed282e94d4d0a27d525d80126940cfe3099b602701", "snapshot_path": "sources/82be809c754bdaccc52868ed282e94d4d0a27d525d80126940cfe3099b602701.txt", "url": "https://raw.githubusercontent.com/Tanq16/ExpenseOwl/HEAD/README.md"}], "summary": "极简自托管支出跟踪应用，按自定义类别记录支出并按月汇总为类别饼图与现金流。", "technology_stack": ["Go", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:floqast-close-management','FloQast Close Management','{"homepage": "https://www.floqast.com/", "id": "commercial:floqast-close-management", "leaf_matches": [{"reason": "官方产品导航把 “Close Checklist” 描述为 “Task management for every close”，并列出 Account Reconciliations 的 “Rec prep, tie-out, and sign-offs”。据此可证周期性结账的任务容器与签署环节；页面未明示责任人分配（assignee），故不把分配写成已验证。", "slug": "financial-close-management", "source_urls": ["https://www.floqast.com/"]}], "name": "FloQast Close Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:34.694057+08:00", "kind": "homepage", "sha256": "4a0ec42eb45b356599f7c5bdaa2eb641c0e0bd3abfffd5526c835db4dd9e063c", "snapshot_path": "sources/4a0ec42eb45b356599f7c5bdaa2eb641c0e0bd3abfffd5526c835db4dd9e063c.txt", "url": "https://www.floqast.com/"}], "summary": "面向会计团队的结账流程平台，提供结账清单、账户对账、签署与关账进度管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:jirav','Jirav','{"homepage": "https://www.jirav.com/", "id": "commercial:jirav", "leaf_matches": [{"reason": "官方首页称其为 “driver-based software forecasts the P&L, balance sheet, and cash flow”，可 “Construct budgets, forecasts, and multiple scenario plans” 并 “Connect your accounting, workforce, and operational data”；规划产品页称以 “dynamic driver-based financial model” 做预测。据此可证显式驱动假设、由输入驱动三表预测的计算逻辑与期间预测三个属性；模型内输入/结果分离的界面细节未核验。", "slug": "financial-modeling-application", "source_urls": ["https://www.jirav.com/", "https://www.jirav.com/accounting-planning-budgeting-forecasting"]}], "name": "Jirav", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:37.200389+08:00", "kind": "homepage", "sha256": "472a23a1e7dadc0e0ba8ac9fbb349a57a91b12ec6cf3abe3cf7e7ea3f4823bd5", "snapshot_path": "sources/472a23a1e7dadc0e0ba8ac9fbb349a57a91b12ec6cf3abe3cf7e7ea3f4823bd5.txt", "url": "https://www.jirav.com/"}, {"fetched_at": "2026-10-24T21:04:51.826329+08:00", "kind": "documentation", "sha256": "cf8744e5fad5cbeb40bd383d492a6ab40af91f34e9685c64919d7d67c1cffd0e", "snapshot_path": "sources/cf8744e5fad5cbeb40bd383d492a6ab40af91f34e9685c64919d7d67c1cffd0e.txt", "url": "https://www.jirav.com/accounting-planning-budgeting-forecasting"}], "summary": "面向中小企业与会计事务所的 FP&A 平台，用驱动因素构建预算与预测，联动三张报表并支持情景。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:18471236','LedgerSMB','{"deployment": ["Perl + PostgreSQL Web 应用，可自托管"], "features": ["总账与日记账分录：以复式记账管理科目并在科目间划转", "按年度关账：General Journal > Year End 的 Close Period 可按 Close As-of 冻结此前交易", "销售与采购（客户/供应商、报价、订单与发票）、库存、固定资产与折旧", "多币种、按项目/部门预算及差异报表"], "github_repository_id": 18471236, "homepage": "https://ledgersmb.org", "id": "github:18471236", "leaf_matches": [{"reason": "官方功能页把 “General Ledger and Journal Entry” 列为核心模块，说明以复式记账管理科目、在科目间划转并查看财务全貌；官方 FAQ 的迁移指引要求在 “General Journal > Year End” 的 “Close Period” 页填写 “Close As-of” 并关账，并说明关账后 “no transaction can be entered or modified before or at” 该日期。据此可证科目表、平衡分录与会计期间开启/关闭三个结构；README 说明其为基于 PostgreSQL 的自托管系统。", "slug": "general-ledger-system", "source_urls": ["https://api.github.com/repos/ledgersmb/ledgersmb", "https://api.github.com/repos/ledgersmb/ledgersmb/license", "https://raw.githubusercontent.com/ledgersmb/ledgersmb/HEAD/README.md", "https://ledgersmb.org/features", "https://ledgersmb.org/faq"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/ledgersmb/ledgersmb/license", "license_review": {"rationale": "GitHub license API 响应的 license.spdx_id 为 NOASSERTION，但同一响应的 content 字段（base64）解码后是完整 GNU GPL Version 2 正文，含 “GNU GENERAL PUBLIC LICENSE”“Version 2” 与 “TERMS AND CONDITIONS”；仓库 README 的徽章亦标注 GPLv2，故按 GPL-2.0 记录。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/ledgersmb/ledgersmb/license", "spdx_id": "GPL-2.0"}, "name": "LedgerSMB", "repository_url": "https://github.com/ledgersmb/ledgersmb", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:31.597964+08:00", "kind": "repository_metadata", "sha256": "b761532c4e066957141445952ccaa60e7b505d47639d08446e7eeeffffe9f4d5", "snapshot_path": "sources/b761532c4e066957141445952ccaa60e7b505d47639d08446e7eeeffffe9f4d5.txt", "url": "https://api.github.com/repos/ledgersmb/ledgersmb"}, {"fetched_at": "2026-10-24T20:22:33.113052+08:00", "kind": "license", "sha256": "de88ba99708f880e77888ddabf1798e6311dfe603895cf1bbf4b4a4351d69c99", "snapshot_path": "sources/de88ba99708f880e77888ddabf1798e6311dfe603895cf1bbf4b4a4351d69c99.txt", "url": "https://api.github.com/repos/ledgersmb/ledgersmb/license"}, {"fetched_at": "2026-10-24T20:22:35.791415+08:00", "kind": "readme", "sha256": "0b048db0143162446d6cb7985e6c656916092c6d6cb72f6118efd9a114e496cd", "snapshot_path": "sources/0b048db0143162446d6cb7985e6c656916092c6d6cb72f6118efd9a114e496cd.txt", "url": "https://raw.githubusercontent.com/ledgersmb/ledgersmb/HEAD/README.md"}, {"fetched_at": "2026-10-24T20:22:38.956928+08:00", "kind": "documentation", "sha256": "e71c655e3f064eb3e7645455c8318eb900e78bf47a1ce6e08180c3cef08f1fa4", "snapshot_path": "sources/e71c655e3f064eb3e7645455c8318eb900e78bf47a1ce6e08180c3cef08f1fa4.txt", "url": "https://ledgersmb.org/features"}, {"fetched_at": "2026-10-24T20:56:19.335875+08:00", "kind": "documentation", "sha256": "e826aca5d77c4e6921ada0c65a0e542b6e93128609645e53ee17a0e2a1d4aafc", "snapshot_path": "sources/e826aca5d77c4e6921ada0c65a0e542b6e93128609645e53ee17a0e2a1d4aafc.txt", "url": "https://ledgersmb.org/faq"}], "summary": "面向中小企业的开源复式记账/ERP，核心为科目、日记账分录与总账报表，并覆盖销售采购库存等外围流程。", "technology_stack": ["Perl", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:kubera','Kubera','{"homepage": "https://www.kubera.com/", "id": "commercial:kubera", "leaf_matches": [{"reason": "官方页面标题为 “Kubera is the Balance Sheet for those who keep the 1%”，meta description 称 “Track Stocks, Bonds, Crypto, Alts, Homes, Cars, Commodities, Debts and more in one place. International bank & brokerage accounts.”，结构化数据 featureList 含 “Track banks and brokerages worldwide” 等，页面文案 “For you, Kubera is your balance sheet... with a daily snapshot of everything since you started.”。据此可证个人资产负债表、资产/债务聚合与每日快照。页面未使用 manual entry 描述任意资产的补录，故不作该断言；机构连接覆盖率与逐条估值历史未核验。", "slug": "net-worth-tracker", "source_urls": ["https://www.kubera.com/"]}], "name": "Kubera", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:18.668720+08:00", "kind": "homepage", "sha256": "96f151dd47ac7fb729fb5860bd5e919220a007eabb6bc76c6587735a37e495b9", "snapshot_path": "sources/96f151dd47ac7fb729fb5860bd5e919220a007eabb6bc76c6587735a37e495b9.txt", "url": "https://www.kubera.com/"}], "summary": "面向个人的净资产/资产负债表工具，集中记录资产与负债、连接账户并保留每日净值快照。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:21298446','Firefly III','{"deployment": ["自托管 Web 应用", "可从多种工具导入数据"], "features": ["管理个人账户并记录收入/支出交易", "预算、类别、标签与规则化交易处理", "生成收入支出等财务报告，提供 REST JSON API"], "github_repository_id": 21298446, "homepage": "https://firefly-iii.org/", "id": "github:21298446", "leaf_matches": [{"reason": "README 说明其为自托管个人财务管理器，管理账户并跟踪收入与支出，使用预算、类别与标签，并生成多种财务报告；对应个人账户记录、交易登记簿与综合个人财务视图，边界为个人而非企业账簿。", "slug": "personal-finance-management-application", "source_urls": ["https://api.github.com/repos/firefly-iii/firefly-iii", "https://api.github.com/repos/firefly-iii/firefly-iii/license", "https://raw.githubusercontent.com/firefly-iii/firefly-iii/main/readme.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/firefly-iii/firefly-iii/license", "name": "Firefly III", "repository_url": "https://github.com/firefly-iii/firefly-iii", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:58.309848+08:00", "kind": "repository_metadata", "sha256": "ba176b9232d140210ac9367f747d7a6340483c20f71904eb9ce56fb45cfcc439", "snapshot_path": "sources/ba176b9232d140210ac9367f747d7a6340483c20f71904eb9ce56fb45cfcc439.txt", "url": "https://api.github.com/repos/firefly-iii/firefly-iii"}, {"fetched_at": "2026-10-24T20:23:01.735486+08:00", "kind": "license", "sha256": "bdfdeb43a085b6c50b2b8833559343881d413d067fcfa6bc03ec46994513ae51", "snapshot_path": "sources/bdfdeb43a085b6c50b2b8833559343881d413d067fcfa6bc03ec46994513ae51.txt", "url": "https://api.github.com/repos/firefly-iii/firefly-iii/license"}, {"fetched_at": "2026-10-24T20:23:03.853169+08:00", "kind": "readme", "sha256": "b9fd944dbb3afcc50f0a9f0e8359e826204bc026d68d97b7146dd1d7d8ef921e", "snapshot_path": "sources/b9fd944dbb3afcc50f0a9f0e8359e826204bc026d68d97b7146dd1d7d8ef921e.txt", "url": "https://raw.githubusercontent.com/firefly-iii/firefly-iii/main/readme.md"}], "summary": "自托管个人财务管理器，记录账户与收支交易，支持预算、类别、标签与财务报告。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1013926104','Ignidash','{"deployment": ["Docker 自托管（README 指向 SELF_HOSTING.md）", "可选官方托管版本"], "features": ["对长期财务结果运行数百次 Monte Carlo 与历史回测并给出成功概率", "估算提取、资产位置与收入变化对美国税负的影响", "以 AI 问答与解读说明税、RMD、Roth 转换与提取策略对结果的影响"], "github_repository_id": 1013926104, "homepage": "https://ignidash.com", "id": "github:1013926104", "leaf_matches": [{"reason": "README 称其为 “web-based retirement planning tool”，聚焦 “long-term financial projections”，以数百次 Monte Carlo 与历史回测算出 “probability of success”，并 “Model how withdrawals, asset location, and income changes impact your estimated tax liability”。据此可证个人退休计划的跨期预测、充足性评估与提取对税负的影响估算。README 的 Roadmap 把 “Configurable drawdown order”（Q1 2026）与 “Support for planning as a couple”（Q2 2026）列为未交付，Compare Plans 标注 Coming Soon，故均不写成已具备，也不宣称家庭/夫妇计划。", "slug": "retirement-planning-application", "source_urls": ["https://api.github.com/repos/schelskedevco/ignidash", "https://api.github.com/repos/schelskedevco/ignidash/license", "https://raw.githubusercontent.com/schelskedevco/ignidash/HEAD/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/schelskedevco/ignidash/license", "name": "Ignidash", "repository_url": "https://github.com/schelskedevco/ignidash", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:23:05.322770+08:00", "kind": "repository_metadata", "sha256": "c9f284368a58dad47a82f99fbeda390d9061a1834a4cc8e594253ce5a04688ed", "snapshot_path": "sources/c9f284368a58dad47a82f99fbeda390d9061a1834a4cc8e594253ce5a04688ed.txt", "url": "https://api.github.com/repos/schelskedevco/ignidash"}, {"fetched_at": "2026-10-24T20:23:07.349554+08:00", "kind": "license", "sha256": "523fb9d35e9079cf79d55b09c8c1d695ac7dfc62e52a203ca913fdf9b35cad22", "snapshot_path": "sources/523fb9d35e9079cf79d55b09c8c1d695ac7dfc62e52a203ca913fdf9b35cad22.txt", "url": "https://api.github.com/repos/schelskedevco/ignidash/license"}, {"fetched_at": "2026-10-24T20:23:08.544045+08:00", "kind": "readme", "sha256": "d6268bd382bb6f505cc43fcbe5b11c5393834b01daf7782aaf61b14cd4f3213d", "snapshot_path": "sources/d6268bd382bb6f505cc43fcbe5b11c5393834b01daf7782aaf61b14cd4f3213d.txt", "url": "https://raw.githubusercontent.com/schelskedevco/ignidash/HEAD/README.md"}], "summary": "开源个人退休规划 Web 应用，对长期计划做 Monte Carlo 与历史回测，估算成功概率并建模提取/资产位置对税负的影响。", "technology_stack": ["Next.js", "React", "TypeScript", "Convex"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1414419030','The Talent App','{"deployment": ["自托管：Supabase（自建或云）+ 前端构建，README 提供本地安装指南"], "features": ["按职位组织候选人与看板式招聘流程", "面试安排、结构化反馈与阶段模板", "预筛问卷、数字申请与 Mark as Hired 终态"], "github_repository_id": 1414419030, "homepage": "https://thetalentapp.io", "id": "github:1414419030", "leaf_matches": [{"reason": "README 说明其为开源 ATS，按职位管理候选人与看板式流程，含面试安排、结构化反馈、预筛问卷与“Mark as Hired”终态；对应雇主侧、职位、按职位申请、跟踪式流程与记录结果四个属性。", "slug": "applicant-tracking-system-ats", "source_urls": ["https://api.github.com/repos/vikashsparxit/the-talent-app", "https://api.github.com/repos/vikashsparxit/the-talent-app/license", "https://raw.githubusercontent.com/vikashsparxit/the-talent-app/HEAD/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/vikashsparxit/the-talent-app/license", "name": "The Talent App", "repository_url": "https://github.com/vikashsparxit/the-talent-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:23:10.078595+08:00", "kind": "repository_metadata", "sha256": "23023e766191c83dadf4808d4ec2beaad3ec6472fc859f27bb63fd037dcc1f0f", "snapshot_path": "sources/23023e766191c83dadf4808d4ec2beaad3ec6472fc859f27bb63fd037dcc1f0f.txt", "url": "https://api.github.com/repos/vikashsparxit/the-talent-app"}, {"fetched_at": "2026-10-24T20:23:11.665803+08:00", "kind": "license", "sha256": "2bfad81fc862f2d73787b56565be26eb53b1f4838e1d5ada251317f7d349857a", "snapshot_path": "sources/2bfad81fc862f2d73787b56565be26eb53b1f4838e1d5ada251317f7d349857a.txt", "url": "https://api.github.com/repos/vikashsparxit/the-talent-app/license"}, {"fetched_at": "2026-10-24T20:23:13.166906+08:00", "kind": "readme", "sha256": "1b539cdd5d76618cc358de790c0199738618bfe68f5f3f7297cd3347826296d1", "snapshot_path": "sources/1b539cdd5d76618cc358de790c0199738618bfe68f5f3f7297cd3347826296d1.txt", "url": "https://raw.githubusercontent.com/vikashsparxit/the-talent-app/HEAD/README.md"}], "summary": "开源 ATS，按职位管理候选人与招聘看板，含面试安排、结构化反馈、预筛与录用终态。", "technology_stack": ["React", "TypeScript", "Supabase", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:testgorilla','TestGorilla','{"homepage": "https://www.testgorilla.com/", "id": "commercial:testgorilla", "leaf_matches": [{"reason": "官方评估页原文：“TestGorilla combines skills tests, job simulations, AI interviews, resume scoring, and identity verification into one assessment. Each one is scored against the same criteria, so you get one true picture of every candidate before you decide who to interview.”，同页另有 “before you book a single interview”。据此可证雇主端在首轮面试前以同一套工具与同一评分标准评估候选人、产出可比较结果；题库效度与评分细则未在该页核验。", "slug": "candidate-assessment-platform", "source_urls": ["https://www.testgorilla.com/assessments/"]}], "name": "TestGorilla", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:41.540591+08:00", "kind": "homepage", "sha256": "a7697e190fad231b25ebbc10a2a1f5547b4bbe5f8967c25d77eb6a6759e12e47", "snapshot_path": "sources/a7697e190fad231b25ebbc10a2a1f5547b4bbe5f8967c25d77eb6a6759e12e47.txt", "url": "https://www.testgorilla.com/assessments/"}], "summary": "雇主端候选人评估平台，以技能测试、AI 面试与简历评分为招聘提供同标准、可比较的评分。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gem-crm','Gem CRM','{"homepage": "https://www.gem.com", "id": "commercial:gem-crm", "leaf_matches": [{"reason": "官方 CRM 页 Manage 段标题为 “One source of truth for every candidate relationship”，正文为 “Gem keeps every profile fresh and every interaction logged”；其下列 “Deep ATS sync … a real-time, bi-directional sync” 与 “Enriched profiles that never go stale”；Rediscover 段为 “AI Talent Rediscovery … surfaces past candidates who match your open roles”。FAQ 进一步区分：ATS 只管已申请者，招聘 CRM 管理 “before, during, and after the application” 的关系，Gem 两者都做并以实时同步连接。据此可证以人为单位、跨申请持续维护的档案层与再发现能力；档案字段结构与去重合并机制未在该页展开。", "slug": "candidate-profile-platform", "source_urls": ["https://www.gem.com/crm"]}], "name": "Gem CRM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:46.078862+08:00", "kind": "homepage", "sha256": "b3be8101260d90bb571af9f937c976390a4c2e84b7b9aa8b6f5bd39c85ab3ebb", "snapshot_path": "sources/b3be8101260d90bb571af9f937c976390a4c2e84b7b9aa8b6f5bd39c85ab3ebb.txt", "url": "https://www.gem.com/crm"}], "summary": "招聘候选人关系平台，维护长期候选人档案、自动丰富并支持过往候选人重新发现与 ATS 同步。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:seekout','SeekOut','{"homepage": "https://www.seekout.com/", "id": "commercial:seekout", "leaf_matches": [{"reason": "官方页面说明可在 10 亿+ 档案与自有 ATS 中按技能与经验检索、以 AI 理解上下文而非仅关键词，并返回按匹配度排序、可识别到人的结果；对应可搜索语料、查询与排序结果三个核心。", "slug": "candidate-search-platform", "source_urls": ["https://www.seekout.com/"]}], "name": "SeekOut", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:48.908531+08:00", "kind": "homepage", "sha256": "3451c4bc15db043ab82d4e4f8b5571457b1346997642ee05c6a46e7f43e73d4a", "snapshot_path": "sources/3451c4bc15db043ab82d4e4f8b5571457b1346997642ee05c6a46e7f43e73d4a.txt", "url": "https://www.seekout.com/"}], "summary": "雇主端人才搜索平台，在 10 亿+ 档案与自有 ATS 中按技能/上下文检索并排序具体候选人。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:greenhouse-interview','Greenhouse Structured Hiring','{"homepage": "https://www.greenhouse.com/", "id": "commercial:greenhouse-interview", "leaf_matches": [{"reason": "官方 ATS 页列出 interview kits 与 scorecards；FAQ 说明结构化面试指 “every candidate for a role gets the same questions and is assessed against the same criteria”，评分卡 “keep feedback consistent and make candidates easier to compare”，Notetaker 把笔记 “organized around scorecard questions” 并可一键转入评分卡；Reporting & analytics 下列 “Compare interview kits and scorecards across jobs”。据此可证按职位定义的结构化面试计划与评分卡、反馈围绕评分卡问题归集，以及跨职位比较面试套件/评分卡的报表能力。逐场面试指南与录音同意细节未在该页核验。", "slug": "interview-management-platform", "source_urls": ["https://www.greenhouse.com/ats"]}], "name": "Greenhouse Structured Hiring", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:21:58.975160+08:00", "kind": "homepage", "sha256": "bdcc9264327e14280d7cdaeef6340589ed176a53b2e83384a10ed07a8127c4d4", "snapshot_path": "sources/bdcc9264327e14280d7cdaeef6340589ed176a53b2e83384a10ed07a8127c4d4.txt", "url": "https://www.greenhouse.com/ats"}], "summary": "招聘平台中的结构化面试管理能力，提供按职位的面试计划、面试套件与评分卡反馈。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:goodtime','GoodTime','{"homepage": "https://goodtime.io/", "id": "commercial:goodtime", "leaf_matches": [{"reason": "官方页面列出 “Single-day, multi-day, and panel interviews”、候选人侧 “Branded self-scheduling and candidate portal”、面试官侧 “Selection, auto-replacement, interviewer portal” 以及 AI Notetaker；页面嵌入 JSON 说明 “Finds times across every interviewer’s calendar, automatically”。据此可证面试记录、候选人自助预约、面试官选择/替换与基于日历的可用性协调。", "slug": "interview-scheduling-platform", "source_urls": ["https://goodtime.io/"]}], "name": "GoodTime", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:01.823340+08:00", "kind": "homepage", "sha256": "0db33b6926667d5bc1b1da1e8bdc3441344185eda495bb3a323ce8c175f35b9a", "snapshot_path": "sources/0db33b6926667d5bc1b1da1e8bdc3441344185eda495bb3a323ce8c175f35b9a.txt", "url": "https://goodtime.io/"}], "summary": "面试安排平台，支持小组/多日面试、候选人自助预约与面试官自动替换。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pinpoint-offer-management','Pinpoint Offer Management','{"homepage": "https://www.pinpointhq.com/", "id": "commercial:pinpoint-offer-management", "leaf_matches": [{"reason": "官方 offer 页面说明以模板生成 offer、按字段配置多级审批并保留审计轨迹、内置或 DocuSign 电子签名、实时状态与到期跟踪、接受后自动转已录用；对应录用记录与发出—回应闭环两个核心。", "slug": "offer-management-platform", "source_urls": ["https://www.pinpointhq.com/features/offer-management-software"]}], "name": "Pinpoint Offer Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:05.122772+08:00", "kind": "homepage", "sha256": "72de15ec7ebdc27fd494792c5d3f53858bcef121b6fbf35dbd0e8177f97c24c4", "snapshot_path": "sources/72de15ec7ebdc27fd494792c5d3f53858bcef121b6fbf35dbd0e8177f97c24c4.txt", "url": "https://www.pinpointhq.com/features/offer-management-software"}], "summary": "招聘平台内的录用管理模块，提供 offer 模板、审批链、电子签名、状态跟踪与接受后转录用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:smartrecruiters','SmartRecruiters','{"homepage": "https://www.smartrecruiters.com/", "id": "commercial:smartrecruiters", "leaf_matches": [{"reason": "官方页面把职位发布、CRM、申请人跟踪、筛选、动态排期、录用管理与入职列为同一企业招聘平台的核心模块；对应职位、候选人、申请流程与记录结果四个属性，并明确其为雇主端软件。", "slug": "recruiting-management-platform", "source_urls": ["https://www.smartrecruiters.com/"]}], "name": "SmartRecruiters", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:07.725540+08:00", "kind": "homepage", "sha256": "dfcb906b89264f147c2779a37cd3679389be7cf476bf73d566966e4ac93b876f", "snapshot_path": "sources/dfcb906b89264f147c2779a37cd3679389be7cf476bf73d566966e4ac93b876f.txt", "url": "https://www.smartrecruiters.com/"}], "summary": "企业招聘管理平台，覆盖职位发布、候选人跟踪、筛选排期、录用管理与入职衔接。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:joveo','Joveo','{"homepage": "https://www.joveo.com/", "id": "commercial:joveo", "leaf_matches": [{"reason": "官方页面写明职位广告投放到 “Across hundreds of thousands of job boards, social media, and destination sites globally” 并自动优化，活动侧提供 “personalized email and SMS sequences” 与 “high-converting career sites and landing pages”，效果侧可 “Track campaign performance and costs in real time” 并以 “Lower cost per qualified applicant” 为指标；页面列出 ATS 集成并称同步后可 “delivering insights from source to hire”。据此可证预申请受众、自有/外部吸引机制与以申请为目标的度量。页面未使用 programmatic 一词，也未披露独立的申请转化漏斗报表，故不作该断言。", "slug": "recruitment-marketing-platform", "source_urls": ["https://www.joveo.com/ai-agent-recruitment-marketing/"]}], "name": "Joveo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:54:59.382373+08:00", "kind": "homepage", "sha256": "cd7f304063f9886bbdb8f7918276565630090e0cb20a9ab5a23373af1cefe584", "snapshot_path": "sources/cd7f304063f9886bbdb8f7918276565630090e0cb20a9ab5a23373af1cefe584.txt", "url": "https://www.joveo.com/ai-agent-recruitment-marketing/"}], "summary": "招聘营销平台，以职位广告投放、职业站点/落地页与邮件短信活动吸引申请并跟踪活动成本与效果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:249995750','Reactive Resume','{"deployment": ["Docker 自托管", "官方托管站点 rxresu.me"], "features": ["按简历章节填写结构化内容并由工具套用模板排版", "实时预览并导出 PDF、Word、Markdown、JSON", "ATS 安全模板筛选与公开分享链接"], "github_repository_id": 249995750, "homepage": "https://rxresu.me", "id": "github:249995750", "leaf_matches": [{"reason": "README 说明以结构化简历编辑器填写内容、由工具套用模板并实时预览，导出 PDF/Word/Markdown/JSON，并提供 ATS 安全模板筛选；对应结构化内容模型、工具负责排版与可移植成品文件三个核心。", "slug": "resume-builder", "source_urls": ["https://api.github.com/repos/reactive-resume/reactive-resume", "https://api.github.com/repos/reactive-resume/reactive-resume/license", "https://raw.githubusercontent.com/reactive-resume/reactive-resume/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/reactive-resume/reactive-resume/license", "name": "Reactive Resume", "repository_url": "https://github.com/reactive-resume/reactive-resume", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:12:17.836380+08:00", "kind": "repository_metadata", "sha256": "f95aa869406feae11549e4695b3290fbc2977dee1e0a51aeadf58bed492eb190", "snapshot_path": "sources/f95aa869406feae11549e4695b3290fbc2977dee1e0a51aeadf58bed492eb190.txt", "url": "https://api.github.com/repos/reactive-resume/reactive-resume"}, {"fetched_at": "2026-10-24T20:12:19.478999+08:00", "kind": "license", "sha256": "2ae658c015a7fbf01d24af6014ac115688c6d063249cf214f31a354cd9a90f34", "snapshot_path": "sources/2ae658c015a7fbf01d24af6014ac115688c6d063249cf214f31a354cd9a90f34.txt", "url": "https://api.github.com/repos/reactive-resume/reactive-resume/license"}, {"fetched_at": "2026-10-24T20:23:17.070207+08:00", "kind": "readme", "sha256": "c888f4d3331b9b27781ab1adae7d586ee8d6cfc4d3d6bd0f2f68815d5319a848", "snapshot_path": "sources/c888f4d3331b9b27781ab1adae7d586ee8d6cfc4d3d6bd0f2f68815d5319a848.txt", "url": "https://raw.githubusercontent.com/reactive-resume/reactive-resume/main/README.md"}], "summary": "开源简历生成器，以结构化内容模型填写简历，套用模板渲染并导出 PDF/Word 等成品文件。", "technology_stack": ["React", "TypeScript", "Hono / Node.js", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lattice-talent-reviews','Lattice Talent Reviews','{"homepage": "https://lattice.com/", "id": "commercial:lattice-talent-reviews", "leaf_matches": [{"reason": "官方人才评审页说明以模板组织评审、用九宫格呈现绩效与潜力，通过校准组调整评分并在全组织达成一致，且与绩效评估数据区分；对应评审人群、评审场合、校准评价与记录结果四个结构。", "slug": "talent-review-platform", "source_urls": ["https://lattice.com/platform/performance/talent-reviews"]}], "name": "Lattice Talent Reviews", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:13.843357+08:00", "kind": "homepage", "sha256": "ee824bb40fd2559975c95283ff3111c4cab03f63e5e88795fcaac34b5bfb164c", "snapshot_path": "sources/ee824bb40fd2559975c95283ff3111c4cab03f63e5e88795fcaac34b5bfb164c.txt", "url": "https://lattice.com/platform/performance/talent-reviews"}], "summary": "HR 平台中的人才评审模块，支持评审模板、九宫格、校准组与绩效/潜力讨论。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sourcewhale','SourceWhale','{"homepage": "https://sourcewhale.com/", "id": "commercial:sourcewhale", "leaf_matches": [{"reason": "官方页面说明以邮件、短信、WhatsApp 多渠程序列从自有时箱发出并自动跟进，回复进入 Inbox，触达与结果同步 CRM/ATS；对应被跟进人群、计划性触达序列与回复循环三个核心。", "slug": "talent-sourcing-platform", "source_urls": ["https://sourcewhale.com/"]}], "name": "SourceWhale", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:16.440693+08:00", "kind": "homepage", "sha256": "3ff8d2614eed6e72ddd6eb3555d260cbfd28580702578cf2039fd6af88ff4bd6", "snapshot_path": "sources/3ff8d2614eed6e72ddd6eb3555d260cbfd28580702578cf2039fd6af88ff4bd6.txt", "url": "https://sourcewhale.com/"}], "summary": "招聘互动执行平台，以多渠道 Outreach 序列联系已识别候选人，并将回复与记录同步到 CRM/ATS。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:501292795','Frappe HR','{"deployment": ["自托管 Web 应用", "Frappe Cloud 可选"], "features": ["员工主数据与生命周期", "员工入职流程与任务", "员工离职流程与任务", "考勤与班次", "薪资与工资条", "绩效考核与目标", "组织结构图"], "github_repository_id": 501292795, "homepage": "https://frappe.io/hr", "id": "github:501292795", "leaf_matches": [{"reason": "Frappe HR 的 Job Portal 是雇主自有 Frappe 站点上的完整招聘门户子模块：官方文档说明 Job Opening 以 Publish on website 发布到 /jobs，门户供申请人浏览并申请已发布职位，点击 Apply Now 填写公共 Web Form，提交后生成 Job Applicant 记录，进入同一系统的招聘流程；职位关闭后不再能申请。仓库代码进一步证明列表查询条件为 status=Open 且 publish=1，详情页在 Open 时输出 Apply Now、Closed 时显示 Opening closed，申请表为 login_required=0 的公开 Web Form。雇主在后台以发布开关、富文本描述、部门/地点/雇佣类型与可选薪资范围无代码维护职位内容，站点层 Website Theme 支持配色字体按钮样式以匹配品牌。四项定义属性均有官方正文支撑；边界上只计其 Job Portal 子模块，不含 Frappe HR 的面试/Offer 等 ATS 流程，也不含多雇主职位板。", "slug": "career-site-platform", "source_urls": ["https://docs.frappe.io/hr/job-portal", "https://docs.frappe.io/hr/job-opening", "https://docs.frappe.io/hr/job-applicant", "https://raw.githubusercontent.com/frappe/hrms/develop/hrms/www/jobs/index.py", "https://raw.githubusercontent.com/frappe/hrms/develop/hrms/templates/generators/job_opening.html", "https://raw.githubusercontent.com/frappe/hrms/develop/hrms/hr/web_form/job_application/job_application.json", "https://docs.frappe.io/erpnext/website-theme"]}, {"reason": "官方文档 Employee Separation 说明基于模板创建离职流程，生成任务与项目，并跟踪活动完成状态。", "slug": "employee-offboarding-platform", "source_urls": ["https://docs.frappe.io/hr/employee-separation"]}, {"reason": "官方文档 Employee Onboarding 说明基于模板创建入职流程，生成任务与项目，并跟踪活动完成状态。", "slug": "employee-onboarding-platform", "source_urls": ["https://docs.frappe.io/hr/employee-onboarding"]}, {"reason": "官方文档 Employee 说明员工主数据记录个人与雇佣信息，并作为员工生命周期的记录。", "slug": "employee-record-system", "source_urls": ["https://docs.frappe.io/hr/employee"]}, {"reason": "官方文档与组织结构图说明员工记录、组织结构与雇佣生命周期管理。", "slug": "human-capital-management-hcm", "source_urls": ["https://docs.frappe.io/hr/employee", "https://docs.frappe.io/hr/organizational-chart"]}, {"reason": "官方文档说明员工记录、组织结构与核心人力资源运营流程。", "slug": "human-resource-information-system-hris", "source_urls": ["https://docs.frappe.io/hr/employee", "https://docs.frappe.io/hr/organizational-chart"]}, {"reason": "官方文档明确组织图由员工记录中的 Reports To 字段生成，员工不向任何人汇报时位于第一层；每个节点可进入员工主档编辑。这证明汇报关系作为记录保存、图表由记录渲染且随记录编辑更新。产品整体是 HRMS，被匹配的是其完整组织图子模块。", "slug": "org-chart-management", "source_urls": ["https://docs.frappe.io/hr/organizational-chart", "https://raw.githubusercontent.com/frappe/hrms/HEAD/README.md"]}, {"reason": "官方文档 Salary Slip 与 Payroll Entry 说明薪资结构、工资条与薪资运行。", "slug": "payroll-system", "source_urls": ["https://docs.frappe.io/hr/payroll-entry", "https://docs.frappe.io/hr/salary-slip"]}, {"reason": "官方文档 Appraisal 说明绩效考核、KRA、反馈与自评。", "slug": "performance-management-platform", "source_urls": ["https://docs.frappe.io/hr/appraisal"]}, {"reason": "官方文档 Attendance 说明考勤状态、班次、工时与自动考勤。", "slug": "time-attendance-system", "source_urls": ["https://docs.frappe.io/hr/attendance", "https://docs.frappe.io/hr/employee-checkin"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/frappe/hrms/license", "name": "Frappe HR", "repository_url": "https://github.com/frappe/hrms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:59:00.700867+08:00", "kind": "repository_metadata", "sha256": "cb9dd2f3ece7cd5ffe7cacaab4355699b45159d08339e8af341d1daaf32f09bd", "snapshot_path": "sources/cb9dd2f3ece7cd5ffe7cacaab4355699b45159d08339e8af341d1daaf32f09bd.txt", "url": "https://api.github.com/repos/frappe/hrms"}, {"fetched_at": "2026-10-24T20:59:32.341764+08:00", "kind": "repository_metadata", "sha256": "dd11354c600b13c9bc726a5a4ec9625d5b87cfba856a66540b3a32d1c56000ab", "snapshot_path": "sources/dd11354c600b13c9bc726a5a4ec9625d5b87cfba856a66540b3a32d1c56000ab.txt", "url": "https://api.github.com/repos/frappe/hrms"}, {"fetched_at": "2026-10-24T20:59:35.350963+08:00", "kind": "license", "sha256": "ae3aeb82597f07a3736c56570f195adf78fbce702b03c4e08