INSERT INTO "application" VALUES('commercial:skills-base','Skills Base','{"homepage": "https://www.skills-base.com", "id": "commercial:skills-base", "leaf_matches": [{"reason": "官方产品正文：/tour 写明 Skill and Competency Targets 为每项技能设定目标等级以暴露差距、Supervisor Skills Assessment 对每人技能等级与工作就绪度作验证、Custom Skill Ratings 对齐组织能力框架与各角色所需熟练度、Role Skills Matrix 展示每个角色的技能优势与差距；/skills-gap-analysis-tool 的六步流程写明用自评与经理验证评估现有熟练度、为每个角色设定目标熟练度、再比较实际与目标得出差距；/competency-framework 说明组织自建并分组技能清单、按职能/组织结构把技能分配给人员。对应定义核心的模型、个人档案与差距比较三层。", "slug": "competency-management-platform", "source_urls": ["https://www.skills-base.com/tour", "https://www.skills-base.com/skills-gap-analysis-tool", "https://www.skills-base.com/competency-framework", "https://www.skills-base.com"]}, {"reason": "官方首页说明技能管理、技能矩阵与技能评估。", "slug": "skills-management-platform", "source_urls": ["https://www.skills-base.com"]}], "name": "Skills Base", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T21:37:58.852029+08:00", "kind": "homepage", "sha256": "88a5791cc2b2adea8f7329ca5f914b81729549b7ba77a4dbef875f52849fea27", "snapshot_path": "sources/88a5791cc2b2adea8f7329ca5f914b81729549b7ba77a4dbef875f52849fea27.txt", "url": "https://www.skills-base.com"}, {"fetched_at": "2026-10-28T16:09:01.632843+08:00", "kind": "documentation", "sha256": "9b5c8a51c79cd5f6e7281bec9a9015e70ce687fe659202056569d6cad47e90be", "snapshot_path": "sources/9b5c8a51c79cd5f6e7281bec9a9015e70ce687fe659202056569d6cad47e90be.txt", "url": "https://www.skills-base.com/competency-framework"}, {"fetched_at": "2026-10-28T16:08:42.243337+08:00", "kind": "documentation", "sha256": "705d7708886335909f4255dcc4187d9c02108bf35422c198a1bbf6b6327a19db", "snapshot_path": "sources/705d7708886335909f4255dcc4187d9c02108bf35422c198a1bbf6b6327a19db.txt", "url": "https://www.skills-base.com/skills-gap-analysis-tool"}, {"fetched_at": "2026-10-28T16:29:08.894919+08:00", "kind": "documentation", "sha256": "f755cec8342fdd69bfb635de83e3726981c4cd78ed4e7825537aee3a18ceedbc", "sna