INSERT INTO "application" VALUES('commercial:visier','Visier','{"homepage": "https://www.visier.com/", "id": "commercial:visier", "leaf_matches": [{"reason": "官方 Workforce Insights 页面说明把分散人员数据整合为单一模型，统一指标与口径，支持按角色提问获得受治理答案、对比基准并解释变动；对应整合数据层、受治理指标与随时间分析问答循环。", "slug": "people-analytics-platform", "source_urls": ["https://www.visier.com/workforce-ai/product/workforce-insights/"]}, {"reason": "官方 Workforce Planning 页面说明可查看当前人数与成本、按未来需求规划、并排比较结构/成本/技能/地点场景，并把 HR、财务与运营输入汇成一个计划；对应基线、需求、差距、场景与持续跟踪结构。", "slug": "workforce-planning-platform", "source_urls": ["https://www.visier.com/workforce-ai/product/workforce-planning/"]}], "name": "Visier", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:53:10.223478+08:00", "kind": "documentation", "sha256": "0e896cf7868980761e61b48e9d63196c63c766132e4a434e5a7b3e5987d52263", "snapshot_path": "sources/0e896cf7868980761e61b48e9d63196c63c766132e4a434e5a7b3e5987d52263.txt", "url": "https://www.visier.com/workforce-ai/product/workforce-insights/"}, {"fetched_at": "2026-10-24T20:53:13.207712+08:00", "kind": "documentation", "sha256": "43a155c716148ee33b424367b855b740a5f4a1da689b09ee4428eff97d2d3a76", "snapshot_path": "sources/43a155c716148ee33b424367b855b740a5f4a1da689b09ee4428eff97d2d3a76.txt", "url": "https://www.visier.com/workforce-ai/product/workforce-planning/"}], "summary": "商业劳动力分析与规划平台：把多源人员数据汇入统一模型，提供受治理指标、基准与问答应答，并在同一产品内做供需与场景规划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
