INSERT INTO "application" VALUES('commercial:topdesk','TOPdesk','{"homepage": "https://www.topdesk.com/en/", "id": "commercial:topdesk", "leaf_matches": [{"reason": "官方 ESM 页说明员工可在门户提交请求并跟踪状态，以类似网店的服务目录申请房间预订、合同变更等服务，并可查知识库/FAQ；对应认证员工、可请求服务集合、引导式请求与请求者可见的跟踪记录。", "slug": "employee-service-portal", "source_urls": ["https://www.topdesk.com/en/enterprise-service-management-software/"]}, {"reason": "官方页面说明同一平台面向 IT 之外的多个部门，各部门作为服务提供方共用门户、目录、SLA 与知识，并以入职为例串联 HR、设施与 IT；对应跨部门共享服务管理机制与部门自治的服务产品。", "slug": "enterprise-service-management", "source_urls": ["https://www.topdesk.com/en/enterprise-service-management-software/", "https://www.topdesk.com/en/"]}], "name": "TOPdesk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T21:07:25.673632+08:00", "kind": "documentation", "sha256": "88698353a31e97e1e28d66d462ff0e12aa0d5b06d0d8a2480d622365f17e738a", "snapshot_path": "sources/88698353a31e97e1e28d66d462ff0e12aa0d5b06d0d8a2480d622365f17e738a.txt", "url": "https://www.topdesk.com/en/"}, {"fetched_at": "2026-10-24T21:09:46.567025+08:00", "kind": "documentation", "sha256": "50d933455138956dfa72bb8fa1be5a6b840c271f76a25280c255089b5628d44f", "snapshot_path": "sources/50d933455138956dfa72bb8fa1be5a6b840c271f76a25280c255089b5628d44f.txt", "url": "https://www.topdesk.com/en/enterprise-service-management-software/"}], "summary": "商业服务管理平台：以自助门户、服务目录、工单与 SLA 支撑多部门内部服务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3305384','LimeSurvey','{"deployment": ["自托管 PHP Web 应用"], "features": ["问卷与问题编辑", "30+ 题型与条件分支", "个人链接/受邀访问的封闭调查", "回复与统计", "多语言问卷", "RemoteControl API"], "github_repository_id": 3305384, "homepage": "https://www.limesurvey.org/", "id": "github:3305384", "leaf_matches": [{"reason": "README 与官网说明可编写不限量问卷、用个人链接或受邀模式定向分发给已知名单、收集回复并查看统计与高级分析；符合定义中「编写问卷→发给已知员工名单→收集→按题结果」的最小核心。其为通用调查工具，未据此断言 HR 系统同步或员工专用匿名阈值。", "slug": "employee-survey-platform", "source_urls": ["https://raw.githubusercontent.com/LimeSurvey/LimeSurvey/HEAD/README.md", "https://www.limesurvey.org/"]}], "license": "GPL-2.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/LimeSurvey/LimeSurvey/HEAD/LICENSE", "license_review": {"rationale": "完整 LICENSE 文本声明按自由软件基金会发布的 GNU GPL 第 2 版或任选更高版本授权，正文含 GPLv2 完整条款；GitHub 许可证 API 仅归类为 Other，故以完整文本作编辑性认定，限定为仓库范围。", "reviewer": "part-017-collection-review", "scope": "repository", "source_url": "https://raw.githubusercontent.com/LimeSurvey/LimeSurvey/HEAD/LICENSE", "spdx_id": "GPL-2.0-or-later"}, "name": "LimeSurvey", "repository_url": "https://github.com/LimeSurvey/LimeSurvey", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:44:33.441112+08:00", "kind": "documentation", "sha256": "17e172f52c8705e5a6da43dd26f8425846ee4895e5293b5cf186d173fc9a6731", "snapshot_path": "sources/17e172f52c8705e5a6da43dd26f8425846ee4895e5293b5cf186d173fc9a6731.txt", "url": "https://www.limesurvey.org/"}, {"fetched_at": "2026-10-24T21:03:24.353680+08:00", "kind": "readme", "sha256": "6ffc8c2f420296f3a3efd7958c7c299d84601b5b988abec5568929fd670ee7d5", "snapshot_path": "sources/6ffc8c2f420296f3a3efd7958c7c299d84601b5b988abec5568929fd670ee7d5.txt", "url": "https://raw.githubusercontent.com/LimeSurvey/LimeSurvey/HEAD/README.md"}, {"fetched_at": "2026-10-24T21:03:26.467922+08:00", "kind": "repository_metadata", "sha256": "24dd4f9dfa4ec3d6f4b9b2e6025d5453d92193bea1db270e2009bfc3b1fbb55c", "snapshot_path": "sources/24dd4f9df