INSERT INTO "application" VALUES('commercial:jira-service-management','Jira Service Management','{"homepage": "https://atlassian.com/software/jira/service-management", "id": "commercial:jira-service-management", "leaf_matches": [{"reason": "Atlassian 官方文档说明用请求类型捕获请求详情、组织到门户分组供客户提交、以队列分派、配置审批阶段并为请求类型定义审批人；对应已发布服务目录、提交请求、路由/审批与请求者可见的受跟踪生命周期。", "slug": "enterprise-request-management", "source_urls": ["https://support.atlassian.com/jira-service-management-cloud/docs/what-is-jira-service-management/"]}], "name": "Jira Service Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T21:01:23.205487+08:00", "kind": "documentation", "sha256": "3b6ba66fbcd0401408993da13627b79a5ceb6f310bf55c608e54bcc899b764cf", "snapshot_path": "sources/3b6ba66fbcd0401408993da13627b79a5ceb6f310bf55c608e54bcc899b764cf.txt", "url": "https://support.atlassian.com/jira-service-management-cloud/docs/what-is-jira-service-management/"}], "summary": "商业服务请求与工作管理平台：以请求类型、门户、队列、审批与 SLA 编排内部请求履行。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
