INSERT INTO "application" VALUES('commercial:discord','Discord','{"homepage": "https://discord.com", "id": "commercial:discord", "leaf_matches": [{"reason": "Discord 官方社区服务器设置与角色权限文档显示服务器（社区）是成员加入的顶层容器，频道位于其下，运营者用角色和频道权限管理访问；符合社区聊天平台的社区—房间—实时消息结构。", "slug": "community-chat-platform", "source_urls": ["https://support.discord.com/hc/en-us/articles/213530048-Advanced-Community-Server-Setup", "https://support.discord.com/hc/en-us/articles/214836687-Discord-Roles-and-Permissions"]}], "name": "Discord", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:32:49.451641+08:00", "kind": "documentation", "sha256": "ed465272ba2e9ce63f6cf3af28e1ff78a34103e99fcaca089aae94323c2aa5a1", "snapshot_path": "sources/ed465272ba2e9ce63f6cf3af28e1ff78a34103e99fcaca089aae94323c2aa5a1.txt", "url": "https://support.discord.com/hc/en-us/articles/223657667-Group-Chat-and-Calls"}, {"fetched_at": "2026-10-23T19:32:51.356075+08:00", "kind": "documentation", "sha256": "4fa324212f2dd2d030662f6bd6af5053840b130228d732ad071a2a5fd3380393", "snapshot_path": "sources/4fa324212f2dd2d030662f6bd6af5053840b130228d732ad071a2a5fd3380393.txt", "url": "https://support.discord.com/hc/en-us/articles/360041721052-Video-Calls"}, {"fetched_at": "2026-10-23T19:32:52.788479+08:00", "kind": "documentation", "sha256": "a6ee6bdb5bbf57891e92ca15a93f8e36a3d5ec9060a59fccb89c4ecdd13f2f71", "snapshot_path": "sources/a6ee6bdb5bbf57891e92ca15a93f8e36a3d5ec9060a59fccb89c4ecdd13f2f71.txt", "url": "https://support.discord.com/hc/en-us/articles/213530048-Advanced-Community-Server-Setup"}, {"fetched_at": "2026-10-23T19:32:54.438667+08:00", "kind": "documentation", "sha256": "b7b996ce12437ee9439bf43f0b744779cc80677815bf49f4ef22084c3837b5d7", "snapshot_path": "sources/b7b996ce12437ee9439bf43f0b744779cc80677815bf49f4ef22084c3837b5d7.txt", "url": "https://support.discord.com/hc/en-us/articles/214836687-Discord-Roles-and-Permissions"}], "summary": "面向社区运营者的托管聊天服务器：用角色与频道权限管理成员访问，并保留社区内的持续交流记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:4224042','Roundcube','{"deployment": ["官方安装说明支持PHP服务器与数据库部署；本轮未运行软件"], "features": ["浏览器中访问IMAP邮箱、管理文件夹、搜索邮件和联系人", "使用SMTP发送邮件并连接常见数据库后端"], "github_repository_id": 4224042, "homepage": "https://roundcube.net", "id": "github:4224042", "leaf_matches": [{"reason": "Roundcube README 与官网说明它是浏览器中的 IMAP 邮件客户端，提供 MIME、地址簿、文件夹管理、邮件搜索与 SMTP 发信；连接实际邮件账户并呈现持久邮箱，符合邮件客户端。它是面向用户配置服务器的客户端，不作为服务托管 Webmail 计入。", "slug": "email-client", "source_urls": ["https://raw.githubusercontent.com/roundcube/roundcubemail/master/README.md", "https://roundcube.net/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/roundcube/roundcubemail/license", "name": "Roundcube", "repository_url": "https://github.com/roundcube/roundcubemail", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:32:08.160915+08:00", "kind": "repository_metadata", "sha256": "3cf5692cc2aceb209180635b60ebc15d6fba62049eb113f2eca96a8c83966730", "snapshot_path": "sources/3cf5692cc2aceb209180635b60ebc15d6fba62049eb113f2eca96a8c83966730.txt", "url": "https://api.github.com/repos/roundcube/roundcubemail"}, {"fetched_at": "2026-10-23T19:32:09.592545+08:00", "kind": "license", "sha256": "5353b94c90a0c5ccc0fd9add80f6ac06bbfe937ce350f042ed9b8adfdb341e82", "snapshot_path": "sources/5353b94c90a0c5ccc0fd9add80f6ac06bbfe937ce350f042ed9b8adfdb341e82.txt", "url": "https://api.github.com/repos/roundcube/roundcubemail/license"}, {"fetched_at": "2026-10-23T19:32:12.198979+08:00", "kind": "readme", "sha256": "ca0e5e4b3d2c30e9bb6816c39d401a9ab1fb1589cb2e26de95fa671cdb041ab6", "snapshot_path": "sources/ca0e5e4b3d2c30e9bb6816c39d401a9ab1fb1589cb2e26de95fa671cdb041ab6.txt", "url": "https://raw.githubusercontent.com/roundcube/roundcubemail/master/README.md"}, {"fetched_at": "2026-10-23T19:32:05.425210+08:00", "kind": "homepage", "sha256": "6d1722645a3887f6e9bffd9c41f0dcd551d3505d022a3ff3161e3c98ef768945", "snapshot_path": "sources/6d1722645a3887f6e9bffd9c41f0dcd551d3505d022a3ff3161e3c98ef768945.txt", "url": "https://roundcube.net/"}, {"fetched_at": "2026-10-23T19:32:06.814860+08:00", "kind": "documentation", "sha256": "b819b0804519c8085a93707735336a6ed10c63bfd56bc294e0d3b87ec8d0a671", "snapshot_path": "sources/b819b0804519c8085a93707735336a6ed10c63bfd56bc294e0d3b87ec8d0a671.txt", "url": "https://roundcube.net/about/"}], "summary": "浏览器中的开源 IMAP 邮件客户端，支持收发信、地址簿、文件夹、搜索和插件扩展，可部署在自有服务器。", "technology_stack": ["PHP", "IMAP/SMTP", "MySQL/PostgreSQL/SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1391032312','Dispatch','{"deployment": ["官方README提供Docker自托管部署与云版说明；这里只映射AGPL社区仓库功能"], "features": ["团队共享邮件工作区，连接Gmail、Outlook和IMAP邮箱", "支持分配、内部评论、共享草稿和协作处理"], "github_repository_id": 1391032312, "homepage": "https://github.com/codextde/dispatch", "id": "github:1391032312", "leaf_matches": [{"reason": "官方README呈现完整团队邮件工作区：连接已有邮箱、共享处理、分派、评论及共同草稿，符合邮件协作应用的客户工作流。", "slug": "email-collaboration-application", "source_urls": ["https://raw.githubusercontent.com/codextde/dispatch/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/codextde/dispatch/license", "name": "Dispatch", "repository_url": "https://github.com/codextde/dispatch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:36:52.473840+08:00", "kind": "repository_metadata", "sha256": "dffd9c0e96d080b5691ba196e3605d4a5ea7e95c5de4ad6900d26f2041cfb148", "snapshot_path": "sources/dffd9c0e96d080b5691ba196e3605d4a5ea7e95c5de4ad6900d26f2041cfb148.txt", "url": "https://api.github.com/repos/codextde/dispatch"}, {"fetched_at": "2026-10-23T19:36:54.163259+08:00", "kind": "license", "sha256": "ecb2a68a9ff56d24d9a71b048b66d487723dbcb9a50acba88ac4ec39500e7744", "snapshot_path": "sources/ecb2a68a9ff56d24d9a71b048b66d487723dbcb9a50acba88ac4ec39500e7744.txt", "url": "https://api.github.com/repos/codextde/dispatch/license"}, {"fetched_at": "2026-10-23T19:36:55.369422+08:00", "kind": "readme", "sha256": "eea1b36676db92df57a2d6cd98baa8af784de551ac2927dc06c09ebe5e0aaea6", "snapshot_path": "sources/eea1b36676db92df57a2d6cd98baa8af784de551ac2927dc06c09ebe5e0aaea6.txt", "url": "https://raw.githubusercontent.com/codextde/dispatch/main/README.md"}], "summary": "面向团队的协作收件箱：连接 Gmail、Outlook 或 IMAP 邮箱，提供共享收件箱、会话内私密评论、分配与共享草稿。", "technology_stack": ["TypeScript", "Node.js", "PostgreSQL", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:exchange-online-shared-mailbox','Exchange Online Shared Mailbox','{"homepage": "https://microsoft.com", "id": "commercial:exchange-online-shared-mailbox", "leaf_matches": [{"reason": "Microsoft官方文档说明共享邮箱作为组织共同地址，由多名成员获完整访问及Send As权限，可集中接收和代表该地址发送邮件。", "slug": "shared-mailbox-application", "source_urls": ["https://learn.microsoft.com/en-us/exchange/collaboration-exo/shared-mailboxes"]}], "name": "Exchange Online Shared Mailbox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:32:21.438106+08:00", "kind": "documentation", "sha256": "537a82bcb14803313394081ab75f512631df6de02f7c00f0c92b2d28b7bf0e6c", "snapshot_path": "sources/537a82bcb14803313394081ab75f512631df6de02f7c00f0c92b2d28b7bf0e6c.txt", "url": "https://learn.microsoft.com/en-us/exchange/collaboration-exo/shared-mailboxes"}], "summary": "组织可分配成员权限并共同处理、回复和发送来自专用组织地址的邮件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fastmail','Fastmail','{"homepage": "https://www.fastmail.com", "id": "commercial:fastmail", "leaf_matches": [{"reason": "Fastmail 官方域名托管页说明由 Fastmail 托管邮箱（Hosting email for your domain），每个用户有自己的 inbox 与 login；速度页说明其自建 Cyrus 邮件服务器与全文搜索索引，并以自有 app 与 webmail 交付。邮箱由服务方托管、用户登录即进入自有邮箱、邮件与搜索在网页客户端完成，浏览器交付、服务托管与登录即用成立。", "slug": "webmail-application", "source_urls": ["https://www.fastmail.com/features/domains/", "https://www.fastmail.com/features/lightning-quick/"]}], "name": "Fastmail", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T20:04:53.386806+08:00", "kind": "homepage", "sha256": "bb7322200ced0c26eb21fbaec3e08a20c2115c47353858957a66e88d5940ae52", "snapshot_path": "sources/bb7322200ced0c26eb21fbaec3e08a20c2115c47353858957a66e88d5940ae52.txt", "url": "https://www.fastmail.com/"}, {"fetched_at": "2026-10-23T20:07:19.486077+08:00", "kind": "homepage", "sha256": "ce350d7fa2bbc90d35adf13111508b1f85f75fe6895dcb29c815c4d433bd3e48", "snapshot_path": "sources/ce350d7fa2bbc90d35adf13111508b1f85f75fe6895dcb29c815c4d433bd3e48.txt", "url": "https://www.fastmail.com/features/"}, {"fetched_at": "2026-10-24T12:22:18.977094+08:00", "kind": "documentation", "sha256": "512bd04f3083aff08e0e5503c2722124dc636ee80b20ccb04384c3b46b27e963", "snapshot_path": "sources/512bd04f3083aff08e0e5503c2722124dc636ee80b20ccb04384c3b46b27e963.txt", "url": "https://www.fastmail.com/features/domains/"}, {"fetched_at": "2026-10-24T12:22:20.824148+08:00", "kind": "documentation", "sha256": "bd4b22a7489f36b968e2c4811e219700a0dad9f594d7279db3c1ad379e07a13c", "snapshot_path": "sources/bd4b22a7489f36b968e2c4811e219700a0dad9f594d7279db3c1ad379e07a13c.txt", "url": "https://www.fastmail.com/features/lightning-quick/"}], "summary": "Fastmail 托管的邮箱服务：用户登录后在自己的网页客户端（webmail）中处理邮件，服务端保存邮箱并提供全文搜索，无需配置第三方邮件服务器。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:freeconference-com','FreeConference.com','{"homepage": "https://www.freeconference.com", "id": "commercial:freeconference-com", "leaf_matches": [{"reason": "FreeConference.com 官方会议功能页说明其提供 15 个以上国际拨入号码、账户配套的拨入号码与访问码、预约邀请与最多 100 人，并明确列出 In-Call 与 Video Conference Moderator Controls；录音功能页说明电脑端可按 RECORD、电话端可按 *9 录制音视频。托管音频桥、可加入音频地址与组织者控制成立。", "slug": "conference-calling-application", "source_urls": ["https://www.freeconference.com/feature/free-conference-calls/", "https://www.freeconference.com/feature/conference-call-recording/", "https://www.freeconference.com/"]}], "name": "FreeConference.com", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T20:05:20.152929+08:00", "kind": "homepage", "sha256": "450deedd00933cef36bddc5ae12b8e1caa92372d3ae8d61aae5111055d146937", "snapshot_path": "sources/450deedd00933cef36bddc5ae12b8e1caa92372d3ae8d61aae5111055d146937.txt", "url": "https://www.freeconference.com/"}, {"fetched_at": "2026-10-24T11:07:28.728440+08:00", "kind": "documentation", "sha256": "f31ddc9634ed2d9ea679094ebe1cd30d825f3999efad57d38bcbfc4864c5a1bf", "snapshot_path": "sources/f31ddc9634ed2d9ea679094ebe1cd30d825f3999efad57d38bcbfc4864c5a1bf.txt", "url": "https://www.freeconference.com/feature/free-conference-calls/"}, {"fetched_at": "2026-10-24T11:07:28.828576+08:00", "kind": "documentation", "sha256": "22e978c91f7eacab06cb24701cafcf2ca90d7602dc7a470a1616f99a917a1751", "snapshot_path": "sources/22e978c91f7eacab06cb24701cafcf2ca90d7602dc7a470a1616f99a917a1751.txt", "url": "https://www.freeconference.com/feature/conference-call-recording/"}], "summary": "电话会议桥服务：主持人登录后发起或预约会议，参与者用拨入号码和访问码加入，支持最多 100 人、录音、邀请与主持人控制。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zello-work','Zello Work','{"homepage": "https://zello.com", "id": "commercial:zello-work", "leaf_matches": [{"reason": "Zello Work官方指南说明成员可在管理员配置的频道内按住PTT键进行实时语音通信，含一对一和一对多。", "slug": "push-to-talk-application", "source_urls": ["https://support.zello.com/zw/getting-started-guide-zello-work-ios", "https://support.zello.com/zw/using-the-ptt-button"]}], "name": "Zello Work", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:32:45.582132+08:00", "kind": "documentation", "sha256": "f03b2778529dee8431e0047ca62c289b185c7a3613fae80355988bb51a0e8f2b", "snapshot_path": "sources/f03b2778529dee8431e0047ca62c289b185c7a3613fae80355988bb51a0e8f2b.txt", "url": "https://support.zello.com/zw/getting-started-guide-zello-work-ios"}, {"fetched_at": "2026-10-23T19:32:47.457546+08:00", "kind": "documentation", "sha256": "ef7c875125a946ebd7b183940e1e267d0cffb49f178d8296a1f87341ba8508c3", "snapshot_path": "sources/ef7c875125a946ebd7b183940e1e267d0cffb49f178d8296a1f87341ba8508c3.txt", "url": "https://support.zello.com/zw/using-the-ptt-button"}], "summary": "面向团队的网络对讲服务，支持按成员和频道组织实时按键通话。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:15225670','Jitsi Meet','{"deployment": ["官方指南支持自行部署会议服务端"], "features": ["基于房间链接的实时多人音视频会议", "支持屏幕/内容共享、浏览器和移动端会议参与"], "github_repository_id": 15225670, "homepage": "https://jitsi.org/jitsi-meet/", "id": "github:15225670", "leaf_matches": [{"reason": "Jitsi Meet官方README与产品页说明多人会议室、音视频和内容共享，符合实时视频会议应用。", "slug": "video-conferencing-application", "source_urls": ["https://raw.githubusercontent.com/jitsi/jitsi-meet/master/README.md", "https://jitsi.org/jitsi-meet/"]}, {"reason": "Jitsi Meet 官方 README 与产品页说明会议在浏览器中创建，以 meet.jit.si 或自定义会议 URL 作为可寻址地址，参与者凭链接加入同一场会议；会议内提供 HD 音视频、桌面/内容共享与聊天。可召集且可寻址的会议、实时音视频会话、多人同时参与并共享同一内容舞台三项成立。", "slug": "virtual-meeting-platform", "source_urls": ["https://raw.githubusercontent.com/jitsi/jitsi-meet/master/README.md", "https://jitsi.org/jitsi-meet/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/jitsi/jitsi-meet/license", "name": "Jitsi Meet", "repository_url": "https://github.com/jitsi/jitsi-meet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:36:56.712288+08:00", "kind": "repository_metadata", "sha256": "4f50f96329dd2324f0ab3ab08ebecae03aab964b894f878008f234dce8ddd048", "snapshot_path": "sources/4f50f96329dd2324f0ab3ab08ebecae03aab964b894f878008f234dce8ddd048.txt", "url": "https://api.github.com/repos/jitsi/jitsi-meet"}, {"fetched_at": "2026-10-23T19:36:58.086562+08:00", "kind": "license", "sha256": "fe5ff1963f3e4915e1243cffee8413dd9ba2d944ef5c5718d0276cd84037ea36", "snapshot_path": "sources/fe5ff1963f3e4915e1243cffee8413dd9ba2d944ef5c5718d0276cd84037ea36.txt", "url": "https://api.github.com/repos/jitsi/jitsi-meet/license"}, {"fetched_at": "2026-10-23T19:36:59.692115+08:00", "kind": "readme", "sha256": "cd50b8ddb4e1fe4569dd36c8cd4f94da91e584a228ee7330d9498a2eccbe769f", "snapshot_path": "sources/cd50b8ddb4e1fe4569dd36c8cd4f94da91e584a228ee7330d9498a2eccbe769f.txt", "url": "https://raw.githubusercontent.com/jitsi/jitsi-meet/master/README.md"}, {"fetched_at": "2026-10-23T19:37:01.265383+08:00", "kind": "homepage", "sha256": "99779c470b486d14c4718c9b079b04d5ba6e023d267a70f382490e90b7ecbfa4", "snapshot_path": "sources/99779c470b486d14c4718c9b079b04d5ba6e023d267a70f382490e90b7ecbfa4.txt", "url": "https://jitsi.org/jitsi-meet/"}], "summary": "可自托管的多方视频会议：通过房间链接加入，支持实时音视频、内容共享、聊天与移动端参与。", "technology_stack": ["JavaScript", "React", "WebRTC", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zoom','Zoom','{"homepage": "https://zoom.com", "id": "commercial:zoom", "leaf_matches": [{"reason": "Zoom 官方 Webinars 产品页说明主持人/嘉宾向注册受众进行一对多广播，提供品牌注册页、投票、问答、录制和效果报告；受管理受众与角色非对称的广播结构成立。", "slug": "webinar-platform", "source_urls": ["https://www.zoom.com/en/products/webinars/"]}], "name": "Zoom", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T20:03:51.275085+08:00", "kind": "homepage", "sha256": "2e3678fcf0971f36930b6de87bfa62f628da06aa72ac5c643b5585afe0df64e9", "snapshot_path": "sources/2e3678fcf0971f36930b6de87bfa62f628da06aa72ac5c643b5585afe0df64e9.txt", "url": "https://www.zoom.com/en/products/webinars/"}], "summary": "Zoom Webinars 面向提前注册受众的一对多在线活动：主持人/嘉宾制作内容，参会者注册后以听众身份加入，支持问答、投票、录制与效果报告；本条目仅指 Webinars，不含 Zoom Events/虚拟活动。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
