INSERT INTO "application" VALUES('commercial:chatgpt','ChatGPT Search','{"homepage": "https://openai.com", "id": "commercial:chatgpt", "leaf_matches": [{"reason": "OpenAI官方帮助文档说明ChatGPT可搜索网页并综合生成直接回答，附相关来源链接与引用，符合答案引擎而非纯搜索结果列表。", "slug": "answer-engine", "source_urls": ["https://help-lb.openai.com/en/articles/9237897-searching-the-web-with-chatgpt"]}], "name": "ChatGPT Search", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:37:15.035863+08:00", "kind": "documentation", "sha256": "c96aaaafe0dfcccb7917e36802e46cebf52e253bede136e329a8657735aa6858", "snapshot_path": "sources/c96aaaafe0dfcccb7917e36802e46cebf52e253bede136e329a8657735aa6858.txt", "url": "https://help-lb.openai.com/en/articles/9237897-searching-the-web-with-chatgpt"}], "summary": "面向用户的AI答案服务，可检索网页并给出带来源引用的综合回答。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
