INSERT INTO "application" VALUES('github:9852918','Ghost','{"deployment": ["官方项目支持自托管部署；此条仅记录代码和公开部署资料，未运行。"], "features": ["帖子作为独立发布单元，拥有各自稳定的永久链接URL", "按发布时间倒序的帖子流，以及按标签/作者的帖子存档", "会员和付费订阅、电子邮件通讯发布"], "github_repository_id": 9852918, "homepage": "https://ghost.org", "id": "github:9852918", "leaf_matches": [{"reason": "Ghost官方开发者文档说明默认routes.yaml把主页设为按时间倒序的帖子列表，每篇帖子通过{slug}参数拥有自己的URL，并另有按标签和作者排序的帖子存档；Introduction将Ghost定位为出版平台，并说明Contributor可撰写帖子、Author/Editor可发布。作者出版物、帖子单元、日期流与每帖寻址四项均由正文覆盖，会员和通讯只是叠加能力。", "slug": "blogging-platform", "source_urls": ["https://docs.ghost.org/introduction", "https://docs.ghost.org/themes/routing"]}, {"reason": "官方 Members 文档说明成员经注册与邮箱确认后成为持久成员记录，记录包含邮箱、姓名、标签、订阅状态等属性，并支持从其他平台导入；成员可被赋予免费/付费/赠送状态和内容访问层级。官方 Newsletters 文档说明通讯可发送给全部免费/付费成员或其细分群体。对应受众记录、注册采集与导入统一、按标签/成员类型细分并通过通讯激活的循环；范围为出版物网站内的受众，不含广告主受众投放。", "slug": "media-audience-management", "source_urls": ["https://docs.ghost.org/members/", "https://docs.ghost.org/newsletters/", "https://api.github.com/repos/TryGhost/Ghost"]}, {"reason": "官方 Members 文档显示一人一成员记录、邮件同意、标签、免费/付费/赠送状态和 Stripe 付费订阅，覆盖受众记录到付费支持者的核心；作为发布平台内嵌的完整成员子模块匹配。", "slug": "creator-crm", "source_urls": ["https://docs.ghost.org/members", "https://raw.githubusercontent.com/TryGhost/Ghost/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/TryGhost/Ghost/license", "name": "Ghost", "repository_url": "https://github.com/TryGhost/Ghost", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:35.395+08:00", "kind": "repository_metadata", "sha256": "7fa01beda5d066312a85cf2df5a32c91cd95959a3c3af111b61cec0cf1525205", "snapshot_path": "sources/7fa01beda5d066312a85cf2df5a32c91cd95959a3c3af111b61cec0cf1525205.txt", "url": "https://api.github.com/repos/TryGhost/Ghost"}, {"fetched_at": "2026-10-23T19:24:48.141+08:00", "kind": "license", "sha256": "136a3704f0748edbb93f250dee1705f380633d0b11fb7fb845d87ac6430ba850", "snapshot_path": "sources/136a3704f0748edbb93f250dee1705f380633d0b11fb