INSERT INTO "application" VALUES('github:43441403','Strapi','{"deployment": ["README说明可自托管或使用官方云服务；本条开源范围只覆盖社区核心。"], "features": ["建立内容类型并管理结构化内容", "生成REST/GraphQL内容API", "管理草稿、发布和媒体"], "github_repository_id": 43441403, "homepage": "https://strapi.io", "id": "github:43441403", "leaf_matches": [{"reason": "官方README将Strapi定义为开源headless CMS，并直接描述内容建模与API；许可文件将ee目录排除，条目标注MIT社区开源核心。", "slug": "headless-cms", "source_urls": ["https://raw.githubusercontent.com/strapi/strapi/develop/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/strapi/strapi/develop/LICENSE", "license_review": {"rationale": "LICENSE明确ee/目录不在该开源许可范围；核对社区核心附带的完整MIT许可正文并限制本条目的许可范围。", "reviewer": "round-06-02 researcher", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/strapi/strapi/develop/LICENSE", "spdx_id": "MIT"}, "name": "Strapi", "repository_url": "https://github.com/strapi/strapi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:36.145+08:00", "kind": "repository_metadata", "sha256": "a4b55ecc84c7cc7af1ac2601ab49b0ffd3d5cc89d3bd64a7067faf6bf8bf7b0d", "snapshot_path": "sources/a4b55ecc84c7cc7af1ac2601ab49b0ffd3d5cc89d3bd64a7067faf6bf8bf7b0d.txt", "url": "https://api.github.com/repos/strapi/strapi"}, {"fetched_at": "2026-10-23T19:24:52.092+08:00", "kind": "license", "sha256": "70e3a1acbdb14a4b71bc11d980725cfa9a4f67df2d4e62f27c8e5c648bba04fa", "snapshot_path": "sources/70e3a1acbdb14a4b71bc11d980725cfa9a4f67df2d4e62f27c8e5c648bba04fa.txt", "url": "https://api.github.com/repos/strapi/strapi/license"}, {"fetched_at": "2026-10-23T19:27:49.774+08:00", "kind": "license", "sha256": "b651f49834c5726917e473ceab038d25e1115041374b615ff5d1688e7403d36d", "snapshot_path": "sources/b651f49834c5726917e473ceab038d25e1115041374b615ff5d1688e7403d36d.txt", "url": "https://raw.githubusercontent.com/strapi/strapi/develop/LICENSE"}, {"fetched_at": "2026-10-23T19:25:07.422+08:00", "kind": "readme", "sha256": "cbc029a16a9d8cb0df0857f8a59001d70792f432cf40c1c5c9c2fa6d653829ea", "snapshot_path": "sources/cbc029a16a9d8cb0df0857f8a59001d70792f432cf40c1c5c9c2fa6d653829ea.txt", "url": "https://raw.githubusercontent.com/strapi/strapi/develop/README.md"}], "summary": "可自托管的无头CMS社区核心，提供内容模型、管理后台及内容API。", "technology_stack": ["JavaScript/TypeScript应用"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:841835','Read the Docs','{"deployment": ["官方说明提供云托管服务；仓库为可自托管的产品实现。"], "features": ["连接Git仓库并自动构建文档", "托管公开文档并保留多个版本", "托管站点内置跨项目/跨版本搜索，提交变更触发重建"], "github_repository_id": 841835, "homepage": "https://readthedocs.com", "id": "github:841835", "leaf_matches": [{"reason": "官方README说明该平台从Git仓库拉取并自动构建、托管文档（push即重建），定位为面向开发者与团队的 Docs as Code 持续文档；docs-as-code 页说明同一产品完成 build/publish/host，支持多版本文档、PR预览与合并即部署，且 Community 版对开源项目免费托管公开文档；features 页说明版本可由 commit/branch/tag 构建、自带域名，构建/托管/认证/搜索一体，并列出所托管的语料可包含 Python 代码参考与 OpenAPI REST 参考；server-side-search 页说明托管站点提供跨项目跨版本全文检索并索引到标题级；documentation-structure 页说明阅读面按主题与任务组织为可复用导航层次（Diátaxis），该层次由接入的 Sphinx/MkDocs 工程及其配置定义。据此具备「团队维护的持久可寻址页面语料 + 结构化导航与检索的自助读者面 + 托管构建/版本/发布流水线」三项核心，与定义DC所列 library manuals 免费托管服务同型；不主张自研编辑器或多租户。", "slug": "developer-documentation-portal", "source_urls": ["https://raw.githubusercontent.com/readthedocs/readthedocs.org/main/README.rst", "https://about.readthedocs.com/docs-as-code/", "https://about.readthedocs.com/features/", "https://docs.readthedocs.com/platform/latest/server-side-search/index.html", "https://docs.readthedocs.com/platform/latest/explanation/documentation-structure.html"]}, {"reason": "官方README与docs-as-code页说明从Git仓库拉取、构建并托管多版本读者站点；Features页说明托管站点内置跨项目/跨版本integrated search，docs.readthedocs.com的Server side search与Flyout menu文档说明读者可对当前版本全库全文检索并从页面内搜索栏进入。生产侧为docs-as-code流水线，读者侧为版本化托管站点与检索；专题导航树由所接入的Sphinx/MkDocs文档工程定义，本条据此限定边界。", "slug": "product-documentation-portal", "source_urls": ["https://about.readthedocs.com/docs-as-code/", "https://about.readthedocs.com/features/", "https://docs.readthedocs.com/platform/latest/explanation/documentation-structure.html", "https://docs.readthedocs.com/platform/latest/flyout-menu.html", "https://docs.readthedocs.com/platform/latest/server-side-search/index.html", "https://raw.githubusercontent.com/readthedocs/readthedocs.org/main/README.rst"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/readthedocs/readthedocs.org/license", "name": "Read the Docs", "repository_url": "https://github.com/readthedocs/readthedocs.org", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:07:01.562948+08:00", "kind": "documentation", "sha256": "d158d0f80ec92fd1cf0fd78c1e993cf80c8a37140f83452f9e9cab787404b6bc", "snapshot_path": "sources/d158d0f80ec92fd1cf0fd78c1e993cf80c8a37140f83452f9e9cab787404b6bc.txt", "url": "https://about.readthedocs.com/docs-as-code/"}, {"fetched_at": "2026-10-23T19:26:54.273+08:00", "kind": "documentation", "sha256": "f57762112824db2109580b5c9a696d98dc631c0dca25055715538e5d1e32865b", "snapshot_path": "sources/f57762112824db2109580b5c9a696d98dc631c0dca25055715538e5d1e32865b.txt", "url": "https://about.readthedocs.com/docs-as-code/"}, {"fetched_at": "2026-10-24T12:37:49.223010+08:00", "kind": "documentation", "sha256": "170a9c5e0ec267f98468a4f6f9c5b69e9dc0efaa2962d8deee90f74b28e94bb6", "snapshot_path": "sources/170a9c5e0ec267f98468a4f6f9c5b69e9dc0efaa2962d8deee90f74b28e94bb6.txt", "url": "https://about.readthedocs.com/features/"}, {"fetched_at": "2026-10-28T23:07:19.628903+08:00", "kind": "documentation", "sha256": "ace18ed2bad7fa00ba4480b1c2a0361df0f0f2be81ae2d867d4e39e71c8e6a37", "snapshot_path": "sources/ace18ed2bad7fa00ba4480b1c2a0361df0f0f2be81ae2d867d4e39e71c8e6a37.txt", "url": "https://about.readthedocs.com/features/"}, {"fetched_at": "2026-10-23T19:24:32.858+08:00", "kind": "repository_metadata", "sha256": "3b3948d83f67dc0b5233ff460fabad9f149264165d82f95567dc8f4c3a54edf7", "snapshot_path": "sources/3b3948d83f67dc0b5233ff460fabad9f149264165d82f95567dc8f4c3a54edf7.txt", "url": "https://api.github.com/repos/readthedocs/readthedocs.org"}, {"fetched_at": "2026-10-28T23:05:57.493877+08:00", "kind": "repository_metadata", "sha256": "a3305dde5d91e02c676ccdd1326bb907508fd36b1963735ce4ca17ed6639e0d3", "snapshot_path": "sources/a3305dde5d91e02c676ccdd1326bb907508fd36b1963735ce4ca17ed6639e0d3.txt", "url": "https://api.github.com/repos/readthedocs/readthedocs.org"}, {"fetched_at": "2026-10-23T19:24:52.586+08:00", "kind": "license", "sha256": "e67135cee94609e98212139d1007e61e526602134d60cbb7636382ffed58aec5", "snapshot_path": "sources/e67135cee94609e98212139d1007e61e526602134d60cbb7636382ffed58aec5.txt", "url": "https://api.github.com/repos/readthedocs/readthedocs.org/license"}, {"fetched_at": "2026-10-28T23:07:20.094109+08:00", "kind": "documentation", "sha256": "5c15b81b0d6eb182b43252420598f11f8fd92305bcf023c8c2c2a2339fa30ec1", "snapshot_path": "sources/5c15b81b0d6eb182b43252420598f11f8fd92305bcf023c8c2c2a2339fa30ec1.txt", "url": "https://docs.readthedocs.com/platform/latest/explanation/documentation-structure.html"}, {"fetched_at": "2026-10-24T12:41:18.082405+08:00", "kind": "documentation", "sha256": "734077f030dea79513784398f99a65a8d277c119d69f186d3a9ada8427fca16d", "snapshot_path": "sources/734077f030dea79513784398f99a65a8d277c119d69f186d3a9ada8427fca16d.txt", "url": "https://docs.readthedocs.com/platform/latest/explanation/documentation-structure.html"}, {"fetched_at": "2026-10-24T12:39:47.094574+08:00", "kind": "documentation", "sha256": "b130c574b9b76fbe329cc6d71de64a774641f1c4f1902d51eab9b29ffb1c3cdd", "snapshot_path": "sources/b130c574b9b76fbe329cc6d71de64a774641f1c4f1902d51eab9b29ffb1c3cdd.txt", "url": "https://docs.readthedocs.com/platform/latest/flyout-menu.html"}, {"fetched_at": "2026-10-28T23:07:19.555441+08:00", "kind": "documentation", "sha256": "16ea86002978531b06646bcc501f436ba7aee5163dfaf97fb49d713d2dbd305f", "snapshot_path": "sources/16ea86002978531b06646bcc501f436ba7aee5163dfaf97fb49d713d2dbd305f.txt", "url": "https://docs.readthedocs.com/platform/latest/server-side-search/index.html"}, {"fetched_at": "2026-10-24T12:39:47.075899+08:00", "kind": "documentation", "sha256": "9c6427ab97da798fc61751436e31075caf275e7db17bb8ef4aa0b298785e0677", "snapshot_path": "sources/9c6427ab97da798fc61751436e31075caf275e7db17bb8ef4aa0b298785e0677.txt", "url": "https://docs.readthedocs.com/platform/latest/server-side-search/index.html"}, {"fetched_at": "2026-10-23T19:25:04.242+08:00", "kind": "readme", "sha256": "3273ad4ce2bdb56656bac4cb62f45f17ee6baace2b3ab3e02eef2d7d5dc370a7", "snapshot_path": "sources/3273ad4ce2bdb56656bac4cb62f45f17ee6baace2b3ab3e02eef2d7d5dc370a7.txt", "url": "https://raw.githubusercontent.com/readthedocs/readthedocs.org/main/README.rst"}], "summary": "托管文档构建与版本发布平台，可从Git仓库构建并发布开发者文档。", "technology_stack": ["Python Web应用，支持Sphinx/MkDocs文档构建"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:raindrop-io','Raindrop.io','{"homepage": "https://raindrop.io", "id": "commercial:raindrop-io", "leaf_matches": [{"reason": "官方帮助页Saving bookmarks正文说明可通过浏览器扩展、粘贴URL或移动端分享把网页保存（Save）到指定集合；官方产品博客正文说明公开策展页可由访客排序、进入嵌套集合并按标签过滤，所有共享集合显示在公开profile，且可嵌入网站/博客。产品首页快照仅Next.js空壳（标题与meta，无正文），故不以首页作为证据。", "slug": "content-curation-platform", "source_urls": ["https://blog.raindrop.io/new-public-page-and-embeds-fab7bcb56b4f/", "https://help.raindrop.io/bookmarks"]}], "name": "Raindrop.io", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:26:54.461+08:00", "kind": "homepage", "sha256": "13e5cab28c8fa2a7d86355710d3f61015e6812a62d4022ef03dd7ca1cbb69f91", "snapshot_path": "sources/13e5cab28c8fa2a7d86355710d3f61015e6812a62d4022ef03dd7ca1cbb69f91.txt", "url": "https://raindrop.io/"}, {"fetched_at": "2026-10-23T19:26:52.117+08:00", "kind": "documentation", "sha256": "e39a0e268c3eb8bee75c4c0105c9d5fe43bd6a8c7923bd42fc4e8a5fa699fe2d", "snapshot_path": "sources/e39a0e268c3eb8bee75c4c0105c9d5fe43bd6a8c7923bd42fc4e8a5fa699fe2d.txt", "url": "https://blog.raindrop.io/new-public-page-and-embeds-fab7bcb56b4f/"}, {"fetched_at": "2026-10-25T21:58:49.677945+08:00", "kind": "documentation", "sha256": "edef2090310327d9b6131549c9275ba9908d1715080afd9611ca66a5abe6f692", "snapshot_path": "sources/edef2090310327d9b6131549c9275ba9908d1715080afd9611ca66a5abe6f692.txt", "url": "https://help.raindrop.io/bookmarks"}], "summary": "在线书签与内容收集服务，可按集合整理网页资源并生成公开分享页。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:111364256','Miniflux','{"deployment": ["README提供官方自托管安装与容器部署方式；本次未运行。"], "features": ["订阅和阅读RSS、Atom及JSON Feed", "导入/导出OPML，并在后台定时抓取更新", "未读/已读状态、未读计数及标记全部已读"], "github_repository_id": 111364256, "homepage": "https://miniflux.app", "id": "github:111364256", "leaf_matches": [{"reason": "Miniflux官方API文档把条目status定义为read/unread/removed，支持按status=unread过滤，并提供feed、category、user三级mark-all-as-read接口以及read/unread counters；README说明RSS/Atom/JSON Feed、OPML和后台定时抓取，首页说明可快速浏览未读条目。用户自选订阅、自动接收与带未读/已读状态的消费面三项齐备。", "slug": "feed-reader", "source_urls": ["https://raw.githubusercontent.com/miniflux/v2/main/README.md", "https://miniflux.app/docs/api.html", "https://miniflux.app/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/miniflux/v2/license", "name": "Miniflux", "repository_url": "https://github.com/miniflux/v2", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:35.809+08:00", "kind": "repository_metadata", "sha256": "f0e27ef4e929bcd372a3a6bd37cfd4c060d86dcb2d84700f0e430d0bdaf86314", "snapshot_path": "sources/f0e27ef4e929bcd372a3a6bd37cfd4c060d86dcb2d84700f0e430d0bdaf86314.txt", "url": "https://api.github.com/repos/miniflux/v2"}, {"fetched_at": "2026-10-23T19:24:51.147+08:00", "kind": "license", "sha256": "38fc6f9fd51ff3e3f187a3e9c48fe20c0c345f98f5011088dc348e23d0c51a41", "snapshot_path": "sources/38fc6f9fd51ff3e3f187a3e9c48fe20c0c345f98f5011088dc348e23d0c51a41.txt", "url": "https://api.github.com/repos/miniflux/v2/license"}, {"fetched_at": "2026-10-23T19:25:02.576+08:00", "kind": "readme", "sha256": "2a18e492d96193f6bb1122bd493944e07987920a06005a48651c304e310a4a48", "snapshot_path": "sources/2a18e492d96193f6bb1122bd493944e07987920a06005a48651c304e310a4a48.txt", "url": "https://raw.githubusercontent.com/miniflux/v2/main/README.md"}, {"fetched_at": "2026-10-24T12:37:39.910136+08:00", "kind": "documentation", "sha256": "8cf55357c9a3a1d5bd5023092ae93885383b20012774bc5ab87e0d4c6d5e1219", "snapshot_path": "sources/8cf55357c9a3a1d5bd5023092ae93885383b20012774bc5ab87e0d4c6d5e1219.txt", "url": "https://miniflux.app/docs/api.html"}, {"fetched_at": "2026-10-24T12:43:26.750491+08:00", "kind": "homepage", "sha256": "470ce96d0c1e3f039532c6c48c3a09ee42261546db27cc1418267addb6c6186c", "snapshot_path": "sources/470ce96d0c1e3f039532c6c48c3a09ee42261546db27cc1418267addb6c6186c.txt", "url": "https://miniflux.app/"}], "summary": "自托管RSS/Atom/JSON Feed阅读器，提供订阅管理、条目阅读和同步。", "technology_stack": ["Go服务端应用，支持PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zotero','Zotero','{"homepage": "https://www.zotero.org", "id": "commercial:zotero", "leaf_matches": [{"reason": "官方文档说明在线文库可在浏览器访问同步的研究项目，PDF Reader文档描述打开论文、批注和笔记的阅读工作流；产品也包含桌面端。", "slug": "academic-paper-reader", "source_urls": ["https://www.zotero.org/", "https://www.zotero.org/support/kb/web_vs_desktop", "https://www.zotero.org/support/pdf_reader"]}], "name": "Zotero", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:27:52.131+08:00", "kind": "homepage", "sha256": "d064179b1c749d53237623450e2963a8600d478cc3d6ae53c6ba8a97a1a9854a", "snapshot_path": "sources/d064179b1c749d53237623450e2963a8600d478cc3d6ae53c6ba8a97a1a9854a.txt", "url": "https://www.zotero.org/"}, {"fetched_at": "2026-10-23T19:26:56.640+08:00", "kind": "documentation", "sha256": "0a016bf62379cf6fe0dc23618135eb28212ee9c4a74709f63dc12f9dbb9c7da1", "snapshot_path": "sources/0a016bf62379cf6fe0dc23618135eb28212ee9c4a74709f63dc12f9dbb9c7da1.txt", "url": "https://www.zotero.org/support/kb/web_vs_desktop"}, {"fetched_at": "2026-10-23T19:26:55.512+08:00", "kind": "documentation", "sha256": "5f6c1e3df0f90dfbca57a4092c974318c956841a0f74c7d834ee67e5805d8a71", "snapshot_path": "sources/5f6c1e3df0f90dfbca57a4092c974318c956841a0f74c7d834ee67e5805d8a71.txt", "url": "https://www.zotero.org/support/pdf_reader"}], "summary": "在线学术文献库和研究管理服务，可收集、组织并阅读论文及PDF。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:320936145','Kavita','{"deployment": ["README明确为自托管阅读服务器，官方项目提供安装方式；本次未部署。本条仅覆盖GPL-3.0社区核心，Kavita+为单独付费的互联网功能，不计入功能与部署范围。"], "features": ["建立并整理电子书/漫画阅读馆藏", "浏览器内阅读EPUB/PDF等格式", "以Collections、Reading Lists、Want to Read分组阅读材料", "富元数据筛选、搜索与智能过滤（社区核心）"], "github_repository_id": 320936145, "homepage": "https://kavitareader.com", "id": "github:320936145", "leaf_matches": [{"reason": "README明确Kavita是自托管阅读服务器，提供epub/pdf馆藏、Collections/Reading Lists/Want to Read分组、富元数据筛选与浏览器阅读入口；本条只覆盖GPL社区核心，Kavita+付费的元数据下载、评论、评分与推荐不计入。", "slug": "e-book-library-application", "source_urls": ["https://raw.githubusercontent.com/Kareadita/Kavita/develop/README.md"]}, {"reason": "Kavita官方EPUB阅读器文档直接说明其在页阅读位置的保存方式，可跨电脑与手机恢复到同一位置；README确认这是自托管阅读服务器。", "slug": "e-book-reader", "source_urls": ["https://raw.githubusercontent.com/Kareadita/Kavita/develop/README.md", "https://wiki.kavitareader.com/guides/readers/epub/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/Kareadita/Kavita/license", "name": "Kavita", "repository_url": "https://github.com/Kareadita/Kavita", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:33.477+08:00", "kind": "repository_metadata", "sha256": "7f8a6cf0bc6fc827dc395c8f758c242ab0a6ba00dce6b16cbc500f041846fdf9", "snapshot_path": "sources/7f8a6cf0bc6fc827dc395c8f758c242ab0a6ba00dce6b16cbc500f041846fdf9.txt", "url": "https://api.github.com/repos/Kareadita/Kavita"}, {"fetched_at": "2026-10-23T19:24:53.586+08:00", "kind": "license", "sha256": "5e0e258d60be5c96d41cc6352a876ae678a69cd2eaf6477c4264b5eda5edc377", "snapshot_path": "sources/5e0e258d60be5c96d41cc6352a876ae678a69cd2eaf6477c4264b5eda5edc377.txt", "url": "https://api.github.com/repos/Kareadita/Kavita/license"}, {"fetched_at": "2026-10-23T19:25:09.278+08:00", "kind": "readme", "sha256": "c418289222b8f01170d365262797101167f9ebc2b71041048603dc9cb1fa39e8", "snapshot_path": "sources/c418289222b8f01170d365262797101167f9ebc2b71041048603dc9cb