INSERT INTO "application" VALUES('github:9193949','wallabag','{"deployment": ["官方项目支持自托管；本次未部署。"], "features": ["保存网页文章供稍后阅读", "提取正文并提供便于阅读的视图", "未读→已读后归档的阅读队列，可另加收藏"], "github_repository_id": 9193949, "homepage": "https://wallabag.org", "id": "github:9193949", "leaf_matches": [{"reason": "官方用户文档说明标记已读会把文章从Unread移入Archive，收藏则进入Favorite；README和产品主页说明保存网页、抽取正文供稍后阅读。保存—持有内容—未读/归档队列—应用内阅读四项成立。", "slug": "read-it-later-application", "source_urls": ["https://raw.githubusercontent.com/wallabag/wallabag/master/README.md", "https://wallabag.org/", "https://doc.wallabag.org/user/articles/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/wallabag/wallabag/license", "name": "wallabag", "repository_url": "https://github.com/wallabag/wallabag", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:33.233+08:00", "kind": "repository_metadata", "sha256": "e34c14fba7abd6ac5e8b5bef5384ea64064e87b088ee75724fd076d5fd34bd41", "snapshot_path": "sources/e34c14fba7abd6ac5e8b5bef5384ea64064e87b088ee75724fd076d5fd34bd41.txt", "url": "https://api.github.com/repos/wallabag/wallabag"}, {"fetched_at": "2026-10-23T19:24:52.755+08:00", "kind": "license", "sha256": "568116dbe544543cdc7a4c7bf97fe323ebc9a2ba292900ce397972da2f571eb0", "snapshot_path": "sources/568116dbe544543cdc7a4c7bf97fe323ebc9a2ba292900ce397972da2f571eb0.txt", "url": "https://api.github.com/repos/wallabag/wallabag/license"}, {"fetched_at": "2026-10-23T19:25:06.244+08:00", "kind": "readme", "sha256": "0dd89f0f2c9e197ae8ef1b5d9f650b3f11384eb951c1d9be38c724ffdc4df4f8", "snapshot_path": "sources/0dd89f0f2c9e197ae8ef1b5d9f650b3f11384eb951c1d9be38c724ffdc4df4f8.txt", "url": "https://raw.githubusercontent.com/wallabag/wallabag/master/README.md"}, {"fetched_at": "2026-10-23T19:26:55.174+08:00", "kind": "homepage", "sha256": "825226c51dd2f4c5f22bbf1ed0ffb62a71ba8a1253c8acc94c4c0bcfd7f4101d", "snapshot_path": "sources/825226c51dd2f4c5f22bbf1ed0ffb62a71ba8a1253c8acc94c4c0bcfd7f4101d.txt", "url": "https://wallabag.org/"}, {"fetched_at": "2026-10-24T12:37:40.973118+08:00", "kind": "documentation", "sha256": "252b8c4fa8f37991ecb0e27d64dc2726bbf03a6be40d968f1529b945993e8889", "snapshot_path": "sources/252b8c4fa8f37991ecb0e27d64dc2726bbf03a6be40d968f1529b945993e8889.txt", "url": "https://doc.wallabag.org/user/articles/"}], "summary": "用于保存网页文章并稍后阅读的自托管应用。", "technology_stack": ["PHP Web应用"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:479657569','Linkwarden','{"deployment": ["官方文档说明Docker自托管部署；本次未运行。"], "features": ["保存并组织书签链接", "为链接创建集合并协作共享", "归档网页内容供日后访问"], "github_repository_id": 479657569, "homepage": "https://linkwarden.app", "id": "github:479657569", "leaf_matches": [{"reason": "官方README和产品页描述收藏、集合与链接归档；自托管安装文档证明这是可部署完整应用。", "slug": "bookmark-manager", "source_urls": ["https://raw.githubusercontent.com/linkwarden/linkwarden/main/README.md", "https://docs.linkwarden.app/self-hosting/setup", "https://linkwarden.app/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/linkwarden/linkwarden/license", "name": "Linkwarden", "repository_url": "https://github.com/linkwarden/linkwarden", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:34.027+08:00", "kind": "repository_metadata", "sha256": "be17b159cf2189006392ea1f3840fa05f4587ccdfacfe42aace74df5b0bdc4a9", "snapshot_path": "sources/be17b159cf2189006392ea1f3840fa05f4587ccdfacfe42aace74df5b0bdc4a9.txt", "url": "https://api.github.com/repos/linkwarden/linkwarden"}, {"fetched_at": "2026-10-23T19:24:51.386+08:00", "kind": "license", "sha256": "588b943e7b473318c922650ea1b10abb4a73ef7595311a26c35830636bf6251c", "snapshot_path": "sources/588b943e7b473318c922650ea1b10abb4a73ef7595311a26c35830636bf6251c.txt", "url": "https://api.github.com/repos/linkwarden/linkwarden/license"}, {"fetched_at": "2026-10-23T19:25:06.527+08:00", "kind": "readme", "sha256": "2813dd16022b0e23f9f2f19cbf216be22b201cb9a089cd3d38184dc7a62c7939", "snapshot_path": "sources/2813dd16022b0e23f9f2f19cbf216be22b201cb9a089cd3d38184dc7a62c7939.txt", "url": "https://raw.githubusercontent.com/linkwarden/linkwarden/main/README.md"}, {"fetched_at": "2026-10-23T19:26:56.443+08:00", "kind": "documentation", "sha256": "9a6333b4de99e0d20ba9083384c38dce9e1fa28fbb7713e5481283f05ff5513c", "snapshot_path": "sources/9a6333b4de99e0d20ba9083384c38dce9e1fa28fbb7713e5481283f05ff5513c.txt", "url": "https://docs.linkwarden.app/self-hosting/setup"}, {"fetched_at": "2026-10-23T19:27:50.439+08:00", "kind": "homepage", "sha256": "7e45de03aafa501d38502a07672fb1b774bbb6248e8218134596367e4989c66b", "snapshot_path": "sources/7e45de03aafa501d38502a07672fb1b774bbb6248e8218134596367e4989c66b.txt", "url": "https://linkwarden.app/"}], "summary": "可自托管的协作式网页书签管理器，保存、组织并归档链接。", "technology_stack": ["TypeScript Web应用，支持Docker部署"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1529160','Etherpad','{"deployment": ["官方项目支持自有服务器部署；本次未部署。"], "features": ["多人实时编辑同一文档", "保留作者归属及修订历史", "内置完整数据导出"], "github_repository_id": 1529160, "homepage": "https://etherpad.org", "id": "github:1529160", "leaf_matches": [{"reason": "官方README明确Etherpad是实时协作文档编辑器，并说明历史时间轴和多人作者标记。", "slug": "collaborative-document-editor", "source_urls": ["https://raw.githubusercontent.com/ether/etherpad/develop/README.md", "https://etherpad.org/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/ether/etherpad/license", "name": "Etherpad", "repository_url": "https://github.com/ether/etherpad", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:33.677+08:00", "kind": "repository_metadata", "sha256": "4a88b1b4516daf632f1651d7ad7a97d28a607dce34a42af438b0823c6ae18b31", "snapshot_path": "sources/4a88b1b4516daf632f1651d7ad7a97d28a607dce34a42af438b0823c6ae18b31.txt", "url": "https://api.github.com/repos/ether/etherpad"}, {"fetched_at": "2026-10-23T19:24:51.413+08:00", "kind": "license", "sha256": "85c1146e5f095232d17f9dd44ae772a795a31a624a710649b3f1f18940b54848", "snapshot_path": "sources/85c1146e5f095232d17f9dd44ae772a795a31a624a710649b3f1f18940b54848.txt", "url": "https://api.github.com/repos/ether/etherpad/license"}, {"fetched_at": "2026-10-23T19:25:07.397+08:00", "kind": "readme", "sha256": "561d9f3d0a97dc6f6ef77654170c4893d9744baad751d081606ef81bf899048f", "snapshot_path": "sources/561d9f3d0a97dc6f6ef77654170c4893d9744baad751d081606ef81bf899048f.txt", "url": "https://raw.githubusercontent.com/ether/etherpad/develop/README.md"}, {"fetched_at": "2026-10-23T19:27:52.072+08:00", "kind": "homepage", "sha256": "4a4d824d7ec41312207db5e4eb7cb61e0f0a774e6bdf0d2fcbb551a2f0d68a80", "snapshot_path": "sources/4a4d824d7ec41312207db5e4eb7cb61e0f0a774e6bdf0d2fcbb551a2f0d68a80.txt", "url": "https://etherpad.org/"}], "summary": "可部署的实时协作网页文档编辑器，支持多人同步编辑与修订历史。", "technology_stack": ["Node.js/TypeScript Web应用"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:186647301','ONLYOFFICE DocSpace Community','{"deployment": ["官方说明提供DocSpace Community Linux/Windows安装方式，以及Docker社区版；需要数据库、Redis/RabbitMQ等配套容器/服务。官方将单容器轻量Docker版明确限定为评估/测试用途；本条未运行或部署。"], "features": ["创建公共、协作、表单填写和虚拟数据室等房间并配置细粒度角色/权限", "邀请用户共同管理和协作处理文档", "在房间中创建、浏览、编辑文本文件、表格、演示文稿及PDF/表单，并进行实时协同编辑、评论与版本历史管理", "电子表格支持A1/R1C1单元格地址、公式引用与自动重算", "文档编辑器支持字体/字号/颜色与页面方向/尺寸/边距设置，可下载或打印（含Save to PDF）"], "github_repository_id": 186647301, "homepage": "https://onlyoffice.com/en/", "id": "github:186647301", "leaf_matches": [{"reason": "DocSpace社区版文档说明可在房间创建和编辑文本文档；ONLYOFFICE Docs官方帮助进一步给出Document Editor的字体/字号/颜色格式、页面方向/尺寸/边距设置，以及下载和打印（含Save to PDF、纸张方向/页范围）。持久文档、原位编辑、显式格式与页面化输出四项由正文覆盖；房间文档管理页还说明可管理版本、评论与共作者锁定。", "slug": "document-editor", "source_urls": ["https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md", "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/document_editor/FontTypeSizeColor.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/document_editor/SetPageParameters.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/document_editor/SavePrintDownload.aspx", "https://helpcenter.onlyoffice.com/docspace/administration/docspace-managing-documents.aspx"]}, {"reason": "官方帮助说明Spreadsheet Editor用A1/R1C1地址标识单元格（如第3行第2列显示为B3，位于公式栏左侧），公式参数可使用单元格/区域引用，计算默认自动执行，也可用Calculation或F9强制重算；DocSpace社区版文档确认可在房间创建和编辑spreadsheet。可寻址网格、公式引用与依赖重算三项均被正文覆盖。", "slug": "spreadsheet-application", "source_urls": ["https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md", "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/spreadsheet_editor/AdvancedSettings.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/spreadsheet_editor/InsertFunction.aspx"]}, {"reason": "DocSpace社区版文档列出用户邀请、房间内实时共同编辑、评论以及创建/编辑表格；ONLYOFFICE表格帮助说明默认Fast协作模式让共同编辑者实时看到彼此改动，并证明单元格地址、公式引用与自动重算的表格语法。共享工作簿、表格语法、多人访问与合并为同一当前版本四项齐备。", "slug": "collaborative-spreadsheet", "source_urls": ["https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md", "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/spreadsheet_editor/AdvancedSettings.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/spreadsheet_editor/InsertFunction.aspx"]}, {"reason": "社区版 README 说明协作房间邀请成员实时共同撰写并编辑文档；安装页列出创建/编辑演示文稿与实时共同编辑、评论；文档管理帮助说明在房间内新建演示文稿并管理版本与协作者。Presentation Editor 帮助进一步证明演示文稿是有序幻灯片序列（可新增、复制、移动排序、隐藏、按版式插入），且每张幻灯片是有界固定页面：SetSlideParameters 可统一设置标准/宽屏/纸张/自定义幻灯片尺寸与横向/纵向；InsertText 可在幻灯片任意位置拖出文本框，InsertAutoshapes 可在光标处放置并拖拽形状，InsertImages/InsertTables 可插入图片与表格，ManipulateObjects 可对文本/形状/图片/图表/表格调整大小、移动、旋转。共享房间提供持久单一在线版本与编辑/查看分级访问，四项核心均成立。", "slug": "collaborative-presentation-editor", "source_urls": ["https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md", "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx", "https://helpcenter.onlyoffice.com/docspace/administration/docspace-managing-documents.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/ManageSlides.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/PreviewPresentation.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SetSlideParameters.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertAutoshapes.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertImages.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/ManipulateObjects.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SlideMaster.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SavePrintDownload.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SupportedFormats.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertText.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertTables.aspx"]}, {"reason": "社区版安装页与文档管理帮助说明可在房间中新建演示文稿、编辑并保存为持久文件；Presentation Editor 帮助说明幻灯片可新增、复制、按版式插入、移动排序、隐藏，并可全屏放映、演讲者模式显示备注。SetSlideParameters 与 SlideMaster 证明主题可应用到全部幻灯片、Slide Master 可同时编辑所有幻灯片布局并添加占位符；SupportedFormats 的 Download as 表列出可下载为 PDF/PDF-A、ODP、PPTX/PPTM 等格式；SavePrintDownload 证明可自动保存、另存、下载和打印。演示文稿作为自包含文档保存在房间中，创作与交付核心成立。", "slug": "presentation-application", "source_urls": ["https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md", "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx", "https://helpcenter.onlyoffice.com/docspace/administration/docspace-managing-documents.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/ManageSlides.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/PreviewPresentation.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SetSlideParameters.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertAutoshapes.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertImages.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/ManipulateObjects.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SlideMaster.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SavePrintDownload.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/SupportedFormats.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertText.aspx", "https://helpcenter.onlyoffice.com/docs/userguides/presentation_editor/InsertTables.aspx"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/ONLYOFFICE/DocSpace/license", "name": "ONLYOFFICE DocSpace Community", "repository_url": "https://github.com/ONLYOFFICE/DocSpace", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:33:50.955+08:00", "kind": "repository_metadata", "sha256": "714ba934f8ba58b6eb46f96f5cbb76176db6800ab4f352dd2374f696d0031ab7", "snapshot_path": "sources/714ba934f8ba58b6eb46f96f5cbb76176db6800ab4f352dd2374f696d0031ab7.txt", "url": "https://api.github.com/repos/ONLYOFFICE/DocSpace"}, {"fetched_at": "2026-10-23T19:33:52.783+08:00", "kind": "license", "sha256": "2a51484552bc6c7b9f6c347c4c6c75e0443e04c176ad91f580d0d20e8eb96bbb", "snapshot_path": "sources/2a51484552bc6c7b9f6c347c4c6c75e0443e04c176ad91f580d0d20e8eb96bbb.txt", "url": "https://api.github.com/repos/ONLYOFFICE/DocSpace/license"}, {"fetched_at": "2026-10-23T19:33:54.220+08:00", "kind": "readme", "sha256": "0afdb4f66b28197ebb2aa5177efd1d77299430330ce9994f47fb100dda932187", "snapshot_path": "sources/0afdb4f66b28197ebb2aa5177efd1d77299430330ce9994f47fb100dda932187.txt", "url": "https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/README.md"}, {"fetched_at": "2026-10-23T19:33:55.618+08:00", "kind": "license", "sha256": "8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef", "snapshot_path": "sources/8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef.txt", "url": "https://raw.githubusercontent.com/ONLYOFFICE/DocSpace/master/LICENSE"}, {"fetched_at": "2026-10-23T19:34:22.023+08:00", "kind": "documentation", "sha256": "b85ae6809d877b164651448e1df89711e705dc860f4803cd2b05eb0966b76f93", "snapshot_path": "sources/b85ae6809d877b164651448e1df89711e705dc860f4803cd2b05eb0966b76f93.txt", "url": "https://helpcenter.onlyoffice.com/docspace/installation/docspace-community-install-windows.aspx"}, {"fetched_at": "2026-10-23T19:34:26.438+08:00", "kind": "documentation", "sha256": "e51d410314a8dc81737c929c43e7364dd5b851e893f12b43611d3a8d97dce4da", "snapshot_path": "sources/e51d410314a8dc81737c929c4