INSERT INTO "application" VALUES('github:266033395','Grist','{"deployment": ["README说明grist-core社区版可自行运行并托管表格服务器；本次未部署。"], "features": ["以关系型表格组织结构化记录", "支持计算列、表间关联和视图", "在服务端托管并共享表格文档"], "github_repository_id": 266033395, "homepage": "https://www.getgrist.com", "id": "github:266033395", "leaf_matches": [{"reason": "README直接称社区版为现代关系型电子表格，并说明可运行服务器托管表格，满足结构化记录/轻量数据库定义。", "slug": "structured-table-lightweight-database-application", "source_urls": ["https://raw.githubusercontent.com/gristlabs/grist-core/main/README.md", "https://www.getgrist.com/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/gristlabs/grist-core/license", "name": "Grist", "repository_url": "https://github.com/gristlabs/grist-core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:24:35.064+08:00", "kind": "repository_metadata", "sha256": "27188dedba6d491582b2d2e8e6a519851961b9015da7fa78cfa934eb53bfbf4b", "snapshot_path": "sources/27188dedba6d491582b2d2e8e6a519851961b9015da7fa78cfa934eb53bfbf4b.txt", "url": "https://api.github.com/repos/gristlabs/grist-core"}, {"fetched_at": "2026-10-23T19:24:51.846+08:00", "kind": "license", "sha256": "047c687dbe862e59eeee637583b18ab19e3827e1cc3072c3376ef1153994c40a", "snapshot_path": "sources/047c687dbe862e59eeee637583b18ab19e3827e1cc3072c3376ef1153994c40a.txt", "url": "https://api.github.com/repos/gristlabs/grist-core/license"}, {"fetched_at": "2026-10-23T19:25:05.733+08:00", "kind": "readme", "sha256": "c5fb7b1b385d179fc99bba809e6786d80c64dcd011aa625d29e633b07d0a810a", "snapshot_path": "sources/c5fb7b1b385d179fc99bba809e6786d80c64dcd011aa625d29e633b07d0a810a.txt", "url": "https://raw.githubusercontent.com/gristlabs/grist-core/main/README.md"}, {"fetched_at": "2026-10-23T19:27:51.764+08:00", "kind": "homepage", "sha256": "ac58d8634f883d5934a0423bcb0f7cc9582af8edab662455ea3bda527d09be81", "snapshot_path": "sources/ac58d8634f883d5934a0423bcb0f7cc9582af8edab662455ea3bda527d09be81.txt", "url": "https://www.getgrist.com/"}], "summary": "社区开源的关系型在线表格，结合电子表格界面与数据库结构化数据能力。", "technology_stack": ["TypeScript/Node.js服务端应用"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:miro','Miro','{"homepage": "https://miro.com/whiteboard/", "id": "commercial:miro", "leaf_matches": [{"reason": "官方白板页面正文说明无限画布是团队共享的视觉工作区，可同时放入便笺、绘图、图示与文件，并通过投票、计时器和实时反应共同编辑；模板库与公开板协作者访问说明板是可命名、可共享的持久工作单元。", "slug": "collaborative-canvas", "source_urls": ["https://miro.com/whiteboard/"]}, {"reason": "同一官方页面正文列出便笺与聚类、画笔自由绘制、形状/连接线、图片与文件，以及团队在同一板上实时协作和公开板邀请访问，匹配数字白板的直接标记+放置内容+多人共同标记。", "slug": "digital-whiteboard", "source_urls": ["https://miro.com/whiteboard/"]}], "name": "Miro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:30:33.563158+08:00", "kind": "homepage", "sha256": "c5885e21a32213f13c641cf9d3a8c577ca9d540f3b66045d80947f1bd1a2f398", "snapshot_path": "sources/c5885e21a32213f13c641cf9d3a8c577ca9d540f3b66045d80947f1bd1a2f398.txt", "url": "https://miro.com/whiteboard/"}], "summary": "Miro 提供团队共享的无限画布，用于在同一视觉板上进行头脑风暴、流程图、图示和其他协作活动。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16238673','Kanboard','{"deployment": ["自托管于自有服务器；官方文档提供安装、升级与 Docker 方式", "官方站点与 README 指向同一 MIT 仓库，未见单独的商业功能分层；README 说明项目处于维护模式"], "features": ["项目看板由有序列组成，可新增、重命名、删除列并拖放任务跨列", "列可设 WIP 任务上限，超过上限时列背景变红", "任务卡片含负责人、截止日期、标签与优先级等字段", "跨列移动在任务视图记录来源列、目标列、执行人与原列停留时间；自定义角色可按列限制创建、关闭与移动任务", "PHP 自托管应用，官方文档列有 SQLite/MySQL/PostgreSQL 与 Docker 安装方式"], "github_repository_id": 16238673, "homepage": "https://kanboard.org/", "id": "github:16238673", "leaf_matches": [{"reason": "官方首页、仓库元数据与 MIT 许可证可证 Kanboard 是免费开源、自托管的看板项目管理应用（README 说明处于维护模式，只做小修复）。看板是了解项目当前状态的直观方式，列可新增/重命名/删除，任务可跨列拖放，列可设 WIP 上限；Boards 文档说明 Board 视图按列排布任务、拖动任务跨列、列达到任务上限时背景变红。补充抓取的官方文档源 Markdown（kanboard/documentation content/en/v1/user/tasks.md、projects.md）正文明确：新建任务时选择 Column；Task Transitions 每次跨列移动记录 Date、Source column、Destination column、Executor、Time spent in origin column；Custom Project Roles 的 Column Restrictions 可限定“仅在指定列间移动任务”及按列创建/关闭任务。任务表单没有与列并行的阶段/状态字段，只有 open/closed 的关闭标记，因此列归属即状态、移动卡片即状态变更；日历/列表/甘特是同一任务集合的替代读取，不另存阶段状态。", "slug": "kanban-task-board", "source_urls": ["https://kanboard.org/", "https://docs.kanboard.org/v1/user/boards/", "https://docs.kanboard.org/v1/user/tasks/", "https://docs.kanboard.org/v1/user/projects/", "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/tasks.md", "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/projects.md", "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/boards.md", "https://raw.githubusercontent.com/kanboard/kanboard/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/kanboard/kanboard/license", "name": "Kanboard", "repository_url": "https://github.com/kanboard/kanboard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T22:34:38.935051+08:00", "kind": "repository_metadata", "sha256": "a40a620878a20fd922c273ded45ea3bef53639288a26cd9267ee5336fa8257b7", "snapshot_path": "sources/a40a620878a20fd922c273ded45ea3bef53639288a26cd9267ee5336fa8257b7.txt", "url": "https://api.github.com/repos/kanboard/kanboard"}, {"fetched_at": "2026-10-25T22:34:40.247896+08:00", "kind": "license", "sha256": "5f7b1da38ab9f403185030db8c590b53d3b200a5988c4845c751221a941a14b4", "snapshot_path": "sources/5f7b1da38ab9f403185030db8c590b53d3b200a5988c4845c751221a941a14b4.txt", "url": "https://api.github.com/repos/kanboard/kanboard/license"}, {"fetched_at": "2026-10-25T22:34:42.317736+08:00", "kind": "readme", "sha256": "2559998a4cf3104c3b628d4aa61e1c5ccafe2d7daf4866da2a05ed52ca5feb09", "snapshot_path": "sources/2559998a4cf3104c3b628d4aa61e1c5ccafe2d7daf4866da2a05ed52ca5feb09.txt", "url": "https://raw.githubusercontent.com/kanboard/kanboard/main/README.md"}, {"fetched_at": "2026-10-25T22:34:44.274335+08:00", "kind": "homepage", "sha256": "c80ac106a7627d094163a23d660e5b6a5cbb2dbb00ac853852b9c3618e5643a7", "snapshot_path": "sources/c80ac106a7627d094163a23d660e5b6a5cbb2dbb00ac853852b9c3618e5643a7.txt", "url": "https://kanboard.org/"}, {"fetched_at": "2026-10-25T22:34:46.233973+08:00", "kind": "documentation", "sha256": "776121f9c403e65aad4b79d469a5135b69ed8520b4d2bbfa7057c613ae3491a6", "snapshot_path": "sources/776121f9c403e65aad4b79d469a5135b69ed8520b4d2bbfa7057c613ae3491a6.txt", "url": "https://docs.kanboard.org/v1/user/boards/"}, {"fetched_at": "2026-10-25T22:34:47.642746+08:00", "kind": "documentation", "sha256": "2de47162ecf799db039fb4c70557253ef6b6caf4fabb1169a92aad3ff352786c", "snapshot_path": "sources/2de47162ecf799db039fb4c70557253ef6b6caf4fabb1169a92aad3ff352786c.txt", "url": "https://docs.kanboard.org/v1/user/tasks/"}, {"fetched_at": "2026-10-25T22:34:49.269574+08:00", "kind": "documentation", "sha256": "b7fc41a5737715c21d54d5d93caf1b6de17bc8fbddb2a38c62e726471826f1fb", "snapshot_path": "sources/b7fc41a5737715c21d54d5d93caf1b6de17bc8fbddb2a38c62e726471826f1fb.txt", "url": "https://docs.kanboard.org/v1/user/projects/"}, {"fetched_at": "2026-10-25T22:44:35.861013+08:00", "kind": "documentation", "sha256": "281c39c6e4c5a9c071d28bf01d08d2544929942977eeff4ae53ce0716510f081", "snapshot_path": "sources/281c39c6e4c5a9c071d28bf01d08d2544929942977eeff4ae53ce0716510f081.txt", "url": "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/tasks.md"}, {"fetched_at": "2026-10-25T22:44:37.453221+08:00", "kind": "documentation", "sha256": "c64e462a0bc63500eb50df6e0604371bb89a44f4e83dd9b40cbba7e82cdfd86f", "snapshot_path": "sources/c64e462a0bc63500eb50df6e0604371bb89a44f4e83dd9b40cbba7e82cdfd86f.txt", "url": "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/projects.md"}, {"fetched_at": "2026-10-25T22:44:38.794347+08:00", "kind": "documentation", "sha256": "eef29ab71f8b751cd1561b33dcaf7ef68dff62ffe81f767dcc7e7bc0e7d15e61", "snapshot_path": "sources/eef29ab71f8b751cd1561b33dcaf7ef68dff62ffe81f767dcc7e7bc0e7d15e61.txt", "url": "https://raw.githubusercontent.com/kanboard/documentation/main/content/en/v1/user/boards.md"}], "summary": "MIT 许可的自托管看板项目管理应用（维护模式）：任务以可配置列组织，跨列拖动即改变阶段，支持 WIP 限制与列级角色限制。", "technology_stack": ["PHP", "SQLite / MySQL / PostgreSQL", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:68362560','Nextcloud Calendar','{"deployment": ["通过 Nextcloud 应用商店或 nextcloud-releases 发布包安装到 Nextcloud 服务器", "本仓库为 Calendar 前端；事件数据由 Nextcloud 服务器的 CalDAV 后端保存"], "features": ["在日/周/月网格上创建、编辑、移动、删除事件并邀请参与者", "重复事件、提醒、Free/Busy 查询与多设备同步", "按本地用户、组或远端联邦用户共享日历，区分只读与读写", "Meeting Proposals：多个候选时间由参与者以 Yes/No/Maybe 回应并汇总", "Appointments：按可用时间生成预约页，外部人员可自行预约并写入日历"], "github_repository_id": 68362560, "homepage": "https://nextcloud.com", "id": "github:68362560", "leaf_matches": [{"reason": "官方 Calendar 用户手册正文说明日历保存在服务器，用户在日/周/月网格上创建事件（含起止与时区）、邀请参与者、设置重复与提醒、共享日历并在多设备同步；README 说明该应用为 Nextcloud Calendar 前端，经应用商店安装。持久日程与可导航时间网格两项核心均成立。", "slug": "calendar-application", "source_urls": ["https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html", "https://raw.githubusercontent.com/nextcloud/calendar/master/README.md"]}, {"reason": "用户手册正文说明日历可共享给本地用户、组或联邦服务器上的远端用户，共享时可设写权限或只读：写权限用户可新建、编辑和删除事件，只读用户不可；创建者可通过共享菜单调整或取消共享，公开链接为只读。同一事件存储由全组读取，构成共享团队日历核心。", "slug": "shared-team-calendar", "source_urls": ["https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html", "https://raw.githubusercontent.com/nextcloud/calendar/master/README.md"]}, {"reason": "用户手册 Proposals 正文说明组织者为一次会议创建提案，填写标题、地点、时长、参与者并选择多个候选时段；系统通知参与者，参与者在时间×参与者矩阵中对每个时段选择 Yes/No/Maybe 并提交；组织者查看各时段票数与回应进度，选定最受欢迎的时段。时间由参与者声明聚合而来，且提案结束后进入会议，符合本叶核心。", "slug": "group-availability-scheduling-application", "source_urls": ["https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html", "https://raw.githubusercontent.com/nextcloud/calendar/master/README.md"]}, {"reason": "用户手册 Appointments 正文说明主办人配置预约类型（标题、地点、描述、时长、时段增量、每周可用时间、缓冲与每日上限），生成公开或秘密链接；预约页向访客展示可选时段，访客填写姓名和邮箱即可预约，成功预约写入主办人指定日历，并可创建 Talk 房间。主办人可用时间定义候选时段、访客自助预约并形成会议记录，四项核心成立。", "slug": "meeting-scheduling-application", "source_urls": ["https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html", "https://raw.githubusercontent.com/nextcloud/calendar/master/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/nextcloud/calendar/license", "name": "Nextcloud Calendar", "repository_url": "https://github.com/nextcloud/calendar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:24:57.906436+08:00", "kind": "repository_metadata", "sha256": "dcbc1fc28e7df927265c7ce1d49089da831de6bcb94885eeecf362999200db89", "snapshot_path": "sources/dcbc1fc28e7df927265c7ce1d49089da831de6bcb94885eeecf362999200db89.txt", "url": "https://api.github.com/repos/nextcloud/calendar"}, {"fetched_at": "2026-10-24T12:24:58.328947+08:00", "kind": "license", "sha256": "fb4568641d9a2be7a600dc83150c31f58c6e6257accce08af0c4d265d2fd7e7e", "snapshot_path": "sources/fb4568641d9a2be7a600dc83150c31f58c6e6257accce08af0c4d265d2fd7e7e.txt", "url": "https://api.github.com/repos/nextcloud/calendar/license"}, {"fetched_at": "2026-10-24T12:25:04.554390+08:00", "kind": "readme", "sha256": "8331a380fb1b94ca9e577aac0623020e6e611cb17f808970a03cf9d0042edcd7", "snapshot_path": "sources/8331a380fb1b94ca9e577aac0623020e6e611cb17f808970a03cf9d0042edcd7.txt", "url": "https://raw.githubusercontent.com/nextcloud/calendar/master/README.md"}, {"fetched_at": "2026-10-23T19:35:37.416162+08:00", "kind": "documentation", "sha256": "a917326d30b0cd0e0e42ec713d974899f7867e7029227588de6b54a3f41c67ea", "snapshot_path": "sources/a917326d30b0cd0e0e42ec713d974899f7867e7029227588de6b54a3f41c67ea.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html"}], "summary": "Nextcloud 官方开源日历应用（AGPL-3.0）：在服务器日程上创建、邀请、重复、提醒、共享日历，并提供会议时间提案与预约页。", "technology_stack": ["PHP/Composer", "JavaScript/Vue", "Vitest/Playwright", "Nextcloud 应用框架与 CalDAV 后端"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:371047037','Nextcloud Calendar Resource Management','{"deployment": ["作为 Nextcloud 应用从应用商店安装，与 Calendar 应用配合使用", "资源由管理员用 php occ 命令配置；依赖 Nextcloud 后台任务同步到 CalDAV"], "features": ["以 OCC 命令创建楼宇、楼层、会议室、通用资源和车辆", "为资源配置容量、无障碍、联系方式、房间号与设备等属性", "按组限制资源可用范围", "用户查看时段内房间可用性并在预约事件时选择地点"], "github_repository_id": 371047037, "homepage": "https://nextcloud.com", "id": "github:371047037", "leaf_matches": [{"reason": "README 正文说明这是 Nextcloud Calendar 的共享资源后端：管理员配置楼宇、楼层、会议室、通用资源与车辆（含容量、无障碍、联系方式、分组限制），用户可查看所选时段的房间可用性并在预订事件时选择地点。管理员日历文档说明 CalDAV 后端支持资源与房间、系统保证同一资源同一时间只被占用一次，且资源必须由后端应用提供（Nextcloud 本身不管理资源，需管理员安装本应用）。用户手册说明把房间/资源加入事件、冲突时显示拒绝，以及 Room availability 面板。资源自身日程、预订条目与作为可用性记录被查询三项成立。", "slug": "resource-calendar", "source_urls": ["https://raw.githubusercontent.com/nextcloud/calendar_resource_management/main/README.md", "https://docs.nextcloud.com/server/stable/admin_manual/groupware/calendar.html", "https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/nextcloud/calendar_resource_management/license", "name": "Nextcloud Calendar Resource Management", "repository_url": "https://github.com/nextcloud/calendar_resource_management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:29:27.592431+08:00", "kind": "repository_metadata", "sha256": "d97c6f4cc61039c92e925f858cc75ee3a51eba1e21a7fd825c19b7d8f4939e77", "snapshot_path": "sources/d97c6f4cc61039c92e925f858cc75ee3a51eba1e21a7fd825c19b7d8f4939e77.txt", "url": "https://api.github.com/repos/nextcloud/calendar_resource_management"}, {"fetched_at": "2026-10-24T12:29:26.587378+08:00", "kind": "license", "sha256": "ef78f995d25dd9e306de093c1d492917b97a91b5e779666d6a2796cca283f0ef", "snapshot_path": "sources/ef78f995d25dd9e306de093c1d492917b97a91b5e779666d6a2796cca283f0ef.txt", "url": "https://api.github.com/repos/nextcloud/calendar_resource_management/license"}, {"fetched_at": "2026-10-24T12:29:33.656802+08:00", "kind": "readme", "sha256": "bfe86b65716994af27e302af4189871732b54684ec7052f35b85350729b04484", "snapshot_path": "sources/bfe86b65716994af27e302af4189871732b54684ec7052f35b85350729b04484.txt", "url": "https://raw.githubusercontent.com/nextcloud/calendar_resource_management/main/README.md"}, {"fetched_at": "2026-10-23T19:35:36.223586+08:00", "kind": "documentation", "sha256": "d4fe11e8109f72182cccc22b33d35dbdd80f1868011d5b9f3988e9b87b4e4afd", "snapshot_path": "sources/d4fe11e8109f72182cccc22b33d35dbdd80f1868011d5b9f3988e9b87b4e4afd.txt", "url": "https://docs.nextcloud.com/server/stable/admin_manual/groupware/calendar.html"}, {"fetched_at": "2026-10-23T19:35:37.416162+08:00", "kind": "documentation", "sha256": "a917326d30b0cd0e0e42ec713d974899f7867e7029227588de6b54a3f41c67ea", "snapshot_path": "sources/a917326d30b0cd0e0e42ec713d974899f7867e7029227588de6b54a3f41c67ea.txt", "url": "https://docs.nextcloud.com/server/latest/user_manual/en/groupware/calendar.html"}], "summary": "Nextcloud 官方开源资源后端应用（AGPL-3.0），为 Calendar 提供楼宇、楼层、会议室、通用资源与车辆的配置、分组限制和可用性查询。", "technology_stack": ["PHP", "Nextcloud 应用框架", "CalDAV 资源后端", "OCC CLI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fireflies','Fireflies.ai','{"homepage": "https://fireflies.ai/", "id": "commercial:fireflies", "leaf_matches": [{"reason": "Fireflies 官方帮助正文说明 AI assistant 捕获、转录、总结并搜索线上/线下会议，可上传历史录音；摘要正文说明摘要含 Action Items 等小节并与相关发言人关联，可定制或重新生成。 本条与 meeting-recording-transcription-application 属同一产品的双重类型（AI 理解层叠加在录制/转录/持久库之上），不是两个独立案例。", "slug": "ai-meeting-assistant", "source_urls": ["https://guide.fireflies.ai/articles/1193528158-what-is-fireflies-ai", "https://guide.fireflies.ai/articles/9547055509-Fireflies-AI-Meeting-Summaries%3A-View%2C-Customise%2C-Expand%2C-Regenerate"]}, {"reason": "官方正文描述会议机器人、浏览器扩展、桌面/移动应用录制与音视频上传、自动转录，并将录音、转录与摘要保存在可按会议检索的 Notepad 中。", "slug": "meeting-recording-transcription-application", "source_urls": ["https://guide.fireflies.ai/articles/1193528158-what-is-fireflies-ai", "https://guide.fireflies.ai/articles/6653885315-learn-about-the-fireflies-notepad"]}], "name": "Fireflies.ai", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:34:41.748059+08:00", "kind": "documentation", "sha256": "c3264c6d14964d7311d3a39d3d3486e7de897eb742391c99a06de08d99bccc54", "snapshot_path": "sources/c3264c6d14964d7311d3a39d3d3486e7de897eb742391c99a06de08d99bccc54.txt", "url": "https://guide.fireflies.ai/articles/1193528158-what-is-fireflies-ai"}, {"fetched_at": "2026-10-24T11:41:27.157556+08:00", "kind": "documentation", "sha256": "7c934d763bf433ee5d1d93b1b71ad5cdf5c05ad948b77d1c03d6eaa7d549ed39", "snapshot_path": "sources/7c934d763bf433ee5d1d93b1b71ad5cdf5c05ad948b77d1c03d6eaa7d549ed39.txt", "url": "https://guide.fireflies.ai/articles/1574234155-leran-about-the-tasks-feed"}, {"fetched_at": "2026-10-24T11:43:29.706233+08:00", "kind": "documentation", "sha256": "dc722f9bb01db064003017c4974ac97e08b4d4cdd0c47ff79740f304f52414ef", "snapshot_path": "sources/dc722f9bb01db064003017c4974ac97e08b4d4cdd0c47ff79740f304f52414ef.txt", "url": "https://guide.fireflies.ai/articles/6653885315-learn-about-the-fireflies-notepad"}, {"fetched_at": "2026-10-24T11:46:16.333773+08:00", "kind": "documentation", "sha256": "5261fe0e832a5fcb54795acb3f149dd0881fb3461672ba510f1a13f27100b0ac", "snapshot_path": "sources/5261fe0e832a5fcb54795acb3f149dd0881fb3461672ba510f1a13f27100b0ac.txt", "url": "https://guide.fireflies.ai/articles/9547055509-Fireflies-AI-Meeting-Summaries%3A-View%2C-Customise%2C-Expand%2C-Regenerate"}, {"fetched_at": "2026-10-24T13:00:43.539726+08:00", "kind": "documentation", "sha256": "818c1569545204cc18d0743ea55fc2ff29f59d6db6e00f32207561a739c85f47", "snapshot_path": "sources/818c1569545204cc18d0743ea55fc2ff29f59d6db6e00f32207561a739c85f47.txt", "url": "https://guide.fireflies.ai/articles/8198957772-learn-about-setting-up-fireflies-before-a-meeting"}], "summary": "Fireflies.ai 转录、总结、记录和搜索会议，并把会议行动项作为可指派负责人、可勾选完成的任务集中跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:slido','Slido','{"homepage": "https://slido.com/", "id": "commercial:slido", "leaf_matches": [{"reason": "Slido 官方帮助正文给出创建与运行流程：选择 Multiple choice，输入问题与答案选项，Start 后向参与者运行投票；Present mode 实时展示结果，默认按得票排序并以百分比显示。官方产品页正文另列 multiple choice、word cloud、quiz、rating、open text、ranking、survey 等类型，说明参与者可用链接或二维码从任意设备投票、结果实时显示，并可在会后导出到 Excel/PDF/Google Sheets。问题+预定义选项、低摩擦分发投票、计算聚合结果三项由正文成立。 Slido 同时具备 Audience Response System 的现场互动特征（Present mode、主持驱动的会议/活动场景），本条按 polling 的问题+预置选项→投票→聚合结果核心记录。", "slug": "polling-application", "source_urls": ["https://community.slido.com/interactive-poll-types-210/create-and-run-a-multiple-choice-poll-854", "https://www.slido.com/features-live-polling"]}], "name": "Slido", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T22:47:45.578775+08:00", "kind": "documentation", "sha256": "4f9b4b8d35021ce9474b5544e199403df28947d7663fdc791f95b0387b459d1a", "snapshot_path": "sources/4f9b4b8d35021ce9474b5544e199403df28947d7663fdc791f95b0387b459d1a.txt", "url": "https://community.slido.com/interactive-poll-types-210/create-and-run-a-multiple-choice-poll-854"}, {"fetched_at": "2026-10-23T19:36:20.439747+08:00", "kind": "homepage", "sha256": "3e37556b1e8bd3e478834327455534ebd6c36deb2a73ca2172b106d3ac378c24", "snapshot_path": "sources/3e37556b1e8bd3e478834327455534ebd6c36deb2a73ca2172b106d3ac378c24.txt", "url": "https://www.slido.com/features-live-polling"}], "summary": "用于会议和活动的在线投票、问答与实时反馈产品；官方帮助正文说明可创建带问题与预置选项的投票并实时展示百分比结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:workadventure','WorkAdventure','{"homepage": "https://workadventu.re/", "id": "commercial:workadventure", "leaf_matches": [{"reason": "官方产品页与 virtual meetings 页正文说明团队在带会议 room、desk 和多功能空间的 2D 数字办公室中以 avatar 持续在场；走近某人即触发私有视频对话气泡，进入会议 room 即加入会议，另有咖啡/休闲空间。本条只按有官方正文证据的托管产品页记录为商业服务，不把未存档的开源仓库元数据或未识别许可证当作 OSS 证据。", "slug": "virtual-office-workspace", "source_urls": ["https://workadventu.re/", "https://workadventu.re/virtual-offices/virtual-meetings/"]}], "name": "WorkAdventure", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:38:24.272004+08:00", "kind": "homepage", "sha256": "9eab6871b079c187d4f4062121835c46b4591dc306be698dbd8b5721f6505c53", "snapshot_path": "sources/9eab6871b079c187d4f4062121835c46b4591dc306be698dbd8b5721f6505c53.txt", "url": "https://workadventu.re/"}, {"fetched_at": "2026-10-24T12:43:11.822355+08:00", "kind": "documentation", "sha256": "af514c3333aa70c8a9aaa45989c85b576815b217a92062fd926cbd39b664a35d", "snapshot_path": "sources/af514c3333aa70c8a9aaa45989c85b576815b217a92062fd926cbd39b664a35d.txt", "url": "https://workadventu.re/virtual-offices/virtual-meetings/"}], "summary": "托管虚拟办公室服务，为远程团队提供可配置的数字空间、接近即发起的虚拟会面及在线活动体验。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:life-goals-app','Life Goals App','{"homepage": "https://goalsandprogress.com/", "id": "commercial:life-goals-app", "leaf_matches": [{"reason": "官方帮助页正文说明应用引导用户选价值观、给 10 个生活领域打分并确定重点，为每个重点写带 3/5/10 年日期的 Summit Goal；再拆为不超过三个年度目标，每个目标设 3–5 个可衡量、带日期的指标，并每季度设约三个里程碑与 On track/At risk/Off track 回顾；习惯网格按日记录，季度与年度有复盘页。目标→较小跟踪单元→进度记录与周期回顾的核心成立。应用数据只保存在浏览器、不上传服务器，但本叶定义明示纸面工作表和离线方式同样满足，故不以云服务形态否决。", "slug": "life-planning-application", "source_urls": ["https://goalsandprogress.com/lifegoalsapp/docs/help.html", "https://goalsandprogress.com/"]}], "name": "Life Goals App", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:25:58.963954+08:00", "kind": "documentation", "sha256": "9d70fa57172eb4a5bd0441b8f64531b78797365d48bb8ba20eb18a9e4605f83b", "snapshot_path": "sources/9d70fa57172eb4a5bd0441b8f64531b78797365d48bb8ba20eb18a9e4605f83b.txt", "url": "https://goalsandprogress.com/lifegoalsapp/docs/help.html"}, {"fetched_at": "2026-10-24T12:35:19.064343+08:00", "kind": "homepage", "sha256": "326acb882f1ce5dbfca7f3febe1b5b20d52c7999830fc646ae3ec4dcad3dbf26", "snapshot_path": "sources/326acb882f1ce5dbfca7f3febe1b5b20d52c7999830fc646ae3ec4dcad3dbf26.txt", "url": "https://goalsandprogress.com/"}], "summary": "Goals and Progress 推出的浏览器端个人生活规划应用：从价值观与生活领域评分出发，建立带日期的长期目标，向下拆到年度目标、指标与季度里程碑，并以习惯网格与周期复盘跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1190598050','Yuvomi','{"deployment": ["Docker 或 Podman 容器部署", "提供浏览器引导安装，也支持 NAS 应用商店", "单文件 SQLite 数据库，可整体复制备份"], "features": ["任务（看板、截止日期、子任务、重复事项）", "日历同步与单事件可见性", "笔记、联系人、生日、健康记录", "预算、账目、共享支出与债务简化", "模块共用同一 SQLite 数据库并互相引用"], "github_repository_id": 1190598050, "homepage": "https://yuvomi.cloud", "id": "github:1190598050", "leaf_matches": [{"reason": "README 说明这是“一个家替代多个订阅”的自托管个人/家庭规划器，任务、日历、笔记、联系人、预算等模块存放在同一 SQLite 文件中，并有专门章节“模块互相通信”，举例说明餐食计划生成购物清单、收据挂到账目、勾选家务发放积分，证明单一数据库与跨领域关联。仓库元数据与 MIT 许可证接口证实身份与许可。", "slug": "personal-organizer", "source_urls": ["https://github.com/ulsklyc/yuvomi", "https://raw.githubusercontent.com/ulsklyc/yuvomi/main/README.md", "https://api.github.com/repos/ulsklyc/yuvomi/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/ulsklyc/yuvomi/license", "name": "Yuvomi", "repository_url": "https://github.com/ulsklyc/yuvomi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:01:11.797247+08:00", "kind": "repository_metadata", "sha256": "18bb121784e063593ef48e61f4d412cc27c9bb44b3cbd9834fd5d50114abfb31", "snapshot_path": "sources/18bb121784e063593ef48e61f4d412cc27c9bb44b3cbd9834fd5d50114abfb31.txt", "url": "https://github.com/ulsklyc/yuvomi"}, {"fetched_at": "2026-10-24T12:01:13.077284+08:00", "kind": "readme", "sha256": "c703d92bd3f0564d809595a28e97252c79139fa100fe31b26f551c5467c21daf", "snapshot_path": "sources/c703d92bd3f0564d809595a28e97252c79139fa100fe31b26f551c5467c21daf.txt", "url": "https://raw.githubusercontent.com/ulsklyc/yuvomi/main/README.md"}, {"fetched_at": "2026-10-24T12:01:58.951532+08:00", "kind": "license", "sha256": "0897afb72c5acda6e7b342894b431886140681fa9badcdceb544e7e99769b376", "snapshot_path": "sources/0897afb72c5acda6e7b342894b431886140681fa9badcdceb544e7e99769b376.txt", "url": "https://api.github.com/repos/ulsklyc/yuvomi/license"}], "summary": "Yuvomi 是自托管家庭/个人事务管理器：任务、日历、笔记、联系人、预算、餐食等模块共用一个 SQLite 数据库，模块间通过记录属性互相引用。", "technology_stack": ["Node.js", "SQLite", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:78243781','Super Productivity','{"deployment": ["Web 应用直接使用", "提供桌面与移动客户端下载", "可选用自托管 SuperSync 或 WebDAV/Dropbox 同步"], "features": ["任务、子任务、项目与标签管理", "planner 与 schedule 时间轴上的时间盒安排", "任务完成、时间追踪与工时表导出", "番茄钟/Flowtime 专注会话与休息提醒", "从 Jira、GitHub、GitLab、日历等导入任务"], "github_repository_id": 78243781, "homepage": "https://super-productivity.com", "id": "github:78243781", "leaf_matches": [{"reason": "README 首句即“带时间盒与时间追踪的高级待办应用”，功能列表说明可在 schedule 时间轴上把一天铺开、与日历事件并列，并用 timeboxing 规划任务、跟踪时间并生成工时表。官方 Schedule Planner 页正文逐句写明：先“Set time estimates so the planner knows how much space each task needs in your day”，再“Drag tasks into the daily timeline”；执行阶段“If something takes longer, drag to reschedule the rest”；FAQ 还写明“Unfinished tasks carry forward automatically”，且“Every scheduled block is a real task with notes, subtasks, and logged time”。官方 Time Boxing 指南亦给出“Assign a time estimate to each task”“Slot these tasks into your calendar like Tetris blocks”“Drag & Drop Planning”与“Easily move tasks into time slots.”。任务→时间块分配、重新安排与未完成结转循环均有官方正文，仓库与 MIT 许可经元数据和许可证接口核实。", "slug": "time-blocking-application", "source_urls": ["https://api.github.com/repos/super-productivity/super-productivity", "https://raw.githubusercontent.com/super-productivity/super-productivity/master/README.md", "https://api.github.com/repos/super-productivity/super-productivity/license", "https://super-productivity.com/use-cases/schedule-planner/", "https://super-productivity.com/guides/time-boxing-method/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/super-productivity/super-productivity/license", "name": "Super Productivity", "repository_url": "https://github.com/super-productivity/super-productivity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:49:55.731531+08:00", "kind": "repository_metadata", "sha256": "691dba04b37fbab8ce927e05962f86af64b8adc96da09941940f38e3e2cf6f61", "snapshot_path": "sources/691dba04b37fbab8ce927e05962f86af64b8adc96da09941940f38e3e2cf6f61.txt", "url": "https://api.github.com/repos/super-productivity/super-productivity"}, {"fetched_at": "2026-10-24T11:53:12.700786+08:00", "kind": "readme", "sha256": "0e1e8e86418adea0749d3e50f3c22a887b009b2e10d4fba554c7327932ca83f8", "snapshot_path": "sources/0e1e8e86418adea0749d3e50f3c22a887b009b2e10d4fba554c7327932ca83f8.txt", "url": "https://raw.githubusercontent.com/super-productivity/super-productivity/master/README.md"}, {"fetched_at": "2026-10-24T11:49:57.295600+08:00", "kind": "license", "sha256": "4183b12ab2b74af0a11d04f6bfa2b6e5e0eded35d821b78ae06dc01e1e04715e", "snapshot_path": "sources/4183b12ab2b74af0a11d04f6bfa2b6e5e0eded35d821b78ae06dc01e1e04715e.txt", "url": "https://api.github.com/repos/super-productivity/super-productivity/license"}, {"fetched_at": "2026-10-24T12:09:12.853855+08:00", "kind": "documentation", "sha256": "79965390063cff8a97c9851b87cb5f9ca9b5ac9c3942092fe53ddff63d8fd2c9", "snapshot_path": "sources/79965390063cff8a97c9851b87cb5f9ca9b5ac9c3942092fe53ddff63d8fd2c9.txt", "url": "https://super-productivity.com/use-cases/schedule-planner/"}, {"fetched_at": "2026-10-25T22:54:10.224880+08:00", "kind": "documentation", "sha256": "f1fac46e0f0dd3ea5a206f7c8b984ba354cf970b78992aa28c771b4498fe5da2", "snapshot_path": "sources/f1fac46e0f0dd3ea5a206f7c8b984ba354cf970b78992aa28c771b4498fe5da2.txt", "url": "https://super-productivity.com/guides/time-boxing-method/"}], "summary": "Super Productivity 是把待办任务放入日程时间块的个人规划应用：任务可拖入 planner/schedule 时间轴成为时间块，支持时间盒、完成与重新安排，未完成任务自动结转，并统计实际用时。", "technology_stack": ["TypeScript", "Angular", "Electron"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:191800260','FileGator','{"deployment": ["PHP 应用部署在自有 Web 服务器", "提供官方 Docker 镜像", "无需数据库"], "features": ["浏览本地或远端存储适配器中的文件夹层级", "复制、移动、重命名、新建、删除、压缩/解压", "分块上传、断点续传与批量下载", "多用户、角色、权限与独立主目录"], "github_repository_id": 191800260, "homepage": "https://filegator.io", "id": "github:191800260", "leaf_matches": [{"reason": "README 与官方文档均说明这是用于管理文件与文件夹的自托管 Web 应用，可直接管理服务器本地仓库目录，也可连接 S3、Dropbox、Azure Blob 等适配器，且明确列出 copy、move、rename、create、delete、zip、unzip、download、upload 等基本文件操作，并支持多用户不同权限与主目录。真实存储层级、以文件/文件夹为操作单元、变更存储三类操作均有官方依据；仓库身份与 MIT 许可由元数据与许可证接口证明。", "slug": "file-manager", "source_urls": ["https://api.github.com/repos/filegator/filegator", "https://raw.githubusercontent.com/filegator/filegator/master/README.md", "https://api.github.com/repos/filegator/filegator/license", "https://docs.filegator.io/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/filegator/filegator/license", "name": "FileGator", "repository_url": "https://github.com/filegator/filegator", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:49:58.802558+08:00", "kind": "repository_metadata", "sha256": "4714022a86975f982109c63451430c9db52ea645c776a01d803a82c33f69aee6", "snapshot_path": "sources/4714022a86975f982109c63451430c9db52ea645c776a01d803a82c33f69aee6.txt", "url": "https://api.github.com/repos/filegator/filegator"}, {"fetched_at": "2026-10-24T11:52:59.902567+08:00", "kind": "readme", "sha256": "7cbe26a30bcbb41d878fd6f875b9cb97cd30867238c9cb2f38b97aae701048d2", "snapshot_path": "sources/7cbe26a30bcbb41d878fd6f875b9cb97cd30867238c9cb2f38b97aae701048d2.txt", "url": "https://raw.githubusercontent.com/filegator/filegator/master/README.md"}, {"fetched_at": "2026-10-24T11:50:00.156138+08:00", "kind": "license", "sha256": "891ab7c6b4e0933983e4c9f990b89f268c23315a866f360f18656c0127b1e24a", "snapshot_path": "sources/891ab7c6b4e0933983e4c9f990b89f268c23315a866f360f18656c0127b1e24a.txt", "url": "https://api.github.com/repos/filegator/filegator/license"}, {"fetched_at": "2026-10-24T12:29:20.947455+08:00", "kind": "documentation", "sha256": "81c1579cb45d2b3d7d9d3b893f0d7d2f2e4f100954378cf320eb03cc3552b84a", "snapshot_path": "sources/81c1579cb45d2b3d7d9d3b893f0d7d2f2e4f100954378cf320eb03cc3552b84a.txt", "url": "https://docs.filegator.io/"}], "summary": "FileGator 是自托管的 Web 文件管理器：浏览服务器本地目录或 S3、FTP 等存储适配器中的真实文件夹层级，执行复制、移动、重命名、删除、上传、压缩等改变存储的操作。", "technology_stack": ["PHP", "Vue.js", "Flysystem"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:davinci-resolve','DaVinci Resolve','{"homepage": "https://www.blackmagicdesign.com/products/davinciresolve", "id": "commercial:davinci-resolve", "leaf_matches": [{"reason": "官方协作页面说明可创建 Blackmagic Cloud ID 登录 DaVinci Resolve Project Server 建立项目库，为项目分配任意数量协作者并通过 Blackmagic Cloud 共享；多人可在同一时间线工作，改动在查看器中查看并接受后才应用，还提供私有 Project Server 应用供受限网络使用。共享持久项目、具名成员与协调机制均有官方来源；商业条目仅作基本索引。", "slug": "collaborative-video-editor", "source_urls": ["https://www.blackmagicdesign.com/products/davinciresolve/collaboration"]}], "name": "DaVinci Resolve", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:00:29.600099+08:00", "kind": "documentation", "sha256": "a04902a860cdc03f6615ca50286c35fee36013f9bf301c3152d5d384d31ed15f", "snapshot_path": "sources/a04902a860cdc03f6615ca50286c35fee36013f9bf301c3152d5d384d31ed15f.txt", "url": "https://www.blackmagicdesign.com/products/davinciresolve/collaboration"}], "summary": "DaVinci Resolve 是含协作功能的专业剪辑/调色软件：通过 Blackmagic Cloud ID 登录项目服务器建立共享项目库，多名成员在同一时间线上工作，改动需在查看器中接受后生效。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:webflow','Webflow','{"homepage": "https://webflow.com", "id": "commercial:webflow", "leaf_matches": [{"reason": "官方 Interactions 页说明可在画布上为任意元素设定滚动/悬停/点击触发器并编辑时间轴动效，官网同时说明可发布并托管站点，满足可视画布、作者定义行为与线上发布三项核心。", "slug": "interactive-web-design-application", "source_urls": ["https://webflow.com/interactions-animations", "https://webflow.com/"]}, {"reason": "官网首页说明在可视化画布中编辑内容与布局、使用模板并由非开发者发布整站，符合可视化建站的可视组装、整站为单位与线上发布三项属性。", "slug": "visual-website-builder", "source_urls": ["https://webflow.com/"]}], "name": "Webflow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T13:28:31.228808+08:00", "kind": "homepage", "sha256": "6e65dc02879d40a1fe6e8048b61b04c74173f5f90f1ebed2e89be4c3bd503632", "snapshot_path": "sources/6e65dc02879d40a1fe6e8048b61b04c74173f5f90f1ebed2e89be4c3bd503632.txt", "url": "https://webflow.com/"}, {"fetched_at": "2026-10-24T13:36:36.821342+08:00", "kind": "documentation", "sha256": "928f84638e0dac10d2bd6d9e8f87efa7f0a2e877882ace214c80fa8009edda4d", "snapshot_path": "sources/928f84638e0dac10d2bd6d9e8f87efa7f0a2e877882ace214c80fa8009edda4d.txt", "url": "https://webflow.com/interactions-animations"}], "summary": "商业可视化网站设计与发布平台：在画布上设计页面，用触发器定义滚动、悬停、点击等交互动效，并直接发布托管站点。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:unbounce','Unbounce','{"homepage": "https://unbounce.com", "id": "commercial:unbounce", "leaf_matches": [{"reason": "官方着陆页产品页说明可用拖拽元素与 100+ 模板快速搭建并上线着陆页、弹窗与粘性条，围绕转化目标做 A/B 测试与智能分流，覆盖活动单页、可视化搭建与线上发布三属性。", "slug": "landing-page-builder", "source_urls": ["https://unbounce.com/product/landing-pages/"]}, {"reason": "官方功能页说明可在平台内构建落地页并发布到任意自定义域名或 URL、由平台免费托管，且可按页查看转化并导出表单线索；A/B 测试页说明可创建不限数量的页面变体、分流访客并比较转化，Smart Traffic 页说明创建不限数量变体、按设备与地域等属性自动把访客路由到更可能转化的版本并持续迭代。构建托管、转化测量与变体优化三段齐备。", "slug": "landing-page-optimization-platform", "source_urls": ["https://unbounce.com/product/features/", "https://unbounce.com/product/ab-testing-tool/", "https://unbounce.com/product/smart-traffic/"]}], "name": "Unbounce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T13:28:33.447518+08:00", "kind": "homepage", "sha256": "4af358cc12fa20c4027a7dd7d396764e45f77f5e1cebdb9b8c48db4a83cf1c46", "snapshot_path": "sources/4af358cc12fa20c4027a7dd7d396764e45f77f5e1cebdb9b8c48db4a83cf1c46.txt", "url": "https://unbounce.com/"}, {"fetched_at": "2026-10-24T14:28:27.001152+08:00", "kind": "documentation", "sha256": "c3f53a8fcf80784cd3af6d6af2d3fd8a2723dc7ca0e0f31fc79e5c49c6985146", "snapshot_path": "sources/c3f53a8fcf80784cd3af6d6af2d3fd8a2723dc7ca0e0f31fc79e5c49c6985146.txt", "url": "https://unbounce.com/product/landing-pages/"}, {"fetched_at": "2026-10-24T15:29:40.427124+08:00", "kind": "documentation", "sha256": "816c5d5706fe08b3c0749648cee8f36d6379931ef274531ce9f8e296307fb488", "snapshot_path": "sources/816c5d5706fe08b3c0749648cee8f36d6379931ef274531ce9f8e296307fb488.txt", "url": "https://unbounce.com/product/features/"}, {"fetched_at": "2026-10-24T15:46:25.077169+08:00", "kind": "documentation", "sha256": "691d49ee0ef07db15f9b678583beef83c661c05586b79f7fc05c2b4e718b2747", "snapshot_path": "sources/691d49ee0ef07db15f9b678583beef83c661c05586b79f7fc05c2b4e718b2747.txt", "url": "https://unbounce.com/product/ab-testing-tool/"}, {"fetched_at": "202