INSERT INTO "application" VALUES('github:13190625','Silex','{"deployment": ["官方在线版 v3.silex.me", "自托管 / 桌面应用（alpha）"], "features": ["浏览器中的可视化编辑器，拖拽排版页面与区块", "可连接 WordPress、Strapi、Supabase 等 CMS 提供动态内容", "整站为单位编辑，含模板与页面结构", "导出静态 HTML/CSS 自托管或使用内置托管发布"], "github_repository_id": 13190625, "homepage": "https://www.silex.me", "id": "github:13190625", "leaf_matches": [{"reason": "官方 README 自述为自由/开源的视觉网站构建器，可可视化设计并导出干净 HTML/CSS、托管到任意位置；官网说明可自托管、连接 CMS 并整站编辑，覆盖可视组装、整站为单位与线上发布三项核心。", "slug": "visual-website-builder", "source_urls": ["https://raw.githubusercontent.com/silexlabs/Silex/main/README.md", "https://www.silex.me/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/silexlabs/Silex/license", "name": "Silex", "repository_url": "https://github.com/silexlabs/Silex", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T13:17:30.042290+08:00", "kind": "repository_metadata", "sha256": "014d67295c163f4b0f14e0234d0a611edaa12171967c4660cc273877ba4b0c9e", "snapshot_path": "sources/014d67295c163f4b0f14e0234d0a611edaa12171967c4660cc273877ba4b0c9e.txt", "url": "https://api.github.com/repos/silexlabs/Silex"}, {"fetched_at": "2026-10-24T13:21:01.550367+08:00", "kind": "license", "sha256": "3009f8c5ad6f67c89959ee0beffcd3a975db5fba8f8684c87c545a1f6bca96b3", "snapshot_path": "sources/3009f8c5ad6f67c89959ee0beffcd3a975db5fba8f8684c87c545a1f6bca96b3.txt", "url": "https://api.github.com/repos/silexlabs/Silex/license"}, {"fetched_at": "2026-10-24T13:22:05.458434+08:00", "kind": "readme", "sha256": "f7f9f1430ad6b670dc03e3cf5bf525cfaaedb459e4ff8b448b98ead3dc489c13", "snapshot_path": "sources/f7f9f1430ad6b670dc03e3cf5bf525cfaaedb459e4ff8b448b98ead3dc489c13.txt", "url": "https://raw.githubusercontent.com/silexlabs/Silex/main/README.md"}, {"fetched_at": "2026-10-24T13:32:35.366809+08:00", "kind": "homepage", "sha256": "d8c58abd85c599a8fe37fe0c24a52a4af85a18b28df1d451fd53836b779559fb", "snapshot_path": "sources/d8c58abd85c599a8fe37fe0c24a52a4af85a18b28df