INSERT INTO "application" VALUES('commercial:sivi','Sivi','{"homepage": "https://sivi.ai", "id": "commercial:sivi", "leaf_matches": [{"reason": "官方 tour 页说明输入文本提示后，AI 设计生成器在约 1–2 分钟内产出分层可编辑设计；官方“What is an AI design generator”说明页进一步说明 Large Design Model 将标题、正文、CTA、图像与背景分别放在独立图层、保持真实文本可编辑并可对单个元素调整，覆盖“描述意图→机器组合设计→可操作结果”的核心。", "slug": "ai-design-generator", "source_urls": ["https://sivi.ai/tour/ai-design-generator", "https://sivi.ai/what-is-ai-design-generator"]}], "name": "Sivi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:58:57.759804+08:00", "kind": "homepage", "sha256": "61b1e90f0987eff7993e31a65df173c8243320c25134d3c47d7e15d51cce31b2", "snapshot_path": "sources/61b1e90f0987eff7993e31a65df173c8243320c25134d3c47d7e15d51cce31b2.txt", "url": "https://sivi.ai/"}, {"fetched_at": "2026-10-24T14:59:00.259426+08:00", "kind": "documentation", "sha256": "cd911d27d915c840044c6ecd38c070bc2142d567a7ffcd4149b65eb0bdad0b8b", "snapshot_path": "sources/cd911d27d915c840044c6ecd38c070bc2142d567a7ffcd4149b65eb0bdad0b8b.txt", "url": "https://sivi.ai/tour/ai-design-generator"}, {"fetched_at": "2026-10-25T23:24:20.940677+08:00", "kind": "documentation", "sha256": "a39f84c6f75c3e2107e24fbb7ff5ba802662163e67a0563153522b950909d27f", "snapshot_path": "sources/a39f84c6f75c3e2107e24fbb7ff5ba802662163e67a0563153522b950909d27f.txt", "url": "https://sivi.ai/what-is-ai-design-generator"}], "summary": "文本到设计的 AI 设计生成器：按提示合成含标题、正文、CTA、图像与背景的分层设计，元素保持可编辑。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:428292281','IOPaint','{"deployment": ["pip 安装后本地启动 Web UI（默认 8080 端口）", "Windows 一键安装包；模型首次启动自动下载"], "features": ["擦除模型去除物体、瑕疵、水印与人物", "扩散模型替换物体、局部重绘（inpainting）与扩图（outpainting）", "内置 Web UI，可在 FileManager 中浏览图片并保存到输出目录", "支持 CPU / GPU / Apple Silicon 自托管运行"], "github_repository_id": 428292281, "homepage": "https://www.iopaint.com/", "id": "github:428292281", "leaf_matches": [{"reason": "README 说明工具对已有图像执行 AI 驱动的擦除、替换对象、局部重绘与扩图，提供 Web UI 供逐次检查并保存输出，属于“源图像→系统执行编辑→审查优化→编辑后图像交付”的核心；GitHub 元数据 archived=true，仓库已归档只读，功能证据成立但不再维护。", "slug": "ai-image-editing-application", "source_urls": ["https://raw.githubusercontent.com/Sanster/IOPaint/HEAD/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/Sanster/IOPaint/license", "name": "IOPaint", "repository_url": "https://github.com/Sanster/IOPaint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:34:21.456465+08:00", "kind": "repository_metadata", "sha256": "b18e9a4e19c3c948f54940fbe166bae2e40d71c35dbe2d7988ded11248ac5fe7", "snapshot_path": "sources/b18e9a4e19c3c948f54940fbe166bae2e40d71c35dbe2d7988ded11248ac5fe7.txt", "url": "https://api.github.com/repos/Sanster/IOPaint"}, {"fetched_at": "2026-10-24T14:34:23.029921+08:00", "kind": "license", "sha256": "29ece00345cec52621b812781b67b85782bbb6d113638bd27bffcee9a6862f2b", "snapshot_path": "sources/29ece00345cec52621b812781b67b85782bbb6d113638bd27bffcee9a6862f2b.txt", "url": "https://api.github.com/repos/Sanster/IOPaint/license"}, {"fetched_at": "2026-10-24T14:38:42.031067+08:00", "kind": "readme", "sha256": "dfeef9bdd08e58f2331daa3ed9675cfa27879b51e34bf7f6e98bb0466d494fdd", "snapshot_path": "sources/dfeef9bdd08e58f2331daa3ed9675cfa27879b51e34bf7f6e98bb0466d494fdd.txt", "url": "https://raw.githubusercontent.com/Sanster/IOPaint/HEAD/README.md"}], "summary": "自托管的 AI 图像修复与扩图工具：对已有图片做擦除、替换、扩图与局部重绘，并在 Web UI 中检查与保存结果；上游仓库已归档、只读。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:525592995','InvokeAI','{"deployment": ["下载官方 Launcher 本地安装", "安装文档提供 Linux Docker 方式"], "features": ["本地 Web 服务器 + React UI，提示词生成图像", "Unified Canvas 支持生成、局部重绘与扩图、笔刷编辑", "工作流/节点编排与可复现的生成参数记录", "支持 SD 1.5 / SDXL / SD 3.5 / Flux 等模型系列"], "github_repository_id": 525592995, "homepage": "https://invoke-ai.github.io/InvokeAI/", "id": "github:525592995", "leaf_matches": [{"reason": "README 说明 Invoke 以提示词生成图像并提供统一画布、工作流与迭代细化，生成结果保存在本地图库并可继续生成/变化，覆盖“描述视觉意图→模型合成图像→交互式请求审查循环”的核心。", "slug": "ai-image-generator", "source_urls": ["https://raw.githubusercontent.com/invoke-ai/InvokeAI/HEAD/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/invoke-ai/InvokeAI/license", "name": "InvokeAI", "repository_url": "https://github.com/invoke-ai/InvokeAI", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:34:24.452002+08:00", "kind": "repository_metadata", "sha256": "d66386e1ea1d8045811a02211959fbe232c7e382494c9f93cf7765936cd4058a", "snapshot_path": "sources/d66386e1ea1d8045811a02211959fbe232c7e382494c9f93cf7765936cd4058a.txt", "url": "https://api.github.com/repos/invoke-ai/InvokeAI"}, {"fetched_at": "2026-10-24T14:34:27.092098+08:00", "kind": "license", "sha256": "f32a153ebbb16849a1d2391866388f794f7d3d1ef308e0a72206578f22b7d763", "snapshot_path": "sources/f32a153ebbb16849a1d2391866388f794f7d3d1ef308e0a72206578f22b7d763.txt", "url": "https://api.github.com/repos/invoke-ai/InvokeAI/license"}, {"fetched_at": "2026-10-24T14:38:45.376540+08:00", "kind": "readme", "sha256": "87f933b43279c7a7955cf8d2af850f5558ff8f2b6a1c4f84019d5db55bbed273", "snapshot_path": "sources/87f933b43279c7a7955cf8d2af850f5558ff8f2b6a1c4f84019d5db55bbed273.txt", "url": "https://raw.githubusercontent.com/invoke-ai/InvokeAI/HEAD/README.md"}], "summary": "自托管的 AI 图像生成工作台：以提示词生成图像，并在统一画布与工作流中反复细化、扩图与保存。", "technology_stack": ["TypeScript（GitHub 元数据主语言）", "React"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:synthesia','Synthesia','{"homepage": "https://www.synthesia.io", "id": "commercial:synthesia", "leaf_matches": [{"reason": "官方首页写明 “AI Video and Avatar platform for business”“Create studio-quality videos with AI avatars and voiceovers in 140+ languages”“100s of avatars”，并以页面示例 lipsyncEnabled: true 与 “voice cloning and perfect lip-sync” 说明口型同步；用户以脚本或配音驱动所选数字人，系统生成说话表演并渲染为视频，符合该类型核心结构。", "slug": "ai-avatar-video-generator", "source_urls": ["https://www.synthesia.io"]}], "name": "Synthesia", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:35:44.681240+08:00", "kind": "homepage", "sha256": "7d8582129b3fe93bc8e390218125d7ca44ec97126d53be23e48b877e385e054b", "snapshot_path": "sources/7d8582129b3fe93bc8e390218125d7ca44ec97126d53be23e48b877e385e054b.txt", "url": "https://www.synthesia.io"}], "summary": "企业级 AI 数字人与视频平台：以脚本和配音驱动 AI 数字人制作 140+ 语言的视频，支持口型同步与声音克隆。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:descript','Descript','{"homepage": "https://www.descript.com", "id": "commercial:descript", "leaf_matches": [{"reason": "官方首页说明可导入录制素材自动转录，通过编辑文字完成剪辑、一键去除填充词与重拍、以 Studio Sound 清理背景噪声并导出成片，属于“用户提供素材→AI 执行编辑→审查优化→编辑后视频交付”的核心。", "slug": "ai-video-editing-application", "source_urls": ["https://www.descript.com"]}], "name": "Descript", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:35:44.503938+08:00", "kind": "homepage", "sha256": "24d1d56977c9bbaec88af220e06e51bc4c6e4106ae2bb39dfe7d2c10aebca197", "snapshot_path": "sources/24d1d56977c9bbaec88af220e06e51bc4c6e4106ae2bb39dfe7d2c10aebca197.txt", "url": "https://www.descript.com"}], "summary": "以文本为中心的 AI 视频与音频编辑器：转录后改文字即改视频，并由 AI 执行去填充词、去重拍与 Studio Sound 音频清理，再导出发布。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pika','Pika','{"homepage": "https://pika.art", "id": "commercial:pika", "leaf_matches": [{"reason": "官方首页与帮助中心说明选择应用后输入提示词或自有素材即可生成视频，可挑选模型与设置、按积分计费，覆盖“描述意图→模型合成素材→生成片段交付”的核心。", "slug": "ai-video-generator", "source_urls": ["https://pika.art", "https://pika.art/faq"]}], "name": "Pika", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:36:45.385322+08:00", "kind": "homepage", "sha256": "b5a7e666d1a31cf7d9937f3342bca424f7e6c7c5fea42ead1e1d1d00a69c5585", "snapshot_path": "sources/b5a7e666d1a31cf7d9937f3342bca424f7e6c7c5fea42ead1e1d1d00a69c5585.txt", "url": "https://pika.art"}, {"fetched_at": "2026-10-24T14:42:21.804310+08:00", "kind": "documentation", "sha256": "ebe46a4f2f9e038ff2987a6b2bc2744e2df585daa0607a1978dd282704b868ca", "snapshot_path": "sources/ebe46a4f2f9e038ff2987a6b2bc2744e2df585daa0607a1978dd282704b868ca.txt", "url": "https://pika.art/faq"}], "summary": "提示词驱动的 AI 视频生成器：由文本或参考素材合成短视频片段，支持模型选择与积分计费。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:elevenlabs-sound-effects','ElevenLabs Sound Effects','{"homepage": "https://elevenlabs.io", "id": "commercial:elevenlabs-sound-effects", "leaf_matches": [{"reason": "官方音效页正文说明其 sound effect generator “lets you create custom sound effects from scratch”，可 “generate, modify, and download your own sounds in MP3 format —all royalty-free”，并由模型按描述生成音效与环境音，输出为有界音频素材而非语音或完整音乐，符合该类型的声音素材范围。", "slug": "ai-audio-generator", "source_urls": ["https://elevenlabs.io/sound-effects"]}], "name": "ElevenLabs Sound Effects", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:37:45.696035+08:00", "kind": "homepage", "sha256": "9d4513321a18480bdf1a2a0b86f2fef8c58de9943f9f9a3eec22453b6ce84208", "snapshot_path": "sources/9d4513321a18480bdf1a2a0b86f2fef8c58de9943f9f9a3eec22453b6ce84208.txt", "url": "https://elevenlabs.io/sound-effects"}], "summary": "文本提示驱动的 AI 音效生成器：按描述合成免版税音效与环境音，可试听并下载为音频片段。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:suno','Suno','{"homepage": "https://suno.com", "id": "commercial:suno", "leaf_matches": [{"reason": "官方首页说明以一句文本提示在约一分钟内生成包含人声、歌词与完整制作的原创歌曲，并提供编辑工具、混音工作区与分轨导出，覆盖“规格驱动输入→按需模型作曲→有界音乐作品交付”的核心。", "slug": "ai-music-generator", "source_urls": ["https://suno.com"]}], "name": "Suno", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:22:58.643280+08:00", "kind": "homepage", "sha256": "26e5cb8b7c2e1a8606086bfa108367deef24cac4e6d10cccb2e14fe4bdde88db", "snapshot_path": "sources/26e5cb8b7c2e1a8606086bfa108367deef24cac4e6d10cccb2e14fe4bdde88db.txt", "url": "https://suno.com"}], "summary": "按提示词创作完整歌曲的 AI 音乐生成器：生成含人声、歌词与编曲的作品，并提供编辑、混音与分轨导出。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:murf-ai','Murf AI','{"homepage": "https://murf.ai", "id": "commercial:murf-ai", "leaf_matches": [{"reason": "官方文本转语音页说明用户键入/粘贴脚本或上传文本、挑选声音后由系统生成语音，可预览并导出音频文件，并提供语速、音调与发音编辑，符合“给定词语+声音选择→按需合成→语音音频交付”的核心。", "slug": "ai-voice-generator", "source_urls": ["https://murf.ai/text-to-speech"]}], "name": "Murf AI", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:44:37.858534+08:00", "kind": "documentation", "sha256": "034648e2c68349ffc4a2f197cb886928af8b093762b574b382b33684adf24ea2", "snapshot_path": "sources/034648e2c68349ffc4a2f197cb886928af8b093762b574b382b33684adf24ea2.txt", "url": "https://murf.ai/text-to-speech"}], "summary": "AI 语音生成器：键入或粘贴脚本、选择声音后合成语音，可调控语速音调并导出音频。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:148129143','Bagisto','{"deployment": ["Docker 单命令运行（内置迁移与种子数据）", "Composer 安装，MySQL/MariaDB/PostgreSQL"], "features": ["商品与目录管理、多店铺面与主题", "购物车、结账与支付方式扩展", "订单管理与库存、发货处理", "可选多卖家市场、B2B、POS 与无头店面"], "github_repository_id": 148129143, "homepage": "https://bagisto.com", "id": "github:148129143", "leaf_matches": [{"reason": "README 说明 Bagisto 是开源 Laravel 电商平台，用于搭建单商家店铺、B2B 与多卖家市场；开发者文档 Backend Architecture 页进一步列出同一 Laravel 应用内的 Product（商品、价格、库存）、Shop（storefront：routes, controllers, views, customer account）、Checkout（cart: items, addresses, payment and shipping rates）与 Sales（orders, invoices, shipments, refunds）包，并由 Admin 包在同一系统提供后台，构成“商家目录→平台店面→购物车/结账→订单同系统管理”的三角核心。", "slug": "e-commerce-platform", "source_urls": ["https://raw.githubusercontent.com/bagisto/bagisto/HEAD/README.md", "https://devdocs.bagisto.com/architecture/backend.html"]}, {"reason": "README 与功能页显示自托管在线店铺、商品目录、多销售渠道、结账/订单管理和支付集成，卖家可运营自有品牌单店，覆盖店铺-目录-购买-收入核心。", "slug": "creator-storefront", "source_urls": ["https://raw.githubusercontent.com/bagisto/bagisto/2.5/README.md", "https://bagisto.com/en/features/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/bagisto/bagisto/license", "name": "Bagisto", "repository_url": "https://github.com/bagisto/bagisto", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:34:28.604287+08:00", "kind": "repository_metadata", "sha256": "51ed804976049cc77f5148e80501ff7f5a116ce0f525884a555b6e4c0f65494a", "snapshot_path": "sources/51ed804976049cc77f5148e80501ff7f5a116ce0f525884a555b6e4c0f65494a.txt", "url": "https://api.github.com/repos/bagisto/bagisto"}, {"fetched_at": "2026-10-24T14:34:30.129898+08:00", "kind": "license", "sha256": "1d6b469e10a65997d21b2beec2e7b7b1ee458484143008c543d422fba4a829e7", "snapshot_path": "sources/1d6b469e10a65997d21b2beec2e7b7b1ee458484143008c543d422fba4a829e7.txt", "url": "https://api.github.com/repos/bagisto/bagisto/license"}, {"fetched_at": "2026-10-24T14:38:48.915121+08:00", "kind": "readme", "sha256": "e74753b5024eec7e10a81cd39f83a07cea1f5b07926dba0a9d15f03a07baacc1", "snapshot_path": "sources/e74753b5024eec7e10a81cd39f83a07cea1f5b07926dba0a9d15f03a07baacc1.txt", "url": "https://raw.githubusercontent.com/bagisto/bagisto/HEAD/README.md"}, {"fetched_at": "2026-10-25T23:32:22.085909+08:00", "kind": "documentation", "sha256": "a52bfad434d81fba875b59233374564ae81d7ed50dc796325d3e550a6f0bd66e", "snapshot_path": "sources/a52bfad434d81fba875b59233374564ae81d7ed50dc796325d3e550a6f0bd66e.txt", "url": "https://devdocs.bagisto.com/architecture/backend.html"}, {"fetched_at": "2026-10-27T01:42:13.872638+08:00", "kind": "repository_metadata", "sha256": "b7504fe9ee95849accd05db0315df626fb415114d3d9f945f044b1cf623463d3", "snapshot_path": "sources/b7504fe9ee95849accd05db0315df626fb415114d3d9f945f044b1cf623463d3.txt", "url": "https://api.github.com/repos/bagisto/bagisto"}, {"fetched_at": "2026-10-27T01:42:19.066673+08:00", "kind": "readme", "sha256": "e74753b5024eec7e10a81cd39f83a07cea1f5b07926dba0a9d15f03a07baacc1", "snapshot_path": "sources/e74753b5024eec7e10a81cd39f83a07cea1f5b07926dba0a9d15f03a07baacc1.txt", "url": "https://raw.githubusercontent.com/bagisto/bagisto/2.5/README.md"}, {"fetched_at": "2026-10-27T01:44:27.477435+08:00", "kind": "documentation", "sha256": "fed8c91deaf0fc8b5af38e1cca9088087c77fb742716fd89dbffb47b084eddab", "snapshot_path": "sources/fed8c91deaf0fc8b5af38e1cca9088087c77fb742716fd89dbffb47b084eddab.txt", "url": "https://bagisto.com/en/features/"}], "summary": "开源电商平台：在同一后台维护商品目录、运营店面、完成购物车与结账，并把成交转为可管理的订单。", "technology_stack": ["PHP（Laravel）", "MySQL / MariaDB / PostgreSQL", "MIT"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:8162715','Saleor','{"deployment": ["Docker Compose 部署（官方文档步骤）", "托管 Saleor Cloud"], "features": ["GraphQL-only API：面向买家与管理端的唯一交互面", "商品与富内容目录、按渠道控制价格/币种/库存", "购物车、促销引擎与结账、支付编排", "订单、退货、多仓库与客户历史"], "github_repository_id": 8162715, "homepage": "https://saleor.io", "id": "github:8162715", "leaf_matches": [{"reason": "README 自述为 “GraphQL native, API-only platform”，并列出目录/购物车/结账/订单/支付与按渠道定价，官方站点强调表现层解耦、可自建前端，符合“交易型引擎+API 为主要消费面+表现层解耦”的三个属性。", "slug": "headless-commerce-platform", "source_urls": ["https://raw.githubusercontent.com/saleor/saleor/HEAD/README.md", "https://saleor.io"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/saleor/saleor/license", "name": "Saleor", "repository_url": "https://github.com/saleor/saleor", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:34:31.898774+08:00", "kind": "repository_metadata", "sha256": "dd760480ab48d60cb54f81f5aef82fc72584282e0e8171fbcc2b4c4560215695", "snapshot_path": "sources/dd760480ab48d60cb54f81f5aef82fc72584282e0e8171fbcc2b4c4560215695.txt", "url": "https://api.github.com/repos/saleor/saleor"}, {"fetched_at": "2026-10-24T14:34:33.480703+08:00", "kind": "license", "sha256": "66414204adfe4e98b68ec0ed6835cb67fa21f2c9dedade0532f0985bc6fe596e", "snapshot_path": "sources/66414204adfe4e98b68ec0ed6835cb67fa21f2c9dedade0532f0985bc6fe596e.txt", "url": "https://api.github.com/repos/saleor/saleor/license"}, {"fetched_at": "2026-10-24T14:38:46.817169+08:00", "kind": "readme", "sha256": "6b285440fe799c8620470efc081157777636d822be759aa8bd812a9855548944", "snapshot_path": "sources/6b285440fe799c8620470efc081157777636d822be759aa8bd812a9855548944.txt", "url": "https://raw.githubusercontent.com/saleor/saleor/HEAD/README.md"}, {"fetched_at": "2026-10-24T15:00:58.550223+08:00", "kind": "homepage", "sha256": "a7a38155d4072ffb3f7424865d45d41bb90dbf09fb201a005b1b0615054fdb7a", "snapshot_path": "sources/a7a38155d4072ffb3f7424865d45d41bb90dbf09fb201a005b1b0615054fdb7a.txt", "url": "https://saleor.io"}], "summary": "GraphQL 原生的无头商务引擎：以 API 提供目录、购物车、结账与订单，店面由外部前端构建。", "technology_stack": ["Python", "GraphQL", "PostgreSQL", "BSD-3-Clause"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:shopify','Shopify','{"homepage": "https://www.shopify.com", "id": "commercial:shopify", "leaf_matches": [{"reason": "官方 /online-store 页说明商家可选 800+ 主题或由 AI 生成店铺设计，并用可视化在线商店编辑器拖拽搭建、无需编码，且由平台托管维护；该页同时说明内置 Shopify Checkout。官方 /orders 与 /inventory 页说明可在同一后台集中管理订单、履约、库存与退货，覆盖线上店铺及多渠道订单。以上对应“商家无代码组装→服务托管单商家场所→完整购买与订单机制”的核心。", "slug": "online-store-builder", "source_urls": ["https://www.shopify.com", "https://www.shopify.com/online-store", "https://www.shopify.com/orders", "https://www.shopify.com/inventory"]}], "name": "Shopify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:24:27.126835+08:00", "kind": "homepage", "sha256": "0c0c36ee7e932cd5928ff2231a9e39bf7b07923280da5cbf611862eac0f6df2f", "snapshot_path": "sources/0c0c36ee7e932cd5928ff2231a9e39bf7b07923280da5cbf611862eac0f6df2f.txt", "url": "https://www.shopify.com"}, {"fetched_at": "2026-10-25T23:33:50.375131+08:00", "kind": "documentation", "sha256": "48c1bd5cd842916370dfdf9be67d8aee27c0384562237372c63dc58813bb9dec", "snapshot_path": "sources/48c1bd5cd842916370dfdf9be67d8aee27c0384562237372c63dc58813bb9dec.txt", "url": "https://www.shopify.com/online-store"}, {"fetched_at": "2026-10-25T23:34:29.365133+08:00", "kind": "documentation", "sha256": "b6a2686be274328728e44d1d27638260e0766d9db348e4a9e23cc24b3a7d7ab1", "snapshot_path": "sources/b6a2686be274328728e44d1d27638260e0766d9db348e4a9e23cc24b3a7d7ab1.txt", "url": "https://www.shopify.com/orders"}, {"fetched_at": "2026-10-25T23:34:30.226559+08:00", "kind": "documentation", "sha256": "1648a7a06bb6cee45983b22de49da39d14eb84875a85ca9c8adc0a84e0800897", "snapshot_path": "sources/1648a7a06bb6cee45983b22de49da39d14eb84875a85ca9c8adc0a84e0800897.txt", "url": "https://www.shopify.com/inventory"}], "summary": "托管式在线店铺构建服务：商家用模板/可视化编辑搭建自有店铺，平台托管并提供目录、结账、支付与订单管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sharetribe','Sharetribe','{"homepage": "https://www.sharetribe.com", "id": "commercial:sharetribe", "leaf_matches": [{"reason": "官方首页说明其为面向运营方的无代码市场构建器，买家面对多供应商聚合的单一场所，卖家拥有 profiles 与 listings，平台提供支付、变现、管理工具与托管基础设施；官方 monetization 页进一步说明可为每笔交易设置佣金比例、由后端自动计算并经 Stripe 拆分付款给 provider，provider 可查看佣金成本与收益。以上对应“运营方场所+众多独立卖家+卖家自管+运营方治理与市场经济学”的核心。", "slug": "marketplace-platform", "source_urls": ["https://www.sharetribe.com", "https://www.sharetribe.com/features/monetization-methods/"]}], "name": "Sharetribe", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:39:42.464114+08:00", "kind": "homepage", "sha256": "0bd4bbb76c00611e528e1d6318c3d037e0c98ccbd562bdaddd02ed949a1c589e", "snapshot_path": "sources/0bd4bbb76c00611e528e1d6318c3d037e0c98ccbd562bdaddd02ed949a1c589e.txt", "url": "https://www.sharetribe.com"}, {"fetched_at": "2026-10-25T23:33:39.853508+08:00", "kind": "documentation", "sha256": "e0f3bf365d8411fc5b73db552946190696783fd1fe3627c2a88819e0bfd4f14d", "snapshot_path": "sources/e0f3bf365d8411fc5b73db552946190696783fd1fe3627c2a88819e0bfd4f14d.txt", "url": "https://www.sharetribe.com/features/monetization-methods/"}], "summary": "面向创始人的市场平台软件：运营方在托管环境中开设多卖家场所，卖家维护档案与上架，平台处理支付与抽成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:catalog-machine','Catalog Machine','{"homepage": "https://www.catalogmachine.com", "id": "commercial:catalog-machine", "leaf_matches": [{"reason": "官方首页说明可用产品数据库、CSV、网址或图片建立在线与 PDF 目录，套用模板排版、分享或密码保护，并可选嵌入订单表与收款；目录持续对应产品数据，符合“产品组合→策划为目录产物→发布为可浏览可分享界面”的核心。", "slug": "digital-product-catalog", "source_urls": ["https://www.catalogmachine.com"]}], "name": "Catalog Machine", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:29:59.792600+08:00", "kind": "homepage", "sha256": "df191bacc871b6c0796c48419948387099816243530707c9d688f182c37f0e8b", "snapshot_path": "sources/df191bacc871b6c0796c48419948387099816243530707c9d688f182c37f0e8b.txt", "url": "https://www.catalogmachine.com"}], "summary": "在线与 PDF 产品目录发布工具：以产品数据库或导入数据生成可品牌化、可分享的目录，浏览阅读为主、下单可选。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:131995661','Shopware 6','{"deployment": ["Docker 开发环境；生产环境按文档部署", "Symfony 应用，MySQL/MariaDB"], "features": ["产品记录含编号、描述、价格、税与库存", "变体生成器按属性组合生成可售单元", "类目树与动态产品组组织目录", "按销售渠道分配商品并控制店面可见性"], "github_repository_id": 131995661, "homepage": "https://shopware.com", "id": "github:131995661", "leaf_matches": [{"reason": "官方产品文档展示新建产品记录（编号、描述、价格、税、库存）、用变体生成器产生可售单元、归入类目树，并指定销售渠道与店面可见性；README 将其定位为可直接使用的购物车系统，符合“目录登记簿+产品记录+可浏览组织+销售可用性”的核心。", "slug": "product-catalog-management", "source_urls": ["https://docs.shopware.com/en/shopware-6-en/catalogues/products", "https://raw.githubusercontent.com/shopware/shopware/HEAD/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/shopware/shopware/license", "name": "Shopware 6", "repository_url": "https://github.com/shopware/shopware", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:45:16.505155+08:00", "kind": "repository_metadata", "sha256": "70840301b0083ba6722768d81892918387e82ed5ce40b45ce4829f1481d61dc0", "snapshot_path": "sources/70840301b0083ba6722768d81892918387e82ed5ce40b45ce4829f1481d61dc0.txt", "url": "https://api.github.com/repos/shopware/shopware"}, {"fetched_at": "2026-10-24T14:45:15.003329+08:00", "kind": "license", "sha256": "dda4e398c7458258669699617e9f8b059c98e789f00ac64b485f7f370b1fcf25", "snapshot_path": "sources/dda4e398c7458258669699617e9f8b059c98e789f00ac64b485f7f370b1fcf25.txt", "url": "https://api.github.com/repos/shopware/shopware/license"}, {"fetched_at": "2026-10-24T14:47:26.864427+08:00", "kind": "readme", "sha256": "614ee87582fa3ef73e2f3fd12da5da94b2c4a95c72279da947ac5f197c005de2", "snapshot_path": "sources/614ee87582fa3ef73e2f3fd12da5da94b2c4a95c72279da947ac5f197c005de2.txt", "url": "https://raw.githubusercontent.com/shopware/shopware/HEAD/README.md"}, {"fetched_at": "2026-10-24T14:48:08.826040+08:00", "kind": "documentation", "sha256": "4d02ff468187f8ce4cc4b7427b908f0b453d8b51a14bfc28933e737efdad9427", "snapshot_path": "sources/4d02ff468187f8ce4cc4b7427b908f0b453d8b51a14bfc28933e737efdad9427.txt", "url": "https://docs.shopware.com/en/shopware-6-en/catalogues/products"}], "summary": "开源电商平台，其后台提供产品目录管理：维护商品记录、价格与变体，按类目组织并控制各销售渠道的可见与可售。", "technology_stack": ["PHP（Symfony）", "Vue.js", "MySQL / MariaDB", "MIT"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:298274485','AtroPIM','{"deployment": ["先安装 AtroCore（GPLv3 开源平台），再叠加 PIM 模块", "Docker 镜像用于评估，生产环境按文档自托管安装"], "features": ["产品为一等实体，属性/关系/布局可界面配置", "变体、分类体系与渠道特定取值", "导入导出、权限、工作流与资产管理（继承自 AtroCore）", "API-first，标准与自定义实体自动生成 API"], "github_repository_id": 298274485, "homepage": "https://www.atropim.com", "id": "github:298274485", "leaf_matches": [{"reason": "AtroPIM 是叠加在 AtroCore 平台上的 PIM 模块（README 明示本仓库为 AtroCore 的 PIM 模块、并非独立应用）；README 说明 AtroPIM 集中整合产品信息并分发到网店、市场、印刷目录、ERP 与合作伙伴门户，属性/关系/分类/渠道可按组织需要配置，变体与渠道特定值属标准功能，符合“中央产品记录库+组织定义的数据结构+下游渠道分发”的三个结构。", "slug": "product-information-management-pim", "source_urls": ["https://raw.githubusercontent.com/atrocore/atropim/HEAD/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/atrocore/atropim/license", "name": "AtroPIM", "repository_url": "https://github.com/atrocore/atropim", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:34:35.218230+08:00", "kind": "repository_metadata", "sha256": "e4eec4c1b44122532074e35e4ece47b4a47d6112a570f56b76424f843addf9a9", "snapshot_path": "sources/e4eec4c1b44122532074e35e4ece47b4a47d6112a570f56b76424f843addf9a9.txt", "url": "https://api.github.com/repos/atrocore/atropim"}, {"fetched_at": "2026-10-24T14:34:37.200850+08:00", "kind": "license", "sha256": "cace1428812b3cef20e59fc367bc7578b9aacb89a3efa3a7353bb1be3c39a588", "snapshot_path": "sources/cace1428812b3cef20e59fc367bc7578b9aacb89a3efa3a7353bb1be3c39a588.txt", "url": "https://api.github.com/repos/atrocore/atropim/license"}, {"fetched_at": "2026-10-24T14:38:50.284287+08:00", "kind": "readme", "sha256": "2a602730a2987f17ab927435ec07a0155a19758b3bb4a613a39e944126b0f75c", "snapshot_path": "sources/2a602730a2987f17ab927435ec07a0155a19758b3bb4a613a39e944126b0f75c.txt", "url": "https://raw.githubusercontent.com/atrocore/atropim/HEAD/README.md"}], "summary": "开源模块化 PIM：需叠加 AtroCore 平台运行，集中管理产品记录与可配置属性，把产品信息按渠道分发到商店、市场、印刷目录与 ERP。", "technology_stack": ["PHP 8.4+", "PostgreSQL / MySQL / MariaDB", "REST / OpenAPI", "GPL-3.0"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:snipcart','Snipcart','{"homepage": "https://snipcart.com", "id": "commercial:snipcart", "leaf_matches": [{"reason": "官方首页自述 “Add a shopping cart to any website”，由商家保留网站与商品展示、平台托管购物车与结账并提供商户后台订单管理，符合“购物者绑定的持久化购物车→带价可编辑累积→转化为订单的交接”这一独立购物车形态。", "slug": "shopping-cart-platform", "source_urls": ["https://snipcart.com"]}], "name": "Snipcart", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:36:45.308309+08:00", "kind": "homepage", "sha256": "ab217f2abef98eb7942bbc4b0f8739ffe162b1444c288bada94e18c3d657acae", "snapshot_path": "sources/ab217f2abef98eb7942bbc4b0f8739ffe162b1444c288bada94e18c3d657acae.txt", "url": "https://snipcart.com"}], "summary": "可附加到任意现有网站的托管购物车：由站点声明商品，平台承载购物车、结账与商户后台订单。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:linnworks','Linnworks','{"homepage": "https://www.linnworks.com", "id": "commercial:linnworks", "leaf_matches": [{"reason": "官方首页与订单管理页说明把多渠道订单集中为单一记录，并按产品类型、目的地、渠道、库存或自定义规则把每单自动路由到自有仓、3PL 或直发供应商，跟踪各地点状态并回传渠道，符合“渠道中立订单记录+履约网络+规则化寻源决策”的核心。", "slug": "distributed-order-management", "source_urls": ["https://www.linnworks.com", "https://www.linnworks.com/order-management/"]}, {"reason": "官方首页与多渠道销售页说明平台连接 100+ 第三方市场，中央目录集中保存商品并从同一处创建、发布和更新各渠道 listing，任一渠道成交后按订单扣减全渠道库存并把追踪号回传各渠道，订单集中到同一处处理，符合渠道连接、中央目录、渠道列表与双向销售循环。", "slug": "multi-marketplace-seller-platform", "source_urls": ["https://www.linnworks.com/", "https://www.linnworks.com/solutions/multichannel-selling/"]}], "name": "Linnworks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:44:04.927961+08:00", "kind": "homepage", "sha256": "4e7747620506e145b3f845dc38100bd26685ba8f8c4927cc1cc70bf97718bf9a", "snapshot_path": "sources/4e7747620506e145b3f845dc38100bd26685ba8f8c4927cc1cc70bf97718bf9a.txt", "url": "https://www.linnworks.com"}, {"fetched_at": "2026-10-24T14:44:47.170423+08:00", "kind": "documentation", "sha256": "8c20a6f3323856efac45deeca83c47cbc7b44a882ef54060974f68ab590457dd", "snapshot_path": "sources/8c20a6f3323856efac45deeca83c47cbc7b44a882ef54060974f68ab590457dd.txt", "url": "https://www.linnworks.com/order-management/"}, {"fetched_at": "2026-10-24T15:06:06.791646+08:00", "kind": "homepage", "sha256": "97c1a5d130e44e82bc57c194bada5378620eef00657b86fd2cb66aef9989ec8b", "snapshot_path": "sources/97c1a5d130e44e82bc57c194bada5378620eef00657b86fd2cb66aef9989ec8b.txt", "url": "https://www.linnworks.com/"}, {"fetched_at": "2026-10-24T15:32:05.003283+08:00", "kind": "documentation", "sha256": "23adc47584602352d7940ff4fd054c64474e5a7a8dfcb13321f2b9d583df2c71", "snapshot_path": "sources/23adc47584602352d7940ff4fd054c64474e5a7a8dfcb13321f2b9d583df2c71.txt", "url": "https://www.linnworks.com/solutions/multichannel-selling/"}], "summary": "多渠道订单与库存管理平台：维护跨渠道订单记录，并按规则把每单寻源到自有仓、3PL 或直发供应商。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fluent-commerce','Fluent Commerce','{"homepage": "https://fluentcommerce.com", "id": "commercial:fluent-commerce", "leaf_matches": [{"reason": "官方首页自述为面向企业的 “Order Management System”，说明跨渠道、门店与仓库编排每笔订单；官方 OMS 子页进一步写明 “Command the full order lifecycle”，并列出订单编排、门店发货/点击提货、退货换货、订单工作流与履约决策。据此核到 OMS 自述、售后生命周期与门店/退货处理的基本功能面；发货追踪字段与取消/退款的状态门控未在已抓正文中核实。曾尝试抓取官方文档门户，但快照为客户端壳、无可读正文，已移除该引用与相关断言。", "slug": "order-management-system-oms", "source_urls": ["https://fluentcommerce.com", "https://fluentcommerce.com/order-management-system/"]}], "name": "Fluent Commerce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:03:55.264969+08:00", "kind": "homepage", "sha256": "d562081dff41b2f3878e6a516a182ff800dffd62a254ae3355c503c1b4159b68", "snapshot_path": "sources/d562081dff41b2f3878e6a516a182ff800dffd62a254ae3355c503c1b4159b68.txt", "url": "https://fluentcommerce.com"}, {"fetched_at": "2026-10-25T23:38:52.633028+08:00", "kind": "documentation", "sha256": "0a6ddcf556724d705cc4e83a7e7249cd72c358b0732343eb35c4dc2547c70b55", "snapshot_path": "sources/0a6ddcf556724d705cc4e83a7e7249cd72c358b0732343eb35c4dc2547c70b55.txt", "url": "https://fluentcommerce.com/order-management-system/"}], "summary": "面向零售的订单管理系统：覆盖跨渠道订单生命周期、退货换货与门店/仓库履约编排。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pipe17','Pipe17','{"homepage": "https://pipe17.com", "id": "commercial:pipe17", "leaf_matches": [{"reason": "官方 Order Management 页写明从 storefront、marketplace、ERP、EDI 等渠道捕获订单后，由路由引擎先按 priority rules and filters 决定优先级，再以实时库存筛除无法履约的仓库，并按成本、距离与交付承诺排名选出履约地点；决策覆盖 warehouses、3PLs、stores 的统一候选池，支持跨地点拆分/合并，执行交由 StoreOps 或外部 WMS，并通过 connectors 把状态同步回渠道与 ERP；异常进入 Exception Resolution，Automation Engine 以无代码规则处理重路由、订单挂起与退货触发。符合“已捕获订单+可配置决策层+跨系统驱动执行+状态回传与订单级异常”的核心。", "slug": "order-orchestration-platform", "source_urls": ["https://pipe17.com", "https://pipe17.com/order-management/"]}], "name": "Pipe17", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:36:49.490435+08:00", "kind": "homepage", "sha256": "8cc7e88c9c2380d4f8138f14977e6a3ac3fadb8008e4b0e1f46b19cf61dae70e", "snapshot_path": "sources/8cc7e88c9c2380d4f8138f14977e6a3ac3fadb8008e4b0e1f46b19cf61dae70e.txt", "url": "https://pipe17.com"}, {"fetched_at": "2026-10-25T23:46:38.892307+08:00", "kind": "documentation", "sha256": "aa26d7491a2a2a8439f56db1a40b696a83194f26f17be5641c428c684a70787e", "snapshot_path": "sources/aa26d7491a2a2a8439f56db1a40b696a83194f26f17be5641c428c684a70787e.txt", "url": "https://pipe17.com/order-management/"}], "summary": "面向品牌与 3PL 的订单运营编排平台：接入销售渠道与履约系统，按成本/库存/承诺做路由并处理异常与状态回传。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:parcellab','parcelLab','{"homepage": "https://parcellab.com", "id": "commercial:parcellab", "leaf_matches": [{"reason": "官方首页定位为零售购后平台，提供订单跟踪、品牌化消息、退货与 WISMO 客服代理；以订单跟踪集中呈现客户可见的配送状态，并通过品牌化消息触达客户，符合“配送旅程记录+品牌化消费者界面+主动配送沟通”的基本形态。", "slug": "delivery-experience-platform", "source_urls": ["https://parcellab.com"]}], "name": "parcelLab", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:36:52.734760+08:00", "kind": "homepage", "sha256": "2362923140a89684bde39447cad3db5ee95cb2ebafe43173b31a3b80a9c3ae9b", "snapshot_path": "sources/2362923140a89684bde39447cad3db5ee95cb2ebafe43173b31a3b80a9c3ae9b.txt", "url": "https://parcellab.com"}], "summary": "购后配送体验平台：把承运商事件标准化为订单配送状态，在品牌自有页面展示并主动推送里程碑与异常通知。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fulfil','Fulfil','{"homepage": "https://www.fulfil.io/", "id": "commercial:fulfil", "leaf_matches": [{"reason": "官方页面把订单管理（Shopify/Amazon/TikTok Shop 等 20+ 渠道原生接入）、跨多仓库存管理（避免超卖）与仓库管理（''Full WMS''、条码扫描、批次拣货、波次释放、降低拣货差错）列在同一运营系统中，并支持按库存把订单路由到 3PL 发货，支持拆单发货；据此可证渠道订单、商户自有库存与仓库拣选、发货的执行主线，面单与追踪号生成未在页面明示。", "slug": "order-fulfillment-platform", "source_urls": ["https://www.fulfil.io/"]}], "name": "Fulfil", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:26.959029+08:00", "kind": "homepage", "sha256": "46d11009a4076e77678d9bb7216dd94545c3fd9067f3831d8d054f80cc412c15", "snapshot_path": "sources/46d11009a4076e77678d9bb7216dd94545c3fd9067f3831d8d054f80cc412c15.txt", "url": "https://www.fulfil.io/"}], "summary": "面向 DTC 与多渠道品牌的订单/库存运营系统，统一接入 Shopify、Amazon、TikTok Shop 等渠道订单，管理多仓库存并驱动仓库拣货与发货作业。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:loop-returns','Loop Returns','{"homepage": "https://loopreturns.com/returns/", "id": "commercial:loop-returns", "leaf_matches": [{"reason": "官方 /returns/ 页写明这是 ''an ecommerce returns portal that decides the right outcome automatically''，可 ''customize your return policy settings across different regions, warehouses, products''，并提供 exchanges、store credit、Instant Refund，以及多承运商、店内投递与 Happy Returns 无箱退货等退货方式；该页 FAQ 区块明确 ''Loop Returns is a self-service returns portal that automates your entire ecommerce returns process, from policy enforcement to resolution''；/faq/ 页可核 ''Our self-service portal manages returns and exchanges without support involvement'' 与 ''checks return eligibility''；官方文档进一步给出 ''Deep Link to a Customer Order in the Return Portal''，并说明 Process Return 会触发 refunds、exchanges、store credits，Flag 则阻止自动处理并转人工复核。据此可证购物者自助发起、政策判定、解决方案选择、退货方式与请求处理状态。购物者侧生命周期展示与礼品退货流程未在正文逐项说明，属证据缺口。", "slug": "returns-exchange-portal", "source_urls": ["https://www.loopreturns.com/returns/", "https://www.loopreturns.com/faq/", "https://www.loopreturns.com/", "https://docs.loopreturns.com/integration-guides/deep-link.md", "https://docs.loopreturns.com/integration-guides/return-actions.md"]}], "name": "Loop Returns", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:31.215096+08:00", "kind": "homepage", "sha256": "54209f066f7985642704d5b41ad00a98c899f9a777791b310f69d9609dddc791", "snapshot_path": "sources/54209f066f7985642704d5b41ad00a98c899f9a777791b310f69d9609dddc791.txt", "url": "https://www.loopreturns.com/returns/"}, {"fetched_at": "2026-10-25T23:40:34.414177+08:00", "kind": "documentation", "sha256": "6d6482db6528632fac99df8050ab890b708ddd9ae27fb9ca4da577de70f10f69", "snapshot_path": "sources/6d6482db6528632fac99df8050ab890b708ddd9ae27fb9ca4da577de70f10f69.txt", "url": "https://www.loopreturns.com/faq/"}, {"fetched_at": "2026-10-25T23:41:13.184731+08:00", "kind": "homepage", "sha256": "13456df66b5dbfc1a34f960df68dc1d54509a3ae5fc04d6e6080d42992004d0d", "snapshot_path": "sources/13456df66b5dbfc1a34f960df68dc1d54509a3ae5fc04d6e6080d42992004d0d.txt", "url": "https://www.loopreturns.com/"}, {"fetched_at": "2026-10-25T23:44:29.775670+08:00", "kind": "documentation", "sha256": "cc2da5ecf4ee1acedeea63f5ee7257cbd333d8d1f40dec0f3674a727dfd3d114", "snapshot_path": "sources/cc2da5ecf4ee1acedeea63f5ee7257cbd333d8d1f40dec0f3674a727dfd3d114.txt", "url": "https://docs.loopreturns.com/integration-guides/deep-link.md"}, {"fetched_at": "2026-10-25T23:44:29.332673+08:00", "kind": "documentation", "sha256": "9c871cfd5e9933281121e61c1d18aa4a5c5b3d53628824ac14a4ceedb1c1db49", "snapshot_path": "sources/9c871cfd5e9933281121e61c1d18aa4a5c5b3d53628824ac14a4ceedb1c1db49.txt", "url": "https://docs.loopreturns.com/integration-guides/return-actions.md"}], "summary": "面向电商品牌的退货换货门户：购物者自助发起退货或换货，按商家政策自动判定结果，支持换货、商店积分、即时退款与多种承运商/投递点退货方式。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:reverselogix','ReverseLogix','{"homepage": "https://www.reverselogix.com/platform/", "id": "commercial:reverselogix", "leaf_matches": [{"reason": "官方平台页描述 RMA 签发与面单、按 RMA 收货并按 SKU 标准检验分级、按规则分流至重新入库/翻新/维修/退供应商/清算，以及退款在承运商接管时释放并回写 ERP/WMS/商务平台；完整覆盖商家侧 RMA 队列、政策决策、财务结果与货物处置。", "slug": "returns-management-platform", "source_urls": ["https://www.reverselogix.com/platform/"]}], "name": "ReverseLogix", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:34.736844+08:00", "kind": "homepage", "sha256": "1f6870e8e858ce960cd20dedfa190ce5b6126d95e63a3db1434d951f46442e19", "snapshot_path": "sources/1f6870e8e858ce960cd20dedfa190ce5b6126d95e63a3db1434d951f46442e19.txt", "url": "https://www.reverselogix.com/platform/"}], "summary": "企业级退货管理平台：以 RMA 为工作记录处理退货、保修与维修，完成授权、收货检验、分级处置、退款释放与库存/ERP 回写。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:loyverse','Loyverse POS','{"homepage": "https://loyverse.com/en-us", "id": "commercial:loyverse", "leaf_matches": [{"reason": "官方页面说明可将智能手机或平板变为 POS，可管理商品（items）与客户、支持折扣与退款、打印/电子收据、离线继续记账，并可用手机 Tap to Pay 或读卡器收款，销售总额会自动发送到支付设备；设备由卖家携带、现场完成销售与收款，符合移动 POS 的核心工作流。首页未逐字展示卖家定价商品目录（价格/税率）与设备上组单计价的完整流程，属证据缺口。", "slug": "mobile-pos", "source_urls": ["https://loyverse.com/en-us"]}], "name": "Loyverse POS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:37.527951+08:00", "kind": "homepage", "sha256": "069f64210d3385388d95b46ed347684869dfe06227e7f178388cf5edd398a343", "snapshot_path": "sources/069f64210d3385388d95b46ed347684869dfe06227e7f178388cf5edd398a343.txt", "url": "https://loyverse.com/en-us"}], "summary": "免费移动 POS：在自有 iOS/Android 手机或平板上管理商品与客户、开单收款、打印或电子小票，并支持离线销售与卡支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:shopify-pos','Shopify POS','{"homepage": "https://www.shopify.com/pos", "id": "commercial:shopify-pos", "leaf_matches": [{"reason": "官方功能页逐项列出 Pickup in store（在 POS 直接管理与履行到店自提订单）、Buy in store and ship（店内成交后从任一有库存地点直发顾客）、Buy online, exchange and return in store（线上或他店购买可在店内换退并即时更新库存）、Ship from store 与 Local delivery（相关项标为 Pro）；首页 FAQ 也写明 buy online, pickup in store 与 buy in store, ship to customer。配合多地点库存实时同步、客户线上线下一体订单历史和线上线下通用礼品卡，统一商务状态与柜台跨渠道履约两条均具备。", "slug": "omnichannel-pos", "source_urls": ["https://www.shopify.com/pos", "https://www.shopify.com/pos/features"]}], "name": "Shopify POS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:39.930593+08:00", "kind": "homepage", "sha256": "924b97edf895fe83b187b9e5729ee0558643c6a0c8fd0768e221f03c22497112", "snapshot_path": "sources/924b97edf895fe83b187b9e5729ee0558643c6a0c8fd0768e221f03c22497112.txt", "url": "https://www.shopify.com/pos"}, {"fetched_at": "2026-10-24T14:30:43.512355+08:00", "kind": "documentation", "sha256": "48aec59ef1b255e6913a0848075dbe637eafce180b2ee1d6cfd49dad38b98496", "snapshot_path": "sources/48aec59ef1b255e6913a0848075dbe637eafce180b2ee1d6cfd49dad38b98496.txt", "url": "https://www.shopify.com/pos/features"}], "summary": "与 Shopify 线上商店共享目录、库存、客户与订单的门店 POS；官方功能页列出 POS 内履约到店自提、店内成交后直发顾客、线上或他店购买的门店换退，以及线上线下通用礼品卡。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:square-point-of-sale','Square Point of Sale','{"homepage": "https://squareup.com/us/en/point-of-sale", "id": "commercial:square-point-of-sale", "leaf_matches": [{"reason": "官方页面说明可创建商品项目或按自定义金额开单、现场与远程收款、库存管理、销售报表、定制小票与离线收款，构成商品目录→操作员组单→收款→完成交易记录的零售 POS 主线，并由门店自行操作。", "slug": "retail-point-of-sale", "source_urls": ["https://squareup.com/us/en/point-of-sale"]}], "name": "Square Point of Sale", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:47.077176+08:00", "kind": "homepage", "sha256": "645a76f66d26e6cc32d1914cb912229bb16abbb03fdcc01c4f86cf829571df83", "snapshot_path": "sources/645a76f66d26e6cc32d1914cb912229bb16abbb03fdcc01c4f86cf829571df83.txt", "url": "https://squareup.com/us/en/point-of-sale"}], "summary": "门店销售点应用：以商品目录开单、收款、打印或电子小票，并含库存管理、销售报表与离线收款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lightspeed-retail','Lightspeed Retail','{"homepage": "https://www.lightspeedhq.com/pos/retail/", "id": "commercial:lightspeed-retail", "leaf_matches": [{"reason": "首页 FAQ 写明可在同一平台 easily switch between their Lightspeed back offices、transfer inventory between locations、order stock for any location，并按整体或单店访问数据；中型商户页进一步写明 Transfer stock between stores、place orders for any location，以及 Set user specific access and role training to control what your staff see and learn、为多店/渠道/用户复制 workflows/settings/tasks。结合内置 POS 与销售/库存报表，形成门店范围记录、管理治理面与业绩回看的闭环。", "slug": "retail-store-management-system", "source_urls": ["https://www.lightspeedhq.com/pos/retail/", "https://www.lightspeedhq.com/pos/retail/midsize-business-pos/"]}], "name": "Lightspeed Retail", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:49.835722+08:00", "kind": "homepage", "sha256": "582ba3857d36ac1be3bf91977353b5e7c10d418074f799d0cd451b8647f06e36", "snapshot_path": "sources/582ba3857d36ac1be3bf91977353b5e7c10d418074f799d0cd451b8647f06e36.txt", "url": "https://www.lightspeedhq.com/pos/retail/"}, {"fetched_at": "2026-10-24T14:30:53.708059+08:00", "kind": "documentation", "sha256": "47c0660542637aaa73cefc2704ebb581963597d687a8d0e64695e22e598d7092", "snapshot_path": "sources/47c0660542637aaa73cefc2704ebb581963597d687a8d0e64695e22e598d7092.txt", "url": "https://www.lightspeedhq.com/pos/retail/midsize-business-pos/"}], "summary": "多门店零售管理系统：在同一平台切换各店后台，管理商品与库存、跨店调拨与补货、员工访问权限与销售/库存报表，并内置 POS。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:yoobic','YOOBIC','{"homepage": "https://yoobic.com/", "id": "commercial:yoobic", "leaf_matches": [{"reason": "官方页面把 Task Management（任务下发、指导、照片验证）、Communications（定向、可衡量的沟通触达每个班次）与 audits/learning 并列为同一平台能力，并按角色和门店组织，覆盖定向工作项、定向运营沟通与执行状态汇总三类结构。", "slug": "store-operations-platform", "source_urls": ["https://yoobic.com/"]}], "name": "YOOBIC", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:30:56.090243+08:00", "kind": "homepage", "sha256": "dd6989cae3c61002c8eb5debbfd106b788242dfc360ff556d1c18017277a41a2", "snapshot_path": "sources/dd6989cae3c61002c8eb5debbfd106b788242dfc360ff556d1c18017277a41a2.txt", "url": "https://yoobic.com/"}], "summary": "零售门店运营平台：总部向门店定向下发任务与沟通，员工执行并上传照片证据，管理层查看执行与审核结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:taqtics','Taqtics','{"homepage": "https://taqtics.co/", "id": "commercial:taqtics", "leaf_matches": [{"reason": "官方页面写明 “Assign recurring or one-time work by store, role, user, schedule, and due time”，FAQ 重复同一指派维度；完成需 live responses、photo proof、comments 与 timestamps，提供按门店的完成率/准时率/待处理汇总，并把 overdue、repeat misses、pending proof 升级给经理。三个结构（按门店/角色/用户指派的执行者、定向工作项、带归属的完成记录与向上汇总）齐备。", "slug": "store-task-management", "source_urls": ["https://taqtics.co/checklist-software/retail-task-management/"]}], "name": "Taqtics", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:02.120214+08:00", "kind": "documentation", "sha256": "3d7fffbac1a7cd75b1b43ed18fd8fac774895b7d07672f442415a63750f6319d", "snapshot_path": "sources/3d7fffbac1a7cd75b1b43ed18fd8fac774895b7d07672f442415a63750f6319d.txt", "url": "https://taqtics.co/checklist-software/retail-task-management/"}], "summary": "多门店零售任务与检查执行软件：按门店、角色、用户、排期和截止时间派发周期性检查清单，要求照片等完成证据，并对逾期与遗漏升级跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sortly','Sortly','{"homepage": "https://www.sortly.com/", "id": "commercial:sortly", "leaf_matches": [{"reason": "官方功能页说明可按任意地点追踪库存、用应用内条码/二维码扫描加快盘点、设置低库存与日期提醒，并提供 Activity History 报表监控团队改动、以及按自定义筛选汇总数量与价值的库存报表；据此可证条目级地点记录、带归属的变动历史与实物清点三项。页面未展示盘点审批会话，属轻量实现。", "slug": "store-inventory-application", "source_urls": ["https://www.sortly.com/features/", "https://www.sortly.com/"]}], "name": "Sortly", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:17.497698+08:00", "kind": "homepage", "sha256": "819b7696d217fcc063aba75512b441ff69c062f3cdc5cf3d35d4ef43d1a514d2", "snapshot_path": "sources/819b7696d217fcc063aba75512b441ff69c062f3cdc5cf3d35d4ef43d1a514d2.txt", "url": "https://www.sortly.com/"}, {"fetched_at": "2026-10-24T14:31:23.013986+08:00", "kind": "documentation", "sha256": "88b4bca7945dd4859273e11115e0b1c0324d0704556bc2e249afc723528089da", "snapshot_path": "sources/88b4bca7945dd4859273e11115e0b1c0324d0704556bc2e249afc723528089da.txt", "url": "https://www.sortly.com/features/"}], "summary": "面向小企业的轻量库存应用：以带照片与自定义字段的商品条目记录数量，支持多地点/文件夹、条码盘点、低库存提醒与活动历史。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:oracle-retail-assortment-planning','Oracle Retail Assortment Planning','{"homepage": "https://oracle.com/retail/assortment-planning/", "id": "commercial:oracle-retail-assortment-planning", "leaf_matches": [{"reason": "Oracle Retail Assortment Planning Cloud Service 用户指南说明：计划以 Assortment Group 组织，由 Assortment Period（定义计划窗口）与 Cluster version（门店集群）共同构成时间与地点框架；Assortment Strategy 以 option counts、attribute mix 与对齐财务目标的销售预期定义组合广度，Assortment Fit 决定哪些 style-color 分配到哪些门店集群，Item Flow 为短生命周期商品制定周销售与收货计划。流程还要求对齐 MFP 目标、为入选商品规划采购数量（Planning Buy Quantity），并以销售单位、零售额、成本与毛利衡量，最后审批组合。四项定义属性均有官方正文。", "slug": "assortment-planning-application", "source_urls": ["https://docs.oracle.com/en/industries/retail/retail-assortment-planning-cloud-service/26.1.201.0/apcsu/to_2523introduction.htm", "https://docs.oracle.com/en/industries/retail/retail-assortment-planning-cloud-service/25.1.201.0/apcsu/to_assortment_planning.htm"]}], "name": "Oracle Retail Assortment Planning", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T23:45:18.701777+08:00", "kind": "documentation", "sha256": "606573b3411eaa7e6ea7bebf0f99ae449d0e13ef77ed4b1d8d4f25b9b515ea5f", "snapshot_path": "sources/606573b3411eaa7e6ea7bebf0f99ae449d0e13ef77ed4b1d8d4f25b9b515ea5f.txt", "url": "https://docs.oracle.com/en/industries/retail/retail-assortment-planning-cloud-service/26.1.201.0/apcsu/to_2523introduction.htm"}, {"fetched_at": "2026-10-25T23:45:42.638412+08:00", "kind": "documentation", "sha256": "ec6abc4cc3d8ca0af23f4293f526269b0d6877663939c2f8c0028d62604892a6", "snapshot_path": "sources/ec6abc4cc3d8ca0af23f4293f526269b0d6877663939c2f8c0028d62604892a6.txt", "url": "https://docs.oracle.com/en/industries/retail/retail-assortment-planning-cloud-service/25.1.201.0/apcsu/to_assortment_planning.htm"}], "summary": "Oracle 零售组合规划云服务：按组合周期/季节与门店集群规划商品组合的广度、本地化分配及单位与金额深度，对齐商品财务计划目标并审批后交给采购/补货执行。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:symphonyai-retail-cpg','SymphonyAI Retail CPG','{"homepage": "https://www.symphonyai.com/retail-cpg/", "id": "commercial:symphonyai-retail-cpg", "leaf_matches": [{"reason": "官方 Category Performance 页说明该服务面向品类经理，按周把销售、库存、促销与竞品数据汇入单一视图，回答“发生了什么、为什么、下一步做什么”，并给出按收入影响排序、带预计 ROI 的建议，由品类团队确认/批准；其品类管理术语页明确这类平台让零售商把商品品类作为战略业务单元管理，并列出对品类与结果做实时分析、绩效衡量与报告、制定并执行品类策略、端到端品类生命周期管理。零售页还要求组合选择与品类目标（category goals）对齐。据此，品类为管理单元、品类绩效记录、战略与目标、评估→解释→建议→批准的持续管理循环四项均有官方正文支撑。", "slug": "category-management-application", "source_urls": ["https://www.symphonyai.com/retail-cpg/category-performance/", "https://www.symphonyai.com/glossary/category-management", "https://www.symphonyai.com/retail-cpg/"]}], "name": "SymphonyAI Retail CPG", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:33.013768+08:00", "kind": "documentation", "sha256": "1c59c58d4a5290200c1479022c5353024b59119a52c3f08b8b57bc7343f8a2d9", "snapshot_path": "sources/1c59c58d4a5290200c1479022c5353024b59119a52c3f08b8b57bc7343f8a2d9.txt", "url": "https://www.symphonyai.com/retail-cpg/"}, {"fetched_at": "2026-10-24T14:31:34.593562+08:00", "kind": "documentation", "sha256": "b8d61835bebfb504ba04fd543820889d82b3789aeacec2975854617bb7b2ec93", "snapshot_path": "sources/b8d61835bebfb504ba04fd543820889d82b3789aeacec2975854617bb7b2ec93.txt", "url": "https://www.symphonyai.com/glossary/category-management"}, {"fetched_at": "2026-10-25T23:44:34.910426+08:00", "kind": "documentation", "sha256": "bf6a332d79327f1c99b0680abc9511ea8f2815bede004ab056a2a790e27b1e60", "snapshot_path": "sources/bf6a332d79327f1c99b0680abc9511ea8f2815bede004ab056a2a790e27b1e60.txt", "url": "https://www.symphonyai.com/retail-cpg/category-performance/"}], "summary": "零售/CPG 商品与品类智能套件：含品类绩效与 AI 助手、组合优化、定价与毛利管理、促销效果与货架执行等模块。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:oracle-retail-merchandising','Oracle Retail Merchandising','{"homepage": "https://oracle.com/retail/merchandising/", "id": "commercial:oracle-retail-merchandising", "leaf_matches": [{"reason": "官方页面说明该服务管理采购、分销、订单履约、库存与财务结账，支持按商品层级/商品组分配、供应商协议与折扣、成本/现价/毛利与未来价格事件可见性，以及审计各渠道销售交易中的缺失、重复或错误数据；对应商品主数据、采购收货与库存账本三类结构。", "slug": "retail-merchandising-platform", "source_urls": ["https://www.oracle.com/retail/merchandising/"]}], "name": "Oracle Retail Merchandising", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:36.161027+08:00", "kind": "documentation", "sha256": "eac9f999c3f5d95383ada2180cf42865dfd1ef406ddd8e5e1bacb596ff858344", "snapshot_path": "sources/eac9f999c3f5d95383ada2180cf42865dfd1ef406ddd8e5e1bacb596ff858344.txt", "url": "https://www.oracle.com/retail/merchandising/"}], "summary": "零售商商品管理后台：维护商品/供应商与采购、按层级与门店分配商品、管理成本与价格事件，并审计各渠道销售交易后进入财务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dotactiv','DotActiv','{"homepage": "https://dotactiv.com/", "id": "commercial:dotactiv", "leaf_matches": [{"reason": "官方空间规划页以货架与门店空间为规划对象，提供陈列图生成、陈列图分析器（实时空间检查与计算）、陈列图报表与高亮，并与集群、组合、楼层规划联动；可证“建模空间→陈列图（商品到位置）→受绩效数据影响”的核心。货架实测尺寸校验、门店级下发与合规核查未在页面明示，属证据缺口。", "slug": "retail-space-planning-application", "source_urls": ["https://dotactiv.com/space-planning-automation-software"]}], "name": "DotActiv", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:27.772066+08:00", "kind": "documentation", "sha256": "bc92b8c758ba705a88d1a7583cd4f0a4c6bac0a5a47d0e6097d34d70ff5334ce", "snapshot_path": "sources/bc92b8c758ba705a88d1a7583cd4f0a4c6bac0a5a47d0e6097d34d70ff5334ce.txt", "url": "https://dotactiv.com/assortment-planning-software"}, {"fetched_at": "2026-10-24T14:31:29.869700+08:00", "kind": "documentation", "sha256": "5e659a380a1c31d9f0725dd8c81c4f3133faf1c5aa255518ee321874def91a2a", "snapshot_path": "sources/5e659a380a1c31d9f0725dd8c81c4f3133faf1c5aa255518ee321874def91a2a.txt", "url": "https://dotactiv.com/space-planning-automation-software"}], "summary": "零售商品组合与空间规划套件：以门店集群做本地化品类与货架规划，生成并分析陈列图，评估组合调整对空间与财务指标的影响。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:7learnings','7Learnings','{"homepage": "https://7learnings.com/", "id": "commercial:7learnings", "leaf_matches": [{"reason": "官方清仓用例页说明其为每个商品确定“确保按时清仓的最低必要折扣”、在保留毛利的同时消除滞销库存，可从首次降价走到最终清仓，并可对折扣深度与时间窗做情景比较；永久降价+分步降价计划+按售罄进度的决策循环三项结构均有对应。", "slug": "markdown-optimization-application", "source_urls": ["https://7learnings.com/use-cases-markdown-clearance-optimization/"]}], "name": "7Learnings", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:43.107246+08:00", "kind": "homepage", "sha256": "02bf4b7362e5cb3afa7ce6d1b70d9bafceda788b09f6874f3fce31583784460f", "snapshot_path": "sources/02bf4b7362e5cb3afa7ce6d1b70d9bafceda788b09f6874f3fce31583784460f.txt", "url": "https://7learnings.com/use-cases-markdown-clearance-optimization/"}], "summary": "面向零售的 AI 定价平台，专注降价与清仓优化：以需求预测确定按期清仓所需的最低折扣，并支持折扣深度与时间窗的情景比较。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:voucherify','Voucherify','{"homepage": "https://voucherify.io/", "id": "commercial:voucherify", "leaf_matches": [{"reason": "官方促销引擎页列出 BOGO、bundles、auto-applied discounts、strikethrough pricing 等机制，可按 segments、products、channels、dates 定向，提供预算与兑换上限、叠加/优先级规则；官方文档另证审批请求（Enterprise 计划，需申请）使受限用户的创建/更新须经审批后才生效并保留请求状态，Performance analytics 提供兑换量、收入影响（折扣金额）、活动排行等效果监测，但不含基线 ROI 报表。覆盖促销记录（机制+范围+有效期）、受治理生命周期与效果衡量。", "slug": "promotion-management", "source_urls": ["https://www.voucherify.io/promotion-engine", "https://docs.voucherify.io/manage/approval-requests", "https://docs.voucherify.io/analyze/performance-analytics"]}], "name": "Voucherify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:45.360337+08:00", "kind": "documentation", "sha256": "026347c3fbde9a833b117c4321408d9956632fee5d1ff27e8d683b33220d7857", "snapshot_path": "sources/026347c3fbde9a833b117c4321408d9956632fee5d1ff27e8d683b33220d7857.txt", "url": "https://www.voucherify.io/promotion-engine"}, {"fetched_at": "2026-10-25T23:53:11.596912+08:00", "kind": "documentation", "sha256": "f225de79c59fda7762507f75d856dad0f6293ae55284de74187541c309cf8665", "snapshot_path": "sources/f225de79c59fda7762507f75d856dad0f6293ae55284de74187541c309cf8665.txt", "url": "https://docs.voucherify.io/manage/approval-requests"}, {"fetched_at": "2026-10-25T23:53:11.732094+08:00", "kind": "documentation", "sha256": "6791029d4ce19e2473779aa148e9e228b2d3243f9b250af41940051fbaeead7c", "snapshot_path": "sources/6791029d4ce19e2473779aa148e9e228b2d3243f9b250af41940051fbaeead7c.txt", "url": "https://docs.voucherify.io/analyze/performance-analytics"}], "summary": "API 优先的促销引擎：按规则自动应用折扣，支持 BOGO、捆绑、买赠、优惠码等机制，可按细分/商品/渠道/日期定向，含审批请求、预算上限与效果分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:oracle-retail-price-management','Oracle Retail Price Management','{"homepage": "https://docs.oracle.com/en/industries/retail/retail-pricing-cloud/latest/", "id": "commercial:oracle-retail-price-management", "leaf_matches": [{"reason": "官方文档说明价格变更是对商品常规零售价的永久变更，需指定商品、区域或门店、变更方式（百分比/金额/新固定价）、生效日期与可选原因码，须经检查并按角色推进提交/审批状态，获批事件在生效日前即下发到下游票签与销售地点；实施指南并称 RPM 是所有零售定价的记录系统。Retail Pricing Cloud Service 产品文档首页亦确认其提供价格变更、清仓与促销的定义、维护与审阅。", "slug": "retail-pricing-management", "source_urls": ["https://docs.oracle.com/en/industries/retail/retail-pricing-cloud/latest/", "https://docs.oracle.com/en/industries/retail/retail-pricing-cloud/latest/rprpc/price-change-overview.htm", "https://docs.oracle.com/cd/E12440_01/rpm/pdf/160/html/implementation_guide/RPM.htm"]}], "name": "Oracle Retail Price Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T23:52:19.440639+08:00", "kind": "documentation", "sha256": "b4595f15f79835d0ea526ed82ceacb40c38011e5cb8a9fa43284be87ba487d85", "snapshot_path": "sources/b4595f15f79835d0ea526ed82ceacb40c38011e5cb8a9fa43284be87ba487d85.txt", "url": "https://docs.oracle.com/en/industries/retail/retail-pricing-cloud/latest/"}, {"fetched_at": "2026-10-24T14:31:37.799864+08:00", "kind": "documentation", "sha256": "4ab1414b98c6b71b45aed5d8f6804dcc65fbbb9a3d454a6bbaf1cd9c2905fb74", "snapshot_path": "sources/4ab1414b98c6b71b45aed5d8f6804dcc65fbbb9a3d454a6bbaf1cd9c2905fb74.txt", "url": "https://docs.oracle.com/en/industries/retail/retail-pricing-cloud/latest/rprpc/price-change-overview.htm"}, {"fetched_at": "2026-10-24T14:31:39.726191+08:00", "kind": "documentation", "sha256": "c0ea4bf2b2ae6a330f7500f79ea195dccf451b3c2e254912eb1b88540cd4f815", "snapshot_path": "sources/c0ea4bf2b2ae6a330f7500f79ea195dccf451b3c2e254912eb1b88540cd4f815.txt", "url": "https://docs.oracle.com/cd/E12440_01/rpm/pdf/160/html/implementation_guide/RPM.htm"}], "summary": "零售定价管理系统：作为全部零售价格的记录系统，按商品与价格区域/门店创建带生效日期的永久价格变更，经检查与审批后提前下发至 POS、电商等销售系统。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:square-gift-cards','Square Gift Cards','{"homepage": "https://squareup.com/us/en/gift-cards", "id": "commercial:square-gift-cards", "leaf_matches": [{"reason": "官方页面说明可创建并发行实体与数字礼品卡、按任意支付方式兑换、顾客可自行查询余额并充值、退款可退回礼品卡作为商店积分，且与 Square POS 同步计入报表；可证标识化卡凭证、商户计划下发行与按余额扣减兑换。逐卡余额活动明细、有效期与未偿负债报表未在页面展开，属证据缺口。", "slug": "gift-card-management", "source_urls": ["https://squareup.com/us/en/gift-cards"]}], "name": "Square Gift Cards", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:47.708151+08:00", "kind": "documentation", "sha256": "cf6f5074d16b2e7b5279cd280e9314bf9f638c6209dfcae7ab5fdaf3e4de9449", "snapshot_path": "sources/cf6f5074d16b2e7b5279cd280e9314bf9f638c6209dfcae7ab5fdaf3e4de9449.txt", "url": "https://squareup.com/us/en/gift-cards"}], "summary": "商户礼品卡计划：发行实体卡与电子礼品卡，按面值或自定义金额售出，可在 POS 或线上商店按余额兑换、查询余额并充值。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:loyaltylion','LoyaltyLion','{"homepage": "https://loyaltylion.com/", "id": "commercial:loyaltylion", "leaf_matches": [{"reason": "官方平台页列出账户注册、生日、购买、推荐、写评价、社交关注等赚取行为，以及免费商品、折扣券、免运费等兑换选项，并提供 Flexible rewards、VIP tiers 与自定义规则/实时购买行为分析；覆盖品牌配置的赚取与兑换规则、会员积分累积及兑换。", "slug": "loyalty-program-management", "source_urls": ["https://loyaltylion.com/", "https://loyaltylion.com/platform"]}], "name": "LoyaltyLion", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:49.545377+08:00", "kind": "homepage", "sha256": "72c1fc5667d6c28cc3098b79cec2a689458470d2e4e4cb1261782719643fed2e", "snapshot_path": "sources/72c1fc5667d6c28cc3098b79cec2a689458470d2e4e4cb1261782719643fed2e.txt", "url": "https://loyaltylion.com/"}, {"fetched_at": "2026-10-24T14:31:51.436906+08:00", "kind": "documentation", "sha256": "d7f059de14003e3d558f0a131b5ffd99b6e20852b51bd5f6c92a303f5dd178ce", "snapshot_path": "sources/d7f059de14003e3d558f0a131b5ffd99b6e20852b51bd5f6c92a303f5dd178ce.txt", "url": "https://loyaltylion.com/platform"}], "summary": "面向电商品牌的忠诚度计划平台：配置积分与奖励规则，对购买及注册、推荐、评价等行为累积积分，并提供 VIP 等级与兑换选项。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:woocommerce-store-credit','Store Credit for WooCommerce','{"homepage": "https://woocommerce.com/products/store-credit/", "id": "commercial:woocommerce-store-credit", "leaf_matches": [{"reason": "官方扩展页说明为每位顾客建立余额，可由礼品卡、退款保留在店内或补偿发放进入，顾客可跨多个订单消费直至用完或过期，结账与我的账户显示可用余额，余额不足时以其他支付方式补足；客户余额记录、商户主导且分来源的发放、作为支付手段的部分兑换均有正文。页面未展示独立的余额变动流水或未偿负债报表，仅说明已用积分进入 WooCommerce REST API 订单数据。", "slug": "store-credit-stored-value-platform", "source_urls": ["https://woocommerce.com/products/store-credit/"]}], "name": "Store Credit for WooCommerce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:53.460514+08:00", "kind": "documentation", "sha256": "674917c654270e729fbc8a283c692035ca67c5dad9aead07c01d7e5315f11b1c", "snapshot_path": "sources/674917c654270e729fbc8a283c692035ca67c5dad9aead07c01d7e5315f11b1c.txt", "url": "https://woocommerce.com/products/store-credit/"}], "summary": "WooCommerce 商店积分扩展：为每位顾客维护可跨订单消费的余额，用于礼品卡、退款转积分与补偿发放，并可在结账时抵扣。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:skio','Skio','{"homepage": "https://skio.com/", "id": "commercial:skio", "leaf_matches": [{"reason": "官方帮助中心 Subscription Management 的 Markdown 正文（2026-09-24 更新）说明订阅卡记录客户姓名/邮箱/收货地址、商品与数量、频率、下次扣款日、状态、时间线与订单历史，可查看即将扣款日期并执行跳过、暂停、取消、换品、单品跳过、合并/拆分、改期与改频；Get now 立即处理下一订单，View order 在 Shopify 打开关联订单。Orders 文档区分首单与 Recurring order，订单详情含商品、金额、收货地址并可跳转 Shopify；Auto-Merge Billing 文档说明同一客户的多笔订阅订单在发送 Shopify 前合并并按合并日计费。据此，订阅承诺记录、下次扣款日/订单历史、逐周期订单与 Shopify 移交、承诺生命周期管理均有官方正文；页面未展示多月未来订单队列或预测订单数据的完整界面。", "slug": "recurring-commerce-management", "source_urls": ["https://skio.com/", "https://help.skio.com/docs/subscription-management.md", "https://help.skio.com/docs/orders-1.md", "https://help.skio.com/docs/auto-merge-billing.md"]}], "name": "Skio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:56.369641+08:00", "kind": "homepage", "sha256": "f3bb76237757b651878d63969c6334deb24b308d4235ae212ddee305662c53ed", "snapshot_path": "sources/f3bb76237757b651878d63969c6334deb24b308d4235ae212ddee305662c53ed.txt", "url": "https://skio.com/"}, {"fetched_at": "2026-10-26T00:03:34.726523+08:00", "kind": "documentation", "sha256": "1965d5b54a672eb8036638b0e7179b59012c6743122c1ab87300fab43bccdc1f", "snapshot_path": "sources/1965d5b54a672eb8036638b0e7179b59012c6743122c1ab87300fab43bccdc1f.txt", "url": "https://help.skio.com/docs/subscription-management.md"}, {"fetched_at": "2026-10-25T23:53:16.127018+08:00", "kind": "documentation", "sha256": "d7f92a71a6aab1d7f3f9d85a4034e0ba4a6628c6e3c779e765757d144a9cd199", "snapshot_path": "sources/d7f92a71a6aab1d7f3f9d85a4034e0ba4a6628c6e3c779e765757d144a9cd199.txt", "url": "https://help.skio.com/docs/orders-1.md"}, {"fetched_at": "2026-10-25T23:53:16.193051+08:00", "kind": "documentation", "sha256": "0a589b38257be243cd39b63a2ffb17c4e3ef49923b484b154bb72ed036a561ca", "snapshot_path": "sources/0a589b38257be243cd39b63a2ffb17c4e3ef49923b484b154bb72ed036a561ca.txt", "url": "https://help.skio.com/docs/auto-merge-billing.md"}], "summary": "面向 Shopify 品牌的订阅平台：以订阅卡管理客户、商品、频率、下次扣款日、状态与收货地址，支持跳过、暂停、取消、换品、合并/拆分与改期，并将订阅订单数据移交 Shopify。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:woocommerce-subscriptions','WooCommerce Subscriptions','{"homepage": "https://woocommerce.com/products/woocommerce-subscriptions/", "id": "commercial:woocommerce-subscriptions", "leaf_matches": [{"reason": "官方扩展页说明顾客可按周/月/年订阅并自动周期性付款，续订失败可自动重试扣款，订阅者可在账户内暂停/取消、升级或降级并更新收货地址与支付方式，商家可调整续订总额与状态；覆盖订阅承诺、周期执行（扣款与续订）及承诺生命周期管理。", "slug": "subscription-commerce-platform", "source_urls": ["https://woocommerce.com/products/woocommerce-subscriptions/"]}], "name": "WooCommerce Subscriptions", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:31:59.587545+08:00", "kind": "documentation", "sha256": "30b9009f76b480d8fdc03cc85191f91f67e38a5ff93fc3f4fe546b00d0fc2a8b", "snapshot_path": "sources/30b9009f76b480d8fdc03cc85191f91f67e38a5ff93fc3f4fe546b00d0fc2a8b.txt", "url": "https://woocommerce.com/products/woocommerce-subscriptions/"}], "summary": "WooCommerce 订阅扩展：按周/月/年周期自动扣款并生成续订，支持失败重试、订阅者自助暂停/取消/升降级与收货地址维护。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1067194123','Bagisto B2B Ecommerce','{"deployment": ["作为 Bagisto 插件安装（需 Bagisto v2.5.x、PHP 8.4+）", "官方提供 b2b-suite:install 安装命令与预构建主题资源；本次未部署或运行"], "features": ["公司注册、管理员审批与公司资料管理", "公司多用户、角色与细粒度权限控制", "按公司定制商品目录与固定/百分比/阶梯定价", "公司信用额度、审计台账与 Pay By Credit 结算", "采购订单、询价/报价与快速下单、请购清单"], "github_repository_id": 1067194123, "homepage": "https://bagisto.com/", "id": "github:1067194123", "leaf_matches": [{"reason": "官方 README 说明公司可注册组织并经管理员审批、管理多用户与角色权限，管理员可按公司配置 Company Catalogs 的产品可见性与差异化定价、信用额度与 Pay By Credit 结算，并支持采购订单、询价与快速下单；组织账户层、目录→购物车→订单核心与账户中介的定价/结算三点齐备。", "slug": "b2b-e-commerce-platform", "source_urls": ["https://raw.githubusercontent.com/bagisto/b2b-ecommerce/master/README.md", "https://api.github.com/repos/bagisto/b2b-ecommerce"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/bagisto/b2b-ecommerce/license", "name": "Bagisto B2B Ecommerce", "repository_url": "https://github.com/bagisto/b2b-ecommerce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:32:00.896701+08:00", "kind": "repository_metadata", "sha256": "1a45ab0c8ad6d888f23a4475c61fad7b029a8f2daff47fa223c1164984f3fa48", "snapshot_path": "sources/1a45ab0c8ad6d888f23a4475c61fad7b029a8f2daff47fa223c1164984f3fa48.txt", "url": "https://api.github.com/repos/bagisto/b2b-ecommerce"}, {"fetched_at": "2026-10-24T14:32:02.392975+08:00", "kind": "license", "sha256": "7446b10eca13bcfe0bcc50d6d54e39ca46cf83c8051ca9dbc24108580e0ce089", "snapshot_path": "sources/7446b10eca13bcfe0bcc50d6d54e39ca46cf83c8051ca9dbc24108580e0ce089.txt", "url": "https://api.github.com/repos/bagisto/b2b-ecommerce/license"}, {"fetched_at": "2026-10-24T14:32:03.641972+08:00", "kind": "readme", "sha256": "00a8abc0cf0a963f7a08ddec32d9a3b5cc65462dd72e22cf88e8d1bcef5af89b", "snapshot_path": "sources/00a8abc0cf0a963f7a08ddec32d9a3b5cc65462dd72e22cf88e8d1bcef5af89b.txt", "url": "https://raw.githubusercontent.com/bagisto/b2b-ecommerce/master/README.md"}], "summary": "构建在 Bagisto 电商平台之上的开源 B2B 商务套件：企业注册与审批、公司多用户与角色权限、按公司定制目录与价格、信用额度与采购订单、询价与快速下单，MIT 许可，可自托管。", "technology_stack": ["PHP（Laravel）", "Bagisto 电商平台", "Vue / Tailwind CSS"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:orderwerks','Orderwerks','{"homepage": "https://www.orderwerks.com/", "id": "commercial:orderwerks", "leaf_matches": [{"reason": "官方经销商门户页说明每个经销商拥有独立账号，按账号看到自己的议价价格与专属目录并下单，卖方审核后才发货，批准订单自动推送 QuickBooks，三个定义性结构均被正文直接描述。", "slug": "dealer-distributor-commerce-portal", "source_urls": ["https://www.orderwerks.com/solutions/dealer-portal", "https://www.orderwerks.com/features/b2b-ecommerce-portal"]}], "name": "Orderwerks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:05:50.846779+08:00", "kind": "homepage", "sha256": "04b57395cddf0a8910957879e569d1994343f0970cbfe7e32bd2a7e26cd73a45", "snapshot_path": "sources/04b57395cddf0a8910957879e569d1994343f0970cbfe7e32bd2a7e26cd73a45.txt", "url": "https://www.orderwerks.com/solutions/dealer-portal"}, {"fetched_at": "2026-10-24T15:19:14.275334+08:00", "kind": "documentation", "sha256": "fd45717f1c0490891520d73c55996f6a6a9df7148ef9229d2e8094056e83a3c6", "snapshot_path": "sources/fd45717f1c0490891520d73c55996f6a6a9df7148ef9229d2e8094056e83a3c6.txt", "url": "https://www.orderwerks.com/features/b2b-ecommerce-portal"}], "summary": "面向制造商与分销商的 B2B 订货平台：经销商以独立账户登录卖方品牌门户，只看到分配给自己的目录与合同价，提交的订单先由卖方审核再进入 QuickBooks 开票与履约。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3314','Spree Commerce','{"deployment": ["官方 quickstart 提供 npx create-spree-app 本地与自托管启动，需要 Node.js 24+ 与 Docker"], "features": ["价格表与数量阶梯定价，客户组与公司账户携带地点、联系人与免税设置", "按客户细分配置目录（catalogs），门店可仅对已批准买家开放", "订单、支付、发货、税费与库存构成统一履约流程", "提供 REST API 与 TypeScript SDK，可自托管并接入既有 ERP/PIM"], "github_repository_id": 3314, "homepage": "https://spreecommerce.org", "id": "github:3314", "leaf_matches": [{"reason": "README 的 B2B & Wholesale 用例明确列出按客户细分的 price lists 与数量阶梯、customer groups、companies、按细分目录（catalogs）以及仅对已批准买家开放的门店，配合仓库核心的订单、支付、发货、税费与库存，构成受控企业买家账户、按账户价格/目录与 B2B 订单生命周期。", "slug": "wholesale-commerce-platform", "source_urls": ["https://api.github.com/repos/spree/spree", "https://api.github.com/repos/spree/spree/license", "https://raw.githubusercontent.com/spree/spree/main/README.md"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/spree/spree/license", "name": "Spree Commerce", "repository_url": "https://github.com/spree/spree", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:04:14.000676+08:00", "kind": "repository_metadata", "sha256": "78f364e8ce02b324f91d09d72ca065312ed79d3e1208aded8a4ef7d92abb5f8a", "snapshot_path": "sources/78f364e8ce02b324f91d09d72ca065312ed79d3e1208aded8a4ef7d92abb5f8a.txt", "url": "https://api.github.com/repos/spree/spree"}, {"fetched_at": "2026-10-24T15:04:31.386922+08:00", "kind": "license", "sha256": "982bdded227bebcf9e82194c8c16e81102baea370bce82189a2f739f3fef378f", "snapshot_path": "sources/982bdded227bebcf9e82194c8c16e81102baea370bce82189a2f739f3fef378f.txt", "url": "https://api.github.com/repos/spree/spree/license"}, {"fetched_at": "2026-10-24T15:20:05.389147+08:00", "kind": "readme", "sha256": "ecf54692e06fe80583235ece128b7d57aef7ad9fbf9b16fc335baa16c61111d7", "snapshot_path": "sources/ecf54692e06fe80583235ece128b7d57aef7ad9fbf9b16fc335baa16c61111d7.txt", "url": "https://raw.githubusercontent.com/spree/spree/main/README.md"}], "summary": "BSD-3-Clause 开源商务平台，社区核心含批发/B2B 能力：价格表与数量阶梯、客户组与公司账户、按细分目录与仅对已批准买家开放的门店，订单进入统一履约流程。", "technology_stack": ["Ruby（仓库 metadata 主要语言）", "Node.js 与 TypeScript（官方 storefront 与 admin）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:selloff-auction','Selloff','{"homepage": "https://www.selloff.auction", "id": "commercial:selloff-auction", "leaf_matches": [{"reason": "官方首页与功能页按卖方运营视角列出委托（consignments）、拍品编目（lot descriptions、estimates & reserves）、场次与出价、成交结果、买家发票与付款、委托人结算（consignor settlements）及运输，覆盖拍品→场次→出价→成交→双边结算的主干。", "slug": "auction-management-system", "source_urls": ["https://www.selloff.auction", "https://www.selloff.auction/features"]}], "name": "Selloff", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:05:53.914222+08:00", "kind": "homepage", "sha256": "2e5a03dc668c7dba6233725d40dbf3d6389c07e219e49aa209a4e687b938f8dc", "snapshot_path": "sources/2e5a03dc668c7dba6233725d40dbf3d6389c07e219e49aa209a4e687b938f8dc.txt", "url": "https://www.selloff.auction"}, {"fetched_at": "2026-10-24T15:05:56.664649+08:00", "kind": "documentation", "sha256": "017bd4dbf85f779d9514fb427e71ebcb042addfadfa348976533956bd8fd96b2", "snapshot_path": "sources/017bd4dbf85f779d9514fb427e71ebcb042addfadfa348976533956bd8fd96b2.txt", "url": "https://www.selloff.auction/features"}], "summary": "拍卖行运营端管理软件：从委托收货与签署文件、拍品编目与估价/保留价、场次与出价登记，到成交结果、买家发票收款、委托人结算与运输，统一在一个数据库中完成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:simpleconsign','SimpleConsign','{"homepage": "https://www.simpleconsign.com", "id": "commercial:simpleconsign", "leaf_matches": [{"reason": "官方功能页展示寄售人余额、按寄售人或品类设置的 consignment splits、逐件商品与寄售期、POS 归属销售、自动 ACH 支付以及寄售人门户，覆盖寄售人账户、寄售商品、佣金条款与归属销售/结算四个结构。", "slug": "consignment-management-platform", "source_urls": ["https://www.simpleconsign.com", "https://www.simpleconsign.com/features"]}], "name": "SimpleConsign", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:05:59.127040+08:00", "kind": "homepage", "sha256": "f7362789562eb38858a00a362bddddf496627395b795175087367f51ce8ec56d", "snapshot_path": "sources/f7362789562eb38858a00a362bddddf496627395b795175087367f51ce8ec56d.txt", "url": "https://www.simpleconsign.com"}, {"fetched_at": "2026-10-24T15:22:07.687095+08:00", "kind": "documentation", "sha256": "7d9667e2da47960863ec4b53ed62c712e9b8f0a71c9f38af3596c3f58d5e10a2", "snapshot_path": "sources/7d9667e2da47960863ec4b53ed62c712e9b8f0a71c9f38af3596c3f58d5e10a2.txt", "url": "https://www.simpleconsign.com/features"}], "summary": "寄售与转售门店管理系统：为每位寄售人维护账户与余额，逐件追踪商品及其寄售期与分成，POS 销售按商品归属计入寄售人，并支持批量/自动支付与寄售人自助查询。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:trove','Trove','{"homepage": "https://trove.com/", "id": "commercial:trove", "leaf_matches": [{"reason": "官方页面说明以旧换新与退货商品经鉴定、定价后进入品牌自有的转售站点与门店，退货/以旧换新按件处理并按状况路由，价值以礼品卡返还，符合单件供应、接收至可售转化、品牌运营转售面与价值闭环。", "slug": "recommerce-platform", "source_urls": ["https://trove.com/", "https://trove.com/resale-trade-in/"]}], "name": "Trove", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:06:01.127423+08:00", "kind": "homepage", "sha256": "6e0de88719ef5093cf30492b44a1366a86de12cb91ed7824ab020f27d9d552bb", "snapshot_path": "sources/6e0de88719ef5093cf30492b44a1366a86de12cb91ed7824ab020f27d9d552bb.txt", "url": "https://trove.com/"}, {"fetched_at": "2026-10-24T15:22:05.480372+08:00", "kind": "documentation", "sha256": "8975ba939a8e1d68f64e36fb972b0a19a24cf3338c2cfead170a1d5c094c5a53", "snapshot_path": "sources/8975ba939a8e1d68f64e36fb972b0a19a24cf3338c2cfead170a1d5c094c5a53.txt", "url": "https://trove.com/resale-trade-in/"}], "summary": "品牌二手转售与以旧换新运营平台：接收退货、以旧换新与过剩库存，完成鉴定、分级与定价，在品牌自有转售店面销售，并以礼品卡或积分把价值返还客户。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dsers','DSers','{"homepage": "https://www.dsers.com/", "id": "commercial:dsers", "leaf_matches": [{"reason": "官方首页与 AliExpress 集成文档说明供应商商品可导入卖家店铺、订单可批量自动提交给供应商、由供应商直发买家并把追踪号同步回店铺，形成供应源连接、自动化履行循环与状态回流。", "slug": "dropshipping-platform", "source_urls": ["https://www.dsers.com/", "https://www.dsers.com/en/integration/aliexpress-dropshipping-service"]}], "name": "DSers", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:06:03.739436+08:00", "kind": "homepage", "sha256": "b03ecb45df5a501d42f84fabf38791249f646107934fc87cc20b594ec34afa96", "snapshot_path": "sources/b03ecb45df5a501d42f84fabf38791249f646107934fc87cc20b594ec34afa96.txt", "url": "https://www.dsers.com/"}, {"fetched_at": "2026-10-24T15:22:12.648387+08:00", "kind": "documentation", "sha256": "01f38dd984d113f413e9d8eac533397efafca775b7d6f3c51d4d251425718b7e", "snapshot_path": "sources/01f38dd984d113f413e9d8eac533397efafca775b7d6f3c51d4d251425718b7e.txt", "url": "https://www.dsers.com/en/integration/aliexpress-dropshipping-service"}], "summary": "代发货运营平台：连接 AliExpress、1688、Alibaba 等供应商，把供应商商品发布为卖家自身上架，自动批量下单并由供应商直发终端客户，运单号与订单状态回写卖家店铺。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3961425','Easy Digital Downloads','{"deployment": ["作为 WordPress 插件安装并通过 Setup Wizard 配置，运行在自托管 WordPress 站点"], "features": ["创建绑定可下载文件的数字商品，支持变体、捆绑与不限商品数", "购买完成后自动生成安全下载链接，可设有效期与下载次数上限", "客户账户可查看历史订单并重新获取已购文件", "折扣码、退款处理与销售/收入报表"], "github_repository_id": 3961425, "homepage": "https://easydigitaldownloads.com", "id": "github:3961425", "leaf_matches": [{"reason": "README 明确该免费插件用于销售数字产品：可售任意文件类型、购买后自动发送安全且带有效期与次数限制的下载链接、客户账户可随时取回购买，并有退款与销售报表；软件许可与订阅被标注为 Pro 付费功能，未纳入社区核心能力。", "slug": "digital-download-commerce-platform", "source_urls": ["https://api.github.com/repos/awesomemotive/easy-digital-downloads", "https://api.github.com/repos/awesomemotive/easy-digital-downloads/license", "https://raw.githubusercontent.com/awesomemotive/easy-digital-downloads/main/readme.txt"]}, {"reason": "readme 显示数字商品目录、购物车结账、支付、唯一下载链接与下载限制、收据和收入报表，购买成功自动交付文件，覆盖数字商品电商核心。", "slug": "digital-product-commerce-platform", "source_urls": ["https://raw.githubusercontent.com/awesomemotive/easy-digital-downloads/main/readme.txt"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/awesomemotive/easy-digital-downloads/license", "name": "Easy Digital Downloads", "repository_url": "https://github.com/awesomemotive/easy-digital-downloads", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:04:15.773576+08:00", "kind": "repository_metadata", "sha256": "10d90a99950329ae060043f082b3cac6938c8ef8c1d5bd00dd25a281dd4a7206", "snapshot_path": "sources/10d90a99950329ae060043f082b3cac6938c8ef8c1d5bd00dd25a281dd4a7206.txt", "url": "https://api.github.com/repos/awesomemotive/easy-digital-downloads"}, {"fetched_at": "2026-10-24T15:04:33.955784+08:00", "kind": "license", "sha256": "d94691cac02b6a842ce69fb22c5479b791c6d968932487461868de7c1f80fadd", "snapshot_path": "sources/d94691cac02b6a842ce69fb22c5479b791c6d968932487461868de7c1f80fadd.txt", "url": "https://api.github.com/repos/awesomemotive/easy-digital-downloads/license"}, {"fetched_at": "2026-10-24T15:04:53.619411+08:00", "kind": "readme", "sha256": "9d0c5f15ad31c45ba39c796f87458213ef2cd7656f6f6bed71c909a5d199a8b4", "snapshot_path": "sources/9d0c5f15ad31c45ba39c796f87458213ef2cd7656f6f6bed71c909a5d199a8b4.txt", "url": "https://raw.githubusercontent.com/awesomemotive/easy-digital-downloads/main/readme.txt"}], "summary": "GPL-2.0 的 WordPress 数字商品商店插件，免费版即开源核心：商品绑定可下载文件，购买后自动生成带有效期与下载次数限制的安全链接；软件许可、订阅等属 Pro 付费扩展，未计入本例。", "technology_stack": ["PHP（仓库 metadata 主要语言）", "WordPress"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:790821454','Mercur','{"deployment": ["README 提供 bun create mercur-app 脚手架与本地自托管方式，依赖 PostgreSQL、Redis 与 Docker"], "features": ["运营方 Admin 面板维护卖家档案、卖家账户与店铺状态", "自助注册、邀请与成员邀请三种卖家入驻流程，账号状态含待审核/开放/暂停/终止", "按商品、类目、卖家配置佣金规则并生成结算与付款流程", "多卖家购物车与按卖家拆单，卖家面板管理自己的商品、订单与收款"], "github_repository_id": 790821454, "homepage": "https://www.mercurjs.com/", "id": "github:790821454", "leaf_matches": [{"reason": "README 与官方功能页说明运营方 Admin 面板管理卖家目录、卖家账户与店铺状态（pending_approval/open/suspended/terminated），卖家经自助或邀请入驻，佣金规则与结算按卖家配置，符合卖家记录群体、运营方受管状态门禁与按卖家商业管理。", "slug": "marketplace-seller-management", "source_urls": ["https://api.github.com/repos/mercurjs/mercur", "https://api.github.com/repos/mercurjs/mercur/license", "https://raw.githubusercontent.com/mercurjs/mercur/main/README.md", "https://www.mercurjs.com/features"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/mercurjs/mercur/license", "name": "Mercur", "repository_url": "https://github.com/mercurjs/mercur", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:04:18.744730+08:00", "kind": "repository_metadata", "sha256": "eacca81596e2337f0472eddbb7ff731acbeb41145d45724baf0b8965ebb55e40", "snapshot_path": "sources/eacca81596e2337f0472eddbb7ff731acbeb41145d45724baf0b8965ebb55e40.txt", "url": "https://api.github.com/repos/mercurjs/mercur"}, {"fetched_at": "2026-10-24T15:04:37.895006+08:00", "kind": "license", "sha256": "418167178e27f0bbfbdbb5066369fa8babc618ba025133328deddae6ff08c577", "snapshot_path": "sources/418167178e27f0bbfbdbb5066369fa8babc618ba025133328deddae6ff08c577.txt", "url": "https://api.github.com/repos/mercurjs/mercur/license"}, {"fetched_at": "2026-10-24T15:04:55.303776+08:00", "kind": "readme", "sha256": "b6f4457485654159c4d16226282874b8503a1cac956e1aec3bd20cc6079e3d28", "snapshot_path": "sources/b6f4457485654159c4d16226282874b8503a1cac956e1aec3bd20cc6079e3d28.txt", "url": "https://raw.githubusercontent.com/mercurjs/mercur/main/README.md"}, {"fetched_at": "2026-10-24T15:21:01.623557+08:00", "kind": "documentation", "sha256": "f9752eb1c760a11cb02bff5646177bb5c6ee3cdaec012e3582c5bbe12f89c0b4", "snapshot_path": "sources/f9752eb1c760a11cb02bff5646177bb5c6ee3cdaec012e3582c5bbe12f89c0b4.txt", "url": "https://www.mercurjs.com/features"}], "summary": "MIT 开源多卖家市场平台（构建于 Medusa 之上）：运营方后台维护卖家档案与入驻状态、按卖家配置佣金与结算，并提供卖家面板；Enterprise 专属模块未计入本例。", "technology_stack": ["TypeScript（仓库 metadata 主要语言）", "Medusa 商务核心", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:global-e','Global-e','{"homepage": "https://www.global-e.com/", "id": "commercial:global-e", "leaf_matches": [{"reason": "官方平台页说明购物者按本地货币浏览支付、结账展示含关税与税费的保证最终价、按市场提供本地支付方式与国际配送，并由 Global-e 承担税务与进口合规，覆盖市场条件化体验与支付、订单承载边境义务。", "slug": "cross-border-commerce-platform", "source_urls": ["https://www.global-e.com/", "https://www.global-e.com/platform/"]}], "name": "Global-e", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T14:25:21.148792+08:00", "kind": "homepage", "sha256": "8fed0584c3c7816968f01c522855885951e503abf86958af92c41863141cb108", "snapshot_path": "sources/8fed0584c3c7816968f01c522855885951e503abf86958af92c41863141cb108.txt", "url": "https://www.global-e.com/"}, {"fetched_at": "2026-10-24T15:06:09.533153+08:00", "kind": "documentation", "sha256": "e7f91bca74ebf2e417d133bc983edb07f1b0992b1f9abfa7c0aef4100c31e1ff", "snapshot_path": "sources/e7f91bca74ebf2e417d133bc983edb07f1b0992b1f9abfa7c0aef4100c31e1ff.txt", "url": "https://www.global-e.com/platform/"}], "summary": "跨境销售平台（以 merchant of record 方式运营）：为商户按买家市场提供本地货币与本地支付结账、结账时保证含关税税费的最终价、本地化配送与合规处理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:shopify-markets','Shopify Markets','{"homepage": "https://shopify.com", "id": "commercial:shopify-markets", "leaf_matches": [{"reason": "官方 Markets 页与帮助中心说明市场是按位置/客户群/零售地点/渠道定义的受众，可按市场覆盖货币、语言、商品目录与定价、税费和配送，并由后台集中管理，符合以市场为配置对象、每市场销售主张与商务义务的核心。本批所读页面覆盖税费与配送；跨境关税/进口费代收未作为本例证据。", "slug": "international-commerce-management", "source_urls": ["https://www.shopify.com/markets", "https://help.shopify.com/en/manual/markets"]}], "name": "Shopify Markets", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:20:01.876374+08:00", "kind": "homepage", "sha256": "8d6f969b29b14e43819a66aa2a3acb2136ccd7fcd17eda2246b76cd5addf2501", "snapshot_path": "sources/8d6f969b29b14e43819a66aa2a3acb2136ccd7fcd17eda2246b76cd5addf2501.txt", "url": "https://www.shopify.com/markets"}, {"fetched_at": "2026-10-24T15:35:08.251505+08:00", "kind": "documentation", "sha256": "07a9df96fd225090d35d699058deda91abca3c223c9d5b683202e8936bbc828d", "snapshot_path": "sources/07a9df96fd225090d35d699058deda91abca3c223c9d5b683202e8936bbc828d.txt", "url": "https://help.shopify.com/en/manual/markets"}], "summary": "Shopify 的多市场管理能力：把国家/地区、客户群、零售地点或销售渠道定义为市场，按市场分别配置货币、语言、目录与定价、税费和配送，由系统按买家归属自动应用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:auror','Auror','{"homepage": "https://www.auror.co/", "id": "commercial:auror", "leaf_matches": [{"reason": "官方首页与 Auror Core 页说明事件以结构化字段上报、跨门店与零售商连接同一嫌疑人与车辆、以案件方式调查并共享证据给执法、并在网络层面输出洞察，符合类型化事件记录、受管响应工作流与资产级聚合。", "slug": "retail-loss-prevention-platform", "source_urls": ["https://www.auror.co/", "https://www.auror.co/auror-core"]}], "name": "Auror", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:50.142418+08:00", "kind": "homepage", "sha256": "ca6687548ad4fc44837011239c41c17481892347ac497e9ac437168162efe2bb", "snapshot_path": "sources/ca6687548ad4fc44837011239c41c17481892347ac497e9ac437168162efe2bb.txt", "url": "https://www.auror.co/"}, {"fetched_at": "2026-10-24T15:32:07.348148+08:00", "kind": "documentation", "sha256": "e065d35159b43fef29a6d2ce060a3181de9cd0266127f221e9db00de5d378ee8", "snapshot_path": "sources/e065d35159b43fef29a6d2ce060a3181de9cd0266127f221e9db00de5d378ee8.txt", "url": "https://www.auror.co/auror-core"}], "summary": "零售犯罪情报与防损平台：门店以结构化表单上报内外盗与安全事件，跨店与跨零售商关联嫌疑人和车辆，支持案件调查、证据留存与执法协作，并汇总为区域级洞察。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:amazon-ads','Amazon Ads（Sponsored Products）','{"homepage": "https://advertising.amazon.com", "id": "commercial:amazon-ads", "leaf_matches": [{"reason": "官方 Sponsored Products 页与帮助文档说明广告主创建活动时命名、设定起止日期、每日预算与出价，选择自动/关键词/商品定向后上线，预算按日强制执行，并可按活动查看曝光、点击、转化与 ROAS 报表，覆盖活动对象、真实投放、支出控制与归因反馈。", "slug": "advertising-campaign-management", "source_urls": ["https://advertising.amazon.com", "https://advertising.amazon.com/solutions/products/sponsored-products"]}], "name": "Amazon Ads（Sponsored Products）", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:16.756464+08:00", "kind": "homepage", "sha256": "4ba4ad2fd3992aa7e2534f461aec8e731a6c4caa56cccf05818a503aace38878", "snapshot_path": "sources/4ba4ad2fd3992aa7e2534f461aec8e731a6c4caa56cccf05818a503aace38878.txt", "url": "https://advertising.amazon.com"}, {"fetched_at": "2026-10-24T15:19:19.547722+08:00", "kind": "documentation", "sha256": "6fa5ad19c50c37327d259ac8d4e651bb5c917ce6b47b679ed93e15d351612f15", "snapshot_path": "sources/6fa5ad19c50c37327d259ac8d4e651bb5c917ce6b47b679ed93e15d351612f15.txt", "url": "https://advertising.amazon.com/solutions/products/sponsored-products"}], "summary": "广告主端自助广告平台：以广告活动为对象选择商品与定向、设置每日预算与出价并投放至 Amazon 及站外位置，活动数据回报花费、点击与转化，供持续调整。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lotame','Lotame Spherical','{"homepage": "https://www.lotame.com/", "id": "commercial:lotame", "leaf_matches": [{"reason": "官方首页与 Spherical 平台页说明可整合多来源数据、创建与建模受众细分、按目的地控制向 DSP 与媒体伙伴的激活与分发，符合多源数据→受管细分→对外交付，且不承担媒体购买或广告投放。", "slug": "data-management-platform-dmp", "source_urls": ["https://www.lotame.com/", "https://www.lotame.com/products/spherical-platform"]}, {"reason": "官方首页正文写明 Spherical 平台帮助营销人员 “connect, enrich, and activate audience data”，并逐项说明 Audience Creation & Modeling（以可信数据源、AI/机器学习和 lookalike 扩展受众）、First-Party Data Onboarding（连接碎片化营销与广告数据）、Identity Resolution & Activation（跨渠道与设备识别）；可证具名可定向受众、数据基础与向外激活的受管受众结构。", "slug": "audience-management-platform", "source_urls": ["https://www.lotame.com/"]}], "name": "Lotame Spherical", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:21.521692+08:00", "kind": "homepage", "sha256": "15bb4801047319e86de8b22dc372c979adaa01a9f82c2b9b8fb8b86b48bba707", "snapshot_path": "sources/15bb4801047319e86de8b22dc372c979adaa01a9f82c2b9b8fb8b86b48bba707.txt", "url": "https://www.lotame.com/"}, {"fetched_at": "2026-10-24T15:32:13.229393+08:00", "kind": "documentation", "sha256": "da9721e6a0944cd2fb8aa52b23cdbaf24089a1bfe85631b7d261345e67dfdedc", "snapshot_path": "sources/da9721e6a0944cd2fb8aa52b23cdbaf24089a1bfe85631b7d261345e67dfdedc.txt", "url": "https://www.lotame.com/products/spherical-platform"}, {"fetched_at": "2026-10-24T15:28:30.715915+08:00", "kind": "homepage", "sha256": "1a08edb7a6a8179362bdabc6be03a55e3ea0542706a7585d37c9e7e98d6f3661", "snapshot_path": "sources/1a08edb7a6a8179362bdabc6be03a55e3ea0542706a7585d37c9e7e98d6f3661.txt", "url": "https://www.lotame.com/"}], "summary": "广告侧受众数据平台：接入并整合第一方与合作伙伴数据，构建、丰富与管理受众细分，并向 DSP、媒体与其它目的地激活交付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:the-trade-desk','The Trade Desk','{"homepage": "https://www.thetradedesk.com", "id": "commercial:the-trade-desk", "leaf_matches": [{"reason": "官方 DSP 页说明其为数据驱动营销者的买方平台，接入开放互联网的跨渠道库存，按受众与数据定向、以 AI 实时评估广告机会并优化，提供成效测量，且明确不拥有也不运营媒体，符合买方、外部供给、竞价引擎与回报四要素。", "slug": "demand-side-platform-dsp", "source_urls": ["https://www.thetradedesk.com", "https://www.thetradedesk.com/our-demand-side-platform"]}], "name": "The Trade Desk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:45.306875+08:00", "kind": "homepage", "sha256": "67eaf44087325beb6773084d993f59f16cc63b754236963faa122396b83ff27a", "snapshot_path": "sources/67eaf44087325beb6773084d993f59f16cc63b754236963faa122396b83ff27a.txt", "url": "https://www.thetradedesk.com"}, {"fetched_at": "2026-10-24T15:19:47.737461+08:00", "kind": "documentation", "sha256": "40fbed1304b94a2dd0fb056523e0531e2cc1dd01802e54ecdc10576ccc6af135", "snapshot_path": "sources/40fbed1304b94a2dd0fb056523e0531e2cc1dd01802e54ecdc10576ccc6af135.txt", "url": "https://www.thetradedesk.com/our-demand-side-platform"}], "summary": "独立需求方平台：广告主与代理机构在开放互联网跨渠道程序化购买，按第一/第三方数据定向、实时竞价与优化，并回报投放与成效测量。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:celtra','Celtra','{"homepage": "https://celtra.com/", "id": "commercial:celtra", "leaf_matches": [{"reason": "官方首页与 Dynamic Product Ads 页说明以品牌模板套用整个商品目录自动生成大量动态商品广告，并按折扣、可用性等目录输入生成不同版式变体；页面列明支持 Meta、TikTok、Snapchat、Pinterest、X，且商品目录每小时刷新，符合参数化创意、数据驱动规则与规模化变体连接投放。", "slug": "dynamic-creative-optimization-platform", "source_urls": ["https://celtra.com/", "https://celtra.com/solution/dpa"]}], "name": "Celtra", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:24.798036+08:00", "kind": "homepage", "sha256": "15e0cb0baaf23f9a0e647d355df3143ff6098f2d51c38f7635ea8b7fd647bd88", "snapshot_path": "sources/15e0cb0baaf23f9a0e647d355df3143ff6098f2d51c38f7635ea8b7fd647bd88.txt", "url": "https://celtra.com/"}, {"fetched_at": "2026-10-24T15:32:09.246850+08:00", "kind": "documentation", "sha256": "4c6fa7e1853136818d899fe5f4aafc0808bf06943ad387a0fbe98a3fdae5ac5b", "snapshot_path": "sources/4c6fa7e1853136818d899fe5f4aafc0808bf06943ad387a0fbe98a3fdae5ac5b.txt", "url": "https://celtra.com/solution/dpa"}], "summary": "广告创意自动化与动态创意平台：以品牌模板套用商品目录批量生成动态商品广告，目录按小时刷新，按折扣与库存等目录输入生成不同版式变体，并可发布到 Meta、TikTok、Snapchat、Pinterest、X。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:bionic-ads','Bionic Advertising Systems','{"homepage": "https://www.bionic-ads.com/", "id": "commercial:bionic-ads", "leaf_matches": [{"reason": "官方首页与供应商账单对账页说明平台自动化媒体计划与购买流程、集中媒体计划/插入订单/投放绩效/账单/付款数据、跟踪各渠道投放表现，并以订单余额、服务期媒体估算与投放表现计算可结金额、对账供应商账单后推送至会计系统，覆盖计划记录、购买记录与账单/交付问责闭环。", "slug": "media-buying-platform", "source_urls": ["https://www.bionic-ads.com/", "https://www.bionic-ads.com/agencies/capabilities/reconciliations/"]}], "name": "Bionic Advertising Systems", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:27.338675+08:00", "kind": "homepage", "sha256": "862c2cf7e6e2b09b135905aae6e15ce3bde32385893876996a104740e6c066c5", "snapshot_path": "sources/862c2cf7e6e2b09b135905aae6e15ce3bde32385893876996a104740e6c066c5.txt", "url": "https://www.bionic-ads.com/"}, {"fetched_at": "2026-10-24T15:19:30.060768+08:00", "kind": "documentation", "sha256": "25f7683fb04440ce1c49e339a5e920e78d8a027860f413a44344233ed77f5a2e", "snapshot_path": "sources/25f7683fb04440ce1c49e339a5e920e78d8a027860f413a44344233ed77f5a2e.txt", "url": "https://www.bionic-ads.com/agencies/capabilities/reconciliations/"}], "summary": "代理机构媒体购买平台：集中媒体计划、插入订单、投放绩效、供应商账单与付款数据，跟踪各渠道投放表现，并按订单余额、服务期媒体估算与投放表现对账供应商账单后推送会计系统。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:magnite','Magnite','{"homepage": "https://www.magnite.com/", "id": "commercial:magnite", "leaf_matches": [{"reason": "官方首页与 Sellers 页说明媒体所有者用其 SSP 与 header bidding 软件变现展示、在线视频、音频、原生、数字户外与移动应用内库存，平台连接代理商、品牌与 DSP 等外部需求，提供基于实时市场信号的底价建议、收益优化以及从预测到实时绩效监控的洞察，符合媒体所有者、自动暴露需求与卖方规则。", "slug": "supply-side-platform-ssp", "source_urls": ["https://www.magnite.com/", "https://www.magnite.com/sellers/"]}], "name": "Magnite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:32.362945+08:00", "kind": "homepage", "sha256": "0678bd02528ac6f4cdea337e78d871141b20e188fe73456de0d07d2b0f509368", "snapshot_path": "sources/0678bd02528ac6f4cdea337e78d871141b20e188fe73456de0d07d2b0f509368.txt", "url": "https://www.magnite.com/"}, {"fetched_at": "2026-10-24T15:19:34.588406+08:00", "kind": "documentation", "sha256": "dc4ec6abec3fe5a0fdd720069080d083cce9ff8d667f3f24313200dba011d44d", "snapshot_path": "sources/dc4ec6abec3fe5a0fdd720069080d083cce9ff8d667f3f24313200dba011d44d.txt", "url": "https://www.magnite.com/sellers/"}], "summary": "独立卖方平台（SSP）：媒体所有者注册并组织库存，通过 SSP 与 header bidding 软件将展示、在线视频、音频、原生、数字户外与移动应用内库存变现，连接代理商、品牌与 DSP 等外部需求，并提供底价建议、收益优化与预测/实时绩效监控。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:optmyzr','Optmyzr','{"homepage": "https://www.optmyzr.com", "id": "commercial:optmyzr", "leaf_matches": [{"reason": "官方首页、预算管理与 Rule Engine 页说明平台连接多个搜索引擎账户，在同一工作区监控与调整预算和出价、按条件批量执行规则并输出报告，且改动最终写回引擎账户，符合跨账户管理层在引擎记录之上运营付费搜索。", "slug": "search-engine-marketing-management-platform", "source_urls": ["https://www.optmyzr.com", "https://www.optmyzr.com/solutions/budget-management", "https://www.optmyzr.com/solutions/rule-engine/"]}], "name": "Optmyzr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:19:40.648944+08:00", "kind": "homepage", "sha256": "14a0041a93144350c18c79927ba987471d5c19584fa23e953eb54b6799150201", "snapshot_path": "sources/14a0041a93144350c18c79927ba987471d5c19584fa23e953eb54b6799150201.txt", "url": "https://www.optmyzr.com"}, {"fetched_at": "2026-10-24T15:32:02.460396+08:00", "kind": "documentation", "sha256": "0ae4f84b3479686775c8a78ae7bf2faca008a8ca920cdb68fd00915e026ea516", "snapshot_path": "sources/0ae4f84b3479686775c8a78ae7bf2faca008a8ca920cdb68fd00915e026ea516.txt", "url": "https://www.optmyzr.com/solutions/budget-management"}, {"fetched_at": "2026-10-24T15:19:43.029002+08:00", "kind": "documentation", "sha256": "621637cc2c9fc617b05285d1216924be189e39b98884b441d8c3253a802b39de", "snapshot_path": "sources/621637cc2c9fc617b05285d1216924be189e39b98884b441d8c3253a802b39de.txt", "url": "https://www.optmyzr.com/solutions/rule-engine/"}], "summary": "第三方付费搜索管理平台：跨 Google、Microsoft、Amazon 等广告账户集中管理关键词、出价与预算，以规则引擎和预算监控执行优化，并汇总跨账户报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:465254307','SEOnaut','{"deployment": ["README 推荐以 docker compose 同时启动 MySQL 与应用镜像"], "features": ["自建爬虫扫描站点并记录页面属性", "按严重度（critical/high/low）归类 SEO 问题", "检测断链、重定向与循环、缺失或重复 meta 标签、标题层级错误", "提供 Docker 自托管部署与仪表盘"], "github_repository_id": 465254307, "homepage": "https://seonaut.org", "id": "github:465254307", "leaf_matches": [{"reason": "README 说明该工具对网站执行完整扫描并把发现的问题按 critical/high/low 分级生成报告，覆盖断链、重定向与循环、缺失或重复 meta 标签、标题层级错误，符合页面群体发现、规则评估与问题报告。", "slug": "seo-site-audit-application", "source_urls": ["https://api.github.com/repos/StJudeWasHere/seonaut", "https://api.github.com/repos/StJudeWasHere/seonaut/license", "https://raw.githubusercontent.com/StJudeWasHere/seonaut/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/StJudeWasHere/seonaut/license", "name": "SEOnaut", "repository_url": "https://github.com/StJudeWasHere/seonaut", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:04:20.253246+08:00", "kind": "repository_metadata", "sha256": "c79105630e9d55a00a01f4203c2554fa3bfb7479a1d60a6a939ee32ed98e9b9a", "snapshot_path": "sources/c79105630e9d55a00a01f4203c2554fa3bfb7479a1d60a6a939ee32ed98e9b9a.txt", "url": "https://api.github.com/repos/StJudeWasHere/seonaut"}, {"fetched_at": "2026-10-24T15:04:39.475919+08:00", "kind": "license", "sha256": "cd9b1937c8d47bbb06bd3ad966675626f4559e569c5fc4912ffeb53b50e0fdd7", "snapshot_path": "sources/cd9b1937c8d47bbb06bd3ad966675626f4559e569c5fc4912ffeb53b50e0fdd7.txt", "url": "https://api.github.com/repos/StJudeWasHere/seonaut/license"}, {"fetched_at": "2026-10-24T15:04:56.663599+08:00", "kind": "readme", "sha256": "a7ec866efc2b533235f27daab4c0a9adb6abadb0d9c51a240c0e142e30655577", "snapshot_path": "sources/a7ec866efc2b533235f27daab4c0a9adb6abadb0d9c51a240c0e142e30655577.txt", "url": "https://raw.githubusercontent.com/StJudeWasHere/seonaut/main/README.md"}], "summary": "MIT 开源 SEO 站点审计应用：从种子地址自行爬取站点页面，按 SEO 规则库检查断链、重定向、元标签与标题层级等问题，输出按严重度分