INSERT INTO "application" VALUES('github:32042787','phpList','{"deployment": ["README 支持部署在自有服务器，并提供 Docker 镜像；另有官方托管服务"], "features": ["订阅者与列表管理，支持属性、偏好与个性化占位符", "campaign 编排、排期、暂停/恢复与消息队列节流", "自动化退信处理并归档每条投递结果", "打开、点击与退订等实时统计，提供插件架构与 API"], "github_repository_id": 32042787, "homepage": "https://www.phplist.org", "id": "github:32042787", "leaf_matches": [{"reason": "README 说明其用于创建、发送、集成与分析 email campaigns 与 newsletters，含订阅者列表、内容个性化、退信处理、打开与点击等实时分析及队列节流，符合同意受众记录、活动、批量投递与按次测量。", "slug": "email-marketing-platform", "source_urls": ["https://api.github.com/repos/phpList/phplist3", "https://api.github.com/repos/phpList/phplist3/license", "https://raw.githubusercontent.com/phpList/phplist3/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/phpList/phplist3/license", "name": "phpList", "repository_url": "https://github.com/phpList/phplist3", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:24:57.110343+08:00", "kind": "repository_metadata", "sha256": "f324f88acae92edd14ddbf3adee67afa9c306d51c2200c850120207c7d07c74a", "snapshot_path": "sources/f324f88acae92edd14ddbf3adee67afa9c306d51c2200c850120207c7d07c74a.txt", "url": "https://api.github.com/repos/phpList/phplist3"}, {"fetched_at": "2026-10-24T14:50:01.284062+08:00", "kind": "license", "sha256": "879bfa92c095533227341abdd59a60ae8bd43265596af6f04394cc762ba3ea7b", "snapshot_path": "sources/879bfa92c095533227341abdd59a60ae8bd43265596af6f04394cc762ba3ea7b.txt", "url": "https://api.github.com/repos/phpList/phplist3/license"}, {"fetched_at": "2026-10-24T15:20:06.713824+08:00", "kind": "readme", "sha256": "2decbfbc252a39e83a7c51a996fa58c246bde0e13af523a41347bae66e492adb", "snapshot_path": "sources/2decbfbc252a39e83a7c51a996fa58c246bde0e13af523a41347bae66e492adb.txt", "url": "https://raw.githubusercontent.com/phpList/phplist3/main/README.md"}], "summary": "AGPL-3.0 开源自托管邮件营销系统：维护订阅者与列表，编排并批量发送 campaign，自动处理退信并跟踪打开与点击后输出统计。", "technology_stack": ["PHP（仓库 metadata 主要语言）", "MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:prowly','Prowly','{"homepage": "https://prowly.com/", "id": "commercial:prowly", "leaf_matches": [{"reason": "官方页面说明可按主题筛选记者档案、构建带受众与流量数据的定向媒体列表、直接向记者发送 pitch 并跟踪打开与互动、据互动安排跟进，符合媒体联系记录、媒体列表与可追踪发送三个结构。", "slug": "media-relations-platform", "source_urls": ["https://prowly.com/media-database/"]}, {"reason": "官方首页正文（HTML 文本节点，非仅 meta）四段逐字可证：AI-Cited Media Database（“Get a list of journalist profiles”“Build targeted media lists with audience and traffic data”）、Email Outreach and Analytics（“Send media pitches that get engagement”“Email journalists and track engagement”“Schedule follow-ups based on recipient behavior”“Automatically track which pitches earned media mentions”）、Media Monitoring（“Monitor online news, blogs, and forums”“Automatically filter out irrelevant and duplicate mentions”）、Strategic Intelligence & Benchmarking（“Benchmark your share of voice, sentiment, and reach against your competitors”）；媒体关系记录—外联—覆盖捕获与回链—报告四段连成公关管理闭环。", "slug": "public-relations-management-platform", "source_urls": ["https://prowly.com/"]}], "name": "Prowly", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:39.994814+08:00", "kind": "documentation", "sha256": "57bfcd05d2b60fb6eb4dd7c552e0d7f73456fcb8623cd4152a3ef918150d59b7", "snapshot_path": "sources/57bfcd05d2b60fb6eb4dd7c552e0d7f73456fcb8623cd4152a3ef918150d59b7.txt", "url": "https://prowly.com/media-database/"}, {"fetched_at": "2026-10-24T15:27:54.564602+08:00", "kind": "homepage", "sha256": "57bfcd05d2b60fb6eb4dd7c552e0d7f73456fcb8623cd4152a3ef918150d59b7", "snapshot_path": "sources/57bfcd05d2b60fb6eb4dd7c552e0d7f73456fcb8623cd4152a3ef918150d59b7.txt", "url": "https://prowly.com/"}], "summary": "媒体关系与 PR 平台（现为 Semrush AI PR Toolkit）：提供记者与媒体数据库，按主题构建媒体列表，从平台发送个性化 pitch 并跟踪打开、点击与后续互动。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:193833307','listmonk','{"deployment": ["README 提供 Docker 与单二进制两种自托管安装方式，依赖 PostgreSQL"], "features": ["订阅者记录与列表，支持单/双确认及订阅状态", "以模板编排 campaign 并发送至一个或多个列表", "退订、黑名单与退信处理", "内置 campaign 打开、点击与退订统计及 REST API"], "github_repository_id": 193833307, "homepage": "https://listmonk.app", "id": "github:193833307", "leaf_matches": [{"reason": "README 与官方 Concepts 文档说明订阅者以邮箱标识并带 unconfirmed/confirmed/unsubscribed 状态、列表区分单/双确认、campaign 向一个或多个列表投递且退订者不再收到，符合订阅受众、期次、单向投递与订阅生命周期。", "slug": "newsletter-marketing-platform", "source_urls": ["https://api.github.com/repos/knadh/listmonk", "https://api.github.com/repos/knadh/listmonk/license", "https://raw.githubusercontent.com/knadh/listmonk/master/README.md", "https://listmonk.app/docs/concepts/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/knadh/listmonk/license", "name": "listmonk", "repository_url": "https://github.com/knadh/listmonk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:04:23.352540+08:00", "kind": "repository_metadata", "sha256": "1911d404c5ddef6ac5dba5d1b4804b8ae9fc514e4d6aa0c793e92d300fee38e1", "snapshot_path": "sources/1911d404c5ddef6ac5dba5d1b4804b8ae9fc514e4d6aa0c793e92d300fee38e1.txt", "url": "https://api.github.com/repos/knadh/listmonk"}, {"fetched_at": "2026-10-24T15:04:42.289176+08:00", "kind": "license", "sha256": "777fadb690b7fe35021344669d93f470af807279f6d371612be2970ab4a56594", "snapshot_path": "sources/777fadb690b7fe35021344669d93f470af807279f6d371612be2970ab4a56594.txt", "url": "https://api.github.com/repos/knadh/listmonk/license"}, {"fetched_at": "2026-10-24T15:04:58.006502+08:00", "kind": "readme", "sha256": "e3592dcea72705901f2cfba4f674de81e96dc7aaded2343246cca9312a092cee", "snapshot_path": "sources/e3592dcea72705901f2cfba4f674de81e96dc7aaded2343246cca9312a092cee.txt", "url": "https://raw.githubusercontent.com/knadh/listmonk/master/README.md"}, {"fetched_at": "2026-10-24T15:26:08.723307+08:00", "kind": "documentation", "sha256": "8464a1921ceff634401d4ff3384a5b057a3e113615086c99800b58018bfc2b6b", "snapshot_path": "sources/8464a1921ceff634401d4ff3384a5b057a3e113615086c99800b58018bfc2b6b.txt", "url": "https://listmonk.app/docs/concepts/"}], "summary": "AGPL-3.0 开源自托管 newsletter 与邮件列表管理器：维护订阅者与单/双确认列表，以 campaign 编排期次并批量投递，处理退订与退信并内置打开点击统计。", "technology_stack": ["Go（仓库 metadata 主要语言）", "Vue（前端）", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:creatoriq','CreatorIQ','{"homepage": "https://www.creatoriq.com", "id": "commercial:creatoriq", "leaf_matches": [{"reason": "官方 Campaign Management 页说明可按步骤搭建活动并按需选择模块，向创作者批量发出邀请并共享简报，集中审核与批准内容，自动采集活动窗口内提及品牌的内容，并提供活动绩效报告；覆盖活动容器、参与创作者、简报与内容、活动结果四层结构。", "slug": "influencer-campaign-management", "source_urls": ["https://www.creatoriq.com/influencer-marketing-solution/influencer-campaign-management"]}, {"reason": "官方 Creator Management 页以统一创作者记录承接合作关系与完整绩效历史，提供创作者单点登录查看简报与付款；Creator Discovery 页说明可在覆盖主要社交平台的数百万公开创作者档案上按受众人口、互动质量、内容风格与品牌契合度筛选，按品牌名与关键词检索，并用相似创作者推荐与品牌安全/受众真实性核查评估候选；Community Insights 页说明可查看每个创作者的完整社交内容史、粉丝与社群指标、留存率，用于判断是否适合再次合作。创作者记录、发现与评估、跨活动关系三项均有正文机制描述。", "slug": "influencer-marketing-platform", "source_urls": ["https://www.creatoriq.com/influencer-marketing-solution/creator-management", "https://www.creatoriq.com/influencer-marketing-solution/creator-search", "https://www.creatoriq.com/influencer-marketing-solution/influencer-community-composition"]}], "name": "CreatorIQ", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:33.083448+08:00", "kind": "documentation", "sha256": "34a5d978a1595ff9f1cec65ba596df04ed1dc2ae51061a3865f2f20591569d34", "snapshot_path": "sources/34a5d978a1595ff9f1cec65ba596df04ed1dc2ae51061a3865f2f20591569d34.txt", "url": "https://www.creatoriq.com/influencer-marketing-solution/influencer-campaign-management"}, {"fetched_at": "2026-10-24T15:44:18.935505+08:00", "kind": "documentation", "sha256": "bc49822b1936bf48c7cd31163902234ff448b52d7b3e28694cef5ccbdc173d88", "snapshot_path": "sources/bc49822b1936bf48c7cd31163902234ff448b52d7b3e28694cef5ccbdc173d88.txt", "url": "https://www.creatoriq.com/influencer-marketing-solution/creator-management"}, {"fetched_at": "2026-10-24T18:44:38.936004+08:00", "kind": "documentation", "sha256": "85796ce038896bd2f9aabf55724689828c1705a3b421cb9ce761b79ae44049a6", "snapshot_path": "sources/85796ce038896bd2f9aabf55724689828c1705a3b421cb9ce761b79ae44049a6.txt", "url": "https://www.creatoriq.com/influencer-marketing-solution/creator-search"}, {"fetched_at": "2026-10-24T18:44:40.946540+08:00", "kind": "documentation", "sha256": "bad5b29eb74c539b191a6ff7f47fdf792d5d6f13a4e9da259811c890401a22ee", "snapshot_path": "sources/bad5b29eb74c539b191a6ff7f47fdf792d5d6f13a4e9da259811c890401a22ee.txt", "url": "https://www.creatoriq.com/influencer-marketing-solution/influencer-community-composition"}], "summary": "面向品牌与代理商的创作者营销平台，活动管理模块覆盖活动搭建、创作者邀请与简报共享、内容审核与采集以及活动绩效报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1212017049','InfluenceX','{"deployment": ["README 提供 docker compose 一键启动，也支持本地 Node 运行", "数据库默认 SQLite，可切换 PostgreSQL 15"], "features": ["按 YouTube、TikTok、Instagram 等平台发现创作者并沉淀为 KOL 库与联系人记录", "按活动组织 KOL，跟踪合同到内容再到付款的流程", "外联流水线：草稿、审核、批准、发送，并通过入站 webhook 收集回复", "ROI 看板展示转化漏斗、回复率、完成率、有效 CPM 与单结果成本"], "github_repository_id": 1212017049, "homepage": "https://github.com/oratis/influencex", "id": "github:1212017049", "leaf_matches": [{"reason": "README 说明以活动组织 KOL，按合同、内容、付款三个环节跟踪每位参与者的进度，并提供 ROI 看板汇总转化漏斗、回复率、完成率与单结果成本；活动容器、参与记录与活动结果三层成立。缺口：README 未说明简报与交付物的模板化定义、内容审核的三态结果，属该叶子的能力缺口而非结构改变。", "slug": "influencer-campaign-management", "source_urls": ["https://raw.githubusercontent.com/oratis/influencex/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/oratis/influencex/license", "name": "InfluenceX", "repository_url": "https://github.com/oratis/influencex", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:33:03.881741+08:00", "kind": "repository_metadata", "sha256": "fab2b1b84414641996f1234f44dd84e405b35d80c737865af28183e2c384fe91", "snapshot_path": "sources/fab2b1b84414641996f1234f44dd84e405b35d80c737865af28183e2c384fe91.txt", "url": "https://api.github.com/repos/oratis/influencex"}, {"fetched_at": "2026-10-24T15:33:05.341833+08:00", "kind": "license", "sha256": "5866aea11fbff92b5d049e4af4f430d8a7e1e01a03bb20cb78d395c9dd37550b", "snapshot_path": "sources/5866aea11fbff92b5d049e4af4f430d8a7e1e01a03bb20cb78d395c9dd37550b.txt", "url": "https://api.github.com/repos/oratis/influencex/license"}, {"fetched_at": "2026-10-24T15:33:07.778116+08:00", "kind": "readme", "sha256": "7eadeb9dd6ca532876e386707cfe11547314393ac71616fb66e65cd29168fff0", "snapshot_path": "sources/7eadeb9dd6ca532876e386707cfe11547314393ac71616fb66e65cd29168fff0.txt", "url": "https://raw.githubusercontent.com/oratis/influencex/main/README.md"}], "summary": "MIT 许可、可自托管的 KOL 营销自动化应用，提供多平台创作者发现、创作者库与外联流水线、按活动跟踪合同到内容与付款，以及 ROI 看板。", "technology_stack": ["Node.js 20+ / Express 5", "React 18 / Vite", "SQLite 或 PostgreSQL", "Resend 或 SMTP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1018517574','OpenFunnels','{"deployment": ["README 提供 docker compose 评估栈，含 web、队列、调度器与持久化 SQLite 卷", "也可用 Composer 与 pnpm 在本地运行 Laravel 与前端"], "features": ["用可视化拖拽编辑器构建漏斗页面，发布到 slug 或已验证的自定义域名", "表单支持可配置与条件字段，保留每次提交并记录 UTM 与来源归因", "管理联系人状态与备注，可按筛选导出 CSV", "新线索触发邮件通知或 Webhook，另提供 A/B 实验与流失分析"], "github_repository_id": 1018517574, "homepage": "https://github.com/aialvi/openfunnels", "id": "github:1018517574", "leaf_matches": [{"reason": "README 说明以可配置表单在页面上捕获潜客自愿填写的信息，把每次提交保存为带 UTM 与来源归因的联系人记录，并通过新线索邮件、Webhook 与 CSV 导出把线索交给后续系统。捕获点、线索记录与交接三段齐备；自带轻量 CRM 属附加能力，不影响接收层定位。", "slug": "lead-capture-platform", "source_urls": ["https://raw.githubusercontent.com/aialvi/openfunnels/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/aialvi/openfunnels/license", "name": "OpenFunnels", "repository_url": "https://github.com/aialvi/openfunnels", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:33:10.117732+08:00", "kind": "repository_metadata", "sha256": "8a2ea837c588e8c46323c6a654f0e513160c45cb3efe9606f46014258d96ad87", "snapshot_path": "sources/8a2ea837c588e8c46323c6a654f0e513160c45cb3efe9606f46014258d96ad87.txt", "url": "https://api.github.com/repos/aialvi/openfunnels"}, {"fetched_at": "2026-10-24T15:33:11.819268+08:00", "kind": "license", "sha256": "3c12f4418ec499c5ba8043e259b0e686863acc42e0ca1e3c4b63d42f9afa7428", "snapshot_path": "sources/3c12f4418ec499c5ba8043e259b0e686863acc42e0ca1e3c4b63d42f9afa7428.txt", "url": "https://api.github.com/repos/aialvi/openfunnels/license"}, {"fetched_at": "2026-10-24T15:33:13.283425+08:00", "kind": "readme", "sha256": "57358f8d7147796b9606c43987c181f2e47bdf7e5b73718de0e47abfc6c36e73", "snapshot_path": "sources/57358f8d7147796b9606c43987c181f2e47bdf7e5b73718de0e47abfc6c36e73.txt", "url": "https://raw.githubusercontent.com/aialvi/openfunnels/main/README.md"}], "summary": "MIT 许可、可自托管的漏斗与线索捕获应用，用可视化编辑器构建并发布页面，保存带来源归因的联系人记录并通过通知、Webhook 与导出交付线索。", "technology_stack": ["PHP 8.3+ / Laravel", "React 19 / TypeScript / Inertia", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ruler-analytics','Ruler Analytics','{"homepage": "https://www.ruleranalytics.com", "id": "commercial:ruler-analytics", "leaf_matches": [{"reason": "官方归因页给出完整链路：跨会话跟踪访客并记录来源、渠道、活动与关键词，把电话、表单、聊天和电商转化与其历史互动匹配，再按首次点击、末次点击、线性、时间衰减、位置与数据驱动等模型把收入分配给触点，并提供渠道与活动层聚合。模型可选即信用分配机制的直接证据。", "slug": "marketing-attribution-platform", "source_urls": ["https://www.ruleranalytics.com/marketing-attribution", "https://www.ruleranalytics.com/"]}], "name": "Ruler Analytics", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:47.295863+08:00", "kind": "documentation", "sha256": "f999c44df1433519bc59878fee19b3976bde7734d259c07bddaf7df0f08f4184", "snapshot_path": "sources/f999c44df1433519bc59878fee19b3976bde7734d259c07bddaf7df0f08f4184.txt", "url": "https://www.ruleranalytics.com/marketing-attribution"}, {"fetched_at": "2026-10-24T15:51:57.673695+08:00", "kind": "homepage", "sha256": "e15757c1d51492ef340be489f43360ffc19bbe6655f79f379b1b6828f1f7a067", "snapshot_path": "sources/e15757c1d51492ef340be489f43360ffc19bbe6655f79f379b1b6828f1f7a067.txt", "url": "https://www.ruleranalytics.com/"}], "summary": "面向营销团队的多触点归因与营销衡量平台，跨会话跟踪访客触点、匹配转化并按多种归因模型把收入分配到渠道与活动。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:referralcandy','ReferralCandy','{"homepage": "https://www.referralcandy.com", "id": "commercial:referralcandy", "leaf_matches": [{"reason": "官网直接展示每位客户持有专属推荐链接与优惠码，好友经该链接下单后归因到推荐人并触发双向奖励（好友首单折扣、推荐人店铺积分），并列出欺诈检查、奖励发放与推荐计划分析。本案只取 customer referral program，不把 affiliate 佣金或 loyalty 计入推荐者定义；推荐计划、可追踪身份、分享、归因与奖励链条完整。", "slug": "referral-marketing-platform", "source_urls": ["https://www.referralcandy.com/"]}], "name": "ReferralCandy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:49.411252+08:00", "kind": "homepage", "sha256": "9f086c36bd750706155b77682838fd901cac253a2645a25653af8a21f1139363", "snapshot_path": "sources/9f086c36bd750706155b77682838fd901cac253a2645a25653af8a21f1139363.txt", "url": "https://www.referralcandy.com/"}], "summary": "面向电商品牌的客户推荐（customer referral）应用：为老客户生成专属推荐链接与优惠码、记录好友首单归因，并在符合条件时发放双向奖励；不含其 affiliate 佣金与 loyalty 产品线。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:24459441','EspoCRM','{"deployment": ["README 提供脚本安装、手动安装与 Docker（含 Traefik）部署方式", "AGPLv3 社区核心可自托管；Workflows、BPM 与报表等官方扩展（Advanced Pack）需单独授权，社区版自托管不等于这些扩展功能免费可用"], "features": ["Web-to-Lead 入口从表单或 API 捕获线索并写入目标列表、团队与活动统计", "线索可归属到目标团队/目标列表；按 Round-Robin 或 Least-Busy 自动分配需借助 Workflows/BPM，而这两项属官方 Advanced Pack 付费扩展，不在 AGPL 社区版内", "线索转化后保留 Converted 状态与所转换到的客户、联系人、商机记录", "商机按可配置阶段与概率推进，支持多管道并计入销售仪表盘"], "github_repository_id": 24459441, "homepage": "https://www.espocrm.com", "id": "github:24459441", "leaf_matches": [{"reason": "官方销售管理文档把 Lead 定义为尚未成为客户的潜客记录，可由手工、API/Web 表单进入；线索可归属到目标团队/目标列表，转化时生成客户、联系人与商机且保留 Converted 记录；商机支持可配置阶段与多管道。按 Round-Robin/Least-Busy 自动分配需 Workflows/BPM，而 EspoCRM 将这两项与报表一起列为官方 Advanced Pack 附加组件，需单独授权（付费扩展），故不计入 AGPL 社区版自带能力。本案按 CRM 的 Lead 模块匹配，捕获/转化/分配与跟进有据，响应时间纪律与不合格回收未内置。", "slug": "lead-management-platform", "source_urls": ["https://raw.githubusercontent.com/espocrm/documentation/master/docs/user-guide/sales-management.md", "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/web-to-lead.md", "https://www.espocrm.com/extensions/advanced-pack/"]}, {"reason": "同一官方文档说明 Opportunity 代表一笔潜在或已完成的交易，具备买方/Account 关联、金额与 Close Date 字段、可配置阶段（含 Closed Won 与 Closed Lost）、阶段概率与多管道，Closed Won 商机计入默认销售仪表盘。收入预测需 Advanced Pack 的 Reports 付费扩展，属 AGPLv3 社区核心之外的下游报表，不计入本开源匹配。商机记录、买方上下文、受管推进与明确结果的结构齐备。", "slug": "opportunity-management", "source_urls": ["https://raw.githubusercontent.com/espocrm/documentation/master/docs/user-guide/sales-management.md"]}, {"reason": "官方用户指南说明 Accounts 在 EspoCRM 中处于中心角色，代表公司/组织，并与 Contacts、Opportunities、Cases、Documents 建立关系，用户可订阅账户更新；Accounts/Contacts 功能页说明账户可关联一个或多个联系人，联系人记录保存与该客户相关的交互历史并可关联多个账户；官方用户与角色文档说明用户可属于多个团队、团队角色自动继承，记录访问按 scope 以 all/team/own/no 级别授予，且可限制记录重新分配，覆盖账户、关联人员、关系历史与负责/权限管理。", "slug": "account-management-crm", "source_urls": ["https://api.github.com/repos/espocrm/espocrm", "https://api.github.com/repos/espocrm/espocrm/license", "https://raw.githubusercontent.com/espocrm/espocrm/master/README.md", "https://www.espocrm.com/features/accounts", "https://www.espocrm.com/features/contacts", "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/users-management.md", "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/roles-management.md", "https://raw.githubusercontent.com/espocrm/documentation/master/docs/user-guide/sales-management.md"]}, {"reason": "官方 README 明确将 EspoCRM 定义为 Web CRM，持续管理 leads、contacts、sales opportunities 和 support cases；复用已有正式产品身份及许可记录。", "slug": "customer-relationship-management-crm", "source_urls": ["https://raw.githubusercontent.com/espocrm/espocrm/master/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/espocrm/espocrm/license", "name": "EspoCRM", "repository_url": "https://github.com/espocrm/espocrm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:33:17.852470+08:00", "kind": "repository_metadata", "sha256": "563bd89b1d945a55ac78c7d3f4387d952b4127e6a264bf59964da2acbfbd856c", "snapshot_path": "sources/563bd89b1d945a55ac78c7d3f4387d952b4127e6a264bf59964da2acbfbd856c.txt", "url": "https://api.github.com/repos/espocrm/espocrm"}, {"fetched_at": "2026-10-24T16:54:38.779298+08:00", "kind": "license", "sha256": "da1460df5d1ffeea7af3779a5d4f22797cae1b3c4d7660cb99dafacbdca2ceaa", "snapshot_path": "sources/da1460df5d1ffeea7af3779a5d4f22797cae1b3c4d7660cb99dafacbdca2ceaa.txt", "url": "https://api.github.com/repos/espocrm/espocrm/license"}, {"fetched_at": "2026-10-24T15:33:21.105349+08:00", "kind": "readme", "sha256": "7e3594c47d68d8410dd68441df06cd897877b0da21ac479a237ea1a61f9ac6ed", "snapshot_path": "sources/7e3594c47d68d8410dd68441df06cd897877b0da21ac479a237ea1a61f9ac6ed.txt", "url": "https://raw.githubusercontent.com/espocrm/espocrm/master/README.md"}, {"fetched_at": "2026-10-24T15:58:27.712083+08:00", "kind": "documentation", "sha256": "318d14efa9bc6e42fba5d633590b20a9f1dfaa216623366b8786c27c16c32229", "snapshot_path": "sources/318d14efa9bc6e42fba5d633590b20a9f1dfaa216623366b8786c27c16c32229.txt", "url": "https://raw.githubusercontent.com/espocrm/documentation/master/docs/user-guide/sales-management.md"}, {"fetched_at": "2026-10-24T15:58:29.049199+08:00", "kind": "documentation", "sha256": "f711adea06a535a26ec160b3bbb969d9a493e8b463fb4f89f3f47955199c9c3f", "snapshot_path": "sources/f711adea06a535a26ec160b3bbb969d9a493e8b463fb4f89f3f47955199c9c3f.txt", "url": "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/web-to-lead.md"}, {"fetched_at": "2026-10-26T12:20:00.142074+08:00", "kind": "documentation", "sha256": "229e025cc219418cb386a8f730c6b294b403416aab4885a6900059a8cab2b7fb", "snapshot_path": "sources/229e025cc219418cb386a8f730c6b294b403416aab4885a6900059a8cab2b7fb.txt", "url": "https://www.espocrm.com/extensions/advanced-pack/"}, {"fetched_at": "2026-10-24T17:12:33.783608+08:00", "kind": "repository_metadata", "sha256": "b260b6bd46b6bb661bf4a6b39a0b7cc836317b83ef5031a03667d417d5470e77", "snapshot_path": "sources/b260b6bd46b6bb661bf4a6b39a0b7cc836317b83ef5031a03667d417d5470e77.txt", "url": "https://api.github.com/repos/espocrm/espocrm"}, {"fetched_at": "2026-10-24T16:21:37.507976+08:00", "kind": "documentation", "sha256": "58598516c96a1ca2b32f194913f292d2ee8c66f6e6b3658b748620cdfd1794ba", "snapshot_path": "sources/58598516c96a1ca2b32f194913f292d2ee8c66f6e6b3658b748620cdfd1794ba.txt", "url": "https://www.espocrm.com/features/accounts"}, {"fetched_at": "2026-10-24T16:21:41.795352+08:00", "kind": "documentation", "sha256": "2cb2f91f87da7ff3ae1e33b0d69b49b276243bb2a9d38522afe553a4eeadbc9a", "snapshot_path": "sources/2cb2f91f87da7ff3ae1e33b0d69b49b276243bb2a9d38522afe553a4eeadbc9a.txt", "url": "https://www.espocrm.com/features/contacts"}, {"fetched_at": "2026-10-26T12:22:32.899161+08:00", "kind": "documentation", "sha256": "c660fb418d8f613e85c7b8fda81e5c33be23afdae6fc24d4bb40a6b95606f663", "snapshot_path": "sources/c660fb418d8f613e85c7b8fda81e5c33be23afdae6fc24d4bb40a6b95606f663.txt", "url": "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/users-management.md"}, {"fetched_at": "2026-10-26T12:22:34.350837+08:00", "kind": "documentation", "sha256": "a925d84aee53f101ee198c89cc759db65ba0c1630cf3ac49f039010414344cc4", "snapshot_path": "sources/a925d84aee53f101ee198c89cc759db65ba0c1630cf3ac49f039010414344cc4.txt", "url": "https://raw.githubusercontent.com/espocrm/documentation/master/docs/administration/roles-management.md"}], "summary": "AGPLv3 开源 CRM；Lead 是其潜客记录模块，提供线索捕获、团队/目标列表归属、线索转化，以及带可配置阶段与多管道的商机管理。社区版可自托管；自动分配所需的 Workflows/BPM 属官方 Advanced Pack 扩展，需另行购买授权。", "technology_stack": ["PHP", "REST API", "单页应用前端", "MySQL/MariaDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:reply-io','Reply.io','{"homepage": "https://reply.io", "id": "commercial:reply-io", "leaf_matches": [{"reason": "官方 How Reply Works 说明序列按步骤逐个推进联系人、步骤之间设延迟、以每日新增联系人数与发件上限节流，并在回复、退信或退订时自动停止或排除该联系人；停止机制页进一步列出六种序列状态与暂停条件。序列定义、逐联系人状态、系统执行与响应中断的核心齐备。", "slug": "outreach-sequencing-platform", "source_urls": ["https://how.reply.io/behavior/sequence-execution/", "https://how.reply.io/behavior/sequence-stopping/"]}], "name": "Reply.io", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:46:23.140395+08:00", "kind": "documentation", "sha256": "d3f34da72fde42d6c1fcfcf1ad97caa111990868e0b30afc26703cae850679a2", "snapshot_path": "sources/d3f34da72fde42d6c1fcfcf1ad97caa111990868e0b30afc26703cae850679a2.txt", "url": "https://how.reply.io/behavior/sequence-execution/"}, {"fetched_at": "2026-10-24T16:05:22.568233+08:00", "kind": "documentation", "sha256": "ed0a2773dfa48354460676995aafff1135c0ff7278c159f4d539f38b08e02221", "snapshot_path": "sources/ed0a2773dfa48354460676995aafff1135c0ff7278c159f4d539f38b08e02221.txt", "url": "https://how.reply.io/behavior/sequence-stopping/"}, {"fetched_at": "2026-10-24T15:39:14.831697+08:00", "kind": "documentation", "sha256": "e8cb315edbd37389b922f601c65b12f976a0d615b31ce796c82cc3719797b85b", "snapshot_path": "sources/e8cb315edbd37389b922f601c65b12f976a0d615b31ce796c82cc3719797b85b.txt", "url": "https://reply.io/features/"}], "summary": "面向销售团队的多渠道外联平台，以序列编排邮件、电话与社交步骤，按每位联系人的状态自动推进、暂停或停止。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:phoneburner','PhoneBurner','{"homepage": "https://www.phoneburner.com", "id": "commercial:phoneburner", "leaf_matches": [{"reason": "官方产品页说明其为逐通外呼的 power dialer：单个销售代表在联系人列表上拨号、每通电话保持真人接听，处置按钮一键回写联系人记录并触发后续邮件或语音留言；平台页补充自定义处置、通话记录与录音，其团队管理、实时辅导与自动线索分配属于承载产品层，不计入单代表拨号器核心。记录驱动呼叫、实时通话与结果捕获齐备。", "slug": "sales-dialer", "source_urls": ["https://www.phoneburner.com/power-dialer/", "https://www.phoneburner.com/platform/"]}], "name": "PhoneBurner", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:46:26.823575+08:00", "kind": "documentation", "sha256": "bf28f950f888b8bf9a8fb345a15bed531484e3b38590925e4c9c07abbc93234b", "snapshot_path": "sources/bf28f950f888b8bf9a8fb345a15bed531484e3b38590925e4c9c07abbc93234b.txt", "url": "https://www.phoneburner.com/power-dialer/"}, {"fetched_at": "2026-10-24T17:08:16.779238+08:00", "kind": "documentation", "sha256": "b12faf7c12e57d096460fd097559254e848c8f74baac3dc96b1d2717d2e329fd", "snapshot_path": "sources/b12faf7c12e57d096460fd097559254e848c8f74baac3dc96b1d2717d2e329fd.txt", "url": "https://www.phoneburner.com/platform/"}], "summary": "面向单个销售代表的功率拨号器，按联系人列表逐通外呼，并在通话结束后一键记录处置结果与后续动作。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hubspot-quotes','HubSpot Quotes','{"homepage": "https://hubspot.com", "id": "commercial:hubspot-quotes", "leaf_matches": [{"reason": "官方知识库说明报价模板与报价文档是不同对象：模板预置版式与模块、可显示或隐藏并锁定区块，再用交易与产品数据（含分层、阶梯与斜坡定价）生成品牌化报价；报价可带到期日，触发条件时须先请求并取得批准才能分享，最后以电子签名或点击接受成交并跟踪查看与收款。模板、数据组装、有状态文档、审批门与买方接受齐备。", "slug": "sales-document-automation", "source_urls": ["https://knowledge.hubspot.com/quotes/create-quote-templates", "https://knowledge.hubspot.com/quotes/create-and-send-quotes"]}], "name": "HubSpot Quotes", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:03:32.425261+08:00", "kind": "documentation", "sha256": "b98a6b03aeac0252d95218677c0fd90e9d5278ae5baa81f5531a4251cb9a3e66", "snapshot_path": "sources/b98a6b03aeac0252d95218677c0fd90e9d5278ae5baa81f5531a4251cb9a3e66.txt", "url": "https://knowledge.hubspot.com/quotes/create-quote-templates"}, {"fetched_at": "2026-10-24T16:03:35.543924+08:00", "kind": "documentation", "sha256": "c20eb08cc8e08b39d3e35f3cf2fe8304f88c81d0b6fa3f4c87cc8e01f5baa8c8", "snapshot_path": "sources/c20eb08cc8e08b39d3e35f3cf2fe8304f88c81d0b6fa3f4c87cc8e01f5baa8c8.txt", "url": "https://knowledge.hubspot.com/quotes/create-and-send-quotes"}], "summary": "HubSpot 销售套件内的报价文档工具，用模板与交易数据生成报价、经审批后发送，并以电子签名或点击接受形成成交记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:salesloft','Salesloft','{"homepage": "https://salesloft.com", "id": "commercial:salesloft", "leaf_matches": [{"reason": "官方平台页与销售互动软件页把 Cadence 定义为跨渠道步骤集合，可按渠道、时区与账户排序步骤并由自动化规则替代重复任务；开发者 Cadence 导入文档的 settings 给出逐 Cadence 的推进控制：目标每日新增人数（target_daily_people）、回复后是否移出（remove_replied）、退信后是否移出（remove_bounced）、收到自动回复时标记为 out of office 并支持暂停后重排（reschedule_from_pause_enabled），以及回复/退信/加入/完成各自触发的阶段；automated-settings 给出自动步骤的发送时间、按联系人时区或用户时区发送、是否允许周末发送。序列定义、逐潜客状态、按发送日历执行与回复/退信/OOO 中断机制均有官方正文支持。缺口：退订/取消订阅触发移出的规则未在保留快照中说明。", "slug": "sales-engagement-platform", "source_urls": ["https://www.salesloft.com/platform-overview", "https://www.salesloft.com/platform/sales-engagement-software", "https://developer.salesloft.com/docs/platform/cadence-imports/settings/", "https://developer.salesloft.com/docs/platform/cadence-imports/automated-settings/"]}], "name": "Salesloft", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:39:04.265088+08:00", "kind": "documentation", "sha256": "9e13f19b684b7f3fbc62d49f95022106fe85d9fe061594085311a1b7463996cb", "snapshot_path": "sources/9e13f19b684b7f3fbc62d49f95022106fe85d9fe061594085311a1b7463996cb.txt", "url": "https://www.salesloft.com/platform-overview"}, {"fetched_at": "2026-10-24T17:22:01.475523+08:00", "kind": "documentation", "sha256": "667a8767f9bd067b86c643e6440dc08062b51a74cd8533eb60c77b663e2b7b31", "snapshot_path": "sources/667a8767f9bd067b86c643e6440dc08062b51a74cd8533eb60c77b663e2b7b31.txt", "url": "https://www.salesloft.com/platform/sales-engagement-software"}, {"fetched_at": "2026-10-24T18:47:23.430396+08:00", "kind": "documentation", "sha256": "8a20b94559dc8f42e945897e83c6639aee9900c5427885caaab5119ca6bce42d", "snapshot_path": "sources/8a20b94559dc8f42e945897e83c6639aee9900c5427885caaab5119ca6bce42d.txt", "url": "https://developer.salesloft.com/docs/platform/cadence-imports/settings/"}, {"fetched_at": "2026-10-24T18:50:40.820303+08:00", "kind": "documentation", "sha256": "4e823687c0d7093a5c0d83c0341e311ff923cd1d0fbf41ea699ecd4226b676cd", "snapshot_path": "sources/4e823687c0d7093a5c0d83c0341e311ff923cd1d0fbf41ea699ecd4226b676cd.txt", "url": "https://developer.salesloft.com/docs/platform/cadence-imports/automated-settings/"}], "summary": "面向销售团队的互动平台，以 Cadence 编排跨渠道触达，并结合会话智能、交易与预测模块运行销售执行流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:channeltivity','Channeltivity','{"homepage": "https://www.channeltivity.com", "id": "commercial:channeltivity", "leaf_matches": [{"reason": "官方渠道销售页列出交易注册、线索分发、推荐与佣金三个模块，并与 HubSpot、Salesforce、Dynamics 365 同步；Deal Registration 页给出完整流程：伙伴在门户提交商机（客户信息、地点、产品兴趣等资格字段），厂商渠道团队按预设标准（ICP、最低金额、目标客户）评估，若管道中没有重复商机则批准，通常授予有期限的独家保护，并记录审批历史、发送状态变更通知与到期提醒，同时统计审批标准与 SLA 达成；渠道销售总览页的 Lead Distribution 段说明可按地域、产品专长、伙伴层级与自定义条件配置路由规则，把合格线索分给正确的伙伴，并跟踪线索接受、跟进与转化；Referrals & Commissions 页说明推荐可由伙伴提交或经专属链接表单自动生成，厂商可接受、转派或拒绝，成交后状态转为待付款并据成交金额计算推荐伙伴佣金。伙伴侧在系统内提交与推进，厂商侧评估审批，联名管道与按来源伙伴的推荐佣金归属均有正文支持。", "slug": "channel-sales-management", "source_urls": ["https://www.channeltivity.com/channel-sales/", "https://www.channeltivity.com/channel-sales/deal-registration/", "https://www.channeltivity.com/channel-sales/referrals-commissions/"]}], "name": "Channeltivity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:53:28.612205+08:00", "kind": "documentation", "sha256": "08a9245db52aba6392befccfef8cdcffb654a18a3738909e48649826383e2acd", "snapshot_path": "sources/08a9245db52aba6392befccfef8cdcffb654a18a3738909e48649826383e2acd.txt", "url": "https://www.channeltivity.com/channel-sales/"}, {"fetched_at": "2026-10-24T18:44:38.848205+08:00", "kind": "documentation", "sha256": "ab730d1c45e6419bbd5f000eb8e1495b18a379ddeb8858c8bf2385a3c7b2fd58", "snapshot_path": "sources/ab730d1c45e6419bbd5f000eb8e1495b18a379ddeb8858c8bf2385a3c7b2fd58.txt", "url": "https://www.channeltivity.com/channel-sales/deal-registration/"}, {"fetched_at": "2026-10-24T18:50:02.013646+08:00", "kind": "documentation", "sha256": "c99e1321a1743b6fbee70e0a312799d7d65edc28524fba70d4ebd730c8da24ec", "snapshot_path": "sources/c99e1321a1743b6fbee70e0a312799d7d65edc28524fba70d4ebd730c8da24ec.txt", "url": "https://www.channeltivity.com/channel-sales/referrals-commissions/"}], "summary": "面向厂商的渠道与伙伴关系管理平台，提供交易注册（含审批与冲突检查）、线索分发、推荐与佣金管理，与伙伴共享管道并同步主流 CRM。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:xactly','Xactly','{"homepage": "https://www.xactlycorp.com", "id": "commercial:xactly", "leaf_matches": [{"reason": "官方 Xactly Manage 页的 Quota Management 段说明可按规则与命名分配为二级/覆盖团队派生配额，并在用户定义工作流中查看配额变更及其潜在影响；People Management 段说明可实时监控销售人员的当前与历史销售绩效并跟踪其进展；Quota Fairness Monitoring 直接监控团队配额达成模式，标出目标过高或过低。平台页 Plan/Manage 段补充以覆盖模型平衡区域潜力并制定配额分配，把区域、人员、商机、归属与配额置于单一事实源。配额对象、分配机制与达成衡量均有正文支持。", "slug": "quota-management", "source_urls": ["https://www.xactlycorp.com/platform", "https://www.xactlycorp.com/products/xactly-manage"]}], "name": "Xactly", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:54:51.532059+08:00", "kind": "documentation", "sha256": "910b4f757b5bfb71e28ccd4a1ae681addbaee882131227156b4e71c2e0b3cc0b", "snapshot_path": "sources/910b4f757b5bfb71e28ccd4a1ae681addbaee882131227156b4e71c2e0b3cc0b.txt", "url": "https://www.xactlycorp.com/platform"}, {"fetched_at": "2026-10-24T15:39:06.930262+08:00", "kind": "documentation", "sha256": "427e86aceb114c92bccb93c5caa01af35083b2639b3e3cbc163cc9f0a922cf30", "snapshot_path": "sources/427e86aceb114c92bccb93c5caa01af35083b2639b3e3cbc163cc9f0a922cf30.txt", "url": "https://www.xactlycorp.com/products/xactly-forecast"}, {"fetched_at": "2026-10-26T12:13:30.474413+08:00", "kind": "documentation", "sha256": "a1a7463a66b3e5dddcbbcba17e2371293ac1cc840e3ca0e9b9eb2893a4722e70", "snapshot_path": "sources/a1a7463a66b3e5dddcbbcba17e2371293ac1cc840e3ca0e9b9eb2893a4722e70.txt", "url": "https://www.xactlycorp.com/products/xactly-manage"}], "summary": "面向销售与财务的销售绩效与收入平台，覆盖区域与配额规划、配额达成、激励薪酬，以及基于 CRM 管道数据的销售预测。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pipedrive','Pipedrive','{"homepage": "https://www.pipedrive.com", "id": "commercial:pipedrive", "leaf_matches": [{"reason": "官方管道管理页说明可按团队实际销售流程自定义阶段、可视化每笔交易所处阶段与卡点、为每个阶段指派下一步动作并跟踪销售活动，交易管理页补充交易记录与预测报表。交易、阶段管道、受管推进与群体视图的核心齐备。", "slug": "sales-pipeline-management", "source_urls": ["https://www.pipedrive.com/en/features/pipeline-management", "https://www.pipedrive.com/en/products/sales/deal-management"]}], "name": "Pipedrive", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:39:00.702444+08:00", "kind": "documentation", "sha256": "832d322dbe2eaaf8c57f9a15ff92d124d2aa00103091f45536c05e4bed9f2257", "snapshot_path": "sources/832d322dbe2eaaf8c57f9a15ff92d124d2aa00103091f45536c05e4bed9f2257.txt", "url": "https://www.pipedrive.com/en/features/pipeline-management"}, {"fetched_at": "2026-10-24T16:08:57.310408+08:00", "kind": "documentation", "sha256": "00ef98a14afbf22490ea433ef502ffe171ce78f23cf08c73892ab302b5c43c43", "snapshot_path": "sources/00ef98a14afbf22490ea433ef502ffe171ce78f23cf08c73892ab302b5c43c43.txt", "url": "https://www.pipedrive.com/en/products/sales/deal-management"}], "summary": "面向销售团队的 CRM，以可定制阶段的可视化管道管理交易，并跟踪活动、停滞与预测。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dealhub','DealHub','{"homepage": "https://dealhub.io", "id": "commercial:dealhub", "leaf_matches": [{"reason": "DealHub 官方 CPQ 产品页列出引导式报价配置（guided selling、结构化产品与筛选）、可承载用量/分层/固定计价的自适应价格簿、可配置捆绑与折扣、按报价行实时调整并保留版本化订单表单、自动化审批工作流，以及与 Salesforce、Dynamics 365、HubSpot 的实时报价/产品/交易数据同步。这些功能说明其在产品目录与规则约束下组装报价、由系统按价格规则计算，并生成可修订、可审批的报价记录；Configure/Price/Quote 三段仅按该产品页所列能力描述，不引用术语表的品类通识。缺口：产品目录的兼容规则细节与报价接受后的下游转换未在该页说明。", "slug": "configure-price-quote-cpq", "source_urls": ["https://dealhub.io/platform/cpq/"]}], "name": "DealHub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T18:44:41.262082+08:00", "kind": "documentation", "sha256": "c3b092a106711ff244b3efa7e85468c9cfb3483dad431ed28d7773176529f914", "snapshot_path": "sources/c3b092a106711ff244b3efa7e85468c9cfb3483dad431ed28d7773176529f914.txt", "url": "https://dealhub.io/platform/cpq/"}], "summary": "面向 B2B 销售的 CPQ 与收入编排平台，以引导式配置、自适应价格簿和审批工作流生成可修订的报价，并与主流 CRM 同步。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:configure-to-win','Configure to WIN','{"homepage": "https://configure.win", "id": "commercial:configure-to-win", "leaf_matches": [{"reason": "官方 Deal Desk 页说明以报价数据与可配置度量作为商业上下文，由审批规则判定报价默认通过、被阻止、自动拒绝或转人工评审，并把审批周期、责任组、决策人与当前状态挂在报价上，同时明确产品范围不含通用交易协作或 CLM。例外评审、授权决策与留痕的核心齐备。", "slug": "deal-desk-commercial-approval-platform", "source_urls": ["https://configure.win/deal-desk-software"]}], "name": "Configure to WIN", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:26:18.730454+08:00", "kind": "documentation", "sha256": "57e312d182f998593f096cf2ee5a05f81e1f10b32d2ce9eaa5e71053e551bc84", "snapshot_path": "sources/57e312d182f998593f096cf2ee5a05f81e1f10b32d2ce9eaa5e71053e551bc84.txt", "url": "https://configure.win/deal-desk-software"}], "summary": "面向 B2B 报价的可配置 CPQ 产品，用可配置度量与审批规则在报价内完成定价例外评审与决策留痕。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:getaccept','GetAccept','{"homepage": "https://www.getaccept.com", "id": "commercial:getaccept", "leaf_matches": [{"reason": "官方提案软件页说明可用模板与 CRM 数据生成品牌化提案、嵌入取自产品库的定价表、按规则路由审批、实时跟踪每位利益相关方的打开与页面停留，并在同一处完成电子签署。提案记录、内容组装、内部审批、交付跟踪与接受决策的核心齐备。", "slug": "proposal-management", "source_urls": ["https://www.getaccept.com/product/proposal-software"]}], "name": "GetAccept", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:26:21.274200+08:00", "kind": "documentation", "sha256": "72717a171203387bf4636c69774fe57c67e87a2c69f7c091684932c5e4e31aef", "snapshot_path": "sources/72717a171203387bf4636c69774fe57c67e87a2c69f7c091684932c5e4e31aef.txt", "url": "https://www.getaccept.com/product/proposal-software"}], "summary": "面向销售团队的提案与成交平台，用模板和 CRM 数据生成提案、路由审批、跟踪买方互动并完成电子签署。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gainsight-renewal-center','Gainsight Renewal Center','{"homepage": "https://gainsight.com", "id": "commercial:gainsight-renewal-center", "leaf_matches": [{"reason": "官方Renewal Center文档说明其以续约机会为单位跟踪到期日、预测与实际值，提供Renewal Due、Late Renewals、Churn Forecast与Renewal Waterfall视图，并由续约团队逐条更新机会，覆盖续约记录、决策前动作、结果与前瞻管道。", "slug": "renewal-management-platform", "source_urls": ["https://support.gainsight.com/gainsight_nxt/Renewal_Center/01About/Renewal_Center_Overview", "https://support.gainsight.com/gainsight_nxt/Renewal_Center/03User_Guides/Renewal_Center_User_Guide", "https://www.gainsight.com/solutions/gainsight-for-revenue-teams"]}], "name": "Gainsight Renewal Center", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:15:18.047457+08:00", "kind": "documentation", "sha256": "929006b4e3fdf72a9106bf8ebe98f649c775cc9daa183b6dc56810037a177088", "snapshot_path": "sources/929006b4e3fdf72a9106bf8ebe98f649c775cc9daa183b6dc56810037a177088.txt", "url": "https://support.gainsight.com/gainsight_nxt/Renewal_Center/01About/Renewal_Center_Overview"}, {"fetched_at": "2026-10-24T16:15:20.726858+08:00", "kind": "documentation", "sha256": "4afcfb935f680175cb15af89be38c89142f49c4ff802f8ffebc302f5e0ac6ebd", "snapshot_path": "sources/4afcfb935f680175cb15af89be38c89142f49c4ff802f8ffebc302f5e0ac6ebd.txt", "url": "https://support.gainsight.com/gainsight_nxt/Renewal_Center/03User_Guides/Renewal_Center_User_Guide"}, {"fetched_at": "2026-10-24T16:41:29.364153+08:00", "kind": "documentation", "sha256": "61b8b82a895fc6a19b1edf167891d29da282f92af215b4c6eccf4484f8dea5f0", "snapshot_path": "sources/61b8b82a895fc6a19b1edf167891d29da282f92af215b4c6eccf4484f8dea5f0.txt", "url": "https://www.gainsight.com/solutions/gainsight-for-revenue-teams"}], "summary": "面向客户成功与续约团队的续约管理模块，按续约机会汇总到期日、金额与预测，并记录续约结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:medallia-experience-management','Medallia Experience Management','{"homepage": "https://www.medallia.com", "id": "commercial:medallia-experience-management", "leaf_matches": [{"reason": "官方平台页正文覆盖问卷创建、跨渠道反馈/行为/运营信号采集、Total Experience Profiles 的客户级交互时间线、AI 主题/根因与 CSAT/情感分析、警报与 case management、smart closed-loop；反馈采集页补充 email/website/mobile/voice 问卷投放及 survey/voice/chat/social 等信号；文本分析页补充主题/情感/意图、按分类或情感触发警报并路由责任人、优先工单和触发工作流。三者共同支撑体验计划→客户级响应与测量→警报/工单跟进闭环。", "slug": "customer-experience-management-platform", "source_urls": ["https://www.medallia.com/platform/", "https://www.medallia.com/platform/signals/", "https://www.medallia.com/platform/text-analytics/"]}, {"reason": "官方平台页列出 Comprehensive Feedback Capture、统一调研与多渠道信号、角色化报表和“Close the loop and drive action”，并说明告警与案件管理使一线团队针对反馈采取行动，构成征询式反馈采集、体验测量与告警/工单式跟进闭环；平台同时覆盖 social 等更广信号，本匹配以其主动征询调研与闭环能力为核心，并承认与社交聆听/全渠道体验管理的重叠。", "slug": "voice-of-customer-platform", "source_urls": ["https://www.medallia.com/platform/"]}], "name": "Medallia Experience Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:58:59.319495+08:00", "kind": "documentation", "sha256": "2e9abba3c32161a11cb18d6c63d6861460f78d20f976052e1173f2a05f2ce454", "snapshot_path": "sources/2e9abba3c32161a11cb18d6c63d6861460f78d20f976052e1173f2a05f2ce454.txt", "url": "https://www.medallia.com/platform/"}, {"fetched_at": "2026-10-24T16:19:44.747289+08:00", "kind": "documentation", "sha256": "eb49212f19899219a635ef70186a393aa5168fa749424a268c4cd5d206f4f5a8", "snapshot_path": "sources/eb49212f19899219a635ef70186a393aa5168fa749424a268c4cd5d206f4f5a8.txt", "url": "https://www.medallia.com/platform/"}, {"fetched_at": "2026-10-26T16:58:10.995081+08:00", "kind": "documentation", "sha256": "84e67ae4cd10f73630c4c018b8b912529105312f69086622ec080d48eda15cdf", "snapshot_path": "sources/84e67ae4cd10f73630c4c018b8b912529105312f69086622ec080d48eda15cdf.txt", "url": "https://www.medallia.com/platform/signals/"}, {"fetched_at": "2026-10-26T16:44:31.623704+08:00", "kind": "documentation", "sha256": "810b49a114d13baea0e63ba6105ecba11b95b3351bc423e5b63abe1a68959d10", "snapshot_path": "sources/810b49a114d13baea0e63ba6105ecba11b95b3351bc423e5b63abe1a68959d10.txt", "url": "https://www.medallia.com/platform/text-analytics/"}], "summary": "面向企业客户体验计划的全渠道反馈平台，覆盖调研投放、指标与主题分析、告警与闭环跟进。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:clinked','Clinked','{"homepage": "https://www.clinked.com", "id": "commercial:clinked", "leaf_matches": [{"reason": "官方客户门户页说明客户以安全登录凭证进入专属工作区，可自助上传文件、提交并跟踪审批、查看项目进展与文档，权限按客户范围授予，符合已识别客户的账户空间与自助操作核心。", "slug": "customer-portal", "source_urls": ["https://www.clinked.com/client-portal", "https://www.clinked.com/"]}], "name": "Clinked", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:15:28.177120+08:00", "kind": "documentation", "sha256": "84baffc74ac55ce0236e795db87b6f61b3184a8b8528ee007bf6e04461ba9dbf", "snapshot_path": "sources/84baffc74ac55ce0236e795db87b6f61b3184a8b8528ee007bf6e04461ba9dbf.txt", "url": "https://www.clinked.com/client-portal"}, {"fetched_at": "2026-10-24T16:33:24.793962+08:00", "kind": "homepage", "sha256": "f4d9e9754b8d972dcfdfe08c4df6836e9cca836bdbb66d27d4d080e5055764b1", "snapshot_path": "sources/f4d9e9754b8d972dcfdfe08c4df6836e9cca836bdbb66d27d4d080e5055764b1.txt", "url": "https://www.clinked.com/"}], "summary": "白标客户门户，为客户提供登录后的文件、任务、审批、消息与项目进展自助空间。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:impartner','Impartner PRM','{"homepage": "https://impartner.com", "id": "commercial:impartner", "leaf_matches": [{"reason": "官方PRM页描述伙伴生命周期与分层、Pipeline Management同步交易注册和伙伴线索、供应商审批注册并开展联合销售，以及Market Development Funds申请与ROI，体现伙伴注册表、伙伴门户与供应商控制审批的渠道工作流。", "slug": "partner-relationship-management-prm", "source_urls": ["https://impartner.com/platform/", "https://impartner.com/platform/partner-relationship-management/"]}], "name": "Impartner PRM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:15:32.762982+08:00", "kind": "homepage", "sha256": "774382fdbe12af3f8bca8fd097785f167ab7dfa7f551fb72142a96fa3fbe4c65", "snapshot_path": "sources/774382fdbe12af3f8bca8fd097785f167ab7dfa7f551fb72142a96fa3fbe4c65.txt", "url": "https://impartner.com/platform/"}, {"fetched_at": "2026-10-24T16:24:31.507454+08:00", "kind": "documentation", "sha256": "bc2ff698f473154bbc9e8707122db15b732738c1f34fffe2f918d566d6d1357a", "snapshot_path": "sources/bc2ff698f473154bbc9e8707122db15b732738c1f34fffe2f918d566d6d1357a.txt", "url": "https://impartner.com/platform/partner-relationship-management/"}], "summary": "面向渠道项目的合作伙伴关系管理平台，覆盖伙伴生命周期、交易注册、线索同步、赋能与MDF。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:revegy','Revegy Account Planning','{"homepage": "https://help.revegy.com", "id": "commercial:revegy", "leaf_matches": [{"reason": "官方帮助中心说明账户计划用于围绕单个客户共享目标、行动与进展，并用于评审，历史账户活动可见；Contact Map 用于客户内外部关键利益相关者与关系结构分析，Strategy Map 记录客户目标与举措，并支持识别覆盖缺口与风险。", "slug": "strategic-account-planning-platform", "source_urls": ["https://help.revegy.com/Help/Content/RevegyUI/Plans.htm", "https://help.revegy.com/Help/Content/RevegyUI/Maps/Maps.htm", "https://help.revegy.com/Help/Content/RevegyUI/Accounts.htm"]}], "name": "Revegy Account Planning", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:26:43.078287+08:00", "kind": "documentation", "sha256": "be7471414a4ef6e3d1a592b112efa3a789ea48f18a5a35af922036e22c43c5bc", "snapshot_path": "sources/be7471414a4ef6e3d1a592b112efa3a789ea48f18a5a35af922036e22c43c5bc.txt", "url": "https://help.revegy.com/Help/Content/RevegyUI/Plans.htm"}, {"fetched_at": "2026-10-24T16:26:44.951375+08:00", "kind": "documentation", "sha256": "c127e76f4320fe984a793edec4b73bf939679c7c260d16648fb71464b556d32b", "snapshot_path": "sources/c127e76f4320fe984a793edec4b73bf939679c7c260d16648fb71464b556d32b.txt", "url": "https://help.revegy.com/Help/Content/RevegyUI/Maps/Maps.htm"}, {"fetched_at": "2026-10-24T16:34:20.746176+08:00", "kind": "documentation", "sha256": "33ab26bea6d05d5951ec2966d5e77caa4ecab22b4932d0e374f7f3280e42328b", "snapshot_path": "sources/33ab26bea6d05d5951ec2966d5e77caa4ecab22b4932d0e374f7f3280e42328b.txt", "url": "https://help.revegy.com/Help/Content/RevegyUI/Accounts.htm"}], "summary": "面向战略客户的账户规划平台，以持久化计划、关系图谱和行动项组织客户团队协同执行。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zoho-crm-territory-management','Zoho CRM Territory Management','{"homepage": "https://www.zoho.com", "id": "commercial:zoho-crm-territory-management", "leaf_matches": [{"reason": "官方Territory Management页说明按地区、团队或个人建立层级区域，用自动化将客户分配给区域并让相应销售人员从一开始就对齐，并按区域跟踪业绩与实时报表，覆盖区域单元、市场实体绑定与销售人员绑定。", "slug": "territory-management", "source_urls": ["https://www.zoho.com/crm/territory-management.html"]}], "name": "Zoho CRM Territory Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:28:15.443346+08:00", "kind": "documentation", "sha256": "dd75f680eed1888eb920a984eb6b420bee09562d6e2a1603d1b13e159e52be7a", "snapshot_path": "sources/dd75f680eed1888eb920a984eb6b420bee09562d6e2a1603d1b13e159e52be7a.txt", "url": "https://www.zoho.com/crm/territory-management.html"}], "summary": "Zoho CRM内的销售区域管理能力，按地理层级划分区域、自动将客户分配给区域并跟踪区域业绩。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:6325420','Kill Bill','{"deployment": ["自托管（本地或自有云基础设施）", "Kubernetes部署指南", "AWS单层/多层部署指南"], "features": ["目录、计划与定价及订阅生命周期管理", "用量计费与发票生成；信用与催收（dunning）", "跨支付网关收款与退款", "基础税务处理（Aviate 提供进阶税务）"], "github_repository_id": 6325420, "homepage": "https://killbill.io", "id": "github:6325420", "leaf_matches": [{"reason": "官方 README、Features 与 Invoice subsystem 文档说明 Apache-2.0 社区核心处理目录/定价、订阅、用量计费、发票、跨网关支付、信用、基础税务与催收；Invoice subsystem 说明发票按账户生成，包含 DRAFT/COMMITTED 状态、账户级 AUTO_INVOICING_DRAFT 标签、作废与 parked account 等控制。Aviate Premium 卡片（658c98... 落地页）另列增强 Metering、Wallet、Coupons、进阶 Tax、Custom Invoice Sequencing，故仅这些增强项不计入开源核心。原 userguide/account URL 现返回文档站落地页，账户作为财务容器的直接正文证据缺失，只能由发票按账户生成、账户级标签与 parked account 等间接支持，已下调该点结论。", "slug": "billing-platform", "source_urls": ["https://api.github.com/repos/killbill/killbill", "https://api.github.com/repos/killbill/killbill/license", "https://raw.githubusercontent.com/killbill/killbill/master/README.md", "https://docs.killbill.io/latest/features", "https://docs.killbill.io/latest/invoice_subsystem", "https://docs.killbill.io/latest/what_is_kill_bill", "https://docs.killbill.io/userguide/account", "https://docs.killbill.io/latest/what_is_aviate"]}, {"reason": "README说明其为开源订阅计费与支付平台，处理目录与定价、订阅、用量计费、开票、跨网关付款、信用、税与催收，并可在自有基础设施运行；订阅作为持久对象驱动周期计费，覆盖订阅记录、自动周期开票及生命周期/催收路径，具体状态机实现未逐项核验。", "slug": "subscription-billing-platform", "source_urls": ["https://api.github.com/repos/killbill/killbill/readme", "https://api.github.com/repos/killbill/killbill"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/killbill/killbill/license", "name": "Kill Bill", "repository_url": "https://github.com/killbill/killbill", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T17:12:26.450000+08:00", "kind": "repository_metadata", "sha256": "3443f0b7165cc7eb4f8e8812827b3cf5511d40cf907288fc7640abba69ae0f65", "snapshot_path": "sources/3443f0b7165cc7eb4f8e8812827b3cf5511d40cf907288fc7640abba69ae0f65.txt", "url": "https://api.github.com/repos/killbill/killbill"}, {"fetched_at": "2026-10-24T17:12:28.083769+08:00", "kind": "license", "sha256": "f821f25c4b850abca9170bd1c3da13f5c59c36b3282f4787d83289b0af65ca8a", "snapshot_path": "sources/f821f25c4b850abca9170bd1c3da13f5c59c36b3282f4787d83289b0af65ca8a.txt", "url": "https://api.github.com/repos/killbill/killbill/license"}, {"fetched_at": "2026-10-24T16:28:11.755746+08:00", "kind": "readme", "sha256": "876ccc55eb745a396df32cc098154d4232600714ca3c5fb72338eb4c9ef32fcb", "snapshot_path": "sources/876ccc55eb745a396df32cc098154d4232600714ca3c5fb72338eb4c9ef32fcb.txt", "url": "https://raw.githubusercontent.com/killbill/killbill/master/README.md"}, {"fetched_at": "2026-10-24T16:55:59.753745+08:00", "kind": "documentation", "sha256": "658c98d4b2a006bef14524e497a3091cb9196a55c44f729ed821a99beb4f8fa8", "snapshot_path": "sources/658c98d4b2a006bef14524e497a3091cb9196a55c44f729ed821a99beb4f8fa8.txt", "url": "https://docs.killbill.io/userguide/account"}, {"fetched_at": "2026-10-26T12:17:12.425464+08:00", "kind": "documentation", "sha256": "59d8c8f8089cf2604dbc4e984c299676b5017533ab668d55c32c84b1d69c9aaa", "snapshot_path": "sources/59d8c8f8089cf2604dbc4e984c299676b5017533ab668d55c32c84b1d69c9aaa.txt", "url": "https://docs.killbill.io/latest/what_is_aviate"}, {"fetched_at": "2026-10-26T12:28:49.751221+08:00", "kind": "documentation", "sha256": "aabc1602ac41410a0824ab5863070ebb46a75ad4affa4b082ee13a30465105fe", "snapshot_path": "sources/aabc1602ac41410a0824ab5863070ebb46a75ad4affa4b082ee13a30465105fe.txt", "url": "https://docs.killbill.io/latest/features"}, {"fetched_at": "2026-10-26T12:27:51.036064+08:00", "kind": "documentation", "sha256": "5d8cac10e5c62e84e9fc2a2a3cce489868d74c65d7ebfc5a7d9d0e37d8989a4c", "snapshot_path": "sources/5d8cac10e5c62e84e9fc2a2a3cce489868d74c65d7ebfc5a7d9d0e37d8989a4c.txt", "url": "https://docs.killbill.io/latest/invoice_subsystem"}, {"fetched_at": "2026-10-26T12:28:51.426069+08:00", "kind": "documentation", "sha256": "41380d7e40c2f17b62f390e81ec65b49d4fff5bcc9e126a1bef99e4a1323a1cc", "snapshot_path": "sources/41380d7e40c2f17b62f390e81ec65b49d4fff5bcc9e126a1bef99e4a1323a1cc.txt", "url": "https://docs.killbill.io/latest/what_is_kill_bill"}, {"fetched_at": "2026-10-24T20:06:59.824413+08:00", "kind": "readme", "sha256": "b69bc01278ae41ea179e80045aaa69a4659200069fe9f5c85a0e724feba9c00b", "snapshot_path": "sources/b69bc01278ae41ea179e80045aaa69a4659200069fe9f5c85a0e724feba9c00b.txt", "url": "https://api.github.com/repos/killbill/killbill/readme"}], "summary": "Apache-2.0 开源自托管的订阅计费与支付平台：社区核心管理目录/定价、订阅、用量计费、发票、跨网关收款、信用、基础税务与催收；Aviate 企业版另提供增强计量、钱包、优惠券、进阶税务、自定义发票排序等扩展。", "technology_stack": ["Java", "REST API", "PostgreSQL", "Kaui Web管理界面"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:stripe-issuing','Stripe Issuing','{"homepage": "https://stripe.com", "id": "commercial:stripe-issuing", "leaf_matches": [{"reason": "官方Issuing文档与产品页说明以卡项目（program）为单位配置卡产品、持卡人类型与资金，创建实体/虚拟卡，提供实时授权、消费与生命周期控制、卡片状态管理及资金约束，覆盖发卡平台核心。", "slug": "card-issuing-platform", "source_urls": ["https://docs.stripe.com/issuing", "https://docs.stripe.com/issuing/cards", "https://stripe.com/issuing"]}], "name": "Stripe Issuing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:18:57.735852+08:00", "kind": "documentation", "sha256": "6ce9d28cf6a2aa05e2bd9d6142635d962fce37ab10343e8f972f28bdac2398c8", "snapshot_path": "sources/6ce9d28cf6a2aa05e2bd9d6142635d962fce37ab10343e8f972f28bdac2398c8.txt", "url": "https://docs.stripe.com/issuing"}, {"fetched_at": "2026-10-24T16:42:21.842494+08:00", "kind": "documentation", "sha256": "2383673be6ac0f05b4f83e7e05edba092ffd6047ca6bddf9db84bb49f04aa2f3", "snapshot_path": "sources/2383673be6ac0f05b4f83e7e05edba092ffd6047ca6bddf9db84bb49f04aa2f3.txt", "url": "https://docs.stripe.com/issuing/cards"}, {"fetched_at": "2026-10-24T16:19:00.122800+08:00", "kind": "documentation", "sha256": "6a201c2f3588aea9669c1c04999b43df70c948c89ef3639f516d64d534536767", "snapshot_path": "sources/6a201c2f3588aea9669c1c04999b43df70c948c89ef3639f516d64d534536767.txt", "url": "https://stripe.com/issuing"}], "summary": "发卡基础设施平台，支持卡项目管理、实体卡与虚拟卡发行、实时授权与消费控制。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ramp','Ramp','{"homepage": "https://ramp.com", "id": "commercial:ramp", "leaf_matches": [{"reason": "官方支出管理页说明公司卡、报销与账单支付在同一平台流转，交易自动分类并附收据匹配，管理员可设置预算与供应商支出护栏、阻止违规采购，覆盖组织发卡、公司侧支出记录与项目管理控制。", "slug": "corporate-card-spend-platform", "source_urls": ["https://ramp.com/spend-management"]}], "name": "Ramp", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:24:46.519196+08:00", "kind": "documentation", "sha256": "a64bfdf22f87929fa7a8d56f9c1179e4557ad411afd661257c21e19bdbf87ad9", "snapshot_path": "sources/a64bfdf22f87929fa7a8d56f9c1179e4557ad411afd661257c21e19bdbf87ad9.txt", "url": "https://ramp.com/spend-management"}], "summary": "企业卡与支出管理平台，统一公司卡、报销与账单支付，并提供预算与政策控制。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:nortridge-loan-collections','Nortridge Loan Collections','{"homepage": "https://nortridge.com", "id": "commercial:nortridge-loan-collections", "leaf_matches": [{"reason": "官方Loan Collections页说明集中查看逾期账户、借款人历史与逾期款项，按规则生成催收队列与自动提醒，跟踪承诺还款的履行与违约，并通过邮件、短信与拨号器开展活动，覆盖逾期账户、催收处置与处置历史。", "slug": "collections-platform", "source_urls": ["https://nortridge.com/collections/"]}], "name": "Nortridge Loan Collections", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:28:03.563122+08:00", "kind": "documentation", "sha256": "fdc65f5973c3a3ef99991c91c842abf2a74bc607aef46a85d511c99540cc5d27", "snapshot_path": "sources/fdc65f5973c3a3ef99991c91c842abf2a74bc607aef46a85d511c99540cc5d27.txt", "url": "https://nortridge.com/collections/"}], "summary": "贷款机构的催收工作平台，集中逾期账户、催收队列、承诺还款跟踪与自动催收活动。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:finastra-loan-iq','Finastra Loan IQ','{"homepage": "https://www.finastra.com", "id": "commercial:finastra-loan-iq", "leaf_matches": [{"reason": "官方Loan IQ页说明其为商业贷款平台，服务银团、双边、CRE、SBA等贷款类型，在统一平台自动化贷款服务、集中管理贷款组合，并提及交易建立、booking、生命周期数据流转，覆盖商业借款人、贷款账户服务循环与全生命周期交易管理。", "slug": "commercial-loan-management", "source_urls": ["https://www.finastra.com/solutions/loan-iq"]}], "name": "Finastra Loan IQ", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:23:04.139769+08:00", "kind": "documentation", "sha256": "47f8a265915a74ec06490cd652315e0e770c6d13da1accea439926396a506aa6", "snapshot_path": "sources/47f8a265915a74ec06490cd652315e0e770c6d13da1accea439926396a506aa6.txt", "url": "https://www.finastra.com/solutions/loan-iq"}], "summary": "商业贷款服务系统，支持银团与双边贷款的记账、服务、交易生命周期与组合管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:abrigo-commercial-lending','Abrigo Commercial Lending','{"homepage": "https://abrigo.com", "id": "commercial:abrigo-commercial-lending", "leaf_matches": [{"reason": "官方商业贷款页说明其自动化数据收集、工作流路由、信贷备忘录生成与审批跟踪，并内置机构信贷政策校验；官方平台页说明工作流跨越受理、承保与成交（closing）阶段；官方开发者文档进一步说明在Sageworks中完成受理、承保、决策与文件准备后，可将贷款标记为待入账并执行Board Loan to Core、关联拟入账贷款与组合贷款。据此覆盖商业借款人、在办信贷案件、政策下审批与入账交接；来源未明确放款/资金划拨作业，故不作该断言。", "slug": "commercial-loan-origination", "source_urls": ["https://www.abrigo.com/software/lending-and-credit-risk/sageworks-lending-software", "https://www.abrigo.com/software/lending-and-credit-risk/", "https://developer.abrigo.com/docs/copy-of-boarding-loans"]}], "name": "Abrigo Commercial Lending", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:26:50.484543+08:00", "kind": "documentation", "sha256": "2b7b389b4b783582dc54a3b3e542aedfd03b77c1d33dd241c82303d9f1a3fa36", "snapshot_path": "sources/2b7b389b4b783582dc54a3b3e542aedfd03b77c1d33dd241c82303d9f1a3fa36.txt", "url": "https://www.abrigo.com/software/lending-and-credit-risk/sageworks-lending-software"}, {"fetched_at": "2026-10-26T12:28:44.713738+08:00", "kind": "documentation", "sha256": "df7d46d314c022ce6af48bfc5b226a3592f0fcfce2ab882a6165d0c355e5fe03", "snapshot_path": "sources/df7d46d314c022ce6af48bfc5b226a3592f0fcfce2ab882a6165d0c355e5fe03.txt", "url": "https://developer.abrigo.com/docs/copy-of-boarding-loans"}, {"fetched_at": "2026-10-26T12:29:22.594561+08:00", "kind": "documentation", "sha256": "037965a5576ddec0a5baaa679760d8ce1b098cf10422f77abbf6f7f4d0d2e00a", "snapshot_path": "sources/037965a5576ddec0a5baaa679760d8ce1b098cf10422f77abbf6f7f4d0d2e00a.txt", "url": "https://www.abrigo.com/software/lending-and-credit-risk/"}], "summary": "面向银行与信用社的商业贷款发起平台，覆盖申请受理、数据收集、工作流路由、信贷备忘录、审批与成交文件核查，并向核心系统完成入账交接。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:turnkey-lender','TurnKey Lender','{"homepage": "https://www.turnkey-lender.com", "id": "commercial:turnkey-lender", "leaf_matches": [{"reason": "官方平台页说明同一系统提供Loan Origination、Credit Scoring与Underwriting、Decision Engine自动审批、Loan Management与Debt Collection，并明确面向Consumer Lending，覆盖申请、授信、放款、账户服务与催收链条。", "slug": "consumer-lending-platform", "source_urls": ["https://www.turnkey-lender.com/loan-management-software/", "https://www.turnkey-lender.com/"]}], "name": "TurnKey Lender", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:42:24.331152+08:00", "kind": "documentation", "sha256": "7f1d9244766c6add8c61ff34cc6853aa4f68d2cd23c5ca2c59fc2e997ee2806a", "snapshot_path": "sources/7f1d9244766c6add8c61ff34cc6853aa4f68d2cd23c5ca2c59fc2e997ee2806a.txt", "url": "https://www.turnkey-lender.com/loan-management-software/"}, {"fetched_at": "2026-10-24T16:28:05.815866+08:00", "kind": "documentation", "sha256": "f412c8dde0854e217b82515076df911386b012de6abf2bcb8d9317f8f748bc31", "snapshot_path": "sources/f412c8dde0854e217b82515076df911386b012de6abf2bcb8d9317f8f748bc31.txt", "url": "https://www.turnkey-lender.com/"}], "summary": "消费信贷自动化平台，集成贷款申请、评分决策、放款、贷后管理与催收。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:48418599','Apache Fineract','{"deployment": ["自托管（Docker Compose快速启动）", "云部署", "Kubernetes（社区部署方式）"], "features": ["客户与KYC资料管理", "贷款与储蓄产品配置及组合管理", "集成实时会计与报表", "OpenAPI与业务事件"], "github_repository_id": 48418599, "homepage": "https://fineract.apache.org", "id": "github:48418599", "leaf_matches": [{"reason": "官方README称其为开源核心银行平台，官网说明其提供客户端数据管理、贷款与储蓄组合管理、集成实时会计与报表，并支持灵活产品配置、KYC文档与还款记录，覆盖客户、账户、产品与账务的核心银行结构。", "slug": "core-banking-system", "source_urls": ["https://api.github.com/repos/apache/fineract", "https://api.github.com/repos/apache/fineract/license", "https://raw.githubusercontent.com/apache/fineract/develop/README.md", "https://fineract.apache.org/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/apache/fineract/license", "name": "Apache Fineract", "repository_url": "https://github.com/apache/fineract", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T17:12:37.171843+08:00", "kind": "repository_metadata", "sha256": "f7d6b1219761cd174ff9e346681946f20d9ba69fb581d2a6d9889afaa3cb9c7a", "snapshot_path": "sources/f7d6b1219761cd174ff9e346681946f20d9ba69fb581d2a6d9889afaa3cb9c7a.txt", "url": "https://api.github.com/repos/apache/fineract"}, {"fetched_at": "2026-10-24T17:12:38.772545+08:00", "kind": "license", "sha256": "4b0c55f18d81ed0b7e6f87eee5e2c286f4edda7b970ae62c7e6604828c8a0b6b", "snapshot_path": "sources/4b0c55f18d81ed0b7e6f87eee5e2c286f4edda7b970ae62c7e6604828c8a0b6b.txt", "url": "https://api.github.com/repos/apache/fineract/license"}, {"fetched_at": "2026-10-24T16:16:07.845813+08:00", "kind": "readme", "sha256": "6a0cf4f6d44de882e4ee31f7fb3128c1278a0ca352b2691f1f7834092332addf", "snapshot_path": "sources/6a0cf4f6d44de882e4ee31f7fb3128c1278a0ca352b2691f1f7834092332addf.txt", "url": "https://raw.githubusercontent.com/apache/fineract/develop/README.md"}, {"fetched_at": "2026-10-24T16:33:21.143765+08:00", "kind": "homepage", "sha256": "28af9fc75d0868578b5b927c0f115566e2fdde13c6