INSERT INTO "application" VALUES('commercial:collect-comtech','Collect! by Comtech Systems','{"homepage": "https://www.collect.org", "id": "commercial:collect-comtech", "leaf_matches": [{"reason": "官方Solutions页说明可配置工作队列与业务规则将账户分配给催收员、批量信函与邮件整合、客户与消费者两个自助门户按客户范围展示余额与进展，并提供信用局报送、短信与拨号器模块及监管控制，覆盖代理视角的工作队列、外联、支付与客户报告。", "slug": "debt-collection-management", "source_urls": ["https://www.collect.org/solutions/", "https://www.collect.org/"]}], "name": "Collect! by Comtech Systems", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:26:59.556415+08:00", "kind": "documentation", "sha256": "70d8f43bd1681a2b37e20a22d4f4c3770b55868d971e50e8538b76c3546ba9db", "snapshot_path": "sources/70d8f43bd1681a2b37e20a22d4f4c3770b55868d971e50e8538b76c3546ba9db.txt", "url": "https://www.collect.org/solutions/"}, {"fetched_at": "2026-10-24T16:16:10.872251+08:00", "kind": "homepage", "sha256": "5a63d6573dc40f1f5cfc4cc6e379e5708c22ebc30e3957fafbc433e08e9c3bfa", "snapshot_path": "sources/5a63d6573dc40f1f5cfc4cc6e379e5708c22ebc30e3957fafbc433e08e9c3bfa.txt", "url": "https://www.collect.org/"}], "summary": "面向催收机构与应收管理团队的债务催收系统，提供队列、信函、门户与合规工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:loanpro','LoanPro','{"homepage": "https://www.loanpro.io", "id": "commercial:loanpro", "leaf_matches": [{"reason": "官方Servicing Suite页说明其以实时账本管理放款后的全部账户活动，包括还款、利息计提、费用与状态维护，并支持商业、消费、汽车、租赁与信用额度等产品，覆盖贷款账户、可计算条款、周期性服务循环与账户生命周期管理。", "slug": "loan-management-system", "source_urls": ["https://www.loanpro.io/platform/servicing-suite"]}], "name": "LoanPro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:20:02.407080+08:00", "kind": "documentation", "sha256": "8c0428c517aef77ef4873b5b6e1d9c0850814b3164e6ee7f1e72ec51bc69e57a", "snapshot_path": "sources/8c0428c517aef77ef4873b5b6e1d9c0850814b3164e6ee7f1e72ec51bc69e57a.txt", "url": "https://www.loanpro.io/platform/servicing-suite"}], "summary": "API优先的贷款服务与信贷平台，管理贷后账户、还款、利息计提与账务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:meridianlink','MeridianLink','{"homepage": "https://www.meridianlink.com", "id": "commercial:meridianlink", "leaf_matches": [{"reason": "官方Loan Origination Software页说明统一数字贷款平台支持消费、抵押、商业与间接贷款的完整生命周期，连接申请、决策与后续流程，并列出Collections与间接贷款渠道，覆盖申请案件、贷款方发起管线与授信评估。", "slug": "loan-origination-system", "source_urls": ["https://www.meridianlink.com/solutions/loan-origination-software/", "https://www.meridianlink.com/products/"]}], "name": "MeridianLink", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T12:37:26.737002+08:00", "kind": "documentation", "sha256": "0fbcbe66770ae55ae67bd710fa7712a860da427e7d34745367d8949f627a57b1", "snapshot_path": "sources/0fbcbe66770ae55ae67bd710fa7712a860da427e7d34745367d8949f627a57b1.txt", "url": "https://www.meridianlink.com/solutions/loan-origination-software/"}, {"fetched_at": "2026-10-24T16:20:05.879585+08:00", "kind": "documentation", "sha256": "e163a2c6265ba8352dd79e30d9bf4257fcdbcfc9a999adeed987bbd07ca51b2c", "snapshot_path": "sources/e163a2c6265ba8352dd79e30d9bf4257fcdbcfc9a999adeed987bbd07ca51b2c.txt", "url": "https://www.meridianlink.com/products/"}], "summary": "面向银行、信用社与抵押/汽车贷款机构的数字贷款发起平台，连接申请、决策与放款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ice-encompass','ICE Encompass','{"homepage": "https://mortgagetech.ice.com", "id": "commercial:ice-encompass", "leaf_matches": [{"reason": "官方Encompass页称其为行业记录系统，连接并加速贷款流程各环节，提供工作流、定价引擎、TPO与eClose等组件，按贷款记录推进承销与交割，覆盖抵押贷款申请案件与贷款方发起流程。", "slug": "mortgage-origination-platform", "source_urls": ["https://mortgagetech.ice.com/products/encompass/"]}], "name": "ICE Encompass", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:28:17.731307+08:00", "kind": "documentation", "sha256": "140fa6228920a297a052e7217d5affa198681787acd5db36721ca01cbe0a307f", "snapshot_path": "sources/140fa6228920a297a052e7217d5affa198681787acd5db36721ca01cbe0a307f.txt", "url": "https://mortgagetech.ice.com/products/encompass/"}], "summary": "抵押贷款发起系统，作为贷款机构记录系统贯穿申请、处理、承销、定价与电子交割。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sagent-dara','Sagent Dara','{"homepage": "https://sagent.com", "id": "commercial:sagent-dara", "leaf_matches": [{"reason": "官方 Dara 首页与 Establish & Manage / Engage & Assist 产品页显示其为面向银行与贷款机构的住宅抵押贷款服务软件：Transfer & Boarding 覆盖贷款转入服务、校验与工作流管理；Loan Administration 集中维护贷款级属性、规则与运营控制；Money Management 实时执行并跟踪还款处理、公司垫款与交易管理；Escrow 覆盖托管分析、短缺与计算；Investor Management 覆盖服务协议、报告要求与托管管理；Collections 监控逾期并组织外联；Loss Mitigation 提供困难援助工作流与决策。结合首页 16M+ 活跃服务贷款与 $1.4B+ 月度还款处理规模，可支持服务账户、还款/托管/投资者报告等周期性服务处理与贷后管理；页面未披露利息计提、对账单生成与分配瀑布细节。", "slug": "mortgage-servicing-platform", "source_urls": ["https://sagent.com/dara/establish-manage/", "https://sagent.com/dara/engage-assist/", "https://sagent.com/"]}], "name": "Sagent Dara", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:22:15.587577+08:00", "kind": "documentation", "sha256": "e29ce7e6d2f892acccb7c662555e162a8ce9080dbd913ce4fb1870ac6b4554c4", "snapshot_path": "sources/e29ce7e6d2f892acccb7c662555e162a8ce9080dbd913ce4fb1870ac6b4554c4.txt", "url": "https://sagent.com/"}, {"fetched_at": "2026-10-26T12:35:51.536098+08:00", "kind": "documentation", "sha256": "daccac3fd14efaf2b42118c56220bbfa9fca378c527b9dbc49b80355d52d11f2", "snapshot_path": "sources/daccac3fd14efaf2b42118c56220bbfa9fca378c527b9dbc49b80355d52d11f2.txt", "url": "https://sagent.com/dara/establish-manage/"}, {"fetched_at": "2026-10-26T12:35:57.484474+08:00", "kind": "documentation", "sha256": "d1b27413ecbca67dccca5121bfba15aacc0c673c9d32afc50f0a00f756cb77ac", "snapshot_path": "sources/d1b27413ecbca67dccca5121bfba15aacc0c673c9d32afc50f0a00f756cb77ac.txt", "url": "https://sagent.com/dara/engage-assist/"}], "summary": "住宅抵押贷款服务平台的统一工作环境，覆盖贷款管理、资金与托管、投资者报告要求及催收/损失缓解。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:561734951','Jube','{"deployment": ["Docker Compose单节点评估部署", "Jube Cluster（Docker Swarm）高可用生产部署"], "features": ["实时AML与欺诈交易监控", "规则、速度、制裁名单与有监督/无监督机器学习混合检测", "案例管理与合规人员可编辑的规则构建器", "多租户与水平扩展"], "github_repository_id": 561734951, "homepage": "https://jube.io/", "id": "github:561734951", "leaf_matches": [{"reason": "README明确其为实时AML/欺诈交易监控平台，以规则、速度和制裁名单结合有监督/无监督机器学习检测交易，提供案例管理与可编辑规则，并说明可自托管、多租户与集群部署；覆盖交易流检测→警报→案例管理工作流，人工分诊/处置字段与监管报送格式未在已读资料中核验。", "slug": "transaction-monitoring-platform", "source_urls": ["https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring/readme", "https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring/license", "name": "Jube", "repository_url": "https://github.com/jube-home/aml-fraud-transaction-monitoring", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:07:02.384528+08:00", "kind": "repository_metadata", "sha256": "97fa0c186d63f34162f3c0c5d8320ca61abedf89452e2a07bb5c4e7d502cc274", "snapshot_path": "sources/97fa0c186d63f34162f3c0c5d8320ca61abedf89452e2a07bb5c4e7d502cc274.txt", "url": "https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring"}, {"fetched_at": "2026-10-24T20:07:05.609016+08:00", "kind": "license", "sha256": "77f698d09e871bdb2f1bccff61cff0fc43fba4d439afc8d6738488ad802a16f0", "snapshot_path": "sources/77f698d09e871bdb2f1bccff61cff0fc43fba4d439afc8d6738488ad802a16f0.txt", "url": "https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring/license"}, {"fetched_at": "2026-10-24T20:07:07.083929+08:00", "kind": "readme", "sha256": "f25ab4c730d677b285f9b216c29e495309066ad9adb0ddc9226d1d9d2c88f15a", "snapshot_path": "sources/f25ab4c730d677b285f9b216c29e495309066ad9adb0ddc9226d1d9d2c88f15a.txt", "url": "https://api.github.com/repos/jube-home/aml-fraud-transaction-monitoring/readme"}], "summary": "开源自托管的实时交易监控平台，以可配置规则与机器学习检测AML/欺诈风险，并提供案例管理。", "technology_stack": ["C#/.NET", "PostgreSQL", "Redis", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:nomentia','Nomentia Smart Treasury Suite','{"homepage": "https://www.nomentia.com/", "id": "commercial:nomentia", "leaf_matches": [{"reason": "官方Debt & Investments页说明以单一交易登记簿跟踪外部与公司间贷款、债券、商业票据、存款、存单及融资额度，自动处理本金/利息/费用/应计现金流和估值，提供利用率、余量、到期与成本视图，并输出财资会计过账至ERP；覆盖企业自身财资交易台账与生命周期。衍生品、担保、敞口/风险与现金池仅见于站点导航，未作为核心证据。", "slug": "treasury-management-system", "source_urls": ["https://www.nomentia.com/smart-treasury-suite/manage/debt-and-investments", "https://www.nomentia.com/"]}, {"reason": "现金定位页正文说明按账户/银行/币种/实体及集团层级合并现金、存款、投资、债务与授信额度并展示 headroom；现金流预测页说明合并 ERP/银行/子公司/财资数据的滚动预测、情景与差异分析；两页连同现金池/目标余额调拨构成头寸—预测—资金引导核心。", "slug": "liquidity-management-platform", "source_urls": ["https://www.nomentia.com/smart-treasury-suite/view/cash-flow-forecasting", "https://www.nomentia.com/smart-treasury-suite/view/cash-positioning"]}], "name": "Nomentia Smart Treasury Suite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:05.919153+08:00", "kind": "homepage", "sha256": "b9222197a14d9fae75ca604e0778a17f06acce5c38756e8c7c4d13be8443c25c", "snapshot_path": "sources/b9222197a14d9fae75ca604e0778a17f06acce5c38756e8c7c4d13be8443c25c.txt", "url": "https://www.nomentia.com/"}, {"fetched_at": "2026-10-24T20:27:07.806700+08:00", "kind": "documentation", "sha256": "3eb85108d817573d3e22afe4c449d13052327b9e1cb07fccfbe12a002de5eafd", "snapshot_path": "sources/3eb85108d817573d3e22afe4c449d13052327b9e1cb07fccfbe12a002de5eafd.txt", "url": "https://www.nomentia.com/smart-treasury-suite/manage/debt-and-investments"}, {"fetched_at": "2026-10-26T17:11:36.496371+08:00", "kind": "documentation", "sha256": "345c575a1a4c6efe09f89ff82c69d18290ddc0f4ad599a198ad979cc991776d0", "snapshot_path": "sources/345c575a1a4c6efe09f89ff82c69d18290ddc0f4ad599a198ad979cc991776d0.txt", "url": "https://www.nomentia.com/smart-treasury-suite/view/cash-flow-forecasting"}, {"fetched_at": "2026-10-26T17:11:38.416118+08:00", "kind": "documentation", "sha256": "d65181632a83eacadb536d6dcb1c50752552524529394fd0b6418d252b4e0a3a", "snapshot_path": "sources/d65181632a83eacadb536d6dcb1c50752552524529394fd0b6418d252b4e0a3a.txt", "url": "https://www.nomentia.com/smart-treasury-suite/view/cash-positioning"}], "summary": "企业财资管理套件，在单一交易登记簿中管理债务、存款、商业票据、存单及融资额度，自动处理现金流、利息、费用与会计，并提供利用率、到期与成本视图。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:addepar','Addepar','{"homepage": "https://addepar.com", "id": "commercial:addepar", "leaf_matches": [{"reason": "Platform Overview说明其将公私资产统一建模为单一数据源，提供定制化报告与品牌化客户门户；Why Addepar页说明其聚合客户在各机构的全部金融账户与投资并形成合并视图，并以专用费用管理系统处理复杂费率、资产排除与估值方法、自动化账单计算与复核。覆盖客户与资产结构记录、综合财富视图与计费/报告机制；托管、交易执行与角色权限/合规监督未在已读页面证实，故不写入。", "slug": "wealth-management-platform", "source_urls": ["https://addepar.com/platform-overview", "https://addepar.com/why-addepar"]}], "name": "Addepar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:11.277422+08:00", "kind": "documentation", "sha256": "175ed7d33a5e6a8bd4d51e63fa8269050babbfdc5c9720b7ff6ec93fd3ff90c3", "snapshot_path": "sources/175ed7d33a5e6a8bd4d51e63fa8269050babbfdc5c9720b7ff6ec93fd3ff90c3.txt", "url": "https://addepar.com/platform-overview"}, {"fetched_at": "2026-10-24T20:27:13.241732+08:00", "kind": "documentation", "sha256": "eddf69ed7b9ca9a0b34b954b5520ace10ec861569278eab4964f49bbf253a79f", "snapshot_path": "sources/eddf69ed7b9ca9a0b34b954b5520ace10ec861569278eab4964f49bbf253a79f.txt", "url": "https://addepar.com/why-addepar"}], "summary": "面向财富管理机构的组合数据平台，聚合客户全部账户与另类资产，并提供报告、客户门户与费用计算/账单复核。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:stampli','Stampli','{"homepage": "https://www.stampli.com/", "id": "commercial:stampli", "leaf_matches": [{"reason": "官方AP Automation页说明其与ERP集成，自动完成发票捕获、编码、审批路由与重复发票检查，并将沟通与流程集中在发票上；覆盖供应商发票结构化、审批关卡与ERP会计交接，付款执行属其相邻产品模块，未计入核心。", "slug": "accounts-payable-automation", "source_urls": ["https://www.stampli.com/ap-automation/"]}], "name": "Stampli", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:16.026910+08:00", "kind": "documentation", "sha256": "02cd5909b25ff88d8de1553c24757b304ea284f8fbd634c6bb8f75031c449d3d", "snapshot_path": "sources/02cd5909b25ff88d8de1553c24757b304ea284f8fbd634c6bb8f75031c449d3d.txt", "url": "https://www.stampli.com/ap-automation/"}], "summary": "应付账款自动化平台，将供应商发票捕获为结构化记录，自动编码、路由审批并与ERP集成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:billtrust','Billtrust','{"homepage": "https://www.billtrust.com/", "id": "commercial:billtrust", "leaf_matches": [{"reason": "官网将开票、付款、信用、催收与现金应用组织为同一AR平台，说明自动应用汇款、按优先级编排催收流程并持续更新信用决策，页面另称提供200+ ERP/银行连接器；覆盖未结应收群体—催收活动—现金核销—账簿一致，具体ERP字段级集成未核验。", "slug": "accounts-receivable-management", "source_urls": ["https://www.billtrust.com/"]}], "name": "Billtrust", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:31:44.448639+08:00", "kind": "homepage", "sha256": "59228f04d111687ce7993ea8e9443109e79a68d85a3b519f2126cce9653cb2cb", "snapshot_path": "sources/59228f04d111687ce7993ea8e9443109e79a68d85a3b519f2126cce9653cb2cb.txt", "url": "https://www.billtrust.com/"}], "summary": "应收账款自动化平台，覆盖开票、付款、信用、催收与现金应用，并将回款与未结发票匹配。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:chaser','Chaser','{"homepage": "https://www.chaserhq.com/", "id": "commercial:chaser", "leaf_matches": [{"reason": "官方页说明与会计系统双向同步应收数据，自动发送催款邮件、短信与电话，提供客户门户、付款计划与任务管理，并在付款后自动停止提醒；覆盖余额群体、催收追讨与付款结果，争议与核销状态未在已读页面证实，故不写入能力断言。", "slug": "collections-automation-platform", "source_urls": ["https://www.chaserhq.com/credit-control-accounts-receivables-software", "https://www.chaserhq.com/"]}], "name": "Chaser", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:21.896564+08:00", "kind": "documentation", "sha256": "2eab6d60fb7fba1ee2c3864a3155fd7dc927bfe80960fd90b8ddaebaa95ea690", "snapshot_path": "sources/2eab6d60fb7fba1ee2c3864a3155fd7dc927bfe80960fd90b8ddaebaa95ea690.txt", "url": "https://www.chaserhq.com/credit-control-accounts-receivables-software"}, {"fetched_at": "2026-10-24T19:44:15.548492+08:00", "kind": "homepage", "sha256": "4e4fd74061d693ce929cc8d5a3f20509a85b5e7a1b76b90d41ce797890979412", "snapshot_path": "sources/4e4fd74061d693ce929cc8d5a3f20509a85b5e7a1b76b90d41ce797890979412.txt", "url": "https://www.chaserhq.com/"}], "summary": "应收账款催收自动化软件，从会计系统同步应收数据，自动发送催款提醒并跟踪付款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:thomson-reuters-onesource','Thomson Reuters ONESOURCE','{"homepage": "https://tax.thomsonreuters.com/", "id": "commercial:thomson-reuters-onesource", "leaf_matches": [{"reason": "Tax Provision页说明从ERP与Excel工作底稿汇集数据，自动生成税务报告、附注与分录并支持实体级下钻与审计；Income Tax页说明多实体多辖区企业税申报、电子报送及与准备金/预估税款模块联动，覆盖实体×辖区×期间的税务计算与正式交付；间接税判定不并入本叶。", "slug": "corporate-tax-management", "source_urls": ["https://tax.thomsonreuters.com/en/products/onesource-tax-provision", "https://tax.thomsonreuters.com/en/products/onesource-income-tax"]}], "name": "Thomson Reuters ONESOURCE", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:43.437232+08:00", "kind": "documentation", "sha256": "b41da4c54ad5505b7c5b870d3891dbcd6a3d1f1094d956e7a58a8ae4af72e755", "snapshot_path": "sources/b41da4c54ad5505b7c5b870d3891dbcd6a3d1f1094d956e7a58a8ae4af72e755.txt", "url": "https://tax.thomsonreuters.com/en/products/onesource-tax-provision"}, {"fetched_at": "2026-10-24T20:27:46.308903+08:00", "kind": "documentation", "sha256": "f75bf7dd16ee3065d1a746f7c882db0b3e398b520834e1ed258ae55a65013add", "snapshot_path": "sources/f75bf7dd16ee3065d1a746f7c882db0b3e398b520834e1ed258ae55a65013add.txt", "url": "https://tax.thomsonreuters.com/en/products/onesource-income-tax"}], "summary": "企业税务软件套件，覆盖税务准备金计算与企业所得税申报，并可与ERP及Excel工作底稿集成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:medius','Medius','{"homepage": "https://www.medius.com/", "id": "commercial:medius", "leaf_matches": [{"reason": "Invoice Automation页说明从纸质、邮件、EDI与电子发票摄取并结构化发票，以机器学习自动编码、按规则路由审批并标记异常；Invoice Capture页说明与SAP、Oracle、NetSuite、Dynamics等ERP集成，覆盖捕获—验证—审批—ERP交接，付款执行属相邻模块。", "slug": "invoice-processing-platform", "source_urls": ["https://www.medius.com/solutions/medius-accounts-payable-automation/invoice-automation/", "https://www.medius.com/solutions/medius-accounts-payable-automation/invoice-capture/"]}], "name": "Medius", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:49.532956+08:00", "kind": "documentation", "sha256": "773840ce2622d1ecccc902637ea2925a56be4c297fd90efe2b44799932bb8c6d", "snapshot_path": "sources/773840ce2622d1ecccc902637ea2925a56be4c297fd90efe2b44799932bb8c6d.txt", "url": "https://www.medius.com/solutions/medius-accounts-payable-automation/invoice-automation/"}, {"fetched_at": "2026-10-24T20:27:51.726774+08:00", "kind": "documentation", "sha256": "57575f63d2bc19fa26eccc9f5769e6138275585d79477267d2ba779afee3674c", "snapshot_path": "sources/57575f63d2bc19fa26eccc9f5769e6138275585d79477267d2ba779afee3674c.txt", "url": "https://www.medius.com/solutions/medius-accounts-payable-automation/invoice-capture/"}], "summary": "应付账款与发票自动化平台，自动摄取并结构化供应商发票，完成编码、审批与ERP交接。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:222873550','Crater','{"deployment": ["自托管Web应用", "Docker镜像"], "features": ["客户与发票/估算单管理", "记录费用与付款并追踪发票状态", "周期性发票与客户门户", "多公司支持"], "github_repository_id": 222873550, "homepage": "https://craterapp.com/", "id": "github:222873550", "leaf_matches": [{"reason": "README说明其为开源Web与移动开票应用，可创建专业发票与估算单、跟踪费用与付款，并列出周期性发票、客户门户、多公司与在线收款等已完成项；仓库元数据与许可证确认AGPL-3.0，覆盖客户记录—发票文件—交付与付款状态；不把它当作会计账簿。", "slug": "invoicing-application", "source_urls": ["https://api.github.com/repos/crater-invoice-inc/crater/readme", "https://api.github.com/repos/crater-invoice-inc/crater"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/crater-invoice-inc/crater/license", "name": "Crater", "repository_url": "https://github.com/crater-invoice-inc/crater", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:06:52.858846+08:00", "kind": "repository_metadata", "sha256": "785dc1872a76e85b5d6770a38ce4ac5a5de2788515ccb5d9dc5f81e98f39aab3", "snapshot_path": "sources/785dc1872a76e85b5d6770a38ce4ac5a5de2788515ccb5d9dc5f81e98f39aab3.txt", "url": "https://api.github.com/repos/crater-invoice-inc/crater"}, {"fetched_at": "2026-10-24T20:06:55.100116+08:00", "kind": "license", "sha256": "515a6b2087e63b811f64107b21c8f34d552bf0f632678f716b7c159db7ede003", "snapshot_path": "sources/515a6b2087e63b811f64107b21c8f34d552bf0f632678f716b7c159db7ede003.txt", "url": "https://api.github.com/repos/crater-invoice-inc/crater/license"}, {"fetched_at": "2026-10-24T20:06:56.553194+08:00", "kind": "readme", "sha256": "501aec1eead999a644405e0f6b2c0e941a25cc2002288517f40950e41daa21a8", "snapshot_path": "sources/501aec1eead999a644405e0f6b2c0e941a25cc2002288517f40950e41daa21a8.txt", "url": "https://api.github.com/repos/crater-invoice-inc/crater/readme"}], "summary": "开源自托管开票应用，维护客户记录、开具发票与估算单并记录付款。", "technology_stack": ["PHP/Laravel", "VueJS", "React Native"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vertex','Vertex','{"homepage": "https://www.vertexinc.com/", "id": "commercial:vertex", "leaf_matches": [{"reason": "官方Sales & Use Tax页说明实时税务判定、免税证书管理、跨辖区生成可签报税表与电子申报格式，并提供面向申报与审计的报告；交易级判定与申报表生成有据。页面仅将申报/缴纳列为外包服务卡片，未证明由Vertex实际向税务机关传输或提交，故不声称实际报送。持久交易记录的存储方式未在页面细述，故不声称具体数据模型。", "slug": "tax-compliance-platform", "source_urls": ["https://www.vertexinc.com/solutions/tax-type/sales-use-tax"]}], "name": "Vertex", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:54.559059+08:00", "kind": "documentation", "sha256": "020fb7ae890f8715e87de9621ec9fc37a1e9ca7f3e7ffd2b39428ab5d3008780", "snapshot_path": "sources/020fb7ae890f8715e87de9621ec9fc37a1e9ca7f3e7ffd2b39428ab5d3008780.txt", "url": "https://www.vertexinc.com/solutions/tax-type/sales-use-tax"}], "summary": "销售与使用税合规平台，提供交易级税额判定、免税证书管理及申报表与电子申报格式生成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tax1099','Tax1099','{"homepage": "https://www.tax1099.com/", "id": "commercial:tax1099", "leaf_matches": [{"reason": "官网列示向IRS、SSA与CFS eFile、更正/作废申报、计划申报、被IRS拒绝后重报、TIN匹配、记录保存与审计轨迹，覆盖申报记录—机关格式校验—授权通道传输—受理/拒绝更正循环；不评价其税务计算或准备能力。", "slug": "tax-filing-platform", "source_urls": ["https://www.tax1099.com/"]}], "name": "Tax1099", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:27:57.424633+08:00", "kind": "homepage", "sha256": "7391ee3715bdf9c75dd6dc944ed2792d22692c828c82cfc266515ce93f11975b", "snapshot_path": "sources/7391ee3715bdf9c75dd6dc944ed2792d22692c828c82cfc266515ce93f11975b.txt", "url": "https://www.tax1099.com/"}], "summary": "美国税务信息申报平台，向IRS/SSA等电子报送1099、W-2等表格并处理受理与拒绝重报。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:taxact','TaxAct','{"homepage": "https://www.taxact.com/", "id": "commercial:taxact", "leaf_matches": [{"reason": "官网说明个人与企业可在线报税，提供引导式填报、税务数据导入、扣除与抵免计算并生成可提交申报表；免费版限定仅使用1040且不附表格/附表的情形，覆盖纳税人情况输入—表格组装—计算—交付，具体附表资格逻辑未逐项核验。", "slug": "tax-preparation-application", "source_urls": ["https://www.taxact.com/"]}], "name": "TaxAct", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:00.553144+08:00", "kind": "homepage", "sha256": "702c11e1597f7e57c6a615542029e3b9761728dad5f6a1d696cbcd8030b35686", "snapshot_path": "sources/702c11e1597f7e57c6a615542029e3b9761728dad5f6a1d696cbcd8030b35686.txt", "url": "https://www.taxact.com/"}], "summary": "个人与企业在线报税软件，按申报情形引导填报、导入数据并计算扣除与抵免后生成申报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:unit21','Unit21','{"homepage": "https://www.unit21.ai/", "id": "commercial:unit21", "leaf_matches": [{"reason": "官网说明其为统一欺诈与AML平台，包含交易监控、案件管理、支付与制裁筛查、监管报送，AI代理在人工复核下完成调查并保留完整审计轨迹；覆盖受监控客户与交易—可配置检测—警报—案件调查—监管报送闭环，不将其归为纯欺诈工具。", "slug": "aml-platform", "source_urls": ["https://www.unit21.ai/"]}], "name": "Unit21", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:04.193324+08:00", "kind": "homepage", "sha256": "dfea109e4a4727b25a3634ca588de8253521b9b2d28bdb76bfdb87e466231eb6", "snapshot_path": "sources/dfea109e4a4727b25a3634ca588de8253521b9b2d28bdb76bfdb87e466231eb6.txt", "url": "https://www.unit21.ai/"}], "summary": "面向金融科技与金融机构的欺诈与反洗钱平台，覆盖交易监控、案件调查、名单筛查与监管报送。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:provenir','Provenir','{"homepage": "https://www.provenir.com/", "id": "commercial:provenir", "leaf_matches": [{"reason": "Decisioning页说明以低代码规则与模型、数据整合和受治理AI代理执行高量决策，支持转人工案件、决策解释与审计叙事；Solutions页列出信贷准入的实时审批，覆盖申请评估—规则/模型决策—转人工与理由记录；放款与申请文件管理属发起系统，未并入。", "slug": "credit-decisioning-platform", "source_urls": ["https://www.provenir.com/platform/decisioning/", "https://www.provenir.com/solutions/"]}], "name": "Provenir", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:12.759894+08:00", "kind": "documentation", "sha256": "aaafd34e2271e150f2594a85a82866db2062257f6716e0c9b91e91fa5ec94559", "snapshot_path": "sources/aaafd34e2271e150f2594a85a82866db2062257f6716e0c9b91e91fa5ec94559.txt", "url": "https://www.provenir.com/solutions/"}, {"fetched_at": "2026-10-24T20:29:46.851748+08:00", "kind": "documentation", "sha256": "ae275a1d4dfa0425db406b7afd13868a5e90f93b051eb75474ba5c6adb665aeb", "snapshot_path": "sources/ae275a1d4dfa0425db406b7afd13868a5e90f93b051eb75474ba5c6adb665aeb.txt", "url": "https://www.provenir.com/platform/decisioning/"}], "summary": "信贷决策平台，以低代码规则与模型整合数据并输出可解释的信贷审批决策。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:highradius','HighRadius Credit Management','{"homepage": "https://www.highradius.com/", "id": "commercial:highradius", "leaf_matches": [{"reason": "官方Credit Management页说明自动信用评估、信用额度执行、订单阻断与解除、持续组合监控与预警，并覆盖从准入到定期复审的客户信用生命周期；覆盖客户信用账户—受治理额度—实时敞口—信用行动，仅记录信用层，不延伸为其应收账款或催收全流程。", "slug": "credit-management-platform", "source_urls": ["https://www.highradius.com/software/order-to-cash/credit-management/"]}], "name": "HighRadius Credit Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:16.361248+08:00", "kind": "documentation", "sha256": "782e31804b6491c6d7d43a2ba742d1665c1626664c8a4e6710636c82d41e70f4", "snapshot_path": "sources/782e31804b6491c6d7d43a2ba742d1665c1626664c8a4e6710636c82d41e70f4.txt", "url": "https://www.highradius.com/software/order-to-cash/credit-management/"}], "summary": "面向企业财务的信用管理软件，自动评估客户信用、执行信用额度、阻断订单并持续监控敞口。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sas-risk-management','SAS Risk Management','{"homepage": "https://www.sas.com/", "id": "commercial:sas-risk-management", "leaf_matches": [{"reason": "官方Risk Management页列出信用风险管理（面向贷款组合的可扩展信用模型）、风险引擎的敞口视图、监管资本、预期信用损失与压力测试；Risk Engine页说明以模型对海量头寸计算、聚合与分析信用敞口及CVA并做情景与压力测试，覆盖敞口记录—债务人质量—风险计量—组合监控；具体评级量表配置未在页面细述。", "slug": "credit-risk-platform", "source_urls": ["https://www.sas.com/en_us/solutions/risk-management.html", "https://www.sas.com/en_us/software/risk-engine.html"]}], "name": "SAS Risk Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:19.539693+08:00", "kind": "documentation", "sha256": "7cc3459d6d24e2352ff5c1a805db76ea043a414bf9b2076b3b04b62abb327b20", "snapshot_path": "sources/7cc3459d6d24e2352ff5c1a805db76ea043a414bf9b2076b3b04b62abb327b20.txt", "url": "https://www.sas.com/en_us/solutions/risk-management.html"}, {"fetched_at": "2026-10-24T20:40:26.183524+08:00", "kind": "documentation", "sha256": "c9959ba35ccb952f9bccfe6d97b20dcc481b67691864383b6ff57143cf5a171f", "snapshot_path": "sources/c9959ba35ccb952f9bccfe6d97b20dcc481b67691864383b6ff57143cf5a171f.txt", "url": "https://www.sas.com/en_us/software/risk-engine.html"}], "summary": "面向银行的风险管理软件，覆盖信用风险组合模型、敞口视图、监管资本、预期信用损失与压力测试。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:murex-mx3','Murex MX.3','{"homepage": "https://www.murex.com/", "id": "commercial:murex-mx3", "leaf_matches": [{"reason": "官方ERM页说明在同一平台控制市场、信用与流动性风险，提供实时限额与敞口监控、FRTB/SA-CCR/IM等监管计量，并以共享参考数据与统一计算框架保证跨报表风险数字一致；覆盖敞口—计量—企业聚合—监控，不将其归为单一风险类型平台。", "slug": "financial-risk-management-platform", "source_urls": ["https://www.murex.com/en/insights/brochure/mx3-market-risk-control", "https://www.murex.com/en/solutions/business-solutions/enterprise-risk-management"]}, {"reason": "财资页“Liquidity risk”段说明：整合银行账簿与含交易、证券借贷、回购抵押及质押品的集中证券库存，以现金流引擎生成合同流量、估计未来流量并实时监控流动性阶梯，同时优化 HQLA 缓冲并做合规检查；同页“Risk control”段与 ERM 页给出覆盖流动性风险的实时限额/敞口监控、超限后的限额暂停、阻断交易、超限原因与处理时长看板及限额重分配。三环（可检视融资头寸与缓冲、当前及压力情景下充足性、风险偏好下的限额—违规处置—治理报告）均由官方正文支撑；LCR/NSFR 等命名比率仅作表述，未作硬门槛。", "slug": "liquidity-risk-platform", "source_urls": ["https://www.murex.com/en/solutions/business-solutions/treasury-management", "https://www.murex.com/en/solutions/business-solutions/enterprise-risk-management"]}], "name": "Murex MX.3", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:22.901593+08:00", "kind": "documentation", "sha256": "7a6cc0db121603fd3f8e374b5fb5a6983d2ac6941c8b5077ea412619e9f47499", "snapshot_path": "sources/7a6cc0db121603fd3f8e374b5fb5a6983d2ac6941c8b5077ea412619e9f47499.txt", "url": "https://www.murex.com/en/insights/brochure/mx3-market-risk-control"}, {"fetched_at": "2026-10-24T20:28:21.255814+08:00", "kind": "documentation", "sha256": "6190d166d8b0dc360b8d1513f247226485d08fd9290fe11849bb2a78d9b519f6", "snapshot_path": "sources/6190d166d8b0dc360b8d1513f247226485d08fd9290fe11849bb2a78d9b519f6.txt", "url": "https://www.murex.com/en/solutions/business-solutions/enterprise-risk-management"}, {"fetched_at": "2026-10-28T15:48:04.783378+08:00", "kind": "documentation", "sha256": "ee480ed4715e21dfaad5440744f4f815396bc9d88274d2c89212bf69bd425a44", "snapshot_path": "sources/ee480ed4715e21dfaad5440744f4f815396bc9d88274d2c89212bf69bd425a44.txt", "url": "https://www.murex.com/en/solutions/business-solutions/enterprise-risk-management"}, {"fetched_at": "2026-10-28T15:44:20.312079+08:00", "kind": "documentation", "sha256": "1d99438eba61c13ed9ee2e7fc35eed07539a94e509318f8336c570010b7ad005", "snapshot_path": "sources/1d99438eba61c13ed9ee2e7fc35eed07539a94e509318f8336c570010b7ad005.txt", "url": "https://www.murex.com/en/solutions/business-solutions/treasury-management"}], "summary": "资本市场交易与风险管理平台，在同一数据基础上覆盖市场、信用与流动性风险及监管计量。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:feedzai','Feedzai','{"homepage": "https://www.feedzai.com/", "id": "commercial:feedzai", "leaf_matches": [{"reason": "官网说明以AI对交易、开户与账户等活动做实时风险决策，规则与警报由分析师处置，Farol代理协助处理警报与SAR；Transaction Fraud页说明在支付流程内实时拦截欺诈，覆盖活动记录—可配置检测—风险决策—人工审核路径，具体拒付模块未在已读页面证实。", "slug": "fraud-detection-platform", "source_urls": ["https://www.feedzai.com/", "https://www.feedzai.com/solutions/transaction-fraud/"]}], "name": "Feedzai", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:26.078058+08:00", "kind": "homepage", "sha256": "158db3e0c1f59eab328b378ffcabd7938f04203914cee79c9f7df1c1668a5e72", "snapshot_path": "sources/158db3e0c1f59eab328b378ffcabd7938f04203914cee79c9f7df1c1668a5e72.txt", "url": "https://www.feedzai.com/"}, {"fetched_at": "2026-10-24T20:33:11.487271+08:00", "kind": "documentation", "sha256": "a14fd63ef7e7b030a4c3ba81bf688c166d217d2835693d02012333e752f47d3b", "snapshot_path": "sources/a14fd63ef7e7b030a4c3ba81bf688c166d217d2835693d02012333e752f47d3b.txt", "url": "https://www.feedzai.com/solutions/transaction-fraud/"}], "summary": "金融欺诈与金融犯罪风险平台，对交易与开户等活动实时评分并支持分析师处置警报。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:activeviam','ActiveViam Atoti','{"homepage": "https://www.activeviam.com/", "id": "commercial:activeviam", "leaf_matches": [{"reason": "Atoti Market Risk页说明其整合现有风险引擎与估值引擎数据，支持VaR、SVaR、成分/增量VaR与Expected Shortfall计算、风险敏感性下钻、动态KPI与限额定义、实时监控告警及what-if情景；Atoti Limits页补充跨业务立方体的限额定义、按需或自动触发评估，以及违规进入可配置工作流处理。覆盖风险头寸计量—限额/违规处理；模型治理与监管资本细节未在已读页面证实。", "slug": "market-risk-platform", "source_urls": ["https://www.activeviam.com/solutions/atoti-market-risk", "https://www.activeviam.com/solutions/atoti-limits"]}], "name": "ActiveViam Atoti", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:29.619117+08:00", "kind": "documentation", "sha256": "b9e0094204e0e488afe23519f7bf60dd0c19eb282b3ff6fac4b3ccd889b4caad", "snapshot_path": "sources/b9e0094204e0e488afe23519f7bf60dd0c19eb282b3ff6fac4b3ccd889b4caad.txt", "url": "https://www.activeviam.com/solutions/atoti-market-risk"}, {"fetched_at": "2026-10-24T20:33:13.739709+08:00", "kind": "documentation", "sha256": "39fd200149f00e4d072da5b236b8e536ebc0f39d8eb1f3925865277b0c259fde", "snapshot_path": "sources/39fd200149f00e4d072da5b236b8e536ebc0f39d8eb1f3925865277b0c259fde.txt", "url": "https://www.activeviam.com/solutions/atoti-limits"}], "summary": "面向金融机构的风险分析平台，提供市场风险计量、实时限额监控与违规处理工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:regnology-reporting-hub','Regnology Reporting Hub','{"homepage": "https://www.regnology.net/", "id": "commercial:regnology-reporting-hub", "leaf_matches": [{"reason": "官方Reporting Hub页说明以细粒度数据模型实现“map once, report many”，内置校验规则（页面称逾万条）、异常监控与regulator-ready提交，并保留数据治理与血缘；覆盖监管报表—数据生产—校验—提交，具体机关受理回执流程未在页面细述。", "slug": "regulatory-reporting-platform", "source_urls": ["https://www.regnology.net/en/solutions/for-the-regulated/regnology-reporting-hub/"]}], "name": "Regnology Reporting Hub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:33.911833+08:00", "kind": "documentation", "sha256": "06c98be8e295a3152779d07a286e04e6395bcc172841957c0092df4b64804308", "snapshot_path": "sources/06c98be8e295a3152779d07a286e04e6395bcc172841957c0092df4b64804308.txt", "url": "https://www.regnology.net/en/solutions/for-the-regulated/regnology-reporting-hub/"}], "summary": "金融机构监管报送平台，以细粒度数据模型生成、校验并提交监管报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sanction-scanner','Sanction Scanner','{"homepage": "https://www.sanctionscanner.com/", "id": "commercial:sanction-scanner", "leaf_matches": [{"reason": "官方AML Screening页说明对客户做名单、PEP与负面媒体筛查，可调匹配阈值与黑白名单，提供匹配历史、审计日志、每日持续重筛与案件管理；覆盖名单数据—被筛主体—潜在匹配—记录处置，不把其交易监控模块当作本叶核心。", "slug": "sanctions-screening-platform", "source_urls": ["https://www.sanctionscanner.com/aml-screening-monitoring", "https://www.sanctionscanner.com/"]}], "name": "Sanction Scanner", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:28:38.091759+08:00", "kind": "homepage", "sha256": "c335cc893d488ad98e30f32607d30bba859f596f453a6c0a36c0bb3ad25c0a6c", "snapshot_path": "sources/c335cc893d488ad98e30f32607d30bba859f596f453a6c0a36c0bb3ad25c0a6c.txt", "url": "https://www.sanctionscanner.com/"}, {"fetched_at": "2026-10-24T20:31:41.910863+08:00", "kind": "documentation", "sha256": "5f7cf28fabbcede9438ed5c597b752715e984587324626316418170a2b752a39", "snapshot_path": "sources/5f7cf28fabbcede9438ed5c597b752715e984587324626316418170a2b752a39.txt", "url": "https://www.sanctionscanner.com/aml-screening-monitoring"}], "summary": "制裁与观察名单筛查平台，支持名单/PEP/负面媒体匹配、人工处置与持续重筛。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:22257580','CourtListener','{"deployment": ["官方仓库提供 README 与源码；本轮未运行或部署软件"], "features": ["A fully-searchable and accessible archive of court data including growing repositories of opinions, oral arguments, judges, judicial financial records, and federal filings.", "官方仓库 OpinionsCited 模型定义判决之间的 citing_opinion / cited_opinion 关系、引用次数 depth，并提供 cited_opinions 与 citing_opinions 双向关联；官方 API 索引提供 opinions-cited 端点。"], "github_repository_id": 22257580, "homepage": "https://www.courtlistener.com", "id": "github:22257580", "leaf_matches": [{"reason": "官方仓库与 API 索引显示三层核心：判决意见语料、检索服务，以及 OpinionsCited 的 citing/cited 双向引文关系（含引用次数）；官方 citations 模型另记录未匹配引文的解析状态。不主张 treatment/citator 判断。", "slug": "case-law-research-platform", "source_urls": ["https://api.github.com/repos/freelawproject/courtlistener", "https://www.courtlistener.com/api/rest/v4/", "https://raw.githubusercontent.com/freelawproject/courtlistener/main/cl/search/models.py", "https://raw.githubusercontent.com/freelawproject/courtlistener/main/cl/citations/models.py"]}], "license": "AGPL-3.0-or-later", "license_evidence_url": "https://api.github.com/repos/freelawproject/courtlistener/license", "license_review": {"rationale": "GitHub 许可证 API 返回 NOASSERTION，已核对仓库 LICENSE 完整文本为 GNU Affero General Public License version 3 或任何更晚版本。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/freelawproject/courtlistener/license", "spdx_id": "AGPL-3.0-or-later"}, "name": "CourtListener", "repository_url": "https://github.com/freelawproject/courtlistener", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:16.007157+08:00", "kind": "repository_metadata", "sha256": "8825fa025ab1358b6fd6ee99a660b3a8eafb247370ab0ce8f3361237e8f501d4", "snapshot_path": "sources/8825fa025ab1358b6fd6ee99a660b3a8eafb247370ab0ce8f3361237e8f501d4.txt", "url": "https://api.github.com/repos/freelawproject/courtlistener"}, {"fetched_at": "2026-10-24T22:24:27.715968+08:00", "kind": "license", "sha256": "7ce8720df1c4caa6968b89de86b24d22acceddf8cf1d40609c1d9c2e5c264a92", "snapshot_path": "sources/7ce8720df1c4caa6968b89de86b24d22acceddf8cf1d40609c1d9c2e5c264a92.txt", "url": "https://api.github.com/repos/freelawproject/courtlistener/license"}, {"fetched_at": "2026-10-24T22:41:48.176262+08:00", "kind": "readme", "sha256": "560a76b72c00062ee64fc9c1d8bd123ee3e9d81ba6d6bb7f01c7de21c8978c6e", "snapshot_path": "sources/560a76b72c00062ee64fc9c1d8bd123ee3e9d81ba6d6bb7f01c7de21c8978c6e.txt", "url": "https://raw.githubusercontent.com/freelawproject/courtlistener/main/README.md"}, {"fetched_at": "2026-10-26T12:49:20.135612+08:00", "kind": "documentation", "sha256": "86c6cb6dc4273918027be3df1db7892acc69c9fcd4a487067191af5a9d2ddd97", "snapshot_path": "sources/86c6cb6dc4273918027be3df1db7892acc69c9fcd4a487067191af5a9d2ddd97.txt", "url": "https://www.courtlistener.com/api/rest/v4/"}, {"fetched_at": "2026-10-26T12:49:47.661200+08:00", "kind": "documentation", "sha256": "b9ebe17c0b48487e35ed0ffeaf598ebf2f089f3e9d8524100ec4e5c8a61ebf9f", "snapshot_path": "sources/b9ebe17c0b48487e35ed0ffeaf598ebf2f089f3e9d8524100ec4e5c8a61ebf9f.txt", "url": "https://raw.githubusercontent.com/freelawproject/courtlistener/main/cl/search/models.py"}, {"fetched_at": "2026-10-26T12:58:05.916529+08:00", "kind": "documentation", "sha256": "2efa1eb459293c1eb77c4d665bb5958ee742ce22b5302fa3197cbcd6ceef673b", "snapshot_path": "sources/2efa1eb459293c1eb77c4d665bb5958ee742ce22b5302fa3197cbcd6ceef673b.txt", "url": "https://raw.githubusercontent.com/freelawproject/courtlistener/main/cl/citations/models.py"}], "summary": "Free Law Project 提供的美国法院意见检索与判决引文关系平台。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:34148903','Docassemble','{"deployment": ["官方仓库提供 README、源码与安装说明；本轮未运行或部署软件"], "features": ["A free, open-source expert system for guided interviews and document assembly, based on Python, YAML, and Markdown.", "官方文档说明 interview 由 YAML、变量与条件逻辑驱动；文档组装支持 Markdown、DOCX/Jinja2 模板与 PDF 表单填充，输出 PDF、RTF、DOCX。"], "github_repository_id": 34148903, "homepage": "https://docassemble.org", "id": "github:34148903", "leaf_matches": [{"reason": "官方文档正文说明 interview 是 YAML 文件、用户答案存入变量，并可依据先前答案决定后续问题与顺序；文档组装页说明可用 DOCX 模板 + Jinja2 变量生成 PDF/DOCX，或用 Markdown 生成 PDF/RTF/DOCX，亦可填充 PDF 表单字段。", "slug": "legal-document-automation", "source_urls": ["https://api.github.com/repos/jhpyle/docassemble", "https://docassemble.org/docs/interviews.html", "https://docassemble.org/docs/documents.html"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/jhpyle/docassemble/license", "license_review": {"rationale": "GitHub 许可证 API 快照内包含完整 MIT 文本，已核对授权与免责条款。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/jhpyle/docassemble/license", "spdx_id": "MIT"}, "name": "Docassemble", "repository_url": "https://github.com/jhpyle/docassemble", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:18.906768+08:00", "kind": "repository_metadata", "sha256": "5d7d9c7c6251d884e0a548560a52ff08e24db8effa940f7ec4c54ff036d35dc3", "snapshot_path": "sources/5d7d9c7c6251d884e0a548560a52ff08e24db8effa940f7ec4c54ff036d35dc3.txt", "url": "https://api.github.com/repos/jhpyle/docassemble"}, {"fetched_at": "2026-10-24T22:25:07.005696+08:00", "kind": "license", "sha256": "4b18f2a7ed1aba6f4c1a7074427fb6962a67e11c8be60acb4abcf5e3cfbbee68", "snapshot_path": "sources/4b18f2a7ed1aba6f4c1a7074427fb6962a67e11c8be60acb4abcf5e3cfbbee68.txt", "url": "https://api.github.com/repos/jhpyle/docassemble/license"}, {"fetched_at": "2026-10-24T22:41:48.176324+08:00", "kind": "readme", "sha256": "a1c9c5fe78b19cfc4724e23d2c359e216459c70e2e68dd8ce868a2b5e645ae59", "snapshot_path": "sources/a1c9c5fe78b19cfc4724e23d2c359e216459c70e2e68dd8ce868a2b5e645ae59.txt", "url": "https://raw.githubusercontent.com/jhpyle/docassemble/master/README.md"}, {"fetched_at": "2026-10-26T12:57:33.517414+08:00", "kind": "documentation", "sha256": "6055c68416e0a3be05f323fc7398304f6ff722255f9044d1cd54838265ab87ff", "snapshot_path": "sources/6055c68416e0a3be05f323fc7398304f6ff722255f9044d1cd54838265ab87ff.txt", "url": "https://docassemble.org/docs/interviews.html"}, {"fetched_at": "2026-10-26T12:57:33.292168+08:00", "kind": "documentation", "sha256": "ea3881e37fed8e9bc661e5c36de14cbea57677e70ac77bda3adbf35aa65be361", "snapshot_path": "sources/ea3881e37fed8e9bc661e5c36de14cbea57677e70ac77bda3adbf35aa65be361.txt", "url": "https://docassemble.org/docs/documents.html"}], "summary": "用于引导式访谈与法律文档自动组装的开源专家系统，按 YAML 访谈采集变量，并以 DOCX 模板或 PDF 表单生成文档。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:westlaw','Westlaw','{"homepage": "https://legal.thomsonreuters.com/en/products/westlaw", "id": "commercial:westlaw", "leaf_matches": [{"reason": "官方产品页正文列出 legal research tools、KeyCite Overruling Risk、任意两个版本的 statute/regulation 对比，以及 Practical Law 的 how-to guides/templates/checklists，支持多内容家族 + 专业检索的法律研究平台类型。", "slug": "legal-research-platform", "source_urls": ["https://legal.thomsonreuters.com/en/products/westlaw"]}], "name": "Westlaw", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:26:38.114133+08:00", "kind": "homepage", "sha256": "5cedcb67bde9dd91178da9ca152cf8c1ff998efa1b2700fbdbf36284ab299a1d", "snapshot_path": "sources/5cedcb67bde9dd91178da9ca152cf8c1ff998efa1b2700fbdbf36284ab299a1d.txt", "url": "https://legal.thomsonreuters.com/en/products/westlaw"}], "summary": "面向法律专业人士的商业法律研究平台，涵盖案例、法规与分析性内容。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:luminance','Luminance','{"homepage": "https://www.luminance.com", "id": "commercial:luminance", "leaf_matches": [{"reason": "官方产品页正文写明可对合同组合（contract portfolio）提问并获得 source-backed answers，呈现风险、义务、续约与商业机会，并分析跨行业、司法辖区的整个合同组合；官方 llms.txt 索引另概述其为 Contract Intelligence 平台、将合同组合转为可行动洞察，并指向 AI-powered contract repository 与 document search engine。按合同智能/分析平台基本匹配，不扩写导入或抽取管线。", "slug": "contract-analytics-platform", "source_urls": ["https://www.luminance.com", "https://www.luminance.com/platform/product", "https://www.luminance.com/llms.txt"]}], "name": "Luminance", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:26:41.617227+08:00", "kind": "homepage", "sha256": "713473bea652b8ddb20b503e8a91906e6937b7bfccb2ae862199317a8f73558f", "snapshot_path": "sources/713473bea652b8ddb20b503e8a91906e6937b7bfccb2ae862199317a8f73558f.txt", "url": "https://www.luminance.com"}, {"fetched_at": "2026-10-26T12:57:33.499640+08:00", "kind": "documentation", "sha256": "44a1b65376e21adf04d9f03fa66d2ce652f9f17188831ae6183a3d1e028fcb34", "snapshot_path": "sources/44a1b65376e21adf04d9f03fa66d2ce652f9f17188831ae6183a3d1e028fcb34.txt", "url": "https://www.luminance.com/platform/product"}, {"fetched_at": "2026-10-26T13:03:18.775075+08:00", "kind": "documentation", "sha256": "9fb3a3b7206789dc4cd97f20beab7b7d68f99af38111c7403d192eec6653c6bd", "snapshot_path": "sources/9fb3a3b7206789dc4cd97f20beab7b7d68f99af38111c7403d192eec6653c6bd.txt", "url": "https://www.luminance.com/llms.txt"}], "summary": "商业合同智能/分析平台，对合同组合提供带来源依据的问答，呈现风险、义务、续约与商业机会。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dealroom','DealRoom','{"homepage": "https://dealroom.net", "id": "commercial:dealroom", "leaf_matches": [{"reason": "官方首页 JSON-LD 与正文展示 Due Diligence Management、协作 Q&A、请求项答复与交易进度报告，并有 140+ diligence requests 的客户案例；这是 M&A 平台中的尽调模块匹配，不把 VDR 或交易管道当作尽调核心。", "slug": "due-diligence-platform", "source_urls": ["https://dealroom.net"]}], "name": "DealRoom", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:26:46.854054+08:00", "kind": "homepage", "sha256": "83e00a66e3729699f09ca56245e19f5a4aebda4a372a7c95b91e3ce270bba6d6", "snapshot_path": "sources/83e00a66e3729699f09ca56245e19f5a4aebda4a372a7c95b91e3ce270bba6d6.txt", "url": "https://dealroom.net"}], "summary": "商业 M&A 交易管理平台，其 Diligence 模块跟踪尽调请求、答复与交易进度。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:646985602','Papermark','{"deployment": ["README 提供自托管步骤（Node.js、PostgreSQL、S3/Blob 存储）；本轮未运行或部署软件"], "features": ["Open-source DocSend alternative with secure document sharing and virtual data rooms", "Multiple data rooms with nested folders and per-viewer/file/folder permissions", "NDA gating, dynamic watermarks, Q&A, page-by-page analytics, and append-only audit log"], "github_repository_id": 646985602, "homepage": "https://www.papermark.com", "id": "github:646985602", "leaf_matches": [{"reason": "官方数据室文档说明可创建多个数据室，按查看者/文件/文件夹授权，支持 NDA 门禁、逐页分析与只追加审计日志；README 与 LICENSE 说明开源核心可自托管、ee/ 为商业许可。", "slug": "virtual-data-room", "source_urls": ["https://api.github.com/repos/papermark/papermark", "https://api.github.com/repos/papermark/papermark/license", "https://raw.githubusercontent.com/papermark/papermark/main/README.md", "https://www.papermark.com/data-room.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/papermark/papermark/license", "license_review": {"rationale": "仓库 LICENSE 说明非 ee/ 内容采用 AGPLv3，ee/ 与 app/(ee) 采用独立商业许可；已核对完整许可证文本。", "reviewer": "source_research", "scope": "community_core", "source_url": "https://api.github.com/repos/papermark/papermark/license", "spdx_id": "AGPL-3.0"}, "name": "Papermark", "repository_url": "https://github.com/papermark/papermark", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:20.243665+08:00", "kind": "repository_metadata", "sha256": "712e2e6ee004a9db9d8fd5814f887cdc1679a12a752e0ab0baa67ddd9c29b659", "snapshot_path": "sources/712e2e6ee004a9db9d8fd5814f887cdc1679a12a752e0ab0baa67ddd9c29b659.txt", "url": "https://api.github.com/repos/papermark/papermark"}, {"fetched_at": "2026-10-24T22:24:37.186684+08:00", "kind": "license", "sha256": "4d154b98ff962d4f02a9166a28d2b8754caf2e3c06608db8376cbaca6210e918", "snapshot_path": "sources/4d154b98ff962d4f02a9166a28d2b8754caf2e3c06608db8376cbaca6210e918.txt", "url": "https://api.github.com/repos/papermark/papermark/license"}, {"fetched_at": "2026-10-24T22:41:48.176379+08:00", "kind": "readme", "sha256": "e42afe0b82218aac2ec4e55affe14d8532ab3795a4f48ad89c4e5edff8481fb9", "snapshot_path": "sources/e42afe0b82218aac2ec4e55affe14d8532ab3795a4f48ad89c4e5edff8481fb9.txt", "url": "https://raw.githubusercontent.com/papermark/papermark/main/README.md"}, {"fetched_at": "2026-10-26T12:53:08.691167+08:00", "kind": "documentation", "sha256": "b1f5da873e8433db5d556fc559f721656c49a597654f701a61e12703666980bb", "snapshot_path": "sources/b1f5da873e8433db5d556fc559f721656c49a597654f701a61e12703666980bb.txt", "url": "https://www.papermark.com/data-room.md"}], "summary": "Papermark 开源核心以 AGPLv3 提供安全文档分享与虚拟数据室；官方数据室文档说明多房间、按查看者/文件权限、NDA、逐页分析与审计日志，ee/ 目录使用独立商业许可。", "technology_stack": ["TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:771302083','OpenHands Agent Canvas','{"deployment": ["README 提供 npm、Docker 与源码自托管方式；本轮未运行或部署软件"], "features": ["Self-hosted developer control center for OpenHands and ACP-compatible coding agents", "Runs agents on local, Docker, VM, or cloud backends with switchable workspaces", "Automations integrate with Slack, GitHub, and Linear for tasks such as code review and dependency updates"], "github_repository_id": 771302083, "homepage": "https://openhands.dev", "id": "github:771302083", "leaf_matches": [{"reason": "README 说明 Agent Canvas 默认运行开源 OpenHands 代理，可连接本地/Docker/VM/云后端，代理在工作区读写项目文件，并可自动化代码审查、依赖更新等任务；官方后端文档确认工作区是代理读写文件的项目目录、容器或沙箱。", "slug": "ai-software-engineering-agent", "source_urls": ["https://api.github.com/repos/OpenHands/OpenHands", "https://raw.githubusercontent.com/OpenHands/OpenHands/main/README.md", "https://docs.openhands.dev/openhands/usage/agent-canvas/backends", "https://api.github.com/repos/OpenHands/OpenHands/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/OpenHands/OpenHands/license", "name": "OpenHands Agent Canvas", "repository_url": "https://github.com/OpenHands/OpenHands", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:41.661461+08:00", "kind": "repository_metadata", "sha256": "1cfcd9174545dbe7812d9587252eaf35747fe085507103305a1086130abde099", "snapshot_path": "sources/1cfcd9174545dbe7812d9587252eaf35747fe085507103305a1086130abde099.txt", "url": "https://api.github.com/repos/OpenHands/OpenHands"}, {"fetched_at": "2026-10-24T22:25:10.445302+08:00", "kind": "license", "sha256": "21dfa6a405ef7718fa2d14ae48e41a3156acb89facd35c236c02f2cce6052ab4", "snapshot_path": "sources/21dfa6a405ef7718fa2d14ae48e41a3156acb89facd35c236c02f2cce6052ab4.txt", "url": "https://api.github.com/repos/OpenHands/OpenHands/license"}, {"fetched_at": "2026-10-24T22:41:48.176495+08:00", "kind": "readme", "sha256": "3211341a775a6ac63b47cd3d8ba7704aecd15a3ed5aa2891a2ed74448de7a66f", "snapshot_path": "sources/3211341a775a6ac63b47cd3d8ba7704aecd15a3ed5aa2891a2ed74448de7a66f.txt", "url": "https://raw.githubusercontent.com/OpenHands/OpenHands/main/README.md"}, {"fetched_at": "2026-10-26T12:53:40.326223+08:00", "kind": "documentation", "sha256": "2c99006226701958a32a26708113d78e7075a8367bae3b40aa698a5068abb166", "snapshot_path": "sources/2c99006226701958a32a26708113d78e7075a8367bae3b40aa698a5068abb166.txt", "url": "https://docs.openhands.dev/openhands/usage/agent-canvas/backends"}], "summary": "OpenHands 仓库提供的自托管 Agent Canvas 开发控制中心，运行 OpenHands 及第三方编码代理，在本地/Docker/VM/云后端工作区执行任务并支持自动化；代理执行由独立 Agent Server/SDK 提供。", "technology_stack": ["TypeScript", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:172953845','code-server','{"deployment": ["README 提供安装脚本、手动安装、Coder 与 devcontainer 部署方式；本轮未运行或部署软件"], "features": ["VS Code in the browser", "Run on any machine anywhere with a consistent development environment", "Use cloud servers for tests, compilations, and downloads"], "github_repository_id": 172953845, "homepage": "https://coder.com", "id": "github:172953845", "leaf_matches": [{"reason": "README 说明可在任意机器运行 VS Code 并通过浏览器访问，测试、编译、下载等重任务在服务器执行；属部署方自托管的远程工作区与远程执行，不含厂商托管云服务。", "slug": "cloud-ide", "source_urls": ["https://api.github.com/repos/coder/code-server", "https://api.github.com/repos/coder/code-server/license", "https://raw.githubusercontent.com/coder/code-server/main/README.md"]}, {"reason": "官方 FAQ 说明 code-server 以浏览器打开服务器端工作区/文件夹、可直接打开指定文件定位到行列，并复用 VS Code 的配置与扩展；README 说明在任意机器运行 VS Code 并在浏览器访问。即用户直接对服务器文件系统中的源文件做字符级编辑，具备 VS Code 的代码呈现、查找与导航，且以常驻服务形式提供（密码认证、healthz、重连宽限期），符合代码编辑器的纯文本缓冲区、文件系统工作集与代码结构化三项核心，而非仅桌面客户端或 SDK。", "slug": "code-editor", "source_urls": ["https://api.github.com/repos/coder/code-server", "https://raw.githubusercontent.com/coder/code-server/main/README.md", "https://coder.com/docs/code-server/FAQ"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/coder/code-server/license", "name": "code-server", "repository_url": "https://github.com/coder/code-server", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:43.010781+08:00", "kind": "repository_metadata", "sha256": "d00ef74b97f84fb0dd90506a0c3c9027c5c4b87743f792f5b5399f25f733d439", "snapshot_path": "sources/d00ef74b97f84fb0dd90506a0c3c9027c5c4b87743f792f5b5399f25f733d439.txt", "url": "https://api.github.com/repos/coder/code-server"}, {"fetched_at": "2026-10-24T22:25:11.902565+08:00", "kind": "license", "sha256": "39e085e6b980b9b15e2c48127e59328870d11bc64864089ab1fa6cd3b8395114", "snapshot_path": "sources/39e085e6b980b9b15e2c48127e59328870d11bc64864089ab1fa6cd3b8395114.txt", "url": "https://api.github.com/repos/coder/code-server/license"}, {"fetched_at": "2026-10-28T22:26:27.144166+08:00", "kind": "documentation", "sha256": "30239287dd0869c9fceb0bf9fbb24cac14cf13e18766980eec88bb5d0b8b8dfb", "snapshot_path": "sources/30239287dd0869c9fceb0bf9fbb24cac14cf13e18766980eec88bb5d0b8b8dfb.txt", "url": "https://coder.com/docs/code-server/FAQ"}, {"fetched_at": "2026-10-24T22:41:48.176545+08:00", "kind": "readme", "sha256": "34ea118681ed7212d8b1e3e1be602d09e8829838e5f2b0e3e0b184b00109ab78", "snapshot_path": "sources/34ea118681ed7212d8b1e3e1be602d09e8829838e5f2b0e3e0b184b00109ab78.txt", "url": "https://raw.githubusercontent.com/coder/code-server/main/README.md"}], "summary": "在远程服务器上运行 VS Code，并通过浏览器访问的自托管云开发环境；测试、编译等重任务在服务器执行。", "technology_stack": ["TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:285304','Review Board','{"deployment": ["官方提供安装器与部署文档，可自托管在自有服务器；厂商另提供 RBCommons 托管服务", "本轮未运行或部署软件"], "features": ["待审代码与文档变更的差异查看，支持 interdiffs 和移动行检测", "评论讨论与 Ship It / Fix It then Ship It 等审查裁决", "支持多种版本控制与托管服务集成，可部署在自有服务器"], "github_repository_id": 285304, "homepage": "https://www.reviewboard.org/", "id": "github:285304", "leaf_matches": [{"reason": "README 说明其跟踪待审代码与文档变更，围绕 diff、评论和决策保存审查过程；官方手册进一步记录 Ship It!、Fix It then Ship It! 及开放 issue 影响批准的规则，覆盖“提议变更的审查工作流 + 可归因裁决”核心。", "slug": "code-review-platform", "source_urls": ["https://raw.githubusercontent.com/reviewboard/reviewboard/master/README.md", "https://www.reviewboard.org/docs/manual/latest/users/reviews/approving-changes/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/reviewboard/reviewboard/license", "name": "Review Board", "repository_url": "https://github.com/reviewboard/reviewboard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:25:41.732087+08:00", "kind": "repository_metadata", "sha256": "df4e6a2b5d61803df1c9acb20dc48d4a3659e98a9f9f94477fc3c0c8ef959153", "snapshot_path": "sources/df4e6a2b5d61803df1c9acb20dc48d4a3659e98a9f9f94477fc3c0c8ef959153.txt", "url": "https://api.github.com/repos/reviewboard/reviewboard"}, {"fetched_at": "2026-10-24T22:25:44.005982+08:00", "kind": "license", "sha256": "8eb74cbc740f77ab6e285ff3f237612c52b018521eb86c689de796188d0c9969", "snapshot_path": "sources/8eb74cbc740f77ab6e285ff3f237612c52b018521eb86c689de796188d0c9969.txt", "url": "https://api.github.com/repos/reviewboard/reviewboard/license"}, {"fetched_at": "2026-10-24T22:41:48.176699+08:00", "kind": "readme", "sha256": "42c2f5471dfdcfd9712b758c9ca1a8769d54b26f4384b23fffb6be74b1225dbc", "snapshot_path": "sources/42c2f5471dfdcfd9712b758c9ca1a8769d54b26f4384b23fffb6be74b1225dbc.txt", "url": "https://raw.githubusercontent.com/reviewboard/reviewboard/master/README.md"}, {"fetched_at": "2026-10-26T12:53:13.282650+08:00", "kind": "documentation", "sha256": "4b1fe355cab0a8105ab6e3d9c59cd58b335875ccb71414e68ce7c1e82e4a1a8c", "snapshot_path": "sources/4b1fe355cab0a8105ab6e3d9c59cd58b335875ccb71414e68ce7c1e82e4a1a8c.txt", "url": "https://www.reviewboard.org/docs/manual/latest/users/reviews/approving-changes/"}], "summary": "基于 Web 的开源代码与文档审查平台，围绕待审变更的差异、讨论线程和 Ship It 裁决组织审查流程。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sourcegraph','Sourcegraph','{"homepage": "https://sourcegraph.com", "id": "commercial:sourcegraph", "leaf_matches": [{"reason": "官方 Code Search 产品页说明可在 100 至 1M+ 仓库中按字面量、关键字和正则检索，按文件路径、语言或自定义模式过滤，并支持 Search contexts（指定仓库集与修订版）、Symbol search、Commit + Diff Search 与浏览器内代码导航；官网首页将 Code Search 列为平台产品之一（整体定位为 Context Layer）。覆盖受管代码语料、查询面和定位匹配核心。", "slug": "code-search-platform", "source_urls": ["https://sourcegraph.com", "https://sourcegraph.com/code-search"]}], "name": "Sourcegraph", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:31:27.703790+08:00", "kind": "homepage", "sha256": "43be669ab9f71d9bb77bcbf6c394e1397311a6dc534573bf381be2a2384bef42", "snapshot_path": "sources/43be669ab9f71d9bb77bcbf6c394e1397311a6dc534573bf381be2a2384bef42.txt", "url": "https://sourcegraph.com"}, {"fetched_at": "2026-10-26T12:54:00.812183+08:00", "kind": "documentation", "sha256": "ab56acb6f8f3646ea1ba1cecfcc7cb4560bfd3da02301e1359d3e4160ddfe5ec", "snapshot_path": "sources/ab56acb6f8f3646ea1ba1cecfcc7cb4560bfd3da02301e1359d3e4160ddfe5ec.txt", "url": "https://sourcegraph.com/code-search"}], "summary": "商业代码搜索平台，面向大规模多仓库代码库提供字面量、正则、符号与跨仓库搜索，并在浏览器内提供代码导航。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:102083576','Apache NetBeans','{"deployment": ["官方提供多平台安装包与源码构建；本轮未运行或部署软件"], "features": ["以项目组织源码、依赖与构建配置", "源码编辑支持语法/语义高亮与重构", "在 IDE 内编译、运行、测试，并使用断点、变量查看和步进调试 Java 等应用"], "github_repository_id": 102083576, "homepage": "https://netbeans.apache.org/", "id": "github:102083576", "leaf_matches": [{"reason": "官方 README 将其定位为开源开发环境；官网说明其提供语法/语义高亮与重构等编辑能力；官方 Java 教程以项目为起点，覆盖创建/编辑源码、编译运行、JUnit 测试以及断点、变量查看和步进调试，完整对应项目制“编辑—构建运行—调试”集成核心。", "slug": "integrated-development-environment-ide", "source_urls": ["https://raw.githubusercontent.com/apache/netbeans/master/README.md", "https://netbeans.apache.org/", "https://netbeans.apache.org/tutorial/main/kb/docs/java/javase-intro/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/apache/netbeans/license", "name": "Apache NetBeans", "repository_url": "https://github.com/apache/netbeans", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:33:34.781229+08:00", "kind": "repository_metadata", "sha256": "2aeab8ae77d495fe146280d4e7447c0498116f43328ac750d466b06f43e3444b", "snapshot_path": "sources/2aeab8ae77d495fe146280d4e7447c0498116f43328ac750d466b06f43e3444b.txt", "url": "https://api.github.com/repos/apache/netbeans"}, {"fetched_at": "2026-10-24T22:33:40.543075+08:00", "kind": "license", "sha256": "1ae2d79695816fc20ceb3b1282e21592740f3da92c933fecd3e2882ea9976bc3", "snapshot_path": "sources/1ae2d79695816fc20ceb3b1282e21592740f3da92c933fecd3e2882ea9976bc3.txt", "url": "https://api.github.com/repos/apache/netbeans/license"}, {"fetched_at": "2026-10-24T22:41:48.177192+08:00", "kind": "readme", "sha256": "c16617ce420b14ffd1b6165da9f1dfa677bf993cce41cfd04b5bc527a10ffade", "snapshot_path": "sources/c16617ce420b14ffd1b6165da9f1dfa677bf993cce41cfd04b5bc527a10ffade.txt", "url": "https://raw.githubusercontent.com/apache/netbeans/master/README.md"}, {"fetched_at": "2026-10-26T12:53:46.416335+08:00", "kind": "documentation", "sha256": "a56c5c111e22d2ce1b55adf1c