INSERT INTO "application" VALUES('github:92381207','Kiwi TCMS','{"deployment": ["README: Docker container installation documented; a public tenant is also available. 本轮未运行或部署。"], "features": ["README: open source test management system for manual and automated testing; bug tracker integration, search pages, access control, test automation framework plugins, visual reports and a rich API.", "docs testcase.rst: test cases carry setup instructions, actions and measurable expected results; cases are associated with test plans; only CONFIRMED cases can be added to a test run; peer review workflow.", "docs testrun.rst: a Test Run contains execution results of selected test cases against particular product builds; it is created for a test plan, assigned to a tester, and each case execution records a status and comment."], "github_repository_id": 92381207, "homepage": "https://kiwitcms.org", "id": "github:92381207", "leaf_matches": [{"reason": "README 与官方用户指南显示：测试用例是与测试计划关联的可复用受管记录（含步骤与可测量预期结果），测试运行针对特定产品构建实例化选定的已确认用例，执行时由测试人员逐项记录状态与备注；对应测试用例库、测试运行/判定、受管测试工作三结构。", "slug": "software-test-management", "source_urls": ["https://raw.githubusercontent.com/kiwitcms/Kiwi/master/README.md", "https://raw.githubusercontent.com/kiwitcms/Kiwi/master/docs/source/guide/testcase.rst", "https://raw.githubusercontent.com/kiwitcms/Kiwi/master/docs/source/guide/testrun.rst", "https://api.github.com/repos/kiwitcms/Kiwi"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/kiwitcms/Kiwi/license", "name": "Kiwi TCMS", "repository_url": "https://github.com/kiwitcms/Kiwi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:25:52.218937+08:00", "kind": "repository_metadata", "sha256": "1d243ee6ba7af3c21a10a94465d6621bf496c8c0c67ebaad2e8f694d620d632e", "snapshot_path": "sources/1d243ee6ba7af3c21a10a94465d6621bf496c8c0c67ebaad2e8f694d620d632e.txt", "url": "https://api.github.com/repos/kiwitcms/Kiwi"}, {"fetched_at": "2026-10-24T22:26:18.990032+08:00", "kind": "license", "sha256": "4f9e45233f856ffdc37792ad0416531dd78464aa4ba6d340766cbc7db1177af8", "snapshot_path": "sources/4f9e45233f856ffdc37792ad0416531dd78464aa4ba6d340766cbc7db1177af8.txt", "url": "https://api.github.com/repos/kiwitcms/Kiwi/license"}, {"fetched_at": "2026-10-24T22:41:48.176847+08:00", "kind": "readme", "sha256": "19c2f0742f395d53a65e43b7c73febffc6395b15f53a122ef7dd42f040fed048", "snapshot_path": "sources/19c2f0742f395d53a65e43b7c73febffc6395b15f53a122ef7dd42f040fed048.txt", "url": "https://raw.githubusercontent.com/kiwitcms/Kiwi/master/README.md"}, {"fetched_at": "2026-10-26T13:02:15.032178+08:00", "kind": "documentation", "sha256": "5c3ef711d19eb7ef9b555f2119e39ad1875535482468f444b05f2d68cf8eb2e9", "snapshot_path": "sources/5c3ef711d19eb7ef9b555f2119e39ad1875535482468f444b05f2d68cf8eb2e9.txt", "url": "https://raw.githubusercontent.com/kiwitcms/Kiwi/master/docs/source/guide/testcase.rst"}, {"fetched_at": "2026-10-26T13:02:14.965458+08:00", "kind": "documentation", "sha256": "bf45e65d365247288c570d4e0118f721085186797907ba8ae4fb55651ad6c4fb", "snapshot_path": "sources/bf45e65d365247288c570d4e0118f721085186797907ba8ae4fb55651ad6c4fb.txt", "url": "https://raw.githubusercontent.com/kiwitcms/Kiwi/master/docs/source/guide/testrun.rst"}], "summary": "开源测试管理系统，管理测试用例、测试计划与针对构建的测试执行，并记录逐项执行结果。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:270942530','DBLab Engine','{"deployment": ["官方 README 提供 Docker 镜像与安装文档（Community Edition 教程及 SE 安装入口）；支持云与本地环境；本轮未部署"], "features": ["从源 PostgreSQL（自管理实例或 RDS/Cloud SQL 等托管服务）创建写时复制的精简克隆与数据库分支，供开发、测试、QA 和 staging 环境使用", "管理快照、克隆、分支与保留策略，自动清理未使用的克隆，并支持删除保护", "通过 UI、API 与 CLI 创建、重置和删除克隆，按需选择快照并刷新环境"], "github_repository_id": 270942530, "homepage": "https://postgres.ai", "id": "github:270942530", "leaf_matches": [{"reason": "官方 README 说明 DBLab 从源 PostgreSQL（含托管服务）创建写时复制的克隆与分支，提供快照/克隆/分支的保留、重置、自动清理和删除保护，用于 dev/test/QA/staging 环境，符合数据库开发/测试环境管理器核心。", "slug": "database-dev-test-environment-manager", "source_urls": ["https://raw.githubusercontent.com/postgres-ai/database-lab-engine/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/postgres-ai/database-lab-engine/master/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/postgres-ai/database-lab-engine/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "DBLab Engine", "repository_url": "https://github.com/postgres-ai/database-lab-engine", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:36:02.621058+08:00", "kind": "repository_metadata", "sha256": "fe4da88f20d44e49caff89a171b1c89504e3b53f426c003c497cef5103a89ccb", "snapshot_path": "sources/fe4da88f20d44e49caff89a171b1c89504e3b53f426c003c497cef5103a89ccb.txt", "url": "https://github.com/postgres-ai/database-lab-engine"}, {"fetched_at": "2026-10-24T22:36:09.478049+08:00", "kind": "license", "sha256": "29013af86dd87c31de3d0b1ebcd5e745d1e3166e8f797dcc97cb2628adcb0795", "snapshot_path": "sources/29013af86dd87c31de3d0b1ebcd5e745d1e3166e8f797dcc97cb2628adcb0795.txt", "url": "https://raw.githubusercontent.com/postgres-ai/database-lab-engine/master/LICENSE"}, {"fetched_at": "2026-10-24T22:36:04.101446+08:00", "kind": "readme", "sha256": "52f3295d0feee89e877d1b5e97564e34eeffb17be42d4c731f60485d995d323b", "snapshot_path": "sources/52f3295d0feee89e877d1b5e97564e34eeffb17be42d4c731f60485d995d323b.txt", "url": "https://raw.githubusercontent.com/postgres-ai/database-lab-engine/master/README.md"}], "summary": "DBLab Engine 是开源的 PostgreSQL 精简克隆与分支引擎，可自托管构建开发、测试和 QA 环境。", "technology_stack": ["PostgreSQL", "ZFS/LVM", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:384111310','Apache DevLake','{"deployment": ["官方 README 提供 Docker Compose 或 Helm 自托管安装；本轮未部署"], "features": ["从 GitHub、GitLab、Jenkins、Jira、SonarQube 等开发工具采集工程活动数据", "通过 Blueprint 配置数据连接、数据范围、转换规则与同步频率", "以 Grafana 预置仪表板呈现 DORA 等指标，并支持用 SQL 自定义指标和仪表板"], "github_repository_id": 384111310, "homepage": "https://devlake.apache.org", "id": "github:384111310", "leaf_matches": [{"reason": "官方 README 说明 DevLake 从 GitHub/GitLab/Jira/Jenkins 等工具持续采集开发活动数据，按 Blueprint 转换并计算 DORA 等指标，通过 Grafana 仪表板供工程负责人审视交付流程，符合工程生产力分析核心。", "slug": "engineering-productivity-analytics", "source_urls": ["https://raw.githubusercontent.com/apache/devlake/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/apache/devlake/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/apache/devlake/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Apache DevLake", "repository_url": "https://github.com/apache/devlake", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:36:41.594698+08:00", "kind": "repository_metadata", "sha256": "8c7a0dcb14774dc45120261954445178de6957dd040a4daa7f6cdd8a1e112a12", "snapshot_path": "sources/8c7a0dcb14774dc45120261954445178de6957dd040a4daa7f6cdd8a1e112a12.txt", "url": "https://github.com/apache/devlake"}, {"fetched_at": "2026-10-24T22:36:44.542616+08:00", "kind": "license", "sha256": "9633dec2730f3c61e1fcc702fdcdbafa2ecb1d65b27b15a60576ba805bfc6f03", "snapshot_path": "sources/9633dec2730f3c61e1fcc702fdcdbafa2ecb1d65b27b15a60576ba805bfc6f03.txt", "url": "https://raw.githubusercontent.com/apache/devlake/main/LICENSE"}, {"fetched_at": "2026-10-24T22:36:43.060571+08:00", "kind": "readme", "sha256": "5ecd442b3a0ec99a7b99b3e13daddce5d19ca76b71dba176848dc73d9d33419d", "snapshot_path":