INSERT INTO "application" VALUES('github:24594933','Unleash','{"deployment": ["官方 README 提供 Docker Compose 本地运行与自托管生产部署文档；本轮未部署"], "features": ["集中管理跨环境、应用和服务的 feature flags", "通过 activation strategies 在运行时定向启用或禁用功能，支持 canary/渐进发布和 kill switch", "提供官方后端与前端 SDK 及 API，由应用程序在运行时评估标志", "开源版包含 2 个环境；RBAC、SSO、更多环境和高级分段等属 Pro/Enterprise 能力"], "github_repository_id": 24594933, "homepage": "https://www.getunleash.io", "id": "github:24594933", "leaf_matches": [{"reason": "官方 README 说明 Unleash 是开源 feature management 平台，可集中管理跨环境的功能标志，应用通过 SDK 在运行时评估，并支持 activation strategies、渐进发布和 kill switch，符合功能开关管理平台核心；条目仅覆盖开源核心，未混入企业版能力。", "slug": "feature-flag-management-platform", "source_urls": ["https://raw.githubusercontent.com/Unleash/unleash/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/Unleash/unleash/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/Unleash/unleash/main/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "Unleash", "repository_url": "https://github.com/Unleash/unleash", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:36:48.005970+08:00", "kind": "repository_metadata", "sha256": "4c57b31d103bbd875ed793459a900fa02d6527f73b747c761b93c09f3a1f8db1", "snapshot_path": "sources/4c57b31d103bbd875ed793459a900fa02d6527f73b747c761b93c09f3a1f8db1.txt", "url": "https://github.com/Unleash/unleash"}, {"fetched_at": "2026-10-24T22:36:51.700429+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/Unleash/unleash/main/LICENSE"}, {"fetched_at": "2026-10-24T22:36:49.410832+08:00", "kind": "readme", "sha256": "a5b05da9b75b61cf31ec40cca5