INSERT INTO "application" VALUES('github:14051004','Dataverse','{"deployment": ["官方 README 提供安装指南与容器指南；本轮未部署"], "features": ["发布和描述研究数据集", "对文件设置访问限制，启用 Request Access 并设置 Terms of Access", "提供数据集检索、引用与长期保存"], "github_repository_id": 14051004, "homepage": "https://dataverse.org", "id": "github:14051004", "leaf_matches": [{"reason": "README 说明 Dataverse 用于共享、查找、引用和保存研究数据；官方用户文档进一步说明可限制文件下载、启用 Request Access 并设置 Terms of Access，对应数据提供方控制授权后再交付数据集。", "slug": "data-exchange-platform", "source_urls": ["https://raw.githubusercontent.com/IQSS/dataverse/master/README.md", "https://guides.dataverse.org/en/latest/user/dataset-management.html"]}, {"reason": "官方仓库 README 说明 Dataverse 是用于共享、查找、引用和保存研究数据的开源平台，供研究机构托管、管理与共享数据。", "slug": "research-data-management", "source_urls": ["https://github.com/IQSS/dataverse", "https://raw.githubusercontent.com/IQSS/dataverse/develop/LICENSE.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/IQSS/dataverse/master/LICENSE.md", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/IQSS/dataverse/master/LICENSE.md", "spdx_id": "Apache-2.0"}, "name": "Dataverse", "repository_url": "https://github.com/IQSS/dataverse", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:37:30.883279+08:00", "kind": "repository_metadata", "sha256": "f37224c89f82eb0882c163081cee3efec0c4f1d11c159d7419821eca985022c8", "snapshot_path": "sources/f37224c89f82eb0882c163081cee3efec0c4f1d11c159d7419821eca985022c8.txt", "url": "https://github.com/IQSS/dataverse"}, {"fetched_at": "2026-10-24T22:37:38.463450+08:00", "kind": "license", "sha256": "194b865caa806471273cfccebabfcd8c5094297f0e31a5ab8ff2155c6f86f64c", "snapshot_path": "sources/194b865caa806471273cfccebabfcd8c5094297f0e31a5ab8ff2155c6f86f64c.txt", "url": "https://raw.githubuserconte