INSERT INTO "application" VALUES('commercial:truecommerce','TrueCommerce','{"homepage": "https://www.truecommerce.com", "id": "commercial:truecommerce", "leaf_matches": [{"reason": "官方首页正文说明其连接 ERP 与交易伙伴，跨系统/格式管理 orders、invoices、shipments，电子交换业务单据，并按特定 EDI 要求校验以避免 chargebacks。", "slug": "edi-platform", "source_urls": ["https://www.truecommerce.com/"]}], "name": "TrueCommerce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:55:06.625435+08:00", "kind": "homepage", "sha256": "c9a6ebf3ee5f2126f0c2a29e794e9e80581b3b85bb4c58bf67df5a4a1d3a0974", "snapshot_path": "sources/c9a6ebf3ee5f2126f0c2a29e794e9e80581b3b85bb4c58bf67df5a4a1d3a0974.txt", "url": "https://www.truecommerce.com/"}], "summary": "TrueCommerce 是商业 EDI 集成平台，连接 ERP 与交易伙伴，电子交换订单、发票、发货等业务单据，并按伙伴 EDI 要求校验。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cleo','Cleo','{"homepage": "https://www.cleo.com", "id": "commercial:cleo", "leaf_matches": [{"reason": "官方 MFT 产品页正文说明其用于交易伙伴/系统间安全交换文件，支持协议传输、加密、用户认证、审计跟踪、收发文件记录查询以及交易伙伴级监控/告警；对应托管文件传输的端点维护、平台执行与传输结果记录核心。", "slug": "managed-file-transfer", "source_urls": ["https://www.cleo.com/solutions/technology/mft-managed-file-transfer"]}], "name": "Cleo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:55:26.803698+08:00", "kind": "homepage", "sha256": "088d79b913136114efdea6fe6506248b9093e4bfb50e3145ca049e0efb194ea2", "snapshot_path": "sources/088d79b913136114efdea6fe6506248b9093e4bfb50e3145ca049e0efb194ea2.txt", "url": "https://www.cleo.com/"}, {"fetched_at": "2026-10-26T13:09:58.638231+08:00", "kind": "documentation", "sha256": "e883cee01e693664de263e8dba19fb062c9bbb674fa787e17132626950c23015", "snapshot_path": "sources/e883cee01e693664de263e8dba19fb062c9bbb674fa787e17132626950c23015.txt", "url": "https://www.cleo.com/solutions/technology/mft-managed-file-transfer"}], "summary": "Cleo 的 MFT 子产品用于在交易伙伴与系统间安全交换供应链文件，支持多协议、加密、审计跟踪与监控告警。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hightouch','Hightouch','{"homepage": "https://hightouch.com", "id": "commercial:hightouch", "leaf_matches": [{"reason": "官方 Reverse ETL 产品页与 Syncs 文档正文说明：从数据仓库/数据湖等源取数，一个 sync 绑定一个 model 到一个目标对象/列表/表，配置目标对象、insert/update/upsert 写入模式、记录匹配键与字段映射，并用 CDC 仅发送新增/变更/删除行，按实时或周期计划写入 300+ 业务工具；对应反向 ETL 的外部数据源、同步绑定与业务对象激活核心。", "slug": "reverse-etl-platform", "source_urls": ["https://hightouch.com/platform/reverse-etl", "https://hightouch.com/docs/syncs/overview"]}], "name": "Hightouch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:55:41.630921+08:00", "kind": "homepage", "sha256": "20da8ecde221a92ffc44b6d165d775d7a74a0e2fbae44e43b8f2e73b54cf79f9", "snapshot_path": "sources/20da8ecde221a92ffc44b6d165d775d7a74a0e2fbae44e43b8f2e73b54cf79f9.txt", "url": "https://hightouch.com/"}, {"fetched_at": "2026-10-26T13:09:59.016914+08:00", "kind": "documentation", "sha256": "bcfbf62071d6ff8cb3026b47d5e076e4d9b2c83c9687f5762826e337cdfdcf1d", "snapshot_path": "sources/bcfbf62071d6ff8cb3026b47d5e076e4d9b2c83c9687f5762826e337cdfdcf1d.txt", "url": "https://hightouch.com/platform/reverse-etl"}, {"fetched_at": "2026-10-26T13:12:27.549329+08:00", "kind": "documentation", "sha256": "78031c9851274e47d7e4db276a10037fc91a0a2e7e229c9ad5b718949d703f18", "snapshot_path": "sources/78031c9851274e47d7e4db276a10037fc91a0a2e7e229c9ad5b718949d703f18.txt", "url": "https://hightouch.com/docs/syncs/overview"}], "summary": "Hightouch Reverse ETL 从客户数据仓库/数据湖读取数据，按同步定义映射字段并写入 300+ 业务工具。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:192640529','Label Studio','{"deployment": ["官方文档提供 Docker/Python 自托管；本轮未部署"], "features": ["管理数据项目、标签方案和标注任务", "支持图像、文本、音频等多模态标注", "导出结构化标注数据集"], "github_repository_id": 192640529, "homepage": "https://labelstud.io", "id": "github:192640529", "leaf_matches": [{"reason": "官方 README 明确 Label Studio 是开源数据标注工具，可在多用户、多项目下以可配置标签格式标注图像/文本/音频/视频/时间序列，从云存储导入并导出为多种模型格式，且提供 Docker/Python 自托管；对应受管数据项、标签方案、人工标注与结构化导出核心。", "slug": "data-labeling-platform", "source_urls": ["https://raw.githubusercontent.com/HumanSignal/label-studio/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/HumanSignal/label-studio/master/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/HumanSignal/label-studio/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Label Studio", "repository_url": "https://github.com/HumanSignal/label-studio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:57:55.248024+08:00", "kind": "repository_metadata", "sha256": "05c7a52c59fde524982142c536876827b16bab62ffcc2702560f9f9e92e518a7", "snapshot_path": "sources/05c7a52c59fde524982142c536876827b16bab62ffcc2702560f9f9e92e518a7.txt", "url": "https://github.com/HumanSignal/label-studio"}, {"fetched_at": "2026-10-24T22:58:00.195274+08:00", "kind": "license", "sha256": "ca656b15c1e22468c7798df4356660755fb1ccd12d7ee0bade82bd65e3038e1b", "snapshot_path": "sources/ca656b15c1e22468c7798df4356660755fb1ccd12d7ee0bade82bd65e3038e1b.txt", "url": "https://raw.githubusercontent.com/HumanSignal/label-studio/master/LICENSE"}, {"fetched_at": "2026-10-24T22:57:57.479619+08:00", "kind": "readme", "sha256": "40700321776602f0ee8e84bb1bc54eaa3a526dba95aa44658e2a1ee48bbcbd16", "snapshot_path": "sources/40700321776602f0ee8e84bb1bc54eaa3a526dba95aa44658e2a1ee48bbcbd16.txt", "url": "https://raw.githubusercontent.com/HumanSignal/label-studio/master/README.md"}], "summary": "Label Studio 是可自托管的开源数据标注平台，支持图像、文本、音频、视频等多模态标注与结构化导出。", "technology_stack": ["Python", "React", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:642497346','Langfuse','{"deployment": ["官方文档提供 Docker Compose 自托管；企业目录另按企业许可，本轮仅匹配 MIT 社区核心"], "features": ["采集 LLM 应用的 trace 与步骤详情", "管理提示版本并通过 production 等标签控制发布", "提供评估与数据集运行记录"], "github_repository_id": 642497346, "homepage": "https://langfuse.com", "id": "github:642497346", "leaf_matches": [{"reason": "官方 README 的 LLM Application Observability 说明插桩采集 trace、跟踪模型/检索/嵌入/智能体步骤并可检查会话，符合 LLM 可观测平台核心；仅计 MIT 社区核心。", "slug": "llm-observability-platform", "source_urls": ["https://raw.githubusercontent.com/langfuse/langfuse/main/README.md"]}, {"reason": "官方 README 说明 Langfuse 集中管理并版本控制提示，官方提示管理文档补充 version、production 标签与运行时 API/SDK 获取，符合提示管理平台核心；仅计 MIT 社区核心。", "slug": "prompt-management-platform", "source_urls": ["https://raw.githubusercontent.com/langfuse/langfuse/main/README.md", "https://langfuse.com/docs/prompt-management/get-started"]}, {"reason": "README 与官方 Tracing 文档明确：SDK 采集应用内 LLM 调用、检索、嵌入与智能体动作，形成含输入/输出/时延的嵌套 trace，并可在 UI 中逐条检视；符合“插桩捕获→执行 trace→持久化存储→检视界面”的定义核心。", "slug": "agent-observability-platform", "source_urls": ["https://raw.githubusercontent.com/langfuse/langfuse/main/README.md", "https://langfuse.com/docs/observability/overview.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/langfuse/langfuse/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/langfuse/langfuse/main/LICENSE", "spdx_id": "MIT"}, "name": "Langfuse", "repository_url": "https://github.com/langfuse/langfuse", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:53:41.847089+08:00", "kind": "repository_metadata", "sha256": "5ab285941744db7d81afce534051f037046c1db045c261b249d3e0d588713a62", "snapshot_path": "sources/5ab285941744db7d81afce534051f037046c1db045c261b249d3e0d588713a62.txt", "url": "https:/