tack": ["TypeScript", "Node.js", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:315977578','Evidently','{"deployment": ["官方 README 提供 pip 安装与本地 Evidently UI；告警、用户管理等为 Evidently Cloud 额外功能，本轮未部署"], "features": ["使用参考数据集评估数据质量、分布漂移与模型表现", "生成 Report/Test Suite 并设置通过/失败条件", "通过自托管 Monitoring UI 按时间查看指标与测试结果"], "github_repository_id": 315977578, "homepage": "https://www.evidentlyai.com", "id": "github:315977578", "leaf_matches": [{"reason": "官方 README 说明 Evidently 开源版可评估、测试并监控 ML 系统，Monitoring UI 按时间展示指标与测试结果，并以参考数据集做漂移评估；告警等为 Evidently Cloud 额外功能，故仅计自托管 OSS 的报告/监控子工作流。", "slug": "ml-model-monitoring-platform", "source_urls": ["https://raw.githubusercontent.com/evidentlyai/evidently/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/evidentlyai/evidently/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/evidentlyai/evidently/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Evidently", "repository_url": "https://github.com/evidentlyai/evidently", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:53:49.565780+08:00", "kind": "repository_metadata", "sha256": "fd71432541056fa2150c4526dd146c8b0822f88f5104f186e404a63fad61dcd1", "snapshot_path": "sources/fd71432541056fa2150c4526dd146c8b0822f88f5104f186e404a63fad61dcd1.txt", "url": "https://github.com/evidentlyai/evidently"}, {"fetched_at": "2026-10-24T22:53:51.973063+08:00", "kind": "license", "sha256": "379054a067cbe8e134e084287550e9391d2804636687c4723f80a2c58a463f0e", "snapshot_path": "sources/379054a067cbe8e134e084287550e9391d2804636687c4723f80a2c58a463f0e.txt", "url": "https://raw.githubusercontent.com/evidentlyai/evidently/main/LICENSE"}, {"fetched_at": "2026-10-24T22:53:50.847129+08:00", "kind": "readme", "sha256": "c8ac72c2363a2f0b7c36f38a6e7801817e5659507a2e6a37212702ad1cd51c20", "snapsho