INSERT INTO "application" VALUES('github:136202695','MLflow','{"deployment": ["官方文档支持本地/服务器自托管；本轮未部署"], "features": ["记录实验参数、指标与产物", "管理模型版本、阶段与别名", "支持批量/实时部署，并通过注册表/别名消费模型版本"], "github_repository_id": 136202695, "homepage": "https://mlflow.org", "id": "github:136202695", "leaf_matches": [{"reason": "官方 README 与 Model Registry 文档说明 MLflow 提供注册模型、版本、别名、阶段、血缘、标签/描述，并可被部署按别名消费，符合模型注册中心核心。", "slug": "model-registry", "source_urls": ["https://raw.githubusercontent.com/mlflow/mlflow/master/README.md", "https://mlflow.org/docs/latest/ml/model-registry/"]}, {"reason": "官方 README 与 Model Registry 文档说明 MLflow 以 Experiment Tracking 记录运行参数/指标/结果、以 Model Registry 管理模型版本与生命周期、并提供批量/实时部署，三结构齐备，符合 MLOps 平台核心。", "slug": "mlops-platform", "source_urls": ["https://raw.githubusercontent.com/mlflow/mlflow/master/README.md", "https://mlflow.org/docs/latest/ml/model-registry/"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/mlflow/mlflow/master/LICENSE.txt", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/mlflow/mlflow/master/LICENSE.txt", "spdx_id": "Apache-2.0"}, "name": "MLflow", "repository_url": "https://github.com/mlflow/mlflow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:54:02.342419+08:00", "kind": "repository_metadata", "sha256": "211187453a048c7971d94dcd11faed98ecc4a1f01efc3a5926ec319ce056f746", "snapshot_path": "sources/211187453a048c7971d94dcd11faed98ecc4a1f01efc3a5926ec319ce056f746.txt", "url": "https://github.com/mlflow/mlflow"}, {"fetched_at": "2026-10-24T22:54:13.724206+08:00", "kind": "license", "sha256": "6395355de6f391afff35996a30fb41b189b4991a4cb54993ace35ab69a0bfa28", "snapshot_path": "sources/6395355de6f391afff35996a30fb41b189b4991a4cb54993ace35ab69a0bfa28.txt", "url": "https://raw.githubusercontent.com/mlflow/mlflow/master/LICENSE.txt"}, {"fetched_at": "2026-10-24T22:54:03.689796+08:00", "kind": "readme", "sha256": "e9b30b8aee35e78fb87bdbbfcf837e8739f596aef5f6def89e735680d7d8b00e", "snapshot_path": "sources/e9b30b8aee35e78fb87bdbbfcf837e8739f596aef5f6def89e735680d7d8b00e.txt", "url": "https://raw.githubusercontent.com/mlflow/mlflow/master/README.md"}, {"fetched_at": "2026-10-26T13:12:26.971769+08:00", "kind": "documentation", "sha256": "eb5e4b9f5199bdc6fae2856b2c55564a64683fb7b521480383008b5bb5f9a7f3", "snapshot_path": "sources/eb5e4b9f5199bdc6fae2856b2c55564a64683fb7b521480383008b5bb5f9a7f3.txt", "url": "https://mlflow.org/docs/latest/ml/model-registry/"}], "summary": "MLflow 是可自托管的开源软件。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
