INSERT INTO "application" VALUES('commercial:medrio-rtsm','Medrio RTSM','{"homepage": "https://medrio.com/solutions/rtsm/", "id": "commercial:medrio-rtsm", "leaf_matches": [{"reason": "Medrio official RTSM page describes subject randomization, adaptive treatment allocation, stratification, kit assignment, inventory and shipment tracking, automated supply/resupply notifications, expiry management and site resupply orders, including support for single- or double-blind studies.", "slug": "irt-rtsm", "source_urls": ["https://medrio.com/solutions/rtsm/"]}], "name": "Medrio RTSM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:01:45.908033+08:00", "kind": "homepage", "sha256": "952a5fa97e9679729542eddbedfabe112250ba03478524901546a33c08f88371", "snapshot_path": "sources/952a5fa97e9679729542eddbedfabe112250ba03478524901546a33c08f88371.txt", "url": "https://medrio.com/solutions/rtsm/"}], "summary": "Medrio RTSM is a configurable clinical trial randomization and trial supply management (IRT/RTSM) application for subject randomization, treatment allocation, stratification, kit assignment, inventory and shipment tracking, automated supply/resupply notifications, expiry tracking and site resupply orders.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:montrium-etmf-connect','Montrium eTMF Connect','{"homepage": "https://www.montrium.com/etmf-connect/", "id": "commercial:montrium-etmf-connect", "leaf_matches": [{"reason": "Montrium official eTMF page describes TMF Reference Model 3.3.1-aligned structures, study TMF plans/document indexes, placeholders, real-time completeness and missing-document reporting, role-based access, email-to-TMF intake and full audit trails.", "slug": "electronic-trial-master-file-etmf", "source_urls": ["https://www.montrium.com/etmf-connect/"]}], "name": "Montrium eTMF Connect", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:50.859964+08:00", "kind": "homepage", "sha256": "6b7a619481e552a327a86aaa3bb14777f8af25775f426361101a53ad0e81fa65", "snapshot_path": "sources/6b7a619481e552a327a86aaa3bb14777f8af25775f426361101a53ad0e81fa65.txt", "url": "https://www.montrium.com/etmf-connect/"}], "summary": "Montrium eTMF Connect is a clinical trial electronic trial master file application with TMF Reference Model structures, document indexing, completeness tracking and inspection readiness.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:montrium-training-management','Montrium Training Management','{"homepage": "https://www.montrium.com/training-management-software", "id": "commercial:montrium-training-management", "leaf_matches": [{"reason": "Montrium official training page body contains: ''GxP training management made easy''; an ''Automated training matrix'' that distributes activities ''based on role and job title''; ''Automate the distribution of retraining tasks when critical SOPs, policies, and work instructions are updated''; ''Training gaps reporting''; ''21 CFR Part 11 eSignatures'' with ''Annex 11 compliant digital signatures''; ''Full tracking & audit trails''; ''Real-time progress data'' capturing ''training completion information''; and a ''built-in records center to store final records in accordance with 21 CFR Part 11''.", "slug": "gxp-training-management", "source_urls": ["https://www.montrium.com/training-management-software"]}], "name": "Montrium Training Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:52.474519+08:00", "kind": "homepage", "sha256": "41d1aeee8c9827c7ae78a599ba6ef192911ecd6963d209763413f05b79aacf54", "snapshot_path": "sources/41d1aeee8c9827c7ae78a599ba6ef192911ecd6963d209763413f05b79aacf54.txt", "url": "https://www.montrium.com/training-management-software"}], "summary": "Montrium Training Management is a training management application for life-science companies whose official page states GxP training management, an automated role/job-title training matrix, retraining when SOPs/policies/work instructions are updated, training-gap reporting, training-completion records, 21 CFR Part 11 eSignatures with Annex 11-compliant digital signatures, audit trails and a Part 11 records center.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:meg-quality-management','MEG Healthcare Quality Management','{"homepage": "https://megit.com/usa-quality-management-software", "id": "commercial:meg-quality-management", "leaf_matches": [{"reason": "MEG official page describes healthcare quality/risk/compliance workflows: incident and near-miss reporting, investigations and root-cause work, risk registers, corrective actions tracked to completion, audit preparation, accreditation readiness and policy management.", "slug": "healthcare-quality-management", "source_urls": ["https://megit.com/usa-quality-management-software"]}], "name": "MEG Healthcare Quality Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:54.697998+08:00", "kind": "homepage", "sha256": "9b8f87b11af881fead223d2436a334f05f923a6fc5bd711529c6b844bbca7333", "snapshot_path": "sources/9b8f87b11af881fead223d2436a334f05f923a6fc5bd711529c6b844bbca7333.txt", "url": "https://megit.com/usa-quality-management-software"}], "summary": "MEG is a healthcare quality, risk and compliance platform for incident and near-miss reporting, investigations, risk registers, corrective actions, audit/accreditation readiness and policy management.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:qmsdesk','QMSdesk','{"homepage": "https://www.qmsdesk.com/", "id": "commercial:qmsdesk", "leaf_matches": [{"reason": "QMSdesk 官方首页正文明确为面向生命科学的 cloud eQMS，列出 quality events（偏差/投诉/OOS）、CAPA、change control、audit management、risk management、audit trail/e-signatures 与文档/培训控制；与叶子要求的质量记录、闭环工作流和证据姿态一致。", "slug": "life-sciences-qms", "source_urls": ["https://www.qmsdesk.com/"]}], "name": "QMSdesk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:09.909422+08:00", "kind": "homepage", "sha256": "6a4dc5c148a833c5426d1261a02eb10cdb7541bb669a07cc51f55c2a4134fa14", "snapshot_path": "sources/6a4dc5c148a833c5426d1261a02eb10cdb7541bb669a07cc51f55c2a4134fa14.txt", "url": "https://www.qmsdesk.com/"}], "summary": "QMSdesk is a cloud eQMS for life sciences covering document control, quality events, CAPA, change control, training, risk and audits.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:greenlight-guru','Greenlight Guru','{"homepage": "https://www.greenlight.guru/", "id": "commercial:greenlight-guru", "leaf_matches": [{"reason": "Greenlight Guru 官方首页正文描述 design controls/DHF、用户需求-要求-验证链接、ISO 14971 风险管理与端到端可追溯性，并覆盖从开发到 post-market 的器械生命周期；符合器械设计控制记录链与受控变更核心。", "slug": "medical-device-lifecycle-management", "source_urls": ["https://www.greenlight.guru/"]}], "name": "Greenlight Guru", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:14.107951+08:00", "kind": "homepage", "sha256": "4c861ef7c4b27dcdc80948d21dbe0200d4a01ff9251437583742142401760ad1", "snapshot_path": "sources/4c861ef7c4b27dcdc80948d21dbe0200d4a01ff9251437583742142401760ad1.txt", "url": "https://www.greenlight.guru/"}], "summary": "Greenlight Guru is a MedTech quality and product lifecycle platform with design controls, DHF, risk management, traceability and post-market quality/complaint management.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:veeva-product-surveillance','Veeva Product Surveillance','{"homepage": "https://www.veeva.com/medtech/products/quality/product-surveillance", "id": "commercial:veeva-product-surveillance", "leaf_matches": [{"reason": "Veeva 官方产品页正文明确面向医疗器械/诊断的 postmarket incident reporting management，含 complaint handling、global reportability decision tree、submission timeliness 与 complaint-handling metrics；覆盖现场安全事件评估/可报告性与监管提交跟踪核心。设备群体趋势/信号分析未在该快照明示，按边界收窄。", "slug": "medical-device-post-market-surveillance", "source_urls": ["https://www.veeva.com/medtech/products/quality/product-surveillance", "https://www.veeva.com/medtech/resources/vault-product-surveillance-product-brief"]}], "name": "Veeva Product Surveillance", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:37:38.020257+08:00", "kind": "homepage", "sha256": "e4dc81857dec9b9fcba5499afd11f8e416664bc3277cd01647ae7a3016b0ec19", "snapshot_path": "sources/e4dc81857dec9b9fcba5499afd11f8e416664bc3277cd01647ae7a3016b0ec19.txt", "url": "https://www.veeva.com/medtech/products/quality/product-surveillance"}, {"fetched_at": "2026-10-26T13:40:43.545087+08:00", "kind": "documentation", "sha256": "c8b7cfc262723210d834d184bee0b6c5baaed2103cbbb5adabb1d1596e21f844", "snapshot_path": "sources/c8b7cfc262723210d834d184bee0b6c5baaed2103cbbb5adabb1d1596e21f844.txt", "url": "https://www.veeva.com/medtech/resources/vault-product-surveillance-product-brief"}], "summary": "Veeva Product Surveillance is a postmarket surveillance and incident reporting application for medical devices and diagnostics, with complaint handling, global reportability decisions and submission tracking.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:veeva-vault-rim','Veeva Vault RIM','{"homepage": "https://www.veeva.com/products/vault-rim/", "id": "commercial:veeva-vault-rim", "leaf_matches": [{"reason": "Veeva 官方产品页正文描述 Veeva RIM 统一 registration tracking、submissions、submissions archive、correspondence and commitments、dossier publishing；覆盖产品注册、提交/案卷与监管活动记录核心。", "slug": "regulatory-information-management-rim", "source_urls": ["https://www.veeva.com/products/vault-rim/"]}], "name": "Veeva Vault RIM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:22.471784+08:00", "kind": "homepage", "sha256": "d74c02e5f23fe95b9bd2eb1f198f217c281fb4ecd62b382107482fa1f44e2a37", "snapshot_path": "sources/d74c02e5f23fe95b9bd2eb1f198f217c281fb4ecd62b382107482fa1f44e2a37.txt", "url": "https://www.veeva.com/products/vault-rim/"}], "summary": "Veeva Vault RIM is a regulatory information management application for product registrations, submissions, dossiers, publishing, and health authority correspondence and commitments.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
