INSERT INTO "application" VALUES('commercial:healthedge','HealthEdge','{"homepage": "https://healthedge.com/", "id": "commercial:healthedge", "leaf_matches": [{"reason": "HealthEdge official HealthRules Edge page identifies a core administrative processing system for health plans and describes configurable benefit/rules, claims administration, auto-adjudication and payment accuracy; enrollment/eligibility workflow details are not shown in the snapshots.", "slug": "health-plan-administration-system", "source_urls": ["https://healthedge.com/solutions/healthrules-edge/", "https://healthedge.com/"]}, {"reason": "HealthEdge official HealthRules Edge product page describes a claims processing core system for health plans: claims administration, 90-97% first-pass auto-adjudication, 99%+ payment accuracy, and configurable benefit plans/provider contracts. Payment settlement itself is not explicitly stated in the snapshot, so it is not asserted.", "slug": "payer-claims-processing", "source_urls": ["https://healthedge.com/", "https://healthedge.com/solutions/healthrules-edge/"]}], "name": "HealthEdge", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:41:16.465928+08:00", "kind": "documentation", "sha256": "f407f9ae29acfb3798a12cd9cf5783ede69a0cdb89a2235491e90aadd1c3e8b3", "snapshot_path": "sources/f407f9ae29acfb3798a12cd9cf5783ede69a0cdb89a2235491e90aadd1c3e8b3.txt", "url": "https://healthedge.com/solutions/healthrules-edge/"}, {"fetched_at": "2026-10-25T08:04:09.221035+08:00", "kind": "homepage", "sha256": "590c366eff161fa24fcac0e006c477baf4dbb99427ee6eece1e47c3164ea43d9", "snapshot_path": "sources/590c366eff161fa24fcac0e006c477baf4dbb99427ee6eece1e47c3164ea43d9.txt", "url": "https://healthedge.com/"}], "summary": "HealthEdge HealthRules Edge is a cloud-native core administrative processing system (CAPS) for health plans, with configurable benefit/rule setup, claims administration, auto-adjudication and payment accuracy.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:waystar','Waystar','{"homepage": "https://www.waystar.com/", "id": "commercial:waystar", "leaf_matches": [{"reason": "Waystar official platform page states it provides revenue cycle management in healthcare and a complete RCM suite, with modules for financial clearance, charge integrity/revenue capture, claim and payer payment management, remittance/deposit management, denial recovery and patient payments.", "slug": "healthcare-revenue-cycle-management", "source_urls": ["https://www.waystar.com/our-platform/"]}], "name": "Waystar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:39:16.838029+08:00", "kind": "documentation", "sha256": "7ce5fca98348b8ed057a7d6eb19ea6663ee580fbe6530de4825a7be2e9483d03", "snapshot_path": "sources/7ce5fca98348b8ed057a7d6eb19ea6663ee580fbe6530de4825a7be2e9483d03.txt", "url": "https://www.waystar.com/our-platform/"}], "summary": "Waystar is a healthcare revenue cycle management platform covering financial clearance, charge capture, claims and payer payment management, remittance posting, denial recovery and patient payments.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:phreesia','Phreesia','{"homepage": "https://www.phreesia.com/", "id": "commercial:phreesia", "leaf_matches": [{"reason": "Phreesia official platform page describes registration, check-in, signed consents, real-time insurance eligibility, pre-registration completion tracking and bidirectional patient-data flow into PM/EHR.", "slug": "patient-registration-intake", "source_urls": ["https://www.phreesia.com/platform/", "https://www.phreesia.com/"]}], "name": "Phreesia", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:41:54.542169+08:00", "kind": "documentation", "sha256": "1a788b36ffca6a7113e488d2124cacd6beb9e0b3815a9b8b2aa1bc9ecee0817e", "snapshot_path": "sources/1a788b36ffca6a7113e488d2124cacd6beb9e0b3815a9b8b2aa1bc9ecee0817e.txt", "url": "https://www.phreesia.com/platform/"}, {"fetched_at": "2026-10-25T08:04:15.693280+08:00", "kind": "homepage", "sha256": "942861c8915a451958ad6c757d7b9265d5c1c3a4512ad4bbfeb14bb3862ad06c", "snapshot_path": "sources/942861c8915a451958ad6c757d7b9265d5c1c3a4512ad4bbfeb14bb3862ad06c.txt", "url": "https://www.phreesia.com/"}], "summary": "Phreesia is a patient intake and registration platform covering registration, digital check-in, consents, forms, insurance eligibility, payments and bidirectional PM/EHR data handoff.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zeomega-jiva','ZeOmega Jiva','{"homepage": "https://www.zeomega.com/", "id": "commercial:zeomega-jiva", "leaf_matches": [{"reason": "ZeOmega official care-management page describes risk identification, member needs assessment, auto-recommended care-plan goals and interventions, chronic/acute care programs and care-management workflows.", "slug": "payer-care-management", "source_urls": ["https://www.zeomega.com/solutions/care-management-solution", "https://www.zeomega.com/"]}], "name": "ZeOmega Jiva", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:41:31.341978+08:00", "kind": "documentation", "sha256": "6910956f392b055a2ed9b0258c11b3ec65187ea5df155b6fb4975d142835fe1b", "snapshot_path": "sources/6910956f392b055a2ed9b0258c11b3ec65187ea5df155b6fb4975d142835fe1b.txt", "url": "https://www.zeomega.com/solutions/care-management-solution"}, {"fetched_at": "2026-10-25T08:04:26.728059+08:00", "kind": "homepage", "sha256": "d0e118e42c3740b84ae1725694550dc31b3a5bf3d7b6b575509fa54c888f0119", "snapshot_path": "sources/d0e118e42c3740b84ae1725694550dc31b3a5bf3d7b6b575509fa54c888f0119.txt", "url": "https://www.zeomega.com/"}], "summary": "ZeOmega Jiva is a payer care management platform for risk identification, member needs assessment, care-plan goals and interventions, care-program workflows and population health.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:679584','OpenEMR','{"deployment": ["Self-hosted web application", "Windows, Linux and macOS support"], "features": ["Patient demographics and registration", "Patient scheduling and flow board", "Medical billing and claim management", "Electronic claim submission via ANSI X12", "Accounts receivable and EOB/835 interfaces", "E-prescribing"], "github_repository_id": 679584, "homepage": "https://www.open-emr.org/", "id": "github:679584", "leaf_matches": [{"reason": "OpenEMR official homepage and features page describe patient demographics, scheduling, electronic billing and claim management for medical practices; the EHR and practice-management capabilities are bundled, with the PM/billing function in scope.", "slug": "practice-management-system", "source_urls": ["https://www.open-emr.org/", "https://www.open-emr.org/wiki/index.php/OpenEMR_Features"]}, {"reason": "OpenEMR official features page documents medical billing and claim management, electronic claim submission to clearinghouses via ANSI X12, insurance tracking, accounts receivable and EOB/835 interfaces; ClaimRev module documentation describes sending claims from the billing manager and tracking 999/277 responses.", "slug": "provider-claims-management", "source_urls": ["https://www.open-emr.org/wiki/index.php/OpenEMR_Features", "https://www.open-emr.org/wiki/index.php/ClaimRev_Clearinghouse_Module"]}, {"reason": "OpenEMR''s official features page lists online drug search, tracking patient prescriptions and medications, and creating/sending prescriptions via E-Prescribe, print, fax or email; the homepage describes electronic sending to the patient''s pharmacy.", "slug": "electronic-prescribing", "source_urls": ["https://www.open-emr.org/wiki/index.php/OpenEMR_Features", "https://www.open-emr.org/"]}, {"reason": "OpenEMR 官方 Features 页与用户指南记录：患者人口学与 Patient Summary；Medical Issues（文档明确 issue 为 medical problem、allergy、medication 等）与 Encounter 关联；Medications；SOAP/临床笔记；encounters 与 past encounters；登录后按 provider 工作，未授权用户无法查看问题、免疫与处方，Features 页并称基于角色菜单与细粒度逐用户访问控制。据此匹配以已识别患者纵向图表、问题/药物/笔记、encounter 组织与角色限制访问为核心的 EHR 定义。", "slug": "electronic-health-record-ehr", "source_urls": ["https://api.github.com/repos/openemr/openemr", "https://api.github.com/repos/openemr/openemr/license", "https://raw.githubusercontent.com/openemr/openemr/master/README.md", "https://www.open-emr.org/wiki/index.php/OpenEMR_Features", "https://www.open-emr.org/wiki/index.php/Issues_%26_Immunizations_4.1", "https://www.open-emr.org/wiki/index.php/New_Encounters_%26_Coding_4.1", "https://www.open-emr.org/wiki/index.php/Patient_Notes_%26_Transactions_4.1"]}, {"reason": "OpenEMR 仓库内 Procedures 帮助明确该模块用于 place and review orders，并说明其满足实验室与影像 CPOE，覆盖 Procedure、Laboratory Test、Imaging 等可开项；官方 wiki 记录医嘱可保存/传输、进入 pending review、更新状态，并在签署后回写患者结果与 encounter。关系限定在检查、影像与操作类医嘱的创建、传输、审阅与签署后结果回链；所引帮助文件中的 Canceled 属于 Procedure Report/Result Statuses，仅表示报告/结果取消状态，不作为医嘱停用证据；不主张药物医嘱修订/续开/停用或开嘱医生归属。", "slug": "cpoe-clinical-order-management", "source_urls": ["https://raw.githubusercontent.com/openemr/openemr/master/README.md", "https://raw.githubusercontent.com/openemr/openemr/master/Documentation/help_files/procedure_provider_help.php", "https://www.open-emr.org/wiki/index.php/Procedure_configuration_%26_order_process", "https://raw.githubusercontent.com/openemr/openemr/master/Documentation/help_files/configure_orders_help.php"]}, {"reason": "OpenEMR README 官方列出 scheduling 作为 medical practice management 的一部分，记录为集成 EHR 内的预约调度能力；README 未展开服务类型、时间槽或预约生命周期细节，故不主张独立调度产品。", "slug": "patient-scheduling", "source_urls": ["https://raw.githubusercontent.com/openemr/openemr/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/openemr/openemr/license", "license_review": {"rationale": "GitHub license API returns GPL-3.0 and repository metadata confirms OpenEMR.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://api.github.com/repos/openemr/openemr/license", "spdx_id": "GPL-3.0"}, "name": "OpenEMR", "repository_url": "https://github.com/openemr/openemr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:24.006526+08:00", "kind": "repository_metadata", "sha256": "89f29f5bf435378277a6521426431931a53d29d658a1432508acf9a410bcaa63", "snapshot_path": "sources/89f29f5bf435378277a6521426431931a53d29d658a1432508acf9a410bcaa63.txt", "url": "https://api.github.com/repos/openemr/openemr"}, {"fetched_at": "2026-10-25T08:02:26.602200+08:00", "kind": "license", "sha256": "9c87137e367c506e0a3b2e3c3ac23047df5828d81ea3b69775bef2debe8be666", "snapshot_path": "sources/9c87137e367c506e0a3b2e3c3ac23047df5828d81ea3b69775bef2debe8be666.txt", "url": "https://api.github.com/repos/openemr/openemr/license"}, {"fetched_at": "2026-10-25T08:04:39.563090+08:00", "kind": "homepage", "sha256": "214f5f934f05f75859259da16c8af7a9ee139c4e6c94526e9bef83fc4846b622", "snapshot_path": "sources/214f5f934f05f75859259da16c8af7a9ee139c4e6c94526e9bef83fc4846b622.txt", "url": "https://www.open-emr.org/"}, {"fetched_at": "2026-10-26T13:41:11.390943+08:00", "kind": "documentation", "sha256": "059f852e5a05eb2ee9a79a828094a8424e51d5976dbf0c0c37e06807f3dff1c4", "snapshot_path": "sources/059f852e5a05eb2ee9a79a828094a8424e51d5976dbf0c0c37e06807f3dff1c4.txt", "url": "https://www.open-emr.org/wiki/index.php/OpenEMR_Features"}, {"fetched_at": "2026-10-26T13:41:04.075107+08:00", "kind": "documentation", "sha256": "2919176dde970886db3f4cca653c6da1cc4b4f08a6bff2bbd313ad7c45c71e34", "snapshot_path": "sources/2919176dde970886db3f4cca653c6da1cc4b4f08a6bff2bbd313ad7c45c71e34.txt", "url": "https://www.open-emr.org/wiki/index.php/ClaimRev_Clearinghouse_Module"}, {"fetched_at": "2026-10-26T13:46:40.522114+08:00", "kind": "readme", "sha256": "4116f147eec550fa1762c1f8be13a90097b6bba7fc266d14cbb93722d1be819f", "snapshot_path": "sources/4116f147eec550fa1762c1f8be13a90097b6bba7fc266d14cbb93722d1be819f.txt", "url": "https://api.github.com/repos/openemr/openemr/readme"}, {"fetched_at": "2026-10-26T13:50:35.798962+08:00", "kind": "documentation", "sha256": "0d03742e17f4b888fdb5a4163d4d360cd66e0290e4585916e1fd4b7505212c8b", "snapshot_path": "sources/0d03742e17f4b888fdb5a4163d4d360cd66e0290e4585916e1fd4b7505212c8b.txt", "url": "https://www.open-emr.org/wiki/index.php/OpenEMR_Features"}, {"fetched_at": "2026-10-25T08:02:10.233537+08:00", "kind": "readme", "sha256": "c3b6d3d05bfe5761f3bcb92717e94ec2d9837bd2667b19d1a31d9fb30933178f", "snapshot_path": "sources/c3b6d3d05bfe5761f3bcb92717e94ec2d9837bd2667b19d1a31d9fb30933178f.txt", "url": "https://raw.githubusercontent.com/openemr/openemr/master/README.md"}, {"fetched_at": "2026-10-26T23:14:29.994801+08:00", "kind": "documentation", "sha256": "f3cd65723f9957a1988c193a17b14968ecbb6a0daf4ab596c35130626acb50ef", "snapshot_path": "sources/f3cd65723f9957a1988c193a17b14968ecbb6a0daf4ab596c35130626acb50ef.txt", "url": "https://raw.githubusercontent.com/openemr/openemr/master/Documentation/help_files/procedure_provider_help.php"}, {"fetched_at": "2026-10-26T23:16:25.291074+08:00", "kind": "documentation", "sha256": "d3e001a2074f419b64d890328fdd51052793a71f495c73d3c247ec0946835005", "snapshot_path": "sources/d3e001a2074f419b64d890328fdd51052793a71f495c73d3c247ec0946835005.txt", "url": "https://www.open-emr.org/wiki/index.php/Procedure_configuration_%26_order_process"}, {"fetched_at": "2026-10-26T23:18:12.262276+08:00", "kind": "documentation", "sha256": "d698ac3b06df9fd8c2db37f93e5883061bc0c1a3b1fd886d94a87bd8e06bea00", "snapshot_path": "sources/d698ac3b06df9fd8c2db37f93e5883061bc0c1a3b1fd886d94a87bd8e06bea00.txt", "url": "https://raw.githubusercontent.com/openemr/openemr/master/Documentation/help_files/configure_orders_help.php"}, {"fetched_at": "2026-10-26T23:27:30.843835+08:00", "kind": "documentation", "sha256": "56c8f0b49a45401a121d2b5a9532e50fdd58ca960fe6e5f577f6e8a1d91da534", "snapshot_path": "sources/56c8f0b49a45401a121d2b5a9532e50fdd58ca960fe6e5f577f6e8a1d91da534.txt", "url": "https://www.open-emr.org/wiki/index.php/OpenEMR_Features"}, {"fetched_at": "2026-10-26T23:28:55.842597+08:00", "kind": "documentation", "sha256": "8e8661803be2e1c0f8c54bca70021e527026d132f9297521d3ed45c29e240980", "snapshot_path": "sources/8e8661803be2e1c0f8c54bca70021e527026d132f9297521d3ed45c29e240980.txt", "url": "https://www.open-emr.org/wiki/index.php/Issues_%26_Immunizations_4.1"}, {"fetched_at": "2026-10-26T23:29:25.247203+08:00", "kind": "documentation", "sha256": "3b767a53ecc72ccd14298bb9f15442013cd3f664bf8c762a42f7d0837c08c84b", "snapshot_path": "sources/3b767a53ecc72ccd14298bb9f15442013cd3f664bf8c762a42f7d0837c08c84b.txt", "url": "https://www.open-emr.org/wiki/index.php/New_Encounters_%26_Coding_4.1"}, {"fetched_at": "2026-10-26T23:28:39.689062+08:00", "kind": "documentation", "sha256": "288015bd688c4b9564cbf2ecb062b92d0c7b7a713911200c81609fca031c4130", "snapshot_path": "sources/288015bd688c4b9564cbf2ecb062b92d0c7b7a713911200c81609fca031c4130.txt", "url": "https://www.open-emr.org/wiki/index.php/Patient_Notes_%26_Transactions_4.1"}], "summary": "OpenEMR is an open source electronic health records and medical practice management application with patient demographics, scheduling, medical billing and claim management, AR/EOB interfaces and e-prescribing.", "technology_stack": ["PHP", "MySQL/MariaDB", "Web browser client"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:availity','Availity','{"homepage": "https://www.availity.com/", "id": "commercial:availity", "leaf_matches": [{"reason": "Availity official Intelligent Utilization Management page describes AI-assisted prior authorization: requests carry clinical data, recommendations follow the plan''s medical policy, pended cases go to human review, and determinations return through FHIR APIs or the portal while the health plan remains the decision authority.", "slug": "prior-authorization-platform", "source_urls": ["https://www.availity.com/intelligentum/"]}], "name": "Availity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:05:17.443771+08:00", "kind": "homepage", "sha256": "3666badc323de219d289a31ead78499acf71e7ccb72f15a7714a22d4e82b07eb", "snapshot_path": "sources/3666badc323de219d289a31ead78499acf71e7ccb72f15a7714a22d4e82b07eb.txt", "url": "https://www.availity.com/"}, {"fetched_at": "2026-10-26T13:40:39.422301+08:00", "kind": "documentation", "sha256": "4b7a822dd8bbc5f2ba50ccc53b9b942fe40de5d12f8ff22fc3aa16de270555a4", "snapshot_path": "sources/4b7a822dd8bbc5f2ba50ccc53b9b942fe40de5d12f8ff22fc3aa16de270555a4.txt", "url": "https://www.availity.com/intelligentum/"}], "summary": "Availity is a healthcare network platform for provider-payer connectivity, prior authorization and utilization management.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:healthstream-v12','V12 Enterprise by HealthStream','{"homepage": "https://www.healthstream.com/", "id": "commercial:healthstream-v12", "leaf_matches": [{"reason": "The official V12 Enterprise by HealthStream page is explicitly built for U.S. healthcare payers and describes full provider lifecycle management including provider data, credentialing, contracting, network adequacy analytics, directory accuracy, delegated credentialing oversight and claims activation.", "slug": "provider-network-management", "source_urls": ["https://www.healthstream.com/solution/credentialing/network"]}], "name": "V12 Enterprise by HealthStream", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:44:59.897135+08:00", "kind": "documentation", "sha256": "7e01edad339c5aa4761b7705ca8e801ac5d5bb0ac6b8d480ccaeea5de9fe2843", "snapshot_path": "sources/7e01edad339c5aa4761b7705ca8e801ac5d5bb0ac6b8d480ccaeea5de9fe2843.txt", "url": "https://www.healthstream.com/solution/credentialing/network"}], "summary": "V12 Enterprise by HealthStream is a provider network management platform for U.S. healthcare payers, covering provider data, credentialing, contracting, network adequacy, directory accuracy, delegated credentialing oversight and claims activation.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:mhk','MHK','{"homepage": "https://mhk.com/", "id": "commercial:mhk", "leaf_matches": [{"reason": "MHK''s CareProminence Utilization Management page describes medical-necessity review of prior authorizations, concurrent inpatient and post-service cases, case inventory and turnaround dashboards, configurable approval logic and routing, built-in compliance alerts, and a provider portal with appeals submission.", "slug": "utilization-management", "source_urls": ["https://mhk.com/solutions/mhk-careprominence/utilization-management-suite/"]}], "name": "MHK", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:47:36.489672+08:00", "kind": "documentation", "sha256": "7afa60e3a76f83bf682ac4761c2a5a26f0ab1a26792b55b2157fa134db8d98f5", "snapshot_path": "sources/7afa60e3a76f83bf682ac4761c2a5a26f0ab1a26792b55b2157fa134db8d98f5.txt", "url": "https://mhk.com/solutions/mhk-careprominence/utilization-management-suite/"}], "summary": "MHK CareProminence is a health-plan utilization management suite for medical-necessity review, prior authorization, concurrent and post-service review, compliance and provider self-service.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:innovaccer','Innovaccer','{"homepage": "https://innovaccer.com/", "id": "commercial:innovaccer", "leaf_matches": [{"reason": "Innovaccer''s value-based care page describes contract management with financial modeling, performance tracking and scenario analysis, risk adjustment, quality measurement, and shared-savings/downside-risk performance for value-based contracts.", "slug": "value-based-care-platform", "source_urls": ["https://innovaccer.com/value-based-care"]}], "name": "Innovaccer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:05:48.628449+08:00", "kind": "homepage", "sha256": "152e1bc3a68e9627c1ac2d5c554b2add5a8d73e53841c69af2fd1bf4e8ca28d1", "snapshot_path": "sources/152e1bc3a68e9627c1ac2d5c554b2add5a8d73e53841c69af2fd1bf4e8ca28d1.txt", "url": "https://innovaccer.com/"}, {"fetched_at": "2026-10-26T13:46:41.560690+08:00", "kind": "documentation", "sha256": "14176d10307201155625c77812b7c565ce3a116ab59bbae89fc432a8b061a250", "snapshot_path": "sources/14176d10307201155625c77812b7c565ce3a116ab59bbae89fc432a8b061a250.txt", "url": "https://innovaccer.com/value-based-care"}], "summary": "Innovaccer is a healthcare intelligence cloud whose value-based care solutions cover contract management, risk adjustment, quality measurement and financial performance tracking for value-based contracts.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:brightree','Brightree','{"homepage": "https://www.brightree.com/", "id": "commercial:brightree", "leaf_matches": [{"reason": "Brightree''s HME (DME) software page describes referral and intake workflows, DME billing and reimbursement, mobile delivery, patient resupply and documentation; the homepage additionally describes inventory for HME/DME providers.", "slug": "durable-medical-equipment-management", "source_urls": ["https://www.brightree.com/hme-dme-software/", "https://www.brightree.com/"]}, {"reason": "Brightree''s Home Infusion Pharmacy page describes home infusion pharmacy workflows from referral to revenue, including clinical oversight, compounding support for infusion and TPN prescriptions, and billing and compliance documentation.", "slug": "home-infusion-management", "source_urls": ["https://www.brightree.com/home-infusion-pharmacy/"]}], "name": "Brightree", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:05:51.665993+08:00", "kind": "homepage", "sha256": "651e5cf5e11664b500472c4ab39f406f069848ba515aafe40301becc7f1af4a4", "snapshot_path": "sources/651e5cf5e11664b500472c4ab39f406f069848ba515aafe40301becc7f1af4a4.txt", "url": "https://www.brightree.com/"}, {"fetched_at": "2026-10-26T13:48:19.047414+08:00", "kind": "documentation", "sha256": "73b1310e144dbdaf513874322cd910eee3362404e0b694fe69a4d269ff7a4ac1", "snapshot_path": "sources/73b1310e144dbdaf513874322cd910eee3362404e0b694fe69a4d269ff7a4ac1.txt", "url": "https://www.brightree.com/hme-dme-software/"}, {"fetched_at": "2026-10-26T13:46:41.101100+08:00", "kind": "documentation", "sha256": "b998e2dc03f5e093da4508b6694fb4814060d100802ac3554915a0ce131d1879", "snapshot_path": "sources/b998e2dc03f5e093da4508b6694fb4814060d100802ac3554915a0ce131d1879.txt", "url": "https://www.brightree.com/home-infusion-pharmacy/"}], "summary": "Brightree is a cloud-based business management platform for HME/DME providers and home infusion pharmacies, covering documentation, inventory, delivery, resupply, billing and clinical workflows.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:13562581','Adapt Authoring Tool','{"deployment": ["官方 README 说明为 Node.js/Backbone.js/MongoDB 的服务端应用，可自托管；本次未部署"], "features": ["基于 Web 的课程创建、编辑与发布（作者工具 README）", "支持所有核心扩展与组件（作者工具 README）", "发布为 SCORM 包或网页交付物供 LMS/网站交付（作者工具 README）", "评估题库、随机化、可定制反馈与步骤锁定等学习者交互组件由官方 Adapt Framework README 说明（框架层）"], "github_repository_id": 13562581, "homepage": "https://www.adaptlearning.org/", "id": "github:13562581", "leaf_matches": [{"reason": "作者工具 README 证明其创建、编辑并发布响应式 HTML5/SCORM 课程，且支持所有核心扩展与组件；其官方 Adapt Framework README 进一步列出评估题库、随机化、可定制反馈与步骤锁定等学习者交互能力，可对应课程项目、学习者交互与可发布交付物三项核心。", "slug": "elearning-authoring-tool", "source_urls": ["https://github.com/adaptlearning/adapt_authoring", "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/README.md", "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/LICENSE", "https://raw.githubusercontent.com/adaptlearning/adapt_framework/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/LICENSE", "license_review": {"rationale": "The fetched LICENSE text is the complete license and contains the standard markers for this SPDX identifier.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/LICENSE", "spdx_id": "GPL-3.0"}, "name": "Adapt Authoring Tool", "repository_url": "https://github.com/adaptlearning/adapt_authoring", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:07:28.510966+08:00", "kind": "repository_metadata", "sha256": "f21eca69ef7fe201a31f2f3607ffd8f49546a9d13e89450ebf009860599bd4a0", "snapshot_path": "sources/f21eca69ef7fe201a31f2f3607ffd8f49546a9d13e89450ebf009860599bd4a0.txt", "url": "https://github.com/adaptlearning/adapt_authoring"}, {"fetched_at": "2026-10-25T08:07:32.848190+08:00", "kind": "license", "sha256": "b98fbb37db5b23bc5cfdcd16793206a5a7120a7b01f75374e5e0888376e4691c", "snapshot_path": "sources/b98fbb37db5b23bc5cfdcd16793206a5a7120a7b01f75374e5e0888376e4691c.txt", "url": "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/LICENSE"}, {"fetched_at": "2026-10-25T08:09:00.256554+08:00", "kind": "readme", "sha256": "18f1240342e0e55b601a5537a5cf40bfd4fc11a6d8f07c92b1a5d186e428762a", "snapshot_path": "sources/18f1240342e0e55b601a5537a5cf40bfd4fc11a6d8f07c92b1a5d186e428762a.txt", "url": "https://raw.githubusercontent.com/adaptlearning/adapt_authoring/master/README.md"}, {"fetched_at": "2026-10-26T13:46:47.521634+08:00", "kind": "documentation", "sha256": "855d552d3f66476ca75a4a43185f508b0f9562694ed55a71a78d01174d7e0f18", "snapshot_path": "sources/855d552d3f66476ca75a4a43185f508b0f9562694ed55a71a78d01174d7e0f18.txt", "url": "https://raw.githubusercontent.com/adaptlearning/adapt_framework/master/README.md"}], "summary": "用于创作响应式 HTML5 电子学习课程并发布为 SCORM/网页交付物的开源创作工具。", "technology_stack": ["Node.js", "Backbone.js", "MongoDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:liveschool','LiveSchool','{"homepage": "https://whyliveschool.com/", "id": "commercial:liveschool", "leaf_matches": [{"reason": "官方行为追踪页面正文说明其提供全校期望矩阵、按行为类别与分值记录积分、可选负向行为是否扣分、评论、转介实时提醒以及学生与全校报告；页面同时说明可由 Clever/ClassLink 同步学生与班级名册，符合全校统一行为框架、行为事件记录、响应与历史审查的核心。", "slug": "student-behavior-management", "source_urls": ["https://whyliveschool.com/features/behavior-tracking"]}], "name": "LiveSchool", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:52:42.073921+08:00", "kind": "homepage", "sha256": "96fd823839e2adf3077b95c7de7c507bdf3b7fbecf86c254626899d67d49f1d0", "snapshot_path": "sources/96fd823839e2adf3077b95c7de7c507bdf3b7fbecf86c254626899d67d49f1d0.txt", "url": "https://whyliveschool.com/features/behavior-tracking"}], "summary": "面向 K-12 全校的行为管理与正向激励平台，支持自定义行为矩阵、积分与负向行为记录、转介提醒和报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:panorama-student-success','Panorama Student Success','{"homepage": "https://www.panoramaed.com/student-success", "id": "commercial:panorama-student-success", "leaf_matches": [{"reason": "官方产品页正文说明其汇总学生数据提供早期预警、把转介路由到支持团队、管理 Tiers 1-3 干预并监测干预响应与毕业进展，且以学区层面展示可衡量结果，覆盖学生成功平台的学生群体记录、主动信号、协调干预闭环与成果衡量四项核心。", "slug": "student-success-platform", "source_urls": ["https://www.panoramaed.com/student-success"]}], "name": "Panorama Student Success", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:53:02.119984+08:00", "kind": "homepage", "sha256": "a2aabc0978bf0bd449c1d227446e20d7a1feb9f3f78835cf8db286fa5abb6ad7", "snapshot_path": "sources/a2aabc0978bf0bd449c1d227446e20d7a1feb9f3f78835cf8db286fa5abb6ad7.txt", "url": "https://www.panoramaed.com/student-success"}], "summary": "面向学区与学校的学生成功平台，整合早期预警、干预管理、转介流程、分层支持与进展监测。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:684382','BigBlueButton','{"deployment": ["官方 README 说明可在 Ubuntu 24.04 上通过 bbb-install.sh 安装；本次未部署"], "features": ["实时共享音频、视频、幻灯片（含白板标注）、聊天与屏幕", "教师/主持人可用投票、表情、多用户白板、共享笔记与分组讨论组织课堂参与", "会话期间生成对主持人可见的学习分析，并支持录制与回放"], "github_repository_id": 684382, "homepage": "https://bigbluebutton.org/", "id": "github:684382", "leaf_matches": [{"reason": "官方 README 明确称其为开源虚拟教室，并说明支持实时共享音视频、幻灯片与白板标注，主持人可用投票、多用户白板、共享笔记和分组讨论组织课堂参与，另有学习分析仪表板与录制回放，符合实时教学会话、教师权威、共享教学界面和课堂式参与四项核心。", "slug": "virtual-classroom", "source_urls": ["https://github.com/bigbluebutton/bigbluebutton", "https://raw.githubusercontent.com/bigbluebutton/bigbluebutton/v4.0.x-develop/README.md", "https://api.github.com/repos/bigbluebutton/bigbluebutton/license"]}], "license": "LGPL-3.0", "license_evidence_url": "https://api.github.com/repos/bigbluebutton/bigbluebutton/license", "name": "BigBlueButton", "repository_url": "https://github.com/bigbluebutton/bigbluebutton", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:51:38.844441+08:00", "kind": "repository_metadata", "sha256": "fb1da54601a1027f098d3a43e9f6c0f9ab4c3693f7e7308a05a9282e57be4c1c", "snapshot_path": "sources/fb1da54601a1027f098d3a43e9f6c0f9ab4c3693f7e7308a05a9282e57be4c1c.txt", "url": "https://api.github.com/repos/bigbluebutton/bigbluebutton"}, {"fetched_at": "2026-10-26T13:53:23.665606+08:00", "kind": "license", "sha256": "1843d7741576a5e8a284ff657a54b9911d9d184581af7fd743d1068e98246c43", "snapshot_path": "sources/1843d7741576a5e8a284ff657a54b9911d9d184581af7fd743d1068e98246c43.txt", "url": "https://api.github.com/repos/bigbluebutton/bigbluebutton/license"}, {"fetched_at": "2026-10-26T13:51:47.082251+08:00", "kind": "readme", "sha256": "10327605faf3fbd8d39b03c0e23d37415ddec5cbb6bb9715abb2c71f9427fb6b", "snapshot_path": "sources/10327605faf3fbd8d39b03c0e23d37415ddec5cbb6bb9715abb2c71f9427fb6b.txt", "url": "https://raw.githubusercontent.com/bigbluebutton/bigbluebutton/v4.0.x-develop/README.md"}, {"fetch