INSERT INTO "application" VALUES('github:867017055','Free-Turnitin Plagiarism Checker','{"deployment": ["仓库含 client/server、Dockerfile 与 docker-compose；README 未给出部署步骤；本次未部署"], "features": ["上传 txt/doc/docx/pdf 并与公开网页文本比对", "相似度分析与匹配高亮", "PDF 报告生成与引用排除", "语料范围仅公开网页，不含论文/IEEE 数据库或历史提交库"], "github_repository_id": 867017055, "homepage": "https://github.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker", "id": "github:867017055", "leaf_matches": [{"reason": "README 说明上传文档、与公开网页文本比对、按相似度展示匹配并生成 PDF 报告，覆盖提交—比对—报告核心；语料仅公开网页，未证明论文库或历史提交库。", "slug": "academic-integrity-plagiarism-platform", "source_urls": ["https://github.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker", "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/README.md", "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/LICENSE"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/LICENSE", "license_review": {"rationale": "The fetched LICENSE text is the complete Apache License 2.0 text and contains the standard markers for this SPDX identifier.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Free-Turnitin Plagiarism Checker", "repository_url": "https://github.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:57:11.463902+08:00", "kind": "repository_metadata", "sha256": "7caee3ce1186f8ad17304bbae03863278a4b3be761f8edeb41c4117ad8af5f71", "snapshot_path": "sources/7caee3ce1186f8ad17304bbae03863278a4b3be761f8edeb41c4117ad8af5f71.txt", "url": "https://github.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker"}, {"fetched_at": "2026-10-26T13:57:12.928101+08:00", "kind": "license", "sha256": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4", "snapshot_path": "sources/c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4.txt", "url": "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/LICENSE"}, {"fetched_at": "2026-10-26T13:57:14.174611+08:00", "kind": "readme", "sha256": "0be840d87b77ce5d41b48fb86747245aede21699e6e49693f7269b5f5832cb87", "snapshot_path": "sources/0be840d87b77ce5d41b48fb86747245aede21699e6e49693f7269b5f5832cb87.txt", "url": "https://raw.githubusercontent.com/cu-sanjay/Free-Turnitin-Plagiarism-Checker/main/README.md"}], "summary": "用于上传文档、仅与公开网页文本比对并生成相似度报告的开源查重 Web 应用；不覆盖论文库或历史提交库。", "technology_stack": ["Node.js", "React", "Vite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:9455072','TCExam','{"deployment": ["官方 README 为 PHP LAMP 应用，支持 Docker；本次未部署"], "features": ["题库、试卷与考试创作，支持随机组卷与 OMR 纸笔考试", "按用户组、IP 范围与考试密码控制考生准入，tce_tests_users 绑定考生与考试", "服务器保存并强制执行考试时长，到时自动关闭，记录 IP、答题与反应时间，可锁定/解锁/延长", "客观题自动评分，主观题通过 Answer Evaluation 人工评分并写评语", "成绩统计、结果管理与受控发布（面向考生展示、邮件、PDF/XML/TSV 导出）"], "github_repository_id": 9455072, "homepage": "https://tcexam.org/", "id": "github:9455072", "leaf_matches": [{"reason": "README、仓库描述与官方评分/数据库文档证明可创作、排期、分发并报告考试、测验与调查，含自动评分、成绩统计、随机组卷与 OMR；tce_tests_users/tce_tests_logs 持久保存考生尝试与逐题得分，覆盖评估平台的题目—测评—交付—评分—统计循环。", "slug": "assessment-platform", "source_urls": ["https://github.com/tecnickcom/tcexam", "https://raw.githubusercontent.com/tecnickcom/tcexam/main/README.md", "https://raw.githubusercontent.com/tecnickcom/tcexam/main/LICENSE", "https://tcexam.org/docs/scoring/", "https://tcexam.org/docs/database_docs/"]}, {"reason": "官方安全、数据库、评分、首次考试与源码文档证明：考试按用户组、IP 范围与考试密码准入，tce_tests_users 将考生绑定到考试；服务器保存并强制执行考试时长，到时自动关闭，tce_tests_logs 记录 IP、答题时间与反应时间，管理员可锁定、解锁、延长或终止考试；客观题自动评分，主观题经 Answer Evaluation 人工评分（独立 K_AUTH_ADMIN_RATING 评分编辑器），结果通过 test_results_to_users/test_report_to_users 控制向考生发布，并可按用户/全员导出 PDF/XML/TSV 或邮件发送。已覆盖名册准入、服务器强制场次与受控评分/结果发布。", "slug": "examination-platform", "source_urls": ["https://github.com/tecnickcom/tcexam", "https://raw.githubusercontent.com/tecnickcom/tcexam/main/README.md", "https://raw.githubusercontent.com/tecnickcom/tcexam/main/LICENSE", "https://tcexam.org/docs/security/", "https://tcexam.org/docs/database_docs/", "https://tcexam.org/docs/scoring/", "https://tcexam.org/docs/first_test/", "https://tcexam.org/docs/srcdoc/tcexam/files-shared-code-tce-functions-test/", "https://raw.githubusercontent.com/tecnickcom/tcexam/main/admin/code/tce_edit_rating.php"]}], "license": "AGPL-3.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/tecnickcom/tcexam/main/LICENSE", "license_review": {"rationale": "The fetched LICENSE text is the complete GN