INSERT INTO "application" VALUES('commercial:tyler-enterprise-jury-manager','Tyler Enterprise Jury Manager','{"homepage": "https://www.tylertech.com/solutions/courts-public-safety/courts-justice/jury-management", "id": "commercial:tyler-enterprise-jury-manager", "leaf_matches": [{"reason": "官方产品页正文说明其面向法院书记官和法院管理者管理陪审流程，并提到陪审员历史与延期请求处理，匹配陪审团管理类型；正文未展开随机抽选、资格裁决和陪审小组组建。", "slug": "jury-management-system", "source_urls": ["https://www.tylertech.com/solutions/courts-public-safety/courts-justice/jury-management"]}], "name": "Tyler Enterprise Jury Manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:23:17.391859+08:00", "kind": "homepage", "sha256": "3c90bdfe51815ac98e8e7f44540cf116118cddd90ef34443ada8bd483f663c79", "snapshot_path": "sources/3c90bdfe51815ac98e8e7f44540cf116118cddd90ef34443ada8bd483f663c79.txt", "url": "https://www.tylertech.com/solutions/courts-public-safety/courts-justice/jury-management"}], "summary": "面向法院的陪审团管理商业软件，官方产品页称覆盖陪审流程、陪审员历史与延期请求处理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:case-closed','Case Closed Software','{"homepage": "https://caseclosedsoftware.com/", "id": "commercial:case-closed", "leaf_matches": [{"reason": "官方正文将产品定位为执法案件管理，说明从接报到庭审的案件生命周期、证据/情报、任务与角色共享；未展开实体网络和主管审查细节。", "slug": "law-enforcement-case-management", "source_urls": ["https://caseclosedsoftware.com/"]}], "name": "Case Closed Software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:22:59.251236+08:00", "kind": "homepage", "sha256": "5449e5744b96ce9c5748b11916dcc7841075a021d6df8ed217df8404b76de4da", "snapshot_path": "sources/5449e5744b96ce9c5748b11916dcc7841075a021d6df8ed217df8404b76de4da.txt", "url": "https://caseclosedsoftware.com/"}], "summary": "面向执法与调查机构的案件管理商业软件，官方页面称覆盖从接报到庭审的案件跟踪、证据、情报与协作。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:eprosecutor','eProsecutor','{"homepage": "https://www.journaltech.com/eprosecutor", "id": "commercial:eprosecutor", "leaf_matches": [{"reason": "官方正文明确该产品专为检察官构建，覆盖执法转介审查、指控的接受/修正/追加/驳回、指控历史与指控文件、案件参与冲突检查、证据开示及法庭排期，匹配检察官案件管理核心。", "slug": "prosecutor-case-management", "source_urls": ["https://www.journaltech.com/eprosecutor"]}], "name": "eProsecutor", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:23:16.996906+08:00", "kind": "homepage", "sha256": "a662cb0cf1e62ad09fb78aad8dab98098eb24fa4b80691a45d891e1c6de6f6c5", "snapshot_path": "sources/a662cb0cf1e62ad09fb78aad8dab98098eb24fa4b80691a45d891e1c6de6f6c5.txt", "url": "https://www.journaltech.com/eprosecutor"}], "summary": "面向检察官办公室的案件管理商业软件，官方页面称覆盖执法转介审查、指控决定、指控文件、案件冲突检查、证据开示和法庭流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:legalserver','LegalServer','{"homepage": "https://www.legalserver.org/", "id": "commercial:legalserver", "leaf_matches": [{"reason": "官方正文明确面向公设辩护人的案件与文档管理，列出实时案件量跟踪、按案件类型的工作量基准、案件分配/外部律师协作、工作流和结果报告，匹配辩护案件与案件量管理核心；未展开法院案号与冲突检查细节。", "slug": "public-defender-case-management", "source_urls": ["https://www.legalserver.org/public-defender/"]}], "name": "LegalServer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:22:53.528653+08:00", "kind": "homepage", "sha256": "9050d99d5e4bed22ad22ad92c4f7dcf7344f17b75cabcfce206f128b5590730f", "snapshot_path": "sources/9050d99d5e4bed22ad22ad92c4f7dcf7344f17b75cabcfce206f128b5590730f.txt", "url": "https://www.legalserver.org/public-defender/"}], "summary": "面向公设辩护人和法律援助机构的案件与文档管理商业软件，官方页面称支持案件量跟踪、案件分配/外部律师协作、工作流与报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:146009627','ArkCase','{"deployment": ["本地部署", "混合部署", "云部署"], "features": ["案件、文档与记录的统一 360° 视图", "可配置的审批、任务与工作流自动化", "队列与通信、文档管理", "元数据与全文检索、报表与分析", "FOIA、投诉、事件、法律案件等预置解决方案", "REST 接口及日历、LDAP、邮件、ECM/CRM 集成"], "github_repository_id": 146009627, "homepage": "https://www.arkcase.com/", "id": "github:146009627", "leaf_matches": [{"reason": "官方开源版页面将 ArkCase 定义为面向政府等组织的案件管理平台，法务案件页正文列出案件/文档/记录 360° 视图、任务与审批工作流、人员与备注、检索报表，匹配公共部门案件管理核心；未单独验证个案工作者案件量/分配视图。", "slug": "public-sector-case-management", "source_urls": ["https://www.arkcase.com/product/arkcase-open-source-case-management-platform/", "https://www.arkcase.com/legal-case-management/"]}], "license": "LGPL-3.0", "license_evidence_url": "https://api.github.com/repos/ArkCase/ArkCase/license", "name": "ArkCase", "repository_url": "https://github.com/ArkCase/ArkCase", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:22:35.894242+08:00", "kind": "repository_metadata", "sha256": "5a4abd2eaeab42aebf86c8618bac46d4e78c40989d0ec411e6a8457636611b98", "snapshot_path": "sources/5a4abd2eaeab42aebf86c8618bac46d4e78c40989d0ec411e6a8457636611b98.txt", "url": "https://api.github.com/repos/ArkCase/ArkCase"}, {"fetched_at": "2026-10-26T14:22:45.354289+08:00", "kind": "readme", "sha256": "9d4d0e5449f5a0e8c566806c83eaa9a9757e97f09359fca04f006ff43e4485a1", "snapshot_path": "sources/9d4d0e5449f5a0e8c566806c83eaa9a9757e97f09359fca04f006ff43e4485a1.txt", "url": "https://api.github.com/repos/ArkCase/ArkCase/readme"}, {"fetched_at": "2026-10-26T14:22:46.877889+08:00", "kind": "license", "sha256": "ac3f89419a00a39108047e860b1beca89b67d94f101bd958b2a828dc74aae5c0", "snapshot_path": "sources/ac3f89419a00a39108047e860b1beca89b67d94f101bd958b2a828dc74aae5c0.txt", "url": "https://api.github.com/repos/ArkCase/ArkCase/license"}, {"fetched_at": "2026-10-26T14:23:18.063970+08:00", "kind": "homepage", "sha256": "ea5062de9f9ea2730d6dea8f265e128eab54e874ac2be6989a298f6e2a0018f1", "snapshot_path": "sources/ea5062de9f9ea2730d6dea8f265e128eab54e874ac2be6989a298f6e2a0018f1.txt", "url": "https://www.arkcase.com/"}, {"fetched_at": "2026-10-26T14:24:16.031234+08:00", "kind": "documentation", "sha256": "d498a49d08ea278412e6502c6bef9d5422b63f7e7dedfd77fb4608bd2b8fa6d0", "snapshot_path": "sources/d498a49d08ea278412e6502c6bef9d5422b63f7e7dedfd77fb4608bd2b8fa6d0.txt", "url": "https://www.arkcase.com/product/arkcase-open-source-case-management-platform/"}, {"fetched_at": "2026-10-26T14:24:18.620266+08:00", "kind": "documentation", "sha256": "886d5a4480ad383c9c46d9d2d94af92ce9633e576d1b1cafd8b935c85d33817b", "snapshot_path": "sources/886d5a4480ad383c9c46d9d2d94af92ce9633e576d1b1cafd8b935c85d33817b.txt", "url": "https://www.arkcase.com/legal-case-management/"}], "summary": "ArkCase 社区版是面向政府与公共部门案件管理的开源平台，提供案件与文档 360° 视图、可配置任务/审批工作流、队列、检索报表与集成能力；企业版另提供扩展支持与高可用等商业能力。", "technology_stack": ["Java", "Apache Tomcat", "MySQL", "Apache Solr", "ActiveMQ", "Alfresco", "Pentaho"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:549936212','Frappe Changemakers','{"deployment": ["自托管（Frappe bench）", "Web 应用", "PWA/移动端（Alpha）"], "features": ["受益人登记与档案", "案件/需求登记与分派", "食品分发等服务记录", "收容入住与退出记录", "服务机构与收容点主数据"], "github_repository_id": 549936212, "homepage": "https://frappe.io/products/changemakers", "id": "github:549936212", "leaf_matches": [{"reason": "官方 README 说明系统以 Beneficiary 为中心，记录案件（Food、Shelter 等需求）、Food Distribution Record、Shelter Home Admission/Exit 等服务交付，支撑受益人登记、服务关联、援助事件与入住/退出状态。", "slug": "beneficiary-management", "source_urls": ["https://raw.githubusercontent.com/frappe/changemakers/develop/README.md", "https://api.github.com/repos/frappe/changemakers"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/frappe/changemakers/license", "name": "Frappe Changemakers", "repository_url": "https://github.com/frappe/changemakers", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:37:07.602089+08:00", "kind": "repository_metadata", "sha256": "30e6bb35e33e74452b2597a3d9f5734dba364baee7832d47be89b9cc68c3c79a", "snapshot_path": "sources/30e6bb35e33e74452b2597a3d9f5734dba364baee7832d47be89b9cc68c3c79a.txt", "url": "https://api.github.com/repos/frappe/changemakers"}, {"fetched_at": "2026-10-26T14:36:32.600568+08:00", "kind": "readme", "sha256": "262f03238c7228b54408d9240156daa7d4874bd5b7e194f02b5b9d625157d7c8", "snapshot_path": "sources/262f03238c7228b54408d9240156daa7d4874bd5b7e194f02b5b9d625157d7c8.txt", "url": "https://raw.githubusercontent.com/frappe/changemakers/develop/README.md"}, {"fetched_at": "2026-10-26T14:36:33.032303+08:00", "kind": "license", "sha256": "5d937e740d806575ccab6b46e7c7577ecf3e48eae5d56c10eb79875f0f347884", "snapshot_path": "sources/5d937e740d806575ccab6b46e7c7577ecf3e48eae5d56c10eb79875f0f347884.txt", "url": "https://api.github.com/repos/frappe/changemakers/license"}], "summary": "开源受益人管理平台，面向非营利与社会服务机构，以受益人为中心记录案件、服务交付以及收容入住/退出，可自托管。", "technology_stack": ["Frappe Framework", "Vue.js", "Ionic"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:30856851','ChurchCRM','{"deployment": ["自托管", "Web 应用"], "features": ["人员与家庭管理", "小组管理", "活动与出席", "按家庭记录奉献（日期/金额/基金/方式）", "捐赠基金管理与年度奉献报告", "志愿者管理"], "github_repository_id": 30856851, "homepage": "https://churchcrm.io/", "id": "github:30856851", "leaf_matches": [{"reason": "官方 Finances 文档说明按家庭（捐赠者）记录 Payment 的日期、金额、基金与支付方式，并提供 Donation Funds 管理、捐款批次与 Tax Statement；官方 README 亦列出 Giving & financial tracking，足以支撑奉献记录、捐赠者归属、基金指定与教会端管理。", "slug": "church-giving-platform", "source_urls": ["https://raw.githubusercontent.com/ChurchCRM/docs.churchcrm.io/main/docs/user-guide/finances.md", "https://raw.githubusercontent.com/ChurchCRM/CRM/master/README.md", "https://api.github.com/repos/ChurchCRM/CRM"]}, {"reason": "Official README and homepage document people and family records, groups, events, attendance, giving, volunteers and reports as one self-hosted church management system; the repository is MIT-licensed with no premium split indicated.", "slug": "church-management-system-chms", "source_urls": ["https://api.github.com/repos/ChurchCRM/CRM", "https://raw.githubusercontent.com/ChurchCRM/CRM/master/README.md", "https://churchcrm.io/"]}, {"reason": "Official homepage documents individual member records and profiles, with people and families as the foundation and group roles/membership assignment; this is the membership record core inside a full ChMS.", "slug": "congregation-membership-management", "source_urls": ["https://churchcrm.io/", "https://raw.githubusercontent.com/ChurchCRM/CRM/master/README.md"]}, {"reason": "官方文档把 ministry/team/position、排期与 occurrence、岗位分配状态以及替换提案与审批作为完整志愿者排班流程描述，覆盖岗位、日期场合、人员分配和响应/替换闭环。", "slug": "ministry-scheduling", "source_urls": ["https://docs.churchcrm.io/user-guide/ministries/ministries-teams-positions", "https://docs.churchcrm.io/user-guide/ministries/staffing-an-occurrence", "https://docs.churchcrm.io/user-guide/ministries/substitutions"]}], "license": "MIT", "license_evidence_url": "https://api.gith