INSERT INTO "application" VALUES('github:557508553','Navari Grants Management','{"deployment": ["自托管（ERPNext/Frappe bench）"], "features": ["资助计划与征集", "申请记录与参数模板", "评审分配与评分", "申请状态决策", "资助项目与预算", "拨款支付登记", "项目进展报告", "结项与状态管理", "分析报表", "仪表板"], "github_repository_id": 557508553, "homepage": "https://github.com/navariltd/navari_gms", "id": "github:557508553", "leaf_matches": [{"reason": "develop 分支代码提供可核对的 doctype 记录：Grant Programme 与 Grant Call 记录计划、征集类型、开放/截止日期、申请参数模板、报告频率和网站发布，Grant Call Template 另定义模板类型、评审数量与评分区间，对应计划规则与周期；Grant Call 页面在开放期提供 Apply Now 入口指向 Grant Application，Grant Review Assignment/Grant Application Review 记录评审分配、评分与意见（评审表单按申请明细生成评分项、合计并校验评分不超过上限），Grant Application 的 Approved/Rejected 状态（ERPNext 核心同名 doctype，应用 README 指定基于 ERPNext）记录选择决策；Grant Project 关联申请与征集，记录受助机构、预算、起止日期、状态与进度收集，Grant Project Disbursement/Grant Disbursement Entry 记录拨款日期与金额，Grant Project Report 记录项目活动、报告项和预算更新，Grant Project 的 Completed/Expired 状态与 README 的 closeout 说明对应结项；README 另说明分析报表与仪表板。", "slug": "grantmaking-platform", "source_urls": ["https://raw.githubusercontent.com/navariltd/navari_gms/develop/README.md", "https://api.github.com/repos/navariltd/navari_gms/git/trees/develop?recursive=1", "https://raw.githubusercontent.com/navariltd/navari_gms/develop/grants_management_system/grants_management_system/doctype/grant_programme/grant_programme.json", "https://raw.githubusercontent.com/navariltd/navari_gms/develop/grants_management_system/grants_management_system/doctype/grant_call/grant_call.json", "https://raw.githubusercontent.com/navariltd/navari_gms/develop/grants_management_system/grants_management_system/doctype/grant_call_template/grant_call_template.json", "https://raw.githubusercontent.com/navariltd/navari_gms/develop/grants_management_system/templates/generators/grant_call.html", "https://raw.githubusercontent.com/navariltd/navari_gms/develop/grants_management_system/grants_management_system/doctype/grant_review_assignment/grant_review_assignment.json", "https://raw.