INSERT INTO "application" VALUES('github:641978792','MONIC','{"deployment": ["自托管", "Azure 托管"], "features": ["变革理论", "逻辑框架", "指标管理", "数据采集", "自动聚合", "问卷调查", "文档库", "活动计划", "细粒度权限", "PDF/Excel 报告"], "github_repository_id": 641978792, "homepage": "https://www.monic.tech/", "id": "github:641978792", "leaf_matches": [{"reason": "官方项目页说明以变革理论/逻辑框架组织活动、产出、成果与目标并关联指标，监测组件按时间和实体层级采集数据、自动聚合并计算复合指标；仓库包含指标图表及 PDF/Excel 报告模块。", "slug": "monitoring-evaluation-platform", "source_urls": ["https://www.monic.tech/", "https://raw.githubusercontent.com/capesean/MONIC/master/README.md", "https://api.github.com/repos/capesean/MONIC/git/trees/master?recursive=1", "https://raw.githubusercontent.com/capesean/MONIC/master/WEB/Code/Reports/PDFReports.cs"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/capesean/MONIC/license", "name": "MONIC", "repository_url": "https://github.com/capesean/MONIC", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:38:11.542107+08:00", "kind": "repository_metadata", "sha256": "5f4d6227879ea7d1817bca7503004fd9e4158fe87293bcebce416f924d6e6560", "snapshot_path": "sources/5f4d6227879ea7d1817bca7503004fd9e4158fe87293bcebce416f924d6e6560.txt", "url": "https://api.github.com/repos/capesean/MONIC"}, {"fetched_at": "2026-10-26T14:38:13.349467+08:00", "kind": "readme", "sha256": "5b39e6427cbdc806f4491d17a843647c649d2ba40aa53faabb4e7fcaa54df0e1", "snapshot_path": "sources/5b39e6427cbdc806f4491d17a843647c649d2ba40aa53faabb4e7fcaa54df0e1.txt", "url": "https://raw.githubusercontent.com/capesean/MONIC/master/README.md"}, {"fetched_at": "2026-10-26T14:38:16.559641+08:00", "kind": "license", "sha256": "e3819c6fad786882535c4a7efaca5bd7947db35bfb4840e6b152ffe29be68ec2", "snapshot_path": "sources/e3819c6fad786882535c4a7efaca5bd7947db35bfb4840e6b152ffe29be68ec2.txt", "url": "https://api.github.com/repos/capesean/MONIC/license"}, {"fetched_at": "2026-10-26T14:38:19.638267+08:00", "kind": "homepage", "sha256": "92575d8332a0b63c6c6edbda113f63d74ee93eb8bc0842ed885d49db77942ae1", "snapshot_path": "sources/92575d8332a0b63c6c6edbda113f63d74ee93eb8bc0842ed885d49db77942ae1.txt", "url": "https://www.monic.tech/"}, {"fetched_at": "2026-10-26T14:40:04.134031+08:00", "kind": "documentation", "sha256": "3acd0836385d4ad54a0800c2bcf654b676b7e7ee04aca89e0e7fd28b2087559f", "snapshot_path": "sources/3acd0836385d4ad54a0800c2bcf654b676b7e7ee04aca89e0e7fd28b2087559f.txt", "url": "https://api.github.com/repos/capesean/MONIC/git/trees/master?recursive=1"}, {"fetched_at": "2026-10-26T14:40:31.092230+08:00", "kind": "documentation", "sha256": "e21ff062bb68ec515799a923f1bcee4329757da3af28e5e3d3f85ec3cd617b57", "snapshot_path": "sources/e21ff062bb68ec515799a923f1bcee4329757da3af28e5e3d3f85ec3cd617b57.txt", "url": "https://raw.githubusercontent.com/capesean/MONIC/master/WEB/Code/Reports/PDFReports.cs"}], "summary": "开源监测与评估系统，提供变革理论/逻辑框架、指标与数据采集、按时间和实体层级自动聚合，以及 PDF/Excel 报告与指标图表；项目仍在开发中，需要自托管 .NET/SQL Server 环境。", "technology_stack": ["ASP.NET Core", ".NET", "Angular", "SQL Server"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1241862435','GivStack','{"deployment": ["自托管", "Docker"], "features": ["公开活动页与进度条", "捐赠者墙与倒计时", "捐赠录入与支付回调", "活动更新与大使分享链接", "管理后台与 CSV 导出"], "github_repository_id": 1241862435, "homepage": "https://github.com/gabihorn/givstack", "id": "github:1241862435", "leaf_matches": [{"reason": "官方仓库描述与 README 明确其为面向社区、会堂与非营利组织的开源自托管众筹平台；活动页含进度条、捐赠者墙与倒计时，支持捐赠录入、Nedarim Plus 机构账户支付回调和管理后台，支撑公开活动容器、按捐赠者捕获捐赠与公开进展核心。项目创建于 2026-05、当前为单活动部署，成熟度不作更强断言。", "slug": "nonprofit-crowdfunding-platform", "source_urls": ["https://api.github.com/repos/gabihorn/givstack", "https://raw.githubusercontent.com/gabihorn/givstack/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/gabihorn/givstack/license", "name": "GivStack", "repository_url": "https://github.com/gabihorn/givstack", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:58:43.256612+08:00", "kind": "repository_metadata", "sha256": "349476201fd42182ccdbd0c7d851dcddd4ee6a07a9153c878f885b537d0ec93a", "snapshot_path": "sources/349476201fd42182ccdbd0c7d851dcddd4ee6a07a9153c878f885b537d0ec93a.txt", "url": "https://api.github.com/repos/gabihorn/givstack"}, {"fetched_at": "2026-10-26T14:58:46.869613+08:00", "kind": "readme", "sha256": "c0c5a22889258d3719914a97e56eaccef720218c5037e209b5faa142e1b83701", "snapshot_path": "sources/c0c5a22889258d3719914a97e56eaccef720218c5037e209b5faa142e1b83701.txt", "url": "https://raw.githubusercontent.com/gabihorn/givstack/main/README.md"}, {"fetched_at": "2026-10-26T14:58:48.904390+08:00", "kind": "license", "sha256": "648919e1728224fb9055e9e2d27ba23f38f801ec1debe185effc889da360492a", "snapshot_path": "sources/648919e1728224fb9055e9e2d27ba23f38f801ec1debe185effc889da360492a.txt", "url": "https://api.github.com/repos/gabihorn/givstack/license"}], "summary": "开源自托管众筹平台，面向社区、会堂与非营利组织；活动页提供进度条、捐赠者墙与倒计时，支持捐赠录入、Nedarim Plus 机构账户支付回调和活动更新。项目创建于 2026-05，当前为单活动部署，成熟度有限。", "technology_stack": ["Node.js", "Express", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wildapricot','WildApricot','{"homepage": "https://www.wildapricot.com", "id": "commercial:wildapricot", "leaf_matches": [{"reason": "Official WildApricot homepage describes a membership database with automated renewals and recurring payments for associations, clubs and chapters.", "slug": "association-management-system-ams", "source_urls": ["https://www.wildapricot.com"]}, {"reason": "Official WildApricot event page states membership-level event visibility, members-only tickets, member pricing, registration limits/waitlists and attendance tracking integrated with the member database.", "slug": "association-event-management", "source_urls": ["https://www.wildapricot.com/features/online-event-registration-software"]}, {"reason": "Official WildApricot add-ons page describes a Job Board for associations with job posters, member single sign-on, filterable posts and non-dues revenue.", "slug": "association-job-board", "source_urls": ["https://www.wildapricot.com/add-ons"]}, {"reason": "Official chapters page describes a centralized platform for multi-chapter organizations, overseeing memberships, events and communications across all chapters, with a centralized dashboard and financial/membership reporting.", "slug": "chapter-management-platform", "source_urls": ["https://www.wildapricot.com/who-we-serve/chapters"]}, {"reason": "Official add-ons page describes CommUnity as a dedicated online space for members with discussion boards, forums, special interest groups and member-to-member messaging.", "slug": "member-community-platform", "source_urls": ["https://www.wildapricot.com/add-ons"]}, {"reason": "Official membership-management page describes searchable, customizable member directories showing member profiles and contact information, with public or members-only visibility controls.", "slug": "member-directory", "source_urls": ["https://www.wildapricot.com/features/membership-management-software"]}, {"reason": "Official membership-management page describes a branded member portal, members-only spaces, self-service profile updates, automated renewals/invoicing and online payments.", "slug": "member-portal", "source_urls": ["https://www.wildapricot.com/features/membership-management-software"]}, {"reason": "Official WildApricot homepage body describes automating membership renewals and recurring payments, invoicing and tracking payments, and a member database with applications, so the member-dues-payment loop is documented as a core use.", "slug": "membership-billing", "source_urls": ["https://www.wildapricot.com"]}, {"reason": "Official WildApricot homepage body describes a centralized member database, membership applications, member directory, automated membership renewals and recurring payments for associations, clubs and nonprofits.", "slug": "membership-management-system", "source_urls": ["https://www.wildapricot.com"]}], "name": "WildApricot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:37:58.234541+08:00", "kind": "homepage", "sha256": "e69520b50e207bca7f45388ebcc4ce69950479265967d5a2658caf9cfbcc68de", "snapshot_path": "sources/e69520b50e207bca7f45388ebcc4ce69950479265967d5a2658caf9cfbcc68de.txt", "url": "https://www.wildapricot.com"}, {"fetched_at": "2026-10-26T14:45:51.931791+08:00", "kind": "documentation", "sha256": "9ad62146f58062d14158f34c7f9136d6112b495d1f55427b15cd43f93977eba4", "snapshot_path": "sources/9ad62146f58062d14158f34c7f9136d6112b495d1f55427b15cd43f93977eba4.txt", "url": "https://www.wildapricot.com/features/online-event-registration-software"}, {"fetched_at": "2026-10-26T14:45:51.959025+08:00", "kind": "homepage", "sha256": "a9714b4846714efe45ec02c89ce035ec6de70bc2891a15261853d007416c897d", "snapshot_path": "sources/a9714b4846714efe45ec02c89ce035ec6de70bc2891a15261853d007416c897d.txt", "url": "https://www.wildapricot.com/add-ons"}, {"fetched_at": "2026-10-26T14:55:17.263184+08:00", "kind": "documentation", "sha256": "82a105aca99e4790f50b95efe703a257a0b99e319c5b1235509e2d57dc4c1869", "snapshot_path": "sources/82a105aca99e4790f50b95efe703a257a0b99e319c5b1235509e2d57dc4c1869.txt", "url": "https://www.wildapricot.com/who-we-serve/chapters"}, {"fetched_at": "2026-10-26T14:56:42.998683+08:00", "kind": "documentation", "sha256": "95d6b73bece938f2373538fde6dc628d47c823674947f5aaa04388aa7147d90c", "snapshot_path": "sources/95d6b73bece938f2373538fde6dc628d47c823674947f5aaa04388aa7147d90c.txt", "url": "https://www.wildapricot.com/add-ons"}, {"fetched_at": "2026-10-26T14:55:18.304810+08:00", "kind": "documentation", "sha256": "fcaa04684b7c9ad015c62e64d412e1aab44bf89764457605b5b7e88beb7748bf", "snapshot_path": "sources/fcaa04684b7c9ad015c62e64d412e1aab44bf89764457605b5b7e88beb7748bf.txt", "url": "https://www.wildapricot.com/features/membership-management-software"}], "summary": "Cloud membership management software for associations, clubs, nonprofits and chapters, covering member database, website builder, payments, event management, communications, mobile app, job board and community add-ons.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:8495499','CiviCRM','{"deployment": ["Self-hosted PHP application", "Integrates with WordPress/Drupal/Joomla/Backdrop"], "features": ["Contact management", "Membership management", "Event registration", "Contributions and fundraising", "Email marketing", "Case management", "Reporting"], "github_repository_id": 8495499, "homepage": "https://civicrm.org", "id": "github:8495499", "leaf_matches": [{"reason": "Official CiviCRM homepage describes constituent/donor and membership management for nonprofits; the CiviMember guide documents membership types and pricing, online join/renewal, automated renewal reminders and member-only website privileges, matching a staff-side membership system of record.", "slug": "association-management-system-ams", "source_urls": ["https://civicrm.org", "https://docs.civicrm.org/user/en/latest/membership/what-is-civimember/"]}, {"reason": "CiviCRM 官方社区文档（docs.civicrm.org）说明联系人记录涵盖个人/组织/家庭并作为贡献等数据的中心；联系人页的 Contributions 标签按联系人汇总捐赠总额、笔数与平均值；CiviContribute 组件记录并报告捐赠，场景中成功支付后发送感谢邮件与收据。产品整体为非营利 CRM，本条仅取联系人记录与捐赠管理子模块。", "slug": "donor-management-system", "source_urls": ["https://docs.civicrm.org/user/en/latest/organising-your-data/contacts/", "https://docs.civicrm.org/user/en/latest/contributions/what-is-civicontribute/", "https://raw.githubusercontent.com/civicrm/civicrm-core/master/README.md"]}, {"reason": "社区用户指南正文显示：捐献页可关联 Campaign、设置目标金额与起止日期、配置支付处理器并出具收据；CiviCampaign 把事件、邮件与捐献归入同一筹款计划并设定/跟踪收入目标；个人筹款页支持支持者自建页面并由 CiviReport 汇总；报表可按 campaign 筛选。社区许可页与 GitHub 许可快照证明 AGPL-3.0，README 证明其为自托管完整 Web 应用。拍卖/抽奖等机制未由本条来源证明，不在本条主张。", "slug": "fundraising-management-platform", "source_urls": ["https://docs.civicrm.org/user/en/latest/contributions/contribution-pages/", "https://docs.civicrm.org/user/en/latest/contributions/personal-campaign-pages/", "https://docs.civicrm.org/user/en/latest/campaign/what-is-civicampaign/", "https://docs.civicrm.org/user/en/latest/campaign/reports-and-analysis/", "https://civicrm.org/licensing", "https://raw.githubusercontent.com/civicrm/civicrm-core/master/README.md"]}, {"reason": "Official CiviCRM user guide documents membership types with duration, membership status rules tied to join/start/end dates, automatic status updates, auto-renew through the payment processor, scheduled renewal reminders, online renewals and linked payment records.", "slug": "membership-management-system", "source_urls": ["https://api.github.com/repos/civicrm/civicrm-core", "https://civicrm.org", "https://docs.civicrm.org/user/en/latest/membership/defining-memberships/", "https://docs.civicrm.org/user/en/latest/membership/renewals/"]}, {"reason": "CiviCRM 社区官方用户指南的 CiviCase 章节说明：可在联系人记录（含新联系人）上开立个案，为个案配置类型与角色并分配给工作人员，以带日期和归属的活动记录接触、附件与邮件，通过 Ongoing/Resolved 等状态变更记录个案进展与结案，并提供个案仪表盘、搜索和审计报告；官方仓库 README 与 AGPL-3.0 许可证确认其为可自托管的开源 PHP Web 应用。", "slug": "nonprofit-case-management", "source_urls": ["https://docs.civicrm.org/user/en/latest/case-management/what-is-civicase/", "https://docs.civicrm.org/user/en/latest/case-management/everyday-tasks/", "https://raw.githubusercontent.com/civicrm/civicrm-core/master/README.md"]}, {"reason": "官方社区文档说明 CiviCRM 是面向非营利组织/NGO 的 Web CRM：联系人记录是基本构建块，并累积关系、活动、捐献、会员与邮件等标签页历史；CiviContribute、CiviMember 与 CiviMail 正文分别支撑捐献记录/致谢收据、会员生命周期及带退订抑制的细分邮件沟通。项目 README 与安装要求证明其为 AGPL-3.0 开源独立 PHP Web 应用/CMS 模块，仓库元数据与许可证绑定同一 civicrm/civicrm-core 身份。", "slug": "nonprofit-crm", "source_urls": ["https://api.github.com/repos/civicrm/civicrm-core", "https://api.github.com/repos/civicrm/civicrm-core/license", "https://civicrm.org/", "https://civicrm.org/about/license", "https://docs.civicrm.org/user/en/latest/introduction/what-is-civicrm/", "https://docs.civicrm.org/user/en/latest/organising-your-data/contacts/", "https://docs.civicrm.org/user/en/latest/contributions/what-is-civicontribute/", "https://docs.civicrm.org/user/en/latest/membership/what-is-civimember/", "https://docs.civicrm.org/user/en/latest/email/what-is-civimail/", "https://docs.civicrm.org/installation/en/latest/requirements/", "https://raw.githubusercontent.com/civicrm/civicrm-core/master/README.md"]}, {"reason": "社区官方用户指南（与 AGPL 社区核心同一产品）证明：CiviEvent 以活动为持久记录，支持活动类型/模板/复制、在线自助报名、多参与者报名、价格集与多档/早鸟费用及按桌套餐、候补、现场签到、参与者状态和活动结果报告；CiviContribute 将捐赠与活动费分列，支持捐赠、专项筹款、自动收据/致谢、付款与待付承诺区分、活动关联贡献记录（绑定捐赠者联系人）及欠款报告；PCP 必须挂接既有活动或贡献页，活动报名者可创建个人募款页。据此覆盖活动记录、报名/入场、活动关联捐赠与结算致谢四项核心。拍卖、抽奖和赞助套餐未在所引官方指南中证实，不作断言。", "slug": "nonprofit-event-management", "source_urls": ["https://docs.civicrm.org/user/en/latest/events/what-is-civievent/", "https://docs.civicrm.org/user/en/latest/events/online-event-registration/", "https://docs.civicrm.org/user/en/latest/events/complex-event-fees/", "https://docs.civicrm.org/user/en/latest/contributions/what-is-civicontribute/", "https://docs.civicrm.org/user/en/latest/contributions/personal-campaign-pages/", "https://civicrm.org/"]}, {"reason": "官方用户指南《What is CiviCRM?》明确说明 CiviCRM 是面向非营利组织的平台，把捐赠、活动、会员、互动、案例、campaign 与 mailings 等置于同一系统，并围绕组织所交互的人员与组织记录进行管理；civicrm.org 首页也以集中支持者沟通、管理捐赠者与会员基础来介绍该产品。两项官方开源项目来源直接支撑其共享记录基础与跨域员工管理形态，不再依赖 civicrm.com 商业功能页。", "slug": "nonprofit-management-platform", "source_urls": ["https://docs.civicrm.org/user/en/latest/introduction/what-is-civicrm/", "https://docs.civicrm.org/user/en/latest/", "https://civicrm.org/", "https://raw.githubusercontent.com/civicrm/civicrm-core/master/README.md", "https://raw.githubusercontent.com/civicrm/civicrm-user-guide/master/docs/contributions/personal-campaign-pages.md"]}, {"reason": "官方PCP指南证明支持者自建个人募款页、故事/目标/图片、tell-a-friend邀请、个人页归因、管理员审批与金额报告，页面绑定机构贡献页或活动；指南明确不支持团队管理，不扩展此能力。", "slug": "peer-to-peer-fundraising-platform", "source_urls": ["https://raw.githubusercontent.com/civicrm/civicrm-user-guide/master/docs/contributions/personal-campaign-pages.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/civicrm/civicrm-core/license", "name": "CiviCRM", "repository_url": "https://github.com/civicrm/civicrm-core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:21:20.997825+08:00", "kind": "repository_metadata", "sha256": "cd112cdbfcd7306fa5688d9f4ff5f005c7354e25be562bf0600cc39a1d2058df", "snapshot_path": "sources/cd112cdbfcd7306fa5688d9f4ff5f005c7354e25be562bf0600cc39a1d2058df.txt", "url": "https://api.github.com/repos/civicrm/civicrm-core"}, {"fetched_at": "2026-10-25T08:38:08.772560+08:00", "kind": "repository_metadata", "sha256": "d94ddb7d8e45349dd86517e634020973df6a6fcb5a445d49b3a362d23b45a5b8", "snapshot_path": "sources/d94ddb7d8e45349dd86517e634020973df6a6fcb5a445d49b3a362d23b45a5b8.txt", "url": "https://api.github.com/repos/civicrm/civicrm-core"}, {"fetched_at": "2026-10-25T08:38:10.632025+08:00", "kind": "license", "sha256": "1925789ddeb6107627083c6813b58486b2b4d217c372ed9e87c7d1447d059131", "snapshot_path": "sources/1925789ddeb6107627083c6813b58486b2b4d217c372ed9e87c7d1447d059131.txt", "url": "https://api.github.com/repos/civicrm/civicrm-core/license"}, {"fetched_at": "2026-10-25T08:42:19.727580+08:00", "kind": "homepage", "sha256": "dc380b33faa4165a704a245c375084d16f605064730823cbd9b9dad167f2a00b", "snapshot_path": "sources/dc380b33faa4165a704a245c375084d16f605064730823cbd9b9dad167f2a00b.txt", "url": "https://civicrm.org"}, {"fetched_at": "2026-10-29T15:44:32.382149+08:00", "kind": "homepage", "sha256": "63fb7af52c78dff7ed43a2cd0fbefa01b5d58b7a8b6d0638a6af7f22a12605b8", "snapshot_path": "sources/63fb7af52c78dff7ed43a2cd0fbefa01b5d58b7a8b6d0638a6af7f22a12605b8.txt", "url": "https://civicrm.org/"}, {"fetched_at": "2026-10-29T15:50:30.367052+08:00", "kind": "documentation", "sha256": "70358da407ca320a7bbc454fb969179fd76322e133ffdcb4f7f5b2936ec35c1d", "snapshot_path": "sources/70358da407ca320a7bbc454fb969179fd76322e133ffdcb4f7f5b2936ec35c1d.txt", "url": "https://civicrm.org/about/license"}, {"fetched_at": "2026-10-29T15:44:34.112647+08:00", "kind": "documentation", "sha256": "70358da407ca320a7bbc454fb969179fd76322e133ffdcb4f7f5b2936ec35c1d", "snapshot_path": "sources/70358da407ca320a7bbc454fb