INSERT INTO "application" VALUES('commercial:onesignal','OneSignal','{"homepage": "https://onesignal.com/", "id": "commercial:onesignal", "leaf_matches": [{"reason": "官方首页列出移动推送与 Web 推送渠道，按用户分群与 Journey 编排发送，并提供推送分析与事件 API；页面代码示例调用 requestPermission，说明触达以系统/浏览器通知权限为前提，符合推送营销的权限—分群—投放—衡量循环。", "slug": "push-notification-marketing-platform", "source_urls": ["https://onesignal.com/"]}], "name": "OneSignal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:28:21.600230+08:00", "kind": "homepage", "sha256": "923825031a2c45551178aca4be74c26c49bfee83eee464211b5cd9ec81f864dc", "snapshot_path": "sources/923825031a2c45551178aca4be74c26c49bfee83eee464211b5cd9ec81f864dc.txt", "url": "https://onesignal.com/"}], "summary": "面向应用与网站营销人员的移动/网页推送编排、分群投放与效果分析平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:slicktext','SlickText','{"homepage": "https://www.slicktext.com/", "id": "commercial:slicktext", "leaf_matches": [{"reason": "官方首页展示群发短信活动、关键词/网页表单/二维码等订阅获取方式、动态分群、短信合规指南与活动分析，构成同意订阅—短信群发—退订合规—衡量的营销短信闭环；功能页进一步说明按合规要求保存订阅同意记录并自动处理 STOP/UNSUBSCRIBE 等退订关键词。", "slug": "sms-marketing-platform", "source_urls": ["https://www.slicktext.com/", "https://www.slicktext.com/features/"]}], "name": "SlickText", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:28:24.622884+08:00", "kind": "homepage", "sha256": "a04ffbb62ee8ef32b37b96766845a6d6f7ce8ffceb54b06fddaf2e96141e9f8e", "snapshot_path": "sources/a04ffbb62ee8ef32b37b96766845a6d6f7ce8ffceb54b06fddaf2e96141e9f8e.txt", "url": "https://www.slicktext.com/"}, {"fetched_at": "2026-10-24T15:53:22.617478+08:00", "kind": "documentation", "sha256": "bb6810002e5aa99e916a747f2d4a107b5a7b954e308bdcbb7dd518d0e16586e5", "snapshot_path": "sources/bb6810002e5aa99e916a747f2d4a107b5a7b954e308bdcbb7dd518d0e16586e5.txt", "url": "https://www.slicktext.com/features/"}], "summary": "面向营销人员的短信订阅名单获取、群发活动、合规退订与效果分析的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sprout-social','Sprout Social','{"homepage": "https://sproutsocial.com/", "id": "commercial:sprout-social", "leaf_matches": [{"reason": "官方首页 meta 写明 publishing and engagement to analytics，正文以 Plan & schedule content、Engage with customers、Publishing、Analytics 为主线，套餐按所管理 profile 规模区分（a few profiles across social networks / a lot of profiles）；Smart Inbox 官方页进一步说明 “The Smart Inbox consolidates all your connected social profiles into one organized stream”，评论、私信与提及汇入单一工作区，可按网络/类型/状态分流、结合 Conversation History 回复并用 Collision Detection 避免同事重复回复，覆盖发布—同控制台入站回复—分析闭环。", "slug": "social-media-management-platform", "source_urls": ["https://sproutsocial.com/", "https://sproutsocial.com/features/smart-inbox/"]}], "name": "Sprout Social", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:39:30.590136+08:00", "kind": "homepage", "sha256": "52b0cb543b20457c75ba63a6199098d415bf970ecbe0b6cd0310c388410a98fa", "snapshot_path": "sources/52b0cb543b20457c75ba63a6199098d415bf970ecbe0b6cd0310c388410a98fa.txt", "url": "https://sproutsocial.com/"}, {"fetched_at": "2026-10-24T18:46:56.135677+08:00", "kind": "documentation", "sha256": "71a0ea2145b56665ce54765ae97a8a13084a2ca82153bf323dbcb60867197e3b", "snapshot_path": "sources/71a0ea2145b56665ce54765ae97a8a13084a2ca82153bf323dbcb60867197e3b.txt", "url": "https://sproutsocial.com/features/smart-inbox/"}], "summary": "统一管理已连接多个社交 profile 的规划发布、评论/私信/提及入站回复与表现分析的商业社媒管理平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:664013991','Postiz','{"deployment": ["Docker / Coolify / Railway / 任意 VPS 自托管，需自备 PostgreSQL、Redis 与对象存储", "自托管需在各有社交平台创建开发者应用并完成平台审核"], "features": ["跨多个社交网络排期并发布帖子", "发布效果分析（需自备各平台应用凭据）", "团队成员协作、评论与共同排期", "RSS 自动发布与 Public API/Webhook 集成"], "github_repository_id": 664013991, "homepage": "https://postiz.com", "id": "github:664013991", "leaf_matches": [{"reason": "连接自有社交账号后，以内容日历组织草稿/定时/已发布帖子，按渠道独立时间完成计划到发布的转换；发布失败为可见状态。", "slug": "creator-content-planner", "source_urls": ["https://docs.postiz.com/general/calendar/overview", "https://docs.postiz.com/general/composer/scheduling", "https://docs.postiz.com/general/channels/connect"]}, {"reason": "README 说明可跨多个社交网络排期发布帖子、查看分析并与团队协作，且提供 Docker/自托管部署与开放 API；仓库元数据与许可证 API 证明其为 AGPL-3.0 的完整自托管应用，符合组织自有账号的社交发布闭环。", "slug": "social-publishing-platform", "source_urls": ["https://api.github.com/repos/gitroomhq/postiz-app", "https://api.github.com/repos/gitroomhq/postiz-app/license", "https://raw.githubusercontent.com/gitroomhq/postiz-app/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/gitroomhq/postiz-app/license", "name": "Postiz", "repository_url": "https://github.com/gitroomhq/postiz-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:14:40.398133+08:00", "kind": "repository_metadata", "sha256": "8640fbc7de35702e087f749f671308bcfa3f22e4482943541cf6891d1a331954", "snapshot_path": "sources/8640fbc7de35702e087f749f671308bcfa3f22e4482943541cf6891d1a331954.txt", "url": "https://api.github.com/repos/gitroomhq/postiz-app"}, {"fetched_at": "2026-10-24T15:44:00.306293+08:00", "kind": "license", "sha256": "4f23a18581911e2bf6a7347cd28199c4adbcdc81e68024d7227218ea0985a028", "snapshot_path": "sources/4f23a18581911e2bf6a7347cd28199c4adbcdc81e68024d7227218ea0985a028.txt", "url": "https://api.github.com/repos/gitroomhq/postiz-app/license"}, {"fetched_at": "2026-10-27T02:03:59+08:00", "kind": "documentation", "sha256": "ea0febab9bd172bda5d7381e5d2a02339646ab8e1109469c5efe70fb0e3437a1", "snapshot_path": "sources/ea0febab9bd172bda5d7381e5d2a02339646ab8e1109469c5efe70fb0e3437a1.txt", "url": "https://docs.postiz.com/general/calendar/overview"}, {"fetched_at": "2026-10-27T02:04:03+08:00", "kind": "documentation", "sha256": "e8122d6e305c15854a169b67f6b621e1dfbbbc2aa41ddd4bb39604a161ba5f21", "snapshot_path": "sources/e8122d6e305c15854a169b67f6b621e1dfbbbc2aa41ddd4bb39604a161ba5f21.txt", "url": "https://docs.postiz.com/general/channels/connect"}, {"fetched_at": "2026-10-27T02:04:01+08:00", "kind": "documentation", "sha256": "2778e5c0abd2f536cab2e8b37fa19830f332efc805f75596e760094e32106802", "snapshot_path": "sources/2778e5c0abd2f536cab2e8b37fa19830f332efc805f75596e760094e32106802.txt", "url": "https://docs.postiz.com/general/composer/scheduling"}, {"fetched_at": "2026-10-27T02:04:41+08:00", "kind": "repository_metadata", "sha256": "72cb39750d28de3c06b2a40916ee6fd4d5a407a9073d3381560a530f6bd07db1", "snapshot_path": "sources/72cb39750d28de3c06b2a40916ee6fd4d5a407a9073d3381560a530f6bd07db1.txt", "url": "https://github.com/gitroomhq/postiz-app"}, {"fetched_at": "2026-10-27T02:04:43+08:00", "kind": "license", "sha256": "d322fb1066693d8ed25495d11029f443aa793316852749e1389773c1946251b3", "snapshot_path": "sources/d322fb1066693d8ed25495d11029f443aa793316852749e1389773c1946251b3.txt", "url": "https://raw.githubusercontent.com/gitroomhq/postiz-app/main/LICENSE"}, {"fetched_at": "2026-10-24T15:43:58.427340+08:00", "kind": "readme", "sha256": "03ca37863c7ea1f663ea620f46277da45708f7e8079b5c5568517a10c042a0c5", "snapshot_path": "sources/03ca37863c7ea1f663ea620f46277da45708f7e8079b5c5568517a10c042a0c5.txt", "url": "https://raw.githubusercontent.com/gitroomhq/postiz-app/main/README.md"}], "summary": "AGPL-3.0 开源、可自托管的社交内容排期与跨网络发布平台，附带分析与团队协作。", "technology_stack": ["TypeScript", "NextJS", "NestJS", "Prisma / PostgreSQL", "Temporal", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:birdeye','Birdeye','{"homepage": "https://birdeye.com/", "id": "commercial:birdeye", "leaf_matches": [{"reason": "官方评论页正文写明 “Jay generates, responds, and markets reviews at every location”，并以 Review generation agent（按客户最可能响应的时机与渠道征集评论）、Review response agent（读取完整评论、以品牌语调回复、可自动发布或待审批）与 Unified AI reputation management（“Every rating and review, from every site, in one place”，Ticketing Agent 将问题路由至根因）描述逐条处理闭环。官方 Reputation Score 页正文另证 “Ratings, review counts, and responses, tracked over time”，并可按地点与来源比较、报告声誉变化；可证品牌/多门店实体上的评论征集、逐条回复、问题路由与声誉状态追踪。", "slug": "brand-reputation-management", "source_urls": ["https://birdeye.com/reviews/", "https://birdeye.com/reputation-score/"]}], "name": "Birdeye", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:34:17.549743+08:00", "kind": "documentation", "sha256": "76a00d8a2ef0e1a935f61bdfa101a008ac26b3359f542557f341d20ccc101d37", "snapshot_path": "sources/76a00d8a2ef0e1a935f61bdfa101a008ac26b3359f542557f341d20ccc101d37.txt", "url": "https://birdeye.com/reviews/"}, {"fetched_at": "2026-10-24T15:51:07.685732+08:00", "kind": "homepage", "sha256": "ee6e8d92ee72d0186a0ba90c39a189cdb346846c5b9f52c9c901adbaeb6a87f7", "snapshot_path": "sources/ee6e8d92ee72d0186a0ba90c39a189cdb346846c5b9f52c9c901adbaeb6a87f7.txt", "url": "https://birdeye.com/"}, {"fetched_at": "2026-10-26T16:25:30.523020+08:00", "kind": "documentation", "sha256": "6a2fdac943d050e72a0c22ca9daf185dae71b9f2479ca2f1502ec24061476c2f", "snapshot_path": "sources/6a2fdac943d050e72a0c22ca9daf185dae71b9f2479ca2f1502ec24061476c2f.txt", "url": "https://birdeye.com/reputation-score/"}], "summary": "面向多门店品牌的评论征集、逐条回复与声誉结果报告的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:klue','Klue','{"homepage": "https://klue.com/", "id": "commercial:klue", "leaf_matches": [{"reason": "官方 Compete Agent 页正文写明 “Automatically collect, curate, and share competitive intel throughout your organization”，并以 Research Analyst 持续收集分析情报、生成竞争对手档案，battlecards 维护 Tier 1 竞争内容，Win/Loss 分析胜负模式；覆盖追踪实体—持续收集—知识策展—内部分发。", "slug": "competitive-intelligence-platform", "source_urls": ["https://klue.com/compete-agent"]}], "name": "Klue", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:35:56.077683+08:00", "kind": "documentation", "sha256": "ff6e7c03b87dbfc30a7777bd3e085d4e388286f08b86f2c4dcb68f5d2a52daed", "snapshot_path": "sources/ff6e7c03b87dbfc30a7777bd3e085d4e388286f08b86f2c4dcb68f5d2a52daed.txt", "url": "https://klue.com/compete-agent"}], "summary": "面向内部销售与市场团队的竞争情报收集、整理、战斗卡分发与赢单/失单分析平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:supermetrics','Supermetrics','{"homepage": "https://supermetrics.com/", "id": "commercial:supermetrics", "leaf_matches": [{"reason": "官方 Studio 页 meta/JSON-LD 写明 “Build dashboards in Claude with Supermetrics Studio. Connect live marketing data, share securely, and turn insights into campaign actions instantly.”，正文说明 “Live data from all your Supermetrics data sources” 与 “Every channel, together”；可证多源营销数据连接、实时仪表盘/报告与跨渠道分析。首页 Organization JSON-LD 亦自述为 Marketing Intelligence Platform。", "slug": "marketing-analytics-platform", "source_urls": ["https://supermetrics.com/", "https://supermetrics.com/products/supermetrics-studio"]}], "name": "Supermetrics", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:39:33.605000+08:00", "kind": "homepage", "sha256": "87f7b3506c1feeb66a39776d4c41856acf49c4a46d1f4c0013664735e6931753", "snapshot_path": "sources/87f7b3506c1feeb66a39776d4c41856acf49c4a46d1f4c0013664735e6931753.txt", "url": "https://supermetrics.com/"}, {"fetched_at": "2026-10-26T16:16:43.564451+08:00", "kind": "documentation", "sha256": "1dc44986e498622d6aba7ca3d5d54a04ab0a5fb6f8775c0682023567689a0f69", "snapshot_path": "sources/1dc44986e498622d6aba7ca3d5d54a04ab0a5fb6f8775c0682023567689a0f69.txt", "url": "https://supermetrics.com/products/supermetrics-studio"}], "summary": "连接多个营销数据源，将实时营销数据汇入仪表盘与报告，用于跨渠道营销分析与结果汇报的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lifesight','Lifesight','{"homepage": "https://lifesight.io/", "id": "commercial:lifesight", "leaf_matches": [{"reason": "官方首页正文写明 “Lifesight combines causal MMM, incrementality testing and incrementality-adjusted attribution with AI agents that plan, optimize and act within your rules”，并以 Planning Agent 比较预算情景（current mix / suggested mix 的 modelled incremental revenue）、按 marginal ROAS 比较渠道组合；可证汇总支出—结果建模与预算分配决策。", "slug": "marketing-mix-modeling-application", "source_urls": ["https://lifesight.io/"]}], "name": "Lifesight", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:33:52.103243+08:00", "kind": "homepage", "sha256": "7bad614c86317b75f8165016d67f3fdb804c0ba3bf05d36bc53c24f980568ca7", "snapshot_path": "sources/7bad614c86317b75f8165016d67f3fdb804c0ba3bf05d36bc53c24f980568ca7.txt", "url": "https://lifesight.io/"}], "summary": "以因果 MMM、增量测试与预算优化支持营销预算分配的测量应用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:meltwater','Meltwater','{"homepage": "https://www.meltwater.com/", "id": "commercial:meltwater", "leaf_matches": [{"reason": "官方媒体监测页说明从新闻/社交/广播/印刷/播客持续收集提及，提供可定制警报、仪表盘、情感与声量分析及 PR 影响报告，覆盖监测定义—条目级覆盖—组织测量交付。", "slug": "media-monitoring-platform", "source_urls": ["https://www.meltwater.com/en/products/media-monitoring"]}], "name": "Meltwater", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:34:19.344580+08:00", "kind": "documentation", "sha256": "3819ebe2b4498f1c8e0ab23bd76ec47c51a9ec80bb6c9d2e2b2d356bbe7d9aa5", "snapshot_path": "sources/3819ebe2b4498f1c8e0ab23bd76ec47c51a9ec80bb6c9d2e2b2d356bbe7d9aa5.txt", "url": "https://www.meltwater.com/en/products/media-monitoring"}], "summary": "持续收集新闻、社交、广播、印刷与播客报道并提供警报、仪表盘与报道测量的媒体情报平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:brandwatch','Brandwatch','{"homepage": "https://www.brandwatch.com/", "id": "commercial:brandwatch", "leaf_matches": [{"reason": "官方 Listen 页说明可监测品牌、产品与竞品的提及并实时发现趋势（Monitor mentions… discover those trends in real-time），分析情感与品牌认知，覆盖 100 million online sources 与多语言，并对异常趋势和负面评论自动告警；符合常设监测—公开语料—聚合洞察的聆听结构。", "slug": "social-listening-platform", "source_urls": ["https://www.brandwatch.com/products/listen/"]}], "name": "Brandwatch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:35:15.495910+08:00", "kind": "documentation", "sha256": "8934859c21aa39f9834b7771a40d13fd5e5c2a8f738b7d48c5a64ac39dfa691f", "snapshot_path": "sources/8934859c21aa39f9834b7771a40d13fd5e5c2a8f738b7d48c5a64ac39dfa691f.txt", "url": "https://www.brandwatch.com/products/listen/"}], "summary": "持续监测公开社交对话、分析情感与主题并输出消费者洞察的商业聆听平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:socialinsider','Socialinsider','{"homepage": "https://www.socialinsider.io/", "id": "commercial:socialinsider", "leaf_matches": [{"reason": "官方分析页列出「Social media analytics across Instagram, Facebook, TikTok, LinkedIn, X (Twitter), and YouTube」「Competitor analysis and benchmarking」「Industry-level social media benchmarks」「Automated social media reporting」，并说明可查看品牌表现随时间的变化（how your brand''s performance has evolved over time）；测量对象为品牌自身的社交账号表现，面向营销的仪表盘/对比/报告结构成立。", "slug": "social-media-analytics-platform", "source_urls": ["https://www.socialinsider.io/social-media-analytics"]}], "name": "Socialinsider", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:35:18.578331+08:00", "kind": "documentation", "sha256": "a8d9ebeefa708801c216ea3b31c5a2dc265df2bf2b29bcb29bcf5a086950927b", "snapshot_path": "sources/a8d9ebeefa708801c216ea3b31c5a2dc265df2bf2b29bcb29bcf5a086950927b.txt", "url": "https://www.socialinsider.io/social-media-analytics"}], "summary": "衡量组织自有社交档案表现并与竞争对手基准对比的分析平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:frontify','Frontify','{"homepage": "https://www.frontify.com/", "id": "commercial:frontify", "leaf_matches": [{"reason": "品牌指南页正文说明指南被维护为可持续更新的 living system（sections、tokens、images，「easier to find, update, and share」「always current, always correct」），并提供「Self-service brand access」，可安全向代理、供应商等外部合作方共享指南并控制可见范围；DAM 页正文说明「Permissions control who can access, download, or share each asset」「Approval workflows prevent unapproved content from going live」，销售、HR、代理与区域团队可自助获取已批准资产。两页正文共同覆盖受管资产库—已发布使用指南—内外部自助分发三段。", "slug": "brand-asset-guideline-platform", "source_urls": ["https://www.frontify.com/en/digital-asset-management", "https://www.frontify.com/en/brand-guidelines"]}], "name": "Frontify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:28:49.501544+08:00", "kind": "homepage", "sha256": "9d0441ef32e86105ae2ab7f654e7a551b0979b5dce404283959561e2affaec2e", "snapshot_path": "sources/9d0441ef32e86105ae2ab7f654e7a551b0979b5dce404283959561e2affaec2e.txt", "url": "https://www.frontify.com/"}, {"fetched_at": "2026-10-24T18:44:44.653955+08:00", "kind": "documentation", "sha256": "9d0ec73554c4c61a22ef349f78a3c219e26a0bc44aaabcb7a2e5af8c3c320a3f", "snapshot_path": "sources/9d0ec73554c4c61a22ef349f78a3c219e26a0bc44aaabcb7a2e5af8c3c320a3f.txt", "url": "https://www.frontify.com/en/digital-asset-management"}, {"fetched_at": "2026-10-26T16:16:21.049360+08:00", "kind": "documentation", "sha256": "a9d02cd5f0254cc37c44ac347df4a477faf5f7e29245b62cb0076956165f283e", "snapshot_path": "sources/a9d02cd5f0254cc37c44ac347df4a477faf5f7e29245b62cb0076956165f283e.txt", "url": "https://www.frontify.com/en/brand-guidelines"}], "summary": "集中管理品牌资产与品牌指南并向内外部共享分发的品牌平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:marq','Marq','{"homepage": "https://www.marq.com/", "id": "commercial:marq", "leaf_matches": [{"reason": "Brand Portal 页正文说明把「approved brand images, fonts, colors and style guidelines」保留在「one central location」，品牌门户维护「the most recent brand assets」，并以「brand asset manager」集中存储、搜索与分发；品牌团队可经用户权限与审批流程控制他人访问，非设计人员经可锁定模板（logo、颜色、字体、版式）自助制作并发布内容。Content Management 页正文进一步说明品牌资产集中于「a single source of truth」、模板按用户角色与权限开放。受管品牌表达记录与超出品牌团队的受控自助使用两项成立；显式资产版本历史/到期生命周期未见正文，故不作断言。", "slug": "brand-management-platform", "source_urls": ["https://www.marq.com/pages/brand-portal/", "https://www.marq.com/pages/platform/content-management/"]}], "name": "Marq", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:33:54.529342+08:00", "kind": "homepage", "sha256": "c00da05edd0397d9273857a79bf576f2496ba83f0d496f3145e10ac4f081da29", "snapshot_path": "sources/c00da05edd0397d9273857a79bf576f2496ba83f0d496f3145e10ac4f081da29.txt", "url": "https://www.marq.com/"}, {"fetched_at": "2026-10-26T16:25:30.557689+08:00", "kind": "documentation", "sha256": "cb5f2df584a3b4641f370af8a3398402a767d8cf427c53ebe75d76180fb99363", "snapshot_path": "sources/cb5f2df584a3b4641f370af8a3398402a767d8cf427c53ebe75d76180fb99363.txt", "url": "https://www.marq.com/pages/platform/content-management/"}, {"fetched_at": "2026-10-26T16:25:31.045188+08:00", "kind": "documentation", "sha256": "1ee2fa19107ed953757540455b4e2c2b6e12b013156cc2a75cc0daca3b55431f", "snapshot_path": "sources/1ee2fa19107ed953757540455b4e2c2b6e12b013156cc2a75cc0daca3b55431f.txt", "url": "https://www.marq.com/pages/brand-portal/"}], "summary": "以集中品牌资产与指南的品牌门户结合可锁定模板和审批，让非设计人员自助产出合规材料的品牌管理平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:contently','Contently','{"homepage": "https://contently.com/", "id": "commercial:contently", "leaf_matches": [{"reason": "官方平台页展示跨团队内容日历、简报自动路由到相应团队/审阅者、编辑与合规审阅、从简报到发布的流程，并通过 CMS/社交/CRM/邮件集成完成分发，覆盖内容单元—编辑计划—生产发布闭环。", "slug": "content-marketing-platform", "source_urls": ["https://contently.com/platform/"]}], "name": "Contently", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:37:36.756441+08:00", "kind": "documentation", "sha256": "e4bba62ce99dc60f6bda9d9d1d650380f99462ee627c4e9b508639d552691b66", "snapshot_path": "sources/e4bba62ce99dc60f6bda9d9d1d650380f99462ee627c4e9b508639d552691b66.txt", "url": "https://contently.com/platform/"}, {"fetched_at": "2026-10-24T15:51:11.525998+08:00", "kind": "homepage", "sha256": "bbfb7aff4ed323444ae91973892adc099d30968839192ecc8e42113ccb100ba7", "snapshot_path": "sources/bbfb7aff4ed323444ae91973892adc099d30968839192ecc8e42113ccb100ba7.txt", "url": "https://contently.com/"}], "summary": "面向品牌内容项目的规划、简报、合规审阅与发布协调平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:coschedule','CoSchedule','{"homepage": "https://coschedule.com/", "id": "commercial:coschedule", "leaf_matches": [{"reason": "官方内容营销页以内容规划为中心：正文写明 “Simplify content planning, get visibility across channels”，提供按品牌/团队/部门/举措划分的多日历、Kanban 看板、为每个项目分配角色/截止日期/交付物并跟踪进度；博客与邮件内容与其他活动同处一个计划，并可从同一集中日历跨渠道排期发布，页面另列 feedback/revisions/approvals 协作能力。营销日历页同时列出 Social/Content/Email/Events/Podcasting 板块，并支持拖拽改期。首页标题仍以 Social Media Management 定位，因此本匹配只采用上述内容规划与协调面，不主张社交账户管理是核心。", "slug": "content-planning-platform", "source_urls": ["https://coschedule.com/content-marketing-help", "https://coschedule.com/marketing-calendar"]}], "name": "CoSchedule", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:37:08.248786+08:00", "kind": "documentation", "sha256": "91b038533348cc5bcd94d6ca143bd37f1b6e11e36751b270da93dc9a5054b0d3", "snapshot_path": "sources/91b038533348cc5bcd94d6ca143bd37f1b6e11e36751b270da93dc9a5054b0d3.txt", "url": "https://coschedule.com/marketing-calendar"}, {"fetched_at": "2026-10-24T15:51:14.644956+08:00", "kind": "homepage", "sha256": "fc0b2cbd48e492427d82041044ac25b7cde9871eeca6ed502f73a91763894b71", "snapshot_path": "sources/fc0b2cbd48e492427d82041044ac25b7cde9871eeca6ed502f73a91763894b71.txt", "url": "https://coschedule.com/"}, {"fetched_at": "2026-10-26T16:30:00.755693+08:00", "kind": "documentation", "sha256": "0517f88d8b12b6d7f7e52a4320d5051097621aa6423c441ba5744d7be812be26", "snapshot_path": "sources/0517f88d8b12b6d7f7e52a4320d5051097621aa6423c441ba5744d7be812be26.txt", "url": "https://coschedule.com/content-marketing-help"}], "summary": "以共享内容日历和内容项目协调为中心，覆盖博客、邮件、落地页与活动，同时提供社交发布与互动能力的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:bannerflow','Bannerflow','{"homepage": "https://www.bannerflow.com/", "id": "commercial:bannerflow", "leaf_matches": [{"reason": "官方首页展示把一个主创意自动扩展为各种格式和版本、本地化与翻译、动态创意优化，并向渠道自动发布和排期、支持实时更新投放中创意，覆盖多变体生产—交付链就绪输出。", "slug": "creative-management-platform-cmp", "source_urls": ["https://www.bannerflow.com/"]}], "name": "Bannerflow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:07.966445+08:00", "kind": "homepage", "sha256": "db688ac315bbd9f22be296b70833340d4d89c93f47d80e2a5c2cb49be3f730fe", "snapshot_path": "sources/db688ac315bbd9f22be296b70833340d4d89c93f47d80e2a5c2cb49be3f730fe.txt", "url": "https://www.bannerflow.com/"}], "summary": "把品牌资产批量生产为多尺寸、多市场广告创意并向渠道发布排期的创意自动化平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aprimo-plan','Aprimo Plan','{"homepage": "https://www.aprimo.com/", "id": "commercial:aprimo-plan", "leaf_matches": [{"reason": "官方 Plan 页展示营销活动与内容计划、统一活动日历、活动与内容简报、模板化活动框架、目标/项目与活动洞察，说明其以活动/项目为组织单位协调计划、简报与执行进度。", "slug": "marketing-campaign-management-platform", "source_urls": ["https://www.aprimo.com/platform/plan"]}], "name": "Aprimo Plan", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:37:39.751105+08:00", "kind": "documentation", "sha256": "090a43e4b7f812353af11e764983c1440742e99037a006d32fa4b9125f8464dc", "snapshot_path": "sources/090a43e4b7f812353af11e764983c1440742e99037a006d32fa4b9125f8464dc.txt", "url": "https://www.aprimo.com/platform/plan"}, {"fetched_at": "2026-10-24T15:51:16.900125+08:00", "kind": "homepage", "sha256": "1f917667ad682cc9bf1ba79b0c149057ca2749717ee5e6d77c6953ee61968651", "snapshot_path": "sources/1f917667ad682cc9bf1ba79b0c149057ca2749717ee5e6d77c6953ee61968651.txt", "url": "https://www.aprimo.com/"}], "summary": "以活动/项目为组织单位、统一日历与简报协调营销计划与跨团队执行的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:6697085','Sixpack','{"deployment": ["需 Redis ≥ 2.6 与 Python ≥ 2.7；pip 安装后以 sixpack 启动服务，sixpack-web 启动仪表盘", "生产环境 README 建议以 gunicorn 运行"], "features": ["通过 participate API 把 client_id 粘性分配到实验替代方案", "通过 convert API 按实验/ KPI 记录转化", "sixpack-web 仪表盘比较各替代方案表现并选择胜出者", "支持 traffic_fraction 限定实验流量比例"], "github_repository_id": 6697085, "homepage": "http://sixpack.seatgeek.com", "id": "github:6697085", "leaf_matches": [{"reason": "README 说明通过 participate/convert API 将同一 client_id 粘性分配到实验替代方案并记录转化，内置 sixpack-web 仪表盘比较各方案表现并选择胜出者；仓库元数据与许可证 API 证明其为 BSD-2-Clause 开源、可自托管的服务端 + 可选仪表盘。", "slug": "a-b-testing-platform", "source_urls": ["https://raw.githubusercontent.com/sixpack/sixpack/master/README.rst", "https://api.github.com/repos/sixpack/sixpack", "https://api.github.com/repos/sixpack/sixpack/license"]}], "license": "BSD-2-Clause", "license_evidence_url": "https://api.github.com/repos/sixpack/sixpack/license", "name": "Sixpack", "repository_url": "https://github.com/sixpack/sixpack", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:45:24.235798+08:00", "kind": "repository_metadata", "sha256": "7a5db80964196fd485bb953a66e77ea3aa59c9b0795576e656f8bbd43ce21ade", "snapshot_path": "sources/7a5db80964196fd485bb953a66e77ea3aa59c9b0795576e656f8bbd43ce21ade.txt", "url": "https://api.github.com/repos/sixpack/sixpack"}, {"fetched_at": "2026-10-24T15:24:30.532980+08:00", "kind": "license", "sha256": "f1c3a0be950d431e8cdda80ab95fb088ecd3ff70d8879b144474153f2f4900d9", "snapshot_path": "sources/f1c3a0be950d431e8cdda80ab95fb088ecd3ff70d8879b144474153f2f4900d9.txt", "url": "https://api.github.com/repos/sixpack/sixpack/license"}, {"fetched_at": "2026-10-24T15:24:26.127171+08:00", "kind": "readme", "sha256": "13cf84a51e5a5cf3a52eb560b07c60aebd53125cb8cdf30bff21d11e9b87e177", "snapshot_path": "sources/13cf84a51e5a5cf3a52eb560b07c60aebd53125cb8cdf30bff21d11e9b87e177.txt", "url": "https://raw.githubusercontent.com/sixpack/sixpack/master/README.rst"}], "summary": "BSD-2-Clause 开源的跨语言 A/B 测试服务，含参与/转化 API 与可选 Web 仪表盘。", "technology_stack": ["Python", "Redis", "Flask"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pricefx','Pricefx','{"homepage": "https://www.pricefx.com/", "id": "commercial:pricefx", "leaf_matches": [{"reason": "官方 Price Management 页面称其为受治理的统一定价系统：集中 list/base/customer prices，规则编码 markup/index/corridor 并自动重算，情景模拟比较利润率影响，可配置审批流与审计轨迹，批准后发布到 ERP/CRM/CPQ；并明确 ERP 存价而非设计/测试/治理价格，符合定价治理与销售接口边界。", "slug": "sales-pricing-application", "source_urls": ["https://www.pricefx.com/platform/price-management/"]}], "name": "Pricefx", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:34:28.853996+08:00", "kind": "documentation", "sha256": "fc70e4eaf689ef58d64b884e0b9c4291f064411610f69ec2496a523741b2bce5", "snapshot_path": "sources/fc70e4eaf689ef58d64b884e0b9c4291f064411610f69ec2496a523741b2bce5.txt", "url": "https://www.pricefx.com/platform/price-management/"}], "summary": "面向 B2B 企业的定价管理平台，集中维护列表价/基础价与客户价，支持规则计算、情景模拟、审批流及向 ERP/CRM/CPQ 发布已批准价格。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:assembled','Assembled','{"homepage": "https://www.assembled.com/", "id": "commercial:assembled", "leaf_matches": [{"reason": "官方预测页按 queue/channel/site 预测业务量并即时 right-size staffing，给出未来数月人员需求；排班页将规则、班次时长、合规、休息、覆盖率纳入自动排班，支持比较草稿/情景、预测 SLA 影响、班次交换与按人员阈值自动批假，并把变更通知坐席；构成需求衍生的坐席排班核心。", "slug": "agent-scheduling-platform", "source_urls": ["https://www.assembled.com/features/forecasting", "https://www.assembled.com/features/scheduling"]}, {"reason": "官方预测页正文覆盖可配置需求预测模型与按团队人员配置；排班页正文覆盖自动排班、日内调整、基于人员阈值的自动休假审批、自愿休假/额外工作（extra work）调配，以及休息/加班/班次上限的排班合规检查；实时管理页正文覆盖坐席状态、遵守度指标、超时遵守警报与日内人员调整，共同构成预测→人员配置/排班→日内对齐的持续循环。", "slug": "workforce-management-for-contact-centers", "source_urls": ["https://www.assembled.com/features/forecasting", "https://www.assembled.com/features/scheduling", "https://www.assembled.com/features/realtime-management"]}], "name": "Assembled", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:38:08.402401+08:00", "kind": "documentation", "sha256": "62fa6492fbc9917d3ee97086568b3ada65aae1b650d5cdcd0d82ddbc970c148f", "snapshot_path": "sources/62fa6492fbc9917d3ee97086568b3ada65aae1b650d5cdcd0d82ddbc970c148f.txt", "url": "https://www.assembled.com/features/forecasting"}, {"fetched_at": "2026-10-27T11:56:32.172433+08:00", "kind": "documentation", "sha256": "3b911739e19b1300e293e389cb7dd9928e29816e705ff4c3023fd25cce2beff6", "snapshot_path": "sources/3b911739e19b1300e293e389cb7dd9928e29816e705ff4c3023fd25cce2beff6.txt", "url": "https://www.assembled.com/features/realtime-management"}, {"fetched_at": "2026-10-26T16:34:28.520071+08:00", "kind": "documentation", "sha256": "fba4d00a90e32419d61b4d09c7d917994fe0530bca34f14ee693369df5d87aaa", "snapshot_path": "sources/fba4d00a90e32419d61b4d09c7d917994fe0530bca34f14ee693369df5d87aaa.txt", "url": "https://www.assembled.com/features/scheduling"}], "summary": "面向客户支持团队的劳动力管理平台，以按队列/渠道/站点的业务量预测驱动人员配置，并生成、比较和发布坐席排班。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:amazon-connect-customer','Amazon Connect Customer','{"homepage": "https://aws.amazon.com/connect/", "id": "commercial:amazon-connect-customer", "leaf_matches": [{"reason": "官方管理员指南定义其为联络中心：客户通过语音/聊天/短信等联系，系统将客户接到坐席、智能路由并按队列/路由配置分配，实时跟踪绩效；按用量付费、由 AWS 配置电话号码。功能页进一步说明 AWS 电信网络覆盖 158 国 DID/免费号码、直连 40+ 一级运营商、无需自管多供应商或承诺峰值容量，符合供应商运营的云 CCaaS 形态。", "slug": "cloud-contact-center-ccaas", "source_urls": ["https://docs.aws.amazon.com/connect/latest/adminguide/what-is-amazon-connect.html", "https://aws.amazon.com/connect/features/"]}], "name": "Amazon Connect Customer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:34:27.867196+08:00", "kind": "documentation", "sha256": "619dc1be446466e49ac16c721928e3545dc80f44fcaf8197dad92b27186ed4a2", "snapshot_path": "sources/619dc1be446466e49ac16c721928e3545dc80f44fcaf8197dad92b27186ed4a2.txt", "url": "https://docs.aws.amazon.com/connect/latest/adminguide/what-is-amazon-connect.html"}, {"fetched_at": "2026-10-26T16:36:50.265578+08:00", "kind": "documentation", "sha256": "a02e2fbec012a1b20582a5a308e93b8db212b9fbe879864065caa4bfc87b395b", "snapshot_path": "sources/a02e2fbec012a1b20582a5a308e93b8db212b9fbe879864065caa4bfc87b395b.txt", "url": "https://aws.amazon.com/connect/features/"}], "summary": "AWS 运营的云联络中心服务（CCaaS）：以队列和路由配置将语音、聊天、短信、邮件等客户互动分配给坐席，按用量付费并从 AWS 电信网络配置号码。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:190705676','MikoPBX','{"deployment": ["裸机 Live USB / ISO 安装", "VMware、VirtualBox、Hyper-V、Proxmox 等虚拟机或 LXC 容器", "Docker / Docker Compose", "AWS、GCP、Azure、DigitalOcean、Vultr 等云主机"], "features": ["Web 界面配置 IVR 菜单、呼入/呼出呼叫规则与自定义呼叫流程", "Asterisk 22 呼叫引擎，支持通话录音、队列、语音信箱、转接与代接", "可自托管于裸机、虚拟机、容器或云主机"], "github_repository_id": 190705676, "homepage": "https://www.mikopbx.com", "id": "github:190705676", "leaf_matches": [{"reason": "README 明确列出 IVR 菜单、呼入/呼出呼叫规则、节假日/夜间切换和自定义呼叫流程编程，并支持通话录音；系统由 Asterisk 22 自行处理来电并按预设菜单/流程执行，符合自动化呼叫处理、持久化呼叫流程和语音交互三项核心。", "slug": "ivr-platform", "source_urls": ["https://raw.githubusercontent.com/mikopbx/Core/develop/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/mikopbx/Core/license", "name": "MikoPBX", "repository_url": "https://github.com/mikopbx/Core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:39:41.573227+08:00", "kind": "repository_metadata", "sha256": "5ea91696d680e6d89b87d02757fa335d77d5e32746521d6440376e59bf8d1536", "snapshot_path": "sources/5ea91696d680e6d89b87d02757fa335d77d5e32746521d6440376e59bf8d1536.txt", "url": "https://api.github.com/repos/mikopbx/Core"}, {"fetched_at": "2026-10-26T16:39:43.492246+08:00", "kind": "license", "sha256": "b49cd455164479e5fe9834e7a9d3e6e407b1a7a1313d72071d4190106a21bfe2", "snapshot_path": "sources/b49cd455164479e5fe9834e7a9d3e6e407b1a7a1313d72071d4190106a21bfe2.txt", "url": "https://api.github.com/repos/mikopbx/Core/license"}, {"fetched_at": "2026-10-26T16:39:44.922977+08:00", "kind": "readme", "sha256": "ffd812c30e262e7de78fe3a03ebb0db47296cd52f6dd0b2ddef0d71ab9c5ec6c", "snapshot_path": "sources/ffd812c30e262e7de78fe3a03ebb0db47296cd52f6dd0b2ddef0d71ab9c5ec6c.txt", "url": "https://raw.githubusercontent.com/mikopbx/Core/develop/README.md"}], "summary": "MikoPBX 是以 Asterisk 为内核的开源 PBX，提供可在 Web 界面配置的 IVR 菜单、入站呼叫规则和自定义呼叫流程，核心功能免费。", "technology_stack": ["PHP 8.4", "Phalcon 5", "Asterisk 22 LTS", "SQLite", "Nginx"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:176523594','Remotely','{"deployment": ["官方 Docker Compose Quickstart 自托管，Caddy 反向代理", "默认 SQLite，可切换 SQL Server 或 PostgreSQL", ".NET 服务端；agent 覆盖 Windows 与 Linux"], "features": ["终端用户 /get-support 支持请求页，提交后显示在主控制台告警区", "Web 远程控制查看器，提供屏幕查看与键鼠控制", "Quick support 客户端与 Windows 安装器，可按组织品牌化", "EnforceAttendedAccess / RemoteControlNotifyUsers 控制用户同意与会话提示", "远程控制会话录制，区分 server admin 与 organization admin"], "github_repository_id": 176523594, "homepage": "https://github.com/immense/Remotely", "id": "github:176523594", "leaf_matches": [{"reason": "README 的 End User Support Page 说明终端用户可通过 /get-support 提交支持请求，提交后在主控制台出现告警，安装器可放置支持快捷方式；Branding 会应用到 quick support clients 和 Windows 安装器；EnforceAttendedAccess 要求客户端提示用户允许远程控制，RemoteControlNotifyUsers 在会话开始时通知终端用户，EnableRemoteControlRecording 可保存会话录像；Admin Accounts 区分 server admin 与 organization admin。技师经 Web RemoteControl Viewer 发起实时会话，客户侧有支持请求入口、快速支持客户端和同意提示，具备本叶要求的支持交付关系；远程脚本与 RMM 告警不并入核心。", "slug": "remote-customer-support-platform", "source_urls": ["https://raw.githubusercontent.com/immense/Remotely/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/immense/Remotely/license", "name": "Remotely", "repository_url": "https://github.com/immense/Remotely", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:53:43.380866+08:00", "kind": "repository_metadata", "sha256": "a8622bcc14b432426a40d0644b08a8f9aa5cf6c2b42925fa991aa69ba60a9694", "snapshot_path": "sources/a8622bcc14b432426a40d0644b08a8f9aa5cf6c2b42925fa991aa69ba60a9694.txt", "url": "https://api.github.com/repos/immense/Remotely"}, {"fetched_at": "2026-10-26T16:53:51.712672+08:00", "kind": "license", "sha256": "51d78bddc1f112bc6cc035ec0569f2d2921ca30c492cbf7610b88d242a0345e5", "snapshot_path": "sources/51d78bddc1f112bc6cc035ec0569f2d2921ca30c492cbf7610b88d242a0345e5.txt", "url": "https://api.github.com/repos/immense/Remotely/license"}, {"fetched_at": "2026-10-26T16:53:49.817631+08:00", "kind": "readme", "sha256": "4ddde87d6c72fc0c72d146130b5381304de26a302f1a3527bfca2bb838da9c46", "snapshot_path": "sources/4ddde87d6c72fc0c72d146130b5381304de26a302f1a3527bfca2bb838da9c46.txt", "url": "https://raw.githubusercontent.com/immense/Remotely/master/README.md"}], "summary": "Remotely 是 GPL-3.0 开源自托管的远程控制与远程支持应用，提供技师 Web 控制台、终端用户支持请求页、按需快速支持客户端、可强制用户同意的会话、会话录制与客户界面品牌化。", "technology_stack": ["C# / .NET 8", "Blazor", "SignalR Core", "SQLite / SQL Server / PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12063996','osTicket','{"deployment": ["自托管于 IIS 或 Apache Web 服务器", "PHP 8.2–8.4 与 MySQL 5.5+", "通过 git clone 与 manage.php 部署"], "features": ["客户门户集中存档支持请求与回复", "知识库文章供用户自助检索", "网站、邮件、电话多渠道受理工单", "客户以邮箱+工单号或注册账户查看关联工单"], "github_repository_id": 12063996, "homepage": "https://osticket.com/", "id": "github:12063996", "leaf_matches": [{"reason": "README 直接描述用户经网站/邮件/电话建单、工单保存并分配给坐席、坐席回复解决的完整流程，符合服务台核心工单闭环。", "slug": "help-desk", "source_urls": ["https://api.github.com/repos/osTicket/osTicket", "https://api.github.com/repos/osTicket/osTicket/license", "https://raw.githubusercontent.com/osTicket/osTicket/develop/README.md"]}, {"reason": "功能页 Customer Portal 说明所有支持请求与回复对最终用户在线存档，用户可用邮箱加工单号登录或注册账户查看全部关联工单，并可从知识库自助检索；README 说明用户可通过网站、邮件或电话创建工单。自助答案层、客户自主提交与请求人自己的请求记录三项核心齐全。", "slug": "self-service-support-portal", "source_urls": ["https://osticket.com/features/", "https://raw.githubusercontent.com/osTicket/osTicket/develop/README.md"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/osTicket/osTicket/license", "name": "osTicket", "repository_url": "https://github.com/osTicket/osTicket", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:40:04.876553+08:00", "kind": "repository_metadata", "sha256": "f5c6532d305ff2cd18f51cb4308bb29d3f9f7526e8ac8d62ccdc42a118724165", "snapshot_path": "sources/f5c6532d305ff2cd18f51cb4308bb29d3f9f7526e8ac8d62ccdc42a118724165.txt", "url": "https://api.github.com/repos/osTicket/osTicket"}, {"fetched_at": "2026-10-26T16:40:07.124603+08:00", "kind": "license", "sha256": "d8a1c1db5a7d5762f23a42e88234bb539c5a32b685fa045bce6573543858b268", "snapshot_path": "sources/d8a1c1db5a7d5762f23a42e88234bb539c5a32b685fa045bce6573543858b268.txt", "url": "https://api.github.com/repos/osTicket/osTicket/license"}, {"fetched_at": "2026-10-26T16:40:12.509722+08:00", "kind": "documentation", "sha256": "02c7ea8d549fc72a46b3eeba7d26be0ffc1f7f1529ab3eb85eea7c6839d439eb", "snapshot_path": "sources/02c7ea8d549fc72a46b3eeba7d26be0ffc1f7f1529ab3eb85eea7c6839d439eb.txt", "url": "https://osticket.com/features/"}, {"fetched_at": "2026-10-26T16:40:08.623594+08:00", "kind": "readme", "sha256": "a991a329a842522a2750732364dc6abe92f582ae9366421635a3d5ddeeaf7eab", "snapshot_path": "sources/a991a329a842522a2750732364dc6abe92f582ae9366421635a3d5ddeeaf7eab.txt", "url": "https://raw.githubusercontent.com/osTicket/osTicket/develop/README.md"}], "summary": "osTicket 是 GPL-2.0 开源自托管支持工单系统，提供客户门户、知识库自助、网站/邮件/电话请求受理与客户查看自身工单的能力。", "technology_stack": ["PHP 8.2–8.4", "MySQL", "Apache/IIS"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:callminer','CallMiner','{"homepage": "https://callminer.com/", "id": "commercial:callminer", "leaf_matches": [{"reason": "官方 platform 页正文写明 transcriptions 的情感/情绪标记、预置 topics、根因分析、omnichannel customer journey mapping，以及 recorder 的 live monitoring/playback 与 conversation analytics；覆盖服务对话结构化与跨会话洞察两项核心。", "slug": "support-conversation-analytics", "source_urls": ["https://callminer.com/platform/"]}], "name": "CallMiner", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:40:16.366163+08:00", "kind": "documentation", "sha256": "170337b5032be3181c86513f0a92cce548f6b35da93eae0d09d81552065c909f", "snapshot_path": "sources/170337b5032be3181c86513f0a92cce548f6b35da93eae0d09d81552065c909f.txt", "url": "https://callminer.com/platform/"}], "summary": "CallMiner 是商业客服对话分析平台，对通话与文本互动做转录、主题与情感标记，并提供跨会话检索、根因分析、回放与洞察仪表盘。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vitally','Vitally','{"homepage": "https://www.vitally.io/", "id": "commercial:vitally", "leaf_matches": [{"reason": "官方健康评分页展示按账户构建多因子健康分、阈值/权重与预览、健康变化触发动作，符合账户级健康度量与监控循环核心。", "slug": "customer-health-monitoring", "source_urls": ["https://www.vitally.io/features/health-scores"]}], "name": "Vitally", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:03:12.616377+08:00", "kind": "documentation", "sha256": "ee3174bed43f95604e8833704f79f228b17ae12544dd3e72fd1a5651aebec491", "snapshot_path": "sources/ee3174bed43f95604e8833704f79f228b17ae12544dd3e72fd1a5651aebec491.txt", "url": "https://www.vitally.io/features/health-scores"}], "summary": "面向 B2B 客户成功团队的客户健康度监控与客户成功平台。官方健康评分功能页说明可按账户构建多因子健康分，使用特征、指标与互动信号，支持按细分/生命周期阶段配置权重与阈值并预览，健康变化可自动触发邮件、任务和提醒；同时保留账户健康历史与触点记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:guidecx','GUIDEcx','{"homepage": "https://www.guidecx.com/", "id": "commercial:guidecx", "leaf_matches": [{"reason": "官方首页明确为共享客户入职工作区，供应商与客户共同完成任务和里程碑，并跟踪上线与首次价值进展。", "slug": "customer-onboarding-platform", "source_urls": ["https://www.guidecx.com/"]}], "name": "GUIDEcx", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:23.080773+08:00", "kind": "homepage", "sha256": "1e57c0fbe9fdbb1dd1ff19c6e066e644b33ed85c3d7d23145ece29418e3446f6", "snapshot_path": "sources/1e57c0fbe9fdbb1dd1ff19c6e066e644b33ed85c3d7d23145ece29418e3446f6.txt", "url": "https://www.guidecx.com/"}], "summary": "面向 B2B 客户入职的协作平台。官方首页说明其提供供应商与客户共享的入职工作区，双方在同一计划中查看时间线、里程碑、风险与责任并完成各自任务，通过提醒和自动化推动客户参与，跟踪从销售移交到上线/首次价值的进展。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gainsight','Gainsight','{"homepage": "https://www.gainsight.com/", "id": "commercial:gainsight", "leaf_matches": [{"reason": "官方客户成功页展示账户健康记分卡、产品使用/支持/续约/情绪信号聚合及自动工作流，覆盖客户账本、成功画像与关系工作循环。", "slug": "customer-success-platform", "source_urls": ["https://www.gainsight.com/customer-success/"]}], "name": "Gainsight", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:01:45.621133+08:00", "kind": "documentation", "sha256": "4261e21c955a0ebf4f46bbfaef612e83f4bfcf2a52531746b461f5e543a28a7a", "snapshot_path": "sources/4261e21c955a0ebf4f46bbfaef612e83f4bfcf2a52531746b461f5e543a28a7a.txt", "url": "https://www.gainsight.com/customer-success/"}], "summary": "面向经常性收入企业的客户成功平台。官方客户成功产品页说明其把邮件、通话、工单与触点汇入账户级视图，持续生成风险评分、健康记分卡、产品使用、支持历史、续约时间线与利益相关者地图，并据风险/扩展信号自动触发客户成功工作流；同时提供与业务成果关联的成功计划及可重复剧本。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:skilljar','Skilljar','{"homepage": "https://www.skilljar.com/", "id": "commercial:skilljar", "leaf_matches": [{"reason": "官方产品页明确为面向客户的 External LMS，提供品牌化学院、课程/认证、注册与完成记录，符合外部学员培训核心。", "slug": "customer-training-academy-platform", "source_urls": ["https://www.skilljar.com/product/"]}], "name": "Skilljar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:03:17.178156+08:00", "kind": "documentation", "sha256": "5ebe56ea576b7d0012f1d8a84f0059d0946d193f32871e93c8af5495c8875d82", "snapshot_path": "sources/5ebe56ea576b7d0012f1d8a84f0059d0946d193f32871e93c8af5495c8875d82.txt", "url": "https://www.skilljar.com/product/"}], "summary": "面向客户与合作伙伴外部培训的 External LMS。官方产品页说明其提供可品牌化的学院站点、课程与学习路径、直播培训、单点登录、注册与完成记录、证书/认证，并可向 Salesforce/Gainsight 等系统输出学习数据；学习者主体为组织外部客户。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:235901813','PostHog','{"deployment": ["自托管 Docker hobby 部署（README 标称约 10 万事件/月）", "PostHog Cloud 官方托管"], "features": ["事件埋点与自动捕获", "产品分析（趋势/漏斗/留存等）", "分组与多席位账户分析", "会话回放", "功能开关与实验", "问卷与反馈"], "github_repository_id": 235901813, "homepage": "https://posthog.com/", "id": "github:235901813", "leaf_matches": [{"reason": "README 与仓库元数据表明其通过事件埋点、自动捕获与分组分析度量真实用户及多席位账户的产品使用，符合产品使用/采纳平台核心；开源核心为 MIT Expat（ee/ 除外）。", "slug": "product-usage-adoption-platform", "source_urls": ["https://raw.githubusercontent.com/PostHog/posthog/master/README.md", "https://api.github.com/repos/PostHog/posthog"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/PostHog/posthog/license", "license_review": {"rationale": "仓库 LICENSE 明确 ee/ 目录外内容采用 MIT Expat 许可，ee/ 目录及第三方组件另有许可；此处仅将开源核心标注为 MIT，企业目录不纳入开源范围。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "community_core", "source_url": "https://api.github.com/repos/PostHog/posthog/license", "spdx_id": "MIT"}, "name": "PostHog", "repository_url": "https://github.com/PostHog/posthog", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:01:35.994130+08:00", "kind": "repository_metadata", "sha256": "8c5f1418896849d6f47bf990ef6954bdf215100bf9bb168b7545018b9106a095", "snapshot_path": "sources/8c5f1418896849d6f47bf990ef6954bdf215100bf9bb168b7545018b9106a095.txt", "url": "https://api.github.com/repos/PostHog/posthog"}, {"fetched_at": "2026-10-26T17:01:37.692809+08:00", "kind": "license", "sha256": "95579ca52f21b70af37e72386d4ac193b412fa11566a675f6e979709195798d1", "snapshot_path": "sources/95579ca52f21b70af37e72386d4ac193b412fa11566a675f6e979709195798d1.txt", "url": "https://api.github.com/repos/PostHog/posthog/license"}, {"fetched_at": "2026-10-26T17:01:39.286219+08:00", "kind": "readme", "sha256": "738e40fc476ba820d91c17965b54141f9c243006b077b0607d885349ae85fd51", "snapshot_path": "sources/738e40fc476ba820d91c17965b54141f9c243006b077b0607d885349ae85fd51.txt", "url": "https://raw.githubusercontent.com/PostHog/posthog/master/README.md"}], "summary": "开源核心的产品分析与产品采用度量平台（仓库为 MIT Expat，ee/ 目录与第三方组件除外）。通过自动捕获或手动埋点采集真实用户事件，提供产品分析可视化、SQL 查询与分组/多席位账户分析，并附带会话回放、功能开关、实验和问卷；可自托管 Docker hobby 实例或使用 PostHog Cloud。", "technology_stack": ["Python", "TypeScript", "React"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gullysystem','GullySystem','{"homepage": "https://www.gullysystem.com/", "id": "commercial:gullysystem", "leaf_matches": [{"reason": "官方产品页明确以客户文件组织多家承保人的保单，覆盖询价、出单、批改、续保、理赔与佣金对账，属于保险经纪的出单账簿与续保生命周期管理。", "slug": "broker-management-platform", "source_urls": ["https://www.gullysystem.com/product/insurance-broker-management-software"]}], "name": "GullySystem", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:56.145174+08:00", "kind": "documentation", "sha256": "9b93d4f06c45ef146e9e8e52803bf781401fc882da1c9d4d9b69ad9e53d4ffe2", "snapshot_path": "sources/9b93d4f06c45ef146e9e8e52803bf781401fc882da1c9d4d9b69ad9e53d4ffe2.txt", "url": "https://www.gullysystem.com/product/insurance-broker-management-software"}], "summary": "面向保险经纪公司的客户档案、向多家承保人询价、出单与保单、批单、续保、理赔和佣金对账平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:xactware','Xactware (Verisk)','{"homepage": "https://www.xactware.com/", "id": "commercial:xactware", "leaf_matches": [{"reason": "官方页面围绕财产索赔从 FNOL 到修复的处理链条，提供 Xactimate 损失估算、XactAnalysis 分派/工作流/质检和 ClaimXperience 协作，匹配理算师的损失评估、估价、审查与结算工作台。", "slug": "claims-adjuster-platform", "source_urls": ["https://www.xactware.com/home/"]}], "name": "Xactware (Verisk)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:37.721077+08:00", "kind": "homepage", "sha256": "f2114459237e814da7fd3eb6bf43dd44a15dc906d008ee6d5a6094c53103de51", "snapshot_path": "sources/f2114459237e814da7fd3eb6bf43dd44a15dc906d008ee6d5a6094c53103de51.txt", "url": "https://www.xactware.com/home/"}], "summary": "财产理赔估算与流程套件：Xactimate 估算、XactAnalysis 任务分派与质检、XactContents 物品估算、ClaimXperience 从 FNOL 到解决的协作。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hawksoft','HawkSoft','{"homepage": "https://www.hawksoft.com/", "id": "commercial:hawksoft", "leaf_matches": [{"reason": "官方 AMS 页面明确提供客户与个人/商业险保单管理、续保提醒、承运商下载、佣金对账与信托会计，构成代理机构对已出单账簿的记录与续保驱动工作流。", "slug": "insurance-agency-management", "source_urls": ["https://www.hawksoft.com/agency-management-system/"]}], "name": "HawkSoft", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:25.266657+08:00", "kind": "documentation", "sha256": "c9a9e264531f9b7dc678af43cbddffd4408bb24dafa3af36a4c8ffe7bc64ecc2", "snapshot_path": "sources/c9a9e264531f9b7dc678af43cbddffd4408bb24dafa3af36a4c8ffe7bc64ecc2.txt", "url": "https://www.hawksoft.com/agency-management-system/"}], "summary": "面向独立保险代理机构的代理管理系统（AMS），覆盖客户与保单记录、续保提醒、承运商下载、佣金对账与信托会计。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:guidewire-claimcenter','Guidewire ClaimCenter','{"homepage": "https://www.guidewire.com/", "id": "commercial:guidewire-claimcenter", "leaf_matches": [{"reason": "官方产品页说明其管理从 FNOL 到结算的完整理赔生命周期，支持理赔受理、保单检索、角色化工作流与任务，面向保险公司理赔组织，匹配支付方理赔系统记录。", "slug": "insurance-claims-management", "source_urls": ["https://www.guidewire.com/products/core-products/insurancesuite/claimcenter-claims-management-software"]}], "name": "Guidewire ClaimCenter", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:25.226506+08:00", "kind": "documentation", "sha256": "328942467e2eb17cdef1d39c8f16fafa5a9216923d673ad9114d21fbe1698625", "snapshot_path": "sources/328942467e2eb17cdef1d39c8f16fafa5a9216923d673ad9114d21fbe1698625.txt", "url": "https://www.guidewire.com/products/core-products/insurancesuite/claimcenter-claims-management-software"}], "summary": "面向 P&C 保险公司的理赔管理系统，覆盖从 First Notice of Loss 到结算的理赔生命周期、保单检索、角色化工作流与任务管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1255299527','LatticePolicy','{"deployment": ["Docker Compose 本地部署", "AWS ECS 部署示例"], "features": ["多租户保单生命周期 API", "报价、核保复核、评级、绑定、签发、批改、取消、恢复与续保", "内部运营界面与客户门户", "产品包与租户配置"], "github_repository_id": 1255299527, "homepage": "https://github.com/kishorjakkula/LatticePolicy", "id": "github:1255299527", "leaf_matches": [{"reason": "仓库 README 明确覆盖报价、核保、评级、绑定、签发、批改、取消、恢复与续保等保单生命周期，并提供运营 UI、客户门户和 Docker 部署；Apache-2.0 已由许可证 API 与正文核对，匹配保险公司侧保单主记录与生命周期管理。", "slug": "insurance-policy-administration-system", "source_urls": ["https://api.github.com/repos/kishorjakkula/LatticePolicy", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/README.md"]}, {"reason": "仓库文档与源码显示：提交（submission）作为独立案件被摄取、结构化并按运营商配置的承保规则（evaluateUW，Eligible/Refer/Decline，含 reason）判定；Refer 会生成可指派、可评论、须由具备权限的核保人决定的 referral 记录并阻断绑定；授权额度（authority grants）超限自动转介；决定连同依据、作出人与时间写入记录，随后同一平台执行报价/绑定/签发。这覆盖“风险提交→按偏好评估→记录承保决定（接受/拒绝/转介）并交下游出单”的核心结构，且为 Apache-2.0 完整开源应用（Docker 自托管）。", "slug": "underwriting-workbench", "source_urls": ["https://api.github.com/repos/kishorjakkula/LatticePolicy", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/README.md", "https://api.github.com/repos/kishorjakkula/LatticePolicy/license", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/SUBMISSION_INTAKE.md", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/issue-50-underwriting-referral-workflow.md", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/admin-underwriting-rules-engine.md", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/issue-316-underwriting-authority.md", "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/server/src/services/uw.service.ts"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/kishorjakkula/LatticePolicy/license", "name": "LatticePolicy", "repository_url": "https://github.com/kishorjakkula/LatticePolicy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:54:10.342152+08:00", "kind": "repository_metadata", "sha256": "0d8cb4111228bdcaa5888d6a99934f2193eaafa6a84a920b2192259a3161cefc", "snapshot_path": "sources/0d8cb4111228bdcaa5888d6a99934f2193eaafa6a84a920b2192259a3161cefc.txt", "url": "https://api.github.com/repos/kishorjakkula/LatticePolicy"}, {"fetched_at": "2026-10-26T17:02:37.475322+08:00", "kind": "repository_metadata", "sha256": "79cc4d82ffdd4d6f2832272c17c9f267b334591d35cb6492d243579f0cef9be9", "snapshot_path": "sources/79cc4d82ffdd4d6f2832272c17c9f267b334591d35cb6492d243579f0cef9be9.txt", "url": "https://api.github.com/repos/kishorjakkula/LatticePolicy"}, {"fetched_at": "2026-10-26T17:02:37.539266+08:00", "kind": "license", "sha256": "5ff04f32fc3528b1008a532ed2a16a4c57baf5e5acf3994439056366d5a44dcd", "snapshot_path": "sources/5ff04f32fc3528b1008a532ed2a16a4c57baf5e5acf3994439056366d5a44dcd.txt", "url": "https://api.github.com/repos/kishorjakkula/LatticePolicy/license"}, {"fetched_at": "2026-10-26T17:02:37.074175+08:00", "kind": "readme", "sha256": "c4a2f31ffe45e9c8de29323c2f42f93a11ac1cc04f3915928898ca26cfa45b2b", "snapshot_path": "sources/c4a2f31ffe45e9c8de29323c2f42f93a11ac1cc04f3915928898ca26cfa45b2b.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/README.md"}, {"fetched_at": "2026-10-28T15:55:14.255552+08:00", "kind": "documentation", "sha256": "68ad64854434dbc4baace6acc8e29e11dc1adb491f97f80899da4b67e44cb4cf", "snapshot_path": "sources/68ad64854434dbc4baace6acc8e29e11dc1adb491f97f80899da4b67e44cb4cf.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/SUBMISSION_INTAKE.md"}, {"fetched_at": "2026-10-28T15:56:19.909198+08:00", "kind": "documentation", "sha256": "0a8d634706feb4b0de12952ef43b016d8743d94735f99d39459c0df8d484c471", "snapshot_path": "sources/0a8d634706feb4b0de12952ef43b016d8743d94735f99d39459c0df8d484c471.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/admin-underwriting-rules-engine.md"}, {"fetched_at": "2026-10-28T15:56:48.962081+08:00", "kind": "documentation", "sha256": "8197f98abb2884c6c06bb75ebaeafdecab142b230b37b550a80377cf8d5bf86b", "snapshot_path": "sources/8197f98abb2884c6c06bb75ebaeafdecab142b230b37b550a80377cf8d5bf86b.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/issue-316-underwriting-authority.md"}, {"fetched_at": "2026-10-28T15:55:16.157483+08:00", "kind": "documentation", "sha256": "0bab5bb10a2aba5a726f201df043c22a84d6bafffe3e14babcb675e2cc491d54", "snapshot_path": "sources/0bab5bb10a2aba5a726f201df043c22a84d6bafffe3e14babcb675e2cc491d54.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/docs/tasks/issue-50-underwriting-referral-workflow.md"}, {"fetched_at": "2026-10-28T15:59:54.054407+08:00", "kind": "documentation", "sha256": "068916be6e09a4b6c2c69850f6de73674ed7474ece4ca6c0efe386ab73f2d737", "snapshot_path": "sources/068916be6e09a4b6c2c69850f6de73674ed7474ece4ca6c0efe386ab73f2d737.txt", "url": "https://raw.githubusercontent.com/kishorjakkula/LatticePolicy/main/server/src/services/uw.service.ts"}], "summary": "开源 P&C 保单管理与核保框架，覆盖报价、核保、评级、绑定、签发、批改、取消、恢复与续保，含运营界面、客户门户和 Docker 部署。", "technology_stack": ["React", "Node.js", "PostgreSQL", "Redis", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:kalepa','Kalepa','{"homepage": "https://kalepa.com/", "id": "commercial:kalepa", "leaf_matches": [{"reason": "官方首页把承保流程列为 Submission Ingestion、Clearance、Triage、Risk Analysis、Rating、Quote & Bind，并展示 Preferred/Refer/Decline 结果与 referral guidance；Carriers 页明示其为 AI underwriting platform，能处理更多 submission 并形成 decision-ready quotes。这构成“风险提交→按偏好评估→记录报价/绑定或转介/拒绝决定”的核心。", "slug": "insurance-underwriting-platform", "source_urls": ["https://kalepa.com/", "https://kalepa.com/solutions/carriers/"]}, {"reason": "官方首页把承保流程列为提交摄取、清分、分诊、风险分析、评级、Quote & Bind，并在同一承保界面展示 Preferred/Refer/Decline 状态与 referral guidance；Quote & Bind 页说明在“single workspace”内完成报价到绑定的流转并回写既有核心系统。据此记录其作为承保决策工作台的基本类型关系，不主张其持有保单主记录或承担出单。", "slug": "underwriting-workbench", "source_urls": ["https://kalepa.com/", "https://kalepa.com/platforms/quote-bind"]}], "name": "Kalepa", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:51.198963+08:00", "kind": "homepage", "sha256": "705f6873e8b2e079ed6952494903d9f425b55d56b5958e92fdb727f4ddb8a6ec", "snapshot_path": "sources/705f6873e8b2e079ed6952494903d9f425b55d56b5958e92fdb727f4ddb8a6ec.txt", "url": "https://kalepa.com/"}, {"fetched_at": "2026-10-28T15:56:01.198159+08:00", "kind": "documentation", "sha256": "8f0187b14d270c4f2ae1e9b9addddad411bef82225f19690685f5b27d05912aa", "snapshot_path": "sources/8f0187b14d270c4f2ae1e9b9addddad411bef82225f19690685f5b27d05912aa.txt", "url": "https://kalepa.com/platforms/quote-bind"}, {"fetched_at": "2026-10-26T17:02:34.322417+08:00", "kind": "documentation", "sha256": "75fdfc2c6ed1378113116d1c7498393b60c010ae8ecb4cf6a5395b963d479fd0", "snapshot_path": "sources/75fdfc2c6ed1378113116d1c7498393b60c010ae8ecb4cf6a5395b963d479fd0.txt", "url": "https://kalepa.com/solutions/carriers/"}], "summary": "面向财产险承运人的 AI 核保平台，覆盖提交接收、清分、分诊、风险分析、评级、报价与绑定，并保留转介/拒绝等承保路由。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:duck-creek-reinsurance','Duck Creek Reinsurance','{"homepage": "https://www.duckcreek.com/", "id": "commercial:duck-creek-reinsurance", "leaf_matches": [{"reason": "官方产品页明示其为 reinsurance management software，覆盖 ceded/assumed 全生命周期；正文列出 treaties、facultative、ceded/assumed/retroceded、proportional/non-proportional、分层、续期、理赔追偿及 premiums/claims/commissions 的多币种会计，构成“协议→业务分入/分出→对手方财务循环”的核心。", "slug": "reinsurance-management-system", "source_urls": ["https://www.duckcreek.com/product/reinsurance/"]}], "name": "Duck Creek Reinsurance", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:32.757445+08:00", "kind": "documentation", "sha256": "a0a6a3c4a6626d139db4bf9d1fcf31aef5542d70e4b4fdc8600257c9129fbd22", "snapshot_path": "sources/a0a6a3c4a6626d139db4bf9d1fcf31aef5542d70e4b4fdc8600257c9129fbd22.txt", "url": "https://www.duckcreek.com/product/reinsurance/"}], "summary": "面向保险公司与再保险人的再保险管理平台，集中管理合约/临分、分出与分入业务、理赔追偿、续期以及再保险会计结算。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:blackline-account-reconciliation','BlackLine Account Reconciliation','{"homepage": "https://www.blackline.com/", "id": "commercial:blackline-account-reconciliation", "leaf_matches": [{"reason": "官方产品页明确面向 account reconciliation，正文与 FAQ 可证总账余额与银行/子账等支撑来源的比对、reconciling items 的查看与起草、低风险对账自动认证、人工最终复核，以及记录 who did what 的审计轨迹；符合“双边比较→差异处理→归责签核”的核心。", "slug": "account-reconciliation-platform", "source_urls": ["https://www.blackline.com/products/financial-close/account-reconciliations/"]}], "name": "BlackLine Account Reconciliation", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:43.784941+08:00", "kind": "documentation", "sha256": "0255893a271b29eaecfaa3d8745716456af2d13090f2a26e7b25f1b2f1a9925d", "snapshot_path": "sources/0255893a271b29eaecfaa3d8745716456af2d13090f2a26e7b25f1b2f1a9925d.txt", "url": "https://www.blackline.com/products/financial-close/account-reconciliations/"}], "summary": "面向会计与财务团队的账户对账软件，支持总账余额与银行/子账等支撑来源比对、调节项处理、低风险自动认证、人工复核和审计轨迹。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1335844694','OpenActuary','{"deployment": ["Docker Compose 全栈启动（api、worker、web、infra）", "hybrid 模式：基础设施运行于 Docker，API/Web/worker 本地运行", "no-docker 模式：使用自备的 PostgreSQL 与 Redis", "Kubernetes Helm charts"], "features": ["可视化模型构建器：拖拽 data→features→models→explainability→rating/deploy→governance 组件，并编译为可执行 Python", "项目工作区统一管理模型、notebook、rating plans、数据连接与治理记录", "数据连接器与项目内数据探查，支持数据库、API、文件及保单管理系统等来源", "orchestrator 负责 canvas→Python 编译与运行，独立 scoring API 提供结果/评分端点", "治理与合规工作流、审批记录、部署、drift 与 rate tables"], "github_repository_id": 1335844694, "homepage": "https://openactuary.io/", "id": "github:1335844694", "leaf_matches": [{"reason": "官方 README 与 CURRENT_STATE 可证其为精算建模平台：可视化 canvas 定义 model pipeline 并编译为 Python，Projects 管理模型与数据连接，orchestrator 执行模型，scoring API/部署输出结果；覆盖“用户定义模型 + 结构化数据 + 受控运行 + 可分析结果”。已读实现快照未明确展示版本化 assumption 对象，故不把该细节写入关系理由。", "slug": "actuarial-modeling-platform", "source_urls": ["https://raw.githubusercontent.com/openactuary-io/openactuary/main/README.md", "https://raw.githubusercontent.com/openactuary-io/openactuary/main/CURRENT_STATE.md", "https://api.github.com/repos/openactuary-io/openactuary"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/openactuary-io/openactuary/license", "name": "OpenActuary", "repository_url": "https://github.com/openactuary-io/openactuary", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:41.923525+08:00", "kind": "repository_metadata", "sha256": "d63491eb626dadef3f583c366b05e1f94b9933f04fe34c253f221ab6c4aa4a1a", "snapshot_path": "sources/d63491eb626dadef3f583c366b05e1f94b9933f04fe34c253f221ab6c4aa4a1a.txt", "url": "https://api.github.com/repos/openactuary-io/openactuary"}, {"fetched_at": "2026-10-26T17:02:51.184985+08:00", "kind": "license", "sha256": "77ec4d66d06dac837ab1fec039717a70e63ca99aeca4c1633cdad113bcc412d3", "snapshot_path": "sources/77ec4d66d06dac837ab1fec039717a70e63ca99aeca4c1633cdad113bcc412d3.txt", "url": "https://api.github.com/repos/openactuary-io/openactuary/license"}, {"fetched_at": "2026-10-26T17:02:53.947996+08:00", "kind": "readme", "sha256": "ae5f033e323cd0cc68d73edf59a848340d7f1adffb9073e4b4a3ba9bbd4e292c", "snapshot_path": "sources/ae5f033e323cd0cc68d73edf59a848340d7f1adffb9073e4b4a3ba9bbd4e292c.txt", "url": "https://raw.githubusercontent.com/openactuary-io/openactuary/main/README.md"}, {"fetched_at": "2026-10-26T17:03:12.217887+08:00", "kind": "documentation", "sha256": "e71fb0a0e8fcf117d773ed0854525a1a6a206164250b7e3da911a4235096c49b", "snapshot_path": "sources/e71fb0a0e8fcf117d773ed0854525a1a6a206164250b7e3da911a4235096c49b.txt", "url": "https://raw.githubusercontent.com/openactuary-io/openactuary/main/CURRENT_STATE.md"}, {"fetched_at": "2026-10-26T17:05:52.468788+08:00", "kind": "documentation", "sha256": "125fc326eb6fd51ed5ee9ed6f35b17aa064cf26b7da236a7513e3b0bd7519e27", "snapshot_path": "sources/125fc326eb6fd51ed5ee9ed6f35b17aa064cf26b7da236a7513e3b0bd7519e27.txt", "url": "https://raw.githubusercontent.com/openactuary-io/openactuary/main/docs/openactuary-complete-spec.md"}], "summary": "开源保险精算建模平台，提供可视化模型构建器、项目工作区、数据连接器、编排运行与评分/部署；平台核心采用 AGPL-3.0，SDK 采用 Apache-2.0。", "technology_stack": ["Python 3.12、FastAPI、SQLAlchemy 2.0、Celery", "React 18、TypeScript、Vite、ReactFlow", "PostgreSQL 16 + pgvector、DuckDB、Redis 7、MinIO、Meilisearch", "Docker Compose、Kubernetes/Helm"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:91629816','Freqtrade','{"deployment": ["官方 Docker Quickstart 容器部署", "原生安装（Windows、macOS、Linux）"], "features": ["Python 策略编写与参数优化，含 hyperopt 与 FreqAI 自适应/机器学习建模", "基于历史数据的 backtesting、数据下载、绘图与绩效分析", "Dry-run 模拟交易与通过交易所连接执行交易", "内置 WebUI 与 Telegram 控制，可查看/强制退出交易、查看余额与绩效", "SQLite 持久化交易与运行状态"], "github_repository_id": 91629816, "homepage": "https://www.freqtrade.io/", "id": "github:91629816", "leaf_matches": [{"reason": "README 明示其为开源加密货币交易机器人：用户以 Python 编写策略，平台可下载历史数据并 backtesting/hyperopt，支持 Dry-run 与交易所交易，并通过 WebUI/Telegram 查看、停止或强制退出交易；构成“可执行策略→市场数据→订单/头寸→持续管理”的循环。", "slug": "algorithmic-trading-platform", "source_urls": ["https://raw.githubusercontent.com/freqtrade/freqtrade/develop/README.md", "https://api.github.com/repos/freqtrade/freqtrade"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/freqtrade/freqtrade/license", "name": "Freqtrade", "repository_url": "https://github.com/freqtrade/freqtrade", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:02:41.939038+08:00", "kind": "repository_metadata", "sha256": "47f2eb01c640b19652ef839df7ff0429207a9832edc20e0402d948969c08a9be", "snapshot_path": "sources/47f2eb01c640b19652ef839df7ff0429207a9832edc20e0402d948969c08a9be.txt", "url": "https://api.github.com/repos/freqtrade/freqtrade"}, {"fetched_at": "2026-10-26T17:02:51.750959+08:00", "kind": "license", "sha256": "3985eb5e18ca9df2d26962144027516e1cfd969b8083cdac497ddad1fad3268a", "snapshot_path": "sources/3985eb5e18ca9df2d26962144027516e1cfd969b8083cdac497ddad1fad3268a.txt", "url": "https://api.github.com/repos/freqtrade/freqtrade/license"}, {"fetched_at": "2026-10-26T17:02:53.224286+08:00", "kind": "readme", "sha256": "119d586166ae397b05f9763caf7f90e2d27792f90c8455c04ac3455e14a40d89", "snapshot_path": "sources/119d586166ae397b05f9763caf7f90e2d27792f90c8455c04ac3455e14a40d89.txt", "url": "https://raw.githubusercontent.com/freqtrade/freqtrade/develop/README.md"}], "summary": "开源加密货币算法交易机器人：用户以 Python 编写策略，平台完成历史回测、参数/机器学习优化、模拟或实盘交易，并通过 WebUI/Telegram 管理运行中的交易与头寸。", "technology_stack": ["Python 3.12+", "SQLite 持久化", "内置 WebUI（FreqUI）与 Telegram 控制面", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:planful','Planful','{"homepage": "https://planful.com", "id": "commercial:planful", "leaf_matches": [{"reason": "官方解决方案与平台页说明其以单一财务模型承载实际数、假设和计划，覆盖预算、预测、差异、合并和报告，符合预算与预测平台的定义性核心。", "slug": "budgeting-forecasting-platform", "source_urls": ["https://planful.com/solutions/", "https://planful.com/platform/"]}, {"reason": "官方页面说明 Planful 用于 plan、budget、forecast、consolidate、report，并把 actuals、assumptions、plans 放在同一财务模型中；页面同时连接 close、consolidation、reporting，并描述 headcount 的 managers propose/finance approve、budget 对 committed spend/results 等受管规划流程。匹配同一模型内的计划/实际/假设、受管规划周期与关账合并报告衔接的核心。", "slug": "financial-planning-analysis-platform", "source_urls": ["https://planful.com/solutions/"]}], "name": "Planful", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:09:08.294808+08:00", "kind": "documentation", "sha256": "f6aa0cbe6ab9b580020efecd077175bec59849a26e212d9a99bb571954168498", "snapshot_path": "sources/f6aa0cbe6ab9b580020efecd077175bec59849a26e212d9a99bb571954168498.txt", "url": "https://planful.com/solutions/"}, {"fetched_at": "2026-10-26T17:10:08.610549+08:00", "kind": "documentation", "sha256": "e3fc1357ff04f1e40381956883a84ba51fda1269695a5a45db072b7d8222ffca", "snapshot_path": "sources/e3fc1357ff04f1e40381956883a84ba51fda1269695a5a45db072b7d8222ffca.txt", "url": "https://planful.com/platform/"}], "summary": "面向财务团队的商业 FP&A 平台：官方页面称其在单一财务模型中保存 actuals、assumptions 与 plans，覆盖预算、预测、差异分析、合并与报告，并支持多团队在同一模型内按各自口径编制计划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
