INSERT INTO "application" VALUES('commercial:trust-and-will','Trust & Will','{"homepage": "https://trustandwill.com", "id": "commercial:trust-and-will", "leaf_matches": [{"reason": "官方首页说明其在线创建并持续维护州特定的遗嘱/可撤销生前信托，指定监护人、受托人与受益人，并要求签署、见证、公证使其生效，核心匹配生前遗产规划应用。", "slug": "estate-planning-application", "source_urls": ["https://trustandwill.com/"]}], "name": "Trust & Will", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:09:08.642545+08:00", "kind": "homepage", "sha256": "7bd7ea3329d6b74e246ac6fd9b44579c16bcc6e14ad1bc394e497c0d56f78d1b", "snapshot_path": "sources/7bd7ea3329d6b74e246ac6fd9b44579c16bcc6e14ad1bc394e497c0d56f78d1b.txt", "url": "https://trustandwill.com/"}], "summary": "面向消费者的在线遗产规划服务：官方页面提供州特定的遗嘱与可撤销生前信托、监护人与受益人指定，并衔接签署、见证和公证步骤；自身声明不提供法律意见。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
