INSERT INTO "application" VALUES('commercial:starcompliance','StarCompliance','{"homepage": "https://www.starcompliance.com/", "id": "commercial:starcompliance", "leaf_matches": [{"reason": "官方页面列出个人账户交易预审与交易后监控、加密交易、私人投资/外部活动/礼品申报、公司交易 surveillance、MNPI 控制室与限制名单、培训认证等，形成受监管金融机构可审查的合规活动记录。", "slug": "financial-compliance-management", "source_urls": ["https://www.starcompliance.com/compliance-solutions/"]}], "name": "StarCompliance", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:10:12.479195+08:00", "kind": "documentation", "sha256": "b9b7653805496e5d36146dc5e97e66c6a47b2220058fab7a661e8bb0163515eb", "snapshot_path": "sources/b9b7653805496e5d36146dc5e97e66c6a47b2220058fab7a661e8bb0163515eb.txt", "url": "https://www.starcompliance.com/compliance-solutions/"}], "summary": "面向金融服务机构的员工与公司合规管理平台，覆盖个人账户交易预审/交易后监控、礼品与外部活动申报、利益冲突与 MNPI 控制、公司交易监控及培训认证。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:onestream','OneStream','{"homepage": "https://onestream.com/", "id": "commercial:onestream", "leaf_matches": [{"reason": "官方平台页的 Financial Close & Consolidations 段列出合并引擎覆盖 accounts、currencies、ownership 与 automated intercompany eliminations，并支持 adjustments、audit trails、从报表 drill down/drill back 到交易明细；官方专页补充跨实体合并、intercompany eliminations、currency translations、收购管理与合并报表；官方 Consolidation 文档给出从 base level Entities 沿 hierarchy 汇总到 Parent 的计算链（LOCAL→TRANSLATED→SHARE 按 % Consolidation→ELIMINATION→OWNERPOSTADJ→TOP），Consolidation Dimension 文档说明该层级从本币滚到贡献给 parent 的最终数字并涵盖 translation、share、elimination、adjustment（Journal）。共同支撑集团结构、实体数据、换算/抵消/调整到合并报表的核心。", "slug": "financial-consolidation-platform", "source_urls": ["https://www.onestream.com/platform/", "https://www.onestream.com/solutions/financial-close-and-consolidation-software/", "https://documentation.onestream.com/docs/Content/Design%20and%20Reference/Financial%20Model%20Guides/Consolidation.html", "https://documentation.onestream.com/docs/Content/Design%20and%20Reference/Cube/Consolidation%20Dimension.html"]}], "name": "OneStream", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:10:12.645762+08:00", "kind": "documentation", "sha256": "8750820020900e5dfdedbe9929a33577c529e6bc3d192754381543cc279d6c7c", "snapshot_path": "sources/8750820020900e5dfdedbe9929a33577c529e6bc3d192754381543cc279d6c7c.txt", "url": "https://www.onestream.com/platform/"}, {"fetched_at": "2026-10-26T17:18:37.542497+08:00", "kind": "documentation", "sha256": "d35ee2f23ba8184fcf84b7bab0d800409160147c6cda449577ab15834acb80a7", "snapshot_path": "sources/d35ee2f23ba8184fcf84b7bab0d800409160147c6cda449577ab15834acb80a7.txt", "url": "https://www.onestream.com/solutions/financial-close-and-consolidation-software/"}, {"fetched_at": "2026-10-26T17:19:48.795191+08:00", "kind": "documentation", "sha256": "d7734c4351ff8ebf26460c821a4a8e4482d54eeacef7f84fa70e2be87f20ee41", "snapshot_path": "sources/d77