INSERT INTO "application" VALUES('github:12776324','frePPLe','{"deployment": ["Docker 社区版容器", "Ubuntu .deb 包（README 标注 deprecated）", "源码压缩包"], "features": ["统计需求预测与分层预测审核（物料、地点、客户、时间）", "多地点供应网络与生产计划建模（供应商到成品）", "受约束/非受约束生产计划与排程（APS）", "计划员在甘特图中调整计划，经 Odoo 连接器发布制造/采购订单"], "github_repository_id": 12776324, "homepage": "https://frepple.com", "id": "github:12776324", "leaf_matches": [{"reason": "README 与官方功能文档明确其覆盖需求预测、多地点供应网络建模、生产计划/排程，并可在甘特图中调整计划、经 Odoo 连接器发布制造/采购订单，匹配供应链计划平台的需求→供应计划→下达核心。", "slug": "supply-chain-planning-platform", "source_urls": ["https://raw.githubusercontent.com/frePPLe/frepple/master/README.md", "https://raw.githubusercontent.com/frePPLe/frepple/master/doc/features.rst"]}, {"reason": "官方功能文档明确其以需求为输入生成受约束/非受约束生产计划与排程，支持计划员在甘特图调整，并经 Odoo 连接器发布制造与采购订单，匹配供应计划核心；运输/调拨细节未展开。", "slug": "supply-planning", "source_urls": ["https://raw.githubusercontent.com/frePPLe/frepple/master/doc/features.rst"]}, {"reason": "README 明确定位 advanced planning and scheduling；features.rst 描述有限产能约束、资源瓶颈、前后向排程、约束/非约束计划以及甘特图调整，匹配 APS 的操作级有限产能排程核心。", "slug": "advanced-planning-scheduling-aps", "source_urls": ["https://raw.githubusercontent.com/frePPLe/frepple/master/README.md", "https://raw.githubusercontent.com/frePPLe/frepple/master/doc/features.rst"]}, {"reason": "需求预测、库存净算、BOM/工艺路线、分时段计划订单与计划员甘特调整构成生产计划主链；连接器可把计划发布为生产/采购订单。产品同时含详细排程，关系不覆盖车间执行。", "slug": "production-planning", "source_urls": ["https://raw.githubusercontent.com/frePPLe/frepple/master/README.md", "https://raw.githubusercontent.com/frePPLe/frepple/master/doc/features.rst"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/frePPLe/frepple/master/COPYING", "license_review": {"rationale": "COPYING 明确说明双许可：社区版可按 MIT 使用，企业版需向 frePPLe bv 购买；README 同样区分 Community、Enterprise 与 Cloud Edition。MIT 许可文本标记完整，故仅将 MIT 限定于社区核心。", "reviewer": "collection curator", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/frePPLe/frepple/master/COPYING", "spdx_id": "MIT"}, "name": 