INSERT INTO "application" VALUES('commercial:concord-contract','Concord','{"homepage": "https://www.concord.app", "id": "commercial:concord-contract", "leaf_matches": [{"reason": "官网正文说明合同从 intake 到 renewal 在同一平台集中管理，并含截止日期提醒、自助 intake、redlining/版本控制、评论与电子签名，匹配业务合同管理的受管记录、生命周期与时间型管理核心。", "slug": "business-contract-administration", "source_urls": ["https://www.concord.app/"]}], "name": "Concord", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T21:38:49.680319+08:00", "kind": "homepage", "sha256": "ea700100a882112f880c22b4b502f52bdd93cab433fdcd6e127cf904916276d4", "snapshot_path": "sources/ea700100a882112f880c22b4b502f52bdd93cab433fdcd6e127cf904916276d4.txt", "url": "https://www.concord.app/"}], "summary": "商业合同管理与 CLM 平台，覆盖合同从 intake 到续约的集中管理、期限提醒、协作修订与电子签名。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1957456','Dolibarr ERP CRM','{"deployment": ["官方 README 提供自托管、Docker 与打包安装说明"], "features": ["联系人与供应商管理", "报价、订单、发票与支付", "库存与仓库管理", "项目与任务管理", "会计与银行账户管理"], "github_repository_id": 1957456, "homepage": "https://www.dolibarr.org", "id": "github:1957456", "leaf_matches": [{"reason": "官方 README 说明它是同一套开源 ERP/CRM 软件包，模块覆盖联系人/供应商、报价/订单/发票、库存、项目任务与会计；仓库元数据（id 1957456）与 GPL-3.0 许可证证实身份和许可。功能跨度覆盖销售、资金与工作组织三极，且为同一产品而非外部同步拼接，匹配业务管理套件核心。", "slug": "business-management-suite", "source_urls": ["https://api.github.com/repos/Dolibarr/dolibarr", "https://api.github.com/repos/Dolibarr/dolibarr/license", "https://raw.githubusercontent.com/Dolibarr/dolibarr/develop/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/Dolibarr/dolibarr/license", "name": "Dolibarr ERP CRM", "repository_url": "https://github.com/Dolibarr/dolibarr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:13:00.000000+08:00", "kind": "repository_metadata", "sha256": "641a013f7f2df5d984e93b94214583bcdf14be57f9c7355272e37cf60def0523", "snapshot_path": "sources/641a013f7f2df5d984e93b94214583bcdf14be57f9c7355272e37cf60def0523.txt", "url": "https://api.github.com/repos/Dolibarr/dolibarr"}, {"fetched_at": "2026-10-24T21:44:59.483962+08:00", "kind": "license", "sha256": "4be3677b4080aefefb34d33aaa08767b302334dbda48f9cff59c0c09feac1722", "snapshot_path": "sources/4be3677b4080aefefb34d33aaa08767b302334dbda48f9cff59c0c09feac1722.txt", "url": "https://api.github.com/repos/Dolibarr/dolibarr/license"}, {"fetched_at": "2026-10-26T17:28:20.354744+08:00", "kind": "readme", "sha256": "48b8c3ec01b01cca3dd9b8393a3bb92437af08fbdd2563aa80a796abae0b20e2", "snapshot_path": "sources/48b8c3ec01b01cca3dd9b8393a3bb92437af08fbdd2563aa80a796abae0b20e2.txt", "url": "https://raw.githubusercontent.com/Dolibarr/dolibarr/develop/README.md"}], "summary": "开源 ERP/CRM 业务管理套件，在同一软件包内覆盖联系人、报价、订单、发票、库存、项目任务与会计等公司活动。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:microsoft-purview-records-management','Microsoft Purview Records Management','{"homepage": "https://learn.microsoft.com/en-us/purview/records-management", "id": "commercial:microsoft-purview-records-management", "leaf_matches": [{"reason": "官方文档正文将其定义为 records management system，支持将项目声明为 record 或 regulatory record、用 file plan 管理保留要求、按事件启动保留、处置审查与删除证明，并对记录编辑/删除施加限制。", "slug": "enterprise-records-management", "source_urls": ["https://learn.microsoft.com/en-us/purview/records-management"]}], "name": "Microsoft Purview Records Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:29:21.224217+08:00", "kind": "documentation", "sha256": "4f742ed2d1b7b1b320200d91be58ef1f6986e441cb1a9d58481d871c6b7a6f5b", "snapshot_path": "sources/4f742ed2d1b7b1b320200d91be58ef1f6986e441cb1a9d58481d871c6b7a6f5b.txt", "url": "https://learn.microsoft.com/en-us/purview/records-management"}], "summary": "Microsoft Purview 记录管理是面向 Microsoft 365 内容的记录管理服务，通过保留标签声明记录、文件计划、事件驱动保留和处置审查来管理记录生命周期。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:387898302','Meeting Room Booking System (MRBS)','{"deployment": ["PHP 7.2+ 与 MySQL/PostgreSQL", "支持 PHP 的 Web 服务器"], "features": ["区域与会议室登记", "预约与冲突预防", "重复预约与日/周/月共享日程", "只读、用户和管理员访问级别", "预约报表与邮件通知"], "github_repository_id": 387898302, "homepage": "https://meeting-room-booking-system.github.io/", "id": "github:387898302", "leaf_matches": [{"reason": "README 与 INSTALL 说明管理员登记 Area/Room 并发起预约；官方首页确认其用于会议室和其他共享资源排期，具备冲突预防、预约规则、重复预约、日/周/月共享日程及分级访问权限。", "slug": "enterprise-resource-scheduling-platform", "source_urls": ["https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/master/README.md", "https://meeting-room-booking-system.github.io/", "https://api.github.com/repos/meeting-room-booking-system/mrbs-code"]}], "license": "GPL-2.0", "license_evidence_url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/master/COPYING", "license_review": {"rationale": "仓库 LICENSE 明确声明 MRBS 采用 GNU GPL v2，COPYING 快照包含完整 GPL v2 正文；第三方组件许可另列。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/master/COPYING", "spdx_id": "GPL-2.0"}, "name": "Meeting Room Booking System (MRBS)", "repository_url": "https://github.com/meeting-room-booking-system/mrbs-code", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:22:09.371258+08:00", "kind": "repository_metadata", "sha256": "f185f214f902e78481119d1597cd0c8fdfcaf7a49ca2aa401a95a23d37aa72a2", "snapshot_path": "sources/f185f214f902e78481119d1597cd0c8fdfcaf7a49ca2aa401a95a23d37aa72a2.txt", "url": "https://api.github.com/repos/meeting-room-booking-system/mrbs-code"}, {"fetched_at": "2026-10-24T22:22:11.150506+08:00", "kind": "readme", "sha256": "d4e4bd478343edd5d6c7f9ee7f36135a80421d014d50bb8702eeb6dd3dada3e4", "snapshot_path": "sources/d4e4bd478343edd5d6c7f9ee7f36135a80421d014d50bb8702eeb6dd3dada3e4.txt", "url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/master/README.md"}, {"fetched_at": "2026-10-24T22:22:12.310388+08:00", "kind": "license", "sha256": "91df39d1816bfb17a4dda2d3d2c83b1f6f2d38d53e53e41e8f97ad5ac46a0cad", "snapshot_path": "sources/91df39d1816bfb17a4dda2d3d2c83b1f6f2d38d53e53e41e8f97ad5ac46a0cad.txt", "url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/master/COPYING"}, {"fetched_at": "2026-10-26T17:29:21.612114+08:00", "kind": "license", "sha256": "6f57cbf0274c3e7baaf9d505a596eb209cfe07efaa2a206760dc9eace8601994", "snapshot_path": "sources/6f57cbf0274c3e7baaf9d505a596eb209cfe07efaa2a206760dc9eace8601994.txt", "url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/main/LICENSE"}, {"fetched_at": "2026-10-26T17:30:05.098103+08:00", "kind": "documentation", "sha256": "f82b0a8a9f4d4ead002852c85fa6dbf743dc5cff870c9e0dc43b06d04530e5e4", "snapshot_path": "sources/f82b0a8a9f4d4ead002852c85fa6dbf743dc5cff870c9e0dc43b06d04530e5e4.txt", "url": "https://raw.githubusercontent.com/meeting-room-booking-system/mrbs-code/main/INSTALL"}, {"fetched_at": "2026-10-26T17:30:22.656226+08:00", "kind": "homepage", "sha256": "35a481432fc8a2969dfbc77b146ba6323062f8836f8e1e3322e903dab04fd985", "snapshot_path": "sources/35a481432fc8a2969dfbc77b146ba6323062f8836f8e1e3322e903dab04fd985.txt", "url": "https://meeting-room-booking-system.github.io/"}], "summary": "MRBS 是基于 PHP 的开源会议室/区域预约系统，支持资源登记、预约与冲突避免。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12801725','Fess','{"deployment": ["Java 21+", "OpenSearch 后端", "DEB/RPM/ZIP 或 Docker 自托管"], "features": ["网站、文件系统、数据库及云/SaaS 数据源爬取", "统一搜索 UI 与 REST API", "角色与权限过滤", "LDAP/OIDC/SAML/SPNEGO/Entra ID 单点登录", "20+ 语言检索"], "github_repository_id": 12801725, "homepage": "https://fess.codelibs.org", "id": "github:12801725", "leaf_matches": [{"reason": "README 明确自称企业搜索服务器，内置爬虫覆盖网站、文件系统、数据库与多类云/SaaS 源，提供单一搜索界面、REST API 与角色/权限过滤；逐源 ACL 自动继承未在来源中确认，故不作该断言。", "slug": "enterprise-search-platform", "source_urls": ["https://api.github.com/repos/codelibs/fess", "https://raw.githubusercontent.com/codelibs/fess/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/codelibs/fess/license", "name": "Fess", "repository_url": "https://github.com/codelibs/fess", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:29:20.804101+08:00", "kind": "repository_metadata", "sha256": "e9c979d3dc87dad8755437ce5b59e1e6a3e9314ece151e756691ba5c0796a3d8", "snapshot_path": "sources/e9c979d3dc87dad8755437ce5b59e1e6a3e9314ece151e756691ba5c0796a3d8.txt", "url": "https://api.github.com/repos/codelibs/fess"}, {"fetched_at": "2026-10-26T17:29:35.722659+08:00", "kind": "license", "sha256": "f698a71d79531977e6730ec7fc4a867523dbfcc9db1a6dfdd0e8f6a01ef3a1de", "snapshot_path": "sources/f698a71d79531977e6730ec7fc4a867523dbfcc9db1a6dfdd0e8f6a01ef3a1de.txt", "url": "https://api.github.com/repos/codelibs/fess/license"}, {"fetched_at": "2026-10-26T17:29:35.423817+08:00", "kind": "readme", "sha256": "7c8e5b14cf0a196aa9cb4d90c750d3b8a68b10715265283e9b9953aa9caf4e9e", "snapshot_path": "sources/7c8e5b14cf0a196aa9cb4d90c750d3b8a68b10715265283e9b9953aa9caf4e9e.txt", "url": "https://raw.githubusercontent.com/codelibs/fess/main/README.md"}], "summary": "Fess 是 Apache-2.0 的自托管企业搜索服务器，内置爬虫采集网站、文件系统、数据库与云/SaaS 数据源，提供统一搜索界面和基于角色/权限的结果过滤。", "technology_stack": ["Java"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:powerdms','PowerDMS Policy','{"homepage": "https://www.powerdms.com/", "id": "commercial:powerdms", "leaf_matches": [{"reason": "PowerDMS 官方 Policy 产品页正文说明其集中管理政策、程序、SOP 与其他运营文档，提供自动版本控制、评审与审批工作流、按人员分发、记录确认签署和完整审计轨迹，匹配组织政策语料库、受控生命周期与向受管辖群体发布。该条目为 PowerDMS by NEOGOV 套件中的 Policy 模块，非整套公共安全套件。", "slug": "compliance-policy-management", "source_urls": ["https://www.powerdms.com/policy-management-software"]}, {"reason": "官方 Policy 产品页说明其集中管理策略、程序、SOP 等运营文档，提供自动版本控制、评审与审批工作流、按人员/组/组织单位分发并跟踪确认，发布新版本时自动归档旧版本并保留审计记录，匹配策略库、受控生命周期与向受管辖群体发布。", "slug": "policy-management", "source_urls": ["https://www.powerdms.com/policy-management-software"]}], "name": "PowerDMS Policy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:23:15.313061+08:00", "kind": "homepage", "sha256": "a05390d6cb8ab389293630464bbdb3df62b8cb412908e547a344cfc918b4fe8b", "snapshot_path": "sources/a05390d6cb8ab389293630464bbdb3df62b8cb412908e547a344cfc918b4fe8b.txt", "url": "https://www.powerdms.com/"}, {"fetched_at": "2026-10-26T17:36:43.309530+08:00", "kind": "documentation", "sha256": "a43baf365468323394be08d25d2d3904ab8525e6b51407b41143f805e2e710c3", "snapshot_path": "sources/a43baf365468323394be08d25d2d3904ab8525e6b51407b41143f805e2e710c3.txt", "url": "https://www.powerdms.com/policy-management-software"}], "summary": "面向公共安全等组织的商业策略管理平台，提供策略、程序与 SOP 的集中库、版本归档、评审审批、分发确认和审计记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:495150380','OpenQMS.net','{"deployment": ["ASP.NET Core 8 自托管", "推荐 Windows Server/IIS 与 SQL Server"], "features": ["策略、流程与其他文档的版本控制", "管理员/经理审批后成为正式版本", "新主版本发布后旧版本标记为作废", "培训关联已批准策略并按角色分配"], "github_repository_id": 495150380, "homepage": "https://www.c-realize.com/qms", "id": "github:495150380", "leaf_matches": [{"reason": "官方文档“Managing policies, procedures and other documents”说明策略、流程等文档受版本控制；管理员/经理凭据审批后才成为主版本，已批准版本不可编辑删除，新主版本发布后旧版本置为作废；培训可关联已批准策略并按角色分配，匹配程序文档库、审批发布生命周期与分发记录。", "slug": "procedure-management", "source_urls": ["https://www.c-realize.com/docs", "https://raw.githubusercontent.com/C-realize/OpenQMS/main/README.md", "https://api.github.com/repos/C-realize/OpenQMS"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/C-realize/OpenQMS/license", "name": "OpenQMS.net", "repository_url": "https://github.com/C-realize/OpenQMS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:32:25.850524+08:00", "kind": "repository_metadata", "sha256": "5bcf57a39b8c9b375d75d9e34b19cdbefc91c418c6ddec28845d92ef97558269", "snapshot_path": "sources/5bcf57a39b8c9b375d75d9e34b19cdbefc91c418c6ddec28845d92ef97558269.txt", "url": "https://api.github.com/repos/C-realize/OpenQMS"}, {"fetched_at": "2026-10-26T17:32:53.614341+08:00", "kind": "license", "sha256": "d84b990307bd8d94f5a444cebdd9575cb48c35417b808d57893ee60b59720124", "snapshot_path": "sources/d84b990307bd8d94f5a444cebdd9575cb48c35417b808d57893ee60b59720124.txt", "url": "https://api.github.com/repos/C-realize/OpenQMS/license"}, {"fetched_at": "2026-10-26T17:32:53.070493+08:00", "kind": "readme", "sha256": "af49a1ec7af0debf0c69defef0adfe500b4d0759489d1be5b2d1c5a9aa6d4d55", "snapshot_path": "sources/af49a1ec7af0debf0c69defef0adfe500b4d0759489d1be5b2d1c5a9aa6d4d55.txt", "url": "https://raw.githubusercontent.com/C-realize/OpenQMS/main/README.md"}, {"fetched_at": "2026-10-26T17:34:34.276346+08:00", "kind": "documentation", "sha256": "8332495d0e3478cb3daec90d6ce14ab895e4dca65f6222a2a451eca5593fca20", "snapshot_path": "sources/8332495d0e3478cb3daec90d6ce14ab895e4dca65f6222a2a451eca5593fca20.txt", "url": "https://www.c-realize.com/docs"}], "summary": "OpenQMS.net 是开源质量管理应用（AGPL-3.0 许可版本，亦提供商业许可），其文档模块用于策略、流程与 SOP 的版本控制、审批发布和培训分发。", "technology_stack": [".NET (ASP.NET Core)", "SQL Server"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:navan','Navan','{"homepage": "https://navan.com/", "id": "commercial:navan", "leaf_matches": [{"reason": "官方 Business Travel 页面描述公司差旅项目配置、全球航班/酒店/铁路/租车库存、预订时展示 in-policy 选项与个性化限额、合规预订自动批准或路由审批、公司侧差旅跟踪仪表盘与虚拟卡支付，匹配公司差旅项目、受控预订记录和管理循环。", "slug": "corporate-travel-management-platform", "source_urls": ["https://navan.com/product/business-travel"]}], "name": "Navan", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:35:53.502182+08:00", "kind": "documentation", "sha256": "ae32d10a850b4ca6bb110d5c1e45a30e7d898b15394a7474be6c3e962fce3ad1", "snapshot_path": "sources/ae32d10a850b4ca6bb110d5c1e45a30e7d898b15394a7474be6c3e962fce3ad1.txt", "url": "https://navan.com/product/business-travel"}], "summary": "面向企业的商业差旅平台，支持公司差旅项目、聚合航班/酒店/铁路/租车库存、预订时政策校验与审批，以及公司侧差旅可见性。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:officespace-software','OfficeSpace Software','{"homepage": "https://www.officespacesoftware.com/", "id": "commercial:officespace-software", "leaf_matches": [{"reason": "官方首页说明其管理办公空间、楼层与资产，提供员工工位/会议室实时预订、入住提醒和 Slack/Teams 集成，并以设施请求、工单、预防性维护、访客与资产维护支撑办公室服务循环，匹配在册办公场所、员工预订界面和办公室团队服务循环。", "slug": "office-operations-platform", "source_urls": ["https://www.officespacesoftware.com/"]}, {"reason": "官方 Moves, Adds & Changes 页正文写明在数字平面图上拖拽生成搬迁请求、按空间类型与容量汇总搬迁计划、搬迁请求由搬迁团队审批且批准后自动更新位置与搬迁日期、保留搬迁历史；Stack & Block 页写明按楼层/团队查看空间分配、拖拽团队生成工位分配并连接 HRIS 人员数据；Scenario Planning 页写明比较情景楼层与在用楼层、合并已批准情景并查看按楼层/LOB 的到岗人数与工位计数。上述正文对应组织自持空间库存、分配与占用状态、搬迁审批与情景比较核心。", "slug": "space-management-platform", "source_urls": ["https://www.officespacesoftware.com/features/move-management/", "https://www.officespacesoftware.com/features/stack-plans/", "https://www.officespacesoftware.com/features/scenario-planning/"]}, {"reason": "Desk Booking 页正文写明员工从任意地点预订工位、到达自动签到、未签到自动释放并显示实时占用；Room Booking 页写明会议室预订、自动签到与未使用自动释放；Request Management 页正文写明设施请求进入工单队列、可配置请求类型/分配规则/SLA、自动分配工单、状态通知、完成后请求自动关闭并通知员工；Visitor Management 页写明访客登记与包裹递送记录。以上正文共同构成工作场所记录、员工预订与协调界面、运营请求闭环。", "slug": "workplace-management-platform", "source_urls": ["https://www.officespacesoftware.com/features/desk-booking/", "https://www.officespacesoftware.com/features/room-booking/", "https://www.officespacesoftware.com/features/request-management/", "https://www.officespacesoftware.com/features/visitor-management-system/"]}], "name": "OfficeSpace Software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:35:53.758201+08:00", "kind": "homepage", "sha256": "2a5a5eedd754c005d335f2eaf9639ab1c43cb3080c5d543ff76674b13367b6fc", "snapshot_path": "sources/2a5a5eedd754c005d335f2eaf9639ab1c43cb3080c5d543ff76674b13367b6fc.txt", "url": "https://www.officespacesoftware.com/"}, {"fetched_at": "2026-10-27T12:06:47.900193+08:00", "kind": "documentation", "sha256": "7dd5f2abd9ba5408285296dd487be53a1ce919d2cb0b5a0875e5e300c0563f3a", "snapshot_path": "sources/7dd5f2abd9ba5408285296dd487be53a1ce919d2cb0b5a0875e5e300c0563f3a.txt", "url": "https://www.officespacesoftware.com/features/desk-booking/"}, {"fetched_at": "2026-10-27T12:06:25.174549+08:00", "kind": "documentation", "sha256": "534d5061c24c356f98ea22179c26d800fdfca9a36c985b4202d06046eaafd8bd", "snapshot_path": "sources/534d5061c24c356f98ea22179c26d800fdfca9a36c985b4202d06046eaafd8bd.txt", "url": "https://www.officespacesoftware.com/features/move-management/"}, {"fetched_at": "2026-10-27T12:06:55.241431+08:00", "kind": "documentation", "sha256": "a1054bf0eec3f39570726f0b59f7f6cdc362384cf29d6e839eb14069c3c733df", "snapshot_path": "sources/a1054bf0eec3f39570726f0b59f7f6cdc362384cf29d6e839eb14069c3c733df.txt", "url": "https://www.officespacesoftware.com/features/request-management/"}, {"fetched_at": "2026-10-27T12:06:46.629458+08:00", "kind": "documentation", "sha256": "f49c0531bd0ed3385090e172cd85e26bf4f02dbbca91534b768ff7a66a8c8e1d", "snapshot_path": "sources/f49c0531bd0ed3385090e172cd85e26bf4f02dbbca91534b768ff7a66a8c8e1d.txt", "url": "https://www.officespacesoftware.com/features/room-booking/"}, {"fetched_at": "2026-10-27T12:06:24.723190+08:00", "kind": "documentation", "sha256": "9efede1b5f9df337b808241d1b12058c7b214229af83caadc7aebd4f475d2b64", "snapshot_path": "sources/9efede1b5f9df337b808241d1b12058c7b214229af83caadc7aebd4f475d2b64.txt", "url": "https://www.officespacesoftware.com/features/scenario-planning/"}, {"fetched_at": "2026-10-27T12:06:25.119868+08:00", "kind": "documentation", "sha256": "5c6a3238f1b23d4ae1580f85d71bd14990a28c2613798bc181e483460d947a4d", "snapshot_path": "sources/5c6a3238f1b23d4ae1580f85d71bd14990a28c2613798bc181e483460d947a4d.txt", "url": "https://www.officespacesoftware.com/features/stack-plans/"}, {"fetched_at": "2026-10-27T12:06:45.257054+08:00", "kind": "documentation", "sha256": "cdcbc66ca13340aa2b1d0a404632faef2146ba14aa39c9f4b3b21194981509f3", "snapshot_path": "sources/cdcbc66ca13340aa2b1d0a404632faef2146ba14aa39c9f4b3b21194981509f3.txt", "url": "https://www.officespacesoftware.com/features/visitor-management-system/"}], "summary": "面向设施与职场团队的商业办公运营平台，覆盖办公空间与楼层、员工工位/会议室预订、设施请求与工单、访客与资产维护。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1261406772','LawLink','{"deployment": ["README 提供自托管本地开发（Node.js 22 + PostgreSQL 16）与 Docker Compose 部署", "生产部署需按云服务器安装指南配置端口/HTTPS、初始化与备份"], "features": ["收案登记、冲突检索、转正式案件、持续跟进、财务记录、结案归档与数据导出", "Matter/MatterProcedure/MatterStage/Task/Hearing/Deadline/Document 三层案卷结构", "案件档案、办案进程、委托与财务、统一审批用印、岗位/团队和归档制度", "法院来件、送达台账、期限与提醒", "当事人及不同程序中的诉讼地位、法院/仲裁机构、案号、立案/结案与结果"], "github_repository_id": 1261406772, "homepage": "https://github.com/lawflow-boop/LawLink", "id": "github:1261406772", "leaf_matches": [{"reason": "README 说明系统以“收案登记→冲突检索→转正式案件→持续跟进→财务记录→结案归档→数据导出”组织律所案件，并提供案件档案、办案进程、委托与财务、审批、岗位/团队与归档；DATA-MODEL 把 Matter 定义为法律争议或非诉项目的持久容器，挂客户、案由、标的、状态、合同、财务、沟通，并以 MatterProcedure/MatterStage/Task/Hearing/Deadline/Document 承载案卷。据此符合事务为记录单位、累积案卷、人员与状态受管的定义核心。", "slug": "legal-matter-management", "source_urls": ["https://raw.githubusercontent.com/lawflow-boop/LawLink/main/README.md", "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/docs/DATA-MODEL.md"]}, {"reason": "DATA-MODEL 将诉讼细分民商事/刑事/行政，MatterProcedure 记录一审/二审/再审/仲裁/执行等程序及独立案号、法院/仲裁机构、立案日、结案日与结果；Party 以 CLIENT_PARTY/OPPOSING_PARTY/THIRD_PARTY/CO_LITIGANT/AGENT/WITNESS 等角色记录当事人与代理人，ProcedureParty 记录同一当事人不同程序中的诉讼地位；MatterStage 下挂 Hearing/Deadline/Document，Document 设 EVIDENCE 证据材料类别。README 当前版还列出法院来件、期限与提醒、办案进程和案件档案。据此可匹配诉讼案件持久记录、当事人/代理、法院/程序态势、阶段、期限与证据案卷层的核心；未把资料未明确的证据开示请求/制作清单写成已实现。", "slug": "litigation-management-platform", "source_urls": ["https://raw.githubusercontent.com/lawflow-boop/LawLink/main/README.md", "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/docs/DATA-MODEL.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/LICENSE", "license_review": {"rationale": "已核对仓库 LICENSE 完整文本：包含 MIT 许可授予、版权保留与免责声明条款，仓库元数据 license.spdx_id 亦为 MIT。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/LICENSE", "spdx_id": "MIT"}, "name": "LawLink", "repository_url": "https://github.com/lawflow-boop/LawLink", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:51:45.456952+08:00", "kind": "repository_metadata", "sha256": "92423632a232636d60b0f36e7b60f8a41418226abf4e8a8b878011ac3b6429d3", "snapshot_path": "sources/92423632a232636d60b0f36e7b60f8a41418226abf4e8a8b878011ac3b6429d3.txt", "url": "https://api.github.com/repos/lawflow-boop/LawLink"}, {"fetched_at": "2026-10-26T17:51:46.826151+08:00", "kind": "readme", "sha256": "d18878aec656940698449416e940a7e4b534930a94f38f489d3669d6af25f007", "snapshot_path": "sources/d18878aec656940698449416e940a7e4b534930a94f38f489d3669d6af25f007.txt", "url": "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/README.md"}, {"fetched_at": "2026-10-26T17:51:48.100623+08:00", "kind": "license", "sha256": "3712fe81e52ef81ce253d05bd6929cec9b5c2782c89a0ed7b14baa0a6f96cded", "snapshot_path": "sources/3712fe81e52ef81ce253d05bd6929cec9b5c2782c89a0ed7b14baa0a6f96cded.txt", "url": "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/LICENSE"}, {"fetched_at": "2026-10-26T17:51:49.732755+08:00", "kind": "documentation", "sha256": "9122714342233332ae62e54c8123cdec5795b06d8ef24a649236af1ab9129ed8", "snapshot_path": "sources/9122714342233332ae62e54c8123cdec5795b06d8ef24a649236af1ab9129ed8.txt", "url": "https://raw.githubusercontent.com/lawflow-boop/LawLink/main/docs/DATA-MODEL.md"}], "summary": "MIT 许可、可自托管的法律案件/项目管理系统，以案件（Matter）为记录单位，串接收案、冲突检索、程序阶段、当事人、法院来件、期限、财务、审批和结案归档；本次只记录公开仓库核心，不把路线图写成已实现。", "technology_stack": ["TypeScript", "Next.js 16", "React 19", "PostgreSQL 16", "Prisma 5"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:legal-tracker','Thomson Reuters Legal Tracker','{"homepage": "https://legal.thomsonreuters.com/en/products/legal-tracker", "id": "commercial:legal-tracker", "leaf_matches": [{"reason": "官方产品页将 Legal Tracker 定义为 legal operations platform，并同时列出 AI 电子计费/发票审查、法律事项管理、律所与费率基准、法律支出报表与仪表板；工作、外部资金和律所三类记录在同一产品叙述中联动，符合部门级运营监督核心。", "slug": "legal-operations-platform", "source_urls": ["https://legal.thomsonreuters.com/en/products/legal-tracker"]}, {"reason": "官方产品页明确以 AI invoice review 检测账单异常、检查合规、支持 LEDES 等多格式，并与外部律师沟通账单；同时提供法律支出报表、仪表板和基准。可匹配采购方账单审查关卡与全职能支出视图；页面未逐项确认应计采集节奏，正文不展开该细节。", "slug": "legal-spend-management", "source_urls": ["https://legal.thomsonreuters.com/en/products/legal-tracker"]}, {"reason": "官方产品页说明其面向企业法务部门管理法律事项、律所与费率基准、外部律师账单审查和沟通，并给出 120,000+ 律所/供应商用户规模；可匹配买方侧律所关系与成本的核心。页面未逐项展示聘约登记表模块，故不把该细节写成已确认。", "slug": "outside-counsel-management", "source_urls": ["https://legal.thomsonreuters.com/en/products/legal-tracker"]}], "name": "Thomson Reuters Legal Tracker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:51:52.204744+08:00", "kind": "homepage", "sha256": "c242cc6b9cd71023790e1a8086fc31bdf7d87fec818c21edbbec5b571b4d0488", "snapshot_path": "sources/c242cc6b9cd71023790e1a8086fc31bdf7d87fec818c21edbbec5b571b4d0488.txt", "url": "https://legal.thomsonreuters.com/en/products/legal-tracker"}], "summary": "面向企业法务部门的商业法律电子计费与法律运营平台：官方产品页称其提供 AI 发票审查（含 LEDES）、法律支出报表与基准、法律事项管理及律所/费率管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:40549369','Seal Report','{"deployment": ["Windows 或 Linux 自托管", ".NET 10 与 ASP.NET Core/IIS 部署", "GitHub Releases 安装包"], "features": ["报表定义绑定 SQL/NoSQL 数据源，支持运行参数与 restriction", "Web Report Server 发布报表，安全组可控制仓库文件夹与报表权限", "报告计划任务可投递到文件夹、FTP/SFTP、SharePoint 或电子邮件", "同一报表可输出 PDF、Excel、HTML、CSV、XML、JSON 等格式", "支持下钻、子报表与审计日志"], "github_repository_id": 40549369, "homepage": "https://sealreport.org/", "id": "github:40549369", "leaf_matches": [{"reason": "README 与官方 Server 文档显示：报表由 SQL/NoSQL 查询、参数和 restriction 定义，由 Web Report Server 发布并按安全组/文件夹授权，计划器把 PDF/Excel/CSV 等渲染结果投递到邮件、FTP/SFTP、文件夹或 SharePoint，构成固定布局文档报告的生产与交付闭环。", "slug": "reporting-platform", "source_urls": ["https://raw.githubusercontent.com/ariacom/Seal-Report/master/README.md", "https://raw.githubusercontent.com/ariacom/Seal-Report/master/Projects/SealDocumentation/Pages/Server.cshtml"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/ariacom/Seal-Report/license", "name": "Seal Report", "repository_url": "https://github.com/ariacom/Seal-Report", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:52:18.199506+08:00", "kind": "repository_metadata", "sha256": "04340d2466a5319ee700b24b5698936071b5800e4574c3b205581808c92525f1", "snapshot_path": "sources/04340d2466a5319ee700b24b5698936071b5800e4574c3b205581808c92525f1.txt", "url": "https://api.github.com/repos/ariacom/Seal-Report"}, {"fetched_at": "2026-10-26T17:52:25.886284+08:00", "kind": "readme", "sha256": "236df1e8936727d2cf25858649f7598274ffee93bfe664e250ee582b771bf8ba", "snapshot_path": "sources/236df1e8936727d2cf25858649f7598274ffee93bfe664e250ee582b771bf8ba.txt", "url": "https://raw.githubusercontent.com/ariacom/Seal-Report/master/README.md"}, {"fetched_at": "2026-10-26T17:52:18.182177+08:00", "kind": "license", "sha256": "00ee35db566cc478df679558a479df53323c5870ec1e047685dea5a858336979", "snapshot_path": "sources/00ee35db566cc478df679558a479df53323c5870ec1e047685dea5a858336979.txt", "url": "https://api.github.com/repos/ariacom/Seal-Report/license"}, {"fetched_at": "2026-10-26T17:53:37.042243+08:00", "kind": "documentation", "sha256": "f852d1c13de7f813c3132fcc66fe0e062aa37ba59e9bcb647f11f168f5ef3c06", "snapshot_path": "sources/f852d1c13de7f813c3132fcc66fe0e062aa37ba59e9bcb647f11f168f5ef3c06.txt", "url": "https://raw.githubusercontent.com/ariacom/Seal-Report/master/Projects/SealDocumentation/Pages/Server.cshtml"}], "summary": "MIT 开源自托管报表平台：以 SQL/NoSQL 报表定义和参数生成 PDF、Excel、HTML、CSV 等文档型结果，经 Web 报表服务器和安全组权限发布，并按计划投递到邮件、文件共享或 SharePoint。", "technology_stack": [".NET 10", "C#", "ASP.NET Core", "Razor", "SQL/NoSQL 数据源"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ai-spendops','AI SpendOps','{"homepage": "https://www.aispendops.com/", "id": "commercial:ai-spendops", "leaf_matches": [{"reason": "官方首页正文说明其跟踪 16+ LLM 提供商的 token 成本，按团队/功能/环境归因，提供支出仪表盘、预算阈值与预测，并可在网关执行模型策略；对应 AI 消耗→成本分配→组织归因→支出可见性四项核心。", "slug": "ai-cost-finops-platform", "source_urls": ["https://www.aispendops.com/"]}], "name": "AI SpendOps", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:53:26.191179+08:00", "kind": "homepage", "sha256": "9ed09c586ff16bd7dd9ec237a17bb55fc2b4e967d2052992746da9effa1fa3b5", "snapshot_path": "sources/9ed09c586ff16bd7dd9ec237a17bb55fc2b4e967d2052992746da9effa1fa3b5.txt", "url": "https://www.aispendops.com/"}], "summary": "商业 AI 支出管理平台：按团队、功能或客户归因 token 成本，跟踪与预测预算，并通过网关执行模型策略。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:credo-ai','Credo AI','{"homepage": "https://www.credo.ai/", "id": "commercial:credo-ai", "leaf_matches": [{"reason": "官方产品页正文列出 AI Registry 与影子 AI 发现、代理/模型风险评估、政策引擎与合规映射、带审批门控的治理工作流和审计证据，覆盖治理对象登记→评估→控制→生命周期决策→治理记录。", "slug": "ai-governance-platform", "source_urls": ["https://www.credo.ai/product"]}], "name": "Credo AI", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:53:04.410460+08:00", "kind": "documentation", "sha256": "efc16b094ba9228a72c6a47c1e46a5230058a96c664298e26ea71db9fa8d444c", "snapshot_path": "sources/efc16b094ba9228a72c6a47c1e46a5230058a96c664298e26ea71db9fa8d444c.txt", "url": "https://www.credo.ai/product"}], "summary": "商业 AI 治理平台：集中登记 AI 系统、代理与模型，做风险评估、政策与合规映射、审批工作流，并留存审计证据。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:600596928','LibreChat','{"deployment": ["Docker Compose 自托管", "单机到 Redis 横向扩展部署", "完全本地或云端运行"], "features": ["多用户安全认证，支持 OAuth2、LDAP 与邮箱登录", "管理员面板管理用户、组、角色和逐角色/组权限", "多模型对话、Agents、MCP、文件搜索与代码解释器", "对话搜索、预设、共享与导入导出", "Docker Compose 一键自托管"], "github_repository_id": 600596928, "homepage": "https://librechat.ai/", "id": "github:600596928", "leaf_matches": [{"reason": "README 明确其为自托管 AI 对话平台，具备多用户认证、管理员/角色/组权限和 Docker 部署，员工以自然语言获得模型生成的回答与代理协助；组织运营、面向员工、AI 对话三项核心同时成立。", "slug": "enterprise-ai-assistant", "source_urls": ["https://raw.githubusercontent.com/LibreChat-AI/LibreChat/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/LibreChat-AI/LibreChat/license", "name": "LibreChat", "repository_url": "https://github.com/LibreChat-AI/LibreChat", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:51:56.343650+08:00", "kind": "repository_metadata", "sha256": "8acd159e73536763eb96faca33d003b520a9608a878f8cecffaf138407eff1f4", "snapshot_path": "sources/8acd159e73536763eb96faca33d003b520a9608a878f8cecffaf138407eff1f4.txt", "url": "https://api.github.com/repos/LibreChat-AI/LibreChat"}, {"fetched_at": "2026-10-26T17:52:25.856520+08:00", "kind": "readme", "sha256": "84a943a2e911f9a3566e9c959d6a5b0a7ceb69481d67d9d66817f4ea2bc95412", "snapshot_path": "sources/84a943a2e911f9a3566e9c959d6a5b0a7ceb69481d67d9d66817f4ea2bc95412.txt", "url": "https://raw.githubusercontent.com/LibreChat-AI/LibreChat/main/README.md"}, {"fetched_at": "2026-10-26T17:52:31.694121+08:00", "kind": "license", "sha256": "6730be6f46f02a3ebe3940ceed4ab8abef1ae8ca9f48ce30dbcbdafa6b33acf2", "snapshot_path": "sources/6730be6f46f02a3ebe3940ceed4ab8abef1ae8ca9f48ce30dbcbdafa6b33acf2.txt", "url": "https://api.github.com/repos/LibreChat-AI/LibreChat/license"}], "summary": "MIT 开源自托管企业 AI 对话平台：组织可部署并管理多用户、组与角色，员工在同一界面使用多家模型的对话、Agents 与文件/代码工具。", "technology_stack": ["Node.js", "React", "MongoDB", "Redis", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:649170660','AnythingLLM','{"deployment": ["Docker 自托管", "桌面版本地运行", "本地或云主机部署"], "features": ["工作区文档问答，聊天回答附来源引用", "Docker 版支持多用户实例与按用户权限", "摄取 PDF、TXT、DOCX 等多种文档格式", "支持本地与云端 LLM、嵌入模型和向量数据库", "可自托管或本地运行，提供开发者 API"], "github_repository_id": 649170660, "homepage": "https://anythingllm.com/", "id": "github:649170660", "leaf_matches": [{"reason": "README 说明其以组织文档为工作区语料，提供带来源引用的文档聊天、多用户实例和按用户权限，可由组织自托管；员工自然语言提问得到基于自有知识的合成回答，符合 EKA 的语料+合成答案核心。", "slug": "enterprise-knowledge-assistant", "source_urls": ["https://raw.githubusercontent.com/Mintplex-Labs/anything-llm/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Mintplex-Labs/anything-llm/license", "name": "AnythingLLM", "repository_url": "https://github.com/Mintplex-Labs/anything-llm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:53:58.347057+08:00", "kind": "repository_metadata", "sha256": "2a2c43258bb155fb21fda1ae1ff3898121daf156a07aae77fdf249f79824e5f6", "snapshot_path": "sources/2a2c43258bb155fb21fda1ae1ff3898121daf156a07aae77fdf249f79824e5f6.txt", "url": "https://api.github.com/repos/Mintplex-Labs/anything-llm"}, {"fetched_at": "2026-10-26T17:54:02.662909+08:00", "kind": "readme", "sha256": "54fa19d813e8bb7bbed9346771e17ad29a9d5753effa19427bea4c38de6c7a2c", "snapshot_path": "sources/54fa19d813e8bb7bbed9346771e17ad29a9d5753effa19427bea4c38de6c7a2c.txt", "url": "https://raw.githubusercontent.com/Mintplex-Labs/anything-llm/master/README.md"}, {"fetched_at": "2026-10-26T17:53:57.828451+08:00", "kind": "license", "sha256": "c9e397b6578efc3d9e6c18673cdd344c754322a147a193249ee4334c4fb68a83", "snapshot_path": "sources/c9e397b6578efc3d9e6c18673cdd344c754322a147a193249ee4334c4fb68a83.txt", "url": "https://api.github.com/repos/Mintplex-Labs/anything-llm/license"}], "summary": "MIT 开源自托管知识助手：把组织文档摄取到工作区，多用户按权限与文档对话，回答附来源引用；Docker 版支持多用户与权限管理。", "technology_stack": ["Node.js", "React", "JavaScript", "向量数据库", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:13926404','Redash','{"deployment": ["自托管实例（官方 setup 指南）", "官方提供的 AWS/GCE 镜像"], "features": ["浏览器端 SQL/NoSQL 查询编辑器，带 schema 浏览器与自动补全", "连接 35+ 种数据库与数据平台", "结果表格与拖拽式可视化", "保存查询、仪表板、定时刷新与告警", "REST API"], "github_repository_id": 13926404, "homepage": "https://redash.io/", "id": "github:13926404", "leaf_matches": [{"reason": "README 明确：用户在浏览器查询编辑器中当场组合 SQL/NoSQL 查询（含 schema browser 与自动补全），面向已连接的 35+ 数据源，结果以表格/可视化呈现并可保存、共享和继续调整。可查询数据源、用户即时构建、会话内执行、结果呈现与交互细化五个属性均成立。", "slug": "ad-hoc-query-application", "source_urls": ["https://raw.githubusercontent.com/getredash/redash/master/README.md"]}], "license": "BSD-2-Clause", "license_evidence_url": "https://api.github.com/repos/getredash/redash/license", "name": "Redash", "repository_url": "https://github.com/getredash/redash", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:58:55.207217+08:00", "kind": "repository_metadata", "sha256": "9ae5adbb12b5f4eba71b1f955fc0fe467ebdbf0b0ce88d328cc33fe8ada8b16c", "snapshot_path": "sources/9ae5adbb12b5f4eba71b1f955fc0fe467ebdbf0b0ce88d328cc33fe8ada8b16c.txt", "url": "https://api.github.com/repos/getredash/redash"}, {"fetched_at": "2026-10-26T17:58:56.653739+08:00", "kind": "license", "sha256": "80bba9b2aef274a9f6219ba46aaaf5ca71ffe05df384321005e7cd835146b1c4", "snapshot_path": "sources/80bba9b2aef274a9f6219ba46aaaf5ca71ffe05df384321005e7cd835146b1c4.txt", "url": "https://api.github.com/repos/getredash/redash/license"}, {"fetched_at": "2026-10-26T17:58:58.015276+08:00", "kind": "readme", "sha256": "3989c99aada63f02bb56c4947f7cdc5099433c4432bec7104ef5fc913a468aa6", "snapshot_path": "sources/3989c99aada63f02bb56c4947f7cdc5099433c4432bec7104ef5fc913a468aa6.txt", "url": "https://raw.githubusercontent.com/getredash/redash/master/README.md"}], "summary": "开源（BSD-2-Clause）的浏览器端即席查询与可视化应用：连接 35+ 种 SQL/NoSQL 数据源，用户在查询编辑器中当场编写查询并立即执行，以表格或图表读取结果并就地继续调整；保存后的查询可组合为仪表板、定时刷新与告警。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:60374819','JupyterLab','{"deployment": ["pip/conda 本地自托管", "JupyterHub 多用户部署"], "features": ["连接内核的有状态代码会话", "代码、叙述文本与富输出交织的 notebook", "内核选择与管理", "代码控制台、终端与文本编辑器", "workspace 与扩展机制"], "github_repository_id": 60374819, "homepage": "https://jupyterlab.readthedocs.io/", "id": "github:60374819", "leaf_matches": [{"reason": "官方文档明确 JupyterLab 是 notebook 编写与编辑环境，notebook 结合可运行代码、叙述、数据与可视化，创建时选择内核并在其中增量执行；README 说明其提供 notebook、控制台、终端等构件。符合有状态代码会话 + 数据工作材料 + 探索性分析建模三个结构。", "slug": "data-science-workbench", "source_urls": ["https://raw.githubusercontent.com/jupyterlab/jupyterlab/main/README.md", "https://jupyterlab.readthedocs.io/en/stable/", "https://jupyterlab.readthedocs.io/en/stable/user/notebook.html"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/jupyterlab/jupyterlab/license", "name": "JupyterLab", "repository_url": "https://github.com/jupyterlab/jupyterlab", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:59:07.862348+08:00", "kind": "repository_metadata", "sha256": "43ff535e9b52174acee6c780795a1cb24a55c819f117c28aee1606ce2ba8efd0", "snapshot_path": "sources/43ff535e9b52174acee6c780795a1cb24a55c819f117c28aee1606ce2ba8efd0.txt", "url": "https://api.github.com/repos/jupyterlab/jupyterlab"}, {"fetched_at": "2026-10-26T17:59:09.366366+08:00", "kind": "license", "sha256": "e6711f10b2af438dda7988ca088f48a1dcf024fb2c5e302645c8f4d3cc209bff", "snapshot_path": "sources/e6711f10b2af438dda7988ca088f48a1dcf024fb2c5e302645c8f4d3cc209bff.txt", "url": "https://api.github.com/repos/jupyterlab/jupyterlab/license"}, {"fetched_at": "2026-10-26T17:59:10.742251+08:00", "kind": "readme", "sha256": "f2a9d4e09ca81a79ffe7f21ca31cbb51d8e04cf0a801d638ae3f32c3317b67d3", "snapshot_path": "sources/f2a9d4e09ca81a79ffe7f21ca31cbb51d8e04cf0a801d638ae3f32c3317b67d3.txt", "url": "https://raw.githubusercontent.com/jupyterlab/jupyterlab/main/README.md"}, {"fetched_at": "2026-10-26T18:00:22.327953+08:00", "kind": "documentation", "sha256": "835c77de6e3c8e89f58ce4a885a442859c1c1c9c9e3526ad483809261f494d99", "snapshot_path": "sources/835c77de6e3c8e89f58ce4a885a442859c1c1c9c9e3526ad483809261f494d99.txt", "url": "https://jupyterlab.readthedocs.io/en/stable/"}, {"fetched_at": "2026-10-26T18:02:45.895307+08:00", "kind": "documentation", "sha256": "c1227feffde5b03eb621bc4ae15d6638e6b9d1aed4ec14f2c0b36f6ed955ed65", "snapshot_path": "sources/c1227feffde5b03eb621bc4ae15d6638e6b9d1aed4ec14f2c0b36f6ed955ed65.txt", "url": "https://jupyterlab.readthedocs.io/en/stable/user/notebook.html"}], "summary": "开源（BSD-3-Clause）交互式笔记本工作台：以连接内核的有状态代码会话为中心，用户把文件/数据引入会话，增量运行代码并查看内联输出，用于探索性数据分析与建模；notebook 是主要表面形式，另有控制台、终端与编辑器。", "technology_stack": ["TypeScript", "Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:45993608','Neo4j Browser','{"deployment": ["可从源码构建运行的经典版 Web 应用", "连接 Neo4j Server/Aura/Desktop 实例"], "features": ["连接运行中的 Neo4j 实例", "Cypher 查询编辑器", "图/表/RAW/执行计划结果帧", "节点-关系图可视化与结果继续展开", "结果导出"], "github_repository_id": 45993608, "homepage": "https://neo4j.com", "id": "github:45993608", "leaf_matches": [{"reason": "README 将 Neo4j Browser 定义为面向 Neo4j 的通用图形界面，核心用途是查询与可视化图数据；官方 Browser 文档进一步说明 Cypher 查询结果以图/表/RAW/计划结果帧呈现，图帧按节点与关系渲染并可从结果继续展开。符合“运行中图数据库 + Cypher 访问 + 保留元素的结果”。", "slug": "graph-database-explorer", "source_urls": ["https://raw.githubusercontent.com/neo4j/neo4j-browser/master/README.md", "https://neo4j.com/docs/browser-manual/current/", "https://neo4j.com/docs/browser-manual/current/operations/result-frames/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/neo4j/neo4j-browser/license", "name": "Neo4j Browser", "repository_url": "https://github.com/neo4j/neo4j-browser", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:59:12.090088+08:00", "kind": "repository_metadata", "sha256": "4ebfbf85a44e15e2a1ded50f8ab25c936a4c29a80fb6283ab479feea441cfb46", "snapshot_path": "sources/4ebfbf85a44e15e2a1ded50f8ab25c936a4c29a80fb6283ab479feea441cfb46.txt", "url": "https://api.github.com/repos/neo4j/neo4j-browser"}, {"fetched_at": "2026-10-26T17:59:13.743145+08:00", "kind": "license", "sha256": "b870b14678e1cdf0ab705e43f1193bdbff56799c8016152aa5334ce5481ba3dc", "snapshot_path": "sources/b870b14678e1cdf0ab705e43f1193bdbff56799c8016152aa5334ce5481ba3dc.txt", "url": "https://api.github.com/repos/neo4j/neo4j-browser/license"}, {"fetched_at": "2026-10-26T18:00:20.814337+08:00", "kind": "readme", "sha256": "1a0b1dfc71659e8304f1014b1f80b80f6136e8877345b8594ac960c4ce507112", "snapshot_path": "sources/1a0b1dfc71659e8304f1014b1f80b80f6136e8877345b8594ac960c4ce507112.txt", "url": "https://raw.githubusercontent.com/neo4j/neo4j-browser/master/README.md"}, {"fetched_at": "2026-10-26T18:02:48.545583+08:00", "kind": "documentation", "sha256": "aa8ff2285a2f51210c92b2992c827e8f24b8ee8478055df22d61cdb2bf9c93e2", "snapshot_path": "sources/aa8ff2285a2f51210c92b2992c827e8f24b8ee8478055df22d61cdb2bf9c93e2.txt", "url": "https://neo4j.com/docs/browser-manual/current/"}, {"fetched_at": "2026-10-26T18:03:08.966342+08:00", "kind": "documentation", "sha256": "b400e42144c12cacac28a4b32dffd3d74c55a48356bc7423a13244cf19a01873", "snapshot_path": "sources/b400e42144c12cacac28a4b32dffd3d74c55a48356bc7423a13244cf19a01873.txt", "url": "https://neo4j.com/docs/browser-manual/current/operations/result-frames/"}], "summary": "Neo4j 的经典开源图数据库浏览器（GPL-3.0）：连接运行中的 Neo4j 实例，在 Cypher 编辑器中查询存储的节点/关系，结果以图、表、RAW、执行计划等结果帧呈现，可从结果继续展开探索。该仓库为经典版且维护有限；当前新版 Neo4j Browser 由闭源构件构建。", "technology_stack": ["TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:216628419','Flyte','{"deployment": ["自托管 Kubernetes", "云端或本地部署"], "features": ["版本化、不可变的 workflow/task 定义", "development/staging/production Domain 隔离", "生产调度、运行历史与项目仪表盘", "Python SDK 与多语言容器任务", "Kubernetes 原生，云端或本地部署"], "github_repository_id": 216628419, "homepage": "https://flyte.org", "id": "github:216628419", "leaf_matches": [{"reason": "官方文档同时覆盖定义核心三部分：versioning.rst 说明整个 workflow 版本化且 task/entity 不可变；domains.rst 以 development/staging/production 为例隔离部署并限制开发域调度；projects.rst 与 README 提供生产调度、运行历史和项目仪表盘。Flyte 不是裸 SDK，而是含控制面的自托管管道平台。", "slug": "dataops-platform", "source_urls": ["https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/main_concepts/versioning.rst", "https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/control_plane/domains.rst", "https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/control_plane/projects.rst", "https://raw.githubusercontent.com/flyteorg/flyte/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/flyteorg/flyte/license", "name": "Flyte", "repository_url": "https://github.com/flyteorg/flyte", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:01:36.881341+08:00", "kind": "repository_metadata", "sha256": "050f5b2c45a1b593ea65c8606fe0a480d7fbbc51b670efa642878cb453a88520", "snapshot_path": "sources/050f5b2c45a1b593ea65c8606fe0a480d7fbbc51b670efa642878cb453a88520.txt", "url": "https://api.github.com/repos/flyteorg/flyte"}, {"fetched_at": "2026-10-26T18:01:37.026000+08:00", "kind": "license", "sha256": "09c787244bbb005cb20f6363b82317015c09a0b4956aba23e4c378e8d564793e", "snapshot_path": "sources/09c787244bbb005cb20f6363b82317015c09a0b4956aba23e4c378e8d564793e.txt", "url": "https://api.github.com/repos/flyteorg/flyte/license"}, {"fetched_at": "2026-10-26T18:04:59.539345+08:00", "kind": "readme", "sha256": "639b4c504cfd6b2d7b7bb74e6dcdd223ccae40276c972f43ed56ed43c9bef520", "snapshot_path": "sources/639b4c504cfd6b2d7b7bb74e6dcdd223ccae40276c972f43ed56ed43c9bef520.txt", "url": "https://raw.githubusercontent.com/flyteorg/flyte/master/README.md"}, {"fetched_at": "2026-10-26T18:01:42.140801+08:00", "kind": "readme", "sha256": "d0c000540850e6ae2211930afaf8fd17de34e46cc2f30fa9aa7b8806c0f303f6", "snapshot_path": "sources/d0c000540850e6ae2211930afaf8fd17de34e46cc2f30fa9aa7b8806c0f303f6.txt", "url": "https://raw.githubusercontent.com/flyteorg/flyte/main/README.md"}, {"fetched_at": "2026-10-26T18:02:09.303023+08:00", "kind": "documentation", "sha256": "c247a1f795225abe8962281499ac75e0944cbff50f3150d9bacb90fcfb1463f3", "snapshot_path": "sources/c247a1f795225abe8962281499ac75e0944cbff50f3150d9bacb90fcfb1463f3.txt", "url": "https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/control_plane/domains.rst"}, {"fetched_at": "2026-10-26T18:02:09.288337+08:00", "kind": "documentation", "sha256": "63276c5726d6fe2deefa475c9067da8880186ad6ad65151596c8de2a6c33f31e", "snapshot_path": "sources/63276c5726d6fe2deefa475c9067da8880186ad6ad65151596c8de2a6c33f31e.txt", "url": "https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/control_plane/projects.rst"}, {"fetched_at": "2026-10-26T18:05:04.275072+08:00", "kind": "documentation", "sha256": "322b50918b36ef074ad9ae1cafd1f7c4092075edf52cb0125d66cd371bc7e2a1", "snapshot_path": "sources/322b50918b36ef074ad9ae1cafd1f7c4092075edf52cb0125d66cd371bc7e2a1.txt", "url": "https://raw.githubusercontent.com/flyteorg/flyte/master/docs/user_guide/concepts/main_concepts/versioning.rst"}], "summary": "开源、Kubernetes 原生的数据与机器学习管道编排平台。工作流和任务以不可变、可版本化的定义登记，可通过 Domain 隔离开发、预发布与生产环境；生产运行可由调度触发，并在平台中查看运行历史和项目仪表盘。本条按 Flyte 1.x 记录；README 说明 Flyte 2 的开源分布式后端仍在准备中。", "technology_stack": ["Go", "Python", "Kubernetes"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:semarchy-data-platform','Semarchy Data Platform (xDM)','{"homepage": "https://semarchy.com", "id": "commercial:semarchy-data-platform", "leaf_matches": [{"reason": "Semarchy 官方 concepts 页明确列出 master data management 能力（创建并维护准确、一致、受治理的主数据）；designer guides 进一步覆盖逻辑数据模型、认证/校验、match and merge、golden records、MDM Web 应用和治理工作流，构成完整的 MDM 核心。", "slug": "master-data-management", "source_urls": ["https://docs.semarchy.com/self-hosted/latest/get-started/concepts", "https://docs.semarchy.com/self-hosted/latest/guides/design", "https://semarchy.com/"]}], "name": "Semarchy Data Platform (xDM)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:02:52.760414+08:00", "kind": "homepage", "sha256": "ed6346ec2f077b9945449c9e69bcdcce100f716a4a87a5b4d72d7066ab2715f7", "snapshot_path": "sources/ed6346ec2f077b9945449c9e69bcdcce100f716a4a87a5b4d72d7066ab2715f7.txt", "url": "https://semarchy.com/"}, {"fetched_at": "2026-10-26T18:03:39.962303+08:00", "kind": "documentation", "sha256": "b41635adb94166cc43d568639158b02e0fbbb0be23b049de94a806661a0e20cc", "snapshot_path": "sources/b41635adb94166cc43d568639158b02e0fbbb0be23b049de94a806661a0e20cc.txt", "url": "https://docs.semarchy.com/self-hosted/latest/"}, {"fetched_at": "2026-10-26T18:03:50.733614+08:00", "kind": "documentation", "sha256": "167d7f52e0e48329320bdb485a714960e6b20152c24944115f8dde21b73928c9", "snapshot_path": "sources/167d7f52e0e48329320bdb485a714960e6b20152c24944115f8dde21b73928c9.txt", "url": "https://docs.semarchy.com/self-hosted/latest/get-started/concepts"}, {"fetched_at": "2026-10-26T18:04:01.092005+08:00", "kind": "documentation", "sha256": "d510a8013b1e7d35ffb084717b3cd6504873b7d48efd6588e8811e90c655efb1", "snapshot_path": "sources/d510a8013b1e7d35ffb084717b3cd6504873b7d48efd6588e8811e90c655efb1.txt", "url": "https://docs.semarchy.com/self-hosted/latest/guides/design"}], "summary": "商业 MDM/数据平台。官方文档把 master data management 列为平台核心能力；设计指南覆盖逻辑数据模型、数据认证（enrichment/validation）、match and merge、golden records、MDM Web 应用、数据管理工作流，以及 data product 的 build/deploy。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:391740664','OpenMetadata','{"deployment": ["自托管部署"], "features": ["中央元数据知识图谱", "130+ 数据源连接器", "lineage、glossary、classification、quality 等元数据", "REST API、SDK 与 MCP server", "Apache-2.0 开源，可部署服务端"], "github_repository_id": 391740664, "homepage": "https://open-metadata.org", "id": "github:391740664", "leaf_matches": [{"reason": "官方治理文档把术语表、分类/标签和领域作为受管对象并关联数据资产；术语表审批要求指定 reviewer 通过 Task 审阅，保留 Draft/Approved/Rejected 状态；所有者/团队层级和领域把责任落到资产；角色策略约束治理操作，活动流与任务保留可归属的治理历史。这些共同覆盖治理规则、问责结构、受治理流程三项核心，目录发现、血缘和质量仅作外围能力。", "slug": "data-governance-platform", "source_urls": ["https://docs.open-metadata.org/v2.0.x/how-to-guides/data-governance.md", "https://docs.open-metadata.org/v2.0.x/how-to-guides/data-governance/glossary/approval.md", "https://docs.open-metadata.org/v2.0.x/how-to-guides/guide-for-data-users/data-ownership.md", "https://docs.open-metadata.org/v2.0.x/how-to-guides/admin-guide/roles-policies.md", "https://docs.open-metadata.org/v2.0.x/how-to-guides/data-marketplace/domains.md"]}, {"reason": "README 与官网正文确认 OpenMetadata 把技术元数据、lineage、glossary、classification 等汇入统一元数据知识图谱，以 130+ connectors 采集并通过 API、SDK、MCP server 提供给人和机器；仓库与许可证确认 Apache-2.0 身份。", "slug": "metadata-management-platform", "source_urls": ["https://api.github.com/repos/open-metadata/OpenMetadata", "https://open-metadata.org/", "https://raw.githubusercontent.com/open-metadata/OpenMetadata/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/open-metadata/OpenMetadata/license", "name": "OpenMetadata", "repository_url": "https://github.com/open-metadata/OpenMetadata", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:02:09.686327+08:00", "kind": "repository_metadata", "sha256": "f7bd41e43606ed52bd1e3c25074954bd8b6521ca13aac4435fa7f5fae3481a1f", "snapshot_path": "sources/f7bd41e43606ed52bd1e3c25074954bd8b6521ca13aac4435fa7f5fae3481a1f.txt", "url": "https://api.github.com/repos/open-metadata/OpenMetadata"}, {"fetched_at": "2026-10-26T18:02:09.674028+08:00", "kind": "license", "sha256": "69d6a1c5a439b9b98f732d78ee17bb8651859dde31597c7edb7cf597ec355589", "snapshot_path": "sources/69d6a1c5a439b9b98f732d78ee17bb8651859dde31597c7edb7cf597ec355589.txt", "url": "https://api.github.com/repos/open-metadata/OpenMetadata/license"}, {"fetched_at": "2026-10-26T18:05:49.265086+08:00", "kind": "documentation", "sha256": "ac3aaca8df4f4c1e6df3ef6e41f86f0bb4e189868c3dc657c4df9d578feedd4a", "snapshot_path": "sources/ac3aaca8df4f4c1e6df3ef6e41f86f0bb4e189868c3dc657c4df9d578feedd4a.txt", "url": "https://docs.open-metadata.org/v2.0.x/developers/architecture.md"}, {"fetched_at": "2026-10-26T18:05:25.691687+08:00", "kind": "documentation", "sha256": "82f4a9a04f35c451f1b6f21e14883ddac8fcfb74203fcce3a3f884df504e7b42", "snapshot_path": "sources/82f4a9a04f35c451f1b6f21e14883ddac8fcfb74203fcce3a3f884df504e7b42.txt", "url": "https://docs.open-metadata.org/v2.0.x/how-to-guides/admin-guide/roles-policies.md"}, {"fetched_at": "2026-10-26T18:05:17.569255+08:00", "kind": "documentation", "sha256": "599b02f0074931befc7f60af5b56470b4fd5503d3312bfbb5da48694b3780887", "snapshot_path": "sources/599b02f0074931befc7f60af5b56470b4fd5503d3312bfbb5da48694b3780887.txt", "url": "https://docs.open-metadata.org/v2.0.x/how-to-guides/data-governance.md"}, {"fetched_at": "2026-10-26T18:05:17.610752+08:00", "kind": "documentation", "sha256": "f340caa71ac833c317ebe653204af841c8fb89dbb4b8810df7a8c2d3ee0526fc", "snapshot_path": "sources/f340caa71ac833c317ebe653204af841c8fb89dbb4b8810df7a8c2d3ee0526fc.txt", "url": "https://docs.open-metadata.org/v2.0.x/how-to-guides/data-governance/glossary/approval.md"}, {"fetched_at": "2026-10-26T18:06:02.004192+08:00", "kind": "documentation", "sha256": "e75024c7f9e2f526ecaedfacc7e34e9ff34288b9e947670f71384002ac0e1a3e", "snapshot_path": "sources/e75024c7f9e2f526ecaedfacc7e34e9ff34288b9e947670f71384002ac0e1a3e.txt", "url": "https://docs.open-metadata.org/v2.0.x/how-to-guides/data-marketplace/domains.md"}, {"fetched_at": "2026-10-26T18:05:17.702730+08:00", "kind": "documentation", "sha256": "13164e3d89d0253a663fa1e4293e7963226a16c673894edab430de39b684e1cc", "snapshot_path": "sources/13164e3d89d0253a663fa1e4293e7963226a16c673894edab430de39b684e1cc.txt", "url": "https://docs.open-metadata.org/v2.0.x/how-to-guides/guide-for-data-users/data-ownership.md"}, {"fetched_at": "2026-10-26T18:05:39.197874+08:00", "kind": "documentation", "sha256": "120692ea57815d865e30921ea2521209105f139d3998ae4b6acb03f232e48db0", "snapshot_path": "sources/120692ea57815d865e30921ea2521209105f139d3998ae4b6acb03f232e48db0.txt", "url": "https://docs.open-metadata.org/v2.0.x/quick-start.md"}, {"fetched_at": "2026-10-26T18:02:24.492561+08:00", "kind": "homepage", "sha256": "4a1b39c27f2c70aacfa51fe519c58fe4cadd13537e2e184d9af902571c9ef588", "snapshot_path": "sources/4a1b39c27f2c70aacfa51fe519c58fe4cadd13537e2e184d9af902571c9ef588.txt", "url": "https://open-metadata.org/"}, {"fetched_at": "2026-10-26T18:02:23.398191+08:00", "kind": "readme", "sha256": "06a9b258ffddcd339488aef2339158bce91d4f7f3708dd726b9829539fe01ae2", "snapshot_path": "sources/06a9b258ffddcd339488aef2339158bce91d4f7f3708dd726b9829539fe01ae2.txt", "url": "https://raw.githubusercontent.com/open-metadata/OpenMetadata/main/README.md"}], "summary": "开源元数据管理与数据目录平台，把 schema、表、列、dashboard、pipeline、ML model、owner、lineage、glossary、classification 等汇聚为统一的元数据知识图谱；通过 130+ connectors 采集，并提供 API、SDK、MCP server 和面向人员的目录界面。仓库与许可证确认 Apache-2.0。", "technology_stack": ["TypeScript", "Java", "Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:mostly-ai','MOSTLY AI Data Intelligence Platform','{"homepage": "https://mostly.ai", "id": "commercial:mostly-ai", "leaf_matches": [{"reason": "官网 synthetic-data-basics 页说明生成式模型从真实数据学习 patterns/correlations/statistical properties，训练后的 generator 可生成新的人工记录；SDK 文档把 Generators、Synthetic Datasets、Connectors 明确为平台核心资源，符合以持久生成器制造人工数据集的定义。", "slug": "synthetic-data-platform", "source_urls": ["https://mostly.ai/", "https://mostly.ai/synthetic-data-basics", "https://mostly.ai/synthetic-data-sdk"]}], "name": "MOSTLY AI Data Intelligence Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:02:32.559539+08:00", "kind": "homepage", "sha256": "c842b584f9075df6bbbeeb84066914a778035af904b1ab29bd37f2fa8045b3e1", "snapshot_path": "sources/c842b584f9075df6bbbeeb84066914a778035af904b1ab29bd37f2fa8045b3e1.txt", "url": "https://mostly.ai/"}, {"fetched_at": "2026-10-26T18:05:20.967580+08:00", "kind": "documentation", "sha256": "733d473961fd112f6d48e5f7d6fb1805fcc05bb1984c7dcf4e72e97cc4d7c87d", "snapshot_path": "sources/733d473961fd112f6d48e5f7d6fb1805fcc05bb1984c7dcf4e72e97cc4d7c87d.txt", "url": "https://mostly.ai/synthetic-data-basics"}, {"fetched_at": "2026-10-26T18:05:21.085300+08:00", "kind": "documentation", "sha256": "4934f1d6f1f8a8504468f2f05c487fe29452caf5e093c1146b18a1a4af2b0bf5", "snapshot_path": "sources/4934f1d6f1f8a8504468f2f05c487fe29452caf5e093c1146b18a1a4af2b0bf5.txt", "url": "https://mostly.ai/synthetic-data-sdk"}], "summary": "商业合成数据平台（官网当前标注 powered by Syntho）。平台在真实数据上训练生成器，再按需生成厂商称高保真、隐私安全的合成数据集；官方 SDK 文档把 Generators、Synthetic Datasets、Connectors 列为平台核心资源，生成器可训练、导出并复用。首页同时提供 Mock Data 和 Simulated Data。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:88740103','Postal','{"deployment": ["自托管部署；官方 README 指向 docs.postalserver.io 的安装说明"], "features": ["通过 SMTP 或 HTTP API 注入外发邮件，并支持多组服务器凭证", "按发送域进行 DNS 检查与 DKIM 签名，管理多个发信 IP 池", "提供投递队列、历史消息、完整日志与 webhook 投递反馈", "内置抑制列表、每服务器发信限额和多组织/多邮件服务器管理"], "github_repository_id": 88740103, "homepage": "https://postalserver.io", "id": "github:88740103", "leaf_matches": [{"reason": "官方 README 与功能列表显示 Postal 是自托管邮件投递平台，支持 SMTP/HTTP API 注入、DKIM/DNS 域名认证、投递队列与 webhook 反馈、抑制列表，符合邮件基础设施管理的四项核心。", "slug": "email-infrastructure-management", "source_urls": ["https://raw.githubusercontent.com/postalserver/postal/main/README.md", "https://docs.postalserver.io/welcome/feature-list"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/postalserver/postal/license", "name": "Postal", "repository_url": "https://github.com/postalserver/postal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:15:59.762432+08:00", "kind": "repository_metadata", "sha256": "1045c11f18c2e456f810f9f9665fdcb5552e0ce6a2c336e15d115b9d3e842d7d", "snapshot_path": "sources/1045c11f18c2e456f810f9f9665fdcb5552e0ce6a2c336e15d115b9d3e842d7d.txt", "url": "https://api.github.com/repos/postalserver/postal"}, {"fetched_at": "2026-10-26T18:15:59.679083+08:00", "kind": "license", "sha256": "70b3cfd296de076a4049ad1ec36c2a306240c45357b08a8712495f77a40719d9", "snapshot_path": "sources/70b3cfd296de076a4049ad1ec36c2a306240c45357b08a8712495f77a40719d9.txt", "url": "https://api.github.com/repos/postalserver/postal/license"}, {"fetched_at": "2026-10-26T18:15:59.436912+08:00", "kind": "readme", "sha256": "cd12bd3c9dae6282fcad76a214c341a698ca3425a4070ede411de1d6dc157bf0", "snapshot_path": "sources/cd12bd3c9dae6282fcad76a214c341a698ca3425a4070ede411de1d6dc157bf0.txt", "url": "https://raw.githubusercontent.com/postalserver/postal/main/README.md"}, {"fetched_at": "2026-10-26T18:16:09.861873+08:00", "kind": "documentation", "sha256": "afd65c5dc217e0c1b8919346baa6fd070bfd48ffe9dc6a310c1109fd5298764a", "snapshot_path": "sources/afd65c5dc217e0c1b8919346baa6fd070bfd48ffe9dc6a310c1109fd5298764a.txt", "url": "https://docs.postalserver.io/welcome/feature-list"}], "summary": "Postal 是一个可自托管的开源邮件投递平台，面向网站和 Web 服务器，提供 SMTP/HTTP API 注入、域名 DNS/DKIM 认证检查、投递队列与反馈、抑制列表。", "technology_stack": ["Ruby"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:26337322','Rancher','{"deployment": ["自托管部署；README 提供 Docker 快速启动与官方安装/升级文档入口"], "features": ["从托管提供商供给 Kubernetes、在自备节点上安装，或导入现有集群", "将多个集群作为受管资产集中查看和管理", "跨集群集中认证与基于角色的访问控制（RBAC）", "集群与资源监控告警、日志外送，以及 Helm Application Catalog 和 Fleet 工作负载交付"], "github_repository_id": 26337322, "homepage": "https://rancher.com", "id": "github:26337322", "leaf_matches": [{"reason": "官方文档说明 Rancher 将 Kubernetes 集群作为受管资产，支持供给/导入、集中认证与 RBAC、监控告警、Helm/Fleet 工作负载交付，符合 Kubernetes 管理平台的集群资产库与原生操作面核心。", "slug": "kubernetes-management-platform", "source_urls": ["https://ranchermanager.docs.rancher.com/v2.15/rancher-manager", "https://www.rancher.com/products/rancher", "https://raw.githubusercontent.com/rancher/rancher/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/rancher/rancher/license", "name": "Rancher", "repository_url": "https://github.com/rancher/rancher", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:17:33.494220+08:00", "kind": "repository_metadata", "sha256": "1561be6797284a5cd716920ff561c1ebbfee8d36db91f86974500b38a4b31ced", "snapshot_path": "sources/1561be6797284a5cd716920ff561c1ebbfee8d36db91f86974500b38a4b31ced.txt", "url": "https://api.github.com/repos/rancher/rancher"}, {"fetched_at": "2026-10-26T18:17:33.563570+08:00", "kind": "license", "sha256": "12946ec5c965868fe2ef3db17d0a3b87edde7abcb72e6dc65c71cc9aee026705", "snapshot_path": "sources/12946ec5c965868fe2ef3db17d0a3b87edde7abcb72e6dc65c71cc9aee026705.txt", "url": "https://api.github.com/repos/rancher/rancher/license"}, {"fetched_at": "2026-10-26T18:17:33.627803+08:00", "kind": "readme", "sha256": "8db98126d2571e4c5258c57b44da28c2765e97af91ad789b1b53a647686d0756", "snapshot_path": "sources/8db98126d2571e4c5258c57b44da28c2765e97af91ad789b1b53a647686d0756.txt", "url": "https://raw.githubusercontent.com/rancher/rancher/main/README.md"}, {"fetched_at": "2026-10-26T18:17:47.300770+08:00", "kind": "homepage", "sha256": "d870c236c9d4d1d4703b0598187fd90638ae6ee46a5fd73c9c143e81ec5963ad", "snapshot_path": "sources/d870c236c9d4d1d4703b0598187fd90638ae6ee46a5fd73c9c143e81ec5963ad.txt", "url": "https://www.rancher.com/products/rancher"}, {"fetched_at": "2026-10-26T18:18:16.601727+08:00", "kind": "documentation", "sha256": "277dbaaaf60917daf624a67fcf96feceb6fe558b5eefa019d2bc968d8b95bca6", "snapshot_path": "sources/277dbaaaf60917daf624a67fcf96feceb6fe558b5eefa019d2bc968d8b95bca6.txt", "url": "https://ranchermanager.docs.rancher.com/v2.15/rancher-manager"}], "summary": "Rancher 是 Apache-2.0 开源的 Kubernetes 管理平台，可供给或导入集群、集中认证与 RBAC、监控告警，并通过 Helm 与 Fleet 交付工作负载；SUSE Rancher Prime 为商业支持版。", "technology_stack": ["Go", "Kubernetes"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:326404870','SigNoz','{"deployment": ["社区版自托管：Docker、Kubernetes 或 Linux", "官方另提供 SigNoz Cloud 与 Enterprise 商业服务"], "features": ["通过 OpenTelemetry 接收日志、指标、追踪等遥测信号", "在同一平台提供 APM、分布式追踪、日志管理与基础设施监控", "从服务图表关联到 trace、日志、基础设施指标和异常，保持上下文调查", "提供告警、仪表板和查询构建器；社区版支持 Docker、Kubernetes、Linux 自托管"], "github_repository_id": 326404870, "homepage": "https://signoz.io", "id": "github:326404870", "leaf_matches": [{"reason": "README 显示 SigNoz 原生接收 OpenTelemetry 日志、指标、追踪等信号，并在同一平台跨信号关联调查，符合可观测性平台的多信号摄取、共享上下文与跨信号调查三项核心。", "slug": "observability-platform", "source_urls": ["https://raw.githubusercontent.com/SigNoz/signoz/main/README.md", "https://api.github.com/repos/SigNoz/signoz"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/SigNoz/signoz/main/LICENSE", "license_review": {"rationale": "Full repository LICENSE read: content outside ee/ and cmd/enterprise/ is MIT Expat; those enterprise directories have a separate license and are excluded from this open-source-core classification.", "reviewer": "collection-agent", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/SigNoz/signoz/main/LICENSE", "spdx_id": "MIT"}, "name": "SigNoz", "repository_url": "https://github.com/SigNoz/signoz", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:18:40.645733+08:00", "kind": "repository_metadata", "sha256": "3a30d5fa1475ce56d25aed6db6b52ccd46b335536bd892b4ad524b3115d74d9d", "snapshot_path": "sources/3a30d5fa1475ce56d25aed6db6b52ccd46b335536bd892b4ad524b3115d74d9d.txt", "url": "https://api.github.com/repos/SigNoz/signoz"}, {"fetched_at": "2026-10-26T18:18:39.576459+08:00", "kind": "readme", "sha256": "25621be3e5a76e70740b3b55a36b35a9074af930c6c189df633c7e9cadbceb73", "snapshot_path": "sources/25621be3e5a76e70740b3b55a36b35a9074af930c6c189df633c7e9cadbceb73.txt", "url": "https://raw.githubusercontent.com/SigNoz/signoz/main/README.md"}, {"fetched_at": "2026-10-26T18:18:49.724671+08:00", "kind": "license", "sha256": "449417bc4e96c1787726c58de4b846b2d5146076e4a0a82a2093452ec0882abf", "snapshot_path": "sources/449417bc4e96c1787726c58de4b846b2d5146076e4a0a82a2093452ec0882abf.txt", "url": "https://raw.githubusercontent.com/SigNoz/signoz/main/LICENSE"}], "summary": "SigNoz 是开源核心（社区版 MIT；ee/ 与 cmd/enterprise/ 为企业许可）的可观测性平台，基于 OpenTelemetry 统一日志、指标、追踪、异常与告警，并提供跨信号关联调查。", "technology_stack": ["TypeScript", "Go", "OpenTelemetry"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:91797088','Nuclio','{"deployment": ["以 Docker 容器运行 Nuclio Dashboard", "部署到现有 Kubernetes 集群"], "features": ["通过 Web 仪表板或 nuctl 创建、部署函数", "为函数绑定 HTTP、Kafka 等事件触发器", "函数调用、日志与监控", "按负载自动伸缩，支持 Docker 与 Kubernetes"], "github_repository_id": 91797088, "homepage": "https://nuclio.io", "id": "github:91797088", "leaf_matches": [{"reason": "Nuclio 官方 README 显示可通过 Web 仪表板创建项目与函数、绑定事件触发器、部署并调用函数，并提供日志与监控，符合无服务器管理平台的函数记录与调用连接核心。", "slug": "serverless-management-platform", "source_urls": ["https://raw.githubusercontent.com/nuclio/nuclio/master/README.md", "https://api.github.com/repos/nuclio/nuclio"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/nuclio/nuclio/license", "name": "Nuclio", "repository_url": "https://github.com/nuclio/nuclio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:18:15.451008+08:00", "kind": "repository_metadata", "sha256": "b985d79307e97f3f881ff772f912fa1379f5754c118c6cb74f6ced2fa5ec2bd2", "snapshot_path": "sources/b985d79307e97f3f881ff772f912fa1379f5754c118c6cb74f6ced2fa5ec2bd2.txt", "url": "https://api.github.com/repos/nuclio/nuclio"}, {"fetched_at": "2026-10-26T18:20:03.748892+08:00", "kind": "license", "sha256": "78b38140076742447518ca565815f208f0fb36866492792d8385b634160b2c34", "snapshot_path": "sources/78b38140076742447518ca565815f208f0fb36866492792d8385b634160b2c34.txt", "url": "https://api.github.com/repos/nuclio/nuclio/license"}, {"fetched_at": "2026-10-26T18:20:05.168760+08:00", "kind": "readme", "sha256": "28ba0e3750aab0058ed306a4c7cef58384825d986e6783349e156d71655b23f6", "snapshot_path": "sources/28ba0e3750aab0058ed306a4c7cef58384825d986e6783349e156d71655b23f6.txt", "url": "https://raw.githubusercontent.com/nuclio/nuclio/master/README.md"}], "summary": "Nuclio 是 Apache-2.0 开源的 Serverless 函数平台，提供 Web 仪表板、函数部署、事件触发器以及日志与监控；可独立运行于 Docker 或部署到 Kubernetes。", "technology_stack": ["Go", "Docker", "Kubernetes"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:309820286','Fleet','{"deployment": ["在受管设备安装 fleetd，或连接 Apple Business / Microsoft Entra 自动注册", "通过集中 Fleet 服务器统一下发 profiles、policies 与软件"], "features": ["通过 fleetd agent 手动注册，或经 Apple Business / Microsoft Entra 自动注册设备", "以配置 profiles 集中执行 macOS、iOS、iPadOS、Windows、Android 的 OS 安全设置", "按平台定向 profiles 与 policies；标签/团队细分定向属 Fleet Premium", "policies 按平台/标签（标签定向为 Premium）评估设备合规并显示 passing/failing", "软件部署、补丁状态与基于 osquery 的清单/查询", "卸载、关闭 MDM、删除或抹除设备以完成退役"], "github_repository_id": 309820286, "homepage": "https://fleetdm.com", "id": "github:309820286", "leaf_matches": [{"reason": "Fleet 官方文档显示设备经 fleetd 手动注册或经 Apple Business / Microsoft Entra 自动注册进入受管集合；配置 profiles 按平台定向执行 OS 设置并报告下发/验证状态（标签/团队细分定向属 Premium）；policies 按平台/标签评估设备合规并显示 passing/failing；并记录卸载、关闭 MDM、删除或抹除的退役流程。该关系仅基于 MIT 开源核心，不包含 ee/ 企业功能。", "slug": "endpoint-management-uem", "source_urls": ["https://raw.githubusercontent.com/fleetdm/fleet/main/README.md", "https://fleetdm.com/guides/enroll-hosts", "https://fleetdm.com/guides/custom-os-settings", "https://fleetdm.com/securing/what-are-fleet-policies"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/fleetdm/fleet/license", "license_review": {"rationale": "Repository LICENSE shows content outside ee/ and docs/ is MIT Expat, while ee/ carries a separate enterprise license; only the open-source core is claimed.", "reviewer": "collection-agent", "scope": "community_core", "source_url": "https://api.github.com/repos/fleetdm/fleet/license", "spdx_id": "MIT"}, "name": "Fleet", "repository_url": "https://github.com/fleetdm/fleet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:18:21.493545+08:00", "kind": "repository_metadata", "sha256": "c206a941721c9039563f6f878c2b8f3339bbae929802ed1e7eb26d9b31d46d00", "snapshot_path": "sources/c206a941721c9039563f6f878c2b8f3339bbae929802ed1e7eb26d9b31d46d00.txt", "url": "https://api.github.com/repos/fleetdm/fleet"}, {"fetched_at": "2026-10-26T18:18:34.869201+08:00", "kind": "license", "sha256": "4198c4be21df506c0216401f26350c76683ab474bf9a420272da452d61d49000", "snapshot_path": "sources/4198c4be21df506c0216401f26350c76683ab474bf9a420272da452d61d49000.txt", "url": "https://api.github.com/repos/fleetdm/fleet/license"}, {"fetched_at": "2026-10-26T18:20:19.062949+08:00", "kind": "readme", "sha256": "48e486d6a6f26a7b3c9fc8b5e16338a3b930df1bf70be01a89fe32d1de9270c0", "snapshot_path": "sources/48e486d6a6f26a7b3c9fc8b5e16338a3b930df1bf70be01a89fe32d1de9270c0.txt", "url": "https://raw.githubusercontent.com/fleetdm/fleet/main/README.md"}, {"fetched_at": "2026-10-26T18:31:50.239316+08:00", "kind": "documentation", "sha256": "30843a0c2f1cb01716cede7c65eb11533669ac7df64a6aa3b71fffd3d9f14607", "snapshot_path": "sources/30843a0c2f1cb01716cede7c65eb11533669ac7df64a6aa3b71fffd3d9f14607.txt", "url": "https://fleetdm.com/guides/enroll-hosts"}, {"fetched_at": "2026-10-26T18:31:52.507511+08:00", "kind": "documentation", "sha256": "dfda4ee9ceaf2787cbcfd2805aa4fc1c74038be74aca86993945658d617c9e66", "snapshot_path": "sources/dfda4ee9ceaf2787cbcfd2805aa4fc1c74038be74aca86993945658d617c9e66.txt", "url": "https://fleetdm.com/guides/custom-os-settings"}, {"fetched_at": "2026-10-26T18:32:52.871550+08:00", "kind": "documentation", "sha256": "8bcb12de4bfa6b82afab264ddb384de6ee5b7fe39751a7df53ae99d1865e9c59", "snapshot_path": "sources/8bcb12de4bfa6b82afab264ddb384de6ee5b7fe39751a7df53ae99d1865e9c59.txt", "url": "https://fleetdm.com/securing/what-are-fleet-policies"}], "summary": "Fleet 是开源核心（MIT Expat；ee/ 目录按企业许可）的端点管理与 MDM 平台，集中管理已注册设备的配置 profiles、合规 policies、软件部署与补丁状态，并支持卸载、关闭 MDM、删除或抹除等退役操作，覆盖多种操作系统。", "technology_stack": ["Go", "osquery", "MDM"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:143291989','Uyuni','{"deployment": ["部署 Uyuni Server 并配置/克隆软件通道", "为受管系统配置客户端联系方法并订阅相应软件通道"], "features": ["维护并克隆软件通道中的补丁目录，含厂商通道同步与 retracted 状态传播（Patch Sync/CLM）", "按客户端订阅的通道与已安装版本判定适用补丁", "对单台或批量客户端选择补丁并安排安装时间", "在 Pending Actions 与状态列跟踪补丁安装进度"], "github_repository_id": 143291989, "homepage": "https://www.uyuni-project.org/", "id": "github:143291989", "leaf_matches": [{"reason": "Uyuni 官方补丁文档显示其维护/克隆软件通道中的补丁目录，并通过 Patch Sync/CLM 处理 retracted 状态传播；按客户端订阅通道与已安装版本判定适用补丁；支持单机或批量选择补丁、安排安装时间，并在 Pending Actions/状态列跟踪执行。该关系仅覆盖补丁/更新循环，不把通用配置管理或完整合规审计纳入断言。", "slug": "patch-management", "source_urls": ["https://raw.githubusercontent.com/uyuni-project/uyuni/master/README.md", "https://www.uyuni-project.org/uyuni-docs/en/uyuni/administration/patch-management.html", "https://www.uyuni-project.org/uyuni-docs/en/uyuni/client-configuration/patch-management.html", "https://www.uyuni-project.org/uyuni-docs/en/uyuni/reference/systems/system-details/sd-patches.html"]}, {"reason": "官方站点与 README 表明 Uyuni 集中注册并管理大量 Linux 机器，执行补丁/软件包部署、模板置备、Salt 配置与合规审计，覆盖受管资产、控制平面操作和可追踪生命周期。", "slug": "server-management-platform", "source_urls": ["https://www.uyuni-project.org/", "https://raw.githubusercontent.com/uyuni-project/uyuni/master/README.md"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/uyuni-project/uyuni/license", "name": "Uyuni", "repository_url": "https://github.com/uyuni-project/uyuni", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:18:22.986724+08:00", "kind": "repository_metadata", "sha256": "091a84ec4d104ef668527400df898b2f8f960126261a2948785acbbd07fb163b", "snapshot_path": "sources/091a84ec4d104ef668527400df898b2f8f960126261a2948785acbbd07fb163b.txt", "url": "https://api.github.com/repos/uyuni-project/uyuni"}, {"fetched_at": "2026-10-26T18:20:13.254875+08:00", "kind": "license", "sha256": "c42c24b3e2ee1a83cdf8bc8bad365a603b016acaae6e4d15f85df249b58c6d60", "snapshot_path": "sources/c42c24b3e2ee1a83cdf8bc8bad365a603b016acaae6e4d15f85df249b58c6d60.txt", "url": "https://api.github.com/repos/uyuni-project/uyuni/license"}, {"fetched_at": "2026-10-26T18:20:14.323128+08:00", "kind": "readme", "sha256": "1b149f42fbbba47d05f9a52051574b52e20b251e455fc4751d85e572625dbfe6", "snapshot_path": "sources/1b149f42fbbba47d05f9a52051574b52e20b251e455fc4751d85e572625dbfe6.txt", "url": "https://raw.githubusercontent.com/uyuni-project/uyuni/master/README.md"}, {"fetched_at": "2026-10-26T18:21:10.960623+08:00", "kind": "documentation", "sha256": "a4957f1553d2226192c1e8236a62bc3153034f92dd4a7a610dc9b808d19a070d", "snapshot_path": "sources/a4957f1553d2226192c1e8236a62bc3153034f92dd4a7a610dc9b808d19a070d.txt", "url": "https://www.uyuni-project.org/uyuni-docs/en/uyuni/administration/patch-management.html"}, {"fetched_at": "2026-10-26T18:31:23.291997+08:00", "kind": "documentation", "sha256": "50ea1794d1663954b653906e47cb6e44cc013d61a639f9d7e6d77e219bb00824", "snapshot_path": "sources/50ea1794d1663954b653906e47cb6e44cc013d61a639f9d7e6d77e219bb00824.txt", "url": "https://www.uyuni-project.org/uyuni-docs/en/uyuni/client-configuration/patch-management.html"}, {"fetched_at": "2026-10-26T18:31:23.304374+08:00", "kind": "documentation", "sha256": "e202aef8a14b10dbd4efb8932d1405ff0382ff15f5419f7c75d7df488a1b6e68", "snapshot_path": "sources/e202aef8a14b10dbd4efb8932d1405ff0382ff15f5419f7c75d7df488a1b6e68.txt", "url": "https://www.uyuni-project.org/uyuni-docs/en/uyuni/reference/systems/system-details/sd-patches.html"}, {"fetched_at": "2026-10-26T18:19:59.938289+08:00", "kind": "homepage", "sha256": "8d22c3c433cb9ea947da6e8b63da8e70fb41fada262de02b46f195bfbbcf0b0c", "snapshot_path": "sources/8d22c3c433cb9ea947da6e8b63da8e70fb41fada262de02b46f195bfbbcf0b0c.txt", "url": "https://www.uyuni-project.org/"}], "summary": "Uyuni 是 GPL-2.0 开源的 Linux 系统管理与补丁管理平台，维护软件通道中的补丁目录，按通道订阅与已安装版本判定适用补丁，并支持单机或批量安排安装与状态跟踪。", "technology_stack": ["Java", "Linux"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cloudflare-cdn','Cloudflare CDN','{"homepage": "https://www.cloudflare.com/cdn/", "id": "commercial:cloudflare-cdn", "leaf_matches": [{"reason": "官方页面正文说明其将静态与动态内容缓存于 335+ 城市的数据中心并从边缘直接交付，提供即时清除、API 驱动控制与细粒度 Cache Rules，并以切换 DNS 的反向代理方式接入，对应交付配置、边缘缓存与清除控制核心。", "slug": "cdn-management", "source_urls": ["https://www.cloudflare.com/cdn/"]}], "name": "Cloudflare CDN", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:19:26.346453+08:00", "kind": "homepage", "sha256": "641ba4abc63952a46705787cc91de5813c3617922558a2c2470ed408b7390e64", "snapshot_path": "sources/641ba4abc63952a46705787cc91de5813c3617922558a2c2470ed408b7390e64.txt", "url": "https://www.cloudflare.com/cdn/"}], "summary": "Cloudflare CDN 是 Cloudflare 全球边缘网络上的内容分发服务，将静态与动态内容缓存于 335+ 城市的数据中心，并从边缘直接交付、吸收源站流量。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fastly-cdn','Fastly CDN','{"homepage": "https://www.fastly.com/products/cdn", "id": "commercial:fastly-cdn", "leaf_matches": [{"reason": "官方 CDN 页面正文以现代化 POP 边缘网络、Instant Purge 和 UI/API 可配置控制为特色，说明内容在 Fastly 边缘 POP 缓存并可即时清除，属于在提供商边缘网络上配置和运营内容交付的控制平面。", "slug": "cdn-management", "source_urls": ["https://www.fastly.com/products/cdn"]}], "name": "Fastly CDN", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:19:28.662811+08:00", "kind": "homepage", "sha256": "03e503e62c34463b18fd679cdb5a42e7076dd324ede44bfd552e503693ecb230", "snapshot_path": "sources/03e503e62c34463b18fd679cdb5a42e7076dd324ede44bfd552e503693ecb230.txt", "url": "https://www.fastly.com/products/cdn"}], "summary": "Fastly CDN 是 Fastly 边缘网络上的商业内容分发服务，提供边缘缓存、Instant Purge 清除与可配置的交付控制。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:52796596','NetBox','{"deployment": ["Self-hosted web application (NetBox Community); NetBox Cloud/Enterprise are separate offerings"], "features": ["Inter-linked data model covering racks, devices, cables, IP addresses, VLANs, circuits and power", "Rack view and cable trace for physical placement and connectivity", "Single user interface and programmable APIs for infrastructure records", "Configuration rendering from stored data via templates"], "github_repository_id": 52796596, "homepage": "https://github.com/netbox-community/netbox", "id": "github:52796596", "leaf_matches": [{"reason": "README 明确其为传统 IPAM/DCIM 应用的继任者，数据模型包含机架、设备、线缆与电力，并提供 Rack View 和 Cable Trace，对应物理位置、连接与供电资源的结构化记录。", "slug": "data-center-infrastructure-management-dcim", "source_urls": ["https://raw.githubusercontent.com/netbox-community/netbox/main/README.md"]}, {"reason": "官方README直接说明NetBox是网络预期状态的记录源，模型包含IP地址，权限可限制IP地址修改；以IP范围分配触发事件为例，所有对象创建/修改/删除均记录用户及变更历史，并提供统一UI与API。据此仅确认地址/范围的记录、分配和变更管理，不额外断言未由README展开的利用率计算。", "slug": "ip-address-management-ipam", "source_urls": ["https://raw.githubusercontent.com/netbox-community/netbox/main/README.md"]}, {"reason": "NetBox 将设备、电缆、端口、电路、提供商、IP/VLAN 等作为持久且相互关联的记录，形成网络资产与资源的受治理参考，符合运营商侧电信资源库存的核心记录结构；它不建模光纤接续/分光器，因此不匹配光纤网络管理叶。", "slug": "telecom-inventory-management", "source_urls": ["https://github.com/netbox-community/netbox", "https://raw.githubusercontent.com/netbox-community/netbox/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/netbox-community/netbox/license", "name": "NetBox", "repository_url": "https://github.com/netbox-community/netbox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:20:33.191343+08:00", "kind": "repository_metadata", "sha256": "022bfa23881f67ec8b8c988feeeadb734c0e85552126367e0926360cdfb4f8d4", "snapshot_path": "sources/022bfa23881f67ec8b8c988feeeadb734c0e85552126367e0926360cdfb4f8d4.txt", "url": "https://api.github.com/repos/netbox-community/netbox"}, {"fetched_at": "2026-10-26T18:20:34.756058+08:00", "kind": "license", "sha256": "f0eb0311250794dcbc280398e4e79984192813cf69777d745304c1c97036f503", "snapshot_path": "sources/f0eb0311250794dcbc280398e4e79984192813cf69777d745304c1c97036f503.txt", "url": "https://api.github.com/repos/netbox-community/netbox/license"}, {"fetched_at": "2026-10-26T18:39:20.969906+08:00", "kind": "repository_metadata", "sha256": "6e5c53617affff5ee182757e857f1a966de764b26b57307510e599c422dee123", "snapshot_path": "sources/6e5c53617affff5ee182757e857f1a966de764b26b57307510e599c422dee123.txt", "url": "https://github.com/netbox-community/netbox"}, {"fetched_at": "2026-10-26T21:49:43.058692+08:00", "kind": "repository_metadata", "sha256": "d7b33074ccec3b3362583485b16880f0cc2423ab54eb67b2f9edc7ef33371149", "snapshot_path": "sources/d7b33074ccec3b3362583485b16880f0cc2423ab54eb67b2f9edc7ef33371149.txt", "url": "https://github.com/netbox-community/netbox"}, {"fetched_at": "2026-10-26T21:49:46.052015+08:00", "kind": "license", "sha256": "0d542e0c8804e39aa7f37eb00da5a762149dc682d7829451287e11b938e94594", "snapshot_path": "sources/0d542e0c8804e39aa7f37eb00da5a762149dc682d7829451287e11b938e94594.txt", "url": "https://raw.githubusercontent.com/netbox-community/netbox/main/LICENSE.txt"}, {"fetched_at": "2026-10-26T18:20:36.071301+08:00", "kind": "readme", "sha256": "3674638ca1d513087d21d8da8325587dba33d57a9085e44099ccdf67db2b5e2c", "snapshot_path": "sources/3674638ca1d513087d21d8da8325587dba33d57a9085e44099ccdf67db2b5e2c.txt", "url": "https://raw.githubusercontent.com/netbox-community/netbox/main/README.md"}], "summary": "NetBox 是开源的网络基础设施建模与记录系统，作为传统 IPAM/DCIM 的继任者，提供机架、设备、线缆、电力、IP 与电路等相互关联的数据模型。", "technology_stack": ["Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:infoblox-ddi','Infoblox DDI','{"homepage": "https://www.infoblox.com/products/ddi/", "id": "commercial:infoblox-ddi", "leaf_matches": [{"reason": "官方 DDI 页面正文以统一管理 DNS、DHCP 与 IPAM 为核心，并提供 Universal DDI Management 与 NIOS DDI 产品线，对应 DNS 与 DHCP 配置的集中管理。", "slug": "dns-dhcp-management", "source_urls": ["https://www.infoblox.com/products/ddi/"]}], "name": "Infoblox DDI", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:19:30.978853+08:00", "kind": "homepage", "sha256": "2efc2fa3a2426f647311a69f68d46ab5ee7787c164d7f100252c018337778bcf", "snapshot_path": "sources/2efc2fa3a2426f647311a69f68d46ab5ee7787c164d7f100252c018337778bcf.txt", "url": "https://www.infoblox.com/products/ddi/"}], "summary": "Infoblox DDI 是集中管理 DNS、DHCP 与 IPAM 的商业网络服务管理平台，覆盖混合与多云环境中的名称解析和地址分配。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:108726321','Technitium DNS Server','{"deployment": ["Self-hosted on Windows, Linux, macOS or Raspberry Pi; Docker image available"], "features": ["Authoritative and recursive DNS service", "Zone and resource record management through a web console", "Built-in DHCP server for multiple networks", "Clustering to manage two or more DNS server instances from a single admin console", "DNSSEC validation and encrypted DNS transports"], "github_repository_id": 108726321, "homepage": "https://technitium.com/dns/", "id": "github:108726321", "leaf_matches": [{"reason": "README 说明其同时提供权威/递归 DNS 与内置 DHCP 服务，配置由同一产品交付的 Web 控制台集中管理，集群功能可从单一控制台管理多个 DNS 服务器实例，覆盖 DNS 区域与 DHCP 配置在服务实例上的管理与传播；管理面与服务端并非独立产品。", "slug": "dns-dhcp-management", "source_urls": ["https://raw.githubusercontent.com/TechnitiumSoftware/DnsServer/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/TechnitiumSoftware/DnsServer/license", "name": "Technitium DNS Server", "repository_url": "https://github.com/TechnitiumSoftware/DnsServer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:19:12.663835+08:00", "kind": "repository_metadata", "sha256": "ca2e0aadf1f0d10b1fbb23a114b8c463ee1680ba1a0c02beb5ee1e2eb561b864", "snapshot_path": "sources/ca2e0aadf1f0d10b1fbb23a114b8c463ee1680ba1a0c02beb5ee1e2eb561b864.txt", "url": "https://api.github.com/repos/TechnitiumSoftware/DnsServer"}, {"fetched_at": "2026-10-26T18:19:14.463057+08:00", "kind": "license", "sha256": "d362d1b19ab73f0865cf6ac385d17727e7ed17929c6a12e7589e44e39a0c3f52", "snapshot_path": "sources/d362d1b19ab73f0865cf6ac385d17727e7ed17929c6a12e7589e44e39a0c3f52.txt", "url": "https://api.github.com/repos/TechnitiumSoftware/DnsServer/license"}, {"fetched_at": "2026-10-26T18:19:15.603532+08:00", "kind": "readme", "sha256": "bc042cb4c9bfcf2fcd031291876fb148136e0c3839b17b3ff53ebdef6c6f403d", "snapshot_path": "sources/bc042cb4c9bfcf2fcd031291876fb148136e0c3839b17b3ff53ebdef6c6f403d.txt", "url": "https://raw.githubusercontent.com/TechnitiumSoftware/DnsServer/master/README.md"}], "summary": "Technitium DNS Server 是开源的权威/递归 DNS 服务器，内置 DHCP 服务器与同一产品交付的 Web 管理控制台；集群控制台可从一个控制台管理多个实例，但不是独立于第三方守护进程的通用 DDI 管理层。", "technology_stack": ["C#"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:332880689','Coolify','{"deployment": ["官方安装脚本部署到自有服务器", "官方托管 Coolify Cloud 选项"], "features": ["从 GitHub/GitLab/Bitbucket/Gitea 或 Dockerfile/Docker Compose 构建并部署应用", "保留应用镜像并回滚到先前部署", "环境变量、密钥、域名与自动 HTTPS 管理", "部署与运行日志、资源状态监控", "控制台、API、CLI 与团队级访问控制"], "github_repository_id": 332880689, "homepage": "https://coolify.io/", "id": "github:332880689", "leaf_matches": [{"reason": "README 证明其以应用为部署与回滚单元，提供应用级环境变量、域名/HTTPS、日志和团队权限，控制台/API/CLI 并存；自托管平台承担构建、发布与路由，符合应用粒度的 PaaS 控制台核心。", "slug": "paas-management-console", "source_urls": ["https://raw.githubusercontent.com/coollabsio/coolify/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/coollabsio/coolify/main/LICENSE", "license_review": {"rationale": "完整读取仓库根目录 LICENSE，正文为 Apache License Version 2.0 全文，包含 Terms and Conditions 与 limitations under the license，按仓库整体适用 Apache-2.0。", "reviewer": "collection-editor", "scope": "repository", "source_url": "https://raw.githubusercontent.com/coollabsio/coolify/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Coolify", "repository_url": "https://github.com/coollabsio/coolify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:38:35.251513+08:00", "kind": "repository_metadata", "sha256": "a7890c5b6bc262c999ce83fc6c1e124299c1b80f51396c3b5de59278ab0ad2c2", "snapshot_path": "sources/a7890c5b6bc262c999ce83fc6c1e124299c1b80f51396c3b5de59278ab0ad2c2.txt", "url": "https://github.com/coollabsio/coolify"}, {"fetched_at": "2026-10-26T18:38:15.006287+08:00", "kind": "readme", "sha256": "9ddd86aae945aa2a6ddb91f32f047ff311772e8a2b0700bd8689f3f6ad8d3cf0", "snapshot_path": "sources/9ddd86aae945aa2a6ddb91f32f047ff311772e8a2b0700bd8689f3f6ad8d3cf0.txt", "url": "https://raw.githubusercontent.com/coollabsio/coolify/main/README.md"}, {"fetched_at": "2026-10-26T18:39:44.911674+08:00", "kind": "license", "sha256": "1a3e7d8a466b117e9c26062db5fd6a59bb03caf617517d1f57a4bc7f29dc9d24", "snapshot_path": "sources/1a3e7d8a466b117e9c26062db5fd6a59bb03caf617517d1f57a4bc7f29dc9d24.txt", "url": "https://raw.githubusercontent.com/coollabsio/coolify/main/LICENSE"}], "summary": "Coolify 是 Apache-2.0 开源、可自托管的 PaaS 管理控制台：以应用为记录单元，从 Git 构建并部署应用，保留应用镜像用于回滚，并提供环境变量/密钥、域名与自动 HTTPS、部署/运行日志及团队权限。它同时暴露服务器与容器终端，和容器管理的边界有重叠，本次仅以应用部署与发布回滚等应用粒度能力作为类型匹配依据。", "technology_stack": ["Docker", "Nixpacks", "Railpack", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:2316088','OpenXPKI','{"deployment": ["Debian 软件包自托管安装", "官方 Docker 镜像部署"], "features": ["基于 WebUI 的证书与 CA 管理", "单实例运行多个独立 CA 及 CA 代际自动滚动", "可定制工作流驱动证书请求、续期与吊销", "SCEP、EST、SimpleCMC、ACME 注册协议", "OpenSSL 加密层与 HSM 支持", "证书状态报告与告警"], "github_repository_id": 2316088, "homepage": "https://www.openxpki.org/", "id": "github:2316088", "leaf_matches": [{"reason": "官网与 README 证明其管理多个持久 CA、CA 代际滚动，并以工作流执行证书请求、续期和吊销；WebUI 面向运营者提供 CA 与证书生命周期控制，符合 PKI 管理核心。", "slug": "pki-management", "source_urls": ["https://www.openxpki.org/", "https://raw.githubusercontent.com/openxpki/openxpki/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/openxpki/openxpki/master/LICENSE", "license_review": {"rationale": "完整读取仓库根目录 LICENSE，正文为 Apache License Version 2.0 全文，包含 Terms and Conditions 与 limitations under the license，按仓库整体适用 Apache-2.0。", "reviewer": "collection-editor", "scope": "repository", "source_url": "https://raw.githubusercontent.com/openxpki/openxpki/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "OpenXPKI", "repository_url": "https://github.com/openxpki/openxpki", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:41:23.487922+08:00", "kind": "repository_metadata", "sha256": "2631556a4b6d98b6a9a0f48deade9f30d325315f43434d3da651bf0da85a41f4", "snapshot_path": "sources/2631556a4b6d98b6a9a0f48deade9f30d325315f43434d3da651bf0da85a41f4.txt", "url": "https://github.com/openxpki/openxpki"}, {"fetched_at": "2026-10-26T18:41:25.142235+08:00", "kind": "readme", "sha256": "3c7a78d58fe07ea274d8e9d8dda9226b6a4021fed88fd2429d08f5ca8dbdcc4b", "snapshot_path": "sources/3c7a78d58fe07ea274d8e9d8dda9226b6a4021fed88fd2429d08f5ca8dbdcc4b.txt", "url": "https://raw.githubusercontent.com/openxpki/openxpki/master/README.md"}, {"fetched_at": "2026-10-26T18:41:26.944805+08:00", "kind": "license", "sha256": "b2bd58d42da85de61dd702a9bd5b410f76c8230665db74fd402a1b6964539393", "snapshot_path": "sources/b2bd58d42da85de61dd702a9bd5b410f76c8230665db74fd402a1b6964539393.txt", "url": "https://raw.githubusercontent.com/openxpki/openxpki/master/LICENSE"}, {"fetched_at": "2026-10-26T18:41:52.937513+08:00", "kind": "homepage", "sha256": "6b5ac7f489a1a2b6dc57bdcf576bc589736ed9c7b7277a80e9b832d58d51da60", "snapshot_path": "sources/6b5ac7f489a1a2b6dc57bdcf576bc589736ed9c7b7277a80e9b832d58d51da60.txt", "url": "https://www.openxpki.org/"}], "summary": "OpenXPKI 是 Apache-2.0 开源的 PKI/Trustcenter 管理应用，提供 WebUI、单实例多 CA 与 CA 代际滚动、证书请求/续期/吊销工作流、SCEP/EST/SimpleCMC/ACME 注册协议、HSM 支持和报告。其核心是持久化 CA 与受策略约束的证书生命周期，符合 PKI 管理叶。", "technology_stack": ["Perl", "OpenSSL", "Ember.js", "YAML"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zylo','Zylo','{"homepage": "https://zylo.com/", "id": "commercial:zylo", "leaf_matches": [{"reason": "官方 /product 正文说明其以财务系统数据建立持续更新的 SaaS/AI 支出系统记录，统一软件支出、使用与合同；连接已购许可证与实际使用，回收未使用和低使用席位；按节省潜力排序续订；识别重复应用；并以可辩护的系统记录支持策略执行、审计准备与合规，覆盖资产记录、许可证使用与续订优化闭环。", "slug": "saas-management", "source_urls": ["https://zylo.com/product", "https://zylo.com/"]}], "name": "Zylo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:41:45.987380+08:00", "kind": "homepage", "sha256": "92fcdfb07f207edd72a73ff5a49207f3fc24cef08504c81189a30cdd32b60d82", "snapshot_path": "sources/92fcdfb07f207edd72a73ff5a49207f3fc24cef08504c81189a30cdd32b60d82.txt", "url": "https://zylo.com/"}, {"fetched_at": "2026-10-26T18:49:29.407016+08:00", "kind": "documentation", "sha256": "956c98664a53e7362fa00eedb60c58955e944bccec0570bd4e2cf59d3ce7695d", "snapshot_path": "sources/956c98664a53e7362fa00eedb60c58955e944bccec0570bd4e2cf59d3ce7695d.txt", "url": "https://zylo.com/product"}], "summary": "Zylo 是面向企业 IT、采购与 FinOps 的 SaaS 与 AI 支出管理平台，以持续更新的软件资产记录汇总订阅支出、使用、合同与续订信息，连接已购许可证与实际使用以回收闲置席位，按节省潜力排序续订，识别重复应用，并以可辩护的系统记录支持策略执行与审计准备。按 SaaS 资产记录、许可证使用与续订优化闭环匹配 SaaS 管理叶。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:378310716','Logto','{"deployment": ["Docker Compose 自托管 OSS 部署", "官方托管 Logto Cloud"], "features": ["面向终端用户的多租户身份基础设施（Console 多租户属 Cloud/付费能力）", "预置注册与注册确认、登录、密码找回终端用户流程", "账户设置：资料、邮箱/电话/用户名、密码、MFA、社交账号与会话管理", "OIDC、OAuth 2.1 与 SAML（OSS 最多 3 个 SAML 应用）", "Web 管理 Console 配置登录体验、用户与组织", "RBAC、组织与企业 SSO（IdP 发起 SSO 属 Cloud）", "外部 IdP 连接器与 30+ 框架 SDK"], "github_repository_id": 378310716, "homepage": "https://logto.io/", "id": "github:378310716", "leaf_matches": [{"reason": "官方注册页证明自助注册与注册时的邮箱/手机验证码确认；重置密码页证明通过已验证渠道的忘记密码与改密流程；账户设置页证明终端用户可管理资料、标识符、密码、MFA 与会话；Management API 提供删除/停用/恢复账户能力。README 与 sign-up-and-sign-in 文档证明应用以 OIDC 委托登录，logto-oss 文档给出 OSS 能力边界（SAML 应用上限 3，Console 多租户/协作者邀请/IdP 发起 SSO 等属 Cloud 或付费许可）。", "slug": "customer-identity-ciam", "source_urls": ["https://docs.logto.io/end-user-flows/sign-up-and-sign-in/sign-up", "https://docs.logto.io/end-user-flows/sign-up-and-sign-in/reset-password", "https://docs.logto.io/end-user-flows/account-settings", "https://docs.logto.io/logto-oss", "https://raw.githubusercontent.com/logto-io/logto/master/README.md"]}], "license": "MPL-2.0", "license_evidence_url": "https://raw.githubusercontent.com/logto-io/logto/master/LICENSE", "license_review": {"rationale": "完整读取仓库根目录 LICENSE，正文为 Mozilla Public License Version 2.0 全文，包含 Definitions、Covered Software 与 Source Code Form 条款，按仓库整体适用 MPL-2.0。LICENSE 末尾 Exhibit B 声明 “Incompatible With Secondary Licenses”；license 仍可标 MPL-2.0，更严谨的 SPDX 标识为 MPL-2.0-no-copyleft-exception。", "reviewer": "collection-editor", "scope": "repository", "source_url": "https://raw.githubusercontent.com/logto-io/logto/master/LICENSE", "spdx_id": "MPL-2.0"}, "name": "Logto", "repository_url": "https://github.com/logto-io/logto", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:38:48.626067+08:00", "kind": "repository_metadata", "sha256": "4c0bb642010bd5f742b92d0182eb61bb323ebbfc9f9272f7590c0af9b5454b82", "snapshot_path": "sources/4c0bb642010bd5f742b92d0182eb61bb323ebbfc9f9272f7590c0af9b5454b82.txt", "url": "https://github.com/logto-io/logto"}, {"fetched_at": "2026-10-26T18:38:24.890319+08:00", "kind": "readme", "sha256": "6386fb6b534aee11852488647cf0ae27984b1ce53daa4c1f096aad9c18725d04", "snapshot_path": "sources/6386fb6b534aee11852488647cf0ae27984b1ce53daa4c1f096aad9c18725d04.txt", "url": "https://raw.githubusercontent.com/logto-io/logto/master/README.md"}, {"fetched_at": "2026-10-26T18:39:47.687088+08:00", "kind": "license", "sha256": "1f256ecad192880510e84ad60474eab7589218784b9a50bc7ceee34c2b91f1d5", "snapshot_path": "sources/1f256ecad192880510e84ad60474eab7589218784b9a50bc7ceee34c2b91f1d5.txt", "url": "https://raw.githubusercontent.com/logto-io/logto/master/LICENSE"}, {"fetched_at": "2026-10-26T18:42:17.708880+08:00", "kind": "documentation", "sha256": "f961d02e6c91f05342047a9cb8c82dc121e9a7d0166a5d4792cca0a9bb444f9b", "snapshot_path": "sources/f961d02e6c91f05342047a9cb8c82dc121e9a7d0166a5d4792cca0a9bb444f9b.txt", "url": "https://docs.logto.io/introduction"}, {"fetched_at": "2026-10-26T18:49:29.089009+08:00", "kind": "documentation", "sha256": "33c63b011d8e82bdfca57ad0aae90138f68836f633a463f2fb8ae6410071eabf", "snapshot_path": "sources/33c63b011d8e82bdfca57ad0aae90138f68836f633a463f2fb8ae6410071eabf.txt", "url": "https://docs.logto.io/end-user-flows/account-settings"}, {"fetched_at": "2026-10-26T18:50:11.886925+08:00", "kind": "documentation", "sha256": "8361084d8d675f3f3c2021a324a6c43c6fb03a6f40aabc6a56c635f9c23645c0", "snapshot_path": "sources/8361084d8d675f3f3c2021a324a6c43c6fb03a6f40aabc6a56c635f9c23645c0.txt", "url": "https://docs.logto.io/end-user-flows/sign-up-and-sign-in/sign-up"}, {"fetched_at": "2026-10-26T18:50:11.692928+08:00", "kind": "documentation", "sha256": "f6542583c043b1393171626f8d5c4d55fea0a5f3eee03a6de0dd471c1e0344c9", "snapshot_path": "sources/f6542583c043b1393171626f8d5c4d55fea0a5f3eee03a6de0dd471c1e0344c9.txt", "url": "https://docs.logto.io/end-user-flows/sign-up-and-sign-in/reset-password"}, {"fetched_at": "2026-10-26T18:49:46.812458+08:00", "kind": "documentation", "sha256": "3c041b6df8758e328a46802a1bf0973d6790db89b0036b3de56d3b235fbd4887", "snapshot_path": "sources/3c041b6df8758e328a46802a1bf0973d6790db89b0036b3de56d3b235fbd4887.txt", "url": "https://docs.logto.io/logto-oss"}, {"fetched_at": "2026-10-26T18:49:46.667740+08:00", "kind": "documentation", "sha256": "09caf3ae0630660cf2362e5a9c7da7bc96089f0d4f95e9eca5543cff4c460e39", "snapshot_path": "sources/09caf3ae0630660cf2362e5a9c7da7bc96089f0d4f95e9eca5543cff4c460e39.txt", "url": "https://docs.logto.io/end-user-flows/sign-up-and-sign-in"}], "summary": "Logto 是 MPL-2.0 开源的客户身份与访问管理平台，面向 SaaS 与 AI 应用提供终端用户注册与注册确认、登录、密码找回、账户设置、OIDC/OAuth 2.1、面向终端用户的多租户、RBAC、管理 Console、外部 IdP 连接器与 30+ SDK。账户删除可由 Management API 管理端执行，或由开发者在自有自助端点中封装。OSS 覆盖多数核心能力；Console 多租户、Console 协作者邀请、Console MFA、IdP 发起 SSO、内置邮件服务、Protected App、隐藏 Logto 品牌与无限 SAML 应用属 Cloud 或需自托管许可，OSS 的 SAML 应用上限为 3。", "technology_stack": ["Node.js", "PostgreSQL", "OIDC", "OAuth 2.1", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:varonis-data-access-governance','Varonis Data Access Governance','{"homepage": "https://www.varonis.com/", "id": "commercial:varonis-data-access-governance", "leaf_matches": [{"reason": "官方产品页说明其可视化敏感数据访问、提供双向访问视图、解析嵌套权限、持续监控权限、支持权限复核/请求并清理不需要的访问、向最小权限收窄，覆盖有效访问映射与治理闭环。", "slug": "data-access-governance", "source_urls": ["https://www.varonis.com/platform/data-access-governance"]}], "name": "Varonis Data Access Governance", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:41:25.758953+08:00", "kind": "documentation", "sha256": "45adbf020e132d66b79de23c07c3f4adc3ea5a561057f750f1e9a0cbf814d8b1", "snapshot_path": "sources/45adbf020e132d66b79de23c07c3f4adc3ea5a561057f750f1e9a0cbf814d8b1.txt", "url": "https://www.varonis.com/platform/data-access-governance"}], "summary": "Varonis Data Access Governance 是其数据安全平台中的访问治理模块，用于跨环境可视化敏感数据的访问关系、解析嵌套权限并持续监控权限，支持权限复核与访问请求，并支持清理不需要的访问、向最小权限收窄。按有效访问映射与治理决策闭环匹配数据访问治理叶。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:11125589','Keycloak','{"deployment": ["发行包解压后运行 bin/kc.sh start-dev", "Docker 镜像 quay.io/keycloak/keycloak"], "features": ["用户联合", "强认证", "用户管理", "细粒度授权"], "github_repository_id": 11125589, "homepage": "https://www.keycloak.org", "id": "github:11125589", "leaf_matches": [{"reason": "README 标题为 Open Source Identity and Access Management，并明确提供 user federation、strong authentication、user management 与 fine-grained authorization；仓库与 Apache-2.0 许可证身份已核对。", "slug": "identity-access-management-iam", "source_urls": ["https://github.com/keycloak/keycloak", "https://raw.githubusercontent.com/keycloak/keycloak/main/README.md", "https://api.github.com/repos/keycloak/keycloak/license"]}, {"reason": "官方 securing-apps 文档把客户端描述为与 Keycloak 交互认证并取得令牌、为多个应用提供 single sign-on 体验；README 说明应用无需自行保存用户或认证用户。符合 SSO 的中央认证代理、应用委托连接与中介会话核心。", "slug": "single-sign-on-sso", "source_urls": ["https://www.keycloak.org/securing-apps/overview", "https://raw.githubusercontent.com/keycloak/keycloak/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/keycloak/keycloak/license", "name": "Keycloak", "repository_url": "https://github.com/keycloak/keycloak", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:50:51+08:00", "kind": "repository_metadata", "sha256": "9617a9682e86c86868670e4c29671e095a5465aa6792bc8375ce1dbd9fa12b2e", "snapshot_path": "sources/9617a9682e86c86868670e4c29671e095a5465aa6792bc8375ce1dbd9fa12b2e.txt", "url": "https://github.com/keycloak/keycloak"}, {"fetched_at": "2026-10-26T18:50:50+08:00", "kind": "readme", "sha256": "5a5b61cb4caa1e113cc53fd07794fc8b78cafce254761ab6c690dcfb7355879c", "snapshot_path": "sources/5a5b61cb4caa1e113cc53fd07794fc8b78cafce254761ab6c690dcfb7355879c.txt", "url": "https://raw.githubusercontent.com/keycloak/keycloak/main/README.md"}, {"fetched_at": "2026-10-26T18:50:50+08:00", "kind": "license", "sha256": "c283c1df11549ce41a05d8b790131d3895f5b2877633025f626d14a729703b03", "snapshot_path": "sources/c283c1df11549ce41a05d8b790131d3895f5b2877633025f626d14a729703b03.txt", "url": "https://api.github.com/repos/keycloak/keycloak/license"}, {"fetched_at": "2026-10-26T18:54:03.458019+08:00", "kind": "documentation", "sha256": "0966bcd7afefffb2c4eae6ff3f5eb37748031eaa9b83451916f6d69585f28c60", "snapshot_path": "sources/0966bcd7afefffb2c4eae6ff3f5eb37748031eaa9b83451916f6d69585f28c60.txt", "url": "https://raw.githubusercontent.com/keycloak/keycloak/main/docs/building.md"}, {"fetched_at": "2026-10-26T18:47:38.672499+08:00", "kind": "repository_metadata", "sha256": "f18a74361b52c63c1df84094cbd8401f7dd077320bcda7164491bca6dd0af45b", "snapshot_path": "sources/f18a74361b52c63c1df84094cbd8401f7dd077320bcda7164491bca6dd0af45b.txt", "url": "https://api.github.com/repos/keycloak/keycloak"}, {"fetched_at": "2026-10-26T18:47:54.936234+08:00", "kind": "license", "sha256": "cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30", "snapshot_path": "sources/cfc7749b96f63bd31c3c42b5c471bf756814053e847c10f3eb003417bc523d30.txt", "url": "https://raw.githubusercontent.com/keycloak/keycloak/main/LICENSE.txt"}, {"fetched_at": "2026-10-26T18:48:44.887133+08:00", "kind": "documentation", "sha256": "ea8d0498447966b65c58a61b18ce49c5217d1d96b4e5b4fd51ee267adba0307b", "snapshot_path": "sources/ea8d0498447966b65c58a61b18ce49c5217d1d96b4e5b4fd51ee267adba0307b.txt", "url": "https://www.keycloak.org/securing-apps/overview"}], "summary": "开源身份与访问管理系统，提供用户联合、强认证、用户管理与细粒度授权，可作为组织统一登录与访问控制中心。", "technology_stack": ["Java", "Maven", "Quarkus"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:veriff','Veriff','{"homepage": "https://www.veriff.com", "id": "commercial:veriff", "leaf_matches": [{"reason": "官方产品正文描述用户采集政府签发证件与自拍、系统执行文件与活体检查并返回决定，支持人工审核；符合身份证据采集、评估与记录结果的核心。", "slug": "identity-verification", "source_urls": ["https://www.veriff.com/product/identity-verification"]}], "name": "Veriff", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:53:02.660537+08:00", "kind": "documentation", "sha256": "5400cbed039b7476b8fa112bbbb52e59b9ae1da1c99e04f5e46aeae989d25e88", "snapshot_path": "sources/5400cbed039b7476b8fa112bbbb52e59b9ae1da1c99e04f5e46aeae989d25e88.txt", "url": "https://www.veriff.com/product/identity-verification"}], "summary": "商业身份验证平台，通过证件照片、自拍与活体检查评估身份证据并返回验证决定，支持人工复核与定制检查流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:20446681','privacyIDEA','{"deployment": ["自托管 Linux 服务器", "REST API 集成到现有应用"], "features": ["通用第二因素认证", "FIDO2/WebAuthn 与 Passkey", "TOTP/HOTP 与推送认证", "短信/邮件/SSH 密钥等令牌", "对接 AD/LDAP/SQL/EntraID"], "github_repository_id": 20446681, "homepage": "https://www.privacyidea.org", "id": "github:20446681", "leaf_matches": [{"reason": "README 标题即 Open-Source Multi-Factor Authentication，正文说明其自托管 MFA 平台、第二因素类型、身份源连接和 REST API 集成；官网确认其为令牌/OTP 认证服务器。", "slug": "multi-factor-authentication-mfa", "source_urls": ["https://github.com/privacyidea/privacyidea", "https://raw.githubusercontent.com/privacyidea/privacyidea/master/README.rst", "https://api.github.com/repos/privacyidea/privacyidea/license", "https://www.privacyidea.org/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/privacyidea/privacyidea/license", "name": "privacyIDEA", "repository_url": "https://github.com/privacyidea/privacyidea", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:52:26.884249+08:00", "kind": "repository_metadata", "sha256": "679d6cfe1cc83e2d8444e2cde890a38b239d15561369837aa61378c899be3013", "snapshot_path": "sources/679d6cfe1cc83e2d8444e2cde890a38b239d15561369837aa61378c899be3013.txt", "url": "https://github.com/privacyidea/privacyidea"}, {"fetched_at": "2026-10-26T18:53:02.070871+08:00", "kind": "readme", "sha256": "77a5621ee9b067a23cb7c7a9a114546e28595eaadd35da1049b6066616570418", "snapshot_path": "sources/77a5621ee9b067a23cb7c7a9a114546e28595eaadd35da1049b6066616570418.txt", "url": "https://raw.githubusercontent.com/privacyidea/privacyidea/master/README.rst"}, {"fetched_at": "2026-10-26T18:52:34.971986+08:00", "kind": "license", "sha256": "bd5fd8c06a2a561fb5f96ddb525a86e43fc5335d46eeac901e5bf9dad22770d1", "snapshot_path": "sources/bd5fd8c06a2a561fb5f96ddb525a86e43fc5335d46eeac901e5bf9dad22770d1.txt", "url": "https://api.github.com/repos/privacyidea/privacyidea/license"}, {"fetched_at": "2026-10-26T18:53:27.428385+08:00", "kind": "homepage", "sha256": "e75fad3043f53500d2b957b4c98943862550b57f43143850d03b8aaa2abfde49", "snapshot_path": "sources/e75fad3043f53500d2b957b4c98943862550b57f43143850d03b8aaa2abfde49.txt", "url": "https://www.privacyidea.org/"}, {"fetched_at": "2026-10-26T18:54:09.717337+08:00", "kind": "repository_metadata", "sha256": "ae3f43c18b97c32d3cd1e0981ae232958cfee94447032089b5dde114f0c9805f", "snapshot_path": "sources/ae3f43c18b97c32d3cd1e0981ae232958cfee94447032089b5dde114f0c9805f.txt", "url": "https://api.github.com/repos/privacyidea/privacyidea/languages"}], "summary": "自托管开源多因素认证平台，管理令牌与 OTP 等第二因素，并为现有应用和身份源提供统一的认证接口。", "technology_stack": ["Python", "TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:21484781','JumpServer','{"deployment": ["官方 quick_start.sh 在 64 位 Linux 服务器上一键安装", "提供 Docker 镜像作为自托管部署路径", "本记录未实际部署运行"], "features": ["统一管理 SSH、RDP、Kubernetes、数据库、Web 等资产的特权访问", "发现特权账户、定期轮换密码并加密备份凭据", "基于 RBAC 与 JIT 的细粒度授权和访问审批", "会话视频录制、命令审计、实时监控与 SIEM 转发"], "github_repository_id": 21484781, "homepage": "https://www.jumpserver.com", "id": "github:21484781", "leaf_matches": [{"reason": "README 自述为开源 PAM/堡垒机并覆盖资产访问；官方 features 页进一步给出特权账户发现与改密、加密凭据备份、RBAC/JIT 授权、会话录制与审计，符合 PAM 对特权账户的保管、策略门控使用和可追溯记录核心。仅社区版能力计入。", "slug": "privileged-access-management-pam", "source_urls": ["https://raw.githubusercontent.com/jumpserver/jumpserver/dev/README.md", "https://www.jumpserver.com/features"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/jumpserver/jumpserver/license", "name": "JumpServer", "repository_url": "https://github.com/jumpserver/jumpserver", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:47:32.182026+08:00", "kind": "repository_metadata", "sha256": "53725a161c26c6aadc3d34936fe9cec4cad103c1b77403bfe2d945de8a12b463", "snapshot_path": "sources/53725a161c26c6aadc3d34936fe9cec4cad103c1b77403bfe2d945de8a12b463.txt", "url": "https://api.github.com/repos/jumpserver/jumpserver"}, {"fetched_at": "2026-10-26T18:47:49.304360+08:00", "kind": "readme", "sha256": "245abbb3ad7a1196d63a5d5713f846b2b91180f4146ac0166ff24959e906cd71", "snapshot_path": "sources/245abbb3ad7a1196d63a5d5713f846b2b91180f4146ac0166ff24959e906cd71.txt", "url": "https://raw.githubusercontent.com/jumpserver/jumpserver/dev/README.md"}, {"fetched_at": "2026-10-26T18:47:49.661699+08:00", "kind": "license", "sha256": "dd2303b898fd8d08eca2a79bee20d3f7766220c53bc8e9759a07fc624082ea3e", "snapshot_path": "sources/dd2303b898fd8d08eca2a79bee20d3f7766220c53bc8e9759a07fc624082ea3e.txt", "url": "https://api.github.com/repos/jumpserver/jumpserver/license"}, {"fetched_at": "2026-10-26T18:48:57.461579+08:00", "kind": "documentation", "sha256": "203727dd9d5ff03f951bca44144b756297bef5778434362dc04f4e1596ad637d", "snapshot_path": "sources/203727dd9d5ff03f951bca44144b756297bef5778434362dc04f4e1596ad637d.txt", "url": "https://www.jumpserver.com/features"}], "summary": "开源特权访问管理（PAM）平台（堡垒机），围绕资产与特权账户提供凭证发现/轮换与加密备份、RBAC/JIT 授权、多协议代理接入和会话录制审计。本条只计入社区版核心能力；README 列为私有或企业版的组件与工单审批、多云同步不纳入。", "technology_stack": ["Web 管理控制台与多协议连接/代理组件（KoKo、Chen 等）", "面向服务器、数据库与网络设备的自托管堡垒机架构"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:microsoft-purview-dlp','Microsoft Purview Data Loss Prevention','{"homepage": "https://learn.microsoft.com/en-us/purview/", "id": "commercial:microsoft-purview-dlp", "leaf_matches": [{"reason": "官方文档说明 DLP 策略识别、监控并自动保护企业应用、设备与内联 Web 流量中的敏感数据，涵盖内容分析、策略提示、阻止/覆盖理由与隔离响应，符合 DLP 在数据流动节点检查内容并执行策略响应的核心。", "slug": "data-loss-prevention-dlp", "source_urls": ["https://learn.microsoft.com/en-us/purview/dlp-learn-about-dlp"]}], "name": "Microsoft Purview Data Loss Prevention", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:49:20.561487+08:00", "kind": "documentation", "sha256": "e70ecaedc0e7dd39a0776e435767590038de87bbfcaeeb926e7870235d6acf06", "snapshot_path": "sources/e70ecaedc0e7dd39a0776e435767590038de87bbfcaeeb926e7870235d6acf06.txt", "url": "https://learn.microsoft.com/en-us/purview/dlp-learn-about-dlp"}], "summary": "Microsoft Purview 中的 DLP 策略，对 Microsoft 365、终端、本地文件共享和内联 Web 流量中的敏感内容做内容分析，并按策略告警、阻止、要求用户理由或隔离数据。本条只记录官方文档所述的基本商业能力。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cyera-dspm','Cyera DSPM','{"homepage": "https://www.cyera.com/", "id": "commercial:cyera-dspm", "leaf_matches": [{"reason": "官方产品页描述持续扫描数百 PB 的云/SaaS/DBaaS/本地存储、AI 分类敏感数据，并将数据敏感度与业务用途、身份、访问活动和暴露关联为风险评分及修复动作，符合 DSPM 的连接数据资产→敏感清单→发现循环核心。", "slug": "data-security-posture-management-dspm", "source_urls": ["https://www.cyera.com/platform/dspm"]}], "name": "Cyera DSPM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:50:38.583478+08:00", "kind": "homepage", "sha256": "701d22f4cb39590ca7cb4eb8ccf19f741a0b3265fb7b8dcce58cc4e96c058b00", "snapshot_path": "sources/701d22f4cb39590ca7cb4eb8ccf19f741a0b3265fb7b8dcce58cc4e96c058b00.txt", "url": "https://www.cyera.com/platform/dspm"}], "summary": "商业 DSPM 平台，持续扫描云、SaaS、DBaaS 与本地数据存储，分类敏感数据，并结合身份、访问活动与暴露上下文排序风险、支持修复。本条只记录官方产品页所述的基本商业能力。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:121898717','Vaultwarden','{"deployment": ["Docker/Podman 容器并挂载持久化数据卷", "Docker Compose", "从源码构建二进制", "第三方社区软件包"], "features": ["个人保险库", "组织、集合与密码共享", "附件与 Send", "多因素认证与紧急访问", "Bitwarden 客户端兼容 API 与内置 Web Vault"], "github_repository_id": 121898717, "homepage": "https://github.com/dani-garcia/vaultwarden", "id": "github:121898717", "leaf_matches": [{"reason": "自托管 Bitwarden 兼容密码保险库服务，提供个人保险库、组织/集合共享和官方客户端接入，符合密码管理器的记录存储与使用点检索结构。", "slug": "password-manager", "source_urls": ["https://raw.githubusercontent.com/dani-garcia/vaultwarden/main/README.md", "https://api.github.com/repos/dani-garcia/vaultwarden"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/dani-garcia/vaultwarden/license", "name": "Vaultwarden", "repository_url": "https://github.com/dani-garcia/vaultwarden", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:39.587845+08:00", "kind": "repository_metadata", "sha256": "d8fefe1e3b0a5b9018e52775e36b7b701c1d7bb252caa2e5961746308b8faf55", "snapshot_path": "sources/d8fefe1e3b0a5b9018e52775e36b7b701c1d7bb252caa2e5961746308b8faf55.txt", "url": "https://api.github.com/repos/dani-garcia/vaultwarden"}, {"fetched_at": "2026-10-26T18:57:41.390437+08:00", "kind": "license", "sha256": "b86025fabb12c73661640fc1c407f2b57e87c52a7086d1de5bb20f20c401c054", "snapshot_path": "sources/b86025fabb12c73661640fc1c407f2b57e87c52a7086d1de5bb20f20c401c054.txt", "url": "https://api.github.com/repos/dani-garcia/vaultwarden/license"}, {"fetched_at": "2026-10-26T18:57:42.518169+08:00", "kind": "readme", "sha256": "5c7e29e287f600fe1979d196d53f94cd8f87f9c0de1acf6481fde510fbfdd4fc", "snapshot_path": "sources/5c7e29e287f600fe1979d196d53f94cd8f87f9c0de1acf6481fde510fbfdd4fc.txt", "url": "https://raw.githubusercontent.com/dani-garcia/vaultwarden/main/README.md"}], "summary": "用 Rust 编写的 Bitwarden 兼容自托管密码保险库服务端，提供个人保险库、组织与集合共享、附件、多因素认证和紧急访问，并配套内置 Web Vault 与官方客户端 API。", "technology_stack": ["Rust", "Rocket Web 框架", "Docker/Podman"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gitguardian','GitGuardian','{"homepage": "https://gitguardian.com/", "id": "commercial:gitguardian", "leaf_matches": [{"reason": "官方文档展示从秘密检测引擎到事件记录、影响评估、吊销/轮换和回归告警的完整生命周期，匹配机密暴露检测与凭证中心修复。", "slug": "secrets-security", "source_urls": ["https://docs.gitguardian.com/platform/getting-started/first-incident", "https://docs.gitguardian.com/public-monitoring/detect-public-secret-incidents/overview"]}], "name": "GitGuardian", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:58:07.685783+08:00", "kind": "homepage", "sha256": "513f2f09e2e657963fe0f5203ff24660933be7dfe07235a288081d3d9c29272b", "snapshot_path": "sources/513f2f09e2e657963fe0f5203ff24660933be7dfe07235a288081d3d9c29272b.txt", "url": "https://www.gitguardian.com/"}, {"fetched_at": "2026-10-26T18:58:09.357597+08:00", "kind": "documentation", "sha256": "de106b07b4bd592aa9f0fa96d1d440dee9be9e75cd2e77100bc89deeb5a8f244", "snapshot_path": "sources/de106b07b4bd592aa9f0fa96d1d440dee9be9e75cd2e77100bc89deeb5a8f244.txt", "url": "https://docs.gitguardian.com/platform/getting-started/first-incident"}, {"fetched_at": "2026-10-26T18:58:11.054196+08:00", "kind": "documentation", "sha256": "501bacfde126c08180efa9b370e744eb2f47209775288c1b1364997f5915578f", "snapshot_path": "sources/501bacfde126c08180efa9b370e744eb2f47209775288c1b1364997f5915578f.txt", "url": "https://docs.gitguardian.com/public-monitoring/detect-public-secret-incidents/overview"}], "summary": "商业机密检测平台，持续扫描代码仓库与公开来源，生成可跟踪的秘密事件，并提供影响评估、吊销/轮换与修复指引。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1317133034','dmarc-service','{"deployment": ["单机 Docker Compose 部署", "Kubernetes Helm chart 部署", "直接接收 25 端口报告或通过 IMAP 轮询邮箱"], "features": ["SMTP、HTTPS 与 IMAP 报告接收", "DMARC 聚合报告和 TLS-RPT 解析、去重与隔离", "按域名与发送源展示 SPF 授权、DMARC 判定和认证域", "生成并实时校验 DMARC/TLS-RPT 报告相关 DNS 记录（含外部目的地验证记录）", "多租户、SSO/API token 与 Prometheus 指标"], "github_repository_id": 1317133034, "homepage": "https://github.com/pescheckit/dmarc-service", "id": "github:1317133034", "leaf_matches": [{"reason": "以受保护域名为单位生成并校验 DMARC/TLS-RPT 报告相关 DNS 记录，同时运营接收方聚合报告循环，把报告整理为按发送源的 SPF/DKIM 结果与对齐证据，符合 DMARC 管理核心。", "slug": "email-authentication-dmarc-management", "source_urls": ["https://raw.githubusercontent.com/pescheckit/dmarc-service/main/README.md", "https://raw.githubusercontent.com/pescheckit/dmarc-service/main/docs/FEATURES.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/pescheckit/dmarc-service/license", "name": "dmarc-service", "repository_url": "https://github.com/pescheckit/dmarc-service", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:51.927017+08:00", "kind": "repository_metadata", "sha256": "53476617cef79d6fcb4b9e47d8b86e338a8eebcab42fdd14c58fecf78043a70f", "snapshot_path": "sources/53476617cef79d6fcb4b9e47d8b86e338a8eebcab42fdd14c58fecf78043a70f.txt", "url": "https://api.github.com/repos/pescheckit/dmarc-service"}, {"fetched_at": "2026-10-26T18:57:53.569717+08:00", "kind": "license", "sha256": "3846ab3ee25a32304217b127b20b38b676263db6a6911107c4b23246c6903a51", "snapshot_path": "sources/3846ab3ee25a32304217b127b20b38b676263db6a6911107c4b23246c6903a51.txt", "url": "https://api.github.com/repos/pescheckit/dmarc-service/license"}, {"fetched_at": "2026-10-26T18:57:54.872047+08:00", "kind": "readme", "sha256": "0a6d618afbb6281626d7555e422a65fc1ff9b91fa59a3ac1f9b4a9f5b04ced72", "snapshot_path": "sources/0a6d618afbb6281626d7555e422a65fc1ff9b91fa59a3ac1f9b4a9f5b04ced72.txt", "url": "https://raw.githubusercontent.com/pescheckit/dmarc-service/main/README.md"}, {"fetched_at": "2026-10-26T18:57:56.138984+08:00", "kind": "documentation", "sha256": "ffa6c0d5ed2ccd0d79ed7cc88c71f58d11543f5fa5529bae4340c14c90d15719", "snapshot_path": "sources/ffa6c0d5ed2ccd0d79ed7cc88c71f58d11543f5fa5529bae4340c14c90d15719.txt", "url": "https://raw.githubusercontent.com/pescheckit/dmarc-service/main/docs/FEATURES.md"}], "summary": "自托管多租户 DMARC/TLS-RPT 报告收集与查看服务，接收并解析聚合报告，按域名和发送源展示 SPF 授权与 DMARC 对齐结果，并生成、校验 DMARC/TLS-RPT 报告相关 DNS 记录。", "technology_stack": ["Python", "Docker Compose", "Kubernetes/Helm", "SMTP/IMAP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:821147194','RITA','{"deployment": ["Docker Engine 与 Compose 插件运行安装器", "依赖 Zeek 生成网络流量日志", "支持滚动导入以持续累积数据集"], "features": ["信标行为检测", "长连接检测", "DNS 隧道检测", "威胁情报源比对", "Zeek TSV/JSON 日志导入与调查视图"], "github_repository_id": 821147194, "homepage": "https://www.activecountermeasures.com/free-tools/rita/", "id": "github:821147194", "leaf_matches": [{"reason": "从网络观测日志构建数据集，执行信标、DNS 隧道与威胁情报等威胁检测并提供调查视图，响应通过外部执行点完成，符合 NDR 的检测与调查核心。", "slug": "network-detection-response-ndr", "source_urls": ["https://raw.githubusercontent.com/activecm/rita/main/README.md", "https://api.github.com/repos/activecm/rita"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/activecm/rita/license", "name": "RITA", "repository_url": "https://github.com/activecm/rita", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:43.868181+08:00", "kind": "repository_metadata", "sha256": "7e1add8a418e6100e73b9889b7745cea84c04a68e5475ebacb2d1f64f832dc0b", "snapshot_path": "sources/7e1add8a418e6100e73b9889b7745cea84c04a68e5475ebacb2d1f64f832dc0b.txt", "url": "https://api.github.com/repos/activecm/rita"}, {"fetched_at": "2026-10-26T18:57:45.531295+08:00", "kind": "license", "sha256": "ae35fd6abbc60a525005efe07d30b331bf8fe80059206c314acd43d04a499ac8", "snapshot_path": "sources/ae35fd6abbc60a525005efe07d30b331bf8fe80059206c314acd43d04a499ac8.txt", "url": "https://api.github.com/repos/activecm/rita/license"}, {"fetched_at": "2026-10-26T18:57:46.906971+08:00", "kind": "readme", "sha256": "9db58a2934da41b386b196ea93780c99adcd0507dd6ebb22b80a6a5b5d9b6649", "snapshot_path": "sources/9db58a2934da41b386b196ea93780c99adcd0507dd6ebb22b80a6a5b5d9b6649.txt", "url": "https://raw.githubusercontent.com/activecm/rita/main/README.md"}], "summary": "RITA 是开源网络流量分析应用，导入 Zeek 日志并检测信标、长连接、DNS 隧道和威胁情报命中，通过调查视图支持安全分析。", "technology_stack": ["Go", "Docker Compose", "Zeek"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cloudflare-one','Cloudflare One','{"homepage": "https://www.cloudflare.com/sase/", "id": "commercial:cloudflare-one", "leaf_matches": [{"reason": "官方页面明确 Cloudflare One 为统一 SASE 平台，FAQ 列出 ZTNA、SWG、CASB、NaaS、FWaaS、RBI、DLP、邮件安全与 DEM，并说明单一控制平面、数据平面和全球边缘承载；同时描述按身份提供零信任访问和统一策略，可核对云边缘调解、融合服务与身份策略三项核心。", "slug": "sase-sse-platform", "source_urls": ["https://www.cloudflare.com/sase/"]}], "name": "Cloudflare One", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:49.075508+08:00", "kind": "homepage", "sha256": "3a26743281115288a1a7047fffefe9d6d6d775bf1468fb33b434b5b215de930d", "snapshot_path": "sources/3a26743281115288a1a7047fffefe9d6d6d775bf1468fb33b434b5b215de930d.txt", "url": "https://www.cloudflare.com/sase/"}], "summary": "Cloudflare 的云交付 SASE 平台，将 ZTNA、SWG、CASB、NaaS、FWaaS、RBI、DLP、邮件安全与 DEM 收敛到单一控制平面和全球边缘网络，按身份与目标执行访问和安全策略。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zscaler-zero-trust-exchange','Zscaler Zero Trust Exchange','{"homepage": "https://www.zscaler.com/products/zscaler-zero-trust-exchange", "id": "commercial:zscaler-zero-trust-exchange", "leaf_matches": [{"reason": "官方页面将 Zero Trust Exchange 描述为统一 SASE 平台，列出 ZIA、ZPA、零信任分支、零信任防火墙、云沙箱与 ZDX，并说明代理架构按身份、上下文和业务策略在用户与应用间建立一对一连接；覆盖云边缘调解、融合安全服务和身份上下文策略。", "slug": "sase-sse-platform", "source_urls": ["https://www.zscaler.com/products/zscaler-zero-trust-exchange"]}], "name": "Zscaler Zero Trust Exchange", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:50.191184+08:00", "kind": "homepage", "sha256": "1f307f18b5ecfa5767d4aa712ce9ad005ae5ab7a8d0396835b4510cded8fd8f8", "snapshot_path": "sources/1f307f18b5ecfa5767d4aa712ce9ad005ae5ab7a8d0396835b4510cded8fd8f8.txt", "url": "https://www.zscaler.com/products/zscaler-zero-trust-exchange"}], "summary": "Zscaler 的零信任 SASE 平台，通过 Zero Trust Exchange 提供 ZIA 互联网/SaaS 安全、ZPA 私有应用访问、零信任分支/防火墙、云沙箱与数字体验监控，并按身份、上下文和业务策略代理连接。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:40556106','Wazuh','{"deployment": ["自建 Wazuh manager、indexer 与 dashboard", "在受管终端安装 Wazuh agent", "支持 Docker、Kubernetes、Ansible 等编排"], "features": ["终端代理采集日志、文件完整性、漏洞与恶意/rootkit 迹象", "规则与行为分析在集中管理端生成安全告警", "Wazuh Dashboard 提供安全事件与终端状态调查", "Active response 在终端执行阻断或远程查询", "云工作负载与容器遥测接入"], "github_repository_id": 40556106, "homepage": "https://wazuh.com/", "id": "github:40556106", "leaf_matches": [{"reason": "官方 README 说明终端代理持续采集主机日志、文件完整性、漏洞与恶意/rootkit 迹象，manager 规则分析生成告警，active response 可在终端阻断访问或远程执行查询；官方 XDR 页补充行为分析与自动响应，对应 EDR 的终端遥测、行为检测、调查和终端响应四段核心。", "slug": "endpoint-detection-response-edr", "source_urls": ["https://raw.githubusercontent.com/wazuh/wazuh/main/README.md", "https://wazuh.com/platform/xdr/"]}, {"reason": "README 说明代理采集日志、管理器做基于规则的分析与告警、索引器/仪表盘用于浏览安全告警，覆盖 SIEM 的数据平面、持续检测与分析师调查控制台三层。", "slug": "siem", "source_urls": ["https://raw.githubusercontent.com/wazuh/wazuh/main/README.md"]}], "license": "GPL-2.0-only", "license_evidence_url": "https://api.github.com/repos/wazuh/wazuh/license", "license_review": {"rationale": "Wazuh 仓库为混合许可：src/engine 为 AGPL-3.0-or-later，部分共享库为 GPL-2.0-only OR AGPL-3.0-or-later，其余主体为 GPL-2.0-only；本条按社区核心主体记为 GPL-2.0-only，engine 单独适用 AGPL。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "community_core", "source_url": "https://api.github.com/repos/wazuh/wazuh/license", "spdx_id": "GPL-2.0-only"}, "name": "Wazuh", "repository_url": "https://github.com/wazuh/wazuh", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:57:15.450534+08:00", "kind": "repository_metadata", "sha256": "2833878e74244c75017aa649a02f4a01b67f71130459aa0e5a30d24b8bf94084", "snapshot_path": "sources/2833878e74244c75017aa649a02f4a01b67f71130459aa0e5a30d24b8bf94084.txt", "url": "https://api.github.com/repos/wazuh/wazuh"}, {"fetched_at": "2026-10-26T18:57:24.046609+08:00", "kind": "license", "sha256": "8317677aa79aaf665e614e915e14d7d77d0a2c998e010e4995994a21be97446c", "snapshot_path": "sources/8317677aa79aaf665e614e915e14d7d77d0a2c998e010e4995994a21be97446c.txt", "url": "https://api.github.com/repos/wazuh/wazuh/license"}, {"fetched_at": "2026-10-26T18:57:23.992613+08:00", "kind": "readme", "sha256": "6fce527aeea895a9411497bb18a97a3c25acdefe75fa533299a9e320c5dd2030", "snapshot_path": "sources/6fce527aeea895a9411497bb18a97a3c25acdefe75fa533299a9e320c5dd2030.txt", "url": "https://raw.githubusercontent.com/wazuh/wazuh/main/README.md"}, {"fetched_at": "2026-10-26T18:58:33.345355+08:00", "kind": "homepage", "sha256": "fadcbfd5f309f686a92eb2e1327b6408d0deaa3d8533f1fb345dafcb9072e848", "snapshot_path": "sources/fadcbfd5f309f686a92eb2e1327b6408d0deaa3d8533f1fb345dafcb9072e848.txt", "url": "https://wazuh.com/"}, {"fetched_at": "2026-10-26T18:58:48.081581+08:00", "kind": "homepage", "sha256": "6dd9c3ee0c99eb367dc4a6d81448795ebf13451da7f43de0ae36e622c35bb39b", "snapshot_path": "sources/6dd9c3ee0c99eb367dc4a6d81448795ebf13451da7f43de0ae36e622c35bb39b.txt", "url": "https://wazuh.com/platform/xdr/"}, {"fetched_at": "2026-10-26T19:15:47.327956+08:00", "kind": "repository_metadata", "sha256": "cc4b94b5db1a72ad2dcd667233337e61d288f777f9fef258075cb3bcdf5492e0", "snapshot_path": "sources/cc4b94b5db1a72ad2dcd667233337e61d288f777f9fef258075cb3bcdf5492e0.txt", "url": "https://api.github.com/repos/wazuh/wazuh"}], "summary": "Wazuh 是开源核心的安全平台：终端代理采集主机与云工作负载遥测，集中管理端做规则/行为检测生成告警，并可通过 active response 在终端执行阻断或远程查询。仓库主体为 GPL-2.0-only，src/engine 单独适用 AGPL-3.0-or-later。", "technology_stack": ["C/C++", "Python"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:crowdstrike-falcon-prevent','CrowdStrike Falcon Prevent','{"homepage": "https://www.crowdstrike.com/en-us/products/falcon-prevent/", "id": "commercial:crowdstrike-falcon-prevent", "leaf_matches": [{"reason": "官方产品页说明 Falcon Prevent 以轻量代理覆盖整个终端集群、由云原生架构和统一控制台管理，使用 AI、威胁情报、行为分析、内存扫描与漏洞利用缓解识别并阻止高级威胁，且可离线防护；对应 EPP 的受管终端、威胁评估、预防执行与持续维护保护。", "slug": "endpoint-protection-platform", "source_urls": ["https://www.crowdstrike.com/en-us/products/falcon-prevent/"]}], "name": "CrowdStrike Falcon Prevent", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:59:33.238836+08:00", "kind": "homepage", "sha256": "b54eea3c926babc1f98f83ee90736f3f79cb5ce581e3d64685096d6a8fb56b88", "snapshot_path": "sources/b54eea3c926babc1f98f83ee90736f3f79cb5ce581e3d64685096d6a8fb56b88.txt", "url": "https://www.crowdstrike.com/en-us/products/falcon-prevent/"}], "summary": "CrowdStrike Falcon 的下一代防病毒（EPP）模块，通过轻量终端代理和云原生架构执行 AI/行为分析、内存扫描与漏洞利用缓解，阻止已知和未知恶意软件，并由统一控制台管理终端集群。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:microsoft-defender-xdr','Microsoft Defender XDR','{"homepage": "https://microsoft.com/en-us/security/business/siem-and-xdr/microsoft-defender-xdr", "id": "commercial:microsoft-defender-xdr", "leaf_matches": [{"reason": "Microsoft Learn 官方文档说明 Defender XDR 原生协调终端、身份、邮件和应用域的检测、预防、调查与响应，把跨产品告警、可疑事件和受影响资产关联为事件，在 Defender 门户统一调查，并自动修复邮箱、终端和身份；对应多域信号、统一事件关联、统一调查和跨域响应四段核心。", "slug": "extended-detection-response-xdr", "source_urls": ["https://learn.microsoft.com/en-us/defender-xdr/microsoft-365-defender"]}], "name": "Microsoft Defender XDR", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:59:18.706338+08:00", "kind": "documentation", "sha256": "758073a0e67f72f5547e3d79fd14dc004a2756d6079eb6e1f4f89da5fafc48b4", "snapshot_path": "sources/758073a0e67f72f5547e3d79fd14dc004a2756d6079eb6e1f4f89da5fafc48b4.txt", "url": "https://learn.microsoft.com/en-us/defender-xdr/microsoft-365-defender"}], "summary": "Microsoft 的扩展检测与响应平台，原生协调终端、身份、邮件/协作和云应用信号，在 Defender 门户把跨产品告警与受影响资产关联为事件，支持统一调查、威胁狩猎和跨域自动响应。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zimperium-mobile-threat-defense','Zimperium Mobile Threat Defense','{"homepage": "https://zimperium.com/mobile-threat-defense/", "id": "commercial:zimperium-mobile-threat-defense", "leaf_matches": [{"reason": "官方 MTD 页面说明其对企业与 BYOD 移动设备持续防护，覆盖钓鱼、恶意软件、零日、被 root/越狱等，设备完整性检查在授予企业资源访问前执行，支持应用审查、取证扫描、终端用户告警及 MDM/EMM/UEM/SIEM/SOAR/XDR 集成；对应移动设备持续评估、逐设备风险判断与保护响应。", "slug": "mobile-threat-defense", "source_urls": ["https://zimperium.com/mobile-threat-defense/"]}], "name": "Zimperium Mobile Threat Defense", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:58:59.774801+08:00", "kind": "homepage", "sha256": "a4fb9601409094db1f6d5ce4471ef7231e2cce996116010045403d0d8b78e748", "snapshot_path": "sources/a4fb9601409094db1f6d5ce4471ef7231e2cce996116010045403d0d8b78e748.txt", "url": "https://zimperium.com/mobile-threat-defense/"}], "summary": "Zimperium 的移动威胁防御产品，在 Android、iOS 与 ChromeOS 设备上持续检测恶意应用、钓鱼、网络风险与 root/越狱等设备完整性威胁，向用户告警，并通过 MDM/EMM 集成在授予企业资源访问前执行设备检查。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1222504','SonarQube Community Build','{"deployment": ["SonarQube Community Build 自托管部署", "README 提供构建与本地启动说明"], "features": ["对源代码执行静态分析（符号执行、数据与控制流分析），报告安全漏洞、安全热点、缺陷与可维护性问题", "支持多种编程语言（社区版为平台语言支持的子集），可按质量门禁对新代码判定通过或失败", "以自托管平台形式交付，分析结果可在 CI/IDE 中使用；分支分析与拉取请求装饰为商业版能力"], "github_repository_id": 1222504, "homepage": "https://sonarsource.com", "id": "github:1222504", "leaf_matches": [{"reason": "Community Build 以符号执行、数据/控制流分析检查一手源代码，输出可定位的安全漏洞与安全热点及修复指引；README 明确深度污点分析、SCA 与分支/PR 分析属商业版，本关系仅按社区版能力记录。", "slug": "sast", "source_urls": ["https://raw.githubusercontent.com/SonarSource/sonarqube/master/README.md"]}, {"reason": "README 说明本仓库是 SonarQube Community Build 的源码，即 SonarQube 平台的免费开源版，并以符号执行、数据与控制流分析检查代码、指出缺陷与漏洞及其修复原因；社区版分析文档说明扫描器从文件系统读取源文件、按质量配置中的启用规则分析并把结果送到平台计算，整个过程是自动化静态代码审查而非运行被分析程序；质量配置文档说明规则目录可按语言启用/停用、调整参数、自定义与继承；问题文档说明规则被触发即产生 issue，带主/次定位与执行流路径、严重度、状态生命周期与指派/标记/评论。三项定义核心（不执行代码的静态检查、封装且可配置的规则目录、定位可操作的发现）均有官方正文对应。本条仅记录社区版自托管平台能力，深度污点 SAST、SCA、分支/PR 分析等商业版能力不纳入。", "slug": "static-code-analysis-platform", "source_urls": ["https://raw.githubusercontent.com/SonarSource/sonarqube/master/README.md", "https://docs.sonarsource.com/sonarqube-community-build/analyzing-source-code/analysis-overview.md", "https://docs.sonarsource.com/sonarqube-community-build/quality-standards-administration/managing-quality-profiles/understanding-quality-profiles.md", "https://docs.sonarsource.com/sonarqube-community-build/user-guide/issues/introduction.md"]}], "license": "LGPL-3.0", "license_evidence_url": "https://api.github.com/repos/SonarSource/sonarqube/license", "name": "SonarQube Community Build", "repository_url": "https://github.com/SonarSource/sonarqube", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:56:18.330171+08:00", "kind": "repository_metadata", "sha256": "8e008c1c54f5cf2d0a0ec6647caddff1a2c579f4890198f7c594fecb3dae8bd8", "snapshot_path": "sources/8e008c1c54f5cf2d0a0ec6647caddff1a2c579f4890198f7c594fecb3dae8bd8.txt", "url": "https://api.github.com/repos/SonarSource/sonarqube"}, {"fetched_at": "2026-10-26T19:00:07.436106+08:00", "kind": "repository_metadata", "sha256": "bd08e1338b31b95992fb66fa195466b9bb284c32bc001fd91483345716c5d6b3", "snapshot_path": "sources/bd08e1338b31b95992fb66fa195466b9bb284c32bc001fd91483345716c5d6b3.txt", "url": "https://api.github.com/repos/SonarSource/sonarqube"}, {"fetched_at": "2026-10-26T19:00:18.743359+08:00", "kind": "license", "sha256": "a39e18ddc0394830eb8924ba8ac1b672c295e5681d61de587ba0a3f3735e2533", "snapshot_path": "sources/a39e18ddc0394830eb8924ba8ac1b672c295e5681d61de587ba0a3f3735e2533.txt", "url": "https://api.github.com/repos/SonarSource/sonarqube/license"}, {"fetched_at": "2026-10-28T22:56:26.531683+08:00", "kind": "documentation", "sha256": "d646a4830b11be0f9bd2442926a60f3b45ab1ffd79d5df6e8e717f24ee770817", "snapshot_path": "sources/d646a4830b11be0f9bd2442926a60f3b45ab1ffd79d5df6e8e717f24ee770817.txt", "url": "https://docs.sonarsource.com/sonarqube-community-build/analyzing-source-code/analysis-overview.md"}, {"fetched_at": "2026-10-28T22:56:26.428076+08:00", "kind": "documentation", "sha256": "843396b562104fb94296a1d950c2e72af24458f6fc565d26c2cc98ddaef5d324", "snapshot_path": "sources/843396b562104fb94296a1d950c2e72af24458f6fc565d26c2cc98ddaef5d324.txt", "url": "https://docs.sonarsource.com/sonarqube-community-build/quality-standards-administration/managing-quality-profiles/understanding-quality-profiles.md"}, {"fetched_at": "2026-10-28T22:56:35.410897+08:00", "kind": "documentation", "sha256": "0f02f15ee894c718084a9ad35bdd669126b4141ca1cdcaae41c1772f10ecb639", "snapshot_path": "sources/0f02f15ee894c718084a9ad35bdd669126b4141ca1cdcaae41c1772f10ecb639.txt", "url": "https://docs.sonarsource.com/sonarqube-community-build/user-guide/issues/introduction.md"}, {"fetched_at": "2026-10-26T19:00:27.714016+08:00", "kind": "readme", "sha256": "018a24c87f6694520e4035d346fe0204770c39db305c570da279132ec64d7fb5", "snapshot_path": "sources/018a24c87f6694520e4035d346fe0204770c39db305c570da279132ec64d7fb5.txt", "url": "https://raw.githubusercontent.com/SonarSource/sonarqube/master/README.md"}], "summary": "开源（社区版）自托管代码静态分析平台，对源代码做静态安全与质量分析，报告可定位的安全漏洞、安全热点与代码问题；深度污点分析、SCA 及分支/PR 分析等为商业版能力。", "technology_stack": ["静态分析引擎", "多语言静态分析", "CI/CD 扫描集成"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:11457947','OWASP Dependency-Track','{"deployment": ["README 提供 Docker Compose 本地快速启动", "提供 Helm charts 用于自托管部署"], "features": ["摄取 CycloneDX SBOM，按项目与版本盘点库、容器、操作系统、固件与服务组件", "持续将组件匹配多个漏洞源并输出风险发现，新情报出现时可重新分析已有清单", "以表达式策略引擎执行门禁与自动分诊，通过 REST API、CI 插件和 Web 界面交付"], "github_repository_id": 11457947, "homepage": "https://dependencytrack.org", "id": "github:11457947", "leaf_matches": [{"reason": "以 BOM 为核心记录：摄取 CycloneDX SBOM，按项目与版本保留组件清单，持续重新分析并支持版本/组合聚合，符合 SBOM 记录、产品版本绑定与受管理生命周期三项。", "slug": "sbom-management", "source_urls": ["https://dependencytrack.org/", "https://raw.githubusercontent.com/DependencyTrack/dependency-track/main/README.md"]}, {"reason": "把项目/版本下已解析的第三方组件清单持续匹配多个漏洞源与许可证情报，并将风险绑定到具体组件与版本，输出可操作的每组件发现。", "slug": "software-composition-analysis-sca", "source_urls": ["https://dependencytrack.org/", "https://raw.githubusercontent.com/DependencyTrack/dependency-track/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/DependencyTrack/dependency-track/license", "name": "OWASP Dependency-Track", "repository_url": "https://github.com/DependencyTrack/dependency-track", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:00:07.598754+08:00", "kind": "repository_metadata", "sha256": "a12a8dd2be520fb370cd5611ac29dc12416774ae4d55f5c1ba9d26baf1da5615", "snapshot_path": "sources/a12a8dd2be520fb370cd5611ac29dc12416774ae4d55f5c1ba9d26baf1da5615.txt", "url": "https://api.github.com/repos/DependencyTrack/dependency-track"}, {"fetched_at": "2026-10-26T19:00:29.035000+08:00", "kind": "readme", "sha256": "70b38a18097a812ccd495d827377a2e005bef787b5faa9eb0acd59b65bb79c63", "snapshot_path": "sources/70b38a18097a812ccd495d827377a2e005bef787b5faa9eb0acd59b65bb79c63.txt", "url": "https://raw.githubusercontent.com/DependencyTrack/dependency-track/main/README.md"}, {"fetched_at": "2026-10-26T19:00:20.306322+08:00", "kind": "license", "sha256": "2b3b262de31e4a04ec6d2066c203221367ba4e1bd710d4ca23019ed5ca543325", "snapshot_path": "sources/2b3b262de31e4a04ec6d2066c203221367ba4e1bd710d4ca23019ed5ca543325.txt", "url": "https://api.github.com/repos/DependencyTrack/dependency-track/license"}, {"fetched_at": "2026-10-26T19:02:43.458598+08:00", "kind": "homepage", "sha256": "fa25102aab3cadbf55e08bc0b0be5d744893b7eb6d892b504de8e5903e3d845f", "snapshot_path": "sources/fa25102aab3cadbf55e08bc0b0be5d744893b7eb6d892b504de8e5903e3d845f.txt", "url": "https://dependencytrack.org/"}], "summary": "开源 SBOM/组件分析平台，围绕软件物料清单按项目与版本盘点组件，持续匹配漏洞与许可证风险并执行策略治理。", "technology_stack": ["CycloneDX SBOM", "组件与漏洞匹配", "REST API 与 Web 界面"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:snyk','Snyk Open Source','{"homepage": "https://snyk.io", "id": "commercial:snyk", "leaf_matches": [{"reason": "官方文档正文（Markdown 版）明确其为 SCA 方案，扫描应用使用的开源库，覆盖间接依赖中的漏洞，并检查许可证合规问题、提供修复建议。", "slug": "software-composition-analysis-sca", "source_urls": ["https://docs.snyk.io/scan-fix-and-prevent/scan-with-snyk/snyk-open-source.md"]}], "name": "Snyk Open Source", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:10:46.512860+08:00", "kind": "documentation", "sha256": "ae2680062a39658c8e3339005cadfa850e6a692714ed7259db8cea618eece2b5", "snapshot_path": "sources/ae2680062a39658c8e3339005cadfa850e6a692714ed7259db8cea618eece2b5.txt", "url": "https://docs.snyk.io/scan-fix-and-prevent/scan-with-snyk/snyk-open-source.md"}], "summary": "商业开发者安全平台，Snyk Open Source 对应用的开源依赖做软件成分分析，发现开源依赖（含间接依赖）中的漏洞，并检查许可证合规问题、提供修复建议。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:610316941','Chainloop','{"deployment": ["Helm 安装控制平面与制品 CAS", "Apache-2.0 自托管 OSS 版本"], "features": ["收集并签名 SBOM、扫描、测试报告与 SLSA 来源等证明，并关联到对应提交与发布", "用 Rego/WASM 策略检查证明与材料，违规时阻断流水线并保留可审计记录", "证明存入 OCI registry、S3 或 Azure Blob，控制平面支持 Helm 自托管"], "github_repository_id": 610316941, "homepage": "https://chainloop.dev", "id": "github:610316941", "leaf_matches": [{"reason": "对跨供应链的软件制品保留签名、可核验的证明记录，按完整性/来源可信与策略要求做信任判定，并在 CI/CD 边界实际阻断不合规发布；恶意包行为检测无证据，不纳入本关系。", "slug": "software-supply-chain-security", "source_urls": ["https://raw.githubusercontent.com/chainloop-dev/chainloop/main/README.md", "https://docs.chainloop.dev/concepts/policies"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/chainloop-dev/chainloop/license", "name": "Chainloop", "repository_url": "https://github.com/chainloop-dev/chainloop", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:00:12.411401+08:00", "kind": "repository_metadata", "sha256": "44f1d1a52ef03774956fe1141ab96f0d221fd6e4b0ae89dc0b7dd15701293ed2", "snapshot_path": "sources/44f1d1a52ef03774956fe1141ab96f0d221fd6e4b0ae89dc0b7dd15701293ed2.txt", "url": "https://api.github.com/repos/chainloop-dev/chainloop"}, {"fetched_at": "2026-10-26T19:00:30.635987+08:00", "kind": "readme", "sha256": "fc775299c1c9c1b455012833464a3f16ec80088b336f8f0f54f3def393efa19e", "snapshot_path": "sources/fc775299c1c9c1b455012833464a3f16ec80088b336f8f0f54f3def393efa19e.txt", "url": "https://raw.githubusercontent.com/chainloop-dev/chainloop/main/README.md"}, {"fetched_at": "2026-10-26T19:00:22.078966+08:00", "kind": "license", "sha256": "2a81894ba067eff4f6db342d2cc6eed73b91db5de79e147b29c982ab0b815b8e", "snapshot_path": "sources/2a81894ba067eff4f6db342d2cc6eed73b91db5de79e147b29c982ab0b815b8e.txt", "url": "https://api.github.com/repos/chainloop-dev/chainloop/license"}, {"fetched_at": "2026-10-26T19:00:55.938682+08:00", "kind": "documentation", "sha256": "699aba41876c487f207c35dfc1f26ae4b4df3974d43affe1df3fdf22cfbc964d", "snapshot_path": "sources/699aba41876c487f207c35dfc1f26ae4b4df3974d43affe1df3fdf22cfbc964d.txt", "url": "https://docs.chainloop.dev/concepts/policies"}], "summary": "开源软件供应链安全平台，以签名 in-toto 证明记录 SBOM、扫描与构建来源，用 Rego/WASM 策略在 CI/CD 边界执行放行或阻断，控制平面与制品存储可自托管。", "technology_stack": ["in-toto 证明与 Sigstore 签名", "Rego/WASM 策略引擎", "OCI/S3/Azure Blob 存储"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:66474729','Prowler','{"deployment": ["Docker Compose 自托管 Prowler Local Server", "提供本地仪表板与 API 服务"], "features": ["对 AWS、Azure、GCP、Kubernetes 等环境执行内置安全检查与合规评估", "覆盖 CIS、NIST、PCI-DSS 等合规框架，输出发现、评分与修复指引", "Prowler Local Server 提供 Web 界面与 API；CLI 为独立入口"], "github_repository_id": 66474729, "homepage": "https://prowler.com", "id": "github:66474729", "leaf_matches": [{"reason": "通过授权连接云账户读取资源配置，按内置检查评估并产出配置错误发现，Local Server 提供资源清单、仪表板与发现查看；Attack Paths 等扩展不据以主张 CSPM 核心。", "slug": "cloud-security-posture-management-cspm", "source_urls": ["https://raw.githubusercontent.com/prowler-cloud/prowler/master/README.md", "https://docs.prowler.com/user-guide/tutorials/prowler-app", "https://docs.prowler.com/getting-started/installation/prowler-app"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/prowler-cloud/prowler/license", "name": "Prowler", "repository_url": "https://github.com/prowler-cloud/prowler", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:00:13.890967+08:00", "kind": "repository_metadata", "sha256": "669edc38fc52fc67d6067e6662e7e97031d60c715dcc0c6d6175a0ace3d25838", "snapshot_path": "sources/669edc38fc52fc67d6067e6662e7e97031d60c715dcc0c6d6175a0ace3d25838.txt", "url": "https://api.github.com/repos/prowler-cloud/prowler"}, {"fetched_at": "2026-10-26T19:00:31.940665+08:00", "kind": "readme", "sha256": "7f0fbdb7e980596994bbc6da14202f6f5726f2016fb53f635d872a0aa117c735", "snapshot_path": "sources/7f0fbdb7e980596994bbc6da14202f6f5726f2016fb53f635d872a0aa117c735.txt", "url": "https://raw.githubusercontent.com/prowler-cloud/prowler/master/README.md"}, {"fetched_at": "2026-10-26T19:00:23.963931+08:00", "kind": "license", "sha256": "8f75362577dcad74a8a5b0d61a65d93121f59a2484749a7669f71bbf38fcaff2", "snapshot_path": "sources/8f75362577dcad74a8a5b0d61a65d93121f59a2484749a7669f71bbf38fcaff2.txt", "url": "https://api.github.com/repos/prowler-cloud/prowler/license"}, {"fetched_at": "2026-10-26T19:00:55.768400+08:00", "kind": "documentation", "sha256": "93bb76d682b059945e21827a4f4de093c906a24dc5d940bd3dc04b85c98bad50", "snapshot_path": "sources/93bb76d682b059945e21827a4f4de093c906a24dc5d940bd3dc04b85c98bad50.txt", "url": "https://docs.prowler.com/getting-started/installation/prowler-app"}, {"fetched_at": "2026-10-26T19:01:21.351841+08:00", "kind": "documentation", "sha256": "f01666d9f076c7b5faefa00ca77aaf79173935648f83a68ed4bd37cd3b4fc02b", "snapshot_path": "sources/f01666d9f076c7b5faefa00ca77aaf79173935648f83a68ed4bd37cd3b4fc02b.txt", "url": "https://docs.prowler.com/user-guide/tutorials/prowler-app"}], "summary": "开源多云安全与合规平台，Prowler Local Server 自托管连接云账户，执行大量配置检查，汇总安全发现、合规框架与仪表板。", "technology_stack": ["Python 检查引擎", "多云 Provider 连接", "Web 控制台与 API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sysdig-secure','Sysdig Secure','{"homepage": "https://www.sysdig.com/", "id": "commercial:sysdig-secure", "leaf_matches": [{"reason": "官方产品页正文明确列出 Inventory search（users、workloads、hosts、container images）与 Resource 360 运行中资源视图，并说明实时检测、AI 辅助调查和引导式响应工作流，符合 CWPP 的受管工作负载清单与运行时保护核心。", "slug": "cloud-workload-protection-cwpp", "source_urls": ["https://www.sysdig.com/", "https://www.sysdig.com/products/secure/", "https://www.sysdig.com/platform/secure"]}], "name": "Sysdig Secure", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:04:42.513679+08:00", "kind": "homepage", "sha256": "0922c1f88d8982232af524a2875d0f7dc36c96b22b401fc6a9b84d3fede436b1", "snapshot_path": "sources/0922c1f88d8982232af524a2875d0f7dc36c96b22b401fc6a9b84d3fede436b1.txt", "url": "https://www.sysdig.com/"}, {"fetched_at": "2026-10-26T19:05:03.898717+08:00", "kind": "documentation", "sha256": "7144b1bd410d0a50106e80bdcbd523312a559cd5b2d3c2134a4fe2d9a0f56cbe", "snapshot_path": "sources/7144b1bd410d0a50106e80bdcbd523312a559cd5b2d3c2134a4fe2d9a0f56cbe.txt", "url": "https://www.sysdig.com/products/secure/"}, {"fetched_at": "2026-10-26T19:13:41.736565+08:00", "kind": "documentation", "sha256": "7144b1bd410d0a50106e80bdcbd523312a559cd5b2d3c2134a4fe2d9a0f56cbe", "snapshot_path": "sources/7144b1bd410d0a50106e80bdcbd523312a559cd5b2d3c2134a4fe2d9a0f56cbe.txt", "url": "https://www.sysdig.com/platform/secure"}], "summary": "商业云工作负载保护平台，统一容器与 Kubernetes、主机及云服务的运行时可见性、实时威胁检测、调查与响应；官方页面以 Inventory search 覆盖 users、workloads、hosts 与 container images，并提供 Resource 360 资源视图与风险优先级。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wiz','Wiz','{"homepage": "https://www.wiz.io/", "id": "commercial:wiz", "leaf_matches": [{"reason": "官方 Wiz Cloud 页面列出共享资产清单之上的 CSPM、漏洞管理、CIEM、容器安全、DSPM、CWP 等多域能力，并强调统一 Security Graph 与单一风险视图，符合 CNAPP 结构定义。", "slug": "cnapp", "source_urls": ["https://www.wiz.io/", "https://www.wiz.io/platform/wiz-cloud"]}], "name": "Wiz", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:04:20.571677+08:00", "kind": "homepage", "sha256": "111fb5bdef8f8face7657b65e67397cb25ca65dfc40b6f8c1b4acd80c6c14db1", "snapshot_path": "sources/111fb5bdef8f8face7657b65e67397cb25ca65dfc40b6f8c1b4acd80c6c14db1.txt", "url": "https://www.wiz.io/"}, {"fetched_at": "2026-10-26T19:04:50.435365+08:00", "kind": "documentation", "sha256": "18ea787b4b6ffb7dc48fb7ea808c4600dc2188d105d8749b66ad0837c1753639", "snapshot_path": "sources/18ea787b4b6ffb7dc48fb7ea808c4600dc2188d105d8749b66ad0837c1753639.txt", "url": "https://www.wiz.io/platform/wiz-cloud"}], "summary": "商业 CNAPP，以统一云资产清单与 Security Graph 关联配置、漏洞、身份权限、容器、数据和运行时风险，在单一平台内做跨域优先级排序与修复。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:439449479','NeuVector','{"deployment": ["Kubernetes/OpenShift 集群部署", "Helm Chart 与 Rancher 集成", "manager/controller/enforcer/scanner 多组件镜像"], "features": ["容器镜像漏洞防护", "自动化运行时威胁检测", "Layer 7 容器防火墙"], "github_repository_id": 439449479, "homepage": "https://www.suse.com/products/rancher/security/", "id": "github:439449479", "leaf_matches": [{"reason": "官方 README 与仓库资料表明其为覆盖镜像漏洞防护、运行时检测和容器防火墙的全生命周期容器安全平台，管理对象是容器镜像、运行中容器/Pod 与 Kubernetes 集群。", "slug": "container-kubernetes-security", "source_urls": ["https://api.github.com/repos/neuvector/neuvector", "https://api.github.com/repos/neuvector/neuvector/license", "https://raw.githubusercontent.com/neuvector/neuvector/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/neuvector/neuvector/license", "name": "NeuVector", "repository_url": "https://github.com/neuvector/neuvector", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:04:19.521051+08:00", "kind": "repository_metadata", "sha256": "0dc9f06099b22beab93dfd43a43562f847ded70170cc11a2586faaeda5e14b8f", "snapshot_path": "sources/0dc9f06099b22beab93dfd43a43562f847ded70170cc11a2586faaeda5e14b8f.txt", "url": "https://api.github.com/repos/neuvector/neuvector"}, {"fetched_at": "2026-10-26T19:04:22.565171+08:00", "kind": "license", "sha256": "9414bb51c615b15344b5ba2045b7d549377bbf00605483417f64cc0bf21bee54", "snapshot_path": "sources/9414bb51c615b15344b5ba2045b7d549377bbf00605483417f64cc0bf21bee54.txt", "url": "https://api.github.com/repos/neuvector/neuvector/license"}, {"fetched_at": "2026-10-26T19:04:24.004823+08:00", "kind": "readme", "sha256": "22f3d8bc9633676beca182ebcb601a4a7a3f35e46cecdf7e90946354818388ca", "snapshot_path": "sources/22f3d8bc9633676beca182ebcb601a4a7a3f35e46cecdf7e90946354818388ca.txt", "url": "https://raw.githubusercontent.com/neuvector/neuvector/main/README.md"}], "summary": "Apache-2.0 许可的开源 Kubernetes 原生容器安全平台（SUSE 维护），覆盖镜像漏洞防护、自动化运行时安全与 Layer 7 容器防火墙