INSERT INTO "application" VALUES('commercial:forescout-vistaro','Forescout Vistaro','{"homepage": "https://www.forescout.com/", "id": "commercial:forescout-vistaro", "leaf_matches": [{"reason": "官方 IoT 安全页展示设备自动发现与分类、实时持续监控、弱口令评估、资产清单与基于策略的分段，覆盖 IoT 安全平台的设备资产、每设备评估和持续监控三项核心。", "slug": "iot-security-platform", "source_urls": ["https://www.forescout.com/", "https://www.forescout.com/solutions/iot-security/"]}], "name": "Forescout Vistaro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:04:42.876530+08:00", "kind": "homepage", "sha256": "bef00974e704533c9024d47660fb7c3baa2d628008a11619479871d39e2df33b", "snapshot_path": "sources/bef00974e704533c9024d47660fb7c3baa2d628008a11619479871d39e2df33b.txt", "url": "https://www.forescout.com/"}, {"fetched_at": "2026-10-26T19:05:12.231847+08:00", "kind": "documentation", "sha256": "d848e481254ea5afd415003bc5db072c4ebffe5918efed0ed80d80bcd40f7d7c", "snapshot_path": "sources/d848e481254ea5afd415003bc5db072c4ebffe5918efed0ed80d80bcd40f7d7c.txt", "url": "https://www.forescout.com/solutions/iot-security/"}], "summary": "商业 IoT/OT/IoMT 资产可见性与安全平台，以无代理方式发现并分类联网设备，持续监控设备通信与风险行为，评估弱口令并自动化网络分段与访问策略。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:nozomi-networks-vantage','Nozomi Networks Platform','{"homepage": "https://www.nozominetworks.com/", "id": "commercial:nozomi-networks-vantage", "leaf_matches": [{"reason": "官方平台页明确面向工业与关键基础设施，提供自组装的 OT/IoT 资产清单、持续监控、OT 专用威胁情报与异常检测、风险评分及响应建议，符合 OT 安全平台核心。", "slug": "ot-security-platform", "source_urls": ["https://www.nozominetworks.com/", "https://www.nozominetworks.com/products/"]}], "name": "Nozomi Networks Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:05:37.938145+08:00", "kind": "homepage", "sha256": "99bdd8b77389753aa18a60a0571c31e753192501c03b3af36ceb504f92ed8379", "snapshot_path": "sources/99bdd8b77389753aa18a60a0571c31e753192501c03b3af36ceb504f92ed8379.txt", "url": "https://www.nozominetworks.com/"}, {"fetched_at": "2026-10-26T19:04:23.767855+08:00", "kind": "documentation", "sha256": "61ee55bd5db5050d3519317120bcb9705df6cdcc182ac8337ec9d1b029300a47", "snapshot_path": "sources/61ee55bd5db5050d3519317120bcb9705df6cdcc182ac8337ec9d1b029300a47.txt", "url": "https://www.nozominetworks.com/products/"}], "summary": "商业 OT/IoT 网络安全平台，通过被动/主动传感器持续发现并分类工业资产，监控通信与行为异常，结合 OT 专用威胁情报、漏洞与风险评分及响应工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:appomni','AppOmni','{"homepage": "https://appomni.com/", "id": "commercial:appomni", "leaf_matches": [{"reason": "官方平台页与 Posture Management 专页正文说明其集中管理 SaaS 配置、持续监控配置错误/策略违规与漂移、以发现项和态势评分排序，并提供准确的修复步骤与策略执行，属于 SSPM 商业产品。", "slug": "saas-security-posture-management-sspm", "source_urls": ["https://appomni.com/platform/", "https://appomni.com/use-cases/posture-management/"]}], "name": "AppOmni", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:10:25.791061+08:00", "kind": "homepage", "sha256": "34d8b5a6d2bf4b6e7e57d5a77c1af4469e633485a6285ab61c8276f0644047b1", "snapshot_path": "sources/34d8b5a6d2bf4b6e7e57d5a77c1af4469e633485a6285ab61c8276f0644047b1.txt", "url": "https://appomni.com/platform/"}, {"fetched_at": "2026-10-26T19:13:00.193912+08:00", "kind": "documentation", "sha256": "92b301c8dc4034e480d7ba6d4f0542ebf8f6fca125f15200cfa48ee7d1f94e18", "snapshot_path": "sources/92b301c8dc4034e480d7ba6d4f0542ebf8f6fca125f15200cfa48ee7d1f94e18.txt", "url": "https://appomni.com/use-cases/posture-management/"}], "summary": "AppOmni 是 SaaS 安全态势管理平台，以 agentless 方式集中连接受管 SaaS 应用，持续监测配置错误与配置漂移，并提供修复指引和调查工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:440092871','IRIS','{"deployment": ["Docker Compose 自托管，含 PostgreSQL、RabbitMQ 等服务"], "features": ["SIEM/EDR/REST 告警接入并可升级为案件", "案件级 IOC、任务、证据、笔记与调查时间线", "证据 SHA-256 校验与监管链记录", "案件级/组级 RBAC、审计、报告与 REST API"], "github_repository_id": 440092871, "homepage": "https://docs.dfir-iris.org/latest/", "id": "github:440092871", "leaf_matches": [{"reason": "官方文档显示告警可转为安全案件，案件承载 IOC、任务、证据、时间线与报告，覆盖事件响应案例及响应活动记录的管理闭环。", "slug": "cyber-incident-response-platform", "source_urls": ["https://docs.dfir-iris.org/latest/", "https://api.github.com/repos/dfir-iris/iris-web"]}], "license": "LGPL-3.0", "license_evidence_url": "https://api.github.com/repos/dfir-iris/iris-web/license", "name": "IRIS", "repository_url": "https://github.com/dfir-iris/iris-web", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:10:06.580574+08:00", "kind": "repository_metadata", "sha256": "f85d096f99366a372ff425c5bc5d3be02d72b40142d6cda712f349fcf392d196", "snapshot_path": "sources/f85d096f99366a372ff425c5bc5d3be02d72b40142d6cda712f349fcf392d196.txt", "url": "https://api.github.com/repos/dfir-iris/iris-web"}, {"fetched_at": "2026-10-26T19:10:12.126413+08:00", "kind": "license", "sha256": "eb649f0bc919439cbcd35d1f7b1574dea34fa9afcdf3507d64d167242ebce72e", "snapshot_path": "sources/eb649f0bc919439cbcd35d1f7b1574dea34fa9afcdf3507d64d167242ebce72e.txt", "url": "https://api.github.com/repos/dfir-iris/iris-web/license"}, {"fetched_at": "2026-10-26T19:10:13.395063+08:00", "kind": "readme", "sha256": "a2d24e01454487749db050fe43d8037e12d78103f6219e5339c93fbd0c222433", "snapshot_path": "sources/a2d24e01454487749db050fe43d8037e12d78103f6219e5339c93fbd0c222433.txt", "url": "https://raw.githubusercontent.com/dfir-iris/iris-web/master/README.md"}, {"fetched_at": "2026-10-26T19:10:14.969597+08:00", "kind": "documentation", "sha256": "5e1a2b0dd627f5b78ee98445c0ffbb4b1ff670bd469db82b8bd4f0c269e89b78", "snapshot_path": "sources/5e1a2b0dd627f5b78ee98445c0ffbb4b1ff670bd469db82