INSERT INTO "application" VALUES('commercial:plextrac','PlexTrac','{"homepage": "https://plextrac.com/", "id": "commercial:plextrac", "leaf_matches": [{"reason": "官方平台页正文列明 Schedule & Scope、手动测试执行、发现项聚合、修复与复测（retest）工作流及报告/客户门户，覆盖渗透测试任务与发现生命周期管理。", "slug": "penetration-testing-management", "source_urls": ["https://plextrac.com/platform/"]}], "name": "PlexTrac", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:10:28.674955+08:00", "kind": "homepage", "sha256": "28ca00f40c6f3a7760b392d24ce36788c8c0d7e20defe9e49f8ed677ee9392e3", "snapshot_path": "sources/28ca00f40c6f3a7760b392d24ce36788c8c0d7e20defe9e49f8ed677ee9392e3.txt", "url": "https://plextrac.com/platform/"}], "summary": "PlexTrac 是渗透测试报告与暴露评估平台，覆盖测试任务的排期与范围、手动测试、发现项集中管理、修复与复测工作流及报告交付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:knowbe4','KnowBe4','{"homepage": "https://www.knowbe4.com/", "id": "commercial:knowbe4", "leaf_matches": [{"reason": "官方页面说明其提供持续安全培训与钓鱼模拟，并由 SmartRisk 为每位员工生成动态风险评分、自动编排补救培训，覆盖受管学习者、模拟攻击与项目度量三条核心。", "slug": "security-awareness-platform", "source_urls": ["https://www.knowbe4.com/security-awareness-training"]}], "name": "KnowBe4", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:10:32.120147+08:00", "kind": "homepage", "sha256": "9d4e5f6b14a5d38f127c8566808f8b56d36cc3d1c12a0aacca9e2e9e1813901f", "snapshot_path": "sources/9d4e5f6b14a5d38f127c8566808f8b56d36cc3d1c12a0aacca9e2e9e1813901f.txt", "url": "https://www.knowbe4.com/security-awareness-training"}], "summary": "KnowBe4 是安全意识培训平台，将培训内容、钓鱼模拟与按员工风险评分结合，用于持续训练、测试和度量员工安全行为。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1150018630','OpenCTEM','{"deployment": ["Docker Compose", "all-in-one 容器", "Kubernetes Helm", "自托管或官方云服务"], "features": ["持续暴露面发现与资产清单", "多格式结果合并去重与风险排序", "传感器安全复验、复测与回归重开", "修复任务、SLA 与 Jira/GitHub 同步"], "github_repository_id": 1150018630, "homepage": "https://openctem.io/", "id": "github:1150018630", "leaf_matches": [{"reason": "官网首页给出五阶段 CTEM 闭环（含 validation 与 verified close），产品页 Validation 段进一步明确传感器以安全检查复验发现项、复测按发现项自身工具重跑、修复仅在复测自身证据成立时由有验证权限的人关闭、回归则重开；README 提供平台结构与自托管/云部署说明。覆盖暴露清单→安全复验/复测→修复→复测证据关闭的核心，验证方式为单项安全检查而非完整杀伤链模拟。", "slug": "security-validation-platform", "source_urls": ["https://openctem.io/", "https://openctem.io/product/", "https://raw.githubusercontent.com/openctemio/openctem/develop/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/openctemio/openctem/license", "name": "OpenCTEM", "repository_url": "https://github.com/openctemio/openctem", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:17:51.525081+08:00", "kind": "homepage", "sha256": "b4bd2592dce3f71ae89c0426fee18e0c5ada93999c656fb02c2e37c3698515bf", "snapshot_path": "sources/b4bd2592dce3f71ae89c0426fee18e0c5ada93999c656fb02c2e37c3698515bf.txt", "url": "https://openctem.io/"}, {"fetched_at": "2026-10-26T19:30:07.113928+08:00", "kind": "documentation", "sha256": "1c2092f32da74a7f1576ea4f074082163d83a2e59e66a94b176e77199b2b7a8a", "snapshot_path": "sources/1c2092f32da74a7f1576ea4f074082163d83a2e59e66a94b176e77199b2b7a8a.txt", "url": "https://openctem.io/product/"}, {"fetched_at": "2026-10-26T19:17:58.744114+08:00", "kind": "repository_metadata", "sha256": "6e0b80839a09f2b9ce6ff640b34f5b179ad7c69618b0d689f7679a6832cf273d", "snapshot_path": "sources/6e0b80839a09f2b9ce6ff640b34f5b179ad7c69618b0d689f7679a6832cf273d.txt", "url": "https://api.github.com/repos/openctemio/openctem"}, {"fetched_at": "2026-10-26T19:18:00.328869+08:00", "kind": "license", "sha256": "5ad8c257feef07ccc74bd94964c39bf041563d9c66e3b289ab0057af412db904", "snapshot_path": "sources/5ad8c257feef07ccc74bd94964c39bf041563d9c66e3b289ab0057af412db904.txt", "url": "https://api.github.com/repos/openctemio/openctem/license"}, {"fetched_at": "2026-10-26T19:17:58.641257+08:00", "kind": "readme", "sha256": "aebac4c26f499236714918406523d01031a51b563fc10cca60895d5461ea00d0", "snapshot_path": "sources/aebac4c26f499236714918406523d01031a51b563fc10cca60895d5461ea00d0.txt", "url": "https://raw.githubusercontent.com/openctemio/openctem/develop/README.md"}], "summary": "开源持续威胁暴露管理（CTEM）平台，将资产发现、风险排序、安全验证与修复闭环放在同一套 Go API + Next.js 控制台中；以传感器安全检查复验与复测证据驱动发现项关闭，支持自托管或官方云。", "technology_stack": ["Go API", "Next.js Web 控制台", "PostgreSQL", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:262044260','Shuffle','{"deployment": ["自托管 Docker Compose", "shuffler.io 云服务"], "features": ["可视化工作流编辑器", "预制安全工具应用与 OpenAPI 应用创建", "Webhook/API 触发与执行", "组织/子组织控制"], "github_repository_id": 262044260, "homepage": "https://shuffler.io", "id": "github:262044260", "leaf_matches": [{"reason": "README 描述安全自动化平台、工作流编辑器、预制安全工具应用与自托管执行，符合连接外部工具→编写工作流→触发执行的 SOAR 核心。", "slug": "soar", "source_urls": ["https://raw.githubusercontent.com/Shuffle/Shuffle/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/Shuffle/Shuffle/license", "name": "Shuffle", "repository_url": "https://github.com/Shuffle/Shuffle", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:16:12.915872+08:00", "kind": "repository_metadata", "sha256": "72385f1fbcdf53cb3c81e954f6cb613917068d139f640dc1481c42764dffe8af", "snapshot_path": "sources/72385f1fbcdf53cb3c81e954f6cb613917068d139f640dc1481c42764dffe8af.txt", "url": "https://api.github.com/repos/Shuffle/Shuffle"}, {"fetched_at": "2026-10-26T19:16:20.679836+08:00", "kind": "license", "sha256": "14362f479f7ffc2987350d935eccd4df0a1b7361e64255d575be39c0fc27ac14", "snapshot_path": "sources/14362f479f7ffc2987350d935eccd4df0a1b7361e64255d575be39c0fc27ac14.txt", "url": "https://api.github.com/repos/Shuffle/Shuffle/license"}, {"fetched_at": "2026-10-26T19:16:45.351109+08:00", "kind": "readme", "sha256": "c46bf50ef56a50fec83458064adc3263134220c8fedc6cc4edb0fc59fe2b7b31", "snapshot_path": "sources/c46bf50ef56a50fec83458064adc3263134220c8fedc6cc4edb0fc59fe2b7b31.txt", "url": "https://raw.githubusercontent.com/Shuffle/Shuffle/main/README.md"}], "summary": "开源安全自动化平台（SOAR 核心，AGPL-3.0），提供工作流编辑器、预制安全工具应用、Webhook/API 触发与自托管执行，用于编排安全工具动作和响应流程。", "technology_stack": ["Go 后端", "ReactJS 前端", "Python 应用与 SDK", "OpenAPI 应用定义"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cortex-xsiam','Palo Alto Cortex XSIAM','{"homepage": "https://www.paloaltonetworks.com/cortex/cortex-xsiam", "id": "commercial:cortex-xsiam", "leaf_matches": [{"reason": "Cortex XSIAM 官方页面明确以 SOC platform 定位，列出 SIEM、SOAR、TIP、EDR/NDR、统一数据与自动化分诊，并说明将告警归并为优先案件和统一调查，覆盖原生数据检测、案件层与响应自动化的统一工作流。", "slug": "soc-platform", "source_urls": ["https://www.paloaltonetworks.com/cortex/cortex-xsiam"]}], "name": "Palo Alto Cortex XSIAM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:17:13.975384+08:00", "kind": "homepage", "sha256": "2839b10e67674a2357f0346b17459a4857120c787830590080b742051c811aa9", "snapshot_path": "sources/2839b10e67674a2357f0346b17459a4857120c787830590080b742051c811aa9.txt", "url": "https://www.paloaltonetworks.com/cortex/cortex-xsiam"}], "summary": "商业 SOC 平台，官方页面称其以统一数据层整合 SIEM、SOAR、EDR、NDR、TIP，并将大量告警归并为优先案件，提供自动化分诊、统一调查与引导式处置。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
