INSERT INTO "application" VALUES('commercial:labware','LabWare QA/QC','{"homepage": "https://www.labware.com/", "id": "commercial:labware", "leaf_matches": [{"reason": "官方 QA/QC 页面直接描述 batch/lot 跟踪、规格外结果触发 hold/调查、lot release 与 COA 生成/审批，匹配工业 QC 实验室的“生产批次样品—规格测试—放行/COA”主链。", "slug": "industrial-laboratory-management", "source_urls": ["https://www.labware.com/lims/saas/qaqc", "https://www.labware.com/"]}, {"reason": "产品页明确面向水与环境检测实验室，正文描述采样与监管链、样品从采集到检测的跟踪、超标/逾期标记、合规报告和审计就绪记录，符合环境样品记录—分析工作流—经验证交付物的核心。", "slug": "environmental-laboratory-management", "source_urls": ["https://www.labware.com/industries/water-environmental"]}], "name": "LabWare QA/QC", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:53:31.832111+08:00", "kind": "homepage", "sha256": "201106e84974fa090934886729bc273fc47da08464d7a649844c68ab20f97578", "snapshot_path": "sources/201106e84974fa090934886729bc273fc47da08464d7a649844c68ab20f97578.txt", "url": "https://www.labware.com/"}, {"fetched_at": "2026-10-26T19:53:34.234936+08:00", "kind": "documentation", "sha256": "1fe3cbc03c8d1c01b0f36c769cd3dacb1d137d79d55c126b942306882c8f0c8e", "snapshot_path": "sources/1fe3cbc03c8d1c01b0f36c769cd3dacb1d137d79d55c126b942306882c8f0c8e.txt", "url": "https://www.labware.com/lims/saas/qaqc"}, {"fetched_at": "2026-10-26T22:39:18.483027+08:00", "kind": "documentation", "sha256": "8a0018f0c104c75dcd4ec36963624b97e59e6493c6ff78a5cc86eec507cd73f0", "snapshot_path": "sources/8a0018f0c104c75dcd4ec36963624b97e59e6493c6ff78a5cc86eec507cd73f0.txt", "url": "https://www.labware.com/industries/water-environmental"}], "summary": "LabWare QA/QC 是面向分析测试与物料测试实验室的商业 LIMS，覆盖样品/批次跟踪、规格判定、结果复核、批次/批量放行、COA 自动生成与审批，以及仪器集成和审计追踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:934441434','Atlas CMMS','{"deployment": ["Self-hosted Docker Compose deployment (README quick start)", "Cloud-hosted service optionally available at atlas-cmms.com"], "features": ["Asset, equipment and location register with maintenance history", "Work order creation, assignment, priority, time logging and closure records", "Preventive maintenance and automated work-order triggers", "Service requests and custom roles/permissions", "Parts inventory and purchasing capabilities described in the README (edition/license gating may apply)", "Web dashboard plus React Native mobile app"], "github_repository_id": 934441434, "homepage": "https://atlas-cmms.com/", "id": "github:934441434", "leaf_matches": [{"reason": "Self-hosted CMMS with an asset register, work orders bound to assets, persistent maintenance history, preventive maintenance and service requests documented in the official README and product site.", "slug": "cmms-maintenance-management", "source_urls": ["https://raw.githubusercontent.com/Grashjs/cmms/main/README.MD", "https://atlas-cmms.com/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/Grashjs/cmms/license", "name": "Atlas CMMS", "repository_url": "https://github.com/Grashjs/cmms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:59:01.695817+08:00", "kind": "repository_metadata", "sha256": "77abff1dc0dcfc3fdd04999b93f3723883d12f5142c8e25be927c32f9f59f8f1", "snapshot_path": "sources/77abff1dc0dcfc3fdd04999b93f3723883d12f5142c8e25be927c32f9f59f8f1.txt", "url": "https://api.github.com/repos/Grashjs/cmms"}, {"fetched_at": "2026-10-26T19:59:03.743443+08:00", "kind": "license", "sha256": "2ed91911fb92f34ffae77670089cc5ecea21dea0e0250c880166d924483c67da", "snapshot_path": "sources/2ed91911fb92f34ffae77670089cc5ecea21dea0e0250c880166d924483c67da.txt", "url": "https://api.github.com/repos/Grashjs/cmms/license"}, {"fetched_at": "2026-10-26T19:59:59.357616+08:00", "kind": "readme", "sha256": "85ae43aeaaecfa70128aaad0c9750b684960e8f6c408d01efe9c922011158635", "snapshot_path": "sources/85ae43aeaaecfa70128aaad0c9750b684960e8f6c408d01efe9c922011158635.txt", "url": "https://raw.githubusercontent.com/Grashjs/cmms/main/README.MD"}, {"fetched_at": "2026-10-26T19:59:08.045105+08:00", "kind": "homepage", "sha256": "3f34db1c64ece61f34c6a33f567239add13aa313426de8fde206e11c3a8e2444", "snapshot_path": "sources/3f34db1c64ece61f34c6a33f567239add13aa313426de8fde206e11c3a8e2444.txt", "url": "https://atlas-cmms.com/"}], "summary": "Self-hosted CMMS for assets, work orders and maintenance history. The AGPL-3.0 codebase documents asset/location registers, work orders with labor and history, preventive maintenance, service requests and a React Native mobile app; inventory/purchasing and some enterprise or white-label features may be edition- or license-gated.", "technology_stack": ["Java Spring Boot backend", "React/TypeScript web frontend", "React Native mobile app"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
