INSERT INTO "application" VALUES('github:981534981','LGDXRobot Cloud','{"deployment": ["Docker Compose self-hosted deployment (README fast setup)", "Any ROS 2 compatible robot via the LGDXRobot Cloud Adapter"], "features": ["Robot and fleet setup/configuration with live status", "Real-time map monitoring of robot location, status and planned path", "Task and mission creation with priority and assignment to specific robots", "Multi-fleet management across rooms/floors from one instance", "SLAM map generation, navigation rules and workflow triggers", "Email notifications, API keys, 2FA and certificate-based robot authentication"], "github_repository_id": 981534981, "homepage": "https://lgdxrobot.uk/cloud/", "id": "github:981534981", "leaf_matches": [{"reason": "Web-based AMR fleet manager with a robot register, real-time fleet oversight, task/mission assignment to robots and multi-fleet coordination, documented in the official README and product site.", "slug": "robot-fleet-management", "source_urls": ["https://raw.githubusercontent.com/yukaitung/lgdxrobot-cloud/main/README.md", "https://lgdxrobot.uk/cloud/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/yukaitung/lgdxrobot-cloud/license", "name": "LGDXRobot Cloud", "repository_url": "https://github.com/yukaitung/lgdxrobot-cloud", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T19:59:33.737979+08:00", "kind": "repository_metadata", "sha256": "27e519361b6cc235dab008d900b3192c94ee29d010c9c5c52ec04e4f091ed063", "snapshot_path": "sources/27e519361b6cc235dab008d900b3192c94ee29d010c9c5c52ec04e4f091ed063.txt", "url": "https://api.github.com/repos/yukaitung/lgdxrobot-cloud"}, {"fetched_at": "2026-10-26T19:59:36.043388+08:00", "kind": "license", "sha256": "a0025e162bce618664a8bc2bdc8402c49729cb185b4068bc2088ea08e301366e", "snapshot_path": "sources/a0025e162bce618664a8bc2bdc8402c49729cb185b4068bc2088ea08e301366e.txt", "url": "https://api.github.com/repos/yukaitung/lgdxrobot-cloud/license"}, {"fetched_at": "2026-10-26T19:59:38.758638+08:00", "kind": "readme", "sha256": "c6e285a58eea81ca501b18c3070a282b5f7759286fcb7f29c8059af612770373", "snapshot_path": "sources/c6e285a58eea81ca501b18c3070a282b5f7759286fcb7f29c8059af612770373.txt", "url": "https://raw.githubusercontent.com/yukaitung/lgdxrobot-cloud/main/README.md"}, {"fetched_at": "2026-10-26T19:59:40.675165+08:00", "kind": "homepage", "sha256": "fd0bad38250ff33319fe77e54ca3b471349813afbc83e70cb27fa712192be8b4", "snapshot_path": "sources/fd0bad38250ff33319fe77e54ca3b471349813afbc83e70cb27fa712192be8b4.txt", "url": "https://lgdxrobot.uk/cloud/"}], "summary": "Open-source web-based fleet management system for autonomous mobile robots: robot and fleet registration, real-time status and map monitoring, task creation/prioritization/assignment, multi-fleet operation, SLAM mapping, notifications and role-based access, with Docker Compose self-hosting.", "technology_stack": [".NET ASP.NET Web API backend", "Blazor frontend", "RabbitMQ, Redis and PostgreSQL", "gRPC robot communication"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
