INSERT INTO "application" VALUES('commercial:payrent','PayRent','{"homepage": "https://www.payrent.com/", "id": "commercial:payrent", "leaf_matches": [{"reason": "官网正文明确提供在线租金收取：租户通过平台付款，房东仪表盘展示单元应收、租户余额、已收与未收，自动提醒并拒绝部分付款，同时保护房东银行信息，符合收款平台核心。", "slug": "rent-collection-platform", "source_urls": ["https://www.payrent.com/"]}], "name": "PayRent", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:04:15.729030+08:00", "kind": "homepage", "sha256": "e9afd2c00bea77b307f2b7eb2f7ff9b4d27ab08772bc59fcd7433e032b1fe282", "snapshot_path": "sources/e9afd2c00bea77b307f2b7eb2f7ff9b4d27ab08772bc59fcd7433e032b1fe282.txt", "url": "https://www.payrent.com/"}], "summary": "面向独立房东的租金收款平台：按单元和租户展示应收、余额与到期费用，租户经平台以银行转账或信用卡付款，支持提醒、预约付款和拒绝部分付款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
