INSERT INTO "application" VALUES('github:1224518473','OpenProperty','{"deployment": ["自托管部署（Cloudflare Workers + D1，或本地开发环境）"], "features": ["物业与单元档案，含空置/已租/周转状态", "租户与租约记录，含租金、押金、到期日与滞纳金设置", "按月生成租金费用并记录付款，展示已收、未收与逾期", "维修工单与供应商目录", "入住率、欠租与租约到期仪表盘"], "github_repository_id": 1224518473, "homepage": "https://github.com/clawnify/OpenProperty", "id": "github:1224518473", "leaf_matches": [{"reason": "README 明确覆盖住宅物业与单元、租户、租约、按月租金账本与付款记录、维修工单及供应商，构成自托管住宅租赁运营系统；同时明确不含在线收款、招租分发、真实筛选和住户门户，关系仅限其实际范围。", "slug": "residential-property-management", "source_urls": ["https://raw.githubusercontent.com/clawnify/OpenProperty/master/README.md", "https://api.github.com/repos/clawnify/OpenProperty"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/clawnify/OpenProperty/license", "name": "OpenProperty", "repository_url": "https://github.com/clawnify/OpenProperty", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:03:18.087761+08:00", "kind": "repository_metadata", "sha256": "d5e4c39df5df87c1cafb30a83a48f5684cf6c927020575869e7eff3c6825d0d0", "snapshot_path": "sources/d5e4c39df5df87c1cafb30a83a48f5684cf6c927020575869e7eff3c6825d0d0.txt", "url": "https://api.github.com/repos/clawnify/OpenProperty"}, {"fetched_at": "2026-10-26T20:03:20.357934+08:00", "kind": "license", "sha256": "9eb6f9f6347626d5daac275a45dd2cbee2ae46847b3010770950350697d29b08", "snapshot_path": "sources/9eb6f9f6347626d5daac275a45dd2cbee2ae46847b3010770950350697d29b08.txt", "url": "https://api.github.com/repos/clawnify/OpenProperty/license"}, {"fetched_at": "2026-10-26T20:03:22.301496+08:00", "kind": "readme", "sha256": "9adaae26a5367be97c92a5ccf2c0031f780f57755bab39d4efa93008d358a863", "snapshot_path": "sources/9adaae26a5367be97c92a5ccf2c0031f780f57755bab39d4efa93008d358a863.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenProperty/master/README.md"}], "summary": "MIT 许可的自托管住宅租赁管理应用，覆盖物业/单元、租户、租约、按月租金账本与收款记录、维修工单和供应商；不含在线支付、招租分发、真实筛选与住户门户。", "technology_stack": ["React 19", "TypeScript", "Vite", "Tailwind CSS", "Hono", "Cloudflare Workers", "Cloudflare D1"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:self-storage-manager','Self Storage Manager','{"homepage": "https://www.selfstoragemanager.com/", "id": "commercial:self-storage-manager", "leaf_matches": [{"reason": "官方产品页正文明确这是面向多设施自助仓储运营商的云软件：实时单元库存与在线预订/租赁、租赁协议与电子签名、入住/退租/换仓、循环费用与自动租金调整、逾期锁门和留置费用、租户门户及运营会计报表，完整覆盖单元库存、租赁关系、占用状态与循环租金四个定义核心；仅记录商业基本用途，未深入价格或架构。", "slug": "self-storage-management", "source_urls": ["https://www.selfstoragemanager.com/contents/managementsoftware.aspx"]}], "name": "Self Storage Manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:14:45.604708+08:00", "kind": "homepage", "sha256": "f5816f47d7aaa0c072f8b745c7fe7b8c4668f3148f7df81c0823c20d7475b7cf", "snapshot_path": "sources/f5816f47d7aaa0c072f8b745c7fe7b8c4668f3148f7df81c0823c20d7475b7cf.txt", "url": "https://www.selfstoragemanager.com/contents/managementsoftware.aspx"}], "summary": "面向自助仓储运营商的云物业管理软件，按设施维护实时单元库存与可用性，处理租赁协议、入住/退租/换仓、循环租金与费用、逾期锁门和留置流程，并提供租户门户与运营报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1201444346','RentTools.io','{"deployment": ["MIT 许可下自托管", "Docker 部署", "Linux 单机 systemd/nginx 部署", "SQLite 本地数据库"], "features": ["跨平台 iCal 日历同步与双重预订检测", "退房至入住的清洁周转排期、清洁工分配与冲突提示", "多房源管理及 co-host、清洁工角色权限", "住客护照 OCR 提取与入住前住客信息表单", "消息模板、多语言支持与住客搜索", "入住率、ADR、收入报告及 CSV 导出", "每房源公开的合并 iCal 订阅源"], "github_repository_id": 1201444346, "homepage": "https://renttools.io", "id": "github:1201444346", "leaf_matches": [{"reason": "README 明确该 MIT 项目是短租房东的物业管理应用：以多房源组合为主库存，汇入并回写各渠道预订日历、检测双重预订，按退房/入住间隔生成清洁周转任务，并保存住客与报告；符合短租运营后台核心，未覆盖的渠道 API、动态定价和业主结算属于常见增强而非定义要件。", "slug": "short-term-rental-management", "source_urls": ["https://api.github.com/repos/Gribadan/RentTools.io", "https://raw.githubusercontent.com/Gribadan/RentTools.io/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Gribadan/RentTools.io/license", "name": "RentTools.io", "repository_url": "https://github.com/Gribadan/RentTools.io", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:10:47.312550+08:00", "kind": "repository_metadata", "sha256": "7bcb4bd33cbfa1d93ed49a0a344a3727d1055646b9bda11505093cc39051b9d7", "snapshot_path": "sources/7bcb4bd33cbfa1d93ed49a0a344a3727d1055646b9bda11505093cc39051b9d7.txt", "url": "https://api.github.com/repos/Gribadan/RentTools.io"}, {"fetched_at": "2026-10-26T20:10:49.965201+08:00", "kind": "license", "sha256": "3be30f5e2c786c9101210c945214c5dbd5d6a458ed30f499e827b1893575724d", "snapshot_path": "sources/3be30f5e2c786c9101210c945214c5dbd5d6a458ed30f499e827b1893575724d.txt", "url": "https://api.github.com/repos/Gribadan/RentTools.io/license"}, {"fetched_at": "2026-10-26T20:10:51.202612+08:00", "kind": "readme", "sha256": "0d1cb3bae0f5687bc88e21be3d63088937c23740ea4c7a9a91047be22f23e66d", "snapshot_path": "sources/0d1cb3bae0f5687bc88e21be3d63088937c23740ea4c7a9a91047be22f23e66d.txt", "url": "https://raw.githubusercontent.com/Gribadan/RentTools.io/master/README.md"}], "summary": "面向短租房东的开源物业管理应用，把 Airbnb、Booking.com、Vrbo 等平台的 iCal 日历汇入统一后台并发布合并日历，管理多房源、清洁周转、住客表单与运营报告。", "technology_stack": ["Next.js 16", "TypeScript", "Tailwind CSS 4", "Prisma 7", "SQLite/libSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:room-choice','Room Choice','{"homepage": "https://www.roomchoice.com/", "id": "commercial:room-choice", "leaf_matches": [{"reason": "官方功能页正文明确按 bed/room/unit 跟踪各物业可用性，覆盖申请到入住的租赁流程、续租、电子签约、每日自动计费、住户账本、自助门户和多物业入住率/收入报表，符合学生住房按床位租赁、独立住户账本与续租运营的定义核心；未深入价格或部署。", "slug": "student-housing-management", "source_urls": ["https://www.roomchoice.com/features/"]}], "name": "Room Choice", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:11:16.834869+08:00", "kind": "documentation", "sha256": "1bcba76a69e3e77970631af5b617295b2197d91c55291aab00958634e9e86248", "snapshot_path": "sources/1bcba76a69e3e77970631af5b617295b2197d91c55291aab00958634e9e86248.txt", "url": "https://www.roomchoice.com/features/"}], "summary": "面向学生住房运营商的租赁与计费平台，按床位/房间/单元管理可用性，覆盖申请、电子签约、续租、自动计费、住户账本、自助门户与多物业报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:appfolio-foliospace','AppFolio FolioSpace','{"homepage": "https://www.appfolio.com/property-manager/resident-experience", "id": "commercial:appfolio-foliospace", "leaf_matches": [{"reason": "官方页正文明确 FolioSpace 是绑定 AppFolio Property Manager 记录的住户自助界面：在线租金支付与 AutoPay、维修请求、与物业团队消息沟通、入住任务及申请至续租的住户旅程，符合住户账户锚定运营商记录并针对自身居住关系自助操作的定义核心；未测试运行时。", "slug": "tenant-resident-portal", "source_urls": ["https://www.appfolio.com/property-manager/resident-experience"]}], "name": "AppFolio FolioSpace", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:10:48.270570+08:00", "kind": "homepage", "sha256": "80828de5c0f5016c91344942a7a28f403f2bd8131b8041bf6616a91a062c3c73", "snapshot_path": "sources/80828de5c0f5016c91344942a7a28f403f2bd8131b8041bf6616a91a062c3c73.txt", "url": "https://www.appfolio.com/property-manager/resident-experience"}], "summary": "AppFolio Property Manager 的住户端自助门户与移动应用，住户可在线支付租金并设置 AutoPay、提交维修请求、与物业团队沟通，并完成入住及续租相关自助事项。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1199643986','OpenConstructionERP','{"deployment": ["pip 安装自托管", "桌面安装包", "Docker Compose 部署", "本地嵌入式 PostgreSQL 或独立 PostgreSQL 16+"], "features": ["变更订单：范围变更、成本影响与工期影响明细", "变更订单可关联合同并回写合同金额", "草稿、提交、批准、执行状态流与命名审批链", "批准后作为修订承诺进入项目预算", "变更订单导出 CSV", "更广的 BOQ、估算、招采、进度、财务等建筑 ERP 模块"], "github_repository_id": 1199643986, "homepage": "https://openconstructionerp.com/", "id": "github:1199643986", "leaf_matches": [{"reason": "官方模块指南明确变更订单记录已商定范围的变化及其成本和工期影响，可关联合同，按 Draft→Submitted→Approved→Executed 流转并支持命名审批链，批准后作为修订承诺写入项目预算并修订合同金额；该关系限定为这个完整变更订单模块，而非把整个建筑 ERP 当作变更订单产品。", "slug": "change-order-management", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/changeorders/changeordersGuide.ts", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}, {"reason": "官方文档的 ISO 19650 CDE 明确提供文档容器、受控修订编号与已废止版本保留、WIP/Shared/Published/Archived 状态转换、适用性代码和按 CDE 状态的角色访问；Transmittals 还提供收件人、发送/接收/回执与已废止修订警告。这些直接对应项目文档登记、当前修订纪律和多组织受控发行三个核心属性。", "slug": "construction-document-management", "source_urls": ["https://openconstructionerp.com/docs?lang=en", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md"]}, {"reason": "README 的 BOQ 章节说明从初稿到投标提交的完整估算流程：层级 sections/positions、数量×单价自动计算、章节小计与 markups 总计、资源/assemblies、缺量/零价/重复校验，以及 Excel/CSV/PDF/GAEB 输出；官方文档另列 tender/bid 流程。符合授标前定价行项目、分组汇总和结构化总额的核心。", "slug": "construction-estimating", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md", "https://openconstructionerp.com/docs?lang=en", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md"]}, {"reason": "模块目录列出 daily_diary（天气、条目、照片/视频的签名归档）、fieldreports（每日现场报告，含天气、劳动力、延误和安全）、punchlist（带照片证据和验证的缺陷/整改项）与 inspections/NCR；官方文档说明检查失败项生成后续行动/NCR，NCR 经整改到 Verified 后关闭。日记录与现场工作项两条核心结构均有正文证据。", "slug": "construction-field-management", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md", "https://openconstructionerp.com/docs?lang=en", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}, {"reason": "模块目录的 resources 明确管理人员与班组、技能、可用性和冲突检测；field_time 记录按成本编码且签名的劳务/设备工时；fieldreports 每日报告 workforce；payroll 从现场工时生成工资批次。覆盖已识别工人、计划分配和现场记录两种跟踪形式，并保留向工资交接的环节。", "slug": "construction-labor-management", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}, {"reason": "模块目录的 site_inventory 记录现场材料移动并推导在手库存、损耗率和成本偏差；site_logistics 提供大门、堆场和交付预约；procurement 提供采购订单与收货。官方文档进一步说明采购订单行项目关联 BOQ 位置/成本码，收货记录数量、质量备注和照片。对应带数量的材料记录、移动事件和与工作关联的要求；未据此宣称完整安装闭环。", "slug": "construction-materials-management", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md", "https://openconstructionerp.com/docs?lang=en", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}, {"reason": "Last Planner 模块明确提供主计划、阶段计划、六周前瞻、约束清除、周承诺、PPC 与未完成原因，覆盖共享承诺计划、make-ready 约束和承诺兑现度量。", "slug": "lean-construction-planning", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/schedule-advanced/scheduleAdvancedGuide.ts", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/planning-and-cost-control.md"]}, {"reason": "CRM 机会记录可转为项目并进入招标，招标文档说明从已定价 BOQ 生成投标包、收集并逐项平衡分包/供应报价、授标后转为承诺；覆盖 pursuit、定价范围、供应链询价平衡和授标移交。", "slug": "preconstruction-management", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/tendering-and-bids.md", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/cases/data/track-an-opportunity-from-enquiry-to-tender.playbook.ts", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/crm/crmGuide.ts"]}, {"reason": "合同模块实现进度款申请/索赔、SOV 累计计算、AIA G702/G703 与保留款；AIA 代码说明其建立在既有 ProgressClaim/ProgressClaimLine、认证和财务发票桥上，支持前次申请扣减与保留款。", "slug": "progress-billing", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/backend/app/modules/contracts/aia.py", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/backend/app/modules/contracts/retention.py"]}, {"reason": "规划与成本控制文档说明 4D 进度与 5D 成本模型共同形成预算、S 曲线和挣值，提供基线、进度/成本偏差、EAC/ETC 预测、变更控制和项目控制仪表板。", "slug": "project-controls-platform", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/planning-and-cost-control.md", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}, {"reason": "工程量提取文档说明以 PDF/DWG/IFC 施工文件为尺寸来源，在图纸上测量距离/面积/计数并保留可追溯测量对象，再按 BOQ 项目累计并链接到清单。", "slug": "quantity-takeoff", "source_urls": ["https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/quantity-takeoff.md", "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/datadrivenconstruction/OpenConstructionERP/license", "name": "OpenConstructionERP", "repository_url": "https://github.com/datadrivenconstruction/OpenConstructionERP", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:10:47.291049+08:00", "kind": "repository_metadata", "sha256": "692571eb1dba3814cd66b2c632bc622c9bc4c1013aaf49a74c6edca20c601912", "snapshot_path": "sources/692571eb1dba3814cd66b2c632bc622c9bc4c1013aaf49a74c6edca20c601912.txt", "url": "https://api.github.com/repos/datadrivenconstruction/OpenConstructionERP"}, {"fetched_at": "2026-10-26T20:10:49.225816+08:00", "kind": "license", "sha256": "7743e907422ebfc0c90401e1054cf8097160abd53b249b88bacfde0f97b9f02d", "snapshot_path": "sources/7743e907422ebfc0c90401e1054cf8097160abd53b249b88bacfde0f97b9f02d.txt", "url": "https://api.github.com/repos/datadrivenconstruction/OpenConstructionERP/license"}, {"fetched_at": "2026-10-26T20:10:50.996723+08:00", "kind": "readme", "sha256": "d640bceecae06c83cc5b9d1acf06eb179761df9ed26113663efc97ff4f6e907a", "snapshot_path": "sources/d640bceecae06c83cc5b9d1acf06eb179761df9ed26113663efc97ff4f6e907a.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/README.md"}, {"fetched_at": "2026-10-26T20:11:41.665544+08:00", "kind": "documentation", "sha256": "55eed2fc62f2fa2193080623a113dce7ccb8a363cbe8bbd584b8e7b5c6814463", "snapshot_path": "sources/55eed2fc62f2fa2193080623a113dce7ccb8a363cbe8bbd584b8e7b5c6814463.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/changeorders/changeordersGuide.ts"}, {"fetched_at": "2026-10-26T20:11:49.912368+08:00", "kind": "documentation", "sha256": "145f6e36c5e206fb60969fad6aa00b67bd93708f4a04361303797dcdbb2e3759", "snapshot_path": "sources/145f6e36c5e206fb60969fad6aa00b67bd93708f4a04361303797dcdbb2e3759.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/MODULES.md"}, {"fetched_at": "2026-10-26T20:11:40.268512+08:00", "kind": "documentation", "sha256": "b3a54a86da6568311cb98378dd4d8d3bf410fd73673d0990f3abe613b8b6bdc6", "snapshot_path": "sources/b3a54a86da6568311cb98378dd4d8d3bf410fd73673d0990f3abe613b8b6bdc6.txt", "url": "https://openconstructionerp.com/docs?lang=en"}, {"fetched_at": "2026-10-26T20:24:45.171133+08:00", "kind": "repository_metadata", "sha256": "9b10b8a1633347728b482ccec6276875e28f48a2ce764d812be81607ed7681cf", "snapshot_path": "sources/9b10b8a1633347728b482ccec6276875e28f48a2ce764d812be81607ed7681cf.txt", "url": "https://github.com/datadrivenconstruction/OpenConstructionERP"}, {"fetched_at": "2026-10-26T20:24:43.306390+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/LICENSE"}, {"fetched_at": "2026-10-26T20:24:58.007994+08:00", "kind": "documentation", "sha256": "1cb53ae06109c631c267a484ee4019db305924a093713142a029831e7384eb80", "snapshot_path": "sources/1cb53ae06109c631c267a484ee4019db305924a093713142a029831e7384eb80.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/quantity-takeoff.md"}, {"fetched_at": "2026-10-26T20:24:57.982320+08:00", "kind": "documentation", "sha256": "d240c8c1013ca50aebdd7d4c56cc5bf56cea53dda609dbafe08c6e905326d249", "snapshot_path": "sources/d240c8c1013ca50aebdd7d4c56cc5bf56cea53dda609dbafe08c6e905326d249.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/tendering-and-bids.md"}, {"fetched_at": "2026-10-26T20:24:57.652254+08:00", "kind": "documentation", "sha256": "b14d81508ad6739fe08d5fb265114ad728b8c1bde1e2f1432cf43ae43743a248", "snapshot_path": "sources/b14d81508ad6739fe08d5fb265114ad728b8c1bde1e2f1432cf43ae43743a248.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/docs/user-guide/planning-and-cost-control.md"}, {"fetched_at": "2026-10-26T20:25:06.179861+08:00", "kind": "documentation", "sha256": "36bb3ed25fe2ecfa909978ab8b0bc7aba3413d3fda0af33745d53a545e537441", "snapshot_path": "sources/36bb3ed25fe2ecfa909978ab8b0bc7aba3413d3fda0af33745d53a545e537441.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/schedule-advanced/scheduleAdvancedGuide.ts"}, {"fetched_at": "2026-10-26T20:25:06.248805+08:00", "kind": "documentation", "sha256": "9fe8ae1f8217a41b474ede9bacf0b8334737d7c30192f09851152bde07fc353e", "snapshot_path": "sources/9fe8ae1f8217a41b474ede9bacf0b8334737d7c30192f09851152bde07fc353e.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/backend/app/modules/contracts/aia.py"}, {"fetched_at": "2026-10-26T20:25:05.900372+08:00", "kind": "documentation", "sha256": "8d71480ba0e6e928948e0818a5459962176beee37bd22d53b075fd31c12e2c4c", "snapshot_path": "sources/8d71480ba0e6e928948e0818a5459962176beee37bd22d53b075fd31c12e2c4c.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/cases/data/track-an-opportunity-from-enquiry-to-tender.playbook.ts"}, {"fetched_at": "2026-10-26T20:25:06.139495+08:00", "kind": "documentation", "sha256": "a80ceceb0055d7b5b4b51430a31d7c022a416ad5d628e4d23a695ea6fd57121d", "snapshot_path": "sources/a80ceceb0055d7b5b4b51430a31d7c022a416ad5d628e4d23a695ea6fd57121d.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/backend/app/modules/contracts/retention.py"}, {"fetched_at": "2026-10-26T20:26:54.405179+08:00", "kind": "documentation", "sha256": "9d1f120b32b8967ae07f0e4ec0447adb542fd079e242d606d1bd2e52cda345f4", "snapshot_path": "sources/9d1f120b32b8967ae07f0e4ec0447adb542fd079e242d606d1bd2e52cda345f4.txt", "url": "https://raw.githubusercontent.com/datadrivenconstruction/OpenConstructionERP/main/frontend/src/features/crm/crmGuide.ts"}], "summary": "面向建筑项目管理的开源 ERP，其变更订单模块把范围变更记录关联到合同，按明细计算成本与工期影响，经审批链批准后执行到合同金额与项目预算。", "technology_stack": ["Python 3.12+", "FastAPI", "React", "PostgreSQL 16+"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:buildingconnected','BuildingConnected','{"homepage": "https://construction.autodesk.com/products/buildingconnected/", "id": "commercial:buildingconnected", "leaf_matches": [{"reason": "官方页面明确描述总包/业主的投标管理、投标者网络、在线投标板、Plan Room、招标邀请和截止日期跟踪，构成招标包与投标者参与的双边场所。", "slug": "construction-bidding-platform", "source_urls": ["https://construction.autodesk.com/products/buildingconnected/"]}], "name": "BuildingConnected", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:14:59.871404+08:00", "kind": "documentation", "sha256": "81ff50c9a890f1b2b6db808620ae327657d75dde41f70b23a60045c1bb76cc70", "snapshot_path": "sources/81ff50c9a890f1b2b6db808620ae327657d75dde41f70b23a60045c1bb76cc70.txt", "url": "https://construction.autodesk.com/products/buildingconnected/"}], "summary": "Autodesk 旗下的建筑招标网络，面向总承包商和业主发布投标包、在 Builders Network 中接触分包商，并提供在线投标板；分包商通过 Plan Room 查看邀请并跟踪项目与截止日期，招标方比较报价。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:contraclaim','ContraClaim','{"homepage": "https://web.contraclaim.com/", "id": "commercial:contraclaim", "leaf_matches": [{"reason": "官方正文写明 construction claims management、条款/函件/证据的可追溯记录、首次通知至最终裁决、variations/EOT 记录与 time-bar 跟踪，匹配索赔记录、证据链和受控生命周期。", "slug": "construction-claims-management", "source_urls": ["https://web.contraclaim.com/"]}], "name": "ContraClaim", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:02.387986+08:00", "kind": "documentation", "sha256": "860ebfaa16144a2529805f1dda99f336b89f451ec0169395cbc89e5eba94afee", "snapshot_path": "sources/860ebfaa16144a2529805f1dda99f336b89f451ec0169395cbc89e5eba94afee.txt", "url": "https://web.contraclaim.com/"}], "summary": "面向建筑与基础设施合同团队的索赔管理工作区，将合同条款、往来函件和证据连接到可审计记录，覆盖首次通知到最终裁决，并跟踪变更、工期延长记录和合同时效。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:punchoutpro','PunchOutPro','{"homepage": "https://punchoutpro.app/", "id": "commercial:punchoutpro", "leaf_matches": [{"reason": "官方页面明确描述 punch 项跟踪、照片证明、re-walk 独立验证、业主签收和移交/CO 文件，匹配缺陷项验证关闭与移交验收的收尾核心。", "slug": "construction-closeout-management", "source_urls": ["https://punchoutpro.app/solutions/construction-closeout-software"]}], "name": "PunchOutPro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:05.122405+08:00", "kind": "documentation", "sha256": "5e4489614788b734f0ba063d237d9d521881fe23e2d4fb4185e5b719286f5047", "snapshot_path": "sources/5e4489614788b734f0ba063d237d9d521881fe23e2d4fb4185e5b719286f5047.txt", "url": "https://punchoutpro.app/solutions/construction-closeout-software"}], "summary": "施工收尾与缺陷清单 SaaS，按项目跟踪 punch 项，支持照片完成证明、复查验证、状态可见性和导出报告，并用于业主签收、CO 文件、移交资料及保留金释放。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cmic-project-controls','CMiC Project Controls','{"homepage": "https://cmicglobal.com/", "id": "commercial:cmic-project-controls", "leaf_matches": [{"reason": "官方页面在 Subcontract Management、Change Management、Billing 段落写明分包合同价值/承诺/付款与项目财务对齐、分包合同执行或修订后即时更新、变更单进入账单与 WIP 并保留审计轨迹；这些支持分包合同记录、变更驱动的动态价值和合同相关资金流。页面未出现主合同、合同生命周期状态或 retainage 的直接说明，故不作全生命周期断言。", "slug": "construction-contract-administration", "source_urls": ["https://cmicglobal.com/products/project-management/project-controls"]}], "name": "CMiC Project Controls", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:14:59.253405+08:00", "kind": "documentation", "sha256": "b6f87a2cc2bfd20c7aa74732802a7a20921816471b60001c4a5e0b7bf6939319", "snapshot_path": "sources/b6f87a2cc2bfd20c7aa74732802a7a20921816471b60001c4a5e0b7bf6939319.txt", "url": "https://cmicglobal.com/products/project-management/project-controls"}], "summary": "CMiC 建筑 ERP 的项目控制模块，围绕分包合同管理组织合同价值、承诺与付款：分包合同执行或修订后承诺成本和预测即时更新，变更事件进入预测、分包合同、账单与 WIP，已批准变更单自动进入账单并保留审计轨迹。官方页面未单列主合同、合同生命周期状态或保留金，因此仅按分包合同维度的合同管理能力记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:procore-cost-management','Procore Cost Management','{"homepage": "https://www.procore.com/", "id": "commercial:procore-cost-management", "leaf_matches": [{"reason": "官方成本页写明项目预算、实时支出、发票/变更管理和前瞻性预测；项目财务页补充主合同、分包承诺/采购订单和直接成本，匹配预算—记录成本—对比/预测的成本控制核心。", "slug": "construction-cost-management", "source_urls": ["https://www.procore.com/cost-management", "https://www.procore.com/project-financials"]}], "name": "Procore Cost Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:02.606688+08:00", "kind": "documentation", "sha256": "d0c9d8333e9a7e13de69b8185ad534810ec03ccac22f8062ccb4469c4a07bc05", "snapshot_path": "sources/d0c9d8333e9a7e13de69b8185ad534810ec03ccac22f8062ccb4469c4a07bc05.txt", "url": "https://www.procore.com/cost-management"}, {"fetched_at": "2026-10-26T20:15:05.707584+08:00", "kind": "documentation", "sha256": "6d04c0fc2e79d3cb0f7cf0fcc7e17c863d1c619c41246a4131d7e8bbf9fa659c", "snapshot_path": "sources/6d04c0fc2e79d3cb0f7cf0fcc7e17c863d1c619c41246a4131d7e8bbf9fa659c.txt", "url": "https://www.procore.com/project-financials"}], "summary": "Procore 的施工成本管理产品，集中管理项目预算、成本、发票和变更，提供实时支出与预算对比、前瞻性成本预测和报告，并通过 Project Financials 关联主合同、分包承诺与直接成本。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:procore','Procore','{"homepage": "https://procore.com/", "id": "commercial:procore", "leaf_matches": [{"reason": "官方项目页正文写明按项目连接团队与项目信息，列出 RFI、提交物、会议、通信、图纸修订、项目目录及可定制权限，并提及 owners/partners、general contractors、vendors；对应项目容器、多组织社区和跨方协调记录三项定义核心。", "slug": "construction-project-management", "source_urls": ["https://www.procore.com/project-management"]}, {"reason": "官方质量与安全页写明可用模板在移动端执行检查清单，检查项失败或需跟进时创建须完成的观察记录，并可指派、跟踪多种观察与纠正措施；官方 Inspections 页补充可定制检查模板与实时问题跟踪，Observations 页补充非符合/安全违规观察、指派责任方与截止日期、维护实时动作历史并跟踪至完成。上述证据支持检查记录→不符合/观察→指派纠正→跟踪完成的闭环，但未证明由不同有权方另行验证关闭。", "slug": "construction-quality-management", "source_urls": ["https://www.procore.com/quality-safety", "https://www.procore.com/quality-safety/inspections", "https://www.procore.com/quality-safety/observations"]}, {"reason": "Procore 官方支持文档说明送审件是承包方提交给设计团队审批的材料、设备或车间图纸，批准后方可制造安装；审批工作流指定提交者、审核者与分发角色。Submittals Log 是项目级送审登记册，按规范章节、编号/修订号、标题和类型列出记录；修订说明被拒后对同一送审件创建 revision 并保留关联。三者覆盖登记册、审查决定与修订循环。", "slug": "submittal-management", "source_urls": ["https://support.procore.com/faq/what-is-a-submittal", "https://support.procore.com/faq/what-is-a-submittal-revision", "https://support.procore.com/faq/what-does-each-column-in-the-submittals-log-represent"]}], "name": "Procore", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:15.254571+08:00", "kind": "homepage", "sha256": "40b38189762b9df90baafe5074cdcb26c574897299187369720ce5b1d706e238", "snapshot_path": "sources/40b38189762b9df90baafe5074cdcb26c574897299187369720ce5b1d706e238.txt", "url": "https://www.procore.com/project-management"}, {"fetched_at": "2026-10-26T20:15:19.993659+08:00", "kind": "homepage", "sha256": "35ee73ed6b5fc1f2ec23c42bc849725c7de754891f6d4c66fa4aecb3b2dedb57", "snapshot_path": "sources/35ee73ed6b5fc1f2ec23c42bc849725c7de754891f6d4c66fa4aecb3b2dedb57.txt", "url": "https://www.procore.com/quality-safety"}, {"fetched_at": "2026-10-26T20:22:33.848112+08:00", "kind": "documentation", "sha256": "58c4e29ade549a194b0ca818b4dbe87be0feb9a53cb6bfb88b952646c0f9d3aa", "snapshot_path": "sources/58c4e29ade549a194b0ca818b4dbe87be0feb9a53cb6bfb88b952646c0f9d3aa.txt", "url": "https://www.procore.com/quality-safety/inspections"}, {"fetched_at": "2026-10-26T20:22:33.628339+08:00", "kind": "documentation", "sha256": "c59534dec7c1308b0e59cd5e6637d692a9769cc0e871d62a66cea75d6d917928", "snapshot_path": "sources/c59534dec7c1308b0e59cd5e6637d692a9769cc0e871d62a66cea75d6d917928.txt", "url": "https://www.procore.com/quality-safety/observations"}, {"fetched_at": "2026-10-26T20:42:01.401519+08:00", "kind": "documentation", "sha256": "17434ed9dc77d52f550af4b41507e4a427da377363473cd3128946910e85c67e", "snapshot_path": "sources/17434ed9dc77d52f550af4b41507e4a427da377363473cd3128946910e85c67e.txt", "url": "https://support.procore.com/faq/what-is-a-submittal"}, {"fetched_at": "2026-10-26T20:42:04.335444+08:00", "kind": "documentation", "sha256": "88c015bd0a1febd6f1211fa9cb23543de7e76586a8c797e739475d4bbd133bf7", "snapshot_path": "sources/88c015bd0a1febd6f1211fa9cb23543de7e76586a8c797e739475d4bbd133bf7.txt", "url": "https://support.procore.com/faq/what-is-a-submittal-revision"}, {"fetched_at": "2026-10-26T20:42:25.061379+08:00", "kind": "documentation", "sha256": "9fef2368a2877a9dfdf4955492f0dbb13cd7e7e277d523c51a4451125a21b338", "snapshot_path": "sources/9fef2368a2877a9dfdf4955492f0dbb13cd7e7e277d523c51a4451125a21b338.txt", "url": "https://support.procore.com/faq/what-does-each-column-in-the-submittals-log-represent"}], "summary": "Procore 是商业建筑项目管理平台，按项目组织业主、总包与供应商协作，提供 RFI、提交物、会议纪要、通信、图纸修订和项目目录权限等正式协调记录，并在同一项目容器内提供检查、观察与纠正措施等质量安全模块。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:openspace','OpenSpace Capture','{"homepage": "https://www.openspace.ai/", "id": "commercial:openspace", "leaf_matches": [{"reason": "官方 Capture 页正文写明 Spatial AI 自动为影像打时间戳并映射到平面图，按时间/日期查看，Split View 对比两个日期，覆盖确认与 Field Notes/问题跟踪，并可向 Punch/Observation/Issue 工作流交接；对应带日期、可定位、可比较的现场视觉历史核心。", "slug": "construction-reality-capture-platform", "source_urls": ["https://www.openspace.ai/products/capture"]}], "name": "OpenSpace Capture", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:14.200285+08:00", "kind": "homepage", "sha256": "cb7965019d16a81196d86724e9a26b69fdd368ab77631d79a2396456a0bdf0a0", "snapshot_path": "sources/cb7965019d16a81196d86724e9a26b69fdd368ab77631d79a2396456a0bdf0a0.txt", "url": "https://www.openspace.ai/products/capture"}], "summary": "OpenSpace Capture 是商业建筑实景捕捉平台，将 360° 相机、无人机、手机与激光扫描影像自动映射到平面图和 BIM，按日期保留可导航的现场视觉记录，支持跨日期对比、覆盖确认、Field Notes 与问题跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1242815792','BeaconHS','{"deployment": ["自托管：Node 24、pnpm 与 Docker Compose 启动本地 Postgres、Redis、MinIO", "提供 macOS/Windows/Linux 一键启动脚本，可用 pnpm 手动部署", "AGPL-3.0，可作为网络服务自托管并需按许可证公开修改后的源码"], "features": ["事件与未遂事件登记及调查工作流（事件时间线、贡献因素、5-whys 根因、预防步骤）", "纠正与预防措施（CAPA）含验证关闭、照片证据、逾期报告和批量改派", "检查模板与标准库、危险评估风险矩阵、签名与不合规项处理", "培训、设备、PPE、许可、文档和人员/项目/地点等 HSE 模块", "可配置表单引擎、自动化画布和内置分析", "逐条变更审计与多租户 PostgreSQL 行级安全隔离"], "github_repository_id": 1242815792, "homepage": "https://github.com/braedonsaunders/beaconhs", "id": "github:1242815792", "leaf_matches": [{"reason": "README 正文写明面向工业建筑的多租户 HSE 平台，含事件与完整调查、检查/危险评估、带照片证据与验证关闭的 CAPA、项目/站点/人员锚定和逐条变更审计；对应安全事件与发现记录、项目锚定、纠正行动闭环与可辩护留存四项核心。", "slug": "construction-safety-management", "source_urls": ["https://raw.githubusercontent.com/braedonsaunders/beaconhs/HEAD/README.md", "https://api.github.com/repos/braedonsaunders/beaconhs"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/braedonsaunders/beaconhs/license", "name": "BeaconHS", "repository_url": "https://github.com/braedonsaunders/beaconhs", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:14:01.191347+08:00", "kind": "repository_metadata", "sha256": "d7e8126ef12447540be677b477f7f7c7cf5ac3eeb0a0e411e70601d67574b275", "snapshot_path": "sources/d7e8126ef12447540be677b477f7f7c7cf5ac3eeb0a0e411e70601d67574b275.txt", "url": "https://api.github.com/repos/braedonsaunders/beaconhs"}, {"fetched_at": "2026-10-26T20:14:26.120678+08:00", "kind": "license", "sha256": "755243b88ef8493a9516ba7131c055cb94fa5c18314f7a679c5f0cf893bc7ca9", "snapshot_path": "sources/755243b88ef8493a9516ba7131c055cb94fa5c18314f7a679c5f0cf893bc7ca9.txt", "url": "https://api.github.com/repos/braedonsaunders/beaconhs/license"}, {"fetched_at": "2026-10-26T20:17:52.737003+08:00", "kind": "readme", "sha256": "a9a1ca7f7bd0dd1068172758f8aaad4d99e739807cbb0c2da38e4bace4ceb618", "snapshot_path": "sources/a9a1ca7f7bd0dd1068172758f8aaad4d99e739807cbb0c2da38e4bace4ceb618.txt", "url": "https://raw.githubusercontent.com/braedonsaunders/beaconhs/HEAD/README.md"}], "summary": "BeaconHS 是面向工业建筑的多租户开源 HSE 平台，覆盖事件与未遂事件、调查、检查与危险评估、CAPA 验证关闭、培训、设备、许可和可配置表单；AGPL-3.0，自托管。公开社区核心提供完整平台功能，未见单独的付费企业版；company-specific migration tooling 为私有、未包含在公开 workspace。", "technology_stack": ["Next.js 16 / React 19 / TypeScript", "PostgreSQL + Drizzle ORM + 行级安全（RLS）", "BullMQ + Redis 后台任务", "S3 兼容存储（开发用 MinIO，生产可用 Cloudflare R2）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:oracle-primavera-p6','Oracle Primavera P6 EPPM','{"homepage": "https://oracle.com/construction-engineering/primavera-p6", "id": "commercial:oracle-primavera-p6", "leaf_matches": [{"reason": "Oracle 官方产品页以 CPM Schedule 为核心功能，说明多用户访问、多项目并行排程、状态更新与资源/成本联动；官方 P6 帮助页进一步说明活动依赖关系和关键活动（critical activities）的图示。两者结合对应以活动与依赖计算日期并维护项目计划的定义核心。", "slug": "construction-scheduling", "source_urls": ["https://www.oracle.com/construction-engineering/primavera-p6", "https://docs.oracle.com/cd/F51301_01/p6help/en/37742.htm"]}], "name": "Oracle Primavera P6 EPPM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:15:19.165111+08:00", "kind": "homepage", "sha256": "702bce2aa9f0b1fcf4fe18139576e2252025cc7208f7e6762bdd80b963ca6ff1", "snapshot_path": "sources/702bce2aa9f0b1fcf4fe18139576e2252025cc7208f7e6762bdd80b963ca6ff1.txt", "url": "https://www.oracle.com/construction-engineering/primavera-p6"}, {"fetched_at": "2026-10-26T20:16:22.314617+08:00", "kind": "documentation", "sha256": "2405ccef272a85e489e9c66f4214c2ce39750c3c5b6b587971ba95a255776c7b", "snapshot_path": "sources/2405ccef272a85e489e9c66f4214c2ce39750c3c5b6b587971ba95a255776c7b.txt", "url": "https://docs.oracle.com/cd/F51301_01/p6help/en/37742.htm"}], "summary": "Oracle Primavera P6 EPPM 是商业项目组合与 CPM 进度管理平台，以项目、活动、依赖关系和日历组织施工进度，支持多用户、多项目、进度状态更新、资源与成本加载，以及关键活动和关键路径分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hammertech','HammerTech','{"homepage": "https://www.hammertech.com/", "id": "commercial:hammertech", "leaf_matches": [{"reason": "官方正文明确分包商公司目录（名称、地址、活跃项目）、保险/安全文件与到期跟踪、分包商自助上传和预审问题/审批状态，同时展示每家分包商参与的项目，覆盖公司群体、适任状态与项目关联三段核心。", "slug": "subcontractor-management", "source_urls": ["https://www.hammertech.com/en-us/platform/subcontractor-management"]}], "name": "HammerTech", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:25:57.524191+08:00", "kind": "documentation", "sha256": "0f3c2424122e20beae2490c5595002837e822380d75fb5aee3c405cda95e4ee2", "snapshot_path": "sources/0f3c2424122e20beae2490c5595002837e822380d75fb5aee3c405cda95e4ee2.txt", "url": "https://www.hammertech.com/en-us/platform/subcontractor-management"}], "summary": "面向总包与业主的施工分包商安全与合规管理 SaaS；以分包商公司档案为中心，关联活跃项目、保险与安全文件，分包商可自助上传材料接收到期提醒，并支持资格预审问题与审批状态。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:skyciv-structural-3d','SkyCiv Structural 3D','{"homepage": "https://skyciv.com/", "id": "commercial:skyciv-structural-3d", "leaf_matches": [{"reason": "官方产品页与 Structural 3D 文档页明确浏览器端三维建模、集成荷载组合、线性/非线性/屈曲/动力分析，以及钢、混凝土、木、冷弯构件和连接的规范设计验算，结果附完整公式、规范引用与计算报告；覆盖结构模型、荷载、响应和规范验算四段核心。", "slug": "structural-engineering-design", "source_urls": ["https://skyciv.com/structural-software/", "https://skyciv.com/structural-software/s3d-structural-analysis-software/"]}], "name": "SkyCiv Structural 3D", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:25:04.377328+08:00", "kind": "documentation", "sha256": "570b93ea0adf20cfd786f79eef349ef46cde84b6e82f18c9532234186b821349", "snapshot_path": "sources/570b93ea0adf20cfd786f79eef349ef46cde84b6e82f18c9532234186b821349.txt", "url": "https://skyciv.com/structural-software/"}, {"fetched_at": "2026-10-26T20:30:16.237003+08:00", "kind": "documentation", "sha256": "cc465b795617caa12f0be2bae71a2a3c598bb824a5970e90885cd92658166275", "snapshot_path": "sources/cc465b795617caa12f0be2bae71a2a3c598bb824a5970e90885cd92658166275.txt", "url": "https://skyciv.com/structural-software/s3d-structural-analysis-software/"}], "summary": "浏览器端结构分析与设计 SaaS；维护三维结构模型和荷载组合，运行线性、非线性、屈曲与动力分析，并按 AISC、ACI、Eurocode、AS、CSA 等规范做构件与连接验算，输出含公式和规范引用的计算报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1418976622','openMAINT','{"deployment": ["Web 应用，部署在 Tomcat 上并使用 PostgreSQL/PostGIS", "官方仓库提供 openmaint.war 与安装向导，要求 Java 25、Tomcat 11、PostgreSQL 17", "可由组织自托管；官方另提供在线演示"], "features": ["按园区、建筑、楼层、房间和机电设备/技术资产建立可定制资产卡", "技术档案记录状况、状态，行政档案记录维护成本、折旧与维护覆盖", "预防性与故障维修、维护手册、工单和检查表", "备件仓库、经济预算与能耗环境管理", "GIS 与 IFC/BIM 模型查看", "资产手册、图片、合同等文档档案"], "github_repository_id": 1418976622, "homepage": "https://www.openmaint.org/", "id": "github:1418976622", "leaf_matches": [{"reason": "官方资产清单页明确按园区、建筑、楼层、房间及机电设备/技术资产建卡，技术档案记录状况与状态，行政档案记录维护成本、折旧和维护覆盖；设施维护页明确预防性/故障维修、维护手册、工单和检查表，形成建筑位置资产、可追溯维护历史与状况/成本生命周期视图。", "slug": "building-asset-management", "source_urls": ["https://www.openmaint.org/en/product/modules/space-asset-inventory", "https://www.openmaint.org/en/product/modules/facility-maintenance", "https://raw.githubusercontent.com/Pat-srl/cmdbuild/master/README.md", "https://www.openmaint.org/en"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/Pat-srl/cmdbuild/license", "name": "openMAINT", "repository_url": "https://github.com/Pat-srl/cmdbuild", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:24:48.549699+08:00", "kind": "homepage", "sha256": "3748277c8e268c17577a0a19e922be04f0a9eb9a4ba8cb6a7431c9c1feb8663c", "snapshot_path": "sources/3748277c8e268c17577a0a19e922be04f0a9eb9a4ba8cb6a7431c9c1feb8663c.txt", "url": "https://www.openmaint.org/en"}, {"fetched_at": "2026-10-26T20:27:53.480861+08:00", "kind": "documentation", "sha256": "a6d1559dc03ce32c0b2fce4fc260b027ca313fb067e788edc691d918c72a5acc", "snapshot_path": "sources/a6d1559dc03ce32c0b2fce4fc260b027ca313fb067e788edc691d918c72a5acc.txt", "url": "https://www.openmaint.org/en/product"}, {"fetched_at": "2026-10-26T20:27:47.918195+08:00", "kind": "documentation", "sha256": "10a9584aa83cde7aac2e06782b5f4e8d12c565d700baa933aa9de6d59cc267b7", "snapshot_path": "sources/10a9584aa83cde7aac2e06782b5f4e8d12c565d700baa933aa9de6d59cc267b7.txt", "url": "https://www.openmaint.org/en/product/modules/space-asset-inventory"}, {"fetched_at": "2026-10-26T20:27:50.686512+08:00", "kind": "documentation", "sha256": "d8f60c68b69db40a037470024ce26b89122fa123182a379050c590a15bf2517b", "snapshot_path": "sources/d8f60c68b69db40a037470024ce26b89122fa123182a379050c590a15bf2517b.txt", "url": "https://www.openmaint.org/en/product/modules/facility-maintenance"}, {"fetched_at": "2026-10-26T20:25:56.103507+08:00", "kind": "repository_metadata", "sha256": "3a44c7b82c88354383edd9a4adf9d23690dc3c5820ffb56c2389e081d60361db", "snapshot_path": "sources/3a44c7b82c88354383edd9a4adf9d23690dc3c5820ffb56c2389e081d60361db.txt", "url": "https://api.github.com/repos/Pat-srl/cmdbuild"}, {"fetched_at": "2026-10-26T20:25:58.249328+08:00", "kind": "license", "sha256": "2a3c7fa154a2ac42eca590e30c66613be1d8c4edc80f9b3e9d71b8878f08ae1c", "snapshot_path": "sources/2a3c7fa154a2ac42eca590e30c66613be1d8c4edc80f9b3e9d71b8878f08ae1c.txt", "url": "https://api.github.com/repos/Pat-srl/cmdbuild/license"}, {"fetched_at": "2026-10-26T20:25:59.846116+08:00", "kind": "readme", "sha256": "41bb4eb860265af576eaf8555cd1b30e87f047888ca99fafeede10d5fe3c75a2", "snapshot_path": "sources/41bb4eb860265af576eaf8555cd1b30e87f047888ca99fafeede10d5fe3c75a2.txt", "url": "https://raw.githubusercontent.com/Pat-srl/cmdbuild/master/README.md"}], "summary": "openMAINT 是 CMDBuild 开源平台上的物业与设施管理发行版（AGPL-3.0）；以建筑、楼层、房间和机电设备等资产卡为中心，记录状况、维护成本与折旧，管理预防性和故障维修工单，并支持 IFC/BIM 查看。", "technology_stack": ["Java", "Apache Tomcat", "PostgreSQL/PostGIS", "CMDBuild", "IFC/BIM"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gordian-assessments-capital-planning','Gordian Assessments and Capital Planning','{"homepage": "https://www.gordian.com/", "id": "commercial:gordian-assessments-capital-planning", "leaf_matches": [{"reason": "官方产品页明确提供 FCA/FCA+、资产级状况数据、Asset Capture 现场记录、RSMeans 成本估算与多年资本计划，覆盖建筑状况评估的元素—状况—成本—资本计划核心。", "slug": "building-condition-assessment", "source_urls": ["https://www.gordian.com/products/assessment-and-planning/"]}], "name": "Gordian Assessments and Capital Planning", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:32:02.236101+08:00", "kind": "documentation", "sha256": "7b264ae66896f127a1c87ada8514c2ca6ae9c22adf238b2a3a297a7ec55c3bdb", "snapshot_path": "sources/7b264ae66896f127a1c87ada8514c2ca6ae9c22adf238b2a3a297a7ec55c3bdb.txt", "url": "https://www.gordian.com/products/assessment-and-planning/"}], "summary": "Gordian Cloud Platform 上的设施评估与资本规划产品：提供 Facility Condition Assessment (FCA/FCA+)、Modeled Assessment 和 Self-Assessment，使用 Asset Capture 现场采集建筑资产与状况，并依托 RSMeans 成本数据把资产需求转为多年资本计划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:240169434','MyEMS','{"deployment": ["自托管社区版：MyEMS API、Web UI、Admin UI、数据库与采集服务", "官方社区版文档提供 Docker 与私有云部署说明", "社区版免费；企业版的光伏、储能、充电桩、微电网、设备控制等可选功能不计入本条"], "features": ["建筑/园区空间、仪表、设备与租户台账", "在线仪表与离线仪表能耗、成本、碳排放数据", "同比、环比、自由对比等跨时间/空间比较", "能耗/成本/碳排放报表、看板与 Excel 导出", "租户账单及仪表/空间/设备跟踪"], "github_repository_id": 240169434, "homepage": "https://myems.cn", "id": "github:240169434", "leaf_matches": [{"reason": "官方 README 明确 MyEMS 面向建筑、工厂、商场、医院和园区采集、分析并报告电/水/气/冷/热等能耗；社区版文档列出空间/仪表/设备/租户层级、在线与离线仪表、同比/环比/自由对比、仪表与空间能耗/成本/碳排放报表、看板、租户账单和 Excel 导出，覆盖建筑/场地—消费记录—比较分析—可视化报告核心。", "slug": "building-energy-management", "source_urls": ["https://raw.githubusercontent.com/MyEMS/myems/master/README.md", "https://myems.cn/en/docs/community/"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/MyEMS/myems/master/LICENSE", "license_review": {"rationale": "社区版 LICENSE 正文为标准 MIT 条款（授权与免责声明齐全），并附“不得移除或修改 MyEMS LOGO 或版权信息”的附加条件；官方社区版页面也标注 Open Source / MIT License 并说明须保留 LOGO 与版权标识。此处按 MIT 记录社区版核心，同时明确该附加条件，不把企业版功能计入。", "reviewer": "OpenCode collection review (unit 170 repair)", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/MyEMS/myems/master/LICENSE", "spdx_id": "MIT"}, "name": "MyEMS", "repository_url": "https://github.com/MyEMS/myems", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:43:08.206338+08:00", "kind": "repository_metadata", "sha256": "440a0ea55d822aba0c767632913024102631ba46add44e3e96dba4010ac620c3", "snapshot_path": "sources/440a0ea55d822aba0c767632913024102631ba46add44e3e96dba4010ac620c3.txt", "url": "https://api.github.com/repos/MyEMS/myems"}, {"fetched_at": "2026-10-26T20:43:09.943391+08:00", "kind": "readme", "sha256": "f9ee2d0055526af80b0fc2046adece117c71d7d6ced7ff25a91aea697762dcb7", "snapshot_path": "sources/f9ee2d0055526af80b0fc2046adece117c71d7d6ced7ff25a91aea697762dcb7.txt", "url": "https://raw.githubusercontent.com/MyEMS/myems/master/README.md"}, {"fetched_at": "2026-10-26T20:43:07.908876+08:00", "kind": "license", "sha256": "2ff2d46afb3f180c84c77b9614177714d274fafca32f1ef55a30c3b2c3734c5a", "snapshot_path": "sources/2ff2d46afb3f180c84c77b9614177714d274fafca32f1ef55a30c3b2c3734c5a.txt", "url": "https://raw.githubusercontent.com/MyEMS/myems/master/LICENSE"}, {"fetched_at": "2026-10-26T20:43:08.691006+08:00", "kind": "documentation", "sha256": "7b051f2701c6f41d5aa3268ae4b6c970442aec786ee07b0f9493c66327f84a0d", "snapshot_path": "sources/7b051f2701c6f41d5aa3268ae4b6c970442aec786ee07b0f9493c66327f84a0d.txt", "url": "https://myems.cn/en/docs/community/"}], "summary": "MyEMS 是开源社区版建筑/园区能源管理系统：按空间、仪表、设备、租户组织建筑与场地，采集在线/离线仪表能耗，提供同比/环比/自由对比、能耗/成本/碳排放报表、仪表与空间看板、租户账单和 Excel 导出。社区版许可证为 MIT 正文，另附保留 MyEMS LOGO 与版权标识的附加条件。", "technology_stack": ["Python", "ReactJS", "AngularJS", "MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:condo-control','Condo Control','{"homepage": "https://www.condocontrol.com/", "id": "commercial:condo-control", "leaf_matches": [{"reason": "官方 Amenity Booking 页明确运营者配置设施页面与预约限制、住户支付费用/押金、管理员审批或拒绝并通知、移动端预约，覆盖建筑共享设施的可预约清单、住户预约、审批与楼宇侧控制界面等核心要素。", "slug": "amenity-booking-platform", "source_urls": ["https://www.condocontrol.com/resident/amenity-booking/"]}], "name": "Condo Control", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:32:07.919106+08:00", "kind": "documentation", "sha256": "ae5c910b02718d03bb4550011fcba26289e7570eee50e8549f244f5bf3ca19f3", "snapshot_path": "sources/ae5c910b02718d03bb4550011fcba26289e7570eee50e8549f244f5bf3ca19f3.txt", "url": "https://www.condocontrol.com/resident/amenity-booking/"}], "summary": "Condo Control 是面向公寓、HOA 和物业管理公司的社区管理平台，其 Amenity Booking 模块让运营者为楼宇共享设施建立可预约页面、限制可约时长与频率、支持住户在线支付费用和押金、审批或拒绝预订，并向住户发送通知；住户可在门户或移动端预约并支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:facilio','Facilio','{"homepage": "https://facilio.com/", "id": "commercial:facilio", "leaf_matches": [{"reason": "官方预防性维护页明确按资产类别/位置配置 PPM、按时间/用量/状况触发工单、分派技术人员或供应商、记录检查清单和资产历史，面向物业/设施组合，符合建筑设备维护的资产—工单—预防性计划—历史核心。", "slug": "building-maintenance-management", "source_urls": ["https://facilio.com/product/preventive-maintenance-software/"]}], "name": "Facilio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:32:08.659174+08:00", "kind": "documentation", "sha256": "3770932a167a94a52fa12380f49a4cc501868b580bf5622495321fab66824393", "snapshot_path": "sources/3770932a167a94a52fa12380f49a4cc501868b580bf5622495321fab66824393.txt", "url": "https://facilio.com/product/preventive-maintenance-software/"}], "summary": "Facilio 是面向物业与设施运营的 Connected CMMS：按资产类别、位置、优先级或关键性配置预防性维护计划，自动生成并分派工单，技术人员或供应商执行检查清单并记录资产历史，支持多站点组合运营。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tenna','Tenna','{"homepage": "https://www.tenna.com/", "id": "commercial:tenna", "leaf_matches": [{"reason": "官方施工设备管理页明确面向承包商混合车队，覆盖设备定位/状态/历史、利用率、调度、预防性维护和工单、资产财务与成本跟踪，符合设备台账—运行状态—作业分配核心。", "slug": "construction-equipment-management", "source_urls": ["https://www.tenna.com/use-cases/construction-equipment-management/"]}], "name": "Tenna", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:32:16.031857+08:00", "kind": "documentation", "sha256": "3a55dcf2375f3f9b8e3bc5354f1a1015c0bd5a3e49b8c7b50f72842b0a95c021", "snapshot_path": "sources/3a55dcf2375f3f9b8e3bc5354f1a1015c0bd5a3e49b8c7b50f72842b0a95c021.txt", "url": "https://www.tenna.com/use-cases/construction-equipment-management/"}], "summary": "Tenna 是面向承包商的施工设备管理系统：统一登记自有和租赁设备，跟踪位置、状态、利用率与工时，支持工地调度、预防性维护、工单、检查以及资产财务与成本跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cobot','Cobot','{"homepage": "https://www.cobot.me/", "id": "commercial:cobot", "leaf_matches": [{"reason": "官网功能页明确列出会员与会员计划、工位/会议室预订、循环开票与付款、Office Rental Management、多地点和门禁集成，覆盖空间库存—会员—预订/分配—计费四个核心结构。", "slug": "coworking-flexible-workspace-management", "source_urls": ["https://www.cobot.me/en/features", "https://www.cobot.me/"]}], "name": "Cobot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:33:06.485721+08:00", "kind": "homepage", "sha256": "6cba123ac38c9184a00479684b2c385b38bbaa09861934ef0de898002897dc2c", "snapshot_path": "sources/6cba123ac38c9184a00479684b2c385b38bbaa09861934ef0de898002897dc2c.txt", "url": "https://www.cobot.me/"}, {"fetched_at": "2026-10-26T20:34:16.494125+08:00", "kind": "documentation", "sha256": "f876c2665e79f7e3f9e5ad208d49374004997713be13a7472de82c96ec7c75ca", "snapshot_path": "sources/f876c2665e79f7e3f9e5ad208d49374004997713be13a7472de82c96ec7c75ca.txt", "url": "https://www.cobot.me/en/features"}], "summary": "面向联合办公与灵活工作空间的运营管理软件，覆盖会员及会员计划、工位/办公室与会议室预订、循环计费与付款、办公出租、多地点管理和门禁集成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:officernd','OfficeRnD','{"homepage": "https://www.officernd.com/", "id": "commercial:officernd", "leaf_matches": [{"reason": "官网 coworking operations 页正文写明该平台用于统一管理 members、bookings、billing 和 inventory；Flex Operations 明确列出“Manage your members’ lifecycle”“Automate billing, invoicing, payments, and accounting”“Streamline bookings and reservations”“Manage coworking inventory”，并说明会员信息覆盖 memberships、contracts、bookings 与 credits，会员和访客可预订 desk、room 或其他资源，覆盖会员生命周期—预订/分配—计费与空间库存。", "slug": "coworking-flexible-workspace-management", "source_urls": ["https://www.officernd.com/coworking-software/coworking-operations/", "https://www.officernd.com/"]}], "name": "OfficeRnD", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:34:37.725170+08:00", "kind": "homepage", "sha256": "ed248ab3d940c56871bb2b4fe9f0d715f4cc5e5213ed0439866b799a6d76567a", "snapshot_path": "sources/ed248ab3d940c56871bb2b4fe9f0d715f4cc5e5213ed0439866b799a6d76567a.txt", "url": "https://www.officernd.com/"}, {"fetched_at": "2026-10-26T20:47:16.076111+08:00", "kind": "documentation", "sha256": "0c9c8e29d026b67c1c48d4dbb75e59a21a57e1bbca254e146ad732a94499d280", "snapshot_path": "sources/0c9c8e29d026b67c1c48d4dbb75e59a21a57e1bbca254e146ad732a94499d280.txt", "url": "https://www.officernd.com/coworking-software/coworking-operations/"}], "summary": "面向共享办公与灵活空间运营商的商业平台，管理会员、工位和会议室预订、计费、访客及日常空间运营。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:planon','Planon','{"homepage": "https://planonsoftware.com/", "id": "commercial:planon", "leaf_matches": [{"reason": "资产与维护管理模块页面列出反应式工单、预防性维护、资产全生命周期、图形化资源排程和移动执行；该模块与 Planon 的房地产、空间及工作场所管理同处一个集成 IWMS 平台，按定义承担套件中执行设施工作的 FMS 层。", "slug": "facility-management-system", "source_urls": ["https://planonsoftware.com/uk/software/iwms/asset-maintenance-management/", "https://planonsoftware.com/uk/software/iwms/"]}, {"reason": "官网明确将产品定位为 IoT-enabled IWMS，并在“Planon Integrated Workplace Management Solution contains”下同一平台列出房地产管理、空间与工作场所服务、资产与维护、能源与可持续性四个模块；租赁会计在导航中列为同厂商单独解决方案，未算入该 IWMS 模块清单。", "slug": "integrated-workplace-management-system-iwms", "source_urls": ["https://planonsoftware.com/uk/software/iwms/", "https://planonsoftware.com/uk/"]}], "name": "Planon", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:35:10.163208+08:00", "kind": "homepage", "sha256": "7d8fcb3db34571e6d410e687531453e5c58bf15f337e33bd6c1ae28ed3101efd", "snapshot_path": "sources/7d8fcb3db34571e6d410e687531453e5c58bf15f337e33bd6c1ae28ed3101efd.txt", "url": "https://planonsoftware.com/uk/"}, {"fetched_at": "2026-10-26T20:35:34.516992+08:00", "kind": "documentation", "sha256": "a0b890c270a4a0da14547b5fd68ce7d1191d9965f59bf524544eabc3b8939a12", "snapshot_path": "sources/a0b890c270a4a0da14547b5fd68ce7d1191d9965f59bf524544eabc3b8939a12.txt", "url": "https://planonsoftware.com/uk/software/iwms/"}, {"fetched_at": "2026-10-26T20:35:33.442097+08:00", "kind": "documentation", "sha256": "fa09fc7c8a098495148d8b50d65a7c5f3427ff9c42401bc8b9458d96c68c61f8", "snapshot_path": "sources/fa09fc7c8a098495148d8b50d65a7c5f3427ff9c42401bc8b9458d96c68c61f8.txt", "url": "https://planonsoftware.com/uk/software/iwms/asset-maintenance-management/"}], "summary": "企业级综合工作场所管理（IWMS）软件，在同一平台提供房地产、空间与工作场所、资产与维护、能源与可持续性四个模块；租赁会计为同厂商单独解决方案。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:archibus','Archibus by Eptura','{"homepage": "https://eptura.com/our-platform/archibus/", "id": "commercial:archibus", "leaf_matches": [{"reason": "产品页将 Archibus 定义为面向复杂环境的 IWMS，并在同一平台/应用下列出设施维护与资产管理、空间与占用、租约管理、资本项目和工作场所体验；租约与资产子页补充关键日期、工单与服务请求等记录。", "slug": "integrated-workplace-management-system-iwms", "source_urls": ["https://eptura.com/our-platform/archibus/", "https://eptura.com/our-platform/archibus/lease-management/", "https://eptura.com/our-platform/archibus/asset-management-bim/"]}, {"reason": "空间优化页明确展示基于楼层平面图/BIM 的实时占用与利用率、空间分配、自动工位分配、情景规划和搬迁管理，覆盖空间表示、占用状态与占用变更操作；页面以 space optimization 表述，未直接给出独立空间库存台账的措辞。", "slug": "space-occupancy-management", "source_urls": ["https://eptura.com/our-platform/archibus/space-optimization/", "https://eptura.com/our-platform/archibus/"]}], "name": "Archibus by Eptura", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:35:08.275667+08:00", "kind": "homepage", "sha256": "4d429afbd9632b68b0f2364dfb83a68301621e35dc9be7797c10ba75bed0eb40", "snapshot_path": "sources/4d429afbd9632b68b0f2364dfb83a68301621e35dc9be7797c10ba75bed0eb40.txt", "url": "https://eptura.com/our-platform/archibus/"}, {"fetched_at": "2026-10-26T20:35:55.489250+08:00", "kind": "documentation", "sha256": "4f3840f17df508dc66a067cf6f5e9fe72cdc623396d1cef11f0321cd3256f88c", "snapshot_path": "sources/4f3840f17df508dc66a067cf6f5e9fe72cdc623396d1cef11f0321cd3256f88c.txt", "url": "https://eptura.com/our-platform/archibus/space-optimization/"}, {"fetched_at": "2026-10-26T20:35:55.065258+08:00", "kind": "documentation", "sha256": "72d6f22f4c2c427d8b7cca1230e5bfa4979b46742b4ea637ccb69dac6c522297", "snapshot_path": "sources/72d6f22f4c2c427d8b7cca1230e5bfa4979b46742b4ea637ccb69dac6c522297.txt", "url": "https://eptura.com/our-platform/archibus/lease-management/"}, {"fetched_at": "2026-10-26T20:35:54.635921+08:00", "kind": "documentation", "sha256": "f1fd984360f4bc6455f19eb40733bd55135d8d0465a42ceb8678b468ae824653", "snapshot_path": "sources/f1fd984360f4bc6455f19eb40733bd55135d8d0465a42ceb8678b468ae824653.txt", "url": "https://eptura.com/our-platform/archibus/asset-management-bim/"}], "summary": "面向复杂企业环境的综合工作场所管理（IWMS）软件，统一设施维护与资产、空间与占用、租约管理、资本项目及工作场所体验。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:propertymeld','Property Meld','{"homepage": "https://propertymeld.com/", "id": "commercial:propertymeld", "leaf_matches": [{"reason": "官网与软件页定位为 property maintenance software，描述工单沟通与跟踪、工单排程、供应商协调、居民沟通和维修绩效数据，并面向单户、多户、HOA 与学生公寓等受管物业组合。", "slug": "property-maintenance-management", "source_urls": ["https://propertymeld.com/our-software/", "https://propertymeld.com/"]}], "name": "Property Meld", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:35:08.525332+08:00", "kind": "homepage", "sha256": "070f339ce307c9128e08e90c8b691a4c73038772109d139874f682c2beba0dd8", "snapshot_path": "sources/070f339ce307c9128e08e90c8b691a4c73038772109d139874f682c2beba0dd8.txt", "url": "https://propertymeld.com/"}, {"fetched_at": "2026-10-26T20:35:34.502095+08:00", "kind": "documentation", "sha256": "dfc657ba88486ec88fc2126bc76a1e49ae51f440613613348ccfd903a1853262", "snapshot_path": "sources/dfc657ba88486ec88fc2126bc76a1e49ae51f440613613348ccfd903a1853262.txt", "url": "https://propertymeld.com/our-software/"}], "summary": "面向物业管理公司的维护协调软件，接收和调度维修工单，协调居民、内部维修人员与供应商，并追踪沟通、进度和维修绩效数据。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cxalloy','CxAlloy','{"homepage": "https://www.cxalloy.com/", "id": "commercial:cxalloy", "leaf_matches": [{"reason": "官网正文明确描述资产层级、绑定资产的检查表/测试、问题指派与解决、报告/移交及现场离线执行，覆盖本类型设备登记→结构化验证→缺陷闭环→报告的核心。", "slug": "building-commissioning-platform", "source_urls": ["https://www.cxalloy.com/", "https://www.cxalloy.com/asset-management/"]}], "name": "CxAlloy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:40:54.327497+08:00", "kind": "homepage", "sha256": "092fd97393fd940de0b1ff4865d6642ba965687a528d93d48cf6dcaf94282ec6", "snapshot_path": "sources/092fd97393fd940de0b1ff4865d6642ba965687a528d93d48cf6dcaf94282ec6.txt", "url": "https://www.cxalloy.com/"}, {"fetched_at": "2026-10-26T20:41:04.323463+08:00", "kind": "documentation", "sha256": "a5c0da082ec8a826818feb70a70ae16085c1fb289d6656955b3518cb915f6f91", "snapshot_path": "sources/a5c0da082ec8a826818feb70a70ae16085c1fb289d6656955b3518cb915f6f91.txt", "url": "https://www.cxalloy.com/asset-management/"}], "summary": "面向建筑调试（Cx）团队的商业平台：以建筑/空间/系统/设备层级资产为记录主干，把检查表、功能测试、问题日志、报告与移交证据关联到资产，并支持现场离线执行和资产历史留存。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1269449119','Massing','{"deployment": ["自托管：docker compose --profile full up --build（web 8080、api 8000，含 PostgreSQL 与 MinIO）", "可选演示数据：docker compose --profile full --profile seed run --rm seed", "另有 Tauri 桌面版（单项目）"], "features": ["RFI 登记簿：draft→open→answered→closed/void，答复字段必填，answered 可重开，记录支持图纸/规范引用与分发", "施工日报：按项目/日期记录天气、人力与工种、已完成工作、到货、设备、延误、访客、安全观察和照片，支持 draft→submitted", "Punchlist：缺陷项含位置、责任方、截止日、照片；open→ready→verified，仅 GC 方验证，可拒绝退回", "通用模块引擎：CRUD、角色/公司门控工作流、评论、CSV/PDF、IFC 模型锚点、审计时间线", "Docker Compose 自托管，MIT 许可，无按席位许可"], "github_repository_id": 1269449119, "homepage": "https://github.com/ibuilder/massing", "id": "github:1269449119", "leaf_matches": [{"reason": "官方GitHub README正文明确为open, self-hosted, IFC-native的浏览器BIM创作平台；从空白/模板绘制并按GUID编辑墙、柱、板、门窗和MEP等真实IFC构件，模型生成平面、剖面、立面、表格及SVG/PDF/DXF图纸，直接覆盖类型化建筑模型与模型派生成果的核心。仅依此已保留的README建立本次关系，不依赖新增站点主机。", "slug": "bim-authoring", "source_urls": ["https://raw.githubusercontent.com/ibuilder/massing/main/README.md"]}, {"reason": "日报模块按项目和日期记录天气、人力、工作、到货、延误与照片，并有草稿/提交状态，是平台内完整的施工日记录子模块。", "slug": "daily-log-application", "source_urls": ["https://raw.githubusercontent.com/ibuilder/massing/main/README.md", "https://raw.githubusercontent.com/ibuilder/massing/main/docs/gc-portal.md", "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/daily_report/module.json"]}, {"reason": "Punchlist 模块以缺陷项为单位，含位置、责任方、截止日、照片与验证人，工作流把整改报完成（ready）与 GC 验证关闭（verified）分开，是完整子模块；模块只按角色限制验证，未强制验证人与责任方不同。", "slug": "punch-list-management", "source_urls": ["https://raw.githubusercontent.com/ibuilder/massing/main/README.md", "https://raw.githubusercontent.com/ibuilder/massing/main/docs/gc-portal.md", "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/punchlist/module.json"]}, {"reason": "RFI 模块具备项目编号、正式问题与文件引用、指定的 RFI 负责人/联系人、答复字段必填，以及 GC 接受关闭/重开的工作流，是平台内的完整 RFI 登记簿子模块。", "slug": "rfi-management", "source_urls": ["https://raw.githubusercontent.com/ibuilder/massing/main/README.md", "https://raw.githubusercontent.com/ibuilder/massing/main/docs/gc-portal.md", "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/rfi/module.json"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/ibuilder/massing/main/LICENSE", "license_review": {"rationale": "逐字读取仓库根 LICENSE，完整文本为标准 MIT 许可，含授权、版权声明与免责声明，未见额外限制，覆盖整个仓库。", "reviewer": "opencode-go/deepseek-v4.1-flash 独立采集会话", "scope": "repository", "source_url": "https://raw.githubusercontent.com/ibuilder/massing/main/LICENSE", "spdx_id": "MIT"}, "name": "Massing", "repository_url": "https://github.com/ibuilder/massing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-29T12:53:25.421428+08:00", "kind": "repository_metadata", "sha256": "9ce5e1f0a92f7a28163a262ab750a0df67324710562b97d916e6100966c1d190", "snapshot_path": "sources/9ce5e1f0a92f7a28163a262ab750a0df67324710562b97d916e6100966c1d190.txt", "url": "https://api.github.com/repos/ibuilder/massing"}, {"fetched_at": "2026-10-29T12:53:25.645032+08:00", "kind": "license", "sha256": "58cef4e7cdbc29ac51eeb3ad08ef51da3a7c6d2d082c8bdb59e51bd3a6a009a0", "snapshot_path": "sources/58cef4e7cdbc29ac51eeb3ad08ef51da3a7c6d2d082c8bdb59e51bd3a6a009a0.txt", "url": "https://api.github.com/repos/ibuilder/massing/license"}, {"fetched_at": "2026-10-26T20:40:37.003723+08:00", "kind": "repository_metadata", "sha256": "baf14b1e8311cdf6f8489656e3092d51171ffc82c090a6e0ab56db44714f8580", "snapshot_path": "sources/baf14b1e8311cdf6f8489656e3092d51171ffc82c090a6e0ab56db44714f8580.txt", "url": "https://github.com/ibuilder/massing"}, {"fetched_at": "2026-10-26T20:40:41.002472+08:00", "kind": "license", "sha256": "18a600129c34f9e9532de5009f4392b5bc514cf5d22f3681c90df934288c2607", "snapshot_path": "sources/18a600129c34f9e9532de5009f4392b5bc514cf5d22f3681c90df934288c2607.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/LICENSE"}, {"fetched_at": "2026-10-26T20:40:38.892439+08:00", "kind": "readme", "sha256": "dae45285485a16591713707f19cfa44af2f937a3340dd31495d7f352b7abf733", "snapshot_path": "sources/dae45285485a16591713707f19cfa44af2f937a3340dd31495d7f352b7abf733.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/README.md"}, {"fetched_at": "2026-10-26T20:40:47.436923+08:00", "kind": "documentation", "sha256": "42012f66a27879ecde8d88bb2581742f501510ad564d8adbb833af4d8141bff8", "snapshot_path": "sources/42012f66a27879ecde8d88bb2581742f501510ad564d8adbb833af4d8141bff8.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/docs/gc-portal.md"}, {"fetched_at": "2026-10-26T20:40:45.468655+08:00", "kind": "documentation", "sha256": "5825aec49f2ef50bbea09138591ba2e02d77e8dae082655ae0e28d2258f8ea2f", "snapshot_path": "sources/5825aec49f2ef50bbea09138591ba2e02d77e8dae082655ae0e28d2258f8ea2f.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/daily_report/module.json"}, {"fetched_at": "2026-10-26T20:40:43.982541+08:00", "kind": "documentation", "sha256": "cabff3dbe6fe5bdfb5dded07dc1ff5298f82ee163e4df383d19a085033e2935a", "snapshot_path": "sources/cabff3dbe6fe5bdfb5dded07dc1ff5298f82ee163e4df383d19a085033e2935a.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/punchlist/module.json"}, {"fetched_at": "2026-10-26T20:40:42.312310+08:00", "kind": "documentation", "sha256": "4c73f3ed209e81e726fbdbfdd02ce773b0ee27555bfd28300edf9880ee645766", "snapshot_path": "sources/4c73f3ed209e81e726fbdbfdd02ce773b0ee27555bfd28300edf9880ee645766.txt", "url": "https://raw.githubusercontent.com/ibuilder/massing/main/services/api/modules/rfi/module.json"}], "summary": "Massing 是 MIT 许可、可自托管的 IFC 原生 AEC 平台，内含通用记录模块与总承包门户；本单元采用其 RFI、施工日报和 Punchlist 三个有独立字段与角色门控工作流的完整登记簿模块。", "technology_stack": ["FastAPI", "React/Vite", "PostgreSQL", "MinIO/S3", "That Open / web-ifc / IfcOpenShell", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hellopackage','HelloPackage','{"homepage": "https://hellopackage.com/", "id": "commercial:hellopackage", "leaf_matches": [{"reason": "官网与 FAQ 正文描述司机扫码登记包裹、包裹与住户档案/物业管理系统匹配（含未匹配状态与昵称/别名处理）、即时通知、个人取件码释放的完整包裹房流程，属于收件方静置状态的到件记录与监护释放，核心匹配。", "slug": "package-mailroom-management", "source_urls": ["https://hellopackage.com/", "https://hellopackage.com/what-is-hellopackage/", "https://hellopackage.com/faqs/"]}], "name": "HelloPackage", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:41:58.069071+08:00", "kind": "homepage", "sha256": "ef34d851235aee9ece46f09f9a880f103c8dea33e013c72d7b873b969501ab4c", "snapshot_path": "sources/ef34d851235aee9ece46f09f9a880f103c8dea33e013c72d7b873b969501ab4c.txt", "url": "https://hellopackage.com/"}, {"fetched_at": "2026-10-26T20:44:09.906662+08:00", "kind": "documentation", "sha256": "bf60f129e1fb81ce1de514a453dcefdfd620b18d023a2e1c1809db036ea1f116", "snapshot_path": "sources/bf60f129e1fb81ce1de514a453dcefdfd620b18d023a2e1c1809db036ea1f116.txt", "url": "https://hellopackage.com/what-is-hellopackage/"}, {"fetched_at": "2026-10-26T20:44:12.932517+08:00", "kind": "documentation", "sha256": "f6c0c3cea48870668ff3f44ce3e9d292c1a4de5120cddb0fe0b2a64021fdb08d", "snapshot_path": "sources/f6c0c3cea48870668ff3f44ce3e9d292c1a4de5120cddb0fe0b2a64021fdb08d.txt", "url": "https://hellopackage.com/faqs/"}], "summary": "面向多户住宅/学生公寓等物业的包裹房管理平台：司机到店扫码登记包裹，系统把包裹与住户档案（可含别名）匹配并即时发送短信/邮件/App 通知，住户用个人取件码 24/7 取件；官网称从投递到取件全流程由平台记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:visual-lease','Visual Lease','{"homepage": "https://visuallease.com/", "id": "commercial:visual-lease", "leaf_matches": [{"reason": "官方租约管理页说明集中管理租约数据库，拆分复杂租约以理解义务、选项、现金流和关键日期；支持跟踪租约条款、主租约/转租、续约选项和关键日期，并对续约、到期、租金上涨提供提醒。对应租约记录、条款派生义务与期限日期生命周期三项核心。", "slug": "lease-administration", "source_urls": ["https://visuallease.com/solutions/lease-management-software/", "https://visuallease.com/"]}], "name": "Visual Lease", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:42:02.769990+08:00", "kind": "documentation", "sha256": "6818347f1445b4171283e8032cc0a4f8e6ff8aa555900b6da0afb09d551225db", "snapshot_path": "sources/6818347f1445b4171283e8032cc0a4f8e6ff8aa555900b6da0afb09d551225db.txt", "url": "https://visuallease.com/solutions/lease-management-software/"}, {"fetched_at": "2026-10-26T20:42:07.098946+08:00", "kind": "homepage", "sha256": "d1e2362a43bfab15f37b6ea0ce6f0dd422494b2819e9d9da799a2ae4ababc154", "snapshot_path": "sources/d1e2362a43bfab15f37b6ea0ce6f0dd422494b2819e9d9da799a2ae4ababc154.txt", "url": "https://visuallease.com/"}], "summary": "商业租赁管理与租赁会计平台；集中维护租约数据库和抽象条款，跟踪财务义务、续约/终止选项与关键日期，并提供期限提醒。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1181094397','InsulaCRM','{"deployment": ["Docker Compose（nginx、MySQL 8.0、Redis）", "Laravel 自托管 Web 应用"], "features": ["线索/客户记录、来源与经纪人归属", "房产记录与客户/交易关联", "经纪模式管道：挂牌协议→活跃挂牌→带看→成交", "房源、带看与开放日", "活动/任务历史与角色隔离", "多租户团队与权限"], "github_repository_id": 1181094397, "homepage": "https://github.com/InsulaCRM/InsulaCRM", "id": "github:1181094397", "leaf_matches": [{"reason": "README 说明这是自托管多租户房地产 CRM，提供经纪模式：挂牌协议→活跃挂牌→带看→成交管道，含房源、带看、开放日与挂牌/买方经纪人角色；线索按经纪人归属并按角色隔离，活动历史持续累积，客户与房产/交易关联。仓库元数据 API 核对 id=1181094397 与 full_name，许可证 API 核对 SPDX MIT 及完整文本。", "slug": "real-estate-brokerage-crm", "source_urls": ["https://api.github.com/repos/InsulaCRM/InsulaCRM", "https://api.github.com/repos/InsulaCRM/InsulaCRM/license", "https://raw.githubusercontent.com/InsulaCRM/InsulaCRM/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/InsulaCRM/InsulaCRM/license", "name": "InsulaCRM", "repository_url": "https://github.com/InsulaCRM/InsulaCRM", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:42:00.984845+08:00", "kind": "repository_metadata", "sha256": "f2724329dcb34bf0fef834b0fa640404e0278678dbcd438d23c7ef673fdaf2c7", "snapshot_path": "sources/f2724329dcb34bf0fef834b0fa640404e0278678dbcd438d23c7ef673fdaf2c7.txt", "url": "https://api.github.com/repos/InsulaCRM/InsulaCRM"}, {"fetched_at": "2026-10-26T20:42:02.580500+08:00", "kind": "license", "sha256": "462c14ed511e3f76e4dcd70c37437ced66b7e5082f028b01bfac541178addaaa", "snapshot_path": "sources/462c14ed511e3f76e4dcd70c37437ced66b7e5082f028b01bfac541178addaaa.txt", "url": "https://api.github.com/repos/InsulaCRM/InsulaCRM/license"}, {"fetched_at": "2026-10-26T20:42:05.898903+08:00", "kind": "readme", "sha256": "a3cc4190576639714e9b255ff364883c954fd0aa7fd6ea89435e9e1cb193afb7", "snapshot_path": "sources/a3cc4190576639714e9b255ff364883c954fd0aa7fd6ea89435e9e1cb193afb7.txt", "url": "https://raw.githubusercontent.com/InsulaCRM/InsulaCRM/main/README.md"}], "summary": "开源自托管的房地产经纪/批发 CRM，含客户与房产记录、经纪挂牌-带看-成交管道、经纪人归属和团队权限。", "technology_stack": ["Laravel 12", "PHP 8.2", "MySQL 8.0", "Redis", "Tabler", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:argus-developer','ARGUS Developer','{"homepage": "https://www.altusgroup.com", "id": "commercial:argus-developer", "leaf_matches": [{"reason": "官方产品页称 ARGUS Developer 是端到端房地产开发管理平台，从初始 pro forma 到交付；功能包括土地残值、开发情景比较、风险敏感性、现金流预测并按实际更新、项目融资、开发监控与透明报告。对应开发项目记录、分阶段生命周期和项目资金结构；未主张页面未展示的审批或文档能力。", "slug": "real-estate-development-management", "source_urls": ["https://www.altusgroup.com/solutions/argus-developer/"]}], "name": "ARGUS Developer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:42:04.175351+08:00", "kind": "documentation", "sha256": "f19808045e2f5e3fbfcf1ccbe5cc031cec8ded9dc69d9c82522898252d59c3a7", "snapshot_path": "sources/f19808045e2f5e3fbfcf1ccbe5cc031cec8ded9dc69d9c82522898252d59c3a7.txt", "url": "https://www.altusgroup.com/solutions/argus-developer/"}], "summary": "商业房地产开发评估与全周期管理软件；从土地可行性、pro forma、现金流与预算，到项目融资和交付监控。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dealpath','Dealpath','{"homepage": "https://www.dealpath.com", "id": "commercial:dealpath", "leaf_matches": [{"reason": "官方平台页说明其面向机构 CRE 投资团队，集中交易数据，提供实时管道管理、Excel 承销执行与审计轨迹、组合洞察及持有/出售/再融资决策，并称覆盖投资过程各阶段。对应投资记录、生命周期和承销/组合价值回报结构；不主张未展示的基金 waterfall 或投资者账户能力。", "slug": "real-estate-investment-management", "source_urls": ["https://www.dealpath.com/platform/"]}], "name": "Dealpath", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:41:21.289226+08:00", "kind": "documentation", "sha256": "32fc664406bad7393f52d92902746627b26dfd45756a9b3dcf28fc1bee4875e6", "snapshot_path": "sources/32fc664406bad7393f52d92902746627b26dfd45756a9b3dcf28fc1bee4875e6.txt", "url": "https://www.dealpath.com/platform/"}], "summary": "面向机构房地产投资团队的交易管理与组合平台；集中交易/资产记录，覆盖管道、承销执行、审计轨迹及持有/出售/再融资决策。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:skyslope','SkySlope','{"homepage": "https://skyslope.com/", "id": "commercial:skyslope", "leaf_matches": [{"reason": "首页正文说明其管理从合同到交割的房地产交易，提供交易表单、DigiSign 电子签名、合规检查清单与经纪后台，符合交易文件与文档执行状态的核心。", "slug": "real-estate-transaction-management", "source_urls": ["https://skyslope.com/"]}], "name": "SkySlope", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:50:11+08:00", "kind": "homepage", "sha256": "615732d4c99750002eabc3bdf7caf7798aecf96705d631fe2f963c5ad58a014b", "snapshot_path": "sources/615732d4c99750002eabc3bdf7caf7798aecf96705d631fe2f963c5ad58a014b.txt", "url": "https://skyslope.com/"}], "summary": "面向房地产经纪公司的交易管理 SaaS，覆盖从合同到交割的流程、交易表单、电子签名与合规审核。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:applied-autonomy','Applied Autonomy xFlow','{"homepage": "https://www.appliedautonomy.no/", "id": "commercial:applied-autonomy", "leaf_matches": [{"reason": "官方首页快照的 Google Sites body 正文（非仅 meta）明确 xFlow 为已商业发布的 fleet management SaaS，支持与车型/自动驾驶方案无关的混合车队接入、实时监控（持续遥测、车载视频、分级告警）、按角色远程操作员协助（启停/暂停自动驾驶、批准或指挥驾驶动作、开关车门）、历史报表/KPI 与外部系统接口；官方方案页补充不同厂商车辆可接入并由运营中心监控支持，新闻页说明其作为数字控制塔由一名远程操作员同时监督多辆车，并支持 Stavanger 常规线路无安全员运营。按可核实内容收窄为车队接入与运营监控、监督干预闭环，不声称已演示车辆登记状态字段或任务调度界面。", "slug": "autonomous-fleet-management", "source_urls": ["https://www.appliedautonomy.no/", "https://www.appliedautonomy.no/our-solution", "https://www.appliedautonomy.no/portfolio/press-release-no-driver-behind-the-wheel"]}], "name": "Applied Autonomy xFlow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:50:04+08:00", "kind": "homepage", "sha256": "a020cdef777a18438abc41b3a0cf5f33e621329ab7469c42a61d4f656508106c", "snapshot_path": "sources/a020cdef777a18438abc41b3a0cf5f33e621329ab7469c42a61d4f656508106c.txt", "url": "https://www.appliedautonomy.no/"}, {"fetched_at": "2026-10-26T20:59:22.440349+08:00", "kind": "documentation", "sha256": "8c2d20dd723c9fa066323203fa606f6c596d43359e6980567883688c2709bda3", "snapshot_path": "sources/8c2d20dd723c9fa066323203fa606f6c596d43359e6980567883688c2709bda3.txt", "url": "https://www.appliedautonomy.no/our-solution"}, {"fetched_at": "2026-10-26T20:59:41.546497+08:00", "kind": "documentation", "sha256": "7873a40bed03d75910857558124f7dc7cee120fa20c21d7e16c16c36e8010fb0", "snapshot_path": "sources/7873a40bed03d75910857558124f7dc7cee120fa20c21d7e16c16c36e8010fb0.txt", "url": "https://www.appliedautonomy.no/portfolio/press-release-no-driver-behind-the-wheel"}], "summary": "面向自动驾驶客运与物流运营方的车队管理 SaaS，提供混合车队实时监控、远程操作员协助、运营报表与外部系统接口。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dgoffice','DGOffice','{"homepage": "https://dgm-sdg.com/", "id": "commercial:dgoffice", "leaf_matches": [{"reason": "官方服务页正文说明 DGOffice 覆盖 ICAO/IATA、IMDG、ADR、49CFR 等运输法规，可创建危险货物文件与标签、共享数据并提供危险货物分类数据维护，符合分类、合规文件与承运交接核心。", "slug": "dangerous-goods-transportation-management", "source_urls": ["https://dgm-sdg.com/services/"]}], "name": "DGOffice", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:52:48+08:00", "kind": "documentation", "sha256": "d074ac58be26b031c8b9f949a09af6dd44a9b7dd1347fedf5bda45c6c88390d9", "snapshot_path": "sources/d074ac58be26b031c8b9f949a09af6dd44a9b7dd1347fedf5bda45c6c88390d9.txt", "url": "https://dgm-sdg.com/services/"}], "summary": "危险货物运输与化学品管理的在线合规软件，按 IATA、IMDG、ADR 等法规生成运输文件与标签并支持危险货物数据交换。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tenstreet','Tenstreet','{"homepage": "https://www.tenstreet.com/", "id": "commercial:tenstreet", "leaf_matches": [{"reason": "官方首页与 DQF 页面正文说明其维护驾驶员资格文件、年度 MVR 报告和数字化司机档案，并以安全/合规中心持续更新记录，符合驾驶员证据记录与合规维护核心。", "slug": "driver-management", "source_urls": ["https://www.tenstreet.com/", "https://www.tenstreet.com/software/dqf/"]}], "name": "Tenstreet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:51:30+08:00", "kind": "homepage", "sha256": "40ad42afa50fb2e5dc08207e177e0d1ef0a555bc208cba861666b84d83917bd8", "snapshot_path": "sources/40ad42afa50fb2e5dc08207e177e0d1ef0a555bc208cba861666b84d83917bd8.txt", "url": "https://www.tenstreet.com/"}, {"fetched_at": "2026-10-26T20:53:27+08:00", "kind": "documentation", "sha256": "e5f8668e9e74750cf7321b0c34f62c2d4a8ad50a37ae04e8c5dfcb5428b92061", "snapshot_path": "sources/e5f8668e9e74750cf7321b0c34f62c2d4a8ad50a37ae04e8c5dfcb5428b92061.txt", "url": "https://www.tenstreet.com/software/dqf/"}], "summary": "面向运输企业的驾驶员全生命周期管理平台，提供数字化驾驶员资格文件、历史核查与合规维护。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:motive','Motive','{"homepage": "https://gomotive.com/", "id": "commercial:motive", "leaf_matches": [{"reason": "官方 ELD 页面正文说明其提供 HOS 倒计时时钟、驾驶员日志与值班状态、未识别行程匹配、违规与周期趋势、美加 ELD 认证及路边检查支持，符合 ELD/HOS 平台核心。", "slug": "electronic-logging-device-hos-platform", "source_urls": ["https://gomotive.com/", "https://gomotive.com/products/fleet-compliance/eld-compliance/"]}], "name": "Motive", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:49:56+08:00", "kind": "homepage", "sha256": "9efb5e63e1feae0a05396fd14dc659f2f130e35ce44a89b539c8f643d35f3a45", "snapshot_path": "sources/9efb5e63e1feae0a05396fd14dc659f2f130e35ce44a89b539c8f643d35f3a45.txt", "url": "https://gomotive.com/"}, {"fetched_at": "2026-10-26T20:51:54+08:00", "kind": "documentation", "sha256": "de1d385832488b66b98af5a87bf14a3563d7b3a46cfd394f60935fff02e7c026", "snapshot_path": "sources/de1d385832488b66b98af5a87bf14a3563d7b3a46cfd394f60935fff02e7c026.txt", "url": "https://gomotive.com/products/fleet-compliance/eld-compliance/"}], "summary": "面向商用车队的 ELD/HOS 合规平台，提供车辆采集的驾驶员日志、HOS 倒计时与违规监控并支持路边检查。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:chargepilot','The Mobility House ChargePilot','{"homepage": "https://www.mobilityhouse.com/int_en/chargepilot", "id": "commercial:chargepilot", "leaf_matches": [{"reason": "官方产品页说明车队模块可按排程优先充电，优先级依据出发时间与 SoC，门户可启停单个充电点；本地控制器按场地功率上限执行负载管理，覆盖车辆任务导向的充电计划与直接控制。", "slug": "ev-fleet-charging-management", "source_urls": ["https://www.mobilityhouse.com/int_en/chargepilot", "https://www.mobilityhouse.com/usa_en/industries/commercial-fleets"]}], "name": "The Mobility House ChargePilot", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:53:05.454035+08:00", "kind": "documentation", "sha256": "a4f71468c287db89fee5d8332f0a0d9c2999fdbfe34a05766642e69ae61a17a2", "snapshot_path": "sources/a4f71468c287db89fee5d8332f0a0d9c2999fdbfe34a05766642e69ae61a17a2.txt", "url": "https://www.mobilityhouse.com/int_en/chargepilot"}, {"fetched_at": "2026-10-26T20:53:08.160845+08:00", "kind": "homepage", "sha256": "45ad36289ca149d8f7ec3d3cced52d0612f49bb72aba80745c6ccf7fb4d3c923", "snapshot_path": "sources/45ad36289ca149d8f7ec3d3cced52d0612f49bb72aba80745c6ccf7fb4d3c923.txt", "url": "https://www.mobilityhouse.com/usa_en/industries/commercial-fleets"}], "summary": "面向商业与公交电动化车队的智能充电管理产品：按车辆出发时间与 SoC 排定充电优先级，通过 Web 门户启停充电点，并由本地控制器执行场地负载管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:540371158','Fleetbase','{"deployment": ["README 提供 Docker Compose 自托管方式，要求 Docker Compose v2、Git、Node.js 18+ 和至少 4GB Docker 内存", "官方也提供托管云版本 Fleetbase Cloud"], "features": ["Fleet-Ops 维护车辆、司机和订单记录，支持分配、实时跟踪与路线优化", "维护（maintenance）、地理围栏、服务区域和可配置工作流", "REST API、WebSocket 与 webhook，支持外部系统集成"], "github_repository_id": 540371158, "homepage": "https://fleetbase.io/", "id": "github:540371158", "leaf_matches": [{"reason": "Fleet-Ops 订单文档明确订单以取件/送达地点、客户、货件实体、司机与车辆、条码/QR 追踪号及状态生命周期为核心，订单可分配/改派司机并 dispatch 到 Navigator 司机端；POD 文档明确司机在交付点采集签名、照片、条码/QR 扫码或短信验证码，订单详情保留活动时间线及 POD 文件；Service Rates 文档按里程、固定、按点、多区、包裹等费率计价并生成 Service Quote，Ledger 文档说明订单加入 PurchaseRate 后自动生成草稿发票。四项核心——快递订单、分派给自营司机、带现场交付证明的执行闭环、按费率开票——均有官方正文证据。README 将 Courier & Parcel 列为适用行业；官方许可页明确核心 API、Console、Fleet-Ops 等官方扩展与移动端整体采用 AGPL-3.0，可自托管，故成立。", "slug": "courier-management-platform", "source_urls": ["https://raw.githubusercontent.com/fleetbase/fleetbase/main/README.md", "https://fleetbase.io/docs/community/licensing", "https://fleetbase.io/docs/fleet-ops/operations/orders/overview", "https://fleetbase.io/docs/fleet-ops/operations/orders/proof-of-delivery", "https://fleetbase.io/docs/fleet-ops/operations/service-rates/overview", "https://fleetbase.io/docs/ledger"]}, {"reason": "Fleet-Ops 订单看板与实时地图同时呈现未分配订单、司机和车辆；调度员可手动或批量分配订单，司机端接收派单并推进活动流，覆盖调度管理的队列、资源花名册、分配动作与实时全景。", "slug": "dispatch-management", "source_urls": ["https://api.github.com/repos/fleetbase/fleetbase", "https://raw.githubusercontent.com/fleetbase/fleetbase/main/README.md"]}, {"reason": "README 的 Fleet-Ops 模块明确包含车辆、司机、实时跟踪、可配置工作流和维护；车辆与司机作为记录被调度，维护和运营活动围绕车辆展开，构成可监控、可处置的车队管理完整子模块。", "slug": "fleet-management-system", "source_urls": ["https://raw.githubusercontent.com/fleetbase/fleetbase/main/README.md"]}, {"reason": "README 行业场景明确列出即时配送（instant dispatch、live customer tracking、automated notifications），Storefront 面向 on-demand business 并以 Fleet-Ops 配送，Navigator 采集送达证明；可支撑按需请求→即时派单→请求者追踪→送达证明。", "slug": "on-demand-delivery-platform", "source_urls": ["https://api.github.com/repos/fleetbase/fleetbase", "https://raw.githubusercontent.com/fleetbase/fleetbase/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/fleetbase/fleetbase/license", "name": "Fleetbase", "repository_url": "https://github.com/fleetbase/fleetbase", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-29T12:56:08.007513+08:00", "kind": "repository_metadata", "sha256": "0c30c7341e0bdbd648df0360855b10051f77c91c84cdb9931501d2e8c2cbfcd8", "snapshot_path": "sources/0c30c7341e0bdbd648df0360855b10051f77c91c84cdb9931501d2e8c2cbfcd8.txt", "url": "https://api.github.com/repos/fleetbase/fleetbase"}, {"fetched_at": "2026-10-26T20:52:02.766673+08:00", "kind": "repository_metadata", "sha256": "1afb630ad7fe4738e6f1d4413db1dab0b330e70864b60cef221f308855ed9186", "snapshot_path": "sources/1afb630ad7fe4738e6f1d4413db1dab0b330e70864b60cef221f308855ed9186.txt", "url": "https://api.github.com/repos/fleetbase/fleetbase"}, {"fetched_at": "2026-10-26T21:02:26.409476+08:00", "kind": "repository_metadata", "sha256": "94f48dc951dcde703e0d4e9809056ece864a01b18bd6ed449566a5ecff42abeb", "snapshot_path": "sources/94f48dc951dcde703e0d4e9809056ece864a01b18bd6ed449566a5ecff42abeb.txt", "url": "https://api.github.com/repos/fleetbase/fleetbase"}, {"fetched_at": "2026-10-26T20:52:07.346379+08:00", "kind": "license", "sha256": "f25f3e8369f8fa5e1d671b795e7dcc23bfd83058124c1c0b4e3b7f75c72b8fc7", "snapshot_path": "sources/f25f3e8369f8fa5e1d671b795e7dcc23bfd83058124c1c0b4e3b7f75c72b8fc7.txt", "url": "https://api.github.com/repos/fleetbase/fleetbase/license"}, {"fetched_at": "2026-10-26T20:52:25.313599+08:00", "kind": "homepage", "sha256": "7317a20129b413f0becddb32ffbdbe0b1ef2dc58fbfa8f61bba6de71f62eb8ad", "snapshot_path": "sources/7317a20129b413f0becddb32ffbdbe0b1ef2dc58fbfa8f61bba6de71f62eb8ad.txt", "url": "https://fleetbase.io/"}, {"fetched_at": "2026-10-29T12:59:22.359490+08:00", "kind": "documentation", "sha256": "b6d2813437ea2b4eb3cbd2a3fa8eb89e16a5b62ee47129e0aed4c2c496cc98ee", "snapshot_path": "sources/b6d2813437ea2b4eb3cbd2a3fa8eb89e16a5b62ee47129e0aed4c2c496cc98ee.txt", "url": "https://fleetbase.io/docs/community/licensing"}, {"fetched_at": "2026-10-29T12:56:18.566498+08:00", "kind": "documentation", "sha256": "735987a3666871f273039f98badf1dd6a0f370a43003f8f088dc48b62bcf2eb1", "snapshot_path": "sources/735987a3666871f273039f98badf1dd6a0f370a43003f8f088dc48b62bcf2eb1.txt", "url": "https://fleetbase.io/docs/fleet-ops/operations/orders/overview"}, {"fetched_at": "2026-10-29T12:56:18.291553+08:00", "kind": "documentation", "sha256": "eeb97636096761c4fe7e19724220ed587a6f11a97b36b0a0b9bf67dd071b1f54", "snapshot_path": "sources/eeb97636096761c4fe7e19724220ed587a6f11a97b36b0a0b9bf67dd071b1f54.txt", "url": "https://fleetbase.io/docs/fleet-ops/operations/orders/proof-of-delivery"}, {"fetched_at": "2026-10-29T12:56:47.039440+08:00", "kind": "documentation", "sha256": "a8fd0f2a16918d9e34ee0eb77fd10fc20019f6ca3242bb68791f64c778c26bb9", "snapshot_path": "sources/a8fd0f2a16918d9e34ee0eb77fd10fc20019f6ca3242bb68791f64c778c26bb9.txt", "url": "https://fleetbase.io/docs/fleet-ops/operations/service-rates/overview"}, {"fetched_at": "2026-10-29T12:56:33.464053+08:00", "kind": "documentation", "sha256": "a161675005597250d22492991d867cda609716177b0cdc27b9ca817ff7e4ced5", "snapshot_path": "sources/a161675005597250d22492991d867cda609716177b0cdc27b9ca817ff7e4ced5.txt", "url": "https://fleetbase.io/docs/ledger"}, {"fetched_at": "2026-10-26T20:52:17.586504+08:00", "kind": "readme", "sha256": "f90c307471ecb43b2cf4f58f82bd0f8ef4f6c6a119ba92d471f3cad0f86bcf99", "snapshot_path": "sources/f90c307471ecb43b2cf4f58f82bd0f8ef4f6c6a119ba92d471f3cad0f86bcf99.txt", "url": "https://raw.githubusercontent.com/fleetbase/fleetbase/main/README.md"}], "summary": "AGPL-3.0 的开源物流运营平台；Fleet-Ops 完整子模块提供车辆/司机记录、调度、实时跟踪、路线优化与维护管理，可 Docker 自托管或使用云版。", "technology_stack": ["PHP / FrankenPHP 后端（README 说明发布二进制为静态 FrankenPHP 构建）", "MySQL 与 Redis", "React Native 移动应用（Navigator App）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1060011355','Open TMS','{"deployment": ["README 提供 Docker Compose 自托管，以及 DigitalOcean、Azure、GCP、AWS 部署方式"], "features": ["Issue 作为持久记录，支持创建、分配、升级、延后、解决、关闭和重新打开", "确定性 Issue Engine 从货运异常信号自动建单，同货运同类型升级而非重复", "Triage Centre 提供看板/列表、分面检索、SLA 违约检测、MTTR 与关闭报告"], "github_repository_id": 1060011355, "homepage": "https://www.opentms.co.uk/", "id": "github:1060011355", "leaf_matches": [{"reason": "README 明确 Issue 具有创建、分配、升级、延后、解决、关闭和重新打开的完整生命周期，并绑定货运；确定性 Issue Engine 自动从异常信号建单，Triage Centre 提供队列、SLA 与解决闭包，构成异常管理完整子模块。", "slug": "transportation-exception-management", "source_urls": ["https://raw.githubusercontent.com/DominicFinn/open_tms/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/DominicFinn/open_tms/license", "name": "Open TMS", "repository_url": "https://github.com/DominicFinn/open_tms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:52:49.267574+08:00", "kind": "repository_metadata", "sha256": "7937614d7910ba26638fc805b6fbbee6e1500dfbbc17c1100e0c8b46aa7b90fc", "snapshot_path": "sources/7937614d7910ba26638fc805b6fbbee6e1500dfbbc17c1100e0c8b46aa7b90fc.txt", "url": "https://api.github.com/repos/DominicFinn/open_tms"}, {"fetched_at": "2026-10-26T20:52:51.779884+08:00", "kind": "license", "sha256": "97e970c4d793247615f6f58d381177ccde8615920af1d5fa033f4d436f420196", "snapshot_path": "sources/97e970c4d793247615f6f58d381177ccde8615920af1d5fa033f4d436f420196.txt", "url": "https://api.github.com/repos/DominicFinn/open_tms/license"}, {"fetched_at": "2026-10-26T20:53:04.187351+08:00", "kind": "readme", "sha256": "951c4d2a5a6d0282c214e267ec6f2c0637b8179aee0592a66c24994ea4380787", "snapshot_path": "sources/951c4d2a5a6d0282c214e267ec6f2c0637b8179aee0592a66c24994ea4380787.txt", "url": "https://raw.githubusercontent.com/DominicFinn/open_tms/main/README.md"}, {"fetched_at": "2026-10-26T20:54:18.034025+08:00", "kind": "homepage", "sha256": "19a59fb659826b1f89bdc0ab11913a7b426e04b671f13c2caf5ca46f9ae7d58d", "snapshot_path": "sources/19a59fb659826b1f89bdc0ab11913a7b426e04b671f13c2caf5ca46f9ae7d58d.txt", "url": "https://www.opentms.co.uk/"}], "summary": "MIT 许可的开源 TMS；其 Issue/Triage Centre 子模块把运输异常作为持久 Issue 记录，支持自动建单、分诊、升级、解决、关闭与重新打开。", "technology_stack": ["TypeScript 前后端", "PostgreSQL（Prisma）", "React 前端与 pg-boss 事件队列"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:trenova','Trenova','{"homepage": "https://trenova.app/", "id": "commercial:trenova", "leaf_matches": [{"reason": "官方定位为资产型承运商 TMS，正文覆盖 tender 到 cash 的单一 shipment 记录、dispatch、rating、billing、settlement & driver pay 与总账，符合自有运力承运与客户计费/司机结算双向资金核心。", "slug": "trucking-management-system", "source_urls": ["https://trenova.app/", "https://trenova.app/tms-software", "https://trenova.app/features/"]}], "name": "Trenova", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:53:04.480575+08:00", "kind": "homepage", "sha256": "c76f363d8655d999371281ee1c76ccfc37c5c5fdd4b05a9d45999e2b48d970aa", "snapshot_path": "sources/c76f363d8655d999371281ee1c76ccfc37c5c5fdd4b05a9d45999e2b48d970aa.txt", "url": "https://trenova.app/"}, {"fetched_at": "2026-10-26T20:53:06.558518+08:00", "kind": "documentation", "sha256": "d096e83ffaedacde1800e82854e7bff137f2a75a48d013872a9351f1edd9efff", "snapshot_path": "sources/d096e83ffaedacde1800e82854e7bff137f2a75a48d013872a9351f1edd9efff.txt", "url": "https://trenova.app/tms-software"}, {"fetched_at": "2026-10-26T20:57:05.345673+08:00", "kind": "documentation", "sha256": "5b08485aebd318bc501b67213f2e92813ce96db4350ba5ba9913f95f2b7396a7", "snapshot_path": "sources/5b08485aebd318bc501b67213f2e92813ce96db4350ba5ba9913f95f2b7396a7.txt", "url": "https://trenova.app/features/"}], "summary": "面向资产型卡车承运商/自有车队的 carrier TMS，覆盖调度、评级、计费、司机结算、总账与合规；代码以 FSL-1.1 源可见方式发布，非 OSI 开源。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:4038949','Traccar','{"deployment": ["README 提供 Docker Compose + MySQL 的生产级自托管方式", "官方也提供托管服务"], "features": ["实时 GPS 跟踪、地理围栏、报警与通知", "行程/历史和汇总报告、驾驶员行为监控", "账户与设备管理、邮件和 SMS 支持"], "github_repository_id": 4038949, "homepage": "https://www.traccar.org/", "id": "github:4038949", "leaf_matches": [{"reason": "README 与官网说明设备自动上报位置和状态，平台提供实时 GPS 跟踪、行程/历史与汇总报告、地理围栏、报警、设备管理和 REST API，覆盖联网车辆、自动采集、集中实时画面与历史、组织侧暴露四项核心。", "slug": "vehicle-telematics-platform", "source_urls": ["https://raw.githubusercontent.com/traccar/traccar/master/README.md", "https://www.traccar.org/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/traccar/traccar/license", "name": "Traccar", "repository_url": "https://github.com/traccar/traccar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:52:03.296954+08:00", "kind": "repository_metadata", "sha256": "9a845e9251766ac82a133baec351f83541d3597620bebb5e535e1eedb42b6ed0", "snapshot_path": "sources/9a845e9251766ac82a133baec351f83541d3597620bebb5e535e1eedb42b6ed0.txt", "url": "https://api.github.com/repos/traccar/traccar"}, {"fetched_at": "2026-10-26T20:52:05.132155+08:00", "kind": "license", "sha256": "b7e9904b03910db30a744d56d2f3617554aeb9307179a2a143349664f7d1cbe9", "snapshot_path": "sources/b7e9904b03910db30a744d56d2f3617554aeb9307179a2a143349664f7d1cbe9.txt", "url": "https://api.github.com/repos/traccar/traccar/license"}, {"fetched_at": "2026-10-26T20:52:17.212079+08:00", "kind": "readme", "sha256": "1596e06c59c2054f7d9a25f7e2eca6264216159fd1b359fee03397ee5bbe5d7a", "snapshot_path": "sources/1596e06c59c2054f7d9a25f7e2eca6264216159fd1b359fee03397ee5bbe5d7a.txt", "url": "https://raw.githubusercontent.com/traccar/traccar/master/README.md"}, {"fetched_at": "2026-10-26T20:52:19.029064+08:00", "kind": "homepage", "sha256": "3cbe5b16a3e6402a5c977532e78b48bfdbadf95b3f4bd99c7206cc49fd69f3b7", "snapshot_path": "sources/3cbe5b16a3e6402a5c977532e78b48bfdbadf95b3f4bd99c7206cc49fd69f3b7.txt", "url": "https://www.traccar.org/"}], "summary": "Apache-2.0 的开源 GPS 车辆跟踪/远程信息处理平台；支持 200+ 设备协议，提供实时地图、历史行程、地理围栏、报警、账户设备和 REST API。", "technology_stack": ["Java 后端（仓库说明为 Java-based back-end server）", "MySQL 等主要 SQL 数据库", "REST API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
