INSERT INTO "application" VALUES('github:1153079753','Simple Aircraft Manager','{"deployment": ["Python/Django 自托管", "PostgreSQL（生产示例含 OpenShift/Kubernetes）", "可选 OIDC 单点登录"], "features": ["飞机与机队登记（飞行小时、状态）", "部件寿命/TBO 与服务间隔跟踪", "适航状态（AD、故障、检查、部件健康）", "检查要求与到期/逾期记录", "维修日志与文件归档", "机主/飞行员角色权限与可选 OIDC"], "github_repository_id": 1153079753, "homepage": "https://github.com/marbindrakon/simple-aircraft-manager", "id": "github:1153079753", "leaf_matches": [{"reason": "README 明确 Aircraft & Fleet Management（多机、飞行小时/状态）、Component Tracking（TBO/服务间隔）、Airworthiness Status（AD、squawk、inspection）、AD recurring due dates/overdue detection、Inspection Tracking、Logbook；构成飞机登记、到期清单与适航记录闭环。", "slug": "aircraft-maintenance-management", "source_urls": ["https://raw.githubusercontent.com/marbindrakon/simple-aircraft-manager/main/README.md"]}], "license": "Unlicense", "license_evidence_url": "https://api.github.com/repos/marbindrakon/simple-aircraft-manager/license", "name": "Simple Aircraft Manager", "repository_url": "https://github.com/marbindrakon/simple-aircraft-manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:54:23.206377+08:00", "kind": "repository_metadata", "sha256": "1ce60cf0a09b96169881a67d08652750daa80e6424b438a839bc49daba59dcab", "snapshot_path": "sources/1ce60cf0a09b96169881a67d08652750daa80e6424b438a839bc49daba59dcab.txt", "url": "https://api.github.com/repos/marbindrakon/simple-aircraft-manager"}, {"fetched_at": "2026-10-26T20:54:23.654518+08:00", "kind": "license", "sha256": "ac88ae1feb513943734b44b01e0b0b64ed64ec1bdba9cfd40941f0331cc35110", "snapshot_path": "sources/ac88ae1feb513943734b44b01e0b0b64ed64ec1bdba9cfd40941f0331cc35110.txt", "url": "https://api.github.com/repos/marbindrakon/simple-aircraft-manager/license"}, {"fetched_at": "2026-10-26T20:54:24.083946+08:00", "kind": "readme", "sha256": "fb3a7ba477cda3c17a9d1aea58047482686da1d80a45be4e92d1ed96dc44f458", "snapshot_path": "sources/fb3a7ba477cda3c17a9d1aea58047482686da1d80a45be4e92d1ed96dc