INSERT INTO "application" VALUES('commercial:aims-operations-control','AIMS Operations Control','{"homepage": "https://www.aimsairlinesoftware.com/", "id": "commercial:aims-operations-control", "leaf_matches": [{"reason": "产品页明确 Aircraft Movement Control（按机尾优化/重分配、6 小时至 1 个月实际/预计视图、SITA 动态报文、延误及机组值勤冲突提示、快速重排、授权 override）、维护计划联动与航班计划构建；覆盖运营日航段、机尾轮转、实时状态和 OCC 修订循环。", "slug": "airline-operations-platform", "source_urls": ["https://www.aimsairlinesoftware.com/operations-control", "https://www.aimsairlinesoftware.com/"]}], "name": "AIMS Operations Control", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:53:34.697221+08:00", "kind": "homepage", "sha256": "264f3bd3d2449bb2b794823dc79bf2b2d2b585c9f021fd8cf8825ff52da3ec8e", "snapshot_path": "sources/264f3bd3d2449bb2b794823dc79bf2b2d2b585c9f021fd8cf8825ff52da3ec8e.txt", "url": "https://www.aimsairlinesoftware.com/"}, {"fetched_at": "2026-10-26T20:53:49.930320+08:00", "kind": "documentation", "sha256": "e2bef7108e12bea811d87c11259ea314aef9b6a5445a39168570ae5a4f7d7ee5", "snapshot_path": "sources/e2bef7108e12bea811d87c11259ea314aef9b6a5445a39168570ae5a4f7d7ee5.txt", "url": "https://www.aimsairlinesoftware.com/operations-control"}], "summary": "航空公司运行控制平台：以机尾为资源编排运营日航段，跟踪实际/预计运行状态，处理延误与机组值勤冲突，并在授权范围内重排飞机与航班。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:navitaire-new-skies','Navitaire New Skies','{"homepage": "https://www.navitaire.com/", "id": "commercial:navitaire-new-skies", "leaf_matches": [{"reason": "产品页明确 airline reservation platform、reservation and distribution、Internet Booking Engine、GDS/e-ticket integration、payment options、agency accounts、codeshare/interline、Single Order/ONE Order，并与 GoNow day-of-departure 服务集成；证明航空公司预订/分销与旅行当天服务。页面未明示座位库存 bucket 模型，未据此断言具体库存实现。", "slug": "airline-reservation-passenger-service-system", "source_urls": ["https://www.navitaire.com/new-skies-reservation-system", "https://www.navitaire.com/"]}], "name": "Navitaire New Skies", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:52:58.522726+08:00", "kind": "homepage", "sha256": "b7c204fc3295567205582200b4f6dd4cbd9f93b79e074d70f41eb3d8836d93ec", "snapshot_path": "sources/b7c204fc3295567205582200b4f6dd4cbd9f93b79e074d70f41eb3d8836d93ec.txt", "url": "https://www.navitaire.com/"}, {"fetched_at": "2026-10-26T20:53:22.322701+08:00", "kind": "documentation", "sha256": "ca9246f93295148a76c8dfb04caf9ce598178e6872a4cf05d6286157bf5ac7ff", "snapshot_path": "sources/ca9246f93295148a76c8dfb04caf9ce598178e6872a4cf05d6286157bf5ac7ff.txt", "url": "https://www.navitaire.com/new-skies-reservation-system"}], "summary": "航空公司预订与分销平台：互联网订座引擎、GDS/电子客票/支付与代理结算，基于 Single Order 概念，并配套旅行当天服务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1300432801','Openfront Airline','{"deployment": ["Next.js + PostgreSQL 自托管", "Vercel 一键部署示例", "Prisma 迁移与 S3 对象存储配置"], "features": ["航线、班期、日期航班、舱位/票价品牌与库存 bucket/hold", "Offer 与 booking（不可变 booking lines）", "旅客、证件、客票/联票、座位、值机、登机牌、行李与舱单", "支付登记/对账、换开、退款与不正常航班恢复", "公开航班发现、manage-booking、check-in 与航班状态页面"], "github_repository_id": 1300432801, "homepage": "https://github.com/openshiporg/openfront-airline", "id": "github:1300432801", "leaf_matches": [{"reason": "README 明确 self-hostable airline retailing and passenger-service；配置 routes/schedules/dated flights/cabins/fare brands/inventory buckets/holds，创建 offers/bookings，维护 passengers、tickets、seats、check-in、boarding passes、manifests；并含 payments/refunds 与 disruption recovery。覆盖可售航班库存、旅客预订记录、商业承诺和旅行当天处理。", "slug": "airline-reservation-passenger-service-system", "source_urls": ["https://raw.githubusercontent.com/openshiporg/openfront-airline/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/openshiporg/openfront-airline/license", "name": "Openfront Airline", "repository_url": "https://github.com/openshiporg/openfront-airline", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T20:54:54.564741+08:00", "kind": "repository_metadata", "sha256": "56d520cc7d716d4ff8640688c089027c485f7527313689fc086f21e7669fedb4", "snapshot_path": "sources/56d520cc7d716d4ff8640688c089027c485f7527313689fc086f21e7669fedb4.txt", "url": "https://api.github.com/repos/openshiporg/openfront-airline"}, {"fetched_at": "2026-10-26T20:54:54.675175+08:00", "kind": "license", "sha256": "d43e7ce62ea5829c5bd1574959ded92ed1ec9fd43782bcd94faadcf005fbd1c7", "snapshot_path": "sources/d43e7ce62ea5829c5bd1574959ded92ed1ec9fd43782bcd94faadcf005fbd1c7.txt", "url": "https://api.github.com/repos/openshiporg/openfront-airline/license"}, {"fetched_at": "2026-10-26T20:55:16.724060+08:00", "kind": "readme", "sha256": "a85ff04724acddb77cd405f826c8f03222b3b25f03de7b5002a80f6a71bc479b