INSERT INTO "application" VALUES('commercial:pros-revenue-management','PROS Revenue Management','{"homepage": "https://pros.com/", "id": "commercial:pros-revenue-management", "leaf_matches": [{"reason": "官方产品页正文写明需求预测、bid price 与 inventory controls，面向未来航班做容量受限优化，属于收益管理决策系统。", "slug": "airline-revenue-management", "source_urls": ["https://pros.com/products/airline-revenue-management-software"]}], "name": "PROS Revenue Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:00:17.870277+08:00", "kind": "documentation", "sha256": "4333cef10d98dce8bf48288427f998866c2741407593df7040ae990286136626", "snapshot_path": "sources/4333cef10d98dce8bf48288427f998866c2741407593df7040ae990286136626.txt", "url": "https://pros.com/products/airline-revenue-management-software"}], "summary": "面向航空公司的收益管理系统，按未来航班预测需求与价格弹性，计算 bid price 和库存/可用性控制，并把控制交给航空公司的销售与预订系统执行。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
