INSERT INTO "application" VALUES('commercial:inform-groundstar','INFORM GroundStar','{"homepage": "https://www.inform-software.com/", "id": "commercial:inform-groundstar", "leaf_matches": [{"reason": "官方正文明确面向 ground handlers，对 ground handling staff 与 equipment 做规划、排班、分配和分析，覆盖地勤运营承诺的资源分配核心。", "slug": "ground-handling-management", "source_urls": ["https://www.inform-software.com/en/software/groundstar"]}], "name": "INFORM GroundStar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:00:42.126685+08:00", "kind": "documentation", "sha256": "e30c91367dc3d42f61f10fe81afe4ecccd239920213848e266fefb707633d8b5", "snapshot_path": "sources/e30c91367dc3d42f61f10fe81afe4ecccd239920213848e266fefb707633d8b5.txt", "url": "https://www.inform-software.com/en/software/groundstar"}], "summary": "面向机场、航空公司和地勤服务商的地面服务资源管理套件，覆盖人员与地面支持设备（GSE）的规划、排班、分配与运营后分析，并提供实时运营可视性和中断恢复能力。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:descartes-delivery-appointment-scheduling','Descartes Delivery Appointment Scheduling','{"homepage": "https://www.descartes.com/", "id": "commercial:descartes-delivery-appointment-scheduling", "leaf_matches": [{"reason": "官方正文以可预约配送时段、真实容量、可达时段、订单截止时间和持续优化为核心，符合配送承诺/时间表/可用性结构。", "slug": "delivery-scheduling-platform", "source_urls": ["https://www.descartes.com/solutions/routing-mobile-and-telematics/delivery-appointment-scheduling"]}], "name": "Descartes Delivery Appointment Scheduling", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:00:44.743329+08:00", "kind": "documentation", "sha256": "1655252693c777619fd4944b96eb9ab3f1e97be6d9ecff3e0280cbc708e73471", "snapshot_path": "sources/1655252693c777619fd4944b96eb9ab3f1e97be6d9ecff3e0280cbc708e73471.txt", "url": "https://www.descartes.com/solutions/routing-mobile-and-telematics/delivery-appointment-scheduling"}], "summary": "面向零售与配送业务的配送预约调度软件：按真实容量、服务时长、地址与体积生成可承诺的配送时段，执行截止时间与持续优化，并向客户提供可预约选项。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
