INSERT INTO "application" VALUES('github:521139207','YunParking','{"deployment": ["自托管部署（MySQL、Redis、RabbitMQ、JDK 1.8）"], "features": ["路内与路外停车场统一管理", "停车收费规则与计费", "支付聚合、月卡与余额支付", "车位预约与共享车位", "巡查PAD执法与设备管理", "车场、车主与区域管理"], "github_repository_id": 521139207, "homepage": "https://yuncitys.com", "id": "github:521139207", "leaf_matches": [{"reason": "开源代码包含停车运营后台、路内与路外停车、计费规则、支付中心与月卡模块，覆盖停车库存、临时停留与长期许可及费率、收费与对账核心；仓库自述为旧版部分代码，完整性与成熟度有限。", "slug": "parking-management-platform", "source_urls": ["https://api.github.com/repos/yuncitys/YunParking/readme"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/yuncitys/YunParking/license", "name": "YunParking", "repository_url": "https://github.com/yuncitys/YunParking", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:18:24.558979+08:00", "kind": "repository_metadata", "sha256": "d9152ed0832053f6436f4df2eb93956af84f0a9867481c6fb70f1d25bb93bc3d", "snapshot_path": "sources/d9152ed0832053f6436f4df2eb93956af84f0a9867481c6fb70f1d25bb93bc3d.txt", "url": "https://api.github.com/repos/yuncitys/YunParking"}, {"fetched_at": "2026-10-26T21:18:43.969762+08:00", "kind": "readme", "sha256": "10b5cf2fd14cf947ef4f57df3791e6d9ec39ae28ac0ee65dfda2ad1512754b7d", "snapshot_path": "sources/10b5cf2fd14cf947ef4f57df3791e6d9ec39ae28ac0ee65dfda2ad1512754b7d.txt", "url": "https://api.github.com/repos/yuncitys/YunParking/readme"}, {"fetched_at": "2026-10-26T21:18:45.892515+08:00", "kind": "license", "sha256": "68dd55a12c71a8de383ba9e7a48f40a3c462c5db653f2aa72715874e708a7a6f", "snapshot_path": "sources/68dd55a12c71a8de383ba9e7a48f40a3c462c5db653f2aa72715874e708a7a6f.txt", "url": "https://api.github.com/repos/yuncitys/YunParking/license"}], "summary": "城市级智慧停车开源旧版（仓库自述为部分旧代码），覆盖路内与路外停车、收费规则、支付聚合、月卡许可、会员、巡查执法与设备管理；当前商业版为重构后的新版，与本开源版本不同。", "technology_stack": ["Java/Spring Cloud 微服务", "MySQL", "Redis", "RabbitMQ", "MQTT"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
