INSERT INTO "application" VALUES('commercial:energy-one-power-plant-management','Energy One Power Plant Management System','{"homepage": "https://www.energyone.com/solutions/power-plant-management-system", "id": "commercial:energy-one-power-plant-management", "leaf_matches": [{"reason": "官方页面描述面向燃气电厂的 Power Plant Management System，包含按机组调度计划、基于停机/天气/技术限制的可用能力计算、计划停机、市场提名、审计日志及可用性/调度/结算报告，覆盖本叶生产、可用性与核算核心；案例为 Energy One 定制交付的商业应用。", "slug": "power-plant-management", "source_urls": ["https://www.energyone.com/solutions/power-plant-management-system"]}], "name": "Energy One Power Plant Management System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:26:18.220050+08:00", "kind": "documentation", "sha256": "0d3f0706b3fb87369193125da5d954297576545b18da2287aa50e53a8aa92990", "snapshot_path": "sources/0d3f0706b3fb87369193125da5d954297576545b18da2287aa50e53a8aa92990.txt", "url": "https://www.energyone.com/solutions/power-plant-management-system"}], "summary": "Energy One 为燃气电厂提供电力资产管理应用，按机组维护调度计划、可用性声明、计划/非计划停机、市场提名与结算/审计报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:power-factors-unity','Power Factors Unity','{"homepage": "https://www.powerfactors.com/", "id": "commercial:power-factors-unity", "leaf_matches": [{"reason": "官方首页正文将 Unity 定位为 renewable energy management suite，列示组合级 system of record、资产可用性与产出优化、发票管理、现场服务工单及收入监督，并有 4.6 GW 光伏与储能客户案例，覆盖本叶组合记录、生产/可用性与资金报告核心。", "slug": "renewable-energy-asset-management", "source_urls": ["https://www.powerfactors.com/"]}], "name": "Power Factors Unity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:25:39.785436+08:00", "kind": "homepage", "sha256": "3ec331364ac808aa12b1c0edf352ff641d6893cac3a55fc1dd6ad4ea70f2b5b3", "snapshot_path": "sources/3ec331364ac808aa12b1c0edf352ff641d6893cac3a55fc1dd6ad4ea70f2b5b3.txt", "url": "https://www.powerfactors.com/"}], "summary": "Power Factors Unity 面向风、光、储等可再生资产组合，提供组合级系统记录、资产绩效与可用性管理、发票管理、现场工单和收入/运营监督。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:alsoenergy-powertrack','AlsoEnergy PowerTrack','{"homepage": "https://home.alsoenergy.com/", "id": "commercial:alsoenergy-powertrack", "leaf_matches": [{"reason": "官方 PowerTrack 页明确展示 actual versus weather-adjusted energy production、组合/站点/设备层级系统记录、诊断与远程排障；Asset Managers 页列示组合级财务报告、PPA 管理、发票、站点对比和第三方 CMMS/BI 集成，覆盖本叶资源校正预期、可用性恢复与资金/报告核心。", "slug": "solar-asset-management", "source_urls": ["https://home.alsoenergy.com/powertrack/", "https://home.alsoenergy.com/asset-managers/"]}], "name": "AlsoEnergy PowerTrack", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:27:23.813693+08:00", "kind": "homepage", "sha256": "7d19539cbc47e68b6d0f1f7f2f4521352e052af1c36b364aada0341f43f61509", "snapshot_path": "sources/7d19539cbc47e68b6d0f1f7f2f4521352e052af1c36b364aada0341f43f61509.txt", "url": "https://home.alsoenergy.com/"}, {"fetched_at": "2026-10-26T21:28:50.455264+08:00", "kind": "documentation", "sha256": "ebae0131e7058a97a9d2530b6052ea4aea121e62eb5b91b992a924759fffa4aa", "snapshot_path": "sources/ebae0131e7058a97a9d2530b6052ea4aea121e62eb5b91b992a924759fffa4aa.txt", "url": "https://home.alsoenergy.com/powertrack/"}, {"fetched_at": "2026-10-26T21:28:53.708548+08:00", "kind": "documentation", "sha256": "9040d801163190267e69dedfd663e1adbf2515a71dabcd67355d2dbdc5563172", "snapshot_path": "sources/9040d801163190267e69dedfd663e1adbf2515a71dabcd67355d2dbdc5563172.txt", "url": "https://home.alsoenergy.com/asset-managers/"}], "summary": "AlsoEnergy PowerTrack 面向光伏/清洁能源组合，提供站点与设备记录、天气校正的实际与预期发电对比、故障诊断、PPA/财务报告和运维监督。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:power-factors-unity-apm','Power Factors Unity Asset Performance Management','{"homepage": "https://www.powerfactors.com/", "id": "commercial:power-factors-unity-apm", "leaf_matches": [{"reason": "官方产品页明确以风电场/机组为组合记录，按资源调整基线比较实际与预期发电，并对停机、限电和欠发损失分类，覆盖风电产量管理与可用性/服务协同核心。", "slug": "wind-asset-management", "source_urls": ["https://www.powerfactors.com/unity/asset-performance-management"]}], "name": "Power Factors Unity Asset Performance Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:33:46.871394+08:00", "kind": "documentation", "sha256": "39ed7971fc18b5c7662f05a2eb043b28fcd2ea87ec056ed26da3753a51bd1717", "snapshot_path": "sources/39ed7971fc18b5c7662f05a2eb043b28fcd2ea87ec056ed26da3753a51bd1717.txt", "url": "https://www.powerfactors.com/unity/asset-performance-management"}], "summary": "面向风电、光伏和储能的资产绩效管理产品，提供风电场/机组级组合视图、实际与预期发电对比、停机/限电/欠发损失分类、可用性与服务协同。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dnv-synergi-pipeline','DNV Synergi Pipeline','{"homepage": "https://www.dnv.com/", "id": "commercial:dnv-synergi-pipeline", "leaf_matches": [{"reason": "官方页面说明其面向气体与液体管道，按管道、阀门、调压站、储存组织资产，管理检查、维修、异常生命周期、HCA/MCA 与变更审计，网络模型可由 Esri ArcGIS 主控，符合管道网络记录与生命周期核心。", "slug": "gas-pipeline-management", "source_urls": ["https://www.dnv.com/services/synergi-pipeline"]}], "name": "DNV Synergi Pipeline", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:33:49.775826+08:00", "kind": "documentation", "sha256": "6db0dcac6b8e3b7f60ec54135dcc9d678d2cc10df48863200fd174c1ffb38a4b", "snapshot_path": "sources/6db0dcac6b8e3b7f60ec54135dcc9d678d2cc10df48863200fd174c1ffb38a4b.txt", "url": "https://www.dnv.com/services/synergi-pipeline"}], "summary": "管道风险与完整性管理平台，覆盖管道、阀门、调压站和储存设施，管理风险评估、检查/维修、异常全生命周期、合规报告与变更审计。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:starnik-utility-billing','Starnik Utility Billing','{"homepage": "https://www.starnik.com/", "id": "commercial:starnik-utility-billing", "leaf_matches": [{"reason": "官方页面明确面向 Gas Utilities，提供云 CIS、AMI/AMR 表计读数、任意费率计费、实时支付、服务工单、现场作业和押金/费用，覆盖燃气公用事业客户账户与资金循环。", "slug": "gas-utility-management", "source_urls": ["https://www.starnik.com/solutions/utilities"]}], "name": "Starnik Utility Billing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:35:34.937828+08:00", "kind": "documentation", "sha256": "cd0717043b6e263bbde5031d90fada5033cf877b00dc9628f5521186f13322d8", "snapshot_path": "sources/cd0717043b6e263bbde5031d90fada5033cf877b00dc9628f5521186f13322d8.txt", "url": "https://www.starnik.com/solutions/utilities"}], "summary": "面向水、电、燃气和污水公用事业的云 CIS/计费平台，覆盖表计读数、费率计费、收款、服务工单、现场作业和客户门户。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3612045','Ubilling','{"deployment": ["自托管部署于 ISP 自有服务器（官方提供安装与系统需求文档）"], "features": ["订阅者账户与用户标签管理", "Internet/IPTV/OTT 等服务与费率管理", "服务冻结天数限制与计费周期", "用户门户、报表与网络设备监控"], "github_repository_id": 3612045, "homepage": "https://ubilling.net.ua/", "id": "github:3612045", "leaf_matches": [{"reason": "官方仓库元数据与项目主页说明其管理 ISP 订阅者、服务计费和支付；官方 Wiki 进一步列出用户标签、复杂服务、费率周期、冻结天数限制和用户门户，支撑订阅者记录及服务生命周期。", "slug": "subscriber-management", "source_urls": ["https://api.github.com/repos/nightflyza/Ubilling", "https://ubilling.net.ua/", "https://wiki.ubilling.net.ua/"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/nightflyza/Ubilling/license", "name": "Ubilling", "repository_url": "https://github.com/nightflyza/Ubilling", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:34:12.211175+08:00", "kind": "repository_metadata", "sha256": "b0729c4e1a4473b541c058a476c07406e0a96cd2d68294b4861b5317f1a0b23e", "snapshot_path": "sources/b0729c4e1a4473b541c058a476c07406e0a96cd2d68294b4861b5317f1a0b23e.txt", "url": "https://api.github.com/repos/nightflyza/Ubilling"}, {"fetched_at": "2026-10-26T21:34:12.641571+08:00", "kind": "license", "sha256": "561ef96148d6c660c02f2cbb4e5226bcd49082d4d1590b7f9556ba4eba3f57f9", "snapshot_path": "sources/561ef96148d6c660c02f2cbb4e5226bcd49082d4d1590b7f9556ba4eba3f57f9.txt", "url": "https://api.github.com/repos/nightflyza/Ubilling/license"}, {"fetched_at": "2026-10-26T21:34:12.468722+08:00", "kind": "readme", "sha256": "97957cd37d358363af35cb8ef27443ab290dd7a18af9a403e176010e5380109e", "snapshot_path": "sources/97957cd37d358363af35cb8ef27443ab290dd7a18af9a403e176010e5380109e.txt", "url": "https://raw.githubusercontent.com/nightflyza/Ubilling/master/README.md"}, {"fetched_at": "2026-10-26T21:34:40.046920+08:00", "kind": "homepage", "sha256": "514e56fd85d8a8c7cdfdc7b5bf3d92089f362f6686439fe0e680be2e26d00929", "snapshot_path": "sources/514e56fd85d8a8c7cdfdc7b5bf3d92089f362f6686439fe0e680be2e26d00929.txt", "url": "https://ubilling.net.ua/"}, {"fetched_at": "2026-10-26T21:36:04.695205+08:00", "kind": "documentation", "sha256": "06c42720a440809a62e6511801be185ca221935d57fecd8e19877ef058949383", "snapshot_path": "sources/06c42720a440809a62e6511801be185ca221935d57fecd8e19877ef058949383.txt", "url": "https://wiki.ubilling.net.ua/"}], "summary": "面向 ISP 的开源用户与计费管理系统（GPL-2.0），维护订阅者账户、服务/费率与付费状态，并提供网络设备监控和报表。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:assetworks-eam-utilities','AssetWorks EAM for Utilities','{"homepage": "https://www.assetworks.com/", "id": "commercial:assetworks-eam-utilities", "leaf_matches": [{"reason": "官方页面说明其为公用事业提供资产登记与全生命周期管理，包含预防性维护、检查、工单、成本、资本规划和 GIS，适用于网络型公用事业资产范围。", "slug": "utility-asset-management", "source_urls": ["https://www.assetworks.com/eam/utilities"]}], "name": "AssetWorks EAM for Utilities", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:33:48.079153+08:00", "kind": "documentation", "sha256": "46c8e4109becf3897bad1f417046c9bb27092d98e7296cec516d226014d576aa", "snapshot_path": "sources/46c8e4109becf3897bad1f417046c9bb27092d98e7296cec516d226014d576aa.txt", "url": "https://www.assetworks.com/eam/utilities"}], "summary": "面向公用事业的资产管理平台，管理基础设施、管道、表计与设施，覆盖资产全生命周期、检查/工单、成本、资本规划并集成 GIS。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:867131396','Utility Billing & Property Management (ERPNext)','{"deployment": ["Frappe Bench 自托管", "安装于 ERPNext 站点"], "features": ["服务申请→勘察→BOM→销售订单", "抄表读数与用量自动计算", "价格清单/费率与客户分组", "批量计费与按客户合并发票", "销售订单→发票→收款（ERPNext 会计）", "物业、租约与租户公用事业计费"], "github_repository_id": 867131396, "homepage": "https://github.com/navariltd/utility-billing", "id": "github:867131396", "leaf_matches": [{"reason": "公用事业计费子模块：按客户与计量表处理抄表、用量、费率和批量开票，并以销售订单/发票/收款承载计费资金链路；文档未展示停复电与最终账单，不据此扩展。", "slug": "utility-billing-platform", "source_urls": ["https://api.github.com/repos/navariltd/utility-billing", "https://raw.githubusercontent.com/navariltd/utility-billing/develop/README.md", "https://api.github.com/repos/navariltd/utility-billing/license", "https://raw.githubusercontent.com/navariltd/utility-billing/develop/utility_billing/docs/Utility-Billing.md"]}, {"reason": "ERPNext/Frappe 的公用事业计费模块，覆盖服务账户、抄表读数、可配置费率/价格表、批量出账、收款及会计集成，可作为供水客户与资金系统；欠费停复水、押金和付款计划需由 ERPNext 配置扩展，仓库文档未明确。", "slug": "water-utility-management", "source_urls": ["https://raw.githubusercontent.com/navariltd/utility-billing/develop/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/navariltd/utility-billing/license", "name": "Utility Billing & Property Management (ERPNext)", "repository_url": "https://github.com/navariltd/utility-billing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:30:45.155921+08:00", "kind": "repository_metadata", "sha256": "ba9c4058469f7505a5c39027fa24ab83aba0564b2c2eff252b909dbb2eb9f686", "snapshot_path": "sources/ba9c4058469f7505a5c39027fa24ab83aba0564b2c2eff252b909dbb2eb9f686.txt", "url": "https://api.github.com/repos/navariltd/utility-billing"}, {"fetched_at": "2026-10-26T21:30:46.759542+08:00", "kind": "readme", "sha256": "70cae28b7bb3d52401874e086941166f839beb6b7fc6ae9adfa82c1645c2a9c7", "snapshot_path": "sources/70cae28b7bb3d52401874e086941166f839beb6b7fc6ae9adfa82c1645c2a9c7.txt", "url": "https://raw.githubusercontent.com/navariltd/utility-billing/develop/README.md"}, {"fetched_at": "2026-10-26T21:30:48.768301+08:00", "kind": "license", "sha256": "a4dd7987198cb333d5168b2cc025d251c5d1356a0f604d7a68d95c4a070be326", "snapshot_path": "sources/a4dd7987198cb333d5168b2cc025d251c5d1356a0f604d7a68d95c4a070be326.txt", "url": "https://api.github.com/repos/navariltd/utility-billing/license"}, {"fetched_at": "2026-10-26T21:31:03.963828+08:00", "kind": "documentation", "sha256": "569d511631ac8791d77aa594334f17c62bc29b5104f5624875c790a11f9f77de", "snapshot_path": "sources/569d511631ac8791d77aa594334f17c62bc29b5104f5624875c790a11f9f77de.txt", "url": "https://raw.githubusercontent.com/navariltd/utility-billing/develop/utility_billing/docs/Utility-Billing.md"}], "summary": "ERPNext 的开源公用事业计费与物业管理子模块（AGPL-3.0），提供公用事业服务申请、抄表用量计算、费率与批量开票，并接入 ERPNext 的销售订单、发票与收款；同样覆盖物业/租户计费。", "technology_stack": ["Python", "Frappe Framework", "ERPNext", "MariaDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:northstar-utilities-cis','NorthStar Customer Information System','{"homepage": "https://www.northstarutilities.com/", "id": "commercial:northstar-utilities-cis", "leaf_matches": [{"reason": "官方产品页明确以公用事业 CIS 定位，按客户账户处理 move-in/move-out、多公用事业账单及替代能源计费，属于客户与服务记录主导的 CIS 类型。", "slug": "utility-customer-information-system-cis", "source_urls": ["https://www.northstarutilities.com/customer-information-billing"]}], "name": "NorthStar Customer Information System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:32:18.402810+08:00", "kind": "documentation", "sha256": "24842d01394e03d258c88f3cd3e33a4dcc08e7290c96a918e80b007e1b2700b7", "snapshot_path": "sources/24842d01394e03d258c88f3cd3e33a4dcc08e7290c96a918e80b007e1b2700b7.txt", "url": "https://www.northstarutilities.com/customer-information-billing"}], "summary": "面向中小型公用事业与市政的客户信息系统/计费软件，覆盖客户从入住到搬出的服务账户、多公用事业合并账单与放松管制能源计费。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:northstar-servicelink','NorthStar ServiceLink','{"homepage": "https://www.northstarutilities.com/", "id": "commercial:northstar-servicelink", "leaf_matches": [{"reason": "官方产品页明确面向 water/gas/electric/sanitation 现场团队，覆盖调度→到场→移动作业→作业完成表单的现场执行循环，并支持技能匹配、预约与离线作业，符合公用事业现场服务类型。", "slug": "utility-field-service-management", "source_urls": ["https://www.northstarutilities.com/mobile-workforce-management"]}], "name": "NorthStar ServiceLink", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:33:07.768226+08:00", "kind": "documentation", "sha256": "9cf347546019b4e27f6278e98af5f5fd5a6344c9d5425f3ec8558c15c37d50b3", "snapshot_path": "sources/9cf347546019b4e27f6278e98af5f5fd5a6344c9d5425f3ec8558c15c37d50b3.txt", "url": "https://www.northstarutilities.com/mobile-workforce-management"}], "summary": "面向水、燃气、电力与环卫公用事业的现场服务管理产品，提供实时调度与优化、技能匹配、路由、预约通知、离线移动作业与作业完成表单。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:esri-arcgis-utility-network','ArcGIS Utility Network','{"homepage": "https://www.esri.com/", "id": "commercial:esri-arcgis-utility-network", "leaf_matches": [{"reason": "官方产品页明确以连通的统一网络模型管理公用事业基础设施，并强调 GIS 图层、连接规则/数据治理、追踪分析、2D/3D 可视化与编辑权限，符合公用事业 GIS 的连通网络记录模型核心。", "slug": "utility-gis", "source_urls": ["https://www.esri.com/en-us/arcgis/products/arcgis-utility-network/overview"]}], "name": "ArcGIS Utility Network", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:33:44.602566+08:00", "kind": "documentation", "sha256": "11dcdb776914ed8dd6b535edcd0e7afd74155006d209f44d028abf7c5daae726", "snapshot_path": "sources/11dcdb776914ed8dd6b535edcd0e7afd74155006d209f44d028abf7c5daae726.txt", "url": "https://www.esri.com/en-us/arcgis/products/arcgis-utility-network/overview"}], "summary": "Esri 的公用事业网络 GIS 数据模型与能力扩展，在 ArcGIS Enterprise/Pro 上维护连通的公用事业网络模型，支持连接规则、追踪分析、2D/3D 可视化与角色化编辑。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aidash-ivms','AiDASH IVMS (Intelligent Vegetation Management System)','{"homepage": "https://www.aidash.com/", "id": "commercial:aidash-ivms", "leaf_matches": [{"reason": "官方产品页正文展示以输配电走廊为空间框架的植被条件监测、按电路/子电路与预算的修剪计划、前后检查与监管审计报告，符合公用事业植被管理的走廊资产+计划性项目核心；未据此断言完整承包商派工闭环。", "slug": "utility-vegetation-management", "source_urls": ["https://www.aidash.com/intelligent-vegetation-management-system/"]}], "name": "AiDASH IVMS (Intelligent Vegetation Management System)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:35:36.858531+08:00", "kind": "documentation", "sha256": "bad726e2f4cf8a0c65013d77eff57fedc58d9961a4055c8deec77bbcec283521", "snapshot_path": "sources/bad726e2f4cf8a0c65013d77eff57fedc58d9961a4055c8deec77bbcec283521.txt", "url": "https://www.aidash.com/intelligent-vegetation-management-system/"}], "summary": "面向电力公用事业的商业植被管理产品，结合卫星/遥感与 AI 监测输配电走廊植被条件，支持按电路/子电路和预算规划修剪周期、修剪前后检查及监管审计报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:muni-link','Muni-Link','{"homepage": "https://muni-link.com/", "id": "commercial:muni-link", "leaf_matches": [{"reason": "官方页面明确面向水、污水和雨水公用事业，提供账户、抄表、计费、收款、服务工单与客户门户；污水服务作为同一客户账户上的收费项目。", "slug": "wastewater-utility-management", "source_urls": ["https://muni-link.com/features/billing", "https://muni-link.com/product"]}, {"reason": "同一云端平台明确支持供水公用事业，覆盖供水账户、抄表、计费、收款、服务工单和客户沟通，符合客户与资金记录系统的主流程。", "slug": "water-utility-management", "source_urls": ["https://muni-link.com/features/billing", "https://muni-link.com/product"]}], "name": "Muni-Link", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:38:43.357769+08:00", "kind": "homepage", "sha256": "a93a1eda4150a9fc94ef11152f30e96cecf39daa61bf90f8de925b7819a5e198", "snapshot_path": "sources/a93a1eda4150a9fc94ef11152f30e96cecf39daa61bf90f8de925b7819a5e198.txt", "url": "https://muni-link.com/features/billing"}, {"fetched_at": "2026-10-26T21:38:42.279729+08:00", "kind": "homepage", "sha256": "16fcda69f02afd0c92d007f4bb67fb911cf9e781c31b102098944670bbdeb10f", "snapshot_path": "sources/16fcda69f02afd0c92d007f4bb67fb911cf9e781c31b102098944670bbdeb10f.txt", "url": "https://muni-link.com/product"}], "summary": "面向水、污水与雨水公用事业的云端客户信息与计费平台，统一管理客户账户、抄表、账单计算、收款、服务工单和客户门户；适合市政公用事业及水务当局。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:takadu','TaKaDu','{"homepage": "https://www.takadu.com/", "id": "commercial:takadu", "leaf_matches": [{"reason": "官网说明其 24/7 分析管网数据，自动检测漏损、水质、压力事件和资产故障，并在同一仪表板中从检测管理到解决，符合监测—事件—响应闭环。", "slug": "water-network-monitoring", "source_urls": ["https://www.takadu.com/"]}], "name": "TaKaDu", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:38:04.788097+08:00", "kind": "homepage", "sha256": "3622114cc9468a10d27ea29f796c253aaef43747bbbf53afb5c369a2b58dc1cc", "snapshot_path": "sources/3622114cc9468a10d27ea29f796c253aaef43747bbbf53afb5c369a2b58dc1cc.txt", "url": "https://www.takadu.com/"}], "summary": "面向水务公用事业的云端中央事件管理（CEM）平台，持续分析管网与外部系统数据，自动检测漏损、水质、压力事件及资产故障，并支持事件优先级排序、修复状态跟踪直到解决。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hach-wims','Hach WIMS / WIMS Rio','{"homepage": "https://aquaticinformatics.com/", "id": "commercial:hach-wims", "leaf_matches": [{"reason": "官方产品页与 FAQ 说明其面向饮用水与污水公用事业集中实验室、过程与现场水质数据，保留审计追踪，Sample Manager 可跟踪采样计划，并生成 NetDMR、MOR 等监管报告；WIMS Rio 为云端版本，覆盖水质数据与合规记录主流程。", "slug": "water-quality-management", "source_urls": ["https://aquaticinformatics.com/products/hach-wims-water-information-management-solution-platform/", "https://aquaticinformatics.com/blog/water-quality/wims-rio-frequent-questions/"]}], "name": "Hach WIMS / WIMS Rio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:39:40.066624+08:00", "kind": "documentation", "sha256": "b49333cc84ac763a28d434b4bda704a5249cd08a0f28a9f60c66135b0ea11895", "snapshot_path": "sources/b49333cc84ac763a28d434b4bda704a5249cd08a0f28a9f60c66135b0ea11895.txt", "url": "https://aquaticinformatics.com/products/hach-wims-water-information-management-solution-platform/"}, {"fetched_at": "2026-10-26T21:42:35.291078+08:00", "kind": "documentation", "sha256": "fc04fcc723f21d6bfd8403f2859a8bfd26895577e6ecad01d33d6cf384c6b15c", "snapshot_path": "sources/fc04fcc723f21d6bfd8403f2859a8bfd26895577e6ecad01d33d6cf384c6b15c.txt", "url": "https://aquaticinformatics.com/blog/water-quality/wims-rio-frequent-questions/"}], "summary": "由 Aquatic Informatics 管理的 Hach WIMS 水质信息管理平台：集中实验室、过程、现场与其他水质数据，提供审计追踪、历史保留、告警、采样计划跟踪和 EPA/州合规报告模板；WIMS Rio 为面向饮用水与污水公用事业的云端版本。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:3-gis','3-GIS','{"homepage": "https://www.3-gis.com/", "id": "commercial:3-gis", "leaf_matches": [{"reason": "官方页面说明可从设计生成工单与可施工工作包，连接施工状态、承包商更新、检查验证与竣工回写，并以网络地图/GIS 记录为锚，符合设计到现场工作及现场验证的建设管理核心。", "slug": "network-construction-management", "source_urls": ["https://www.3-gis.com/telecom/fiber-construction-field-operations", "https://www.3-gis.com/software/3-gis-web"]}, {"reason": "官方页面正文明确描述光纤网络从规划、OSP 设计、连接建模、资产库存、施工/as-built 到运维的持续记录，覆盖光纤设施记录、连接模型与管理生命周期。", "slug": "fiber-network-management", "source_urls": ["https://www.3-gis.com/"]}], "name": "3-GIS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:38:40.913695+08:00", "kind": "documentation", "sha256": "bbf84169503af5bc51492bab422059f494ed775c288ed1831d1bfd34d19838d3", "snapshot_path": "sources/bbf84169503af5bc51492bab422059f494ed775c288ed1831d1bfd34d19838d3.txt", "url": "https://www.3-gis.com/telecom/fiber-construction-field-operations"}, {"fetched_at": "2026-10-26T21:39:11.207762+08:00", "kind": "documentation", "sha256": "1408bf2b7088e3d2d8100f9adad95e508851e66e2375403e278bd12a351d99c6", "snapshot_path": "sources/1408bf2b7088e3d2d8100f9adad95e508851e66e2375403e278bd12a351d99c6.txt", "url": "https://www.3-gis.com/software/3-gis-web"}, {"fetched_at": "2026-10-26T21:52:45.861292+08:00", "kind": "homepage", "sha256": "ea2ca6e61d41d61949aa84554edd3eb9812a8887535e42673a8d52fba2ed8a04", "snapshot_path": "sources/ea2ca6e61d41d61949aa84554edd3eb9812a8887535e42673a8d52fba2ed8a04.txt", "url": "https://www.3-gis.com/"}], "summary": "面向光纤与铜缆网络运营商及承包商的网络记录与施工执行平台：把设计转为工单和可施工工作包，承接现场施工更新、承包商协作、检查与竣工回写，并保持与长期网络记录一致。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
