INSERT INTO "application" VALUES('commercial:csg-quote-and-order','CSG Quote & Order','{"homepage": "https://www.csgi.com/", "id": "commercial:csg-quote-and-order", "leaf_matches": [{"reason": "官方页面说明其将复杂报价转为结构化订单、按目录将订单分解为技术与服务任务、跨网络/IT/现场/合作伙伴编排、跟踪依赖与状态、管理在途变更并回写计费与客户系统；符合电信订单管理的订单记录、分解、编排与完成核心。", "slug": "telecom-order-management", "source_urls": ["https://www.csgi.com/solutions/quote-to-cash/order-management"]}], "name": "CSG Quote & Order", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:47:06.674944+08:00", "kind": "documentation", "sha256": "becf9ad58852889fc795dd1bd0edecfdaa7cc706352bf108f217c9c901d8dc5f", "snapshot_path": "sources/becf9ad58852889fc795dd1bd0edecfdaa7cc706352bf108f217c9c901d8dc5f.txt", "url": "https://www.csgi.com/solutions/quote-to-cash/order-management"}], "summary": "CSG 面向电信 B2B 复杂报价与订单的 CPQ/订单管理产品，将合同拆解为技术和服务任务并跨网络、IT、现场与合作伙伴编排履约。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:netcracker-e2e-service-orchestration','Netcracker E2E Service Orchestration','{"homepage": "https://www.netcracker.com/", "id": "commercial:netcracker-e2e-service-orchestration", "leaf_matches": [{"reason": "官方产品页说明该套件包含 Service/Slice Catalog、Service Inventory、Service Orchestration、Service Quality Management 与 Service Assurance，覆盖跨域服务从设计、部署到生命周期管理和保障，并位于 BSS 与域编排之间；符合电信 OSS 以服务库存为共享记录、编排与保障闭环的套件核心。", "slug": "telecom-oss", "source_urls": ["https://www.netcracker.com/portfolio/solutions/intelligent-operations-automation/e2e-service-orchestration"]}], "name": "Netcracker E2E Service Orchestration", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:45:41.033191+08:00", "kind": "documentation", "sha256": "e89559de161c88420b460639ce3432d957fc76d966cf591efd4f0ddc7097ff71", "snapshot_path": "sources/e89559de161c88420b460639ce3432d957fc76d966cf591efd4f0ddc7097ff71.txt", "url": "https://www.netcracker.com/portfolio/solutions/intelligent-operations-automation/e2e-service-orchestration"}], "summary": "Netcracker 的端到端服务编排产品，把服务/切片目录、服务库存、服务编排、服务质量与保障组合为面向电信网络的 OSS 组件套件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cerillion-enterprise-product-catalogue','Cerillion Enterprise Product Catalogue','{"homepage": "https://www.cerillion.com/", "id": "commercial:cerillion-enterprise-product-catalogue", "leaf_matches": [{"reason": "官方产品页说明产品目录管理产品、套餐、资费、价格、资格规则与网络服务，可发布到 CRM、计费、订单管理等下游系统并管理生命周期；配套服务目录页进一步说明产品目录定义商业报价、服务目录定义网络服务/资源与开通逻辑，二者形成产品到服务映射。符合电信产品目录的报价、实现绑定和受控发布三要素。", "slug": "telecom-product-catalog", "source_urls": ["https://www.cerillion.com/products/bssoss-suite/enterprise-product-catalogue/", "https://www.cerillion.com/products/bssoss-suite/service-catalogue/"]}], "name": "Cerillion Enterprise Product Catalogue", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:45:43.908246+08:00", "kind": "documentation", "sha256": "6e0bb6c578d85cfa070d38c65460a59d3599ca822621886421cbb57641438b35", "snapshot_path": "sources/6e0bb6c578d85cfa070d38c65460a59d3599ca822621886421cbb57641438b35.txt", "url": "https://www.cerillion.com/products/bssoss-suite/enterprise-product-catalogue/"}, {"fetched_at": "2026-10-26T21:45:51.888222+08:00", "kind": "documentation", "sha256": "624b7f523d30cba9b1e83f55ae27a6d525365a43667424243ca2992f2e016653", "snapshot_path": "sources/624b7f523d30cba9b1e83f55ae27a6d525365a43667424243ca2992f2e016653.txt", "url": "https://www.cerillion.com/products/bssoss-suite/service-catalogue/"}], "summary": "Cerillion 的电信产品目录，管理产品、套餐、资费、价格与网络服务，并通过服务目录映射到资源与服务实现。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:9377198','OpenNMS Horizon','{"deployment": ["自托管部署；官方提供 Linux 评估安装脚本和安装指南", "支持 Minion、Sentinel 等分布式组件扩展"], "features": ["故障、性能与流量监控及告警生成", "库存与配置管理，支持 SNMP、JSON、JDBC、Prometheus 等多协议采集", "可分层拓扑图并接入服务问题管理工作流", "通过 Minion、Sentinel 扩展分布式监控和流数据处理"], "github_repository_id": 9377198, "homepage": "https://www.opennms.org/", "id": "github:9377198", "leaf_matches": [{"reason": "README 与仓库说明 OpenNMS 是开源网络监控平台，集中提供故障、性能与流量监控、告警生成、分层拓扑和服务问题管理工作流；这些对应电信服务保障的监控、检测、拓扑关联与故障处理核心。快照未确认其提供电信专用服务影响计算，关系按监控与故障管理核心收窄。", "slug": "telecom-service-assurance", "source_urls": ["https://raw.githubusercontent.com/OpenNMS/opennms/develop/README.md", "https://github.com/OpenNMS/opennms", "https://raw.githubusercontent.com/OpenNMS/opennms/develop/COPYING"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/OpenNMS/opennms/develop/COPYING", "license_review": {"rationale": "仓库根目录 COPYING 为完整 GNU Affero GPL v3 文本，并列出少量特别许可文件；本条目按社区核心范围记录，不覆盖商业 Meridian 版本与托管服务。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/OpenNMS/opennms/develop/COPYING", "spdx_id": "AGPL-3.0"}, "name": "OpenNMS Horizon", "repository_url": "https://github.com/OpenNMS/opennms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:47:04.538029+08:00", "kind": "repository_metadata", "sha256": "57ba2aeacec0e74c32e64c622be07aee24cb4bdf61c89ceab64d0da9707732a0", "snapshot_path": "sources/57ba2aeacec0e74c32e64c622be07aee24cb4bdf61c89ceab64d0da9707732a0.txt", "url": "https://github.com/OpenNMS/opennms"}, {"fetched_at": "2026-10-26T21:45:55.248189+08:00", "kind": "license", "sha256": "57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6", "snapshot_path": "sources/57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6.txt", "url": "https://raw.githubusercontent.com/OpenNMS/opennms/develop/COPYING"}, {"fetched_at": "2026-10-26T21:45:56.552038+08:00", "kind": "readme", "sha256": "6e27782ffec09ca39d266b1eab64e9f82c26a2dc688c940bf9ede3622946936d", "snapshot_path": "sources/6e27782ffec09ca39d266b1eab64e9f82c26a2dc688c940bf9ede3622946936d.txt", "url": "https://raw.githubusercontent.com/OpenNMS/opennms/develop/README.md"}], "summary": "OpenNMS Horizon 是 OpenNMS 的开源核心，提供网络与服务的故障、性能、流量监控、告警生成及拓扑视图，可用于电信服务保障。", "technology_stack": ["Java", "Maven"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vcom-solutions','vCom Technology Lifecycle Management','{"homepage": "https://www.vcomsolutions.com/", "id": "commercial:vcom-solutions", "leaf_matches": [{"reason": "官方首页说明可在统一平台跟踪网络与移动资产、订单、项目与工单，管理合同谈判与供应商关系、按资产/运营商/服务/位置归集成本，并提供发票管理与审计、争议管理、MACD 变更；对应运营商作为受管供应商、合同基准、所购连接服务与服务订单/变更的核心。", "slug": "carrier-management", "source_urls": ["https://www.vcomsolutions.com/"]}], "name": "vCom Technology Lifecycle Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:45:58.749126+08:00", "kind": "documentation", "sha256": "104a55f39dafa4d334780f8e5575cb0de98ae261f40b61269a28ceddc17b8ce6", "snapshot_path": "sources/104a55f39dafa4d334780f8e5575cb0de98ae261f40b61269a28ceddc17b8ce6.txt", "url": "https://www.vcomsolutions.com/"}], "summary": "vCom 的技术全生命周期管理平台（含托管服务），覆盖运营商/供应商合同、服务订单与资产、发票审计、争议管理及 MACD 变更。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ampeco','AMPECO','{"homepage": "https://www.ampeco.com/", "id": "commercial:ampeco", "leaf_matches": [{"reason": "官方计费页说明可按充电会话/用量计费、生成驾驶员发票、与站点宿主和合作伙伴按使用与收入结算，并支持月结/后付与企业计费；漫游页说明通过 OCPI 连接漫游伙伴、管理漫游合同与费率，并用结算报告核对伙伴间交易。覆盖 CDR 定价、多方结算与漫游核心。", "slug": "ev-charging-billing-roaming", "source_urls": ["https://www.ampeco.com/ev-charging-platform/payments-and-billing/", "https://www.ampeco.com/ev-charging-platform/ev-roaming/"]}], "name": "AMPECO", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:46:02.666950+08:00", "kind": "documentation", "sha256": "b6e6c24980c1ee8efd796b50a077b06b92e5ab6fc52a32ad4037c8ad5014811f", "snapshot_path": "sources/b6e6c24980c1ee8efd796b50a077b06b92e5ab6fc52a32ad4037c8ad5014811f.txt", "url": "https://www.ampeco.com/ev-charging-platform/payments-and-billing/"}, {"fetched_at": "2026-10-26T21:46:06.188014+08:00", "kind": "documentation", "sha256": "38739be66d6a86f6364a3c5eba24bfbbbfb96ffb92a0748a5c62193f3715fdf0", "snapshot_path": "sources/38739be66d6a86f6364a3c5eba24bfbbbfb96ffb92a0748a5c62193f3715fdf0.txt", "url": "https://www.ampeco.com/ev-charging-platform/ev-roaming/"}], "summary": "AMPECO 是面向充电点运营商与充电服务商的 EV 充电管理平台，提供会话计费、发票、合作伙伴结算与 OCPI 漫游。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12617198','SteVe','{"deployment": ["独立 Java WAR 部署", "Docker Compose", "Kubernetes"], "features": ["充电桩注册与记录管理", "OCPP 1.2/1.5/1.6 心跳与状态接收", "连接器状态与充电交易记录", "充电桩 OCPP 操作界面", "用户与 RFID 卡认证数据管理", "Web 管理界面"], "github_repository_id": 12617198, "homepage": "https://github.com/steve-community/steve", "id": "github:12617198", "leaf_matches": [{"reason": "SteVe 作为 OCPP 中央系统持有充电桩/连接器记录，接收心跳与状态事件，并提供 OCPP 操作与交易界面，覆盖该类型的充电桩车队记录、实时管理连接和运维闭环。", "slug": "ev-charging-network-management", "source_urls": ["https://github.com/steve-community/steve", "https://raw.githubusercontent.com/steve-community/steve/HEAD/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/steve-community/steve/HEAD/LICENSE.txt", "license_review": {"rationale": "读取仓库 LICENSE.txt 全文，确认是 GNU GPL v3 完整文本；README 亦明确项目以 GPL 发布。该许可覆盖仓库整体，Powerfill 商业服务不在本条目范围内。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/steve-community/steve/HEAD/LICENSE.txt", "spdx_id": "GPL-3.0"}, "name": "SteVe", "repository_url": "https://github.com/steve-community/steve", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:49:34.066956+08:00", "kind": "repository_metadata", "sha256": "b5c5fe42598652addd2cc17cd6a338e0f42003463e2709ee27c7d3634561dd8e", "snapshot_path": "sources/b5c5fe42598652addd2cc17cd6a338e0f42003463e2709ee27c7d3634561dd8e.txt", "url": "https://github.com/steve-community/steve"}, {"fetched_at": "2026-10-26T21:49:36.281982+08:00", "kind": "readme", "sha256": "82661892229b07f8d9dc69f5466389ae3fdbb30b54d94fe1621b6560be30cc7b", "snapshot_path": "sources/82661892229b07f8d9dc69f5466389ae3fdbb30b54d94fe1621b6560be30cc7b.txt", "url": "https://raw.githubusercontent.com/steve-community/steve/HEAD/README.md"}, {"fetched_at": "2026-10-26T21:49:37.952774+08:00", "kind": "license", "sha256": "8ceb4b9ee5adedde47b31e975c1d90c73ad27b6b165a1dcd80c7c545eb65b903", "snapshot_path": "sources/8ceb4b9ee5adedde47b31e975c1d90c73ad27b6b165a1dcd80c7c545eb65b903.txt", "url": "https://raw.githubusercontent.com/steve-community/steve/HEAD/LICENSE.txt"}], "summary": "SteVe 是面向充电运营商的 OCPP 中央系统：登记充电桩与连接器，接收心跳、状态和交易事件，提供充电桩/连接器状态、交易与 OCPP 操作界面。项目自 2013 年起开源，社区版以 GPL-3.0 发布；Powerfill 是其上的独立商业服务，不属于本条目。", "technology_stack": ["Java", "MySQL/MariaDB", "OCPP 1.2/1.5/1.6"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:telna','Telna Connect','{"homepage": "https://www.telna.com/", "id": "commercial:telna", "leaf_matches": [{"reason": "官方 Connect 页面正文列出 eSIM 生命周期管理、服务状态/IMSI/配置文件/库存，以及数据/短信/语音服务的激活与停用，符合 SIM/eSIM 凭证群体与生命周期管理的核心结构。", "slug": "sim-esim-management", "source_urls": ["https://www.telna.com/connect"]}], "name": "Telna Connect", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:52:48.001553+08:00", "kind": "homepage", "sha256": "399847c7908e5bfea4be69d9d0670276fe33daab9bc431927c31bb4167161208", "snapshot_path": "sources/399847c7908e5bfea4be69d9d0670276fe33daab9bc431927c31bb4167161208.txt", "url": "https://www.telna.com/connect"}], "summary": "Telna Connect 是面向 CSP/MNO/MVNO 的云连接与 eSIM 管理平台，提供 eSIM 生命周期管理、服务状态与 IMSI/配置文件/套餐/库存查看，以及数据、短信和语音服务的激活/停用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sitetracker','Sitetracker Tower Operations','{"homepage": "https://www.sitetracker.com", "id": "commercial:sitetracker", "leaf_matches": [{"reason": "官方正文把站点点位、容量、资产、租约管理、共置申请、租户/业主、租金起算与维护放在同一系统；租约含主协议、关键日期、付款计划和条款，符合铁塔租赁运营核心。", "slug": "tower-management-platform", "source_urls": ["https://www.sitetracker.com/industries/tower"]}], "name": "Sitetracker Tower Operations", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:53:45.489016+08:00", "kind": "documentation", "sha256": "059158e4e2a1249dce01e92aebbe45c811299b020b59df08dc61742a4fa1804a", "snapshot_path": "sources/059158e4e2a1249dce01e92aebbe45c811299b020b59df08dc61742a4fa1804a.txt", "url": "https://www.sitetracker.com/industries/tower"}], "summary": "面向 TowerCo 的站点与租赁运营平台（官方 Tower Operations 页面），覆盖站点组合、站点容量、租约与主协议、共置申请、租户/业主协作以及维护工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:agworld','Agworld','{"homepage": "https://www.agworld.com", "id": "commercial:agworld", "leaf_matches": [{"reason": "官方 agronomists 页正文（非 meta）明确：可建立从轮作到逐田块生产计划的 crop plans；为每块田生成含 products、rates、timing 的推荐；记录 scouting notes 与 field observations；将建议一键转为 spray records；对照 planned inputs 与 actual applications；查看 field history。", "slug": "agronomy-management", "source_urls": ["https://www.agworld.com/solutions/agronomists"]}], "name": "Agworld", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:05:29.342682+08:00", "kind": "documentation", "sha256": "e58509e7fdc479cb57d53c360f76f506f7bc731614855b866a7d9e5830f28475", "snapshot_path": "sources/e58509e7fdc479cb57d53c360f76f506f7bc731614855b866a7d9e5830f28475.txt", "url": "https://www.agworld.com/solutions/agronomists"}], "summary": "面向农艺师与种植者的协作式农艺管理平台；官方正文明确支持从简单轮作到逐田块生产计划的作物计划、为每块田生成含产品/用量/时机的农艺建议、记录巡查与田间观察，并把建议转为施药记录、对照计划投入与实际施用、查看田块历史。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16508135','farmOS','{"deployment": ["自托管 Web 应用，官方提供安装指南", "官方 Docker 镜像", "README 另提及 Farmier 付费托管；未说明社区版/企业版功能切分"], "features": ["Land 资产表示地块、田块、苗床和牧场，可映射并层级组织", "Plant 资产按作物/品种表示种植批次，支持精细作物计划与记录", "Seeding、transplanting、input、observation、harvest、lab test 等日志", "日志状态 pending/done/abandoned，支持计划与实际对比", "资产可归档；归档资产可在资产列表用 Filters 检索"], "github_repository_id": 16508135, "homepage": "https://farmos.org", "id": "github:16508135", "leaf_matches": [{"reason": "Plant 资产按作物/品种建立种植批次，seeding、transplanting、input、observation、harvest 日志挂接该批次；作物季不是独立对象，由 Plant 资产、批次命名与日志近似承载。pending/done/abandoned 状态区分计划与实际，收获后可归档 Plant；归档资产可在资产列表用 Filters 检索。", "slug": "crop-management", "source_urls": ["https://farmos.org/guide/assets/plantings", "https://farmos.org/guide/logs", "https://farmos.org/model/type/log"]}, {"reason": "Land 资产是持久、可单独识别的地块记录，可映射并层级组织；Logs 与土壤检测挂接到地块；归档资产可在资产列表用 Filters 检索。页面只称可映射，未展示边界编辑、面积计算或按季几何版本化。", "slug": "field-management", "source_urls": ["https://farmos.org/guide/assets/plantings", "https://farmos.org/guide/logs", "https://farmos.org/model/type/log"]}, {"reason": "官方用户指南说明 farmOS 可管理动物/牲畜记录：动物可作为个体或可调头数资产，按群体组织，并用出生、医疗与移动日志形成带日期的事件历史。", "slug": "livestock-management", "source_urls": ["https://farmos.org/guide/assets/", "https://raw.githubusercontent.com/farmOS/farmOS/4.x/README.md"]}, {"reason": "官方 User Guide 显示 farmOS 以农场整体为范围管理位置/资产、计划、日志、数量与报告；Assets 文档列出 Land、Plants、Animals、Equipment 等管理单元；Logs 文档显示活动、观察、投入、收获、播种、实验室检测等记录与计划/待办共用同一记录循环；记录可关联资产与位置并回查历史。匹配农场管理平台的整场记录循环。", "slug": "farm-management-platform", "source_urls": ["https://farmOS.org/guide/", "https://raw.githubusercontent.com/farmOS/farmOS/4.x/README.md", "https://api.github.com/repos/farmOS/farmOS", "https://farmOS.org/guide/assets/", "https://farmOS.org/guide/logs/"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/farmOS/farmOS/license", "name": "farmOS", "repository_url": "https://github.com/farmOS/farmOS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:52:39.663924+08:00", "kind": "repository_metadata", "sha256": "bae6a7758c70366615865e997a77782fa937ef6ea20559be5984927a4ef703a3", "snapshot_path": "sources/bae6a7758c70366615865e997a77782fa937ef6ea20559be5984927a4ef703a3.txt", "url": "https://api.github.com/repos/farmOS/farmOS"}, {"fetched_at": "2026-10-26T21:52:40.008461+08:00", "kind": "license", "sha256": "7c4f6b823a4b929b2660bf9ab55b1298532df259ba914ba9543312804284494a", "snapshot_path": "sources/7c4f6b823a4b929b2660bf9ab55b1298532df259ba914ba9543312804284494a.txt", "url": "https://api.github.com/repos/farmOS/farmOS/license"}, {"fetched_at": "2026-10-26T21:52:39.637996+08:00", "kind": "readme", "sha256": "08b6b5d5518f01814ab994864a0e7ff5838569c505fef8e50ff2f653188f2277", "snapshot_path": "sources/08b6b5d5518f01814ab994864a0e7ff5838569c505fef8e50ff2f653188f2277.txt", "url": "https://raw.githubusercontent.com/farmOS/farmOS/2.x/README.md"}, {"fetched_at": "2026-10-26T21:52:55.226190+08:00", "kind": "documentation", "sha256": "13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c", "snapshot_path": "sources/13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c.txt", "url": "https://farmos.org/guide/assets/plantings"}, {"fetched_at": "2026-10-26T21:53:19.763160+08:00", "kind": "documentation", "sha256": "5103b74d8c037502ddc4bca681befd6f28688215fe2e09ca04dab36a576c6c3d", "snapshot_path": "sources/5103b74d8c037502ddc4bca681befd6f28688215fe2e09ca04dab36a576c6c3d.txt", "url": "https://farmos.org/guide/logs"}, {"fetched_at": "2026-10-26T21:53:19.860878+08:00", "kind": "documentation", "sha256": "21bb1ce754f8b3e0806d5ce814f189674f294ab6f2cf7ce23a55c476d48ed6d1", "snapshot_path": "sources/21bb1ce754f8b3e0806d5ce814f189674f294ab6f2cf7ce23a55c476d48ed6d1.txt", "url": "https://farmos.org/model/type/log"}, {"fetched_at": "2026-10-26T22:10:03.540680+08:00", "kind": "homepage", "sha256": "e6d54d72bf0f5d528a2654b398e749e6c872c38276d02a3f803f3aa5e87ae142", "snapshot_path": "sources/e6d54d72bf0f5d528a2654b398e749e6c872c38276d02a3f803f3aa5e87ae142.txt", "url": "https://farmos.org"}, {"fetched_at": "2026-10-26T22:10:57.942438+08:00", "kind": "readme", "sha256": "c2097cd86495dc9a6fca45989d8042b3f374844168c832cf0a5f62db6d9f5f25", "snapshot_path": "sources/c2097cd86495dc9a6fca45989d8042b3f374844168c832cf0a5f62db6d9f5f25.txt", "url": "https://raw.githubusercontent.com/farmOS/farmOS/4.x/README.md"}, {"fetched_at": "2026-10-26T22:10:59.830997+08:00", "kind": "documentation", "sha256": "13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c", "snapshot_path": "sources/13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c.txt", "url": "https://farmos.org/guide/assets/"}, {"fetched_at": "2026-10-26T22:32:17.740535+08:00", "kind": "documentation", "sha256": "e6d54d72bf0f5d528a2654b398e749e6c872c38276d02a3f803f3aa5e87ae142", "snapshot_path": "sources/e6d54d72bf0f5d528a2654b398e749e6c872c38276d02a3f803f3aa5e87ae142.txt", "url": "https://farmOS.org/"}, {"fetched_at": "2026-10-26T22:33:09.668846+08:00", "kind": "documentation", "sha256": "39c946ce47391dc6d13877509777b8d319b4f2f4043fa6cd21b7a51c2ceaae89", "snapshot_path": "sources/39c946ce47391dc6d13877509777b8d319b4f2f4043fa6cd21b7a51c2ceaae89.txt", "url": "https://farmOS.org/guide/"}, {"fetched_at": "2026-10-26T22:36:46.890275+08:00", "kind": "documentation", "sha256": "13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c", "snapshot_path": "sources/13c4570b668188ed936eab05347cb99c69f5e4a7f53885362ee547daf68b615c.txt", "url": "https://farmOS.org/guide/assets/"}, {"fetched_at": "2026-10-26T22:36:47.573075+08:00", "kind": "documentation", "sha256": "5103b74d8c037502ddc4bca681befd6f28688215fe2e09ca04dab36a576c6c3d", "snapshot_path": "sources/5103b74d8c037502ddc4bca681befd6f28688215fe2e09ca04dab36a576c6c3d.txt", "url": "https://farmOS.org/guide/logs/"}], "summary": "GPL-2.0 开源、可自托管的农场记录与计划 Web 应用；以 Land 资产保存地块，以 Plant 资产和日志承载作物季（非独立对象）的种植、投入、观察与收获，并支持计划/实际状态与历史留存。", "technology_stack": ["PHP", "Drupal", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:croptracker','Croptracker Spray','{"homepage": "https://www.croptracker.com", "id": "commercial:croptracker", "leaf_matches": [{"reason": "官方正文覆盖施药日期/地点/天气、化学品清单与施用历史、PHI/REI、工单与 USDA/GAP 审计报告，构成处理记录与合规输出核心；受管产品登记号层未明确展示，关系按已验证范围收窄。", "slug": "crop-protection-management", "source_urls": ["https://www.croptracker.com/product/farm-management-software/spray-record-keeping.html"]}, {"reason": "官方 Harvest Management 页面以收获作业记录为核心：按 block/variety/row 记录产量，bin tag 转为数字库存，并覆盖采收到 dock handoff 的批次追溯，符合收获管理的采摘事件与已识别收获库存核心。", "slug": "harvest-management", "source_urls": ["https://www.croptracker.com/product/harvest-management-software.html"]}, {"reason": "官方果园页面记录喷雾/施肥及其再入与采收间隔、修剪/疏果/割草等生产实践、按 block 与 picker 的采收产量和季节表现，具备持久果园资产、周期作业与收获归集的果园管理核心。", "slug": "orchard-management", "source_urls": ["https://www.croptracker.com/product/orchard-management-software.html"]}], "name": "Croptracker Spray", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T21:53:40.629700+08:00", "kind": "documentation", "sha256": "f9b8b08785a917108687211eee4977760e5bdae8059cecabebf908813ad67e9d", "snapshot_path": "sources/f9b8b08785a917108687211eee4977760e5bdae8059cecabebf908813ad67e9d.txt", "url": "https://www.croptracker.com/product/farm-management-software/spray-record-keeping.html"}, {"fetched_at": "2026-10-26T21:58:23.793823+08:00", "kind": "documentation", "sha256": "5753c08cbe3990491aeacb5b57ea9748db7dce630c4612f8df03a56a99e94a19", "snapshot_path": "sources/5753c08cbe3990491aeacb5b57ea9748db7dce630c4612f8df03a56a99e94a19.txt", "url": "https://www.croptracker.com/product/harvest-management-software.html"}, {"fetched_at": "2026-10-26T22:00:34.324457+08:00", "kind": "documentation", "sha256": "4cee217818b9441d74818c95906ca892e1a30947a2283acfe0bdd7002f4c6e81", "snapshot_path": "sources/4cee217818b9441d74818c95906ca892e1a30947a2283acfe0bdd7002f4c6e81.txt", "url": "https://www.croptracker.com/product/orchard-management-software.html"}], "summary": "面向果蔬种植者的云端喷药记录与合规模块，记录施药日期、时间、地点、化学品与设备，管理 PHI/REI、工单、化学品清单并生成 USDA/GAP 审计报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:cepaos-vinedo','Cepaos Vinedo','{"homepage": "https://www.cepaos.com/en-US/addons/vinedo", "id": "commercial:cepaos-vinedo", "leaf_matches": [{"reason": "以地块为持久资产，覆盖品种/面积/根砧/种植年份、按地块的栽培与物候作业、按地块采收与产量，并将地块果实关联到酒窖批次，符合葡萄园管理核心。", "slug": "vineyard-management", "source_urls": ["https://www.cepaos.com/en-US/addons/vinedo"]}], "name": "Cepaos Vinedo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:06:58.311641+08:00", "kind": "homepage", "sha256": "275149949635b44c159fb840b427e3bf91a1d1e5678843601bd5588fb2125c29", "snapshot_path": "sources/275149949635b44c159fb840b427e3bf91a1d1e5678843601bd5588fb2125c29.txt", "url": "https://www.cepaos.com/en-US/addons/vinedo"}], "summary": "Cepaos Vinedo 是面向酒庄的葡萄园管理附加模块：按区块保存品种、面积、根砧、种植年份与行，记录修剪/冠层/灌溉/物候与喷洒，并按地块记录采收产量并关联酒窖批次。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1111749091','fishfarm','{"deployment": ["Docker Compose：PHP 7.4 + Apache，映射 8000 端口", "标准 PHP Web 服务器 + MySQL"], "features": ["养殖场、养殖单元与池塘/网箱档案", "生产周期及放养/现存数量、状态", "放养记录（物种、数量、来源、成本）", "投喂、死亡、水质、健康与生物安全日志", "收获记录（日期、公斤、售价）并归属生产周期", "饲料与物资库存、成本/KPI 控制器"], "github_repository_id": 1111749091, "homepage": "https://github.com/JavisOTie/fishfarm", "id": "github:1111749091", "leaf_matches": [{"reason": "以池塘/网箱等生产单元和生产周期为核算单位，记录放养、现存数量、投喂、死亡、水质与收获，形成周期存栏与产出闭环，符合水产养殖管理核心。", "slug": "aquaculture-management", "source_urls": ["https://raw.githubusercontent.com/JavisOTie/fishfarm/main/models/PondCycles.php", "https://raw.githubusercontent.com/JavisOTie/fishfarm/main/models/PondsOrCages.php", "https://raw.githubusercontent.com/JavisOTie/fishfarm/main/models/HarvestRecords.php", "https://raw.githubusercontent.com/JavisOTie/fishfarm/main/models/StockingRecords.php"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/JavisOTie/fishfarm/license", "name": "fishfarm", "repository_url": "https://github.com/JavisOTie/fishfarm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:04:58.037242+08:00", "kind": "repository_metadata", "sha256": "3badfb70e214b1b81b9b87862fc6f673c3dc19d6a753c881875765dc3cf24f8f", "snapshot_path": "sources/3badfb70e214b1b81b9b87862fc6f673c3dc19d6a753c881875765dc3cf24f8f.txt", "url": "https://api.github.com/repos/JavisOTie/fishfarm"}, {"fetched_at": "2026-10-26T22:04:59.434695+08:00", "kind": "readme", "sha256": "4370ad8ce1c8df2da0827a7dcfddc55e2b6c881bfcd45fbe1e9504fc1ac2b780", "snapshot_path": "sources/4370ad8ce1c8df2da0827a7dcfddc55e2b6c881bfcd45fbe1e9504fc1ac2b780.txt", "url": "https://raw.githubusercontent.com/JavisOTie/fishfarm/main/README.md"}, {"fetched_at": "2026-10-26T22:05:01.250303+08:00", "kind": "license", "sha256": "94f2d56ca65e8c38056981cf5208ef0cdc491073e15c747612d2549b6413e2fa", "snapshot_path": "sources/94f2d56ca65e8c38056981cf5208ef0cdc491073e15c747612d25