INSERT INTO "application" VALUES('github:160875998','BoviBook','{"deployment": ["自托管 Web 应用：Apache + PHP，PostgreSQL 数据库（README 安装步骤）"], "features": ["个体牛只档案与出生/死亡/离群记录", "泌乳期与产奶量、乳成分记录", "配种、孕检与繁殖等待期计算", "健康治疗与药物停奶/干奶标记", "日粮配方、饲料成本与每头牛营养视图", "按牛群/批次的查询与报表"], "github_repository_id": 160875998, "homepage": "https://github.com/wandc/bovibook", "id": "github:160875998", "leaf_matches": [{"reason": "以个体牛只档案为记录单位，按泌乳期记录产奶与乳成分，保存配种/孕检/健康治疗/分群事件，并由事件派生繁殖与干奶等日常工作清单，符合奶牛场管理核心。", "slug": "dairy-farm-management", "source_urls": ["https://raw.githubusercontent.com/wandc/bovibook/master/Setup/bovibook-schema.sql", "https://raw.githubusercontent.com/wandc/bovibook/master/README.txt"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/wandc/bovibook/license", "name": "BoviBook", "repository_url": "https://github.com/wandc/bovibook", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:04:46.602867+08:00", "kind": "repository_metadata", "sha256": "5982ce7583d4b4e1645623f88093c64b92f95fff9de98b907ae0bdfd3ce1f559", "snapshot_path": "sources/5982ce7583d4b4e1645623f88093c64b92f95fff9de98b907ae0bdfd3ce1f559.txt", "url": "https://api.github.com/repos/wandc/bovibook"}, {"fetched_at": "2026-10-26T22:04:48.097798+08:00", "kind": "readme", "sha256": "c41ef600a27dec4931af2e966343ada11a533abbd91d6ee5a5f41f0b68b87d3f", "snapshot_path": "sources/c41ef600a27dec4931af2e966343ada11a533abbd91d6ee5a5f41f0b68b87d3f.txt", "url": "https://raw.githubusercontent.com/wandc/bovibook/master/README.txt"}, {"fetched_at": "2026-10-26T22:04:51.703653+08:00", "kind": "license", "sha256": "5d3d1098864e830ff62b48f200d5b237f8b7891b5e18556b2357c13924e33c7a", "snapshot_path": "sources/5d3d1098864e830ff62b48f200d5b237f8b7891b5e18556b2357c13924e33c7a.txt", "url": "https://api.github.com/repos/wandc/bovibook/license"}, {"fetched_at": "2026-10-26T22:04:55.183972+08:00", "kind": "documentation", "sha256": "b73fed574095a2dbfd90ebc4921f7f10649d34d05ce37dfdf46cc99be717fcc0", "snapshot_path": "sources/b73fed574095a2dbfd90ebc4921f7f10649d34d05ce37dfdf46cc99be717fcc0.txt", "url": "https://raw.githubusercontent.com/wandc/bovibook/master/Setup/bovibook-schema.sql"}], "summary": "BoviBook 是面向奶牛场的开源牛群管理 Web 应用，围绕个体牛只档案记录泌乳期、产奶量、繁殖、孕检、健康治疗与日粮营养，并生成日常牛群工作报表。", "technology_stack": ["PHP", "PostgreSQL", "Apache"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dinamica-generale-dtm','DTM (Daily TMR Manager)','{"homepage": "https://www.dinamicagenerale.com/product/dtm-software/", "id": "commercial:dinamica-generale-dtm", "leaf_matches": [{"reason": "以饲料原料与日粮配方为计划记录，绑定饲喂群体与库存，并记录装载、配送、实际用量、拒食与损耗，使饲料成本与执行差异可计算，符合饲料管理核心。", "slug": "feed-management", "source_urls": ["https://www.dinamicagenerale.com/product/dtm-software/", "https://www.dinamicagenerale.com/resource/feed-management-software-faqs-everything-dairy-farmers-need-to-know/"]}], "name": "DTM (Daily TMR Manager)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:07:01.368318+08:00", "kind": "homepage", "sha256": "216ac72ce272a01aed3fc3602023c0388a8fbcdc41c1465453df1bb806238486", "snapshot_path": "sources/216ac72ce272a01aed3fc3602023c0388a8fbcdc41c1465453df1bb806238486.txt", "url": "https://www.dinamicagenerale.com/product/dtm-software/"}, {"fetched_at": "2026-10-26T22:07:05.619966+08:00", "kind": "documentation", "sha256": "0ee6ac5c6673a546ec1733e98e84b78cd8e6c8bea23e5a26fa6832ec2e585368", "snapshot_path": "sources/0ee6ac5c6673a546ec1733e98e84b78cd8e6c8bea23e5a26fa6832ec2e585368.txt", "url": "https://www.dinamicagenerale.com/resource/feed-management-software-faqs-everything-dairy-farmers-need-to-know/"}], "summary": "DTM（Daily TMR Manager）是 Dinamica Generale 的云端饲喂管理软件，连接日粮配方、饲料库存、装载/配送执行与绩效分析，记录计划与实际用量、拒食、采食与饲料成本。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:trackwell-fims','Trackwell FiMS','{"homepage": "https://trackwellfims.com/", "id": "commercial:trackwell-fims", "leaf_matches": [{"reason": "以渔业主管机构为使用方，管理渔船登记与捕捞许可/授权、电子渔获报告与日志，并对照配额/规则进行核查、告警和监管报表，覆盖渔业治理框架、捕捞记录与管理闭环。", "slug": "fisheries-management", "source_urls": ["https://trackwellfims.com/fisheries-management-systems/", "https://trackwellfims.com/fisheries-management-systems/vms/"]}], "name": "Trackwell FiMS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:04:38.694833+08:00", "kind": "homepage", "sha256": "6e4afead9eb1cec9c2067463320440f2f6593b07e44d025ca019764df43bc276", "snapshot_path": "sources/6e4afead9eb1cec9c2067463320440f2f6593b07e44d025ca019764df43bc276.txt", "url": "https://trackwellfims.com/"}, {"fetched_at": "2026-10-26T22:04:41.423027+08:00", "kind": "documentation", "sha256": "2151914f7dd5b197dc1eb73c514d18220a727c8249d079588a3375e73b47a37a", "snapshot_path": "sources/2151914f7dd5b197dc1eb73c514d18220a727c8249d079588a3375e73b47a37a.txt", "url": "https://trackwellfims.com/fisheries-management-systems/"}, {"fetched_at": "2026-10-26T22:04:44.854273+08:00", "kind": "documentation", "sha256": "6733211be6894458e8fae637b2763ed574d5e0d9cf1dc99993bf693c8ad52ec4", "snapshot_path": "sources/6733211be6894458e8fae637b2763ed574d5e0d9cf1dc99993bf693c8ad52ec4.txt", "url": "https://trackwellfims.com/fisheries-management-systems/vms/"}], "summary": "Trackwell FiMS 是面向渔业主管机构与区域渔业组织的渔业管理软件套件，整合渔船监测、电子报告/电子日志、渔船登记与捕捞许可，并支持配额执法、告警、审计与监管报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1211653818','Poultry Farm Tracker','{"deployment": ["AWS serverless（S3/CloudFront、API Gateway、Lambda、DynamoDB，通过 AWS CDK 部署）"], "features": ["肉鸡批次从入雏到出栏的全周期记录", "FCR、单只成本与预计收入", "蛋鸡舍产蛋率与换羽支持", "每日饲料、饮水、死淘与产蛋录入", "死亡率与产量预警", "多批次与多角色团队"], "github_repository_id": 1211653818, "homepage": "https://github.com/tino1b2be/poultry-farm-tracker", "id": "github:1211653818", "leaf_matches": [{"reason": "README 将肉鸡按 batch、蛋鸡按 house 建模，记录每日饲料/饮水/死淘/产蛋并计算 FCR、产蛋率与周期预警，符合舍内禽群与周期绩效管理的核心。", "slug": "poultry-farm-management", "source_urls": ["https://raw.githubusercontent.com/tino1b2be/poultry-farm-tracker/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/tino1b2be/poultry-farm-tracker/license", "name": "Poultry Farm Tracker", "repository_url": "https://github.com/tino1b2be/poultry-farm-tracker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:11:01.290014+08:00", "kind": "repository_metadata", "sha256": "179aa899fee0313d9bf48aa3b0d92ac4d082055d913201f6cffe5a09029a02d3", "snapshot_path": "sources/179aa899fee0313d9bf48aa3b0d92ac4d082055d913201f6cffe5a09029a02d3.txt", "url": "https://api.github.com/repos/tino1b2be/poultry-farm-tracker"}, {"fetched_at": "2026-10-26T22:11:03.183598+08:00", "kind": "license", "sha256": "8ff5566abe387d909fb4fd9c8180d839a7e121069cefd200babead7dac932e0d", "snapshot_path": "sources/8ff5566abe387d909fb4fd9c8180d839a7e121069cefd200babead7dac932e0d.txt", "url": "https://api.github.com/repos/tino1b2be/poultry-farm-tracker/license"}, {"fetched_at": "2026-10-26T22:11:04.744987+08:00", "kind": "readme", "sha256": "3e04799f48062623b021c4b417177c07e8df4409c5b0a0eadce420c61289f6be", "snapshot_path": "sources/3e04799f48062623b021c4b417177c07e8df4409c5b0a0eadce420c61289f6be.txt", "url": "https://raw.githubusercontent.com/tino1b2be/poultry-farm-tracker/main/README.md"}], "summary": "开源、移动优先的家禽养殖记录与绩效应用，围绕肉鸡批次和蛋鸡舍记录每日饲料、饮水、死淘与产蛋，计算饲料转化率并生成批次/农场报表，支持多批次并行和预警。", "technology_stack": ["React", "TypeScript", "AWS Lambda", "DynamoDB", "AWS CDK"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:mtech-systems-swine','MTech Systems Swine','{"homepage": "https://mtechsystems.io/", "id": "commercial:mtech-systems-swine", "leaf_matches": [{"reason": "官方猪业产品页正文覆盖母猪场、Breed to Wean、Wean to Harvest，按 Barn/Room 追踪 ADG/FCR/死亡率，并做个体母猪与仔猪跟踪，属于猪只生产管理系统。", "slug": "swine-management", "source_urls": ["https://mtechsystems.io/p-2/swine/swine-solutions/industrys-best-pig-farm-management-system"]}], "name": "MTech Systems Swine", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:11:10.125295+08:00", "kind": "documentation", "sha256": "bbb05616d1d8df0dd4c2f9dbd0e6a9f3404c17363acc95f2fac3ff7d6ee23b3b", "snapshot_path": "sources/bbb05616d1d8df0dd4c2f9dbd0e6a9f3404c17363acc95f2fac3ff7d6ee23b3b.txt", "url": "https://mtechsystems.io/p-2/swine/swine-solutions/industrys-best-pig-farm-management-system"}], "summary": "面向养猪生产的商业管理软件，覆盖母猪场繁殖、断奶到育肥、遗传、饲料营养、加工与库存，支持个体母猪性能、按猪舍/房间追踪 ADG、FCR 和死亡率，并提供可追溯与成本核算。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1294173298','BrewLedger','{"deployment": ["自托管 API 服务与 Web 控制台"], "features": ["库存台账（收货、消耗、转移、盘点）", "批次跟踪：配方、容器、读数、里程碑、生产完成", "TTB 5130.9 表单字段映射辅助", "酒馆/出酒与容器占用管理", "离线优先客户端与多设备同步"], "github_repository_id": 1294173298, "homepage": "https://getbrewledger.com", "id": "github:1294173298", "leaf_matches": [{"reason": "README 明确提供配方与批次跟踪（容器、读数、里程碑、生产完成）以及库存台账，覆盖配方驱动批次生命周期和物料库存两侧。", "slug": "brewery-management", "source_urls": ["https://raw.githubusercontent.com/jackjusko/brewledger-oss/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/jackjusko/brewledger-oss/license", "name": "BrewLedger", "repository_url": "https://github.com/jackjusko/brewledger-oss", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:11:11.556848+08:00", "kind": "repository_metadata", "sha256": "bbed6d757b5fe2f8659509f1b41701006be57c5d57f9e1431b0b69cd406726e2", "snapshot_path": "sources/bbed6d757b5fe2f8659509f1b41701006be57c5d57f9e1431b0b69cd406726e2.txt", "url": "https://api.github.com/repos/jackjusko/brewledger-oss"}, {"fetched_at": "2026-10-26T22:11:13.429295+08:00", "kind": "license", "sha256": "bc731cec266127ba06558b22581c2597884e35332fe895ff4982148f6f505857", "snapshot_path": "sources/bc731cec266127ba06558b22581c2597884e35332fe895ff4982148f6f505857.txt", "url": "https://api.github.com/repos/jackjusko/brewledger-oss/license"}, {"fetched_at": "2026-10-26T22:11:15.255006+08:00", "kind": "readme", "sha256": "d3f3eaeb4cbb836f88e20c2a5bb7aa21501dd9b3bbee86eee0264142f2469010", "snapshot_path": "sources/d3f3eaeb4cbb836f88e20c2a5bb7aa21501dd9b3bbee86eee0264142f2469010.txt", "url": "https://raw.githubusercontent.com/jackjusko/brewledger-oss/master/README.md"}], "summary": "开源、可自托管的酿酒厂运营平台，围绕配方与批次管理库存、容器、过程读数、生产里程碑和包装完成流程，并提供酒馆/出酒与多设备离线同步。", "technology_stack": ["Node.js", "Express 5", "SQLite", "Vue 3", "Capacitor 6"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:meez','meez','{"homepage": "https://www.getmeez.com/", "id": "commercial:meez", "leaf_matches": [{"reason": "官方页面展示以配方为记录、按批量/份数缩放并执行每日预制生产，连接成本与库存，属于专业厨房后台生产管理而非 POS/KDS。", "slug": "commercial-kitchen-management", "source_urls": ["https://www.getmeez.com/", "https://www.getmeez.com/daily-production", "https://www.getmeez.com/scaling"]}], "name": "meez", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:14:41.252390+08:00", "kind": "homepage", "sha256": "15b04d1225a37b757023d8489cc3c7fc21bdc0eacbad03caaa1a44081bd570de", "snapshot_path": "sources/15b04d1225a37b757023d8489cc3c7fc21bdc0eacbad03caaa1a44081bd570de.txt", "url": "https://www.getmeez.com/"}, {"fetched_at": "2026-10-26T22:12:18.328591+08:00", "kind": "documentation", "sha256": "0b63bd0a85db8dbbe6c1c6aad4ac062203bbb118e0bf702cc6c70785fcbc6182", "snapshot_path": "sources/0b63bd0a85db8dbbe6c1c6aad4ac062203bbb118e0bf702cc6c70785fcbc6182.txt", "url": "https://www.getmeez.com/daily-production"}, {"fetched_at": "2026-10-26T22:12:21.549722+08:00", "kind": "documentation", "sha256": "31ef31c1f291d9043631eda992e2e4c736f0d9e27540ef23efa4eae6d6bb7e93", "snapshot_path": "sources/31ef31c1f291d9043631eda992e2e4c736f0d9e27540ef23efa4eae6d6bb7e93.txt", "url": "https://www.getmeez.com/scaling"}], "summary": "面向餐厅与多门店厨房的云端配方及生产执行软件，集中管理配方、按份量缩放与每日预制执行，连接成本、库存、过敏原与营养信息，并支持菜单工程和厨房培训。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sonicu','Sonicu','{"homepage": "https://www.sonicu.com/", "id": "commercial:sonicu", "leaf_matches": [{"reason": "官方 HACCP 页面说明 SoniCloud 持续监测冰箱、冷库和备餐区温度，按 HACCP 范围配置阈值，提供电话/短信/邮件/应用告警与升级路径，并自动生成带纠正措施记录、可导出审计的数字日志，覆盖食品运营者自有的冷链资产、温度要求、偏离响应与留存记录四个核心结构。", "slug": "food-cold-chain-management", "source_urls": ["https://www.sonicu.com/solutions/regulatory-compliance-reporting/haccp"]}], "name": "Sonicu", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:10:09.331104+08:00", "kind": "documentation", "sha256": "aa782b50f995d73972b1c9b748b35f653cf73e28c5c70e034d09ae7c1cddadaa", "snapshot_path": "sources/aa782b50f995d73972b1c9b748b35f653cf73e28c5c70e034d09ae7c1cddadaa.txt", "url": "https://www.sonicu.com/solutions/regulatory-compliance-reporting/haccp"}], "summary": "面向食品服务与食品储藏场景的云端温度/湿度监控平台，持续监测冰箱、冷库与备餐区，按 HACCP 阈值告警并生成带纠正措施记录的数字日志。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:brix','Brix','{"homepage": "https://brixsoftware.com/", "id": "commercial:brix", "leaf_matches": [{"reason": "官网说明 Brix 以原料库中的供应商、成本、营养与理化数据为基底，用子配方嵌套构建成品配方；改动任一行即重算总固形物、脂肪、蛋白、糖、密度、成本与热量，并从同一配方产出营养标签、配料表、BOM 和批次表，符合“配方记录＋成分基底＋成分驱动评估”的定义核心。", "slug": "food-formulation-platform", "source_urls": ["https://brixsoftware.com/"]}], "name": "Brix", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:09:53.583917+08:00", "kind": "homepage", "sha256": "29b3f6f2f04c09f65dbe5ddde45ff1361b6000baa1f60023dec09ba86eabdd2a", "snapshot_path": "sources/29b3f6f2f04c09f65dbe5ddde45ff1361b6000baa1f60023dec09ba86eabdd2a.txt", "url": "https://brixsoftware.com/"}], "summary": "面向食品研发团队的配方管理与配方计算平台，以原料库构建子配方和成品配方，实时重算营养、成本与理化指标，并输出营养标签、配料表、BOM 和批次表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:recipal','ReciPal','{"homepage": "https://www.recipal.com/", "id": "commercial:recipal", "leaf_matches": [{"reason": "官网说明 ReciPal 将配方、原料数据库、批次产量与份量作为标签承载数据，自动应用 FDA 和 CFIA 的舍入与格式规则，生成营养声明、配料表和过敏原声明，并支持多种标签版式与打印用 PDF/PNG 导出；配方和标签保存在云端，构成从产品数据到合规标签制品的标签生产链。", "slug": "food-labeling-platform", "source_urls": ["https://www.recipal.com/"]}], "name": "ReciPal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:09:53.250137+08:00", "kind": "homepage", "sha256": "be15b9362b75fc66e12685afb840c56e27672f26372dcbce459e8032dcca4602", "snapshot_path": "sources/be15b9362b75fc66e12685afb840c56e27672f26372dcbce459e8032dcca4602.txt", "url": "https://www.recipal.com/"}], "summary": "面向食品企业的云端营养标签与配方管理系统，从配方、原料、批次产量和份量计算营养，自动应用 FDA/CFIA 规则并生成营养声明、配料表与过敏原声明，可导出 PDF/PNG。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:becpg','beCPG','{"homepage": "https://www.becpg.net/", "id": "commercial:becpg", "leaf_matches": [{"reason": "beCPG 官方 PLM 页面说明其以产品库集中原料、成品、包装和文档，配方改动会实时重算成本、营养和过敏原，规格、包装 BOM、项目与供应商数据关联在同一产品记录，并保留完整变更历史，通过 REST API/ERP/GS1 连接器把已发布定义交给下游；对应食品 PLM 的产品记录、受控定义与开发到上市生命周期。", "slug": "food-plm", "source_urls": ["https://www.becpg.net/plm-software/"]}], "name": "beCPG", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:10:08.827141+08:00", "kind": "documentation", "sha256": "7b979fa0dfb1b023f4d6500a7a72ce8196cf974fc866ab0e6ab718ecffe956c3", "snapshot_path": "sources/7b979fa0dfb1b023f4d6500a7a72ce8196cf974fc866ab0e6ab718ecffe956c3.txt", "url": "https://www.becpg.net/plm-software/"}], "summary": "面向食品、饮料与化妆品的产品生命周期管理（PLM）平台，集中产品记录、配方、规格、包装、法规数据与项目协作，提供 SaaS 和本地部署。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:recall-infolink','Recall InfoLink','{"homepage": "https://www.recallinfolink.com/", "id": "commercial:recall-infolink", "leaf_matches": [{"reason": "官网正文列出结构化召回录入、受影响方联系人导入、多渠道通知、响应跟踪与自动提醒、行动核实和合规报告，覆盖召回事件→范围→通知/响应/验证闭环。", "slug": "food-recall-management", "source_urls": ["https://www.recallinfolink.com/"]}], "name": "Recall InfoLink", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:19:57.719635+08:00", "kind": "homepage", "sha256": "d22496e1b097e5f79b2ecf358848ba24875453a60fca95758f4b18a4ba43b06c", "snapshot_path": "sources/d22496e1b097e5f79b2ecf358848ba24875453a60fca95758f4b18a4ba43b06c.txt", "url": "https://www.recallinfolink.com/"}], "summary": "产品召回管理系统，支持结构化录入召回事件、导入受影响方名单、通过邮件/短信/电话/传真通知、跟踪响应与提醒、核实受影响产品已移除/处置并生成合规报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fooddocs','FoodDocs','{"homepage": "https://www.fooddocs.com/", "id": "commercial:fooddocs", "leaf_matches": [{"reason": "官网正文提供 HACCP 计划、监控任务/日志、温度记录、纠正措施、供应商与追溯文档及多地点合规总览，匹配食品安全项目的常设记录与验证闭环。", "slug": "food-safety-management", "source_urls": ["https://www.fooddocs.com/"]}, {"reason": "官方 HACCP 产品页明确列出危害分析、关键控制点、关键限值、监控程序、纠正行动计划、验证程序和记录留存，并说明可在同一平台建立计划、监控 CCP 与管理食品安全记录，符合 HACCP 计划及执行记录的核心。", "slug": "haccp-management", "source_urls": ["https://www.fooddocs.com/haccp"]}], "name": "FoodDocs", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:18:27.346347+08:00", "kind": "homepage", "sha256": "67fd79d3959b827b0844b287faa7027cdf88901dd4a33881b02565c501caed85", "snapshot_path": "sources/67fd79d3959b827b0844b287faa7027cdf88901dd4a33881b02565c501caed85.txt", "url": "https://www.fooddocs.com/"}, {"fetched_at": "2026-10-26T22:22:37.647681+08:00", "kind": "homepage", "sha256": "a5a38192f8b82193c3fee0f44bcff96b8ff642d2d2af1cf0a9e4432d2e95c588", "snapshot_path": "sources/a5a38192f8b82193c3fee0f44bcff96b8ff642d2d2af1cf0a9e4432d2e95c588.txt", "url": "https://www.fooddocs.com/haccp"}], "summary": "食品安全管理系统，提供 HACCP 计划、数字化监控任务与日志、温度记录、纠正措施、供应商与追溯文档，以及多地点实时合规总览。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tracegains','TraceGains','{"homepage": "https://tracegains.com/", "id": "commercial:tracegains", "leaf_matches": [{"reason": "官网规格管理页正文描述规格模板与属性、版本/状态、受影响规格自动更新、供应商文件、提醒/通知、审计追踪与往来记录，匹配规格记录→版本治理→贸易伙伴交换核心。", "slug": "food-specification-management", "source_urls": ["https://tracegains.com/resource/specification-management/"]}], "name": "TraceGains", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:18:30.708080+08:00", "kind": "documentation", "sha256": "99fe70953be21c2fe4152905629f154ede9f3fdac614d2c40485e4e887f9220a", "snapshot_path": "sources/99fe70953be21c2fe4152905629f154ede9f3fdac614d2c40485e4e887f9220a.txt", "url": "https://tracegains.com/resource/specification-management/"}], "summary": "面向食品饮料企业的规格管理系统，以结构化模板维护规格及版本/状态，联动供应商文件并自动更新受影响规格，支持告警、通知和审计追踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:trustwell-foodlogiq-traceability','Trustwell FoodLogiQ Traceability','{"homepage": "https://www.trustwell.com/", "id": "commercial:trustwell-foodlogiq-traceability", "leaf_matches": [{"reason": "官网正文明确按 batch-lot 级别正反向追溯、采集/共享 CTE、识别数据缺口、跨供应链伙伴查看产品去向并导出 FSMA 204 记录，匹配批次台账+跨伙伴链接+双向追溯核心。", "slug": "food-traceability-platform", "source_urls": ["https://www.trustwell.com/products/foodlogiq/traceability/"]}], "name": "Trustwell FoodLogiQ Traceability", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:20:30.406165+08:00", "kind": "documentation", "sha256": "f099d6267edb5de5cfaf09579947016a58c4173e646d73a2df5ce619cd97b788", "snapshot_path": "sources/f099d6267edb5de5cfaf09579947016a58c4173e646d73a2df5ce619cd97b788.txt", "url": "https://www.trustwell.com/products/foodlogiq/traceability/"}], "summary": "面向食品供应链的批次级追溯平台，采集并共享关键追踪事件（CTE），支持正反向批次追溯、合作伙伴数据链接、缺口识别与 FSMA 204 导出。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
