INSERT INTO "application" VALUES('commercial:nutritics','Nutritics','{"homepage": "https://www.nutritics.com/en/product/nutritics-recipe-and-menu-management/", "id": "commercial:nutritics", "leaf_matches": [{"reason": "官方页面说明以超过一百万种食物、258 种营养素的成分数据库计算配方与菜单营养；食品服务页明确自动计算营养、热量和过敏原并发布合规标签，医疗页说明患者膳食报告，具备被分析组合、营养参考基底和计算结果的完整分析链。", "slug": "nutrition-analysis-application", "source_urls": ["https://www.nutritics.com/en/product/nutritics-recipe-and-menu-management/", "https://www.nutritics.com/en/sectors/healthcare/", "https://www.nutritics.com/en/sectors/food-service/"]}], "name": "Nutritics", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:22:34.315131+08:00", "kind": "homepage", "sha256": "faf3372af415e078589163d55a263ea9fdd1c311cce37eb3cbe0a3dda8b007cf", "snapshot_path": "sources/faf3372af415e078589163d55a263ea9fdd1c311cce37eb3cbe0a3dda8b007cf.txt", "url": "https://www.nutritics.com/en/product/nutritics-recipe-and-menu-management/"}, {"fetched_at": "2026-10-26T22:23:15.739765+08:00", "kind": "documentation", "sha256": "6058e85298031d0edfd4d7ff359807753226dbca34ef371d9985261f50a9332c", "snapshot_path": "sources/6058e85298031d0edfd4d7ff359807753226dbca34ef371d9985261f50a9332c.txt", "url": "https://www.nutritics.com/en/sectors/healthcare/"}, {"fetched_at": "2026-10-26T22:23:16.085165+08:00", "kind": "documentation", "sha256": "f45c3a37ce0cc7eb1d3a6f008915e071dac6537a4ee4decd75a9d028bd2e8a22", "snapshot_path": "sources/f45c3a37ce0cc7eb1d3a6f008915e071dac6537a4ee4decd75a9d028bd2e8a22.txt", "url": "https://www.nutritics.com/en/sectors/food-service/"}], "summary": "面向营养师、医疗与餐饮专业人员的营养分析平台，以大型食物成分数据库计算配方、菜单和患者膳食的营养与过敏原信息，并生成报告和标签。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vintrace','vintrace','{"homepage": "https://www.encompasstech.com/vintrace/wine-production-software", "id": "commercial:vintrace", "leaf_matches": [{"reason": "官方产品页说明可创建并分配酒窖工单，跟踪添加、罐内内容、橡木桶使用与分析，安排葡萄接收和压榨，管理装瓶、库存及物料批次，并输出合规报告，覆盖酒庄容器资产和酒窖操作记录的核心。", "slug": "winery-management", "source_urls": ["https://www.encompasstech.com/vintrace/wine-production-software"]}], "name": "vintrace", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:22:34.002512+08:00", "kind": "homepage", "sha256": "d8d460f0ceaadad209ab79da02184fd39a22c468ee5973b075ee4e4931a21b04", "snapshot_path": "sources/d8d460f0ceaadad209ab79da02184fd39a22c468ee5973b075ee4e4931a21b04.txt", "url": "https://www.encompasstech.com/vintrace/wine-production-software"}], "summary": "面向酒庄的云端生产管理系统，按工单管理酒罐与橡木桶内容、添加、葡萄接收与压榨、装瓶和库存，并生成合规与经营报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:remsoft-fms','Remsoft FMS','{"homepage": "https://remsoft.com/solutions/fms/", "id": "commercial:remsoft-fms", "leaf_matches": [{"reason": "官方 FMS 页面说明以林地与森林登记集中权属、环境文档和林分信息，结合森林资源调查、造林/施肥/病虫害等经营活动管理与综合森林规划，覆盖有地址的管理单元、立木资源和多年经营计划三项结构。", "slug": "forestry-management", "source_urls": ["https://remsoft.com/solutions/fms/"]}], "name": "Remsoft FMS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:22:45.786905+08:00", "kind": "homepage", "sha256": "04d619dbe9916ad6842df43e5c3ed361d0540bd10a699c4ae861f5e0e2f523bf", "snapshot_path": "sources/04d619dbe9916ad6842df43e5c3ed361d0540bd10a699c4ae861f5e0e2f523bf.txt", "url": "https://remsoft.com/solutions/fms/"}], "summary": "面向大型林业经营的森林管理平台，集中林地权属与林分登记、森林资源调查、造林与采伐活动计划，并支持长期经营规划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:remsoft-operations','Remsoft Operations','{"homepage": "https://remsoft.com/remsoft-operations/", "id": "commercial:remsoft-operations", "leaf_matches": [{"reason": "官方 Operations 页面说明围绕采伐单元、产品、班组与车队分配、运输成本和生产率管理多季作业，并整合采伐设备、班组、载荷与产量；LOGR 页面说明以单一可审计数字交付记录替代纸质票据并可与地磅、工厂系统及会计系统衔接，覆盖作业、归集生产与结算依据的核心。", "slug": "logging-operations-management", "source_urls": ["https://remsoft.com/remsoft-operations/", "https://remsoft.com/remsoft-logr/"]}], "name": "Remsoft Operations", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:22:35.462365+08:00", "kind": "homepage", "sha256": "ce0ac5f993484523a535695af54efdac900d73b48752a37bd2ba4b06d13ac6b5", "snapshot_path": "sources/ce0ac5f993484523a535695af54efdac900d73b48752a37bd2ba4b06d13ac6b5.txt", "url": "https://remsoft.com/remsoft-operations/"}, {"fetched_at": "2026-10-26T22:22:34.403108+08:00", "kind": "documentation", "sha256": "f23c975e2a3c994b83deab27053c412ef7890fa62d2e98f10daf75309323ce9f", "snapshot_path": "sources/f23c975e2a3c994b83deab27053c412ef7890fa62d2e98f10daf75309323ce9f.txt", "url": "https://remsoft.com/remsoft-logr/"}], "summary": "面向林业采运作业的云端运营系统，围绕采伐单元管理产品、班组与设备分配、产量和运输，并以数字交付记录连接采伐现场与工厂。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:maptek-vulcan','Maptek Vulcan','{"homepage": "https://www.maptek.com/", "id": "commercial:maptek-vulcan", "leaf_matches": [{"reason": "官方产品页将 Vulcan 定位为 3D mine planning、建模、矿山设计与 scheduling，并列出块模型操作、reserving capabilities、露天/地下设计和排程工具，匹配矿床模型→设计→储量→计划的核心链条。", "slug": "mine-planning-application", "source_urls": ["https://www.maptek.com/products/vulcan/"]}], "name": "Maptek Vulcan", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:21:54.556235+08:00", "kind": "homepage", "sha256": "00bc43219eda92da29d444f8cd97fd42debefc47310655cc240e031a57be85b5", "snapshot_path": "sources/00bc43219eda92da29d444f8cd97fd42debefc47310655cc240e031a57be85b5.txt", "url": "https://www.maptek.com/products/vulcan/"}], "summary": "商业矿山规划与三维建模软件，围绕矿床块模型提供露天/地下矿山设计、储量评估、排程与优化工具。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wenco-fms','Wenco Mining Fleet Management','{"homepage": "https://www.wencomine.com/", "id": "commercial:wenco-fms", "leaf_matches": [{"reason": "官网 FMS 页展示对卡车、挖掘机和辅助设备的拖拽式分配、班次中切换 assignments、锁定与限制，并实时跟踪 cycle times、payload compliance 与生产；设备分配循环明确，生产记录以设备/循环级跟踪呈现（页面未逐条列出装载记录字段）。", "slug": "mining-fleet-management", "source_urls": ["https://www.wencomine.com/our-solutions/mining-fleet-management"]}], "name": "Wenco Mining Fleet Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:20:11.788766+08:00", "kind": "homepage", "sha256": "de7788ac786e5f14e501e2bb9c4f4090aa207d1e3fb2e04029302e9517008655", "snapshot_path": "sources/de7788ac786e5f14e501e2bb9c4f4090aa207d1e3fb2e04029302e9517008655.txt", "url": "https://www.wencomine.com/our-solutions/mining-fleet-management"}], "summary": "商业矿山车队管理系统（FMS），面向露天矿卡车、挖掘机与辅助设备，提供实时调度分配、循环与产能跟踪、设备状态和报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:datamine-production','Datamine Production','{"homepage": "https://dataminesoftware.com/", "id": "commercial:datamine-production", "leaf_matches": [{"reason": "官网生产方案页把日常运营与班次执行、material tracking、inventory management、mine and material reconciliation with plan compliance、plant metals balancing and accounting 串成生产工作流，匹配生产记录+物料平衡→对账并产出可审计数字的核心。", "slug": "mining-operations-management", "source_urls": ["https://dataminesoftware.com/solutions/production"]}], "name": "Datamine Production", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:20:14.207214+08:00", "kind": "homepage", "sha256": "5cc8ff2c3b543004bf67ec85ab734ae50a5f6ccb36fe77207f7a9aabaff5dc57", "snapshot_path": "sources/5cc8ff2c3b543004bf67ec85ab734ae50a5f6ccb36fe77207f7a9aabaff5dc57.txt", "url": "https://dataminesoftware.com/solutions/production"}], "summary": "商业矿山生产与对账软件组合，覆盖班次执行、物料跟踪、库存与混配、矿山与工厂对账、金属核算和发运物流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:quorum-on-demand-land','Quorum On Demand Land','{"homepage": "https://www.quorumsoftware.com/", "id": "commercial:quorum-on-demand-land", "leaf_matches": [{"reason": "官网列出 leases、acquisitions、obligations、rights of way 的全生命周期，义务/租金/关井与连续作业条款、关键日期自动提醒、权属链和地块 GIS 关联，匹配资源权利+义务日历+生命周期核心。", "slug": "natural-resource-rights-management", "source_urls": ["https://www.quorumsoftware.com/solutions/upstream-on-demand/land"]}], "name": "Quorum On Demand Land", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:20:13.411871+08:00", "kind": "homepage", "sha256": "1a8dfce4497c8ebcdea0d8156a65dce860903399975555c14e88e78a0bf55f6e", "snapshot_path": "sources/1a8dfce4497c8ebcdea0d8156a65dce860903399975555c14e88e78a0bf55f6e.txt", "url": "https://www.quorumsoftware.com/solutions/upstream-on-demand/land"}], "summary": "商业上游油气土地与矿权管理云平台，记录租赁、取得、义务和通行权，提供关键日期提醒、文件/权属链和地块 GIS 关联。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:smsturbo-fulcrum','SMSTurbo Fulcrum','{"homepage": "https://www.smsturbo.com/", "id": "commercial:smsturbo-fulcrum", "leaf_matches": [{"reason": "官网采石场页明确面向 rock quarry，提供数字 scale tickets、卡车装载与调度、实时库存/堆场监控、发票和客户自助门户，匹配生产场地+票据化装载+场地物料账本核心。", "slug": "quarry-management", "source_urls": ["https://www.smsturbo.com/industries/rock-quarry-scale-ticketing"]}], "name": "SMSTurbo Fulcrum", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:21:35.201578+08:00", "kind": "homepage", "sha256": "238e88830824b1e53a0ada7cf4892bada15608a8e0c9ea15282ef06db453816e", "snapshot_path": "sources/238e88830824b1e53a0ada7cf4892bada15608a8e0c9ea15282ef06db453816e.txt", "url": "https://www.smsturbo.com/industries/rock-quarry-scale-ticketing"}], "summary": "商业采石场与骨料地磅开票运营软件，覆盖数字地磅票据、装载调度、库存与堆场监控、发票和客户自助查询。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:remsoft','Remsoft','{"homepage": "https://remsoft.com/", "id": "commercial:remsoft", "leaf_matches": [{"reason": "官网把木材流动规划（Tactical Optimization: Integrated Harvest, Roads and Wood Flow Planning）与从森林到工厂的多方装载记录放在同一平台：forest owners、contractors、mills 共享每次装载记录，并连接路线规划、调度、称重验证和交付协调。该快照支持分配计划与装载/交付执行两个核心；未明确展示 roadside/rolling/yard/mill 的节点级库存画面，因此不把链上库存写成已完整覆盖。", "slug": "timber-supply-chain-management", "source_urls": ["https://remsoft.com/"]}], "name": "Remsoft", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:30:49.572134+08:00", "kind": "homepage", "sha256": "6c3e496028e9dc1dcc96b634813d2f57914568d3cc7d8cf4d9eea7945e9f5b13", "snapshot_path": "sources/6c3e496028e9dc1dcc96b634813d2f57914568d3cc7d8cf4d9eea7945e9f5b13.txt", "url": "https://remsoft.com/"}], "summary": "面向林业的森林规划与木材供应链平台：Woodstock 做采伐、道路与木材流动的整合规划；Operations/Logistics 提供从森林到工厂的多方数字化装载记录、路线与调度、称重验证和交付协调。官网仅用于基本类型核对，未验证部署或价格。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1150674441','FarmInsight','{"deployment": ["Django 后端与 React 前端分别启动；InfluxDB 可用 Docker Compose 运行"], "features": ["HTTP 与 MQTT 传感器接入，支持 10+ 传感器型号", "实时遥测看板与历史趋势", "按设施配置的阈值警报与通知", "基于间隔、时间、传感器阈值的自动控制", "多租户组织与 Admin/Member 角色"], "github_repository_id": 1150674441, "homepage": "https://farminsight.etce-lab.de", "id": "github:1150674441", "leaf_matches": [{"reason": "README 展示了设备/传感器接入、实时与历史遥测、按设施阈值警报、通知和自动控制，构成农业 IoT 平台所需的设备集群、遥测、监控界面和警报闭环。", "slug": "agricultural-iot-platform", "source_urls": ["https://api.github.com/repos/ETCE-LAB/FarmInsight", "https://api.github.com/repos/ETCE-LAB/FarmInsight/readme", "https://api.github.com/repos/ETCE-LAB/FarmInsight/license"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/ETCE-LAB/FarmInsight/license", "name": "FarmInsight", "repository_url": "https://github.com/ETCE-LAB/FarmInsight", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:29:32.341454+08:00", "kind": "repository_metadata", "sha256": "af7f637eb2458b6eb2a3ed6df5df3f5a8ff3b0fb3273afe43666f7b689816a74", "snapshot_path": "sources/af7f637eb2458b6eb2a3ed6df5df3f5a8ff3b0fb3273afe43666f7b689816a74.txt", "url": "https://api.github.com/repos/ETCE-LAB/FarmInsight"}, {"fetched_at": "2026-10-26T22:29:34.143545+08:00", "kind": "readme", "sha256": "19413fd432aa9b102060a7f7e45bc3dd67ea74aef3c2be6b4ff24ac08fdf0937", "snapshot_path": "sources/19413fd432aa9b102060a7f7e45bc3dd67ea74aef3c2be6b4ff24ac08fdf0937.txt", "url": "https://api.github.com/repos/ETCE-LAB/FarmInsight/readme"}, {"fetched_at": "2026-10-26T22:29:36.993236+08:00", "kind": "license", "sha256": "8ae9c2d6d3fce4d36d4977995091c9b44d703facf687929fa26b15b7c5922751", "snapshot_path": "sources/8ae9c2d6d3fce4d36d4977995091c9b44d703facf687929fa26b15b7c5922751.txt", "url": "https://api.github.com/repos/ETCE-LAB/FarmInsight/license"}], "summary": "面向食品生产设施（温室、垂直农场等）的开源自托管 IoT 监测平台（AGPL-3.0）：接入 HTTP/MQTT 传感器与摄像头，提供实时遥测、历史趋势、阈值警报、通知和基于触发的自动控制；含多租户与角色权限。大学项目，未做生产验证。", "technology_stack": ["Django", "React", "TypeScript", "InfluxDB", "MQTT", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1158459932','OpenFarm','{"deployment": ["Docker Compose 启动 Web、API、TiTiler、PostGIS、Redis、MinIO 和 Celery worker"], "features": ["绘制或上传 GeoJSON/KML 田块边界并自动计算面积", "Sentinel-2 NDVI/EVI/SAVI 多指数监测与 24 个月历史回填", "按指数配置阈值/跌幅警报", "地理标记巡查与照片记录", "采样分区、地图图层与分享报告"], "github_repository_id": 1158459932, "homepage": "https://openfarm.earth", "id": "github:1158459932", "leaf_matches": [{"reason": "README 明确以田块边界为锚点，接入 Sentinel-2 影像生成 NDVI/EVI/SAVI 时间序列，并将异常/阈值警报、巡查、采样分区和分享报告交付到作物管理，覆盖作物遥感平台的核心链路。", "slug": "crop-remote-sensing-platform", "source_urls": ["https://api.github.com/repos/superzero11/OpenFarm", "https://api.github.com/repos/superzero11/OpenFarm/readme", "https://api.github.com/repos/superzero11/OpenFarm/license"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/superzero11/OpenFarm/license", "name": "OpenFarm", "repository_url": "https://github.com/superzero11/OpenFarm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:29:38.417024+08:00", "kind": "repository_metadata", "sha256": "c3b36996172a3394f58dd184549702af6453ca0a54378c67f2835bc785d46e63", "snapshot_path": "sources/c3b36996172a3394f58dd184549702af6453ca0a54378c67f2835bc785d46e63.txt", "url": "https://api.github.com/repos/superzero11/OpenFarm"}, {"fetched_at": "2026-10-26T22:29:40.491405+08:00", "kind": "readme", "sha256": "81265bd5acdd0f7ea6fa41bc7a54bfb76760daf9dff6198b76293644466c8344", "snapshot_path": "sources/81265bd5acdd0f7ea6fa41bc7a54bfb76760daf9dff6198b76293644466c8344.txt", "url": "https://api.github.com/repos/superzero11/OpenFarm/readme"}, {"fetched_at": "2026-10-26T22:29:42.866436+08:00", "kind": "license", "sha256": "75f074e890122998b27754e5b86e2559ae0abcc736c9cef8e765d956ed9b4476", "snapshot_path": "sources/75f074e890122998b27754e5b86e2559ae0abcc736c9cef8e765d956ed9b4476.txt", "url": "https://api.github.com/repos/superzero11/OpenFarm/license"}], "summary": "以田块为锚点的开源自托管作物遥感/田间情报平台（BSD-3-Clause）：绘制或导入 GeoJSON/KML 田块边界，接入 Sentinel-2 影像计算 NDVI/EVI/SAVI 时间序列，提供异常与阈值警报、巡查、采样分区、地图和分享报告；支持 Docker/PostGIS/TiTiler 部署。项目较新，未做运行验证。", "technology_stack": ["Next.js", "FastAPI", "PostgreSQL/PostGIS", "TiTiler", "Celery", "Redis", "MinIO", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:john-deere-operations-center','John Deere Operations Center','{"homepage": "https://www.deere.com/", "id": "commercial:john-deere-operations-center", "leaf_matches": [{"reason": "JDLink 官方页说明机器无线接入 Operations Center、可远程查看位置/使用数据/诊断并分析历史性能；Operations Center 页说明近实时监控作业与回看当季结果，核心匹配农机遥测的车队实时视图与机器历史。", "slug": "farm-equipment-telematics", "source_urls": ["https://www.deere.com/en-us/products-solutions/technology-solutions/precision-ag-technology/operations-center", "https://www.deere.com/en/technology-products/precision-ag-technology/data-management/jdlink/"]}], "name": "John Deere Operations Center", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:29:50.156968+08:00", "kind": "homepage", "sha256": "3a3c201f13740f4ff27a728a7a264cdaedded7ebc1499007261632ffa07f59f5", "snapshot_path": "sources/3a3c201f13740f4ff27a728a7a264cdaedded7ebc1499007261632ffa07f59f5.txt", "url": "https://www.deere.com/en-us/products-solutions/technology-solutions/precision-ag-technology/operations-center"}, {"fetched_at": "2026-10-26T22:31:52.564079+08:00", "kind": "documentation", "sha256": "55c66e6ed70e0c9d98f7406de94ae55cf5c934e78f174056c600af8a80597d62", "snapshot_path": "sources/55c66e6ed70e0c9d98f7406de94ae55cf5c934e78f174056c600af8a80597d62.txt", "url": "https://www.deere.com/en/technology-products/precision-ag-technology/data-management/jdlink/"}], "summary": "John Deere 的联网农机作业与车队管理平台：通过 JDLink 等连接设备获取机器位置、使用数据与诊断，近实时监控作业，并回看历史性能与季节结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:petex-move-suite','Petex MOVE Suite','{"homepage": "https://www.petex.com/", "id": "commercial:petex-move-suite", "leaf_matches": [{"reason": "官方页说明 MOVE Core 是构建地质模型的独立环境，整合 2D/3D 数据与视图、构建剖面和三维模型并提供验证；3D Kinematic 模块支持三维恢复、正演建模、情景测试与模型验证，匹配地质建模平台的观测—解释—更新循环。", "slug": "geological-modeling-platform", "source_urls": ["https://www.petex.com/products/move-suite/"]}], "name": "Petex MOVE Suite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:29:52.117363+08:00", "kind": "homepage", "sha256": "826ebe7e787c8c62f917ef97641a27b44dcc2448547f312796f08581852a0d63", "snapshot_path": "sources/826ebe7e787c8c62f917ef97641a27b44dcc2448547f312796f08581852a0d63.txt", "url": "https://www.petex.com/products/move-suite/"}], "summary": "Petex（原 Midland Valley）的商业地质建模套件：MOVE Core 在统一工作区整合地质数据、2D/3D 视图与 100+ 数据格式，构建并验证地质剖面与三维模型，3D Kinematic 模块支持恢复、正演与替代情景测试。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:climate-fieldview','Climate FieldView','{"homepage": "https://climate.com/", "id": "commercial:climate-fieldview", "leaf_matches": [{"reason": "官方 Build Prescriptions 页显示可按种子/施肥/植保创建并导出或无线发送处方；Gather Information 与 Analyze Data 页显示 FieldView Drive 采集设备数据、系统保存种植与施用记录并分析产量，构成处方—机器执行数据回传—效果分析的主要闭环。未将未明确展示的处方偏差评分写入。", "slug": "precision-agriculture-platform", "source_urls": ["https://climate.com/en-us/solutions/build-prescriptions.html", "https://climate.com/en-us/solutions/gather-information.html", "https://climate.com/en-us/solutions/analyze-data.html", "https://climate.com/en-us.html"]}], "name": "Climate FieldView", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:29:50.184799+08:00", "kind": "homepage", "sha256": "6441f5cd0eb4d8d5f257835d28134c21c2726b83fd718370792a9228b8655be1", "snapshot_path": "sources/6441f5cd0eb4d8d5f257835d28134c21c2726b83fd718370792a9228b8655be1.txt", "url": "https://climate.com/en-us.html"}, {"fetched_at": "2026-10-26T22:31:52.700669+08:00", "kind": "documentation", "sha256": "a8624ea95c14843acb42cfa1af92f0b5b84b209d284705f8180d913413bf44af", "snapshot_path": "sources/a8624ea95c14843acb42cfa1af92f0b5b84b209d284705f8180d913413bf44af.txt", "url": "https://climate.com/en-us/solutions/build-prescriptions.html"}, {"fetched_at": "2026-10-26T22:33:40.913073+08:00", "kind": "documentation", "sha256": "8f7932c766951c3f78b8e1c70edc6d07ac3eb8096684b0901f750b75f34f9f88", "snapshot_path": "sources/8f7932c766951c3f78b8e1c70edc6d07ac3eb8096684b0901f750b75f34f9f88.txt", "url": "https://climate.com/en-us/solutions/gather-information.html"}, {"fetched_at": "2026-10-26T22:33:41.107435+08:00", "kind": "documentation", "sha256": "4a8bbd4e3a9b42aeb83fe440e8a475210da5ec1591904fa089b4fb6f7df3cac1", "snapshot_path": "sources/4a8bbd4e3a9b42aeb83fe440e8a475210da5ec1591904fa089b4fb6f7df3cac1.txt", "url": "https://climate.com/en-us/solutions/analyze-data.html"}], "summary": "Climate FieldView 是商业数字农业平台：可创建种子、施肥与植保处方并导出/无线发送，通过 FieldView Drive 采集设备作业与产量数据，用于田块、投入和实践的效果分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:soil-test-pro','Soil Test Pro','{"homepage": "https://soiltestpro.com/", "id": "commercial:soil-test-pro", "leaf_matches": [{"reason": "官方首页与实验室页说明系统覆盖田块/采样点、网格或分区采样、实验室结果回传、施肥建议与处方/控制器文件，并可查看多年土壤采样历史，匹配土壤管理应用以土壤记录为核心并驱动改良决策的结构。", "slug": "soil-management", "source_urls": ["https://soiltestpro.com/", "https://soiltestpro.com/soil-testing-labs/"]}], "name": "Soil Test Pro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:31:52.585767+08:00", "kind": "homepage", "sha256": "032483c6fd83bbd3bf2797cbfd758d149b1665cfa3feab8d5069331a8b8a9467", "snapshot_path": "sources/032483c6fd83bbd3bf2797cbfd758d149b1665cfa3feab8d5069331a8b8a9467.txt", "url": "https://soiltestpro.com/"}, {"fetched_at": "2026-10-26T22:31:53.246006+08:00", "kind": "documentation", "sha256": "dac0cc7663af3d74953281ffe2f68879a6df0bafd6561d36a222459ad44b1052", "snapshot_path": "sources/dac0cc7663af3d74953281ffe2f68879a6df0bafd6561d36a222459ad44b1052.txt", "url": "https://soiltestpro.com/soil-testing-labs/"}], "summary": "Soil Test Pro（TapLogic）是商业土壤采样与养分管理 SaaS：移动 App 结合 Web Headquarters 管理田块、网格/分区采样、实验室送样与结果回传，并据此生成施肥建议、处方图和控制器文件。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dis-quantum-ag','DIS Quantum for Agriculture','{"homepage": "https://www.discorp.com/products/quantum/ag", "id": "commercial:dis-quantum-ag", "leaf_matches": [{"reason": "官方产品页说明其面向农业设备经销商，覆盖整机销售、零件库存、服务工单、客户历史与多门店运营，符合经销店管理核心。", "slug": "agricultural-dealer-management", "source_urls": ["https://www.discorp.com/products/quantum/ag"]}], "name": "DIS Quantum for Agriculture", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:30:25.315342+08:00", "kind": "documentation", "sha256": "34977a49bc8b4028c21b0c193b23097211775038830848e4f08b9e2c95516dae", "snapshot_path": "sources/34977a49bc8b4028c21b0c193b23097211775038830848e4f08b9e2c95516dae.txt", "url": "https://www.discorp.com/products/quantum/ag"}], "summary": "面向农业设备经销商的经销店管理系统，覆盖整机销售、零件与库存、服务工单、客户关系、财务和多门店报表；提供云端与本地部署。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fieldclock','FieldClock','{"homepage": "https://www.fieldclock.com", "id": "commercial:fieldclock", "leaf_matches": [{"reason": "官方页面说明其面向农场与劳务承包商，记录工时、非生产时间和产量，支持离线采集、H-2A 合规及向薪资输出。", "slug": "farm-labor-management", "source_urls": ["https://www.fieldclock.com"]}], "name": "FieldClock", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:33:20.636927+08:00", "kind": "homepage", "sha256": "7153ed94642357b897345e308a49f7abf188f7aa2508734d2940379fe0302924", "snapshot_path": "sources/7153ed94642357b897345e308a49f7abf188f7aa2508734d2940379fe0302924.txt", "url": "https://www.fieldclock.com"}], "summary": "面向农场及农场劳务承包商的劳动力管理应用，提供离线工时与考勤、非生产时间、产量记录、H-2A 合规跟踪，并向薪资流程提供数据。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gms-grain','GMS Grain Management System','{"homepage": "https://www.gmsgrain.com/", "id": "commercial:gms-grain", "leaf_matches": [{"reason": "官方页面明确面向粮库，提供自动票证、合同管理、自有/代储库存、月末合同市值及种植者门户，覆盖票证—合同—库存核心。", "slug": "grain-elevator-management", "source_urls": ["https://www.gmsgrain.com/"]}], "name": "GMS Grain Management System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:32:23.876619+08:00", "kind": "homepage", "sha256": "3dfe1111faf1cb5db7efc96bb6b821da024f5257a3dd73f4082584ce42593648", "snapshot_path": "sources/3dfe1111faf1cb5db7efc96bb6b821da024f5257a3dd73f4082584ce42593648.txt", "url": "https://www.gmsgrain.com/"}], "summary": "面向谷物升降机的运营与核算软件，覆盖地磅票与运输票、合同、库存头寸、结算单、市场数据接口，可选与 Sage 50/QuickBooks 集成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:bushel-trade','Bushel Trade','{"homepage": "https://www.bushelpowered.com/agribusiness/solutions/trade", "id": "commercial:bushel-trade", "leaf_matches": [{"reason": "官方页面说明其面向粮食买家，管理数字现金报价、种植者 firm offers、接受锁价、合同定价与期货订单，符合收购侧核心。", "slug": "grain-origination-platform", "source_urls": ["https://www.bushelpowered.com/agribusiness/solutions/trade"]}], "name": "Bushel Trade", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:30:22.632840+08:00", "kind": "documentation", "sha256": "b68229695b7910d49db2d1d16d183f05f31b6eccaca9112afbee3523c86cb12d", "snapshot_path": "sources/b68229695b7910d49db2d1d16d183f05f31b6eccaca9112afbee3523c86cb12d.txt", "url": "https://www.bushelpowered.com/agribusiness/solutions/trade"}], "summary": "面向粮食买家的交易与收购平台，支持发布现金报价、种植者提交坚定报价、在线接受报价并锁定价格、合同定价及期货订单跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:croptracker-packing','Croptracker Packing','{"homepage": "https://www.croptracker.com/product/farm-management-software/produce-packing-traceability-records.html", "id": "commercial:croptracker-packing", "leaf_matches": [{"reason": "官方页面说明包装模块记录原料批次到包装成品的转化、消耗与成品创建、剔除/修剪、标签、冷藏库存和订单发货追溯，符合包装作业核心。", "slug": "produce-packing-house-management", "source_urls": ["https://www.croptracker.com/product/farm-management-software/produce-packing-traceability-records.html"]}], "name": "Croptracker Packing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:33:21.433754+08:00", "kind": "documentation", "sha256": "0b57aba45c7abe63d353ae53adf489f5c66eeeab28a62bf26f431b4ab2d05721", "snapshot_path": "sources/0b57aba45c7abe63d353ae53adf489f5c66eeeab28a62bf26f431b4ab2d05721.txt", "url": "https://www.croptracker.com/product/farm-management-software/produce-packing-traceability-records.html"}], "summary": "面向果蔬种植者与包装作业的农场管理平台，其 Packing 模块记录原料批次到包装成品的转化、包装材料消耗、托盘与产品标签、仓储库位及发货追溯。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:enfos','ENFOS Environmental Remediation Obligation','{"homepage": "https://enfos.com/", "id": "commercial:enfos", "leaf_matches": [{"reason": "官方 ERO 正文以场地/资产为锚记录污染修复义务，覆盖从污染发现、评估、修复策略与进展到关闭标准的受管进程，并保留技术与会计审计轨迹；未将其写成采样数据或环境数据平台。", "slug": "contaminated-site-management", "source_urls": ["https://enfos.com/", "https://enfos.com/environmental-remediation-obligation"]}, {"reason": "官方 ERO 正文以污染场地/资产为持续记录单元，把修复策略、清理阶段与工作分解、关闭标准、进展和支出列为全生命周期要素；2026 年官方 ROI 白皮书进一步称平台集中 sites、vendors、documents、financial plans、costs、regulatory info，可按项目/供应商跟踪授权支出、PO 承诺与实际花费，并以变更单控制未授权工作；官方文章明确称 ENFOS 是仅面向环境修复的项目管理软件。据此建立商业关系；不据此声称其管理逐次采样或提供实验室数据导入。", "slug": "environmental-remediation-management", "source_urls": ["https://enfos.com/environmental-remediation-obligation", "https://enfos.com/", "https://go.enfos.com/blog/6-proven-ways-to-supercharge-your-remediation-management", "https://enfos.com/white-papers/enfos-roi-environmental-remediation-obligations"]}], "name": "ENFOS Environmental Remediation Obligation", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:39:06+08:00", "kind": "homepage", "sha256": "6faf47e77999c1fc002e7c8809fc56a0890eb2ee63232aa48af93a30642b3aa6", "snapshot_path": "sources/6faf47e77999c1fc002e7c8809fc56a0890eb2ee63232aa48af93a30642b3aa6.txt", "url": "https://enfos.com/"}, {"fetched_at": "2026-10-26T22:39:05+08:00", "kind": "documentation", "sha256": "1d4b48a73d2b45dc28f5388e9bf717b2e312035d1464850ec9b8a1b2710f8ce8", "snapshot_path": "sources/1d4b48a73d2b45dc28f5388e9bf717b2e312035d1464850ec9b8a1b2710f8ce8.txt", "url": "https://enfos.com/environmental-remediation-obligation"}, {"fetched_at": "2026-10-29T13:17:21.697076+08:00", "kind": "documentation", "sha256": "950806f59a6fa03e3dfa5881a9bc4e5aaf5e39f129317e3e9a5485769bc308c3", "snapshot_path": "sources/950806f59a6fa03e3dfa5881a9bc4e5aaf5e39f129317e3e9a5485769bc308c3.txt", "url": "https://enfos.com/white-papers/enfos-roi-environmental-remediation-obligations"}, {"fetched_at": "2026-10-29T13:15:25.407405+08:00", "kind": "documentation", "sha256": "5d7a2bdb3f1da806b68f8b656e02efab6d7084511d492fa81f771d2998baeef1", "snapshot_path": "sources/5d7a2bdb3f1da806b68f8b656e02efab6d7084511d492fa81f771d2998baeef1.txt", "url": "https://go.enfos.com/blog/6-proven-ways-to-supercharge-your-remediation-management"}], "summary": "面向企业环境修复义务（ASC 410-30）的商业 SaaS 记录系统，把污染场地/资产的环境修复义务集中登记，跟踪调查、评估、修复策略、进展、支出与关闭，并保留技术与会计审计轨迹；未证实其管理逐次采样结果或提供实验室数据导入。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1296093906','EHSBase','{"deployment": ["自托管 PHP 应用", "SQLite 文件数据库，无外部服务依赖"], "features": ["风险评估（可能性×后果评分）", "文档控制与多级审批", "事件登记、调查与纠正措施", "作业许可（高危作业审批）", "人员、角色与访问管理"], "github_repository_id": 1296093906, "homepage": "https://github.com/coreaxiskkdutt/ehsbase", "id": "github:1296093906", "leaf_matches": [{"reason": "README 明确为组织级 EHS 工作区，事件与纠正措施、文档审批、风险评估和作业许可共用一个记录与行动循环；事件类别包含 Environmental Issue，符合集成式 EHS 主干，但不宣称已具备独立环境登记册或全模块企业套件。", "slug": "ehs-hse-platform", "source_urls": ["https://api.github.com/repos/coreaxiskkdutt/ehsbase/readme"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/coreaxiskkdutt/ehsbase/license", "name": "EHSBase", "repository_url": "https://github.com/coreaxiskkdutt/ehsbase", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:39:46+08:00", "kind": "repository_metadata", "sha256": "cbeb2f7f1559b79fa0f9a5c38568c2b5ab7194b6956c60ae3f94f2a1bd542976", "snapshot_path": "sources/cbeb2f7f1559b79fa0f9a5c38568c2b5ab7194b6956c60ae3f94f2a1bd542976.txt", "url": "https://api.github.com/repos/coreaxiskkdutt/ehsbase"}, {"fetched_at": "2026-10-26T22:39:48+08:00", "kind": "readme", "sha256": "b7eeac498e872ea4ca78ce335fb2389fb73afa074d1c20c79502b52948a3dd70", "snapshot_path": "sources/b7eeac498e872ea4ca78ce335fb2389fb73afa074d1c20c79502b52948a3dd70.txt", "url": "https://api.github.com/repos/coreaxiskkdutt/ehsbase/readme"}, {"fetched_at": "2026-10-26T22:39:51+08:00", "kind": "license", "sha256": "e39d0a23fd7b6eba2344ffabd17a5879f62bc569b33526a3d37ffe2c6106d016", "snapshot_path": "sources/e39d0a23fd7b6eba2344ffabd17a5879f62bc569b33526a3d37ffe2c6106d016.txt", "url": "https://api.github.com/repos/coreaxiskkdutt/ehsbase/license"}], "summary": "自托管 PHP + SQLite 的开源 EHS 平台，提供风险评估、文档控制与审批、事件调查与纠正措施、作业许可、人员与权限管理；事件类别包含 Environmental Issue，但独立环境登记册、化学品/SDS、培训与承包商模块未在已读资料中证实。", "technology_stack": ["PHP 8.0+", "SQLite (PDO)", "Bootstrap 5", "jQuery", "DataTables"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:mapistry','Mapistry','{"homepage": "https://www.mapistry.com/", "id": "commercial:mapistry", "leaf_matches": [{"reason": "官方正文把空气、雨洪、废水、SPCC 与废物等环境义务放进同一平台，并以移动检查、合规日历、限值监测、纠正措施和记录留存支撑义务驱动的工作与证据状态；未写成通用 EHS 平台。", "slug": "environmental-compliance-management", "source_urls": ["https://www.mapistry.com/", "https://www.mapistry.com/product-inspections-corrective-actions", "https://www.mapistry.com/use-case-visibility"]}], "name": "Mapistry", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:40:15+08:00", "kind": "homepage", "sha256": "c84001250bd08fb52217d5810aeb9cd4ff30d4d82c2439cbca9e2d49cd528564", "snapshot_path": "sources/c84001250bd08fb52217d5810aeb9cd4ff30d4d82c2439cbca9e2d49cd528564.txt", "url": "https://www.mapistry.com/"}, {"fetched_at": "2026-10-26T22:40:17+08:00", "kind": "documentation", "sha256": "8ea0247560bdbd3d12e9be9b87a88e82a879fcf177c0983f02df05a302cce75c", "snapshot_path": "sources/8ea0247560bdbd3d12e9be9b87a88e82a879fcf177c0983f02df05a302cce75c.txt", "url": "https://www.mapistry.com/product-inspections-corrective-actions"}, {"fetched_at": "2026-10-26T22:40:23+08:00", "kind": "documentation", "sha256": "50380b0773e4919a216dc699f43a3d26c019bb4a0d21667855dd17c874383e9c", "snapshot_path": "sources/50380b0773e4919a216dc699f43a3d26c019bb4a0d21667855dd17c874383e9c.txt", "url": "https://www.mapistry.com/use-case-visibility"}], "summary": "面向工业设施的环保合规 SaaS，覆盖 Title V 空气许可、雨洪、废水、SPCC、废物等环境义务，提供移动检查、合规日历、限值监测、纠正措施与记录云；官方明确将其定位为环境（非安全）软件，法规内容库或适用性扫描未在已读正文中证实。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ecesis-ems','Ecesis Environmental Management (ISO 14001)','{"homepage": "https://www.ecesis.net/ISO-14001-Software.aspx", "id": "commercial:ecesis-ems", "leaf_matches": [{"reason": "正文列出环境因素与影响库、合规义务、环境目标、内部审核、纠正措施及 PDCA 仪表板，覆盖因素影响登记册与管理系统循环两项定义性结构。", "slug": "environmental-management-system", "source_urls": ["https://www.ecesis.net/ISO-14001-Software.aspx"]}], "name": "Ecesis Environmental Management (ISO 14001)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:39:18.011060+08:00", "kind": "documentation", "sha256": "abe18d8b709a6e231bd2575c6f834d2fcd944b62900a4eb7a26e633c8a283f3f", "snapshot_path": "sources/abe18d8b709a6e231bd2575c6f834d2fcd944b62900a4eb7a26e633c8a283f3f.txt", "url": "https://www.ecesis.net/ISO-14001-Software.aspx"}], "summary": "面向 ISO 14001 环境管理体系的商业软件，提供环境因素与影响、合规义务、环境目标、培训、内部审核、纠正措施和管理评审等模块。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ecesis-permit','Ecesis Environmental Permit Management','{"homepage": "https://www.ecesis.net/Environmental-Permit-Management-Software.aspx", "id": "commercial:ecesis-permit", "leaf_matches": [{"reason": "产品页面向被许可设施，正文说明将许可证文件转为带负责人、续期日期、条件与报告截止日的可执行任务并自动提醒，符合许可记录、授权生命周期和条件可操作三项核心。", "slug": "environmental-permit-management", "source_urls": ["https://www.ecesis.net/Environmental-Permit-Management-Software.aspx"]}], "name": "Ecesis Environmental Permit Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:39:18.328644+08:00", "kind": "documentation", "sha256": "a62f77d271a473eee91652be467c6745856b469e1398db08684a21978ccba7e1", "snapshot_path": "sources/a62f77d271a473eee91652be467c6745856b469e1398db08684a21978ccba7e1.txt", "url": "https://www.ecesis.net/Environmental-Permit-Management-Software.aspx"}], "summary": "面向设施运营方的环境许可管理商业软件，集中管理空气、水、废物等许可证及其条件、续期日期和合规任务，并提供负责人、提醒与合规仪表板。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ibat','IBAT (Integrated Biodiversity Assessment Tool)','{"homepage": "https://www.ibat-alliance.org/", "id": "commercial:ibat", "leaf_matches": [{"reason": "IBAT 将项目场址、供应链和投资组合位置批量绑定到地理坐标，按缓冲区叠加 WDPCA、KBA 与 IUCN 红色名录物种数据，评估敏感性与优先级并生成 TNFD/CSRD/GRI 报告，符合以地点为锚的自然风险识别与评估核心。", "slug": "nature-risk-management", "source_urls": ["https://www.ibat-alliance.org/", "https://www.ibat-alliance.org/services"]}, {"reason": "官网正文面向企业用户提供地点级生物多样性风险制图、行动优先级和报告，数据来自保护区、KBA、IUCN 受威胁物种等全球数据集，对应以地点为锚的筛选评估与报告输出；未证实其维护长期地点组合或现场监测。", "slug": "biodiversity-management", "source_urls": ["https://www.ibat-alliance.org/"]}], "name": "IBAT (Integrated Biodiversity Assessment Tool)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:43:40.985639+08:00", "kind": "homepage", "sha256": "875da1a94ae6c05693f10c62850c5b759e4bfc6e2d005eadf86d0e040165003c", "snapshot_path": "sources/875da1a94ae6c05693f10c62850c5b759e4bfc6e2d005eadf86d0e040165003c.txt", "url": "https://www.ibat-alliance.org/"}, {"fetched_at": "2026-10-26T22:44:12.884506+08:00", "kind": "documentation", "sha256": "f98559b914d83b55c2bc5bd8f27109444ab892c626ea343456b0f64efdc320fe", "snapshot_path": "sources/f98559b914d83b55c2bc5bd8f27109444ab892c626ea343456b0f64efdc320fe.txt", "url": "https://www.ibat-alliance.org/services"}], "summary": "面向企业、金融机构和项目的生物多样性风险筛查平台；可批量上传场址、供应链和投资组合位置，叠加保护区、关键生物多样性区（KBA）与 IUCN 受威胁物种数据，按缓冲区生成筛查结果、优先级与 TNFD/CSRD/GRI 报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:climateview','ClimateView','{"homepage": "https://www.climateview.global/", "id": "commercial:climateview", "leaf_matches": [{"reason": "ClimateView 的 SECAP 页面明确把气候风险与脆弱性评估（RVA）以及包含减缓与适应措施的行动计划列为计划组成部分，平台提供行动编辑、目标情景与进展监测，形成危害证据→适应计划→措施→跟踪的规划闭环。", "slug": "climate-adaptation-planning", "source_urls": ["https://www.climateview.global/en/platform", "https://www.climateview.global/en/solutions/secap"]}, {"reason": "官方产品页展示排放清单、战略与目标、干预措施评估和监测的持续规划闭环；服务对象为地方政府或地区，符合本叶的市政脱碳规划形态。", "slug": "decarbonization-planning-platform", "source_urls": ["https://www.climateview.global/", "https://www.climateview.global/en/platform"]}], "name": "ClimateView", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:43:44.981713+08:00", "kind": "homepage", "sha256": "e7f5cc7300ea774959e9d7af31568eff97f5a6e601ff0a2ede3bc50bf2b619f2", "snapshot_path": "sources/e7f5cc7300ea774959e9d7af31568eff97f5a6e601ff0a2ede3bc50bf2b619f2.txt", "url": "https://www.climateview.global/"}, {"fetched_at": "2026-10-26T22:44:14.526504+08:00", "kind": "documentation", "sha256": "939a7d2646d9f5530bbab8f6aeee234fa97bbd1df3ca05eb8ff4f2b4226af1bb", "snapshot_path": "sources/939a7d2646d9f5530bbab8f6aeee234fa97bbd1df3ca05eb8ff4f2b4226af1bb.txt", "url": "https://www.climateview.global/en/platform"}, {"fetched_at": "2026-10-26T22:46:58.574776+08:00", "kind": "documentation", "sha256": "84d514506dd3da474cdfbbfcdfc710930bc4ed8807a2f8dfc20db2af0346b7c7", "snapshot_path": "sources/84d514506dd3da474cdfbbfcdfc710930bc4ed8807a2f8dfc20db2af0346b7c7.txt", "url": "https://www.climateview.global/en/solutions/secap"}, {"fetched_at": "2026-10-26T22:49:58.911421+08:00", "kind": "homepage", "sha256": "6761729020b5a63bc6126bc984e0b178c281cad0978eb6421f50d1209cee94c3", "snapshot_path": "sources/6761729020b5a63bc6126bc984e0b178c281cad0978eb6421f50d1209cee94c3.txt", "url": "https://www.climateview.global/"}, {"fetched_at": "2026-10-26T22:50:45.149758+08:00", "kind": "documentation", "sha256": "f43769cec5cabe8d6f176aa222e886ca3f557da270919d67d4396a3a251e222e", "snapshot_path": "sources/f43769cec5cabe8d6f176aa222e886ca3f557da270919d67d4396a3a251e222e.txt", "url": "https://www.climateview.global/en/platform"}], "summary": "面向城市、区域和国家的综合气候行动规划平台；以 SECAP/CCAP 等计划为载体，整合排放清单、气候风险与脆弱性评估、减缓与适应措施，支持行动编辑、情景比较和进展监测。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:moodys-climate-risk','Moody''s Physical & Transition Risk','{"homepage": "https://www.moodys.com/web/en/us/capabilities/climate-risk.html", "id": "commercial:moodys-climate-risk", "leaf_matches": [{"reason": "Moody''s 以设施、基础设施、客户资产和投资组合为对象，覆盖物理与转型风险、近中长期情景与财务量化，并接入压力测试、监管披露和投资决策工作流，符合组织侧气候风险管理与决策支持的核心。", "slug": "climate-risk-management", "source_urls": ["https://www.moodys.com/web/en/us/capabilities/climate-risk.html"]}], "name": "Moody''s Physical & Transition Risk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:46:14.753069+08:00", "kind": "homepage", "sha256": "6b86f654991dab851982d352a535dde57cc1fcb3f40f67817a77c5be96a7a88e", "snapshot_path": "sources/6b86f654991dab851982d352a535dde57cc1fcb3f40f67817a77c5be96a7a88e.txt", "url": "https://www.moodys.com/web/en/us/capabilities/climate-risk.html"}], "summary": "面向银行、保险、资产管理与企业的物理及转型气候风险管理平台；按情景和时间范围量化设施、资产与投资组合的损害、信用及财务影响，并接入压力测试、披露和投资决策工作流。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:jupiter','Jupiter Intelligence','{"homepage": "https://www.jupiterintel.com/", "id": "commercial:jupiter", "leaf_matches": [{"reason": "Jupiter 对客户资产做资产级、多灾种、多情景（5 年步进、至 2100 年）的物理风险预测，计算损害/损失并翻译为信用、损失和现金流指标，支持组合汇总与 API/平台交付，符合物理气候风险平台的计算与情景条件化核心。", "slug": "physical-climate-risk-platform", "source_urls": ["https://www.jupiterintel.com/"]}], "name": "Jupiter Intelligence", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:44:01.252367+08:00", "kind": "homepage", "sha256": "9cbba55472e2a3153abfcfce7b60345595970c8a4d008201bb898025f47ceb14", "snapshot_path": "sources/9cbba55472e2a3153abfcfce7b60345595970c8a4d008201bb898025f47ceb14.txt", "url": "https://www.jupiterintel.com/"}], "summary": "资产级物理气候风险计算平台；对客户自有资产和组合运行多灾种、多情景、长时段预测，输出损害与损失、信用/现金流等财务指标及组合汇总，并提供适应 ROI 与披露支持。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ibm-envizi','IBM Envizi Emissions Management','{"homepage": "https://www.ibm.com/products/envizi", "id": "commercial:ibm-envizi", "leaf_matches": [{"reason": "IBM Envizi 以组织层级为核算边界，覆盖 Scope 1/2/3 活动数据、维护型排放因子与 GHG Protocol 方法，计算并汇总报告期清单，提供审计追踪和多框架披露，符合组织碳核算平台的核心闭环。", "slug": "carbon-accounting-platform", "source_urls": ["https://www.ibm.com/products/envizi", "https://www.ibm.com/products/envizi/emissions-management"]}, {"reason": "官方页面列出公用事业账单分析、间隔计量分析、能耗与排放目标跟踪，以及基于 GHG Protocol 的排放核算，覆盖能源数据记录、碳核算与绩效闭环。", "slug": "energy-carbon-management", "source_urls": ["https://www.ibm.com/products/envizi", "https://www.ibm.com/products/envizi/esg-data-management"]}, {"reason": "Envizi 将组织自身的环境、社会与治理数据集中为单一可审计记录，自动化采集 ERP、物联网、公用事业和供应商数据，提供数据质量、组织层级汇总、减排目标设定与跟踪及可持续发展项目跟踪；这些正是多域 ESG 数据资产、组织级采集运营和 ESG 计划三层核心。", "slug": "esg-management-platform", "source_urls": ["https://www.ibm.com/products/envizi", "https://www.ibm.com/products/envizi/esg-data-management"]}], "name": "IBM Envizi Emissions Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:47:44.718185+08:00", "kind": "homepage", "sha256": "a79b4936b6d197b057fd954468b853f3471d33ddae57ca4622190325564ddbe2", "snapshot_path": "sources/a79b4936b6d197b057fd954468b853f3471d33ddae57ca4622190325564ddbe2.txt", "url": "https://www.ibm.com/products/envizi"}, {"fetched_at": "2026-10-26T22:48:33.172737+08:00", "kind": "documentation", "sha256": "7ad5077c63c05d0d249ed14d7bc0b6c672527837f70d9d36b5b22b79e3de7119", "snapshot_path": "sources/7ad5077c63c05d0d249ed14d7bc0b6c672527837f70d9d36b5b22b79e3de7119.txt", "url": "https://www.ibm.com/products/envizi/emissions-management"}, {"fetched_at": "2026-10-26T22:50:06.023801+08:00", "kind": "documentation", "sha256": "655260ce8429b0dd4941c8b5bb3e6ad7c6c06d77432c9519c25b70e71f25f0ea", "snapshot_path": "sources/655260ce8429b0dd4941c8b5bb3e6ad7c6c06d77432c9519c25b70e71f25f0ea.txt", "url": "https://www.ibm.com/products/envizi/esg-data-management"}, {"fetched_at": "2026-10-26T23:00:50.734594+08:00", "kind": "documentation", "sha256": "adfc56f8613340265794ce58a41f5a58bcdc7fa44b0e3f66c486c225bedc351e", "snapshot_path": "sources/adfc56f8613340265794ce58a41f5a58bcdc7fa44b0e3f66c486c225bedc351e.txt", "url": "https://www.ibm.com/products/envizi/esg-reporting"}], "summary": "企业级温室气体核算与 ESG 数据平台；覆盖 Scope 1/2/3 排放计算、维护型排放因子库、组织层级汇总、审计追踪与多框架披露，属于完整的组织碳核算平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:313740591','Cloud Carbon Footprint','{"deployment": ["自托管 Node.js Web 应用（API + 前端）", "支持 Docker 运行", "提供 create-app 脚手架与 CLI"], "features": ["按云服务用量与供应商排放因子估算能源消耗（kWh）和碳排放（tCO2e）", "支持 AWS、Google Cloud、Microsoft Azure 多云账号统一查看", "按云厂商、账号、服务和时段下钻，支持 CSV 导出", "提供 CLI、Web 应用与 API"], "github_repository_id": 313740591, "homepage": "https://www.cloudcarbonfootprint.org/", "id": "github:313740591", "leaf_matches": [{"reason": "Cloud Carbon Footprint 以云账号和组织为边界，把公有云用量记录按公开方法论与供应商因子计算为能耗和 CO2e，按服务/账号/时段汇总并导出，覆盖活动数据→因子→计算清单的完整云口径碳核算子模块。", "slug": "carbon-accounting-platform", "source_urls": ["https://api.github.com/repos/cloud-carbon-footprint/cloud-carbon-footprint/readme", "https://www.cloudcarbonfootprint.org/", "https://www.cloudcarbonfootprint.org/docs/getting-started"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/cloud-carbon-footprint/cloud-carbon-footprint/license", "name": "Cloud Carbon Footprint", "repository_url": "https://github.com/cloud-carbon-footprint/cloud-carbon-footprint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:43:06.686276+08:00", "kind": "repository_metadata", "sha256": "4f869f736e46ffe647121c147a018d3d0f61b6adc68623dfa881b90b4502d4d2", "snapshot_path": "sources/4f869f736e46ffe647121c147a018d3d0f61b6adc68623dfa881b90b4502d4d2.txt", "url": "https://api.github.com/repos/cloud-carbon-footprint/cloud-carbon-footprint"}, {"fetched_at": "2026-10-26T22:43:18.170066+08:00", "kind": "readme", "sha256": "83dfd143ef7943f7b19270341481d0ca293d3a4f363c084b067c461721eba6cb", "snapshot_path": "sources/83dfd143ef7943f7b19270341481d0ca293d3a4f363c084b067c461721eba6cb.txt", "url": "https://api.github.com/repos/cloud-carbon-footprint/cloud-carbon-footprint/readme"}, {"fetched_at": "2026-10-26T22:43:20.049783+08:00", "kind": "license", "sha256": "1ada4dfc422c8c263d4a025a7c9bb8c58ed189c15e83dac512810c5617e96d5a", "snapshot_path": "sources/1ada4dfc422c8c263d4a025a7c9bb8c58ed189c15e83dac512810c5617e96d5a.txt", "url": "https://api.github.com/repos/cloud-carbon-footprint/cloud-carbon-footprint/license"}, {"fetched_at": "2026-10-26T22:47:41.002041+08:00", "kind": "homepage", "sha256": "0ca6d6fcba0200ca813cc3343a5df2975fbae7c750c7f40b8b72b63abe7fee43", "snapshot_path": "sources/0ca6d6fcba0200ca813cc3343a5df2975fbae7c750c7f40b8b72b63abe7fee43.txt", "url": "https://www.cloudcarbonfootprint.org/"}, {"fetched_at": "2026-10-26T22:47:42.685638+08:00", "kind": "documentation", "sha256": "fd8928731d4728c284e4f4ead0ad56090dec76073674a72e169b1bc7f3ee0bfd", "snapshot_path": "sources/fd8928731d4728c284e4f4ead0ad56090dec76073674a72e169b1bc7f3ee0bfd.txt", "url": "https://www.cloudcarbonfootprint.org/docs/getting-started"}], "summary": "开源云碳核算应用；以云账号/组织为边界，将 AWS、GCP、Azure 用量按公开方法论和供应商排放因子转换为能耗与 CO2e，按服务、账号和时段汇总并可导出，属于完整的云口径碳核算子模块。", "technology_stack": ["TypeScript", "Node.js", "MongoDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:abatable','Abatable','{"homepage": "https://abatable.com/", "id": "commercial:abatable", "leaf_matches": [{"reason": "官方平台页把环境资产采购、项目评估和组合管理放在同一系统，覆盖从首次购买到注销及交付节点跟踪，符合信用组合、交易与证据链核心。", "slug": "carbon-credit-management", "source_urls": ["https://abatable.com/", "https://abatable.com/platform"]}], "name": "Abatable", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:52:23.443979+08:00", "kind": "homepage", "sha256": "15ddd28920b322f2de4973c4284278bbc0b9c611c89345cb1cfae41ee67ac1f2", "snapshot_path": "sources/15ddd28920b322f2de4973c4284278bbc0b9c611c89345cb1cfae41ee67ac1f2.txt", "url": "https://abatable.com/"}, {"fetched_at": "2026-10-26T22:52:25.544909+08:00", "kind": "documentation", "sha256": "3f53c4fe5dcf2f3e283d1290c4f37de1523a79bf9d90a4336253f97e547e2d27", "snapshot_path": "sources/3f53c4fe5dcf2f3e283d1290c4f37de1523a79bf9d90a4336253f97e547e2d27.txt", "url": "https://abatable.com/platform"}], "summary": "面向碳信用买方的环境资产采购与组合管理平台：以结构化 RFP 和尽职调查获取信用，跟踪交付节点，并管理从首次购买到注销的整个组合。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:507142361','UNDP National Carbon Registry','{"deployment": ["Docker Compose 容器部署", "Serverless/AWS Lambda 部署"], "features": ["项目生命周期与授权", "信用签发与序列号", "信用转让、注销与余额", "账本与审计时间线", "AEF 报告与开放 API"], "github_repository_id": 507142361, "homepage": "https://github.com/undp/undp-national-carbon-registry", "id": "github:507142361", "leaf_matches": [{"reason": "登记处侧完整应用，追踪信用签发、持有余额、转让和注销，并保留序列号与账本证据；服务对象为国家登记机构而非单一企业买方。", "slug": "carbon-credit-management", "source_urls": ["https://raw.githubusercontent.com/undp/undp-national-carbon-registry/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/undp/undp-national-carbon-registry/license", "name": "UNDP National Carbon Registry", "repository_url": "https://github.com/undp/undp-national-carbon-registry", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:49:38.296478+08:00", "kind": "repository_metadata", "sha256": "07e9821c39921aa990af2ea94e8427dee74af767f88d74b94f5a177bcb1e2cf4", "snapshot_path": "sources/07e9821c39921aa990af2ea94e8427dee74af767f88d74b94f5a177bcb1e2cf4.txt", "url": "https://api.github.com/repos/undp/undp-national-carbon-registry"}, {"fetched_at": "2026-10-26T22:49:40.731222+08:00", "kind": "license", "sha256": "ef43317d4634d71c474b1bb28edef4abc60eaa206f7ad4ac550e41a1e4923422", "snapshot_path": "sources/ef43317d4634d71c474b1bb28edef4abc60eaa206f7ad4ac550e41a1e4923422.txt", "url": "https://api.github.com/repos/undp/undp-national-carbon-registry/license"}, {"fetched_at": "2026-10-26T22:49:42.382845+08:00", "kind": "readme", "sha256": "7235a33212551bc049d62cabaaf1cf5757b49d41a71a5d98bd4e29c51a0d7f38", "snapshot_path": "sources/7235a33212551bc049d62cabaaf1cf5757b49d41a71a5d98bd4e29c51a0d7f38.txt", "url": "https://raw.githubusercontent.com/undp/undp-national-carbon-registry/main/README.md"}], "summary": "UNDP 开源国家碳信用登记处：管理项目与信用签发、序列号、组织间转让、自愿或跨境注销，并以账本和审计时间线保留可追溯证据。", "technology_stack": ["TypeScript", "NestJS", "React", "PostgreSQL", "Amazon QLDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1144303732','MatXchange','{"deployment": ["Frappe Bench + ERPNext v16 自托管", "站点配置接入 Stellar 与 M-Pesa"], "features": ["废料交易与重量记录", "回收物保管链与流转记录", "RECO 每公斤凭证", "EPR 合规凭证与影响记录", "USSD 与移动支付接口"], "github_repository_id": 1144303732, "homepage": "https://github.com/samogera/matxchange", "id": "github:1144303732", "leaf_matches": [{"reason": "官方 README 描述多方废料回收交易、保管链、每公斤凭证、EPR 合规与分流数据，覆盖循环对象、回收路径、记录结果和审计可见性。", "slug": "circular-economy-platform", "source_urls": ["https://raw.githubusercontent.com/samogera/matxchange/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/samogera/matxchange/license", "name": "MatXchange", "repository_url": "https://github.com/samogera/matxchange", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:49:43.920592+08:00", "kind": "repository_metadata", "sha256": "11a68a948b64577eeae38686663ca97e559249af9e2fca272a8d6a59df797d58", "snapshot_path": "sources/11a68a948b64577eeae38686663ca97e559249af9e2fca272a8d6a59df797d58.txt", "url": "https://api.github.com/repos/samogera/matxchange"}, {"fetched_at": "2026-10-26T22:49:45.667552+08:00", "kind": "license", "sha256": "a3e7d7f17d2e95b93ce74b63fedd4bcdd495256b8ccd54374364507496ba4855", "snapshot_path": "sources/a3e7d7f17d2e95b93ce74b63fedd4bcdd495256b8ccd54374364507496ba4855.txt", "url": "https://api.github.com/repos/samogera/matxchange/license"}, {"fetched_at": "2026-10-26T22:49:46.967836+08:00", "kind": "readme", "sha256": "639f6dfb91938e347eaa6213644b26edd0c9085c80f247d190c2346a1dd5f23f", "snapshot_path": "sources/639f6dfb91938e347eaa6213644b26edd0c9085c80f247d190c2346a1dd5f23f.txt", "url": "https://raw.githubusercontent.com/samogera/matxchange/main/README.md"}], "summary": "基于 Frappe/ERPNext 的开源循环经济应用：记录废料回收交易与保管链，按公斤铸造 RECO 凭证，并生成 EPR 合规与流转/影响记录。", "technology_stack": ["Python", "Frappe", "ERPNext", "MariaDB", "Stellar"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:287392516','Hyperledger Blockchain Carbon Accounting','{"deployment": ["本地 Node.js/Hardhat 启动", "PostgreSQL 数据加载", "BSC 测试网演示"], "features": ["活动数据与排放因子计算", "排放审计申请与签发", "企业与供应链总足迹", "审计文档加密与审计员流程", "分布式账本审计记录"], "github_repository_id": 287392516, "homepage": "https://github.com/hyperledger-labs/blockchain-carbon-accounting", "id": "github:287392516", "leaf_matches": [{"reason": "用户指南描述按活动量与排放因子计算排放、签发审计记录并汇总总足迹，覆盖活动数据、因子、计算清单与可审计证据的核心循环。", "slug": "greenhouse-gas-accounting", "source_urls": ["https://raw.githubusercontent.com/hyperledger-labs/blockchain-carbon-accounting/main/User_Guide.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/hyperledger-labs/blockchain-carbon-accounting/license", "name": "Hyperledger Blockchain Carbon Accounting", "repository_url": "https://github.com/hyperledger-labs/blockchain-carbon-accounting", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:49:48.483933+08:00", "kind": "repository_metadata", "sha256": "2182680641631093be8009e68b4f9e4fdadb8df612eadfcbd6ce548e6e451134", "snapshot_path": "sources/2182680641631093be8009e68b4f9e4fdadb8df612eadfcbd6ce548e6e451134.txt", "url": "https://api.github.com/repos/hyperledger-labs/blockchain-carbon-accounting"}, {"fetched_at": "2026-10-26T22:49:50.771933+08:00", "kind": "license", "sha256": "ac7231961bbc7a47828b2979889630dc99cca1b8250d54b659c85018e287940b", "snapshot_path": "sources/ac7231961bbc7a47828b2979889630dc99cca1b8250d54b659c85018e287940b.txt", "url": "https://api.github.com/repos/hyperledger-labs/blockchain-carbon-accounting/license"}, {"fetched_at": "2026-10-26T22:49:51.885112+08:00", "kind": "readme", "sha256": "4e01dabc4e740d543caef60fb5bd06a7fa8e942b66f1c297961806c182828bee", "snapshot_path": "sources/4e01dabc4e740d543caef60fb5bd06a7fa8e942b66f1c297961806c182828bee.txt", "url": "https://raw.githubusercontent.com/hyperledger-labs/blockchain-carbon-accounting/main/README.md"}, {"fetched_at": "2026-10-26T22:49:55.256255+08:00", "kind": "documentation", "sha256": "2ce0c38a3b865bc9097d4230a7329499ad6b20098079a1382c1557d21ec91d37", "snapshot_path": "sources/2ce0c38a3b865bc9097d4230a7329499ad6b20098079a1382c1557d21ec91d37.txt", "url": "https://raw.githubusercontent.com/hyperledger-labs/blockchain-carbon-accounting/main/User_Guide.md"}, {"fetched_at": "2026-10-26T22:51:20.918125+08:00", "kind": "documentation", "sha256": "3239f6636df05f53efad390ef6ebb9348a1e4961062e647899b786f70d984008", "snapshot_path": "sources/3239f6636df05f53efad390ef6ebb9348a1e4961062e647899b786f70d984008.txt", "url": "https://raw.githubusercontent.com/hyperledger-labs/blockchain-carbon-accounting/main/Getting_Started.md"}], "summary": "Hyperledger Labs 的开源温室气体核算与审计应用：按活动数据与排放因子计算排放，生成经审计的排放记录和总足迹，并以分布式账本保存审计与流转记录。", "technology_stack": ["TypeScript", "Node.js", "React", "Solidity/Hardhat", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:carbonfact','Carbonfact','{"homepage": "https://www.carbonfact.com/", "id": "commercial:carbonfact", "leaf_matches": [{"reason": "官方页面明确按完整产品目录计算产品级 LCA/碳足迹，客户证言说明将每个产品的碳足迹用于标签与客户披露；产品记录可维护并对外交付，符合 PCF 平台核心。", "slug": "product-carbon-footprint-platform", "source_urls": ["https://www.carbonfact.com/lca-for-fashion", "https://www.carbonfact.com/product-tour", "https://www.carbonfact.com/"]}], "name": "Carbonfact", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:51:21.382229+08:00", "kind": "homepage", "sha256": "b38ec392b4faa2f1264aa11d5fabf1c91d56790cd8abf43a1ab73221a1a7dcd0", "snapshot_path": "sources/b38ec392b4faa2f1264aa11d5fabf1c91d56790cd8abf43a1ab73221a1a7dcd0.txt", "url": "https://www.carbonfact.com/"}, {"fetched_at": "2026-10-26T22:51:25.010789+08:00", "kind": "documentation", "sha256": "95a3a96e59060c7886f6ba74d2129833a1b3c998d6dc44c0ad27b2948f6aea66", "snapshot_path": "sources/95a3a96e59060c7886f6ba74d2129833a1b3c998d6dc44c0ad27b2948f6aea66.txt", "url": "https://www.carbonfact.com/lca-for-fashion"}, {"fetched_at": "2026-10-26T22:51:27.723780+08:00", "kind": "documentation", "sha256": "c2a345f25a6de6beae7fda7e4f1a7787349625f85cef8516e365dd68a0f8b502", "snapshot_path": "sources/c2a345f25a6de6beae7fda7e4f1a7787349625f85cef8516e365dd68a0f8b502.txt", "url": "https://www.carbonfact.com/product-tour"}], "summary": "Carbonfact 是面向服装、鞋履与奢侈品的商业产品碳足迹平台：以产品目录/SKU 为单位，结合 BOM、材料、供应商与排放因子计算产品级碳足迹，支持供应商数据收集、PLM/ERP 数据接入、审计报告与数字产品护照等对外交付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:202363022','Energy Web Origin','{"deployment": ["Docker/Heroku 演示环境；本地 UI 默认 localhost:3000", "Rush monorepo 构建；前端、后端、issuer 与 exchange 组件按需组合部署", "可选 I-REC API 连接器"], "features": ["证书申请、签发、转移、声明/注销与撤销的 REST 接口", "设备/组织注册与 I-REC 兼容的注册表模块", "Claims Report：查看退役并声明用于报告的证书、已声明/剩余电量、受益方与链上交易历史", "交易所与 ERC-1888 存取组件", "可部署的 React UI 与 NestJS 后端"], "github_repository_id": 202363022, "homepage": "https://www.energyweb.org/", "id": "github:202363022", "leaf_matches": [{"reason": "官方 README 将系统定义为 EAC 签发与管理工具集；Issuer API 覆盖申请、签发、转移、声明/注销与撤销；Claims Report 文档验证声明报告、受益方及审计轨迹，符合证书生命周期与声明链接核心。", "slug": "renewable-energy-certificate-management", "source_urls": ["https://raw.githubusercontent.com/energywebfoundation/origin/master/README.md", "https://raw.githubusercontent.com/energywebfoundation/origin/master/packages/traceability/issuer-api/README.md", "https://raw.githubusercontent.com/energywebfoundation/origin/master/docs/certificate-guides/claims-report.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/energywebfoundation/origin/license", "name": "Energy Web Origin", "repository_url": "https://github.com/energywebfoundation/origin", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:51:06.881270+08:00", "kind": "repository_metadata", "sha256": "8fce447eda8baa95d70f7a23646b90ac28454ddb89282fddbf581297925d622b", "snapshot_path": "sources/8fce447eda8baa95d70f7a23646b90ac28454ddb89282fddbf581297925d622b.txt", "url": "https://api.github.com/repos/energywebfoundation/origin"}, {"fetched_at": "2026-10-26T22:51:09.336663+08:00", "kind": "license", "sha256": "3edf7eca90a3968c08e818da35df1001b4342c7a7821d8f3e37dc3cd565d2c99", "snapshot_path": "sources/3edf7eca90a3968c08e818da35df1001b4342c7a7821d8f3e37dc3cd565d2c99.txt", "url": "https://api.github.com/repos/energywebfoundation/origin/license"}, {"fetched_at": "2026-10-26T22:51:11.078902+08:00", "kind": "readme", "sha256": "91fd73e31d8eb867c1e84c48d97d0ba760438fbc9f20cb01caab4a35923ecc44", "snapshot_path": "sources/91fd73e31d8eb867c1e84c48d97d0ba760438fbc9f20cb01caab4a35923ecc44.txt", "url": "https://raw.githubusercontent.com/energywebfoundation/origin/master/README.md"}, {"fetched_at": "2026-10-26T22:51:12.320179+08:00", "kind": "documentation", "sha256": "8b96587d18f1fae3c19d5019094d545db79519a042d5aa1dd1f4b72b1c096be4", "snapshot_path": "sources/8b96587d18f1fae3c19d5019094d545db79519a042d5aa1dd1f4b72b1c096be4.txt", "url": "https://raw.githubusercontent.com/energywebfoundation/origin/master/packages/traceability/issuer-api/README.md"}, {"fetched_at": "2026-10-26T22:51:13.770368+08:00", "kind": "documentation", "sha256": "04a125708a08597d4ea2b529283475b27901e40c5a4a3e25b64bed67df181b97", "snapshot_path": "sources/04a125708a08597d4ea2b529283475b27901e40c5a4a3e25b64bed67df181b97.txt", "url": "https://raw.githubusercontent.com/energywebfoundation/origin/master/docs/certificate-guides/claims-report.md"}], "summary": "Energy Web Origin 是用于能源属性证书（EAC/GO/REC/I-REC）签发与管理的开源工具集：包含设备/组织注册、证书申请与签发、账户间转移、声明/注销、声明报告与交易所组件，并提供可部署的 UI 与后端。其声明报告可追溯到证书 ID、已声明电量、受益方与链上交易历史。", "technology_stack": ["TypeScript", "NestJS", "React", "PostgreSQL", "ERC-1888 区块链证书", "Rush monorepo"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:watershed-supply-chain','Watershed Supply Chain','{"homepage": "https://watershed.com/", "id": "commercial:watershed-supply-chain", "leaf_matches": [{"reason": "官方 Supply Chain 页明确以 Scope 3 为对象，提供供应商映射/排序、供应商门户数据收集、估算替换为一手数据、承诺与减排计划跟踪，对应本类型的价值链账户、对等方群体与参与循环。", "slug": "scope-3-management-platform", "source_urls": ["https://watershed.com/solutions/supply-chain", "https://watershed.com/"]}], "name": "Watershed Supply Chain", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:51:35.437723+08:00", "kind": "homepage", "sha256": "a529f6a91dfd3175810ad21400b2ddcf5483e94addcee3eb038c1cfc8392e821", "snapshot_path": "sources/a529f6a91dfd3175810ad21400b2ddcf5483e94addcee3eb038c1cfc8392e821.txt", "url": "https://watershed.com/"}, {"fetched_at": "2026-10-26T22:51:38.898124+08:00", "kind": "documentation", "sha256": "34b6ac787e6419140aa0c50f48b341af10bafdb212874fe08699b2914c0a7c59", "snapshot_path": "sources/34b6ac787e6419140aa0c50f48b341af10bafdb212874fe08699b2914c0a7c59.txt", "url": "https://watershed.com/solutions/supply-chain"}], "summary": "Watershed Supply Chain 是 Watershed 面向采购方的商业 Scope 3 管理方案：映射供应商并按排放影响排序，通过供应商门户收集一手数据、目标承诺与减排计划，并将回复汇入企业足迹，以一手数据替换行业平均估算。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:makersite','Makersite','{"homepage": "https://makersite.io/", "id": "commercial:makersite", "leaf_matches": [{"reason": "官方页面显示其管理产品组合的产品可持续性状态，以 BOM/供应链数据和 LCA/PCF 评估机制生成结果，并支持替代材料、生态设计、报告与客户分享等产品决策循环，符合 SPM 三重结构。", "slug": "sustainable-product-management", "source_urls": ["https://makersite.io/product-sustainability/", "https://makersite.io/"]}], "name": "Makersite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:51:43.893132+08:00", "kind": "homepage", "sha256": "3ddfb6a72565f3c720b5026a7b14d60051ba70b7fcd4a8b5f5d1c93cf8a0708a", "snapshot_path": "sources/3ddfb6a72565f3c720b5026a7b14d60051ba70b7fcd4a8b5f5d1c93cf8a0708a.txt", "url": "https://makersite.io/"}, {"fetched_at": "2026-10-26T22:51:54.075129+08:00", "kind": "documentation", "sha256": "273b5c117bb0eee85e22c73cd88aff250ce03e5dd74f22d2014909c314b7cc34", "snapshot_path": "sources/273b5c117bb0eee85e22c73cd88aff250ce03e5dd74f22d2014909c314b7cc34.txt", "url": "https://makersite.io/product-sustainability/"}], "summary": "Makersite 是面向产品制造企业的商业产品可持续性管理平台：以产品/BOM 和供应链数据构建生命周期数字孪生，生成 LCA/PCF/合规等可持续性结果，支持热点分析、替代材料与生态设计场景，并把结果用于产品组合决策和对外报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:663663407','HydroServer','{"deployment": ["自托管实例（本地服务器、虚拟机或云主机）", "Docker Compose 部署", "Google Cloud Platform 与 AWS 部署指南"], "features": ["监测站点、数据流、观测值与元数据管理", "流式数据加载与作业编排（ETL）", "数据质量查看、导出下载与 HydroShare 归档", "工作区、角色与访问控制", "基于 REST/SensorThings 接口的数据共享", "独立部署的环境数据实例，支持自托管或云主机"], "github_repository_id": 663663407, "homepage": "https://hydroserver.org", "id": "github:663663407", "leaf_matches": [{"reason": "HydroServer 面向环境监测站点，提供观测时序数据的采集、存储、管理、共享，配套站点与数据流元数据、ETL编排和访问控制；其自托管实例承担组织环境数据语料库与受控导入的核心职责，属于遥测型环境数据平台实现。", "slug": "environmental-data-platform", "source_urls": ["https://github.com/hydroserver2/hydroserver", "https://raw.githubusercontent.com/hydroserver2/hydroserver/main/README.md", "https://hydroserver.org/introduction/hydroserver-overview.html"]}, {"reason": "面向水文/环境监测站点的时间序列采集与管理，提供监测点、数据流、最新与历史数据访问，符合环境水体持续观测记录的核心。", "slug": "environmental-water-monitoring", "source_urls": ["https://raw.githubusercontent.com/hydroserver2/hydroserver/main/README.md", "https://hydroserver.org/"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://raw.githubusercontent.com/hydroserver2/hydroserver/main/LICENSE", "license_review": {"rationale": "读取仓库 LICENSE 全文，确认包含 BSD 3-Clause 的源代码/二进制再分发、保留版权声明、不得背书及免责声明条款，仓库根目录完整许可文本与 SPDX 标识一致。", "reviewer": "OpenCode collection review unit 207", "scope": "repository", "source_url": "https://raw.githubusercontent.com/hydroserver2/hydroserver/main/LICENSE", "spdx_id": "BSD-3-Clause"}, "name": "HydroServer", "repository_url": "https://github.com/hydroserver2/hydroserver", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:32.602417+08:00", "kind": "repository_metadata", "sha256": "4b1b4b1c1c0329873604e697c973a0564db252ae403c0d1ca0e680155a162b02", "snapshot_path": "sources/4b1b4b1c1c0329873604e697c973a0564db252ae403c0d1ca0e680155a162b02.txt", "url": "https://github.com/hydroserver2/hydroserver"}, {"fetched_at": "2026-10-26T22:58:35.668012+08:00", "kind": "readme", "sha256": "424b9d53637e234e5cb81dada7d73d4595959877a72dbf4ee6c1625bf785deb9", "snapshot_path": "sources/424b9d53637e234e5cb81dada7d73d4595959877a72dbf4ee6c1625bf785deb9.txt", "url": "https://raw.githubusercontent.com/hydroserver2/hydroserver/main/README.md"}, {"fetched_at": "2026-10-26T22:58:36.951882+08:00", "kind": "license", "sha256": "c55a85c43c3740e109ba46a42fb8100aa20c4d0d5d952093a3a39cd68b4d5bcd", "snapshot_path": "sources/c55a85c43c3740e109ba46a42fb8100aa20c4d0d5d952093a3a39cd68b4d5bcd.txt", "url": "https://raw.githubusercontent.com/hydroserver2/hydroserver/main/LICENSE"}, {"fetched_at": "2026-10-26T22:58:38.806339+08:00", "kind": "documentation", "sha256": "7b5391cd5a9094d49583f78816504062dfa0632b53040363bef6632ced3001ca", "snapshot_path": "sources/7b5391cd5a9094d49583f78816504062dfa0632b53040363bef6632ced3001ca.txt", "url": "https://hydroserver.org/introduction/hydroserver-overview.html"}, {"fetched_at": "2026-10-26T23:03:01.541573+08:00", "kind": "repository_metadata", "sha256": "8ed33c6938b597d3e446105a035ef9d881f1b28f7bf8b25537e2be6a7dc2db06", "snapshot_path": "sources/8ed33c6938b597d3e446105a035ef9d881f1b28f7bf8b25537e2be6a7dc2db06.txt", "url": "https://api.github.com/repos/hydroserver2/hydroserver"}, {"fetched_at": "2026-10-26T23:03:03.588214+08:00", "kind": "license", "sha256": "fb802d2de5a7feec2c7dff84a8907b912ed90ebec105d446a826dffca73c5c33", "snapshot_path": "sources/fb802d2de5a7feec2c7dff84a8907b912ed90ebec105d446a826dffca73c5c33.txt", "url": "https://api.github.com/repos/hydroserver2/hydroserver/license"}, {"fetched_at": "2026-10-26T23:03:07.743816+08:00", "kind": "documentation", "sha256": "beb107d9a2e1a0c8d0b8a54c731222d899fe8899fd298636c0c739d2b4f338c9", "snapshot_path": "sources/beb107d9a2e1a0c8d0b8a54c731222d899fe8899fd298636c0c739d2b4f338c9.txt", "url": "https://hydroserver.org/"}], "summary": "开源、可自托管的环境监测时序数据平台，面向水文与环境监测站点，提供观测数据的采集、存储、管理、共享，以及站点/数据流元数据、ETL编排和访问控制。", "technology_stack": ["Django", "TypeScript", "PostgreSQL", "VitePress"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:workiva','Workiva','{"homepage": "https://www.workiva.com", "id": "commercial:workiva", "leaf_matches": [{"reason": "Workiva 将披露文件作为受控记录生产与报送，提供数据连接、协作审核/认证、版本控制、审计轨迹、XBRL 标记校验、跨期滚动及 SEC 等目的地提交；ESG 页面明确将 ESG 数据以 SEC-ready、XBRL 格式校验并与可持续发展报告整合，符合以披露文件及其治理生命周期为中心的类型关系。", "slug": "esg-disclosure-management", "source_urls": ["https://www.workiva.com/solutions/esg-reporting", "https://www.workiva.com/solutions/sec-reporting"]}], "name": "Workiva", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:00:00.022161+08:00", "kind": "homepage", "sha256": "7e20d0f6b20b4ed5ac6ee906a71df7c007b9b0506b6317ffe523b65b4aa382bb", "snapshot_path": "sources/7e20d0f6b20b4ed5ac6ee906a71df7c007b9b0506b6317ffe523b65b4aa382bb.txt", "url": "https://www.workiva.com/"}, {"fetched_at": "2026-10-26T23:00:04.404853+08:00", "kind": "documentation", "sha256": "3dfb0df635682bb82c42a0bcb3d559ef4c6e3f408a33673bc5dd276a8e698f55", "snapshot_path": "sources/3dfb0df635682bb82c42a0bcb3d559ef4c6e3f408a33673bc5dd276a8e698f55.txt", "url": "https://www.workiva.com/solutions/esg-reporting"}, {"fetched_at": "2026-10-26T23:00:06.937594+08:00", "kind": "documentation", "sha256": "eb12331a506262c525cd800121fc8db12c785934ff31011502eb7cbe9bb6efa8", "snapshot_path": "sources/eb12331a506262c525cd800121fc8db12c785934ff31011502eb7cbe9bb6efa8.txt", "url": "https://www.workiva.com/solutions/sec-reporting"}], "summary": "商业云平台，用于财务与可持续发展披露的受控生产与报送：将披露内容连接至受控数据源，支持多人协作、审核与认证、版本和审计轨迹、XBRL 标记校验、跨期滚动及向监管目的地提交。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:533334646','Portail RSE','{"deployment": ["Docker Compose 本地部署", "Scalingo 生产部署", "自托管 Django + PostgreSQL 实例"], "features": ["企业档案与报告期管理", "RSE 义务填报、跟踪与验证", "VSME 披露项及数据模式（schema）", "环境、社会、治理三类指标组织", "XLSX 与 PPTX 报告导出", "Django 管理后台与用户/权限支持"], "github_repository_id": 533334646, "homepage": "https://app.portail-rse.beta.gouv.fr", "id": "github:533334646", "leaf_matches": [{"reason": "Portail RSE 以企业/报告期为范围保存 ESG 绩效与公司记录，按 VSME 的披露项和 E/S/G 分类组织填报，按 schema 校验，并生成 XLSX/PPTX 对外报告；其数据记录—披露结构—交付物三层与 ESG 报告平台核心一致。", "slug": "esg-reporting-platform", "source_urls": ["https://raw.githubusercontent.com/betagouv/portail-rse/main/doc/overview.md", "https://raw.githubusercontent.com/betagouv/portail-rse/main/impact/vsme/models.py", "https://raw.githubusercontent.com/betagouv/portail-rse/main/impact/vsme/export_xlsx.py"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/LICENSE", "license_review": {"rationale": "读取仓库 LICENSE 全文，确认是 GNU Affero General Public License 第 3 版的完整条款文本，包含网络使用对应的源码提供义务；与仓库根目录许可证文件及 AGPL-3.0 标识一致。", "reviewer": "OpenCode collection review unit 207", "scope": "repository", "source_url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "Portail RSE", "repository_url": "https://github.com/betagouv/portail-rse", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:01:50.712520+08:00", "kind": "repository_metadata", "sha256": "c288c60f8744b393b46d79ecf2588d87682ed6206497711ac4f8f87a284a29bc", "snapshot_path": "sources/c288c60f8744b393b46d79ecf2588d87682ed6206497711ac4f8f87a284a29bc.txt", "url": "https://github.com/betagouv/portail-rse"}, {"fetched_at": "2026-10-26T23:01:53.146690+08:00", "kind": "readme", "sha256": "2564a8c5f6aacdfbaf436a587c2a3465285e61b1d1054ad1dad0c20a6b3b4ee1", "snapshot_path": "sources/2564a8c5f6aacdfbaf436a587c2a3465285e61b1d1054ad1dad0c20a6b3b4ee1.txt", "url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/README.md"}, {"fetched_at": "2026-10-26T23:01:55.159958+08:00", "kind": "license", "sha256": "8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef", "snapshot_path": "sources/8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef.txt", "url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/LICENSE"}, {"fetched_at": "2026-10-26T23:01:56.804806+08:00", "kind": "documentation", "sha256": "b0840a43aff7856f413472337da9f19b814a5f4eedc5cd01ffac00c372f2f67e", "snapshot_path": "sources/b0840a43aff7856f413472337da9f19b814a5f4eedc5cd01ffac00c372f2f67e.txt", "url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/doc/overview.md"}, {"fetched_at": "2026-10-26T23:01:58.318779+08:00", "kind": "documentation", "sha256": "44c5ce43bcbb8b4e87a4b933edacd5009910cdfdcd5fddaad90dc4243a8e4772", "snapshot_path": "sources/44c5ce43bcbb8b4e87a4b933edacd5009910cdfdcd5fddaad90dc4243a8e4772.txt", "url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/impact/vsme/models.py"}, {"fetched_at": "2026-10-26T23:01:59.984449+08:00", "kind": "documentation", "sha256": "9755128ba7bac99c16cad72e0aa2cc1d8478c0833befd1fe66678f5c38be3526", "snapshot_path": "sources/9755128ba7bac99c16cad72e0aa2cc1d8478c0833befd1fe66678f5c38be3526.txt", "url": "https://raw.githubusercontent.com/betagouv/portail-rse/main/impact/vsme/export_xlsx.py"}], "summary": "开源（AGPL-3.0）的 RSE/ESG 披露填报平台：企业按报告期维护公司数据与 VSME 披露项，按环境、社会、治理分类组织指标，生成 XLSX/PPTX 报告，并跟踪和验证 RSE 义务。", "technology_stack": ["Python", "Django", "Svelte", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:energycap','EnergyCAP','{"homepage": "https://www.energycap.com", "id": "commercial:energycap", "leaf_matches": [{"reason": "EnergyCAP 以电、天然气、水、污水、蒸汽等多类公用事业为对象，集中保存消耗量与费用，自动校验账单和异常，按归一化建筑基准比较，并通过 IPMVP 基线测量验证节能效果；符合多资源消耗账本与效率闭环的核心。", "slug": "resource-efficiency-management", "source_urls": ["https://www.energycap.com/utility-bill-energy-management-software/", "https://www.energycap.com/product-features/"]}], "name": "EnergyCAP", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:03:14.249416+08:00", "kind": "homepage", "sha256": "ceadc834d36f07eaa2dd7dbeb7af75145dea03d30167b21c0b6328ea9b333085", "snapshot_path": "sources/ceadc834d36f07eaa2dd7dbeb7af75145dea03d30167b21c0b6328ea9b333085.txt", "url": "https://www.energycap.com/"}, {"fetched_at": "2026-10-26T23:03:17.968954+08:00", "kind": "documentation", "sha256": "168a10484f80d6629ed857078c6762a32799407a2bef70123ceb15ba0d48999d", "snapshot_path": "sources/168a10484f80d6629ed857078c6762a32799407a2bef70123ceb15ba0d48999d.txt", "url": "https://www.energycap.com/product-features/"}, {"fetched_at": "2026-10-26T23:03:20.749043+08:00", "kind": "documentation", "sha256": "fdd3051e792dc3724425780583931159dc7a0a585c66247476b3f5ffe4b8d399", "snapshot_path": "sources/fdd3051e792dc3724425780583931159dc7a0a585c66247476b3f5ffe4b8d399.txt", "url": "https://www.energycap.com/utility-bill-energy-management-software/"}], "summary": "商业能源与公用事业数据管理平台：集中电、天然气、水、污水、蒸汽等多类资源的账单与表计数据，保留消耗与费用，自动校验账单与异常，支持建筑基准比较、归一化节能测量验证和排放输出。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ecovadis','EcoVadis','{"homepage": "https://ecovadis.com/", "id": "commercial:ecovadis", "leaf_matches": [{"reason": "EcoVadis Ratings 以供应商为对象保存经分析的评级与记分卡，供应商参与问卷和证据提交，并通过可跟踪的纠正行动计划推动改进；官方页面还说明评级可用于采购生命周期。", "slug": "supplier-sustainability-management", "source_urls": ["https://ecovadis.com/ratings/"]}], "name": "EcoVadis", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:52.442787+08:00", "kind": "documentation", "sha256": "972a20e0dfa0192fd4ef22c0cfd1fb085b36fa27bb4641f026b3c2493205bf5f", "snapshot_path": "sources/972a20e0dfa0192fd4ef22c0cfd1fb085b36fa27bb4641f026b3c2493205bf5f.txt", "url": "https://ecovadis.com/ratings/"}], "summary": "面向采购组织的供应商可持续性评级平台：供应商完成问卷与证据提交，EcoVadis 分析核验后形成环境、劳工与人权、道德、可持续采购维度的记分卡，并支持供应商纠正行动计划及在采购生命周期中使用评级。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:watershed','Watershed','{"homepage": "https://watershed.com/", "id": "commercial:watershed", "leaf_matches": [{"reason": "Watershed 汇集多领域 ESG 与排放数据并保留计算来源和审计轨迹，支持目标设定、减排行动与进展跟踪，并输出披露报告。", "slug": "sustainability-management-platform", "source_urls": ["https://watershed.com/platform"]}], "name": "Watershed", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:44.848270+08:00", "kind": "documentation", "sha256": "1db9da90024b9229838ac8e3fa653794d2c65773183cba2bdd29722c3c8483f5", "snapshot_path": "sources/1db9da90024b9229838ac8e3fa653794d2c65773183cba2bdd29722c3c8483f5.txt", "url": "https://watershed.com/platform"}], "summary": "面向企业的可持续发展数据与披露平台：汇集并清洗多来源 ESG 与排放数据，保留计算来源和审计轨迹，支持目标设定、减排行动与进展跟踪，并复用同一数据产出对外报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:jaggaer','JAGGAER ESG Intelligence','{"homepage": "https://www.jaggaer.com/", "id": "commercial:jaggaer", "leaf_matches": [{"reason": "JAGGAER ESG Intelligence 将供应商 ESG 数据、可配置记分卡与文件核验用于采购流程，并明确在 RFx 评标授标中计入可持续性指标和碳价。", "slug": "sustainable-procurement-platform", "source_urls": ["https://www.jaggaer.com/solutions/esg-intelligence/"]}], "name": "JAGGAER ESG Intelligence", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:52.922130+08:00", "kind": "documentation", "sha256": "890d7ab65566211c6012bcf8653fb47108fc0e135d7726bf54da2af95675812c", "snapshot_path": "sources/890d7ab65566211c6012bcf8653fb47108fc0e135d7726bf54da2af95675812c.txt", "url": "https://www.jaggaer.com/solutions/esg-intelligence/"}], "summary": "采购套件中的 ESG 智能模块：集中供应商排放、风险评分与证书数据，提供可配置记分卡、文件核验和改进计划，并在 RFx 评标授标中计入碳价与可持续性指标。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:klir','Klir','{"homepage": "https://www.klir.com/", "id": "commercial:klir", "leaf_matches": [{"reason": "Klir 面向污水处理机构管理 NPDES 许可证、监测参数与限值、采样结果和超标预警，并从同一数据源生成 DMR 报告。", "slug": "wastewater-compliance-management", "source_urls": ["https://www.klir.com/klir-for-wastewater"]}], "name": "Klir", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:45.361090+08:00", "kind": "documentation", "sha256": "4e70674dfb005823edb2d08c71002fdae20239aefc6b45cec86f6bd7b46db326", "snapshot_path": "sources/4e70674dfb005823edb2d08c71002fdae20239aefc6b45cec86f6bd7b46db326.txt", "url": "https://www.klir.com/klir-for-wastewater"}], "summary": "面向水务与污水处理机构的合规管理平台：集中 NPDES 许可证的参数与限值、采样结果、超标预警和 DMR 报告，并提供现场移动录入与合规任务跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3199417','AirCasting','{"deployment": ["Capistrano 部署到自托管服务器", "bin/setup 本地开发环境"], "features": ["固定与移动监测会话", "测量流和时间序列", "环境数据可视化与共享", "按时间范围查询测量值与平均值", "固定站点活跃/休眠状态"], "github_repository_id": 3199417, "homepage": "https://aircasting.org/", "id": "github:3199417", "leaf_matches": [{"reason": "AirCasting 以固定/移动监测会话承载污染物测量流，API 文档提供按时间范围的测量值、平均值和固定站点状态查询，平台用于环境数据的可视化与共享。", "slug": "air-quality-monitoring", "source_urls": ["https://api.github.com/repos/HabitatMap/AirCasting", "https://api.github.com/repos/HabitatMap/AirCasting/readme", "https://raw.githubusercontent.com/HabitatMap/AirCasting/master/doc/api.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/HabitatMap/AirCasting/license", "name": "AirCasting", "repository_url": "https://github.com/HabitatMap/AirCasting", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T22:58:02.491907+08:00", "kind": "repository_metadata", "sha256": "28289ee5ebf345868b187bd49c80e5afba6ec6be0ee4d3de75105ed690e6cab3", "snapshot_path": "sources/28289ee5ebf345868b187bd49c80e5afba6ec6be0ee4d3de75105ed690e6cab3.txt", "url": "https://api.github.com/repos/HabitatMap/AirCasting"}, {"fetched_at": "2026-10-26T22:58:04.477765+08:00", "kind": "license", "sha256": "0ca149aca8719e24bcf538fd1fad4907d86e4c177e0c338252e85ca202a3846b", "snapshot_path": "sources/0ca149aca8719e24bcf538fd1fad4907d86e4c177e0c338252e85ca202a3846b.txt", "url": "https://api.github.com/repos/HabitatMap/AirCasting/license"}, {"fetched_at": "2026-10-26T22:58:01.852295+08:00", "kind": "readme", "sha256": "b9d42c9d6f37779845ed9675f9e2b0dcfa8ee9a62ad2a6daca94fb4efb2faa66", "snapshot_path": "sources/b9d42c9d6f37779845ed9675f9e2b0dcfa8ee9a62ad2a6daca94fb4efb2faa66.txt", "url": "https://api.github.com/repos/HabitatMap/AirCasting/readme"}, {"fetched_at": "2026-10-26T22:59:39.707055+08:00", "kind": "documentation", "sha256": "1fc7e4fe5c47668e872cfd841a28e923946598e1e5d38343b4232402b20c89a2", "snapsho