INSERT INTO "application" VALUES('commercial:teledyne-monitor-labs-regperfect','Teledyne Monitor Labs RegPerfect','{"homepage": "https://www.teledyne-ml.com/", "id": "commercial:teledyne-monitor-labs-regperfect", "leaf_matches": [{"reason": "RegPerfect 是 CEMS 的 DAHS，官方正文明确其实时数据采集、质量保证和排放合规报告能力，对应受监管排放源的数据处理核心。", "slug": "emissions-monitoring-cems", "source_urls": ["https://www.teledyne-ml.com/en-us/products/data-acquisition-handling-system"]}], "name": "Teledyne Monitor Labs RegPerfect", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:03:33.049353+08:00", "kind": "documentation", "sha256": "47befea29708945b36df270ba9eb17d21e49a583779528439191c21c5a3f8f0e", "snapshot_path": "sources/47befea29708945b36df270ba9eb17d21e49a583779528439191c21c5a3f8f0e.txt", "url": "https://www.teledyne-ml.com/en-us/products/data-acquisition-handling-system"}, {"fetched_at": "2026-10-26T23:03:37.384383+08:00", "kind": "homepage", "sha256": "4013b209a87cc0f8ea34c727942c5bde5f195332210cfdbb50e55208b96bf9d5", "snapshot_path": "sources/4013b209a87cc0f8ea34c727942c5bde5f195332210cfdbb50e55208b96bf9d5.txt", "url": "https://www.teledyne-ml.com/"}], "summary": "面向连续排放监测系统（CEMS）的数据采集、处理与报告软件（DAHS）：从 CEM 系统实时采集数据，执行质量保证与联邦/地方监管报告要求，并提供访问授权控制。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16999809','openSenseMap','{"deployment": ["Node.js 16、MongoDB 与 Docker Compose 自托管", "README 引用 OSeM-compose 作为整套平台部署方式"], "features": ["senseBox 监测点注册、位置与归属管理", "传感器最新测量与按时间段查询历史测量", "多监测点/标签聚合及描述统计、IDW 插值接口", "JWT 用户认证与设备转移"], "github_repository_id": 16999809, "homepage": "https://opensensemap.org/", "id": "github:16999809", "leaf_matches": [{"reason": "平台按 senseBox 监测点保存传感器最新与历史测量，前端提供地图和站点可视化，符合环境监测点的持续观测循环。", "slug": "environmental-monitoring-platform", "source_urls": ["https://raw.githubusercontent.com/sensebox/openSenseMap-API/master/README.md", "https://api.opensensemap.org/", "https://raw.githubusercontent.com/sensebox/openSenseMap/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/sensebox/openSenseMap-API/license", "name": "openSenseMap", "repository_url": "https://github.com/sensebox/openSenseMap-API", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:03:01.579731+08:00", "kind": "repository_metadata", "sha256": "a6457e6249fb76cdc7d9e3b276f09852503d7fa5e928a51cae54f43cb88fd6df", "snapshot_path": "sources/a6457e6249fb76cdc7d9e3b276f09852503d7fa5e928a51cae54f43cb88fd6df.txt", "url": "https://api.github.com/repos/sensebox/openSenseMap-API"}, {"fetched_at": "2026-10-26T23:03:03.360656+08:00", "kind": "license", "sha256": "891d1686532c27a65e7c3552beb5a4262e520a782f28ffbebf69eafbd7ee74d2", "snapshot_path": "sources/891d1686532c27a65e7c3552beb5a4262e520a782f28ffbebf69eafbd7ee74d2.txt", "url": "https://api.github.com/repos/sensebox/openSenseMap-API/license"}, {"fetched_at": "2026-10-26T23:03:05.385104+08:00", "kind": "readme", "sha256": "4a60f5d8eb99993dbabbef39bada24706bbfa4b4ff666ffc874db8ac129b4f5c", "snapshot_path": "sources/4a60f5d8eb99993dbabbef39bada24706bbfa4b4ff666ffc874db8ac129b4f5c.txt", "url": "https://raw.githubusercontent.com/sensebox/openSenseMap-API/master/README.md"}, {"fetched_at": "2026-10-26T23:03:07.638599+08:00", "kind": "documentation", "sha256": "6b13858abfd7dfe5d8efca6a5aa9c94a59c771fc4da077734f16c11afe112918", "snapshot_path": "sources/6b13858abfd7dfe5d8efca6a5aa9c94a59c771fc4da077734f16c11afe112918.txt", "url": "https://api.opensensemap.org/"}, {"fetched_at": "2026-10-26T23:03:08.899948+08:00", "kind": "readme", "sha256": "67185b6fde89e8f75e92b006131d5df4351d6af57f16457f40bd8eef89d01eec", "snapshot_path": "sources/67185b6fde89e8f75e92b006131d5df4351d6af57f16457f40bd8eef89d01eec.txt", "url": "https://raw.githubusercontent.com/sensebox/openSenseMap/master/README.md"}, {"fetched_at": "2026-10-26T23:03:11.184701+08:00", "kind": "homepage", "sha256": "a05848b2fa660d6ab26ec691430bba17d875686cb12c077e30965da460b2fa71", "snapshot_path": "sources/a05848b2fa660d6ab26ec691430bba17d875686cb12c077e30965da460b2fa71.txt", "url": "https://opensensemap.org/"}], "summary": "openSenseMap 是开源的环境传感器数据发布与可视化平台：以 senseBox 为监测点，持续接收传感器测量，提供站点最新读数、历史测量查询和多站点聚合统计；本条目以 MIT 许可的 API 后端为身份，展示层由同为 MIT 的独立前端提供。", "technology_stack": ["Node.js", "MongoDB", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
