INSERT INTO "application" VALUES('github:1031078379','Ingwe Bika LIMS 4','{"deployment": ["Docker Compose", "self-hosted"], "features": ["sample tracking", "analytical workflows", "instrument integration", "quality control", "results reporting", "ISO 17025 support", "Docker Compose deployment"], "github_repository_id": 1031078379, "homepage": "https://www.bikalims.org/", "id": "github:1031078379", "leaf_matches": [{"reason": "Official Docker distribution README states it installs Bika/SENAITE LIMS for sample tracking, analytical workflows, instrument integration, QC and results reporting; the repository is packaging, with application source in upstream SENAITE repositories.", "slug": "laboratory-information-management-system-lims", "source_urls": ["https://api.github.com/repos/bikalims/bika.lims", "https://api.github.com/repos/bikalims/bika.lims/license", "https://raw.githubusercontent.com/bikalims/bika.lims/main/README.md"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/bikalims/bika.lims/license", "name": "Ingwe Bika LIMS 4", "repository_url": "https://github.com/bikalims/bika.lims", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:34.274005+08:00", "kind": "repository_metadata", "sha256": "e0f7968ca08382d3725233fcbcbda5e45964fd566b6eaacd56e7b39fcfe807a5", "snapshot_path": "sources/e0f7968ca08382d3725233fcbcbda5e45964fd566b6eaacd56e7b39fcfe807a5.txt", "url": "https://api.github.com/repos/bikalims/bika.lims"}, {"fetched_at": "2026-10-25T08:02:35.877046+08:00", "kind": "license", "sha256": "4357eeb29c20808c598f821c9ca0145346f06939f3b76dc0538029d02a3dc82a", "snapshot_path": "sources/4357eeb29c20808c598f821c9ca0145346f06939f3b76dc0538029d02a3dc82a.txt", "url": "https://api.github.com/repos/bikalims/bika.lims/license"}, {"fetched_at": "2026-10-26T23:43:09.256962+08:00", "kind": "readme", "sha256": "a324911ebe5e279945072323b0444fff4ea1f668b462e9c961bf9c94bdb16f0e", "snapshot_path": "sources/a324911ebe5e279945072323b04