INSERT INTO "application" VALUES('github:165933530','OpenELIS Global 2','{"deployment": ["Docker Compose", "self-hosted"], "features": ["laboratory order intake", "specimen accessioning and workflow", "analyzer result import", "result validation and quality control", "FHIR and HL7 result exchange", "public-health laboratory reporting"], "github_repository_id": 165933530, "homepage": "https://openelis-global.org/", "id": "github:165933530", "leaf_matches": [{"reason": "Repository metadata and README describe a clinical/public-health LIS/LIMS with laboratory orders, specimen workflows, clinical analyzer result import, result validation and FHIR/HL7 result exchange to care systems.", "slug": "laboratory-information-system-lis", "source_urls": ["https://api.github.com/repos/DIGI-UW/OpenELIS-Global-2", "https://api.github.com/repos/DIGI-UW/OpenELIS-Global-2/license", "https://raw.githubusercontent.com/DIGI-UW/OpenELIS-Global-2/develop/README.md"]}], "license": "MPL-2.0", "license_evidence_url": "https://api.github.com/repos/DIGI-UW/OpenELIS-Global-2/license", "name": "OpenELIS Global 2", "repository_url": "https://github.com/DIGI-UW/OpenELIS-Global-2", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:42:56.007160+08:00", "kind": "repository_metadata", "sha256": "814cb712c5a124efed97e9b9ed23a65986e1a1fdd32e1d0ec438527713f731ea", "snapshot_path": "sources/814cb712c5a124efed97e9b9ed23a65986e1a1fdd32e1d0ec438527713f731ea.txt", "url": "https://api.github.com/repos/DIGI-UW/OpenELIS-Global-2"}, {"fetched_at": "2026-10-26T23:42:58.096840+08:00", "kind": "license", "sha256": "6380408d6f2c28e02f0d3ab1177bfc77589d49ac8afb00e7f224fcd4628e8d6b", "snapshot_path": "sources/6380408d6f2c28e02f0d3ab1177bfc77589d49ac8afb00e7f224fcd4628e8d6b.txt", "url": "https://api.github.com/repos/DIGI-UW/OpenELIS-Global-2/license"}, {"fetched_at": "2026-10-26T23:43:10.168722+08:00", "kind": "readme", "sha256": "c7e243a4791f50990cbc900ba743141fd1bec90b0bb0f551d549261caf5bf9ca", "snapsho