INSERT INTO "application" VALUES('commercial:aidoc','Aidoc','{"homepage": "https://www.aidoc.com/", "id": "commercial:aidoc", "leaf_matches": [{"reason": "Official radiology page states AI triage results are marked directly in the PACS worklist, key images and result summaries are provided, results of every algorithm run are visible with and without AI findings, and the radiologist sees which pathologies to confirm; the aiOS page documents PACS/EHR integration and urgency-based triage. This matches image-derived results delivered into clinical review with clinician decision authority.", "slug": "medical-image-analysis-platform", "source_urls": ["https://www.aidoc.com/platform/aios/", "https://www.aidoc.com/solutions/radiology/"]}], "name": "Aidoc", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:44:58.257377+08:00", "kind": "homepage", "sha256": "ea37bcc318749d9968d511e714d2984112881bd53d35feab9fd933c64dc32b63", "snapshot_path": "sources/ea37bcc318749d9968d511e714d2984112881bd53d35feab9fd933c64dc32b63.txt", "url": "https://www.aidoc.com/"}, {"fetched_at": "2026-10-26T23:45:38.451422+08:00", "kind": "documentation", "sha256": "4d50b817d44ec72d967169e76d9239370232743389192c2522ea1d8ef4f6dbcb", "snapshot_path": "sources/4d50b817d44ec72d967169e76d9239370232743389192c2522ea1d8ef4f6dbcb.txt", "url": "https://www.aidoc.com/platform/aios/"}, {"fetched_at": "2026-10-26T23:45:37.829271+08:00", "kind": "documentation", "sha256": "506a05c4830285357da8b2d8837d21b42d661c13362b6796c0e9374f6e7650a3", "snapshot_path": "sources/506a05c4830285357da8b2d8837d21b42d661c13362b6796c0e9374f6e7650a3.txt", "url": "https://www.aidoc.com/solutions/radiology/"}], "summary": "Commercial clinical AI platform (aiOS) that analyzes medical images, marks triage results in the radiology worklist, and routes suspected and incidental findings to care teams for clinician confirmation; integrates with PACS, EHR, scheduling and reporting systems.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:15527090','Orthanc','{"deployment": ["server", "on-premises", "Linux", "Windows", "macOS"], "features": ["DICOM receive, upload and transfer", "study archive", "REST API for imaging flows", "DICOMweb plugin", "official web viewer plugins"], "github_repository_id": 15527090, "homepage": "https://www.orthanc-server.com/", "id": "github:15527090", "leaf_matches": [{"reason": "Official about page calls Orthanc a standalone DICOM store (\"mini-PACS\") that improves hospital DICOM flows, stores medical images and ships a Web viewer plugin; the homepage documents upload/receive/transfer, Web interface and REST API, and links to DICOMweb and whole-slide plugins. GitHub metadata/license confirm repository identity and GPL-3.0. The GitHub README is a release-mirror notice pointing to the canonical Mercurial source, so functionality is evidenced by the official about/homepage and plugin pages rather than that README.", "slug": "pacs", "source_urls": ["https://www.orthanc-server.com/static.php?page=about", "https://www.orthanc-server.com/", "https://www.orthanc-server.com/static.php?page=web-viewer", "https://api.github.com/repos/jodogne/Orthanc", "https://api.github.com/repos/jodogne/Orthanc/license"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/jodogne/Orthanc/license", "name": "Orthanc", "repository_url": "https://github.com/jodogne/Orthanc", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:10.434398+08:00", "kind": "repository_metadata", "sha256": "90c33cea6c82c57abc99f08d30293096e3230a9ad7e7b2fe36a34ede76037380", "snapshot_path": "sources/90c33cea6c82c57abc99f08d30293096e3230a9ad7e7b2fe36a34ede76037380.txt", "url": "https://api.github.com/repos/jodogne/Orthanc"}, {"fetched_at": "2026-10-25T08:02:21.484543+08:00", "kind": "license", "sha256": "aed60ca286079267d75ad2fd3a60ac2d0bdbcfb46d5a3ff62d82ea6a56b770d5", "snapshot_path": "sources/aed60ca286079267d75ad2fd3a60ac2d0bdbcfb46d5a3ff62d82ea6a56b770d5.txt", "url": "https://api.github.com/repos/jodogne/Orthanc/license"}, {"fetched_at": "2026-10-25T08:02:27.621430+08:00", "kind": "readme", "sha256": "62287cbb802a589e35ac93255b9a382246689fa20b3abbf48397236ed5bf3930", "snapshot_path": "sources/62287cbb802a589e35ac93255b9a382246689fa20b3abbf48397236ed5bf3930.txt", "url": "https://raw.githubusercontent.com/jodogne/Orthanc/master/README.md"}, {"fetched_at": "2026-10-26T23:43:23.983259+08:00", "kind": "homepage", "sha256": "e0b17f28b08190c85a629e625c4a5812af855bacf1090aaf532a5a2311ad74dc", "snapshot_path": "sources/e0b17f28b08190c85a629e625c4a5812af855bacf1090aaf532a5a2311ad74dc.txt", "url": "https://www.orthanc-server.com/"}, {"fetched_at": "2026-10-26T23:44:08.364584+08:00", "kind": "documentation", "sha256": "600d4a90a55fe6e3acb3839e2a615b78c263ef6e0891fee3ec174ab90232368c", "snapshot_path": "sources/600d4a90a55fe6e3acb3839e2a615b78c263ef6e0891fee3ec174ab90232368c.txt", "url": "https://www.orthanc-server.com/static.php?page=web-viewer"}, {"fetched_at": "2026-10-26T23:48:18.343006+08:00", "kind": "documentation", "sha256": "e00c9b763ab683f4829f0d9c396eb6c95154e838b80d5b4a5455f4f57367d35b", "snapshot_path": "sources/e00c9b763ab683f4829f0d9c396eb6c95154e838b80d5b4a5455f4f57367d35b.txt", "url": "https://www.orthanc-server.com/static.php?page=about"}], "summary": "Open-source standalone DICOM server and store (mini-PACS) for medical imaging: receives and archives DICOM studies, exposes REST/DICOMweb access, and serves images through official web-viewer plugins; GPL-3.0 licensed.", "technology_stack": ["C++"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:474123487','Sirius RIS','{"deployment": ["web application", "Docker"], "features": ["patient and appointment intake", "modality worklist over HL7/MLLP", "report export", "signer and authenticator roles", "role-based access"], "github_repository_id": 474123487, "homepage": "https://github.com/opendicom/sirius-ris", "id": "github:474123487", "leaf_matches": [{"reason": "README describes an open-source radiological information system built with Angular/NodeJS/MongoDB/Docker and interoperating with MWL and DICOM/PACS services; architecture documents patient/appointment-driven HL7/MLLP modality worklist messages; API documentation documents report export and signer/authenticator role lookup, and the data dictionary documents report revision, medical signatures and authenticated-report fields. Together these support an imaging-exam workflow and report lifecycle. License verified via GitHub license API.", "slug": "radiology-information-system-ris", "source_urls": ["https://raw.githubusercontent.com/opendicom/sirius-ris/master/README.md", "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/02_architecture.md", "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/04_sirius_backend_api_rest.md", "https://api.github.com/repos/opendicom/sirius-ris/license", "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/resources/dictionary-generator/data_dictionary.md"]}], "license": "MPL-2.0", "license_evidence_url": "https://api.github.com/repos/opendicom/sirius-ris/license", "name": "Sirius RIS", "repository_url": "https://github.com/opendicom/sirius-ris", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:02:49.250567+08:00", "kind": "repository_metadata", "sha256": "f92ec35c71a31431ab572c9e657ecfbcd7e08c63d0153dd1d8a98fe6782517b3", "snapshot_path": "sources/f92ec35c71a31431ab572c9e657ecfbcd7e08c63d0153dd1d8a98fe6782517b3.txt", "url": "https://api.github.com/repos/opendicom/sirius-ris"}, {"fetched_at": "2026-10-25T08:02:50.777168+08:00", "kind": "license", "sha256": "7b8e4977e4ae69a599912166b9a4b7cbad0fc2b1f813505e24a68fdc1daceedf", "snapshot_path": "sources/7b8e4977e4ae69a599912166b9a4b7cbad0fc2b1f813505e24a68fdc1daceedf.txt", "url": "https://api.github.com/repos/opendicom/sirius-ris/license"}, {"fetched_at": "2026-10-26T23:44:07.955943+08:00", "kind": "readme", "sha256": "a949d55bc03fe6fda2a61363f5430f619f29d7079625e78ecf6d0365270eb64a", "snapshot_path": "sources/a949d55bc03fe6fda2a61363f5430f619f29d7079625e78ecf6d0365270eb64a.txt", "url": "https://raw.githubusercontent.com/opendicom/sirius-ris/master/README.md"}, {"fetched_at": "2026-10-26T23:43:22.684715+08:00", "kind": "documentation", "sha256": "75821ffdb30108d81639fd8b7986e73e9922628f3e59dce0071df031460affb4", "snapshot_path": "sources/75821ffdb30108d81639fd8b7986e73e9922628f3e59dce0071df031460affb4.txt", "url": "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/02_architecture.md"}, {"fetched_at": "2026-10-26T23:45:31.901184+08:00", "kind": "documentation", "sha256": "1c9d8678d3bd1d42f1eae77fc8bc8c06ec369c16a64e6ceac2a12602aafa5a42", "snapshot_path": "sources/1c9d8678d3bd1d42f1eae77fc8bc8c06ec369c16a64e6ceac2a12602aafa5a42.txt", "url": "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/04_sirius_backend_api_rest.md"}, {"fetched_at": "2026-10-26T23:49:19.818978+08:00", "kind": "documentation", "sha256": "9cf188d59130570657d4d3436bdb41052912a3335d949ec96542433273793ca6", "snapshot_path": "sources/9cf188d59130570657d4d3436bdb41052912a3335d949ec96542433273793ca6.txt", "url": "https://raw.githubusercontent.com/opendicom/sirius-ris/master/documentation/resources/dictionary-generator/data_dictionary.md"}], "summary": "Open-source radiology information system for imaging-exam workflow: patient and appointment intake, modality worklist delivery over HL7/MLLP, and radiologist reporting with signer/authenticator roles; MPL-2.0 licensed.", "technology_stack": ["Angular", "Node.js", "MongoDB", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:26468071','VOXCE','{"deployment": ["self-hosted Java web application"], "features": ["study and site records", "participant and visit records", "study and participant payment records", "query and discrepancy records"], "github_repository_id": 26468071, "homepage": "https://github.com/trialmanager/voxce", "id": "github:26468071", "leaf_matches": [{"reason": "README describes a clinical trial management framework; the source tree contains studies, StudySites/Sites, Patients/PatientVisits, StudyPayment and Queries/Discrepancies models, supporting the study-site operational record core. Last push in 2015 and no deployment docs, so the summary is narrowed to a dormant web application.", "slug": "clinical-trial-management-system-ctms", "source_urls": ["https://raw.githubusercontent.com/trialmanager/voxce/master/README.md", "https://github.com/trialmanager/voxce", "https://github.com/trialmanager/voxce/tree/master/src/com/Voxce/model"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/trialmanager/voxce/license", "name": "VOXCE", "repository_url": "https://github.com/trialmanager/voxce", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:21.477028+08:00", "kind": "repository_metadata", "sha256": "eff2b9a0055e58ee9640891807576df033fb2bc1b9657d9f780cff30469bb693", "snapshot_path": "sources/eff2b9a0055e58ee9640891807576df033fb2bc1b9657d9f780cff30469bb693.txt", "url": "https://api.github.com/repos/trialmanager/voxce"}, {"fetched_at": "2026-10-25T08:03:22.911076+08:00", "kind": "license", "sha256": "4d3f41e567cecf295235b8e03fb6f6e4b3ba70fbb811dfc5ef91954bde023f9d", "snapshot_path": "sources/4d3f41e567cecf295235b8e03fb6f6e4b3ba70fbb811dfc5ef91954bde023f9d.txt", "url": "https://api.github.com/repos/trialmanager/voxce/license"}, {"fetched_at": "2026-10-26T23:50:42.784975+08:00", "kind": "readme", "sha256": "1b6e1fba6694fb306e6925c1ebbf6f54c6b8d592f58e133eace40785fafad5bd", "snapshot_path": 