INSERT INTO "application" VALUES('github:494161860','OpenRecruit','{"deployment": ["cloud-native (Docker Compose, Kubernetes)"], "features": ["eligibility criteria as SQL", "automatic patient screening", "screening list and recruitment status", "attrition funnel", "notifications"], "github_repository_id": 494161860, "homepage": "https://openrecruit.dev/", "id": "github:494161860", "leaf_matches": [{"reason": "Official homepage states recruIT screens clinical data for patients matching a trial''s eligibility criteria, keeps a screening list with recruitment status, shows an attrition funnel and notifies the study team; metadata identifies it as a cloud-native clinical trial recruitment support system. Consent and enrollment remain with the site.", "slug": "clinical-trial-recruitment-platform", "source_urls": ["https://api.github.com/repos/open-recruit/recruit", "https://openrecruit.dev/", "https://raw.githubusercontent.com/open-recruit/recruit/master/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/open-recruit/recruit/license", "name": "OpenRecruit", "repository_url": "https://github.com/open-recruit/recruit", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:16.968807+08:00", "kind": "repository_metadata", "sha256": "2af23a6e5fb4472be2003c55c3783a2915a900cbc20667038a58179904273bf3", "snapshot_path": "sources/2af23a6e5fb4472be2003c55c3783a2915a900cbc20667038a58179904273bf3.txt", "url": "https://api.github.com/repos/open-recruit/recruit"}, {"fetched_at": "2026-10-25T08:03:19.935455+08:00", "kind": "license", "sha256": "1b1812024fc4e282584a37ac1e207e5e1cabecf0293d79798ea32fb9754a2112", "snapshot_path": "sources/1b1812024fc4e282584a37ac1e207e5e1cabecf0293d79798ea32fb9754a2112.txt", "url": "https://api.github.com/repos/open-recruit/recruit/license"}, {"fetched_at": "2026-10-26T23:50:42.679413+08:00", "kind": "readme", "sha256": "1b44fdbcbbd95c03ccf8d4a81f41eceb061e25acb2667a40846f16b52ab6ff44", "snapshot_path": "sources/1b44fdbcbbd95c03ccf8d4a81f41eceb061e25acb2667a40846f16b52ab6ff44.txt", "url": "https://raw.githubusercontent.com/open-recruit/recruit/master/README.md"}, {"fetched_at": "2026-10-26T23:51:01.819599+08:00", "kind": "homepage", "sha256": "9aba5cab62f8f80e8aef173fe573a6469489491c60c48e68909261c6c5ea4f26", "snapshot_path": "sources/9aba5cab62f8f80e8aef173fe573a6469489491c60c48e68909261c6c5ea4f26.txt", "url": "https://openrecruit.dev/"}], "summary": "Open-source, cloud-native clinical trial recruitment support system (recruIT) that screens clinical data against a study''s eligibility criteria, maintains a screening list and tracks recruitment status; AGPL-3.0 licensed.", "technology_stack": ["C#", "HL7 FHIR", "Trino", "DuckDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:169558966','LibreClinica','{"deployment": ["self-hosted web application (Tomcat, PostgreSQL)"], "features": ["electronic data capture (EDC)", "clinical data management (CDM)", "self-hosted web application"], "github_repository_id": 169558966, "homepage": "https://libreclinica.org", "id": "github:169558966", "leaf_matches": [{"reason": "README, official homepage and GitHub metadata identify LibreClinica as an open-source EDC/CDM web application that can be self-hosted; complete LICENSE text supports GPL-3.0 rather than the API''s LGPL-3.0 label.", "slug": "electronic-data-capture-edc", "source_urls": ["https://api.github.com/repos/reliatec-gmbh/LibreClinica", "https://api.github.com/repos/reliatec-gmbh/LibreClinica/license", "https://raw.githubusercontent.com/reliatec-gmbh/LibreClinica/lc-develop/README.md", "https://libreclinica.org/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/reliatec-gmbh/LibreClinica/license", "license_review": {"rationale": "完整 LICENSE 快照是 GNU GPL v3 全文（含 GPLv3 条款，仅在末尾提及 LGPL）；GitHub API 的 lgpl-3.0 归类与正文不符，按完整许可文本记为 GPL-3.0。", "reviewer": "unit-220 collector", "scope": "repository", "source_url": "https://api.github.com/repos/reliatec-gmbh/LibreClinica/license", "spdx_id": "GPL-3.0"}, "name": "LibreClinica", "repository_url": "https://github.com/reliatec-gmbh/LibreClinica", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:03:27.807563+08:00", "kind": "repository_metadata", "sha256": "c0c8cc3c3abe71e4c1e36ee41471f4dee59472616c83b30a3a7c69ed241e8e36", "snapshot_path": "sources/c0c8cc3c3abe71e4c1e36ee41471f4dee59472616c83b30a3a7c69ed241e8e36.txt", "url": "https://api.github.com/repos/reliatec-gmbh/LibreClinica"}, {"fetched_at": "2026-10-25T08:03:29.707684+08:00", "kind": "license", "sha256": "e112d77736f3fc442d1d29b31c84dc9279a5766785e5ded3f3b3bb896056c2c9", "snapshot_path": "sources/e112d77736f3fc442d1d29b31c84dc9279a5766785e5ded3f3b3bb896056c2c9.txt", "url": "https://api.github.com/repos/reliatec-gmbh/LibreClinica/license"}, {"fetched_at": "2026-10-26T23:50:41.907709+08:00", "kind": "readme", "sha256": "b4dacb075304a030f161bc7e4f5ba5f476d35c3d48aaa5833f5764dcab4f50e4", "snapshot_path": "sources/b4dacb075304a030f161bc7e4f5ba5f476d35c3d48aaa5833f5764dcab4f50e4.txt", "url": "https://raw.githubusercontent.com/reliatec-gmbh/LibreClinica/lc-develop/README.md"}, {"fetched_at": "2026-10-26T23:53:38.506293+08:00", "kind": "homepage", "sha256": "abd3237f09cfed3739f7e11bf6398938900381848de75e1be9ebb8c8fb4e3c5f", "snapshot_path": "sources/abd3237f09cfed3739f7e11bf6398938900381848de75e1be9ebb8c8fb4e3c5f.txt", "url": "https://libreclinica.org/"}], "summary": "Open-source, self-hosted clinical trial software for electronic data capture (EDC) and clinical data management (CDM); community successor of OpenClinica. GPL-3.0 licensed.", "technology_stack": ["Java", "Tomcat", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:658815259','OpenRIMS-PV (OpenPV)','{"deployment": ["Web 应用", "自托管"], "features": ["不良事件报告", "因果评估", "安全性信号生成", "E2B 个案安全报告导出", "主动监测与自发报告"], "github_repository_id": 658815259, "homepage": "https://openrims.org/", "id": "github:658815259", "leaf_matches": [{"reason": "官方项目页说明其面向不良事件报告与药物安全监测，覆盖数据收集、分析与报告全流程；用户手册进一步说明因果评估、严重性与安全性信号，并支持 E2B 个案安全报告导出，匹配安全案例处理与监管报告循环。", "slug": "pharmacovigilance-platform", "source_urls": ["https://www.openrims.org/", "https://wiki.openrims.org/index.php/OpenRIMS-PVM_-_User_Manual_Chapter_1", "https://github.com/MSH/OpenRIMS-PV", "https://raw.githubusercontent.com/MSH/OpenRIMS-PV/main/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/MSH/OpenRIMS-PV/main/LICENSE", "license_review": {"rationale": "仓库根目录 LICENSE 为完整 GNU GPL v3 文本，包含版本 3 条款与免责声明，与 GPL-3.0 标识一致。", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/MSH/OpenRIMS-PV/main/LICENSE", "spdx_id": "GPL-3.0"}, "name": "OpenRIMS-PV (OpenPV)", "repository_url": "https://github.com/MSH/OpenRIMS-PV", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T23:56:36.777837+08:00", "kind": "repository_metadata", "sha256": "26c3b0275b16cab20b1f198c3caf1ee778981604d50a407d8118a3812c634d0b", "snapshot_path": "sources/26c3b0275b16cab20b1f198c3caf1ee778981604d50a407d8118a3812c634d0b.txt", "url": "https://github.com/MSH/OpenRIMS-PV"}, {"fetched_at": "2026-10-26T23:56:38.487280+08:00", "kind": "license", "sha256": "3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986", "snapshot_path": "sources/3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986.txt", "url": "https://raw.githubusercontent.com/MSH/OpenRIMS-PV/main/LICENSE"}, {"fetched_at": "2026-10-26T23:56:39.802063+08:00", "kind": "readme", "sha256": "2aa6d479ecca46b2fe8c19e19cdfdb3e7c370a74569e091f608c81f8efc03b88", "snapshot_path": "sources/2aa6d479ecca46b2fe8c19e19cdfdb3e7c370a74569e091f608c81f8efc03b88.txt", "url": "https://raw.githubusercontent.com/MSH/OpenRIMS-PV/main/README.md"}, {"fetched_at": "2026-10-26T23:56:44.122971+08:00", "kind": "homepage", "sha256": "81d13acaafe048d1de04d4d6358b1b9c508b6b9e089c1feb4d103e64a9411a9f", "snapshot_path": "sources/81d13acaafe048d1de04d4d6358b1b9c508b6b9e089c1feb4d103e64a9411a9f.txt", "url": "https://www.openrims.org/"}, {"fetched_at": "2026-10-26T23:56:47.004728+08:00", "kind": "documentation", "sha256": "ac0a86c56a06b22dc91e2d1e80b9a34622b342f252c896d88dbc693f8db2a616", "snapshot_path": "sources/ac0a86c56a06b22dc91e2d1e80b9a34622b342f252c896d88dbc693f8db2a616.txt", "url": "https://wiki.openrims.org/index.php/OpenRIMS-PVM_-_User_Manual_Chapter_1"}], "summary": "面向监管机构与医疗机构药物警戒的开源 Web 应用，覆盖不良事件报告、因果评估、安全信号生成与 E2B 个案安全报告导出。", "technology_stack": ["C#", "TypeScript", "TSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:11130811','RosarioSIS','{"deployment": ["Web 应用", "自托管"], "features": ["教师成绩簿", "成绩区间设置", "作业权重", "作业跟踪", "季度/学期成绩", "进度报告", "报告卡与成绩单"], "github_repository_id": 11130811, "homepage": "https://www.rosariosis.org/", "id": "github:11130811", "leaf_matches": [{"reason": "Scheduling 帮助正文显示 Subjects/Courses/Course Periods 课程目录、Course Period 可设 Seats 与 Gender Restriction；Student Requests 供 Scheduler 排课，Run Scheduler 检查冲突并提示 zero available seats；Student Schedule 支持加课、按 Dropped 日期退课、换 Period/Teacher，Add/Drop Report 记录学期内变更。满足目录-学生-规则校验-生命周期核心。", "slug": "course-registration-system", "source_urls": ["https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/Help_en.php", "https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/README.md", "https://github.com/francoisjacquet/rosariosis"]}, {"reason": "README 明确描述 comprehensive grade book：教师可设置成绩区间、按作业加权、跟踪作业并发布季度/学期成绩与进度报告，匹配班级名册-评分项目-成绩账本-总成绩核心；关系限于其成绩簿模块。", "slug": "digital-gradebook", "source_urls": ["https://raw.githubusercontent.com/francoisjacquet/rosariosis/master/LICENSE", "https://raw.githubusercontent.com/francoisjacquet/rosariosis/master/README.md"]}, {"reason": "Parent handbook 说明家长登录后可选择孩子并查看其信息、课表、作业、成绩、资格与出勤；School administrator handbook 说明学校从学生联系人信息创建 Parent accounts，必须用 Associate Parents with Students 记录监护关联，且 Parent profile 只能看到自己孩子的信息，直接对应监护人关联账户与学校控制的记录可见性。", "slug": "parent-portal", "source_urls": ["https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/README.md", "https://www.rosariosis.org/documentation/parent-handbook/", "https://www.rosariosis.org/documentation/school-administrator-handbook/"]}, {"reason": "管理员手册的 Attendance 章节证明：按课程/课时 Take Attendance，学校可配置出勤代码，Add Absences 可批量选择学生/时段并填写缺勤代码与缺勤原因，管理员可分配所有代码；Average Daily Attendance、Attendance Chart、Absence Summary、Teacher Completion 提供出勤与缺勤报告；家长手册证明家长门户可查看每日出勤和缺勤摘要。该完整考勤子模块覆盖持久记录、绑定课表/名册的捕获、缺勤原因与授权定码、对外报表及家庭可见性，故作为完整业务子模块匹配本叶。", "slug": "student-attendance-system", "source_urls": ["https://www.rosariosis.org/documentation/school-administrator-handbook/", "https://www.rosariosis.org/documentation/parent-handbook/", "https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/README.md"]}, {"reason": "Student_Billing 菜单包含费用、付款、批量收费/付款、学生余额、每日交易与对账单；StudentBalances 以费用汇总减付款汇总计算学生学年余额，覆盖学生账户、机构费用评估与收款循环。", "slug": "student-billing-system", "source_urls": ["https://api.github.com/repos/francoisjacquet/rosariosis", "https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/modules/Student_Billing/Menu.php", "https://raw.githubusercontent.com/francoisjacquet/rosariosis/mobile/modules/Student_Billing/StudentBalances.php"]}], "license": "GPL-2.0", "license_evidence_url": "https://raw.githubusercontent.com/francoisjacquet/rosariosis/master/LICENSE", "license_review": {"rationale": "完整 LICENSE 文本为 GNU General Public License Version 2，含 version 2 与 terms and conditions 条款，适用于该仓库。", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/francoisjacquet/rosariosis/master/LICENSE", "spdx_id": "GPL-2.0"}, "name": "RosarioSIS", "repository_url": "https://github.com/francoisjacquet/rosariosis", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:08:49.087655+08:00", "kind": "repository_metadata", "sha256": "980dfb6c4cbc35563cdf0c6ee59ee990b42cea43f715ee04557fe530d0e07c81", "snapshot_path": "sources/980dfb6c4cbc35563cdf0c6ee59ee990b42cea43f715ee04557fe530d0e07c81.txt", "url": "https://api.github.com/repos/francoisjacquet/rosariosis"}, {"fetched_at": "2026-10-27T00:08:53.244570+08:00", "kind": "license", "sha256": "d97f2a8a78e00b5ad3afa51e7b1d1e97fde310af2159eedcff14a11219a80006", "snapshot_path": "sources/d97f2a8a78e00b5ad3afa51e7b1d1e97fde310af2159eedcff14a11219a80006.txt", "url": "https://api.github.com/repos/francoisjacquet/rosariosis/license"}, {"fetched_at": "2026-10-29T14:23:07.466141+08:00", "kind": "repository_metadata", "sha256": "73306a11e26cf4ae2a1315e7336402ec21b