INSERT INTO "application" VALUES('commercial:blackbaud-enrollment-management','Blackbaud Enrollment Management System','{"homepage": "https://www.blackbaud.com/products/enrollment-management", "id": "commercial:blackbaud-enrollment-management", "leaf_matches": [{"reason": "官方产品页正文说明家庭可单一登录申请、跟踪状态、提交合同并次年 re-enroll；in-system contracts 支持选择付款计划、提交押金和支付学费；学校侧有可配置 checklist、自动提醒及统计已返回合同和同比趋势的 dashboard/report，覆盖承诺捕获、准备跟踪与周期人口视图。", "slug": "enrollment-management", "source_urls": ["https://www.blackbaud.com/products/enrollment-management"]}], "name": "Blackbaud Enrollment Management System", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:09:04.210500+08:00", "kind": "documentation", "sha256": "9195b1e717a3d00ad1df78611392103f654b107c6d5cc247af3211c2cfe449e3", "snapshot_path": "sources/9195b1e717a3d00ad1df78611392103f654b107c6d5cc247af3211c2cfe449e3.txt", "url": "https://www.blackbaud.com/products/enrollment-management"}], "summary": "面向 K-12 私立/独立学校的入学管理软件：家庭用单一登录申请、提交入学合同与押金、完成次年 re-enrollment；学校用 checklist、提醒和报表跟踪合同与周期进展。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:blackbaud-financial-aid-management','Blackbaud Financial Aid Management','{"homepage": "https://www.blackbaud.com/products/financial-aid", "id": "commercial:blackbaud-financial-aid-management", "leaf_matches": [{"reason": "官方产品页正文覆盖可定制申请与文件上传、由 Blackbaud financial aid experts 审核申请并核实财务信息、need/non-need 奖项、按 award source 建预算并跟踪 disbursement、可配置计算、批量 awarding、未接受奖励自动回收再分配，以及与 enrollment/tuition/billing 的奖励显示集成；对应资金/项目、申请家庭、资格/奖励决定与拨付跟踪的核心。", "slug": "financial-aid-management", "source_urls": ["https://www.blackbaud.com/products/financial-aid"]}], "name": "Blackbaud Financial Aid Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:09:06.376341+08:00", "kind": "documentation", "sha256": "209a8e188a89f20bd641bbdbd5c3b0cae883956dee93ab2a18d677dbb003c28f", "snapshot_path": "sources/209a8e188a89f20bd641bbdbd5c3b0cae883956dee93ab2a18d677dbb003c28f.txt", "url": "https://www.blackbaud.com/products/financial-aid"}], "summary": "面向私立/独立学校的助学金管理软件：家庭在线申请并上传财务文件，由 Blackbaud 助学金专家审核申请并核实财务信息，按奖项来源设置预算、计算并批量授予 need/merit/voucher/第三方奖学金，并跟踪拨付与未接受奖励回收。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
