INSERT INTO "application" VALUES('github:860334186','Module Management System (TUM CIT)','{"deployment": ["Web 应用", "自托管"], "features": ["模块提案", "结构化审查与反馈", "版本管理", "模块重叠检测", "PDF 导出"], "github_repository_id": 860334186, "homepage": "https://github.com/ls1intum/Module-Management", "id": "github:860334186", "leaf_matches": [{"reason": "TUM CIT 的 README 说明其集中管理模块提案、审查与批准，支持按字段反馈、基于反馈的版本管理、与现有课程的重叠检测和 PDF 导出；覆盖课程记录→受控变更→版本化结果的治理核心，但为模块级、机构特定。", "slug": "curriculum-management", "source_urls": ["https://api.github.com/repos/ls1intum/Module-Management", "https://raw.githubusercontent.com/ls1intum/Module-Management/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/ls1intum/Module-Management/license", "name": "Module Management System (TUM CIT)", "repository_url": "https://github.com/ls1intum/Module-Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:17:08.405108+08:00", "kind": "repository_metadata", "sha256": "a64467b4dfb3b541c22ed41bf0be72e82d2697caf838bedeefd6717f0e8b2e95", "snapshot_path": "sources/a64467b4dfb3b541c22ed41bf0be72e82d2697caf838bedeefd6717f0e8b2e95.txt", "url": "https://api.github.com/repos/ls1intum/Module-Management"}, {"fetched_at": "2026-10-27T00:17:11.639891+08:00", "kind": "license", "sha256": "ba5d055ca4d40f37a90ebf1376ee04e0847dd69d6a3871f5e44364c66a3442ff", "snapshot_path": "sources/ba5d055ca4d40f37a90ebf1376ee04e0847dd69d6a3871f5e44364c66a3442ff.txt", "url": "https://api.github.com/repos/ls1intum/Module-Management/license"}, {"fetched_at": "2026-10-27T00:17:08.189422+08:00", "kind": "readme", "sha256": "b12d66aa06eff0a6107f62b7473d3bf23b63ce5d4656b4044dee4807fd5831c4", "snapshot_path": "sources/b12d66aa06eff0a6107f62b7473d3bf23b63ce5d4656b4044dee4807fd5831c4.txt", "url": "https://raw.githubusercontent.com/ls1intum/Module-Management/main/README.md"}], "summary": "TUM CIT 的模块/课程提案、审查与批准系统，含版本历史、结构化反馈与模块重叠检测。", "technology_stack": ["TypeScript", "Angular", "Java", "Spring Boot"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:161860953','Resgrid Core','{"deployment": ["自托管：Docker、Kubernetes/k3s、Windows 桌面", "托管 SaaS 版与开源自托管版使用同一代码库"], "features": ["计算机辅助调度：创建事件/呼叫并人工或自动派遣人员、单位、角色或小组", "人员、单位、小组与驻地的状态、可用性和问责记录", "AVL 地图与 BigBoard 实时状态板（人员/单位状态、呼叫、地图）", "值班、消息/聊天、通知、部门链接与互援协作", "运行记录、报告、检查清单、库存、文档存储与记录管理（RMS）"], "github_repository_id": 161860953, "homepage": "https://resgrid.com/", "id": "github:161860953", "leaf_matches": [{"reason": "README 明确提供 CAD 事件/呼叫创建、人工与自动派单、单位状态与 AVL、运行记录，并在文档中列出 Dispatch & Calls、Units、Mapping 与 Big Board 实时状态板，覆盖事件→分配→响应单元→实时画面核心结构。", "slug": "computer-aided-dispatch-cad", "source_urls": ["https://raw.githubusercontent.com/Resgrid/Core/master/README.md", "https://docs.resgrid.com/"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/Resgrid/Core/master/LICENSE", "license_review": {"rationale": "完整 Apache License 2.0 原文由本仓库 master 分支 LICENSE 直接取得，含明确的许可证标题、版本 2.0 与责任限制条款，仓库范围适用。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/Resgrid/Core/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Resgrid Core", "repository_url": "https://github.com/Resgrid/Core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:20:04.817199+08:00", "kind": "repository_metadata", "sha256": "50459e5d606fbb74400ed5eee0a2b2ba8d42d7473a49af6ce39f872ae1dd027d", "snapshot_path": "sources/50459e5d606fbb74400ed5eee0a2b2ba8d42d7473a49af6ce39f872ae1dd027d.txt", "url": "https://github.com/Resgrid/Core"}, {"fetched_at": "2026-10-27T00:20:47.822160+08:00", "kind": "license", "sha256": "ce3eb20818c05de0e30d6126affcf61f8494ed985242fbdb36bbd3feaf07fb0f", "snapshot_path": "sources/ce3eb20818c05de0e30d6126affcf61f8494ed985242fbdb36bbd3feaf07fb0f.txt", "url": "https://raw.githubusercontent.com/Resgrid/Core/master/LICENSE"}, {"fetched_at": "2026-10-27T00:20:49.268545+08:00", "kind": "readme", "sha256": "5b858725e33d1ccea124aae4f8f33d19c054c6f