INSERT INTO "application" VALUES('commercial:tyler-enterprise-corrections','Tyler Enterprise Corrections','{"homepage": "https://www.tylertech.com/products/enterprise-corrections", "id": "commercial:tyler-enterprise-corrections", "leaf_matches": [{"reason": "官方 Local Jail Administration 页面描述收押预登记、在押人员住房分配（按风险、床位、位置与日程）、牢房检查/安全巡查、移动记录行动与释放流程，匹配在押人员记录、羁押期、监室安置及行动问责核心。", "slug": "corrections-management-system", "source_urls": ["https://www.tylertech.com/products/enterprise-corrections", "https://www.tylertech.com/solutions/courts-public-safety/corrections/administration/local-jail-administration"]}], "name": "Tyler Enterprise Corrections", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:21:29.278664+08:00", "kind": "homepage", "sha256": "d5a6dc2c62220d41213a46a811e2f0c949d029b86d89c7ae9e1a5d915ad4108c", "snapshot_path": "sources/d5a6dc2c62220d41213a46a811e2f0c949d029b86d89c7ae9e1a5d915ad4108c.txt", "url": "https://www.tylertech.com/products/enterprise-corrections"}, {"fetched_at": "2026-10-27T00:22:35.133236+08:00", "kind": "documentation", "sha256": "5eabeadc4321aece20836535d3427ab3b21a8efd48bf93dddf50d39dbb023dd2", "snapshot_path": "sources/5eabeadc4321aece20836535d3427ab3b21a8efd48bf93dddf50d39dbb023dd2.txt", "url": "https://www.tylertech.com/solutions/courts-public-safety/corrections/administration/local-jail-administration"}], "summary": "面向县看守所与州矫正部门的矫正管理套件；官方资料覆盖从收押/登记、分类与监室分配、移动点名与行动记录到释放的流程，并整合财务、通信与重返社会模块。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:veoci','Veoci','{"homepage": "https://veoci.com/", "id": "commercial:veoci", "leaf_matches": [{"reason": "官方应急管理页面明确提供一键激活事件、计划/检查清单、任务与资源跟踪、实时态势看板/GIS 地图、通信中心和自动时间戳/事后报告，覆盖事件容器、共享态势、协调工作与行动记录。", "slug": "emergency-management-platform", "source_urls": ["https://veoci.com/", "https://veoci.com/emergency-management"]}], "name": "Veoci", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:23:17.633927+08:00", "kind": "homepage", "sha256": "6bfa2de09e75b10813c6619ab83e5423b71d45d76bc32efa601e976ccf576abe", "snapshot_path": "sources/6bfa2de09e75b10813c6619ab83e5423b71d45d76bc32efa601e976ccf576abe.txt", "url": "https://veoci.com/"}, {"fetched_at": "2026-10-27T00:23:15.204407+08:00", "kind": "documentation", "sha256": "0c20d4ba109be940cdbec06adec77fa11043017f448a472e4b19d5251b71db51", "snapshot_path": "sources/0c20d4ba109be940cdbec06adec77fa11043017f448a472e4b19d5251b71db51.txt", "url": "https://veoci.com/emergency-management"}], "summary": "面向政府与应急管理机构的虚拟应急运营中心（EOC）平台；支持一键激活事件、共享态势看板与 GIS 地图、任务/资源分配、通知，以及带时间戳的行动记录和事后报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:eso','ESO EMS Platform','{"homepage": "https://www.eso.com/ems/", "id": "commercial:eso", "leaf_matches": [{"reason": "官方 EMS 页面列出 crews、calls、patient care、scheduling/personnel、dispatch、billing 与 performance；EHR 页面明确为 ePCR 工作流并带 CAD/监护仪集成，覆盖响应事件、人员车辆单元与患者护理报告核心。", "slug": "ems-operations-platform", "source_urls": ["https://www.eso.com/ems/", "https://www.eso.com/ems/ehr/"]}], "name": "ESO EMS Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:21:31.140323+08:00", "kind": "homepage", "sha256": "bdce8c49b00a889d750ef18aec1855559ee13883f1b5a72f999d5c5b8d02e8ee", "snapshot_path": "sources/bdce8c49b00a889d750ef18aec1855559ee13883f1b5a72f999d5c5b8d02e8ee.txt", "url": "https://www.eso.com/ems/"}, {"fetched_at": "2026-10-27T00:23:58.726559+08:00", "kind": "documentation", "sha256": "17b73034402b372df3f50153ced4b63a6ca7afcd409245befea560cccb5f07b3", "snapshot_path": "sources/17b73034402b372df3f50153ced4b63a6ca7afcd409245befea560cccb5f07b3.txt", "url": "https://www.eso.com/ems/ehr/"}], "summary": "面向 EMS 机构的云端运营平台，覆盖人员排班、调度、患者护理记录（ePCR）、计费与绩效分析，并支持与 CAD、监护仪及医院数据交换。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:axon-evidence','Axon Evidence','{"homepage": "https://www.axon.com/en-ca/products/axon-evidence", "id": "commercial:axon-evidence", "leaf_matches": [{"reason": "官方页面明确说明每个上传文件分配数字指纹、所有查看/编辑/下载操作自动记录审计轨迹以保护监管链，并支持集中存储、检索、保留和向检察官披露，匹配证据记录与持续保管链核心。", "slug": "evidence-management-system", "source_urls": ["https://www.axon.com/en-ca/products/axon-evidence"]}], "name": "Axon Evidence", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:22:07.569939+08:00", "kind": "homepage", "sha256": "1063dce6d60dda6dea83855981e16b6f40e941ff59f178b3c8db5458a1c2cc59", "snapshot_path": "sources/1063dce6d60dda6dea83855981e16b6f40e941ff59f178b3c8db5458a1c2cc59.txt", "url": "https://www.axon.com/en-ca/products/axon-evidence"}], "summary": "面向执法机构的数字证据管理平台；集中存储与共享证据，对上传、查看、编辑和下载等操作保留审计轨迹和监管链。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:granicus-govservice','Granicus govService','{"homepage": "https://granicus.com/product/service-request-management-govservice/", "id": "commercial:granicus-govservice", "leaf_matches": [{"reason": "厂商官方产品页自述：govService 以在线表单、工作流和案件管理组成数字服务，客户门户可为居民提供 all online services 并做成 one-stop shop，居民可提交在线请求并保持知情，后台以单一记录系统跟踪请求。类型匹配依据服务聚合入口与居民发起请求；具体跨机构服务目录、支付与身份验证未在快照中展示，all online services/one-stop shop 属厂商概括性表述，未作独立验证。", "slug": "government-service-portal", "source_urls": ["https://granicus.com/product/service-request-management-govservice/"]}], "name": "Granicus govService", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:36:57.713047+08:00", "kind": "documentation", "sha256": "eb59bb86892c6e3b75bf07672f29b188329ff8d4101ce9e70b2b667b4ecb79ac", "snapshot_path": "sources/eb59bb86892c6e3b75bf07672f29b188329ff8d4101ce9e70b2b667b4ecb79ac.txt", "url": "https://granicus.com/product/service-request-management-govservice/"}], "summary": "面向地方政府的商业数字服务请求与客户门户：以可配置在线表单、工作流和案件管理，把居民在线请求集中到客户门户，并以单一记录系统跟踪处理状态。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tyler-enterprise-records-management','Tyler Enterprise Records Management','{"homepage": "https://www.tylertech.com/products/enterprise-records-management", "id": "commercial:tyler-enterprise-records-management", "leaf_matches": [{"reason": "官方页面说明该软件供县记录办公室记录和归档土地与官方文书，支持索引、影像、电子提交的接受或拒绝，以及公众检索和购买副本；对应文书与官方记录生命周期。两份快照均未出现 parcel、plat 或 legal description，宗地/地块绑定未直接取证，故仅按土地文书记录匹配，未断言宗地模块。", "slug": "land-records-cadastre-system", "source_urls": ["https://www.tylertech.com/products/enterprise-records-management", "https://www.tylertech.com/products/enterprise-records-management/enterprise-records-management-for-the-recorder"]}], "name": "Tyler Enterprise Records Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:37:03.890259+08:00", "kind": "documentation", "sha256": "8cb40edfe84557240e5ea26b853656653adb29bf565690c515177a69d8e3b463", "snapshot_path": "sources/8cb40edfe84557240e5ea26b853656653adb29bf565690c515177a69d8e3b463.txt", "url": "https://www.tylertech.com/products/enterprise-records-management"}, {"fetched_at": "2026-10-27T00:37:07.052832+08:00", "kind": "documentation", "sha256": "20748b328dc1cb845e9685f973307170e9c9dab8aa2e984954ecf72778a9fdac", "snapshot_path": "sources/20748b328dc1cb845e9685f973307170e9c9dab8aa2e984954ecf72778a9fdac.txt", "url": "https://www.tylertech.com/products/enterprise-records-management/enterprise-records-management-for-the-recorder"}], "summary": "面向县记录办公室的商业土地与官方记录系统：接收、审核、索引、影像化并公开检索契约、抵押、留置权等文书。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tyler-enterprise-permitting-licensing','Tyler Enterprise Permitting & Licensing','{"homepage": "https://www.tylertech.com/products/enterprise-permitting-licensing", "id": "commercial:tyler-enterprise-permitting-licensing", "leaf_matches": [{"reason": "官方页面说明系统覆盖规划、许可、检查和合规，支持在线申请与提交、并发审查、状态跟踪、许可签发及 24/7 门户；对应外部申请、机构审查决策与签发许可核心。本条仅按许可审批收窄：licensing/持证人执照、检查结果（inspection）与违规执法（code enforcement）属相邻类型，未纳入本条。", "slug": "permit-management", "source_urls": ["https://www.tylertech.com/products/enterprise-permitting-licensing"]}], "name": "Tyler Enterprise Permitting & Licensing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:37:10.649829+08:00", "kind": "documentation", "sha256": "90d5754492a1207f2c821c908c1682d71401c1b020f8d63dbf4d6ef29fad2f93", "snapshot_path": "sources/90d5754492a1207f2c821c908c1682d71401c1b020f8d63dbf4d6ef29fad2f93.txt", "url": "https://www.tylertech.com/products/enterprise-permitting-licensing"}], "summary": "面向地方政府的商业许可审批系统：受理外部申请、跨部门并发审查、电子图纸审查并签发许可；检查与合规属相邻能力，本条按许可审批收窄。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:accela-planning-zoning','Accela Planning & Zoning','{"homepage": "https://www.accela.com", "id": "commercial:accela-planning-zoning", "leaf_matches": [{"reason": "官方规划与分区产品页正文明确覆盖申请受理、审查与批准、公告/听证排期，以及听证结果和批准条件的记录。", "slug": "planning-zoning-management", "source_urls": ["https://www.accela.com/solutions/planning/"]}], "name": "Accela Planning & Zoning", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:42:13.117452+08:00", "kind": "homepage", "sha256": "a70f9fa45e327b1f188ca0bdb787cd03c61a1e1b3ee3d955c9690efeed2567bb", "snapshot_path": "sources/a70f9fa45e327b1f188ca0bdb787cd03c61a1e1b3ee3d955c9690efeed2567bb.txt", "url": "https://www.accela.com/solutions/planning/"}], "summary": "面向地方政府的规划与分区生命周期平台，覆盖申请受理、跨部门同步审查与批准、公告/听证排期，并在同一记录中保存听证结果与批准条件；属于规划与分区管理的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:catalis-cama','Catalis CAMA','{"homepage": "https://catalisgov.com", "id": "commercial:catalis-cama", "leaf_matches": [{"reason": "官方 CAMA 产品页正文明确覆盖财产数据管理、估值/批量评估、评估行政与税册处理，符合以评估册为交付物的评估系统核心。", "slug": "property-assessment-system", "source_urls": ["https://catalisgov.com/tax-cama/computer-assisted-mass-appraisal-cama"]}], "name": "Catalis CAMA", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:43:19.812012+08:00", "kind": "homepage", "sha256": "f7382c939f22336620fde9931f29908d7bf3151c555aa0590dae56b00d6114a1", "snapshot_path": "sources/f7382c939f22336620fde9931f29908d7bf3151c555aa0590dae56b00d6114a1.txt", "url": "https://catalisgov.com/tax-cama/computer-assisted-mass-appraisal-cama"}], "summary": "面向地方评估机构的计算机辅助批量评估（CAMA）平台，统一房地产与个人财产数据、估值与批量评估、评估行政及税册处理；属于房地产评估系统的商业产品。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:opengov-property-tax','OpenGov Property Tax','{"homepage": "https://opengov.com", "id": "commercial:opengov-property-tax", "leaf_matches": [{"reason": "官方产品页正文明确覆盖评估导入、按税率/征收生成账单、支付征收、逾期管理和总账分配，构成房产税征收与结算核心。", "slug": "property-tax-administration", "source_urls": ["https://opengov.com/products/tax-and-revenue/property-tax"]}], "name": "OpenGov Property Tax", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:42:21.166829+08:00", "kind": "homepage", "sha256": "71b84936e9c5471bd44820aaf58f1ac8c14cf3822d736436407836c85da85c7a", "snapshot_path": "sources/71b84936e9c5471bd44820aaf58f1ac8c14cf3822d736436407836c85da85c7a.txt", "url": "https://opengov.com/products/tax-and-revenue/property-tax"}], "summary": "面向地方政府的房产税账单与征收平台，从评估数据导入、批量账单生成到支付征收、逾期管理与总账分配；属于房产税管理的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:opengov-enterprise-asset-management','OpenGov Enterprise Asset Management','{"homepage": "https://opengov.com", "id": "commercial:opengov-enterprise-asset-management", "leaf_matches": [{"reason": "官方产品页正文明确面向州/地方政府与公共工程，记录资产状况、成本与工单历史，并以资本改善规划支持维修/更换决策，符合公共受托资产登记与生命周期管理。", "slug": "public-asset-management", "source_urls": ["https://opengov.com/products/enterprise-asset-management"]}], "name": "OpenGov Enterprise Asset Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:42:29.110545+08:00", "kind": "homepage", "sha256": "fafb279e9f7a6b69447b2c90b2011fd2372d1ceae454247607ba244e9c282e18", "snapshot_path": "sources/fafb279e9f7a6b69447b2c90b2011fd2372d1ceae454247607ba244e9c282e18.txt", "url": "https://opengov.com/products/enterprise-asset-management"}], "summary": "面向州/地方政府公共工程与公用事业的基础设施资产管理平台，覆盖资产位置、状况、成本与工单历史、GIS、预防性维护及资本改善规划；属于公共资产管理的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1095025428','ShiftLog','{"deployment": ["自托管 Node.js 应用，npm start 生产启动", "配置文件位于 data/config.js", "提供 Windows 服务安装/卸载脚本", "使用 Microsoft SQL Server 多连接池"], "features": ["工单记录、更新与消息", "班次活动日志", "工时表跟踪", "基于 Leaflet/OpenStreetMap 的工单地图", "邮件、Microsoft Teams、ntfy 通知", "与 Avanti、CentralSquare Pearl、ArcGIS 的数据同步集成"], "github_repository_id": 1095025428, "homepage": "https://github.com/cityssm/shiftlog", "id": "github:1095025428", "leaf_matches": [{"reason": "README 明确面向 Community Services and Public Works 的工单管理，并提供工单、班次活动、工时表与地图/通知能力；覆盖工作执行侧，市民请求入口与成本核算未证明。", "slug": "public-works-management", "source_urls": ["https://github.com/cityssm/shiftlog", "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/LICENSE.md", "license_review": {"rationale": "逐字核对仓库 LICENSE.md 的完整 MIT 文本，确认授予复制、修改、分发与再许可权利，并按现状提供。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/LICENSE.md", "spdx_id": "MIT"}, "name": "ShiftLog", "repository_url": "https://github.com/cityssm/shiftlog", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:42:13.693481+08:00", "kind": "repository_metadata", "sha256": "5ce2a10d49f777f584b4e18b8c77d0ad2eee2f60ca40c5635e30b148aec0cb12", "snapshot_path": "sources/5ce2a10d49f777f584b4e18b8c77d0ad2eee2f60ca40c5635e30b148aec0cb12.txt", "url": "https://github.com/cityssm/shiftlog"}, {"fetched_at": "2026-10-27T00:42:14.978428+08:00", "kind": "readme", "sha256": "bc8ce63273e918d8e6b6267e1ec6ecb3cfe22e96f29760edaaf24d59fd3a08b1", "snapshot_path": "sources/bc8ce63273e918d8e6b6267e1ec6ecb3cfe22e96f29760edaaf24d59fd3a08b1.txt", "url": "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/README.md"}, {"fetched_at": "2026-10-27T00:42:16.264068+08:00", "kind": "license", "sha256": "db5b54219eed21dbb8a787bbe57946ad945f6593541ff40fa72c90bc6c41cc1c", "snapshot_path": "sources/db5b54219eed21dbb8a787bbe57946ad945f6593541ff40fa72c90bc6c41cc1c.txt", "url": "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/LICENSE.md"}, {"fetched_at": "2026-10-27T00:42:53.469378+08:00", "kind": "documentation", "sha256": "a0fdd57b7e989e80eb6b1e2acf6bc29a22c5c23120a0266a4c923a23f7da5e29", "snapshot_path": "sources/a0fdd57b7e989e80eb6b1e2acf6bc29a22c5c23120a0266a4c923a23f7da5e29.txt", "url": "https://raw.githubusercontent.com/cityssm/shiftlog/HEAD/package.json"}], "summary": "面向社区服务与公共工程部门的开源工作管理系统，提供工单记录/更新、班次活动日志、工时表、地图与通知集成；覆盖公共工程工作执行记录，但未证明市民请求受理与成本核算。", "technology_stack": ["Node.js", "Express", "EJS", "Microsoft SQL Server", "Leaflet"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1308925398','OpenRevenue','{"deployment": ["Go API/worker/scheduler 与 PostgreSQL/Redis/MinIO Docker Compose", "React/TypeScript/Vite 门户"], "features": ["纳税人注册与审批", "申报、计算与评估", "支付记录与账本分录", "审计事件记录"], "github_repository_id": 1308925398, "homepage": "https://github.com/opencorex-org/openrevenue", "id": "github:1308925398", "leaf_matches": [{"reason": "README 与仓库元数据说明平台面向政府税务管理，支持纳税人注册、申报/评估、支付与账本等核心流程。", "slug": "tax-administration-system", "source_urls": ["https://raw.githubusercontent.com/opencorex-org/openrevenue/main/README.md", "https://api.github.com/repos/opencorex-org/openrevenue"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/opencorex-org/openrevenue/license", "name": "OpenRevenue", "repository_url": "https://github.com/opencorex-org/openrevenue", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:14:36.276073+08:00", "kind": "repository_metadata", "sha256": "dd640ff57a066d7eed843937a99620b251254b953ce73d451515c429cd4e500f", "snapshot_path": "sources/dd640ff57a066d7eed843937a99620b251254b953ce73d451515c429cd4e500f.txt", "url": "https://api.github.com/repos/opencorex-org/openrevenue"}, {"fetched_at": "2026-10-25T08:14:37.770844+08:00", "kind": "license", "sha256": "376294f76905c499fe7d984b05d8d3526190bdf898d178b6fe6b5cfd89214d29", "snapshot_path": "sources/376294f76905c499fe7d984b05d8d3526190bdf898d178b6fe6b5cfd89214d29.txt", "url": "https://api.github.com/repos/opencorex-org/openrevenue/license"}, {"fetched_at": "2026-10-25T08:15:55.962596+08:00", "kind": "readme", "sha256": "fadd7db9b0debc4a078b8e39d536bccabf92345c90f88f4c56294c2670b48f75", "snapshot_path": "sources/fadd7db9b0debc4a078b8e39d536bccabf92345c90f88f4c56294c2670b48f75.txt", "url": "https://raw.githubusercontent.com/opencorex-org/openrevenue/main/README.md"}], "summary": "开源可配置的政府税务与收入管理平台基础，支持纳税人注册、申报/评估、支付、账本与审计等核心流程（早期版本）；按税种分账、欠款持续、退款及法定通知/执法未在此版本证明。", "technology_stack": ["Go", "React", "TypeScript", "PostgreSQL", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:72849464','Primero','{"deployment": ["Ansible 生产部署", "Docker Compose 开发/评估部署", "PostgreSQL 14/15（README：14 为默认，15 自 v2.10 起支持）"], "features": ["儿童保护个案记录", "事件（incident）记录及与个案的关联", "寻亲请求、追踪与潜在匹配", "转介、分配与记录转移", "附件与记录标记", "儿童与家庭/照顾者关联记录（Child、Family 模型）", "保护关注、风险等级及评估/个案计划到期记录（Child 模型）", "评估、个案计划与结案的监督审批（Approval）", "照护安排（安置类型/照顾者/起始日期）与重新团聚记录"], "github_repository_id": 72849464, "homepage": "https://www.primero.org", "id": "github:72849464", "leaf_matches": [{"reason": "GitHub 仓库 description 与 LICENSE 前言说明 Primero 面向儿童保护与社会工作者管理弱势儿童及暴力幸存者数据；API 文档列出个案、事件、寻亲请求、转介及记录分配/转移；公开模型代码显示儿童-家庭关联、保护关注与风险等级、评估/个案计划审批、照护安排与重新团聚字段。CPIMS+/GBVIMS+ 配置包不在开源核心，正式筛查决定与收养等永久性流程未获公开证据，故匹配范围限于上述公开核心个案工作流。", "slug": "child-welfare-management", "source_urls": ["https://api.github.com/repos/primeroIMS/primero", "https://api.github.com/repos/primeroIMS/primero/license", "https://raw.githubusercontent.com/primeroIMS/primero/main/doc/api.md", "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/child.rb", "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/family.rb", "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/approval.rb", "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/reportable_protection_concern.rb", "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/concerns/care_arrangements.rb"]}, {"reason": "官方用户指南说明个案从登记、评估、个案计划、转介/移交到结案审批的流程，并含任务截止、审计日志和角色权限；README 说明其用于儿童保护与社会工作。", "slug": "social-services-case-management", "source_urls": ["https://raw.githubusercontent.com/primeroIMS/PrimeroCPIMSUserGuide/master/UsersGuide.md", "https://raw.githubusercontent.com/primeroIMS/primero/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/primeroIMS/primero/license", "license_review": {"rationale": "LICENSE 全文为 GNU AGPL v3，前言写明可按 version 3 或任何更晚版本使用；GitHub license API 将其分类为 AGPL-3.0，本条目沿用该 SPDX 分类。LICENSE 前言与仓库 description 均说明 CPIMS+/GBVIMS+ 配置 JSON 包需另行联系获取，因此仅对开源代码核心记录，不把受限配置包计入开源范围。", "reviewer": "opencode-go/deepseek-v4.1-flash (初审后修正)", "scope": "community_core", "source_url": "https://api.github.com/repos/primeroIMS/primero/license", "spdx_id": "AGPL-3.0"}, "name": "Primero", "repository_url": "https://github.com/primeroIMS/primero", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:47:05.529453+08:00", "kind": "repository_metadata", "sha256": "fd390498e726bf829cf36ae8b0d53d2d1d327fe98b18149fdecf15646b2a9262", "snapshot_path": "sources/fd390498e726bf829cf36ae8b0d53d2d1d327fe98b18149fdecf15646b2a9262.txt", "url": "https://api.github.com/repos/primeroIMS/primero"}, {"fetched_at": "2026-10-27T00:47:10.258034+08:00", "kind": "readme", "sha256": "edb05521f8cf335d637b6257fdf09d455b93c2580212787d765b1c21f5eb2bb7", "snapshot_path": "sources/edb05521f8cf335d637b6257fdf09d455b93c2580212787d765b1c21f5eb2bb7.txt", "url": "https://raw.githubusercontent.com/primeroIMS/primero/main/README.md"}, {"fetched_at": "2026-10-27T00:47:12.251921+08:00", "kind": "license", "sha256": "42f8ece27e80d6a7152ab0c0bbf81047c4c36c134f14e201df7cfd97dfed87a3", "snapshot_path": "sources/42f8ece27e80d6a7152ab0c0bbf81047c4c36c134f14e201df7cfd97dfed87a3.txt", "url": "https://api.github.com/repos/primeroIMS/primero/license"}, {"fetched_at": "2026-10-27T00:47:41.321992+08:00", "kind": "documentation", "sha256": "1b5a34a5205ed1f451520577342ef8444849cc3fe20663f1fd959d34a0569121", "snapshot_path": "sources/1b5a34a5205ed1f451520577342ef8444849cc3fe20663f1fd959d34a0569121.txt", "url": "https://raw.githubusercontent.com/primeroIMS/primero/main/doc/api.md"}, {"fetched_at": "2026-10-27T01:01:02.501266+08:00", "kind": "documentation", "sha256": "56301cff9044d52c34247a70a7f77ca5528bfa5bcd4b3b597b6ea355e81655aa", "snapshot_path": "sources/56301cff9044d52c34247a70a7f77ca5528bfa5bcd4b3b597b6ea355e81655aa.txt", "url": "https://raw.githubusercontent.com/primeroIMS/primero/main/app/models/child.rb"}, {"fetched_at