INSERT INTO "application" VALUES('commercial:granicus-agenda-meeting-management','Granicus Agenda & Meeting Management','{"homepage": "https://granicus.com/", "id": "commercial:granicus-agenda-meeting-management", "leaf_matches": [{"reason": "产品页正文说明面向书记官自动化议程创建、审批和会议纪要管理，并提供公开议程/视频门户与委员会管理，匹配公共会议议程与记录核心。", "slug": "government-meeting-agenda-management", "source_urls": ["https://granicus.com/solution/agenda-meeting-management/"]}], "name": "Granicus Agenda & Meeting Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T00:52:34.834736+08:00", "kind": "homepage", "sha256": "dd5b097da7ac5313197d82f6e73ab9c44444652874d2de48ae0e13f2a12e86a1", "snapshot_path": "sources/dd5b097da7ac5313197d82f6e73ab9c44444652874d2de48ae0e13f2a12e86a1.txt", "url": "https://granicus.com/solution/agenda-meeting-management/"}], "summary": "面向地方政府书记官的商业议程与会议管理方案，覆盖议程创建与审批、会议材料、纪要管理、公开议程/视频门户及委员会管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
