INSERT INTO "application" VALUES('commercial:sponsorcx','SponsorCX','{"homepage": "https://www.sponsorcx.com/", "id": "commercial:sponsorcx", "leaf_matches": [{"reason": "官方产品页说明赞助库存可实时区分可售、已售和提案中，合同与权益直接关联库存，成交后自动生成任务与时间线，资产按活动排期并跟踪交付/未交付状态；报告基于销售、库存与履约数据生成交付证明和续约依据。", "slug": "sponsor-management", "source_urls": ["https://www.sponsorcx.com/", "https://www.sponsorcx.com/property-product/"]}], "name": "SponsorCX", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:27:37.613026+08:00", "kind": "homepage", "sha256": "7c2ef2ec77e0ffaaf56a59236e17e28b9d9dcdcad4049f5d8c00b3990d7928f0", "snapshot_path": "sources/7c2ef2ec77e0ffaaf56a59236e17e28b9d9dcdcad4049f5d8c00b3990d7928f0.txt", "url": "https://www.sponsorcx.com/"}, {"fetched_at": "2026-10-27T01:28:13.634877+08:00", "kind": "documentation", "sha256": "ebda31a6f518cff3ab22e6636cd340611ae1512b570cfb5a2789f28cd45ee991", "snapshot_path": "sources/ebda31a6f518cff3ab22e6636cd340611ae1512b570cfb5a2789f28cd45ee991.txt", "url": "https://www.sponsorcx.com/property-product/"}], "summary": "面向活动、体育和场馆主办方的赞助管理平台，集中赞助库存、合同与权益，自动生成履约任务并按活动跟踪交付状态，赛后汇总交付与绩效报告用于续约。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
