INSERT INTO "application" VALUES('commercial:centeredge','CenterEdge Software','{"homepage": "https://centeredgesoftware.com/", "id": "commercial:centeredge", "leaf_matches": [{"reason": "官方 FEC 页面说明一体化 POS/票务、景点门票与游戏卡、派对和场地预订、餐饮零售、奖品兑换与储值卡，覆盖全场收入中心。", "slug": "family-entertainment-center-management", "source_urls": ["https://centeredgesoftware.com/industries/family-entertainment-centers/"]}], "name": "CenterEdge Software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:15:23.804680+08:00", "kind": "homepage", "sha256": "30eee6ca2914c6057ce6b080d7b24eec8e67b051f3d1c73051ef409581272a34", "snapshot_path": "sources/30eee6ca2914c6057ce6b080d7b24eec8e67b051f3d1c73051ef409581272a34.txt", "url": "https://centeredgesoftware.com/industries/family-entertainment-centers/"}], "summary": "面向家庭娱乐中心的一体化运营系统：统一 POS 覆盖景点票务、游戏卡/储值、派对与场地预订、餐饮零售和奖品兑换，并提供报表、会员与免责声明流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pladia','Pladia','{"homepage": "https://pladia.io/", "id": "commercial:pladia", "leaf_matches": [{"reason": "帮助中心《Create and Manage Tours》逐步文档明确：机构创建 Tour、在编辑器中加入文本/图像/按钮/视频；Tour Stop 可引用已有 Objects 或 Spaces 并继承其内容，也可新建；可设置 location pin 自动生成地图；发布后在 Console 执行 Publish 与 Release to Public；访客从站点点击进入关联 Object/Space。产品页另说明发布到 PWA 即时上线、访客无需下载或登录逐站浏览；Image Recognition 页说明对准展品打开对象专属页面；文化机构页正文列数字标签、现场屏幕与 welcome kiosk。机构编写导览、站点与展品/空间绑定、发布与访客端逐站访问三层均有正文证据。", "slug": "museum-visitor-experience-platform", "source_urls": ["https://support.pladia.io/en/articles/12566960-create-and-manage-tours", "https://www.pladia.io/features/tours", "https://www.pladia.io/features/image-recognition", "https://www.pladia.io/industries/cultural-institutions"]}], "name": "Pladia", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:20:36.107211+08:00", "kind": "homepage", "sha256": "6796abe54cdaad773eb0d79a0a3b566e432d92dc2faaab92fc10a21c1394009b", "snapshot_path": "sources/6796abe54cdaad773eb0d79a0a3b566e432d92dc2faaab92fc10a21c1394009b.txt", "url": "https://www.pladia.io/"}, {"fetched_at": "2026-10-27T01:20:36.140329+08:00", "kind": "documentation", "sha256": "1db483166cb59b567cd93802c33ac9500f0018d0f57cef1b84674b119e6bb3af", "snapshot_path": "sources/1db483166cb59b567cd93802c33ac9500f0018d0f57cef1b84674b119e6bb3af.txt", "url": "https://www.pladia.io/industries/cultural-institutions"}, {"fetched_at": "2026-10-27T01:20:35.989458+08:00", "kind": "documentation", "sha256": "9b7c5ca9938edf2dc503888dae504b2eeec46365a1a06e0c759c427c4ebfc5a7", "snapshot_path": "sources/9b7c5ca9938edf2dc503888dae504b2eeec46365a1a06e0c759c427c4ebfc5a7.txt", "url": "https://www.pladia.io/products/empower"}, {"fetched_at": "2026-10-27T01:29:00.115558+08:00", "kind": "documentation", "sha256": "96d3c8dc829a648ec6fd450ad75f6bbbccbb09634a62f413a5f464c083ba0f88", "snapshot_path": "sources/96d3c8dc829a648ec6fd450ad75f6bbbccbb09634a62f413a5f464c083ba0f88.txt", "url": "https://www.pladia.io/features/tours"}, {"fetched_at": "2026-10-27T01:29:00.261123+08:00", "kind": "documentation", "sha256": "044e547d6573532269a9fae671a8ea1b3cb336772b6bbb1ce0c1f82a3657ca9a", "snapshot_path": "sources/044e547d6573532269a9fae671a8ea1b3cb336772b6bbb1ce0c1f82a3657ca9a.txt", "url": "https://www.pladia.io/features/image-recognition"}, {"fetched_at": "2026-10-27T01:32:24.696360+08:00", "kind": "documentation", "sha256": "96eae6a43506e29861464e93773907871a65ed26f95937aea52172113e00c7da", "snapshot_path": "sources/96eae6a43506e29861464e93773907871a65ed26f95937aea52172113e00c7da.txt", "url": "https://support.pladia.io/en/articles/12566960-create-and-manage-tours"}], "summary": "面向博物馆与画廊的游客体验平台：机构在后台创建带丰富内容的导览站点、用位置点绑定空间并发布到访客浏览器（PWA），也通过数字标签、现场屏幕和自助终端发布；访客可对准展品识别或逐站浏览，平台提供语音导览与访客分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:accesso','accesso','{"homepage": "https://accesso.com/", "id": "commercial:accesso", "leaf_matches": [{"reason": "官方主题公园与票务页面说明入园票务、线上线下/移动销售、园内餐饮零售与虚拟排队；Horizon 页面进一步说明 web/kiosk/移动/呼叫中心统一销售，并按游客档案管理 pass、add-on 与权益。", "slug": "theme-park-management", "source_urls": ["https://accesso.com/markets/theme-parks-water-parks", "https://accesso.com/solutions/ticketing", "https://accesso.com/capabilities/products/horizon/"]}], "name": "accesso", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:15:33.224916+08:00", "kind": "homepage", "sha256": "351cbedac7bf916dc3711479cb1f527352da7c061362f2999fb270b0a4aaf008", "snapshot_path": "sources/351cbedac7bf916dc3711479cb1f527352da7c061362f2999fb270b0a4aaf008.txt", "url": "https://accesso.com/markets/theme-parks-water-parks"}, {"fetched_at": "2026-10-27T01:15:32.600492+08:00", "kind": "documentation", "sha256": "2b2d216e606e0291d23d9ef89a2d1255e82c3a77659e6cf696d341c221374595", "snapshot_path": "sources/2b2d216e606e0291d23d9ef89a2d1255e82c3a77659e6cf696d341c221374595.txt", "url": "https://accesso.com/solutions/ticketing"}, {"fetched_at": "2026-10-27T01:15:45.198127+08:00", "kind": "documentation", "sha256": "de8c87e05203aa44fe38a56954db663af3b7ac2f789b55e0b5d71d24468d6472", "snapshot_path": "sources/de8c87e05203aa44fe38a56954db663af3b7ac2f789b55e0b5d71d24468d6472.txt", "url": "https://accesso.com/solutions/point-of-sale/"}, {"fetched_at": "2026-10-27T01:22:05.545379+08:00", "kind": "documentation", "sha256": "9bcb606db3bb2e35118ca3cb49eca3dca30b5b648c7014bcc5b2dfa9f62150f8", "snapshot_path": "sources/9bcb606db3bb2e35118ca3cb49eca3dca30b5b648c7014bcc5b2dfa9f62150f8.txt", "url": "https://accesso.com/capabilities/products/horizon/"}], "summary": "面向主题公园与水上乐园的票务和游客管理平台：线上线下及移动售票、统一 POS、虚拟排队、分销，以及按游客档案管理通行权益与园内消费记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:375152','Open Journal Systems','{"deployment": ["自托管部署（官方发布包或源码）", "PHP 8.2+", "MySQL/MariaDB/PostgreSQL"], "features": ["可配置的分步投稿向导", "同行评审：指派审稿人、设置截止日期并自动提醒", "按投稿、评审、文字编辑和生产阶段跟踪稿件", "可配置用户角色与编辑团队分工", "期刊与文章元数据发布，支持 OAI-PMH 等发现渠道"], "github_repository_id": 375152, "homepage": "https://pkp.sfu.ca/software/ojs/", "id": "github:375152", "leaf_matches": [{"reason": "PKP 官方编辑工作流正文分章证明：新投稿进入 Submission 阶段并分配编辑、可作桌面决定或转评审；Review 阶段分配审稿人、跟踪审稿状态、开启新评审轮次、请求修改并作最终编辑决定；随后经 Copyediting、Production 制作校样，最终创建并出版期号。README 仅用于确认 OJS 的期刊管理定位。", "slug": "academic-journal-management", "source_urls": ["https://github.com/pkp/ojs", "https://raw.githubusercontent.com/pkp/ojs/main/LICENSE", "https://raw.githubusercontent.com/pkp/ojs/main/README.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/copyedit.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/production.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/publication.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/review.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/submission.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/index.md"]}, {"reason": "Official OJS README and PKP docs describe a journal record with Future/Back issues, issue creation and article scheduling with publication dates, issue publish/unpublish, and subscription types, expiry, renewals and payments, while submission/peer review is treated only as adjacent machinery.", "slug": "magazine-periodical-management", "source_urls": ["https://api.github.com/repos/pkp/ojs", "https://raw.githubusercontent.com/pkp/ojs/main/README.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/publication.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/3.4/en/subscriptions.md", "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/journal-managers/en/content-access.md"]}, {"reason": "OJS 以投稿—评审—编辑—生产为主线，支持指派编辑/审稿人、设置截止日期和逾期提醒，并有可配置角色；稿件记录从投稿持续到发表，符合出版编辑工作流的阶段、关卡与角色分派核心。", "slug": "publishing-editorial-workflow", "source_urls": ["https://pkp.sfu.ca/software/ojs/", "https://raw.githubusercontent.com/pkp/ojs/main/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/pkp/ojs/license", "name": "Open Journal Systems", "repository_url": "https://github.com/pkp/ojs", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:17:36.265747+08:00", "kind": "repository_metadata", "sha256": "3379cfed12dd12f0dfba04faa294ee0e6345d51f0433c51a3d905182e934f093", "snapshot_path": "sources/3379cfed12dd12f0dfba04faa294ee0e6345d51f0433c51a3d905182e934f093.txt", "url": "https://api.github.com/repos/pkp/ojs"}, {"fetched_at": "2026-10-25T08:41:28.366295+08:00", "kind": "repository_metadata", "sha256": "3598ef148b5e1e3f44a3d95cded69ba70f9eae8aae5e32468085c6c9d18a8590", "snapshot_path": "sources/3598ef148b5e1e3f44a3d95cded69ba70f9eae8aae5e32468085c6c9d18a8590.txt", "url": "https://api.github.com/repos/pkp/ojs"}, {"fetched_at": "2026-10-27T01:17:38.050387+08:00", "kind": "license", "sha256": "5eec326dbb6f25dde322c5d309db7ffc3b76f3818fa39d158e61ecf46eb1abe0", "snapshot_path": "sources/5eec326dbb6f25dde322c5d309db7ffc3b76f3818fa39d158e61ecf46eb1abe0.txt", "url": "https://api.github.com/repos/pkp/ojs/license"}, {"fetched_at": "2026-10-25T08:08:04.127386+08:00", "kind": "repository_metadata", "sha256": "7eb7ce8f387c44055a2d34cb647bb5ed055955f7173c25ca97870fdde6cbe048", "snapshot_path": "sources/7eb7ce8f387c44055a2d34cb647bb5ed055955f7173c25ca97870fdde6cbe048.txt", "url": "https://github.com/pkp/ojs"}, {"fetched_at": "2026-10-27T01:19:08.500449+08:00", "kind": "homepage", "sha256": "609be13ef5f665ea05d8f2600c8d8cead0291943e43610501faeadfcb69e95af", "snapshot_path": "sources/609be13ef5f665ea05d8f2600c8d8cead0291943e43610501faeadfcb69e95af.txt", "url": "https://pkp.sfu.ca/software/ojs/"}, {"fetched_at": "2026-10-25T08:08:17.040391+08:00", "kind": "license", "sha256": "3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986", "snapshot_path": "sources/3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986.txt", "url": "https://raw.githubusercontent.com/pkp/ojs/main/LICENSE"}, {"fetched_at": "2026-10-27T01:17:39.338044+08:00", "kind": "readme", "sha256": "04886c33cbcb9dd5145426bee7ff76fe0585f300b87c866e8ce398c3738a2c8d", "snapshot_path": "sources/04886c33cbcb9dd5145426bee7ff76fe0585f300b87c866e8ce398c3738a2c8d.txt", "url": "https://raw.githubusercontent.com/pkp/ojs/main/README.md"}, {"fetched_at": "2026-10-27T13:28:18.116508+08:00", "kind": "documentation", "sha256": "9c922e958d6aa8ce0864e539993a15492d3ec3be51448a5477165b1ccbcc94c9", "snapshot_path": "sources/9c922e958d6aa8ce0864e539993a15492d3ec3be51448a5477165b1ccbcc94c9.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/3.4/en/subscriptions.md"}, {"fetched_at": "2026-10-26T14:10:14.069987+08:00", "kind": "documentation", "sha256": "7e3916112a4f4df5cd0722513310214efb456d975d95ee6c13d054ab3ee4875a", "snapshot_path": "sources/7e3916112a4f4df5cd0722513310214efb456d975d95ee6c13d054ab3ee4875a.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/copyedit.md"}, {"fetched_at": "2026-10-26T14:10:15.624637+08:00", "kind": "documentation", "sha256": "12a7c86e31cbd5bfb623fd058284660c67f4cc343f1fb855d8d99f632d5cef87", "snapshot_path": "sources/12a7c86e31cbd5bfb623fd058284660c67f4cc343f1fb855d8d99f632d5cef87.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/production.md"}, {"fetched_at": "2026-10-26T14:10:16.992860+08:00", "kind": "documentation", "sha256": "9081147f7eb89fcc0a5991ac3e904521f0d81d5eb71c827fca39569b114e181f", "snapshot_path": "sources/9081147f7eb89fcc0a5991ac3e904521f0d81d5eb71c827fca39569b114e181f.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/publication.md"}, {"fetched_at": "2026-10-26T14:10:12.633115+08:00", "kind": "documentation", "sha256": "dbe51e821f98182c1597c277c1badde305904ba0e6e06aa12eaeeaa383db5457", "snapshot_path": "sources/dbe51e821f98182c1597c277c1badde305904ba0e6e06aa12eaeeaa383db5457.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/review.md"}, {"fetched_at": "2026-10-26T14:10:11.303636+08:00", "kind": "documentation", "sha256": "999f547ce95fe4d0aa5e5c4cd43d398e918e44bd4f088aa8d037b5f85cb89b0b", "snapshot_path": "sources/999f547ce95fe4d0aa5e5c4cd43d398e918e44bd4f088aa8d037b5f85cb89b0b.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/en/submission.md"}, {"fetched_at": "2026-10-26T13:58:52.522142+08:00", "kind": "documentation", "sha256": "44bc95021f8460c7cabb721f1f0abdc04f456f742fbf8984746993d3389b5742", "snapshot_path": "sources/44bc95021f8460c7cabb721f1f0abdc04f456f742fbf8984746993d3389b5742.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/editorial-workflow/index.md"}, {"fetched_at": "2026-10-27T13:29:05.690225+08:00", "kind": "documentation", "sha256": "895bcb21a398da7a27360951bf32898fcb779618a4be63e73ff262778684a0cb", "snapshot_path": "sources/895bcb21a398da7a27360951bf32898fcb779618a4be63e73ff262778684a0cb.txt", "url": "https://raw.githubusercontent.com/pkp/pkp-docs/main/learning-ojs/journal-managers/en/content-access.md"}], "summary": "Open Journal Systems（OJS）是 PKP 开发的开源学术期刊出版平台，覆盖投稿、同行评审、编辑加工与生产的完整编辑工作流，支持编辑角色、审稿截止日期和逾期提醒。", "technology_stack": ["PHP", "MySQL", "MariaDB", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:239727725','Thoth','{"deployment": ["Docker Compose（开发/生产）", "Rust/Cargo 原生运行", "PostgreSQL"], "features": ["面向开放获取图书与章节的结构化书目元数据管理", "ONIX、MARC、KBART、CSV、BibTeX、Crossref XML 等格式导出", "GraphQL API 与 REST 导出 API", "与 OMP 等出版工作流集成", "Docker 与原生 Rust 自托管部署"], "github_repository_id": 239727725, "homepage": "https://thoth.pub/", "id": "github:239727725", "leaf_matches": [{"reason": "Thoth 把图书/章节书目记录作为核心资产维护，并以 ONIX、MARC、KBART 等标准格式向平台、聚合器和索引自动导出，记录本身即交付物，符合出版元数据管理核心。", "slug": "publishing-metadata-management", "source_urls": ["https://thoth.pub/", "https://raw.githubusercontent.com/thoth-pub/thoth/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/thoth-pub/thoth/license", "name": "Thoth", "repository_url": "https://github.com/thoth-pub/thoth", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:17:36.253511+08:00", "kind": "repository_metadata", "sha256": "d2958f0351ce07959178a4a4f83bce8357a35c9e2421816e672e901be09d9a28", "snapshot_path": "sources/d2958f0351ce07959178a4a4f83bce8357a35c9e2421816e672e901be09d9a28.txt", "url": "https://api.github.com/repos/thoth-pub/thoth"}, {"fetched_at": "2026-10-27T01:17:37.735136+08:00", "kind": "license", "sha256": "c1a212b5521e88235ad979ebb38c1396801be0414f6c95015e840bedd2b4af32", "snapshot_path": "sources/c1a212b5521e88235ad979ebb38c1396801be0414f6c95015e840bedd2b4af32.txt", "url": "https://api.github.com/repos/thoth-pub/thoth/license"}, {"fetched_at": "2026-10-27T01:17:39.157643+08:00", "kind": "readme", "sha256": "39e9fc851cadd31c5d08c6589af4ea2b957177f08b0a2783733ce0750a2be037", "snapshot_path": "sources/39e9fc851cadd31c5d08c6589af4ea2b957177f08b0a2783733ce0750a2be037.txt", "url": "https://raw.githubusercontent.com/thoth-pub/thoth/master/README.md"}, {"fetched_at": "2026-10-27T01:17:51.990272+08:00", "kind": "homepage", "sha256": "7be253127d6cba49a1379a5d4292b97d210f5539c308194d0ee734a7bc78e139", "snapshot_path": "sources/7be253127d6cba49a1379a5d4292b97d210f5539c308194d0ee734a7bc78e139.txt", "url": "https://thoth.pub/"}], "summary": "Thoth 是面向开放获取图书的开源书目元数据管理与分发系统，集中维护图书/章节记录，并通过 ONIX、MARC、KBART、CSV、BibTeX 与 Crossref XML 等格式向外部平台、聚合器和索引交付。", "technology_stack": ["Rust", "PostgreSQL", "GraphQL", "REST"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:reprtoir','Reprtoir','{"homepage": "https://www.reprtoir.com/", "id": "commercial:reprtoir", "leaf_matches": [{"reason": "其目录管理、发行构建与版税核算覆盖受控录音目录、合同资金条款和收入→计算→账单的结算循环，符合唱片公司管理核心。", "slug": "record-label-management", "source_urls": ["https://www.reprtoir.com/", "https://www.reprtoir.com/royalty-accounting"]}], "name": "Reprtoir", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:20:11.134055+08:00", "kind": "homepage", "sha256": "f29c7094ad54b53ebd55667008d56a5997abb428eadff4584e25d76e19a63a37", "snapshot_path": "sources/f29c7094ad54b53ebd55667008d56a5997abb428eadff4584e25d76e19a63a37.txt", "url": "https://www.reprtoir.com/"}, {"fetched_at": "2026-10-27T01:20:12.771307+08:00", "kind": "documentation", "sha256": "8144e190d058a147460063c52da09c239954aa95fc062ad4d6c5d8c7c037a5be", "snapshot_path": "sources/8144e190d058a147460063c52da09c239954aa95fc062ad4d6c5d8c7c037a5be.txt", "url": "https://www.reprtoir.com/royalty-accounting"}], "summary": "Reprtoir 是面向唱片公司和音乐出版商的商业音乐业务工作区，集中管理曲目/发行目录、合同与版税核算，可导入多来源收入报表、计算版税并生成结算账单。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:artlogic','Artlogic','{"homepage": "https://artlogic.net/", "id": "commercial:artlogic", "leaf_matches": [{"reason": "Artlogic 明确覆盖作品编目与库存、寄售、销售型 CRM 和在线收款，并将作品与客户/销售记录关联，符合商业画廊管理核心。", "slug": "art-gallery-management", "source_urls": ["https://artlogic.net/"]}, {"reason": "产品页正文说明作品库存支持多地点、运输、寄售与借展、来源和状况报告，并用于跟踪展览、提案和 inventory lists；逐段运输交接的状态配对细节未在该页说明。", "slug": "artwork-exhibition-logistics", "source_urls": ["https://artlogic.net/products/gallery/management"]}], "name": "Artlogic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:20:11.510595+08:00", "kind": "homepage", "sha256": "618e6414903d6c22c581f6e8ef36683a5ee22341ac3d93f76def591370d88723", "snapshot_path": "sources/618e6414903d6c22c581f6e8ef36683a5ee22341ac3d93f76def591370d88723.txt", "url": "https://artlogic.net/"}, {"fetched_at": "2026-10-27T01:54:30.710207+08:00", "kind": "documentation", "sha256": "a0a2a1e4879e222a930863ce70329a24cd7616ee69cec45fad3e99489f1d957e", "snapshot_path": "sources/a0a2a1e4879e222a930863ce70329a24cd7616ee69cec45fad3e99489f1d957e.txt", "url": "https://artlogic.net/products/gallery/management"}], "summary": "Artlogic 是面向商业画廊的艺术业务平台，提供作品库存、寄售、销售与 CRM、网站和收款的一体化管理，并把作品状态与客户/销售记录关联起来。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:art-galleria','Art Galleria','{"homepage": "https://www.artgalleria.com/", "id": "commercial:art-galleria", "leaf_matches": [{"reason": "官方功能页在 Inventory & Collections 下明确列出 artworks、artists、locations、consignments，For Artists 一节亦列出 consignments；据此只确认官方把 consignments 作为库存与收藏模块管理的实体之一。逐件寄售作品记录、处置（sold/returned）状态、寄售条款、佣金/结算及艺术家与画廊共享记录未在快照中说明，均不作断言。", "slug": "artwork-consignment-management", "source_urls": ["https://www.artgalleria.com/features"]}], "name": "Art Galleria", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:27:49.197502+08:00", "kind": "documentation", "sha256": "95b5fd04cf9c1b46ed5a0baa11a0d36c07a0e55a9bb6b67d8227645251826be5", "snapshot_path": "sources/95b5fd04cf9c1b46ed5a0baa11a0d36c07a0e55a9bb6b67d8227645251826be5.txt", "url": "https://www.artgalleria.com/features"}], "summary": "面向画廊、艺术家工作室与收藏机构的商业艺术品管理平台；官方功能页将 consignments 列为库存与收藏模块管理的实体之一（同列 artworks、artists、editions、locations）。本条目仅按“寄售关系被列为库存实体”作基本类型记录；逐件处置状态、寄售条款、佣金/结算与艺术家共享记录均未在来源中核实。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:49451058','Arches','{"deployment": ["自托管 Python Web 应用；README 使用 pip 安装、arches-admin 建项目并在本地运行"], "features": ["不可移动文化遗产资产登记（考古遗址、建筑、历史结构、景观、遗产群/街区）", "基于地理空间的文化遗产清单管理与可视化", "Web 端遗产数据录入与查询", "自托管部署"], "github_repository_id": 49451058, "homepage": "https://www.archesproject.org/", "id": "github:49451058", "leaf_matches": [{"reason": "README 明确 Arches 是面向文化遗产清单与管理的 web-based geospatial information system，purpose-built 记录考古遗址、建筑、历史结构、景观与遗产群/街区；直接对应常设遗产资产记录、遗产领域描述和地理位置锚定。其定位为登记与清单管理，不涉及入藏、存储位置或借出，符合本类型无保管的边界。", "slug": "cultural-heritage-asset-management", "source_urls": ["https://raw.githubusercontent.com/archesproject/arches/dev/8.2.x/README.md", "https://www.archesproject.org/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/archesproject/arches/license", "name": "Arches", "repository_url": "https://github.com/archesproject/arches", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:24:56.206592+08:00", "kind": "repository_metadata", "sha256": "cf99f93dd3e4ccf31210d9a76b1b7b2a577a0b7815017ff864409f6d5ab81770", "snapshot_path": "sources/cf99f93dd3e4ccf31210d9a76b1b7b2a577a0b7815017ff864409f6d5ab81770.txt", "url": "https://api.github.com/repos/archesproject/arches"}, {"fetched_at": "2026-10-27T01:24:56.611913+08:00", "kind": "license", "sha256": "61012aff1db3fc1d01e3e07f3013ef89af959da15eed79c1d8b37012ce6173a6", "snapshot_path": "sources/61012aff1db3fc1d01e3e07f3013ef89af959da15eed79c1d8b37012ce6173a6.txt", "url": "https://api.github.com/repos/archesproject/arches/license"}, {"fetched_at": "2026-10-27T01:26:44.180206+08:00", "kind": "readme", "sha256": "1bedb3814ef59d986282013119203c61f6a75a8892220350fe31a902addc09a1", "snapshot_path": "sources/1bedb3814ef59d986282013119203c61f6a75a8892220350fe31a902addc09a1.txt", "url": "https://raw.githubusercontent.com/archesproject/arches/dev/8.2.x/README.md"}, {"fetched_at": "2026-10-27T01:26:46.146719+08:00", "kind": "homepage", "sha256": "109f95de72c7dce575dd6259c3d4f153891ce68b16d5a7791db7500e7d7cccc6", "snapshot_path": "sources/109f95de72c7dce575dd6259c3d4f153891ce68b16d5a7791db7500e7d7cccc6.txt", "url": "https://www.archesproject.org/"}], "summary": "开源文化遗产资产登记与地理信息管理平台：面向不可移动文化遗产（考古遗址、建筑、景观、历史街区等）建立可检索的资产清单，并提供空间管理与可视化；可自托管。", "technology_stack": ["Python", "JavaScript", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12057192','Omeka S','{"deployment": ["自托管 LAMP Web 应用（Linux/Apache/MySQL/PHP）；README 提供 GitHub 与发行包安装步骤"], "features": ["数字馆藏条目、媒体与元数据管理", "多个独立策展站点共享同一资源池", "发布条目并支持关联开放数据（Linked Open Data）", "模块与主题扩展", "LAMP 自托管安装"], "github_repository_id": 12057192, "homepage": "https://omeka.org/s/", "id": "github:12057192", "leaf_matches": [{"reason": "README 称 Omeka S 是面向大学、画廊、图书馆、档案馆、博物馆的 web publication system，由多个独立策展站点共享条目、媒体与元数据池；官网说明其发布 items、关联开放数据并连接数字文化遗产收藏。对应门户的已发布条目语料与面向外部受众的发布层；未据此断言具体检索控件、字段级发布控制或条目地址稳定性。", "slug": "digital-collection-portal", "source_urls": ["https://raw.githubusercontent.com/omeka/omeka-s/develop/README.md", "https://omeka.org/s/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/omeka/omeka-s/license", "name": "Omeka S", "repository_url": "https://github.com/omeka/omeka-s", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:25:05.539228+08:00", "kind": "repository_metadata", "sha256": "a8ae05df02f8c0ab4531cde0643c804a651cd690a821605286476ba9b92ef297", "snapshot_path": "sources/a8ae05df02f8c0ab4531cde0643c804a651cd690a821605286476ba9b92ef297.txt", "url": "https://api.github.com/repos/omeka/omeka-s"}, {"fetched_at": "2026-10-27T01:25:28.299634+08:00", "kind": "license", "sha256": "28da1c85dc7c02d04d601667b99efd0acc7909bb868f2dc2a4868062ecdf6883", "snapshot_path": "sources/28da1c85dc7c02d04d601667b99efd0acc7909bb868f2dc2a4868062ecdf6883.txt", "url": "https://api.github.com/repos/omeka/omeka-s/license"}, {"fetched_at": "2026-10-27T01:26:44.091074+08:00", "kind": "readme", "sha256": "66bebea205d007bbdcdf3231b103038ca81c64236ecc2aced3f01bd883545ae7", "snapshot_path": "sources/66bebea205d007bbdcdf3231b103038ca81c64236ecc2aced3f01bd883545ae7.txt", "url": "https://raw.githubusercontent.com/omeka/omeka-s/develop/README.md"}, {"fetched_at": "2026-10-27T01:26:45.721095+08:00", "kind": "homepage", "sha256": "91604ffcc6b2f98a9dd2949c12815730ae41bbbb7d2af7f4d48bab2b43854751", "snapshot_path": "sources/91604ffcc6b2f98a9dd2949c12815730ae41bbbb7d2af7f4d48bab2b43854751.txt", "url": "https://omeka.org/s/"}], "summary": "开源数字馆藏发布平台：机构可在共享的条目、媒体与元数据池上建立多个独立策展站点，向外部受众发布数字文化遗产收藏；可自托管。", "technology_stack": ["PHP", "MySQL", "JavaScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:146662901','Nebula','{"deployment": ["自托管/Docker 部署；README 说明仓库含 Dockerfile，官网称可在本地或共享环境 24/7 运行"], "features": ["基于 EBU Core 的媒体资产目录与元数据管理", "全库媒体检索", "低分辨率预览、trim 与子片段创建", "音视频交叉转码与规范化", "线性播出编排与播放控制", "Docker 部署"], "github_repository_id": 146662901, "homepage": "https://nebulabroadcast.com/", "id": "github:146662901", "leaf_matches": [{"reason": "README 明确 Nebula 是开源广播自动化与 MAM，媒体目录基于 EBU Core，含 genre、rights、relations、technical metadata，并提供快速检索、低分辨率预览、trim/子片段与转码；官网称其为可本地或共享部署的 MAM。对应资产记录、结构化元数据、全库检索/预览和媒体处理核心。未把归档分层/按需恢复或字段级权限写成已核实能力。", "slug": "media-asset-management-mam", "source_urls": ["https://raw.githubusercontent.com/nebulabroadcast/nebula/develop/README.md", "https://nebulabroadcast.com/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/nebulabroadcast/nebula/license", "name": "Nebula", "repository_url": "https://github.com/nebulabroadcast/nebula", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:26:44.218017+08:00", "kind": "repository_metadata", "sha256": "f89a0eb9319737fa7e6d00b2de363784d5737080645ee47003bee8988de6920f", "snapshot_path": "sources/f89a0eb9319737fa7e6d00b2de363784d5737080645ee47003bee8988de6920f.txt", "url": "https://api.github.com/repos/nebulabroadcast/nebula"}, {"fetched_at": "2026-10-27T01:26:45.730720+08:00", "kind": "license", "sha256": "6b54fffb2230dc095a42f4e5682b4b377244ce77856070b2c8a049298ddae6d2", "snapshot_path": "sources/6b54fffb2230dc095a42f4e5682b4b377244ce77856070b2c8a049298ddae6d2.txt", "url": "https://api.github.com/repos/nebulabroadcast/nebula/license"}, {"fetched_at": "2026-10-27T01:26:55.592435+08:00", "kind": "readme", "sha256": "952f8404fcbe5ba3f15257d443b2d3e436b8d13efbcf62576ad54ce662791746", "snapshot_path": "sources/952f8404fcbe5ba3f15257d443b2d3e436b8d13efbcf62576ad54ce662791746.txt", "url": "https://raw.githubusercontent.com/nebulabroadcast/nebula/develop/README.md"}, {"fetched_at": "2026-10-27T01:27:46.968913+08:00", "kind": "homepage", "sha256": "f5002575d861ab8a908481179a153701855236852387386f10b40480f4da83ef", "snapshot_path": "sources/f5002575d861ab8a908481179a153701855236852387386f10b40480f4da83ef.txt", "url": "https://nebulabroadcast.com/"}], "summary": "开源媒体资产管理与广播自动化系统：为电视台、电台和 VOD 平台建立基于 EBU Core 的媒体目录，提供元数据、检索、低分辨率预览、子片段、转码与播出编排；可自托管。", "technology_stack": ["Python", "React", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:4337337','CollectiveAccess Providence','{"deployment": ["自托管 PHP Web 应用；README 要求 PHP 8.2/8.3 并使用 Composer 安装依赖"], "features": ["博物馆/档案藏品编目与权威记录", "可配置字段、视图和工作流，适配多种元数据标准", "复杂登录号检索", "位置历史与来源历史跟踪", "图像、音视频、文档与 3D 媒体管理", "批量导入/导出与报告", "GraphQL API"], "github_repository_id": 4337337, "homepage": "https://collectiveaccess.org/", "id": "github:4337337", "leaf_matches": [{"reason": "官方仓库内置的 maxwell 安装配置把对象记录关联到类型为 site 的遗址记录（含 LA 遗址号与备用考古遗址号），并设置 Provenience 字段，说明其用于发掘出土物的土墩号、发掘单元号、探坑号和高程，示例明确要求把总遗址名（Cahokia）放入遗址字段、把 Mound 34 放入 Provenience 字段；同一配置还包含墓葬号、发掘历史、层级存储位置、借展与去入藏。官方功能说明另证对象、收藏、地点和存储位置的层级关系、位置跟踪与出入库；官方 Providence 文档证可配置元数据、层级关系、位置跟踪及状况/保护管理。故可支持考古藏品从遗址/发掘背景到入藏编目、存储位置、移动、借展和去入藏的核心工作流，而不只是通用博物馆编目。", "slug": "archaeological-collection-management", "source_urls": ["https://raw.githubusercontent.com/collectiveaccess/providence/master/install/profiles/xml/maxwell.xml", "https://www.collectiveaccess.org/features/", "https://docs.collectiveaccess.org/providence/"]}, {"reason": "README 说明 Providence 是 CollectiveAccess 的后端编目组件，面向博物馆、档案与研究收藏，支持多种元数据标准、复杂 accession numbers、位置历史与 provenance 跟踪、媒体与报告；官网称其为博物馆/档案收藏的开源编目软件。对应入藏编号、对象目录记录和持续编目/历史跟踪核心；未断言自动编号、防篡改审计或退编流程。", "slug": "museum-accession-cataloging", "source_urls": ["https://collectiveaccess.org/", "https://raw.githubusercontent.com/collectiveaccess/providence/master/README.md"]}, {"reason": "Providence 是面向博物馆/档案馆的编目与数据管理后端，支持对象记录、可配置元数据、层级关系与媒体。", "slug": "museum-collections-management", "source_urls": ["https://docs.collectiveaccess.org/providence", "https://raw.githubusercontent.com/collectiveaccess/providence/master/README.md", "https://www.collectiveaccess.org/"]}, {"reason": "官方专页说明存储位置层级、对象—位置关系与跨时间位置历史；README 亦列位置历史能力。", "slug": "museum-object-movement-management", "source_urls": ["https://docs.collectiveaccess.org/providence", "https://docs.collectiveaccess.org/providence/user/workflow/history_tracking_current_value", "https://raw.githubusercontent.com/collectiveaccess/providence/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/collectiveaccess/providence/license", "name": "CollectiveAccess Providence", "repository_url": "https://github.com/collectiveaccess/providence", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-29T17:03:29.131326+08:00", "kind": "repository_metadata", "sha256": "0c39aefb67d07aeed4d21ca7ae62ab41c13a14c787264dbdafc92f9b5c87df9c", "snapshot_path": "sources/0c39aefb67d07aeed4d21ca7ae62ab41c13a14c787264dbdafc92f9b5c87df9c.txt", "url": "https://api.github.com/repos/collectiveaccess/providence"}, {"fetched_at": "2026-10-27T01:25:10.029686+08:00", "kind": "repository_metadata", "sha256": "87bb065002eef7f2fd74578bccfe76536231319117d298788d9d41a0851fdce7", "snapshot_path": "sources/87bb065002eef7f2fd74578bccfe76536231319117d298788d9d41a0851fdce7.txt", "url": "https://api.github.com/repos/collectiveaccess/providence"}, {"fetched_at": "2026-10-27T01:25:31.498901+08:00", "kind": "license", "sha256": "7603e113372b1e0d14e9d99e6f79e2a21307b6014211610e1ee723d654cc2a8f", "snapshot_path": "sources/7603e113372b1e0d14e9d99e6f79e2a21307b6014211610e1ee723d654cc2a8f.txt", "url": "https://api.github.com/repos/collectiveaccess/providence/license"}, {"fetched_at": "2026-10-27T01:26:45.637773+08:00", "kind": "homepage", "sha256": "37fa351aaa1bbcb09fc2967b594bc4ddbffb540f30f8e0de66034eb474b934fc", "snapshot_path": "sources/37fa351aaa1bbcb09fc2967b594bc4ddbffb540f30f8e0de66034eb474b934fc.txt", "url": "https://collectiveaccess.org/"}, {"fetched_at": "2026-10-27T01:29:25.420649+08:00", "kind": "documentation", "sha256": "5ca9fc8eb02081e1503cbe685a436866ecfcbeaa8023e1a0f8a99a8aec19f874", "snapshot_path": "sources/5ca9fc8eb02081e1503cbe685a436866ecfcbeaa8023e1a0f8a99a8aec19f874.txt", "url": "https://docs.collectiveaccess.org/providence"}, {"fetched_at": "2026-10-29T17:03:29.438633+08:00", "kind": "documentation", "sha256": "5ca9fc8eb02081e1503cbe685a436866ecfcbeaa8023e1a0f8a99a8aec19f874", "snapshot_path": "sources/5ca9fc8eb02081e1503cbe685a436866ecfcbeaa8023e1a0f8a99a8aec19f874.txt", "url": "https://docs.collectiveaccess.org/providence/"}, {"fetched_at": "2026-10-27T01:29:36.826993+08:00", "kind": "documentation", "sha256": "3ce8b470c8005040e4591fc37255e1540f7a9ef8d324b3700fd2ffd886b0af55", "snapshot_path": "sources/3ce8b470c8005040e4591fc37255e1540f7a9ef8d324b3700fd2ffd886b0af55.txt", "url": "https://docs.collectiveaccess.org/providence/user/setup/systemReq"}, {"fetched_at": "2026-10-27T01:29:25.723518+08:00", "kind": "documentation", "sha256": "7d5f349f04ef6529c096fb5081bd1c25ae0390141ad07e25535c94dcb3e47d4a", "snapshot_path": "sources/7d5f349f04ef6529c096fb5081bd1c25ae0390141ad07e25535c94dcb3e47d4a.txt", "url": "https://docs.collectiveaccess.org/providence/user/workflow/history_tracking_current_value"}, {"fetched_at": "2026-10-27T01:26:44.102574+08:00", "kind": "readme", "sha256": "692c03438d5028845e704d87893f2f65177e1ad013ea1ad1b94c51f7e96aba25", "snapshot_path": "sources/692c03438d5028845e704d87893f2f65177e1ad013ea1ad1b94c51f7e96aba25.txt", "url": "https://raw.githubusercontent.com/collectiveaccess/providence/master/README.md"}, {"fetched_at": "2026-10-29T17:03:30.170314+08:00", "kind": "documentation", "sha256": "e68d4258d8d8cb7b9bfdab63f9858b6920c624a5251c385fbb0777396162d3f8", "snapshot_path": "sources/e68d4258d8d8cb7b9bfdab63f9858b6920c624a5251c385fbb0777396162d3f8.txt", "url": "https://raw.githubusercontent.com/collectiveaccess/providence/master/install/profiles/xml/maxwell.xml"}, {"fetched_at": "2026-10-27T01:29:24.513075+08:00", "kind": "homepage", "sha256": "37fa351aaa1bbcb09fc2967b594bc4ddbffb540f30f8e0de66034eb474b934fc", "snapshot_path": "sources/37fa351aaa1bbcb09fc2967b594bc4ddbffb540f30f8e0de66034eb474b934fc.txt", "url": "https://www.collectiveaccess.org/"}, {"fetched_at": "2026-10-29T17:03:29.372039+08:00", "kind": "documentation", "sha256": "ea965516d445acf1c67c501a6bcc0e73710ba011163b0912d8f71c64f9ec967d", "snapshot_path": "sources/ea965516d445acf1c67c501a6bcc0e73710ba011163b0912d8f71c64f9ec967d.txt", "url": "https://www.collectiveaccess.org/features/"}], "summary": "开源博物馆/档案藏品编目与数据管理后端：按可配置元数据标准建立藏品记录，支持复杂登录号检索、位置与来源历史、媒体、报告和批量导入导出；可自托管。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1402200883','Madrona','{"deployment": ["Docker Compose 自托管", "本地开发：Python 3.12 + Node.js 20.19 + PostgreSQL 16 + Redis", "可选 OpenSearch；数据库搜索回退", "S3 兼容对象存储（默认 SeaweedFS）"], "features": ["对象级编目：标题、尺寸、铭文、材料、分类及人物/机构关联", "藏品流程：入库、征集、借入借出、展览、退出与去藏", "状况报告与保护处理记录，含事件报告、估值与保险", "层级位置树、对象移动跟踪与位置历史", "条码标签、扫描盘点与位置核对", "多租户与基于角色的访问控制", "IIIF 媒体与可选公开发现"], "github_repository_id": 1402200883, "homepage": "https://www.madrona.app", "id": "github:1402200883", "leaf_matches": [{"reason": "Collections 应用提供对象级编目、入藏/征集与完整保管流程，是系统的藏品登记与业务记录核心。", "slug": "museum-collections-management", "source_urls": ["https://raw.githubusercontent.com/madrona-app/madrona/main/README.md", "https://www.madrona.app/collections/", "https://www.madrona.app/"]}, {"reason": "官方正文明确列出 Condition checking：结构化状况评估、摄影与保护建议，并保留状况报告记录。", "slug": "museum-condition-reporting", "source_urls": ["https://raw.githubusercontent.com/madrona-app/madrona/main/README.md", "https://www.madrona.app/collections/", "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/record_condition_check.md"]}, {"reason": "官方正文明确列出 Conservation：处理、材料、保护历史及前后文档，并依附于对象记录。", "slug": "museum-conservation-management", "source_urls": ["https://raw.githubusercontent.com/madrona-app/madrona/main/README.md", "https://www.madrona.app/collections/", "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/start_conservation_treatment.md"]}, {"reason": "官方正文明确列出 Loans in & out：借入/借出、设施报告、状况文件与保险跟踪。", "slug": "museum-loan-management", "source_urls": ["https://raw.githubusercontent.com/madrona-app/madrona/main/README.md", "https://www.madrona.app/collections/", "https://www.madrona.app/", "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/process_loan_in.md", "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/process_loan_out.md"]}, {"reason": "官方正文明确列出 Location & movement control：当前位置、历史、位置间移动授权，并有层级位置与盘点。", "slug": "museum-object-movement-management", "source_urls": ["https://raw.githubusercontent.com/madrona-app/madrona/main/README.md", "https://www.madrona.app/collections/", "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/record_movement.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/madrona-app/madrona/license", "name": "Madrona", "repository_url": "https://github.com/madrona-app/madrona", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:29:01.146511+08:00", "kind": "repository_metadata", "sha256": "00bee9856fc17d241919327774135b9cf920a808b02b30a6908ab4390660d9e9", "snapshot_path": "sources/00bee9856fc17d241919327774135b9cf920a808b02b30a6908ab4390660d9e9.txt", "url": "https://api.github.com/repos/madrona-app/madrona"}, {"fetched_at": "2026-10-27T01:29:01.294020+08:00", "kind": "license", "sha256": "9c94356ef4470e9220f3051b8af7dca9594cdf28fc3da67d6edb9a7999654771", "snapshot_path": "sources/9c94356ef4470e9220f3051b8af7dca9594cdf28fc3da67d6edb9a7999654771.txt", "url": "https://api.github.com/repos/madrona-app/madrona/license"}, {"fetched_at": "2026-10-27T01:29:00.965048+08:00", "kind": "readme", "sha256": "bc5969e1f00d9ff5525e54deb5844e675534d3bacf421f7fcae342a91b5756e8", "snapshot_path": "sources/bc5969e1f00d9ff5525e54deb5844e675534d3bacf421f7fcae342a91b5756e8.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/README.md"}, {"fetched_at": "2026-10-27T01:29:06.376771+08:00", "kind": "documentation", "sha256": "61919bc59b16cd73fd3f0c101da27f50119c7eb656cfb06099a63c111e36baae", "snapshot_path": "sources/61919bc59b16cd73fd3f0c101da27f50119c7eb656cfb06099a63c111e36baae.txt", "url": "https://www.madrona.app/collections/"}, {"fetched_at": "2026-10-27T01:29:01.410445+08:00", "kind": "homepage", "sha256": "220f87a047e1d2267ff10183dcfb809dbf0688fb69d52e762301a020682584c3", "snapshot_path": "sources/220f87a047e1d2267ff10183dcfb809dbf0688fb69d52e762301a020682584c3.txt", "url": "https://www.madrona.app/"}, {"fetched_at": "2026-10-27T01:31:44.053188+08:00", "kind": "documentation", "sha256": "68e61cab1fc0110e8c565333489c2c1bfe978e2bf22da6c3eca6bf60c5009b89", "snapshot_path": "sources/68e61cab1fc0110e8c565333489c2c1bfe978e2bf22da6c3eca6bf60c5009b89.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/process_loan_out.md"}, {"fetched_at": "2026-10-27T01:31:44.103211+08:00", "kind": "documentation", "sha256": "18bc0e1ec648affbfc7364f0294f5cebb707786b463e207977a0c0507d6c1a87", "snapshot_path": "sources/18bc0e1ec648affbfc7364f0294f5cebb707786b463e207977a0c0507d6c1a87.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/process_loan_in.md"}, {"fetched_at": "2026-10-27T01:31:44.124172+08:00", "kind": "documentation", "sha256": "140f9ef37f063976d32c478a02e83cee5077a85fcd409f2e69e05115cd644f68", "snapshot_path": "sources/140f9ef37f063976d32c478a02e83cee5077a85fcd409f2e69e05115cd644f68.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/record_condition_check.md"}, {"fetched_at": "2026-10-27T01:31:44.300209+08:00", "kind": "documentation", "sha256": "3b31c1f1b861b72e64112a7ef7f17ae1b53be516848e7d69261657e979a695ae", "snapshot_path": "sources/3b31c1f1b861b72e64112a7ef7f17ae1b53be516848e7d69261657e979a695ae.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/start_conservation_treatment.md"}, {"fetched_at": "2026-10-27T01:31:44.095221+08:00", "kind": "documentation", "sha256": "695b17976a14d9c1c58af38102cfaf3c46847e79a609477743ddbb416105fde3", "snapshot_path": "sources/695b17976a14d9c1c58af38102cfaf3c46847e79a609477743ddbb416105fde3.txt", "url": "https://raw.githubusercontent.com/madrona-app/madrona/main/backend/playbooks/record_movement.md"}], "summary": "面向博物馆与文化机构的开源藏品管理平台。Collections 应用覆盖对象编目、入藏与征集、借入借出、展览、状况报告、保护处理、层级位置与移动跟踪、盘点及退出；Apache-2.0，可通过 Docker Compose 自托管。", "technology_stack": ["Python 3.12", "FastAPI", "SQLAlchemy", "Alembic", "Celery", "React 19", "TypeScript", "PostgreSQL 16", "Redis", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wideorbit','WideOrbit','{"homepage": "https://wideorbit.com/", "id": "commercial:wideorbit", "leaf_matches": [{"reason": "以线性广告库存为对象，贯通订单、播出排期、播出后对账与计费，符合广播管理系统的播出日志与结算主干。", "slug": "broadcast-management-system", "source_urls": ["https://wideorbit.com/", "https://wideorbit.com/products"]}], "name": "WideOrbit", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:37:10.249009+08:00", "kind": "homepage", "sha256": "154ebf6a4fe6dff460ac28a537503f889f7a165171d53657229d22e45213ddfd", "snapshot_path": "sources/154ebf6a4fe6dff460ac28a537503f889f7a165171d53657229d22e45213ddfd.txt", "url": "https://wideorbit.com/"}, {"fetched_at": "2026-10-27T01:38:01.836430+08:00", "kind": "documentation", "sha256": "5c470104475f12267f8af50cad4d5e1d0c731749ab3aef08c5eb0a5f82a0c130", "snapshot_path": "sources/5c470104475f12267f8af50cad4d5e1d0c731749ab3aef08c5eb0a5f82a0c130.txt", "url": "https://wideorbit.com/products"}], "summary": "面向地方电视台、广播网与电台的广告销售与播出业务管理平台；WO Traffic 以单一记录系统贯通提案、订单、排期、对账与计费，管理线性广告库存和播出后结算。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:delenta','Delenta','{"homepage": "https://www.delenta.com/", "id": "commercial:delenta", "leaf_matches": [{"reason": "教练自定义套餐与课程经公开落地页和在线结账售出，购买后进入客户记录、预约和客户门户，覆盖报价—自助购买—履约跟踪的教练商务闭环。", "slug": "coaching-commerce-platform", "source_urls": ["https://www.delenta.com/", "https://www.delenta.com/sales-payments", "https://www.delenta.com/webpage"]}], "name": "Delenta", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:36:31.459437+08:00", "kind": "homepage", "sha256": "330bfb5dd6dac8227a844c68107e36915e4b04c7a8219e9fb8858ce991c5c2f5", "snapshot_path": "sources/330bfb5dd6dac8227a844c68107e36915e4b04c7a8219e9fb8858ce991c5c2f5.txt", "url": "https://www.delenta.com/"}, {"fetched_at": "2026-10-27T01:39:09.278240+08:00", "kind": "documentation", "sha256": "9a3e890ae44a48babef59fdcfea8d9d352f5111c998de77cf4088e3a9c4e9dd8", "snapshot_path": "sources/9a3e890ae44a48babef59fdcfea8d9d352f5111c998de77cf4088e3a9c4e9dd8.txt", "url": "https://www.delenta.com/sales-payments"}, {"fetched_at": "2026-10-27T01:39:12.575311+08:00", "kind": "documentation", "sha256": "a7339b84c61ea409d7907307a8b7516109e755976757823119af117d9444ed70", "snapshot_path": "sources/a7339b84c61ea409d7907307a8b7516109e755976757823119af117d9444ed70.txt", "url": "https://www.delenta.com/webpage"}], "summary": "面向教练与教练机构的业务管理平台：创建并销售教练套餐、课程和单次/团体课程，通过教练落地页与在线结账收款，并把购买接入客户管理、预约与客户门户。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:amagi','Amagi','{"homepage": "https://www.amagi.com/", "id": "commercial:amagi", "leaf_matches": [{"reason": "以内容库存和分发产品为起点，面向多个外部平台建立交付并实时跟踪分发/履约状态，符合提供商侧内容分发平台的核心结构。", "slug": "content-distribution-platform", "source_urls": ["https://www.amagi.com/products/amagi-now", "https://www.amagi.com/products/amagi-connect"]}], "name": "Amagi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:36:01.640594+08:00", "kind": "documentation", "sha256": "f8ef03f3f7abe5a4147dfca742151646c15d086552c64a12e91ba002500cace0", "snapshot_path": "sources/f8ef03f3f7abe5a4147dfca742151646c15d086552c64a12e91ba002500cace0.txt", "url": "https://www.amagi.com/products/amagi-now"}, {"fetched_at": "2026-10-27T01:36:23.517661+08:00", "kind": "documentation", "sha256": "1984e3a884d37997398fe40d42625a5ab0765ca6f82934685ff316e8cfb7d696", "snapshot_path": "sources/1984e3a884d37997398fe40d42625a5ab0765ca6f82934685ff316e8cfb7d696.txt", "url": "https://www.amagi.com/products/amagi-connect"}], "summary": "提供商侧媒体运营与内容分发平台：内容所有者通过 Amagi NOW 与 Amagi CONNECT 将线性频道和 VOD 内容交付到 FAST、vMVPD、SVOD 等外部平台，并跟踪各目的地的分发、履约、版权与本地化状态。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:459095253','LinkStack','{"deployment": ["自托管 Web 服务器（PHP 8 + Apache/Nginx）", "Docker 镜像 linkstackorg/linkstack", "社区实例或官方付费托管实例"], "features": ["有序外链链接页", "多用户与单用户模式", "主题自定义", "管理面板", "点击分析", "数据导入导出", "内置 SMTP"], "github_repository_id": 459095253, "homepage": "https://linkstack.org/", "id": "github:459095253", "leaf_matches": [{"reason": "为每个用户托管稳定地址的链接页，以有序外链为核心内容，管理面板支持无代码编辑并即时发布，定位为社交资料单一链接的替代。", "slug": "link-in-bio-platform", "source_urls": ["https://api.github.com/repos/LinkStackOrg/LinkStack", "https://raw.githubusercontent.com/LinkStackOrg/LinkStack/main/README.md", "https://linkstack.org/", "https://linkstack.org/get-started"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/LinkStackOrg/LinkStack/license", "name": "LinkStack", "repository_url": "https://github.com/LinkStackOrg/LinkStack", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:35:49.841070+08:00", "kind": "repository_metadata", "sha256": "bcb1773975f6ad14fb784fb1340c49cbf961db44cb5e1b4fb6ce7cb3a4bfc3f5", "snapshot_path": "sources/bcb1773975f6ad14fb784fb1340c49cbf961db44cb5e1b4fb6ce7cb3a4bfc3f5.txt", "url": "https://api.github.com/repos/LinkStackOrg/LinkStack"}, {"fetched_at": "2026-10-27T01:35:51.540479+08:00", "kind": "license", "sha256": "ea0be93071e4aabbacf1547dbe1aab9ea73a1b5a0da8cb18f21ea1612bcad153", "snapshot_path": "sources/ea0be93071e4aabbacf1547dbe1aab9ea73a1b5a0da8cb18f21ea1612bcad153.txt", "url": "https://api.github.com/repos/LinkStackOrg/LinkStack/license"}, {"fetched_at": "2026-10-27T01:35:57.676312+08:00", "kind": "readme", "sha256": "385d2b94a3084dcabe27ba652ac4c5949d7968b91e34d7368ccf732498a36d5f", "snapshot_path": "sources/385d2b94a3084dcabe27ba652ac4c5949d7968b91e34d7368ccf732498a36d5f.txt", "url": "https://raw.githubusercontent.com/LinkStackOrg/LinkStack/main/README.md"}, {"fetched_at": "2026-10-27T01:38:54.780712+08:00", "kind": "homepage", "sha256": "99f7a5b513183613d357f1c8e5285f4bba30cdefaeeea2f314fdec3422cc0f3b", "snapshot_path": "sources/99f7a5b513183613d357f1c8e5285f4bba30cdefaeeea2f314fdec3422cc0f3b.txt", "url": "https://linkstack.org/"}, {"fetched_at": "2026-10-27T01:38:59.056582+08:00", "kind": "documentation", "sha256": "71d676e0d3c332064760daeb991d396642a5c3b84b5a97559b79d95e6cc801ff", "snapshot_path": "sources/71d676e0d3c332064760daeb991d396642a5c3b84b5a97559b79d95e6cc801ff.txt", "url": "https://linkstack.org/get-started"}], "summary": "开源自托管的 Link-in-Bio/链接聚合平台：用户通过管理面板维护有序外链与主题，在自托管实例或托管实例上发布个人链接页，替代社交资料中的单一链接；采用 AGPL-3.0，社区核心可自托管，官方亦提供付费托管套餐。", "technology_stack": ["PHP 8", "SQLite/MySQL/MariaDB", "Docker", "Apache/Nginx"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:piano-subscriptions','Piano Subscriptions','{"homepage": "https://www.piano.io/", "id": "commercial:piano-subscriptions", "leaf_matches": [{"reason": "官方 Subscriptions 产品页正文说明该平台连接用户身份、受众细分、实时个性化、计费与支付，覆盖从订阅获取到续订的完整生命周期，并以 Stripe Billing 为核心；站点导航还列出管理、计费、访问控制、灵活定价、印刷订阅与身份管理。对应订阅记录、定期收费续订、订阅状态驱动内容访问的运营侧业务层，主要服务媒体/出版行业。", "slug": "media-subscription-management", "source_urls": ["https://www.piano.io/product/subscriptions"]}], "name": "Piano Subscriptions", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:40:28.063575+08:00", "kind": "homepage", "sha256": "7b1970d1bfa792534cc5e60e8a042dde1e86092176a6a4b7ddf18fb841ecb4fe", "snapshot_path": "sources/7b1970d1bfa792534cc5e60e8a042dde1e86092176a6a4b7ddf18fb841ecb4fe.txt", "url": "https://www.piano.io/product/subscriptions"}], "summary": "面向媒体与出版机构的订阅业务平台，连接用户身份、受众细分、个性化、计费与支付，覆盖从获取到续订的订阅生命周期，并以 Stripe Billing 处理支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tunecore','TuneCore','{"homepage": "https://www.tunecore.com/", "id": "commercial:tunecore", "leaf_matches": [{"reason": "官方首页正文说明可无限上传单曲、EP、专辑并分发至 Spotify、Apple Music、YouTube、TikTok 等 150+ 商店，按月可靠收到流媒体收入，艺人保留 100% 音乐所有权，且从其他分发商迁移目录时保留播放量与发行日期。对应以发行版为记录单元、维护目标商店网络、交付上线与收入回传的分发平台核心；首页未细述逐店上线时序与下架流程，关系仅按已证实范围记录。", "slug": "music-distribution-platform", "source_urls": ["https://www.tunecore.com/"]}], "name": "TuneCore", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:40:34.031887+08:00", "kind": "homepage", "sha256": "cbdbe153f934e2723612d72ba1a9d294c5cb5b5a20bc32a65d249165c8fc8822", "snapshot_path": "sources/cbdbe153f934e2723612d72ba1a9d294c5cb5b5a20bc32a65d249165c8fc8822.txt", "url": "https://www.tunecore.com/"}], "summary": "面向独立艺术家与厂牌的数字音乐分发服务，将单曲、EP 与专辑交付至 150+ 商店和流媒体平台，按月回传收入并保留艺人版权。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:submithub','SubmitHub','{"homepage": "https://www.submithub.com/", "id": "commercial:submithub", "leaf_matches": [{"reason": "官方首页正文说明这是让音乐被评论和推广的透明渠道，艺术家可向 1,700+ 经质量审核的 Spotify 播放列表主、音乐博客与影响者提交音乐，并称已有超过一百万艺术家、公关与厂牌使用。对应提交录音、独立策展人网络与策展人审听并给出评论/推广结果的流程；首页未展示退款或回复保证的具体条款，故不记录该保证关系。", "slug": "music-promotion-platform", "source_urls": ["https://www.submithub.com/"]}], "name": "SubmitHub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:40:35.386347+08:00", "kind": "homepage", "sha256": "433247670c27cae79f3f3f2763a6e224f946f9c6095cea365407e07757ab057d", "snapshot_path": "sources/433247670c27cae79f3f3f2763a6e224f946f9c6095cea365407e07757ab057d.txt", "url": "https://www.submithub.com/"}], "summary": "连接艺术家、厂牌与独立策展人的音乐推广平台，音乐人提交曲目供播放列表主、博客与影响者审听、评论与推广。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:82463450','LibreTime','{"deployment": ["自托管服务器部署", "地面广播或网络电台播出环境"], "features": ["导入音乐、台标/转场与完整节目的音频库管理", "节目与播客自动排程", "AM/FM 与网络音频播出", "自托管网络电台运行"], "github_repository_id": 82463450, "homepage": "https://libretime.org/", "id": "github:82463450", "leaf_matches": [{"reason": "官方站首页与 README 说明 LibreTime 是广播与自动化平台：可导入音乐、转场音与完整节目，自动排程节目和播客，并向广播控制台、AM/FM 发射机或云端网络电台播出。对应电台音频库、按时间编排的播出计划与自动播放执行的三个核心结构；日志的商业广告位来源未在已取正文中展开，不记录与流量/计费系统的集成关系。", "slug": "radio-station-management", "source_urls": ["https://libretime.org/", "https://raw.githubusercontent.com/LibreTime/libretime/main/README.md", "https://api.github.com/repos/libretime/libretime"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/libretime/libretime/license", "name": "LibreTime", "repository_url": "https://github.com/libretime/libretime", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:38:27.792521+08:00", "kind": "repository_metadata", "sha256": "cf4eed4a6b1b88ce64388e64567b9e24b5dfd29b470fab0042f5178d379190e6", "snapshot_path": "sources/cf4eed4a6b1b88ce64388e64567b9e24b5dfd29b470fab0042f5178d379190e6.txt", "url": "https://api.github.com/repos/libretime/libretime"}, {"fetched_at": "2026-10-27T01:38:29.503812+08:00", "kind": "license", "sha256": "fe37a56e2b9b5a9ba257fad4f4b9a02d8eda8631d50c9f6e13dc9f5223f418b1", "snapshot_path": "sources/fe37a56e2b9b5a9ba257fad4f4b9a02d8eda8631d50c9f6e13dc9f5223f418b1.txt", "url": "https://api.github.com/repos/libretime/libretime/license"}, {"fetched_at": "2026-10-27T01:38:30.776276+08:00", "kind": "readme", "sha256": "ba3a095b9debfab70b2fb6ceefe3468fd1e4d0b74f90b0e959f2d2545d32cbd2", "snapshot_path": "sources/ba3a095b9debfab70b2fb6ceefe3468fd1e4d0b74f90b0e959f2d2545d32cbd2.txt", "url": "https://raw.githubusercontent.com/LibreTime/libretime/main/README.md"}, {"fetched_at": "2026-10-27T01:40:25.858149+08:00", "kind": "homepage", "sha256": "a1dfa32d8d4b2b71096419d2ecedc554189fe1f10de4c5d3bf4d03eb074fdb58", "snapshot_path": "sources/a1dfa32d8d4b2b71096419d2ecedc554189fe1f10de4c5d3bf4d03eb074fdb58.txt", "url": "https://libretime.org/"}], "summary": "自托管的广播电台管理与播出自动化平台，管理音频库、自动排程节目与播客，并输出到 AM/FM 发射机或网络电台。", "technology_stack": ["PHP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:199892949','CourseLit','{"deployment": ["官方提供自托管指南", "可部署到 Vercel 或 Docker", "媒体资产依赖 MediaLit，可自建实例"], "features": ["课程创作与课程目录管理", "学生/会员管理与课程访问授予", "Stripe 结账与销售页面", "一次性、订阅、分期和免费会员方案", "发票与支付生命周期记录"], "github_repository_id": 199892949, "homepage": "https://courselit.app", "id": "github:199892949", "leaf_matches": [{"reason": "官方文档显示课程创作、Stripe 结账、销售页与会员访问，memberships 文档进一步给出一次性/订阅/分期/免费方案及支付后授予课程访问，覆盖课程电商完整循环。", "slug": "creator-course-commerce-platform", "source_urls": ["https://raw.githubusercontent.com/codelitdev/courselit/main/docs/README.md", "https://raw.githubusercontent.com/codelitdev/courselit/main/docs/memberships.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/codelitdev/courselit/license", "name": "CourseLit", "repository_url": "https://github.com/codelitdev/courselit", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:42:01.474542+08:00", "kind": "repository_metadata", "sha256": "164dfc762fc4461f1b86b158aded70d9e9d58347a070ac93eb095c8f226af35b", "snapshot_path": "sources/164dfc762fc4461f1b86b158aded70d9e9d58347a070ac93eb095c8f226af35b.txt", "url": "https://api.github.com/repos/codelitdev/courselit"}, {"fetched_at": "2026-10-27T01:42:02.034356+08:00", "kind": "license", "sha256": "3fe3e8e6d977256b0aabc65e23ce79aa9f749aaa403494fbcc361dc0614d12fc", "snapshot_path": "sources/3fe3e8e6d977256b0aabc65e23ce79aa9f749aaa403494fbcc361dc0614d12fc.txt", "url": "https://api.github.com/repos/codelitdev/courselit/license"}, {"fetched_at": "2026-10-27T01:42:19.088503+08:00", "kind": "documentation", "sha256": "412d2dd82ecc11561c18f5fb791095c7a354694101b5e09cfad20666f1c55dfd", "snapshot_path": "sources/412d2dd82ecc11561c18f5fb791095c7a354694101b5e09cfad20666f1c55dfd.txt", "url": "https://raw.githubusercontent.com/codelitdev/courselit/main/docs/README.md"}, {"fetched_at": "2026-10-27T01:42:19.141385+08:00", "kind": "documentation", "sha256": "3c4075cc6ffc84c6d629fdec23178834a7f5a2925817be8e6fd0f55fc37c907e", "snapshot_path": "sources/3c4075cc6ffc84c6d629fdec23178834a7f5a2925817be8e6fd0f55fc37c907e.txt", "url": "https://raw.githubusercontent.com/codelitdev/courselit/main/docs/memberships.md"}], "summary": "CourseLit 是 AGPL-3.0 开源自托管课程电商平台，提供课程创作、学生/会员管理、Stripe 结账、销售页与会员访问，支持一次性、订阅、分期和免费方案。", "technology_stack": ["TypeScript（GitHub 仓库主要语言）", "pnpm workspaces monorepo"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hurdlr','Hurdlr','{"homepage": "https://hurdlr.com/", "id": "commercial:hurdlr", "leaf_matches": [{"reason": "官方首页/功能页与 Hurdlr University 帮助中心正文显示：收入规则可按收入类别、业务、客户自动标记入账；Pro 发票有 Draft/Scheduled/Unpaid/Processing/Paid/Archived/Refunded 状态，并可将 Stripe payout、银行入账或现金匹配到发票，支持部分付款；提供 P&L、按业务收入汇总及 Pro 的 Balance Sheet/Trial Balance/Aged Accounts/Income by Client。覆盖收入归集、已开票到已收款推进和汇总视图；未声称多平台 creator payout 自动归集。", "slug": "creator-revenue-management", "source_urls": ["https://www.hurdlr.com/", "https://www.hurdlr.com/invoicing", "https://university.hurdlr.com/en/articles/3730428-what-are-income-rules", "https://university.hurdlr.com/en/articles/9904004-how-do-i-mark-my-invoices-as-paid-pro", "https://university.hurdlr.com/en/articles/6593991-can-i-accept-payments-through-my-invoices-pro", "https://university.hurdlr.com/en/articles/8396016-can-i-export-a-profit-loss-report", "https://university.hurdlr.com/en/articles/3878797-what-advanced-reports-are-available-with-hurdlr-pro-pro", "https://university.hurdlr.com/en/articles/1773186-how-do-i-view-total-mileage-expenses-and-earnings-per-business"]}], "name": "Hurdlr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:43:19.405111+08:00", "kind": "homepage", "sha256": "e29757b0492493c650360b7e3de63ac4f76cf368144f9861034f0df5963a1843", "snapshot_path": "sources/e29757b0492493c650360b7e3de63ac4f76cf368144f9861034f0df5963a1843.txt", "url": "https://www.hurdlr.com/"}, {"fetched_at": "2026-10-27T01:43:19.541067+08:00", "kind": "homepage", "sha256": "3a0dcc03b129a562fcd850460b131e8333ead5cbe88049bad796996171774684", "snapshot_path": "sources/3a0dcc03b129a562fcd850460b131e8333ead5cbe88049bad796996171774684.txt", "url": "https://www.hurdlr.com/accounting"}, {"fetched_at": "2026-10-27T01:43:19.561009+08:00", "kind": "homepage", "sha256": "f74797033316d08a3fba94f071ccd26733a67f9e5363dedbbe17265d92248d92", "snapshot_path": "sources/f74797033316d08a3fba94f071ccd26733a67f9e5363dedbbe17265d92248d92.txt", "url": "https://www.hurdlr.com/invoicing"}, {"fetched_at": "2026-10-27T01:52:24.808560+08:00", "kind": "documentation", "sha256": "9b012259174ae10f2050d5837f80acce2af5530fe9f172be1dc1d59a99b5284d", "snapshot_path": "sources/9b012259174ae10f2050d5837f80acce2af5530fe9f172be1dc1d59a99b5284d.txt", "url": "https://university.hurdlr.com/en/articles/9904004-how-do-i-mark-my-invoices-as-paid-pro"}, {"fetched_at": "2026-10-27T01:52:43.962718+08:00", "kind": "documentation", "sha256": "3bd33ef4cd9e587cdcf94064c4834d6f9a2680d28573aaee9a46e494750cbe77", "snapshot_path": "sources/3bd33ef4cd9e587cdcf94064c4834d6f9a2680d28573aaee9a46e494750cbe77.txt", "url": "https://university.hurdlr.com/en/articles/6593991-can-i-accept-payments-through-my-invoices-pro"}, {"fetched_at": "2026-10-27T01:52:36.420556+08:00", "kind": "documentation", "sha256": "c5c6f7aa064059773a96fdeebdb1b49b547751f71959d4c03d7e9e831bdc3499", "snapshot_path": "sources/c5c6f7aa064059773a96fdeebdb1b49b547751f71959d4c03d7e9e831bdc3499.txt", "url": "https://university.hurdlr.com/en/articles/3730428-what-are-income-rules"}, {"fetched_at": "2026-10-27T01:52:38.441523+08:00", "kind": "documentation", "sha256": "21fbf67d44ddc182e72b969a1f260c1f7c9d1bc887fda262d1d83bc0c4a67774", "snapshot_path": "sources/21fbf67d44ddc182e72b969a1f260c1f7c9d1bc887fda262d1d83bc0c4a67774.txt", "url": "https://university.hurdlr.com/en/articles/8396016-can-i-export-a-profit-loss-report"}, {"fetched_at": "2026-10-27T01:52:40.227176+08:00", "kind": "documentation", "sha256": "da548b879bbf4dae1aef79f39d41e3710c629ddd42d98eca6647f21e65231c3f", "snapshot_path": "sources/da548b879bbf4dae1aef79f39d41e3710c629ddd42d98eca6647f21e65231c3f.txt", "url": "https://university.hurdlr.com/en/articles/3878797-what-advanced-reports-are-available-with-hurdlr-pro-pro"}, {"fetched_at": "2026-10-27T01:52:42.158926+08:00", "kind": "documentation", "sha256": "d4683778d3a8f0ddb61ac2904edd10254a42703f0ee133ae849a55f285d92a7a", "snapshot_path": "sources/d4683778d3a8f0ddb61ac2904edd10254a42703f0ee133ae849a55f285d92a7a.txt", "url": "https://university.hurdlr.com/en/articles/1773186-how-do-i-view-total-mileage-expenses-and-earnings-per-business"}], "summary": "Hurdlr 是面向自由职业者和小企业的收入/费用追踪、开票收款与会计报表应用；可按收入类别/客户/业务归集入账，Pro 发票状态覆盖草稿到已付/已退款，并可匹配 Stripe 付款或银行入账，提供 P&L 及 Pro 的资产负债表/试算表等报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:movie-magic-scheduling','Movie Magic Scheduling','{"homepage": "https://www.ep.com/movie-magic-scheduling/", "id": "commercial:movie-magic-scheduling", "leaf_matches": [{"reason": "产品页说明以条板拖拽编排拍摄日程、管理多单元 sub-board、自动检测共享资源冲突并提供完整日历；通告单生成未在该页说明，关系仅限于排期核心。", "slug": "production-scheduling-call-sheet-application", "source_urls": ["https://www.ep.com/movie-magic-scheduling/"]}, {"reason": "产品页说明支持 multi-episode management、block shoots 和 cross-boards，可在同一日程中管理多集场景与同一天跨集拍摄。", "slug": "tv-production-management", "source_urls": ["https://www.ep.com/movie-magic-scheduling/"]}], "name": "Movie Magic Scheduling", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:54:27.074471+08:00", "kind": "documentation", "sha256": "eb1b58ba5f55e784b2fb431c8316da59469d87fe4b15cd63f3bff0e739187f52", "snapshot_path": "sources/eb1b58ba5f55e784b2fb431c8316da59469d87fe4b15cd63f3bff0e739187f52.txt", "url": "https://www.ep.com/movie-magic-scheduling/"}], "summary": "Entertainment Partners 的商业影视排期软件，产品页说明条板式场景编排、多集管理与 cross-board、多单元 sub-board、自动冲突检测和多用户实时协作；该页未说明通告单生成。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:yamdu','Yamdu','{"homepage": "https://yamdu.com/", "id": "commercial:yamdu", "leaf_matches": [{"reason": "官网正文说明可拖拽场景组装条板与拍摄日程、实时生成 Day-Out-Of-Days，并可创建或复用模板生成通告单后发送和跟踪，覆盖场景到拍摄日再到通告单的链条。", "slug": "production-scheduling-call-sheet-application", "source_urls": ["https://yamdu.com/"]}, {"reason": "官网正文说明可从 Final Draft、PDF 等格式导入剧本，由 AI 生成分解建议供各部门确认和填充，属于剧本→场景→元素分解工作流。", "slug": "script-breakdown-application", "source_urls": ["https://yamdu.com/"]}, {"reason": "官网将 TV Series 列为适用制作类型，并在同一平台说明剧集的剧本分解、排期、Day-Out-Of-Days 和通告单工作流。", "slug": "tv-production-management", "source_urls": ["https://yamdu.com/"]}], "name": "Yamdu", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:54:23.355352+08:00", "kind": "documentation", "sha256": "08fd0a8a30eb9f326848e7886cfbf3a5086de49c0e3d274c02d6cf8f633df51c", "snapshot_path": "sources/08fd0a8a30eb9f326848e7886cfbf3a5086de49c0e3d274c02d6cf8f633df51c.txt", "url": "https://yamdu.com/"}], "summary": "面向电影、电视、广告和纪录片的商业制作管理平台，官网说明其覆盖剧本导入与 AI 辅助分解、场景条板与拍摄日程、Day-Out-Of-Days 报表，以及通告单模板生成、发送与跟踪。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:setkeeper','SetKeeper','{"homepage": "https://www.setkeeper.com/", "id": "commercial:setkeeper", "leaf_matches": [{"reason": "官网正文说明自动剧本分解并据此创建 sides，可按拍摄顺序和多集交叉排序，属于把剧本场景转为制作输出的分解流程。", "slug": "script-breakdown-application", "source_urls": ["https://www.setkeeper.com/"]}, {"reason": "官网标明面向 film & TV，正文说明按集处理剧本、自动分解与多集 cross-boarding 的 sides 生成，并提供水印分发与通告单功能入口。", "slug": "tv-production-management", "source_urls": ["https://www.setkeeper.com/"]}], "name": "SetKeeper", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:54:25.157733+08:00", "kind": "documentation", "sha256": "a03efbf47cce1c706a94b0bbab06bd6fde2f162fc1f2bc95d7f5fa08210d5ad9", "snapshot_path": "sources/a03efbf47cce1c706a94b0bbab06bd6fde2f162fc1f2bc95d7f5fa08210d5ad9.txt", "url": "https://www.setkeeper.com/"}], "summary": "面向电影和电视制作的云端制作管理平台，官网说明提供剧本与文档水印分发、按场景生成 script sides、自动剧本分解和多集交叉排序，并列出通告单相关功能。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:scenechronize','Scenechronize','{"homepage": "https://www.ep.com/scenechronize/", "id": "commercial:scenechronize", "leaf_matches": [{"reason": "官网正文说明该云端制作办公室用于电视/影视项目，简化剧本分解、通告单和制作日程，生成角色与场景行数等剧本分析报告，并支持按集分发 sides、修订比较和按角色限定文档访问。", "slug": "tv-production-management", "source_urls": ["https://www.ep.com/scenechronize/"]}], "name": "Scenechronize", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:54:28.651452+08:00", "kind": "documentation", "sha256": "f2be2da11dbafa74db9848a4663001458786f3f2f169bdfe587911b439a5e74b", "snapshot_path": "sources/f2be2da11dbafa74db9848a4663001458786f3f2f169bdfe587911b439a5e74b.txt", "url": "https://www.ep.com/scenechronize/"}], "summary": "Entertainment Partners 的云端制作办公室产品，官网说明用于组织、管理和分发制作文档，支持剧本分析与修订比较、自动 sides、剧本分解、通告单、制作日程及按角色控制的剧组主页。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:playtomic','Playtomic','{"homepage": "https://playtomic.com/", "id": "commercial:playtomic", "leaf_matches": [{"reason": "官方帮助文章逐步说明在 app 中按运动、地点、日期/时段选择俱乐部球场与时长、分摊或全额支付，且价格和取消政策由各俱乐部设定；另一篇说明可从俱乐部资料页预订私场或加入公开比赛。构成球员端可预订场地库存、预订记录与第三方俱乐部中介关系。", "slug": "sports-court-booking", "source_urls": ["https://playerhelp.playtomic.com/hc/en-gb/articles/19831881490449-How-to-make-a-reservation-in-Playtomic-app", "https://playerhelp.playtomic.com/hc/en-gb/articles/19831715222929-How-to-book-a-court-or-a-spot-in-a-match-in-your-favourite-Club"]}], "name": "Playtomic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:02:50.788417+08:00", "kind": "documentation", "sha256": "87b03b4711ac2910fcb654a4edf9ce9f9ae76f630d80adb095b0e5fe2d2abbd0", "snapshot_path": "sources/87b03b4711ac2910fcb654a4edf9ce9f9ae76f630d80adb095b0e5fe2d2abbd0.txt", "url": "https://playerhelp.playtomic.com/hc/en-gb/articles/19831881490449-How-to-make-a-reservation-in-Playtomic-app"}, {"fetched_at": "2026-10-27T02:02:52.389523+08:00", "kind": "documentation", "sha256": "5a4d56350f2b569469013d1ea8560c0c77e97c2844d0a52265a63d06c6f89a57", "snapshot_path": "sources/5a4d56350f2b569469013d1ea8560c0c77e97c2844d0a52265a63d06c6f89a57.txt", "url": "https://playerhelp.playtomic.com/hc/en-gb/articles/19831715222929-How-to-book-a-court-or-a-spot-in-a-match-in-your-favourite-Club"}], "summary": "面向球员的场地预订应用：按运动、地点、日期和时段查找俱乐部球场，选择场地与时长并支付（支持分摊），预订受各俱乐部价格与取消政策约束。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ezfacility','EZFacility','{"homepage": "https://www.ezfacility.com/", "id": "commercial:ezfacility", "leaf_matches": [{"reason": "官方首页与功能页说明用于体育设施和多运动综合体的场地排期、租赁与特殊活动，并由同一系统处理会员、发票、支付与 QuickBooks 财务报告；对应运营方可租赁空间库存、预订交易和资金记录三个结构。", "slug": "sports-facility-management", "source_urls": ["https://www.ezfacility.com/", "https://www.ezfacility.com/features/scheduling-operations", "https://www.ezfacility.com/features/billing-payments"]}], "name": "EZFacility", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:01:50.057774+08:00", "kind": "homepage", "sha256": "ad066661cd7f4e10af0f34b187eb2fdc70f5dfe9830687ca74e07ef00ed55c94", "snapshot_path": "sources/ad066661cd7f4e10af0f34b187eb2fdc70f5dfe9830687ca74e07ef00ed55c94.txt", "url": "https://www.ezfacility.com/"}, {"fetched_at": "2026-10-27T02:03:25.474858+08:00", "kind": "documentation", "sha256": "b50bb7021e26d641ec3a696d79e93635810bb682554f2a080155cda524d72f38", "snapshot_path": "sources/b50bb7021e26d641ec3a696d79e93635810bb682554f2a080155cda524d72f38.txt", "url": "https://www.ezfacility.com/features/scheduling-operations"}, {"fetched_at": "2026-10-27T02:04:43.450439+08:00", "kind": "documentation", "sha256": "b6538e2fdcd8af1fbcfa66c0d7f7c3b0e6628be33c28140f04269253f5c2450f", "snapshot_path": "sources/b6538e2fdcd8af1fbcfa66c0d7f7c3b0e6628be33c28140f04269253f5c2450f.txt", "url": "https://www.ezfacility.com/features/billing-payments"}], "summary": "面向体育与健身场馆运营方的排期与营收管理软件：统一管理场地/场馆日历、租赁与课程，并处理会员、发票、支付和财务报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:golfnow','GolfNow','{"homepage": "https://www.golfnow.com/", "id": "commercial:golfnow", "leaf_matches": [{"reason": "官方 App 页说明可在全球数千家球场搜索 Hot Deals 并即时预订 tee time、收藏球场；课程目录页说明覆盖 19,000+ 球场；官方支持页说明预订保存在 Upcoming Reservations，可按球场政策修改或取消，并管理球员增减。可确认球手端发现、预订记录、自助管理与第三方球场关系。", "slug": "tee-time-booking-platform", "source_urls": ["https://www.golfnow.com/mobile", "https://www.golfnow.com/course-directory", "https://www.golfnow.com/support/about-us"]}], "name": "GolfNow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:39.687537+08:00", "kind": "documentation", "sha256": "ce6846ddc15a345422f9987f396b8ec106ce7501dd700e2c16d0a071c0324b5c", "snapshot_path": "sources/ce6846ddc15a345422f9987f396b8ec106ce7501dd700e2c16d0a071c0324b5c.txt", "url": "https://www.golfnow.com/mobile"}, {"fetched_at": "2026-10-27T02:05:10.663955+08:00", "kind": "documentation", "sha256": "aa1839ec9889f213556b35e9fd281d0e67d0e22c6dc493775332b8300b604dff", "snapshot_path": "sources/aa1839ec9889f213556b35e9fd281d0e67d0e22c6dc493775332b8300b604dff.txt", "url": "https://www.golfnow.com/course-directory"}, {"fetched_at": "2026-10-27T02:06:57.027604+08:00", "kind": "documentation", "sha256": "3a37342394352d89feb02440da5de96d3d6805ad752fd0166863260ca6b35093", "snapshot_path": "sources/3a37342394352d89feb02440da5de96d3d6805ad752fd0166863260ca6b35093.txt", "url": "https://www.golfnow.com/support/about-us"}], "summary": "面向高尔夫球手的开球时间预订平台：搜索并即时预订全球数千家球场的 tee time，可在账户中查看、修改或取消预订，并提供 Hot Deals、收藏球场与奖励。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fitbod','Fitbod','{"homepage": "https://fitbod.me/", "id": "commercial:fitbod", "leaf_matches": [{"reason": "官方首页可见正文说明 Fitbod 生成随身体、恢复和进度更新的个性化力量训练计划，跟踪训练表现并据此更新推荐；官方 FAQ 正文说明可按健身水平、表现历史、恢复状态、可用设备和目标逐次调整计划，用户可在 Gym Profile 调整目标后自动更新计划，动作含视频示范与文字提示。可确认软件自身完成评估、计划生成、训练引导与依据记录/恢复调整的闭环。", "slug": "ai-fitness-coach", "source_urls": ["https://fitbod.me/", "https://fitbod.me/faqs/"]}], "name": "Fitbod", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:57.840440+08:00", "kind": "homepage", "sha256": "639a63e8b4967f0f2a6d98573f4c71f386a3c54fb9c30f06c655b18bbec1cd57", "snapshot_path": "sources/639a63e8b4967f0f2a6d98573f4c71f386a3c54fb9c30f06c655b18bbec1cd57.txt", "url": "https://fitbod.me/"}, {"fetched_at": "2026-10-27T02:11:42+08:00", "kind": "documentation", "sha256": "e1748ca2f88f87fee6e8d5c18194f2d83390f0017555319d0fb0f77997722156", "snapshot_path": "sources/e1748ca2f88f87fee6e8d5c18194f2d83390f0017555319d0fb0f77997722156.txt", "url": "https://fitbod.me/faqs/"}], "summary": "面向个人的力量训练应用：根据目标、水平、可用设备和训练历史生成个性化计划，并依据表现与恢复情况持续调整推荐。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:ride-with-gps','Ride with GPS','{"homepage": "https://ridewithgps.com/", "id": "commercial:ride-with-gps", "leaf_matches": [{"reason": "官方首页以骑行为中心，明确提供路线规划与导航，并说明可记录骑行、配对传感器获取性能指标和跟踪训练进度，构成持续骑行记录及骑行性能语义。", "slug": "cycling-application", "source_urls": ["https://ridewithgps.com/"]}], "name": "Ride with GPS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:02:25.246827+08:00", "kind": "homepage", "sha256": "3742da3be4f7d7e9308385dbea317dd8eb8a32d371e666bb3c744ee919af3d31", "snapshot_path": "sources/3742da3be4f7d7e9308385dbea317dd8eb8a32d371e666bb3c744ee919af3d31.txt", "url": "https://ridewithgps.com/"}], "summary": "面向骑行者的云端路线规划、导航与骑行记录平台，提供路线规划器、逐向语音导航、离线地图、传感器配对及骑行数据记录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:trainingpeaks','TrainingPeaks','{"homepage": "https://www.trainingpeaks.com/", "id": "commercial:trainingpeaks", "leaf_matches": [{"reason": "官方首页明确为耐力训练平台，提供训练计划与日历、完成训练同步，以及 fitness/fatigue 分数对训练状态的累积，形成计划—执行—状态反馈闭环。", "slug": "endurance-training-platform", "source_urls": ["https://www.trainingpeaks.com/"]}], "name": "TrainingPeaks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:02:25.622811+08:00", "kind": "homepage", "sha256": "c670ef7b9b4d9d1d89ce49d79acdf3e83979d358f73bbe107ed710d6e3427389", "snapshot_path": "sources/c670ef7b9b4d9d1d89ce49d79acdf3e83979d358f73bbe107ed710d6e3427389.txt", "url": "https://www.trainingpeaks.com/"}], "summary": "面向耐力运动员与教练的训练平台，围绕训练计划、日历中的计划/已完成训练、设备同步及 fitness/fatigue 状态累积组织训练过程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fitnessgram','FitnessGram','{"homepage": "https://www.fitnessgram.net/", "id": "commercial:fitnessgram", "leaf_matches": [{"reason": "官方软件页明确跟踪体能评估分数与健康区间，采用五项研究定义评估并输出个人纵向报告；评估方案、个人记录和标准参照共同构成评估应用核心。", "slug": "fitness-assessment-application", "source_urls": ["https://www.fitnessgram.net/software-overview"]}], "name": "FitnessGram", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:02:47.073891+08:00", "kind": "documentation", "sha256": "260fdf3a005844b9413fd410bd1fd287c359652dbe458ae1f680fe4e7d585d20", "snapshot_path": "sources/260fdf3a005844b9413fd410bd1fd287c359652dbe458ae1f680fe4e7d585d20.txt", "url": "https://www.fitnessgram.net/software-overview"}], "summary": "面向学校体育教育的体能评估与数据平台，按研究定义的测试组合记录学生评估结果，并依据健康区间标准和纵向报告进行解读。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:7705569','wger','{"deployment": ["Docker Compose 自托管", "官方托管实例 wger.de"], "features": ["训练计划与训练日志", "体重与自定义身体测量记录", "饮食计划与食物数据库", "进度照片", "自托管与多用户"], "github_repository_id": 7705569, "homepage": "https://wger.de", "id": "github:7705569", "leaf_matches": [{"reason": "README 明确提供体重、自定义身体测量的持续记录以及进度照片，并支持自托管；这些带日期的个人测量与历史进度构成追踪器核心，属于该健身管理器的进度追踪模块。", "slug": "fitness-progress-tracker", "source_urls": ["https://raw.githubusercontent.com/wger-project/wger/master/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/wger-project/wger/master/LICENSE.txt", "license_review": {"rationale": "完整 LICENSE.txt 文本包含 GNU Affero General Public License Version 3 的条款与条件，仓库 README 亦标注 AGPL-3.0-or-later；按完整许可文本记录为 AGPL-3.0。", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/wger-project/wger/master/LICENSE.txt", "spdx_id": "AGPL-3.0"}, "name": "wger", "repository_url": "https://github.com/wger-project/wger", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:01:24.821051+08:00", "kind": "repository_metadata", "sha256": "aee3810443432f6b99356b3a1334656041cc468de7922b1a21f2fb9062afa392", "snapshot_path": "sources/aee3810443432f6b99356b3a1334656041cc468de7922b1a21f2fb9062afa392.txt", "url": "https://api.github.com/repos/wger-project/wger"}, {"fetched_at": "2026-10-27T02:02:39.403011+08:00", "kind": "readme", "sha256": "11b4826a7357eabd8756a6a5d21099f5660122e87ef6c4ec688249b351b42f05", "snapshot_path": "sources/11b4826a7357eabd8756a6a5d21099f5660122e87ef6c4ec688249b351b42f05.txt", "url": "https://raw.githubusercontent.com/wger-project/wger/master/README.md"}, {"fetched_at": "2026-10-27T02:03:02.989758+08:00", "kind": "license", "sha256": "57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6", "snapshot_path": "sources/57c8ff33c9c0cfc3ef00e650a1cc910d7ee479a8bc509f6c9209a7c2a11399d6.txt", "url": "https://raw.githubusercontent.com/wger-project/wger/master/LICENSE.txt"}], "summary": "AGPL-3.0 开源、可自托管的健身与训练管理器，提供体重和自定义身体测量记录、训练/饮食计划、进度照片及多用户支持；进度追踪作为其中模块存在。", "technology_stack": ["Python", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:myfitnesspal','MyFitnessPal','{"homepage": "https://www.myfitnesspal.com/", "id": "commercial:myfitnesspal", "leaf_matches": [{"reason": "官方首页明确为营养追踪应用，支持记录餐食并解析卡路里/宏量营养素，结合个人目标与营养反馈；构成食物日志、营养参考层与每日目标比较的核心闭环。", "slug": "food-calorie-tracking-application", "source_urls": ["https://www.myfitnesspal.com/"]}], "name": "MyFitnessPal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:02:26.072867+08:00", "kind": "homepage", "sha256": "07928ecb8f74886f57176743862782f2f76ffbcd5cdec958aa5017b1c09b5cb5", "snapshot_path": "sources/07928ecb8f74886f57176743862782f2f76ffbcd5cdec958aa5017b1c09b5cb5.txt", "url": "https://www.myfitnesspal.com/"}], "summary": "面向个人的营养与卡路里追踪应用，提供食物和餐次记录、食物营养数据库、卡路里/宏量营养素统计及个人每日目标反馈。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:thegrint','TheGrint','{"homepage": "https://thegrint.com/", "id": "commercial:thegrint", "leaf_matches": [{"reason": "官网首页正文写明“Track every score, manage an official handicap, get GPS distances on 40,000+ courses”，并以“Official handicap / USGA® data affiliate”标注；球员端逐轮记分、差点管理与球场 GPS 核心成立。", "slug": "golf-tracking-handicap-application", "source_urls": ["https://thegrint.com/"]}], "name": "TheGrint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:12:10.457778+08:00", "kind": "homepage", "sha256": "9bc7f85eaa8ebea83ca5b3be8553363707be7fe9db4eec71023be4feeaaa2546", "snapshot_path": "sources/9bc7f85eaa8ebea83ca5b3be8553363707be7fe9db4eec71023be4feeaaa2546.txt", "url": "https://thegrint.com/"}], "summary": "面向高尔夫球员的记分、差点与球场 GPS 应用，维护逐轮成绩并管理官方差点。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:193416728','HandicapTracker','{"deployment": ["AMP（Apache、MySQL、PHP）环境，自建 Web 服务"], "features": ["按球场保存名称、评分、坡度与 9 洞/18 洞标记", "录入总分并按球场评分/坡度计算差点差分", "持久保存差分历史，并通过 handicap-updater 维护差点指数", "PHP/MySQL 自托管 Web 界面"], "github_repository_id": 193416728, "homepage": "https://github.com/srukelman/HandicapTracker", "id": "github:193416728", "leaf_matches": [{"reason": "entry.php 与 hndcp_trckr.php 显示按球场评分/坡度、9/18 洞和日期录入总分并计算单轮差分；hndcp_insert.php 将差分写入 differentials 表、处理 9 洞合并并调用 handicap_calc；handicap-updater.php 为每个用户重算并写入 Handicap 表；recent-diffs.php 读取并展示当前差点趋势、差点指数和差分历史。属于简化的球员端记分与差点记录系统（不含逐洞成绩或发球台细目）。", "slug": "golf-tracking-handicap-application", "source_urls": ["https://raw.githubusercontent.com/srukelman/HandicapTracker/master/README.md", "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/entry.php", "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/hndcp_trckr.php", "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/hndcp_insert.php", "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/handicap-updater.php", "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/recent-diffs.php"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/LICENSE", "license_review": {"rationale": "完整 GNU GPL v3 许可证文本随仓库提供，正文含第 3 版条款与条款条件，仓库代码与许可证同属该仓库。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/LICENSE", "spdx_id": "GPL-3.0"}, "name": "HandicapTracker", "repository_url": "https://github.com/srukelman/HandicapTracker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:11:56.577523+08:00", "kind": "repository_metadata", "sha256": "e146af3e3ba378cf985a8bb2a8fe67eafa4e267a16c7851a6e6b426a73a099ee", "snapshot_path": "sources/e146af3e3ba378cf985a8bb2a8fe67eafa4e267a16c7851a6e6b426a73a099ee.txt", "url": "https://github.com/srukelman/HandicapTracker"}, {"fetched_at": "2026-10-27T02:11:57.795095+08:00", "kind": "readme", "sha256": "e7b39fddfa7cebfef4182666032794d94ba75ae235b7f744caada6865f300263", "snapshot_path": "sources/e7b39fddfa7cebfef4182666032794d94ba75ae235b7f744caada6865f300263.txt", "url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/README.md"}, {"fetched_at": "2026-10-27T02:11:59.266302+08:00", "kind": "license", "sha256": "3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986", "snapshot_path": "sources/3972dc9744f6499f0f9b2dbf76696f2ae7ad8af9b23dde66d6af86c9dfb36986.txt", "url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/LICENSE"}, {"fetched_at": "2026-10-27T02:12:19.515527+08:00", "kind": "documentation", "sha256": "9621f7be8eed468f2673423fcfe1531500b58bc19240028128ba8b8aab68bfe5", "snapshot_path": "sources/9621f7be8eed468f2673423fcfe1531500b58bc19240028128ba8b8aab68bfe5.txt", "url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/entry.php"}, {"fetched_at": "2026-10-27T02:12:20.608187+08:00", "kind": "documentation", "sha256": "46e6f5806f4c2408b4ea2ba77f19aec681be9cc862a4ed6fb15cf79b4713858a", "snapshot_path": "sources/46e6f5806f4c2408b4ea2ba77f19aec681be9cc862a4ed6fb15cf79b4713858a.txt", "url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/hndcp_trckr.php"}, {"fetched_at": "2026-10-27T02:18:43.471470+08:00", "kind": "documentation", "sha256": "f4ccd7eaabddadfd5674cd41f533b2dc94504cfd2a464fd821a97a7edcd92802", "snapshot_path": "sources/f4ccd7eaabddadfd5674cd41f533b2dc94504cfd2a464fd821a97a7edcd92802.txt", "url": "https://raw.githubusercontent.com/srukelman/HandicapTracker/master/hndcp_insert.php"}, {"fetched_at": "2026-10-27T02:18:43.412516+08:00", "kind": "documentation", "sha256": "81db9d62e70bf1898db39af6bb04210dbe9ac80f3f47eb0337fa7af2360c99d1", "snapshot_path": "sources/81db9d62e70bf1898db39af6bb04210dbe9ac80f3f47eb0337fa7af2360c9