INSERT INTO "application" VALUES('github:319167362','Mealie','{"deployment": ["Docker 自托管部署", "社区版完整代码与许可证同仓库"], "features": ["食谱导入与食谱库管理", "未来膳食计划（按周安排餐食）", "将某日或整份膳食计划加入购物清单，食材数量按计划份量带入", "REST API 与 Docker 自托管"], "github_repository_id": 319167362, "homepage": "https://mealie.io/", "id": "github:319167362", "leaf_matches": [{"reason": "README 明确提供未来膳食计划与购物清单；官方 Features 文档进一步说明“When you add a day or the whole plan to a shopping list, the ingredient quantities follow the serving sizes you''ve planned”，即购物清单由计划餐食派生并按计划份量带入食材，计划本身引用食谱内容，三项定义结构成立。", "slug": "meal-planning-application", "source_urls": ["https://raw.githubusercontent.com/mealie-recipes/mealie/master/README.md", "https://mealie.io/documentation/getting-started/features/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/mealie-recipes/mealie/master/LICENSE", "license_review": {"rationale": "完整 GNU Affero GPL v3 许可证文本随仓库提供，正文含第 3 版条款与条款条件，覆盖该仓库代码。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/mealie-recipes/mealie/master/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "Mealie", "repository_url": "https://github.com/mealie-recipes/mealie", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:11:56.432991+08:00", "kind": "repository_metadata", "sha256": "716f805c2703cce1260618c45cc63b601ff02f8dad94cf4f25acd312685b93ca", "snapshot_path": "sources/716f805c2703cce1260618c45cc63b601ff02f8dad94cf4f25acd312685b93ca.txt", "url": "https://github.com/mealie-recipes/mealie"}, {"fetched_at": "2026-10-27T02:11:57.801987+08:00", "kind": "readme", "sha256": "7a87d6463aba4d2050b89eb4e069b18e5b25ba268372234edbd8d6e8b34650fc", "snapshot_path": "sources/7a87d6463aba4d2050b89eb4e069b18e5b25ba268372234edbd8d6e8b34650fc.txt", "url": "https://raw.githubusercontent.com/mealie-recipes/mealie/master/README.md"}, {"fetched_at": "2026-10-27T02:11:59.313581+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/mealie-recipes/mealie/master/LICENSE"}, {"fetched_at": "2026-10-27T02:18:59.305940+08:00", "kind": "documentation", "sha256": "1dc238e1d7999fc812862c9ee6443af50b49aef153120bb4b99e5a108a654a16", "snapshot_path": "sources/1dc238e1d7999fc812862c9ee6443af50b49aef153120bb4b99e5a108a654a16.txt", "url": "https://mealie.io/documentation/getting-started/features/"}], "summary": "Mealie 是自托管的开源食谱管理与膳食计划应用：保存未来餐食计划，并可将某日或整份计划加入购物清单，食材数量按计划份量带入。", "technology_stack": ["Vue 前端", "REST API 后端", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1366620115','MeroDiet','{"deployment": ["作为 WordPress 插件自托管", "可用 wp-env 或现有 WordPress 安装部署"], "features": ["从业者客户名册与客户记录", "从食物/食谱库编制并分配个体化餐食计划", "客户记录进食合规、替换与体重等测量", "从业者仪表盘复核名册整体合规和计划-实际营养", "基于 USDA FoodData Central 的营养计算"], "github_repository_id": 1366620115, "homepage": "https://github.com/lihsaa591/merodiet", "id": "github:1366620115", "leaf_matches": [{"reason": "README 描述的完整闭环包括从业者客户名册、客户绑定的个体化餐食/营养计划、客户执行记录，以及从业者仪表盘复核；三个定义结构均成立。", "slug": "nutrition-coaching-platform", "source_urls": ["https://raw.githubusercontent.com/lihsaa591/merodiet/main/README.md"]}], "license": "GPL-2.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/lihsaa591/merodiet/main/LICENSE", "license_review": {"rationale": "README 第 72 行明确声明“GPL-2.0-or-later. See LICENSE.”，仓库 LICENSE 为完整 GNU GPL v2 文本；按项目声明记为 GPL-2.0-or-later，不窄化为 GPL-2.0-only。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/lihsaa591/merodiet/main/LICENSE", "spdx_id": "GPL-2.0-or-later"}, "name": "MeroDiet", "repository_url": "https://github.com/lihsaa591/merodiet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:11:56.881925+08:00", "kind": "repository_metadata", "sha256": "65a9f33e745fa063f2081191633ed0ff2f6c22f431ef60bb7a13955715eb9f2e", "snapshot_path": "sources/65a9f33e745fa063f2081191633ed0ff2f6c22f431ef60bb7a13955715eb9f2e.txt", "url": "https://github.com/lihsaa591/merodiet"}, {"fetched_at": "2026-10-27T02:11:58.258913+08:00", "kind": "readme", "sha256": "68ca632789167387d6516e0023b7c177fa2d41e91c3a92be0de16c5aa1004a37", "snapshot_path": "sources/68ca632789167387d6516e0023b7c177fa2d41e91c3a92be0de16c5aa1004a37.txt", "url": "https://raw.githubusercontent.com/lihsaa591/merodiet/main/README.md"}, {"fetched_at": "2026-10-27T02:11:59.717125+08:00", "kind": "license", "sha256": "edaef632cbb643e4e7a221717a6c441a4c1a7c918e6e4d56debc3d8739b233f6", "snapshot_path": "sources/edaef632cbb643e4e7a221717a6c441a4c1a7c918e6e4d56debc3d8739b233f6.txt", "url": "https://raw.githubusercontent.com/lihsaa591/merodiet/main/LICENSE"}], "summary": "MeroDiet 是自托管的开源营养指导实践管理插件，从业者维护客户名册、分配营养计划并复核客户执行记录。", "technology_stack": ["WordPress", "PHP", "React", "USDA FoodData Central API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fishbrain','Fishbrain','{"homepage": "https://fishbrain.com/", "id": "commercial:fishbrain", "leaf_matches": [{"reason": "官网首页正文同时呈现可钓鱼水域知识（钓点地图、深度图、当地渔获报告、法规）和带照片、物种识别、天气与统计的个人渔获日志，两结构及知识-记录循环成立。", "slug": "recreational-fishing-application", "source_urls": ["https://fishbrain.com/"]}], "name": "Fishbrain", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:12:08.721493+08:00", "kind": "homepage", "sha256": "82b2c0b7a3e693f532a19a6402be91767c979967a163f0f7111ea5a9376ad836", "snapshot_path": "sources/82b2c0b7a3e693f532a19a6402be91767c979967a163f0f7111ea5a9376ad836.txt", "url": "https://fishbrain.com/"}], "summary": "面向垂钓者的钓鱼应用，提供钓点与水域地图、当地渔获报告和法规查询，以及个人渔获日志。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:87005375','FitTrackee','{"deployment": ["Docker 自托管", "自有服务器部署，文件存储于本机上传目录"], "features": ["户外活动轨迹文件导入与无文件手动记录", "Running 等运动类型及配速显示", "地图、统计、records 与 segments", "装备关联和可见性控制", "多用户注册与互动"], "github_repository_id": 87005375, "homepage": "https://docs.fittrackee.org", "id": "github:87005375", "leaf_matches": [{"reason": "官方 Sports API 将 Running 列为一等运动并启用 pace 显示；Workouts API 保存距离、时长、移动时间、平均/最佳配速、records、segments 和地图，符合跑步记录及跑步性能语义。", "slug": "running-application", "source_urls": ["https://docs.fittrackee.org/en/api/sports.html", "https://docs.fittrackee.org/en/api/workouts.html", "https://raw.githubusercontent.com/SamR1/FitTrackee/main/README.md"]}, {"reason": "以已执行的单次 workout 为持久记录，支持文件导入和手动添加，并从历史记录派生统计、records 与装备关联；符合第一人称训练记录核心，但不主张力量训练专用能力。", "slug": "workout-tracking-application", "source_urls": ["https://docs.fittrackee.org/en/features/index.html", "https://docs.fittrackee.org/en/api/workouts.html", "https://raw.githubusercontent.com/SamR1/FitTrackee/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/SamR1/FitTrackee/license", "name": "FitTrackee", "repository_url": "https://github.com/SamR1/FitTrackee", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:08:35.446501+08:00", "kind": "repository_metadata", "sha256": "4ed21450d35de0d1b924b463825874785db5adcfbf507e5159018e12e085e57a", "snapshot_path": "sources/4ed21450d35de0d1b924b463825874785db5adcfbf507e5159018e12e085e57a.txt", "url": "https://api.github.com/repos/SamR1/FitTrackee"}, {"fetched_at": "2026-10-27T02:08:43.858935+08:00", "kind": "readme", "sha256": "cad9aac3f7860a7a56ecdc03c20f19a46279d6dd34bd891c4e4c418f13504cc9", "snapshot_path": "sources/cad9aac3f7860a7a56ecdc03c20f19a46279d6dd34bd891c4e4c418f13504cc9.txt", "url": "https://raw.githubusercontent.com/SamR1/FitTrackee/main/README.md"}, {"fetched_at": "2026-10-27T02:08:44.339785+08:00", "kind": "license", "sha256": "8fedf44149e8bd1d234a911fc522f3aef7