INSERT INTO "application" VALUES('commercial:trainheroic','TrainHeroic','{"homepage": "https://www.trainheroic.com/", "id": "commercial:trainheroic", "leaf_matches": [{"reason": "官方教练页正文说明可创建和整理 workouts、circuits、full programs，按 1:1 或团队交付计划，并在客户端跟踪完成度、进展与编程状态，符合处方先于执行及计划制品可移植的核心。", "slug": "workout-programming-application", "source_urls": ["https://www.trainheroic.com/coach/", "https://www.trainheroic.com/"]}], "name": "TrainHeroic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:10:28.469915+08:00", "kind": "homepage", "sha256": "8947f1c4cbfb22b6cd18d7e56ea5cec063bb3b0fe2b6fefde3709cc8b148d296", "snapshot_path": "sources/8947f1c4cbfb22b6cd18d7e56ea5cec063bb3b0fe2b6fefde3709cc8b148d296.txt", "url": "https://www.trainheroic.com/"}, {"fetched_at": "2026-10-27T02:10:46.739791+08:00", "kind": "homepage", "sha256": "51a9344b07c15805bb2821265946032d630430ea05ac6da73253cea02840986e", "snapshot_path": "sources/51a9344b07c15805bb2821265946032d630430ea05ac6da73253cea02840986e.txt", "url": "https://www.trainheroic.com/coach/"}], "summary": "面向力量与体能教练的训练编程与交付平台，可创建训练课和完整计划，按个人或团队交付并跟踪执行；商业产品仅记录基本用途与类型关系。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
