INSERT INTO "application" VALUES('commercial:jersey-watch','Jersey Watch','{"homepage": "https://jerseywatch.com/", "id": "commercial:jersey-watch", "leaf_matches": [{"reason": "官网正文明确其为 youth sports organizations 的一体化平台，提供 online registration、collect payments online、customized registration forms、message teams/divisions 与 scheduling；官方帮助中心 Online Registration 分类进一步列出创建项目、查看/导出报名人信息、退款、付款计划、免责声明、创建和管理队伍、私有项目，覆盖参与方案、平台内报名交易和报名名单三项核心。", "slug": "sports-registration-platform", "source_urls": ["https://www.jerseywatch.com/", "https://help.jerseywatch.com/category/182-online-registration"]}], "name": "Jersey Watch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:18:37.942123+08:00", "kind": "homepage", "sha256": "8b798a3645d91cafe0464e731a6f8dbd2f8272e2f8859bec6f857008d9581813", "snapshot_path": "sources/8b798a3645d91cafe0464e731a6f8dbd2f8272e2f8859bec6f857008d9581813.txt", "url": "https://www.jerseywatch.com/"}, {"fetched_at": "2026-10-27T02:22:50.018625+08:00", "kind": "documentation", "sha256": "be64337a70ba89c94de55a904694d5c7a0de1f3257d52bf55e69c25fa6a86fd5", "snapshot_path": "sources/be64337a70ba89c94de55a904694d5c7a0de1f3257d52bf55e69c25fa6a86fd5.txt", "url": "https://help.jerseywatch.com/category/182-online-registration"}], "summary": "面向青少年体育组织的商业管理平台，提供项目/赛季报名、在线收款、报名人信息查看与导出、退款与付款计划、免责声明、按队伍/分部的消息通知和赛程发布，并配套网站建设、背景调查与捐赠功能。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:576223889','Bracket','{"deployment": ["Docker Compose (backend, frontend and PostgreSQL)", "standalone deployment with uv and pnpm", "documented production and cloud deployment options"], "features": ["single elimination, round-robin and swiss formats", "multi-stage tournament builder with multiple groups and brackets", "team and player registration, including CSV import", "drag-and-drop match scheduling across courts and start times", "score entry, configurable rankings and public dashboards"], "github_repository_id": 576223889, "homepage": "https://docs.bracketapp.nl/", "id": "github:576223889", "leaf_matches": [{"reason": "README 与官方文档正文确认其支持单败/循环/瑞士格式、多阶段分组与对阵表、球队/球员、比分录入和公开排名，构成有界赛事容器、竞争格式、记录结果与计算晋级/名次的完整核心。", "slug": "tournament-management-platform", "source_urls": ["https://raw.githubusercontent.com/evroon/bracket/master/README.md", "https://docs.bracketapp.nl/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/evroon/bracket/license", "name": "Bracket", "repository_url": "https://github.com/evroon/bracket", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:18:47.346003+08:00", "kind": "repository_metadata", "sha256": "6533bf788e38693b8dde42d434b9f30c0a257cd29c74823cc7661b0d649490bf", "snapshot_path": "sources/6533bf788e38693b8dde42d434b9f30c0a257cd29c74823cc7661b0d649490bf.txt", "url": "https://api.github.com/repos/evroon/bracket"}, {"fetched_at": "2026-10-27T02:18:49.018220+08:00", "kind": "license", "sha256": "ee6b6cc517d867a78671e622ede235c2f665e0429ffcbec647a159b4663c6d51", "snapshot_path": "sources/ee6b6cc517d867a78671e622ede235c2f665e0429ffcbec647a159b4663c6d51.txt", "url": "https://api.github.com/repos/evroon/bracket/license"}, {"fetched_at": "2026-10-27T02:18:50.203436+08:00", "kind": "readme", "sha256": "54da1069c7a73db05bbbe6dd1fe8d4d511ad1e3a87a6c4c938bb4324380eb50e", "snapshot_path": "sources/54da1069c7a73db05bbbe6dd1fe8d4d511ad1e3a87a6c4c938bb4324380eb50e.tx