INSERT INTO "application" VALUES('commercial:rock-gym-pro','Rock Gym Pro','{"homepage": "https://www.rockgympro.com/", "id": "commercial:rock-gym-pro", "leaf_matches": [{"reason": "官网正文明确其 tailored for climbing gyms，并提供 memberships、digital waivers、check-in、memberships/day passes 的 POS、billing 与 online booking，覆盖访客身份、入场资格、签到和费用结算，且以数字免责声明承载攀岩安全姿态。", "slug": "climbing-gym-management", "source_urls": ["https://www.rockgympro.com/"]}], "name": "Rock Gym Pro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:18:43.137160+08:00", "kind": "homepage", "sha256": "d307a7b2372c7ce6429141d6227b20e1c517f0f5a31859b44e53cdebb4eaa636", "snapshot_path": "sources/d307a7b2372c7ce6429141d6227b20e1c517f0f5a31859b44e53cdebb4eaa636.txt", "url": "https://www.rockgympro.com/"}], "summary": "面向攀岩馆和高流量场馆的商业会员管理平台，提供会员与计费、数字免责声明、签到、日票/零售 POS、线上预约与报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
