INSERT INTO "application" VALUES('github:1109547882','Tandava','{"deployment": ["自托管：Supabase PostgreSQL + 静态 SPA 托管", "托管版与开源自托管共用同一代码库；需配置 Supabase、Stripe、邮件等环境变量"], "features": ["重复课程排程、代课与取消，活动/工作坊管理", "会员与课程包管理，购买和消耗跟踪", "学生档案、到访历史、免责声明与候补名单", "前台/自助签到（kiosk、二维码）", "教师工资率、可用性与出勤/收入/留存分析"], "github_repository_id": 1109547882, "homepage": "https://tandavastudio.com", "id": "github:1109547882", "leaf_matches": [{"reason": "把客户、会员/课程包权益、重复课程表、消耗权益的预约与签到、收款分析耦合在同一工作室运营循环中，符合工作室管理软件的四段结构。", "slug": "fitness-studio-management", "source_urls": ["https://raw.githubusercontent.com/TaylorONeal/tandava/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/TaylorONeal/tandava/license", "name": "Tandava", "repository_url": "https://github.com/TaylorONeal/tandava", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:19:44.293197+08:00", "kind": "repository_metadata", "sha256": "3e26aa090de5a1feccafbdc80161742960970c5a34a51bb20d81a8aa2fbc0386", "snapshot_path": "sources/3e26aa090de5a1feccafbdc80161742960970c5a34a51bb20d81a8aa2fbc0386.txt", "url": "https://api.github.com/repos/TaylorONeal/tandava"}, {"fetched_at": "2026-10-27T02:19:46.056570+08:00", "kind": "license", "sha256": "2bcd0720706c3e65990b9561eafc47e228d934a1e180c92dbfb399212932d7dd", "snapshot_path": "sources/2bcd0720706c3e65990b9561eafc47e228d934a1e180c92dbfb399212932d7dd.txt", "url": "https://api.github.com/repos/TaylorONeal/tandava/license"}, {"fetched_at": "2026-10-27T02:19:58.694541+08:00", "kind": "readme", "sha256": "88a71c55b7e94b98ecb7e9945cf9ea07e0796f66e1ca293b95fe0ffb5b4df1cc", "snapshot_path": "sources/88a71c55b7e94b98ecb7e9945cf9ea07e0796f66e1ca293b95fe0ffb5b4df1cc.txt", "url": "https://raw.githubusercontent.com/TaylorONeal/tandava/main/README.md"}], "summary": "面向瑜伽、普拉提及运动工作室的开源自托管工作室管理应用，覆盖重复课程排程、会员与课程包、预约/候补、签到、教师与收款，托管版与自托管共用同一代码。", "technology_stack": ["React 18 + TypeScript + Vite 7", "Supabase（PostgreSQL、Auth、Storage、Edge Functions）", "Stripe Connect 支付"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
