INSERT INTO "application" VALUES('commercial:athletemonitoring','AthleteMonitoring (FITSTATS)','{"homepage": "https://www.athletemonitoring.com/", "id": "commercial:athletemonitoring", "leaf_matches": [{"reason": "官方首页将该平台定位为 Athlete Management System，并说明集中训练/健康/负荷数据、个人与团队仪表板；Workout Builder 页说明可编排周期化训练、下发多周程序、回收每组负荷数据并保留完整训练历史，覆盖 AMS 的计划-执行-审查闭环。", "slug": "athlete-management-system", "source_urls": ["https://www.athletemonitoring.com/", "https://www.athletemonitoring.com/strength-and-conditioning-workout-builder/"]}], "name": "AthleteMonitoring (FITSTATS)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:30:00.380569+08:00", "kind": "homepage", "sha256": "3e246ad7ec1140db46cb2b1183df6e0bc7bf3279227ec44674f30eb473dda29e", "snapshot_path": "sources/3e246ad7ec1140db46cb2b1183df6e0bc7bf3279227ec44674f30eb473dda29e.txt", "url": "https://www.athletemonitoring.com/"}, {"fetched_at": "2026-10-27T02:29:57.401705+08:00", "kind": "documentation", "sha256": "9603d07c1eabcca6c4231a47c9e192bd42d64e187733824366c5c4e70ab6e2cf", "snapshot_path": "sources/9603d07c1eabcca6c4231a47c9e192bd42d64e187733824366c5c4e70ab6e2cf.txt", "url": "https://www.athletemonitoring.com/strength-and-conditioning-workout-builder/"}], "summary": "FITSTATS 的运动员监测/运动员管理 SaaS：以运动员和团队为单位集中训练、负荷、健康与测试数据，Workout Builder 支持编排周期化训练、下发到运动员手机并回收完成数据，教练据此查看训练历史并调整计划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
