INSERT INTO "application" VALUES('commercial:paintscout','PaintScout','{"homepage": "https://www.paintscout.com/", "id": "commercial:paintscout", "leaf_matches": [{"reason": "官方页面定位油漆承包商，提供估价/方案与电子签署、日程与作业管理、施工团队和开票收款，符合行业绑定的报价到履约流程。", "slug": "painting-contractor-management", "source_urls": ["https://www.paintscout.com/"]}], "name": "PaintScout", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:35:46.930679+08:00", "kind": "homepage", "sha256": "25f60c895143498d2d684c7dbf717d567193cf9614e25c5e1625d74680bc344e", "snapshot_path": "sources/25f60c895143498d2d684c7dbf717d567193cf9614e25c5e1625d74680bc344e.txt", "url": "https://www.paintscout.com/"}], "summary": "PaintScout 是面向油漆承包商的销售与运营软件：按项目制作并电子签署估价，发送方案、收款，管理线索、日程、作业和施工团队，并支持开票。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1367380420','OpenCare','{"deployment": ["Docker 自托管", "Windows 一体化安装包", "PWA 离线使用"], "features": ["照护圈与邀请/角色权限", "照护日志与照片", "共享日历与提醒", "用药计划与确认", "任务与购物清单", "消息、文档与联系人"], "github_repository_id": 1367380420, "homepage": "https://nexaflowfrance.github.io/OpenCare/", "id": "github:1367380420", "leaf_matches": [{"reason": "README 与 SPEC 展示以单个被照护者为锚点的多角色 care circle、共享实时 care journal、带指派人/状态的任务与共享日历；CarePlan 代码显示计划按被照护者（circle）保存并记录 updated_by 归属。覆盖个人、团队、计划与跟踪活动的协调闭环；计划为叙事段落而非目标/干预结构化模板。", "slug": "care-coordination-platform", "source_urls": ["https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/README.md", "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/docs/SPEC.md", "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/server/src/lib/carePlan.ts"]}, {"reason": "以被照护者为中心的私密照护圈，成员可发布/认领任务与购物需求、共享日历和更新，符合家庭照护协调核心。", "slug": "family-care-coordination", "source_urls": ["https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/NexaFlowFrance/OpenCare/license", "name": "OpenCare", "repository_url": "https://github.com/NexaFlowFrance/OpenCare", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:35:25.547821+08:00", "kind": "repository_metadata", "sha256": "08c3875c18ed661490940c4a0a2c23343219c3e803600f12a319f248111d6c0e", "snapshot_path": "sources/08c3875c18ed661490940c4a0a2c23343219c3e803600f12a319f248111d6c0e.txt", "url": "https://api.github.com/repos/NexaFlowFrance/OpenCare"}, {"fetched_at": "2026-10-27T02:35:27.295049+08:00", "kind": "license", "sha256": "63dd5f3880c336ceb2ae796f6a918dd14c35ca60f69c67caac968adb8a5cdd4d", "snapshot_path": "sources/63dd5f3880c336ceb2ae796f6a918dd14c35ca60f69c67caac968adb8a5cdd4d.txt", "url": "https://api.github.com/repos/NexaFlowFrance/OpenCare/license"}, {"fetched_at": "2026-10-27T02:35:28.563960+08:00", "kind": "readme", "sha256": "0c5004f03de9c071b770085c865082b1dc5ee1883dc47ed029c901c294450505", "snapshot_path": "sources/0c5004f03de9c071b770085c865082b1dc5ee1883dc47ed029c901c294450505.txt", "url": "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/README.md"}, {"fetched_at": "2026-10-26T23:09:46.762349+08:00", "kind": "documentation", "sha256": "c03c2b375c5c70aa1e57b2c6e267ed126147276e4c78b001f147a5482c9d447a", "snapshot_path": "sources/c03c2b375c5c70aa1e57b2c6e267ed126147276e4c78b001f147a5482c9d447a.txt", "url": "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/client/src/pages/CarePlan.tsx"}, {"fetched_at": "2026-10-26T23:09:22.208391+08:00", "kind": "documentation", "sha256": "9d811472675376bf0a4bcc809f9480008926616ffccf46ff0e24df473f592488", "snapshot_path": "sources/9d811472675376bf0a4bcc809f9480008926616ffccf46ff0e24df473f592488.txt", "url": "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/docs/SPEC.md"}, {"fetched_at": "2026-10-26T23:09:48.214174+08:00", "kind": "documentation", "sha256": "5b7407c164cd5b59ca6ab6c10c88c6c42458bda6bba3783fb21393c5da3d77e7", "snapshot_path": "sources/5b7407c164cd5b59ca6ab6c10c88c6c42458bda6bba3783fb21393c5da3d77e7.txt", "url": "https://raw.githubusercontent.com/NexaFlowFrance/OpenCare/main/server/src/lib/carePlan.ts"}], "summary": "OpenCare 是开源自托管的家庭照护协调应用（AGPL-3.0）：围绕一位被照护者建立受邀照护圈，提供共享日历、照护日志、任务与购物清单、用药提醒、消息和文档，并支持家庭成员与专业人员分角色协作。", "technology_stack": ["React", "TypeScript", "Node.js", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1124104820','OpenFamily','{"deployment": ["Docker 自托管", "PWA 离线使用", "Windows 安装包"], "features": ["共享日历与提醒", "购物清单与分类", "重复任务与成员分配", "周计划与餐食计划", "家庭预算", "家长/孩子角色权限"], "github_repository_id": 1124104820, "homepage": "https://openfamily.fr/", "id": "github:1124104820", "leaf_matches": [{"reason": "同一家庭共享空间内并列提供家庭日历与购物/任务/家务/餐食等家庭物品层，成员分配和提醒贯穿两者，符合家庭组织器核心。", "slug": "family-organizer", "source_urls": ["https://raw.githubusercontent.com/NexaFlowFrance/OpenFamily/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/NexaFlowFrance/OpenFamily/license", "name": "OpenFamily", "repository_url": "https://github.com/NexaFlowFrance/OpenFamily", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:35:25.568312+08:00", "kind": "repository_metadata", "sha256": "6969fafced70ce688065e31048fb0df6f06641901f64ce81dd612bb197dac3bf", "snapshot_path": "sources/6969fafced70ce688065e31048fb0df6f06641901f64ce81dd612bb197dac3bf.txt", "url": "https://api.github.com/repos/NexaFlowFrance/OpenFamily"}, {"fetched_at": "2026-10-27T02:35:27.236552+08:00", "kind": "license", "sha256": "5d192613730a7af5e2abbe1a028cb9fcdabce72fa4ec8f66a9533e3406b3d8b4", "snapshot_path": "sources/5d192613730a7af5e2abbe1a028cb9fcdabce72fa4ec8f66a9533e3406b3d8b4.txt", "url": "https://api.github.com/repos/NexaFlowFrance/OpenFamily/license"}, {"fetched_at": "2026-10-27T02:35:28.500509+08:00", "kind": "readme", "sha256": "fb042c1c71279efd7e271e2727856e72a0c1c865d5ce39d9996445cc0c7e45c9", "snapshot_path": "sources/fb042c1c71279efd7e271e2727856e72a0c1c865d5ce39d9996445cc0c7e45c9.txt", "url": "https://raw.githubusercontent.com/NexaFlowFrance/OpenFamily/main/README.md"}], "summary": "OpenFamily 是开源自托管的家庭组织器（AGPL-3.0）：以家庭成员共享空间统一提供共享日历、购物清单、任务与家务、餐食计划和预算，支持邀请成员、家长/孩子权限、提醒与 iCal 导出。", "technology_stack": ["React", "TypeScript", "Node.js", "PostgreSQL", "WebSocket"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:passare','Passare','{"homepage": "https://www.passare.com/", "id": "commercial:passare", "leaf_matches": [{"reason": "官方条码追踪页说明可为逝者、物品和位置分配可扫描条码，绑定到 Passare 案例并记录每次交接与移动，构成案例上的连续监护链；财务页说明预售案例（preneed case）与支付、库存，对应案例安排与结算。属于殡仪馆运营方围绕案例的业务系统，而非泛事件策划工具。", "slug": "funeral-home-management", "source_urls": ["https://www.passare.com/barcodetracking", "https://www.passare.com/financials"]}], "name": "Passare", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:40:45.603270+08:00", "kind": "homepage", "sha256": "8ace25a4b2d5e990f31bb74fcddfe5b0854a20c2f4c5f6bc547eb6d4c595fed0", "snapshot_path": "sources/8ace25a4b2d5e990f31bb74fcddfe5b0854a20c2f4c5f6bc547eb6d4c595fed0.txt", "url": "https://www.passare.com/"}, {"fetched_at": "2026-10-27T02:39:21.388000+08:00", "kind": "documentation", "sha256": "515ea8201de33fc29072abaa3f3a60159a1b74905fdd30efdbec20bc5ff8c62a", "snapshot_path": "sources/515ea8201de33fc29072abaa3f3a60159a1b74905fdd30efdbec20bc5ff8c62a.txt", "url": "https://www.passare.com/barcodetracking"}, {"fetched_at": "2026-10-27T02:39:23.249140+08:00", "kind": "documentation", "sha256": "181128cb650498805335b422803e9f4b389f8682f3c3fa6cd28b0e7b6035585d", "snapshot_path": "sources/181128cb650498805335b422803e9f4b389f8682f3c3fa6cd28b0e7b6035585d.txt", "url": "https://www.passare.com/financials"}], "summary": "面向殡仪馆的运营管理软件，围绕殡葬案例提供团队协作、家属在线安排、逝者/物品条码监护追踪，以及支付、预售案例与库存等财务工具。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:homezada','HomeZada','{"homepage": "https://www.homezada.com/", "id": "commercial:homezada", "leaf_matches": [{"reason": "官方 Home Projects 页标题即“Home Improvement Project Planner & Budgeting App”，说明房主可把想法、设计图或建议转成含项目详情、材料清单、购物选择与预算的项目计划，并按 DIY 或承包商项目估算数量、单价和总成本；项目挂在房主自己的住宅记录上，资金计划是决策变量。", "slug": "home-improvement-planner", "source_urls": ["https://www.homezada.com/homeowners/home-improvement"]}, {"reason": "官方首页把库存、维护、项目与财务描述为同一个住宅数字系统；文件管理页说明收据、保修、承包商文件、保单和房产记录汇入同一住宅记录，并回链维护支出、项目成本与库存价值，符合整合全屋档案并保持运营记录的核心。", "slug": "home-management-application", "source_urls": ["https://www.homezada.com/", "https://www.homezada.com/homeowners/home-document-management"]}], "name": "HomeZada", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:39:25.368382+08:00", "kind": "homepage", "sha256": "1ea0186f9fbb20090408b891aa6a7555179c80053080507a7b494f22cf6d8e6f", "snapshot_path": "sources/1ea0186f9fbb20090408b891aa6a7555179c80053080507a7b494f22cf6d8e6f.txt", "url": "https://www.homezada.com/"}, {"fetched_at": "2026-10-27T02:39:27.072713+08:00", "kind": "documentation", "sha256": "6098e535372327209dd86c9283017f4ab99e45a575315a18f57018ab7fc61931", "snapshot_path": "sources/6098e535372327209dd86c9283017f4ab99e45a575315a18f57018ab7fc61931.txt", "url": "https://www.homezada.com/homeowners/home-improvement"}, {"fetched_at": "2026-10-27T02:39:29.111121+08:00", "kind": "documentation", "sha256": "40b82bb62cf97379c65c3d93af5625e02443991f522905902e7c86fdf4c10900", "snapshot_path": "sources/40b82bb62cf97379c65c3d93af5625e02443991f522905902e7c86fdf4c10900.txt", "url": "https://www.homezada.com/homeowners/home-document-management"}, {"fetched_at": "2026-10-27T02:39:31.061508+08:00", "kind": "documentation", "sha256": "c83f5e32a8bdba8a4aff8ef82dc2b163120cedd25b0e8d154869ffceda7e6174", "snapshot_path": "sources/c83f5e32a8bdba8a4aff8ef82dc2b163120cedd25b0e8d154869ffceda7e6174.txt", "url": "https://www.homezada.com/homeowners/home-maintenance"}], "summary": "面向房主的家庭管理应用，把住宅库存、维护、改造项目、财务与文件整合进同一住宅记录；其中 Home Projects 提供从想法到预算与材料清单的改造规划。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:816422401','HomeBox','{"deployment": ["官方提供 Docker 镜像与 Compose 单容器部署，挂载数据目录持久化", "Go 服务内置 Web UI 与嵌入式 SQLite 数据库"], "features": ["以物品为单位维护家庭财物记录，含照片、自定义字段、购买日期与价格", "按位置、分类和标签组织物品并支持检索", "为物品保存文件与保修信息，并跟踪维护安排", "自托管 Web UI，SQLite 存储，便于备份"], "github_repository_id": 816422401, "homepage": "https://homebox.software/en/", "id": "github:816422401", "leaf_matches": [{"reason": "README 说明其为家庭用户的库存与归置系统：物品有分类、位置、标签与自定义字段，可上传图片，保存文件与保修，记录购买日期/价格和维护安排，并支持检索；记录范围是家庭自有财物，属于家庭库存应用。维护跟踪只是物品附属属性，未据此扩展为家庭维护应用。", "slug": "home-inventory-application", "source_urls": ["https://raw.githubusercontent.com/sysadminsmedia/homebox/main/README.md", "https://homebox.software/en/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/sysadminsmedia/homebox/license", "name": "HomeBox", "repository_url": "https://github.com/sysadminsmedia/homebox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:39:18.811640+08:00", "kind": "repository_metadata", "sha256": "38c97a1e160fb8b5a51b02ff9def4fb5c308a821eea64462dde89be83fdeeed3", "snapshot_path": "sources/38c97a1e160fb8b5a51b02ff9def4fb5c308a821eea64462dde89be83fdeeed3.txt", "url": "https://api.github.com/repos/sysadminsmedia/homebox"}, {"fetched_at": "2026-10-27T02:39:19.898729+08:00", "kind": "readme", "sha256": "eb3f4dc03dc36e3f8f08a31394db063ff5fc3c2bdeb9f18d2fdec030303e9b70", "snapshot_path": "sources/eb3f4dc03dc36e3f8f08a31394db063ff5fc3c2bdeb9f18d2fdec030303e9b70.txt", "url": "https://raw.githubusercontent.com/sysadminsmedia/homebox/main/README.md"}, {"fetched_at": "2026-10-27T02:39:21.449192+08:00", "kind": "license", "sha256": "fbaa9cbdd88b3836f4baf1fa94e6d98dca8ac9c6d9c04781bdfb2fffe79bbd6e", "snapshot_path": "sources/fbaa9cbdd88b3836f4baf1fa94e6d98dca8ac9c6d9c04781bdfb2fffe79bbd6e.txt", "url": "https://api.github.com/repos/sysadminsmedia/homebox/license"}, {"fetched_at": "2026-10-27T02:40:47.454685+08:00", "kind": "homepage", "sha256": "3d79ba1e15e1faf6ee7bfe0496c002be7769b34339c99a22952f5c99c437c1e1", "snapshot_path": "sources/3d79ba1e15e1faf6ee7bfe0496c002be7769b34339c99a22952f5c99c437c1e1.txt", "url": "https://homebox.software/en/"}], "summary": "面向家庭用户的自托管物品清单与归置系统：以物品记录为核心，按位置、分类和标签组织，附照片、文件、保修、购买信息与维护安排。", "technology_stack": ["Go", "SQLite", "Docker", "内嵌 Web UI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:886309718','HomeLogger','{"deployment": ["官方 Docker Compose 单容器部署（推荐方式）", "Go 服务 + React SPA，SQLite 默认，可选 PostgreSQL"], "features": ["为住宅家电等资产建立记录并保存维修/维护历史", "维护任务支持到期日、预计费用和重复周期，完成后推进下一到期日", "完成任务可生成维护或维修记录，并附收据/照片", "自托管 Web 应用，可选 SQLite 或 PostgreSQL"], "github_repository_id": 886309718, "homepage": "https://github.com/FrancisLaboratories/homelogger", "id": "github:886309718", "leaf_matches": [{"reason": "README 自述为房主的家庭维护与资产跟踪，集中家电、维修和维护任务并记录工作、收据与计划；官方 OpenAPI 的 Task 模型含 dueDate、isRecurring、recurrenceInterval/Unit/Mode、lastCompletedAt 与 applianceId，完成任务生成 maintenance/repair 记录，构成以住宅设备为对象的周期维护计划与完成历史。", "slug": "home-maintenance-application", "source_urls": ["https://raw.githubusercontent.com/FrancisLaboratories/homelogger/main/README.md", "https://raw.githubusercontent.com/FrancisLaboratories/homelogger/main/server/openapi.yaml"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/FrancisLaboratories/homelogger/license", "name": "HomeLogger", "repository_url": "https://github.com/FrancisLaboratories/homelogger", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:40:49.081300+08:00", "kind": "repository_metadata", "sha256": "7dd05e2117673196543443c25c1886462b76f8f8aea8d6312ab8f1a477f604ca", "snapshot_path": "sources/7dd05e2117673196543443c25c1886462b76f8f8aea8d6312ab8f1a477f604ca.txt", "url": "https://api.github.com/repos/FrancisLaboratories/homelogger"}, {"fetched_at": "2026-10-27T02:39:25.112372+08:00", "kind": "readme", "sha256": "30070721757e28d308be3ea560bf1cd41942a464b00d3fbf1b991eb5fbefa5be", "snapshot_path": "sources/30070721757e28d308be3ea560bf1cd41942a464b00d3fbf1b991eb5fbefa5be.txt", "url": "https://raw.githubusercontent.com/FrancisLaboratories/homelogger/main/README.md"}, {"fetched_at": "2026-10-27T02:39:26.572558+08:00", "kind": "license", "sha256": "95698cfe1cce6ffaf6b1a5123753ee6a32e0b39dbf8e1c30ace4c4c17398e7d9", "snapshot_path": "sources/95698cfe1cce6ffaf6b1a5123753ee6a32e0b39dbf8e1c30ace4c4c17398e7d9.txt", "url": "https://api.github.com/repos/FrancisLaboratories/homelogger/license"}, {"fetched_at": "2026-10-27T02:41:08.000055+08:00", "kind": "documentation", "sha256": "eea02ef78802c5629c06da0432575bd687d199b7fba4d8066f25570a0a8f84a7", "snapshot_path": "sources/eea02ef78802c5629c06da0432575bd687d199b7fba4d8066f25570a0a8f84a7.txt", "url": "https://raw.githubusercontent.com/FrancisLaboratories/homelogger/main/server/openapi.yaml"}], "summary": "面向房主的自托管家居维护与设备台账（项目自述仍处 0.x 早期）：集中记录家电、维修与维护任务，任务可设重复周期、到期日和预计费用，并保留完成历史与收据。", "technology_stack": ["Go", "Fiber", "GORM", "React", "SQLite", "PostgreSQL", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:simplisafe','SimpliSafe','{"homepage": "https://simplisafe.com/", "id": "commercial:simplisafe", "leaf_matches": [{"reason": "官方监测页可读正文明确系统在 armed 状态下触发检测，App 可布防/撤防、确认/取消警报，监测中心联系用户并在无法联系时请求警察/消防/医疗调度，支持电话安全词取消，覆盖场所安防系统、布防姿态和报警响应路径。", "slug": "home-security-application", "source_urls": ["https://simplisafe.com/features-alarm-monitoring", "https://simplisafe.com/"]}], "name": "SimpliSafe", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:39:49.727139+08:00", "kind": "homepage", "sha256": "09d1f4889cf6f69f0713d2c4eb354c8ab712807b39fd19e74cdcabb4b7467caa", "snapshot_path": "sources/09d1f4889cf6f69f0713d2c4eb354c8ab712807b39fd19e74cdcabb4b7467caa.txt", "url": "https://simplisafe.com/"}, {"fetched_at": "2026-10-27T02:50:18.458546+08:00", "kind": "documentation", "sha256": "6e201d483f4a4e5c1cecd3e294829a8053db15514031cc6493bf8e66d23065c4", "snapshot_path": "sources/6e201d483f4a4e5c1cecd3e294829a8053db15514031cc6493bf8e66d23065c4.txt", "url": "https://simplisafe.com/features-alarm-monitoring"}, {"fetched_at": "2026-10-27T02:40:03.268115+08:00", "kind": "documentation", "sha256": "abc79435bd5ad472e02af50c2ace278803c05100c1591ee001d7bef76046ecc0", "snapshot_path": "sources/abc79435bd5ad472e02af50c2ace278803c05100c1591ee001d7bef76046ecc0.txt", "url": "https://simplisafe.com/features-alarm-monitoring"}], "summary": "面向住宅的安防系统与 24/7 专业监控服务：家庭通过 App 对系统布防/撤防、确认或取消警报；警报触发后监测代理联系用户，核实情况并请求警察、消防或医疗调度，支持电话安全词取消。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1158973286','TidyQuest','{"deployment": ["Docker Compose 自托管", "Unraid Community Applications"], "features": ["按房间组织家务任务", "1–365 天自定义频率与到期日历", "完成记录、连续天数、积分和家庭排行榜", "成员分配（First/Shared/Custom）", "管理员审批（Strict Mode）", "Docker Compose 自托管"], "github_repository_id": 1158973286, "homepage": "https://github.com/mellow-fox/TidyQuest", "id": "github:1158973286", "leaf_matches": [{"reason": "TidyQuest 以家务为产品中心：任务有自定义重复频率和到期日历，完成会推进状态并计入连续天数/积分；成员分配与家长审批覆盖家庭协作，符合家务应用的待办-完成循环。", "slug": "household-chore-application", "source_urls": ["https://raw.githubusercontent.com/mellow-fox/TidyQuest/main/README.md", "https://api.github.com/repos/mellow-fox/TidyQuest"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/mellow-fox/TidyQuest/license", "name": "TidyQuest", "repository_url": "https://github.com/mellow-fox/TidyQuest", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:40:50.790138+08:00", "kind": "repository_metadata", "sha256": "18ba0a4f2cf706f4b9bb17eec0c7b8ac042a80cef25f5b81673451f32f0c11e8", "snapshot_path": "sources/18ba0a4f2cf706f4b9bb17eec0c7b8ac042a80cef25f5b81673451f32f0c11e8.txt", "url": "https://api.github.com/repos/mellow-fox/TidyQuest"}, {"fetched_at": "2026-10-27T02:41:03.716650+08:00", "kind": "license", "sha256": "caa7a8c5cb56a1ed2c08bfb0b1d16f737fa676a25679147795aae78f9fd2ce5c", "snapshot_path": "sources/caa7a8c5cb56a1ed2c08bfb0b1d16f737fa676a25679147795aae78f9fd2ce5c.txt", "url": "https://api.github.com/repos/mellow-fox/TidyQuest/license"}, {"fetched_at": "2026-10-27T02:40:50.551452+08:00", "kind": "readme", "sha256": "dda670ea8e06f300454d1508350ac6b868890dbb7444c91c1595d19ebb6a31cf", "snapshot_path": "sources/dda670ea8e06f300454d1508350ac6b868890dbb7444c91c1595d19ebb6a31cf.txt", "url": "https://raw.githubusercontent.com/mellow-fox/TidyQuest/main/README.md"}], "summary": "自托管家务管理 Web 应用：按房间组织家务，任务带 1–365 天自定义频率、到期日历与随时间衰减的完成状态，记录完成并支持连续天数、积分、家庭排行榜、成员分配和管理员审批。README 自述为早期阶段项目（0.6.0）。", "technology_stack": ["TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:care-com-homepay','Care.com HomePay','{"homepage": "https://www.care.com/homepay", "id": "commercial:care-com-homepay", "leaf_matches": [{"reason": "HomePay 是雇主侧、以薪资/税务记录为中心的家庭雇佣行政服务：把保姆/管家/居家护理人员登记为雇员并记录工资率，运行发薪、代扣代缴、申报、直接存款和工资/年终税表记录；属于家庭雇主制度下的雇佣管理。页面未展示职责、工时、休假或合同档案管理，故不主张完整 HR 闭环。", "slug": "household-staff-management", "source_urls": ["https://www.care.com/homepay"]}], "name": "Care.com HomePay", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:50:15.694593+08:00", "kind": "homepage", "sha256": "3c9d268f6a20fffd41ea8063d5b411098740262e6fa851b98194b2e4488e8401", "snapshot_path": "sources/3c9d268f6a20fffd41ea8063d5b411098740262e6fa851b98194b2e4488e8401.txt", "url": "https://www.care.com/homepay"}, {"fetched_at": "2026-10-27T02:39:24.133794+08:00", "kind": "homepage", "sha256": "ae26deec8db58b1801dff16e8ee3a59d3b3f94a0a8478361729f537fafa22dd7", "snapshot_path": "sources/ae26deec8db58b1801dff16e8ee3a59d3b3f94a0a8478361729f537fafa22dd7.txt", "url": "https://www.care.com/homepay"}], "summary": "面向家庭雇主的保姆、管家和居家护理人员薪资与税务服务：登记雇员与工资率，处理发薪、代扣代缴与税务申报，提供直接存款、工资记录和年终税表，并声明税务申报准确、按时提交的服务保证。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:107898477','Baby Buddy','{"deployment": ["Docker（LinuxServer.io 镜像）", "自托管服务器（官方 Manual/Cloud 部署指南）"], "features": ["多儿童档案", "喂食、睡眠、尿布、趴卧等照护事件记录", "照护计时器", "体温、体重等测量记录", "仪表盘与按儿童时间线历史", "Docker 自托管"], "github_repository_id": 107898477, "homepage": "https://docs.baby-buddy.net/", "id": "github:107898477", "leaf_matches": [{"reason": "Baby Buddy 为每个儿童保存照护事件：官方文档逐项说明可按儿童添加/修改尿布、喂食、睡眠、趴卧和体温/体重条目，并提供计时器；Getting Started 文档说明 Dashboard 汇总最近喂食/尿布/睡眠等状态，Timeline 列出儿童随时间累积的活动记录并可编辑，符合儿童档案、照护者代记、时间戳历史和累积查阅。", "slug": "parenting-baby-tracking-application", "source_urls": ["https://docs.baby-buddy.net/user-guide/adding-entries/", "https://raw.githubusercontent.com/babybuddy/babybuddy/master/README.md", "https://docs.baby-buddy.net/user-guide/getting-started/"]}], "license": "BSD-2-Clause", "license_evidence_url": "https://api.github.com/repos/babybuddy/babybuddy/license", "name": "Baby Buddy", "repository_url": "https://github.com/babybuddy/babybuddy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:38:34.257170+08:00", "kind": "repository_metadata", "sha256": "24a4aad6ca5c37be258b5ef165c12975568da877286f5efd6599663f92d91fb9", "snapshot_path": "sources/24a4aad6ca5c37be258b5ef165c12975568da877286f5efd6599663f92d91fb9.txt", "url": "https://api.github.com/repos/babybuddy/babybuddy"}, {"fetched_at": "2026-10-27T02:38:43.554152+08:00", "kind": "license", "sha256": "ae37902b9ee97e172db82b44f4c1f12976452102fa87af87ebd3a8a3d65961aa", "snapshot_path": "sources/ae37902b9ee97e172db82b44f4c1f12976452102fa87af87ebd3a8a3d65961aa.txt", "url": "https://api.github.com/repos/babybuddy/babybuddy/license"}, {"fetched_at": "2026-10-27T02:38:43.580653+08:00", "kind": "readme", "sha256": "c3c5245908b1d964a22faeb4cb720b2a3d6536b5d7cff187e359cc968a5144cb", "snapshot_path": "sources/c3c5245908b1d964a22faeb4cb720b2a3d6536b5d7cff187e359cc968a5144cb.txt", "url": "https://raw.githubusercontent.com/babybuddy/babybuddy/master/README.md"}, {"fetched_at