INSERT INTO "application" VALUES('commercial:sawyer','Sawyer','{"homepage": "https://www.hisawyer.com/for-business", "id": "commercial:sawyer", "leaf_matches": [{"reason": "官方课后项目页与自动名册页说明可建课程、学期、单次活动与多日选择，家长为儿童报名并保存过敏与接送信息，按活动自动生成名册，支持考勤、候补、转班和付款；对应项目目录→家长报名→名册/考勤。", "slug": "after-school-program-management", "source_urls": ["https://www.hisawyer.com/for-business/businesses/after-school", "https://www.hisawyer.com/for-business/features/automated-rosters"]}], "name": "Sawyer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:44:14.304705+08:00", "kind": "documentation", "sha256": "37cc6b91ccd98b4218d1c8f1940d592af893b9e90b2bb62098b5885068038e9c", "snapshot_path": "sources/37cc6b91ccd98b4218d1c8f1940d592af893b9e90b2bb62098b5885068038e9c.txt", "url": "https://www.hisawyer.com/for-business/businesses/after-school"}, {"fetched_at": "2026-10-27T02:44:16.240673+08:00", "kind": "documentation", "sha256": "acd12e61368beaa1e88a2186f5ce14d01948210590c6df146e925b7bcaf39d22", "snapshot_path": "sources/acd12e61368beaa1e88a2186f5ce14d01948210590c6df146e925b7bcaf39d22.txt", "url": "https://www.hisawyer.com/for-business/features/automated-rosters"}], "summary": "Sawyer 是面向儿童课外活动与课后项目运营方的商业报名和运营平台，提供项目排期、家长报名、自动名册、候补、考勤与付款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
