INSERT INTO "application" VALUES('github:73817618','Animal Shelter Manager (ASM3)','{"deployment": ["Linux/Unix 自托管，提供 Debian/Ubuntu 包与源码包", "Apache/WSGI 运行 Python 应用，可连接 MySQL、PostgreSQL 或 SQLite"], "features": ["动物个体记录，含名称/代码、品种、微芯片、地点与状态", "入所与领养、转出、归还、寄养等移动记录，同一动物仅一个未归还移动", "疫苗、检测、医疗、日誌、费用与死亡记录", "人员、领养人、寄养人与工作人员记录", "报告、文档模板与网站/第三方领养平台发布"], "github_repository_id": 73817618, "homepage": "https://sheltermanager.com/", "id": "github:73817618", "leaf_matches": [{"reason": "官方文档与 README 说明每只动物有独立记录，入所后记录地点/单位与状态，离所需 movement（领养、转出、归还、寄养等）且同一时间仅一个未归还移动，死亡在动物记录中处理；另有疫苗、检测、医疗、日誌与人员记录，对应动物记录→入所/在护/结果生命周期及护理事件。", "slug": "animal-shelter-management", "source_urls": ["https://raw.githubusercontent.com/sheltermanager/asm3/master/README.md", "https://sheltermanager.com/repo/asm3_help/animals.html", "https://sheltermanager.com/repo/asm3_help/movements.html"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/sheltermanager/asm3/license", "name": "Animal Shelter Manager (ASM3)", "repository_url": "https://github.com/sheltermanager/asm3", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:43:52.097823+08:00", "kind": "repository_metadata", "sha256": "36cdbcdb3758a50cca15ebb49906b289ac5947b458857d35aceaa63213da07f1", "snapshot_path": "sources/36cdbcdb3758a50cca15ebb49906b289ac5947b458857d35aceaa63213da07f1.txt", "url": "https://api.github.com/repos/sheltermanager/asm3"}, {"fetched_at": "2026-10-27T02:43:53.925317+08:00", "kind": "license", "sha256": "07f600915d4101c6758317e686e546a45188249ce74d7de550d9f4ae47b69c55", "snapshot_path": "sources/07f600915d4101c6758317e686e546a45188249ce74d7de550d9f4ae47b69c55.txt", "url": "https://api.github.com/repos/sheltermanager/asm3/license"}, {"fetched_at": "2026-10-27T02:43:55.331760+08:00", "kind": "readme", "sha256": "49834e16825c53a117ef81d9e730d474ec1e64331972b2805c71cd12b0df0a85", "snapshot_path": "sources/49834e16825c53a117ef81d9e730d474ec1e64331972b2805c71cd12b0df0a85.txt", "url": "https://raw.githubusercontent.com/sheltermanager/asm3/master/README.md"}, {"fetched_at": "2026-10-27T02:43:57.263164+08:00", "kind": "documentation", "sha256": "f16ddca93f1f053904ef46139cf697353f09ee93fc4f0fb66e20b41f7e820338", "snapshot_path": "sources/f16ddca93f1f053904ef46139cf697353f09ee93fc4f0fb66e20b41f7e820338.txt", "url": "https://sheltermanager.com/repo/asm3_help/animals.html"}, {"fetched_at": "2026-10-27T02:43:58.947877+08:00", "kind": "documentation", "sha256": "f0c33b5a39d67ae4b44a394cbf253ec59c2f503ea448ad3a0028381936d7a937", "snapshot_path": "sources/f0c33b5a39d67ae4b44a394cbf253ec59c2f503ea448ad3a0028381936d7a937.txt", "url": "https://sheltermanager.com/repo/asm3_help/movements.html"}], "summary": "Animal Shelter Manager (ASM3) 是 GPL-3.0 的动物收容所管理应用，围绕动物个体记录、入所/在护/结果的移动记录、医疗与人员记录及报告发布运行。", "technology_stack": ["Python 3", "HTML5", "Apache/WSGI", "MySQL/PostgreSQL/SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:plotbox','PlotBox','{"homepage": "https://plotbox.com/", "id": "commercial:plotbox", "leaf_matches": [{"reason": "官方火葬场软件页列出火化预约日历、火化授权表/合同/许可文件的上传归档、火化报告以及 Stored Remains Report，覆盖火化登记、授权文件与骨灰存放追踪这一核心结构。", "slug": "crematory-management", "source_urls": ["https://plotbox.com/crematory-software"]}], "name": "PlotBox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:51:25.822445+08:00", "kind": "documentation", "sha256": "b2949111ed284735b7e851373afea3b6db2d1e63084510226c3027ce0531221a", "snapshot_path": "sources/b2949111ed284735b7e851373afea3b6db2d1e63084510226c3027ce0531221a.txt", "url": "https://plotbox.com/crematory-software"}], "summary": "面向墓地、火葬场和殡仪馆运营方的商业管理平台；火葬场模块提供火化预约日历、火化授权书/合同/许可文件归档、火化记录与骨灰报告、殡仪馆门户、财务和工单管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pet-fbi','Pet FBI','{"homepage": "https://petfbi.org/", "id": "commercial:pet-fbi", "leaf_matches": [{"reason": "官网说明可报告走失或发现的宠物、进入全国数据库、收到潜在匹配报告提醒，并可在宠物回家或被发现宠物团聚后编辑报告，覆盖失主报告、发现侧和团聚闭环。", "slug": "lost-pet-platform", "source_urls": ["https://petfbi.org/"]}], "name": "Pet FBI", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:51:27.562166+08:00", "kind": "homepage", "sha256": "228ebf4517331d0e7be66df34307391d0bdfcff5bfc7d86a5ef4e651501f7472", "snapshot_path": "sources/228ebf4517331d0e7be66df34307391d0bdfcff5bfc7d86a5ef4e651501f7472.txt", "url": "https://petfbi.org/"}], "summary": "非营利的失踪与发现宠物全国数据库；失主和发现者可提交报告，按地点和描述检索潜在匹配并接收提醒，团聚后可更新或关闭报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:kennel-connection','Kennel Connection','{"homepage": "https://kennelconnection.com/", "id": "commercial:kennel-connection", "leaf_matches": [{"reason": "官方寄养软件页明确面向 boarding facilities 和 kennels，描述预约管理、可自定义的 run 设置与节假日拆分/转移、押金及账单一体化，匹配寄养入住、容量占用和按次计费核心。", "slug": "pet-boarding-management", "source_urls": ["https://kennelconnection.com/boarding-kennel-software/"]}], "name": "Kennel Connection", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:51:34.324612+08:00", "kind": "documentation", "sha256": "682ccf1ed25fcf73edce56bbda61f74b33f35fb87f060bdd8163ae59b1784545", "snapshot_path": "sources/682ccf1ed25fcf73edce56bbda61f74b33f35fb87f060bdd8163ae59b1784545.txt", "url": "https://kennelconnection.com/boarding-kennel-software/"}], "summary": "面向犬舍和宠物寄养设施的商业管理软件，集成寄养预约、跑笼/房间设置与转移、在线预订、押金、客户沟通和账单。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gingr','Gingr','{"homepage": "https://www.gingrapp.com/", "id": "commercial:gingr", "leaf_matches": [{"reason": "官网写明 boarding、daycare、grooming、training 位于同一系统，预约页提供跨服务排期与容量上限、套餐/押金和支付，匹配多服务线共享排期与同一客户门户内的结算。", "slug": "pet-care-business-management", "source_urls": ["https://www.gingrapp.com/pet-scheduling-software", "https://www.gingrapp.com/"]}, {"reason": "官方训练软件页明确“built for classes and private lessons”，正文列出 group classes、group enrollments、instructor scheduling、payments、progress notes、custom pet profiles 与自动提醒；覆盖已排期课程→注册→收费的训练管理核心。", "slug": "pet-training-management", "source_urls": ["https://www.gingrapp.com/dog-training-software", "https://www.gingrapp.com/"]}], "name": "Gingr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:51:36.082420+08:00", "kind": "documentation", "sha256": "16c8d1d4a5e9080541542d992eb1f7ed6f6c06b9ffc6f64e837f1fbd4794ff34", "snapshot_path": "sources/16c8d1d4a5e9080541542d992eb1f7ed6f6c06b9ffc6f64e837f1fbd4794ff34.txt", "url": "https://www.gingrapp.com/pet-scheduling-software"}, {"fetched_at": "2026-10-27T02:52:34.918982+08:00", "kind": "homepage", "sha256": "1b601faf77eaf403f69f6c24597f916c7586e1558263d22d2b530a6c3f8551f5", "snapshot_path": "sources/1b601faf77eaf403f69f6c24597f916c7586e1558263d22d2b530a6c3f8551f5.txt", "url": "https://www.gingrapp.com/"}, {"fetched_at": "2026-10-27T02:58:13.576798+08:00", "kind": "documentation", "sha256": "3c480684257a348cf7fb455e128b1a6f44c062ace482cae5e3e9aba7a92cc426", "snapshot_path": "sources/3c480684257a348cf7fb455e128b1a6f44c062ace482cae5e3e9aba7a92cc426.txt", "url": "https://www.gingrapp.com/dog-training-software"}], "summary": "宠物护理业务一体化管理平台，在同一系统中提供寄养、日托、美容和训练预约，含容量管理、客户自助门户、套餐/押金和支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:doggiedashboard','DoggieDashboard','{"homepage": "https://doggiedashboard.com/", "id": "commercial:doggiedashboard", "leaf_matches": [{"reason": "官方功能页展示犬舍/run 占用日历、预约与循环预约、宠物签到、疫苗到期记录和按客户开票，产品定位包含 dog daycare，覆盖日托出勤、容量占用与开票收款。", "slug": "pet-daycare-management", "source_urls": ["https://blog.doggiedashboard.com/features"]}], "name": "DoggieDashboard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:52:13.105573+08:00", "kind": "documentation", "sha256": "9b48d809c854c5d7f681b06c0090c2c066e66b3e98e195c48184061404f0a10b", "snapshot_path": "sources/9b48d809c854c5d7f681b06c0090c2c066e66b3e98e195c48184061404f0a10b.txt", "url": "https://blog.doggiedashboard.com/features"}], "summary": "面向宠物日托、犬舍、美容和寄养业务的云端管理软件，提供客户/宠物档案、疫苗到期记录、犬舍占用日历、预约与循环预约、签到、开票和收款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:moego','MoeGo','{"homepage": "https://www.moego.pet/", "id": "commercial:moego", "leaf_matches": [{"reason": "官方美容软件页（https://www.moego.pet/pet-grooming-software）正文明确：预约系统可设置 time slots、限制每时段/每日宠物数、按品种/体型/服务设预约规则，日历显示实时可用性并给出冲突提示；服务菜单可按品种、体型、体重、被毛类型和附加项建立价格模板；客户档案可含无限宠物、被毛状况备注、上次美容日期及疫苗/用药/过敏提醒；并提供 deposits、saved cards 与一体化 POS 结账。官方员工管理页（https://www.moego.pet/grooming-software-staff-management）另述按 groomer 产能与节奏排班、multi-pet bookings、breed-aware profiles 和 grooming reports。两页共同覆盖『宠物×服务×美容师时段→按预约收款』。", "slug": "pet-grooming-management", "source_urls": ["https://www.moego.pet/pet-grooming-software", "https://www.moego.pet/grooming-software-staff-management"]}], "name": "MoeGo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:57:35.683827+08:00", "kind": "documentation", "sha256": "a7471937c3eb41eff2361218066e4beb5f094acabd4c34a252a52e0c76941ca4", "snapshot_path": "sources/a7471937c3eb41eff2361218066e4beb5f094acabd4c34a252a52e0c76941ca4.txt", "url": "https://www.moego.pet/pet-grooming-software"}, {"fetched_at": "2026-10-27T03:04:49.666753+08:00", "kind": "documentation", "sha256": "b6bbb70a326118c20a097396e49af8d5f4e0659f6fc159554c01bdba628bf357", "snapshot_path": "sources/b6bbb70a326118c20a097396e49af8d5f4e0659f6fc159554c01bdba628bf357.txt", "url": "https://www.moego.pet/grooming-software-staff-management"}], "summary": "面向宠物美容沙龙与移动美容团队的商业管理软件：按美容师产能与节奏安排班次和预约时段，日历显示实时可用性并提示冲突；客户可挂多只宠物，档案含 breed-aware 资料、被毛状况、上次美容日期及疫苗/用药/过敏提醒；服务菜单可按品种、体型、体重、被毛类型和附加项配置价格；并提供押金、存卡、一体化 POS 结账与美容报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1297966006','Furlo','{"deployment": ["Flutter 应用（iOS/Android/Web）", "Firebase Authentication + Cloud Firestore 账户与云同步", "需自建 Firebase 项目并部署 Firestore 规则"], "features": ["多宠物档案（物种、品种、出生日期、照片）", "健康记录（体检、用药、疾病/受伤、手术、化验等）", "疫苗到期状态与接种时间线", "体重记录与趋势图、喂食计划提醒", "兽医联系人、下次就诊与 PDF 护理摘要导出"], "github_repository_id": 1297966006, "homepage": "https://github.com/TachiBae/Furlo", "id": "github:1297966006", "leaf_matches": [{"reason": "README 的已实现功能列出宠物档案、疫苗到期与接种时间线、健康记录、体重/喂食提醒、兽医联系人和护理摘要导出；账户数据存放在 Cloud Firestore，形成照料者持有的纵向健康记录与到期护理循环。", "slug": "pet-health-application", "source_urls": ["https://raw.githubusercontent.com/TachiBae/Furlo/main/README.md", "https://github.com/TachiBae/Furlo"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/TachiBae/Furlo/main/LICENSE", "license_review": {"rationale": "仓库根 LICENSE 为完整 MIT 许可证文本，含 Permission is hereby granted, free of charge 与免责声明；README 未标注其他许可限制。", "reviewer": "unit-267 collector (opencode-go/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/TachiBae/Furlo/main/LICENSE", "spdx_id": "MIT"}, "name": "Furlo", "repository_url": "https://github.com/TachiBae/Furlo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:56:28.470212+08:00", "kind": "repository_metadata", "sha256": "2dabf78265cd6b39811f82c6df59e23d18bf66285a96eac78b264cb429d64f88", "snapshot_path": "sources/2dabf78265cd6b39811f82c6df59e23d18bf66285a96eac78b264cb429d64f88.txt", "url": "https://github.com/TachiBae/Furlo"}, {"fetched_at": "2026-10-27T02:56:29.726472+08:00", "kind": "license", "sha256": "9f979a384d7c5ecfcf23b416a2054a1447788c18f4ed078147961d084b0dafee", "snapshot_path": "sources/9f979a384d7c5ecfcf23b416a2054a1447788c18f4ed078147961d084b0dafee.txt", "url": "https://raw.githubusercontent.com/TachiBae/Furlo/main/LICENSE"}, {"fetched_at": "2026-10-27T02:56:30.906745+08:00", "kind": "readme", "sha256": "25c76617f794e9da2390d74cc677315c2686291731e12d61bdebad6599f1e411", "snapshot_path": "sources/25c76617f794e9da2390d74cc677315c2686291731e12d61bdebad6599f1e411.txt", "url": "https://raw.githubusercontent.com/TachiBae/Furlo/main/README.md"}], "summary": "开源的宠物健康记录应用：Flutter 客户端配合 Firebase 账户与 Cloud Firestore 云同步，以宠物档案为核心维护疫苗、健康记录、体重、喂食提醒和兽医联系人，并导出护理摘要。", "technology_stack": ["Flutter / Dart", "Firebase Auth、Cloud Firestore", "provider、fl_chart、flutter_local_notifications"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lemonade-pet','Lemonade Pet','{"homepage": "https://www.lemonade.com/pet", "id": "commercial:lemonade-pet", "leaf_matches": [{"reason": "官方宠物保险页说明保单、等待期、免赔额/共保及按报销制在 App 内提交理赔；官方理赔页说明在 App 内点 File a Claim、AI/人工审核并在通过后付款。三者共同构成保单→兽医账单理赔→资金结果的客户应用核心。", "slug": "pet-insurance-customer-app", "source_urls": ["https://www.lemonade.com/pet", "https://www.lemonade.com/claims"]}], "name": "Lemonade Pet", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:56:35.519865+08:00", "kind": "homepage", "sha256": "6b2827625984b0acdafd9f8fa6493b2f4ddd1fac6e3f1adcafd1ba21f80b8e0f", "snapshot_path": "sources/6b2827625984b0acdafd9f8fa6493b2f4ddd1fac6e3f1adcafd1ba21f80b8e0f.txt", "url": "https://www.lemonade.com/pet"}, {"fetched_at": "2026-10-27T02:56:37.205041+08:00", "kind": "documentation", "sha256": "8677e683c89eb93aadc0708639b6e4ee991f1c7828a2b6b04e86b29d062ae96d", "snapshot_path": "sources/8677e683c89eb93aadc0708639b6e4ee991f1c7828a2b6b04e86b29d062ae96d.txt", "url": "https://www.lemonade.com/claims"}], "summary": "Lemonade 的宠物保险客户应用/账户：投保人查看宠物保单与保障条款，在 App 内针对兽医账单提交理赔，并跟踪审核、赔付到银行账户的结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1185503465','OpenVPM','{"deployment": ["Docker Compose 自托管（PostgreSQL 16 + MinIO）", "Vercel 云托管", "pnpm/Turborepo 单仓构建，含数据库迁移脚本"], "features": ["客户（业主）账户与多宠物患者档案", "按医生/诊室排班的预约及到诊/就诊/结账状态流", "SOAP 病历、问题列表、疫苗、化验、处方与附件", "服务/产品目录、估价转发票、付款与账户余额", "库存、受控药品、报表与客户门户"], "github_repository_id": 1185503465, "homepage": "https://openvpm.com", "id": "github:1185503465", "leaf_matches": [{"reason": "README 的已实现功能列出客户/患者档案、按医生排班的预约、SOAP 电子病历、服务目录与估价/发票/收款、客户门户，覆盖兽医执业管理临床记录与客户账户计费两条核心链路；并给出 Docker Compose 自托管方式。", "slug": "veterinary-practice-management", "source_urls": ["https://raw.githubusercontent.com/evangauer/openvpm/main/README.md", "https://github.com/evangauer/openvpm"]}], "license": "AGPL-3.0-only", "license_evidence_url": "https://raw.githubusercontent.com/evangauer/openvpm/main/LICENSE", "license_review": {"rationale": "仓库根 LICENSE 为完整 GNU Affero General Public License v3 文本，含版本 3 与 TERMS AND CONDITIONS；README 徽章与 License 段落均标 AGPLv3 / GNU AGPLv3，未声明“or later”，故按 AGPL-3.0-only 记录。", "reviewer": "unit-267 collector (opencode-go/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/evangauer/openvpm/main/LICENSE", "spdx_id": "AGPL-3.0-only"}, "name": "OpenVPM", "repository_url": "https://github.com/evangauer/openvpm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:56:28.666198+08:00", "kind": "repository_metadata", "sha256": "0f1cc4154d51de7b3c702f57bab9db81a58d55d16dcd215b99ce42ea8c23a178", "snapshot_path": "sources/0f1cc4154d51de7b3c702f57bab9db81a58d55d16dcd215b99ce42ea8c23a178.txt", "url": "https://github.com/evangauer/openvpm"}, {"fetched_at": "2026-10-27T02:56:30.181616+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/evangauer/openvpm/main/LICENSE"}, {"fetched_at": "2026-