INSERT INTO "application" VALUES('commercial:ember-software','Ember Software','{"homepage": "https://www.embersoftware.com/", "id": "commercial:ember-software", "leaf_matches": [{"reason": "消防检查承包商专用：官方首页明确覆盖受检资产、现场数字检查、检查转提案、排程、开票与 AHJ 提交，与定期检查→缺陷→纠正工作→计费的核心链条一致。", "slug": "fire-protection-service-management", "source_urls": ["https://www.embersoftware.com/"]}], "name": "Ember Software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:00:16.994840+08:00", "kind": "homepage", "sha256": "b3c97bc2ce44a35fa05a3b5bbd4e42bfa35893f42593b501484371ac152e4ac7", "snapshot_path": "sources/b3c97bc2ce44a35fa05a3b5bbd4e42bfa35893f42593b501484371ac152e4ac7.txt", "url": "https://www.embersoftware.com/"}], "summary": "面向消防检查承包商的业务平台：数字检查表与资产清单、排班派工、将检查转为提案、开票收款及 AHJ 报告提交。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1112392243','Subfloor','{"deployment": ["Docker Compose 运行应用与 PostgreSQL", "通过 .env 配置数据库和 SuperTokens", "使用预构建 ghcr.io 镜像"], "features": ["客户、线索与项目历史管理", "地板作业状态流转（New→Quoting→Scheduled→Completed）", "报价、变更单与采购单管理", "按颜色/尺寸/表面变体及箱/平方英尺包装管理库存", "样品借出、逾期跟踪与 QR 码扫描", "安装、测量与个人预约统一日历及 iCal 同步", "客户邮件提醒与安装人员每日清单"], "github_repository_id": 1112392243, "homepage": "https://subfloor.app", "id": "github:1112392243", "leaf_matches": [{"reason": "地板业务专用的作业与材料管理：README 记载客户→报价→排程→完成的地板作业流程、按规格与包装的库存、样品借出、变更单/采购单和安装日历；未文档化房间测量/面积算量，故关系限定在已证实的作业、材料与排程范围。", "slug": "flooring-contractor-management", "source_urls": ["https://raw.githubusercontent.com/adampdxdotcom/subfloor/main/README.md", "https://github.com/adampdxdotcom/subfloor"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/adampdxdotcom/subfloor/main/LICENSE", "license_review": {"rationale": "已读取仓库根目录完整 MIT 许可证文本，含版权、授权与免责声明，README 也声明 MIT。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/adampdxdotcom/subfloor/main/LICENSE", "spdx_id": "MIT"}, "name": "Subfloor", "repository_url": "https://github.com/adampdxdotcom/subfloor", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:58:28.921820+08:00", "kind": "repository_metadata", "sha256": "ba14d58da085f5237d0ea7b9b6c3e5dcb1595df48ab5112015b2e8fdafb5afc0", "snapshot_path": "sources/ba14d58da085f5237d0ea7b9b6c3e5dcb1595df48ab5112015b2e8fdafb5afc0.txt", "url": "https://github.com/adampdxdotcom/subfloor"}, {"fetched_at": "2026-10-27T02:58:35.648820+08:00", "kind": "license", "sha256": "f24c07992c1f02c76c121e0953f2486b088a3cb1ed7601ac8dbb987c5b65dd1f", "snapshot_path": "sources/f24c07992c1f02c76c121e0953f2486b088a3cb1ed7601ac8dbb987c5b65dd1f.txt", "url": "https://raw.githubusercontent.com/adampdxdotcom/subfloor/main/LICENSE"}, {"fetched_at": "2026-10-27T02:58:42.902689+08:00", "kind": "readme", "sha256": "29def9c479e605631a7754a63f09fbb1ba66e9ff84fbc0f16d5afdfbee52bea9", "snapshot_path": "sources/29def9c479e605631a7754a63f09fbb1ba66e9ff84fbc0f16d5afdfbee52bea9.txt", "url": "https://raw.githubusercontent.com/adampdxdotcom/subfloor/main/README.md"}], "summary": "面向小型地板承包/安装业务的自托管管理套件，围绕客户与地板作业跟踪线索、样品、报价/变更单/采购单、按规格库存、安装日历和客户通知。", "technology_stack": ["React + TypeScript + Vite", "Node.js + Express", "PostgreSQL", "Docker Compose", "Capacitor"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:team-garage-door','Team Garage Door','{"homepage": "https://teamgaragedoor.com/", "id": "commercial:team-garage-door", "leaf_matches": [{"reason": "车库门服务专用：官方首页明确按车库门公司工作流构建，覆盖客户服务工作、派工排程、估价→发票、零件与作业成本，并明确不是贴牌通用现场服务工具。", "slug": "garage-door-service-management", "source_urls": ["https://teamgaragedoor.com/"]}], "name": "Team Garage Door", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:59.594013+08:00", "kind": "homepage", "sha256": "49fcb094ddbe9183b8a8265e7d2aef2bcf1f4a5d9773f91b47d4dbf57378661c", "snapshot_path": "sources/49fcb094ddbe9183b8a8265e7d2aef2bcf1f4a5d9773f91b47d4dbf57378661c.txt", "url": "https://teamgaragedoor.com/"}], "summary": "面向车库门服务公司的派工与业务软件：派工排程、报价审批、开票收款、零件目录、工时与作业成本、客户门户和技师移动端。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1281884618','OpenFieldPro','{"deployment": ["Docker/Podman Compose + Caddy", "pnpm 安装依赖并执行数据库迁移与种子", "环境变量配置 PostgreSQL 与 Redis"], "features": ["客户、物业与设备服务历史", "工单受理、排程、派工、执行与回访", "价格表、估价、审批、发票与付款", "服务计划与周期性工作基础", "技师移动端与离线基础", "自托管安装、更新、备份与恢复"], "github_repository_id": 1281884618, "homepage": "https://github.com/niko4244/openfieldpro", "id": "github:1281884618", "leaf_matches": [{"reason": "面向小型服务企业的完整现场作业系统：客户/物业→工单派工→报价审批→执行→开票收款，并含服务计划；与杂工按客户地点、多技能小件维修、报价与完工开票的核心结构一致。", "slug": "handyman-business-management", "source_urls": ["https://raw.githubusercontent.com/niko4244/openfieldpro/ofp-monorepo/README.md", "https://github.com/niko4244/openfieldpro"]}], "license": "AGPL-3.0-only", "license_evidence_url": "https://raw.githubusercontent.com/niko4244/openfieldpro/ofp-monorepo/LICENSE", "license_review": {"rationale": "已读取仓库根目录完整 GNU Affero GPL v3 文本，许可证明确 version 3.0 only，README 声明 AGPL 核心。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/niko4244/openfieldpro/ofp-monorepo/LICENSE", "spdx_id": "AGPL-3.0-only"}, "name": "OpenFieldPro", "repository_url": "https://github.com/niko4244/openfieldpro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:58:56.213840+08:00", "kind": "repository_metadata", "sha256": "d547c5599e62003bc1caac8ced9b427c10a0dcbff5741d752535fa8d11075007", "snapshot_path": "sources/d547c5599e62003bc1caac8ced9b427c10a0dcbff5741d752535fa8d11075007.txt", "url": "https://github.com/niko4244/openfieldpro"}, {"fetched_at": "2026-10-27T02:59:36.828747+08:00", "kind": "license", "sha256": "ff58b2a3c68892c321de1fadb26af5174acf16865605a2ae3b39c5518d35e787", "snapshot_path": "sources/ff58b2a3c68892c321de1fadb26af5174acf16865605a2ae3b39c5518d35e787.txt", "url": "https://raw.githubusercontent.com/niko4244/openfieldpro/ofp-monorepo/LICENSE"}, {"fetched_at": "2026-10-27T02:59:38.245828+08:00", "kind": "readme", "sha256": "ef849b34b3959c520fe61f32ec92c0e39c21f7d4ca1764aecc5faf04d21ce4c7", "snapshot_path": "sources/ef849b34b3959c520fe61f32ec92c0e39c21f7d4ca1764aecc5faf04d21ce4c7.txt", "url": "https://raw.githubusercontent.com/niko4244/openfieldpro/ofp-monorepo/README.md"}], "summary": "面向小型现场服务企业的自托管 FSM，覆盖客户/物业、工单派工、估价与审批、开票收款、服务计划与技师移动端；可作为杂工多技能小件维修业务的管理系统。", "technology_stack": ["Fastify 5 + TypeScript", "Next.js 15", "React Native (Expo)", "PostgreSQL 16 + PostGIS", "Redis + BullMQ"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:improveit-360','Improveit 360','{"homepage": "https://www.improveit360.com/", "id": "commercial:improveit-360", "leaf_matches": [{"reason": "家装/改装承包商专用：官方首页覆盖房主线索、预约、报价销售、项目与模板任务、付款与融资，对应销售→住宅项目→生产计划→付款的核心结构；未进一步核对定金/进度款细节。", "slug": "home-improvement-contractor-management", "source_urls": ["https://www.improveit360.com/"]}], "name": "Improveit 360", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:00:01.396175+08:00", "kind": "homepage", "sha256": "7433ac57abd9d7cac5b23e2db169fedd42b1b3c8b5df422d7468c57134b6f160", "snapshot_path": "sources/7433ac57abd9d7cac5b23e2db169fedd42b1b3c8b5df422d7468c57134b6f160.txt", "url": "https://www.improveit360.com/"}], "summary": "面向改装与家装承包商的 CRM 与项目运营平台：线索与预约、报价销售、项目与模板任务、付款/融资、报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:servicetitan','ServiceTitan','{"homepage": "https://www.servicetitan.com/", "id": "commercial:servicetitan", "leaf_matches": [{"reason": "官方 HVAC 行业页说明该平台面向住宅、商业与施工暖通承包商，集中处理排程、派单、工单管理和开票，移动端让技师查看客户历史、工单与收款流程并可导航到客户地点；对应客户档案与工单地点、从排程/派单到开票的工单处理、执行技师和完成工作计费四项核心。", "slug": "hvac-service-management", "source_urls": ["https://www.servicetitan.com/industries/hvac-software"]}], "name": "ServiceTitan", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:04.156953+08:00", "kind": "documentation", "sha256": "cb79aafc34947b92dfa8eaa032a97efededf132715a713c48dd331da6eec59ab", "snapshot_path": "sources/cb79aafc34947b92dfa8eaa032a97efededf132715a713c48dd331da6eec59ab.txt", "url": "https://www.servicetitan.com/industries/hvac-software"}], "summary": "面向住宅与商业暖通承包商的现场服务管理平台，集中管理客户、排程派单、工单、技师移动端、报价与服务协议、开票收款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gem-logic','Gem Logic','{"homepage": "https://www.gem-logic.com/", "id": "commercial:gem-logic", "leaf_matches": [{"reason": "官方维修管理页说明：柜台接件时记录客户、维修工作和承诺日期，拍摄前后照片并打印条码标签；工单按 received/workshop/ready 等阶段在看板流转，可外协；估价经客户书面批准后转维修；完成通知客户，取件时扫码收款，历史随客户保留。对应客户×单件物品×请求工作的维修工单、受管生命周期、归还结算与历史留存。", "slug": "jewelry-repair-management", "source_urls": ["https://www.gem-logic.com/repair-management"]}], "name": "Gem Logic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:03.580149+08:00", "kind": "documentation", "sha256": "9bb03a9a3496f753e6d1223bb2c8f4e3b063e680c0677f6d1c85b31679e2795e", "snapshot_path": "sources/9bb03a9a3496f753e6d1223bb2c8f4e3b063e680c0677f6d1c85b31679e2795e.txt", "url": "https://www.gem-logic.com/repair-management"}], "summary": "面向珠宝零售商与维修工坊的珠宝业务平台，其维修管理模块覆盖接件、拍照/标签、工坊流转、估价审批、取件收款与历史留存。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:curbwaste','CurbWaste','{"homepage": "https://www.curbwaste.com/", "id": "commercial:curbwaste", "leaf_matches": [{"reason": "官方页明确面向废物清运商，提供订单创建与跟踪、一体化路线管理、实时派车和车队管理、司机 iOS/Android 应用、容器/资产位置与在途时间跟踪、自动开票和客户门户；对应客户、服务事件、执行卡车与团队、按记录执行计费。该案例覆盖定义中的路线式废物清运（含 roll-off、商业与住宅路线）实现，未宣称其覆盖按次垃圾清运。", "slug": "junk-removal-waste-hauling-management", "source_urls": ["https://www.curbwaste.com/"]}], "name": "CurbWaste", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:03.099776+08:00", "kind": "homepage", "sha256": "dccb4f0079d9ea9083d3ff235f20abc7212d70031fbc5416e0bc2acc55ad8190", "snapshot_path": "sources/dccb4f0079d9ea9083d3ff235f20abc7212d70031fbc5416e0bc2acc55ad8190.txt", "url": "https://www.curbwaste.com/"}], "summary": "面向废物清运商的云端业务平台，覆盖订单、路线、实时派车、司机移动端、容器/资产跟踪、自动开票与客户门户。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aspire','Aspire','{"homepage": "https://www.youraspire.com/", "id": "commercial:aspire", "leaf_matches": [{"reason": "官方首页说明园林景观企业用其完成精确投标、实时作业成本和运营洞察；排期可把已赢单转为计划并创建循环作业，指标可按服务、物业和部门查看；作业成本跟踪材料与人工小时，CRM 管理投标/提案/客户，开票模块创建并跟踪付款，劳动管理用于同步技师与排期。对应客户与服务物业、景观作业、办公室指派团队、完成工作计费四项核心。", "slug": "landscaping-business-management", "source_urls": ["https://www.youraspire.com/"]}], "name": "Aspire", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:03.816479+08:00", "kind": "homepage", "sha256": "3d0e7c82b78b83fa1c0e356958ba773698c5edc9bc5de2651cfee4d611d0f1a5", "snapshot_path": "sources/3d0e7c82b78b83fa1c0e356958ba773698c5edc9bc5de2651cfee4d611d0f1a5.txt", "url": "https://www.youraspire.com/"}], "summary": "面向园林景观企业的现场服务管理平台，覆盖投标估算、循环作业排期、作业成本、客户/物业 CRM、团队排班与开票收款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:realgreen','RealGreen','{"homepage": "https://www.realgreen.com/", "id": "commercial:realgreen", "leaf_matches": [{"reason": "官方首页说明 RealGreen 是草坪护理企业的统一业务软件，覆盖估算、排期、智能路线、客户沟通、支付与经营分析；估价可按物业测量，移动端向技师提供作业详情、客户历史与实时更新，内置账单和支付，页面示例含客户账户、发票与服务历史。对应客户与服务草坪/物业、草坪服务访问、指派团队/技术人员、完成访问计费四项核心。", "slug": "lawn-care-business-management", "source_urls": ["https://www.realgreen.com/"]}], "name": "RealGreen", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:59:10.119759+08:00", "kind": "homepage", "sha256": "c50328cc47521be96c737c73050aa4a1bc2b3a83d3a9905e0272a8e03be83ddf", "snapshot_path": "sources/c50328cc47521be96c737c73050aa4a1bc2b3a83d3a9905e0272a8e03be83ddf.txt", "url": "https://www.realgreen.com/"}], "summary": "面向草坪护理与绿色产业企业的业务管理平台，覆盖测量估价、排期与路线、客户/服务历史、技师移动端、账单与支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1201466005','OpenFieldService','{"deployment": ["自托管运行，README 提供 pnpm 本地开发与数据库初始化步骤", "数据保存在本地 SQLite/D1，无强制云依赖"], "features": ["客户、服务地点与设备记录", "工单排程、技术员派工与状态跟踪", "可配置服务类型及默认价格与时长", "作业检查清单、材料使用与活动记录", "从已完成工单生成发票并跟踪收款状态"], "github_repository_id": 1201466005, "homepage": "https://github.com/clawnify/OpenFieldService", "id": "github:1201466005", "leaf_matches": [{"reason": "README 明确列出家电维修垂直（洗衣机/烘干机、冰箱、洗碗机、烤箱等），并以客户服务地址、设备序列号与服务历史、技术员派工、完工开票组织工作，核心匹配。", "slug": "appliance-repair-management", "source_urls": ["https://github.com/clawnify/OpenFieldService", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/README.md", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/LICENSE"]}, {"reason": "README 明确列出清洁垂直（家庭保洁、深度清洁、搬入搬出、地毯/窗户清洗），并提供客户场地及入户说明、可重复作业字段、清洁人员派工、作业检查表与完工开票；核心工作流匹配。商业保洁巡检评分与客户门户未包含，关系限于核心。", "slug": "cleaning-business-management", "source_urls": ["https://github.com/clawnify/OpenFieldService", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/README.md", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/LICENSE"]}, {"reason": "README 明确列出电气垂直（配电盘升级、插座安装、照明、吊扇、故障排查），并提供客户服务地址、作业生命周期、电工派工、设备记录与完工开票；核心工作流匹配。估价/定金、采购单与大型项目阶段管理未提供，关系限于服务呼叫型电气作业。", "slug": "electrical-service-management", "source_urls": ["https://github.com/clawnify/OpenFieldService", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/README.md", "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/LICENSE"]}, {"reason": "README 的行业服务目录明确包含 Locksmith（住宅开锁、换锁芯、装门锁、配钥匙、开保险柜），应用具备客户与服务地址、工单生命周期、技术员派工和发票等锁匠业务核心；未提供锁具/钥匙结构化台账。", "slug": "locksmith-business-management", "source_urls": ["https://raw.githubusercontent.com/clawnify/OpenFieldService/main/README.md"]}, {"reason": "README 的行业服务目录明确包含 Plumbing（疏通、管道维修、热水器安装、下水道检测、漏水检测），并以客户/服务地点、工单排程、技术员派工、材料与发票为核心；未提供会员计划，但已满足定义核心。", "slug": "plumbing-business-management", "source_urls": ["https://raw.githubusercontent.com/clawnify/OpenFieldService/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/main/LICENSE", "license_review": {"rationale": "已读取该仓库 LICENSE 全文，MIT 标准许可条款完整，覆盖仓库源代码，未发现附加限制条款。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/main/LICENSE", "spdx_id": "MIT"}, "name": "OpenFieldService", "repository_url": "https://github.com/clawnify/OpenFieldService", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:58:05.432209+08:00", "kind": "repository_metadata", "sha256": "2a553caced92fc04bb7bfb78a5eca29d689dc70e8a9866b0d0505762396674f9", "snapshot_path": "sources/2a553caced92fc04bb7bfb78a5eca29d689dc70e8a9866b0d0505762396674f9.txt", "url": "https://github.com/clawnify/OpenFieldService"}, {"fetched_at": "2026-10-27T03:04:53.279147+08:00", "kind": "repository_metadata", "sha256": "cde14c22ddca07329f3b3f751f571c77327302a8e92b312d4674149ba632f42f", "snapshot_path": "sources/cde14c22ddca07329f3b3f751f571c77327302a8e92b312d4674149ba632f42f.txt", "url": "https://github.com/clawnify/OpenFieldService"}, {"fetched_at": "2026-10-27T02:58:07.723762+08:00", "kind": "license", "sha256": "a14365f7c2920e8aca5269b735f17899f17b4a09b9f348ae2ce4b23b0173460e", "snapshot_path": "sources/a14365f7c2920e8aca5269b735f17899f17b4a09b9f348ae2ce4b23b0173460e.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/LICENSE"}, {"fetched_at": "2026-10-27T02:58:06.678611+08:00", "kind": "readme", "sha256": "bc95e1367f78eed4ea801831f576e0af567fee949df6d12ffa07b13bc7402eff", "snapshot_path": "sources/bc95e1367f78eed4ea801831f576e0af567fee949df6d12ffa07b13bc7402eff.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/HEAD/README.md"}, {"fetched_at": "2026-10-27T03:04:52.039690+08:00", "kind": "license", "sha256": "a14365f7c2920e8aca5269b735f17899f17b4a09b9f348ae2ce4b23b0173460e", "snapshot_path": "sources/a14365f7c2920e8aca5269b735f17899f17b4a09b9f348ae2ce4b23b0173460e.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/main/LICENSE"}, {"fetched_at": "2026-10-27T03:04:45.774129+08:00", "kind": "readme", "sha256": "bc95e1367f78eed4ea801831f576e0af567fee949df6d12ffa07b13bc7402eff", "snapshot_path": "sources/bc95e1367f78eed4ea801831f576e0af567fee949df6d12ffa07b13bc7402eff.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenFieldService/main/README.md"}], "summary": "开源、自托管的现场服务管理应用，围绕客户与服务地点、工单排程、技术员派工、检查清单与材料记录、发票收款组织业务；服务类型可按行业配置，README 明确列出锁匠与管道服务目录。", "technology_stack": ["Preact", "Hono", "SQLite (Cloudflare D1)"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:smartmoving','SmartMoving','{"homepage": "https://www.smartmoving.com/", "id": "commercial:smartmoving", "leaf_matches": [{"reason": "官方产品页明确描述从销售、估价与物品清单到已预订作业、排程、派工、现场、账单的同一作业流程，并说明作业组在手机上接收地址与备注、仓储与客户及作业绑定，符合搬家公司管理核心。", "slug": "moving-company-management", "source_urls": ["https://www.smartmoving.com/moving-company-software"]}], "name": "SmartMoving", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:05:16.410167+08:00", "kind": "documentation", "sha256": "788b5aee25bab06b9f967e16e0d5209c98d4fa4ff1da74a44383754592637355", "snapshot_path": "sources/788b5aee25bab06b9f967e16e0d5209c98d4fa4ff1da74a44383754592637355.txt", "url": "https://www.smartmoving.com/moving-company-software"}], "summary": "面向搬家公司的业务管理软件，把估价与物品清单、已预订搬运作业、排程、作业组派工、现场执行、仓储与账单连接在同一作业记录上。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:pestpac','PestPac','{"homepage": "https://www.pestpac.com/", "id": "commercial:pestpac", "leaf_matches": [{"reason": "官方排程功能页说明其按技术员平衡工作量、支持任意频率的复发服务、在派工给无相应许可证技术员时告警，并结合路线与客户排程；页面导航亦列出化学药剂跟踪与白蚁检查等害虫业专用能力。", "slug": "pest-control-management", "source_urls": ["https://www.pestpac.com/features/pest-control-scheduling-software"]}], "name": "PestPac", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:05:16.459680+08:00", "kind": "documentation", "sha256": "55c201945116424172bbb402b90b682acb9fa51ef1b0fb71240a9c22d7b8e2ff", "snapshot_path": "sources/55c201945116424172bbb402b90b682acb9fa51ef1b0fb71240a9c22d7b8e2ff.txt", "url": "https://www.pestpac.com/features/pest-control-scheduling-software"}], "summary": "面向害虫防治公司的运营管理软件，覆盖客户与作业排程、复发服务频率、技术员资质与路线、现场服务记录和账单。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:skimmer','Skimmer','{"homepage": "https://www.getskimmer.com/", "id": "commercial:skimmer", "leaf_matches": [{"reason": "官方技术员功能页展示按技术员的路线与服务停靠、多个水体与服务地点的化学读数和服务历史、LSI 与投药计算、检查清单及从完成工作生成发票；计费页进一步说明从常规泳池服务和工作单批量开票。", "slug": "pool-service-management", "source_urls": ["https://www.getskimmer.com/product/technicians", "https://www.getskimmer.com/product/billing"]}], "name": "Skimmer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:05:31.415387+08:00", "kind": "documentation", "sha256": "a9af3179410013abc0ae47daac360bc7a5a2a1608cc5af5344b42df27c090f6f", "snapshot_path": "sources/a9af3179410013abc0ae47daac360bc7a5a2a1608cc5af5344b42df27c090f6f.txt", "url": "https://www.getskimmer.com/product/technicians"}, {"fetched_at": "2026-10-27T03:05:31.569004+08:00", "kind": "documentation", "sha256": "405d60ba482553eecfdaa73bb83db99594505ac5731f9d5d97f4266f63f63235", "snapshot_path": "sources/405d60ba482553eecfdaa73bb83db99594505ac5731f9d5d97f4266f63f63235.txt", "url": "https://www.getskimmer.com/product/billing"}], "summary": "面向泳池服务公司的现场服务软件，按技术员组织路线与服务停靠，记录水体化学读数与投药、检查清单和设备信息，并从完成的服务生成发票与收款。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
