INSERT INTO "application" VALUES('commercial:boulevard','Boulevard','{"homepage": "https://www.joinblvd.com/", "id": "commercial:boulevard", "leaf_matches": [{"reason": "官方页面显示 Boulevard 提供预约排班、客户档案、POS 结账与支付，服务沙龙等预约制企业，覆盖预约到收入的经营流程。", "slug": "appointment-based-service-business-management", "source_urls": ["https://www.joinblvd.com/", "https://www.joinblvd.com/features/scheduling", "https://www.joinblvd.com/features/payments", "https://www.joinblvd.com/features/client-management"]}], "name": "Boulevard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:11:50.842388+08:00", "kind": "homepage", "sha256": "72ae218ec8cf26145bc4140b953ca86feb7cd5f010633074a057035307a85261", "snapshot_path": "sources/72ae218ec8cf26145bc4140b953ca86feb7cd5f010633074a057035307a85261.txt", "url": "https://www.joinblvd.com/"}, {"fetched_at": "2026-10-27T03:11:52.893051+08:00", "kind": "documentation", "sha256": "6839443e42a5bd70f6f49524dbf718dbaa473c30353f6f7fbd5fe4ce7f6c8997", "snapshot_path": "sources/6839443e42a5bd70f6f49524dbf718dbaa473c30353f6f7fbd5fe4ce7f6c8997.txt", "url": "https://www.joinblvd.com/features/scheduling"}, {"fetched_at": "2026-10-27T03:11:54.755333+08:00", "kind": "documentation", "sha256": "58b06cd1953270fc92f65e7d2d91069efda523017ad5e62995a8a63f6a823c2e", "snapshot_path": "sources/58b06cd1953270fc92f65e7d2d91069efda523017ad5e62995a8a63f6a823c2e.txt", "url": "https://www.joinblvd.com/features/payments"}, {"fetched_at": "2026-10-27T03:11:56.714661+08:00", "kind": "documentation", "sha256": "52ca9f1b96edd42534cc8c04eb64a81d698de50407c202e68ad341addc8c9358", "snapshot_path": "sources/52ca9f1b96edd42534cc8c04eb64a81d698de50407c202e68ad341addc8c9358.txt", "url": "https://www.joinblvd.com/features/client-management"}], "summary": "面向沙龙、水疗、医美等预约制美容健康企业的商业平台，覆盖自助预约、日历排班、客户档案、POS 结账与支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:squire','SQUIRE','{"homepage": "https://getsquire.com/", "id": "commercial:squire", "leaf_matches": [{"reason": "官方 POS 页说明服务票据由预约日历生成，结账在同一交易中处理服务、零售、小费、提成与摊位租金拆分，并显示客户历史；排班页说明预约、改约、取消、封锁时间与理发师各自管理预约簿；客户页说明客户档案含备注、偏好与预约历史。上述正文覆盖理发店的服务预约、客户、排班到含小费结账的核心链路。", "slug": "barbershop-management", "source_urls": ["https://getsquire.com/features/pos-payments", "https://getsquire.com/features/scheduling", "https://getsquire.com/features/client-management", "https://getsquire.com/"]}], "name": "SQUIRE", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:12:18.465858+08:00", "kind": "homepage", "sha256": "cf12dad7b3889fc09bb8abb41cd546942c4275a5de57514adf6a3ac5ae3b6d73", "snapshot_path": "sources/cf12dad7b3889fc09bb8abb41cd546942c4275a5de57514adf6a3ac5ae3b6d73.txt", "url": "https://getsquire.com/"}, {"fetched_at": "2026-10-27T03:12:10.032906+08:00", "kind": "documentation", "sha256": "6cb6705f3d1e3608dc35f609164b2ab362d7093d6b55a172e0228a786de6bf16", "snapshot_path": "sources/6cb6705f3d1e3608dc35f609164b2ab362d7093d6b55a172e0228a786de6bf16.txt", "url": "https://getsquire.com/features/pos-payments"}, {"fetched_at": "2026-10-27T03:13:40.841132+08:00", "kind": "documentation", "sha256": "26f24004bab60dc333e80577c5f93acc2ba3b7d80a701f423304b75f881695f3", "snapshot_path": "sources/26f24004bab60dc333e80577c5f93acc2ba3b7d80a701f423304b75f881695f3.txt", "url": "https://getsquire.com/features/scheduling"}, {"fetched_at": "2026-10-27T03:13:40.855827+08:00", "kind": "documentation", "sha256": "b0e26c38223ee9b4b205589b7d2fd6e4bc1114642ae9b780d625f56946059f79", "snapshot_path": "sources/b0e26c38223ee9b4b205589b7d2fd6e4bc1114642ae9b780d625f56946059f79.txt", "url": "https://getsquire.com/features/client-management"}], "summary": "面向理发店与独立理发师的预约、客户档案、排班及 POS 结账管理，支持小费与按理发师归属收入。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
