INSERT INTO "application" VALUES('commercial:massagebook','MassageBook','{"homepage": "https://pro.massagebook.com/", "id": "commercial:massagebook", "leaf_matches": [{"reason": "官方实践管理首页正文明确覆盖在线预约、服务与可用性规则、客户数据库、问询表、SOAP notes、结账/支付/小费、会员与复购，以及多提供者/多房间日历和角色权限；这些正对应按摩实践的服务目录、健康相邻客户档案、预约生命周期、治疗记录与结账。", "slug": "massage-practice-management", "source_urls": ["https://pro.massagebook.com/"]}], "name": "MassageBook", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:12:18.218529+08:00", "kind": "homepage", "sha256": "0b3d2b5c519c300842aaa27fa6462c44d2b6afc2afc8f68dd810bf9005039729", "snapshot_path": "sources/0b3d2b5c519c300842aaa27fa6462c44d2b6afc2afc8f68dd810bf9005039729.txt", "url": "https://pro.massagebook.com/"}], "summary": "面向按摩与身体疗愈从业者的实践管理平台，覆盖在线预约、客户档案、问询表/SOAP 记录、结账/小费与会员套餐。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aesthetic-record','Aesthetic Record','{"homepage": "https://www.aestheticrecord.com/", "id": "commercial:aesthetic-record", "leaf_matches": [{"reason": "官方首页定位为医美/医疗水疗的 EMR 与实践管理系统，正文与功能导航覆盖预约/智能排程、客户 CRM、临床文档、chart sign-off/auditing、前后照片、库存、集成支付/Chart-to-Cart、会员与 HIPAA-compliant，正对应受监管美容治疗的目录、客户档案、预约、就诊文档与结账五结构。", "slug": "med-spa-management", "source_urls": ["https://www.aestheticrecord.com/"]}], "name": "Aesthetic Record", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:12:18.639425+08:00", "kind": "homepage", "sha256": "8319666df6c1a33aa76d4f86d558b8f83906284363c763229a4d1a3e707eaa23", "snapshot_path": "sources/8319666df6c1a33aa76d4f86d558b8f83906284363c763229a4d1a3e707eaa23.txt", "url": "https://www.aestheticrecord.com/"}], "summary": "面向医美诊所与医疗水疗机构的 EMR/实践管理系统，覆盖预约、客户 CRM、临床文档与照片、库存和集成支付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:fresha','Fresha','{"homepage": "https://www.fresha.com/for-business", "id": "commercial:fresha", "leaf_matches": [{"reason": "官方商家产品页正文将其定位为沙龙/水疗预约与管理软件，并列出在线预约、日历、客户、团队成员、销售、POS、结账、预付/押金和库存；可核对沙龙的服务预约、客户记录与结账收款核心。正文未逐项说明发型师-服务-时段的绑定与染发配方，故不据此扩写这些细节。", "slug": "salon-management-system", "source_urls": ["https://www.fresha.com/for-business"]}], "name": "Fresha", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:15:29.683005+08:00", "kind": "documentation", "sha256": "e81070fc288b6900fe0ec88e4ddaa761e28100d7f794334d144f6636b16bf36f", "snapshot_path": "sources/e81070fc288b6900fe0ec88e4ddaa761e28100d7f794334d144f6636b16bf36f.txt", "url": "https://www.fresha.com/for-business"}], "summary": "面向沙龙、水疗等美容健康商家的预约与门店管理软件，提供在线预约日历、客户与团队管理、销售、收银支付、押金/预付款和库存管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zenoti','Zenoti','{"homepage": "https://www.zenoti.com/", "id": "commercial:zenoti", "leaf_matches": [{"reason": "官方水疗产品页正文明确写有 room- and therapist-aware appointment book、online booking、client history、POS、memberships/packages、deposits/cancellation policies，并区分 day/resort/multi-location spa；可核对水疗预约、治疗师/房间资源与结账付款三个核心。未据此断言医疗水疗的临床文档与合规模块。", "slug": "spa-management-system", "source_urls": ["https://www.zenoti.com/spa-management-software"]}], "name": "Zenoti", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:15:05.322597+08:00", "kind": "documentation", "sha256": "2e0f05f38be167052f19409cb072eb17f859987ef6cc3eadadbe5d024dc32a0f", "snapshot_path": "sources/2e0f05f38be167052f19409cb072eb17f859987ef6cc3eadadbe5d024dc32a0f.txt", "url": "https://www.zenoti.com/spa-management-software"}], "summary": "面向日间水疗、度假酒店水疗与多店水疗集团的运营管理平台，覆盖在线预约、房间与治疗师排程、客户历史、POS、会员/套餐及押金与取消政策。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1076346771','Tattoo Workshop','{"deployment": ["Node.js 18+ 自托管（npm install / npm run dev）", "生产构建 npm run build，前端静态产物配 Express 服务", "SQLite 本地数据库（better-sqlite3）"], "features": ["客户档案：联系方式、地址与备注，可搜索筛选", "预约：绑定客户与艺术家，记录时长、备注及 scheduled/completed/cancelled 状态", "服务价目：服务分类、价格与预计时长", "发票：关联客户与预约，含明细、税、定金及 pending/partial/paid/cancelled 支付状态", "角色与鉴权：Admin、Artist、Receptionist，JWT 登录", "作品集与可选的 Gemini AI 纹身创意生成"], "github_repository_id": 1076346771, "homepage": "https://github.com/GizzZmo/Tattoo-Workshop", "id": "github:1076346771", "leaf_matches": [{"reason": "README 明确列出 customer database、appointments with customers/artists/status、service categories/pricing/duration、invoices linked to customers and appointments with deposits/payment status，并有 Admin/Artist/Receptionist 角色；可核对纹身工作室的客户记录、客户×艺术家预约、服务价目与结算记录。README 未证明同意书/年龄核验或定金先付才确认，故不写入这些断言。", "slug": "tattoo-studio-management", "source_urls": ["https://github.com/GizzZmo/Tattoo-Workshop", "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/README.md", "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/LICENSE"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/LICENSE", "license_review": {"rationale": "快照为仓库根目录完整 MIT 许可证文本，含版权声明、标准授权段与免责声明，未见附加限制；按 MIT 收录。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/LICENSE", "spdx_id": "MIT"}, "name": "Tattoo Workshop", "repository_url": "https://github.com/GizzZmo/Tattoo-Workshop", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T03:15:11.917440+08:00", "kind": "repository_metadata", "sha256": "47e9233dcec876aefefbfb477a6a8bcbdbbeb27b0b127ca3e367acba0502ad78", "snapshot_path": "sources/47e9233dcec876aefefbfb477a6a8bcbdbbeb27b0b127ca3e367acba0502ad78.txt", "url": "https://github.com/GizzZmo/Tattoo-Workshop"}, {"fetched_at": "2026-10-27T03:15:13.015877+08:00", "kind": "readme", "sha256": "f03c9f9775e529260b7e1fafabc428eb5924bd903fd1c2361be96b56c8e2ed3b", "snapshot_path": "sources/f03c9f9775e529260b7e1fafabc428eb5924bd903fd1c2361be96b56c8e2ed3b.txt", "url": "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/README.md"}, {"fetched_at": "2026-10-27T03:15:14.067473+08:00", "kind": "license", "sha256": "e2a4eb377955e681c1059728c00e4bb7079c96afa0cb7bac3df8aceb1fc6c761", "snapshot_path": "sources/e2a4eb377955e681c1059728c00e4bb7079c96afa0cb7bac3df8aceb1fc6c761.txt", "url": "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/LICENSE"}, {"fetched_at": "2026-10-27T03:15:15.116675+08:00", "kind": "documentation", "sha256": "07e45bf966579bc36a80d4d72ea3c86b937f8e391cc5207cbcb56fd2cf147e85", "snapshot_path": "sources/07e45bf966579bc36a80d4d72ea3c86b937f8e391cc5207cbcb56fd2cf147e85.txt", "url": "https://raw.githubusercontent.com/GizzZmo/Tattoo-Workshop/HEAD/INSTALLATION.md"}], "summary": "开源纹身工作室管理应用，覆盖客户档案、艺术家预约与状态、服务价目、作品集、发票/定金与支付状态、角色权限，可用 Node.js 与 SQLite 自托管。", "technology_stack": ["React 18", "Vite", "Node.js", "Express", "SQLite", "JWT"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:120156076','Cloudreve','{"deployment": ["可使用官方一体化打包或 Docker 部署到自有服务器", "支持从源码构建"], "features": ["文件存于本地、远端节点或多种对象存储", "拖拽上传、并行断点续传、批量下载", "压缩/解压、在线预览与在线编辑", "WebDAV 覆盖全部存储策略", "带有效期的文件与文件夹分享链接"], "github_repository_id": 120156076, "homepage": "https://cloudreve.org", "id": "github:120156076", "leaf_matches": [{"reason": "README 称其为“支持多云的自托管文件管理系统”，明确条目对应 GPL-3.0 社区仓库，可把文件存入 Local、Remote node、OneDrive、S3 兼容 API、阿里云 OSS、腾讯 COS 等，支持拖拽上传、并行断点续传、压缩解压、批量下载、WebDAV 覆盖全部存储策略，以及带有效期的文件/文件夹分享链接；浏览器端访问由快速开始文档的注册/登录与端口访问说明支持。官方快速开始文档另载明 Pro 版需通过 --license-key 另行授权，故所列能力仅按社区 README 记录，不含 Pro 功能；未引用客户端可达性。仓库身份与 GPL-3.0 由元数据及许可证接口证明。作为个人云盘的次级/部分匹配记录：已读快照未证明账户级存储配额与第一方桌面/移动客户端，核心案例由 Nextcloud 覆盖。", "slug": "personal-cloud-drive", "source_urls": ["https://github.com/cloudreve/cloudreve", "https://raw.githubusercontent.com/cloudreve/cloudreve/master/README.md", "https://api.github.com/repos/cloudreve/cloudreve/license", "https://docs.cloudreve.org/overview/quickstart"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/cloudreve/cloudreve/license", "name": "Cloudreve", "repository_url": "https://github.com/cloudreve/cloudreve", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:57:27.589453+08:00", "kind": "repository_metadata", "sha256": "cb631e85a20adadc9d7b8c97a8a417748daba96fc684c76be0f88820ac673292", "snapshot_path": "sources/cb631e85a20adadc9d7b8c97a8a417748daba96fc684c76be0f88820ac673292.txt", "url": "https://github.com/cloudreve/cloudreve"}, {"fetched_at": "2026-10-24T11:58:13.048457+08:00", "kind": "readme", "sha256": "8aabd10da4bc5862e0794d0a9206283f2a551e47484e9bcd6c6aef31b4a3db55", "snapshot_path": "sources/8aabd10da4bc5862e0794d0a9206283f2a551e47484e9bcd6c6aef31b4a3db55.txt", "url": "https://raw.githubusercontent.com/cloudreve/cloudreve/master/README.md"}, {"fetched_at": "2026-10-24T11:58:07.315245+08:00", "kind": "license", "sha256": "2c84ed4095f97263653641bdf38f1a77f3fb8f3bf16d5623c566befbd65d7358", "snapshot_path": "sources/2c84ed4095f97263653641bdf38f1a77f3fb8f3bf16d5623c566befbd65d7358.txt", "url": "https://api.github.com/repos/cloudreve/cloudreve/license"}, {"fetched_at": "2026-10-24T12:09:27.876866+08:00", "kind": "documentation", "sha256": "660cab821ff6a6947e52ced7641a7110b1c23fdab867f81acd46d96e7cec32f5", "snapshot_path": "sources/660cab821ff6a6947e52ced7641a7110b1c23fdab867f81acd46d96e7cec32f5.txt", "url": "https://docs.cloudreve.org/overview/quickstart"}], "summary": "Cloudreve 社区版（GPL-3.0 仓库）是自托管云盘：把文件存放在本地、远端节点或 OneDrive、S3、OSS、COS 等对象存储，通过浏览器与 WebDAV 上传下载、压缩解压、批量下载并分享；Pro 版为另行授权版本，不在本条目开源范围内。", "technology_stack": ["Go", "Gin", "ent", "React", "Redux"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:8681349','Huginn','{"deployment": ["Docker 单容器运行，或按官方文档在自有服务器安装", "需要 MySQL 或 PostgreSQL 数据库", "提供 Web 管理界面管理 Agent 与事件"], "features": ["监视网页、RSS、IMAP、Webhook、MQTT 等事件源", "事件在 Agent 有向图中传播并触发下游动作", "可发送邮件、即时消息、短信，或写入 Dropbox/S3/本地文件", "可发布自有 feed 与 JSON 端点", "提供 Docker 一体化运行方式"], "github_repository_id": 8681349, "homepage": "https://github.com/huginn/huginn", "id": "github:8681349", "leaf_matches": [{"reason": "README 将其描述为“在你自己的服务器上构建替你在线执行自动化任务的 Agent 系统”，Agent 创建并消费事件、沿有向图传播，README 直接类比 IFTTT/Zapier，并列出监视 RSS/IMAP/Webhook/MQTT、按事件触发邮件或消息、发布自有 feed 与 JSON 端点等例子，官方 Docker 方式在服务器上持续运行。外部服务为作用对象、在 Web 界面配置的持久 Agent 图与服务端无人值守执行三层均可由官方正文证明；运行记录以 Agent 创建/消费的 Event 日志承载（README 示例图标题为“Browsing the Events your Agents created”），已读页面未描述独立的逐次运行历史/状态面板，故不据此声称具备该面板。其为自托管而非厂商托管，按任务约定视为完整应用并保留该边界说明。仓库身份与 MIT 许可经元数据及许可证接口核实。", "slug": "personal-workflow-automation-platform", "source_urls": ["https://github.com/huginn/huginn", "https://raw.githubusercontent.com/huginn/huginn/master/README.md", "https://api.github.com/repos/huginn/huginn/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/huginn/huginn/license", "name": "Huginn", "repository_url": "https://github.com/huginn/huginn", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:52:54.515808+08:00", "kind": "repository_metadata", "sha256": "71a9675fdcc0a6dd151562ee720b641b546f72b2633af5a243609f5278e589be", "snapshot_path": "sources/71a9675fdcc0a6dd151562ee720b641b546f72b2633af5a243609f5278e589be.txt", "url": "https://github.com/huginn/huginn"}, {"fetched_at": "2026-10-24T11:52:55.660482+08:00", "kind": "readme", "sha256": "30e1d0322ddf0672de00fb0d9700a9c22892c16ed2957bbf84e2a1968cbbce97", "snapshot_path": "sources/30e1d0322ddf0672de00fb0d9700a9c22892c16ed2957bbf84e2a1968cbbce97.txt", "url": "https://raw.githubusercontent.com/huginn/huginn/master/README.md"}, {"fetched_at": "2026-10-24T11:54:40.165111+08:00", "kind": "license", "sha256": "c455249fed1d8e92d4a2a7a58d71feb875601463b1e0d87ad626194001081b07", "snapshot_path": "sources/c455249fed1d8e92d4a2a7a58d71feb875601463b1e0d87ad626194001081b07.txt", "url": "https://api.github.com/repos/huginn/huginn/license"}], "summary": "Huginn 是自托管的个人自动化平台：用可配置的 Agent 监视网站、RSS、IMAP、Webhook、MQTT 等事件源，按有向图把事件传给下游 Agent 执行发信、发帖、写入存储等动作，并在服务器上持续运行。", "technology_stack": ["Ruby on Rails", "MySQL/PostgreSQL", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1200449429','OpenDesign','{"deployment": ["零云依赖，本地或自有服务器运行", "提供 SQLite 持久化", "可嵌入自有 SaaS 产品"], "features": ["内置约六类 LinkedIn 社交图模板", "Fabric.js 画布对象编辑与 2x 高清渲染", "模板字段可命名并由数据/Agent 填充", "10 种 Google Fonts 与自定义字体导入", "导出多页 PDF 与 2x PNG", "设计自动保存到 SQLite"], "github_repository_id": 1200449429, "homepage": "https://github.com/clawnify/OpenDesign", "id": "github:1200449429", "leaf_matches": [{"reason": "README 自称“开源 Canva 替代”，面向社交媒体图形，随附 LinkedIn 优化的 Quote Card、Announcement、Tips List 等预制模板，使用 Fabric.js 画布做完整对象操作，支持模板字段用数据填充、10 种 Google Fonts、自动保存到 SQLite，并导出多页 PDF 或 2x PNG。模板库、选定模板后个性化、成品导出三项结构均有官方正文；模板库规模有限（约六类、以 LinkedIn 帖子模板为主）在摘要中如实说明；未据此声称多格式/主题组织、关键词检索或持续维护。仓库身份与 MIT 许可经元数据及许可证接口核实。", "slug": "template-based-design-platform", "source_urls": ["https://github.com/clawnify/OpenDesign", "https://raw.githubusercontent.com/clawnify/OpenDesign/main/README.md", "https://api.github.com/repos/clawnify/OpenDesign/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/clawnify/OpenDesign/license", "name": "OpenDesign", "repository_url": "https://github.com/clawnify/OpenDesign", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:57:37.677808+08:00", "kind": "repository_metadata", "sha256": "9cf5d037465946425543e25f7ea9bad9c4b44935c3cd6080a9968ccd7d0d1742", "snapshot_path": "sources/9cf5d037465946425543e25f7ea9bad9c4b44935c3cd6080a9968ccd7d0d1742.txt", "url": "https://github.com/clawnify/OpenDesign"}, {"fetched_at": "2026-10-24T11:57:39.159643+08:00", "kind": "readme", "sha256": "eea6714bb7f40fdc361b28902857638e0bcbcb0239a1938ba61fadda39c7c282", "snapshot_path": "sources/eea6714bb7f40fdc361b28902857638e0bcbcb0239a1938ba61fadda39c7c282.txt", "url": "https://raw.githubusercontent.com/clawnify/OpenDesign/main/README.md"}, {"fetched_at": "2026-10-24T12:01:53.174990+08:00", "kind": "license", "sha256": "d2bcb5a97e9811c9613c4144a872cd39253ea0fd2fd3053baa141eb4fc8d986a", "snapshot_path": "sources/d2bcb5a97e9811c9613c4144a872cd39253ea0fd2fd3053baa141eb4fc8d986a.txt", "url": "https://api.github.com/repos/clawnify/OpenDesign/license"}], "summary": "OpenDesign 是自托管的模板化设计平台：内置有限模板库（约六类 LinkedIn 帖子等成品模板），用户在画布编辑器里替换文字图片、调整颜色字体后导出多页 PDF 或 2x PNG。", "technology_stack": ["Preact", "Fabric.js", "Hono", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:demandbase','Demandbase','{"homepage": "https://www.demandbase.com/", "id": "commercial:demandbase", "leaf_matches": [{"reason": "官方首页以目标账户与购买组为中心，提供账户识别与优先级、针对账户的广告/项目激活、参与度与管道衡量，符合账户级定义、激活与测量闭环。", "slug": "abm-platform", "source_urls": ["https://www.demandbase.com/"]}], "name": "Demandbase", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:30:03.955043+08:00", "kind": "homepage", "sha256": "688e4cfefce8331157e760fd1d27e667969c0fa5963a0a3ae29560357563f923", "snapshot_path": "sources/688e4cfefce8331157e760fd1d27e667969c0fa5963a0a3ae29560357563f923.txt", "url": "https://www.demandbase.com/"}], "summary": "以目标账户与购买组为单位进行识别、优先级排序、广告激活与管道衡量的 B2B 营销平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:post-affiliate-pro','Post Affiliate Pro','{"homepage": "https://www.postaffiliatepro.com/", "id": "commercial:post-affiliate-pro", "leaf_matches": [{"reason": "官方首页展示联盟会员数据库管理、联盟追踪、多级佣金、支付、报告与自动化，说明其以推广者登记—可追踪转化—佣金—结算账本为核心。", "slug": "affiliate-management-platform", "source_urls": ["https://www.postaffiliatepro.com/"]}], "name": "Post Affiliate Pro", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:30:59.455933+08:00", "kind": "homepage", "sha256": "71ac4152eb37c0d9c0916b89698c0c35cb8b3a12351ab9a7c2566c132e4a8f50", "snapshot_path": "sources/71ac4152eb37c0d9c0916b89698c0c35cb8b3a12351ab9a7c2566c132e4a8f50.txt", "url": "https://www.postaffiliatepro.com/"}], "summary": "商户侧自营联盟计划的会员管理、追踪、佣金计算与支付记录平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lucky-orange','Lucky Orange','{"homepage": "https://www.luckyorange.com/", "id": "commercial:lucky-orange", "leaf_matches": [{"reason": "官方首页正文以 “heatmaps, funnels and session recordings” 概括对自有网站的行为观察，并逐步说明动态热图、会话录制回放与 Surveys/Live Chat；/analytics 正文说明实时流量、页面行为与表单字段放弃分析，并以 “why your conversion rate is moving” 连接转化衡量；/pricing 功能对比表正文列出热图、会话录制、漏斗以及页面与表单分析，覆盖持续行为观察、漏斗/表单诊断与转化率改进闭环。", "slug": "conversion-rate-optimization-platform", "source_urls": ["https://www.luckyorange.com/", "https://www.luckyorange.com/pricing", "https://www.luckyorange.com/analytics"]}], "name": "Lucky Orange", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:24.331003+08:00", "kind": "homepage", "sha256": "0ab4721be2102d45580cc9aa5350695e58e1f5b2fa785472023f46dd861e2590", "snapshot_path": "sources/0ab4721be2102d45580cc9aa5350695e58e1f5b2fa785472023f46dd861e2590.txt", "url": "https://www.luckyorange.com/"}, {"fetched_at": "2026-10-24T15:53:58.570425+08:00", "kind": "documentation", "sha256": "477ff74108ca5d6305b0494b49af92e9a935e848609668e25a82adf52286965a", "snapshot_path": "sources/477ff74108ca5d6305b0494b49af92e9a935e848609668e25a82adf52286965a.txt", "url": "https://www.luckyorange.com/pricing"}, {"fetched_at": "2026-10-27T11:57:15.976531+08:00", "kind": "documentation", "sha256": "18a5ca58c7679e2842f84ef464aa8379789c73ff89720ea99f2e64d1b1d4ef13", "snapshot_path": "sources/18a5ca58c7679e2842f84ef464aa8379789c73ff89720ea99f2e64d1b1d4ef13.txt", "url": "https://www.luckyorange.com/analytics"}], "summary": "通过热图、漏斗与会话录制观察访客行为并定位转化改进点的网站优化平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:influitive','Influitive','{"homepage": "https://influitive.com/", "id": "commercial:influitive", "leaf_matches": [{"reason": "官方首页标题即“Customer Advocacy SaaS”，页面与功能页展示倡导者动员、参考客户/评论/推荐/客户故事等具体倡导请求，以 Activities、游戏化与奖励推动参与，并以 ROI 衡量；reference-management 页进一步说明参考池招募、按行业/资历/用例匹配、Salesforce 参考请求直通；customer-advocacy-platform 页再证参考池建设、匹配与 ROI 衡量。上述已读页面未出现完成证明提交、审核/批准或记录门控，故该环节作为缺口留档，不作为已证能力断言。", "slug": "customer-advocacy-platform", "source_urls": ["https://influitive.com/", "https://influitive.com/customer-advocacy-software/features/", "https://influitive.com/use-cases/reference-management/", "https://influitive.com/customer-advocacy-platform/"]}], "name": "Influitive", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:26.651086+08:00", "kind": "homepage", "sha256": "e60cea792b7fa2aa0e065ecd786eb6bbbea702decdb4e0ac7a1b6df2843c5f5d", "snapshot_path": "sources/e60cea792b7fa2aa0e065ecd786eb6bbbea702decdb4e0ac7a1b6df2843c5f5d.txt", "url": "https://influitive.com/"}, {"fetched_at": "2026-10-24T18:44:45.924491+08:00", "kind": "documentation", "sha256": "6bddf7e75042fa486fe58e4de611e06239f3a0704fcb0bb117473a8f1cb1879c", "snapshot_path": "sources/6bddf7e75042fa486fe58e4de611e06239f3a0704fcb0bb117473a8f1cb1879c.txt", "url": "https://influitive.com/customer-advocacy-software/features/"}, {"fetched_at": "2026-10-24T18:44:09.487265+08:00", "kind": "documentation", "sha256": "e315e6c3fdace8cf581f728ff053d766dbf8e2fcd3b5fc79074a4d947db026ac", "snapshot_path": "sources/e315e6c3fdace8cf581f728ff053d766dbf8e2fcd3b5fc79074a4d947db026ac.txt", "url": "https://influitive.com/use-cases/reference-management/"}, {"fetched_at": "2026-10-26T16:30:57.787531+08:00", "kind": "documentation", "sha256": "c29cf3bab8bb306da168c6094c0ada1581765426593ea371a321ad77e3366992", "snapshot_path": "sources/c29cf3bab8bb306da168c6094c0ada1581765426593ea371a321ad77e3366992.txt", "url": "https://influitive.com/customer-advocacy-platform/"}], "summary": "运营客户倡导者群体、发起参考/评论/推荐等倡导请求并衡量商业影响的商业平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:statsig','Statsig','{"homepage": "https://statsig.com/", "id": "commercial:statsig", "leaf_matches": [{"reason": "官方首页正文列出 Experimentation、Feature Flags、Product Analytics、Session Replay、Layers、Holdouts、stats engine、SDKs 与 Warehouse Native，并说明团队可建立受管产品指标、用功能开关与实验迭代、运行测试并用统计引擎分析结果，以及以功能开关控制发布流程；覆盖受管指标、实验比较与发布控制。", "slug": "digital-experimentation-platform", "source_urls": ["https://statsig.com/"]}], "name": "Statsig", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T15:29:29.139628+08:00", "kind": "homepage", "sha256": "f66ffcc694f3f6874aaea5ae4b377225e7e635462fff2292d934f46e10a9e24a", "snapshot_path": "sources/f66ffcc694f3f6874aaea5ae4b377225e7e635462fff2292d934f46e10a9e24a.txt", "url": "https://statsig.com/"}], "summary": "面向产品团队的实验、功能开关、产品指标与统计分析的实验平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:evaluagent','EvaluAgent','{"homepage": "https://www.evaluagent.com/", "id": "commercial:evaluagent", "leaf_matches": [{"reason": "官方质量保证页面说明可跨渠道建立评分卡、在同一评估界面播放录音/查看工单、执行校准、处理坐席申诉并监控评估者，覆盖坐席-交互-评分-质量闭环。", "slug": "contact-center-quality-management", "source_urls": ["https://www.evaluagent.com/us/quality-assurance/"]}], "name": "EvaluAgent", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:37:14.387151+08:00", "kind": "documentation", "sha256": "a94e649a2836dd9a3acd9e0b09c2c6bcb3df579a4d901430c1a9696f02280e02", "snapshot_path": "sources/a94e649a2836dd9a3acd9e0b09c2c6bcb3df579a4d901430c1a9696f02280e02.txt", "url": "https://www.evaluagent.com/us/quality-assurance/"}], "summary": "面向联络中心的商业质量管理产品：以可配置评分卡评估坐席的录音与工单交互，并支持校准、申诉、辅导和质检工作流；未做运行验证。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gong','Gong','{"homepage": "https://gong.io/", "id": "commercial:gong", "leaf_matches": [{"reason": "Gong 官方入门文档正文说明其自动录制并转写 calls、emails、meetings 等客户交互，持续分析对话以识别影响交易的模式与关键时刻，面向销售代表、经理和领导层提供组织级使用，并与 CRM 集成，覆盖捕获对话-机器转录-衍生信号-组织级访问的核心。文档另述销售参与、交易健康与预测等收入智能能力，本关系不据此扩展。", "slug": "conversation-intelligence-platform", "source_urls": ["https://help.gong.io/docs/getting-started-welcome-to-gong.md"]}], "name": "Gong", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T11:56:20.282666+08:00", "kind": "documentation", "sha256": "a9e85bff8a353b2aa00b3e2be17654518e355829af7f356836b4849d2fbacf97", "snapshot_path": "sources/a9e85bff8a353b2aa00b3e2be17654518e355829af7f356836b4849d2fbacf97.txt", "url": "https://help.gong.io/docs/getting-started-welcome-to-gong.md"}], "summary": "商业对话智能平台：自动录制并转写通话、邮件、会议等客户交互，识别影响交易的模式与关键时刻，提供团队级分析与 CRM 集成；仅记录基本用途，未做运行验证。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:278604441','Tiledesk','{"deployment": ["README 提供 Docker Compose 与 Kubernetes/Helm 自托管部署", "部署内容含 Tiledesk Server、Dashboard、Design Studio、Chat21 Ionic/Web Widget/Server/Http Server、MongoDB 和代理", "MIT 证据仅覆盖 Tiledesk/tiledesk 部署编排仓库；官方组件清单将各组件列为 MIT，但组织元数据显示 Dashboard、Design Studio、Chat21 Web Widget、Chat21 Ionic 为 MIT，Android/iOS 坐席应用为 AGPL-3.0；Server 公开源仓库当前 404，未直接核验", "Enterprise 版本需单独凭据拉取私有镜像，README 未逐项列出 Enterprise 功能边界"], "features": ["开源实时聊天平台，集成聊天机器人，面向 Web、Android、iOS 渠道", "可视化机器人脚本一次配置、多渠道自适应回复", "机器人可将会话转交人工坐席：提供 Agent handoff intent/template，并可按部门 round-robin 分配给可用坐席、支持 pooled 未分配队列", "Dashboard Monitor 与 Agent Web Chat 的会话详情面板供坐席查看会话、参与者和备注并接管回复", "会话作为 request 持久记录，含 transcript、participatingAgents/Bots、hasBot、status、分配/关闭时间和备注", "通过 REST API、Webhook 与外部应用集成"], "github_repository_id": 278604441, "homepage": "https://tiledesk.com/", "id": "github:278604441", "leaf_matches": [{"reason": "README 将其定位为开源 Live Chat + integrated Chatbots，支持 Web/Android/iOS 多渠道与机器人脚本；官方文档补足三个核心结构：预聊天表单教程描述机器人把同一会话 handoff 给人工坐席、坐席在 conversation panel 读取用户数据并接管；架构文档说明 Automation Designer 配置 human handoff 规则、Dashboard/Agent Web Chat 及移动端应用供坐席 take over、MongoDB 保存会话历史；Requests API 与 transcript-on-close 教程把会话保存为 request/transcript 记录，含参与坐席/机器人、hasBot、状态、分配/关闭时间和备注；custom-assignment 教程说明按部门 round-robin 或 pooled 队列分配给坐席。", "slug": "customer-service-chatbot-platform", "source_urls": ["https://raw.githubusercontent.com/Tiledesk/tiledesk/master/README.md", "https://developer.tiledesk.com/widget/widget-app-introduction/widget-app-prechat-form.md", "https://developer.tiledesk.com/architecture/schema.md", "https://developer.tiledesk.com/apis/rest-api/requests.md", "https://developer.tiledesk.com/apis/tutorials/webhooks/get-transcript-on-close.md", "https://developer.tiledesk.com/apis/tutorials/webhooks/custom-assignment-pooled.md", "https://developer.tiledesk.com/architecture/components.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Tiledesk/tiledesk/license", "license_review": {"rationale": "MIT 全文与 SPDX 标记来自部署编排仓库 Tiledesk/tiledesk 的 license API；本许可只覆盖该仓库，不概括全部社区组件（含 AGPL-3.0 的移动坐席应用）或 Enterprise 私有镜像。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://api.github.com/repos/Tiledesk/tiledesk/license", "spdx_id": "MIT"}, "name": "Tiledesk", "repository_url": "https://github.com/Tiledesk/tiledesk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:36:29.592630+08:00", "kind": "repository_metadata", "sha256": "fe168d0ee9eaf7df8a8b2d60b2f9b4f6ceca2fc4843f7dae04a437b7ccc1a546", "snapshot_path": "sources/fe168d0ee9eaf7df8a8b2d60b2f9b4f6ceca2fc4843f7dae04a437b7ccc1a546.txt", "url": "https://api.github.com/repos/Tiledesk/tiledesk"}, {"fetched_at": "2026-10-26T16:36:35.011801+08:00", "kind": "license", "sha256": "64fd1010575d00a8eeb3407424a53db80dcb6da3e94214b4a61c28e30e97ea3c", "snapshot_path": "sources/64fd1010575d00a8eeb3407424a53db80dcb6da3e94214b4a61c28e30e97ea3c.txt", "url": "https://api.github.com/repos/Tiledesk/tiledesk/license"}, {"fetched_at": "2026-10-26T16:36:35.024303+08:00", "kind": "readme", "sha256": "13ce06c039f294676058218f662dbac3d4d0816646e802e4a539af78f13a23b6", "snapshot_path": "sources/13ce06c039f294676058218f662dbac3d4d0816646e802e4a539af78f13a23b6.txt", "url": "https://raw.githubusercontent.com/Tiledesk/tiledesk/master/README.md"}, {"fetched_at": "2026-10-26T16:49:53.607168+08:00", "kind": "documentation", "sha256": "b42ce288b99c378eb2893d6896f5d02d3520a0cb1049aa0c85f22bfc1042f269", "snapshot_path": "sources/b42ce288b99c378eb2893d6896f5d02d3520a0cb1049aa0c85f22bfc1042f269.txt", "url": "https://developer.tiledesk.com/apis/tutorials/webhooks/get-transcript-on-close.md"}, {"fetched_at": "2026-10-26T16:49:54.981415+08:00", "kind": "documentation", "sha256": "7072f89c563ed4bfbd17b8bb3810cbaa837ebe0b5a5eac504b1efc1cf5e18f0c", "snapshot_path": "sources/7072f89c563ed4bfbd17b8bb3810cbaa837ebe0b5a5eac504b1efc1cf