INSERT INTO "application" VALUES('github:245541','Request Tracker (RT)','{"deployment": ["自托管部署（Perl Web 应用）", "支持 MySQL/MariaDB/PostgreSQL/Oracle", "Apache 或 nginx + FastCGI/mod_perl"], "features": ["队列化跟踪工单与请求", "可配置工单生命周期、状态与流转", "邮件网关创建和更新工单", "内部备注与对外回复分离", "工单历史、搜索与仪表板", "用户、组、队列级权限与 scrip 自动化"], "github_repository_id": 245541, "homepage": "https://bestpractical.com/rt", "id": "github:245541", "leaf_matches": [{"reason": "官方 README 自述为开源问题与工单跟踪系统；6.0.2 文档展示按队列建单、可配置工单生命周期/状态流转，以及 comment 内部备注与 reply 对外回复的结构性分离，符合工单作为受跟踪需求记录的核心。", "slug": "ticketing-system", "source_urls": ["https://raw.githubusercontent.com/bestpractical/rt/stable/README.md", "https://docs.bestpractical.com/rt/6.0.2/working_with_rt.html", "https://docs.bestpractical.com/rt/6.0.2/customizing/lifecycles.html"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/bestpractical/rt/license", "name": "Request Tracker (RT)", "repository_url": "https://github.com/bestpractical/rt", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:42:18.314738+08:00", "kind": "repository_metadata", "sha256": "8ff6802a4c7683170559b4b1345fb209b267d0cd2a636ce639962af1b373a9a8", "snapshot_path": "sources/8ff6802a4c7683170559b4b1345fb209b267d0cd2a636ce639962af1b373a9a8.txt", "url": "https://api.github.com/repos/bestpractical/rt"}, {"fetched_at": "2026-10-26T16:42:20.656265+08:00", "kind": "license", "sha256": "545bebc68d9476e95bc4409ea4aef14c8969cc496decf6b4352599e84e362828", "snapshot_path": "sources/545bebc68d9476e95bc4409ea4aef14c8969cc496decf6b4352599e84e362828.txt", "url": "https://api.github.com/repos/bestpractical/rt/license"}, {"fetched_at": "2026-10-26T16:42:22.030008+08:00", "kind": "readme", "sha256": "23dd4009c0dd4bb6a0514b942c598ea8b79bc5103aa6cd6773f88085584f12a1", "snapshot_path": "sources/23dd4009c0dd4bb6a0514b942c598ea8b79bc5103aa6cd6773f88085584f12a1.txt", "url": "https://raw.githubusercontent.com/bestpractical/rt/stable/README.md"}, {"fetched_at": "2026-10-26T16