INSERT INTO "application" VALUES('commercial:ruleguard','Ruleguard','{"homepage": "https://www.ruleguard.com/", "id": "commercial:ruleguard", "leaf_matches": [{"reason": "官方投诉管理方案页正文展示投诉从受理、分类、调查到解决的受治理流程，含可配置阶段、自动通知、截止日期跟踪、升级规则、FOS 转介时间线、记录留存与趋势分析，符合投诉记录+生命周期+升级路径核心。", "slug": "complaint-escalation-management", "source_urls": ["https://www.ruleguard.com/solutions/complaint-management-software"]}], "name": "Ruleguard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:43:08.987042+08:00", "kind": "documentation", "sha256": "cb8d651e79976c4550b61bc8242fc69bc88e9922b2ad6cd1939a5f7b379b85d4", "snapshot_path": "sources/cb8d651e79976c4550b61bc8242fc69bc88e9922b2ad6cd1939a5f7b379b85d4.txt", "url": "https://www.ruleguard.com/solutions/complaint-management-software"}], "summary": "Ruleguard 是面向受监管金融企业的投诉管理软件，覆盖投诉受理、分类、调查、解决、截止日期跟踪、升级规则、审计留痕与根因趋势分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:79280946','Fider','{"deployment": ["Docker 自托管", "自有服务器自托管", "官方 Fider Cloud 托管（开源代码可自托管）"], "features": ["反馈帖子与功能请求", "投票、评论与标签", "相似帖检索与重复帖标记", "状态流转与官方回复", "帖子审核与协作者权限", "用户归属与 API 集成"], "github_repository_id": 79280946, "homepage": "https://fider.io", "id": "github:79280946", "leaf_matches": [{"reason": "官方 README 与 API 文档展示反馈帖子、用户归属、投票/评论/标签、相似帖检索、重复帖标记、状态流水线与官方回复，符合反馈记录、跨客户整合和受管理流水线核心。", "slug": "customer-feedback-management", "source_urls": ["https://raw.githubusercontent.com/getfider/fider/main/README.md", "https://docs.fider.io/api/posts/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/getfider/fider/license", "name": "Fider", "repository_url": "https://github.com/getfider/fider", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T16:43:19.630785+08:00", "kind": "repository_metadata", "sha256": "8e29fdfed55bfd662289651776353ed9e258320fabbd212215a82e48a0e74b40", "snapshot_path": "sources/8e29fdfed55bfd662289651776353ed9e258320fabbd212215a82e48a0e74b40.txt", "url": "https://api.github.com/repos/getfider/fider"}, {"fetched_at": "2026-10-26T16:43:22.391244+08:00", "kind": "license", "sha256": "0282b5a19787837b92d91950ece96248bbc0ab44743b759c77f6e0c448911371", "snapshot_path": "sources/0282b5a19787837b92d91950ece96248bbc0ab44743b759c77f6e0c448911371.txt", "url": "https://api.github.com/repos/getfider/fider/license"}, {"fetched_at": "2026-10-26T16:43:23.842966+08:00", "kind": "readme", "sha256": "8a07f0741bd5d3043999db7a1b9b0e2ab04b82d9fb4a4bf791ec58cb1a6e0f59", "snapshot_path": "sources/8a07f0741bd5d3043999db7a1b9b0e2ab04b82d9fb4a4bf791ec58cb1a6e0f59.txt", "url": "https://raw.githubusercontent.com/getfider/fider/main/README.md"}, {"fetched_at": "2026-10-26T16:43:21.948900+08:00", "kind": "documentation", "sha256": "791b0b2e11f6a567d240b25c94f4a0229fdf9d87d18b6980121a58050cafecfd", "snapshot_path": "sources/791b0b2e11f6a567d240b25c94f4a0229fdf9d87d18b6980121a58050cafecfd.txt", "url": "https://docs.fider.io/"}, {"fetched_at": "2026-10-26T16:43:45.283524+08:00", "kind": "documentation", "sha256": "9f783d425aa6ca55161a6b0fc513eb12a0040aea5424cd783450edcd30690a48", "snapshot_path": "sources/9f783d425aa6ca55161a6b0fc513eb12a0040aea5424cd783450edcd30690a48.txt", "url": "https://docs.fider.io/guides/"}, {"fetched_at": "2026-10-26T16:43:57.564591+08:00", "kind": "documentation", "sha256": "e4dda5d751cb76b353ddf7957530fb04c685173d8c13672001a8daf5edab48bf", "snapshot_path": "sources/e4dda5d751cb76b353ddf7957530fb04c685173d8c13672001a8daf5edab48bf.txt", "url": "https://docs.fider.io/api/"}, {"fetched_at": "2026-10-26T16:44:15.497511+08:00", "kind": "documentation", "sha256": "3a3e31002edb6cb21a310f1935ee982884e22794e2acae35b61755e33f293504", "snapshot_path": "sources/3a3e31002edb6cb21a310f1935ee982884e22794e2acae35b61755e33f293504.txt", "url": "https://docs.fider.io/api/posts/"}], "summary": "Fider 是开源客户反馈与功能请求门户，支持提交帖子、投票、评论、标签、相似帖提示、状态流转（open/started/planned/completed/declined/duplicate）和审核，可自托管或使用官方云服务。", "technology_stack": ["Go", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zoho-expense','Zoho Expense','{"homepage": "https://www.zoho.com", "id": "commercial:zoho-expense", "leaf_matches": [{"reason": "官方费用报告页正文说明报告自动编号与命名、按报告类型限制可添加的费用类型、归集后提交审批；同页 Policies/Expense Rules 说明违规可提示或阻止提交，Reimbursement 段原文说明“Sync settlements with payroll and ERP software…delivered directly to their accounts”，Corporate Card Reconciliation 段原文说明“fetch card feeds instantly…automatically match and reconcile your business expenses…reconciliation overview”。首页另列出收据采集、审批、政策审计与实时公司卡流水/自动匹配。可支持以费用报告为记录单位、组织政策校验、非报销人审批，以及报销付款与公司卡对账两种财务完成形态；不另主张工资/ERP 的具体接口或直接付款为独立功能。", "slug": "expense-management-platform", "source_urls": ["https://www.zoho.com/expense/", "https://www.zoho.com/expense/expense-reports/"]}], "name": "Zoho Expense", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:21:53.211783+08:00", "kind": "documentation", "sha256": "d880de994d6b9542a98722a55464edb312f7884ba15efa7f7961d3d261802d12", "snapshot_path": "sources/d880de994d6b9542a98722a55464edb312f7884ba15efa7f7961d3d261802d12.txt", "url": "https://www.zoho.com/expense/"}, {"fetched_at": "2026-10-24T16:34:58.535652+08:00", "kind": "documentation", "sha256": "fcbb8e238c2fc447c6427ed362e887424e85a30a76efc4c4facd2329632175a9", "snapshot_path": "sources/fcbb8e238c2fc447c6427ed362e887424e85a30a76efc4c4facd2329632175a9.txt", "url": "https://www.zoho.com/expense/expense-reports/"}], "summary": "费用报销管理产品，以费用报告为记录单位，支持收据、政策校验、审批，以及报销付款与公司卡对账。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:552877440','Hyperswitch','{"deployment": ["Docker/Podman 本地部署（scripts/setup.sh）", "AWS/GCP/Azure Helm 云部署", "SaaS 托管/沙箱", "Control Center 管理界面"], "features": ["统一支付API对接120+处理商", "智能路由、重试与支付方式编排", "PCI合规卡片保管库与统一结算观测"], "github_repository_id": 552877440, "homepage": "https://hyperswitch.io", "id": "github:552877440", "leaf_matches": [{"reason": "官方 README 说明其以统一接入连接 Stripe、Adyen 等 120 多家处理商，提供智能路由与重试逻辑；商户可在 Control Center 配置连接器与路由工作流，每个连接器有独立的凭证配置指南，覆盖多提供方路径、单一标准化入口与路由控制。", "slug": "payment-orchestration-platform", "source_urls": ["https://api.github.com/repos/juspay/hyperswitch", "https://api.github.com/repos/juspay/hyperswitch/license", "https://raw.githubusercontent.com/juspay/hyperswitch/main/README.md", "https://docs.hyperswitch.io/about-hyperswitch"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/juspay/hyperswitch/license", "name": "Hyperswitch", "repository_url": "https://github.com/juspay/hyperswitch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T17:12:29.747995+08:00", "kind": "repository_metadata", "sha256": "6c4bb5a9b15cdcd53a19bcd66096fa20b33a37465af166d82d5e98645b0995f3", "snapshot_path": "sources/6c4bb5a9b15cdcd53a19bcd66096fa20b33a37465af166d82d5e98645b0995f3.txt", "url": "https://api.github.com/repos/juspay/hyperswitch"}, {"fetched_at": "2026-10-24T17:12:31.512738+08:00", "kind": "license", "sha256": "9843204b245d1e5f29f23d39f1938f79d16078767e21387b4e5309a21174daf3", "snapshot_path": "sources/9843204b245d1e5f29f23d39f1938f79d16078767e21387b4e5309a21174daf3.txt", "url": "https://api.github.com/repos/juspay/hyperswitch/license"}, {"fetched_at": "2026-10-24T16:15:47.355658+08:00", "kind": "readme", "sha256": "58117e63d3e61fbaf9ded8ec7083ed9e6f0a53d28e9ba5d8c6a3223a9a8806f7", "snapshot_path": "sources/58117e63d3e61fbaf9ded8ec7083ed9e6f0a53d28e9ba5d8c6a3223a9a8806f7.txt", "url": "https://raw.githubusercontent.com/juspay/hyperswitch/main/README.md"}, {"fetched_at": "2026-10-24T16:56:06.231936+08:00", "kind": "documentation", "sha256": "4a73085ee3f4e21047e7b09dcc6b1448939e5b1466b99d1e5f9acab2b3dbe766", "snapshot_path": "sources/4a73085ee3f4e21047e7b09dcc6b1448939e5b1466b99d1e5f9acab2b3dbe766.txt", "url": "https://docs.hyperswitch.io/about-hyperswitch"}], "summary": "开源可组合支付编排平台，以单一接入连接多家支付处理商并提供路由、重试与统一观测。", "technology_stack": ["Rust"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:procurify','Procurify','{"homepage": "https://www.procurify.com", "id": "commercial:procurify", "leaf_matches": [{"reason": "官方平台页正文覆盖 Intake-to-Approve 采购申请与审批、Purchase-to-Receive 订单/收货、Invoice-to-Pay 发票匹配与账单付款，正文并列出 Approval Routing、budgets/policies、Audit Trails 与 ERP integrations；另抓取的官方 Expense & Card 页正文说明可发行虚拟/实体 Spending Cards、以预批预算限额控制卡支出，并提供移动收据采集、费用报告审批和公司卡/报销的统一管理。两组正文共同支持申请、卡、发票、报销多渠道及集中预算政策控制。", "slug": "spend-management-platform", "source_urls": ["https://www.procurify.com/", "https://www.procurify.com/procure-to-pay/expense-and-card/"]}], "name": "Procurify", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:15:49.896092+08:00", "kind": "homepage", "sha256": "06beab4bc6d9d038bec2a408f3b13d8e90fa344c619c5bf398845c9ef5a35845", "snapshot_path": "sources/06beab4bc6d9d038bec2a408f3b13d8e90fa344c619c5bf398845c9ef5a35845.txt", "url": "https://www.procurify.com/"}, {"fetched_at": "2026-10-26T12:39:05.395827+08:00", "kind": "documentation", "sha256": "e63b6f3ff439fee7da19d46447fe833e90f28bc3f8f457f3c630b5d6e45a4892", "snapshot_path": "sources/e63b6f3ff439fee7da19d46447fe833e90f28bc3f8f457f3c630b5d6e45a4892.txt", "url": "https://www.procurify.com/procure-to-pay/expense-and-card/"}], "summary": "采购与支出管理平台，将采购申请、订单、发票付款、公司卡与费用报销纳入统一预算与审批。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:oracle-banking-payments','Oracle Banking Payments','{"homepage": "https://oracle.com", "id": "commercial:oracle-banking-payments", "leaf_matches": [{"reason": "官方用户指南说明支付因校验失败进入 Repair Queue，由后台运营人员编辑修复后重新提交；异常队列目录另列授权限额、处理截止与结算复核等队列，View Queue Action 可查看该交易的全部队列活动；Security Guide 说明系统维护用户登录后全部活动与所调用功能的审计轨迹。原交易录入链接返回 404，因此不再主张交易录入。上述来源覆盖员工端交易记录、处理管线、异常路径与持久审计。", "slug": "banking-back-office-platform", "source_urls": ["https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue.html", "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/exception-investigation-queues-internal.html", "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue_repair-action.html", "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/toc.htm", "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue_view-queue-action.html", "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpsg/audit-trail-report.html"]}], "name": "Oracle Banking Payments", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:15:51.472543+08:00", "kind": "documentation", "sha256": "3e1c2a05aec242864ada5af8143c16726004f662f36564e9ab073fd6f44aac01", "snapshot_path": "sources/3e1c2a05aec242864ada5af8143c16726004f662f36564e9ab073fd6f44aac01.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue.html"}, {"fetched_at": "2026-10-24T16:35:04.172978+08:00", "kind": "documentation", "sha256": "99722e411e8bd3f95a2a365f1baa12959de271bbb345f48c930db81e9f8b4f5e", "snapshot_path": "sources/99722e411e8bd3f95a2a365f1baa12959de271bbb345f48c930db81e9f8b4f5e.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/exception-investigation-queues-internal.html"}, {"fetched_at": "2026-10-24T16:33:07.524547+08:00", "kind": "documentation", "sha256": "7b81cab84ddf7ee08da38d8c5ccf71872bc3c423d458c45aad8261e762a9bc08", "snapshot_path": "sources/7b81cab84ddf7ee08da38d8c5ccf71872bc3c423d458c45aad8261e762a9bc08.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue_repair-action.html"}, {"fetched_at": "2026-10-26T12:28:45.522790+08:00", "kind": "documentation", "sha256": "2924fc2235b2da1469665f5d3bdf2b7662da5d2b1f21d259a1d5a59f5e70989a", "snapshot_path": "sources/2924fc2235b2da1469665f5d3bdf2b7662da5d2b1f21d259a1d5a59f5e70989a.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/toc.htm"}, {"fetched_at": "2026-10-26T12:29:19.746934+08:00", "kind": "documentation", "sha256": "b654511117de060a82354344dd1bca37833650ad188e48fb69276ad7c527593f", "snapshot_path": "sources/b654511117de060a82354344dd1bca37833650ad188e48fb69276ad7c527593f.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpeq/repair-queue_view-queue-action.html"}, {"fetched_at": "2026-10-26T12:29:45.207669+08:00", "kind": "documentation", "sha256": "eb01da9e2a1457577833f5cc7a655b1e4b6c980656beaf47cc43b183fa02d368", "snapshot_path": "sources/eb01da9e2a1457577833f5cc7a655b1e4b6c980656beaf47cc43b183fa02d368.txt", "url": "https://docs.oracle.com/en/industries/financial-services/banking-payments/14.7.0.0.0/obpsg/audit-trail-report.html"}], "summary": "银行支付后台处理系统，提供支付异常、授权限额与修复队列，支持修复后重新提交，并可查看队列动作历史与系统审计轨迹。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:backbase-banking-operations','Backbase Banking Operations','{"homepage": "https://www.backbase.com", "id": "commercial:backbase-banking-operations", "leaf_matches": [{"reason": "官方 Banking Operations 页正文按五个运营域展开：“01 Customer Operations”段写明 “SLA tracking built in”；“03 Payments Operations”段写明失败支付、对账差额、合规保留等进入队列，系统 “clears the backlog”，代理按类型与严重度分类并 “route them to the right team”，员工处理 “overrides, escalations, manual reconciliation”；FAQ 段写明预建核心/支付/卡/借贷/KYC/AML/欺诈/CRM/文档连接器且 “Events stream in real time”。官方 Banking OS 页以勾选项列出 “Completed cases / Employee effort / Backlog”，并在采购问题中以 “completion time, repeat contacts, employee effort and rework” 作为价值基线。上述正文支持运营队列的统一可见性、对工作的路由/升级/清理动作和服务目标跟踪，也符合本类型“管理界面嵌入执行平台”的交付形态；页面同时承载案件工作流与执行编排，并非纯管理仪表盘。未找到人员排班/容量调整或按团队/个人归因的生产率与质量度量，故不主张 workforce 管理。", "slug": "banking-operations-management", "source_urls": ["https://www.backbase.com/solutions/banking-operations", "https://www.backbase.com/banking-os"]}], "name": "Backbase Banking Operations", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T16:28:08.468366+08:00", "kind": "documentation", "sha256": "05d23c59c7fde2f5397478216f91641a3f5040fb1c76c424cb85f21e9298182b", "snapshot_path": "sources/05d23c59c7fde2f5397478216f91641a3f5040fb1c76c424cb85f21e9298182b.txt", "url": "https://www.backbase.com/solutions/banking-operations"}, {"fetched_at": "2026-10-26T12:39:18.583916+08:00", "kind": "documentation", "sha256": "d994ff456441355825410f316940741b97ca701589361bd299a6c3563ef32a83", "snapshot_path": "sources/d994ff456441355825410f316940741b97ca701589361bd299a6c3563ef32a83.txt", "url": "https://www.backbase.com/banking-os"}], "summary": "面向银行的运营管理工作台，承载客户、支付/争议、借贷与风控运营的案件与异常，提供按类型/严重度的队列路由、override/升级/人工对账、SLA 跟踪与决策审计。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:international-sos','International SOS','{"homepage": "https://www.internationalsos.com/", "id": "commercial:international-sos", "leaf_matches": [{"reason": "官方 Travel Risk Management 页面写明将核实情报整合进行程、提供实时威胁监控与即时警报，并通过 Monitoring & Location Tracking 展示定位、实时行程、双向沟通和定向警报，匹配在途人员—风险监控—保护通信闭环。", "slug": "travel-risk-duty-of-care-platform", "source_urls": ["https://www.internationalsos.com/services/travel-risk-management"]}], "name": "International SOS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:38:11.557883+08:00", "kind": "documentation", "sha256": "168e5fda8a443d0adb2ef6403a5217c0fde23b83c7bcaf235cfad54c8daf2fa4", "snapshot_path": "sources/168e5fda8a443d0adb2ef6403a5217c0fde23b83c7bcaf235cfad54c8daf2fa4.txt", "url": "https://www.internationalsos.com/services/travel-risk-management"}], "summary": "面向企业差旅风险与关怀职责的全球服务与平台，结合核实情报、行程与位置跟踪、双向沟通、定向警报以及 24/7 医疗与安保支持。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:case-iq','Case IQ','{"homepage": "https://www.caseiq.com/", "id": "commercial:case-iq", "leaf_matches": [{"reason": "官网正文明确从 intake 捕获事件、以可配置工作流管理案件、保留每一步行动的 full audit trails、按角色限制访问并生成 one-click investigation reports，匹配保密案件、受管生命周期与事实记录核心。", "slug": "corporate-investigation-management", "source_urls": ["https://www.caseiq.com/"]}], "name": "Case IQ", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:38:03.773074+08:00", "kind": "homepage", "sha256": "6e6b0983ff0d677e63865a6335e723dc125f3e5845d52177cd1d61c12bc56779", "snapshot_path": "sources/6e6b0983ff0d677e63865a6335e723dc125f3e5845d52177cd1d61c12bc56779.txt", "url": "https://www.caseiq.com/"}], "summary": "面向道德与合规、HR、安保及调查团队的调查案件管理平台，覆盖多渠道受理、可配置工作流、角色权限、完整审计轨迹、AI 辅助与调查报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1024847928','Tazama Case and Investigation Management System','{"deployment": ["NestJS 后端 + React 前端的自托管部署", "PostgreSQL 数据库与 Keycloak 认证服务", "仓库提供 Docker 服务配置"], "features": ["从交易告警或手工输入创建案件，按案件 ID 管理分诊、分配与调查", "证据上传、任务记录、案件笔记与调查摘要", "结案处置结果（Closed Refuted/Confirmed/Inconclusive）与监督审批", "按角色限制案件可见范围，合规官仅见确认结案案件", "不可变案件时间线、评论审计、调查报告生成与归档"], "github_repository_id": 1024847928, "homepage": "https://github.com/tazama-lf/case-management-system", "id": "github:1024847928", "leaf_matches": [{"reason": "官方用户手册与 README 共同证明：案件按 ID 贯穿分诊、分配、证据收集、调查记录、结案与报告；结案时调查员必须选择 Closed Refuted/Confirmed/Inconclusive 处置结果并附调查结论，由监督者审批或退回，报告锁定并归档；角色权限限制案件可见范围（合规官仅见 Closed Confirmed），审计轨迹不可变。该系统面向金融欺诈/AML 交易告警案件，不是通用 HR/道德调查；但案件生命周期、事实记录、记录在案的决定与按角色保密四项核心均有官方正文。", "slug": "corporate-investigation-management", "source_urls": ["https://raw.githubusercontent.com/tazama-lf/case-management-system/main/README.md", "https://raw.githubusercontent.com/tazama-lf/docs/dev/Guides/User%20Manuals%20for%20Downloading/Tazama%20Case%20Management%20System%20-%20User%20Manual.docx"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/tazama-lf/case-management-system/license", "name": "Tazama Case and Investigation Management System", "repository_url": "https://github.com/tazama-lf/case-management-system", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:37:31.050550+08:00", "kind": "repository_metadata", "sha256": "0da21742fb89b8b0397f28888ffc01fdabfcabfb3a868509bf4d694fa0b887c4", "snapshot_path": "sources/0da21742fb89b8b0397f28888ffc01fdabfcabfb3a868509bf4d694fa0b887c4.txt", "url": "https://api.github.com/repos/tazama-lf/case-management-system"}, {"fetched_at": "2026-10-26T17:37:40.467732+08:00", "kind": "license", "sha256": "eb576df0dd73d9cf82a557ae693e9a44fe0ecb770ac36a30eee7fb00482573d3", "snapshot_path": "sources/eb576df0dd73d9cf82a557ae693e9a44fe0ecb770ac36a30eee7fb00482573d3.txt", "url": "https://api.github.com/repos/tazama-lf/case-management-system/license"}, {"fetched_at": "2026-10-26T17:37:38.709954+08:00", "kind": "readme", "sha256": "40cc9e53b2ff1ac769427ba6eada64ed59095ed8087b823e835df5e0c79f5ce4", "snapshot_path": "sources/40cc9e53b2ff1ac769427ba6eada64ed59095ed8087b823e835df5e0c79f5ce4.txt", "url": "https://raw.githubusercontent.com/tazama-lf/case-management-system/main/README.md"}, {"fetched_at": "2026-10-26T17:49:11.773157+08:00", "kind": "documentation", "sha256": "1fb4bd89325180f36610406a5219a15eb31234b5e8cea15cb1fd61df14192086", "snapshot_path": "sources/1fb4bd89325180f36610406a5219a15eb31234b5e8cea15cb1fd61df14192086.txt", "url": "https://raw.githubusercontent.com/tazama-lf/docs/dev/Guides/User%20Manuals%20for%20Downloading/Tazama%20Case%20Management%20System%20-%20User%20Manual.docx"}], "summary": "开源、自托管的金融欺诈/AML 交易告警案件管理平台，围绕案件、证据、分诊、任务、审计与报告组织调查工作流；结案需选择处置结果并经监督审批，合规角色仅能查看已确认结案的案件。", "technology_stack": ["NestJS", "React + TypeScript + Vite", "PostgreSQL", "Keycloak", "CouchDB / Flowable BPMN"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:relativity','Relativity','{"homepage": "https://www.relativity.com/", "id": "commercial:relativity", "leaf_matches": [{"reason": "官方 eDiscovery 页明确 preserve and collect ESI、process at scale、accelerate review with AI，并写明 intake to production；同页列出 legal hold、review 与 production，覆盖事项语料—审阅判定—生产交付核心。", "slug": "ediscovery-platform", "source_urls": ["https://www.relativity.com/platform/ediscovery/", "https://www.relativity.com/"]}], "name": "Relativity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:38:51.798454+08:00", "kind": "homepage", "sha256": "23a98cb0b23fe2fb860b2910d7b957a265d35a94bbabf8200d8e39745e2e03fa", "snapshot_path": "sources/23a98cb0b23fe2fb860b2910d7b957a265d35a94bbabf8200d8e39745e2e03fa.txt", "url": "https://www.relativity.com/"}, {"fetched_at": "2026-10-26T17:39:03.224169+08:00", "kind": "documentation", "sha256": "1dc91c26194d96ab5c2849639094c1314618b8d4769e70832cdb5fb56cbe66ff", "snapshot_path": "sources/1dc91c26194d96ab5c2849639094c1314618b8d4769e70832cdb5fb56cbe66ff.txt", "url": "https://www.relativity.com/platform/ediscovery/"}], "summary": "面向法律团队的 eDiscovery 与法律数据平台，覆盖 ESI 保全与收集、规模化处理、AI 辅助审阅、法律保留以及 production 交付。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:immibox','ImmiBox','{"homepage": "https://immibox.com/", "id": "commercial:immibox", "leaf_matches": [{"reason": "官方 features 正文写明其为移民案件管理解决方案，含案件生命周期与工作流、移民表格、USCIS/DOL e-filing、文件、截止日期、计费与发票。", "slug": "immigration-practice-management", "source_urls": ["https://immibox.com/features"]}], "name": "ImmiBox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:39:37.261591+08:00", "kind": "homepage", "sha256": "66599e66308ad989515c3f1cec1ddc540c9851c5f1b4df7791454f77daac2346", "snapshot_path": "sources/66599e66308ad989515c3f1cec1ddc540c9851c5f1b4df7791454f77daac2346.txt", "url": "https://immibox.com/features"}], "summary": "ImmiBox 是面向移民律所的云端移民案件管理平台，覆盖案件与工作流、移民表格、USCIS/DOL 电子提交、计费发票、文件与截止日期管理。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1331339595','DeedBox','{"deployment": ["Node.js 20+", "PostgreSQL 及扩展"], "features": ["事项与当事人管理", "时间与计费", "账单与信用票据", "信托资金与对账", "工作流与关键日期"], "github_repository_id": 1331339595, "homepage": "https://github.com/deedbox-maintainers/deedbox-app", "id": "github:1331339595", "leaf_matches": [{"reason": "README 描述 DeedBox 为律所开源实务管理系统，包含事项、当事人、时间计费、账单、信托资金和工作流。", "slug": "law-practice-management-system", "source_urls": ["https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/README.md"]}, {"reason": "README 说明该系统含“matters and conflicts”，并对当事人、关系与受限事项做冲突核查；conflicts/page.tsx 显示检索覆盖事务所记录过的名称（现用/曾用/商号、事项与收案当事人、既往检查快照内名称）并做模糊匹配，结果永久快照，登记册含 Searched/By/When/Attached/Resolution，未处置的检查显示 unresolved；runConflictCheck.ts 实现名称索引（fold/phonetic + trigram≥0.4）、matter/intake/历史快照检索、registered_text 语料与 restricted-match 针孔，并向 conflict_check 写入 terms 与 result_snapshot 的不变快照；conflictRecords.ts 的 recordConflictResolution 以查重拒绝第二条处置、要求 conflict_found_action_taken 必须给出 actionNote，并写入 conflict_resolution；createMatter.ts 的 verifyResolvedCheck 在执业领域 require_conflict_resolution 或事务所设置 conflict.required_before_open 开启时，强制要求提供已记录处置、且未附加他处的检查，否则以 conflict_check_required / conflict_check_unresolved / conflict_check_attached 拒绝开立事项。据此，关系宇宙、结构化留存检查、命中与处置记录、可配置的准入闸门四层均有代码依据；检查本身可以先运行并保持 unresolved，闸门只在启用配置的开立事项环节生效。", "slug": "legal-conflict-checking-platform", "source_urls": ["https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/README.md", "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/app/%28app%29/conflicts/page.tsx", "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/runConflictCheck.ts", "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/conflictRecords.ts", "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/createMatter.ts"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/deedbox-maintainers/deedbox-app/license", "name": "DeedBox", "repository_url": "https://github.com/deedbox-maintainers/deedbox-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:22:23.766293+08:00", "kind": "repository_metadata", "sha256": "2abe8a4e305faa37372bcc52d0bb56f61c0f08671e3a6e10252c440725c23572", "snapshot_path": "sources/2abe8a4e305faa37372bcc52d0bb56f61c0f08671e3a6e10252c440725c23572.txt", "url": "https://api.github.com/repos/deedbox-maintainers/deedbox-app"}, {"fetched_at": "2026-10-24T22:22:26.404319+08:00", "kind": "license", "sha256": "5f3719e2115a67b925c5c82c568a0d4e0164d66a51f6c642f46c6d5f4588831e", "snapshot_path": "sources/5f3719e2115a67b925c5c82c568a0d4e0164d66a51f6c642f46c6d5f4588831e.txt", "url": "https://api.github.com/repos/deedbox-maintainers/deedbox-app/license"}, {"fetched_at": "2026-10-24T22:22:27.642598+08:00", "kind": "readme", "sha256": "2be4d9b62139df45c2d64cbc0df11d81154dae69169d2597515370b7698d6a32", "snapshot_path": "sources/2be4d9b62139df45c2d64cbc0df11d81154dae69169d2597515370b7698d6a32.txt", "url": "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/README.md"}, {"fetched_at": "2026-10-28T21:39:34.211249+08:00", "kind": "documentation", "sha256": "3949c0ea2dccb44d74f880b99463573a89e536a2fe1ed0744a7619a86d90cfed", "snapshot_path": "sources/3949c0ea2dccb44d74f880b99463573a89e536a2fe1ed0744a7619a86d90cfed.txt", "url": "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/app/%28app%29/conflicts/page.tsx"}, {"fetched_at": "2026-10-28T21:45:45.344950+08:00", "kind": "documentation", "sha256": "7246dc9625029a401c1fb95c3ddbf49621bb7bc5cc51a36d91338c40a2d41c68", "snapshot_path": "sources/7246dc9625029a401c1fb95c3ddbf49621bb7bc5cc51a36d91338c40a2d41c68.txt", "url": "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/conflictRecords.ts"}, {"fetched_at": "2026-10-28T21:45:47.012624+08:00", "kind": "documentation", "sha256": "e622b4d69c2696066d00a32ed5113a52ade7fa0828de8c2eb7b52927b1412e35", "snapshot_path": "sources/e622b4d69c2696066d00a32ed5113a52ade7fa0828de8c2eb7b52927b1412e35.txt", "url": "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/createMatter.ts"}, {"fetched_at": "2026-10-28T21:39:36.092540+08:00", "kind": "documentation", "sha256": "5144d26bacc321fc9cd07127036f5e3c882cc992a4c96b51ca36b79d312439ad", "snapshot_path": "sources/5144d26bacc321fc9cd07127036f5e3c882cc992a4c96b51ca36b79d312439ad.txt", "url": "https://raw.githubusercontent.com/deedbox-maintainers/deedbox-app/main/lib/ops/matters/runConflictCheck.ts"}], "summary": "DeedBox 是面向律所的开源实务管理系统，涵盖事项、当事人、时间计费、账单与信托资金管理。", "technology_stack": ["TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:leanlaw','LeanLaw','{"homepage": "https://www.leanlaw.co/", "id": "commercial:leanlaw", "leaf_matches": [{"reason": "官方首页 FAQ 将其定义为构建在 QuickBooks Online 上的法律计费与会计软件，覆盖 time tracking、billing、trust accounting、payments 与 real-time reporting，并按 hourly、flat-fee、contingency matters 运行；官方时间与费用页写明每条时间可分配 client、matter、timekeeper、rate 与 narrative，费用按 matter 记录，随后进入 invoice review and approval workflow，并支持 UTBMS/LEDES 编码（比较页注明 LEDES 支持随方案而异）；官方比较页进一步写明 client and matter trust workflows with three-way reconciliation、batch billing、online payments，并明确“LeanLaw is not a full case-management suite”“does not try to replace every case, document, intake, or CRM tool”，属于与案件/文档工具并行的 billing-first 财务层，符合本叶独立 money loop 边界。", "slug": "legal-billing-application", "source_urls": ["https://www.leanlaw.co/", "https://www.leanlaw.co/time-expense-tracking/", "https://www.leanlaw.co/best-legal-billing-software/"]}], "name": "LeanLaw", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T12:07:45.893374+08:00", "kind": "homepage", "sha256": "f1321ec5c6c1ae0877bceb2b37cc4054c32fe2acf8f25e16ec3272ae29ee3427", "snapshot_path": "sources/f1321ec5c6c1ae0877bceb2b37cc4054c32fe2acf8f25e16ec3272ae29ee3427.txt", "url": "https://www.leanlaw.co/"}, {"fetched_at": "2026-10-27T12:07:50.669851+08:00", "kind": "documentation", "sha256": "ef2cf7a55b76f22b176c53f0500bdd0f94ade1d6e676630868de9fbe0296029d", "snapshot_path": "sources/ef2cf7a55b76f22b176c53f0500bdd0f94ade1d6e676630868de9fbe0296029d.txt", "url": "https://www.leanlaw.co/best-legal-billing-software/"}, {"fetched_at": "2026-10-27T12:11:47.378344+08:00", "kind": "documentation", "sha256": "e10aee3cf5880398f7c59c5685c8b16ff3f8299b5d43f3a0773f94ce9ef309a8", "snapshot_path": "sources/e10aee3cf5880398f7c59c5685c8b16ff3f8299b5d43f3a0773f94ce9ef309a8.txt", "url": "https://www.leanlaw.co/time-expense-tracking/"}], "summary": "LeanLaw 是面向律所、构建在 QuickBooks Online 上的法律计费与会计软件，覆盖按客户/事项/时间记录员与费率记录时间与费用、账单审核与开票、在线收款、客户/信托账户与三方对账、方案相关的 LEDES 与实时报告；官方明确其为 billing-first 财务层，不替代案件、文档或收案系统。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:one-legal','One Legal','{"homepage": "https://onelegal.com/", "id": "commercial:one-legal", "leaf_matches": [{"reason": "官方产品页正文写明其是加州与内华达法院认可的 eFiling 服务商，Matters 标签可按 matter 查看案件信息、文件、订单状态与发票，提供在线订购与状态跟踪，并可对法院已驳回的提交使用 Re-File；官方帮助文档进一步说明书记员驳回原因在 Order Details 与通知中展示、部分驳回时仅需重新提交被拒文件、已接受文件保留在案件记录中，且法院费用由 One Legal 代付后开票。", "slug": "legal-e-filing-platform", "source_urls": ["https://www.onelegal.com/products/filing", "https://support.onelegal.com/en_US/court-filing/how-to-use-re-file-to-resubmit-rejected-filings", "https://support.onelegal.com/en_US/court-filing/why-did-the-court-reject-my-filing"]}], "name": "One Legal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:39:55.045729+08:00", "kind": "homepage", "sha256": "87389c5715eafa0d8b8c7ac012b1f6db644b04365f60c84987c3e52e80371f9c", "snapshot_path": "sources/87389c5715eafa0d8b8c7ac012b1f6db644b04365f60c84987c3e52e80371f9c.txt", "url": "https://www.onelegal.com/products/filing"}, {"fetched_at": "2026-10-26T17:49:21.305508+08:00", "kind": "documentation", "sha256": "be5cbb5abe6839a8cf17e1cc3a455659d191ed80a8714f27e8e0b0425d819616", "snapshot_path": "sources/be5cbb5abe6839a8cf17e1cc3a455659d191ed80a8714f27e8e0b0425d819616.txt", "url": "https://support.onelegal.com/en_US/court-filing/how-to-use-re-file-to-resubmit-rejected-filings"}, {"fetched_at": "2026-10-26T17:49:34.712536+08:00", "kind": "documentation", "sha256": "4188ae5283a373f8699fcfef420717f1607686aa5a2bfdda8488bb2097bd5d82", "snapshot_path": "sources/4188ae5283a373f8699fcfef420717f1607686aa5a2bfdda8488bb2097bd5d82.txt", "url": "https://support.onelegal.com/en_US/court-filing/why-did-the-court-reject-my-filing"}], "summary": "One Legal 是面向律所的法院电子立案服务（加州、内华达），提供在线提交、按 Matter/Order 查看案件信息与状态、书记员驳回原因展示及被拒文件重新提交，并代付法院费用后开票。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:lawmatics','Lawmatics','{"homepage": "https://www.lawmatics.com/", "id": "commercial:lawmatics", "leaf_matches": [{"reason": "官方 intake 页包含自定义 intake 表单、文件请求、电子签署与客户 onboarding；官方冲突检查页写明在 intake 开始时自动做冲突筛查并可 approve/deny/flag 新客户。", "slug": "legal-intake-client-onboarding", "source_urls": ["https://www.lawmatics.com/client-intake", "https://www.lawmatics.com/conflict-checking"]}], "name": "Lawmatics", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:39:57.351121+08:00", "kind": "homepage", "sha256": "7a3639676e3f3f7dacbafa6aabb6a87ec2b2763cfbcecd8525af764a6b40dae0", "snapshot_path": "sources/7a3639676e3f3f7dacbafa6aabb6a87ec2b2763cfbcecd8525af764a6b40dae0.txt", "url": "https://www.lawmatics.com/client-intake"}, {"fetched_at": "2026-10-26T17:40:18.498903+08:00", "kind": "homepage", "sha256": "f35bd5bacb48b9c606eac79b39720f6402ce53293079259660eb9527b57d70c9", "snapshot_path": "sources/f35bd5bacb48b9c606eac79b39720f6402ce53293079259660eb9527b57d70c9.txt", "url": "https://www.lawmatics.com/conflict-checking"}], "summary": "Lawmatics 是面向律所的法律客户 intake 与 CRM 平台，提供自定义 intake 表单、冲突检查、预约、电子签署与客户入案流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:39464018','Apache Superset','{"deployment": ["官方 README 提供快速开始与生产部署文档入口；本轮未部署"], "features": ["连接具备 Python DB-API / SQLAlchemy 驱动的 SQL 数据源", "无代码图表构建、Web SQL 编辑器与可组合仪表板", "可配置的安全角色与认证选项", "可配置缓存与 API"], "github_repository_id": 39464018, "homepage": "https://superset.apache.org", "id": "github:39464018", "leaf_matches": [{"reason": "官方 README 明确称 Superset 为 \"enterprise-ready business intelligence web application\"，并说明其连接 SQL 数据源、构建图表与仪表板、提供安全角色与认证；匹配 BI 平台的连接—创作—托管—受控访问核心。消费者端与内容级权限细节未在快照展开，未据此扩展断言。", "slug": "business-intelligence-platform", "source_urls": ["https://raw.githubusercontent.com/apache/superset/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/apache/superset/master/LICENSE.txt", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/apache/superset/master/LICENSE.txt", "spdx_id": "Apache-2.0"}, "name": "Apache Superset", "repository_url": "https://github.com/apache/superset", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:54:18.012566+08:00", "kind": "repository_metadata", "sha256": "52250c1d88a27d7f8e3b021788c097023dd040758f6b97b109371397921153a0", "snapshot_path": "sources/52250c1d88a27d7f8e3b021788c097023dd040758f6b97b109371397921153a0.txt", "url": "https://github.com/apache/superset"}, {"fetched_at": "2026-10-24T22:54:33.024738+08:00", "kind": "license", "sha256": "ff254eb676d6ed2b36f26a74e7c50411cd57e11823f3e91004ffe48fcfd273cf", "snapshot_path": "sources/ff254eb676d6ed2b36f26a74e7c50411cd57e11823f3e91004ffe48fcfd273cf.txt", "url": "https://raw.githubusercontent.com/apache/superset/master/LICENSE.txt"}, {"fetched_at": "2026-10-24T22:54:19.904922+08:00", "kind": "readme", "sha256": "0f9fecb2c68733121efe9aaa968a935c0b81b281935e6b24c4455887860fe3c4", "snapshot_path": "sources/0f9fecb2c68733121efe9aaa968a935c0b81b281935e6b24c4455887860fe3c4.txt", "url": "https://raw.githubusercontent.com/apache/superset/master/README.md"}], "summary": "开源商业智能 Web 应用：连接 SQL 数据源，创作图表与仪表板，并以安全角色管理访问。", "technology_stack": ["Python", "SQLAlchemy"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:15111821','Grafana','{"deployment": ["官方安装文档入口（grafana.com/docs 安装指南）；本轮未部署"], "features": ["查询并混合多种数据源，可按查询指定数据源", "创建、探索和共享多面板仪表板（含模板变量与面板插件）", "持续评估告警规则并通知 Slack、PagerDuty 等渠道", "Organization 的 Viewer/Editor/Admin 角色与仪表板、文件夹权限"], "github_repository_id": 15111821, "homepage": "https://grafana.com", "id": "github:15111821", "leaf_matches": [{"reason": "官方 README 说明 Grafana 可查询/可视化/告警并创建、探索、共享多数据源 dashboard；官方 roles 文档进一步证明 Viewer/Editor 分离及 dashboard/folder 权限。数据源级 RBAC 属 Enterprise/Cloud，未纳入 OSS 断言。", "slug": "dashboard-platform", "source_urls": ["https://raw.githubusercontent.com/grafana/grafana/main/README.md", "https://grafana.com/docs/grafana/latest/administration/roles-and-permissions/"]}], "license": "AGPL-3.0-only", "license_evidence_url": "https://raw.githubusercontent.com/grafana/grafana/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/grafana/grafana/main/LICENSE", "spdx_id": "AGPL-3.0-only"}, "name": "Grafana", "repository_url": "https://github.com/grafana/grafana", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:54:38.159311+08:00", "kind": "repository_metadata", "sha256": "28e08e89ad7dacd9fe1ac95a96f1895d7575d742bcf5ad8f1f5cdcdab2003077", "snapshot_path": "sources/28e08e89ad7dacd9fe1ac95a96f1895d7575d742bcf5ad8f1f5cdcdab2003077.txt", "url": "https://github.com/grafana/grafana"}, {"fetched_at": "2026-10-24T22:54:41.680980+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/grafana/grafana/main/LICENSE"}, {"fetched_at": "2026-10-24T22:54:40.253783+08:00", "kind": "readme", "sha256": "fc8a867bf09f319b9288746ab0148faff2e92ed39cd702252ce59161e576c019", "snapshot_path": "sources/fc8a867bf09f319b9288746ab0148faff2e92ed39cd702252ce59161e576c019.txt", "url": "https://raw.githubusercontent.com/grafana/grafana/main/README.md"}, {"fetched_at": "2026-10-26T13:16:13.906226+08:00", "kind": "documentation", "sha256": "10bd96c6c702189e8e0c38c4aa5401971269dee26eea50957fbcf19f0af852b4", "snapshot_path": "sources/10bd96c6c702189e8e0c38c4aa5401971269dee26eea50957fbcf19f0af852b4.txt", "url": "https://grafana.com/docs/grafana/latest/administration/roles-and-permissions/"}, {"fetched_at": "2026-10-26T13:17:29.416764+08:00", "kind": "documentation", "sha256": "68fbbea07cb56b728597a9cb96c31e00b38edbb56681706ae5a926daaf515ffd", "snapshot_path": "sources/68fbbea07cb56b728597a9cb96c31e00b38edbb56681706ae5a926daaf515ffd.txt", "url": "https://raw.githubusercontent.com/grafana/grafana/main/go.mod"}], "summary": "开源监控与可观测性平台：查询多数据源、组合并共享仪表板，持续评估告警规则。", "technology_stack": ["Go"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:139907613','Marquez','{"deployment": ["官方 README 提供 Docker quickstart（./docker/up.sh）；本轮未部署"], "features": ["通过 OpenLineage 事件采集 dataset / job / run 元数据", "在 Web UI 的血缘图中浏览作业与数据集的依赖关系及运行元数据", "提供 HTTP API 与 GraphQL 端点查询元数据"], "github_repository_id": 139907613, "homepage": "https://marquezproject.github.io/marquez", "id": "github:139907613", "leaf_matches": [{"reason": "官方 README 说明 Marquez 是基于 OpenLineage 的开源元数据服务，维护数据集如何被消费与生产的 provenance，并在 Web UI 中以血缘图展示 job/dataset 依赖。匹配血缘平台的流图与上下游追踪核心；未宣称专门的 impact-analysis 工作流。", "slug": "data-lineage-platform", "source_urls": ["https://raw.githubusercontent.com/MarquezProject/marquez/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/MarquezProject/marquez/main/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/MarquezProject/marquez/main/LICENSE", "spdx_id": "Apache-2.0"}, "name": "Marquez", "repository_url": "https://github.com/MarquezProject/marquez", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:53:12.124257+08:00", "kind": "repository_metadata", "sha256": "d8fa695c2d8717dd4a94333f2bfabd9b4ce824e34cf7bfa2dec6b4c09d8290a6", "snapshot_path": "sources/d8fa695c2d8717dd4a94333f2bfabd9b4ce824e34cf7bfa2dec6b4c09d8290a6.txt", "url": "https://github.com/MarquezProject/marquez"}, {"fetched_at": "2026-10-24T22:53:14.749937+08:00", "kind": "license", "sha256": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4", "snapshot_path": "sources/c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4.txt", "url": "https://raw.githubusercontent.com/MarquezProject/marquez/main/LICENSE"}, {"fetched_at": "2026-10-24T22:53:13.591855+08:00", "kind": "readme", "sha256": "f6b947a608190eae9b65644b57ed186cdbb898f8a6a763fc4a244c7c074150b8", "snapshot_path": "sources/f6b947a608190eae9b65644b57ed186cdbb898f8a6a763fc4a244c7c074150b8.txt", "url": "https://raw.githubusercontent.com/MarquezProject/marquez/main/README.md"}], "summary": "开源元数据服务：通过 OpenLineage 采集数据集、作业与运行元数据，维护可浏览的数据血缘。", "technology_stack": ["Java", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dqops','DQOps','{"homepage": "https://dqops.com/", "id": "commercial:dqops", "leaf_matches": [{"reason": "官网正文称 DQOps 是覆盖数据剖析、自动化和持续监控的数据质量平台，并从连接数据源开始监控；官方文档说明平台按固定周期监控数据源、由失败检查产生数据质量 issue，并把同类 issue 归并为 incident，按 Open→Acknowledged→Resolved 状态流转并支持通知。匹配本叶“外部数据源—受监控资产—自动健康评估—有状态事件闭环”的核心。该产品为商业记录（仓库许可为 BSL 1.1，非 OSI 开源），故按商业基本信息收录，不标 open_source；README 说明云端存储与数据质量面板等能力需 DQOps Cloud 账户，未纳入本地自托管断言。", "slug": "data-observability-platform", "source_urls": ["https://dqops.com/", "https://dqops.com/docs/dqo-concepts/grouping-data-quality-issues-to-incidents/"]}], "name": "DQOps", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:45:37.743266+08:00", "kind": "homepage", "sha256": "f90f24f13062535f23381dc273efe00b34c88e416e4fe019be02f593b31e644c", "snapshot_path": "sources/f90f24f13062535f23381dc273efe00b34c88e416e4fe019be02f593b31e644c.txt", "url": "https://dqops.com/"}, {"fetched_at": "2026-10-27T14:44:55.055789+08:00", "kind": "documentation", "sha256": "9c7cbde23ad7455447a39c910a39d81f8e594673ea365c382074269ebd2e94f5", "snapshot_path": "sources/9c7cbde23ad7455447a39c910a39d81f8e594673ea365c382074269ebd2e94f5.txt", "url": "https://dqops.com/docs/dqo-concepts/grouping-data-quality-issues-to-incidents/"}], "summary": "数据质量与可观测性平台：连接组织的数据源，按周期运行数据质量检查，把同类问题归并为带状态的数据质量事件（Open/Acknowledged/Resolved）并通知负责人。官网提供定价与商业服务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:9496329','RAWGraphs','{"deployment": ["官方 README 支持本地运行（npm start）及自行构建上传服务器；本轮未部署"], "features": ["导入电子表格 / CSV 或粘贴的表格文本", "选择布局并把数据字段映射到视觉通道", "输出基于 SVG 的可编辑可视化，可嵌入网页"], "github_repository_id": 9496329, "homepage": "https://www.rawgraphs.io", "id": "github:9496329", "leaf_matches": [{"reason": "官方 README 说明 RAWGraphs 是浏览器端开放 Web 工具，以表格数据为输入、基于 D3.js 生成 SVG 可视化，并可在矢量软件中编辑或嵌入网页；匹配数据可视化应用的输入—字段映射—计算渲染—成品输出核心。无服务器、仅浏览器处理属于该类型允许的静态输出形态。", "slug": "data-visualization-application", "source_urls": ["https://raw.githubusercontent.com/rawgraphs/rawgraphs-app/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/rawgraphs/rawgraphs-app/master/LICENSE", "license_review": {"rationale": "GitHub raw LICENSE text was fetched and checked against supported SPDX markers for this repository.", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/rawgraphs/rawgraphs-app/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "RAWGraphs", "repository_url": "https://github.com/rawgraphs/rawgraphs-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:53:32.967393+08:00", "kind": "repository_metadata", "sha256": "b3c4512225710507208864f6ef59ad906a2a1ce7c8f33e2ef62f5deae8f5c4be", "snapshot_path": "sources/b3c4512225710507208864f6ef59ad906a2a1ce7c8f33e2ef62f5deae8f5c4be.txt", "url": "https://github.com/rawgraphs/rawgraphs-app"}, {"fetched_at": "2026-10-24T22:53:37.305653+08:00", "kind": "license", "sha256": "36878f63187e9be7638d06f67896513263761af9e842ec7c3ab4c702c010a3e7", "snapshot_path": "sources/36878f63187e9be7638d06f67896513263761af9e842ec7c3ab4c702c010a3e7.txt", "url": "https://raw.githubusercontent.com/rawgraphs/rawgraphs-app/master/LICENSE"}, {"fetched_at": "2026-10-24T22:53:34.618477+08:00", "kind": "readme", "sha256": "e58be75b9e8f355c45579e5b7413257385346010757f2aee4268a7919c4dddc3", "snapshot_path": "sources/e58be75b9e8f355c45579e5b7413257385346010757f2aee4268a7919c4dddc3.txt", "url": "https://raw.githubusercontent.com/rawgraphs/rawgraphs-app/master/README.md"}], "summary": "浏览器端开源可视化应用：导入表格数据、映射字段生成矢量图表并输出 SVG。", "technology_stack": ["D3.js", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:49670957','Eclipse RDF4J Workbench','{"deployment": ["Java servlet web application (WAR) deployed on Tomcat or Jetty", "Docker Compose quick start in the source distribution''s docker/ directory", "Self-hosted alongside RDF4J Server"], "features": ["Web-based RDF4J Workbench UI for RDF4J repositories and SPARQL endpoints", "SPARQL query editor with save, execute, cancel, paging and result download", "SPARQL 1.1 Update editor", "Explore resources, contexts/named graphs, namespaces and summary views", "Export all quads with selectable RDF serializations"], "github_repository_id": 49670957, "homepage": "https://rdf4j.org/", "id": "github:49670957", "leaf_matches": [{"reason": "官方文档明确 Workbench 是连接 RDF4J 仓库的 Web 客户端 UI，提供 SPARQL 查询/更新编辑与执行、结果分页和下载、Explore/Contexts/Export，符合实时 RDF 数据集上的 SPARQL 编写-执行循环与数据保留结果。", "slug": "rdf-sparql-workbench", "source_urls": ["https://rdf4j.org/documentation/tools/server-workbench", "https://raw.githubusercontent.com/eclipse-rdf4j/rdf4j/main/README.md"]}], "license": "BSD-3-Clause", "license_evidence_url": "https://api.github.com/repos/eclipse-rdf4j/rdf4j/license", "name": "Eclipse RDF4J Workbench", "repository_url": "https://github.com/eclipse-rdf4j/rdf4j", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T17:59:08.678483+08:00", "kind": "repository_metadata", "sha256": "994f2898dc34220179f4515556aed0709376cab7e5c8cf765eb2e2ba65a2e774", "snapshot_path": "sources/994f2898dc34220179f4515556aed0709376cab7e5c8cf765eb2e2ba65a2e774.txt", "url": "https://api.github.com/repos/eclipse-rdf4j/rdf4j"}, {"fetched_at": "2026-10-26T17:59:08.838894+08:00", "kind": "license", "sha256": "b09fec43fe1c06b35af7f783c7cb4dbce9147fb258fb3b1a3f5b229ad3126463", "snapshot_path": "sources/b09fec43fe1c06b35af7f783c7cb4dbce9147fb258fb3b1a3f5b229ad3126463.txt", "url": "https://api.github.com/repos/eclipse-rdf4j/rdf4j/license"}, {"fetched_at": "2026-10-26T17:59:13.070590+08:00", "kind": "readme", "sha256": "d127af3e8ac34e6b95d72ad365955f706a9c7186c6fa24d75e33ba46e91e1fc1", "snapshot_path": "sources/d127af3e8ac34e6b95d72ad365955f706a9c7186c6fa24d75e33ba46e91e1fc1.txt", "url": "https://raw.githubusercontent.com/eclipse-rdf4j/rdf4j/main/README.md"}, {"fetched_at": "2026-10-26T17:59:23.117658+08:00", "kind": "documentation", "sha256": "6e7a258e11fa66435d3ec66f2133db816f0cdf31f26dcb19ee0207978e6d80e1", "snapshot_path": "sources/6e7a258e11fa66435d3ec66f2133db816f0cdf31f26dcb19ee0207978e6d80e1.txt", "url": "https://rdf4j.org/documentation/tools/server-workbench"}], "summary": "Eclipse RDF4J 的 Web 工作台，连接运行中的 RDF4J Server/RDF 仓库，编写并执行 SPARQL 查询与 SPARQL Update，以表格或图查看结果、分页加载并下载完整结果，同时提供 Explore、Contexts、Namespaces 与数据导出界面。", "technology_stack": ["Java 25+", "Java Servlet / JSP container (Tomcat 9 or Jetty 9.4 recommended)", "Spring Boot runner for the Workbench"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:66506962','Chronograf','{"deployment": ["Self-hosted Go web application", "Official Debian/RPM packages", "Docker image and source build"], "features": ["Data Explorer with InfluxQL query editor and query templates", "Tabular query results and visualizations over a selected time range", "InfluxDB source and host management", "Dashboards with template variables", "User, role and query management for InfluxDB OSS/Enterprise"], "github_repository_id": 66506962, "homepage": "https://www.influxdata.com/time-series-platform/chronograf/", "id": "github:66506962", "leaf_matches": [{"reason": "官方 README 的 Data Explorer 直接描述在 InfluxDB 时序数据上使用 InfluxQL 查询编辑器生成/编辑查询、用模板探索，并以表格查看结果和生成时间序列可视化；产品为连接实时 InfluxDB 数据源的可自托管 Web 应用。仪表板与主机监控是外围能力，本条以 Data Explorer 的查询循环作为核心依据。", "slug": "time-series-database-workbench", "source_urls": ["https://raw.githubusercontent.com/influxdata/chronograf/master/README.md"]}], "license": "AGPL-3.0-or-later", "license_evidence_url": "https://api.github.com/repos/influxdata/chronograf/license", "license_review": {"rationale": "GitHub License API 返回 NOASSERTION，但所存 LICENSE 完整正文以 GNU Affero General Public License Version 3 开头，包含完整 TERMS AND CONDITIONS，并在前言写明 either version 3 of the License, or (at your option) any later version；按完整文本认定为 AGPL-3.0-or-later。", "reviewer": "unit-008 repair (reusing unit-133 snapshot)", "scope": "repository", "source_url": "https://api.github.com/repos/influxdata/chronograf/license", "spdx_id": "AGPL-3.0-or-later"}, "name": "Chronograf", "repository_url": "https://github.com/influxdata/chronograf", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:00:44.721087+08:00", "kind": "repository_metadata", "sha256": "4b180be22f3727291cf52aa04c16df3cb1db27069785b44b3a9be98790f9fa8d", "snapshot_path": "sources/4b180be22f3727291cf52aa04c16df3cb1db27069785b44b3a9be98790f9fa8d.txt", "url": "https://api.github.com/repos/influxdata/chronograf"}, {"fetched_at": "2026-10-26T18:00:45.140645+08:00", "kind": "license", "sha256": "098b7a67b0b59b618644cf301ec6f4a4ef59b6b72f3079acf3b94135c37eb38e", "snapshot_path": "sources/098b7a67b0b59b618644cf301ec6f4a4ef59b6b72f3079acf3b94135c37eb38e.txt", "url": "https://api.github.com/repos/influxdata/chronograf/license"}, {"fetched_at": "2026-10-26T18:00:44.476979+08:00", "kind": "readme", "sha256": "480ba3afcd325f594d8babd9c27132d99d6fdfce0e28ad9ca6a16434cc777eb6", "snapshot_path": "sources/480ba3afcd325f594d8babd9c27132d99d6fdfce0e28ad9ca6a16434cc777eb6.txt", "url": "https://raw.githubusercontent.com/influxdata/chronograf/master/README.md"}], "summary": "Chronograf 是 TICK 栈的开源 Web 应用，连接 InfluxDB 时序数据源；其工作台核心是 Data Explorer，提供 InfluxQL 查询编辑器、查询模板、按时间范围探索、表格结果与可视化，另有仪表板、用户/权限和查询管理等外围能力。", "technology_stack": ["Go", "React.js", "InfluxQL", "InfluxDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:46398090','DataHub OSS','{"deployment": ["Self-hosted on own infrastructure", "Docker quickstart (8GB RAM, Python 3.10+)", "Kubernetes deployment"], "features": ["Metadata graph fed by 150+ source integrations", "Universal search across the data estate", "Column-level lineage", "Schema, statistics, ownership and usage profiling per asset", "Business glossary and ownership/stewardship metadata"], "github_repository_id": 46398090, "homepage": "https://datahub.com", "id": "github:46398090", "leaf_matches": [{"reason": "README 明确 DataHub OSS 采集 150+ 外部系统的元数据形成元数据图，Discovery 提供全资产搜索、列级血缘及 schema/统计/所有权/使用情况，符合目录条目引用外部资产、结构+描述性上下文、搜索发现三项核心。", "slug": "data-catalog", "source_urls": ["https://raw.githubusercontent.com/datahub-project/datahub/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/datahub-project/datahub/license", "name": "DataHub OSS", "repository_url": "https://github.com/datahub-project/datahub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:01:46.128832+08:00", "kind": "repository_metadata", "sha256": "dd6c6cb358122c47ded45a7444908b971c06370891700d4be02db20b9ed7cbb8", "snapshot_path": "sources/dd6c6cb358122c47ded45a7444908b971c06370891700d4be02db20b9ed7cbb8.txt", "url": "https://api.github.com/repos/datahub-project/datahub"}, {"fetched_at": "2026-10-26T18:01:46.128353+08:00", "kind": "license", "sha256": "c66fcbab18e1ed2328fb2fabf8efd49ada03e2aedebdd1ff688a94af0b0b2d69", "snapshot_path": "sources/c66fcbab18e1ed2328fb2fabf8efd49ada03e2aedebdd1ff688a94af0b0b2d69.txt", "url": "https://api.github.com/repos/datahub-project/datahub/license"}, {"fetched_at": "2026-10-26T18:01:45.704551+08:00", "kind": "readme", "sha256": "9711dc90543bb6a6703e37e246244e4eb689ff68234d9bdfc081edef544fdd7a", "snapshot_path": "sources/9711dc90543bb6a6703e37e246244e4eb689ff68234d9bdfc081edef544fdd7a.txt", "url": "https://raw.githubusercontent.com/datahub-project/datahub/master/README.md"}], "summary": "DataHub OSS 是可自托管的元数据与数据目录平台：从 150+ 外部系统采集表、列、仪表板等资产的结构与描述性上下文，形成统一元数据图，并提供全资产搜索、列级血缘、schema/统计/所有权/使用情况与业务术语表，帮助用户发现和理解数据。", "technology_stack": ["Python CLI (acryl-datahub)", "Docker", "Kubernetes", "GraphQL/REST APIs"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:27911088','Apache NiFi','{"deployment": ["自托管 Java 服务端应用（README 要求 Java 21）", "支持单机与集群横向扩展部署，并提供 Docker 相关构建支持"], "features": ["以 Connection 连接 Processor 组成有向数据流，FlowFile 在连接队列中流转", "Process Group 支持命名、保存、版本化与重跑数据流", "Processor 支持定时驱动和事件驱动调度，内置重试、退避与背压", "Web UI 与 REST API 提供设计、控制、运行状态监控和报告任务", "可搜索的数据溯源与端到端血缘"], "github_repository_id": 27911088, "homepage": "https://nifi.apache.org/", "id": "github:27911088", "leaf_matches": [{"reason": "官方 README 与用户指南显示 NiFi 以 Processor/Controller Service 访问外部系统（数据库、Kafka、S3 等），以 Connection 队列在组件间承载 FlowFile，构成持久化数据流；支持定时/事件驱动调度、运行监控与溯源，符合数据集成平台的连接、管道和受管执行三项核心。", "slug": "data-integration-platform", "source_urls": ["https://github.com/apache/nifi", "https://nifi.apache.org/docs/nifi-docs/html/user-guide.html", "https://raw.githubusercontent.com/apache/nifi/main/README.md"]}, {"reason": "官方首页正文将 NiFi 定义为处理与分发数据的系统，并明确列出浏览器界面用于设计/控制/反馈/监控、容错与保障投递、背压控制、运行时修改 flow 配置、数据 provenance 完整血缘；官方 Overview 正文说明 processor 执行数据路由、转换与系统间中介，FlowFile 携带属性与内容，provenance 仓库记录并索引事件。这些构成持久、可配置、可重跑的 flow 管线与受管转换/执行监控，符合本叶的 ETL/ELT 平台核心；仓库元数据与 GitHub license API 确认 apache/nifi 身份及 Apache-2.0。其强项偏事件流与数据分发而非批式仓库建模，属产品侧重差异，不构成边界排除。", "slug": "etl-elt-platform", "source_urls": ["https://nifi.apache.org/", "https://nifi.apache.org/docs/nifi-docs/html/overview.html", "https://api.github.com/repos/apache/nifi", "https://api.github.com/repos/apache/nifi/license"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/apache/nifi/license", "name": "Apache NiFi", "repository_url": "https://github.com/apache/nifi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:44:27.307607+08:00", "kind": "repository_metadata", "sha256": "c85342dfe4af8eca9e00c37a41e1f2cdd22e51cdc1a188374e275ba72efc240a", "snapshot_path": "sources/c85342dfe4af8eca9e00c37a41e1f2cdd22e51cdc1a188374e275ba72efc240a.txt", "url": "https://api.github.com/repos/apache/nifi"}, {"fetched_at": "2026-10-26T18:00:47.138828+08:00", "kind": "license", "sha256": "58cf39d51585fd1809676de78c6ca145fcbdc6590297f70db3af6a076b451aa5", "snapshot_path": "sources/58cf39d51585fd1809676de78c6ca145fcbdc6590297f70db3af6a076b451aa5.txt", "url": "https://api.github.com/repos/apache/nifi/license"}, {"fetched_at": "2026-10-26T18:00:40.260628+08:00", "kind": "repository_metadata", "sha256": "6e5cf5626a73f3d92033a988121918bbbd6b0fd38f385ed26d8acbf2ab9f72ee", "snapshot_path": "sources/6e5cf5626a73f3d92033a988121918bbbd6b0fd38f385ed26d8acbf2ab9f72ee.txt", "url": "https://github.com/apache/nifi"}, {"fetched_at": "2026-10-28T23:44:29.054637+08:00", "kind": "homepage", "sha256": "897b564fa1866a1f2d689fffa05b6e300e86ca6d5acf9f53150107c7e018bafd", "snapshot_path": "sources/897b564fa1866a1f2d689fffa05b6e300e86ca6d5acf9f53150107c7e018bafd.txt", "url": "https://nifi.apache.org/"}, {"fetched_at": "2026-10-26T18:01:20.214328+08:00", "kind": "documentation", "sha256": "c3a9f599bf30396de9314109f5c7f635d8a07d9d61c129a6b1437ac608cc71ca", "snapshot_path": "sources/c3a9f599bf30396de9314109f5c7f635d8a07d9d61c129a6b1437ac608cc71ca.txt", "url": "https://nifi.apache.org/components/"}, {"fetched_at": "2026-10-28T23:45:18.665108+08:00", "kind": "documentation", "sha256": "dc4eb02af7d5c4ea194ab8f817b4052ce2c096526133fd9c825204fb33782362", "snapshot_path": "sources/dc4eb02af7d5c4ea194ab8f817b4052ce2c096526133fd9c825204fb33782362.txt", "url": "https://nifi.apache.org/docs/nifi-docs/html/overview.html"}, {"fetched_at": "2026-10-26T18:01:30.688050+08:00", "kind": "documentation", "sha256": "2e1519e21c1c8c400c3e2fb0c0330608719ef3caac36370bac5debf50cd7815a", "snapshot_path": "sources/2e1519e21c1c8c400c3e2fb0c0330608719ef3caac36370bac5debf50cd7815a.txt", "url": "https://nifi.apache.org/docs/nifi-docs/html/user-guide.html"}, {"fetched_at": "2026-10-26T18:01:00.438193+08:00", "kind": "readme", "sha256": "0d1019aa65d49b67dc6afbb1de85c597bfe925abb242ec547a8fe6796b655303", "snapshot_path": "sources/0d1019aa65d49b67dc6afbb1de85c597bfe925abb242ec547a8fe6796b655303.txt", "url": "https://raw.githubusercontent.com/apache/nifi/main/README.md"}], "summary": "Apache 旗下的开源数据流平台，用于设计、运行和监控在外部系统之间路由、转换和分发数据的持久化管道；通过 Processor 与 Controller Service 访问外部系统，以 Connection 队列在组件间承载 FlowFile，并提供定时/事件驱动调度、运行监控、数据溯源与版本化数据流。", "technology_stack": ["Java", "Web 浏览器界面", "REST API", "可插拔 Processor / Controller Service"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:223347908','Qualitis','{"deployment": ["自托管 Spring Boot 服务，浏览器访问默认 8090 端口", "需要 MySQL 保存配置与结果，需要 Linkis/Spark 执行质量任务", "DataSphereStudio 为可选工作流依赖"], "features": ["质量规则以数据质量模型表达，支持单表、多表和自定义模型，并提供空值、枚举、数字等预置校验模板", "支持数据质量模型调度执行，将任务提交到 Linkis/Spark", "生成数据质量报告、结果可视化与监控", "异常数据存储、任务日志与管理工作台", "管理员控制台，含人员、访问控制、权限和元数据管理"], "github_repository_id": 223347908, "homepage": "https://github.com/WeBankFinTech/Qualitis", "id": "github:223347908", "leaf_matches": [{"reason": "官方 README 与用户手册显示 Qualitis 以质量模型/模板定义规则、调度执行并生成质量报告和结果可视化；异常数据与日志记录保留执行证据，覆盖定义规则、执行、记录结果三项核心。", "slug": "data-quality-platform", "source_urls": ["https://github.com/WeBankFinTech/Qualitis", "https://raw.githubusercontent.com/WeBankFinTech/Qualitis/master/README.md", "https://raw.githubusercontent.com/WeBankFinTech/Qualitis/master/docs/en_US/ch1/User%20Manual.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/WeBankFinTech/Qualitis/license", "name": "Qualitis", "repository_url": "https://github.com/WeBankFinTech/Qualitis", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:03:42.250584+08:00", "kind": "repository_metadata", "sha256": "6cff5142905fb5cc893eddf1c7e72b4516ced3d8b83b0a101af479d3bb5dcb19", "snapshot_path": "sources/6cff5142905fb5cc893eddf1c7e72b4516ced3d8b83b0a101af479d3bb5dcb19.txt", "url": "https://github.com/WeBankFinTech/Qualitis"}, {"fetched_at": "2026-10-26T18:04:09.453123+08:00", "kind": "license", "sha256": "b557c3e1efe8c3b1e405d9e3b6589417e95a85ac095a39086b35d631efd2252a", "snapshot_path": "sources/b557c3e1efe8c3b1e405d9e3b6589417e95a85ac095a39086b35d631efd2252a.txt", "url": "https://api.github.com/repos/WeBankFinTech/Qualitis/license"}, {"fetched_at": "2026-10-26T18:03:40.503950+08:00", "kind": "readme", "sha256": "c169868d266de20f6cd9547a6ef819e6fd73ea6d5f8dfe765438c606765b95fc", "snapshot_path": "sources/c169868d266de20f6cd9547a6ef819e6fd73ea6d5f8dfe765438c606765b95fc.txt", "url": "https://raw.githubusercontent.com/WeBankFinTech/Qualitis/master/README.md"}, {"fetched_at": "2026-10-26T18:04:08.577602+08:00", "kind": "documentation", "sha256": "e72512586234c28e6aa3aa1af4a3cd014a602b69272bfffcd4d64bfbd5b38c4e", "snapshot_path": "sources/e72512586234c28e6aa3aa1af4a3cd014a602b69272bfffcd4d64bfbd5b38c4e.txt", "url": "https://raw.githubusercontent.com/WeBankFinTech/Qualitis/master/docs/en_US/ch1/User%20Manual.md"}, {"fetched_at": "2026-10-26T18:04:21.893624+08:00", "kind": "documentation", "sha256": "ad61ada0c8328a6ca4a68da1e863fa9323cc553d3d0006f165ccb0fd1be1d474", "snapshot_path": "sources/ad61ada0c8328a6ca4a68da1e863fa9323cc553d3d0006f165ccb0fd1be1d474.txt", "url": "https://raw.githubusercontent.com/WeBankFinTech/Qualitis/master/docs/en_US/ch1/Quick%20Deploy%20Standalone.md"}], "summary": "开源自托管的数据质量管理平台：以数据质量模型和预置校验模板定义规则，将模型调度到 Linkis/Spark 执行，并生成质量报告、结果可视化、异常数据和任务日志。", "technology_stack": ["Java / Spring Boot", "MySQL", "Linkis", "Apache Spark"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dremio-enterprise','Dremio Enterprise','{"homepage": "https://dremio.com/", "id": "commercial:dremio-enterprise", "leaf_matches": [{"reason": "官方 Enterprise 25.x Sonar 概览说明其可对 lakehouse、数据库与数据仓库中的数据执行查询，view 是由 SQL 在表/视图上创建的 virtual table；Connecting to Your Data 列出对象存储、数据库与 metastore 等连接，并说明可在已连接 Dremio 集群间联邦查询；Datasets 说明表不可被 Dremio 修改、视图不是数据副本且始终反映父表状态。连接外部源、持久虚拟视图与请求时查询三项核心均有 Enterprise 官方正文；本条目不把 Apache-2.0 OSS 仓库或仅见 Cloud 的 Polaris/NoSQL 能力混入。", "slug": "data-virtualization-platform", "source_urls": ["https://docs.dremio.com/25.x/sonar/", "https://docs.dremio.com/25.x/sonar/data-sources/", "https://docs.dremio.com/25.x/sonar/query-manage/managing-data/datasets/", "https://www.dremio.com/platform/"]}], "name": "Dremio Enterprise", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T12:14:58.873129+08:00", "kind": "documentation", "sha256": "e52c6b44059f0e78304b5a8e1d72d968cee27e34c2b7a0f1983d8b870a62148f", "snapshot_path": "sources/e52c6b44059f0e78304b5a8e1d72d968cee27e34c2b7a0f1983d8b870a62148f.txt", "url": "https://docs.dremio.com/25.x/sonar/data-sources/"}, {"fetched_at": "2026-10-27T12:19:58.241611+08:00", "kind": "documentation", "sha256": "28e959073b8c7588146a828ffbdcd66b2e58e537a73d907a0d48268c81937354", "snapshot_path": "sources/28e959073b8c7588146a828ffbdcd66b2e58e537a73d907a0d48268c81937354.txt", "url": "https://docs.dremio.com/25.x/sonar/"}, {"fetched_at": "2026-10-26T18:09:14.275997+08:00", "kind": "documentation", "sha256": "c40bd1d89fded5ca00fccdc83560e1cc66d524d82b28d633645e6baaf3154702", "snapshot_path": "sources/c40bd1d89fded5ca00fccdc83560e1cc66d524d82b28d633645e6baaf3154702.txt", "url": "https://docs.dremio.com/25.x/sonar/query-manage/managing-data/datasets/"}, {"fetched_at": "2026-10-26T18:08:46.453817+08:00", "kind": "homepage", "sha256": "aa23591416fde1e833e53bdf9098409275481131d2edbc8ef2873d10dc66c299", "snapshot_path": "sources/aa23591416fde1e833e53bdf9098409275481131d2edbc8ef2873d10dc66c299.txt", "url": "https://www.dremio.com/platform/"}], "summary": "商业自托管的 Dremio Enterprise（Dremio Sonar 查询引擎）：可连接对象存储、关系数据库与外部元数据目录，对源表执行 SQL 查询，并把视图保存为不复制源数据的虚拟表；支持在已连接的 Dremio 集群间联邦查询。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:3217621','phpMyAdmin','{"deployment": ["PHP Web 应用，部署在 Web 服务器上通过浏览器访问", "可连接并集中管理多个 MySQL/MariaDB 服务器"], "features": ["通过 Web 界面管理 MySQL 和 MariaDB 服务器", "主页面显示详细服务器信息，服务器视图含 status、variables 与 privileges 标签", "服务器、数据库与表的维护，并给出服务器配置优化建议", "浏览、删除和管理数据库、表、视图、字段和索引", "管理 MySQL 用户账户与权限；账户管理交由 MySQL 自身用户系统判定", "多服务器集中管理", "数据导入导出与 SQL 语句执行"], "github_repository_id": 3217621, "homepage": "https://www.phpmyadmin.net/", "id": "github:3217621", "leaf_matches": [{"reason": "官方 README 与 docs/intro.rst 说明 phpMyAdmin 用于通过 Web 管理 MySQL/MariaDB 服务器，支持服务器维护、多服务器管理、用户账户与权限管理；docs/config.rst 说明主页面可显示 detailed server information，服务器视图含 status 与 variables 标签；docs/privileges.rst 说明用户与权限由 MySQL 自身判定。被管理对象是运行中的数据库服务器，控制台显示其服务器信息/状态并执行管理操作；本条目不宣称重启、停止、备份或会话管理等快照未证明的部署生命周期能力。", "slug": "database-management-console", "source_urls": ["https://www.phpmyadmin.net/", "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/README", "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/intro.rst", "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/config.rst", "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/privileges.rst"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/phpmyadmin/phpmyadmin/license", "name": "phpMyAdmin", "repository_url": "https://github.com/phpmyadmin/phpmyadmin", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:07:45.682500+08:00", "kind": "repository_metadata", "sha256": "1d8c08960359578162b1ea669228fd9fb525b35610d81146ef49e40909535913", "snapshot_path": "sources/1d8c08960359578162b1ea669228fd9fb525b35610d81146ef49e40909535913.txt", "url": "https://github.com/phpmyadmin/phpmyadmin"}, {"fetched_at": "2026-10-26T18:07:44.821504+08:00", "kind": "license", "sha256": "0596b4faa1bde435f2e24bc3a10dce32c4d9519a2838b713650e888d4c91f514", "snapshot_path": "sources/0596b4faa1bde435f2e24bc3a10dce32c4d9519a2838b713650e888d4c91f514.txt", "url": "https://api.github.com/repos/phpmyadmin/phpmyadmin/license"}, {"fetched_at": "2026-10-26T18:07:44.439723+08:00", "kind": "readme", "sha256": "91aa77fd8eabd79f2c25a4c88d1e445bbcd9efc87e7d051bfc2d46c24484a18c", "snapshot_path": "sources/91aa77fd8eabd79f2c25a4c88d1e445bbcd9efc87e7d051bfc2d46c24484a18c.txt", "url": "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/README"}, {"fetched_at": "2026-10-26T18:08:44.957860+08:00", "kind": "homepage", "sha256": "264906fcb3e905ab2f2fd102d03a880335b7e9cf326f351d4e0ed60676702aa0", "snapshot_path": "sources/264906fcb3e905ab2f2fd102d03a880335b7e9cf326f351d4e0ed60676702aa0.txt", "url": "https://www.phpmyadmin.net/"}, {"fetched_at": "2026-10-27T12:17:05.044175+08:00", "kind": "documentation", "sha256": "997ed2454b77f88597d73d7785ed9943ef5f729fee4149eed99ecb09516ac0fe", "snapshot_path": "sources/997ed2454b77f88597d73d7785ed9943ef5f729fee4149eed99ecb09516ac0fe.txt", "url": "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/intro.rst"}, {"fetched_at": "2026-10-27T12:17:07.216322+08:00", "kind": "documentation", "sha256": "20813f49e12c7081834788012929a2c58cfc73fca63e0accf8590661b04d2b00", "snapshot_path": "sources/20813f49e12c7081834788012929a2c58cfc73fca63e0accf8590661b04d2b00.txt", "url": "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/config.rst"}, {"fetched_at": "2026-10-27T12:17:09.574328+08:00", "kind": "documentation", "sha256": "617ab7da22fece4c123794189b864d2e6b90fa272c9406f9778ca45ff17da21d", "snapshot_path": "sources/617ab7da22fece4c123794189b864d2e6b90fa272c9406f9778ca45ff17da21d.txt", "url": "https://raw.githubusercontent.com/phpmyadmin/phpmyadmin/master/docs/privileges.rst"}], "summary": "开源自托管的 MySQL/MariaDB Web 管理控制台：连接运行中的数据库服务器，在主页面显示服务器信息，提供 status / variables / privileges 服务器视图，执行服务器维护，管理数据库对象、用户账户与权限，并支持多服务器集中管理与导入导出。", "technology_stack": ["PHP", "MySQL / MariaDB", "Web 浏览器界面"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:178079595','OpenCost','{"deployment": ["通过官方 Helm chart 安装到 Kubernetes 1.20+ 集群", "多云成本摄取需配置云厂商账单/定价集成"], "features": ["按集群、节点、命名空间、控制器类型、控制器、服务或 Pod 实时分配 Kubernetes 成本", "监控 AWS、Azure、GCP 多云服务成本，并支持本地集群自定义 CSV 定价", "通过 /metrics 导出定价数据到 Prometheus", "提供成本 API、kubectl cost CLI 与配套 Web UI", "支持通过 OpenCost Plugins 接入外部成本（如 Datadog）"], "github_repository_id": 178079595, "homepage": "https://www.opencost.io", "id": "github:178079595", "leaf_matches": [{"reason": "README 明确说明其摄取 Kubernetes 与云厂商成本数据，按集群、命名空间、控制器、服务或 Pod 归一化分配支出，并通过 API、指标与配套 UI 呈现，对应“账单摄取 → 成本模型 → 组织归属分配 → 成本可见性”核心。README 说明 OpenCost 最初由 Kubecost 开发并开源；本条只按 Apache-2.0 开源发行版记录，不据此推断商业 Kubecost 版本能力。", "slug": "cloud-cost-management-finops", "source_urls": ["https://raw.githubusercontent.com/opencost/opencost/develop/README.md", "https://github.com/opencost/opencost"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/opencost/opencost/license", "license_review": {"rationale": "Reviewed the complete Apache-2.0 license text returned by the official GitHub license API for opencost/opencost; the SPDX identifier is confirmed for this repository.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://api.github.com/repos/opencost/opencost/license", "spdx_id": "Apache-2.0"}, "name": "OpenCost", "repository_url": "https://github.com/opencost/opencost", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:14:16.697983+08:00", "kind": "repository_metadata", "sha256": "fc41fa6077cf3cd5229ba32f35ac67cc4a1307eed417a1d866d8df086a4d3294", "snapshot_path": "sources/fc41fa6077cf3cd5229ba32f35ac67cc4a1307eed417a1d866d8df086a4d3294.txt", "url": "https://github.com/opencost/opencost"}, {"fetched_at": "2026-10-26T18:14:15.391014+08:00", "kind": "license", "sha256": "c674962e70418661ec6ddf1c9160283880c199e594d4b5034599b1d0e98af6bc", "snapshot_path": "sources/c674962e70418661ec6ddf1c9160283880c199e594d4b5034599b1d0e98af6bc.txt", "url": "https://api.github.com/repos/opencost/opencost/license"}, {"fetched_at": "2026-10-26T18:14:15.251148+08:00", "kind": "readme", "sha256": "ad1625c2dd15d0987bd1b6264478edf75cf776f2d34b5887b2a3af2761b391e0", "snapshot_path": "sources/ad1625c2dd15d0987bd1b6264478edf75cf776f2d34b5887b2a3af2761b391e0.txt", "url": "https://raw.githubusercontent.com/opencost/opencost/develop/README.md"}], "summary": "OpenCost 是开源的 Kubernetes 与云成本监控应用：摄取云账单与定价数据，将当前和历史支出按集群、命名空间、控制器、服务或 Pod 分配，并通过成本 API、Prometheus 指标和配套 UI 提供成本可见性。", "technology_stack": ["Go", "Kubernetes", "Prometheus"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:20789757','ManageIQ','{"deployment": ["使用官方提供的社区构建包安装", "可管理异构虚拟化/容器环境，需接入相应环境"], "features": ["在单一平台管理容器、虚拟机、网络和存储", "发现、监控、利用率、性能、报表、分析与趋势", "基于策略的资源与配置管理、告警、安全与合规", "置备、工作负载管理与编排", "通过 Web 服务、CMDB 与外部系统集成"], "github_repository_id": 20789757, "homepage": "https://www.manageiq.org", "id": "github:20789757", "leaf_matches": [{"reason": "官方 User Reference 正文写明 Trending 报表给出 datastore 容量与 host CPU/内存的投影，Tenants 配额报表列出 total/in use/allocated/available，Optimization 报表覆盖 CPU、内存、磁盘的可优化领域与潜在节省，并要求开启 Capacity and Utilization 采集；这些对应容量状态、容量风险（前瞻投影）与容量决策（回收/调整建议）。文档把 Optimization 定位为报表，未证明自动执行优化动作，故不写自动闭环。", "slug": "capacity-management", "source_urls": ["https://www.manageiq.org/docs/reference/latest/monitoring_alerts_and_reporting/index.html", "https://raw.githubusercontent.com/ManageIQ/manageiq/master/README.md"]}, {"reason": "README 声明以单一平台管理容器、虚拟机、网络和存储，并提供发现/监控/利用率、基于策略的控制，以及置备与工作负载编排，分别对应连接异构环境、统一清单与置备/编排操作三个核心；README 为平台级概览，未逐项展示外部连接器，也未展示资源退役流程，本条不作该扩展。", "slug": "cloud-management-platform", "source_urls": ["https://github.com/ManageIQ/manageiq", "https://raw.githubusercontent.com/ManageIQ/manageiq/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/ManageIQ/manageiq/license", "license_review": {"rationale": "Reviewed the complete Apache-2.0 license text returned by the official GitHub license API for ManageIQ/manageiq; the SPDX identifier is confirmed for this repository.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://api.github.com/repos/ManageIQ/manageiq/license", "spdx_id": "Apache-2.0"}, "name": "ManageIQ", "repository_url": "https://github.com/ManageIQ/manageiq", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:14:24.064841+08:00", "kind": "license", "sha256": "d52c04331f643315f59b3068eed0b88da10aaa25c5463206a79745f3a9b5d6c3", "snapshot_path": "sources/d52c04331f643315f59b3068eed0b88da10aaa25c5463206a79745f3a9b5d6c3.txt", "url": "https://api.github.com/repos/ManageIQ/manageiq/license"}, {"fetched_at": "2026-10-26T18:14:25.188216+08:00", "kind": "repository_metadata", "sha256": "7a1d615786122738be2945f8b70280614258027a36f7dd3e23a42999bb7202ac", "snapshot_path": "sources/7a1d615786122738be2945f8b70280614258027a36f7dd3e23a42999bb7202ac.txt", "url": "https://github.com/ManageIQ/manageiq"}, {"fetched_at": "2026-10-28T23:50:42.205625+08:00", "kind": "repository_metadata", "sha256": "db78138151b4479419c299b543bfc64a5a8e48c19c060ac736055d10c4fecfaf", "snapshot_path": "sources/db78138151b4479419c299b543bfc64a5a8e48c19c060ac736055d10c4fecfaf.txt", "url": "https://github.com/ManageIQ/manageiq"}, {"fetched_at": "2026-10-26T18:14:23.807029+08:00", "kind": "readme", "sha256": "71dded0f45e41052ec3560f647ca1938928d8ca2a674dc4e1b18235331aff883", "snapshot_path": "sources/71dded0f45e41052ec3560f647ca1938928d8ca2a674dc4e1b18235331aff883.txt", "url": "https://raw.githubusercontent.com/ManageIQ/manageiq/master/README.md"}, {"fetched_at": "2026-10-28T23:50:16.365035+08:00", "kind": "documentation", "sha256": "3912267c444619f60bfc8f2c3487f3bd5a254627fb32cf8e2642e616eae79794", "snapshot_path": "sources/3912267c444619f60bfc8f2c3487f3bd5a254627fb32cf8e2642e616eae79794.txt", "url": "https://www.manageiq.org/docs/reference/latest/monitoring_alerts_and_reporting/index.html"}], "summary": "ManageIQ 是开源的混合 IT 管理平台，将容器、虚拟机、网络和存储纳入单一平台，提供发现与监控、策略控制，以及置备和工作负载编排。", "technology_stack": ["Ruby on Rails"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:708775091','Dockge','{"deployment": ["以 Docker 容器方式自托管，默认端口 5001", "要求 Docker 20+ 或 Podman，compose 文件保存在宿主机目录"], "features": ["管理 compose.yaml 栈：创建、编辑、启动、停止、重启、删除", "更新 Docker 镜像", "交互式 compose.yaml 编辑器与 Web 终端", "通过多 agent 在单一界面管理不同 Docker 主机上的栈", "将 docker run 命令转换为 compose.yaml", "实时显示拉取/启停进度与终端输出"], "github_repository_id": 708775091, "homepage": "https://github.com/louislam/dockge", "id": "github:708775091", "leaf_matches": [{"reason": "README 说明其连接 Docker 主机、以 compose.yaml 从镜像部署栈，并提供创建/编辑/启动/停止/重启/删除和镜像更新等生命周期操作，同时实时显示拉取/启停进度与终端输出，对应容器管理四项核心；README 未明确资源消耗指标，第四项只按进度/终端输出记录，不称完整容器监控产品。", "slug": "container-management", "source_urls": ["https://raw.githubusercontent.com/louislam/dockge/master/README.md", "https://github.com/louislam/dockge"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/louislam/dockge/license", "license_review": {"rationale": "Reviewed the complete MIT license text returned by the official GitHub license API for louislam/dockge; the SPDX identifier is confirmed for this repository.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://api.github.com/repos/louislam/dockge/license", "spdx_id": "MIT"}, "name": "Dockge", "repository_url": "https://github.com/louislam/dockge", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:14:33.372952+08:00", "kind": "repository_metadata", "sha256": "5570ac0195a5f127a2fbe04e836e415a9011ed61adede7825325ad67c8b0593a", "snapshot_path": "sources/5570ac0195a5f127a2fbe04e836e415a9011ed61adede7825325ad67c8b0593a.txt", "url": "https://github.com/louislam/dockge"}, {"fetched_at": "2026-10-26T18:14:32.078587+08:00", "kind": "license", "sha256": "26c30664cf821e9ce20940fddb76bb8d077d5d51b3e3d40b2dbe575346e35956", "snapshot_path": "sources/26c30664cf821e9ce20940fddb76bb8d077d5d51b3e3d40b2dbe575346e35956.txt", "url": "https://api.github.com/repos/louislam/dockge/license"}, {"fetched_at": "2026-10-26T18:14:31.732555+08:00", "kind": "readme", "sha256": "30189a5bc9d869934fcd34d11f44e1f9ac36387554d73fd318263ba014cbe32d", "snapshot_path": "sources/30189a5bc9d869934fcd34d11f44e1f9ac36387554d73fd318263ba014cbe32d.txt", "url": "https://raw.githubusercontent.com/louislam/dockge/master/README.md"}], "summary": "Dockge 是开源的自托管 Docker Compose 栈管理应用：通过单一 Web 界面创建、编辑、启动、停止、重启和删除 compose 栈，支持多 Docker 主机代理、交互式编辑器、Web 终端与实时进度/终端输出。", "technology_stack": ["TypeScript", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zerto','Zerto','{"homepage": "https://www.zerto.com/", "id": "commercial:zerto", "leaf_matches": [{"reason": "官网首页的标题与描述将其定位为面向本地及云环境的灾难恢复、数据保护与数据移动平台，并明确持续数据保护（CDP）；导航列出 Failover Live & Testing。以上支持其作为灾难恢复平台的类型匹配；本条仅记录该基本定位，不把导航标签或元数据扩展为近同步复制、日志恢复或应用恢复等具体工作流证据。", "slug": "disaster-recovery-platform", "source_urls": ["https://www.zerto.com/"]}], "name": "Zerto", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:15:01.777165+08:00", "kind": "homepage", "sha256": "065d73e2b018e3712a38f9423fcd4af9d1ff69d72f671444ab3456902bc7394f", "snapshot_path": "sources/065d73e2b018e3712a38f9423fcd4af9d1ff69d72f671444ab3456902bc7394f.txt", "url": "https://www.zerto.com/"}], "summary": "Zerto 是商业灾难恢复与数据保护平台。官网首页将其定位为面向本地与云环境的灾难恢复、数据保护与数据移动产品，并明确持续数据保护（CDP）；导航列出故障切换与测试（Failover Live & Testing）。本条仅作商业产品基本记录，不把导航或元数据扩展为近同步复制、日志恢复、应用恢复等具体工作流的已核验证据。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:77444607','OpenWISP Controller','{"deployment": ["Self-hosted Python/Django application; official installers and documentation"], "features": ["Managed device records with adoption, provisioning and management VPN configuration", "Configuration templates, configuration variables and device groups", "Configuration editor with JSON-Schema and advanced NetJSON editing", "Push operations that apply configuration changes to devices over SSH"], "github_repository_id": 77444607, "homepage": "https://openwisp.io", "id": "github:77444607", "leaf_matches": [{"reason": "官方 README、结构文档与 Push Operations 文档证明其维护设备资产、以模板管理配置并可推送配置到设备，符合网络管理的设备记录+配置实体+写入路径核心。", "slug": "network-management", "source_urls": ["https://raw.githubusercontent.com/openwisp/openwisp-controller/master/README.rst", "https://openwisp.io/docs/stable/controller/user/intro.html", "https://openwisp.io/docs/stable/controller/user/push-operations.html"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/openwisp/openwisp-controller/master/LICENSE", "license_review": {"rationale": "Reviewed the complete GPL-3.0 license text fetched from the official project repository; the license applies to the repository as a whole.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/openwisp/openwisp-controller/master/LICENSE", "spdx_id": "GPL-3.0"}, "name": "OpenWISP Controller", "repository_url": "https://github.com/openwisp/openwisp-controller", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:39:35.194919+08:00", "kind": "repository_metadata", "sha256": "75c3501cbced5d9e7f607ee3f9f9e2e1c1c2c36a1a282c07ffb3358cc52a7363", "snapshot_path": "sources/75c3501cbced5d9e7f607ee3f9f9e2e1c1c2c36a1a282c07ffb3358cc52a7363.txt", "url": "https://github.com/openwisp/openwisp-controller"}, {"fetched_at": "2026-10-26T18:39:36.447807+08:00", "kind": "readme", "sha256": "0d247a19f6a2e1bf6003a1ae3cf65ebdd83cad0115a83e7a765b99dd2133b3e4", "snapshot_path": "sources/0d247a19f6a2e1bf6003a1ae3cf65ebdd83cad0115a83e7a765b99dd2133b3e4.txt", "url": "https://raw.githubusercontent.com/openwisp/openwisp-controller/master/README.rst"}, {"fetched_at": "2026-10-26T18:39:37.785202+08:00", "kind": "license", "sha256": "457211dba739c5b727ccf04acace1eaa6ca4cc851a9e0fe8f3c0662723abcbe6", "snapshot_path": "sources/457211dba739c5b727ccf04acace1eaa6ca4cc851a9e0fe8f3c0662723abcbe6.txt", "url": "https://raw.githubusercontent.com/openwisp/openwisp-controller/master/LICENSE"}, {"fetched_at": "2026-10-26T18:39:39.174162+08:00", "kind": "documentation", "sha256": "a2d17270c41509898d634e7c0aae9d51fc34cdc9825f7d29567baf92f7fab466", "snapshot_path": "sources/a2d17270c41509898d634e7c0aae9d51fc34cdc9825f7d29567baf92f7fab466.txt", "url": "https://openwisp.io/docs/stable/controller/user/intro.html"}, {"fetched_at": "2026-10-26T18:39:40.754126+08:00", "kind": "documentation", "sha256": "399d82e00080233ec2e7ecb84011c87ed47f392b73d06d8abdd480714a2ecca1", "snapshot_path": "sources/399d82e00080233ec2e7ecb84011c87ed47f392b73d06d8abdd480714a2ecca1.txt", "url": "https://openwisp.io/docs/stable/controller/user/push-operations.html"}], "summary": "OpenWISP Controller is an open-source network configuration manager for OpenWrt devices with configuration templates, device groups and push operations to devices.", "technology_stack": ["Python", "Django"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tangoe','Tangoe One Telecom','{"homepage": "https://www.tangoe.com/", "id": "commercial:tangoe", "leaf_matches": [{"reason": "官方 TEM 指南正文说明其收集发票、将发票与库存服务清单及合同费率比对以识别计费错误、管理账单争议并跟踪应得贷记与退款，并以潜在节省和实际节省金额跟踪审计结果；官方 Tangoe One Telecom 产品页正文说明计费问题会被识别并准备用于争议，在追回资金后报告月度节省。两项来源共同覆盖发票捕获与规范化→对账审计→差异→争议/贷记/节省的核心闭环。", "slug": "telecom-expense-management", "source_urls": ["https://www.tangoe.com/guides/what-is-telecom-expense-management-tem/", "https://www.tangoe.com/brochure/tangoe-one-telecom/", "https://www.tangoe.com/telecom-expense-management/invoice-audit-optimization/"]}], "name": "Tangoe One Telecom", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:39:44.027358+08:00", "kind": "documentation", "sha256": "102aba423887766dd3c364f92fcb4bef633414fb95e02a41966737c3d3ed8db2", "snapshot_path": "sources/102aba423887766dd3c364f92fcb4bef633414fb95e02a41966737c3d3ed8db2.txt", "url": "https://www.tangoe.com/telecom-expense-management/"}, {"fetched_at": "2026-10-26T18:39:46.296474+08:00", "kind": "documentation", "sha256": "d44fce819cda42440281a4b36c145c8b8d0a47659aaad05f39bfd433304f8f86", "snapshot_path": "sources/d44fce819cda42440281a4b36c145c8b8d0a47659aaad05f39bfd433304f8f86.txt", "url": "https://www.tangoe.com/telecom-expense-management/invoice-audit-optimization/"}, {"fetched_at": "2026-10-27T12:16:21.821466+08:00", "kind": "documentation", "sha256": "9e1d56abdc680bbdbca6a5ad5ee5bde7ebdaecd6377e18524eb1c131891b559a", "snapshot_path": "sources/9e1d56abdc680bbdbca6a5ad5ee5bde7ebdaecd6377e18524eb1c131891b559a.txt", "url": "https://www.tangoe.com/guides/what-is-telecom-expense-management-tem/"}, {"fetched_at": "2026-10-27T12:16:21.741347+08:00", "kind": "documentation", "sha256": "52e4d170ff4f0a8d732dd40a9f457037015c399ae6c62e7fd4a5417e71ce9ecf", "snapshot_path": "sources/52e4d170ff4f0a8d732dd40a9f457037015c399ae6c62e7fd4a5417e71ce9ecf.txt", "url": "https://www.tangoe.com/brochure/tangoe-one-telecom/"}], "summary": "Tangoe One Telecom is a commercial telecom expense management platform that collects and normalizes carrier invoices, audits charges against the service inventory and contracted rates, manages billing disputes and credits, and tracks telecom savings.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sharearchiver','ShareArchiver','{"homepage": "https://sharearchiver.com/", "id": "commercial:sharearchiver", "leaf_matches": [{"reason": "官方首页与 Archive Storage Solutions 页面说明其按策略将文件服务器/SharePoint 数据归档到本地或云端归档存储，并提供检索与恢复，符合归档存储管理的归档目标+受管转换+检索路径核心。", "slug": "archive-storage-management", "source_urls": ["https://sharearchiver.com/", "https://sharearchiver.com/our-solution/archive-storage-solutions/"]}], "name": "ShareArchiver", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:39:49.815379+08:00", "kind": "homepage", "sha256": "d9ca1351cadca2bd87b377f378853bddf06a738f0525a824bd4bea66ee2a8325", "snapshot_path": "sources/d9ca1351cadca2bd87b377f378853bddf06a738f0525a824bd4bea66ee2a8325.txt", "url": "https://sharearchiver.com/"}, {"fetched_at": "2026-10-26T18:39:52.831295+08:00", "kind": "documentation", "sha256": "fc806b1ba0b9da28bd3faa386901c23f62185799fd59dd393c858baa888350e6", "snapshot_path": "sources/fc806b1ba0b9da28bd3faa386901c23f62185799fd59dd393c858baa888350e6.txt", "url": "https://sharearchiver.com/our-solution/archive-storage-solutions/"}], "summary": "ShareArchiver is a commercial enterprise file archiving platform that applies policy-based archiving to move file server and SharePoint data into on-premises or cloud archive storage, with search and restore.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sap-leanix-application-portfolio-management','SAP LeanIX Application Portfolio Management','{"homepage": "https://www.leanix.net/en/products/application-portfolio-management", "id": "commercial:sap-leanix-application-portfolio-management", "leaf_matches": [{"reason": "官方产品页正文展示应用清单、明确所有权、按功能/技术适配/成本/生命周期评估、TIME 分类与退役影响分析，构成 APM 的应用登记、评估、处置与合理化循环。", "slug": "application-portfolio-management", "source_urls": ["https://www.leanix.net/en/products/application-portfolio-management"]}], "name": "SAP LeanIX Application Portfolio Management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:44:46.497779+08:00", "kind": "homepage", "sha256": "7c629c0f43e8a463dd3d19d027ab14beb9a6444f09db97806d6c35c40f31cb92", "snapshot_path": "sources/7c629c0f43e8a463dd3d19d027ab14beb9a6444f09db97806d6c35c40f31cb92.txt", "url": "https://www.leanix.net/en/products/application-portfolio-management"}], "summary": "SAP LeanIX 的企业架构应用组合管理产品，维护应用清单与所有权，按功能/技术适配、成本、生命周期等维度评估，并用 TIME 分类支持合理化、现代化与退役决策。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:61023964','Somleng','{"deployment": ["自托管部署", "AWS Terraform 基础设施配置"], "features": ["Twilio 兼容的可编程语音与 SMS REST API", "Carrier Dashboard 与账户管理", "电话号码的创建、更新、查询与删除", "消息、通话与事件记录查看", "团队与认证配置"], "github_repository_id": 61023964, "homepage": "https://www.somleng.org", "id": "github:61023964", "leaf_matches": [{"reason": "官方文档与官网说明 Somleng 提供 CPaaS Dashboard/API，覆盖 Accounts、Phone Numbers、Messages、Phone Calls、Authentication、Team 等管理面；README 与 MIT 许可证确认其开源身份。", "slug": "cpaas-management", "source_urls": ["https://www.somleng.org/docs.html", "https://www.somleng.org/", "https://raw.githubusercontent.com/somleng/somleng/develop/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/somleng/somleng/develop/LICENSE", "license_review": {"rationale": "抓取的仓库 LICENSE 为完整 MIT 文本，含授予条款与免责声明，并与 README 及官网标注的 MIT 许可证一致。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/somleng/somleng/develop/LICENSE", "spdx_id": "MIT"}, "name": "Somleng", "repository_url": "https://github.com/somleng/somleng", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:44:39.247167+08:00", "kind": "repository_metadata", "sha256": "01a5dab951898a3958b859da9e054280aea94c6ff96411b45f5873b68bedda78", "snapshot_path": "sources/01a5dab951898a3958b859da9e054280aea94c6ff96411b45f5873b68bedda78.txt", "url": "https://github.com/somleng/somleng"}, {"fetched_at": "2026-10-26T18:44:27.693550+08:00", "kind": "readme", "sha256": "26a836c383e34d365fded07b61bba650e7288e9a733919dc84f5aa2aeff5109d", "snapshot_path": "sources/26a836c383e34d365fded07b61bba650e7288e9a733919dc84f5aa2aeff5109d.txt", "url": "https://raw.githubusercontent.com/somleng/somleng/develop/README.md"}, {"fetched_at": "2026-10-26T18:46:15.544348+08:00", "kind": "license", "sha256": "e8a49b238763dd788d632f63ddde3c89a2363f2112afff50c212ee853c81be66", "snapshot_path": "sources/e8a49b238763dd788d632f6