INSERT INTO "application" VALUES('github:148059143','AKHQ','{"deployment": ["Docker/docker compose 快速启动", "支持 Helm 部署（文档导航）"], "features": ["查看 topics 并浏览 topic 内消息数据（分页与排序）", "topic 列表展示 consumer groups 列，consumer groups 视图可隐藏空组", "创建/修改/删除 topics、清空 topic，生产或删除记录", "更新/删除 consumer group offsets、删除 consumer group", "基于 TOPIC/TOPIC_DATA/CONSUMER_GROUP/ACL 等资源与角色的权限模型", "查看/管理 Schema Registry 与 Kafka Connect 状态"], "github_repository_id": 148059143, "homepage": "https://akhq.io/", "id": "github:148059143", "leaf_matches": [{"reason": "官方仓库内文档正文显示 topic data 的浏览与分页/排序、topic 列表的 consumer groups 列与 consumer groups 视图、topic 创建/配置/删除与清空、记录生产/删除、consumer group offsets 更新/删除，以及 TOPIC/TOPIC_DATA/CONSUMER_GROUP/ACL 的权限资源模型；README 确认其是 Kafka GUI，API 文档说明 list topic 暴露 consumer groups/offsets 并提供消息搜索/详情接口。属于 Kafka 管理面而非消息系统。未声称官方正文未出现的 consumer lag、死信浏览/重投或连接终止。", "slug": "message-queue-management", "source_urls": ["https://github.com/tchiotludo/akhq", "https://raw.githubusercontent.com/tchiotludo/akhq/master/README.md", "https://raw.githubusercontent.com/tchiotludo/akhq/dev/docs/docs/configuration/akhq.md", "https://raw.githubusercontent.com/tchiotludo/akhq/dev/docs/docs/configuration/audit.md", "https://raw.githubusercontent.com/tchiotludo/akhq/dev/docs/docs/configuration/authentifications/groups.md", "https://raw.githubusercontent.com/tchiotludo/akhq/dev/docs/docs/api.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/tchiotludo/akhq/master/LICENSE", "license_review": {"rationale": "抓取的仓库 LICENSE 为完整 Apache License 2.0 文本，含授权条款与免责声明，并与 README 及仓库页面标注一致。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/tchiotludo/akhq/master/LICENSE", "spdx_id": "Apache-2.0"}, "name": "AKHQ", "repository_url": "https://github.com/tchiotludo/akhq", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T18:44:38.784914+08:00", "kind": "repository_metadata", "sha256": "2c3e527