INSERT INTO "application" VALUES('commercial:edulog','Edulog','{"homepage": "https://www.edulog.com/", "id": "commercial:edulog", "leaf_matches": [{"reason": "官网正文说明其提供校车路线规划、GPS 车队追踪、学生乘车记录、司机管理与家长沟通应用，匹配学校交通管理的路线计划与日常运行核心。", "slug": "school-transportation-management", "source_urls": ["https://www.edulog.com/"]}], "name": "Edulog", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T13:53:22.424651+08:00", "kind": "homepage", "sha256": "32a03a535cc4785f48dfde88f1e549a916b09af3eb6f1efb782b9ff016cbf8a8", "snapshot_path": "sources/32a03a535cc4785f48dfde88f1e549a916b09af3eb6f1efb782b9ff016cbf8a8.txt", "url": "https://www.edulog.com/"}], "summary": "面向学区的校车路线规划、学生乘车、司机管理与家长沟通平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:samegoal','SameGoal','{"homepage": "https://samegoal.com/", "id": "commercial:samegoal", "leaf_matches": [{"reason": "官网与官方 Special Education/Features 页说明 SameGoal 是面向学区的特殊教育专项项目文档、管理与合规平台：支持州表与校验、IEP 目标/评估/进展报告、家长查看与电子签名、团队会议协作、文档历史与归档、项目参与和截止日期跟踪；官方 Illinois 州别截止日期指南列出转介、初评同意、会议通知、评估/资格、IEP、年度审查与再评估时限；官方 Service Log Export 指南证明服务日志含服务日期、服务类型、时长、场景、目标/进展与提供者签名。按商业基本记录，覆盖转介→评估→资格→IEP→服务/进展→会议→同意→合规时限的核心流程。", "slug": "special-education-management", "source_urls": ["https://samegoal.com/", "https://samegoal.com/sm/special-education", "https://samegoal.com/sm/features", "https://samegoal.com/iep/g/support/online-guides/state-specific-guide/illinois/se-deadlines", "https://samegoal.com/iep/g/support/online-guides/technical-guide/service-log-export"]}], "name": "SameGoal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:07:20+08:00", "kind": "homepage", "sha256": "cf8a2c7fe750b70169072a9f24dc454a7e3b2d84ca39cb532833299e250c8f4d", "snapshot_path": "sources/cf8a2c7fe750b70169072a9f24dc454a7e3b2d84ca39cb532833299e250c8f4d.txt", "url": "https://samegoal.com/"}, {"fetched_at": "2026-10-26T14:08:35+08:00", "kind": "documentation", "sha256": "5ccce6f522461be3edcfcfec249f7add06b027ecd48223fb2edfb142c555dbfc", "snapshot_path": "sources/5ccce6f522461be3edcfcfec249f7add06b027ecd48223fb2edfb142c555dbfc.txt", "url": "https://samegoal.com/sm/special-education"}, {"fetched_at": "2026-10-26T14:08:37+08:00", "kind": "documentation", "sha256": "2ea41ed0d95b167e08c4cc9ac9d04b405020851bff01e2bc363f5637bd01474b", "snapshot_path": "sources/2ea41ed0d95b167e08c4cc9ac9d04b405020851bff01e2bc363f5637bd01474b.txt", "url": "https://samegoal.com/sm/features"}, {"fetched_at": "2026-10-26T14:07:24+08:00", "kind": "documentation", "sha256": "710121c67c3ef032bff7268f53f2fa662dfb6f236946483d604254d82370e902", "snapshot_path": "sources/710121c67c3ef032bff7268f53f2fa662dfb6f236946483d604254d82370e902.txt", "url": "https://samegoal.com/iep/g/support/online-guides/state-specific-guide/illinois/se-deadlines"}, {"fetched_at": "2026-10-26T14:09:42.774114+08:00", "kind": "documentation", "sha256": "4ff68d3b944848ddf864f265d6c73e0841e5a01925266bfd8b8971daf0be0a85", "snapshot_path": "sources/4ff68d3b944848ddf864f265d6c73e0841e5a01925266bfd8b8971daf0be0a85.txt", "url": "https://samegoal.com/iep/g/support/online-guides/technical-guide/service-log-export"}], "summary": "面向学区特殊教育等专项项目的文档、合规与个案流程管理平台。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:300025829','Internet Archive Scholar','{"deployment": ["README 提供 Makefile 与本地 Elasticsearch docker-compose；本次未部署"], "features": ["学术论文全文检索", "书目记录索引与结果高亮", "Elasticsearch 索引与 Web 界面"], "github_repository_id": 300025829, "homepage": "https://scholar.archive.org", "id": "github:300025829", "leaf_matches": [{"reason": "README 说明该仓库是 scholar.archive.org 的源码，提供覆盖 2500 万篇以上开放研究论文的全文 Web 检索界面，由书目记录索引、查询与高亮结果组成，符合学术搜索引擎核心。", "slug": "academic-search-engine", "source_urls": ["https://api.github.com/repos/internetarchive/fatcat-scholar", "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/README.md", "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/LICENSE.AGPLv3.txt"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/LICENSE.AGPLv3.txt", "license_review": {"rationale": "The fetched LICENSE.AGPLv3.txt is the complete GNU Affero General Public License v3 text and contains the standard markers for this SPDX identifier.", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/LICENSE.AGPLv3.txt", "spdx_id": "AGPL-3.0"}, "name": "Internet Archive Scholar", "repository_url": "https://github.com/internetarchive/fatcat-scholar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:00:10.631755+08:00", "kind": "repository_metadata", "sha256": "1b89d85879088c77350942288f4caee14ee3a70ad09a84ee4df07af2f8af3998", "snapshot_path": "sources/1b89d85879088c77350942288f4caee14ee3a70ad09a84ee4df07af2f8af3998.txt", "url": "https://api.github.com/repos/internetarchive/fatcat-scholar"}, {"fetched_at": "2026-10-26T14:00:12.413111+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/LICENSE.AGPLv3.txt"}, {"fetched_at": "2026-10-26T14:00:13.834495+08:00", "kind": "readme", "sha256": "efa2fbb11df1e3a0fd545ea17b34a8e951d6f0786dafde12eb4a6bb0015f98d3", "snapshot_path": "sources/efa2fbb11df1e3a0fd545ea17b34a8e951d6f0786dafde12eb4a6bb0015f98d3.txt", "url": "https://raw.githubusercontent.com/internetarchive/fatcat-scholar/master/README.md"}], "summary": "面向开放获取学术论文的开源全文检索界面，检索 2500 万篇以上论文并展示书目结果。", "technology_stack": ["Python", "Elasticsearch"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:scopus','Scopus','{"homepage": "https://www.elsevier.com/products/scopus", "id": "commercial:scopus", "leaf_matches": [{"reason": "官方产品页确认 Scopus 为摘要与引文数据库并提及作者主页与作者检索；官方 Scopus Metrics 文档正文进一步证明其指标分析层：期刊层面有 CiteScore/SJR/SNIP（SNIP 明确可用于跨领域比较期刊），文章层面有引用次数、引用基准百分位与领域加权引用影响力，作者层面有 h-index、引用概览与可视化分析，且正文表述用于机构决策和跨期刊比较。据此按“引文库 + 实体指标与比较分析层”匹配文献计量平台；仅作商业基本记录。", "slug": "bibliometrics-platform", "source_urls": ["https://www.elsevier.com/products/scopus", "https://www.elsevier.com/products/scopus/metrics"]}], "name": "Scopus", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T14:00:22.906123+08:00", "kind": "homepage", "sha256": "3d67c77e4695b0aff5af2ae9101f8f8c2bd10598b555220f9691761bd548dd4a", "snapshot_path": "sources/3d67c77e4695b0aff5af2ae9101f8f8c2bd10598b555220f9691761bd548dd4a.txt", "url": "https://www.elsevier.com/products/scopus"}, {"fetched_at": "2026-10-27T12:56:47.979606+08:00", "kind": "documentation", "sha256": "14cf2b05cac88d5bd7cae00fb9b0b1c65e095119ee6ad6b310b51dc4b729962a", "snapshot_path": "sources/14cf2b05cac88d5bd7cae00fb9b0b1c65e095119ee6ad6b310b51dc4b729962a.txt", "url": "https://www.elsevier.com/products/scopus/metrics"}], "summary": "Elsevier 的摘要与引文数据库兼研究指标分析平台；官方 metrics 页展示期刊、文章、作者与机构层面的引用指标（CiteScore、SJR、SNIP、h-index、引用基准百分位等），并支持跨期刊、跨领域的比较分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
