INSERT INTO "application" VALUES('github:5705943','AtoM','{"deployment": ["web", "self-hosted"], "features": ["多级档案描述", "权威记录（创建者）", "查找辅助工具生成与发布", "多库与多语言", "EAD/EAC-CPF 等标准导入导出"], "github_repository_id": 5705943, "homepage": "https://www.accesstomemory.org/", "id": "github:5705943", "leaf_matches": [{"reason": "AtoM 官方 README 说明其用于标准化档案描述与访问；官方手册具体记录全宗/系列/文件/条目的多级描述、创建者权威记录，以及查找辅助工具的生成、上传、下载，构成档案管理系统的核心工作流。", "slug": "archives-management-system", "source_urls": ["https://github.com/artefactual/atom", "https://raw.githubusercontent.com/artefactual/atom/qa/2.x/LICENSE", "https://raw.githubusercontent.com/artefactual/atom/qa/2.x/README.md", "https://www.accesstomemory.org/", "https://www.accesstomemory.org/docs/latest/user-manual/add-edit-content/archival-descriptions/", "https://www.accesstomemory.org/docs/latest/user-manual/reports-printing/print-finding-aid/", "https://www.accesstomemory.org/docs/latest/user-manual/add-edit-content/authority-records/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/artefactual/atom/qa/2.x/LICENSE", "license_review": {"rationale": "仓库 LICENSE 为完整 AGPLv3 文本；README 与官网均声明 AtoM 以 AGPLv3 发布。", "reviewer": "collector", "scope": "repository", "source_url": "https://raw.githubusercontent.com/artefactual/atom/qa/2.x/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "AtoM", "repository_url": "https://github.com/artefactual/atom", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:19:59.335836+08:00", "kind": "repository_metadata", "sha256": "3c058f5e5f5e2ef287a5d78ad862f63a706edc282f5e7898782cc72c4fd54b93", "snapshot_path": "sources/3c058f5e5f5e2ef287a5d78ad862f63a706edc282f5e7898782cc72c4fd54b93.txt", "url": "https://github.com/artefactual/atom"}, {"fetched_at": "2026-10-25T08:20:05.000625+08:00", "kind": "license", "sha256": "91b65277959ec273763d28ef002e83a6b3fba57c7a35436c9e5b66536333d720", "snapshot_path": "sources/91b65277959ec273763d28ef002e83a6b3fba57c7a35436c9e5b66536333d720.txt", "url":