INSERT INTO "application" VALUES('github:5885483','Koha','{"deployment": ["web", "self-hosted"], "features": ["书目记录与馆藏复本（items/holdings）", "读者记录与借阅权限", "流通规则驱动的借出/续借/归还", "预约、转移与逾期处理"], "github_repository_id": 5885483, "homepage": "https://koha-community.org/", "id": "github:5885483", "leaf_matches": [{"reason": "Koha 官方手册 Cataloging 页明确每条书目记录可附加一个或多个 items（holdings），每个 item 记录实体复本的馆藏地、索书号与条码等信息；Circulation 页记录从读者条码启动借出、到期日按 circulation rules 计算，并包含续借与 check-in（归还）流程；Administration 页的 “Circulation and fine rules” 明确这些规则定义物品如何流通、罚款如何计算及预约如何处理，并按馆别、读者类别与物品类型组合配置；Patrons 页记录读者记录、读者类别与借阅权限的创建。四者共同支撑“书目/复本—读者—受控借阅”的 ILS 核心。README 与官网确认其 free software ILS 身份，GitHub 元数据 ID 5885483 且标注为官方仓库同步镜像。", "slug": "integrated-library-system-ils", "source_urls": ["https://github.com/koha-community/Koha", "https://raw.githubusercontent.com/koha-community/Koha/main/LICENSE", "https://raw.githubusercontent.com/koha-community/Koha/main/README.md", "https://koha-community.org/", "https://koha-community.org/manual/latest/en/html/cataloging.html", "https://koha-community.org/manual/latest/en/html/circulation.html", "https://koha-community.org/manual/latest/en/html/patrons.html", "https://koha-community.org/manual/latest/en/html/administration.html"]}], "license": "GPL-3.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/koha-community/Koha/main/LICENSE", "license_review": {"rationale": "LICENSE 为完整 GNU GPL Version 3 文本；README 明确写明 ''Koha is distributed under the GNU GPL version 3 or later''，仓库元数据页面亦重复该 ''or later'' 声明，故记为 GPL-3.0-or-later而非 only GPL-3.0。", "reviewer": "collector", "scope": "repository", "source_url": "https://raw.githubusercontent.com/koha-community/Koha/main/LICENSE", "spdx_id": "GPL-3.0-or-later"}, "name": "Koha", "repository_url": "https://github.com/koha-community/Koha", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:18:02.564274+08:00", "kind": "repository_metadata", "sha256": "f1331e8ad12e6110004ddc836d4d28bd87844e87e7c2956b351