ion", "sha256": "bcf2da204bf16945e088e637aa4f1204a3a3a6e434d6ffebcea06c698c0139c0", "snapshot_path": "sources/bcf2da204bf16945e088e637aa4f1204a3a3a6e434d6ffebcea06c698c0139c0.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/entities/PersonType.java"}, {"fetched_at": "2026-10-27T01:06:52.839444+08:00", "kind": "documentation", "sha256": "6ba77903cfbccd99d62e79ae25fa8a8f21856d1cb8b23c53bd775d67934781ae", "snapshot_path": "sources/6ba77903cfbccd99d62e79ae25fa8a8f21856d1cb8b23c53bd775d67934781ae.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/entities/EnforcableCodeElement.java"}, {"fetched_at": "2026-10-27T01:07:01.553072+08:00", "kind": "documentation", "sha256": "3a7aa083ed2480c4dea3b6b625ece170ff5f9e873389b340d012fbb99c9b728b", "snapshot_path": "sources/3a7aa083ed2480c4dea3b6b625ece170ff5f9e873389b340d012fbb99c9b728b.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/entities/Person.java"}, {"fetched_at": "2026-10-27T01:07:02.817132+08:00", "kind": "documentation", "sha256": "11d3a4312d99dbe942a2fe3e920e304113827e4ec6953272ecc56eae1aba50c8", "snapshot_path": "sources/11d3a4312d99dbe942a2fe3e920e304113827e4ec6953272ecc56eae1aba50c8.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/entities/CodeElement.java"}, {"fetched_at": "2026-10-27T01:07:12.278392+08:00", "kind": "documentation", "sha256": "60e40447a7966c02a25febe58d82a707f7746b3ae1101562aef39b9b2b680009", "snapshot_path": "sources/60e40447a7966c02a25febe58d82a707f7746b3ae1101562aef39b9b2b680009.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/application/NoticeOfViolationBB.java"}, {"fetched_at": "2026-10-27T01:07:18.988067+08:00", "kind": "documentation", "sha256": "9e257d55ec18523d035a515e99a8280e2b1aaea265641260d88a08470bad8135", "snapshot_path": "sources/9e257d55ec18523d035a515e99a8280e2b1aaea265641260d88a08470bad8135.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/src/java/com/tcvcog/tcvce/integration/CodeViolationIntegrator.java"}, {"fetched_at": "2026-10-27T01:07:44.045318+08:00", "kind": "documentation", "sha256": "3f6d64f7ff68ca04b5fe28c35c6839618e0ab5b681281efa7a8ca0e04ce163f2", "snapshot_path": "sources/3f6d64f7ff68ca04b5fe28c35c6839618e0ab5b681281efa7a8ca0e04ce163f2.txt", "url": "https://raw.githubusercontent.com/TechnologyRediscovery/codeenforcement/master/database/cogdb_v0.9/entityCreation_step1_v0.9.sql"}], "summary": "面向美国地方政府的开源法规执法与占用许可数据库，以房产为记录锚点，管理执法案件、法规条款违规、整改期限、通知与案件阶段。", "technology_stack": ["Java", "JSF", "PrimeFaces", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1259409130','TPT Court','{"deployment": ["Docker Compose + PostgreSQL + Redis", "Next.js Web 与 Fastify API"], "features": ["案件编号、类型、状态与结案原因", "当事人、律师与角色权限", "案件文档、听证与动议", "支付、通知与审计日志"], "github_repository_id": 1259409130, "homepage": "https://opensource.tptsolutions.co.nz/tpt-court", "id": "github:1259409130", "leaf_matches": [{"reason": "README 与 Prisma schema 显示案件编号、类型、状态、结案原因、当事人、文档、听证、动议及审计日志，构成法院案件登记与流程记录核心。", "slug": "court-case-management-system", "source_urls": ["https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/README.md", "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/packages/database/prisma/schema.prisma"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/LICENSE", "license_review": {"rationale": "Raw LICENSE contains the standard MIT permission and copyright notice; README and Prisma schema describe court case management, parties, documents, hearings and dispositions.", "reviewer": "OpenCode collector (beam-free)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/LICENSE", "spdx_id": "MIT"}, "name": "TPT Court", "repository_url": "https://github.com/tpt-solutions/tpt-court", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:14:56.009295+08:00", "kind": "repository_metadata", "sha256": "9d2b0f4e15d96fd1e3fb6afab0dfa4d2373b8f8aea84a417a4fe6045e88cb3b3", "snapshot_path": "sources/9d2b0f4e15d96fd1e3fb6afab0dfa4d2373b8f8aea84a417a4fe6045e88cb3b3.txt", "url": "https://github.com/tpt-solutions/tpt-court"}, {"fetched_at": "2026-10-25T08:15:00.557605+08:00", "kind": "license", "sha256": "a5ee2ae16b75df974d3eeb973fdcc65498cbfa8d0adc27d1d20582ab3da57ce5", "snapshot_path": "sources/a5ee2ae16b75df974d3eeb973fdcc65498cbfa8d0adc27d1d20582ab3da57ce5.txt", "url": "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/LICENSE"}, {"fetched_at": "2026-10-25T08:15:51.879375+08:00", "kind": "readme", "sha256": "512e803b3fcac6f3c89136d91574eafca40bd79ec7c3cc2d344bc4e7e38665d5", "snapshot_path": "sources/512e803b3fcac6f3c89136d91574eafca40bd79ec7c3cc2d344bc4e7e38665d5.txt", "url": "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/README.md"}, {"fetched_at": "2026-10-27T00:56:50.428168+08:00", "kind": "documentation", "sha256": "3b8ea64da42e7ca0765e38430a6ab3206d5de3d3078df652d22d05d335d7dfae", "snapshot_path": "sources/3b8ea64da42e7ca0765e38430a6ab3206d5de3d3078df652d22d05d335d7dfae.txt", "url": "https://raw.githubusercontent.com/tpt-solutions/tpt-court/master/packages/database/prisma/schema.prisma"}], "summary": "开源法院案件管理平台，支持案件编号与状态、当事人、文档、听证、支付、通知及法官/书记员/律师/公众角色权限。", "technology_stack": ["TypeScript", "Next.js", "Fastify", "Prisma", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:31054058','GiveWP','{"deployment": ["WordPress 插件", "自托管"], "features": ["可定制在线捐赠表单（捐赠层级、自定义金额、嵌入页面或独立表单页）", "Stripe/PayPal 在线支付（核心插件内置）", "捐赠记录与捐赠者管理", "募款报告与导出（按日期、表单、支付方式筛选）", "抵税收据生成", "定期捐赠（付费附加组件 Recurring Donations）", "PDF 收据（付费附加组件）"], "github_repository_id": 31054058, "homepage": "https://givewp.com/", "id": "github:31054058", "leaf_matches": [{"reason": "官方插件 readme.txt 的 Description/Features 正文说明：可创建可定制在线捐赠表单并设置捐赠层级或自定义金额，通过 block、shortcode、widget 或独立表单页常设展示；核心免费支持由组织配置的 Stripe/PayPal 账户处理支付；可查看捐赠者数据与募款报告、管理捐赠者、生成抵税收据，并按日期/表单/支付方式筛选和导出报告。定期捐赠、PDF 收据、P2P 等在 readme 中列为付费附加组件，未计入开源核心。", "slug": "online-donation-platform", "source_urls": ["https://raw.githubusercontent.com/impress-org/givewp/develop/readme.txt"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/impress-org/givewp/license", "license_review": {"rationale": "GitHub license API 快照返回 SPDX GPL-3.0，content 解码为完整 GPLv3 正文；仓库 README 徽章仍标 GPL-2.0+ 并指向另一仓库 license.txt，属徽章口径不一致，以 LICENSE API 快照为准。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/impress-org/givewp/license", "spdx_id": "GPL-3.0"}, "name": "GiveWP", "repository_url": "https://github.com/impress-org/givewp", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:22:40.136302+08:00", "kind": "repository_metadata", "sha256": "a00c3f4989807f70a92fa7d0d2c3758514805109c4380ed41d57f56595fe0341", "snapshot_path": "sources/a00c3f4989807f70a92fa7d0d2c3758514805109c4380ed41d57f56595fe0341.txt", "url": "https://api.github.com/repos/impress-org/givewp"}, {"fetched_at": "2026-10-25T08:22:43.076752+08:00", "kind": "license", "sha256": "1ea0231f76e4d85ada71e89d1093ead1c1950ac77c679b3213d2db29935f6928", "snapshot_path": "sources/1ea0231f76e4d85ada71e89d1093ead1c1950ac77c679b3213d2db29935f6928.txt", "url": "https://api.github.com/repos/impress-org/givewp/license"}, {"fetched_at": "2026-10-26T14:49:05.543884+08:00", "kind": "readme", "sha256": "ccd3bb4c01300ca5c11460869aba28ed145e96e9bc3e0612d1640683e0fde513", "snapshot_path": "sources/ccd3bb4c01300ca5c11460869aba28ed145e96e9bc3e0612d1640683e0fde513.txt", "url": "https://raw.githubusercontent.com/impress-org/givewp/develop/README.md"}, {"fetched_at": "2026-10-26T14:57:30.763581+08:00", "kind": "readme", "sha256": "2cad2eca463e9d1eb850987eed54e8e2ded40b8c6314dd91bfea17e3259c4f15", "snapshot_path": "sources/2cad2eca463e9d1eb850987eed54e8e2ded40b8c6314dd91bfea17e3259c4f15.txt", "url": "https://raw.githubusercontent.com/impress-org/givewp/develop/readme.txt"}], "summary": "GPL-3.0 WordPress 在线捐赠插件（核心开源版）：提供可定制在线捐赠表单、Stripe/PayPal 支付、捐赠记录与捐赠者管理、募款报告及抵税收据；定期捐赠、PDF 收据与 P2P 等为付费附加组件。", "technology_stack": ["PHP", "WordPress"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:agilysys-central-reservations','Agilysys Central Reservations','{"homepage": "https://www.agilysys.com/en/products/central-reservation/", "id": "commercial:agilysys-central-reservations", "leaf_matches": [{"reason": "官方正文明确其为 centralized reservation system (CRS)：集中管理跨物业、房型和渠道的 availability、rates、restrictions，提供 real-time reservation engine，支持 call center/front desk 预订、修改、取消，并与 PMS、channel managers、booking engines 集成；同时覆盖中央可售库存、中央预订记录和分销交换。", "slug": "hotel-central-reservation-system-crs", "source_urls": ["https://www.agilysys.com/en/products/central-reservation/"]}], "name": "Agilysys Central Reservations", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:27:35.265432+08:00", "kind": "homepage", "sha256": "c96ac2be9d9ec68f862f06670c08406b770a098e337f95cf940ac5814ce84ff0", "snapshot_path": "sources/c96ac2be9d9ec68f862f06670c08406b770a098e337f95cf940ac5814ce84ff0.txt", "url": "https://www.agilysys.com/en/products/central-reservation/"}], "summary": "Commercial central reservation system centralizing inventory, rates and availability across properties and channels, with a real-time reservation engine for booking, modification and cancellation.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:siteminder-channel-manager','SiteMinder Channel Manager','{"homepage": "https://www.siteminder.com/channel-manager/", "id": "commercial:siteminder-channel-manager", "leaf_matches": [{"reason": "官方产品页说明可从单一平台连接 500+ 预订渠道、一次映射房型与房价、实时同步 rates/availability/restrictions，并与 PMS/CRS 集成；页面并称预订或库存变化会触发实时可用性更新，匹配多渠道中继的核心。", "slug": "hotel-channel-manager", "source_urls": ["https://www.siteminder.com/channel-manager/"]}], "name": "SiteMinder Channel Manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:23:09.193422+08:00", "kind": "homepage", "sha256": "00f71b5f879ac6668752021f8ab9bbf4330443f52d66c2d02166a5da8f600e06", "snapshot_path": "sources/00f71b5f879ac6668752021f8ab9bbf4330443f52d66c2d02166a5da8f600e06.txt", "url": "https://www.siteminder.com/channel-manager/"}], "summary": "Commercial hotel channel manager that publishes rates, availability and restrictions from one platform to 500+ booking channels and integrates with PMS/CRS systems.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:dailypoint','dailypoint','{"homepage": "https://www.dailypoint.com/the-cdp-for-crm-loyalty", "id": "commercial:dailypoint", "leaf_matches": [{"reason": "官方忠诚度产品页为主要证据：正文说明其运营 B2C/B2B/HR 忠诚度计划，管理 points、tiers、status 与权益，提供会员注册、积分查看、奖励兑换和品牌化会员门户；CRM/CDP 页补充其从 200+ 系统收集并合并客人数据为 Central Profiles，并与 PMS/POS/CRS/IBE 实时同步。统一客人档案与忠诚度计划记录两侧均具备，匹配酒店 CRM/忠诚度平台。", "slug": "hotel-crm-loyalty-platform", "source_urls": ["https://www.dailypoint.com/solutions/loyalty-programs-for-hotels", "https://www.dailypoint.com/the-cdp-for-crm-loyalty"]}], "name": "dailypoint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:25:52.116939+08:00", "kind": "homepage", "sha256": "ab49d9777f5b4e05c18618a28d7d511bbf15b39ecddf1d46a55d07a6be003bf3", "snapshot_path": "sources/ab49d9777f5b4e05c18618a28d7d511bbf15b39ecddf1d46a55d07a6be003bf3.txt", "url": "https://www.dailypoint.com/the-cdp-for-crm-loyalty"}, {"fetched_at": "2026-10-26T15:26:07.768014+08:00", "kind": "documentation", "sha256": "36e6712d1aac2c843b382a3daec5ba69d4aa66eb5f7036fb868657a950450c23", "snapshot_path": "sources/36e6712d1aac2c843b382a3daec5ba69d4aa66eb5f7036fb868657a950450c23.txt", "url": "https://www.dailypoint.com/solutions/loyalty-programs-for-hotels"}], "summary": "Commercial hospitality customer data platform for hotel CRM and loyalty, consolidating guest data into central profiles and operating points, tiers and status across PMS/POS/CRS systems.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1289281455','Kamra PMS','{"deployment": ["Docker", "Frappe Bench self-hosting"], "features": ["Front desk arrivals and departures", "Check-in with room assignment", "Check-out and folios", "Folio split and tax invoice", "Night audit", "Housekeeping", "Booking engine", "POS"], "github_repository_id": 1289281455, "homepage": "https://kamrapms.com", "id": "github:1289281455", "leaf_matches": [{"reason": "README 描述前台工作流：arrivals/departures/in-house 工作队列、分步 check-in（房号、押金、登记卡、钥匙）、check-out 账单、folio 拆分/转账/开票及夜审，且提供 Docker 与 Frappe Bench 自托管方式，匹配前台系统的核心循环。", "slug": "hotel-front-desk-application", "source_urls": ["https://api.github.com/repos/Kamra-PMS/kamra-pms", "https://raw.githubusercontent.com/Kamra-PMS/kamra-pms/develop/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/Kamra-PMS/kamra-pms/license", "name": "Kamra PMS", "repository_url": "https://github.com/Kamra-PMS/kamra-pms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:23:09.273231+08:00", "kind": "repository_metadata", "sha256": "5adb55db1d574c91b7da768cfab59962b1dae08763f005938827532059e56684", "snapshot_path": "sources/5adb55db1d574c91b7da768cfab59962b1dae08763f005938827532059e56684.txt", "url": "https://api.github.com/repos/Kamra-PMS/kamra-pms"}, {"fetched_at": "2026-10-26T15:23:11.465677+08:00", "kind": "license", "sha256": "c4bbf88a979c86a4685911beb429c840b22f4ed139745201af2afd3672083c09", "snapshot_path": "sources/c4bbf88a979c86a4685911beb429c840b22f4ed139745201af2afd3672083c09.txt", "url": "https://api.github.com/repos/Kamra-PMS/kamra-pms/license"}, {"fetched_at": "2026-10-26T15:23:13.203114+08:00", "kind": "readme", "sha256": "05ce2d1425a76e8a49f0915cc765938d66add783858f8b6e732d263c4bd7d572", "snapshot_path": "sources/05ce2d1425a76e8a49f0915cc765938d66add783858f8b6e732d263c4bd7d572.txt", "url": "https://raw.githubusercontent.com/Kamra-PMS/kamra-pms/develop/README.md"}], "summary": "Open-source (AGPL-3.0 community core) hotel and short-term rental PMS with front-desk arrivals/departures, check-in/out, folios and night audit; paid implementation/support and Frappe Cloud hosting are outside the community core.", "technology_stack": ["Frappe v16", "Python", "MariaDB", "React", "Vite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:bluecart','BlueCart','{"homepage": "https://www.bluecart.com", "id": "commercial:bluecart", "leaf_matches": [{"reason": "Official restaurant procurement page describes creating and sending digital purchase orders against supplier catalogs with live pricing and availability, receiving deliveries, and matching incoming supplier invoices to purchase orders line by line with price, quantity, or product discrepancies flagged before payment approval.", "slug": "restaurant-procurement-platform", "source_urls": ["https://www.bluecart.com/restaurant-procurement-software"]}], "name": "BlueCart", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:43:13.331111+08:00", "kind": "homepage", "sha256": "2405347c404dbfb00370819c87ca3e92beb502015aacd99ffc7610c05a74b93b", "snapshot_path": "sources/2405347c404dbfb00370819c87ca3e92beb502015aacd99ffc7610c05a74b93b.txt", "url": "https://www.bluecart.com"}, {"fetched_at": "2026-10-26T15:36:59.044816+08:00", "kind": "documentation", "sha256": "a8b15c2b0583e68650a4e3aa37ea7c1cc3c2aba1deb658804f00232dbe9200ea", "snapshot_path": "sources/a8b15c2b0583e68650a4e3aa37ea7c1cc3c2aba1deb658804f00232dbe9200ea.txt", "url": "https://www.bluecart.com/restaurant-procurement-software"}], "summary": "Commercial restaurant procurement platform for operators: supplier catalogs with pricing and availability, digital purchase orders, mobile receiving, and line-by-line invoice matching.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:resy','Resy','{"homepage": "https://resy.com", "id": "commercial:resy", "leaf_matches": [{"reason": "Official operator-side /join/reservations page body describes reservations and experiences, availability planning that controls what inventory is made bookable, table pacing and table reconfiguration, walk-in and cancellation waitlists (Notify), credit card holds and deposits/prepayment, and guest profiles with notes, tags, visit history, and spend. It also states that guests can book directly through Reserve with Google and claim an available reservation. The earlier /restaurants citation is withdrawn because that URL redirects to the /join marketing page; the withdrawn snapshot is not used for this match. The page does not document an overbooking algorithm, so no such claim is made.", "slug": "restaurant-reservation-platform", "source_urls": ["https://resy.com/join/reservations/"]}], "name": "Resy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:42:58.982260+08:00", "kind": "homepage", "sha256": "7adfadda7bd0c6361dc3a29dde12d413b52ae78918fbd20cdbce9980ec55ed00", "snapshot_path": "sources/7adfadda7bd0c6361dc3a29dde12d413b52ae78918fbd20cdbce9980ec55ed00.txt", "url": "https://resy.com"}, {"fetched_at": "2026-10-26T15:50:05.091923+08:00", "kind": "documentation", "sha256": "1b4932ec77e982d4916ecdf0e38f9a853661f7d0eb5c09bec88357286e4c2388", "snapshot_path": "sources/1b4932ec77e982d4916ecdf0e38f9a853661f7d0eb5c09bec88357286e4c2388.txt", "url": "https://resy.com/join/reservations/"}], "summary": "Commercial restaurant reservation and guest management platform: operator reservations and experiences, bookable availability and table pacing, waitlists, card holds and deposits, and guest profiles with visit history.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:grubbrr','GRUBBRR','{"homepage": "https://grubbrr.com/", "id": "commercial:grubbrr", "leaf_matches": [{"reason": "Official self-ordering kiosk product page body states that customers customize orders and verify their choices on venue-installed self-service kiosks, choose where they want to receive the order, and that kiosk orders go straight to the kitchen. The page also describes integration with existing POS, loyalty, and payment systems, contactless payment, and automated upselling. The match is limited to this customer-composed, venue-controlled ordering and kitchen handoff; the page does not evidence separate order-progress-board or kitchen-display behavior, so those are not asserted.", "slug": "self-service-restaurant-ordering", "source_urls": ["https://grubbrr.com/products/self-ordering-kiosk-machine/"]}], "name": "GRUBBRR", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:38:37.617358+08:00", "kind": "homepage", "sha256": "12e0d741be894d288225d5601821b111f4270c5852e837382c76cb2323bc1408", "snapshot_path": "sources/12e0d741be894d288225d5601821b111f4270c5852e837382c76cb2323bc1408.txt", "url": "https://grubbrr.com/"}, {"fetched_at": "2026-10-26T15:50:08.815311+08:00", "kind": "documentation", "sha256": "89d215daf7f467ad8ebbf5aa929a73bd2a440f66f37743a8502a34526f563707", "snapshot_path": "sources/89d215daf7f467ad8ebbf5aa929a73bd2a440f66f37743a8502a34526f563707.txt", "url": "https://grubbrr.com/products/self-ordering-kiosk-machine/"}], "summary": "Commercial venue-operated self-service kiosk platform for restaurants: customers browse and customize the venue menu on installed kiosks, review and confirm orders, and send them into the venue''s POS and kitchen flow, with upselling, contactless payment, and loyalty/payment integrations.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:awin','Awin','{"homepage": "https://www.awin.com", "id": "commercial:awin", "leaf_matches": [{"reason": "Official content-creator page describes creators joining brand affiliate programs, creating and sharing unique affiliate links across content formats, earning commission when a sale is generated, tracking sales and top partnerships, and receiving secure payments through the creator-facing Awin app.", "slug": "creator-affiliate-dashboard", "source_urls": ["https://www.awin.com/us/publishers"]}], "name": "Awin", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:38:41.504965+08:00", "kind": "homepage", "sha256": "76df0073ec353e24afc69b2e27088246afae85f3f3f06882a3d8f9163e5120b8", "snapshot_path": "sources/76df0073ec353e24afc69b2e27088246afae85f3f3f06882a3d8f9163e5120b8.txt", "url": "https://www.awin.com/us/publishers"}], "summary": "Commercial affiliate network with a creator/publisher-side dashboard for joining brand programs, creating trackable affiliate links, earning commissions, tracking performance, and receiving payments.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:circle','Circle','{"homepage": "https://circle.so", "id": "commercial:circle", "leaf_matches": [{"reason": "Official Circle homepage presents a branded community venue with discussions, events and courses, plus built-in payments supporting one-time purchases, memberships or recurring subscriptions and access groups.", "slug": "paid-community-platform", "source_urls": ["https://circle.so/"]}], "name": "Circle", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-25T08:41:53.603866+08:00", "kind": "homepage", "sha256": "e5b76bb56f9400a4f9931574602e66904afe7ff1fd571716fd7f3da520458e45", "snapshot_path": "sources/e5b76bb56f9400a4f9931574602e66904afe7ff1fd571716fd7f3da520458e45.txt", "url": "https://circle.so/"}], "summary": "Commercial community platform for hosting branded member spaces with built-in checkout for one-time purchases, memberships and recurring subscriptions.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:familiar','Familiar','{"homepage": "https://familiar.pub/", "id": "commercial:familiar", "leaf_matches": [{"reason": "Official Familiar homepage and royalty/contract product pages show a complete author-management spine: book records with ISBNs and formats plus contributors with roles and royalty percentages; contract templates with per-format rates, advances, reserves, signers and agents that flow into royalty tracking; distributor statement imports matched to books; per-contributor calculations, advances and splits, statements, and a contributor/agent portal. The readable body is present deeper in the archived homepage HTML, not only in its head/shell.", "slug": "author-management-platform", "source_urls": ["https://familiar.pub/", "https://familiar.pub/products/royalty-tracking-software", "https://familiar.pub/products/contract-management"]}, {"reason": "The official Familiar homepage positions the product as an all-in-one platform for modern publishers and authors and shows the publishing-management spine: title records carrying formats, ISBNs and publication dates with a launch plan; contributors attached to titles; and a Production & metadata section where each book gets a production schedule dated back from its publication date, with ISBN blocks per format and ONIX delivery. The contract product page adds structured per-format royalty terms, advances, reserves and signers, plus a publication-date addendum, so the contributor attachment rests on recorded contract terms rather than only biographical metadata.", "slug": "book-publishing-management", "source_urls": ["https://familiar.pub/", "https://familiar.pub/products/contract-management"]}], "name": "Familiar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-26T15:49:25+08:00", "kind": "homepage", "sha256": "11a97075f0aaa08eec52a30c2eb291e02e25063afd98d94cf2655815ed586cfa", "snapshot_path": "sources/11a97075f0aaa08eec52a30c2eb291e02e25063afd98d94cf2655815ed586cfa.txt", "url": "https://familiar.pub/"}, {"fetched_at": "2026-10-26T16:05:04+08:00", "kind": "homepage", "sha256": "3bd6466864354136ffdba939d94684da0916f5586920c6e5a12e07ccbe927787", "snapshot_path": "sources/3bd6466864354136ffdba939d94684da0916f5586920c6e5a12e07ccbe927787.txt", "url": "https://familiar.pub/products/royalty-tracking-software"}, {"fetched_at": "2026-10-26T16:05:04+08:00", "kind": "homepage", "sha256": "77b0901ec315cf17a62b5d754203baaf85231b379c3da3012f4976f820877006", "snapshot_path": "sources/77b0901ec315cf17a62b5d754203baaf85231b379c3da3012f4976f820877006.txt", "url": "https://familiar.pub/products/contract-management"}], "summary": "Commercial publishing and royalty management platform that keeps book/edition catalog records, attaches authors and other contributors with royalty shares, manages publishing contracts, and runs distributor statement imports through contributor statements and payments.", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:gigwell','Gigwell','{"homepage": "https://www.gigwell.com/", "id": "commercial:gigwell", "leaf_matches": [{"reason": "官方 Productivity Suite 页面说明其管理艺人名册，为每位艺人建立含 EPK 的预订页，接收 talent buyer 的预订请求，并用合同、电子签名、押金/在线付款和财务报告完成确认与结算；对应可预订艺人档案、有日期预订与确认生命周期。", "slug": "artist-booking-platform", "source_urls": ["https://www.gigwell.com/", "https://www.gigwell.com/productivity"]}], "name": "Gigwell", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:39:28.946510+08:00", "kind": "homepage", "sha256": "f90790b63c881db990da51e0c647e440863e2835e789afd79ee9936da6ab80a8", "snapshot_path": "sources/f90790b63c881db990da51e0c647e440863e2835e789afd79ee9936da6ab80a8.txt", "url": "https://www.gigwell.com/"}, {"fetched_at": "2026-10-27T01:41:17.508773+08:00", "kind": "documentation", "sha256": "6fe3e66e3ec5b10ff730d2ed1f1ae8e13a6ea368afc03733410872a1572585e3", "snapshot_path": "sources/6fe3e66e3ec5b10ff730d2ed1f1ae8e13a6ea368afc03733410872a1572585e3.txt", "url": "https://www.gigwell.com/productivity"}], "summary": "面向演出经纪、艺人和场地的云预订管理平台，覆盖艺人名册/EPK、预订请求、合同签署、押金/在线收款，以及预订、付款和财务报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:patronmanager','PatronManager','{"homepage": "https://patronmanager.com/", "id": "commercial:patronmanager", "leaf_matches": [{"reason": "官方首页面向交响乐团、剧院、舞蹈团等演出机构，明确将 ticketing、fundraising、marketing 汇于一个连接平台，全部数据存于单一系统，并覆盖订阅、捐赠者关系、演出活动与受众参与；对应统一赞助人记录、机构自有演出票务和筹款/会员/营销关系循环。", "slug": "performing-arts-organization-management", "source_urls": ["https://patronmanager.com/"]}], "name": "PatronManager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:39:51.778959+08:00", "kind": "homepage", "sha256": "720c7e3a8443dd186bbe70f70a9bafb7f965077fa53b3831ffc9bd29049e105d", "snapshot_path": "sources/720c7e3a8443dd186bbe70f70a9bafb7f965077fa53b3831ffc9bd29049e105d.txt", "url": "https://patronmanager.com/"}], "summary": "面向演出艺术机构的票务、筹款与营销一体化 CRM，将观众、订阅、捐赠和演出数据集中在同一系统；现属 Ticketure 家族，产品继续运营。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wipo-connect','WIPO Connect','{"homepage": "https://www.wipo.int/en/web/wipo-connect", "id": "commercial:wipo-connect", "leaf_matches": [{"reason": "WIPO 官方页面说明该软件供 CMO 运行集体管理：登记权利人并管理作品、表演、录音及份额、许可协议等档案；对被使用的作品进行识别与匹配并提供使用报告/数据采集；按使用、文档与本地参数生成向权利人分配的版税报告。协会代表曲库、使用→权利人归属与许可收费分配三项结构在同一 CMO 系统内成立，而非仅许可或版税报告的基础设施。", "slug": "performing-rights-management", "source_urls": ["https://www.wipo.int/en/web/wipo-connect"]}], "name": "WIPO Connect", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:48:41.964600+08:00", "kind": "documentation", "sha256": "575394c6a0962cb0193132dd675b35b879aedb9c18252d02457fed22fdfe10f3", "snapshot_path": "sources/575394c6a0962cb0193132dd675b35b879aedb9c18252d02457fed22fdfe10f3.txt", "url": "https://www.wipo.int/en/web/wipo-connect"}], "summary": "WIPO 开发的面向集体管理组织（CMO）的版权与相关权集体管理软件，覆盖权利人登记、作品/表演/录音档案、许可协议、使用匹配与版税分配报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:inentertainment','inEntertainment','{"homepage": "https://www.inentertainment.com/", "id": "commercial:inentertainment", "leaf_matches": [{"reason": "官方首页模块卡片列出 ADDRESSES（客户与联系人信息）、BOOKINGS（客户可远程查看日程）、CALENDARS（按客户与用户分设日历）、PROJECTS（导入 Film/TV/Commercial 项目）、PROPERTIES（跟踪 incoming/outgoing submissions，含剧本、图书、文章与 online reels）以及 bookings、commission and income reports；Accounting 页说明其管理 client trust accounts 与 revenue centers，可处理付款、经支票或电子转账向客户/第三方分配收入、跟踪预付款、开票，并覆盖应收账款、商业重新谈判、佣金收入与税务信息。对应所代表客户记录、项目/提交管道与客户收入→佣金/信托结算循环。", "slug": "talent-agency-management", "source_urls": ["https://www.inentertainment.com/", "https://www.inentertainment.com/accounting/"]}], "name": "inEntertainment", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:40:48.169486+08:00", "kind": "homepage", "sha256": "19dd04ed75c6915cbc43b4d517d4254736e819ce6f114855c9b65dff7aaaf016", "snapshot_path": "sources/19dd04ed75c6915cbc43b4d517d4254736e819ce6f114855c9b65dff7aaaf016.txt", "url": "https://www.inentertainment.com/"}, {"fetched_at": "2026-10-27T13:30:22.013294+08:00", "kind": "documentation", "sha256": "0022dcc14a7e7a5c2aefc266b2eabcab1c6aca8ba588b81896b63da0b387b73b", "snapshot_path": "sources/0022dcc14a7e7a5c2aefc266b2eabcab1c6aca8ba588b81896b63da0b387b73b.txt", "url": "https://www.inentertainment.com/accounting/"}], "summary": "面向演出/影视经纪与管理公司的客户与联系人、客户日程、项目与提交跟踪、信托会计及佣金收入报表系统。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:greenslate-production-accounting','GreenSlate Production Accounting','{"homepage": "https://greenslate.com/film-production-accounting", "id": "commercial:greenslate-production-accounting", "leaf_matches": [{"reason": "官方产品页说明其用于影视制作会计，涵盖应付账款、剧组支出、采购订单及薪资过账到总账；服务页补充周成本报告与对账，符合制作财务记录与成本处理核心。", "slug": "production-accounting-platform", "source_urls": ["https://greenslate.com/film-production-accounting", "https://greenslate.com/production-accounting-services"]}], "name": "GreenSlate Production Accounting", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:50:35.938276+08:00", "kind": "homepage", "sha256": "88cd23b67745560796372852e3ba1f949aebf816bb3b7b302639b3aacde359e0", "snapshot_path": "sources/88cd23b67745560796372852e3ba1f949aebf816bb3b7b302639b3aacde359e0.txt", "url": "https://greenslate.com/film-production-accounting"}, {"fetched_at": "2026-10-27T01:50:37.670111+08:00", "kind": "documentation", "sha256": "bbdbc2422dbacab3de754f1496fce125516bfb1b1426c2eb3ffb533d6449eb5b", "snapshot_path": "sources/bbdbc2422dbacab3de754f1496fce125516bfb1b1426c2eb3ffb533d6449eb5b.txt", "url": "https://greenslate.com/production-accounting-services"}], "summary": "面向电影与剧集制作的制作会计与剧组薪资平台：管理供应商及剧组付款、剧组支出与采购订单，并将剧组薪资过账到总账；同时提供周成本报告、付款与对账服务。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:qlero-royalty-management','Qlero','{"homepage": "https://qlero.io/royalty-management-for-publishers", "id": "commercial:qlero-royalty-management", "leaf_matches": [{"reason": "官方产品页正文说明结构化合同分成与预付款/抵扣、CSV/Excel 版税报表导入、可追溯报表、期间关闭与审计日志，以及自账单和付款文件导出；报表→支付→期间关闭的结算环节有正文依据，按收款人合并余额被列为其设计目标。", "slug": "royalty-management-platform", "source_urls": ["https://qlero.io/royalty-management-for-publishers"]}], "name": "Qlero", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:59:41.586578+08:00", "kind": "documentation", "sha256": "804fc4fd708ea514642ad782c941cad039012a84a084939d561fb01fa31df279", "snapshot_path": "sources/804fc4fd708ea514642ad782c941cad039012a84a084939d561fb01fa31df279.txt", "url": "https://qlero.io/royalty-management-for-publishers"}], "summary": "面向独立音乐出版商、厂牌与权利方的版税管理平台：以结构化合同分成与预付款/抵扣条款导入社会团体、子出版商和直授收入，生成可追溯报表，并支持期间关闭、自账单与付款文件导出。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vista-cinema','Vista Cinema','{"homepage": "https://vista.co/cloud/operational-excellence", "id": "commercial:vista-cinema", "leaf_matches": [{"reason": "官方运营页正文列出影院销售、库存、票房与现金流、票务验票、卖品及影片排片等功能，覆盖影院运营商业务记录系统核心。", "slug": "cinema-management-system", "source_urls": ["https://vista.co/cloud/operational-excellence"]}], "name": "Vista Cinema", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:50:35.902765+08:00", "kind": "homepage", "sha256": "557d8745b75d3c5107af58550befad7f299ffdc7b1b93a3146d5b411b22bb800", "snapshot_path": "sources/557d8745b75d3c5107af58550befad7f299ffdc7b1b93a3146d5b411b22bb800.txt", "url": "https://vista.co/cloud/operational-excellence"}, {"fetched_at": "2026-10-27T01:50:37.892097+08:00", "kind": "documentation", "sha256": "961e177e5e12eaba6054b1b332a6061fb3b9d416c8444dcf244d74e3f9eff79c", "snapshot_path": "sources/961e177e5e12eaba6054b1b332a6061fb3b9d416c8444dcf244d74e3f9eff79c.txt", "url": "https://vista.co/insights/joint-innovation-by-pathe-and-vista-halves-film-programming-time"}], "summary": "面向影院运营商的影院管理平台：覆盖影院销售、库存、票房与现金流、票务验票、卖品、影片排片与排片优化，以及经营报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:filmgrail-planning-tool','Filmgrail Planning Tool','{"homepage": "https://filmgrail.com/", "id": "commercial:filmgrail-planning-tool", "leaf_matches": [{"reason": "官方产品页说明其按影厅铺排每周节目、管理排片行政任务并发布排期，且不替代 POS/票务，符合影院排片应用作为编排支柱的边界。", "slug": "cinema-scheduling-application", "source_urls": ["https://filmgrail.com/planning-tool/", "https://filmgrail.com/"]}], "name": "Filmgrail Planning Tool", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:52:13.286652+08:00", "kind": "documentation", "sha256": "7a22b986b8affc384c2b934311b2cbc6d7fe744b6dc77194d551a60da7148d65", "snapshot_path": "sources/7a22b986b8affc384c2b934311b2cbc6d7fe744b6dc77194d551a60da7148d65.txt", "url": "https://filmgrail.com/planning-tool/"}, {"fetched_at": "2026-10-27T01:52:14.890261+08:00", "kind": "homepage", "sha256": "fdec283dd88152d339eedcad6890339211c7283fd87cc01caf657be9a349c963", "snapshot_path": "sources/fdec283dd88152d339eedcad6890339211c7283fd87cc01caf657be9a349c963.txt", "url": "https://filmgrail.com/"}], "summary": "面向影院运营商的排片应用：按影厅与日期铺排每周节目，自动导入和更新影片，并将完成后的排期发布到网站、应用与榜单；明示集成票务/后台系统而非替代 POS。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:studiobinder','StudioBinder','{"homepage": "https://www.studiobinder.com/", "id": "commercial:studiobinder", "leaf_matches": [{"reason": "官方剧本分解页正文说明导入剧本后按场标注元素并同步到条板、镜头表和通告单；拍摄排期页说明场景自动进入条板、拖拽或自动排期、插入日断点与横幅，并可从条板生成自动填充的通告单，覆盖场景→拍摄日程→通告单核心。", "slug": "film-production-management", "source_urls": ["https://www.studiobinder.com/call-sheet-builder/", "https://www.studiobinder.com/script-breakdown-software/", "https://www.studiobinder.com/film-scheduling-software/"]}], "name": "StudioBinder", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T01:51:15.000000+08:00", "kind": "documentation", "sha256": "29be519dcb8009b12461d83b14acfd6238f0204ee7fce0fcd94f8ad924c37439", "snapshot_path": "sources/29be519dcb8009b12461d83b14acfd6238f0204ee7fce0fcd94f8ad924c37439.txt", "url": "https://www.studiobinder.com/call-sheet-builder/"}, {"fetched_at": "2026-10-27T13:30:48.892441+08:00", "kind": "documentation", "sha256": "e882436950e00400e542af3b7c36812f84e779dbd291235511895d7e7f98569c", "snapshot_path": "sources/e882436950e00400e542af3b7c36812f84e779dbd291235511895d7e7f98569c.txt", "url": "https://www.studiobinder.com/script-breakdown-software/"}, {"fetched_at": "2026-10-27T13:30:48.892441+08:00", "kind": "documentation", "sha256": "d4596eba3fd832cd3c7dcd872a9671290263621b7c22c9ae550225fc7bf9d2ed", "snapshot_path": "sources/d4596eba3fd832cd3c7dcd872a9671290263621b7c22c9ae550225fc7bf9d2ed.txt", "url": "https://www.studiobinder.com/film-scheduling-software/"}], "summary": "面向影视制作的制作管理平台：导入剧本后按场分解并标注道具、服装、演员等元素，将场景放入条板编排拍摄日程，并由日程生成通告单分发；另含分场页、故事板、镜头表与剧组通讯录。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:axiell-collections','Axiell Collections','{"homepage": "https://axiell.com", "id": "commercial:axiell-collections", "leaf_matches": [{"reason": "馆藏系统中的展览执行层：展品记录按场地保存安装起止日期和状态（pending installation、installed、deinstalled 等）及状态日期，直接对应单件展项的布展/撤展状态。", "slug": "exhibition-installation-management", "source_urls": ["https://help.collections.axiell.com/en/Topics/Exhibition%20items.htm"]}, {"reason": "展览记录含展期、场地、审批状态与状态历史，Items 面板维护参展作品清单并逐项跟踪参与状态，构成馆藏系统内的展览规划层。", "slug": "exhibition-planning-platform", "source_urls": ["https://help.collections.axiell.com/en/Topics/Exhibitions%20and%20venues.htm", "https://help.collections.axiell.com/en/Topics/Exhibition%20items.htm", "https://www.axiell.com/solutions/product/axiell-collections/"]}], "name": "Axiell Collections", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:11+08:00", "kind": "homepage", "sha256": "979da7efc2fbafcf93cbba0d3c7f7cc012b81b3e534355b934410a52b36d6d82", "snapshot_path": "sources/979da7efc2fbafcf93cbba0d3c7f7cc012b81b3e534355b934410a52b36d6d82.txt", "url": "https://www.axiell.com/"}, {"fetched_at": "2026-10-27T02:04:07+08:00", "kind": "documentation", "sha256": "8031e904913ec0d72ecf03dfb450ad23a67acb5af29095d41e56686302431ce4", "snapshot_path": "sources/8031e904913ec0d72ecf03dfb450ad23a67acb5af29095d41e56686302431ce4.txt", "url": "https://help.collections.axiell.com/en/Topics/Exhibitions%20and%20venues.htm"}, {"fetched_at": "2026-10-27T02:04:09+08:00", "kind": "documentation", "sha256": "f51cf6410178c44e9b378334d5c346255e1098dec94ca2a314ded03d7e1fae3d", "snapshot_path": "sources/f51cf6410178c44e9b378334d5c346255e1098dec94ca2a314ded03d7e1fae3d.txt", "url": "https://help.collections.axiell.com/en/Topics/Exhibition%20items.htm"}, {"fetched_at": "2026-10-27T02:06:39+08:00", "kind": "homepage", "sha256": "36e8bd16975e5507637ecf31d99b9920c124e1b0b89290ff11baaef0d07a51db", "snapshot_path": "sources/36e8bd16975e5507637ecf31d99b9920c124e1b0b89290ff11baaef0