INSERT INTO "application" VALUES('commercial:gallery-systems-tms-collections','Gallery Systems TMS Collections','{"homepage": "https://gallerysystems.com", "id": "commercial:gallery-systems-tms-collections", "leaf_matches": [{"reason": "展览作为具名、有日期与场地的记录维护，object packages 用于协作细化参展清单，规划阶段与权限控制推进审批，并自动积累展览历史。", "slug": "exhibition-planning-platform", "source_urls": ["https://www.gallerysystems.com/products-tms-suite/tms-collections/", "https://resources.gallerysystems.com/the-essential-guide-to-managing-exhibitions-in-tms-gallery-systems"]}], "name": "Gallery Systems TMS Collections", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:13+08:00", "kind": "homepage", "sha256": "aa7d1099da08958b093bfa10481b4990aebf5e75169443d750137a2bfe80180f", "snapshot_path": "sources/aa7d1099da08958b093bfa10481b4990aebf5e75169443d750137a2bfe80180f.txt", "url": "https://www.gallerysystems.com/products-tms-suite/tms-collections/"}, {"fetched_at": "2026-10-27T02:04:15+08:00", "kind": "homepage", "sha256": "5ac1424296c81cd67c27895518fcb29d35d4efaa9e6bf8df65c6cfacff1ecb97", "snapshot_path": "sources/5ac1424296c81cd67c27895518fcb29d35d4efaa9e6bf8df65c6cfacff1ecb97.txt", "url": "https://www.gallerysystems.com/products-tms-suite/"}, {"fetched_at": "2026-10-27T02:04:17+08:00", "kind": "documentation", "sha256": "63c584014acc1885608b5d08fc72e1ed095f612d9a8205b911a3101f1326b498", "snapshot_path": "sources/63c584014acc1885608b5d08fc72e1ed095f612d9a8205b911a3101f1326b498.txt", "url": "https://resources.gallerysystems.com/the-essential-guide-to-managing-exhibitions-in-tms-gallery-systems"}], "summary": "Gallery Systems TMS Collections 是基于 Web 的博物馆藏品管理系统；展览记录、参展清单（object packages）、规划阶段与权限协作、场地与对象移动跟踪及展览历史构成其展览规划层。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:club-caddie','Club Caddie','{"homepage": "https://clubcaddie.com", "id": "commercial:club-caddie", "leaf_matches": [{"reason": "云端 tee sheet 与在线预订引擎管理散客、会员、联赛、活动与维护封场，官网/App/第三方市场写入同一开球时间容量，并输出轮次与营收报表。", "slug": "golf-course-management", "source_urls": ["https://clubcaddie.com/"]}], "name": "Club Caddie", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:19+08:00", "kind": "homepage", "sha256": "3607a8f4a69bf293a6025d03c27db9a5d871db466cbfa8f95605e5735c78c872", "snapshot_path": "sources/3607a8f4a69bf293a6025d03c27db9a5d871db466cbfa8f95605e5735c78c872.txt", "url": "https://clubcaddie.com/"}], "summary": "Club Caddie 是云端高尔夫球场运营系统：开球时间表与在线预订引擎统一承接会员、散客、官网/App 与第三方渠道，并形成打球轮次、营收与会员账务报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:courtreserve','CourtReserve','{"homepage": "https://courtreserve.com", "id": "commercial:courtreserve", "leaf_matches": [{"reason": "场地时间库存与受规则约束的预订（黄金时段、预订限制、自定义排程、取消惩罚）、会员与家庭账户、计费和签到共同构成俱乐部侧运营记录。", "slug": "racquet-club-management", "source_urls": ["https://courtreserve.com/court-reservations/", "https://courtreserve.com/member-management/"]}], "name": "CourtReserve", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:04:26+08:00", "kind": "homepage", "sha256": "b3483c9b13daac4555b69d6b3f4840dddb812a42060dfe4a96fa01fdc2f8ab4d", "snapshot_path": "sources/b3483c9b13daac4555b69d6b3f4840dddb812a42060dfe4a96fa01fdc2f8ab4d.txt", "url": "https://courtreserve.com/"}, {"fetched_at": "2026-10-27T02:04:21+08:00", "kind": "documentation", "sha256": "d2745290e34e0b894f0328ecd4acc10d3a57f71cc86f0133294a29bfc39cf34d", "snapshot_path": "sources/d2745290e34e0b894f0328ecd4acc10d3a57f71cc86f0133294a29bfc39cf34d.txt", "url": "https://courtreserve.com/court-reservations/"}, {"fetched_at": "2026-10-27T02:04:24+08:00", "kind": "documentation", "sha256": "968cab256f3bd34cbea852d30ec70909c130ffa986d3b8d5b6a8d5289422347e", "snapshot_path": "sources/968cab256f3bd34cbea852d30ec70909c130ffa986d3b8d5b6a8d5289422347e.txt", "url": "https://courtreserve.com/member-management/"}], "summary": "CourtReserve 面向网球、匹克球和板式网球俱乐部：以可拖拽场地时间表管理预订与规则（黄金时段、预订规则与限制、取消惩罚），并整合会员、计费、签到与报表。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:567123100','JRaceman','{"deployment": ["自托管 Go Web 服务器", "SQLite 数据库，可导入赛事定义与历史数据"], "features": ["赛事（event）与子比赛（race）创建", "参赛者、队伍与报名条目（entry）管理", "泳道分配与出发顺序（lane order）编排", "成绩、名次与奖牌统计报表", "用户与基于角色的 API 权限管理"], "github_repository_id": 567123100, "homepage": "https://github.com/jimmc/jraceman", "id": "github:567123100", "leaf_matches": [{"reason": "README 明确为皮划艇赛事管理系统；代码树含 event/race/entry/person/team/lane 领域模型及 RaceResults、MedalCount 报表，覆盖赛事容器、参赛名册、出发编排与成绩记录四段核心。", "slug": "race-management-platform", "source_urls": ["https://raw.githubusercontent.com/jimmc/jraceman/main/README.md", "https://api.github.com/repos/jimmc/jraceman/git/trees/66b15f905e3e4fc8d11135b7aad4eaca6c34ed03"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/jimmc/jraceman/license", "name": "JRaceman", "repository_url": "https://github.com/jimmc/jraceman", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:15:23.667155+08:00", "kind": "repository_metadata", "sha256": "e654975abb4d316f26019e37ee57eb841df7b0f804be83343a5b88ec95896fb4", "snapshot_path": "sources/e654975abb4d316f26019e37ee57eb841df7b0f804be83343a5b88ec95896fb4.txt", "url": "https://api.github.com/repos/jimmc/jraceman"}, {"fetched_at": "2026-10-27T02:18:41.776449+08:00", "kind": "license", "sha256": "b1139c040a3095966be7656e9d78e12dc50145f75af4e9d749c3a5b06f80fec9", "snapshot_path": "sources/b1139c040a3095966be7656e9d78e12dc50145f75af4e9d749c3a5b06f80fec9.txt", "url": "https://api.github.com/repos/jimmc/jraceman/license"}, {"fetched_at": "2026-10-27T02:15:26.611026+08:00", "kind": "readme", "sha256": "55744b3c70eaea18ec125522859b7cbb7ccaa69b21909c1f331de8558ae6055f", "snapshot_path": "sources/55744b3c70eaea18ec125522859b7cbb7ccaa69b21909c1f331de8558ae6055f.txt", "url": "https://raw.githubusercontent.com/jimmc/jraceman/main/README.md"}, {"fetched_at": "2026-10-27T02:15:28.520827+08:00", "kind": "documentation", "sha256": "dbba5aa5adbf2262985f2670dec5e17120da861e015052c1543a726dd14e4d23", "snapshot_path": "sources/dbba5aa5adbf2262985f2670dec5e17120da861e015052c1543a726dd14e4d23.txt", "url": "https://api.github.com/repos/jimmc/jraceman/git/trees/66b15f905e3e4fc8d11135b7aad4eaca6c34ed03"}], "summary": "开源皮划艇静水与激流回旋赛事管理 Web 系统，覆盖赛事与子比赛创建、参赛者/队伍与报名条目管理、泳道与出发顺序编排，以及成绩和奖牌统计报表。", "technology_stack": ["Go", "Lit / TypeScript 前端", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sport80','Sport:80 Platform','{"homepage": "https://www.sport80.com/", "id": "commercial:sport80", "leaf_matches": [{"reason": "官网正文以 NGB 与体育组织为目标客户，列出会员管理、俱乐部管理、认证与治理合规能力，具备管理机构侧组织与参与者登记关系；附属审批与多级费用细节未在首页展开。", "slug": "sports-federation-management", "source_urls": ["https://www.sport80.com/"]}, {"reason": "官网正文说明会员、运动员、教练与裁判可管理个人资料、续费会员、更新资格并报名赛事，平台含 Membership Management、Certification Management 与支付财务模块，构成有期限会员/许可关系的持续运营。", "slug": "sports-membership-licensing-platform", "source_urls": ["https://www.sport80.com/"]}], "name": "Sport:80 Platform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:14:25.688361+08:00", "kind": "homepage", "sha256": "6b2767ad8500e4dfdbc407dc59890f8eae2d74ea84ed35b38180b4c597d6e60d", "snapshot_path": "sources/6b2767ad8500e4dfdbc407dc59890f8eae2d74ea84ed35b38180b4c597d6e60d.txt", "url": "https://www.sport80.com/"}], "summary": "面向国家/地区体育管理机构和会员组织的云端体育业务管理平台，提供会员与续费、认证、赛事报名、俱乐部管理、CRM 及治理合规等模块。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aktivate-scheduling','Aktivate Scheduling (ScheduleGalaxy)','{"homepage": "https://www.schedulegalaxy.com/", "id": "commercial:aktivate-scheduling", "leaf_matches": [{"reason": "官方 About 页把产品定位为专门解决学校体育赛程复杂性的排期软件：创建含日期/时间/地点/交通信息的赛程、赛程与场地冲突管理、面向整个联盟/学区的总排期、日历订阅与变更通知、公开可嵌入日历；首页提供按学校/队伍查看最新赛程的公开入口。产品隶属 Aktivate 套件，但该产品本身是排期应用。", "slug": "sports-scheduling-platform", "source_urls": ["https://www.schedulegalaxy.com/about", "https://www.schedulegalaxy.com/"]}], "name": "Aktivate Scheduling (ScheduleGalaxy)", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:49:06.954887+08:00", "kind": "homepage", "sha256": "9deb5b5baeec1a37ccaec96b84fac21c9d663330966d0380203a77d447197fe3", "snapshot_path": "sources/9deb5b5baeec1a37ccaec96b84fac21c9d663330966d0380203a77d447197fe3.txt", "url": "https://www.schedulegalaxy.com/about"}, {"fetched_at": "2026-10-27T02:49:08.542959+08:00", "kind": "homepage", "sha256": "913fdd35fe9d4a4a5c1cbd89fd6df5a5130bd23afe4c8094d4faa62350e308e3", "snapshot_path": "sources/913fdd35fe9d4a4a5c1cbd89fd6df5a5130bd23afe4c8094d4faa62350e308e3.txt", "url": "https://www.schedulegalaxy.com/"}], "summary": "面向学校与联盟的体育赛程编排与发布平台（原 ScheduleGalaxy）：创建含日期、时间、地点和交通信息的赛程，检测赛程/场地冲突，以总排期功能为整个联盟/学区安排比赛与赛事，并通过公开日历订阅、变更通知和可嵌入日历发布。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:wyscout','Wyscout','{"homepage": "https://www.hudl.com/products/wyscout", "id": "commercial:wyscout", "leaf_matches": [{"reason": "官方产品页说明球员/比赛/球队搜索、球员名单与 shadow teams 短名单、视频评估及球员/球队/赛事数据与指标报告；运动员为被评估记录对象，页面未显示运动员账户或双向联系，符合球探平台核心。", "slug": "sports-scouting-platform", "source_urls": ["https://www.hudl.com/products/wyscout"]}], "name": "Wyscout", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:35:06.335933+08:00", "kind": "homepage", "sha256": "2c8a0d30ea72d4dec0c8a4ae8736a883f392b0f753568a072506c5c6d61a0a36", "snapshot_path": "sources/2c8a0d30ea72d4dec0c8a4ae8736a883f392b0f753568a072506c5c6d61a0a36.txt", "url": "https://www.hudl.com/products/wyscout"}], "summary": "Hudl 旗下的足球视频与数据平台，提供覆盖大量赛事的球员数据库、视频、搜索筛选、球员名单/短名单，以及球员/球队/赛事的数据与指标报告和视频评估，用于引援识别与评估。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:hudl-statsbomb','Hudl Statsbomb','{"homepage": "https://www.hudl.com/en_gb/products/statsbomb", "id": "commercial:hudl-statsbomb", "leaf_matches": [{"reason": "官方页将 tactical analysis 与 opposition analysis 列为用途，提供 300+ 赛事的事件语料、可定制可视化/模型并整合视频；本匹配仅计战术分析用途，限定为数据/分析平台，不声称完整教练备赛演示闭环。", "slug": "tactical-analysis-platform", "source_urls": ["https://www.hudl.com/en_gb/products/statsbomb"]}], "name": "Hudl Statsbomb", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:35:08.494711+08:00", "kind": "homepage", "sha256": "f85f557ea8780ee0c10718521621ebcdc10a19910fe681a39d34174b194943be", "snapshot_path": "sources/f85f557ea8780ee0c10718521621ebcdc10a19910fe681a39d34174b194943be.txt", "url": "https://www.hudl.com/en_gb/products/statsbomb"}], "summary": "面向职业足球的数据分析平台，提供赛事事件数据、可定制可视化、xG/OBV 等模型与报告，用于战术分析、对手分析和引援评估；不是完整的教练备赛报告/演示应用。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1411572157','BayFlow','{"deployment": ["自托管 Next.js 应用，PostgreSQL 数据库", "README 提供 pnpm 安装、Prisma 迁移与种子数据步骤；未提供 Docker 部署"], "features": ["客户与车辆档案（车牌、品牌、型号、年份、里程）", "预约与维修工单生命周期（17 个状态，含估价、授权、零件、维修、质检、完成）", "估价单分项：PART / LABOR，支持客户批准/拒绝与修订版本", "零件库存、预留/分配、采购单与库存台账", "店主/服务顾问/技师/零件员/质检角色分工与工单审计日志", "可打印发票/工单与按车牌查询的服务历史", "多门店租户隔离"], "github_repository_id": 1411572157, "homepage": "https://github.com/ZohaibCodez/bayflow-auto-repair-shop-management", "id": "github:1411572157", "leaf_matches": [{"reason": "README 与 Prisma schema 显示车辆记录含车牌/品牌/型号/年份/里程，Booking 绑定客户×车辆×服务并拥有从预约、估价、授权、零件到维修、质检、完成的 17 状态生命周期；EstimateItem.kind 明确分为 PART 与 LABOR，估价按版本保留批准/拒绝；另有库存/采购、前后台角色分工、可打印发票/工单及按车牌服务历史。覆盖维修订单从开具、估价授权、施工到开票的核心；发票为可打印视图，未声称独立会计发票实体。", "slug": "auto-repair-shop-management", "source_urls": ["https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/README.md", "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/prisma/schema.prisma"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/LICENSE", "license_review": {"rationale": "快照为仓库根目录完整 MIT 许可证文本，含版权声明、标准授权段、条件与免责声明，未见附加限制；据此按 MIT 覆盖仓库整体收录。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/LICENSE", "spdx_id": "MIT"}, "name": "BayFlow", "repository_url": "https://github.com/ZohaibCodez/bayflow-auto-repair-shop-management", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T13:38:20.747774+08:00", "kind": "repository_metadata", "sha256": "f8be32290afc2e970539fa4b998370f0fa4fd3259c9559c462a8f763ceb82ed4", "snapshot_path": "sources/f8be32290afc2e970539fa4b998370f0fa4fd3259c9559c462a8f763ceb82ed4.txt", "url": "https://api.github.com/repos/ZohaibCodez/bayflow-auto-repair-shop-management"}, {"fetched_at": "2026-10-27T13:38:22.879561+08:00", "kind": "license", "sha256": "010f78209c4484a5e10bd768c21dee9086c5f6630f054a62d082446a1886c009", "snapshot_path": "sources/010f78209c4484a5e10bd768c21dee9086c5f6630f054a62d082446a1886c009.txt", "url": "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/LICENSE"}, {"fetched_at": "2026-10-27T13:38:09.255619+08:00", "kind": "readme", "sha256": "9054827194c27fc7d72e25c1af6e79f4fe881d0ccda3591b9a0cfcb6daa00fb8", "snapshot_path": "sources/9054827194c27fc7d72e25c1af6e79f4fe881d0ccda3591b9a0cfcb6daa00fb8.txt", "url": "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/README.md"}, {"fetched_at": "2026-10-27T13:38:20.739784+08:00", "kind": "documentation", "sha256": "9d4388fec6e318c44fd81fcac5358139134a025db7f1ea09b4a36c262371f19f", "snapshot_path": "sources/9d4388fec6e318c44fd81fcac5358139134a025db7f1ea09b4a36c262371f19f.txt", "url": "https://raw.githubusercontent.com/ZohaibCodez/bayflow-auto-repair-shop-management/HEAD/prisma/schema.prisma"}], "summary": "MIT 许可的汽修店管理应用，覆盖客户与车辆档案（车牌/品牌/型号/年份/里程）、预约、维修工单状态机、估价单（PART/LABOR 行项目）、客户批准/拒绝、零件库存与采购、角色分工与审计日志、可打印发票/工单及按车牌查询服务历史；可用 Next.js + PostgreSQL 自托管。", "technology_stack": ["Next.js", "React", "TypeScript", "Prisma", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:936669638','Sunrise CMS','{"deployment": ["Node.js 自托管 Web 应用，package.json 提供 node 启动脚本", "README 称只需普通工作站、无需独立数据库服务器"], "features": ["墓地与墓位库存记录", "合同管理（不限数量）", "安葬与墓穴维护工单", "可选墓地地图", "Find a Grave 记录链接", "用户账户与权限管理", "低资源自托管运行"], "github_repository_id": 936669638, "homepage": "https://github.com/cityssm/sunrise-cms", "id": "github:936669638", "leaf_matches": [{"reason": "README 明确其为墓地记录管理系统，提供墓位/墓地库存、合同及安葬（interments）与墓穴维护工单；合同文档进一步说明合同跟踪生前预订与临终安葬，并在逝者安葬后结束。满足墓位库存 + 安葬记录核心；公共族谱门户与逐条传记字段未在已读资料中说明，未纳入关系。", "slug": "cemetery-management", "source_urls": ["https://github.com/cityssm/sunrise-cms", "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/README.md", "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/LICENSE.md", "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/package.json", "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/docs/contracts.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/LICENSE.md", "license_review": {"rationale": "仓库 LICENSE.md 快照为完整 MIT 许可证文本，含授权、版权声明与免责条款，未见附加限制。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "repository", "source_url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/LICENSE.md", "spdx_id": "MIT"}, "name": "Sunrise CMS", "repository_url": "https://github.com/cityssm/sunrise-cms", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T02:58:10.254864+08:00", "kind": "repository_metadata", "sha256": "ef486ac11850a4c1eb079de968efcbb9287c5056562e6bb526af4f083d9c14c5", "snapshot_path": "sources/ef486ac11850a4c1eb079de968efcbb9287c5056562e6bb526af4f083d9c14c5.txt", "url": "https://github.com/cityssm/sunrise-cms"}, {"fetched_at": "2026-10-27T02:58:11.303628+08:00", "kind": "readme", "sha256": "bfb58d576462a3e5e81d6ce5e734a3587c5c127063bc94715c46ab07dd46c8fa", "snapshot_path": "sources/bfb58d576462a3e5e81d6ce5e734a3587c5c127063bc94715c46ab07dd46c8fa.txt", "url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/README.md"}, {"fetched_at": "2026-10-27T02:58:12.365592+08:00", "kind": "license", "sha256": "db5b54219eed21dbb8a787bbe57946ad945f6593541ff40fa72c90bc6c41cc1c", "snapshot_path": "sources/db5b54219eed21dbb8a787bbe57946ad945f6593541ff40fa72c90bc6c41cc1c.txt", "url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/LICENSE.md"}, {"fetched_at": "2026-10-27T02:59:19.229043+08:00", "kind": "documentation", "sha256": "a8497f44bdcb1ae0920294d4d4a00b6d6bbd62bd310aa0cfdc0f3c2a1a735acf", "snapshot_path": "sources/a8497f44bdcb1ae0920294d4d4a00b6d6bbd62bd310aa0cfdc0f3c2a1a735acf.txt", "url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/package.json"}, {"fetched_at": "2026-10-27T03:03:34.413303+08:00", "kind": "documentation", "sha256": "5732b4b9770c24b903cb4afb86738e01c5d26f9cdae57bfb64a221e466a0c936", "snapshot_path": "sources/5732b4b9770c24b903cb4afb86738e01c5d26f9cdae57bfb64a221e466a0c936.txt", "url": "https://raw.githubusercontent.com/cityssm/sunrise-cms/HEAD/docs/contracts.md"}], "summary": "由市政府维护、仍在开发中的开源墓地记录系统：管理不限数量的墓地、墓位与合同，内置安葬和墓穴维护工单，支持可选地图与 Find a Grave 外链，面向小型/历史墓地自托管使用。", "technology_stack": ["Node.js", "Express", "EJS", "Bulma"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:10553586','Spring Initializr','{"deployment": ["官方 README 说明 initializr-web 模块基于 Spring Boot 可部署为服务，initializr-service-sample 展示自定义实例，需 Java 25 构建；本轮未运行或部署软件"], "features": ["Extensible API to generate JVM-based projects, with language, build-system and hook-point abstractions.", "Metadata model expresses dependencies, supported JVM and platform versions used to parameterize generation.", "Web endpoints generate an actual project and serve metadata; the production instance is start.spring.io.", "A custom/self-hosted instance can be deployed with the initializr-web module and initializr-service-sample."], "github_repository_id": 10553586, "homepage": "https://start.spring.io/", "id": "github:10553586", "leaf_matches": [{"reason": "官方 README 说明 Spring Initializr 以可复用生成器/约定和元数据模型接收依赖、JVM 与平台版本等参数，通过 Web 端点生成实际 JVM 项目，并给出 start.spring.io 生产实例与自托管说明；可复用起点定义、参数化生成、输出起始项目三项成立。服务形态为托管或自托管的项目生成 Web 服务，不是本地 CLI。", "slug": "project-scaffolding-code-generator", "source_urls": ["https://raw.githubusercontent.com/spring-io/initializr/main/README.adoc", "https://api.github.com/repos/spring-io/initializr"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/spring-io/initializr/license", "name": "Spring Initializr", "repository_url": "https://github.com/spring-io/initializr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:55:18.312503+08:00", "kind": "repository_metadata", "sha256": "cb2b494fc43538d9bf52fafbff02ae297253350f2ac80b5d4b3e36d612327bc1", "snapshot_path": "sources/cb2b494fc43538d9bf52fafbff02ae297253350f2ac80b5d4b3e36d612327bc1.txt", "url": "https://api.github.com/repos/spring-io/initializr"}, {"fetched_at": "2026-10-27T14:55:15.550281+08:00", "kind": "license", "sha256": "5cac8123e479c932738a6b9e63de0b9bbf0a01b48fec5a06547753fe0c0e6c51", "snapshot_path": "sources/5cac8123e479c932738a6b9e63de0b9bbf0a01b48fec5a06547753fe0c0e6c51.txt", "url": "https://api.github.com/repos/spring-io/initializr/license"}, {"fetched_at": "2026-10-27T14:55:26.219469+08:00", "kind": "readme", "sha256": "3832da84ac13be80a218ccae0e5c82f1ad8091f423681d4f6df05b33dee69b9d", "snapshot_path": "sources/3832da84ac13be80a218ccae0e5c82f1ad8091f423681d4f6df05b33dee69b9d.txt", "url": "https://raw.githubusercontent.com/spring-io/initializr/main/README.adoc"}], "summary": "以可复用生成器/约定和元数据模型接收依赖与平台版本等参数、由 Web 端点生成 JVM 起始项目的开源脚手架服务；官方生产实例为 start.spring.io，也可自托管。", "technology_stack": ["Java"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:24968828','pgweb','{"deployment": ["官方 README/Usage 说明运行 pgweb 即启动 HTTP 服务（默认 8081），支持连接参数、连接 URL、Docker 等部署方式；本轮未运行或部署软件"], "features": ["Web-based PostgreSQL database explorer distributed as a single Go binary and run as a self-hosted HTTP server.", "Connects with host/user/db flags or a postgres:// URL; supports SSH tunnels and multiple database sessions.", "Execute and analyze custom SQL queries, with query history and table/query data export to CSV/JSON/XML."], "github_repository_id": 24968828, "homepage": "https://sosedoff.github.io/pgweb/", "id": "github:24968828", "leaf_matches": [{"reason": "官方 README 与 Usage 文档说明 pgweb 是运行在本机或服务器上的 Web PostgreSQL 客户端/HTTP 服务：通过 host/user/db 参数或 postgres:// URL 连接外部数据库，执行并分析自定义 SQL 查询，支持查询历史与表/查询数据导出。连接外部数据库、SQL 主界面、可检查结果三项成立，且为可自托管的 Web 服务而非本地终端程序。", "slug": "sql-client", "source_urls": ["https://raw.githubusercontent.com/sosedoff/pgweb/master/README.md", "https://raw.githubusercontent.com/wiki/sosedoff/pgweb/Usage.md", "https://api.github.com/repos/sosedoff/pgweb"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/sosedoff/pgweb/license", "name": "pgweb", "repository_url": "https://github.com/sosedoff/pgweb", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:56:31.738917+08:00", "kind": "repository_metadata", "sha256": "7baff7a8f6877f85e3582e0b61d5f1c677cc4bce7adb2e3e05b0d13e34ed531d", "snapshot_path": "sources/7baff7a8f6877f85e3582e0b61d5f1c677cc4bce7adb2e3e05b0d13e34ed531d.txt", "url": "https://api.github.com/repos/sosedoff/pgweb"}, {"fetched_at": "2026-10-27T14:56:31.540687+08:00", "kind": "license", "sha256": "0898f491811fdc62a2a8a08b00e18920a36663c4e514c7ee5fa320954437a28e", "snapshot_path": "sources/0898f491811fdc62a2a8a08b00e18920a36663c4e514c7ee5fa320954437a28e.txt", "url": "https://api.github.com/repos/sosedoff/pgweb/license"}, {"fetched_at": "2026-10-27T14:56:30.899656+08:00", "kind": "readme", "sha256": "069506db60a04ef66fe10a189b159b80d50cab37dfd2cc4efe029abc7136bbb0", "snapshot_path": "sources/069506db60a04ef66fe10a189b159b80d50cab37dfd2cc4efe029abc7136bbb0.txt", "url": "https://raw.githubusercontent.com/sosedoff/pgweb/master/README.md"}, {"fetched_at": "2026-10-27T14:57:53.475790+08:00", "kind": "documentation", "sha256": "5b7544e1ac2b545acbb5594493dd1b351507463ce1df34fd4d31b33cc62aba95", "snapshot_path": "sources/5b7544e1ac2b545acbb5594493dd1b351507463ce1df34fd4d31b33cc62aba95.txt", "url": "https://raw.githubusercontent.com/wiki/sosedoff/pgweb/Usage.md"}], "summary": "自托管、浏览器访问的 PostgreSQL 客户端：启动 HTTP 服务连接外部数据库，执行自定义 SQL 查询，并支持查询历史与结果数据导出。", "technology_stack": ["Go"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:stackblitz','StackBlitz','{"homepage": "https://stackblitz.com/", "id": "commercial:stackblitz", "leaf_matches": [{"reason": "官方首页把 StackBlitz 定位为面向 web developers 的 collaborative browser-based IDE，官方文档称其为 JavaScript 生态的 instant fullstack web IDE；Available environments 说明支持前端框架及全栈 Web 应用，Starter projects 文档说明可创建无 npm 依赖的纯 HTML/CSS/JavaScript 项目，并由浏览器把项目文件原样提供给预览。General FAQs 说明 Classic Editor 含文件树、npm 包管理器和 light dev server 与 preview pane，可在编码时看到应用，Codeflow 则把 VS Code 带入浏览器并提供终端、包管理器与扩展。IDE 的 Preview 被明确描述为浏览器内的 mini browser，以 iframe 渲染正在构建的应用或网站，并可把 Reload trigger 设为 Save、以 Hot reload 更新，闭合编辑→保存→浏览器预览刷新循环。商业条目仅作基本类型记录，不扩展价格、架构或具体语言补全细节。", "slug": "web-development-ide", "source_urls": ["https://stackblitz.com/", "https://developer.stackblitz.com/guides/user-guide/what-is-stackblitz", "https://developer.stackblitz.com/guides/user-guide/ide-whats-on-your-screen", "https://developer.stackblitz.com/guides/user-guide/available-environments", "https://developer.stackblitz.com/enterprise/starter-projects", "https://developer.stackblitz.com/guides/user-guide/general-faqs"]}], "name": "StackBlitz", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T16:41:16.192526+08:00", "kind": "homepage", "sha256": "f7f5927f4650a9bf9f716ad967d90cfcee4e67984ae42b49a0370c52923dd347", "snapshot_path": "sources/f7f5927f4650a9bf9f716ad967d90cfcee4e67984ae42b49a0370c52923dd347.txt", "url": "https://stackblitz.com/"}, {"fetched_at": "2026-10-27T16:41:16.353530+08:00", "kind": "documentation", "sha256": "a92ee203b75f488507fceca8ad8ead357a2bddca1b0ec868b53aed04f1dbe2ae", "snapshot_path": "sources/a92ee203b75f488507fceca8ad8ead357a2bddca1b0ec868b53aed04f1dbe2ae.txt", "url": "https://developer.stackblitz.com/guides/user-guide/what-is-stackblitz"}, {"fetched_at": "2026-10-27T16:41:16.168861+08:00", "kind": "documentation", "sha256": "26024ebe6682d86cf1107263552063a766fcdcb0fd4a54e1c29a4bfc7389c7a8", "snapshot_path": "sources/26024ebe6682d86cf1107263552063a766fcdcb0fd4a54e1c29a4bfc7389c7a8.txt", "url": "https://developer.stackblitz.com/guides/user-guide/ide-whats-on-your-screen"}, {"fetched_at": "2026-10-27T16:41:53.039649+08:00", "kind": "documentation", "sha256": "3827c6cac61dc35540fc27ccd975605bcfaf4f82bfc41edeefae4ec06af9b7cd", "snapshot_path": "sources/3827c6cac61dc35540fc27ccd975605bcfaf4f82bfc41edeefae4ec06af9b7cd.txt", "url": "https://developer.stackblitz.com/guides/user-guide/available-environments"}, {"fetched_at": "2026-10-27T16:42:42.068491+08:00", "kind": "documentation", "sha256": "da92cb7d4c165c2049a7575429693b0d1df87133ea0b2d08f3a918e9eaa4e703", "snapshot_path": "sources/da92cb7d4c165c2049a7575429693b0d1df87133ea0b2d08f3a918e9eaa4e703.txt", "url": "https://developer.stackblitz.com/enterprise/starter-projects"}, {"fetched_at": "2026-10-27T16:45:18.340861+08:00", "kind": "documentation", "sha256": "f26e0a3726270792cfc60ad0b8434fe08207fac10197b673ede12e7cfdfd51fd", "snapshot_path": "sources/f26e0a3726270792cfc60ad0b8434fe08207fac10197b673ede12e7cfdfd51fd.txt", "url": "https://developer.stackblitz.com/guides/user-guide/general-faqs"}], "summary": "面向 Web 开发者的浏览器内 IDE：在浏览器标签页中编辑并运行前端或全栈 JavaScript 项目，提供编辑器、集成预览以及保存/热重载刷新。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:sonarqube-server','SonarQube Server','{"homepage": "https://docs.sonarsource.com/sonarqube-server", "id": "commercial:sonarqube-server", "leaf_matches": [{"reason": "官方文档逐项对应叶定义：项目可通过导入 GitHub 等 DevOps 平台仓库创建并绑定到源代码仓库（creating-project/introduction、github/import-repos）；Developer 及以上商业版在 Community Build 之上提供分支分析与拉取请求分析（sonarqube-server-editions 功能矩阵）；PR 每次打开或推送都会触发分析，只报告新代码引入的问题并由项目 Quality Gate 判定（pull-request-analysis）；项目 Activity 页列出全部扫描、质量门禁变化与问题/度量趋势（activity-and-history）；问题在后续分析中按行哈希比对判定新增/已修复并保留状态生命周期，跨分支/PR 同步状态、指派与变更记录，度量用于门禁条件（process-steps、issues/introduction、code-metrics/introduction）；Quality Gate 由可配置条件组成，可在 PR 上装饰并阻止合并，或在 CI 中使流水线失败（introduction-to-quality-gates、github/configure-binding）；质量档案可配置启用规则（understanding-quality-profiles）。受管项目、记录分析运行、持久问题/度量/历史、可配置标准与每次变更判定均成立。", "slug": "code-quality-platform", "source_urls": ["https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/introduction.md", "https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/github/import-repos.md", "https://docs.sonarsource.com/sonarqube-server/discovering/sonarqube-server-editions.md", "https://docs.sonarsource.com/sonarqube-server/discovering/code-analysis/branch-analysis.md", "https://docs.sonarsource.com/sonarqube-server/discovering/code-analysis/pull-request-analysis.md", "https://docs.sonarsource.com/sonarqube-server/discovering/analysis-overview/process-steps.md", "https://docs.sonarsource.com/sonarqube-server/user-guide/viewing-projects/activity-and-history.md", "https://docs.sonarsource.com/sonarqube-server/user-guide/issues/introduction.md", "https://docs.sonarsource.com/sonarqube-server/user-guide/code-metrics/introduction.md", "https://docs.sonarsource.com/sonarqube-server/quality-standards-administration/managing-quality-gates/introduction-to-quality-gates.md", "https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/github/configure-binding.md", "https://docs.sonarsource.com/sonarqube-server/quality-standards-administration/managing-quality-profiles/understanding-quality-profiles.md"]}], "name": "SonarQube Server", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T16:48:26.600407+08:00", "kind": "documentation", "sha256": "480a46f68c24b2d8aa23c9fc542f39465cb3cad6944735a009f0cf5f07ff2138", "snapshot_path": "sources/480a46f68c24b2d8aa23c9fc542f39465cb3cad6944735a009f0cf5f07ff2138.txt", "url": "https://docs.sonarsource.com/sonarqube-server/discovering/sonarqube-server-editions.md"}, {"fetched_at": "2026-10-27T16:48:28.016147+08:00", "kind": "documentation", "sha256": "6cb35d9f19ec5e1cc73fb559a8916de30b33076f668b499ad2fa1baf987392d5", "snapshot_path": "sources/6cb35d9f19ec5e1cc73fb559a8916de30b33076f668b499ad2fa1baf987392d5.txt", "url": "https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/introduction.md"}, {"fetched_at": "2026-10-27T16:48:30.588635+08:00", "kind": "documentation", "sha256": "420648a5ae86657a93cfc202bc990ebfcba033269ee7ea8de4dccfe66f660727", "snapshot_path": "sources/420648a5ae86657a93cfc202bc990ebfcba033269ee7ea8de4dccfe66f660727.txt", "url": "https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/github/import-repos.md"}, {"fetched_at": "2026-10-27T16:48:32.176426+08:00", "kind": "documentation", "sha256": "dc6d3a07d3607a0238f3ac4448b9f286a82ea1d792e56a67e76701b7a22f5971", "snapshot_path": "sources/dc6d3a07d3607a0238f3ac4448b9f286a82ea1d792e56a67e76701b7a22f5971.txt", "url": "https://docs.sonarsource.com/sonarqube-server/project-administration/creating-project/github/configure-binding.md"}, {"fetched_at": "2026-10-27T16:48:33.571105+08:00", "kind": "documentation", "sha256": "9224a3a9b77cfbeb89836c1897af9b6a30a1b56da8a05b552f1fcef4aac505e8", "snapshot_path": "sources/9224a3a9b77cfbeb89836c1897af9b6a30a1b56da8a05b552f1fcef4aac505e8.txt", "url": "https://docs.sonarsource.com/sonarqube-server/discovering/code-analysis/branch-analysis.md"}, {"fetched_at": "2026-10-27T16:48:34.962063+08:00", "kind": "documentation", "sha256": "832da86f9eb760714969e25d2ff7abdac7724e98d2c1a2509e243eb7936c5f28", "snapshot_path": "sources/832da86f9eb760714969e25d2ff7abdac7724e98d2c1a2509e243eb7936c5f28.txt", "url": "https://docs.sonarsource.com/sonarqube-server/discovering/code-analysis/pull-request-analysis.md"}, {"fetched_at": "2026-10-27T16:51:13.814529+08:00", "kind": "documentation", "sha256": "fd10e60fafbcac9df2b77df117cb2a009485f47eec10fec37dd32466df30bee2", "snapshot_path": "sources/fd10e60fafbcac9df2b77df117cb2a009485f47eec10fec37dd32466df30bee2.txt", "url": "https://docs.sonarsource.com/sonarqube-server/discovering/analysis-overview/process-steps.md"}, {"fetched_at": "2026-10-27T16:48:36.509540+08:00", "kind": "documentation", "sha256": "2a12947125798794f70045bfc63633f58cab0704d9c1f3dd35cb6317cf33931e", "snapshot_path": "sources/2a12947125798794f70045bfc63633f58cab0704d9c1f3dd35cb6317cf33931e.txt", "url": "https://docs.sonarsource.com/sonarqube-server/user-guide/viewing-projects/activity-and-history.md"}, {"fetched_at": "2026-10-27T16:48:38.651773+08:00", "kind": "documentation", "sha256": "9ae6fa51af2e36a9486f76b77370e56b5c24cdaa0a1f16a6307b55fdc9293868", "snapshot_path": "sources/9ae6fa51af2e36a9486f76b77370e56b5c24cdaa0a1f16a6307b55fdc9293868.txt", "url": "https://docs.sonarsource.com/sonarqube-server/user-guide/issues/introduction.md"}, {"fetched_at": "2026-10-27T16:48:40.582320+08:00", "kind": "documentation", "sha256": "66b96ef1069c789b52d7798e00019d482e204bb716c4964c939d231d776def84", "snapshot_path": "sources/66b96ef1069c789b52d7798e00019d482e204bb716c4964c939d231d776def84.txt", "url": "https://docs.sonarsource.com/sonarqube-server/user-guide/code-metrics/introduction.md"}, {"fetched_at": "2026-10-27T16:48:42.058857+08:00", "kind": "documentation", "sha256": "c0b13775f374060d8722f9d59a1784dec7e42b608234675400dc5ef03486c371", "snapshot_path": "sources/c0b13775f374060d8722f9d59a1784dec7e42b608234675400dc5ef03486c371.txt", "url": "https://docs.sonarsource.com/sonarqube-server/quality-standards-administration/managing-quality-gates/introduction-to-quality-gates.md"}, {"fetched_at": "2026-10-27T16:48:45.243118+08:00", "kind": "documentation", "sha256": "1d86d7af2c51b32e4c8c88dc6a01644e2a9319ef3bc723fb51e782de57028402", "snapshot_path": "sources/1d86d7af2c51b32e4c8c88dc6a01644e2a9319ef3bc723fb51e782de57028402.txt", "url": "https://docs.sonarsource.com/sonarqube-server/quality-standards-administration/managing-quality-profiles/understanding-quality-profiles.md"}], "summary": "SonarQube Server 商业版（Developer/Enterprise/Data Center）是自托管代码质量平台：可导入并绑定 Git 仓库形成受管项目，对主分支、其他分支与拉取请求持续执行分析，保存问题、度量与历史趋势，并以可配置 Quality Gate 在分支/PR 和 CI 中给出通过/失败判定。本条仅记录商业产品的基本用途与官方正文。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1264706707','OpenQMS','{"deployment": ["README：Docker Compose 启动 PostgreSQL、Redis、Neo4j 后端，执行 Alembic 迁移后启动完整应用栈；本轮未部署。"], "features": ["8D/CAPA：D1–D8 按序推进，D7/D8 与归档需审批，报告可关联 FMEA 失效节点", "来料检验：AQL 抽样、检验批状态机、判定/复检，并可关联 CAPA 或 SCAR", "供应商管理：待审核→审核→批准/暂停状态、认证及到期、A/B/C/D 评价与质量绩效仪表板", "供应商 SCAR 保存供应商回复、要求措施与截止日期；风险告警、内审、管理评审与质量目标模块配套"], "github_repository_id": 1264706707, "homepage": "https://qms.smartindustry.world/", "id": "github:1264706707", "leaf_matches": [{"reason": "README 与 8D/CAPA 手册显示制造质量问题按 D1–D8 记录、调查、审批并关闭，D7/D8 和归档需要批准，记录关联 FMEA；来料检验批、供应商与批次提供生产上下文，内审、管理评审与质量目标模块提供体系审核与评审记录。README 明确以 IATF 16949 为目标，符合记录群体、闭环机制与合规锚点；未主张电子签名法规认证。", "slug": "manufacturing-qms", "source_urls": ["https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/README.md", "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/capa.md", "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/iqc-supplier.md"]}, {"reason": "SPC 用户手册显示该模块以检验特性组织时间序列子组，覆盖计量型 X-bar/R、I-MR 与计数型 P/NP/C/U 控制图；控制限由已有子组动态计算并可锁定为版本化快照，录入样本即执行八条 Western Electric 判异规则并生成分级告警，另提供 Cp/Cpk/Pp/Ppk 能力计算。这对应定义中的过程特性、时间序列、过程自算控制限与统计规则；规格限仅用于能力计算，未与控制限混同。", "slug": "statistical-process-control-spc", "source_urls": ["https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/spc-msa.md", "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/README.md"]}, {"reason": "供应商手册显示供应商有 pending_review→audit_required→approved/rejected/suspended 状态与认证到期，approved 标注可正常交易，构成采购方维护的供应商级质量状态（非供应商-零件级）；SCAR 保存供应商回复、要求措施与截止日期，状态由 open/in_progress 经 responded、verified 到 closed，可由 IQC 拒收或风险告警触发，形成双向问题闭环；IQC 判定/复检、PPM、批次合格率、A/B/C/D 评价、审核发现与开放 SCAR 汇总为供应商绩效证据。三结构均有正文支撑；零件级 PPAP 仅见 README 模块表，未证明与供应商批准状态联动。", "slug": "supplier-quality-management", "source_urls": ["https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/README.md", "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/iqc-supplier.md", "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/capa.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Open-Industry-System/OpenQMS/license", "name": "OpenQMS", "repository_url": "https://github.com/Open-Industry-System/OpenQMS", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:52:09.505229+08:00", "kind": "repository_metadata", "sha256": "f2632e42e268a8cf27c4d595b99fd7ddb9fe9e8fdd9f3987d1564ea48dfbda5d", "snapshot_path": "sources/f2632e42e268a8cf27c4d595b99fd7ddb9fe9e8fdd9f3987d1564ea48dfbda5d.txt", "url": "https://api.github.com/repos/Open-Industry-System/OpenQMS"}, {"fetched_at": "2026-10-27T14:52:09.893359+08:00", "kind": "license", "sha256": "bf08cf658bfe23772dd63aac8c1a2a16c6256d192938101a82720d66330b6650", "snapshot_path": "sources/bf08cf658bfe23772dd63aac8c1a2a16c6256d192938101a82720d66330b6650.txt", "url": "https://api.github.com/repos/Open-Industry-System/OpenQMS/license"}, {"fetched_at": "2026-10-27T14:52:08.257417+08:00", "kind": "readme", "sha256": "f34a92bc36c6018087e6d4a795d3783470a0905ef44eaa7d0716654a4db5a962", "snapshot_path": "sources/f34a92bc36c6018087e6d4a795d3783470a0905ef44eaa7d0716654a4db5a962.txt", "url": "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/README.md"}, {"fetched_at": "2026-10-27T14:52:22.053929+08:00", "kind": "documentation", "sha256": "f1e4d895e656dbbc6f93420e28084a1ea9de979c40f518b2f77c2c1d59be9cc3", "snapshot_path": "sources/f1e4d895e656dbbc6f93420e28084a1ea9de979c40f518b2f77c2c1d59be9cc3.txt", "url": "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/iqc-supplier.md"}, {"fetched_at": "2026-10-27T14:52:50.866648+08:00", "kind": "documentation", "sha256": "d51ea75cec59990e7b873d153ac474503bd36349fc705b4deee5612c04937748", "snapshot_path": "sources/d51ea75cec59990e7b873d153ac474503bd36349fc705b4deee5612c04937748.txt", "url": "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/capa.md"}, {"fetched_at": "2026-10-27T16:54:28.342299+08:00", "kind": "documentation", "sha256": "7f0fade7a310f9a4a62cc0344d728502330c82395e53a09b093ee0b0f6e134b1", "snapshot_path": "sources/7f0fade7a310f9a4a62cc0344d728502330c82395e53a09b093ee0b0f6e134b1.txt", "url": "https://raw.githubusercontent.com/Open-Industry-System/OpenQMS/main/docs/modules/spc-msa.md"}], "summary": "OpenQMS 是面向制造业的开源质量管理平台：以来料检验批（含拒收与缺陷记录）、8D/CAPA 记录承载生产质量问题，按审批推进至 D7/D8 关闭；供应商状态、认证、SCAR 与绩效评价共同形成供应商质量记录，并覆盖 FMEA、控制计划、内审与管理评审等 IATF 16949 场景。", "technology_stack": ["Python", "FastAPI", "PostgreSQL", "React", "TypeScript", "Neo4j", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:771468183','HardPy','{"deployment": ["README：本机 hardpy run 启动操作面板；CouchDB 可用 docker compose 启动，也可改用 JSON 存储；本轮未部署。"], "features": ["以 pytest 测试函数/模块组织设备测试台，支持 setup/main/teardown 分组与多套测试计划配置", "浏览器操作面板查看测试层级、启动/停止测试，并在执行过程中与测试交互", "测试结果写入 CouchDB 或 JSON 的 runstore，记录 PASS/FAIL/STOP 判定、失败用例与测量值，操作面板可浏览历史运行与报告", "可选同步到 StandCloud 分析平台，属于补充服务而非运行依赖"], "github_repository_id": 771468183, "homepage": "https://everypinio.github.io/hardpy/", "id": "github:771468183", "leaf_matches": [{"reason": "README 与官方功能文档显示 pytest 测试函数构成持久、可复用的测试定义，操作面板按测试台执行并记录运行状态与测量结果，CouchDB/JSON 保留历史报告，且支持多套测试计划配置。对应测试定义、执行记录与受管测试工作三结构；未主张需求覆盖矩阵、电子签名或缺陷闭环等未读能力。", "slug": "product-test-management", "source_urls": ["https://raw.githubusercontent.com/everypinio/hardpy/main/README.md", "https://everypinio.github.io/hardpy/features/features/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/everypinio/hardpy/license", "name": "HardPy", "repository_url": "https://github.com/everypinio/hardpy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:50:51.879265+08:00", "kind": "repository_metadata", "sha256": "78af52a2bc48627ac17750f5ca0528a42e47a0035e824eec0860758630f8b5a1", "snapshot_path": "sources/78af52a2bc48627ac17750f5ca0528a42e47a0035e824eec0860758630f8b5a1.txt", "url": "https://api.github.com/repos/everypinio/hardpy"}, {"fetched_at": "2026-10-27T14:50:52.390321+08:00", "kind": "license", "sha256": "4b87be2e8a208a7ef7d5f7eadfe3ac7f58973876a53964078438489620b0ee81", "snapshot_path": "sources/4b87be2e8a208a7ef7d5f7eadfe3ac7f58973876a53964078438489620b0ee81.txt", "url": "https://api.github.com/repos/everypinio/hardpy/license"}, {"fetched_at": "2026-10-27T14:53:48.593197+08:00", "kind": "readme", "sha256": "d9c649b4652b08a29274051db8f0ae941bf7409787819f6ab2bb4a7b87e8545f", "snapshot_path": "sources/d9c649b4652b08a29274051db8f0ae941bf7409787819f6ab2bb4a7b87e8545f.txt", "url": "https://raw.githubusercontent.com/everypinio/hardpy/main/README.md"}, {"fetched_at": "2026-10-27T14:50:58.913347+08:00", "kind": "documentation", "sha256": "6bfc7880cdf6005bb5b0e17f865de26274066724a0cc093f3f19b4b00f6343f1", "snapshot_path": "sources/6bfc7880cdf6005bb5b0e17f865de26274066724a0cc093f3f19b4b00f6343f1.txt", "url": "https://everypinio.github.io/hardpy/features/features/"}], "summary": "HardPy 是开源的设备测试台测试执行与记录系统，以 Python 库/CLI 交付并自带浏览器操作面板：以 pytest 测试函数/模块作为持久测试定义，由操作面板启动、停止并交互式执行测试，把每次运行的 PASS/FAIL/STOP 判定与测量结果写入 CouchDB 或 JSON，并提供测试历史与报告查看。", "technology_stack": ["Python", "pytest", "CouchDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1177166217','Cassini','{"deployment": ["README：提供 Windows 安装包、Docker Compose 与源码三种运行方式；本轮未部署。"], "features": ["变量控制图（X-bar/R、X-bar/S、I-MR、CUSUM、EWMA）与计数型控制图（p、np、c、u）", "从过程数据计算控制限并执行八条 Nelson/WECO/AIAG 判异规则；违规记录关联规则、样本与特性", "Cp/Cpk/Pp/Ppk 过程能力与短运行 SPC（偏差/Z-score）；Show Your Work 展示公式、输入与 AIAG 引用", "开源版含哈希链审计日志与工厂级 RBAC；MSA/DOE、时间回溯、电子签名、FAI 与多工厂能力属 Pro/Enterprise（README 版本表）"], "github_repository_id": 1177166217, "homepage": "https://saturnis.io/cassini", "id": "github:1177166217", "leaf_matches": [{"reason": "README 显示平台按过程特性接收时间序列样本并实时更新控制图，控制限来自过程数据，八条 Nelson/WECO/AIAG 规则对点判异并把违规关联到规则与样本，另提供 Cp/Cpk 能力分析。这对应定义中的过程特性、时间序列、过程自算控制限与统计规则四结构；未把规格限或零件判定混入。", "slug": "statistical-process-control-spc", "source_urls": ["https://raw.githubusercontent.com/saturnis-io/cassini/main/README.md", "https://api.github.com/repos/saturnis-io/cassini"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/saturnis-io/cassini/main/LICENSE", "license_review": {"rationale": "LICENSE 为带 Cassini 版权抬头的完整 GNU Affero GPL v3 正文；README 同时标明 AGPL-3.0 Open 版与 Pro/Enterprise 商业层，本条目仅主张开源核心 SPC 能力，不把商业层计入开源范围。", "reviewer": "opencode-go/deepseek-v4.1-flash", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/saturnis-io/cassini/main/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "Cassini", "repository_url": "https://github.com/saturnis-io/cassini", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T14:51:32.407426+08:00", "kind": "repository_metadata", "sha256": "c0ff730e5b4c31babf43a37921ee9d7b7d9c639056e97a0a20f2f7b34e52e6fa", "snapshot_path": "sources/c0ff730e5b4c31babf43a37921ee9d7b7d9c639056e97a0a20f2f7b34e52e6fa.txt", "url": "https://api.github.com/repos/saturnis-io/cassini"}, {"fetched_at": "2026-10-27T14:51:34.245473+08:00", "kind": "license", "sha256": "5379f97c72e4a91d87695c42c5ed3a94fb1b251fa0fed3c0bbef0a9dbd407069", "snapshot_path": "sources/5379f97c72e4a91d87695c42c5ed3a94fb1b251fa0fed3c0bbef0a9dbd407069.txt", "url": "https://raw.githubusercontent.com/saturnis-io/cassini/main/LICENSE"}, {"fetched_at": "2026-10-27T14:51:37.638328+08:00", "kind": "readme", "sha256": "8112bebfdcfdbf4dc30d5f82e39273b5bd90b63b52e41c3611b10a442c1549c8", "snapshot_path": "sources/8112bebfdcfdbf4dc30d5f82e39273b5bd90b63b52e41c3611b10a442c1549c8.txt", "url": "https://raw.githubusercontent.com/saturnis-io/cassini/main/README.md"}], "summary": "Cassini 的开源核心是面向制造质量控制的 SPC 平台：按过程特性汇集时间序列样本，实时绘制变量与计数型控制图，按过程自身变异计算控制限并执行 Nelson/WECO/AIAG 判异规则，同时提供能力分析、Show Your Work 与哈希链审计；MSA/DOE、多工厂、电子签名与高级合规能力属 Pro/Enterprise。", "technology_stack": ["Python", "FastAPI", "React", "TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:rightsline','Rightsline','{"homepage": "https://www.rightsline.com/", "id": "commercial:rightsline", "leaf_matches": [{"reason": "官方首页正文说明集中保存拥有、管理或获许可的IP资产，跟踪合同状态，并处理复杂权利查询与可用性计算；据此记录媒体权利管理的基本商业案例。不将导航中的Avails and Conflict Engine当作已读工作流，不主张逐地区、渠道、窗口或独家字段的具体实现。", "slug": "media-rights-management", "source_urls": ["https://www.rightsline.com/"]}], "name": "Rightsline", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T13:28:31.303522+08:00", "kind": "homepage", "sha256": "414869b98bc4f071b3a1d62046eed3d1e2908f44ebe077277a954624a3a0f632", "snapshot_path": "sources/414869b98bc4f071b3a1d62046eed3d1e2908f44ebe077277a954624a3a0f632.txt", "url": "https://www.rightsline.com/"}], "summary": "商业IP权利与版税管理平台；本条仅记录媒体权利目录、合同状态和权利可用性查询的基本用途。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:141884906','Django Music Publisher','{"deployment": ["Self-hosted Django application", "Cloud or local installation"], "features": ["Musical work and recording metadata catalogue", "Writer and work-level manuscript share records", "Original publishing agreement data, share transfer and publisher fees", "CWR 2.1-3.1 registration export and acknowledgement import", "CSV royalty statement import and distribution data", "Single controlled original publisher; no uncontrolled publisher records"], "github_repository_id": 141884906, "homepage": "https://django-music-publisher.readthedocs.io", "id": "github:141884906", "leaf_matches": [{"reason": "Official repository metadata and DMP documentation describe musical-work metadata, writers and work-level manuscript shares, original publishing agreements, CWR registration, and royalty statement processing; recordings are catalogued alongside works but are not the ownership unit.", "slug": "music-publishing-management", "source_urls": ["https://api.github.com/repos/matijakolaric-com/django-music-publisher", "https://api.github.com/repos/matijakolaric-com/django-music-publisher/license", "https://django-music-publisher.readthedocs.io/en/latest/", "https://django-music-publisher.readthedocs.io/en/latest/features.html"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/matijakolaric-com/django-music-publisher/license", "name": "Django Music Publisher", "repository_url": "https://github.com/matijakolaric-com/django-music-publisher", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T13:28:02.338151+08:00", "kind": "repository_metadata", "sha256": "55140f9cbc4eb112becfe2ced0faab961201f6c414557efbf72ad0dfb233c871", "snapshot_path": "sources/55140f9cbc4eb112becfe2ced0faab961201f6c414557efbf72ad0dfb233c871.txt", "url": "https://api.github.com/repos/matijakolaric-com/django-music-publisher"}, {"fetched_at": "2026-10-27T13:28:17.800169+08:00", "kind": "license", "sha256": "b023c5bd07f1fc1a24d6bc7d31949f18daf551e9ad1789314b87f78ae4c8415c", "snapshot_path": "sources/b023c5bd07f1fc1a24d6bc7d31949f18daf551e9ad1789314b87f78ae4c8415c.txt", "url": "https://api.github.com/repos/matijakolaric-com/django-music-publisher/license"}, {"fetched_at": "2026-10-27T13:28:17.860278+08:00", "kind": "documentation", "sha256": "b17ee1a7d810066ad00005c470383e35caaac093ccc0c33a6b002fa97544bf4a", "snapshot_path": "sources/b17ee1a7d810066ad00005c470383e35caaac093ccc0c33a6b002fa97544bf4a.txt", "url": "https://django-music-publisher.readthedocs.io/en/latest/"}, {"fetched_at": "2026-10-27T13:28:41.928515+08:00", "kind": "documentation", "sha256": "1939cd4af1fba3bf9fe4d1b3b6429ead6e84a9badb615ea42c4c00e418d3d0b5", "snapshot_path": "sources/1939cd4af1fba3bf9fe4d1b3b6429ead6e84a9badb615ea42c4c00e418d3d0b5.txt", "url": "https://django-music-publisher.readthedocs.io/en/latest/features.html"}], "summary": "Open-source music publishing catalogue for small publishers: musical works, writers and work-level manuscript shares, original publishing agreements, CWR registrations, and CSV royalty statement processing; single controlled publisher only.", "technology_stack": ["Python", "Django"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:36218357','Superdesk Publisher','{"deployment": ["Self-hosted Symfony/PHP application on a standard web server", "Official Docker installation path", "Integrated with Superdesk for editorial production; can be extended to legacy back ends"], "features": ["Persistent article records with title, URL, route, metadata, keywords, authors and related media", "Output control separates incoming articles from published articles; incoming content stays offline until assigned to a tenant and route", "Explicit publishing to a tenant and route, publishing to additional tenants, route changes and unpublishing of published articles", "Webhook events for publish, unpublish and update of articles", "Site redirects plus an original article URL retained after slug or route changes", "Manual content lists where editors drag and drop published stories and the list order determines front-page order", "Automatic content lists driven by route, author, publication date and metadata rules"], "github_repository_id": 36218357, "homepage": "https://www.superdesk.org/publishing/publisher", "id": "github:36218357", "leaf_matches": [{"reason": "The official README identifies superdesk/web-publisher as \"Superdesk Publisher - the next generation publishing platform for journalists and newsrooms\" and links the official manual. The manual documents persistent article records (article title, url, route, metadata, keywords, authors and media loaders) and an output-control gate: \"incoming\" articles \"are not yet visible online\" until \"assigned to a tenant, and route\", while the published list supports route changes, unpublishing and publishing to additional tenants; webhook events cover when an editor \"publishes/unpublishes/updates an article\", and original_url preserves the article''s first URL after a slug or route change. Presentation surfaces are editorially curated and ordered: the manual says homepage teasers \"are curated by website editors using Content lists\", and in manual content lists editors \"drag and drop stories ... The order of articles here is the order in which they will appear on the front page\", with the order updated as news arrives. This covers the story record, gated/revisable publication and curated presentation layers. Scheduling/embargoes, a separately named correction workflow, newsroom planning/assignment and rundown are not claimed.", "slug": "news-publishing-platform", "source_urls": ["https://api.github.com/repos/superdesk/web-publisher", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/README.md", "https://www.superdesk.org/publishing/publisher", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/editorial_tools/content_lists.rst", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/content_lists.rst", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/output_control.rst", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/website_management.rst", "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/templates_system/articles.rst"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/superdesk/web-publisher/license", "name": "Superdesk Publisher", "repository_url": "https://github.com/superdesk/web-publisher", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-27T16:59:00.633342+08:00", "kind": "repository_metadata", "sha256": "5c30be3cf525935ba9f34054545d5c1cf2de97592a744e199b7616aac1336699", "snapshot_path": "sources/5c30be3cf525935ba9f34054545d5c1cf2de97592a744e199b7616aac1336699.txt", "url": "https://api.github.com/repos/superdesk/web-publisher"}, {"fetched_at": "2026-10-27T16:59:10.550602+08:00", "kind": "license", "sha256": "3ab22e6a6b310a0bcceed7ae43705c7510905074b68150fdf736572670a782d3", "snapshot_path": "sources/3ab22e6a6b310a0bcceed7ae43705c7510905074b68150fdf736572670a782d3.txt", "url": "https://api.github.com/repos/superdesk/web-publisher/license"}, {"fetched_at": "2026-10-27T16:59:08.512846+08:00", "kind": "readme", "sha256": "d3825c2b1b34b74e6c86e0103cdf4175b644cd9943b071b11569c515e520f346", "snapshot_path": "sources/d3825c2b1b34b74e6c86e0103cdf4175b644cd9943b071b11569c515e520f346.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/README.md"}, {"fetched_at": "2026-10-27T16:59:46.913555+08:00", "kind": "homepage", "sha256": "12fe2e4e849a6b8d0d4159ca81d1d0f465106bf1d25cb6ae0a25b29bbe965680", "snapshot_path": "sources/12fe2e4e849a6b8d0d4159ca81d1d0f465106bf1d25cb6ae0a25b29bbe965680.txt", "url": "https://www.superdesk.org/publishing/publisher"}, {"fetched_at": "2026-10-27T17:02:36.647137+08:00", "kind": "documentation", "sha256": "ae6d5b165bdfa2156e1c33bd4aebe15780c0e524d76027434a213db21a9e09d1", "snapshot_path": "sources/ae6d5b165bdfa2156e1c33bd4aebe15780c0e524d76027434a213db21a9e09d1.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/editorial_tools/content_lists.rst"}, {"fetched_at": "2026-10-27T17:02:38.099032+08:00", "kind": "documentation", "sha256": "05bd74985a6c9ff707a50ff2ac9e67b47d9169649bcced86703ff84556521ccf", "snapshot_path": "sources/05bd74985a6c9ff707a50ff2ac9e67b47d9169649bcced86703ff84556521ccf.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/content_lists.rst"}, {"fetched_at": "2026-10-27T17:02:39.381178+08:00", "kind": "documentation", "sha256": "b79a8337fc793a9179575d79d9d42b0154b8ca838867ed3fd1dafe3cf3ad347e", "snapshot_path": "sources/b79a8337fc793a9179575d79d9d42b0154b8ca838867ed3fd1dafe3cf3ad347e.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/output_control.rst"}, {"fetched_at": "2026-10-27T17:02:41.973328+08:00", "kind": "documentation", "sha256": "de4df09a2f3407ddef00ee4514ac54fabbe23325e2f73372d9eb792edcc15fa4", "snapshot_path": "sources/de4df09a2f3407ddef00ee4514ac54fabbe23325e2f73372d9eb792edcc15fa4.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/admin_interface/website_management.rst"}, {"fetched_at": "2026-10-27T17:02:43.612450+08:00", "kind": "documentation", "sha256": "80d3c94abbe29ffc34f018d35d468cca45cce1ce87a637fde16c4eeca75b0102", "snapshot_path": "sources/80d3c94abbe29ffc34f018d35d468cca45cce1ce87a637fde16c4eeca75b0102.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/templates_system/articles.rst"}, {"fetched_at": "2026-10-27T17:06:06.506157+08:00", "kind": "documentation", "sha256": "3a14e2fa1487dc91a1cfe5b9bed6d0020a06c58f64e8d47817833abfccb00405", "snapshot_path": "sources/3a14e2fa1487dc91a1cfe5b9bed6d0020a06c58f64e8d47817833abfccb00405.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/templates_system/article_author.rst"}, {"fetched_at": "2026-10-27T17:06:07.770895+08:00", "kind": "documentation", "sha256": "d4468585dfda05d5c1a29b8e37189cea1c2faf52482c680de0db8f9bfa37da44", "snapshot_path": "sources/d4468585dfda05d5c1a29b8e37189cea1c2faf52482c680de0db8f9bfa37da44.txt", "url": "https://raw.githubusercontent.com/superdesk/web-publisher/develop/docs/manual/templates_system/article_media.rst"}], "summary": "Open-source (AGPL-3.0) publishing platform for journalists and newsrooms in the Superdesk suite. Articles are held as persistent records and pass through an output-control gate: incoming articles are not visible online until assigned to a tenant and route, and published articles can be moved to another route, published to additional tenants or unpublished. Editors can also build manual content lists by dragging and dropping published stories, with the list order defining front-page order. Content can also originate in Superdesk or a legacy editorial back end.", "technology_stack": ["PHP", "Symfony", "PostgreSQL", "Twig"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:26661222','Tinode','{"deployment": ["自托管 Go 服务端；按官方 INSTALL.md，安装后浏览器访问 http://localhost:6060/ 进行验证", "提供 Docker 镜像与 docker/README.md 部署说明", "支持 MySQL、PostgreSQL、MongoDB 等数据库后端保存消息与账号数据", "Web 界面需从独立仓库 tinode/webapp 获取，并以 -static_data 静态目录挂载，不在服务端仓库内"], "features": ["个人账号与联系人：服务端支持用户 ID，客户端可按邮箱或电话前缀搜索/发现其他用户；电话凭证的短信验证需商业短信订阅，非开箱即用", "一对一 P2P 会话与成员自建群组会话，支持群组权限与成员管理", "消息送达、已读回执和输入状态通知（{note.recv} / {note.read}）", "消息编辑、转发、回复、置顶与收藏", "服务端将 {data} 消息持久化到数据库，客户端可按消息 ID 分页拉取历史", "官方 Web 客户端 TinodeWeb 为独立仓库 tinode/webapp（Apache-2.0），构建为静态文件后由服务端挂载提供浏览器界面"], "github_repository_id": 26661222, "homepage": "https://tinode.co/", "id": "github:26661222", "leaf_matches": [{"reason": "官方 README、INSTALL.md 与 API 文档证明 Tinode 是完整即时通讯应用：用户有唯一 usr ID，P2P 主题按对端用户 ID 建立、群组由成员自建，{note.recv}/{note.read} 提供送达/已读状态，{data} 消息持久化到数据库并可按消息 ID 分页读取历史；官方首页明确可自托管，属于客户可自行运营的完整应用服务。官方 Web 客户端为独立仓库 tinode/webapp（Apache-2.0），服务端仓库为 GPL-3.0。", "slug": "instant-messaging-application", "source_urls": ["https://raw.githubusercontent.com/tinode/chat/master/README.md", "https://raw.githubusercontent.com/tinode/chat/master/INSTALL.md", "https://raw.githubusercontent.com/tinode/chat/master/docs/API.md", "https://tinode.co/"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/tinode/chat/master/LICENSE", "license_review": {"rationale": "逐字读取仓库根目录 LICENSE 全文（35147 字节），为 GNU General Public License Version 3, 29 June 2007 的完整正文，据此将该服务端仓库识别为 GPL-3.0，不代表同组织其他客户端仓库的许可证。", "reviewer": "collector: DeepSeek V4.1 Flash, retained-evidence-20261028-u002", "scope": "repository", "source_url": "https://raw.githubusercontent.com/tinode/chat/master/LICENSE", "spdx_id": "GPL-3.0"}, "name": "Tinode", "repository_url": "https://github.com/tinode/chat", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T08:44:47.366199+08:00", "kind": "repository_metadata", "sha256": "3a4df8d64711c05026d3cebb478bc30921ae2b387724bfb8ea2d914a9b5e8b2d", "snapshot_path": "sources/3a4df8d64711c05026d3cebb478bc30921ae2b387724bfb8ea2d914a9b5e8b2d.txt", "url": "https://api.github.com/repos/tinode/chat"}, {"fetched_at": "2026-10-28T08:51:40.825216+08:00", "kind": "license", "sha256": "8ceb4b9ee5adedde47b31e975c1d90c73ad27b6b165a1dcd80c7c545eb65b903", "snapshot_path": "sources/8ceb4b9ee5adedde47b31e975c1d90c73ad27b6b165a1dcd80c7c545eb65b903.txt", "url": "https://raw.githubusercontent.com/tinode/chat/master/LICENSE"}, {"fetched_at": "2026-10-28T08:44:47.622312+08:00", "kind": "license", "sha256": "2054bbf1d41b3ad935ce9e90d0be4c6b8f2a90706bb8db0ddfb0d7cc0cbce57f", "snapshot_path": "sources/2054bbf1d41b3ad935ce9e90d0be4c6b8f2a90706bb8db0ddfb0d7cc0cbce57f.txt", "url": "https://api.github.com/repos/tinode/chat/license"}, {"fetched_at": "2026-10-28T08:44:47.232511+08:00", "kind": "readme", "sha256": "82688179d12e863cc0d9bd2b573378cb3395758263dd40da1b5b9c1df311815e", "snapshot_path": "sources/82688179d12e863cc0d9bd2b573378cb3395758263dd40da1b5b9c1df311815e.txt", "url": "https://raw.githubusercontent.com/tinode/chat/master/README.md"}, {"fetched_at": "2026-10-28T08:51:04.988508+08:00", "kind": "documentation", "sha256": "54ce4aefb7b40e38eb9af0071c69b65cfdd2e0706fa860a50715966e53bdde2a", "snapshot_path": "sources/54ce4aefb7b40e38eb9af0071c69b65cfdd2e0706fa860a50715966e53bdde2a.txt", "url": "https://raw.githubusercontent.com/tinode/chat/master/INSTALL.md"}, {"fetched_at": "2026-10-28T08:46:26.881475+08:00", "kind": "documentation", "sha256": "56a601bb8af742525bc3b99197a79a3cb3396be33cc04d16fee1b2819fa702e9", "snapshot_path": "sources/56a601bb8af742525bc3b99197a79a3cb3396be33cc04d16fee1b2819fa702e9.txt", "url": "https://raw.githubusercontent.com/tinode/chat/master/docs/API.md"}, {"fetched_at": "2026-10-28T08:45:08.321493+08:00", "kind": "homepage", "sha256": "113523b408e05ee2990f6b4649b067e210140febe47f17dcf71856ff573b95cb", "snapshot_path": "sources/113523b408e05ee2990f6b4649b067e210140febe47f17dcf71856ff573b95cb.txt", "url": "https://tinode.co/"}], "summary": "完整开源自托管即时通讯应用：Go 服务端（GPL-3.0）提供个人账号、一对一与成员自建群组会话、送达/已读状态与持久化消息历史；官方 Web（TinodeWeb）、Android、iOS 客户端为独立 Apache-2.0 仓库，可配合该服务端部署。可选的 Tinode Push Gateway（TNPG）推送网关为闭源服务，核心自托管不依赖。", "technology_stack": ["Go（服务端，GPL-3.0）", "ReactJS（官方 Web 客户端 tinode/webapp，Apache-2.0）", "Java（官方 Android 客户端 tinode/tindroid，Apache-2.0）", "Swift（官方 iOS 客户端 tinode/ios，Apache-2.0）", "JSON over WebSocket 或 protobuf/gRPC"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:mail-tm','Mail.tm','{"homepage": "https://mail.tm/", "id": "commercial:mail-tm", "leaf_matches": [{"reason": "官方 FAQ 正文写明该服务是“temporary, completely anonymous email address that requires no registration”，来信“appear right under your mailbox address”即站内阅读，且“your personal data, the address itself and all emails are erased once you delete the mailbox”“mailbox stays valid until you delete it yourself”（站内邮件另保留 7 天），无身份签发、服务内收件箱与用户删除即销毁三项均可直接核对；官方 API 文档另写明“Create temporary email accounts and receive emails via REST API. No API key required.”并说明服务端接收并存储邮件。首页快照仅用于确认站点身份与标题（“Free Temporary Email, No Sign-Up”），不作为上述功能陈述的依据。", "slug": "disposable-email-service", "source_urls": ["https://mail.tm/en/faq/", "https://docs.mail.tm/"]}], "name": "Mail.tm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T08:47:18.616231+08:00", "kind": "homepage", "sha256": "4da3aa6524ddbaa12f089e7d7f9716c2c03b002ac5229b5915247895b39af3aa", "snapshot_path": "sources/4da3aa6524ddbaa12f089e7d7f9716c2c03b002ac5229b5915247895b39af3aa.txt", "url": "https://mail.tm/"}, {"fetched_at": "2026-10-28T09:01:42.357128+08:00", "kind": "documentation", "sha256": "a11ea460d7d026597e85b28558a6e3c8af78d05852859a9e6d48af785d10fb1b", "snapshot_path": "sources/a11ea460d7d026597e85b28558a6e3c8af78d05852859a9e6d48af785d10fb1b.txt", "url": "https://mail.tm/en/faq/"}, {"fetched_at": "2026-10-28T09:01:02.819113+08:00", "kind": "documentation", "sha256": "fce99cf934e6cb8f19c945714879912a8d174c4a3f0ac5e11a0e5053e833fc4c", "snapshot_path": "sources/fce99cf934e6cb8f19c945714879912a8d174c4a3f0ac5e11a0e5053e833fc4c.txt", "url": "https://docs.mail.tm/"}], "summary": "在线临时邮箱服务：无需注册即可获得临时地址，并在站内收件箱直接阅读来信；邮箱在用户自行删除前保持有效，站内保存的邮件保留 7 天，另提供无需 API key 的 REST API。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1144130915','CloakMail','{"deployment": ["官方 README 提供 docker compose 自托管方式，另可选 Cloudflare Workers 部署"], "features": ["No authentication required：打开即生成收件箱，无需注册或登录", "内置 SMTP 服务器直接接收邮件，并在自带 Web UI 中阅读", "邮件与地址按可配置 TTL 自动删除，默认 86400 秒", "提供 REST API（OpenAPI 文档）与 Docker 部署"], "github_repository_id": 1144130915, "homepage": "https://cloakmail.dev/", "id": "github:1144130915", "leaf_matches": [{"reason": "README 正文明确为 self-hosted disposable email：无认证即时生成地址、自带 SMTP 与 Web 收件箱在服务内收信、按 TTL 自动过期，三项定义性属性均在官方正文中可核。", "slug": "disposable-email-service", "source_urls": ["https://raw.githubusercontent.com/DreamsHive/cloakmail/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/DreamsHive/cloakmail/license", "license_review": {"rationale": "GitHub license endpoint returned the complete repository LICENSE text; decoded text is the full MIT License (Copyright (c) 2025 DreamsHive) including permission grant and warranty disclaimer.", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/DreamsHive/cloakmail/license", "spdx_id": "MIT"}, "name": "CloakMail", "repository_url": "https://github.com/DreamsHive/cloakmail", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T08:45:57.971978+08:00", "kind": "repository_metadata", "sha256": "078b07b77a8f2356703aa32c31e88ca75546bcb240169011af5d2f68364c4e6e", "snapshot_path": "sources/078b07b77a8f2356703aa32c31e88ca75546bcb240169011af5d2f68364c4e6e.txt", "url": "https://api.github.com/repos/DreamsHive/cloakmail"}, {"fetched_at": "2026-10-28T08:46:17.348008+08:00", "kind": "license", "sha256": "feb7c1f0184f6b185e7d9129aeeb77bea36c9ee515630c333b8af17abfc71dde", "snapshot_path": "sources/feb7c1f0184f6b185e7d9129aeeb77bea36c9ee515630c333b8af17abfc71dde.txt", "url": "https://api.github.com/repos/DreamsHive/cloakmail/license"}, {"fetched_at": "2026-10-28T08:45:59.401608+08:00", "kind": "readme", "sha256": "c7d5412994415210e3915e3bc85e465903d7e3a6233b6051826f988810d50a15", "snapshot_path": "sources/c7d5412994415210e3915e3bc85e465903d7e3a6233b6051826f988810d50a15.txt", "url": "https://raw.githubusercontent.com/DreamsHive/cloakmail/main/README.md"}], "summary": "自托管的开源临时邮箱服务：无需注册即时生成临时地址与 Web 收件箱，内置 SMTP 直接收信，邮件与地址按可配置 TTL 自动过期删除。", "technology_stack": ["TypeScript", "SvelteKit", "Tailwind CSS", "Docker", "Cloudflare Workers"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1263870796','MailTub','{"deployment": ["官方 README 与部署文档提供单二进制、Docker 及 Docker Compose 自托管方式"], "features": ["无需注册即时签发随机地址或自定义 local-part，并直接提供内置收件箱", "邮件经 WebSocket 实时到达，单会话可同时持有多个收件箱", "每邮箱可选 1h/6h/24h/7d 过期，并由服务端按 TTL 清理"], "github_repository_id": 1263870796, "homepage": "https://github.com/DML-Labs/MailTub", "id": "github:1263870796", "leaf_matches": [{"reason": "README 正文明确为 self-hosted disposable email：无需注册即时生成地址与内置收件箱、邮件在服务内实时接收，并按 1h/6h/24h/7d 过期，匿名签发、自含收件箱与可丢弃性三项齐备。", "slug": "disposable-email-service", "source_urls": ["https://raw.githubusercontent.com/dml-labs/mailtub/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/dml-labs/mailtub/license", "license_review": {"rationale": "GitHub license endpoint returned the complete repository LICENSE text; decoded text begins Apache License Version 2.0 and includes its full terms.", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/dml-labs/mailtub/license", "spdx_id": "Apache-2.0"}, "name": "MailTub", "repository_url": "https://github.com/DML-Labs/MailTub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-23T19:36:47.269404+08:00", "kind": "repository_metadata", "sha256": "4f4dc629b746367eddf896e5dbbbb5610997d51ac97e1a011d31f8692020c6df", "snapshot_path": "sources/4f4dc629b746367eddf896e5dbbbb5610997d51ac97e1a011d31f8692020c6df.txt", "url": "https://api.github.com/repos/dml-labs/mailtub"}, {"fetched_at": "2026-10-23T19:36:48.949940+08:00", "kind": "license", "sha256": "6a433a7b73a0a14a49bfa1e990f795e61d8474f9c73bcc6c7c11e86bcb7c5cb3", "snapshot_path": "sources/6a433a7b73a0a14a49bfa1e990f795e61d8474f9c73bcc6c7c11e86bcb7c5cb3.txt", "url": "https://api.github.com/repos/dml-labs/mailtub/license"}, {"fetched_at": "2026-10-23T19:36:51.071088+08:00", "kind": "readme", "sha256": "3bda045410f28634d8d2233bb1fc06f01812b7fa35172fe9494fa7e87998b22b", "snapshot_path": "sources/3bda045410f28634d8d2233bb1fc06f01812b7fa35172fe9494fa7e87998b22b.txt", "url": "https://raw.githubusercontent.com/dml-labs/mailtub/main/README.md"}, {"fetched_at": "2026-10-28T09:02:37.960206+08:00", "kind": "documentation", "sha256": "e70867a17a3d9cf4a0e07f3d027ba1c632564f3de6ccb430df0b07c889f71ffb", "snapshot_path": "sources/e70867a17a3d9cf4a0e07f3d027ba1c632564f3de6ccb430df0b07c889f71ffb.txt", "url": "https://raw.githubusercontent.com/DML-Labs/MailTub/main/docs/deployment.md"}], "summary": "自托管的一次性临时邮箱服务：打开即得随机地址或自定义地址及内置收件箱，WebSocket 实时收信，邮箱可按 1 小时至 7 天过期。", "technology_stack": ["Go", "SQLite", "WebSocket", "React", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1138270023','PIN (Personal Identity Node)','{"deployment": ["自托管 Go 服务，默认监听 127.0.0.1:5000", "SQLite 单机存储，环境变量配置", "首次运行在 /setup 创建所有者账户；本次未部署或运行"], "features": ["单个或多个个人/组织档案的创建与设置页维护", "稳定句柄路径与不可变 subject 标识作为共享命名空间地址", "公开档案以 canonical JSON、XML、纯文本与 vCard 输出", "PINC 能力与身份 schema 的 well-known 发现文档", "按客户端作用域与私密/同步权限发放的 claims API（默认关闭，需显式启用 PIN_CLAIMS_API_ENABLED）", "增量变更同步与可选 webhook 推送", "LDAP/AD/SAML/Kerberos 协议投影适配与审计"], "github_repository_id": 1138270023, "homepage": "https://github.com/mlumeau/pin", "id": "github:1138270023", "leaf_matches": [{"reason": "官方 README 与端点文档显示这是完整自托管身份服务器：所有者维护权威个人档案，档案以稳定句柄路径（/{handle}.json 等）和不可变 subject_id（meta.subject）在共享命名空间中寻址；同一档案以 canonical JSON/XML/文本/vCard 公开放出，并有 well-known 发现、按客户端策略的 claims API、增量同步与 LDAP/AD/SAML/Kerberos 投影供外部系统消费。README 明示“The profile page is not the primary product, identity is”，并在 Non-goals 中明确“Act as a social network or community platform”，与本叶“档案即记录、对外消费、无信息流义务”的窄核心一致；本叶不要求信息流/关注/消息，故其“非社交网络”自述与入叶依据不矛盾。", "slug": "social-profile-network", "source_urls": ["https://api.github.com/repos/mlumeau/pin", "https://raw.githubusercontent.com/mlumeau/pin/main/README.md", "https://raw.githubusercontent.com/mlumeau/pin/main/docs/user/endpoints.md", "https://api.github.com/repos/mlumeau/pin/license"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/mlumeau/pin/license", "name": "PIN (Personal Identity Node)", "repository_url": "https://github.com/mlumeau/pin", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:06:19.534242+08:00", "kind": "repository_metadata", "sha256": "6d0a07c9ec30e15064fc00f4c878902f71c2ca8271b1cf5d3c8e27595f683bcc", "snapshot_path": "sources/6d0a07c9ec30e15064fc00f4c878902f71c2ca8271b1cf5d3c8e27595f683bcc.txt", "url": "https://api.github.com/repos/mlumeau/pin"}, {"fetched_at": "2026-10-28T09:06:19.848407+08:00", "kind": "license", "sha256": "42322730fd43e2e90b52356a48c1192b5ad728551491d67364f18681265a41c1", "snapshot_path": "sources/42322730fd43e2e90b52356a48c1192b5ad728551491d67364f18681265a41c1.txt", "url": "https://api.github.com/repos/mlumeau/pin/license"}, {"fetched_at": "2026-10-28T09:06:19.338134+08:00", "kind": "readme", "sha256": "576216b427b37f7d0bde290114bb0292829e8eb744bd4b8da9344195de4b15bb", "snapshot_path": "sources/576216b427b37f7d0bde290114bb0292829e8eb744bd4b8da9344195de4b15bb.txt", "url": "https://raw.githubusercontent.com/mlumeau/pin/main/README.md"}, {"fetched_at": "2026-10-28T09:08:58.875727+08:00", "kind": "documentation", "sha256": "b1da24522c5459e1a5c97deb6fc63a5e8e438c361aa9bd5c1febd9c8a1a565f3", "snapshot_path": "sources/b1da24522c5459e1a5c97deb6fc63a5e8e438c361aa9bd5c1febd9c8a1a565f3.txt", "url": "https://raw.githubusercontent.com/mlumeau/pin/main/docs/user/endpoints.md"}], "summary": "自托管的个人与组织身份服务器：用户维护一份权威档案，以稳定句柄和不可变 subject 标识在共享命名空间中寻址，并通过 JSON/XML/vCard、well-known、机器可读 claims API 与增量同步供外部系统读取和投影。README 明确其非目标为“作为社交网络或社区平台”，档案页本身不是主要产品。", "technology_stack": ["Go net/http 服务端渲染", "SQLite (modernc.org/sqlite)", "WebAuthn 通行密钥与 TOTP", "WebP 图片处理"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:776886715','BookLogr','{"deployment": ["自托管部署，运行于用户自有服务器", "SQLite（默认）或 PostgreSQL 数据库"], "features": ["预置阅读状态列表：Currently Reading、To Be Read、Read、Did Not Finish", "通过 OpenLibrary 按书名/作者/ISBN 检索并添加书籍，支持手动添加 OpenLibrary 未收录书目", "阅读进度跟踪：按页码或完成百分比更新", "阅读会话日志，含每本书的开始与结束日期", "评分（0.5-5 星）、个人笔记、书评与带页码的摘录", "书架/列表排序与视图切换（Gallery/List），按标题、作者、进度、评分或添加日期排序", "数据导入导出：从 Goodreads 迁移或 CSV 重新导入，随时导出 CSV/JSON/HTML", "可选公开个人主页分享馆藏与公开笔记", "单用户私有模式与多用户共享模式"], "github_repository_id": 776886715, "homepage": "https://booklogr.app", "id": "github:776886715", "leaf_matches": [{"reason": "官方功能文档与 README 正文明确：以书目记录建立个人馆藏，按 Currently Reading/To Be Read/Read/Did Not Finish 阅读状态列表组织，记录页码/百分比进度、起止日期、评分、笔记与摘录，并可导入导出个人图书馆数据——完整覆盖该类型的书目记录、个人图书馆与个人关系层三条核心，且不提供书籍正文阅读。", "slug": "reading-library-application", "source_urls": ["https://booklogr.app/docs/Features/Overview/", "https://raw.githubusercontent.com/Mozzo1000/booklogr/main/README.md", "https://api.github.com/repos/Mozzo1000/booklogr", "https://api.github.com/repos/Mozzo1000/booklogr/license"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/Mozzo1000/booklogr/license", "name": "BookLogr", "repository_url": "https://github.com/Mozzo1000/booklogr", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:22:47.243007+08:00", "kind": "repository_metadata", "sha256": "c05758aa53001a970e56e1a7b30eb3c13c7560d71dff66333eba0de21b5d4ef4", "snapshot_path": "sources/c05758aa53001a970e56e1a7b30eb3c13c7560d71dff66333eba0de21b5d4ef4.txt", "url": "https://api.github.com/repos/Mozzo1000/booklogr"}, {"fetched_at": "2026-10-28T09:22:47.312527+08:00", "kind": "license", "sha256": "c24ace95cd98a59174acb276ee9f0c1da5db67644a2caeb853b8771b6cffd481", "snapshot_path": "sources/c24ace95cd98a59174acb276ee9f0c1da5db67644a2caeb853b8771b6cffd481.txt", "url": "https://api.github.com/repos/Mozzo1000/booklogr/license"}, {"fetched_at": "2026-10-28T09:22:47.220984+08:00", "kind": "readme", "sha256": "1a6b57836cdc9743aa55a2a60fd3bde2ecf0f3b324c8b4ca33a66760bd365daf", "snapshot_path": "sources/1a6b57836cdc9743aa55a2a60fd3bde2ecf0f3b324c8b4ca33a66760bd365daf.txt", "url": "https://raw.githubusercontent.com/Mozzo1000/booklogr/main/README.md"}, {"fetched_at": "2026-10-28T09:22:47.577134+08:00", "kind": "documentation", "sha256": "534a75855b8d633b29124eac536013414e6424ac0f6ce0d2142e22446b3df3b4", "snapshot_path": "sources/534a75855b8d633b29124eac536013414e6424ac0f6ce0d2142e22446b3df3b4.txt", "url": "https://booklogr.app/docs/Features/Overview/"}], "summary": "自托管的个人图书管理 Web 应用：以书目记录为中心建立个人馆藏，按 Currently Reading / To Be Read / Read / Did Not Finish 阅读状态列表组织书籍，记录阅读进度（页码或百分比）、起止日期、评分、笔记与摘录，并支持 CSV/JSON/HTML 导入导出。", "technology_stack": ["Python", "Flask", "React", "SQLite", "PostgreSQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:calmly-writer','Calmly Writer','{"homepage": "https://calmlywriter.com/", "id": "commercial:calmly-writer", "leaf_matches": [{"reason": "官方首页把产品定义为“无干扰写作应用”，说明传统文字处理器的众多格式选项会分散写作注意力，而 Calmly 以简洁不打扰的界面让用户专注故事本身；在线版页面说明打开即写、无工具栏/侧栏，文档在浏览器中自动保存，桌面版以本地文件与自动保存持久保留草稿。持久文档、近乎只有文本的写作面与起草优先三项成立。", "slug": "distraction-free-writing-application", "source_urls": ["https://calmlywriter.com/", "https://calmlywriter.com/online.htm", "https://calmlywriter.com/online-vs-app.htm"]}], "name": "Calmly Writer", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:27:09.990022+08:00", "kind": "homepage", "sha256": "d0e273f73d604e0245ceb693dc88637ba0bec86ed558fc53f493508000ba02b8", "snapshot_path": "sources/d0e273f73d604e0245ceb693dc88637ba0bec86ed558fc53f493508000ba02b8.txt", "url": "https://calmlywriter.com/"}, {"fetched_at": "2026-10-28T09:29:00.068146+08:00", "kind": "documentation", "sha256": "473f5a6b52fdb73c6e9ed87f6ab69171040356f6e3c1d1286dbabfd407985da6", "snapshot_path": "sources/473f5a6b52fdb73c6e9ed87f6ab69171040356f6e3c1d1286dbabfd407985da6.txt", "url": "https://calmlywriter.com/online.htm"}, {"fetched_at": "2026-10-28T09:28:58.607353+08:00", "kind": "documentation", "sha256": "27ed18e3e00ddf0827ba58a25c96e6d2d74fa6dd0075260e7ae7bed41c3353bf", "snapshot_path": "sources/27ed18e3e00ddf0827ba58a25c96e6d2d74fa6dd0075260e7ae7bed41c3353bf.txt", "url": "https://calmlywriter.com/online-vs-app.htm"}], "summary": "Calmly Writer 是面向散文起草的写作应用，官方以“无干扰写作”为产品核心：界面刻意保持简洁，工具栏不常驻，Markdown 在输入时直接呈现为样式而无需阅读标记；在线版在浏览器中自动保存文档，桌面版另以本地文件、自动保存与版本历史持久保留草稿。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:86956808','WriteFreely','{"deployment": ["以 Go 静态二进制自托管，内置 SQLite 或连接 MySQL/MariaDB", "提供 Docker 镜像"], "features": ["精简的纯文本编辑器，官方说明其只服务于写作，不推送通知或统计", "Markdown/HTML 轻量标记录入，格式化在发布渲染时呈现", "写作自动保存，离开后可回到原处继续", "草稿（Drafts）与博客文章均可持久保存，支持多博客"], "github_repository_id": 86956808, "homepage": "https://writefreely.org/", "id": "github:86956808", "leaf_matches": [{"reason": "官方 Features 页称 WriteFreely 围绕专注写作构建，编辑器被削减到只做写作一件事，不用通知或统计打扰；README 称其为“distraction-free writing environment”，正文用 Markdown 录入、格式化在渲染/发布时呈现；Autosave 文档证明写作自动保存、离开后可回到原处，Drafts 文档证明草稿持久保存。持久文档、无干扰写作面与起草优先三项均成立。", "slug": "distraction-free-writing-application", "source_urls": ["https://writefreely.org/features/", "https://raw.githubusercontent.com/writefreely/writefreely/develop/README.md", "https://writefreely.org/docs/main/writer/autosave", "https://writefreely.org/docs/main/writer/drafts", "https://writefreely.org/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/writefreely/writefreely/license", "name": "WriteFreely", "repository_url": "https://github.com/writefreely/writefreely", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:27:10.222067+08:00", "kind": "homepage", "sha256": "93b4a04f2dd5f11745f2d62f2a99d6a48c0f728c08532640416520ff9da57f52", "snapshot_path": "sources/93b4a04f2dd5f11745f2d62f2a99d6a48c0f728c08532640416520ff9da57f52.txt", "url": "https://writefreely.org/"}, {"fetched_at": "2026-10-28T09:27:36.365588+08:00", "kind": "repository_metadata", "sha256": "b2df750d1296a435b20973a270b25e9cd564bd54e5479ba9cfe9044a5419ae5c", "snapshot_path": "sources/b2df750d1296a435b20973a270b25e9cd564bd54e5479ba9cfe9044a5419ae5c.txt", "url": "https://api.github.com/repos/writefreely/writefreely"}, {"fetched_at": "2026-10-28T09:27:38.511630+08:00", "kind": "license", "sha256": "b1e0cb18f49eae900bf8daa7a2566c7f2d850131f007cb2ecc0890521d6c11ee", "snapshot_path": "sources/b1e0cb18f49eae900bf8daa7a2566c7f2d850131f007cb2ecc0890521d6c11ee.txt", "url": "https://api.github.com/repos/writefreely/writefreely/license"}, {"fetched_at": "2026-10-28T09:27:54.814509+08:00", "kind": "readme", "sha256": "4753e14323ae0ce1d385bf37bcd98f5f66c70adc1a2a1d4401c3785fa506e34b", "snapshot_path": "sources/4753e14323ae0ce1d385bf37bcd98f5f66c70adc1a2a1d4401c3785fa506e34b.txt", "url": "https://raw.githubusercontent.com/writefreely/writefreely/develop/README.md"}, {"fetched_at": "2026-10-28T09:28:58.913882+08:00", "kind": "documentation", "sha256": "3607126136cdfc66b710835309f1059825786e840dd5a5c18a3091b2c7dafc70", "snapshot_path": "sources/3607126136cdfc66b710835309f1059825786e840dd5a5c18a3091b2c7dafc70.txt", "url": "https://writefreely.org/features/"}, {"fetched_at": "2026-10-28T09:29:01.273001+08:00", "kind": "documentation", "sha256": "b441ee3cb782330a95e30e1ec38f45f6e108f0b2ea965370c55e578dea46e7c3", "snapshot_path": "sources/b441ee3cb782330a95e30e1ec38f45f6e108f0b2ea965370c55e578dea46e7c3.txt", "url": "https://writefreely.org/docs/main/writer/autosave"}, {"fetched_at": "2026-10-28T09:29:03.598964+08:00", "kind": "documentation", "sha256": "81de01ac304842c55c6d4c88e8eebe4cf109641431e919fb5790208fb61edb8c", "snapshot_path": "sources/81de01ac304842c55c6d4c88e8eebe4cf109641431e919fb5790208fb61edb8c.txt", "url": "https://writefreely.org/docs/main/writer/drafts"}], "summary": "WriteFreely 是 AGPL-3.0 开源的写作与发布平台，可自托管。其编辑器刻意精简到只做写作一件事：无通知、无统计横幅，正文以 Markdown 轻量标记录入，格式化留到渲染/发布时呈现；写作内容自动保存，并可用草稿与博客文章形式长期保留。", "technology_stack": ["Go", "SQLite", "MySQL/MariaDB", "ActivityPub"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:67508428','draw.io','{"deployment": ["官方提供可自托管的 Docker 图表服务器（jgraph/drawio 镜像，基于 Tomcat，可置于反向代理后），浏览器内完成编辑与导出，图表数据留在自有服务器，并可配置 Google Drive/OneDrive 存储", "官方同时提供在线编辑器 app.diagrams.net、Windows/macOS/Linux 桌面应用及 Confluence/Jira 等集成", "README 说明该仓库是可自行发布的测试/评估版本，生产部署另有付费版本；图表文件可存于 Google Drive、OneDrive、GitHub/GitLab、浏览器或本地设备", "README 明确写明“draw.io does not support real-time collaborative editing in this version, currently.”，故不把实时协作计入本开放源码仓库能力；实时协作属付费生产版或 Confluence/Jira 等集成部署，本条不据此判定图表应用核心类型"], "features": ["形状库/模板库，可搜索并拖放流程图、UML、网络、平面图等符号", "连接线可固定或浮动附着于形状，移动时保持连接并自动或手动重路由", "多页图表文档、图层、标签与形状元数据", "导出 PNG/SVG/PDF/HTML 等格式；所引 Apache-2.0 测试仓库不支持实时协作，生产/集成部署能力另见 deployment 边界"], "github_repository_id": 67508428, "homepage": "https://www.drawio.com", "id": "github:67508428", "leaf_matches": [{"reason": "官方功能页与用户手册正文说明：从形状库拖放形状、在形状间绘制固定或浮动连接线，连接线随形状移动并保持附着、可自动重路由或加路径点；形状带标签与元数据，文档支持多页、图层与导出，满足持久图表文档、语义形状、绑定连接线与形状词汇表四项核心。服务形态：本轮补采的官方文档明确提供可自托管的 Docker 图表服务器（“Run your own diagramming server using our Docker image of draw.io”，浏览器内编辑/导出、数据不出自有服务器，与 app.diagrams.net 生产版同步），加上官方在线编辑器与桌面应用，构成完整可持续使用的应用服务，而非仅客户端库或 CLI；dc 明示本地文件/桌面形态同样满足，故供应商不托管数据不构成排除。许可与发行边界：核心能力来自 Apache-2.0 的 jgraph/drawio 编辑器源码（仓库 id 67508428，license API 与完整文本一致）；README 明确该仓库是可自行发布的 test/评估版本，生产部署另有付费版本，图标/模板对 Atlassian 市场另有书面许可限制。本条不把付费生产发行版或 Atlassian 市场集成当作开源能力；用于自托管打包的 jgraph/docker-drawio 为独立 GPL-3.0 仓库，仅作部署形态佐证，不计入本条目许可字段。", "slug": "diagramming-application", "source_urls": ["https://www.drawio.com/docs/features/", "https://www.drawio.com/docs/manual/", "https://www.drawio.com/docs/security/diagrams-docker-app/", "https://raw.githubusercontent.com/jgraph/drawio/dev/README.md", "https://www.drawio.com/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/jgraph/drawio/license", "name": "draw.io", "repository_url": "https://github.com/jgraph/drawio", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T12:25:59.935597+08:00", "kind": "repository_metadata", "sha256": "9e491ad59549c768116b6d67f56fb01982408ce1c33b1b991130298f40f43f25", "snapshot_path": "sources/9e491ad59549c768116b6d67f56fb01982408ce1c33b1b991130298f40f43f25.txt", "url": "https://api.github.com/repos/jgraph/drawio"}, {"fetched_at": "2026-10-24T12:28:54.325084+08:00", "kind": "license", "sha256": "cf979f5392b9da229f911f3453fde981c9dec4d77a89a8c3c8b4cfb00e5a809f", "snapshot_path": "sources/cf979f5392b9da229f911f3453fde981c9dec4d77a89a8c3c8b4cfb00e5a809f.txt", "url": "https://api.github.com/repos/jgraph/drawio/license"}, {"fetched_at": "2026-10-24T12:31:26.162265+08:00", "kind": "readme", "sha256": "749486eaa18f4569a45add47b4d1feae09df45044291eec2ce67f0506ef41c51", "snapshot_path": "sources/749486eaa18f4569a45add47b4d1feae09df45044291eec2ce67f0506ef41c51.txt", "url": "https://raw.githubusercontent.com/jgraph/drawio/dev/README.md"}, {"fetched_at": "2026-10-24T12:28:54.460581+08:00", "kind": "documentation", "sha256": "f2f85a3ec55cd0369af634d3d2a5c927136566fc142b21441516d42706f2460d", "snapshot_path": "sources/f2f85a3ec55cd0369af634d3d2a5c927136566fc142b21441516d42706f2460d.txt", "url": "https://www.drawio.com/docs/features/"}, {"fetched_at": "2026-10-24T12:43:10.761111+08:00", "kind": "documentation", "sha256": "4f909d97a43a4dc84ff6f4f8da73730fedb5b5e0f470c7223a2b997acaa22293", "snapshot_path": "sources/4f909d97a43a4dc84ff6f4f8da73730fedb5b5e0f470c7223a2b997acaa22293.txt", "url": "https://www.drawio.com/docs/manual/"}, {"fetched_at": "2026-10-24T12:35:16.306031+08:00", "kind": "homepage", "sha256": "99c7989ff2131537098e9163353ab6f55394bf3ef917a3febda0d03962245945", "snapshot_path": "sources/99c7989ff2131537098e9163353ab6f55394bf3ef917a3febda0d03962245945.txt", "url": "https://www.drawio.com/"}, {"fetched_at": "2026-10-28T09:27:10.162615+08:00", "kind": "documentation", "sha256": "267ed993ea06fad9f884c0f1504f37f92584404b3e73ca52d0b65e1c6b96ebf0", "snapshot_path": "sources/267ed993ea06fad9f884c0f1504f37f92584404b3e73ca52d0b65e1c6b96ebf0.txt", "url": "https://www.drawio.com/docs/security/diagrams-docker-app/"}], "summary": "Apache-2.0 开源图表应用：从形状库拖放语义形状、用固定/浮动连接线建模关系，支持多页文档、图层与多格式导出；官方提供可自托管的 Docker 图表服务器及在线/桌面编辑器，图表文件存于用户自选位置。", "technology_stack": ["JavaScript", "客户端编辑器", "Tomcat/Docker 自托管服务镜像", "Apache-2.0 源码（README 与仓库元数据）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:2057515','Tracks','{"deployment": ["自托管 Web 应用：自带 webserver，可在安装 Ruby 的 macOS、Windows、Linux 上运行", "官方推荐用 Docker 安装，另提供源码安装与升级说明", "提供移动端轻量 Web 界面与 API；社区另有 hosted 实例列表，非本条收录依据"], "features": ["action 是基本待办条目，存放在 context 与 project 中，主页按 context 汇总，也可只看单个 context 或 project", "action 可设可选到期日，日期以红/橙/绿背景表示逾期、临近或较远", "tickler 把 action 安排到未来日期后重新出现在首页，用于先记下暂不处理的事项", "完成项保留：主页可配置显示若干已完成项，completed 页可查看全部已完成 action", "project 可标记为 active、hidden 或 completed；context 与 project 可拖拽排序", "支持标签、星标、Ajax 快速添加、多用户各自独立的 context/project、iCal/RSS 订阅与数据导出"], "github_repository_id": 2057515, "homepage": "https://www.getontracks.org/", "id": "github:2057515", "leaf_matches": [{"reason": "官方首页正文以 action 为待办条目：主页按 context 汇总显示全部 action，也可切换为只看某个 context 或某个 project，context 与 project 是条目归属并可在主页拖拽排序，对应“有名称的容器作为主要工作表面”。完成是可检索的一等状态：正文写 “You can show a configurable number of completed items at the bottom of the main page, but you can see all your completed items on the completed page”；project 也可标记为 completed。紧急度由条目自身日期派生而非工作流阶段：到期日可选，今日或逾期显示红色、明天深橙、7 天内橙色、其余绿色；tickler 只把条目延迟到未来日期重新出现在首页。首页同时写明 “Tracks is Open Source, free and licensed under the GNU GPL”，GitHub 仓库元数据 id 2057515 与许可证 API 的 GPL-2.0 相互印证；首页 GPL 徽章指向 creativecommons.org 链接，故许可只以 COPYING 与 license API 为依据。边界：产品自述按 GTD 方法组织，另含统计、feeds 与多用户（每个用户各自独立的 context/project，无组织角色或审批层级）；本条只据容器归属、可检索完成与派生紧急度建立关系，GTD 框架与统计不计入证据。完成项能否取消勾选在该快照中无正文，故不作可逆完成的断言。", "slug": "to-do-list-application", "source_urls": ["https://www.getontracks.org/", "https://raw.githubusercontent.com/TracksApp/tracks/master/README.md", "https://api.github.com/repos/TracksApp/tracks", "https://api.github.com/repos/TracksApp/tracks/license"]}], "license": "GPL-2.0", "license_evidence_url": "https://api.github.com/repos/TracksApp/tracks/license", "name": "Tracks", "repository_url": "https://github.com/TracksApp/tracks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:32:14.165842+08:00", "kind": "repository_metadata", "sha256": "a46fcfe269fedb61c3153b0aaef92bc660b4d592057b6db0b174d97335576457", "snapshot_path": "sources/a46fcfe269fedb61c3153b0aaef92bc660b4d592057b6db0b174d97335576457.txt", "url": "https://api.github.com/repos/TracksApp/tracks"}, {"fetched_at": "2026-10-28T09:32:15.953429+08:00", "kind": "license", "sha256": "0b04029057e737e2df265510593d907c5d3e8139649418663d461af710bba117", "snapshot_path": "sources/0b04029057e737e2df265510593d907c5d3e8139649418663d461af710bba117.txt", "url": "https://api.github.com/repos/TracksApp/tracks/license"}, {"fetched_at": "2026-10-28T09:32:24.023561+08:00", "kind": "readme", "sha256": "302bbdbfbc8e9e1a3fe7867a0fc794d00a009fba43d68679f6ae17763d898d33", "snapshot_path": "sources/302bbdbfbc8e9e1a3fe7867a0fc794d00a009fba43d68679f6ae17763d898d33.txt", "url": "https://raw.githubusercontent.com/TracksApp/tracks/master/README.md"}, {"fetched_at": "2026-10-28T09:34:15.961520+08:00", "kind": "homepage", "sha256": "95020e1b2ed797ede1af5a7a52c77e0a2bef854cd98bc6204a975977a079dfe9", "snapshot_path": "sources/95020e1b2ed797ede1af5a7a52c77e0a2bef854cd98bc6204a975977a079dfe9.txt", "url": "https://www.getontracks.org/"}], "summary": "GPLv2 开源、可自托管的 Web 待办应用：action（待办条目）存放在 context 与 project 中，主页按 context 汇总展示；action 可设可选到期日并按今日/逾期/临近变色，tickler 让条目在未来日期重新出现，完成项保留在主页底部与 completed 页。", "technology_stack": ["Ruby", "Ruby on Rails", "SQLite/MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:32413820','4Minitz','{"deployment": ["Docker / Docker Compose 自托管", "Meteor 应用源码本地部署（Linux/macOS）", "自有服务器部署"], "features": ["按会议系列创建议程与会议纪要，议题下可挂行动项与信息项", "行动项记录 WHO-WHAT-WHEN：事项、责任人（含外部邮箱）与截止日期", "行动项背景色按截止日期区分正常、今日到期、已逾期与已关闭", "勾选 done 关闭行动项；未完成项随父议题自动结转到下次会议", "My Action Items 汇总本人负责且未关闭的行动项，按截止日期排序", "可按 is:action/is:open/is:closed 过滤并回溯行动项所属议题", "最终确定纪要时以邮件把行动项单独发送给责任人"], "github_repository_id": 32413820, "homepage": "https://www.4minitz.com", "id": "github:32413820", "leaf_matches": [{"reason": "官方用户手册与 FAQ 以行动项为持久记录并挂靠议题：每个行动项有责任人（可填外部邮箱）、截止日期和 done 状态；背景色按截止日期区分正常/今日到期/已逾期/已关闭；未完成项随父议题自动结转到下次会议，My Action Items 汇总本人负责的未关闭项并按截止日期排序，可回溯所属议题——覆盖负责人、日期、开放到完成与会议来源四项定义核心，形态为自托管完整 Web 应用。", "slug": "meeting-action-item-management", "source_urls": ["https://raw.githubusercontent.com/4minitz/4minitz/develop/doc/user/usermanual.md", "https://raw.githubusercontent.com/4minitz/4minitz/develop/doc/faq.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/4minitz/4minitz/license", "name": "4Minitz", "repository_url": "https://github.com/4minitz/4minitz", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:34:31.777497+08:00", "kind": "repository_metadata", "sha256": "962382672b63042c08e6191aae285072ca2301b8da63294aea89601c60e49230", "snapshot_path": "sources/962382672b63042c08e6191aae285072ca2301b8da63294aea89601c60e49230.txt", "url": "https://api.github.com/repos/4minitz/4minitz"}, {"fetched_at": "2026-10-28T09:34:33.278817+08:00", "kind": "license", "sha256": "1a387167cc4496b723a888e62e748b4ef5960819b244abae280d2eff84f6ec55", "snapshot_path": "sources/1a387167cc4496b723a888e62e748b4ef5960819b244abae280d2eff84f6ec55.txt", "url": "https://api.github.com/repos/4minitz/4minitz/license"}, {"fetched_at": "2026-10-28T09:35:30.252814+08:00", "kind": "readme", "sha256": "821c586edd0da95bda611014ffac78e088c29ae9e257e579bd021b9f21ca3350", "snapshot_path": "sources/821c586edd0da95bda611014ffac78e088c29ae9e257e579bd021b9f21ca3350.txt", "url": "https://raw.githubusercontent.com/4minitz/4minitz/develop/README.md"}, {"fetched_at": "2026-10-28T09:34:47.567127+08:00", "kind": "documentation", "sha256": "a2c4b94101859237e715c17ecd139df4132bb66c06fca682250dece3671013ab", "snapshot_path": "sources/a2c4b94101859237e715c17ecd139df4132bb66c06fca682250dece3671013ab.txt", "url": "https://raw.githubusercontent.com/4minitz/4minitz/develop/doc/user/usermanual.md"}, {"fetched_at": "2026-10-28T09:34:49.095446+08:00", "kind": "documentation", "sha256": "8f8e5af6a054f476c8ab10adceff5227aaa0d6a00389c4ae995c134522c806ef", "snapshot_path": "sources/8f8e5af6a054f476c8ab10adceff5227aaa0d6a00389c4ae995c134522c806ef.txt", "url": "https://raw.githubusercontent.com/4minitz/4minitz/develop/doc/faq.md"}, {"fetched_at": "2026-10-28T09:37:28.206893+08:00", "kind": "documentation", "sha256": "4c2b79fdf1d506c65a5d376c4be83c340f1836a60c2c2b5abc364a26dfa19c11", "snapshot_path": "sources/4c2b79fdf1d506c65a5d376c4be83c340f1836a60c2c2b5abc364a26dfa19c11.txt", "url": "https://raw.githubusercontent.com/4minitz/4minitz/develop/doc/admin/adminguide.md"}], "summary": "自托管的开源会议纪要 Web 应用，按会议系列维护议程与纪要，并把行动项作为持久记录跟踪：记录责任人、截止日期与完成状态，未完成项自动结转到下次会议，逾期按颜色提示，并可在“My Action Items”中汇总查看本人负责事项。", "technology_stack": ["Meteor", "Node.js", "MongoDB", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:343078060','Dashy','{"deployment": ["官方 Docker 镜像 lissy93/dashy（Docker Hub 与 GHCR，多架构），提供 compose 示例", "Node.js 源码构建运行（yarn build / yarn start）"], "features": ["多个页面、分区与条目由用户自行编排，支持界面内编辑模式", "小组件展示天气、日历、RSS、行情、加密资产、新闻、服务状态等动态内容", "可为小部件设置 updateInterval 开启连续自动更新", "支持自定义小部件、主题、图标包与多语言界面"], "github_repository_id": 343078060, "homepage": "https://dashy.to", "id": "github:343078060", "leaf_matches": [{"reason": "仓库元数据自述为“A self-hostable personal dashboard built for you.”；README 说明用户在自己的实例上以多页面、分区与条目组合常驻界面（含界面内编辑模式），并以小组件展示天气、日历、RSS、行情等个人关心的动态内容；docs/widgets.md 的 Continuous Updates 明示设置 updateInterval 后小部件可“keep data updated at all times”，即组合面由用户组装、小组件为独立单元且支持自动刷新，符合个人数据基底、组合界面、小组件单元与一目了然的时效性四项。许可证接口证实 MIT 与仓库身份。", "slug": "personal-dashboard", "source_urls": ["https://api.github.com/repos/lissy93/dashy", "https://raw.githubusercontent.com/lissy93/dashy/master/README.md", "https://api.github.com/repos/lissy93/dashy/license", "https://raw.githubusercontent.com/lissy93/dashy/master/docs/widgets.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/lissy93/dashy/license", "name": "Dashy", "repository_url": "https://github.com/lissy93/dashy", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:40:39.795381+08:00", "kind": "repository_metadata", "sha256": "54078cc51f8d18c0e174bca82f5b799dd4547a297b95bf00a9381fc764cbe98b", "snapshot_path": "sources/54078cc51f8d18c0e174bca82f5b799dd4547a297b95bf00a9381fc764cbe98b.txt", "url": "https://api.github.com/repos/lissy93/dashy"}, {"fetched_at": "2026-10-28T09:40:47.037592+08:00", "kind": "readme", "sha256": "4ca539aa6d0d09bf2f4916f86412488f92797ce554470585aabf4e09b667da43", "snapshot_path": "sources/4ca539aa6d0d09bf2f4916f86412488f92797ce554470585aabf4e09b667da43.txt", "url": "https://raw.githubusercontent.com/lissy93/dashy/master/README.md"}, {"fetched_at": "2026-10-28T09:40:39.636406+08:00", "kind": "license", "sha256": "b0406343af33a2b3555aa5ea58d9685485e06d324423e5c910b3abf423171ddd", "snapshot_path": "sources/b0406343af33a2b3555aa5ea58d9685485e06d324423e5c910b3abf423171ddd.txt", "url": "https://api.github.com/repos/lissy93/dashy/license"}, {"fetched_at": "2026-10-28T09:40:58.580687+08:00", "kind": "documentation", "sha256": "2cc50787e83adf768176c30caa0866e4599219bf2f08e416b8513c08e7509fb6", "snapshot_path": "sources/2cc50787e83adf768176c30caa0866e4599219bf2f08e416b8513c08e7509fb6.txt", "url": "https://raw.githubusercontent.com/lissy93/dashy/master/docs/widgets.md"}], "summary": "Dashy 是自托管的个人仪表盘/起始页：用 YAML 或页面内编辑把多个页面、分区与小组件组合成个人常驻主页，展示天气、日历、RSS、行情、服务状态等动态内容，并可对小部件开启连续自动更新。", "technology_stack": ["Vue", "Node.js", "YAML 配置", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:57224308','ActivityWatch','{"deployment": ["本地运行 aw-qt 托盘程序，自动启动 aw-server 与默认 watcher", "Web 界面默认运行于 http://localhost:5600", "提供 Windows/macOS/Linux 安装包与 Android 客户端"], "features": ["自动记录前台应用、窗口标题与浏览器标签 URL", "通过键鼠活动判断离开状态（AFK）", "事件持久化存储为 buckets/events，可在时间线与原始数据视图中浏览", "用户自定义类别层级与基于窗口标题/应用名的正则分类规则", "可在托盘菜单暂停指定 watcher 模块的记录", "通过 Web 界面或 REST API 导出 JSON 数据"], "github_repository_id": 57224308, "homepage": "https://activitywatch.net/", "id": "github:57224308", "leaf_matches": [{"reason": "自动捕获：README 写明 watcher 记录当前活动应用及窗口标题、当前浏览器标签及 URL，并以键鼠活动判断 AFK；官网亦说明开箱追踪活动应用与窗口标题。持久记录：README 说明 aw-server 提供 buckets/events/heartbeat REST 数据存储、Web UI 的 Dashboard/Timeline 与原始事件浏览，并支持 JSON 导出。生产力解读：分类文档说明类别以 Work、Gaming、Social Media 等标题聚合事件，具备父子层级与匹配窗口标题/应用名的正则规则，并在 Activity 视图形成分类可视化，且用户可在 Settings 增改类别。应用形态补证：getting-started 文档说明安装后由 aw-qt 托盘程序自动启动 server 与默认 watcher，Web 界面运行在 http://localhost:5600，可在 Activity 视图查看数据，证明其是可日常使用的完整本地应用，而非仅客户端、CLI 或引擎。边界：remote-server 文档明确不支持且不建议将远程 server 用于员工监控，符合个人本地使用而非组织监控的定位。未把生产力评分或已标为 planned 的数据过滤写成现有能力；定义允许仅分类不评分的实现。", "slug": "productivity-activity-tracker", "source_urls": ["https://api.github.com/repos/ActivityWatch/activitywatch", "https://raw.githubusercontent.com/ActivityWatch/activitywatch/master/README.md", "https://api.github.com/repos/ActivityWatch/activitywatch/license", "https://docs.activitywatch.net/en/latest/features/categorization.html", "https://docs.activitywatch.net/en/latest/features.html", "https://docs.activitywatch.net/en/latest/features/user-interface.html", "https://activitywatch.net/", "https://docs.activitywatch.net/en/latest/getting-started.html", "https://docs.activitywatch.net/en/latest/features/pausing-logging.html", "https://docs.activitywatch.net/en/latest/features/filtering-data.html", "https://docs.activitywatch.net/en/latest/remote-server.html"]}], "license": "MPL-2.0", "license_evidence_url": "https://api.github.com/repos/ActivityWatch/activitywatch/license", "name": "ActivityWatch", "repository_url": "https://github.com/ActivityWatch/activitywatch", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:49:52.556695+08:00", "kind": "repository_metadata", "sha256": "f6bea1aeeeab64057217bb8d8112c94d7f2a49bbbe321c0176b185e779dbb234", "snapshot_path": "sources/f6bea1aeeeab64057217bb8d8112c94d7f2a49bbbe321c0176b185e779dbb234.txt", "url": "https://api.github.com/repos/ActivityWatch/activitywatch"}, {"fetched_at": "2026-10-24T11:53:37.702044+08:00", "kind": "readme", "sha256": "4afdc26bd31ea4e2b516ed4eae6c4f645759dac2d3cca43fd5f99e35b1d94702", "snapshot_path": "sources/4afdc26bd31ea4e2b516ed4eae6c4f645759dac2d3cca43fd5f99e35b1d94702.txt", "url": "https://raw.githubusercontent.com/ActivityWatch/activitywatch/master/README.md"}, {"fetched_at": "2026-10-24T11:49:54.295347+08:00", "kind": "license", "sha256": "6a28a42e95054d2dec4afdfc214c561127a76cdfe79477c5c2b0496a2f705727", "snapshot_path": "sources/6a28a42e95054d2dec4afdfc214c561127a76cdfe79477c5c2b0496a2f705727.txt", "url": "https://api.github.com/repos/ActivityWatch/activitywatch/license"}, {"fetched_at": "2026-10-24T12:09:10.817721+08:00", "kind": "documentation", "sha256": "5b4fe69d1e9319b17cfc100a6a62ec855224461c6c6b5ce0c09f6273dd21445a", "snapshot_path": "sources/5b4fe69d1e9319b17cfc100a6a62ec855224461c6c6b5ce0c09f6273dd21445a.txt", "url": "https://docs.activitywatch.net/en/latest/features/categorization.html"}, {"fetched_at": "2026-10-24T12:05:34.560450+08:00", "kind": "documentation", "sha256": "196741af70976d72c2824c67eac88918bf297982abd9401fd26b56e9510e7cc9", "snapshot_path": "sources/196741af70976d72c2824c67eac88918bf297982abd9401fd26b56e9510e7cc9.txt", "url": "https://docs.activitywatch.net/en/latest/features.html"}, {"fetched_at": "2026-10-24T12:12:53.358911+08:00", "kind": "documentation", "sha256": "78b47fa141c752ada73a70206af152817ce62102e99b1d54765a60f59d15283f", "snapshot_path": "sources/78b47fa141c752ada73a70206af152817ce62102e99b1d54765a60f59d15283f.txt", "url": "https://docs.activitywatch.net/en/latest/features/user-interface.html"}, {"fetched_at": "2026-10-24T12:11:48.542685+08:00", "kind": "homepage", "sha256": "7fa57fa81941869fe320147413b21121524f5841cf6cec7ba71742984666c570", "snapshot_path": "sources/7fa57fa81941869fe320147413b21121524f5841cf6cec7ba71742984666c570.txt", "url": "https://activitywatch.net/"}, {"fetched_at": "2026-10-28T09:47:46.584897+08:00", "kind": "documentation", "sha256": "6c9c577c043178de5321745d3470fbd5b4b0cc0e9b85f462c7fe07fdf300104f", "snapshot_path": "sources/6c9c577c043178de5321745d3470fbd5b4b0cc0e9b85f462c7fe07fdf300104f.txt", "url": "https://docs.activitywatch.net/en/latest/getting-started.html"}, {"fetched_at": "2026-10-28T09:49:53.895437+08:00", "kind": "documentation", "sha256": "c8f45b9a85655fabf77aa4157daf82497e4c43a48ead1674e695acac7784eb1f", "snapshot_path": "sources/c8f45b9a85655fabf77aa4157daf82497e4c43a48ead1674e695acac7784eb1f.txt", "url": "https://docs.activitywatch.net/en/latest/features/pausing-logging.html"}, {"fetched_at": "2026-10-28T09:49:53.538018+08:00", "kind": "documentation", "sha256": "4e8f57444f03b7608544a675369b34c22133a1951b136e9d03cf607f03b63138", "snapshot_path": "sources/4e8f57444f03b7608544a675369b34c22133a1951b136e9d03cf607f03b63138.txt", "url": "https://docs.activitywatch.net/en/latest/features/filtering-data.html"}, {"fetched_at": "2026-10-28T09:50:42.701393+08:00", "kind": "documentation", "sha256": "2244c9f7275751c52cc00d60266d890d00c6b41dd889a4bd600b2be1a3e5a029", "snapshot_path": "sources/2244c9f7275751c52cc00d60266d890d00c6b41dd889a4bd600b2be1a3e5a029.txt", "url": "https://docs.activitywatch.net/en/latest/remote-server.html"}], "summary": "ActivityWatch 是本地优先的开源自动时间追踪应用：托盘程序启动本地 server 与 watcher，持续记录前台应用、窗口标题与浏览器标签，在本地 Web 界面形成时间线与分类汇总，用可编辑的类别规则把时间解读为工作/娱乐等用途。", "technology_stack": ["Python", "Rust", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:258967860','Graphite','{"deployment": ["网页版 editor.graphite.art 直接使用（当前 alpha）"], "features": ["Document panel 提供画布视口，每个打开的文档文件一个标签页，未保存改动以文件名后的 * 标识", "Vector 工具用于绘制和编辑矢量形状、路径与文本，File > Import… 可置入位图图像层或 SVG 内容", "画布上组合矢量元素与实验性光栅元素，并通过图层堆叠顺序、分组、对齐与布尔运算组织构图", "图层与节点混合的非破坏编辑，路径可用 Make Path Editable 在其他非破坏操作之后保持可直接编辑", "File 菜单 New… 新建画布/artboard，Open… 选择 .graphite 文件重新打开，Save 将 .graphite 写出到磁盘", "Export… 输出 PNG、JPG 或 SVG，可选缩放比例，以及按全部作品、选区或 artboard 决定导出范围", "文档以数据保存、按当前分辨率重绘，可缩放视口并在任意尺寸导出", "当前 alpha 提供网页版编辑器入口"], "github_repository_id": 258967860, "homepage": "https://graphite.art", "id": "github:258967860", "leaf_matches": [{"reason": "官方正文四点齐备。①画布构图：Document panel 是显示与编辑作品的主内容区，视口为画布的交互式视觉编辑，工具架含 general/vector/raster 工具，Layers 面板组织 artboard 与图层，Layer 菜单提供 Group、Raise/Lower 堆叠顺序、Align、Flip、Boolean。②可编辑对象状态：文档按文件打开，每个文档一个标签页、未保存改动以 * 标识，File > Save 将 .graphite 写到磁盘、Open… 重新打开 .graphite，Make Path Editable 使路径在其他非破坏操作后仍可直接用 Path/Pen 工具修改；features 页称图层与节点是同一文档结构的两个等价视图，作品以数据而非像素保存并按当前视角分辨率重绘。③用户创作、编辑为先：features 页称「The current alpha version of Graphite is a tool for vector art and graphic design」，手册称矢量编辑是当前核心能力、由使用者绘制与调整参数，非模板浏览、非 AI 生成。④成品输出：File > Export… 可存为 PNG/JPG/SVG，带 Scale Factor 与按全部作品、选区或 artboard 的导出范围。部署仅为网页版 editor.graphite.art（README available now 与功能页 Launch 均指向该入口）；PWA 离线安装与桌面 1.0 在 features 页均列为 roadmap 计划项，不记作现有部署。仓库身份已核（id 258967860 / full_name GraphiteEditor/Graphite）；README 的 License 节说明源代码按 MIT 或 Apache-2.0 双许可（at your option, unless otherwise noted within the repository），LICENSE-MIT 与 LICENSE-APACHE 全文均核对。因共享验证器只接受单一 OSI SPDX 标识，license 按 GitHub license API 的仓库分类记录 Apache-2.0 分支，MIT 分支全文与双许可范围保留在摘要、license_review 与来源中，不将单值解释为唯一选项。alpha 状态与有限实验性光栅能力在摘要中如实保留。", "slug": "graphic-design-application", "source_urls": ["https://api.github.com/repos/GraphiteEditor/Graphite", "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/README.md", "https://api.github.com/repos/GraphiteEditor/Graphite/license", "https://graphite.art/features/", "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-MIT", "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-APACHE", "https://graphite.art/learn/", "https://graphite.art/learn/introduction/features-and-limitations/", "https://graphite.art/learn/interface/document-panel/", "https://graphite.art/learn/interface/menu-bar/"]}], "license": "Apache-2.0", "license_evidence_url": "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-APACHE", "license_review": {"rationale": "README 的 License 节明确写源代码按 MIT 或 Apache-2.0 双许可（your choice of either the MIT license or the Apache License 2.0, at your option, unless otherwise noted within the repository），并同时链接 LICENSE-MIT 与 LICENSE-APACHE，两份全文均已保存核对。共享验证器的 license 字段只接受单一 OSI SPDX 标识，故按 GitHub license API 对该仓库的分类记录 Apache-2.0，并以 LICENSE-APACHE 全文作为该分支的完整许可证证据；MIT 分支的 LICENSE-MIT 全文同样保留在本条目来源中。双许可事实与“除非仓库内另有说明”的范围已在 summary 与 leaf_match 说明，不把 Apache-2.0 单值解释为仓库仅有 Apache 选项。", "reviewer": "source_research", "scope": "repository", "source_url": "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-APACHE", "spdx_id": "Apache-2.0"}, "name": "Graphite", "repository_url": "https://github.com/GraphiteEditor/Graphite", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:47:21.539609+08:00", "kind": "repository_metadata", "sha256": "c953ea4ae4ec7a6dc265f7512d29c4df3baedcda879e5ac01b389b87b6ec0bfa", "snapshot_path": "sources/c953ea4ae4ec7a6dc265f7512d29c4df3baedcda879e5ac01b389b87b6ec0bfa.txt", "url": "https://api.github.com/repos/GraphiteEditor/Graphite"}, {"fetched_at": "2026-10-24T11:53:16.615685+08:00", "kind": "readme", "sha256": "40e1f3b0468bd88205958ea44dd888c69efcf9716e388c5d01a8d576715ce53d", "snapshot_path": "sources/40e1f3b0468bd88205958ea44dd888c69efcf9716e388c5d01a8d576715ce53d.txt", "url": "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/README.md"}, {"fetched_at": "2026-10-24T11:47:22.971371+08:00", "kind": "license", "sha256": "53f89374be184baab5e3a7f841ab6de0497678e8bb76bb6ae97c4fa8c07c3ad1", "snapshot_path": "sources/53f89374be184baab5e3a7f841ab6de0497678e8bb76bb6ae97c4fa8c07c3ad1.txt", "url": "https://api.github.com/repos/GraphiteEditor/Graphite/license"}, {"fetched_at": "2026-10-24T12:09:14.554403+08:00", "kind": "documentation", "sha256": "df13dd09e53168ed1b18cab81798495105333960e557aa200dcf793a3fdd2872", "snapshot_path": "sources/df13dd09e53168ed1b18cab81798495105333960e557aa200dcf793a3fdd2872.txt", "url": "https://graphite.art/features/"}, {"fetched_at": "2026-10-25T23:04:53.349700+08:00", "kind": "license", "sha256": "4949989af51b07086e4ec4bfdaa843a4cd35cda7495f77747b3d9a45cb8b4ca3", "snapshot_path": "sources/4949989af51b07086e4ec4bfdaa843a4cd35cda7495f77747b3d9a45cb8b4ca3.txt", "url": "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-MIT"}, {"fetched_at": "2026-10-25T23:04:54.212962+08:00", "kind": "license", "sha256": "c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4", "snapshot_path": "sources/c71d239df91726fc519c6eb72d318ec65820627232b2f796219e87dcf35d0ab4.txt", "url": "https://raw.githubusercontent.com/GraphiteEditor/Graphite/master/LICENSE-APACHE"}, {"fetched_at": "2026-10-28T09:48:52.808529+08:00", "kind": "documentation", "sha256": "7cee6e96ec0159ea868fb937aaafc8633da5d34d7d35c302ab0c180c64c4abdd", "snapshot_path": "sources/7cee6e96ec0159ea868fb937aaafc8633da5d34d7d35c302ab0c180c64c4abdd.txt", "url": "https://graphite.art/learn/"}, {"fetched_at": "2026-10-28T09:49:11.493331+08:00", "kind": "documentation", "sha256": "f8a19bade7f0b1e77662806109e830467fd91bdba607e53e860200cb209f0766", "snapshot_path": "sources/f8a19bade7f0b1e77662806109e830467fd91bdba607e53e860200cb209f0766.txt", "url": "https://graphite.art/learn/introduction/features-and-limitations/"}, {"fetched_at": "2026-10-28T09:49:11.504414+08:00", "kind": "documentation", "sha256": "e15f9de0536fb86e25c34055f14c8f8278a0aed3b7f6009243343ec29838f4e6", "snapshot_path": "sources/e15f9de0536fb86e25c34055f14c8f8278a0aed3b7f6009243343ec29838f4e6.txt", "url": "https://graphite.art/learn/interface/document-panel/"}, {"fetched_at": "2026-10-28T09:49:31.217587+08:00", "kind": "documentation", "sha256": "2671938f34c8d9c7d1b64c54a1bae710e089bd18cd752c674d291926ba0c336f", "snapshot_path": "sources/2671938f34c8d9c7d1b64c54a1bae710e089bd18cd752c674d291926ba0c336f.txt", "url": "https://graphite.art/learn/interface/menu-bar/"}], "summary": "Graphite 是开源（源代码按 MIT 或 Apache-2.0 双许可，除非仓库内另有说明）矢量与光栅图形设计应用（当前 alpha，光栅编辑为有限实验能力）：在画布上组合形状、文本与图像，以图层加节点的方式保持对象非破坏可编辑，文档保存为可重新打开的 .graphite 文件，并导出 PNG/JPG/SVG 成品。", "technology_stack": ["Rust"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16602433','JS Paint','{"deployment": ["浏览器直接使用的完整 Web 应用（jspaint.app）；README 说明可用普通 Web 服务器自行部署，无需编译"], "features": ["复刻 MS Paint 的工具箱与画布，含画笔、自定义笔刷与橡皮", "无限撤销/重做与非线性历史树", "支持 PNG、BMP 等位图格式的打开与保存", "可作为 Web 应用部署，另有 PWA 与 Electron 桌面分发"], "github_repository_id": 16602433, "homepage": "https://jspaint.app", "id": "github:16602433", "leaf_matches": [{"reason": "README 自述为“pixel-perfect web-based MS Paint remake”，复刻 MS Paint 的全部工具与菜单，含画笔、自定义笔刷（Brush Scaling/Custom Brushes）与橡皮，工作对象是浏览器中的 canvas 像素画布；文件格式表证明可将 PNG/BMP 等位图打开并保存。jspaint.app 是在线完整 Web 应用入口，README 明确可用普通 Web 服务器部署且无需编译，属于持续可用的浏览器应用服务，而非仅桌面客户端或组件。", "slug": "digital-painting-application", "source_urls": ["https://raw.githubusercontent.com/1j01/jspaint/master/README.md", "https://api.github.com/repos/1j01/jspaint", "https://jspaint.app/", "https://jspaint.app/about"]}, {"reason": "README 说明 JS Paint 是 MS Paint 的浏览器复刻，重建其每个工具与菜单，正文列出画笔、填充、橡皮、选区、缩放画布与透明像素编辑，并给出 File > Save / Save As 及 PNG、BMP、TIFF 等格式的读写支持表；官方 About 页亦称其 runs in the browser、可 open and save files。像素网格直接编辑、可缩放可视画布与保存为图像均有官方正文覆盖，且产品为完整浏览器端应用而非桌面/CLI 组件。GitHub 许可证接口返回 MIT，仓库身份与 id 由元数据证明。", "slug": "raster-image-editor", "source_urls": ["https://api.github.com/repos/1j01/jspaint", "https://raw.githubusercontent.com/1j01/jspaint/master/README.md", "https://api.github.com/repos/1j01/jspaint/license", "https://jspaint.app/about"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/1j01/jspaint/license", "name": "JS Paint", "repository_url": "https://github.com/1j01/jspaint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:59:54.466443+08:00", "kind": "repository_metadata", "sha256": "e8c0c248f690610c561d0d46abe7362e47ae437b2984d6c5204e98e1faeeaa47", "snapshot_path": "sources/e8c0c248f690610c561d0d46abe7362e47ae437b2984d6c5204e98e1faeeaa47.txt", "url": "https://api.github.com/repos/1j01/jspaint"}, {"fetched_at": "2026-10-28T09:59:54.572155+08:00", "kind": "readme", "sha256": "664aae98b7ae2bca0ba0660591d7d41bc5555e19f1bbc79f6c7b0481b625f67b", "snapshot_path": "sources/664aae98b7ae2bca0ba0660591d7d41bc5555e19f1bbc79f6c7b0481b625f67b.txt", "url": "https://raw.githubusercontent.com/1j01/jspaint/master/README.md"}, {"fetched_at": "2026-10-28T10:00:12.764650+08:00", "kind": "license", "sha256": "f10898f0e31b96ef2dae866d9199e447319310aa3ddd27b2fe1632934e708274", "snapshot_path": "sources/f10898f0e31b96ef2dae866d9199e447319310aa3ddd27b2fe1632934e708274.txt", "url": "https://api.github.com/repos/1j01/jspaint/license"}, {"fetched_at": "2026-10-28T10:00:11.991590+08:00", "kind": "homepage", "sha256": "7eb622da9f6c3580bbeb4e1bc287bf6b57763b0fb3b7d121c9bab1a671d6dd15", "snapshot_path": "sources/7eb622da9f6c3580bbeb4e1bc287bf6b57763b0fb3b7d121c9bab1a671d6dd15.txt", "url": "https://jspaint.app/"}, {"fetched_at": "2026-10-28T10:01:05.635744+08:00", "kind": "documentation", "sha256": "6ddd39f63178356df2c8adda8ef3e88359da05476e7beab27b7e3c0cdf8df685", "snapshot_path": "sources/6ddd39f63178356df2c8adda8ef3e88359da05476e7beab27b7e3c0cdf8df685.txt", "url": "https://jspaint.app/about"}], "summary": "JS Paint 是开源 Web 版 MS Paint 复刻：在浏览器中从空白位图画布出发，用画笔、自定义笔刷与橡皮等工具绘制，并可打开或保存 PNG/BMP 等图像文件。", "technology_stack": ["JavaScript", "HTML5 Canvas", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:5516383','Piskel','{"deployment": ["官方在线版托管于 piskelapp.com，无需安装即可使用", "提供 Windows、macOS、Linux 离线/桌面构建", "提供面向儿童与教育工作者的无广告 Piskel For Kids 版本"], "features": ["浏览器内直接创建与编辑像素精灵、动画和瓦片", "实时预览动画并即时调整帧延迟", "导出动画 GIF、PNG 与精灵表 ZIP", "定期保存工作并可从 Import 面板恢复上次会话"], "github_repository_id": 5516383, "homepage": "https://www.piskelapp.com", "id": "github:5516383", "leaf_matches": [{"reason": "官方主页称其为“free online editor for animated sprites & pixel art”，在浏览器内设计角色、动画与瓦片，提供实时预览与帧延迟调节，并导出 GIF、PNG 与精灵表 ZIP；FAQ 说明 Piskel 专为制作小型精灵而设计，且会定期保存并可恢复上次会话。README 与仓库元数据将其定位为 sprite/pixel-art 编辑器，并明确它就是 piskelapp.com 所用编辑器，属持续运营的在线编辑服务而非仅客户端分发。受限像素画布、逐像素创作与标准图像/动画导出三项均有官方正文；仓库身份 5516383 与完整 Apache-2.0 正文由元数据与许可证接口证明。", "slug": "pixel-art-editor", "source_urls": ["https://api.github.com/repos/piskelapp/piskel", "https://raw.githubusercontent.com/piskelapp/piskel/master/README.md", "https://api.github.com/repos/piskelapp/piskel/license", "https://www.piskelapp.com/"]}, {"reason": "官网首页声明这是浏览器内运行、可实时预览并导出 GIF/PNG 的像素动画编辑器；编辑器页面正文给出帧列表、FPS 滑杆、洋葱皮开关与动画预览区，导出面板写明可导出动画 GIF、含全部帧的 PNG 精灵表、每帧一张 PNG 的 ZIP，以及单帧 PNG；README 说明编辑器用于制作精灵与像素动画并由 JS/HTML/CSS 构成。逐帧内容、以帧率播放、预览回放与图像序列交付四项定义核心均有正文覆盖。", "slug": "2d-animation-application", "source_urls": ["https://www.piskelapp.com/", "https://www.piskelapp.com/p/create/sprite/", "https://raw.githubusercontent.com/piskelapp/piskel/master/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/piskelapp/piskel/license", "name": "Piskel", "repository_url": "https://github.com/piskelapp/piskel", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T09:58:55.564185+08:00", "kind": "repository_metadata", "sha256": "ca67146156af75b62f0acd81ecadf711e2646d65c4de06c6774979a3d0b99917", "snapshot_path": "sources/ca67146156af75b62f0acd81ecadf711e2646d65c4de06c6774979a3d0b99917.txt", "url": "https://api.github.com/repos/piskelapp/piskel"}, {"fetched_at": "2026-10-28T09:58:55.355555+08:00", "kind": "readme", "sha256": "ba18ce36ba4190d45a12ad25308191661ffa007b33047de5a092dfb9779bf484", "snapshot_path": "sources/ba18ce36ba4190d45a12ad25308191661ffa007b33047de5a092dfb9779bf484.txt", "url": "https://raw.githubusercontent.com/piskelapp/piskel/master/README.md"}, {"fetched_at": "2026-10-28T09:59:18.067534+08:00", "kind": "license", "sha256": "169685d0b0b65f64136b491cf648c4a7a1aa9ab4276fa5cf89b4ad6130c85104", "snapshot_path": "sources/169685d0b0b65f64136b491cf648c4a7a1aa9ab4276fa5cf89b4ad6130c85104.txt", "url": "https://api.github.com/repos/piskelapp/piskel/license"}, {"fetched_at": "2026-10-28T09:59:15.486109+08:00", "kind": "homepage", "sha256": "4535a2f6b14796cc7278fa8257629c0634c0c6baadc592f05b966e4cc49aaf67", "snapshot_path": "sources/4535a2f6b14796cc7278fa8257629c0634c0c6baadc592f05b966e4cc49aaf67.txt", "url": "https://www.piskelapp.com/"}, {"fetched_at": "2026-10-28T13:28:20.987598+08:00", "kind": "repository_metadata", "sha256": "9cf9352dffcd4903d6804f84f79f1c7ab1f5c2173b1877160dff83b6527476da", "snapshot_path": "sources/9cf9352dffcd4903d6804f84f79f1c7ab1f5c2173b1877160dff83b6527476da.txt", "url": "https://api.github.com/repos/piskelapp/piskel"}, {"fetched_at": "2026-10-28T13:29:41.913744+08:00", "kind": "documentation", "sha256": "8890703da05925a6952c000d1cff60c702bfdcbf2b62107762a00636cf18dc05", "snapshot_path": "sources/8890703da05925a6952c000d1cff60c702bfdcbf2b62107762a00636cf18dc05.txt", "url": "https://www.piskelapp.com/p/create/sprite/"}], "summary": "Piskel 是浏览器内运行的像素画与精灵动画编辑器：在刻意限制的小像素画布上逐像素绘制角色、动画与瓦片，并通过导出 GIF、PNG 或精灵表 ZIP 交付。", "technology_stack": ["JavaScript", "HTML", "CSS"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:photopea','Photopea','{"homepage": "https://www.photopea.com/", "id": "commercial:photopea", "leaf_matches": [{"reason": "官方 Learn 文档说明 Photopea 处理以 PNG、JPG 为代表的单层矩形光栅图（像素网格，a grid of pixels）；Basic Tools 页描述画笔在图层上绘制笔触、铅笔产生硬边、橡皮擦除像素、克隆印章复制像素内容；Navigation 页描述 Zoom 工具缩放查看图像；Opening and Saving 页说明经 File - Open 打开文件、以 PSD 保存文档结构，并可导出 JPG、PNG、SVG、PDF 等格式。四项核心均有官方正文，形态为浏览器内运行、无需下载安装的在线编辑器。文档同时称其可处理矢量图形，但成立依据仅取自上述光栅编辑正文，矢量能力不作补充论证；商业产品仅作基本记录。", "slug": "raster-image-editor", "source_urls": ["https://www.photopea.com/", "https://www.photopea.com/learn/opening-saving", "https://www.photopea.com/learn/bt-basic", "https://www.photopea.com/learn/navigation"]}, {"reason": "官方首页正文自述为 free online photo editor，直接在浏览器中运行、无需下载，文件不离开设备；列出裁剪与缩放、图层/蒙版、色阶与曲线、模糊等调整，并在 RAW 部分明确可通过 Exposure、Color Balance、Contrast、Highlights and Shadows 调整照片，以及打开和保存多种图片格式，覆盖照片对象、摄影操作、用户驱动交互循环与导出交付。", "slug": "photo-editor", "source_urls": ["https://www.photopea.com/"]}], "name": "Photopea", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:06:17.029809+08:00", "kind": "homepage", "sha256": "06c400fb581f91aceef4888c8a6a458459fce9f46e728c5f964bf2b198626c29", "snapshot_path": "sources/06c400fb581f91aceef4888c8a6a458459fce9f46e728c5f964bf2b198626c29.txt", "url": "https://www.photopea.com/"}, {"fetched_at": "2026-10-28T10:06:18.609106+08:00", "kind": "documentation", "sha256": "67d6ead721c4a3f8f26b8d0e64d32988002aa8c781c6d5100f318ea8d437b6e4", "snapshot_path": "sources/67d6ead721c4a3f8f26b8d0e64d32988002aa8c781c6d5100f318ea8d437b6e4.txt", "url": "https://www.photopea.com/learn/opening-saving"}, {"fetched_at": "2026-10-28T10:06:58.263090+08:00", "kind": "documentation", "sha256": "5a34efdaef62b883712d834329219746663ba8b06f6daf4072637cbef04cc342", "snapshot_path": "sources/5a34efdaef62b883712d834329219746663ba8b06f6daf4072637cbef04cc342.txt", "url": "https://www.photopea.com/learn/bt-basic"}, {"fetched_at": "2026-10-28T10:09:35.078372+08:00", "kind": "documentation", "sha256": "bf01d0a2b98d8a3a31930b38c1bbd360c071f95ff2e45d2a3357596ca11dbbe2", "snapshot_path": "sources/bf01d0a2b98d8a3a31930b38c1bbd360c071f95ff2e45d2a3357596ca11dbbe2.txt", "url": "https://www.photopea.com/learn/navigation"}], "summary": "浏览器内运行的图像编辑器：以 PNG/JPG 等单层矩形光栅图为编辑对象，提供画笔、铅笔、橡皮、克隆印章与缩放画布，可打开本地文件并以 PSD、JPG、PNG、SVG、PDF 等格式保存或导出。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:11766620','miniPaint','{"deployment": ["浏览器内运行的静态 Web 应用，官方托管于 GitHub Pages", "源码可按 README 中的构建说明自行构建并自托管"], "features": ["画笔、铅笔、橡皮擦、填充、克隆、魔棒与选区等像素级工具", "图层系统、透明度、图层合并与多种效果/滤镜", "打开本地文件、目录、URL、data URL、拖放与剪贴板图像", "缩放、裁剪与调整尺寸等画布操作", "保存/导出 PNG、JPG、BMP、WEBP、动画 GIF、TIFF 与 JSON（图层数据）"], "github_repository_id": 11766620, "homepage": "https://viliusle.github.io/miniPaint/", "id": "github:11766620", "leaf_matches": [{"reason": "README 正文说明 miniPaint 是在浏览器中创建和编辑图像的在线编辑器：可打开本地文件、目录、URL 与剪贴板图像，以铅笔、画笔、橡皮、填充、克隆等工具直接改像素，并用 Save 保存为 PNG、JPG、BMP、WEBP、动画 GIF、TIFF 或 JSON（图层数据）；图像功能另列出 zoom、resize、rotate 等画布操作。像素网格文档、直接像素操作、可视画布与持久化为图像四项均有官方正文覆盖。官方页面为完整浏览器端 Web 应用（含 canvas、工具区、图层与颜色面板），不是桌面客户端或仅引擎/SDK；许可证由仓库内完整 MIT 文本核定。", "slug": "raster-image-editor", "source_urls": ["https://api.github.com/repos/viliusle/miniPaint", "https://raw.githubusercontent.com/viliusle/miniPaint/master/README.md", "https://api.github.com/repos/viliusle/miniPaint/license", "https://raw.githubusercontent.com/viliusle/miniPaint/master/MIT-LICENSE.txt", "https://viliusle.github.io/miniPaint/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/viliusle/miniPaint/license", "license_review": {"rationale": "仓库根目录 MIT-LICENSE.txt 为完整 MIT 许可文本，含 Permission is hereby granted, free of charge 授权段与 THE SOFTWARE IS PROVIDED \"AS IS\" 免责段；GitHub 许可证接口因文件命名把该仓库标为 NOASSERTION，故按仓库内完整文本人工核定为 MIT，覆盖仓库代码。", "reviewer": "collection-agent-u021", "scope": "repository", "source_url": "https://api.github.com/repos/viliusle/miniPaint/license", "spdx_id": "MIT"}, "name": "miniPaint", "repository_url": "https://github.com/viliusle/miniPaint", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:00:59.205743+08:00", "kind": "repository_metadata", "sha256": "83038ec1cc17a06528c00adfd1d254d6c9857686f286c5b46a1e556bd866bfd6", "snapshot_path": "sources/83038ec1cc17a06528c00adfd1d254d6c9857686f286c5b46a1e556bd866bfd6.txt", "url": "https://api.github.com/repos/viliusle/miniPaint"}, {"fetched_at": "2026-10-28T10:00:57.901829+08:00", "kind": "readme", "sha256": "4b00f8990081b49f2514ef4b1aafca045345af2dd12bbcd8de37431105180f67", "snapshot_path": "sources/4b00f8990081b49f2514ef4b1aafca045345af2dd12bbcd8de37431105180f67.txt", "url": "https://raw.githubusercontent.com/viliusle/miniPaint/master/README.md"}, {"fetched_at": "2026-10-28T10:01:05.491639+08:00", "kind": "license", "sha256": "fdf05d7a4556261eb1002ce99915ca6606fffefb27b935021d74ab29c38468d1", "snapshot_path": "sources/fdf05d7a4556261eb1002ce99915ca6606fffefb27b935021d74ab29c38468d1.txt", "url": "https://api.github.com/repos/viliusle/miniPaint/license"}, {"fetched_at": "2026-10-28T10:01:05.054624+08:00", "kind": "license", "sha256": "92a21f763974d0a691f7738ed8aae674b74ef077ff6341844ad7fadf36999be8", "snapshot_path": "sources/92a21f763974d0a691f7738ed8aae674b74ef077ff6341844ad7fadf36999be8.txt", "url": "https://raw.githubusercontent.com/viliusle/miniPaint/master/MIT-LICENSE.txt"}, {"fetched_at": "2026-10-28T10:01:05.171132+08:00", "kind": "homepage", "sha256": "f7380a8b89fe603de8d1fbb282e210fc113c979428849fb2bd7a18a0d6e5b1a7", "snapshot_path": "sources/f7380a8b89fe603de8d1fbb282e210fc113c979428849fb2bd7a18a0d6e5b1a7.txt", "url": "https://viliusle.github.io/miniPaint/"}], "summary": "浏览器内运行的通用位图图像编辑器：在像素画布上用画笔、铅笔、橡皮、填充、克隆、选区等工具直接修改图像，支持图层与效果/滤镜，可打开本地文件、目录、URL 与剪贴板图像，并保存或导出为 PNG、JPG、BMP、WEBP、动画 GIF、TIFF 与 JSON（图层数据）。为完整静态 Web 应用，可自托管。", "technology_stack": ["JavaScript", "HTML5 Canvas", "Webpack"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1398097510','VectorCraft','{"deployment": ["原生支持 macOS、Windows、Linux、FreeBSD", "浏览器内通过 WebAssembly 运行，同一 UI 与桌面版共用代码库", "发布静态 Web 构建，可托管在任意静态服务器"], "features": ["钢笔与直接选择工具编辑贝塞尔锚点和控制柄", "路径查找器、渐变网格、封套变形与透视网格", "图层与实时混合，对象保持可编辑", "原生 .vectorcraft(JSON) 文档格式", "SVG/PDF 导入导出与 PNG/JPEG/WebP 导出", "浏览器内 WebAssembly 版与可自行托管的 Web 构建"], "github_repository_id": 1398097510, "homepage": "https://getartcraft.com/apps/vectorcraft", "id": "github:1398097510", "leaf_matches": [{"reason": "README 自称“矢量插画；开源现代矢量艺术应用”，示例展示通过其命令 API 绘制并由自身渲染器导出的插画；功能段说明有钢笔与直接选择工具的真实贝塞尔锚点与控制柄、实时混合与图层、路径查找器、渐变网格、透视网格，文档为有说明的原生 .vectorcraft(JSON) 格式，并支持 SVG/PDF 导入导出与 PNG/JPEG/WebP 导出——离散矢量对象、用户手绘、持久可重开文档与成品输出均有官方正文。针对原初审“仅客户端/CLI/引擎”的缺口，README 明示“runs natively … and in the browser via WebAssembly”“the same UI in the browser”，官方产品页（getartcraft.com/apps/vectorcraft）正文自述“Vector illustration, reimagined in pure Rust”“Open source, and in your browser too”，平台标注含 Web，并发布“Web build — The WebAssembly app, to host yourself”，证明其为可在线使用的完整矢量插画应用服务而非纯客户端或引擎；页面有指向 ArtCraft 应用入口的 Launch App 链接，该链接指向 app.getartcraft.com 聚合入口，未单独证明 VectorCraft 的在线实例地址。仓库身份由两次元数据快照（同一 id/full_name，2026-10-24 与 2026-10-28）证明；README 与 LICENSE-MIT、LICENSE-APACHE 全文表明项目为 MIT 或 Apache-2.0 双许可、可任选其一，本条目按目录单 SPDX 约定记录 MIT。", "slug": "illustration-application", "source_urls": ["https://api.github.com/repos/storytold/vectorcraft", "https://raw.githubusercontent.com/storytold/vectorcraft/main/README.md", "https://getartcraft.com/apps/vectorcraft", "https://api.github.com/repos/storytold/vectorcraft/license", "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-MIT", "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-APACHE"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-MIT", "license_review": {"rationale": "README 的 License and credits 明确写明 VectorCraft 以 MIT 或 Apache-2.0 双许可发布，被许可方可任选其一；本字段按目录单 SPDX 约定记录 MIT 选项，完整 MIT 文本见 LICENSE-MIT 快照，Apache-2.0 选项全文另存于 LICENSE-APACHE 快照。", "reviewer": "unit-22 repair (opencode/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-MIT", "spdx_id": "MIT"}, "name": "VectorCraft", "repository_url": "https://github.com/storytold/vectorcraft", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:50:07.891157+08:00", "kind": "repository_metadata", "sha256": "f2649b2ba1e67689bc4ba32485ecc18e84104ea74b32c014c37b47d2e6ba08c4", "snapshot_path": "sources/f2649b2ba1e67689bc4ba32485ecc18e84104ea74b32c014c37b47d2e6ba08c4.txt", "url": "https://api.github.com/repos/storytold/vectorcraft"}, {"fetched_at": "2026-10-28T10:02:44.673240+08:00", "kind": "repository_metadata", "sha256": "16ed2f0358bb1640243841675e76835aefc0cb78b0990d084be76a763641bc58", "snapshot_path": "sources/16ed2f0358bb1640243841675e76835aefc0cb78b0990d084be76a763641bc58.txt", "url": "https://api.github.com/repos/storytold/vectorcraft"}, {"fetched_at": "2026-10-24T11:53:08.356591+08:00", "kind": "readme", "sha256": "b3abdb9205705ab8132c17ac9d84ed7b25f6639b3a187e72571689f0f56fcb08", "snapshot_path": "sources/b3abdb9205705ab8132c17ac9d84ed7b25f6639b3a187e72571689f0f56fcb08.txt", "url": "https://raw.githubusercontent.com/storytold/vectorcraft/main/README.md"}, {"fetched_at": "2026-10-28T10:02:44.688778+08:00", "kind": "homepage", "sha256": "f5620d434c9723e57fb79b8935a07219a63f79ba4209bddf4b9a3f9f763f99e2", "snapshot_path": "sources/f5620d434c9723e57fb79b8935a07219a63f79ba4209bddf4b9a3f9f763f99e2.txt", "url": "https://getartcraft.com/apps/vectorcraft"}, {"fetched_at": "2026-10-24T11:50:10.669077+08:00", "kind": "license", "sha256": "5fc7506aa4ae34f70cabedd73ea56ac066eb387d9981440d16494614db1243d6", "snapshot_path": "sources/5fc7506aa4ae34f70cabedd73ea56ac066eb387d9981440d16494614db1243d6.txt", "url": "https://api.github.com/repos/storytold/vectorcraft/license"}, {"fetched_at": "2026-10-25T23:10:49.069453+08:00", "kind": "license", "sha256": "8b6025dc4b707e0fb08b9c2054096f1be3ae61529399aa2c348dec676562dc71", "snapshot_path": "sources/8b6025dc4b707e0fb08b9c2054096f1be3ae61529399aa2c348dec676562dc71.txt", "url": "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-MIT"}, {"fetched_at": "2026-10-25T23:10:48.279892+08:00", "kind": "license", "sha256": "0d542e0c8804e39aa7f37eb00da5a762149dc682d7829451287e11b938e94594", "snapshot_path": "sources/0d542e0c8804e39aa7f37eb00da5a762149dc682d7829451287e11b938e94594.txt", "url": "https://raw.githubusercontent.com/storytold/vectorcraft/main/LICENSE-APACHE"}], "summary": "VectorCraft 是开源矢量插画应用：用钢笔与直接选择工具逐对象绘制贝塞尔路径和形状，文档保持对象可编辑，可导入导出 SVG、PDF 与位图。除 macOS、Windows、Linux、FreeBSD 原生应用与 CLI 外，同一代码库提供浏览器内运行的 WebAssembly 版本（官方产品页在平台标注中列出 Web、设有 Launch App 入口，并发布可自行托管的 Web 构建），构成完整应用服务形态而非仅客户端/引擎。以 MIT 或 Apache-2.0 双许可发布，被许可方可任选其一；项目自述仍在 active development（自评约 65% ready for real work）。", "technology_stack": ["Rust", "WebAssembly"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:21611548','SVG-Edit','{"deployment": ["纯浏览器运行，无需安装", "可将构建产物部署到自有 Web 服务器", "官方 README 提供 Netlify 在线构建入口", "提供 npm 包 @svgedit/svgcanvas 供嵌入"], "features": ["浏览器内 SVG 画布绘制路径、形状与文本", "路径节点独立编辑、旋转与缩放", "对象选择、层级与属性调整", "通过默认 opensave 扩展打开既有或预载的 SVG 文档", "将画布序列化为标准 SVG（image/svg+xml）并保存为 .svg 文件"], "github_repository_id": 21611548, "homepage": "https://svg-edit.github.io/svgedit/", "id": "github:21611548", "leaf_matches": [{"reason": "README 称其为可在任何现代浏览器运行的 SVG 绘图编辑器，给出在线构建入口及部署到自有 Web 服务器的构建步骤，属完整 Web 应用而非仅 SDK。Editor.md 说明路径工具绘制路径、选中后可独立调整路径节点并旋转缩放，证明矢量对象模型与直接几何编辑。ConfigObj.js 的 defaultExtensions 含 ext-opensave；该扩展正文显示 open 调用 fileOpen 后 loadSvgString 载入 SVG 文档，save 将 svgCanvasToString 序列化结果以 image/svg+xml、.svg 扩展名写出，证明可重新打开的持久文档与标准矢量输出。仓库身份与 MIT 许可由仓库元数据及 license 接口证明。", "slug": "vector-graphics-editor", "source_urls": ["https://api.github.com/repos/SVG-Edit/svgedit", "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/README.md", "https://api.github.com/repos/SVG-Edit/svgedit/license", "https://svg-edit.github.io/svgedit/", "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/docs/tutorials/Editor.md", "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/src/editor/extensions/ext-opensave/ext-opensave.js", "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/src/editor/ConfigObj.js"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/SVG-Edit/svgedit/license", "name": "SVG-Edit", "repository_url": "https://github.com/SVG-Edit/svgedit", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T11:47:37.355299+08:00", "kind": "repository_metadata", "sha256": "e9dfd025708067bd4d86718a3c9f28d61ecf57c276e49650b5e4d2f3323ec6f6", "snapshot_path": "sources/e9dfd025708067bd4d86718a3c9f28d61ecf57c276e49650b5e4d2f3323ec6f6.txt", "url": "https://api.github.com/repos/SVG-Edit/svgedit"}, {"fetched_at": "2026-10-24T12:16:25.227612+08:00", "kind": "readme", "sha256": "c05ae3d3b61731d5ff2b4944f987aa848c28aba24d450f4f2d5aad9959b05f94", "snapshot_path": "sources/c05ae3d3b61731d5ff2b4944f987aa848c28aba24d450f4f2d5aad9959b05f94.txt", "url": "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/README.md"}, {"fetched_at": "2026-10-24T11:47:38.734682+08:00", "kind": "license", "sha256": "2fc0ef81072339d512ed0f506bac1140754dac242f5f669437e042f58adaca87", "snapshot_path": "sources/2fc0ef81072339d512ed0f506bac1140754dac242f5f669437e042f58adaca87.txt", "url": "https://api.github.com/repos/SVG-Edit/svgedit/license"}, {"fetched_at": "2026-10-24T12:12:49.476493+08:00", "kind": "documentation", "sha256": "a58bee0ea7fb715ca03e410c6f25028379d75884d34fa84f9860c5811674184f", "snapshot_path": "sources/a58bee0ea7fb715ca03e410c6f25028379d75884d34fa84f9860c5811674184f.txt", "url": "https://svg-edit.github.io/svgedit/"}, {"fetched_at": "2026-10-24T12:24:12.178301+08:00", "kind": "documentation", "sha256": "a8e390d541e7d554b1a6ee9c9639c98d958dd55defa60cdf9c90d5c867ad26a8", "snapshot_path": "sources/a8e390d541e7d554b1a6ee9c9639c98d958dd55defa60cdf9c90d5c867ad26a8.txt", "url": "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/docs/tutorials/Editor.md"}, {"fetched_at": "2026-10-28T10:15:37.148046+08:00", "kind": "documentation", "sha256": "ea89ea1aa09c23997a902900f851d9d899a175b7472873c4fd326f2fe90cba07", "snapshot_path": "sources/ea89ea1aa09c23997a902900f851d9d899a175b7472873c4fd326f2fe90cba07.txt", "url": "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/src/editor/extensions/ext-opensave/ext-opensave.js"}, {"fetched_at": "2026-10-28T10:15:40.014147+08:00", "kind": "documentation", "sha256": "7910fa00b99e7e0b25f9909daac559455a36dc4e53ad83f2ae092513560bdc9b", "snapshot_path": "sources/7910fa00b99e7e0b25f9909daac559455a36dc4e53ad83f2ae092513560bdc9b.txt", "url": "https://raw.githubusercontent.com/SVG-Edit/svgedit/master/src/editor/ConfigObj.js"}], "summary": "SVG-Edit 是浏览器内运行的完整 SVG 矢量图形编辑器：在 SVG 画布上绘制与编辑路径、形状和文本对象，可打开既有 SVG 文档，并以标准 SVG 文件保存输出。提供在线构建入口，也可自建静态站点部署。", "technology_stack": ["JavaScript", "SVG", "Web Components"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:4767074','Method Draw','{"deployment": ["在线实例 editor.method.ac 直接使用，无需注册", "克隆后以静态服务器托管 src 目录", "npm install 后 gulp build，将 dist 部署到自有静态服务器"], "features": ["浏览器内绘制路径、矩形、椭圆、直线与文本对象", "对象选择、编组、层级与路径节点编辑", "Open SVG... 载入既有 SVG 文档", "Save Image... 序列化为标准 SVG 并下载 .svg 文件", "Export as PNG 光栅导出", "撤销/重做、网格吸附与标尺"], "github_repository_id": 4767074, "homepage": "https://editor.method.ac/", "id": "github:4767074", "leaf_matches": [{"reason": "README 自述为 “web based vector drawing application”，提供在线实例与静态托管/构建步骤，属完整 Web 应用。src/index.html 的文件菜单含 Open SVG...、Save Image... 与 Export as PNG，并含矩形、椭圆、直线、路径与文本的属性面板，证明绘图与直接几何编辑。src/js/svgcanvas.js 的 save() 把画布序列化为 image/svg+xml 并以 .svg 文件名下载，setSvgString() 可载入 SVG 文档，rasterExport 提供 PNG 输出，证明持久文档与标准输出。仓库身份与 MIT 许可由仓库元数据及 license 接口证明。", "slug": "vector-graphics-editor", "source_urls": ["https://api.github.com/repos/methodofaction/Method-Draw", "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/readme.md", "https://api.github.com/repos/methodofaction/Method-Draw/license", "https://editor.method.ac/", "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/src/index.html", "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/src/js/svgcanvas.js"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/methodofaction/Method-Draw/license", "name": "Method Draw", "repository_url": "https://github.com/methodofaction/Method-Draw", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:14:32.495899+08:00", "kind": "repository_metadata", "sha256": "697356013014707690ece7a247fe0b6d78a0f39c77d054764ac2bb9f52fd31d5", "snapshot_path": "sources/697356013014707690ece7a247fe0b6d78a0f39c77d054764ac2bb9f52fd31d5.txt", "url": "https://api.github.com/repos/methodofaction/Method-Draw"}, {"fetched_at": "2026-10-28T10:16:04.840677+08:00", "kind": "readme", "sha256": "05fae991b04c700cb37a4350297351e149d26621e38242b72f03d3b97c78507b", "snapshot_path": "sources/05fae991b04c700cb37a4350297351e149d26621e38242b72f03d3b97c78507b.txt", "url": "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/readme.md"}, {"fetched_at": "2026-10-28T10:16:03.360864+08:00", "kind": "license", "sha256": "b4cb9894e7e2c5a6f0b853fd8c95c48c9ce2a47e7989e420ceeafd32bd507e6b", "snapshot_path": "sources/b4cb9894e7e2c5a6f0b853fd8c95c48c9ce2a47e7989e420ceeafd32bd507e6b.txt", "url": "https://api.github.com/repos/methodofaction/Method-Draw/license"}, {"fetched_at": "2026-10-28T10:17:30.586035+08:00", "kind": "homepage", "sha256": "dee35ecfd9833c6fda696baa0e966bfa03790a58efa41a82324acd506f67e46b", "snapshot_path": "sources/dee35ecfd9833c6fda696baa0e966bfa03790a58efa41a82324acd506f67e46b.txt", "url": "https://editor.method.ac/"}, {"fetched_at": "2026-10-28T10:16:07.673008+08:00", "kind": "documentation", "sha256": "10a96d52a06af6710af8f1dab50af84abfa3426229d49839bab6cb0860825fa3", "snapshot_path": "sources/10a96d52a06af6710af8f1dab50af84abfa3426229d49839bab6cb0860825fa3.txt", "url": "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/src/index.html"}, {"fetched_at": "2026-10-28T10:17:48.139519+08:00", "kind": "documentation", "sha256": "9e4fad244644d855fb4de565a60201df907329da62600be4bd44cba4b6d832c3", "snapshot_path": "sources/9e4fad244644d855fb4de565a60201df907329da62600be4bd44cba4b6d832c3.txt", "url": "https://raw.githubusercontent.com/methodofaction/Method-Draw/master/src/js/svgcanvas.js"}], "summary": "Method Draw 是面向 Web 的简化开源 SVG 矢量绘图应用：在浏览器画布上用路径、形状与文本工具绘制并直接调整对象几何，可打开既有 SVG 文档、保存为标准 SVG 文件并导出 PNG。提供在线实例，也可构建为静态站点自托管。", "technology_stack": ["JavaScript", "SVG", "HTML5 Canvas"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1262723706','Culvia','{"deployment": ["本地 Web 应用：pip install culvia 后运行 culvia-web 或 culvia-supervisor", "可选桌面外壳，复用同一后端与界面", "默认仅监听 127.0.0.1"], "features": ["按文件夹加入一次拍摄的照片批次，扫描子目录并按路径去重", "画廊与大图查看器逐张评审", "手动 pick / hold / reject 决策，另有星级与色标", "按 pick/reject/状态与评分筛选，隔离保留照片", "把选中（picked）照片复制到目标文件夹作为交付选集", "导出 CSV，含 manual_status 与 Lightroom/Capture One 映射列"], "github_repository_id": 1262723706, "homepage": "https://github.com/yangzhg/culvia", "id": "github:1262723706", "leaf_matches": [{"reason": "官方 README 将其定位为照片筛选/评审/交付工作台，位于 Lightroom 等编辑器之前；Getting Started 的 Basic Workflow 明确以文件夹照片为批次，逐张应用手动 pick/hold/reject、星级与色标，并可筛选后导出选中照片或 CSV。Export Workflows 文档说明“selected-photo copy”把标记为 picked 的照片复制到目标目录，并给出 Lightroom flag 与 Capture One 色标映射列，构成可交接的选集输出；决策存于本地 SQLite、导出为复制而非改写原图，符合“决定记录在图片旁、像素不动”。模型的自动评分只是建议，人工决定仍是最终层，因此核心仍是逐张人工筛选。", "slug": "photo-culling-application", "source_urls": ["https://raw.githubusercontent.com/yangzhg/culvia/main/README.md", "https://raw.githubusercontent.com/yangzhg/culvia/main/docs/en/user/getting-started.md", "https://raw.githubusercontent.com/yangzhg/culvia/main/docs/en/user/export-workflows.md", "https://api.github.com/repos/yangzhg/culvia", "https://api.github.com/repos/yangzhg/culvia/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/yangzhg/culvia/license", "name": "Culvia", "repository_url": "https://github.com/yangzhg/culvia", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:09:18.674785+08:00", "kind": "repository_metadata", "sha256": "e969b136c44dd385c91140be6c28c79a8cb2994df81a2e3ee7a8dadf62e1d660", "snapshot_path": "sources/e969b136c44dd385c91140be6c28c79a8cb2994df81a2e3ee7a8dadf62e1d660.txt", "url": "https://api.github.com/repos/yangzhg/culvia"}, {"fetched_at": "2026-10-28T10:09:20.260015+08:00", "kind": "license", "sha256": "a667f90a2a4897f5309cd0e0f256171949c22dcfcbfd1a3f101607973235a98a", "snapshot_path": "sources/a667f90a2a4897f5309cd0e0f256171949c22dcfcbfd1a3f101607973235a98a.txt", "url": "https://api.github.com/repos/yangzhg/culvia/license"}, {"fetched_at": "2026-10-28T10:09:26.552605+08:00", "kind": "readme", "sha256": "12b746e0371bc4d388ef016a9046181d0eec7dc802aaa8449052d5d1636be2a5", "snapshot_path": "sources/12b746e0371bc4d388ef016a9046181d0eec7dc802aaa8449052d5d1636be2a5.txt", "url": "https://raw.githubusercontent.com/yangzhg/culvia/main/README.md"}, {"fetched_at": "2026-10-28T10:12:48.615572+08:00", "kind": "documentation", "sha256": "1fb85444fa3e8e889ece4e849c3bcd9f8edbb50f8c183f86af558aa857362142", "snapshot_path": "sources/1fb85444fa3e8e889ece4e849c3bcd9f8edbb50f8c183f86af558aa857362142.txt", "url": "https://raw.githubusercontent.com/yangzhg/culvia/main/docs/en/user/getting-started.md"}, {"fetched_at": "2026-10-28T10:11:37.968794+08:00", "kind": "documentation", "sha256": "857345e3869b891a3f0c4346ec68c2e80a577cc332b7f729293421ada7862335", "snapshot_path": "sources/857345e3869b891a3f0c4346ec68c2e80a577cc332b7f729293421ada7862335.txt", "url": "https://raw.githubusercontent.com/yangzhg/culvia/main/docs/en/user/export-workflows.md"}], "summary": "Culvia 是本地运行的开源照片筛选工作台（项目自述 alpha）：以拍摄文件夹为范围扫描批次，在画廊与大图中逐张标记 pick/hold/reject、星级与色标，筛选后把保留照片复制到目标文件夹或导出 CSV，供后续 Lightroom/Capture One 流程使用；原图不被修改，决定保存在本地 SQLite。", "technology_stack": ["Python", "SQLite", "Web UI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1298027412','Photo Triage','{"deployment": ["自托管 Flask Web 应用，浏览器经局域网访问", "Docker Compose 或 systemd 常驻（可作为树莓派上的服务）", "需本机 exiftool 与 Anthropic API 密钥用于 AI 初判"], "features": ["按 RAW 文件夹浏览一次拍摄批次，支持多种相机 RAW 扩展名", "抽取内嵌 JPEG 预览并后台显示进度", "Claude 给出 reject/评分/关键词建议，可选重复帧分组", "浏览器评审表逐张修改或撤销建议，重复组可换选保留帧", "把最终决定写入 RAW 旁的 XMP 边车（Rating、红色标签、说明、关键词）", "评审结果可再次处理或只处理新增照片"], "github_repository_id": 1298027412, "homepage": "https://github.com/elpicoso/photo-triage-app", "id": "github:1298027412", "leaf_matches": [{"reason": "README 首段即定义其用途：对一个 RAW 照片积压/拍摄批次做筛选，抽取预览、给出 reject/评分/关键词建议，用户在浏览器中复核并修改，最后写入 XMP 边车供 Lightroom Classic 读取。“Using it”一节给出完整循环：浏览包含 RAW 的文件夹 → 抽取预览 → 运行 triage → 在可编辑表格中逐张修正 → 写入边车；重复帧分组还可在评审表中换选保留帧，明确把人工决定置于 AI 建议之上。决定写入原图旁的 sidecar 而不改动 RAW，并说明下游 Read Metadata from File 的交接步骤，符合本叶的批次、逐张决策与选集交接三项；AI 初判只是加速手段，不是核心替代。", "slug": "photo-culling-application", "source_urls": ["https://raw.githubusercontent.com/elpicoso/photo-triage-app/main/README.md", "https://api.github.com/repos/elpicoso/photo-triage-app", "https://api.github.com/repos/elpicoso/photo-triage-app/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/elpicoso/photo-triage-app/license", "name": "Photo Triage", "repository_url": "https://github.com/elpicoso/photo-triage-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:10:38.668073+08:00", "kind": "repository_metadata", "sha256": "aba3950fcbf5bc3e6c3389a5577de7c8996877608b0e0fbd492c42c55e94695b", "snapshot_path": "sources/aba3950fcbf5bc3e6c3389a5577de7c8996877608b0e0fbd492c42c55e94695b.txt", "url": "https://api.github.com/repos/elpicoso/photo-triage-app"}, {"fetched_at": "2026-10-28T10:10:41.754198+08:00", "kind": "readme", "sha256": "46b8e5efc93da8c91223c43fe6141dd315372a6440b9f17b3e48df776dbaa892", "snapshot_path": "sources/46b8e5efc93da8c91223c43fe6141dd315372a6440b9f17b3e48df776dbaa892.txt", "url": "https://raw.githubusercontent.com/elpicoso/photo-triage-app/main/README.md"}, {"fetched_at": "2026-10-28T10:10:43.843088+08:00", "kind": "license", "sha256": "590e18278659f5a598eb1af129141ffc5113e0990b42a0e689599ad8d339cd81", "snapshot_path": "sources/590e18278659f5a598eb1af129141ffc5113e0990b42a0e689599ad8d339cd81.txt", "url": "https://api.github.com/repos/elpicoso/photo-triage-app/license"}], "summary": "Photo Triage 是自托管的开源照片筛选 Web 应用：浏览一次拍摄的 RAW 文件夹，抽取预览后由 Claude 给出淘汰/评分/关键词建议，用户在浏览器表格中逐张复核修改，再把最终决定写成 XMP 边车文件交给 Lightroom Classic 等下游工具；原图与已写边车不被改动。", "technology_stack": ["Python", "Flask", "exiftool", "XMP", "Anthropic API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:968851311','MiNi PhotoEditor','{"deployment": ["托管网页应用：https://mini2-photo-editor.netlify.app/", "图像在浏览器本地处理，不上传后端"], "features": ["光照与色彩调整、颜色曲线", "裁剪、透视校正、图像缩放", "清晰度/锐化、降噪、暗角", "修复画笔（inpaint）", "滤镜、镜头/高斯模糊", "前后分屏对比与颜色直方图", "EXIF/TIFF/GPS 信息查看"], "github_repository_id": 968851311, "homepage": "https://mini2-photo-editor.netlify.app/", "id": "github:968851311", "leaf_matches": [{"reason": "README 正文自述为在线 WebGL2 照片编辑器，逐项列出裁剪、透视校正、图像缩放、光照与色彩调整、颜色曲线、清晰度/锐化、降噪、修复画笔和前后分屏对比，均属于以照片为对象的摄影操作，可边看边调、本地即时预览，并以下载导出结束循环；托管站点可访问（HTTP 200 的应用壳与 manifest），说明它是完整可用的网页应用服务而非纯 SDK/引擎。仓库身份由元数据（id 968851311、full_name xdadda/mini-photo-editor）证明；LICENSE 为完整 MIT 全文，与 GitHub license API 的 spdx_id 一致。", "slug": "photo-editor", "source_urls": ["https://api.github.com/repos/xdadda/mini-photo-editor", "https://raw.githubusercontent.com/xdadda/mini-photo-editor/main/README.md", "https://api.github.com/repos/xdadda/mini-photo-editor/license", "https://mini2-photo-editor.netlify.app/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/xdadda/mini-photo-editor/license", "name": "MiNi PhotoEditor", "repository_url": "https://github.com/xdadda/mini-photo-editor", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:36:49.148614+08:00", "kind": "repository_metadata", "sha256": "6ba2b7a97e2baa461df62681b549878424bb3f727de0683ec265835ed12fb2ac", "snapshot_path": "sources/6ba2b7a97e2baa461df62681b549878424bb3f727de0683ec265835ed12fb2ac.txt", "url": "https://api.github.com/repos/xdadda/mini-photo-editor"}, {"fetched_at": "2026-10-28T10:36:50.530526+08:00", "kind": "readme", "sha256": "2998edadf9715237fb9978dd2b8478a007c69f21289eeb62c5d919072f4473a6", "snapshot_path": "sources/2998edadf9715237fb9978dd2b8478a007c69f21289eeb62c5d919072f4473a6.txt", "url": "https://raw.githubusercontent.com/xdadda/mini-photo-editor/main/README.md"}, {"fetched_at": "2026-10-28T10:38:07.772734+08:00", "kind": "license", "sha256": "6f96f6b6bab9859d6bc2d5501b95c8c3fa3e05a6c07884a082b8f06dbb7c73e6", "snapshot_path": "sources/6f96f6b6bab9859d6bc2d5501b95c8c3fa3e05a6c07884a082b8f06dbb7c73e6.txt", "url": "https://api.github.com/repos/xdadda/mini-photo-editor/license"}, {"fetched_at": "2026-10-28T10:36:53.976765+08:00", "kind": "license", "sha256": "6390a91c6d82a7cdb00c06c2104da7afacc3c029901d3621870b8762386c32ae", "snapshot_path": "sources/6390a91c6d82a7cdb00c06c2104da7afacc3c029901d3621870b8762386c32ae.txt", "url": "https://raw.githubusercontent.com/xdadda/mini-photo-editor/main/LICENSE"}, {"fetched_at": "2026-10-28T10:36:48.988711+08:00", "kind": "homepage", "sha256": "9a6f6f88427f6fa4e3769bc34624e696fab66c72414f71215515b4540f596003", "snapshot_path": "sources/9a6f6f88427f6fa4e3769bc34624e696fab66c72414f71215515b4540f596003.txt", "url": "https://mini2-photo-editor.netlify.app/"}], "summary": "MiNi PhotoEditor 是浏览器端开源照片编辑器：在网页中打开照片后调整光照与色彩、曲线、裁剪与透视、锐化与降噪并修复瑕疵，本地即时预览，最后下载导出处理后的图片。", "technology_stack": ["WebGL2", "JavaScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1420087667','albedo','{"deployment": ["浏览器 Web 应用（PWA，安装后可离线使用，无账号）", "自托管静态站点：npm run build 产出 dist/ 静态资源", "要求 WebGPU（Chrome/Edge 113+、Safari 26、Firefox 141+），Library 与 Develop 可回退 WebGL2"], "features": ["浏览器内 RAW 开发：LibRaw 解码 CR2/CR3/NEF/ARW/RAF（Bayer 与 X-Trans）/ORF/RW2/PEF/DNG 等，另可打开 JPEG/PNG", "自有 GPU 处理管线：RCD 与 X-Trans 去马赛克、高光重建、Lensfun 镜头校正、AgX 或 DCP 色彩配置", "参数化局部调整：线性/径向/画笔蒙版与 AI 主体、天空、背景、对象选择，修复、克隆、AI 降噪", "渲染输出：45MP RAW 导出全分辨率 JPEG，DNG 与 16 位 TIFF 输出，Lightroom XMP 边车与预设读写", "图层合成：RAW 作为智能对象，调整图层、27 种混合模式、蒙版、分组、8/16/32 位", "照片库：旗标、评分、相册、智能集合与键盘剔除；离线 PWA，无账号、照片不上传"], "github_repository_id": 1420087667, "homepage": "https://zahakj.github.io/albedo/", "id": "github:1420087667", "leaf_matches": [{"reason": "官方 README 与项目首页写明其为“运行在浏览器中的 RAW 开发与合成应用”：用 LibRaw 打开 CR2、CR3、NEF、ARW、RAF（Bayer 与 X-Trans）、ORF、RW2、PEF、DNG 等相机 RAW；开发在 GPU 上完成，包含 RCD/X-Trans 去马赛克、高光重建、Lensfun 校正与 AgX/DCP 配置，即应用自身引擎解读传感器数据；调整以 Lightroom XMP 边车与预设读写保存，原文件不被覆盖；导出为全分辨率 JPEG、DNG 与 16 位 TIFF，构成渲染交付物。首页进一步说明“照片以智能对象进入、可随时修改其开发”，对应可修订配方循环。形态为可直接访问的浏览器 Web 应用（https://zahakj.github.io/albedo/app/ 返回 200）并可 npm run build 自托管静态站点，PWA 离线运行、无账号、不上传照片，满足完整应用服务形态而无需额外后端。仓库身份 id 1420087667 与 AGPL-3.0 由元数据与许可证接口证明；README 自述 AGPL-3.0-only，接口 SPDX 为 AGPL-3.0，许可证全文完整。社区体量尚小（0 stars、2026-10 新建），故作为第二案例并列记录，不据此放大成熟度。", "slug": "raw-photo-editor", "source_urls": ["https://api.github.com/repos/ZahakJ/albedo", "https://raw.githubusercontent.com/ZahakJ/albedo/main/README.md", "https://api.github.com/repos/ZahakJ/albedo/license", "https://zahakj.github.io/albedo/"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/ZahakJ/albedo/license", "name": "albedo", "repository_url": "https://github.com/ZahakJ/albedo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:26:55.514105+08:00", "kind": "repository_metadata", "sha256": "aa1809187c442ba5176e766e074c1165eaf808328d5cd7e0355e8afe050c7029", "snapshot_path": "sources/aa1809187c442ba5176e766e074c1165eaf808328d5cd7e0355e8afe050c7029.txt", "url": "https://api.github.com/repos/ZahakJ/albedo"}, {"fetched_at": "2026-10-28T10:26:57.006990+08:00", "kind": "readme", "sha256": "1a08e683fe38b1b9877befb9ffe5f2aa2b3ff41eff8c700ad0ca55dc292fd9d8", "snapshot_path": "sources/1a08e683fe38b1b9877befb9ffe5f2aa2b3ff41eff8c700ad0ca55dc292fd9d8.txt", "url": "https://raw.githubusercontent.com/ZahakJ/albedo/main/README.md"}, {"fetched_at": "2026-10-28T10:26:56.001814+08:00", "kind": "license", "sha256": "d5f931a5a59843a3fcac9584a4deb919c9e899c7850b8ccca882530d1f6ae49c", "snapshot_path": "sources/d5f931a5a59843a3fcac9584a4deb919c9e899c7850b8ccca882530d1f6ae49c.txt", "url": "https://api.github.com/repos/ZahakJ/albedo/license"}, {"fetched_at": "2026-10-28T10:27:38.651744+08:00", "kind": "homepage", "sha256": "41e7456892b749f724c823022624bb2c99d89d0f4026ac7eaaee2ac105edac1c", "snapshot_path": "sources/41e7456892b749f724c823022624bb2c99d89d0f4026ac7eaaee2ac105edac1c.txt", "url": "https://zahakj.github.io/albedo/"}], "summary": "albedo 是完整开源、运行在浏览器中的 RAW 开发与合成应用（AGPL-3.0）：用 LibRaw 解码相机 RAW，在 GPU 上做去马赛克、高光重建与参数化调整，配方以 Lightroom XMP 边车保存，并渲染导出全分辨率 JPEG、DNG 与 16 位 TIFF；同时提供图层合成与照片库，可作为离线 PWA 安装或自托管静态站点，无账号、不上传照片。", "technology_stack": ["TypeScript", "React", "WebGPU", "WebGL2", "WebAssembly（libraw-wasm）", "SQLite（OPFS）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1195367387','SnapOtter','{"deployment": ["单容器 docker run 快速启动（内置 Postgres 与 Redis）", "生产环境可用 app + Postgres 17 + Redis 8 的 Compose 栈", "支持 AMD64 与 ARM64，可选 NVIDIA CUDA 加速"], "features": ["112 项图像工具：resize、crop、compress、convert、watermark、color adjust 等", "Pipelines 把多个工具串成可复用工作流，可对单个文件或整批一次运行", "处理结果可保存到 Files 文件库并保留版本历史", "支持 REST API、默认管理员账号的 Web UI 与多语言界面", "单容器自托管，文件不离开自有网络"], "github_repository_id": 1195367387, "homepage": "https://snapotter.com", "id": "github:1195367387", "leaf_matches": [{"reason": "官方文档 Pipelines 章节正文写道：把工具与设置串成步骤后可“Run on a single file - or an entire batch at once. Save the pipeline for later reuse.”，即集合级一次配置、整批自动执行、可复用定义；README 列出 resize/crop/compress/convert/watermark 等 112 项图像工具、Files 文件库与版本历史，并给出单容器 docker run 自托管步骤，构成 Web 应用服务形态。多图输入集、集合级操作定义、自动逐图执行与输出留存均有官方正文；仓库身份由 GitHub API 元数据（id 1195367387、full_name snapotter-hq/SnapOtter、非 fork、未归档）证明，许可证为 AGPL-3.0，企业目录另按商业许可，社区版无 license key 即具备全部工具、batch、pipelines。", "slug": "image-batch-processor", "source_urls": ["https://api.github.com/repos/snapotter-hq/SnapOtter", "https://raw.githubusercontent.com/snapotter-hq/SnapOtter/main/README.md", "https://api.github.com/repos/snapotter-hq/SnapOtter/license", "https://raw.githubusercontent.com/snapotter-hq/SnapOtter/main/LICENSING.md", "https://docs.snapotter.com/guide/getting-started"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/snapotter-hq/SnapOtter/license", "license_review": {"rationale": "LICENSE 与 GitHub license API 均为完整 AGPL-3.0 正文；同仓库 LICENSING.md 明确除 packages/enterprise/ 外全部内容按 AGPL-3.0 授权，企业目录另需商业许可。社区版无 license key 即具备全部工具、batch、pipelines、API keys 与单节点运行，因此仅就开源核心记录 AGPL-3.0，不声称企业目录开源。", "reviewer": "source_research", "scope": "community_core", "source_url": "https://api.github.com/repos/snapotter-hq/SnapOtter/license", "spdx_id": "AGPL-3.0"}, "name": "SnapOtter", "repository_url": "https://github.com/snapotter-hq/SnapOtter", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:41:21.237001+08:00", "kind": "repository_metadata", "sha256": "d6555774a71f2d94b43aea6d249b80561dad95f80233dbbf6291afd9613905f3", "snapshot_path": "sources/d6555774a71f2d94b43aea6d249b80561dad95f80233dbbf6291afd9613905f3.txt", "url": "https://api.github.com/repos/snapotter-hq/SnapOtter"}, {"fetched_at": "2026-10-28T10:41:09.452087+08:00", "kind": "readme", "sha256": "9b6ee7167ade9454ffb3da0415f99d667483ef3f43058eea99cac72927b091a0", "snapshot_path": "sources/9b6ee7167ade9454ffb3da0415f99d667483ef3f43058eea99cac72927b091a0.txt", "url": "https://raw.githubusercontent.com/snapotter-hq/SnapOtter/main/README.md"}, {"fetched_at": "2026-10-28T10:41:56.108848+08:00", "kind": "license", "sha256": "8041bde8f3da42b89de3f4b6a7e8e7b0affbd700d1657dc4cf587782fb09264c", "snapshot_path": "sources/8041bde8f3da42b89de3f4b6a7e8e7b0affbd700d1657dc4cf587782fb09264c.txt", "url": "https://api.github.com/repos/snapotter-hq/SnapOtter/license"}, {"fetched_at": "2026-10-28T10:41:10.775415+08:00", "kind": "license", "sha256": "fa885b242f8c5b9e0819bd40200b8f3269b1cd2cd5bd8f8abf8ebe0dced9f9a4", "snapshot_path": "sources/fa885b242f8c5b9e0819bd40200b8f3269b1cd2cd5bd8f8abf8ebe0dced9f9a4.txt", "url": "https://raw.githubusercontent.com/snapotter-hq/SnapOtter/main/LICENSING.md"}, {"fetched_at": "2026-10-28T10:41:22.200500+08:00", "kind": "documentation", "sha256": "9e62d4ed31e1523c23ca806067f7c652f1a74f9b7e135a7a3154898984260f8c", "snapshot_path": "sources/9e62d4ed31e1523c23ca806067f7c652f1a74f9b7e135a7a3154898984260f8c.txt", "url": "https://docs.snapotter.com/guide/getting-started"}], "summary": "SnapOtter 是开源核心、社区版功能完整的自托管文件处理 Web 服务：图像工具与 Pipelines 可把一串操作配置一次后对整批图片运行，结果保存在服务端文件库。", "technology_stack": ["TypeScript", "Docker", "PostgreSQL", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:909666349','ImgCompress','{"deployment": ["单个 Docker 容器自托管，浏览器访问 Web UI", "提供 Docker Compose 部署示例（局域网与反向代理两种）", "可选 CLI 供脚本调用"], "features": ["一次上传多张图片，统一设置质量、输出格式与目标体积", "批量压缩，README 称可跨整个照片库多核并行处理", "批量格式转换，支持 70+ 输入格式并可将图片批次输出为分页 PDF", "逐图裁剪（比例预设或自定义像素尺寸），裁剪先于缩放、格式转换与压缩执行", "下载单张结果或整包 ZIP"], "github_repository_id": 909666349, "homepage": "https://imgcompress.karimzouine.com", "id": "github:909666349", "leaf_matches": [{"reason": "官方 Web UI 文档逐步描述批量流程：拖入多张图片 → 统一调整质量、格式等设置 → 点 Convert 由服务端处理 → 单张或 ZIP 下载；裁剪文档明确裁剪先于 resize、格式转换、目标体积压缩执行。README 补充批量压缩可覆盖整个照片库、支持 70+ 格式与图片批次转分页 PDF，并给出单容器 docker run 自托管步骤。多图输入集、集合级一次配置的操作定义、服务端自动逐图执行、明确输出规则四项均有官方正文；仓库身份由 GitHub API 元数据（id 909666349、full_name karimz1/imgcompress、非 fork、未归档）证明，许可证为 GPL-3.0。", "slug": "image-batch-processor", "source_urls": ["https://api.github.com/repos/karimz1/imgcompress", "https://raw.githubusercontent.com/karimz1/imgcompress/main/ReadMe.md", "https://api.github.com/repos/karimz1/imgcompress/license", "https://imgcompress.karimzouine.com/docs/web-ui"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/karimz1/imgcompress/license", "license_review": {"rationale": "GitHub license API 对该仓库返回 spdx_id=GPL-3.0，快照为完整 GNU GPL v3 正文；README 的 License 段亦标注 GPL-3.0，未发现附加限制或仅部分目录授权的说明，故按整仓库 GPL-3.0 记录。", "reviewer": "source_research", "scope": "repository", "source_url": "https://api.github.com/repos/karimz1/imgcompress/license", "spdx_id": "GPL-3.0"}, "name": "ImgCompress", "repository_url": "https://github.com/karimz1/imgcompress", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:41:21.237186+08:00", "kind": "repository_metadata", "sha256": "cc84647cdb49a7a7e364a00130f9bded9d8ef3e5355939a2ec7244d83be8dcc1", "snapshot_path": "sources/cc84647cdb49a7a7e364a00130f9bded9d8ef3e5355939a2ec7244d83be8dcc1.txt", "url": "https://api.github.com/repos/karimz1/imgcompress"}, {"fetched_at": "2026-10-28T10:41:07.945979+08:00", "kind": "readme", "sha256": "9607a5c5d06e740bbb598a7d948045024088c394738fd0002b3acda633086161", "snapshot_path": "sources/9607a5c5d06e740bbb598a7d948045024088c394738fd0002b3acda633086161.txt", "url": "https://raw.githubusercontent.com/karimz1/imgcompress/main/ReadMe.md"}, {"fetched_at": "2026-10-28T10:39:08.698839+08:00", "kind": "license", "sha256": "894acd7e4529f4fe6384ec4b4ffc3e4216647fa7f02bc5ed2de0c6f3049ae6cc", "snapshot_path": "sources/894acd7e4529f4fe6384ec4b4ffc3e4216647fa7f02bc5ed2de0c6f3049ae6cc.txt", "url": "https://api.github.com/repos/karimz1/imgcompress/license"}, {"fetched_at": "2026-10-28T10:41:21.275871+08:00", "kind": "documentation", "sha256": "89a65b9d89ae6e42c0f96d3cb738f80bc1cb93f19497a7e1a3d045a6ad5d9b7c", "snapshot_path": "sources/89a65b9d89ae6e42c0f96d3cb738f80bc1cb93f19497a7e1a3d045a6ad5d9b7c.txt", "url": "https://imgcompress.karimzouine.com/docs/web-ui"}], "summary": "ImgCompress 是可自托管的图像批处理 Web 服务：在浏览器中一次拖入多张图片、统一设置裁剪/缩放/质量/输出格式后，由容器内服务端逐图执行并打包下载结果。", "technology_stack": ["TypeScript", "Docker", "Web UI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1006414368','OpenCut','{"deployment": ["Web 应用，在浏览器中运行，官方托管入口为 opencut.app", "同一代码库规划 Web、桌面与移动端；桌面端仍处于早期"], "features": ["主视频轨、覆盖层轨与音频轨组成的分层时间线", "剪辑修剪、分割、跨轨移动、多选同时移动与缩放", "波纹编辑与撤销后恢复原片段位置和长度", "逐剪辑效果、蒙版、关键帧与图形编辑器", "项目、素材面板与项目缩略图", "浏览器内预览播放并导出含音频的 MP4"], "github_repository_id": 1006414368, "homepage": "https://opencut.app", "id": "github:1006414368", "leaf_matches": [{"reason": "官方首页正文把 OpenCut 描述为在浏览器中运行的视频编辑器并提供 Projects 与编辑器入口（/editor、/projects 均返回 200），构成可持续使用的在线应用服务，而非客户端壳或渲染引擎。README 说明其为 Web/桌面/移动端视频编辑器，当前 opencut.app 运行经典版。0.3.0 变更日志（仓库与官网同文）说明时间线包含主线视频轨、覆盖层轨与音频轨，剪辑可修剪、分割、多选同时移动/缩放，并有逐剪辑效果、关键帧与预览缩放；0.2.0 说明波纹编辑、修剪把手，以及撤销修剪后恢复原片段位置和长度，表明编辑作用于引用而非源文件。导出证据为“MP4 exports with audio”，在浏览器内完成。项目为持久容器：Projects 路由、项目缩略图与项目设置，且应用会请求浏览器保护项目存储。仓库身份（id 1006414368、full_name）与完整 MIT 许可证由元数据及许可证接口正文证明。", "slug": "non-linear-editing-system-nle", "source_urls": ["https://api.github.com/repos/OpenCut-app/OpenCut", "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/README.md", "https://api.github.com/repos/OpenCut-app/OpenCut/license", "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/changelog/0.3.0.md", "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/changelog/0.2.0.md", "https://opencut.app", "https://opencut.app/changelog"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/OpenCut-app/OpenCut/license", "name": "OpenCut", "repository_url": "https://github.com/OpenCut-app/OpenCut", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:07:07.327816+08:00", "kind": "repository_metadata", "sha256": "4dd2f04e612b28c6780abc778c55756fc780d27f7753f2444d7880f812642346", "snapshot_path": "sources/4dd2f04e612b28c6780abc778c55756fc780d27f7753f2444d7880f812642346.txt", "url": "https://api.github.com/repos/OpenCut-app/OpenCut"}, {"fetched_at": "2026-10-28T13:07:06.986578+08:00", "kind": "readme", "sha256": "95ccfeb63ebca77afdde080e2923b5f29b680db6b42a9be8b9098ea7ba25c050", "snapshot_path": "sources/95ccfeb63ebca77afdde080e2923b5f29b680db6b42a9be8b9098ea7ba25c050.txt", "url": "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/README.md"}, {"fetched_at": "2026-10-28T13:07:07.282684+08:00", "kind": "license", "sha256": "b4f5f7f5b3cd7790882650c48345ed937e90bfafcd36bfd6262f833c262f8daf", "snapshot_path": "sources/b4f5f7f5b3cd7790882650c48345ed937e90bfafcd36bfd6262f833c262f8daf.txt", "url": "https://api.github.com/repos/OpenCut-app/OpenCut/license"}, {"fetched_at": "2026-10-28T13:07:07.287169+08:00", "kind": "documentation", "sha256": "25ff04cb5f06fee34c4a29fa355e8df1de17f4c0df276dc2d2f4166ea651dad2", "snapshot_path": "sources/25ff04cb5f06fee34c4a29fa355e8df1de17f4c0df276dc2d2f4166ea651dad2.txt", "url": "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/changelog/0.3.0.md"}, {"fetched_at": "2026-10-28T13:08:52.706435+08:00", "kind": "documentation", "sha256": "724c2c9679dd592ad4e0bde62f4e5cecb712e2f286881242bb01ff50e8606072", "snapshot_path": "sources/724c2c9679dd592ad4e0bde62f4e5cecb712e2f286881242bb01ff50e8606072.txt", "url": "https://raw.githubusercontent.com/OpenCut-app/OpenCut/main/changelog/0.2.0.md"}, {"fetched_at": "2026-10-28T13:07:25.600091+08:00", "kind": "homepage", "sha256": "c0d216eb89616b59c442f7d321fcd2fb04b65e8fd17e0fc83806685efe148243", "snapshot_path": "sources/c0d216eb89616b59c442f7d321fcd2fb04b65e8fd17e0fc83806685efe148243.txt", "url": "https://opencut.app"}, {"fetched_at": "2026-10-28T13:08:30.932751+08:00", "kind": "documentation", "sha256": "53cb0d6957a9140f0592da9a9a60fa2c9110c773603ac6fe545d79bf466059ab", "snapshot_path": "sources/53cb0d6957a9140f0592da9a9a60fa2c9110c773603ac6fe545d79bf466059ab.txt", "url": "https://opencut.app/changelog"}], "summary": "OpenCut 是浏览器内运行的开源非线性剪辑应用：素材进入持久项目，在主视频轨与覆盖/音频轨组成的时间线上任意排列、修剪与分层合成，浏览器内预览后导出 MP4 成品；官方在 opencut.app 提供在线入口。", "technology_stack": ["TypeScript", "React", "Rust", "WebAssembly"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1097654343','FreeCut','{"deployment": ["托管 Web 应用：https://www.freecut.net 打开即用，无需安装", "本地运行：npm install && npm run dev，打开 http://localhost:5173", "需要支持 WebGPU/WebCodecs 的现代 Chromium 浏览器"], "features": ["多轨时间线，支持视频、音频、文字、图像、形状、遮罩与复合剪辑", "链接音视频的分离/合并、波纹、滚动、滑移、滑行与变速工具", "源监视器标记入出点、插入与覆盖编辑，转场与关键帧动画", "实时预览、静帧缩略图、立体声波形、标记与撤销/重做", "按项目工作区文件夹持久化，支持项目 ZIP 打包导入导出与媒体重链接", "浏览器内导出 MP4/WebM/MOV/MKV（H.264/H.265/VP8/VP9/AV1，视浏览器编码器），可选分辨率、帧率与码率，导出任意序列"], "github_repository_id": 1097654343, "homepage": "https://www.freecut.net", "id": "github:1097654343", "leaf_matches": [{"reason": "官方 README 说明这是运行在浏览器内的多轨视频编辑器：选择工作区文件夹并创建项目，拖入素材，将剪辑放到时间线后修剪、排列、加效果/转场/字幕与音频处理，实时预览并在浏览器内导出 MP4/WebM/MOV/MKV。素材以独立剪辑寻址、时间线分层任意排列、渲染导出三项有直接正文；非破坏性与项目持久性亦有正文：导入“不复制原始文件”，项目与媒体元数据以纯文件保存于用户选定文件夹，代理不替换原始素材并支持媒体重链接。托管站点 freecut.net 与本地运行方式提供可持续使用的应用服务形态。", "slug": "video-editor", "source_urls": ["https://github.com/walterlow/freecut", "https://raw.githubusercontent.com/walterlow/freecut/main/README.md", "https://api.github.com/repos/walterlow/freecut/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/walterlow/freecut/license", "name": "FreeCut", "repository_url": "https://github.com/walterlow/freecut", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:41:33.998935+08:00", "kind": "repository_metadata", "sha256": "8c90196a10cf76eb976c740d19f59ebd47e74cb2b7010d96f07ad3032cebf0d8", "snapshot_path": "sources/8c90196a10cf76eb976c740d19f59ebd47e74cb2b7010d96f07ad3032cebf0d8.txt", "url": "https://github.com/walterlow/freecut"}, {"fetched_at": "2026-10-28T10:41:29.044448+08:00", "kind": "readme", "sha256": "9ca1333077a340de90cea2758d1928045d01c995443b1098c1110524270ab6f7", "snapshot_path": "sources/9ca1333077a340de90cea2758d1928045d01c995443b1098c1110524270ab6f7.txt", "url": "https://raw.githubusercontent.com/walterlow/freecut/main/README.md"}, {"fetched_at": "2026-10-28T10:41:31.222576+08:00", "kind": "license", "sha256": "a820317d21dc27538e8a6b45eb58091491ea3388392326bbe0de047e6a833e5c", "snapshot_path": "sources/a820317d21dc27538e8a6b45eb58091491ea3388392326bbe0de047e6a833e5c.txt", "url": "https://api.github.com/repos/walterlow/freecut/license"}, {"fetched_at": "2026-10-28T10:41:38.845832+08:00", "kind": "homepage", "sha256": "943affdf6a74d1d9e189f7244586e070aa000a9cdc30e6f439da1a43aa38137d", "snapshot_path": "sources/943affdf6a74d1d9e189f7244586e070aa000a9cdc30e6f439da1a43aa38137d.txt", "url": "https://www.freecut.net"}], "summary": "FreeCut 是纯浏览器运行的开源多轨视频编辑器：项目与素材保存在本地工作区，剪辑在时间线上修剪、排列并叠加视频/音频/文字/图像，实时预览后经 WebCodecs 导出 MP4、WebM、MOV、MKV 成片；MIT 许可。", "technology_stack": ["React", "TypeScript", "WebGPU", "WebCodecs", "OPFS", "File System Access API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1137441048','OpenReel Video','{"deployment": ["托管 Web 应用：https://openreel.video 直接打开编辑器使用", "可自托管：pnpm install && pnpm dev 运行本地 Web 版", "桌面版（macOS/Windows/Linux）发布构建，当前为 alpha"], "features": ["多轨时间线：素材导入后拖动剪辑，修剪、分割、裁剪、波纹删除、重排与变速", "视频、音频、文字与图形分层叠加，支持转场与关键帧动画", "实时预览与字幕样式、SRT 导入、标题动画", "音频波形、音量、淡入淡出与混音控制", "浏览器内导出 MP4/H.264、WebM，可选分辨率、帧率与码率；桌面版支持原生 FFmpeg 导出", "项目自动保存、撤销/重做、项目文件导入导出与可移植 JSON 编辑文档"], "github_repository_id": 1137441048, "homepage": "https://openreel.video", "id": "github:1137441048", "leaf_matches": [{"reason": "官方 README 说明这是浏览器与桌面的视频编辑器：打开 openreel.video 创建项目、导入素材并把剪辑拖到时间线，经修剪/分割/裁剪/波纹删除/重排与多轨叠加字幕、图形、音频，实时预览后导出 MP4/WebM 成片；素材以独立剪辑寻址、时间线分层任意排列、渲染导出三项有直接正文。项目持久性与非破坏性由官方文档支撑：编辑文档以稳定元素 ID 与本地媒体引用序列化，导入先校验再把整个编辑作为一次撤销步骤替换，缺失文件成为显式占位并可重新链接，撤销/重做与本地自动保存保留编辑历史。托管 Web 版与自托管方式提供可持续使用的应用服务形态。", "slug": "video-editor", "source_urls": ["https://github.com/Augani/openreel-video", "https://raw.githubusercontent.com/Augani/openreel-video/main/README.md", "https://raw.githubusercontent.com/Augani/openreel-video/main/docs/ai-editing.md", "https://api.github.com/repos/Augani/openreel-video/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Augani/openreel-video/license", "name": "OpenReel Video", "repository_url": "https://github.com/Augani/openreel-video", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T10:40:20.112675+08:00", "kind": "repository_metadata", "sha256": "2fbceac07292b7eccaaf972b88591f0ed4a4d522dabb76197387ff84c537a093", "snapshot_path": "sources/2fbceac07292b7eccaaf972b88591f0ed4a4d522dabb76197387ff84c537a093.txt", "url": "https://github.com/Augani/openreel-video"}, {"fetched_at": "2026-10-28T10:40:17.836335+08:00", "kind": "readme", "sha256": "3c0f6e40b85b2dfcaef7f8427e7e723acd9621655a70258c15e7eb4addf805f9", "snapshot_path": "sources/3c0f6e40b85b2dfcaef7f8427e7e723acd9621655a70258c15e7eb4addf805f9.txt", "url": "https://raw.githubusercontent.com/Augani/openreel-video/main/README.md"}, {"fetched_at": "2026-10-28T10:40:19.526660+08:00", "kind": "license", "sha256": "ee8c5ed17a107dcfefc745324fa216f230f7fb5ee9d3e4ab9e4da7d1156990e2", "snapshot_path": "sources/ee8c5ed17a107dcfefc745324fa216f230f7fb5ee9d3e4ab9e4da7d1156990e2.txt", "url": "https://api.github.com/repos/Augani/openreel-video/license"}, {"fetched_at": "2026-10-28T10:43:33.324373+08:00", "kind": "documentation", "sha256": "519fb5586cbea9aaa6e4248285b60944ffcfba8087df33b4ddd54f904c9e5d71", "snapshot_path": "sources/519fb5586cbea9aaa6e4248285b60944ffcfba8087df33b4ddd54f904c9e5d71.txt", "url": "https://raw.githubusercontent.com/Augani/openreel-video/main/docs/ai-editing.md"}, {"fetched_at": "2026-10-28T10:39:06.114653+08:00", "kind": "homepage", "sha256": "8bf350fe0f19b250daaf30a466e21910b0a4e59570b4fde4b5f2cff6d1639c9c", "snapshot_path": "sources/8bf350fe0f19b250daaf30a466e21910b0a4e59570b4fde4b5f2cff6d1639c9c.txt", "url": "https://openreel.video"}], "summary": "OpenReel Video 是浏览器与桌面两用的开源视频编辑器：在 Web 应用中创建项目、导入素材为剪辑，于多轨时间线上修剪/分割/排列并叠加字幕与图层，实时预览后导出 MP4/WebM 成片；MIT 许可，可自托管。", "technology_stack": ["React", "TypeScript", "Zustand", "WebCodecs", "WebGPU", "MediaBunny", "Electron"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:jitter','Jitter','{"homepage": "https://jitter.video/", "id": "commercial:jitter", "leaf_matches": [{"reason": "官方首页正文称其为难以上手即用的在线动效设计工具（“A fast and simple motion design tool on the web”“create stunning animations online”），提供设计并动画化图层与文字、沿路径运动、渐变与模糊等功能，并支持导出 4K、GIF、Lottie，对应构图、参数化动画与渲染成动态图像交付。仅记录基本用途与官网来源，不涉及价格、架构或部署。", "slug": "motion-graphics-application", "source_urls": ["https://jitter.video/"]}], "name": "Jitter", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:06:50.451324+08:00", "kind": "homepage", "sha256": "7ae814c3732fa590cb295d5138dffd4d5d965d225416cecaa7b3a35db0db7253", "snapshot_path": "sources/7ae814c3732fa590cb295d5138dffd4d5d965d225416cecaa7b3a35db0db7253.txt", "url": "https://jitter.video/"}], "summary": "Jitter 是浏览器内使用的商业动态设计工具：从 Figma 导入或直接设计，为图形、文字与媒体元素制作动画，并导出为 4K 视频、GIF 或 Lottie。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:530393473','Motionity','{"deployment": ["Web 应用，在浏览器中运行，无需安装", "官方站点 motionity.app 提供在线使用入口，README 说明无需登录", "桌面浏览器使用；官网提示未针对移动端优化"], "features": ["带自定义缓动的关键帧动画", "图层与时间线编辑，支持图层遮罩", "文字动画（打字机、缩放、淡入淡出等）", "图片与视频滤镜（调整、模糊、色度键等）", "素材搜索与拖放（Pixabay 集成），支持 Lottie 导入", "下载为 WEBM 视频、动图 GIF 或图片，并可导入/导出工程文件"], "github_repository_id": 530393473, "homepage": "https://motionity.app", "id": "github:530393473", "leaf_matches": [{"reason": "README 明确称其为“web-based motion graphics editor”“free and open source animation editor in the web”，并列出带自定义缓动的关键帧动画、图层遮罩、文字动画、滤镜与 Lottie 导入；官网应用界面正文包含图层（LAYERS）、时间线、关键帧属性、播放控制、画布尺寸与时长设置，以及下载设置中的 WEBM 视频、动图 GIF、图片格式，对应“图形构图 + 元素属性随时间的参数化动画 + 应用内预览 + 渲染成动态图像交付”。仓库身份（id 530393473，full_name alyssaxuu/motionity）与 MIT 许可证分别由仓库元数据和许可证接口证明。形态为浏览器内运行的完整 Web 应用，非桌面客户端或 SDK。", "slug": "motion-graphics-application", "source_urls": ["https://api.github.com/repos/alyssaxuu/motionity", "https://raw.githubusercontent.com/alyssaxuu/motionity/master/README.md", "https://api.github.com/repos/alyssaxuu/motionity/license", "https://www.motionity.app/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/alyssaxuu/motionity/license", "name": "Motionity", "repository_url": "https://github.com/alyssaxuu/motionity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:05:31.403334+08:00", "kind": "repository_metadata", "sha256": "f470305d2c407ca52e37ef328a67a2550625db9108e5db5b8f7b2e65ba99a11a", "snapshot_path": "sources/f470305d2c407ca52e37ef328a67a2550625db9108e5db5b8f7b2e65ba99a11a.txt", "url": "https://api.github.com/repos/alyssaxuu/motionity"}, {"fetched_at": "2026-10-28T13:05:32.851869+08:00", "kind": "readme", "sha256": "d3895c3eac7360e545873fc2ebd2d9d55462ed3bbeefddd483da1cd762ff1ac7", "snapshot_path": "sources/d3895c3eac7360e545873fc2ebd2d9d55462ed3bbeefddd483da1cd762ff1ac7.txt", "url": "https://raw.githubusercontent.com/alyssaxuu/motionity/master/README.md"}, {"fetched_at": "2026-10-28T13:05:35.747964+08:00", "kind": "license", "sha256": "e0cc873d067f1029ed4dcd4e705e9c4bd73608dc6d7dea307a82fb10d8ef8c1d", "snapshot_path": "sources/e0cc873d067f1029ed4dcd4e705e9c4bd73608dc6d7dea307a82fb10d8ef8c1d.txt", "url": "https://api.github.com/repos/alyssaxuu/motionity/license"}, {"fetched_at": "2026-10-28T13:06:13.960421+08:00", "kind": "homepage", "sha256": "c4f6a5d5bbf671980e10d692ef09de3a17183fcc2a032459bc08fc9a8de9df4b", "snapshot_path": "sources/c4f6a5d5bbf671980e10d692ef09de3a17183fcc2a032459bc08fc9a8de9df4b.txt", "url": "https://www.motionity.app/"}], "summary": "Motionity 是开源、浏览器内运行的动态图形编辑器：在图层/时间线中组合文字、图形、图片与视频元素，用关键帧和自定义缓动动画化元素属性，可预览运动效果，并下载为 WEBM 视频、动图 GIF 或图片；官网即在线使用入口，README 说明免费且无需登录。", "technology_stack": ["JavaScript", "HTML/CSS", "Fabric.js", "jQuery"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1203642171','Open Live','{"deployment": ["自托管三仓库，许可证分别核对：open-live MIT（API 服务）、open-live-studio MIT（浏览器控制台）、Strom Apache-2.0（仓库同时提供 LICENSE-APACHE 与 LICENSE-MIT，README 标注 MIT OR Apache-2.0）", "组件边界：本仓库仅暴露 REST API 与 WebSocket 控制器通道，不含媒体处理；缺 open-live-studio 则“只有 API 没有控制面”，缺 Strom 则无切换/混合/编码", "需要 CouchDB 保存制作、源与配置；提供 Docker 与 docker-compose", "托管版运行于 Open Source Cloud（openlive.apps.osaas.io 为托管演示实例）：官方正文未描述按功能分层的付费版，托管与自托管的差别在于 Strom/GPU 的供给方式（共享 GPU 或自建 Strom）与 OSC 参数存储、反向代理，代码同源；OSC 目录中的 eyevinn-strom 实例不被支持作为后端"], "features": ["视觉切换（由 Strom 执行）：cuts、自动转场、DSK 图层、画中画、图形叠加与 fade-to-black", "每制作最多 16 路源，支持 SRT、EFP、WHIP 与 HTML 源，另含内置测试图", "图形叠加：HTML/图片经 DSK 键控叠加到节目画面，支持 OGraf 模板 URL", "音频调音台：每通道推子与 EBU R128 响度计量", "多画面监看（multiviewer），浏览器内低延迟监看", "输出：录制（含 ISO 输入录制）、SRT 与 WHEP 端点", "制作生命周期管理：激活/停用制作，按源/输出/图形配置生成 Strom 媒体流程"], "github_repository_id": 1203642171, "homepage": "https://openlive.apps.osaas.io", "id": "github:1203642171", "leaf_matches": [{"reason": "README 将其定义为浏览器实时制作套件：视觉切换台（cuts、自动转场、DSK、画中画、fade-to-black）、每制作最多 16 路源（SRT/EFP/WHIP/HTML 输入）、音频调音台与多画面监看；同文明确本仓库只是 API 服务，切换/混合/图形合成与节目、多画面编码由 Strom 媒体引擎执行，open-live-studio 为浏览器控制台，三仓库均为独立开源项目（MIT / MIT / Apache-2.0，Strom 另提供 MIT 文本）。图形文档说明 HTML/图片经下游键控（DSK）实时叠加到节目画面。组合体具备多路实时源、操作员实时混合与持续节目输出，且为可自托管的服务端应用。仅就 README/ADR 已实现的 SRT/WHEP/录制输出作匹配，不采用 ADR-004 中尚未完成的 RTMP 多目的地能力。", "slug": "video-compositing-application", "source_urls": ["https://api.github.com/repos/Eyevinn/open-live", "https://raw.githubusercontent.com/Eyevinn/open-live/main/README.md", "https://api.github.com/repos/Eyevinn/open-live/license", "https://raw.githubusercontent.com/Eyevinn/open-live/main/docs/decisions/ADR-004-rtmp-multi-destination.md", "https://raw.githubusercontent.com/Eyevinn/open-live/main/docs/graphics.md", "https://api.github.com/repos/Eyevinn/open-live-studio", "https://api.github.com/repos/Eyevinn/open-live-studio/license", "https://raw.githubusercontent.com/Eyevinn/open-live-studio/main/README.md", "https://api.github.com/repos/Eyevinn/strom", "https://api.github.com/repos/Eyevinn/strom/license", "https://raw.githubusercontent.com/Eyevinn/strom/main/LICENSE-MIT", "https://raw.githubusercontent.com/Eyevinn/strom/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/Eyevinn/open-live/license", "name": "Open Live", "repository_url": "https://github.com/Eyevinn/open-live", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:15:05.605286+08:00", "kind": "repository_metadata", "sha256": "8bf40cddc5fd19222a7734102a15bd703bff482f558d70a35ed6a1202d8d8255", "snapshot_path": "sources/8bf40cddc5fd19222a7734102a15bd703bff482f558d70a35ed6a1202d8d8255.txt", "url": "https://api.github.com/repos/Eyevinn/open-live"}, {"fetched_at": "2026-10-28T13:15:07.223870+08:00", "kind": "readme", "sha256": "4d334e9027609531b3d01a5abd61da861a3dc510a6a2160ea78d31bbd4c5c611", "snapshot_path": "sources/4d334e9027609531b3d01a5abd61da861a3dc510a6a2160ea78d31bbd4c5c611.txt", "url": "https://raw.githubusercontent.com/Eyevinn/open-live/main/README.md"}, {"fetched_at": "2026-10-28T13:15:09.521774+08:00", "kind": "license", "sha256": "aa2fd6cfa7a3a387127c728ae581b57f58e6c5de8f20fe6a75937a6de210d2e0", "snapshot_path": "sources/aa2fd6cfa7a3a387127c728ae581b57f58e6c5de8f20fe6a75937a6de210d2e0.txt", "url": "https://api.github.com/repos/Eyevinn/open-live/license"}, {"fetched_at": "2026-10-28T13:16:08.032485+08:00", "kind": "documentation", "sha256": "f52fc86333250146d4d1ded286ea0b2987a147be623288b03fb6d14b93fd0be8", "snapshot_path": "sources/f52fc86333250146d4d1ded286ea0b2987a147be623288b03fb6d14b93fd0be8.txt", "url": "https://raw.githubusercontent.com/Eyevinn/open-live/main/docs/decisions/ADR-004-rtmp-multi-destination.md"}, {"fetched_at": "2026-10-28T13:16:09.553411+08:00", "kind": "documentation", "sha256": "13e820501599a0a1b6d9f3ad8e6a13204de8ecf180f8ce806615364d17ccefba", "snapshot_path": "sources/13e820501599a0a1b6d9f3ad8e6a13204de8ecf180f8ce806615364d17ccefba.txt", "url": "https://raw.githubusercontent.com/Eyevinn/open-live/main/docs/graphics.md"}, {"fetched_at": "2026-10-28T13:27:49.552131+08:00", "kind": "repository_metadata", "sha256": "827c11f33ab922e9383c4dc507c9512711979a8ced9fdba74791352dbd9723c6", "snapshot_path": "sources/827c11f33ab922e9383c4dc507c9512711979a8ced9fdba74791352dbd9723c6.txt", "url": "https://api.github.com/repos/Eyevinn/open-live-studio"}, {"fetched_at": "2026-10-28T13:27:51.061440+08:00", "kind": "license", "sha256": "3b28ae148e299a135ec400a5c5ae44cd6929c58987b5145e5b28241ed28f69c4", "snapshot_path": "sources/3b28ae148e299a135ec400a5c5ae44cd6929c58987b5145e5b28241ed28f69c4.txt", "url": "https://api.github.com/repos/Eyevinn/open-live-studio/license"}, {"fetched_at": "2026-10-28T13:29:16.849630+08:00", "kind": "readme", "sha256": "9d515709c911e48cf90e6b3d86d7ed49dc08dd8e0143944b6d876e9cd0063f6d", "snapshot_path": "sources/9d515709c911e48cf90e6b3d86d7ed49dc08dd8e0143944b6d876e9cd0063f6d.txt", "url": "https://raw.githubusercontent.com/Eyevinn/open-live-studio/main/README.md"}, {"fetched_at": "2026-10-28T13:27:50.000711+08:00", "kind": "repository_metadata", "sha256": "52a64a374417fc9dc47040e8a6dbe3689a483a571d491ad3fcf1ee6ac15ef2e6", "snapshot_path": "sources/52a64a374417fc9dc47040e8a6dbe3689a483a571d491ad3fcf1ee6ac15ef2e6.txt", "url": "https://api.github.com/repos/Eyevinn/strom"}, {"fetched_at": "2026-10-28T13:27:51.850113+08:00", "kind": "license", "sha256": "a839eb741c6a0a8595ae7499cbc4614eca1dcfb955b81dea4f07f66f5307ae3c", "snapshot_path": "sources/a839eb741c6a0a8595ae7499cbc4614eca1dcfb955b81dea4f07f66f5307ae3c.txt", "url": "https://api.github.com/repos/Eyevinn/strom/license"}, {"fetched_at": "2026-10-28T13:31:47.144297+08:00", "kind": "license", "sha256": "fec3c80e37396c760e68c742cc83816cc7558a5fd314088e50d35cacc847facf", "snapshot_path": "sources/fec3c80e37396c760e68c742cc83816cc7558a5fd314088e50d35cacc847facf.txt", "url": "https://raw.githubusercontent.com/Eyevinn/strom/main/LICENSE-MIT"}, {"fetched_at": "2026-10-28T13:29:34.346165+08:00", "kind": "readme", "sha256": "829f447ebd5e05a36d7858f5859e09ff4d658c5043980fcb8bbf3b7899a5a571", "snapshot_path": "sources/829f447ebd5e05a36d7858f5859e09ff4d658c5043980fcb8bbf3b7899a5a571.txt", "url": "https://raw.githubusercontent.com/Eyevinn/strom/main/README.md"}], "summary": "Open Live 是开源的浏览器实时制作套件，由三个独立仓库组成：open-live（MIT，本条目，Node.js/Fastify API 服务）、open-live-studio（MIT，React 浏览器控制台）与 Strom（Apache-2.0，另含 MIT 双许可文本，GStreamer 媒体引擎）。视觉切换、混合、图形合成与节目编码实际由 Strom 执行，本仓库只负责制作配置、源/输出/图形编排与控制器通道；操作员在浏览器控制台完成切换、转场与叠图，节目输出到录制、SRT、WHEP 与多画面监看。", "technology_stack": ["TypeScript", "Node.js", "Fastify", "CouchDB", "GStreamer", "WebRTC", "SRT"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1266672576','SwitchFrame','{"deployment": ["自托管：单个 Go 二进制，内嵌 SvelteKit 控制台，systemd/Nomad 进程监管", "浏览器通过 QUIC/WebTransport 连接服务器，操作员登录后使用", "提供 Docker 与 Dockerfile.cuda 构建", "仓库文档仍以 https://github.com/zsiec/switchframe.git 作为克隆地址与 CI 徽章目标；该地址在 2026-10-28 核对时返回 404，本条目以实际托管代码的 thiagopnts/switchframe 及其仓库 id 为准，不据徽章文字另立条目"], "features": ["多路实时源：SRT 输入（listener/caller）、MoQ 摄像头、MXL 共享内存、文件片段与播放通道", "切换与转场：cut、mix、dip-to-black、六方向 wipe、stinger、手动 T-bar", "帧内合成：上游色度/亮度抠像、DVE、画中画与并排/四宫格布局、8 层下游键（DSK）图形叠加", "音频混合：每路推子、EQ、压缩、限幅与响度计量", "并发输出：MPEG-TS 录制、SRT（push/pull）与 RTMP 目的地、MXL 基带输出与浏览器节目监看", "浏览器控制台与多操作员角色（导播/音频/图形/观看）"], "github_repository_id": 1266672576, "homepage": "https://github.com/thiagopnts/switchframe", "id": "github:1266672576", "leaf_matches": [{"reason": "README 说明该产品由服务端完成全部切换、混合、合成与编码，浏览器仅作为控制面：源经 SRT/MoQ/MXL 进入，具备 cut/mix/dip/wipe/stinger 转场、上游抠像、画中画与并排布局、8 层 DSK 图形叠加，输出到 MPEG-TS 录制、SRT/RTMP 与浏览器监看。架构文档描述节目扇出路径（program relay、MPEG-TS muxer、MXL），部署文档说明以单二进制自托管、操作员从浏览器登录控制台，满足“多个实时源 + 操作员实时混合 + 持续节目 + 独立输出”的定义性核心，且为服务端应用而非纯桌面客户端。身份以仓库元数据 id=1266672576 与 full_name=thiagopnts/switchframe 为准；README 徽章与克隆地址仍写 zsiec/switchframe（该地址 404）、LICENSE 署名为 Thomas Symborski，提交记录显示全部提交作者为 GitHub 用户 zsiec，归属差异按研究记录留档，不据此把证据降级为他人镜像。", "slug": "video-compositing-application", "source_urls": ["https://api.github.com/repos/thiagopnts/switchframe", "https://raw.githubusercontent.com/thiagopnts/switchframe/main/README.md", "https://api.github.com/repos/thiagopnts/switchframe/license", "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/architecture.md", "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/operations/deployment.md", "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/reference/api/output.md", "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/concepts/pipeline.md", "https://api.github.com/repos/thiagopnts/switchframe/commits?per_page=30"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/thiagopnts/switchframe/license", "license_review": {"rationale": "LICENSE 端点返回 base64 编码的完整 MIT 文本（1073 字节，含授权、版权声明保留与免责条款），非摘要或 SPDX 字段；版权署名为 Copyright (c) 2026 Thomas Symborski，与 README/CI 指向的 zsiec 一致而与仓库当前 owner 不同，归属差异已在研究记录留档。", "reviewer": "open-design/deepseek-v4.1-flash unit-32 correction", "scope": "repository", "source_url": "https://api.github.com/repos/thiagopnts/switchframe/license", "spdx_id": "MIT"}, "name": "SwitchFrame", "repository_url": "https://github.com/thiagopnts/switchframe", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:12:35.725101+08:00", "kind": "repository_metadata", "sha256": "f357131cf9e6476b3140b21f9ef4ee1a443d5c0ae3d11a4e0e444576bbb78537", "snapshot_path": "sources/f357131cf9e6476b3140b21f9ef4ee1a443d5c0ae3d11a4e0e444576bbb78537.txt", "url": "https://api.github.com/repos/thiagopnts/switchframe"}, {"fetched_at": "2026-10-28T13:12:35.586145+08:00", "kind": "readme", "sha256": "b29aeb323161037ce4f656cb3981166c72b0b69db0a71898c0e9fe57dde5b335", "snapshot_path": "sources/b29aeb323161037ce4f656cb3981166c72b0b69db0a71898c0e9fe57dde5b335.txt", "url": "https://raw.githubusercontent.com/thiagopnts/switchframe/main/README.md"}, {"fetched_at": "2026-10-28T13:12:51.385192+08:00", "kind": "license", "sha256": "6365c8743cdb0c4a0a77405a7f87541d57ada118966868d5ea97531c43c7f320", "snapshot_path": "sources/6365c8743cdb0c4a0a77405a7f87541d57ada118966868d5ea97531c43c7f320.txt", "url": "https://api.github.com/repos/thiagopnts/switchframe/license"}, {"fetched_at": "2026-10-28T13:12:53.102086+08:00", "kind": "documentation", "sha256": "6de9e95b0821056b821a83f6f3e64a33aa85e08fb4d36ec0a80606c143b45b34", "snapshot_path": "sources/6de9e95b0821056b821a83f6f3e64a33aa85e08fb4d36ec0a80606c143b45b34.txt", "url": "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/architecture.md"}, {"fetched_at": "2026-10-28T13:12:54.461459+08:00", "kind": "documentation", "sha256": "ac52648665a997f07cc1ec26000927114bd353916f48f2389aac99f030885d6b", "snapshot_path": "sources/ac52648665a997f07cc1ec26000927114bd353916f48f2389aac99f030885d6b.txt", "url": "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/operations/deployment.md"}, {"fetched_at": "2026-10-28T13:13:46.135817+08:00", "kind": "documentation", "sha256": "90b440962a47eb65b2fb088f62197b69bee94ff3f4b04f4f3df82ac77f10dd63", "snapshot_path": "sources/90b440962a47eb65b2fb088f62197b69bee94ff3f4b04f4f3df82ac77f10dd63.txt", "url": "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/reference/api/output.md"}, {"fetched_at": "2026-10-28T13:13:48.429282+08:00", "kind": "documentation", "sha256": "b3368edbc31780e4bd356a1a2fe8d3267c3bf41d85f15f458cd701667908670a", "snapshot_path": "sources/b3368edbc31780e4bd356a1a2fe8d3267c3bf41d85f15f458cd701667908670a.txt", "url": "https://raw.githubusercontent.com/thiagopnts/switchframe/main/docs/concepts/pipeline.md"}, {"fetched_at": "2026-10-28T13:31:49.848154+08:00", "kind": "documentation", "sha256": "0110f71f2a7b99cd6aea1a4e9ad4d9fca52f4efe3d01522687244e35c7e9a7e4", "snapshot_path": "sources/0110f71f2a7b99cd6aea1a4e9ad4d9fca52f4efe3d01522687244e35c7e9a7e4.txt", "url": "https://api.github.com/repos/thiagopnts/switchframe/commits?per_page=30"}], "summary": "SwitchFrame 是自托管的浏览器控制实时视频切换台：服务端完成多路源的切换、转场、抠像与合成并编码为持续节目，操作员在浏览器控制台完成导播，节目同时输出到录制、SRT/RTMP 目的地、MXL 基带与浏览器监看。代码现行托管于 thiagopnts/switchframe（仓库 id 1266672576）；仓库自带的 README 徽章、git clone 地址与 LICENSE 署名仍指向 zsiec/switchframe 与 Thomas Symborski（GitHub 用户 zsiec），该地址已不可访问，归属与发布主体核对结果见研究记录。", "technology_stack": ["Go", "SvelteKit", "TypeScript", "FFmpeg", "QUIC/WebTransport", "SRT", "RTMP"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:728438436','Mesh2Motion','{"deployment": ["浏览器 Web 应用（app.mesh2motion.org）", "Node.js 本地开发服务器（npm run dev）", "Docker / docker-compose 自托管"], "features": ["浏览器内导入 GLB/GLTF 模型，选择人形、鸟、龙、马、鱼等骨架模板并将骨骼调整到贴合模型", "自动绑定后可从内置动作库试播并挑选动画，也支持导入外部动画测试兼容性", "一次导出多个动画，打包为单个 GLB 或 FBX（官网 Feature Highlights 表述；仓库 README 的 Usage 一节当前仍写「currently only GLB/GLTF supported format」，两者差异未进一步核实，故不作为确定能力外推）", "提供 Docker 部署方式，目录内 docker-compose up -d 后经 localhost:3000 使用"], "github_repository_id": 728438436, "homepage": "https://mesh2motion.org/", "id": "github:728438436", "leaf_matches": [{"reason": "官网正文以角色/生物为单位描述完整流程：Import, Rig, Animate, then Export；上传模型后自动放置骨骼并按人形、龙、鸟、马等骨架模板绑定，随后套用或导入动作并在浏览器中预览，最后把多个动画打包导出为 GLB/FBX 运行时动画数据。README 给出同一流程与 Docker 自托管方式，属可持续使用的完整 Web 应用服务。已绘/建模的角色外观为导入对象、运动由绑定骨架驱动、交付为运行时动画数据，符合角色动画应用的核心与重心。运动主要来自预备动作库而非逐帧关键帧，属于定义允许的「应用预备好的动作」，不外推未取证的关键帧界面。", "slug": "character-animation-application", "source_urls": ["https://mesh2motion.org/", "https://raw.githubusercontent.com/Mesh2Motion/mesh2motion-app/main/README.md", "https://app.mesh2motion.org/"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/Mesh2Motion/mesh2motion-app/main/LICENSE-MIT.MD", "license_review": {"rationale": "根目录 LICENSE-MIT.MD 为完整 MIT 全文（含 Permission is hereby granted... 与 THE SOFTWARE IS PROVIDED 免责段），README 的 Licenses 段亦明确代码与平台采用 MIT；GitHub license API 将该仓库标为 Other/NOASSERTION，故以原文人工核对而非 API 自动分类。该声明仅覆盖代码，3D 素材另在 mesh2motion-assets 以 CC0 发布，不计入本条目。", "reviewer": "OpenDesign / DeepSeek V4.1 Flash, unit 36", "scope": "repository", "source_url": "https://raw.githubusercontent.com/Mesh2Motion/mesh2motion-app/main/LICENSE-MIT.MD", "spdx_id": "MIT"}, "name": "Mesh2Motion", "repository_url": "https://github.com/Mesh2Motion/mesh2motion-app", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:39:40.830007+08:00", "kind": "repository_metadata", "sha256": "a6cdd28abde1aee8a25d1a9614a9aa2f2b5a53e4d353036f8d28f4e08283c758", "snapshot_path": "sources/a6cdd28abde1aee8a25d1a9614a9aa2f2b5a53e4d353036f8d28f4e08283c758.txt", "url": "https://api.github.com/repos/Mesh2Motion/mesh2motion-app"}, {"fetched_at": "2026-10-28T13:40:33.219585+08:00", "kind": "readme", "sha256": "ce4a2c0cbb3227fadd43de2c4d63226507da0a6241646fb2ef966309300867b5", "snapshot_path": "sources/ce4a2c0cbb3227fadd43de2c4d63226507da0a6241646fb2ef966309300867b5.txt", "url": "https://raw.githubusercontent.com/Mesh2Motion/mesh2motion-app/main/README.md"}, {"fetched_at": "2026-10-28T13:41:49.909662+08:00", "kind": "license", "sha256": "a40dbdb297466562778a58864f075415c1414778a19176bd85091d0434094b1d", "snapshot_path": "sources/a40dbdb297466562778a58864f075415c1414778a19176bd85091d0434094b1d.txt", "url": "https://raw.githubusercontent.com/Mesh2Motion/mesh2motion-app/main/LICENSE-MIT.MD"}, {"fetched_at": "2026-10-28T13:39:39.145253+08:00", "kind": "homepage", "sha256": "6344424386b0559430c0a043d9796628a316b6b54a6017ffc3e880639f432120", "snapshot_path": "sources/6344424386b0559430c0a043d9796628a316b6b54a6017ffc3e880639f432120.txt", "url": "https://mesh2motion.org/"}, {"fetched_at": "2026-10-28T13:43:13.754456+08:00", "kind": "homepage", "sha256": "578a5953947b4aaad4474a3e688bb8715ede13267a3c606fce6e7255f3579401", "snapshot_path": "sources/578a5953947b4aaad4474a3e688bb8715ede13267a3c606fce6e7255f3579401.txt", "url": "https://app.mesh2motion.org/"}], "summary": "开源浏览器端角色动画应用：导入 GLB/GLTF 模型，套用可调整的人形或生物骨架完成自动绑定，从动作库挑选或导入动画，再打包导出为游戏引擎可用的 GLB/FBX；可本地构建并用 Docker 自托管运行。", "technology_stack": ["TypeScript", "Vite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:141853509','AudioMass','{"deployment": ["直接访问官方在线版本 https://audiomass.co/", "下载仓库后以 Go 或 Python 自带的简易静态服务器在本地运行"], "features": ["波形显示、缩放与平移导航", "基于选区的剪切、复制、粘贴、修剪、静音、反转与反相", "增益、淡入淡出、压缩、归一化、混响、延迟、失真与移调等处理", "标记点、节拍检测与吸附", "麦克风录音与多轨剪辑、混音", "导出为 mp3，并在浏览器内保留撤销历史", "可离线使用，无后端或框架依赖"], "github_repository_id": 141853509, "homepage": "https://audiomass.co/", "id": "github:141853509", "leaf_matches": [{"reason": "官方 about 页说明可加载已有音频或录音、在波形上缩放平移并选择区域，对该选区执行剪切、复制、粘贴、修剪、静音、反转与效果处理，导出为 mp3，并在浏览器内保留撤销历史；README 给出在线版本与自托管运行方式，构成已录制音频、波形、直接编辑与持久输出四项核心的完整 Web 应用。", "slug": "audio-editor", "source_urls": ["https://audiomass.co/about.html", "https://raw.githubusercontent.com/pkalogiros/AudioMass/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/pkalogiros/AudioMass/master/LICENSE", "license_review": {"rationale": "已读取仓库根目录完整 LICENSE 文本，含 MIT 标准授权段与免责声明，未被截断；文件开头同时说明项目原始代码采用 MIT、随附第三方库保留各自许可证，据此判定仓库主体代码许可证。", "reviewer": "OpenCode collection session (open-design/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/pkalogiros/AudioMass/master/LICENSE", "spdx_id": "MIT"}, "name": "AudioMass", "repository_url": "https://github.com/pkalogiros/AudioMass", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:37:38.473429+08:00", "kind": "repository_metadata", "sha256": "632efd085ece064bc87bc2bb9592f48c6fbd3e8a18212ac0d6dd03635acbdd08", "snapshot_path": "sources/632efd085ece064bc87bc2bb9592f48c6fbd3e8a18212ac0d6dd03635acbdd08.txt", "url": "https://github.com/pkalogiros/AudioMass"}, {"fetched_at": "2026-10-28T13:37:36.642641+08:00", "kind": "readme", "sha256": "b53adb7a23888e21e87eb277fe27f25dcc09d680c3c7e530bc182579062e678c", "snapshot_path": "sources/b53adb7a23888e21e87eb277fe27f25dcc09d680c3c7e530bc182579062e678c.txt", "url": "https://raw.githubusercontent.com/pkalogiros/AudioMass/master/README.md"}, {"fetched_at": "2026-10-28T13:37:36.554694+08:00", "kind": "license", "sha256": "1bf88bc3d6156fb15a07a5a9225bdf618c1296ddbff75c5fdcb2cbbf49510099", "snapshot_path": "sources/1bf88bc3d6156fb15a07a5a9225bdf618c1296ddbff75c5fdcb2cbbf49510099.txt", "url": "https://raw.githubusercontent.com/pkalogiros/AudioMass/master/LICENSE"}, {"fetched_at": "2026-10-28T13:37:49.649956+08:00", "kind": "documentation", "sha256": "6da60cb1539b9c33897b2fdb635340473a39a82223f9e1435d6f49fdd5d94151", "snapshot_path": "sources/6da60cb1539b9c33897b2fdb635340473a39a82223f9e1435d6f49fdd5d94151.txt", "url": "https://audiomass.co/about.html"}, {"fetched_at": "2026-10-28T13:37:49.032770+08:00", "kind": "homepage", "sha256": "f7f7dc0cffc41a117514bb349ed3c585bb95fa01fdea441be289632775e734d9", "snapshot_path": "sources/f7f7dc0cffc41a117514bb349ed3c585bb95fa01fdea441be289632775e734d9.txt", "url": "https://audiomass.co/"}], "summary": "开源浏览器音频编辑器：直接加载或录制声音，以波形显示振幅并在选区上剪切、复制、粘贴、修剪、静音、反转或应用效果，最后导出为音频文件；官方同时提供可在线使用的完整 Web 版本与可自托管的静态应用。", "technology_stack": ["JavaScript（原生，无框架）", "浏览器端静态应用，无后端依赖"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:auphonic','Auphonic','{"homepage": "https://auphonic.com", "id": "commercial:auphonic", "leaf_matches": [{"reason": "官方算法文档以 Auphonic Web Service 的上传处理流程描述修复循环：先分析并把信号分段分类为语音、音乐、不同背景噪声与静音，再用 Static/Dynamic Denoiser 或 Speech Isolation 等专用处理器抑制噪声、交流声与混响，Classic Denoiser 会为各段提取 noise print 并检测 50/60 Hz 交流声及谐波；官方还给出先不 leveling、不 gate、不压缩的使用纪律以保住噪声指纹，并提供移除量调节与修复前后试听示例，符合损伤分类、专用处理器、保留节目素材并输出修复音频的定义。", "slug": "audio-restoration-application", "source_urls": ["https://auphonic.com/features", "https://auphonic.com/help/algorithms/singletrack.html"]}], "name": "Auphonic", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:42:19.930042+08:00", "kind": "documentation", "sha256": "a776e7c3dd6500842313dc50bf3154813add8fed519d55121dcdd45a58bb2453", "snapshot_path": "sources/a776e7c3dd6500842313dc50bf3154813add8fed519d55121dcdd45a58bb2453.txt", "url": "https://auphonic.com/features"}, {"fetched_at": "2026-10-28T13:42:23.035636+08:00", "kind": "documentation", "sha256": "1254a4eb6a13ed2effdc8728e3179d5153f5a5aa9f4f327f5e1ca8e30aaaa700", "snapshot_path": "sources/1254a4eb6a13ed2effdc8728e3179d5153f5a5aa9f4f327f5e1ca8e30aaaa700.txt", "url": "https://auphonic.com/help/algorithms/singletrack.html"}], "summary": "音频后期 Web 服务：上传既有录音或视频音轨后，自动分类语音、音乐与噪声段，提供动态/静态/经典降噪、交流声检测与去混响，并可分别调节噪声、混响和呼吸音的移除量；同时包含响度、自动剪切、转录与发布等后期功能。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1001427463','HarmonyRestorer','{"deployment": ["Docker Compose 自托管完整前后端", "本地分别运行 FastAPI 后端与 Vite 前端", "公开在线实例 harmonyrestorer.online"], "features": ["上传 WAV、MP3、FLAC、OGG、M4A、AAC 音频并返回去噪后的音频", "OpGAN 默认引擎，可切换 UVR-DeNoise 引擎", "任务状态查询与按 wav/mp3/flac/ogg/m4a 格式下载修复结果", "前端上传向导、波形显示与修复前后交叉淡化对比", "训练噪声覆盖磁带嘶声、黑胶噼啪、交流声、高频衰减与磁带饱和"], "github_repository_id": 1001427463, "homepage": "https://harmonyrestorer.online", "id": "github:1001427463", "leaf_matches": [{"reason": "仓库 README 与在线首页给出完整 Web 修复服务：上传既有的带噪录音，选择去噪引擎处理，查看任务与波形，做修复前后 A/B 试听，再下载修复音频；训练噪声覆盖磁带嘶声、黑胶噼啪、交流声等归档退化类型，处理对象是不可重录的既有素材，符合损伤识别、专用修复处理器与保留节目素材的修复循环。MIT 许可证与仓库身份均已核对，Docker 可自托管。", "slug": "audio-restoration-application", "source_urls": ["https://raw.githubusercontent.com/jacob7choi-xyz/harmonyrestorer-v1/main/README.md", "https://github.com/jacob7choi-xyz/harmonyrestorer-v1", "https://harmonyrestorer.online/"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/jacob7choi-xyz/harmonyrestorer-v1/main/LICENSE", "license_review": {"rationale": "完整读取仓库根 LICENSE 原文：标题为 MIT License，含 Copyright (c) 2025 Jacob J. Choi、标准授权段、保留版权声明条件与免责声明；无附加限制，覆盖整个仓库。", "reviewer": "collector:unit-38", "scope": "repository", "source_url": "https://raw.githubusercontent.com/jacob7choi-xyz/harmonyrestorer-v1/main/LICENSE", "spdx_id": "MIT"}, "name": "HarmonyRestorer", "repository_url": "https://github.com/jacob7choi-xyz/harmonyrestorer-v1", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:43:28.311171+08:00", "kind": "repository_metadata", "sha256": "cda92306034c9f990ef72d4a72a0eca413e0d7c6a37eb2bf74ba878f46e46beb", "snapshot_path": "sources/cda92306034c9f990ef72d4a72a0eca413e0d7c6a37eb2bf74ba878f46e46beb.txt", "url": "https://github.com/jacob7choi-xyz/harmonyrestorer-v1"}, {"fetched_at": "2026-10-28T13:43:23.703739+08:00", "kind": "license", "sha256": "9568cc956038489f73dc9a4fed2ab60762c8ebe9891212a7939c9bb893ec3420", "snapshot_path": "sources/9568cc956038489f73dc9a4fed2ab60762c8ebe9891212a7939c9bb893ec3420.txt", "url": "https://raw.githubusercontent.com/jacob7choi-xyz/harmonyrestorer-v1/main/LICENSE"}, {"fetched_at": "2026-10-28T13:43:25.468985+08:00", "kind": "readme", "sha256": "9e2a1c3ff59915752484b99d6ebf6a81355c258c24ec7f7d02fa649bef4eea33", "snapshot_path": "sources/9e2a1c3ff59915752484b99d6ebf6a81355c258c24ec7f7d02fa649bef4eea33.txt", "url": "https://raw.githubusercontent.com/jacob7choi-xyz/harmonyrestorer-v1/main/README.md"}, {"fetched_at": "2026-10-28T13:43:28.266236+08:00", "kind": "homepage", "sha256": "fc0888f50a6c38a5a2ed41bfe56dcf6bc3d14a4551c09904b27082431916ad1c", "snapshot_path": "sources/fc0888f50a6c38a5a2ed41bfe56dcf6bc3d14a4551c09904b27082431916ad1c.txt", "url": "https://harmonyrestorer.online/"}], "summary": "开源 AI 音频修复 Web 应用：FastAPI 后端加 React 前端，上传带噪录音后由 OpGAN 或 UVR 去噪引擎处理，提供任务状态、波形与修复前后 A/B 对比，并可下载修复结果；支持 Docker 自托管。", "technology_stack": ["Python", "FastAPI", "PyTorch", "React", "TypeScript", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:934715082','openDAW','{"deployment": ["浏览器内运行（官方手册：无需安装、无需账号）", "源码可自行克隆构建，或以 AGPLv3 自托管"], "features": ["多轨音频与 MIDI 录音，可按轨 arm、选择输入并监听", "通道条含音量、声像、发送与输出路由，Audio Bus 与主输出求和", "项目保存在浏览器本地文件系统，支持另存、模板与工程打包导出", "提供 STEM 输入/输出；音频引擎在 Web Worker 中离线渲染，用于导出与 freeze"], "github_repository_id": 934715082, "homepage": "https://opendaw.studio", "id": "github:934715082", "leaf_matches": [{"reason": "官方手册总览写明它在浏览器内运行、无需安装或账号，并列出 Audio Recording、MIDI Recording、Mixer、STEM In / Out；录音页详述按轨 arm、音频/MIDI 输入、监听与延迟补偿；混音器页详述通道条音量/声像/发送与总线到主输出求和；项目管理页说明项目保存于浏览器文件系统、可另存/模板，并以 Project Bundle 打包携带素材；Sink 页说明 stem 导出时信号进入所属 bus；技术栈页说明音频引擎在 Web Worker 中离线渲染用于 exports 与 freeze。四项定义核心（持久多轨工程、用户创作素材、混音、渲染交付）均有官方正文对应；未采信官网 meta 描述中的 Zip 打包说法。", "slug": "digital-audio-workstation-daw", "source_urls": ["https://opendaw.studio/manuals/", "https://opendaw.studio/manuals/recording", "https://opendaw.studio/manuals/mixer", "https://opendaw.studio/manuals/project-management", "https://opendaw.studio/manuals/devices/audio/sink", "https://opendaw.studio/manuals/audio-bus", "https://opendaw.studio/manuals/tech-stack"]}, {"reason": "官方手册与仓库文档对同一产品给出完整制作闭环：Project Management 说明工程保存/另存/模板与重开（持久工程）；Recording 说明音频与 MIDI 轨道录音及输入监听（用户创作素材）；Mixer 说明推子、声像、发送、音频总线到主输出（混音）；仓库 video/12-freeze-and-export.md 明确“Export the finished track as audio”“Export the separate parts as stems”，tech-stack 说明 Web Worker 中离线渲染用于导出与冻结（渲染交付）。产品以 Web 应用形式在浏览器运行（homepage/manuals/tech-stack），工程存于浏览器私有文件系统，符合音乐制作应用核心且为完整在线应用服务形态，不以桌面客户端身份计入。", "slug": "music-production-application", "source_urls": ["https://opendaw.studio/manuals/project-management", "https://opendaw.studio/manuals/recording", "https://opendaw.studio/manuals/mixer", "https://raw.githubusercontent.com/andremichelle/openDAW/main/video/12-freeze-and-export.md", "https://opendaw.studio/manuals/tech-stack", "https://opendaw.studio"]}], "license": "AGPL-3.0-or-later", "license_evidence_url": "https://raw.githubusercontent.com/andremichelle/openDAW/main/LICENSE", "license_review": {"rationale": "已读取仓库根目录 LICENSE 全文，为 GNU Affero General Public License Version 3 完整条款（含 TERMS AND CONDITIONS 与第 13 条网络使用要求），无附加限制；仓库 README 的 Open-Source 与 License 两节均写明 “AGPL v3 (or later)”，故记为 AGPL-3.0-or-later。README 同时说明双许可，商业许可仅针对闭源再分发，不影响 AGPL 下完整源码的可用性。", "reviewer": "OpenCode collection session (open-design/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/andremichelle/openDAW/main/LICENSE", "spdx_id": "AGPL-3.0-or-later"}, "name": "openDAW", "repository_url": "https://github.com/andremichelle/openDAW", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:41:51.923773+08:00", "kind": "repository_metadata", "sha256": "db4666be7a9ab8a8d837f2bf0013b2ac7b85cb1d433002c96555618dd18c2c33", "snapshot_path": "sources/db4666be7a9ab8a8d837f2bf0013b2ac7b85cb1d433002c96555618dd18c2c33.txt", "url": "https://github.com/andremichelle/openDAW"}, {"fetched_at": "2026-10-28T13:41:50.691962+08:00", "kind": "license", "sha256": "0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0", "snapshot_path": "sources/0d96a4ff68ad6d4b6f1f30f713b18d5184912ba8dd389f86aa7710db079abcb0.txt", "url": "https://raw.githubusercontent.com/andremichelle/openDAW/main/LICENSE"}, {"fetched_at": "2026-10-28T13:42:05.783353+08:00", "kind": "readme", "sha256": "541c5cdbf7d4f5b87cd1c1b3ba7dfc4b68942c89ec48970810e58191c2695ebc", "snapshot_path": "sources/541c5cdbf7d4f5b87cd1c1b3ba7dfc4b68942c89ec48970810e58191c2695ebc.txt", "url": "https://raw.githubusercontent.com/andremichelle/openDAW/main/README.md"}, {"fetched_at": "2026-10-28T13:42:36.760464+08:00", "kind": "homepage", "sha256": "a2642f371840a026a256ddf57c3a11a37293459e866c510f372856089e78b62a", "snapshot_path": "sources/a2642f371840a026a256ddf57c3a11a37293459e866c510f372856089e78b62a.txt", "url": "https://opendaw.studio"}, {"fetched_at": "2026-10-28T13:42:37.533880+08:00", "kind": "documentation", "sha256": "1d7df96ce5c2a33be2a76a1a637779b9