tack"}, {"fetched_at": "2026-10-28T14:09:25.160169+08:00", "kind": "repository_metadata", "sha256": "5e7e199772c5272a95f4a750bc0daeef4df52399faa3651050863f04631ad677", "snapshot_path": "sources/5e7e199772c5272a95f4a750bc0daeef4df52399faa3651050863f04631ad677.txt", "url": "https://api.github.com/repos/andremichelle/openDAW"}, {"fetched_at": "2026-10-28T14:09:25.486233+08:00", "kind": "license", "sha256": "b1f1e286b3e2f4450a38339ef9149f43158275f5576a4be0ae0b6cd027399805", "snapshot_path": "sources/b1f1e286b3e2f4450a38339ef9149f43158275f5576a4be0ae0b6cd027399805.txt", "url": "https://api.github.com/repos/andremichelle/openDAW/license"}, {"fetched_at": "2026-10-28T14:09:38.191420+08:00", "kind": "homepage", "sha256": "b1e298cf123a0112c1b6036a7e683f285fcfe8548241f9c92dac7ccadd163d97", "snapshot_path": "sources/b1e298cf123a0112c1b6036a7e683f285fcfe8548241f9c92dac7ccadd163d97.txt", "url": "https://opendaw.studio"}, {"fetched_at": "2026-10-28T14:09:39.571899+08:00", "kind": "documentation", "sha256": "c946e0e7f7a72d4099becbb68716a4efb556ec7eef6fd5f5597e0038142d9dd3", "snapshot_path": "sources/c946e0e7f7a72d4099becbb68716a4efb556ec7eef6fd5f5597e0038142d9dd3.txt", "url": "https://opendaw.studio/manuals"}, {"fetched_at": "2026-10-28T14:10:47.449586+08:00", "kind": "documentation", "sha256": "2f8b0942c5b695d148ccc061ea99a16cdac50d594afb8090b73daa62864277b8", "snapshot_path": "sources/2f8b0942c5b695d148ccc061ea99a16cdac50d594afb8090b73daa62864277b8.txt", "url": "https://opendaw.studio/manuals/recording"}, {"fetched_at": "2026-10-28T14:10:47.249747+08:00", "kind": "documentation", "sha256": "019a3d4e437478b272fd232ec8e0ddc33321ccc0cbfe5f3b216dc40a53eb741a", "snapshot_path": "sources/019a3d4e437478b272fd232ec8e0ddc33321ccc0cbfe5f3b216dc40a53eb741a.txt", "url": "https://opendaw.studio/manuals/mixer"}, {"fetched_at": "2026-10-28T14:10:00.085047+08:00", "kind": "documentation", "sha256": "390d08402a448b297ae98cce848eafc0d4ad05d9e82c905a281000c0ab756663", "snapshot_path": "sources/390d08402a448b297ae98cce848eafc0d4ad05d9e82c905a281000c0ab756663.txt", "url": "https://opendaw.studio/manuals/project-management"}, {"fetched_at": "2026-10-28T14:14:27.830360+08:00", "kind": "documentation", "sha256": "c01a7b31241f497035d943770f274234a667d9904d0512df22341b19d90b33c8", "snapshot_path": "sources/c01a7b31241f497035d943770f274234a667d9904d0512df22341b19d90b33c8.txt", "url": "https://raw.githubusercontent.com/andremichelle/openDAW/main/video/12-freeze-and-export.md"}], "summary": "开源浏览器数字音频工作站：在持久多轨工程中录制音频与 MIDI、编写音符，按通道条与总线混音，并经离线渲染导出成品音频或分轨，无需安装或账号。", "technology_stack": ["TypeScript", "Rust / WebAssembly 音频引擎"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:alitu','Alitu','{"homepage": "https://alitu.com/", "id": "commercial:alitu", "leaf_matches": [{"reason": "官方帮助中心写明在 show 下集中管理 episodes 及其状态，可回放、编辑或发布单集；Episode Builder 内可录制或上传音频、按文稿或波形剪辑并插入音乐；发布阶段生成可发布文件，可选直接推送托管商、下载音频或生成视频版，官方首页同时给出录制/上传→清理→按文稿审阅编辑→发布到 Apple Podcasts 与 Spotify 的流程。覆盖单集工作单元、语音优先编辑与面向发布的完成三项核心。", "slug": "podcast-editing-application", "source_urls": ["https://alitu.com/", "https://help.alitu.com/en/articles/5572679-alitu-overview"]}], "name": "Alitu", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:54:03.107130+08:00", "kind": "homepage", "sha256": "b0f9efa9cc0a6212756e5033cd8b0e24164b30d449d48a76f262cb3c6d773e0e", "snapshot_path": "sources/b0f9efa9cc0a6212756e5033cd8b0e24164b30d449d48a76f262cb3c6d773e0e.txt", "url": "https://alitu.com/"}, {"fetched_at": "2026-10-28T13:54:22.516592+08:00", "kind": "documentation", "sha256": "9a9ebfea1fb29ca66ac6c47b0abaefe1be6a73c21a956bbcbe41b17ebefb80d7", "snapshot_path": "sources/9a9ebfea1fb29ca66ac6c47b0abaefe1be6a73c21a956bbcbe41b17ebefb80d7.txt", "url": "https://help.alitu.com/en/articles/5572679-alitu-overview"}], "summary": "面向播客创作者的 Web 制作工作台：在节目下按单集组织录制或上传的语音素材，自动清理后以文稿或波形编辑，并生成可直接发布或推送托管商的成品单集。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1152449694','HarborFM','{"deployment": ["Docker 单容器或 Docker Compose + Caddy/nginx", "Terraform 部署到 AWS EC2 或 Vultr", "Node.js 22+ 本地/PM2 运行，SQLite 持久化，需 ffmpeg 与 audiowaveform"], "features": ["show 与 episode 持久化管理，含草稿/排程/已发布状态与单集元数据", "episode 由 segments 组装：浏览器录音或上传，插入库内 intro/outro/bumper", "片段裁剪、分割、去静音、噪声抑制与重排，ffmpeg 合成成品单集音频", "远程嘉宾多轨录音（可选 WebRTC 服务）与转录（可选 Whisper ASR）", "生成 RSS 与公开节目页，支持 S3/FTP/SFTP/WebDAV 等目标导出"], "github_repository_id": 1152449694, "homepage": "https://harborfm.com/", "id": "github:1152449694", "leaf_matches": [{"reason": "官方 README 与站点写明以 show 与 episode 为持久对象，每个 episode 由 segments 组成：可录制或在浏览器上传片段、插入库内 intro/bumper、裁剪/分割/去静音/重排，最终合成成品单集音频并生成 RSS；同时提供转录、多轨远程录音与托管导出。服务形态为单进程自托管 Web 应用（Fastify API + React 前端，Docker/Terraform 部署）。覆盖单集工作单元、语音优先捕获与编辑、面向发布的成品导出三项核心。", "slug": "podcast-editing-application", "source_urls": ["https://harborfm.com/", "https://raw.githubusercontent.com/LoganRickert/harborfm/main/README.md"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/LoganRickert/harborfm/license", "name": "HarborFM", "repository_url": "https://github.com/LoganRickert/harborfm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T13:55:33.211441+08:00", "kind": "homepage", "sha256": "b2632313722f98015ac2bcac012c210ba023ed450fe6f14e0023bb4a726a932f", "snapshot_path": "sources/b2632313722f98015ac2bcac012c210ba023ed450fe6f14e0023bb4a726a932f.txt", "url": "https://harborfm.com/"}, {"fetched_at": "2026-10-28T13:55:08.446199+08:00", "kind": "repository_metadata", "sha256": "c00b8376a53fc3ed25866a2f0f4c9304b7b5c6409950d5eeb0a78e1a94791247", "snapshot_path": "sources/c00b8376a53fc3ed25866a2f0f4c9304b7b5c6409950d5eeb0a78e1a94791247.txt", "url": "https://github.com/LoganRickert/harborfm"}, {"fetched_at": "2026-10-28T13:55:15.643428+08:00", "kind": "license", "sha256": "a4f9bf4cd874a5a5fdcc958673ebcb98a07ee1b3c7e5b6f0146c999cc1ed7c45", "snapshot_path": "sources/a4f9bf4cd874a5a5fdcc958673ebcb98a07ee1b3c7e5b6f0146c999cc1ed7c45.txt", "url": "https://api.github.com/repos/LoganRickert/harborfm/license"}, {"fetched_at": "2026-10-28T13:55:23.438192+08:00", "kind": "readme", "sha256": "e88ea90ce2d7f18dedd29519e6fbfc512f005a7943fca07894639564a4666da3", "snapshot_path": "sources/e88ea90ce2d7f18dedd29519e6fbfc512f005a7943fca07894639564a4666da3.txt", "url": "https://raw.githubusercontent.com/LoganRickert/harborfm/main/README.md"}], "summary": "自托管播客制作 Web 应用：在 show 下创建单集，以可录制或上传的片段组装、裁剪、分割、去静音与排序，生成成品单集音频并导出 RSS，另可部署到 S3、FTP 等目标。", "technology_stack": ["Node.js / Fastify", "React / Vite / TanStack Query", "SQLite (better-sqlite3)", "ffmpeg / ffprobe", "可选 mediasoup WebRTC 服务"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1179068604','mpump','{"deployment": ["浏览器即用，官方托管于 https://mpump.live/（静态站点，README 说明部署在 GitHub Pages）", "源码可自行托管静态站点；短链分享中继由项目方运行于 Cloudflare Workers（s.mpump.live），完整节拍链接可离线兜底", "Jam/Live Set 中继需自行部署，公共托管中继当前下线，且该功能默认关闭"], "features": ["鼓声部由 808/909 风格合成鼓组与 8 套采样包构成，另含贝斯与合成器声部", "步进编辑器按 16/32 步构建节奏型，支持力度、半音、swing 与 Euclidean 节奏", "Song Mode 捕获场景并按小节数编排成歌曲，支持循环或单次播放", "Session 功能可将输出录制为 WAV，并导出/导入含节奏型与音色的 JSON 工程", "分享链接承载完整节拍状态（BPM、音色、pattern、效果），接收方可直接改写并回传"], "github_repository_id": 1179068604, "homepage": "https://mpump.live/", "id": "github:1179068604", "leaf_matches": [{"reason": "四项核心均由官方正文支持：README Audio Engine 的 808/909 合成鼓组（9 voices）与 8 套采样包（音源层）；README Editing/SYNTH 视图的 16/32 步步进网格，可逐格编辑半音、力度、slide（节奏型创作，复用单位是 pattern 而非音频片段）；README Song Mode 捕获场景并按 1/2/4/8/16/32 小节排成歌曲、可循环或单次（模式编排）；README Session 段 “Record to WAV”（渲染音频）。与 DAW 叶的分界由官方自述给出：landing.html 正文明写 “mpump is not trying to be a full DAW in the browser. It is a fast loop instrument designed for motion.”，产品无多轨音频录音/波形编辑工作流，编排对象是节奏型场景而非任意音频工程；仓库与 README 亦自述为 “browser drum machine and synth”“browser groovebox”，身份为鼓机/律动盒。与 Loop-based Music Production 的分界：内置 1210+ patterns 是步进网格上的可编辑音符数据，用户在其上改写节奏型，不是拼接预录 loop 音频。服务形态由 README Hosting 段与 landing.html 的 “Open mpump” 入口证明为浏览器应用；仓库为完整应用源码（含 server、worker、link-bridge），非引擎/SDK。", "slug": "beat-making-application", "source_urls": ["https://raw.githubusercontent.com/gdamdam/mpump/main/README.md", "https://mpump.live/landing.html", "https://raw.githubusercontent.com/gdamdam/mpump/main/docs/user-guide.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/gdamdam/mpump/main/LICENSE", "license_review": {"rationale": "仓库 LICENSE 快照为完整 GNU Affero GPL v3 全文（672 行，含标题、序言、TERMS AND CONDITIONS、END OF TERMS AND CONDITIONS 与 How to Apply），文件头声明按 FSF 发布的第 3 版授权；README 的 License 段同样写 AGPL-3.0。按仓库整体授权记为 AGPL-3.0。README 另有商标条款限制以 “mpump” 名义提供衍生服务，属品牌限制而非代码许可限制；内置采样包与第三方依赖未单独核对授权，属未覆盖范围。", "reviewer": "OpenCode collection session (opencode-design/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://raw.githubusercontent.com/gdamdam/mpump/main/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "mpump", "repository_url": "https://github.com/gdamdam/mpump", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:01:07.061839+08:00", "kind": "repository_metadata", "sha256": "32a4970b6156f43db9f53894577f9bde994e4e24203e2dccb7d5de8069700985", "snapshot_path": "sources/32a4970b6156f43db9f53894577f9bde994e4e24203e2dccb7d5de8069700985.txt", "url": "https://github.com/gdamdam/mpump"}, {"fetched_at": "2026-10-28T14:00:08.119691+08:00", "kind": "readme", "sha256": "5ea1d9d402ae06c5fa350bc8ca5fae6f901bd7f47ed934250b93545879e421b0", "snapshot_path": "sources/5ea1d9d402ae06c5fa350bc8ca5fae6f901bd7f47ed934250b93545879e421b0.txt", "url": "https://raw.githubusercontent.com/gdamdam/mpump/main/README.md"}, {"fetched_at": "2026-10-28T14:01:05.062111+08:00", "kind": "license", "sha256": "5a8b6f569fdaed4d1f59509ba560e38c8f4054b71932ef6c852224f9b32c729b", "snapshot_path": "sources/5a8b6f569fdaed4d1f59509ba560e38c8f4054b71932ef6c852224f9b32c729b.txt", "url": "https://raw.githubusercontent.com/gdamdam/mpump/main/LICENSE"}, {"fetched_at": "2026-10-28T14:02:16.162414+08:00", "kind": "documentation", "sha256": "5ee3a8ea0b333f5b51eaf7726adc96d6e02804e320c1f97ca0c2df833b2ceebd", "snapshot_path": "sources/5ee3a8ea0b333f5b51eaf7726adc96d6e02804e320c1f97ca0c2df833b2ceebd.txt", "url": "https://raw.githubusercontent.com/gdamdam/mpump/main/docs/user-guide.md"}, {"fetched_at": "2026-10-28T14:02:59.242744+08:00", "kind": "homepage", "sha256": "0e5d74bcdbf5797f665bb0c31ee0415a8000e2b4c94809919433cb3e4ce08659", "snapshot_path": "sources/0e5d74bcdbf5797f665bb0c31ee0415a8000e2b4c94809919433cb3e4ce08659.txt", "url": "https://mpump.live/"}, {"fetched_at": "2026-10-28T14:06:31.977745+08:00", "kind": "homepage", "sha256": "8834b05d7a94697c4065cddcb1fd518825c652469a5afa161bfdc84c5164de27", "snapshot_path": "sources/8834b05d7a94697c4065cddcb1fd518825c652469a5afa161bfdc84c5164de27.txt", "url": "https://mpump.live/landing.html"}], "summary": "开源浏览器鼓机/律动盒：以 808/909 合成鼓组与采样音源在步进网格内构建可复用节奏型，用 Song Mode 把场景编排成歌曲，并可录制 WAV。官方明确定位为“快速循环乐器”而非完整 DAW。", "technology_stack": ["React", "TypeScript", "Web Audio API", "AudioWorklet"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:soundtrap','Soundtrap','{"homepage": "https://soundtrap.com", "id": "commercial:soundtrap", "leaf_matches": [{"reason": "官方产品页与博客说明内置两万余个循环/采样的循环库，可把预制循环拖入浏览器内工作室的工程轨道并叠放编曲；官方博客明确拖入的循环会自动匹配工程 BPM 与歌曲调性，支持页说明工程可在 File > Export 中导出 WAV/MP3 成品。循环库、时间线装配、速度/调性锁定与音频交付均有官方正文支持。", "slug": "loop-based-music-production-application", "source_urls": ["https://www.soundtrap.com/content/product/audio-loops-sample-packs", "https://blog.soundtrap.com/create-lo-fi-beats/", "https://support.soundtrap.com/hc/en-us/articles/206050101-How-to-Download-Your-Soundtrap-Projects", "https://support.soundtrap.com/hc/en-us/articles/205663231-How-to-Use-the-Metronome-and-Set-Tempo-BPM-in-Soundtrap"]}], "name": "Soundtrap", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:12:23.590707+08:00", "kind": "homepage", "sha256": "60d5e6615aac2204facd4d44c7c22b0d759d37cf2164ec6de54f5c79b3b8569f", "snapshot_path": "sources/60d5e6615aac2204facd4d44c7c22b0d759d37cf2164ec6de54f5c79b3b8569f.txt", "url": "https://www.soundtrap.com/"}, {"fetched_at": "2026-10-28T14:12:20.066859+08:00", "kind": "documentation", "sha256": "92be8e9e0282eec752364f299a0cea7cc70144730987a7b66a9458ab64b2698c", "snapshot_path": "sources/92be8e9e0282eec752364f299a0cea7cc70144730987a7b66a9458ab64b2698c.txt", "url": "https://www.soundtrap.com/content/product/audio-loops-sample-packs"}, {"fetched_at": "2026-10-28T14:18:14.729613+08:00", "kind": "documentation", "sha256": "700734eaa3be1c75a2228e56d8f7057c042af3ab0a26d2facf6c93d984e6ec8e", "snapshot_path": "sources/700734eaa3be1c75a2228e56d8f7057c042af3ab0a26d2facf6c93d984e6ec8e.txt", "url": "https://blog.soundtrap.com/create-lo-fi-beats/"}, {"fetched_at": "2026-10-28T14:13:55.252730+08:00", "kind": "documentation", "sha256": "9f8fa89bb89401a6f16af27e99bc4097c67b4d9006940a5faab49ff795b26fba", "snapshot_path": "sources/9f8fa89bb89401a6f16af27e99bc4097c67b4d9006940a5faab49ff795b26fba.txt", "url": "https://support.soundtrap.com/hc/en-us/articles/206050101-How-to-Download-Your-Soundtrap-Projects"}, {"fetched_at": "2026-10-28T14:12:19.088679+08:00", "kind": "documentation", "sha256": "69b9dd270197d6590ede4a2538550e5962e42ee5d4eac527383c4ef1a279b35f", "snapshot_path": "sources/69b9dd270197d6590ede4a2538550e5962e42ee5d4eac527383c4ef1a279b35f.txt", "url": "https://support.soundtrap.com/hc/en-us/articles/205663231-How-to-Use-the-Metronome-and-Set-Tempo-BPM-in-Soundtrap"}], "summary": "浏览器内的在线音乐工作室：从循环库把预制循环拖入工程编曲，循环自动匹配工程 BPM 与调性，完成后可导出 WAV/MP3 等音频。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1131820351','ComposeYogi','{"deployment": ["官方站点 composeyogi.com 直接使用，无需安装", "Node.js 本地运行或 Docker 自托管（README 提供命令）"], "features": ["内置循环与采样素材库（public/samples/loops 下为按 BPM 命名的预制循环）", "多轨时间线，音频/MIDI/鼓轨片段拖拽编排", "Stretch to BPM：用适配控件把音频片段重采样到工程速度", "模板工程可直接改编，浏览器面板含 Templates/Samples", "WAV/MP3/MIDI/JSON 导出，本地优先自动保存"], "github_repository_id": 1131820351, "homepage": "https://composeyogi.com", "id": "github:1131820351", "leaf_matches": [{"reason": "仓库自带预制循环素材（public/samples/loops 内为按 90/120/128/140 BPM 命名的鼓与打击乐循环），产品为浏览器内多轨时间线，可拖拽片段编排并套用模板；ROADMAP 与站点正文说明已上线 Stretch to BPM，界面文案为把音频片段重采样到工程 BPM（速度锁定由产品适配控件完成），成品可导出 WAV。循环库、时间线装配、速度锁定与音频交付四项核心均有官方正文/仓库内容支持；调性自动匹配未取得正文证据，不据此断言。", "slug": "loop-based-music-production-application", "source_urls": ["https://api.github.com/repos/AppsYogi-com/ComposeYogi/readme", "https://composeyogi.com", "https://api.github.com/repos/AppsYogi-com/ComposeYogi/contents/ROADMAP.md", "https://api.github.com/repos/AppsYogi-com/ComposeYogi/contents/public/samples/loops"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi/license", "name": "ComposeYogi", "repository_url": "https://github.com/AppsYogi-com/ComposeYogi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:11:55.752801+08:00", "kind": "repository_metadata", "sha256": "0934667adda71bf95267b6d27905a754f6fc5fca4b3447edaa05a88c880499cf", "snapshot_path": "sources/0934667adda71bf95267b6d27905a754f6fc5fca4b3447edaa05a88c880499cf.txt", "url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi"}, {"fetched_at": "2026-10-28T14:11:55.926374+08:00", "kind": "readme", "sha256": "56010e0c3920bddaf1e0bb292ec1663889b10495916a60f89887666a10839935", "snapshot_path": "sources/56010e0c3920bddaf1e0bb292ec1663889b10495916a60f89887666a10839935.txt", "url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi/readme"}, {"fetched_at": "2026-10-28T14:11:55.115859+08:00", "kind": "license", "sha256": "57a12667b3e7a20fc1a0c86379bdc341c3a1909bce6bfa93acb0ef995bbec343", "snapshot_path": "sources/57a12667b3e7a20fc1a0c86379bdc341c3a1909bce6bfa93acb0ef995bbec343.txt", "url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi/license"}, {"fetched_at": "2026-10-28T14:13:06.498695+08:00", "kind": "homepage", "sha256": "7ff6720a40c2a8a6d0663923e89ae1e0e1b505a779af55d087943e3e2d20beb2", "snapshot_path": "sources/7ff6720a40c2a8a6d0663923e89ae1e0e1b505a779af55d087943e3e2d20beb2.txt", "url": "https://composeyogi.com"}, {"fetched_at": "2026-10-28T14:17:13.123320+08:00", "kind": "documentation", "sha256": "5ecd63520762ab81f99bf94e90cc301d4c767ce0b2c96ebfad616f919c2724c0", "snapshot_path": "sources/5ecd63520762ab81f99bf94e90cc301d4c767ce0b2c96ebfad616f919c2724c0.txt", "url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi/contents/ROADMAP.md"}, {"fetched_at": "2026-10-28T14:14:32.056143+08:00", "kind": "repository_metadata", "sha256": "27acfbd4568128916478e16d15f4f3e8383c15d505c19813700b9a8c7c0deaae", "snapshot_path": "sources/27acfbd4568128916478e16d15f4f3e8383c15d505c19813700b9a8c7c0deaae.txt", "url": "https://api.github.com/repos/AppsYogi-com/ComposeYogi/contents/public/samples/loops"}], "summary": "浏览器内运行的开源音乐制作应用：内置预制循环/采样库与模板，在时间线上拖拽编排多轨片段，可用 Stretch to BPM 把音频片段对齐工程速度，并导出 WAV/MP3/MIDI。MIT 许可，可自托管或使用官方站点。", "technology_stack": ["Next.js 15", "TypeScript", "Tone.js / Web Audio", "Zustand", "IndexedDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:90661308','Hacklily','{"deployment": ["自托管：Node 前端 + Rust 渲染协调器 + LilyPond Docker 渲染器", "渲染协调器提供 systemd 用户服务与反向代理部署说明"], "features": ["浏览器内 Monaco 编辑 LilyPond 记谱文本", "实时渲染 SVG/PDF/PNG/MIDI 预览", "乐谱保存并发布到 GitHub", "通过 musicxml2ly 导入 MusicXML", "服务端渲染池（稳定/不稳定 LilyPond 版本，按乐谱 \\version 路由）"], "github_repository_id": 90661308, "homepage": "https://www.hacklily.org", "id": "github:90661308", "leaf_matches": [{"reason": "官方 README 自述为在线乐谱编辑器：在浏览器中编辑 LilyPond 记谱文本（音高、时值、休止、声部、拍号等音乐语义），由服务端渲染为 SVG/PDF/PNG 五线谱，乐谱可保存并发布到 GitHub 成为持久文档。编辑采用记谱文本而非图形所见即所得，小节时值等有效性主要由 LilyPond 编译校验，此处不扩展更强断言。", "slug": "music-notation-editor", "source_urls": ["https://raw.githubusercontent.com/jocelyn-stericker/hacklily/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/jocelyn-stericker/hacklily/license", "name": "Hacklily", "repository_url": "https://github.com/jocelyn-stericker/hacklily", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:22:14.696732+08:00", "kind": "repository_metadata", "sha256": "566c78f18370aeed1f20cd63533836183da42107e349d394be5774f2e8c0c08d", "snapshot_path": "sources/566c78f18370aeed1f20cd63533836183da42107e349d394be5774f2e8c0c08d.txt", "url": "https://api.github.com/repos/jocelyn-stericker/hacklily"}, {"fetched_at": "2026-10-28T14:22:37.197137+08:00", "kind": "readme", "sha256": "c1cb2d779b38e03ed8981a03e11115ed3981f54bd6c2a6fb5b89a9c7be2ed6dd", "snapshot_path": "sources/c1cb2d779b38e03ed8981a03e11115ed3981f54bd6c2a6fb5b89a9c7be2ed6dd.txt", "url": "https://raw.githubusercontent.com/jocelyn-stericker/hacklily/main/README.md"}, {"fetched_at": "2026-10-28T14:22:37.483474+08:00", "kind": "license", "sha256": "afba58d0b6a21d91ff748ce4273cbb7fa2484453c7b0c1e9daec6644154f4466", "snapshot_path": "sources/afba58d0b6a21d91ff748ce4273cbb7fa2484453c7b0c1e9daec6644154f4466.txt", "url": "https://api.github.com/repos/jocelyn-stericker/hacklily/license"}, {"fetched_at": "2026-10-28T14:23:00.622269+08:00", "kind": "homepage", "sha256": "8c87a718af7b5d2a2b10e51f33fd64ec346342d46dab99b21894bc08cdf26dd2", "snapshot_path": "sources/8c87a718af7b5d2a2b10e51f33fd64ec346342d46dab99b21894bc08cdf26dd2.txt", "url": "https://www.hacklily.org/"}], "summary": "开源的在线乐谱编辑器与发布工具：在浏览器中编辑 LilyPond 记谱文本，由服务端渲染为 SVG/PDF/PNG 五线谱预览，乐谱可保存并发布到 GitHub。", "technology_stack": ["TypeScript", "React", "Rust", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:121034292','Digital Music Stand','{"deployment": ["下载官方 release 的单二进制运行", "源码自行 go build（官方 README 提供构建步骤）"], "features": ["以单个可执行文件内嵌全部静态资源并提供浏览器界面，无需数据库", "从指定目录读取 PDF 乐谱，按 interpret_title.pdf 命名建立曲库条目", "可用 YAML 定义歌本、曲目与曲目使用的页序，按场次顺序翻阅", "按 P 打开模糊检索，在曲库中快速定位乐谱", "方向键或 1/2 键翻至上一页/下一页，官方说明为可编程脚踏板设计", "可选开启浏览器上传 PDF"], "github_repository_id": 121034292, "homepage": "https://github.com/PatWie/digitalmusicstand", "id": "github:121034292", "leaf_matches": [{"reason": "官方 README 说明这是浏览器内运行的 PDF 乐谱查看器：指定目录的 PDF 按命名形成可检索曲库，YAML 歌本给出曲目与页序，方向键或 1/2 键翻页并明确面向脚踏板；仓库元数据与 GPL-3.0 全文核实了自托管 Web 服务形态和完整许可证，覆盖乐谱、阅读界面与曲库三项核心。", "slug": "sheet-music-reader", "source_urls": ["https://raw.githubusercontent.com/PatWie/digitalmusicstand/master/README.md", "https://api.github.com/repos/PatWie/digitalmusicstand"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/PatWie/digitalmusicstand/license", "name": "Digital Music Stand", "repository_url": "https://github.com/PatWie/digitalmusicstand", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:23:24.198118+08:00", "kind": "repository_metadata", "sha256": "faa97b3094e472d49914674f590c3caf9226de760040d7c27ea9877edc823ede", "snapshot_path": "sources/faa97b3094e472d49914674f590c3caf9226de760040d7c27ea9877edc823ede.txt", "url": "https://api.github.com/repos/PatWie/digitalmusicstand"}, {"fetched_at": "2026-10-28T14:23:30.722123+08:00", "kind": "readme", "sha256": "4a6d0f11c3e965c0417dc4a34817b984836c4d0ee45f8cf68669b942ce7144a5", "snapshot_path": "sources/4a6d0f11c3e965c0417dc4a34817b984836c4d0ee45f8cf68669b942ce7144a5.txt", "url": "https://raw.githubusercontent.com/PatWie/digitalmusicstand/master/README.md"}, {"fetched_at": "2026-10-28T14:23:40.250729+08:00", "kind": "license", "sha256": "65b451d35d41d3bd8be8cb17ae02dcc68f54f0902bad030eef370e0b63df1a8b", "snapshot_path": "sources/65b451d35d41d3bd8be8cb17ae02dcc68f54f0902bad030eef370e0b63df1a8b.txt", "url": "https://api.github.com/repos/PatWie/digitalmusicstand/license"}], "summary": "可自托管的浏览器乐谱阅读服务：把 PDF 乐谱按命名规则收成曲库，支持模糊检索曲目、按歌本页序翻阅，并用脚踏板或方向键翻页。", "technology_stack": ["Go", "JavaScript", "PDF.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:584016836','Chili3D','{"deployment": ["公共 Web 应用 chili3d.com（浏览器直接使用，无需本地安装）", "自托管：npm 构建后由静态服务提供，或用仓库内 docker compose 启动"], "features": ["3D 视口带相机控制，可保存并召回相机位置", "2D 草图工具绘制直线、圆弧、圆、矩形、多边形与贝塞尔曲线", "拉伸、旋转、扫掠、放样及布尔并/差/交等实体建模操作", "对象吸附到点/边/面等工作平面与几何特征，用于精确编辑", "倒角、圆角、修剪、打断、分割、缝合、子形状操作与特征移除", "创建、打开与保存文档，完整撤销/重做与事务历史", "STEP、IGES、BREP、STL 导入导出"], "github_repository_id": 584016836, "homepage": "https://chili3d.com", "id": "github:584016836", "leaf_matches": [{"reason": "官方 README 正文说明这是浏览器中运行的三维 CAD 应用：模型处于可导航的 3D 视口中（相机控制与位置召回），用户通过草图绘制与拉伸/旋转/扫掠/放样、布尔运算、倒角圆角及子形状操作在点/边/面层级直接创建和修改几何，并将结果创建、打开、保存为文档，可导入导出 STEP/IGES/BREP/STL。应用形态为公共 Web 应用并在仓库内提供 Docker 自托管部署，符合软件服务形态；仓库元数据中的 id 584016836 与 full_name xiangechen/chili3d 可核对，许可证 API 返回 AGPL-3.0 全文。", "slug": "3d-modeling-application", "source_urls": ["https://api.github.com/repos/xiangechen/chili3d/readme", "https://api.github.com/repos/xiangechen/chili3d", "https://api.github.com/repos/xiangechen/chili3d/license"]}, {"reason": "README 正文说明 Chili3D 是浏览器端 3D CAD 应用，基于 OCCT WebAssembly，支持 Bézier 曲线、放样与扫掠、偏移曲面与加厚、布尔及圆角/倒角等自由曲面与直接建模操作，并支持 STEP/IGES/BREP/STL 导入导出、测量和几何捕捉；这些正文覆盖精确 B-rep 自由形态几何、以形态为中心的直接迭代操作和面向制造的几何交换。官网 meta 说明其直接在浏览器运行，README 提供 Docker 自托管，属于完整应用而非组件、CLI 或仅内核。", "slug": "industrial-design-application", "source_urls": ["https://chili3d.com", "https://api.github.com/repos/xiangechen/chili3d", "https://raw.githubusercontent.com/xiangechen/chili3d/main/README.md", "https://raw.githubusercontent.com/xiangechen/chili3d/main/LICENSE"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/xiangechen/chili3d/license", "name": "Chili3D", "repository_url": "https://github.com/xiangechen/chili3d", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:46:36.406644+08:00", "kind": "repository_metadata", "sha256": "39fec08b310b693ef7f0ef25e2dafc88d8517fd081080a260ca8d438fbc3c81f", "snapshot_path": "sources/39fec08b310b693ef7f0ef25e2dafc88d8517fd081080a260ca8d438fbc3c81f.txt", "url": "https://api.github.com/repos/xiangechen/chili3d"}, {"fetched_at": "2026-10-28T14:46:46.370221+08:00", "kind": "readme", "sha256": "45b21f3be9f133fbdfce49db7828c2f70de3c0616ef5d7ec33ef92ba5e71d7dc", "snapshot_path": "sources/45b21f3be9f133fbdfce49db7828c2f70de3c0616ef5d7ec33ef92ba5e71d7dc.txt", "url": "https://api.github.com/repos/xiangechen/chili3d/readme"}, {"fetched_at": "2026-10-28T14:46:51.490781+08:00", "kind": "license", "sha256": "efe4dcee3ec6f03c8c8fde1d1290193b4791c62fb41be6d95ae154be35732304", "snapshot_path": "sources/efe4dcee3ec6f03c8c8fde1d1290193b4791c62fb41be6d95ae154be35732304.txt", "url": "https://api.github.com/repos/xiangechen/chili3d/license"}, {"fetched_at": "2026-10-29T12:24:20.904651+08:00", "kind": "homepage", "sha256": "8029b71bffde77b7f06a0d0e45a206312987aa43509dc80635322da6d173cd54", "snapshot_path": "sources/8029b71bffde77b7f06a0d0e45a206312987aa43509dc80635322da6d173cd54.txt", "url": "https://chili3d.com"}, {"fetched_at": "2026-10-29T12:23:42.247935+08:00", "kind": "repository_metadata", "sha256": "b9da6e38f69956343a883400e30cad1a66bc7d2d68903565937768f5aeb3c9a4", "snapshot_path": "sources/b9da6e38f69956343a883400e30cad1a66bc7d2d68903565937768f5aeb3c9a4.txt", "url": "https://api.github.com/repos/xiangechen/chili3d"}, {"fetched_at": "2026-10-29T12:23:49.467700+08:00", "kind": "readme", "sha256": "5a94b6782dfa18d0339bd3c89f7524451e776a81b05cdd1c48d77264aca15d67", "snapshot_path": "sources/5a94b6782dfa18d0339bd3c89f7524451e776a81b05cdd1c48d77264aca15d67.txt", "url": "https://raw.githubusercontent.com/xiangechen/chili3d/main/README.md"}, {"fetched_at": "2026-10-29T12:23:51.303195+08:00", "kind": "license", "sha256": "8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef", "snapshot_path": "sources/8486a10c4393cee1c25392769ddd3b2d6c242d6ec7928e1414efff7dfb2f07ef.txt", "url": "https://raw.githubusercontent.com/xiangechen/chili3d/main/LICENSE"}], "summary": "浏览器中运行的开源三维 CAD 应用：在交互式 3D 视口中绘制草图、创建实体并通过布尔、拉伸、倒角等操作编辑几何，以文档形式创建、打开与保存模型，并可导入导出 STEP/IGES/BREP/STL。", "technology_stack": ["TypeScript", "Three.js", "OpenCascade (OCCT) via WebAssembly", "IndexedDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:11232735','SculptGL','{"deployment": ["浏览器静态应用：webpack 构建产物置于 app/，由静态服务器提供；公开实例 stephaneginier.com/sculptgl/ 为同一入口页面", "可选 Electron 独立桌面打包（README 与 package.json 的 standalone 脚本）"], "features": ["雕刻工具集：Brush、Inflate、Twist、Smooth、Flatten、Pinch、Crease、Drag、Move、LocalScale、Masking（src/editing/tools/Tools.js 注册）", "笔刷参数：Radius、Intensity、Hardness、Negative 反转、Alpha 纹理，以及平板压力对半径与强度的调制", "拓扑辅助：动态细分与体素重网格（quads）、简化，均出现在界面字符串中", "文件与导出：保存/打开 .sgl 工程，导入 OBJ/PLY/STL/SGL，导出 OBJ/PLY/STL", "浏览器静态构建（webpack 输出 app/，可用 http-server 或任意静态托管），另有可选 Electron 打包脚本"], "github_repository_id": 11232735, "homepage": "https://stephaneginier.com/sculptgl/", "id": "github:11232735", "leaf_matches": [{"reason": "仓库自述与构建脚本证明这是一个可自托管的浏览器 WebGL 雕刻应用（README 的浏览器构建步骤、package.json 的 webpack/http-server、公开入口页仅 canvas + sculptgl.js）。核心工作流有代码与界面正文支撑：Tools.js 注册 Brush/Inflate/Twist/Smooth/Flatten/Pinch/Crease/Drag/Move/Masking 等沿笔触作用的变形工具；english.js 给出 Radius/Intensity/Hardness、Negative 反转、alpha 纹理与压力半径/强度；Export.js 落实 OBJ/PLY/STL 与 .sgl 工程导出，对应持久三维表面、笔画式笔刷、笔触参数、可导出结果四项核心。仓库已归档且官网无手册（help/about/manual 均 403），因此以仓库内文档与源码为功能依据，入口页只作浏览器交付形态证据。", "slug": "digital-sculpting-application", "source_urls": ["https://raw.githubusercontent.com/stephomi/sculptgl/master/README.md", "https://raw.githubusercontent.com/stephomi/sculptgl/master/package.json", "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/editing/tools/Tools.js", "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/gui/tr/english.js", "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/files/Export.js", "https://stephaneginier.com/sculptgl/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/stephomi/sculptgl/license", "name": "SculptGL", "repository_url": "https://github.com/stephomi/sculptgl", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:33:07.931847+08:00", "kind": "repository_metadata", "sha256": "0bcf5183bf9c318843746efac46c5efbc1fc7c974f70e940a169ebf8a858178a", "snapshot_path": "sources/0bcf5183bf9c318843746efac46c5efbc1fc7c974f70e940a169ebf8a858178a.txt", "url": "https://api.github.com/repos/stephomi/sculptgl"}, {"fetched_at": "2026-10-28T14:44:58.701099+08:00", "kind": "license", "sha256": "eecd4655159afe5a9ed354a176847332174a90d45d94911f9921036edc188e4b", "snapshot_path": "sources/eecd4655159afe5a9ed354a176847332174a90d45d94911f9921036edc188e4b.txt", "url": "https://api.github.com/repos/stephomi/sculptgl/license"}, {"fetched_at": "2026-10-28T14:33:42.988566+08:00", "kind": "readme", "sha256": "2df7c7e4f23018107104135b9b1115285b7393e8bbf1a9594b60816d0f43cf24", "snapshot_path": "sources/2df7c7e4f23018107104135b9b1115285b7393e8bbf1a9594b60816d0f43cf24.txt", "url": "https://raw.githubusercontent.com/stephomi/sculptgl/master/README.md"}, {"fetched_at": "2026-10-28T14:39:36.732636+08:00", "kind": "documentation", "sha256": "994a445d587285c98b86f2bf964e87cf802f563492f0dd557d99b4f71108f891", "snapshot_path": "sources/994a445d587285c98b86f2bf964e87cf802f563492f0dd557d99b4f71108f891.txt", "url": "https://raw.githubusercontent.com/stephomi/sculptgl/master/package.json"}, {"fetched_at": "2026-10-28T14:43:22.765546+08:00", "kind": "documentation", "sha256": "e73d205748c499e279050db87b79eaf38a7e053f52c617d371ea18baf0ba5bc8", "snapshot_path": "sources/e73d205748c499e279050db87b79eaf38a7e053f52c617d371ea18baf0ba5bc8.txt", "url": "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/editing/tools/Tools.js"}, {"fetched_at": "2026-10-28T14:35:45.987693+08:00", "kind": "documentation", "sha256": "9fe10fafa58ad6ac59c894decaecd5819ae9960c9231f7c832af04cab9fd8cf4", "snapshot_path": "sources/9fe10fafa58ad6ac59c894decaecd5819ae9960c9231f7c832af04cab9fd8cf4.txt", "url": "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/gui/tr/english.js"}, {"fetched_at": "2026-10-28T14:44:58.584997+08:00", "kind": "documentation", "sha256": "e9bb1bbd6b0ff3c2f627f938e0a32b41db3cf924113f2d7ce708ccc89fa9ab0d", "snapshot_path": "sources/e9bb1bbd6b0ff3c2f627f938e0a32b41db3cf924113f2d7ce708ccc89fa9ab0d.txt", "url": "https://raw.githubusercontent.com/stephomi/sculptgl/master/src/files/Export.js"}, {"fetched_at": "2026-10-28T14:34:07.957803+08:00", "kind": "homepage", "sha256": "ef620c4f9903760a1235717e93b17f96dfce4c093426c8bf2dfeebb16ffc0cb9", "snapshot_path": "sources/ef620c4f9903760a1235717e93b17f96dfce4c093426c8bf2dfeebb16ffc0cb9.txt", "url": "https://stephaneginier.com/sculptgl/"}], "summary": "开源 WebGL 数字雕刻应用程序：在浏览器中沿笔触用 Brush/Flatten/Inflate/Drag/Smooth/Pinch/Crease 等工具变形网格，可调半径、强度、硬度与压力，并导出 OBJ/PLY/STL 或 .sgl 工程（界面中的 Clay 是材质/MatCap 选项，不是笔刷）。仓库已归档、基本停止维护（仅少量小修），但仍可自托管静态浏览器构建。", "technology_stack": ["JavaScript", "WebGL", "webpack", "Node.js"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1427684344','OBrush','{"deployment": ["浏览器静态应用：WASM 包与静态资源由普通 Web 服务器提供，公开实例 obrush.app；雕刻与文件处理在访问者设备本地完成，无远程模型上传端点", "桌面 alpha：打包 macOS（Apple Silicon），Windows/Linux 构建尚未验证"], "features": ["笔刷工具：Draw、Clay、Move、Smooth、Crease 等，配合遮罩、顶点绘制、X 对称与压力控制（README）", "笔触参数：浏览器端压力默认调制强度、半径调制可选，笔画可撤销/重做（CONTROLS.md）", "拓扑与细节：持久 Loop 细分级别、0.1.6 起的体素重网格与受约束三角形简化、PNG alpha 笔刷（SCULPTING_FOUNDATIONS.md）", "持久工程与导出：版本化 .obrush 工程保存/打开，导入导出 OBJ/PLY/STL；OBJ 仅导出活动网格", "交付形态：同一 Rust 核心产出浏览器静态 WASM 应用与 macOS（Apple Silicon）桌面 alpha"], "github_repository_id": 1427684344, "homepage": "https://obrush.app/", "id": "github:1427684344", "leaf_matches": [{"reason": "README 明确这是面向桌面与浏览器的开源雕刻应用，公开实例 obrush.app，并列出 Draw/Clay/Move/Smooth/Crease 笔刷及 OBJ/PLY/STL 导入导出；CONTROLS.md 给出左键拖拽雕刻、Shift 临时 Smooth、半径快捷键与浏览器端压力调制强度，属于沿笔触作用且带笔触参数的画笔工作流；SCULPTING_FOUNDATIONS.md 说明版本化 .obrush 工程、细分级别、体素重网格与 PNG alpha，可保存为持久可导出模型；WEB_HOSTING.md 说明浏览器构建为静态 WASM 应用、雕刻在本地设备完成；BUILDING.md 进一步明确浏览器端为同一 Rust 引擎编译的 WebAssembly、视口用 WebGL2、静态包可托管，补足了技术栈依据。README 所称“多对象/雕刻图层”与 0.1.6 文档“仍为单网格、图层待做”矛盾，未计入 features，但不影响四项核心。", "slug": "digital-sculpting-application", "source_urls": ["https://raw.githubusercontent.com/Reza2kn/OBrush/main/README.md", "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/CONTROLS.md", "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/SCULPTING_FOUNDATIONS.md", "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/WEB_HOSTING.md", "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/BUILDING.md", "https://obrush.app/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/Reza2kn/OBrush/license", "license_review": {"rationale": "GitHub license API 的完整 Apache-2.0 文本含 apache license/version 2.0/limitations under the license 标记，仓库根目录另有 LICENSE-APACHE 与 LICENSE-MIT；README 说明可按 MIT 或 Apache-2.0 任选，此处按 API 识别的 Apache-2.0 记录并保留双许可事实。本轮另补 LICENSE-MIT 快照（1076 字节，完整 MIT 文本），双许可两段文本均有留档。", "reviewer": "OpenDesign collector (unit 48)", "scope": "repository", "source_url": "https://api.github.com/repos/Reza2kn/OBrush/license", "spdx_id": "Apache-2.0"}, "name": "OBrush", "repository_url": "https://github.com/Reza2kn/OBrush", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:37:58.128521+08:00", "kind": "repository_metadata", "sha256": "5165be476cb46a4f4611f08a9bd25b96ca94d898964b8f0799a889fe0783a2d9", "snapshot_path": "sources/5165be476cb46a4f4611f08a9bd25b96ca94d898964b8f0799a889fe0783a2d9.txt", "url": "https://api.github.com/repos/Reza2kn/OBrush"}, {"fetched_at": "2026-10-28T14:38:00.219407+08:00", "kind": "license", "sha256": "9dbf851adad776140bc0070e929a77e46f8ab42a367a7f4f20207efca43444a7", "snapshot_path": "sources/9dbf851adad776140bc0070e929a77e46f8ab42a367a7f4f20207efca43444a7.txt", "url": "https://api.github.com/repos/Reza2kn/OBrush/license"}, {"fetched_at": "2026-10-28T14:36:52.826236+08:00", "kind": "readme", "sha256": "15fcebae32dd0f5373e6edd159358c218806c8892a9aff05287ae7d60f70fc18", "snapshot_path": "sources/15fcebae32dd0f5373e6edd159358c218806c8892a9aff05287ae7d60f70fc18.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/README.md"}, {"fetched_at": "2026-10-28T14:41:12.088304+08:00", "kind": "documentation", "sha256": "97a62eecb9caf2ffa4537f4b3abb3518f626ae9b5b7e14bd337cb64be90bfae0", "snapshot_path": "sources/97a62eecb9caf2ffa4537f4b3abb3518f626ae9b5b7e14bd337cb64be90bfae0.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/CONTROLS.md"}, {"fetched_at": "2026-10-28T14:41:15.252879+08:00", "kind": "documentation", "sha256": "7b4f4397b107dcc1a7e9375846a05d85eb03ca28ca052f5873dd1f6346daadd5", "snapshot_path": "sources/7b4f4397b107dcc1a7e9375846a05d85eb03ca28ca052f5873dd1f6346daadd5.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/SCULPTING_FOUNDATIONS.md"}, {"fetched_at": "2026-10-28T14:43:22.882899+08:00", "kind": "documentation", "sha256": "f4d64f69fbf1d44a79a8f5d6fe819dd2bbc1926ee84f14aa031e4f404e8e5047", "snapshot_path": "sources/f4d64f69fbf1d44a79a8f5d6fe819dd2bbc1926ee84f14aa031e4f404e8e5047.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/WEB_HOSTING.md"}, {"fetched_at": "2026-10-28T14:58:11.806726+08:00", "kind": "documentation", "sha256": "4420cc7b3ac25e7f4f140540f3bc2a58218a4a9736a9d9ac232a0a942cff57ca", "snapshot_path": "sources/4420cc7b3ac25e7f4f140540f3bc2a58218a4a9736a9d9ac232a0a942cff57ca.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/docs/BUILDING.md"}, {"fetched_at": "2026-10-28T14:58:23.493965+08:00", "kind": "license", "sha256": "4e0f7f5f3ceab2d876f7aebf6210d11a9c701f40abe5c49c3a098f413a1e07bc", "snapshot_path": "sources/4e0f7f5f3ceab2d876f7aebf6210d11a9c701f40abe5c49c3a098f413a1e07bc.txt", "url": "https://raw.githubusercontent.com/Reza2kn/OBrush/main/LICENSE-MIT"}, {"fetched_at": "2026-10-28T14:58:23.894554+08:00", "kind": "homepage", "sha256": "f684e39bb2f4b243b8941fe1b4ad6b1b170ee69c8579e64f14924c9c761c23b3", "snapshot_path": "sources/f684e39bb2f4b243b8941fe1b4ad6b1b170ee69c8579e64f14924c9c761c23b3.txt", "url": "https://obrush.app/"}], "summary": "开源（MIT 或 Apache-2.0 双许可）数字雕刻应用，Rust 核心同时构建浏览器静态 WASM 版与桌面版：Draw/Clay/Move/Smooth/Crease 等笔刷配合遮罩、顶点绘制、X 对称与压力控制，支持细分、体素重网格与 PNG alpha，保存可编辑 .obrush 工程并导入导出 OBJ/PLY/STL。当前为公开 alpha，浏览器端以 Rust/WASM + WebGL2 在本地设备运行；README 所称多对象/雕刻图层尚未在 0.1.6 文档落实，场景仍为单网格，本条目不计入该功能。", "technology_stack": ["Rust", "WebAssembly", "WebGL2"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:8684805','JSCAD','{"deployment": ["官方在线 Web 应用 openjscad.xyz（无需安装）", "packages/web 提供可自托管的 Web UI", "另有 CLI 与桌面包，非本类型判定依据"], "features": ["以 JavaScript 代码作为持久的设计定义，声明参数化 2D/3D 几何", "浏览器编辑器内执行代码生成模型并实时预览（CTRL-r 重新渲染）", "修改代码或参数后重新执行，重新生成受影响的结果", "导出 STL、3MF、OBJ、AMF、SVG、DXF 等设计/打印格式", "项目可组织多个零件并复用其它 JavaScript 库"], "github_repository_id": 8684805, "homepage": "https://openjscad.xyz/", "id": "github:8684805", "leaf_matches": [{"reason": "官方 README 说明 JSCAD 是以 JavaScript 代码创建参数化 2D/3D 设计的浏览器与命令行工具集，仓库内置可自托管的 Web UI；官方主页显示用户在编辑器内编写代码、拖入或新建设计，按 CTRL-r 重新渲染得到 3D 结果并导出 STL/3MF。代码即持久可编辑的规则结构，修改后重新执行生成几何，符合本叶“过程为文档、评估产出3D、变更后重算”的核心，且以完整 Web 应用而非仅引擎/SDK 形态提供。", "slug": "procedural-3d-creation-application", "source_urls": ["https://raw.githubusercontent.com/jscad/OpenJSCAD.org/master/README.md", "https://raw.githubusercontent.com/jscad/OpenJSCAD.org/master/packages/web/README.md", "https://openjscad.xyz/"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/jscad/OpenJSCAD.org/license", "license_review": {"rationale": "已通过 GitHub license API 读取该仓库许可证元数据与完整正文（1091 字符，未被截断），SPDX 标识为 MIT，正文包含 MIT 授权与免责条款全文；仓库根目录即此许可证，据此判定主体代码许可证，README 亦声明除特别说明外均适用 MIT。", "reviewer": "OpenCode collection session (open-design/deepseek-v4.1-flash)", "scope": "repository", "source_url": "https://api.github.com/repos/jscad/OpenJSCAD.org/license", "spdx_id": "MIT"}, "name": "JSCAD", "repository_url": "https://github.com/jscad/OpenJSCAD.org", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:34:15.632536+08:00", "kind": "repository_metadata", "sha256": "7adbd0639784f5ec9f9333171ae921763baa245eb860febecf40f2e463ca91ee", "snapshot_path": "sources/7adbd0639784f5ec9f9333171ae921763baa245eb860febecf40f2e463ca91ee.txt", "url": "https://api.github.com/repos/jscad/OpenJSCAD.org"}, {"fetched_at": "2026-10-28T14:35:00.271063+08:00", "kind": "license", "sha256": "d90e0baa312f983f11ea31dbbfdbf4d0252bad00c7fdca234072e10a37c71c56", "snapshot_path": "sources/d90e0baa312f983f11ea31dbbfdbf4d0252bad00c7fdca234072e10a37c71c56.txt", "url": "https://api.github.com/repos/jscad/OpenJSCAD.org/license"}, {"fetched_at": "2026-10-28T14:34:43.083581+08:00", "kind": "readme", "sha256": "655a72e4e52f54f766ede34129a94ebbea40ed9b9956db7352b5c0ded7fb3c30", "snapshot_path": "sources/655a72e4e52f54f766ede34129a94ebbea40ed9b9956db7352b5c0ded7fb3c30.txt", "url": "https://raw.githubusercontent.com/jscad/OpenJSCAD.org/master/README.md"}, {"fetched_at": "2026-10-28T14:35:06.762262+08:00", "kind": "documentation", "sha256": "a085e4e02acd45a8e97b63bde4c09dadf932c08151c5dd2025426d49afe1993a", "snapshot_path": "sources/a085e4e02acd45a8e97b63bde4c09dadf932c08151c5dd2025426d49afe1993a.txt", "url": "https://raw.githubusercontent.com/jscad/OpenJSCAD.org/master/packages/web/README.md"}, {"fetched_at": "2026-10-28T14:35:25.090598+08:00", "kind": "homepage", "sha256": "d162c9d7f99feba01f2d60b20b3a819c17581d60638ff77b21aa2e4b8baa0674", "snapshot_path": "sources/d162c9d7f99feba01f2d60b20b3a819c17581d60638ff77b21aa2e4b8baa0674.txt", "url": "https://openjscad.xyz/"}], "summary": "开源程序化3D设计应用：在浏览器编辑器（官方在线站点或自托管 Web UI）中编写 JavaScript 描述参数化 2D/3D 设计，执行代码后生成几何并预览，可导出 STL、3MF、OBJ 等格式。", "technology_stack": ["JavaScript", "Node.js", "浏览器 Web UI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:133735379','OpenCue','{"deployment": ["自托管：Cuebot 服务端 + PostgreSQL 数据库 + 共享文件系统（常为 NFS），单一 Cuebot 实例供全部用户共享", "渲染节点运行 RQD（Python 或 Rust 实现）注册到 Cuebot 并上报结果", "随附 Docker Compose、Docker 镜像与 Kubernetes 部署路径；CueWeb 可用 Docker/反向代理部署"], "features": ["作业提交到可配置调度队列，并拆分为独立任务/帧级单元", "Cuebot 中央管理服务器统一管理作业提交、向渲染节点分发工作并响应 API 请求", "主机可切分为多个 proc 槽位，各自保留 CPU 核与内存；支持标签把特定作业分配到特定机型", "按帧跟踪状态：FRAME_STARTED/FRAME_COMPLETED/FRAME_FAILED/FRAME_RETRIED，失败帧自动重试，全部帧完成后 JOB_FINISHED 关闭作业", "OpenCueWeb 浏览器界面提供作业/层/帧监视与重试、终止等操作，REST Gateway 提供 HTTP 接口", "管理器自身不计算图像，由 Katana、RenderMan、Arnold 等第三方渲染器在渲染节点执行"], "github_repository_id": 133735379, "homepage": "https://opencue.io", "id": "github:133735379", "leaf_matches": [{"reason": "官方 overview 明确 Cuebot 是中央管理服务器（管理作业提交、向渲染节点派发、响应客户端 API），RQD 在各渲染主机注册并回报结果；deploying-cuebot 说明单一 Cuebot 实例由全体用户共享，需 PostgreSQL 与共享文件系统；CueWeb 为浏览器端完整管理应用。README 证作业拆分为独立任务进入可配置派发队列、主机切分为 proc 槽位、标签限定机型；monitoring reference 证 FRAME_STARTED/COMPLETED/FAILED/RETRIED 与全部帧完成后 JOB_FINISHED，构成帧级分解—调度—跟踪—失败重试—关闭作业的闭环。故此前“只证到客户端/CLI”的缺口已由官方服务端文档闭合。", "slug": "rendering-management-application", "source_urls": ["https://raw.githubusercontent.com/AcademySoftwareFoundation/OpenCue/master/README.md", "https://docs.opencue.io/docs/concepts/opencue-overview/", "https://docs.opencue.io/docs/getting-started/deploying-cuebot/", "https://docs.opencue.io/docs/concepts/cueweb-rest-gateway/", "https://docs.opencue.io/docs/reference/monitoring-reference"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/AcademySoftwareFoundation/OpenCue/license", "name": "OpenCue", "repository_url": "https://github.com/AcademySoftwareFoundation/OpenCue", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T13:16:43.794916+08:00", "kind": "repository_metadata", "sha256": "ebac2399fa0037a722e319f0f9e390949ad4873c8dd88f4fb9cb3bebcf5625e5", "snapshot_path": "sources/ebac2399fa0037a722e319f0f9e390949ad4873c8dd88f4fb9cb3bebcf5625e5.txt", "url": "https://api.github.com/repos/AcademySoftwareFoundation/OpenCue"}, {"fetched_at": "2026-10-24T13:20:59.675765+08:00", "kind": "license", "sha256": "e8b45e8d3824b50a30b547d66fc71ca5c2b15c0476b96ddf5c9dd40402eb31b5", "snapshot_path": "sources/e8b45e8d3824b50a30b547d66fc71ca5c2b15c0476b96ddf5c9dd40402eb31b5.txt", "url": "https://api.github.com/repos/AcademySoftwareFoundation/OpenCue/license"}, {"fetched_at": "2026-10-24T13:22:01.585920+08:00", "kind": "readme", "sha256": "c6b29a19ef0bee6b85231d0e5daec6c65f4030487e7c194f4c0eaac44204779e", "snapshot_path": "sources/c6b29a19ef0bee6b85231d0e5daec6c65f4030487e7c194f4c0eaac44204779e.txt", "url": "https://raw.githubusercontent.com/AcademySoftwareFoundation/OpenCue/master/README.md"}, {"fetched_at": "2026-10-25T23:17:09.058312+08:00", "kind": "documentation", "sha256": "ced04c1a8e74cd60ac66ab6a9c4fe3e75ca2a6f70178c50962fbad3178322435", "snapshot_path": "sources/ced04c1a8e74cd60ac66ab6a9c4fe3e75ca2a6f70178c50962fbad3178322435.txt", "url": "https://docs.opencue.io/docs/reference/monitoring-reference"}, {"fetched_at": "2026-10-28T14:40:52.501203+08:00", "kind": "documentation", "sha256": "5c4a800b7468fe2e43b484c0730ec57c4784a08cd9c934c4010856e0c08962fb", "snapshot_path": "sources/5c4a800b7468fe2e43b484c0730ec57c4784a08cd9c934c4010856e0c08962fb.txt", "url": "https://docs.opencue.io/docs/concepts/opencue-overview/"}, {"fetched_at": "2026-10-28T14:40:51.441902+08:00", "kind": "documentation", "sha256": "67669ac1666666b9c1ed9c9fa448dd2e44042c17bbe192b85d78adb988cebadf", "snapshot_path": "sources/67669ac1666666b9c1ed9c9fa448dd2e44042c17bbe192b85d78adb988cebadf.txt", "url": "https://docs.opencue.io/docs/getting-started/deploying-cuebot/"}, {"fetched_at": "2026-10-28T14:42:06.439942+08:00", "kind": "documentation", "sha256": "b09d09a5dcca551b1ad3faec36c873461313f83b25296e564ef867976d2596ed", "snapshot_path": "sources/b09d09a5dcca551b1ad3faec36c873461313f83b25296e564ef867976d2596ed.txt", "url": "https://docs.opencue.io/docs/concepts/cueweb-rest-gateway/"}, {"fetched_at": "2026-10-28T14:42:04.025684+08:00", "kind": "documentation", "sha256": "581ce1572025f91677e34d64d6060b2fee3d3ff4856e7ed597248eeb9b973f21", "snapshot_path": "sources/581ce1572025f91677e34d64d6060b2fee3d3ff4856e7ed597248eeb9b973f21.txt", "url": "https://docs.opencue.io/docs/getting-started/deploying-cueweb/"}, {"fetched_at": "2026-10-28T14:42:21.645130+08:00", "kind": "readme", "sha256": "342e8ea142153c45bfb78363963a078f3092b11349fb804440d162512a55deee", "snapshot_path": "sources/342e8ea142153c45bfb78363963a078f3092b11349fb804440d162512a55deee.txt", "url": "https://raw.githubusercontent.com/AcademySoftwareFoundation/OpenCue/master/cueweb/README.md"}], "summary": "开源渲染管理系统：以 Cuebot 中央服务接收制作工具提交的渲染作业，拆分为帧级任务，调度到渲染机群槽位并跟踪至完成，提供 CueWeb 浏览器界面与 REST 网关。", "technology_stack": ["Java", "Python", "Rust", "PostgreSQL", "gRPC", "Next.js", "React"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:182806722','Quant-UX','{"deployment": ["官方 Docker Compose（qux-fe、qux-be、MongoDB；WebSocket 通过 QUX_WS_URL 配置）", "README 提到的社区 Docker 部署仓库与手工安装（Node.js 前端 + Java 后端 + MongoDB + SMTP）"], "features": ["画布上创建屏幕并添加可交互组件（输入框、复选、按钮等），通过链接定义页面间交互", "屏幕转场：在源组件/屏幕与目标屏幕之间建立链接，可在 Action 中设置淡入/滑入等动画、时长与缓动", "Logic Flows：在按钮与多个页面之间插入逻辑算子并按输入规则选择下一屏", "分享链接启动原型；可配置欢迎语、任务步骤与录像，测试者可完成用户任务", "分析页提供点击热图、测试覆盖率、时长等 KPI，并支持 A/B 测试对比", "官方 Docker Compose（前端、Java 后端、MongoDB，含 WebSocket 地址配置）自托管"], "github_repository_id": 182806722, "homepage": "https://quant-ux.com", "id": "github:182806722", "leaf_matches": [{"reason": "官方 Prototype 功能页正文说明在画布上创建屏幕、添加功能性组件并通过链接建立交互；Animations 文档说明需先建立源组件/屏幕到目标屏幕的链接，再在 Action 中配置动画、时长与缓动；Logic Flows 文档说明按钮经逻辑算子按输入规则选择下一屏；User Testing 文档说明点击 Share 生成分享链接、测试者打开链接即启动原型，并可配置欢迎语与用户任务及其步骤；Analytic 文档说明点击热图、测试覆盖率与时长等 KPI；README 给出前端 + Java 后端 + MongoDB 的 Docker Compose 自托管方式。覆盖屏幕→用户定义交互→可点击流程→运行（分享链接）→测试反馈的验证闭环，产物为虚构数据上的模拟而非生产系统。", "slug": "ux-prototyping-application", "source_urls": ["https://www.quant-ux.com/features/prototype", "https://www.quant-ux.com/docs/animations", "https://www.quant-ux.com/docs/logic_flows", "https://www.quant-ux.com/docs/testing", "https://www.quant-ux.com/features/user_testing", "https://www.quant-ux.com/docs/analytic_intro", "https://raw.githubusercontent.com/KlausSchaefers/quant-ux/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/KlausSchaefers/quant-ux/license", "name": "Quant-UX", "repository_url": "https://github.com/KlausSchaefers/quant-ux", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T14:50:59.864103+08:00", "kind": "repository_metadata", "sha256": "c12b1dca694744a966d81e7009f55f83927854ac86c2d285d75b9fc6bf0b2b1f", "snapshot_path": "sources/c12b1dca694744a966d81e7009f55f83927854ac86c2d285d75b9fc6bf0b2b1f.txt", "url": "https://api.github.com/repos/KlausSchaefers/quant-ux"}, {"fetched_at": "2026-10-28T14:51:15.087530+08:00", "kind": "license", "sha256": "58e50129c46f27de3273c297441280dc3cf382cd6d9028e0794f92c2d8af439d", "snapshot_path": "sources/58e50129c46f27de3273c297441280dc3cf382cd6d9028e0794f92c2d8af439d.txt", "url": "https://api.github.com/repos/KlausSchaefers/quant-ux/license"}, {"fetched_at": "2026-10-28T14:51:18.777814+08:00", "kind": "readme", "sha256": "33a59bb765feff6ce5ddba8139bd83c729ed88135dafa2f1281af6639fb20f59", "snapshot_path": "sources/33a59bb765feff6ce5ddba8139bd83c729ed88135dafa2f1281af6639fb20f59.txt", "url": "https://raw.githubusercontent.com/KlausSchaefers/quant-ux/master/README.md"}, {"fetched_at": "2026-10-28T15:07:47.062928+08:00", "kind": "documentation", "sha256": "6ca434048ae073423a5a9e473388d80fa361dd664970c1cb6d2fa0073a3f4c08", "snapshot_path": "sources/6ca434048ae073423a5a9e473388d80fa361dd664970c1cb6d2fa0073a3f4c08.txt", "url": "https://www.quant-ux.com/features/prototype"}, {"fetched_at": "2026-10-28T15:07:41.945469+08:00", "kind": "documentation", "sha256": "342a8922660fbf40019dda2960f24a7fb71cdb1a9758452420e54731ceb1ef29", "snapshot_path": "sources/342a8922660fbf40019dda2960f24a7fb71cdb1a9758452420e54731ceb1ef29.txt", "url": "https://www.quant-ux.com/docs/animations"}, {"fetched_at": "2026-10-28T15:10:17.544998+08:00", "kind": "documentation", "sha256": "e38a755c635050d023e4a6ed1438cf35ab47c8833a3b49f9d725a99570f201ce", "snapshot_path": "sources/e38a755c635050d023e4a6ed1438cf35ab47c8833a3b49f9d725a99570f201ce.txt", "url": "https://www.quant-ux.com/docs/logic_flows"}, {"fetched_at": "2026-10-28T15:08:09.099543+08:00", "kind": "documentation", "sha256": "a4b39b9490eb654acd64204625fc3a0d13cf4be1a384dba86fe12207b7e1439a", "snapshot_path": "sources/a4b39b9490eb654acd64204625fc3a0d13cf4be1a384dba86fe12207b7e1439a.txt", "url": "https://www.quant-ux.com/docs/testing"}, {"fetched_at": "2026-10-28T15:08:14.609074+08:00", "kind": "documentation", "sha256": "c32325b3b934dece375de04ee3f20cd5d1c1940a19f007cb96c6207306794004", "snapshot_path": "sources/c32325b3b934dece375de04ee3f20cd5d1c1940a19f007cb96c6207306794004.txt", "url": "https://www.quant-ux.com/features/user_testing"}, {"fetched_at": "2026-10-28T15:09:24.219259+08:00", "kind": "documentation", "sha256": "8c0fb7df724d893aa19359ebcd376261d954d63024980c6aa7b6e8ccaafe6beb", "snapshot_path": "sources/8c0fb7df724d893aa19359ebcd376261d954d63024980c6aa7b6e8ccaafe6beb.txt", "url": "https://www.quant-ux.com/docs/analytic_intro"}], "summary": "开源 UX 原型与可用性测试 Web 应用：在画布上创建屏幕与可交互组件，通过链接把源元素/屏幕指向目标屏幕并配置转场动画与条件导航，运行分享链接让测试者完成用户任务，并在分析页查看热图与任务 KPI；官方提供 Docker Compose 自托管。", "technology_stack": ["Vue/Node.js（前端仓库，自带 Web 服务器与代理）", "Java（后端为独立仓库 qux-java，其许可证不在本条目声明范围内）", "MongoDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16652218','Overleaf','{"deployment": ["自托管：Overleaf Community Edition（Docker 镜像，经 Overleaf Toolkit 安装）", "官方托管服务：www.overleaf.com"], "features": ["以 LaTeX 纯文本源文件为文档记录，编辑器提供 Code Editor 与 Visual Editor 两种编辑方式", "通过 documentclass、宏包与模板构成可复用设计层，一处修改作用于整篇文档", "TeX 引擎读取源文件并计算断行、分页、编号、交叉引用与参考文献，输出排版后的 PDF", "基于模板库与示例工程起步，支持实时协作、评论与项目历史", "Community Edition 以 Docker 镜像形式提供完整自托管 Web 应用"], "github_repository_id": 16652218, "homepage": "https://www.overleaf.com", "id": "github:16652218", "leaf_matches": [{"reason": "官方教程正文说明 LaTeX 文档是以纯文本加命令编写的源文件，经 TeX 引擎组合为排版 PDF，并介绍 documentclass、宏包与模板构成的设计层；README 与官方站点证明其以完整 Web 应用（Community Edition 可自托管、官方托管服务）承载编辑→编译→下载 PDF 的工作循环，对应“标记源→设计层→引擎组合→再生交付物”的定义性核心。", "slug": "professional-typesetting-application", "source_urls": ["https://raw.githubusercontent.com/overleaf/overleaf/HEAD/README.md", "https://www.overleaf.com/", "https://www.overleaf.com/learn/latex/Learn_LaTeX_in_30_minutes"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/overleaf/overleaf/license", "name": "Overleaf", "repository_url": "https://github.com/overleaf/overleaf", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:11:34.352818+08:00", "kind": "repository_metadata", "sha256": "0f325505b0b4a50e93fd9f32dca90a4842c2f333499a147f93a8b8c6ef77c83b", "snapshot_path": "sources/0f325505b0b4a50e93fd9f32dca90a4842c2f333499a147f93a8b8c6ef77c83b.txt", "url": "https://api.github.com/repos/overleaf/overleaf"}, {"fetched_at": "2026-10-28T15:11:50.984799+08:00", "kind": "readme", "sha256": "8293b68998a5ade1f1899a85341bfa55f1ec373d5dd1b0e2b6525e04c6bd5c19", "snapshot_path": "sources/8293b68998a5ade1f1899a85341bfa55f1ec373d5dd1b0e2b6525e04c6bd5c19.txt", "url": "https://raw.githubusercontent.com/overleaf/overleaf/HEAD/README.md"}, {"fetched_at": "2026-10-28T15:11:51.390536+08:00", "kind": "license", "sha256": "dc6ea6d96fc2c2f5f46b6e2865d83a3aa2ac7f6c8f22dccd2776534dde456bdf", "snapshot_path": "sources/dc6ea6d96fc2c2f5f46b6e2865d83a3aa2ac7f6c8f22dccd2776534dde456bdf.txt", "url": "https://api.github.com/repos/overleaf/overleaf/license"}, {"fetched_at": "2026-10-28T15:12:09.703541+08:00", "kind": "homepage", "sha256": "079c030c63784c9ede5826b0d65b9e6d2e73aa275f7cfb8412a98d59ad0eb121", "snapshot_path": "sources/079c030c63784c9ede5826b0d65b9e6d2e73aa275f7cfb8412a98d59ad0eb121.txt", "url": "https://www.overleaf.com/"}, {"fetched_at": "2026-10-28T15:12:36.431178+08:00", "kind": "documentation", "sha256": "28f8017b5479b1ba871a675f1b97e5e58dc2dc6b705d32c4614bbf7cd78aed5a", "snapshot_path": "sources/28f8017b5479b1ba871a675f1b97e5e58dc2dc6b705d32c4614bbf7cd78aed5a.txt", "url": "https://www.overleaf.com/learn/latex/Learn_LaTeX_in_30_minutes"}], "summary": "基于 LaTeX 的在线协作排版编辑器：以带标记的纯文本源文件撰写文档，由 TeX 引擎组合为分页 PDF；Community Edition 开源并可自托管。", "technology_stack": ["JavaScript / Node.js", "TeX Live", "Docker", "AGPL-3.0"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:430681576','Fontra','{"deployment": ["自托管：Python 服务器以 `fontra --launch filesystem /path/to/fonts` 启动，浏览器访问本地端口进行编辑", "远程/多用户：README 记录经 fontra-rcjk、django-robo-cjk 在 NGINX 后做带数据库存储的多用户服务器部署", "桌面发行版：Fontra Pak 为 macOS、Windows、Linux(x86_64) 的自包含 Fontra 服务器应用，在默认浏览器中编辑，另有 Flatpak/Snap 社区包"], "features": ["浏览器内字形编辑：轮廓点与钢笔工具、组件、锚点、字形级参考线、变换面板、撤销/重做", "字体级编辑：字体信息、字距、OpenType 特性、变体轴与 avar 映射", "字体项目读写：.designspace、.ufo、.ttf/.otf（读取）以及经插件读写 .glyphs", "客户端/服务器架构，服务器可本地启动或部署在远程机器，客户端与服务器经 WebSocket 传输 JSON", "通过 Fontra Pak 导出 .ttf/.otf 与变量字体，并集成 FontMake；另有 fontra-compile 实验性导出"], "github_repository_id": 430681576, "homepage": "https://fontra.xyz", "id": "github:430681576", "leaf_matches": [{"reason": "仓库 GitHub 元数据将 Fontra 描述为 browser-based font editor，README 说明其由浏览器客户端与 Python 服务器组成，服务器可本地或远程运行并支持多用户数据库部署；项目以 .designspace/.ufo 等字体项目为持久对象，提供字形轮廓点/钢笔编辑、组件与锚点、字距、OpenType 特性、变体轴等字体级编辑，并可通过 Fontra Pak 导出 .ttf/.otf，覆盖“字体项目→字形集→字形图形在字体几何上编辑→编译为可安装字体文件”的定义性核心，且为可自托管的完整 Web 应用而非纯客户端工具。", "slug": "font-editor", "source_urls": ["https://api.github.com/repos/fontra/fontra", "https://raw.githubusercontent.com/fontra/fontra/main/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/fontra/fontra/license", "name": "Fontra", "repository_url": "https://github.com/fontra/fontra", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:16:14.585733+08:00", "kind": "repository_metadata", "sha256": "511d6d86a317444bea13a9f88dca1f0d77bb6f02c996a0d15f81799f5be7d072", "snapshot_path": "sources/511d6d86a317444bea13a9f88dca1f0d77bb6f02c996a0d15f81799f5be7d072.txt", "url": "https://api.github.com/repos/fontra/fontra"}, {"fetched_at": "2026-10-28T15:16:16.049364+08:00", "kind": "readme", "sha256": "2f097d4b0fdb915efc4d8a3037240be19ca442127d12f3615d75660acecb5f78", "snapshot_path": "sources/2f097d4b0fdb915efc4d8a3037240be19ca442127d12f3615d75660acecb5f78.txt", "url": "https://raw.githubusercontent.com/fontra/fontra/main/README.md"}, {"fetched_at": "2026-10-28T15:16:36.274290+08:00", "kind": "license", "sha256": "54b1cfafe0b6c3ce3b70bed5d90d9721a2d1622ccb373e3a4be02e89d9de8df1", "snapshot_path": "sources/54b1cfafe0b6c3ce3b70bed5d90d9721a2d1622ccb373e3a4be02e89d9de8df1.txt", "url": "https://api.github.com/repos/fontra/fontra/license"}], "summary": "浏览器字体编辑器（开发中）：JavaScript 客户端配合可本地或远程运行的 Python 服务器，读写 .designspace、.ufo 等字体项目并进行字形轮廓与字体级编辑，可经 Fontra Pak 导出 .ttf/.otf 字体文件。", "technology_stack": ["JavaScript（浏览器客户端）", "Python（服务器，要求 Python >= 3.11）", "WebSocket / JSON 通信", "GPL-3.0"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:136254950','Glyphr Studio','{"deployment": ["纯浏览器前端应用，可在官网直接打开使用，无需注册账号", "构建产物为静态 HTML/JavaScript/CSS，可自托管于本地或在线静态服务器", "运行不依赖后端服务"], "features": ["新建具名项目或载入已有 .gs2 项目（及 v1 .txt 项目）作为可重编辑的字体项目文档；自动保存默认开启，最近一次修改写入浏览器本地存储，可从 Restore 列表恢复", "项目文件保存全部元数据与字形轮廓，官方建议与导出的字体文件一并保存", "以 Unicode 码位识别字符：可启用任意 Unicode 平面/字符区间（默认 Basic Latin），在 Settings > Project 中搜索并添加区间", "在编辑画布上直接用矩形、椭圆、路径工具绘制轮廓，并用路径点与手柄（Pen/Path edit）调整曲线；Zoom 1:1 定义为 1 像素等于项目 1 em 单位", "侧边距与 advance width：导入 SVG 时可选择自动加左右 side bearing，使形状获得整体 advance width；画布提供 guides 与 overshoot", "水平字距与 class-based kern 组（左右字符组可各给一个值，导出时展开为逐对 kern pair）", "连字（ligatures）、可复用组件（components）与上下文预览字符", "导入 OTF/TTF/WOFF 与 SVG Font；导出 OTF/TTF/WOFF/WOFF2 与 SVG Font", "编辑时实时预览（Live Preview 弹出窗口 / Distraction Free Preview）", "100% 在浏览器内运行，无需下载或注册；构建产物为静态 HTML/JS/CSS，可部署于本地或在线静态服务器且不依赖后端"], "github_repository_id": 136254950, "homepage": "https://www.glyphrstudio.com/", "id": "github:136254950", "leaf_matches": [{"reason": "四项定义性属性逐条落到官方正文段落（帮助站 HTML 快照的 div.vp-doc 内正文，并以官方 Help 仓库 markdown 原文复核）：(1) 持久字体项目——open-project.md「Start a new Glyphr Studio project…Just provide a project name and a default project will be created」「Auto-save is enabled by default…saved to your browser''s local storage…Restore tab shows a list of these auto-saved projects」，import-export.md「The Glyphr Studio Project file contains all the information about your project, including metadata and glyph outlines」「.gs2 file suffix」；(2) 带字符映射的字形集——characters.md「Code point…is also how Glyphr Studio identifies characters in a project」「you can enable any range of characters you want (the default is the ''Basic Latin'' character range)」与 features.md「Editing any character in Unicode…Planes 0 through 3…have range names and can be searched for and added」；(3) 在字体自身几何上直接绘制——editing.md「New Path…Click and drag to add a point with symmetric handles」「Path edit…move that point or move it''s handles」「Zoom 1:1…1 pixel on your screen is equal to 1 Em unit from your project」「add in Left and Right Side Bearings to give the imported shape an overall Advance Width」，import-export.md 元数据表列出 unitsPerEm/ascender/descender；(4) 生成可用字体文件——import-export.md「can export your project as a font file in four formats: .otf, .ttf, .woff, and .woff2」，features.md 支持格式清单，首页「Export fonts / Generate ready-to-use font files straight from your browser」。服务形态：首页与 README 明确 100% in-browser、免注册、静态构建无后端。边界：features.md 列出不支持彩色字体、可变字体、多母版/插值、RTL、垂直排版、上下文/样式替代与 OpenType 特性。六份 help HTML 快照经复核确实内嵌上述正文（此前初审判断其为纯外壳不成立），markdown 原文另存以便直接核对。", "slug": "typeface-design-application", "source_urls": ["https://www.glyphrstudio.com/", "https://www.glyphrstudio.com/help/pages/open-project.html", "https://www.glyphrstudio.com/help/getting-started/import-export.html", "https://www.glyphrstudio.com/help/getting-started/editing.html", "https://www.glyphrstudio.com/help/pages/kerning.html", "https://www.glyphrstudio.com/help/about/features.html", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/open-project.md", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/getting-started/import-export.md", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/getting-started/editing.md", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/characters.md", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/kerning.md", "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/about/features.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2/main/LICENSE-gpl-3.0.txt", "license_review": {"rationale": "许可证结论以本条目 license_evidence_url 指向的仓库根 LICENSE-gpl-3.0.txt 快照为依据：该文件含 GNU GENERAL PUBLIC LICENSE Version 3, 29 June 2007 标题、Preamble、TERMS AND CONDITIONS 0–17 条与 END OF TERMS AND CONDITIONS 全文。README 自述 “released under GPL 3.0”。另有官方 Help 仓库 about/licensing.md 正文（快照 c5ee0d30）写明 “Glyphr Studio, the font editing software code itself, is licensed under GPL v3.0” 并链接本仓库。项目自身声明未写 “or later”，故按 GPL-3.0 记录（等价于 GPL-3.0-only 的严格解读）；README 中指向 mattlag/Glyphr-Studio 的 v1 许可证链接不作为本仓库许可依据。", "reviewer": "OpenDesign unit 57 collector", "scope": "repository", "source_url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2/main/LICENSE-gpl-3.0.txt", "spdx_id": "GPL-3.0"}, "name": "Glyphr Studio", "repository_url": "https://github.com/glyphr-studio/Glyphr-Studio-2", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:21:22.529145+08:00", "kind": "repository_metadata", "sha256": "c156e13357211abe981e68eb5e63020b9309a9fd2208a368f767539f714207b7", "snapshot_path": "sources/c156e13357211abe981e68eb5e63020b9309a9fd2208a368f767539f714207b7.txt", "url": "https://api.github.com/repos/glyphr-studio/Glyphr-Studio-2"}, {"fetched_at": "2026-10-28T15:21:53.927168+08:00", "kind": "license", "sha256": "4d383a04fb2e81b79012eafe0420b1b60a0c097f4193c27d083b7c50af2f337f", "snapshot_path": "sources/4d383a04fb2e81b79012eafe0420b1b60a0c097f4193c27d083b7c50af2f337f.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2/main/LICENSE-gpl-3.0.txt"}, {"fetched_at": "2026-10-28T15:21:32.710741+08:00", "kind": "readme", "sha256": "1db6fe519715b5d9ed0f394dee592ef431ef998e701d8a1c2812e254b8105ea7", "snapshot_path": "sources/1db6fe519715b5d9ed0f394dee592ef431ef998e701d8a1c2812e254b8105ea7.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2/main/README.md"}, {"fetched_at": "2026-10-28T15:22:15.972133+08:00", "kind": "homepage", "sha256": "d4f243433d97081351d1ea0c240a823c3f8126c1f15dcd5b8b9426ef6a9e8baa", "snapshot_path": "sources/d4f243433d97081351d1ea0c240a823c3f8126c1f15dcd5b8b9426ef6a9e8baa.txt", "url": "https://www.glyphrstudio.com/"}, {"fetched_at": "2026-10-28T15:22:46.312064+08:00", "kind": "documentation", "sha256": "a9cfafefdb623819c40601c750574ab8d113ff808d368209b415ee2d60a52e64", "snapshot_path": "sources/a9cfafefdb623819c40601c750574ab8d113ff808d368209b415ee2d60a52e64.txt", "url": "https://www.glyphrstudio.com/help/about/features.html"}, {"fetched_at": "2026-10-28T15:22:45.377721+08:00", "kind": "documentation", "sha256": "3d85524c506adaefc41f840a95d15cb461a7cb3b673b22cc41796b101f3ca3e7", "snapshot_path": "sources/3d85524c506adaefc41f840a95d15cb461a7cb3b673b22cc41796b101f3ca3e7.txt", "url": "https://www.glyphrstudio.com/help/about/licensing.html"}, {"fetched_at": "2026-10-28T15:23:40.912074+08:00", "kind": "documentation", "sha256": "95e5cc806458237de1397a025cc3a1fbfeca3b44ec5b86a634c1c647b659cbad", "snapshot_path": "sources/95e5cc806458237de1397a025cc3a1fbfeca3b44ec5b86a634c1c647b659cbad.txt", "url": "https://www.glyphrstudio.com/help/getting-started/import-export.html"}, {"fetched_at": "2026-10-28T15:24:36.790958+08:00", "kind": "documentation", "sha256": "3c63939de2c06ef76d7b3f3894296c6c9d9b90baf4781aa27d2a156854ede636", "snapshot_path": "sources/3c63939de2c06ef76d7b3f3894296c6c9d9b90baf4781aa27d2a156854ede636.txt", "url": "https://www.glyphrstudio.com/help/getting-started/editing.html"}, {"fetched_at": "2026-10-28T15:24:13.068037+08:00", "kind": "documentation", "sha256": "3c007b69ea2a70bf175398d5f47c92b92c6ce91a90b83c9a98e6eeae7c90d649", "snapshot_path": "sources/3c007b69ea2a70bf175398d5f47c92b92c6ce91a90b83c9a98e6eeae7c90d649.txt", "url": "https://www.glyphrstudio.com/help/pages/kerning.html"}, {"fetched_at": "2026-10-28T15:23:41.758321+08:00", "kind": "documentation", "sha256": "99cef03f60f1bd3756fd7a139c10c4f9615dd49967f5560b917cfc9b64b59a73", "snapshot_path": "sources/99cef03f60f1bd3756fd7a139c10c4f9615dd49967f5560b917cfc9b64b59a73.txt", "url": "https://www.glyphrstudio.com/help/pages/open-project.html"}, {"fetched_at": "2026-10-28T15:35:01.510424+08:00", "kind": "documentation", "sha256": "d316bb0c89c39b48ee1c2905a506e550aa612475d103f6ae381849b894421a90", "snapshot_path": "sources/d316bb0c89c39b48ee1c2905a506e550aa612475d103f6ae381849b894421a90.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/about/features.md"}, {"fetched_at": "2026-10-28T15:35:15.485358+08:00", "kind": "documentation", "sha256": "43bbe040e14d239527d94008674c110bbf908e7f6f48577f6172d81634b8d385", "snapshot_path": "sources/43bbe040e14d239527d94008674c110bbf908e7f6f48577f6172d81634b8d385.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/getting-started/import-export.md"}, {"fetched_at": "2026-10-28T15:35:16.912139+08:00", "kind": "documentation", "sha256": "9883ce0c36ce28f20fade6a6d29fe65d2deb5e173be949e5f141173e488be9c0", "snapshot_path": "sources/9883ce0c36ce28f20fade6a6d29fe65d2deb5e173be949e5f141173e488be9c0.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/getting-started/editing.md"}, {"fetched_at": "2026-10-28T15:35:18.431533+08:00", "kind": "documentation", "sha256": "9809b9f113a1c743142d2fba41937987f6944aad7521fefd3b051e076dc37533", "snapshot_path": "sources/9809b9f113a1c743142d2fba41937987f6944aad7521fefd3b051e076dc37533.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/kerning.md"}, {"fetched_at": "2026-10-28T15:35:21.526383+08:00", "kind": "documentation", "sha256": "a6d9524813873755b00fb63dcfeaeb383d7ccab9f460105ebea5349545c3d155", "snapshot_path": "sources/a6d9524813873755b00fb63dcfeaeb383d7ccab9f460105ebea5349545c3d155.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/open-project.md"}, {"fetched_at": "2026-10-28T15:35:23.017942+08:00", "kind": "documentation", "sha256": "0de07fd5702b76a8037b9cdffed9b70d2f6d76d3845ca76fdc274b6ba2b548c3", "snapshot_path": "sources/0de07fd5702b76a8037b9cdffed9b70d2f6d76d3845ca76fdc274b6ba2b548c3.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/pages/characters.md"}, {"fetched_at": "2026-10-28T15:35:26.901354+08:00", "kind": "documentation", "sha256": "c5ee0d30c91412316b261a142099e1a8f041ebfc8382cb638f54568370d8f43f", "snapshot_path": "sources/c5ee0d30c91412316b261a142099e1a8f041ebfc8382cb638f54568370d8f43f.txt", "url": "https://raw.githubusercontent.com/glyphr-studio/Glyphr-Studio-2-Help/main/docs/about/licensing.md"}], "summary": "开源浏览器端字体编辑器（GPL-3.0，社区版即完整应用仓库，无付费分层）：以 .gs2 项目文件持久保存并自动备份，按 Unicode 码位编辑字符、连字与组件，在 em 坐标画布上用路径点与手柄绘制轮廓并调整侧边距与字距，导出 OTF/TTF/WOFF/WOFF2 字体文件；可在线使用或自托管静态构建，无需注册。", "technology_stack": ["JavaScript", "Vite（模块构建）", "FontFlux JS（字体文件导入导出）", "bezier-boolean（路径布尔运算）", "浏览器本地存储（项目自动保存）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:shipbob','ShipBob','{"homepage": "https://www.shipbob.com/", "id": "commercial:shipbob", "leaf_matches": [{"reason": "ShipBob WMS 官方页明确面向“拥有自己仓库”的商家，列出仓库管理、库存管理、订单管理、运输管理、拣货与打包，以及分批/自动聚类/单订单拣货与逐步打包流程；并说明可按地点查看库存、查看 picked/packed/labeled 状态订单、做订单路由与承运商选择，并接入主流电商平台与市场以支撑自有仓库的全渠道履约。此处只据该页认定自有仓库内运行的履约软件形态；页面未逐条展示挂单与库位级分配细节，属证据缺口。", "slug": "e-commerce-fulfillment-management", "source_urls": ["https://www.shipbob.com/wms/"]}], "name": "ShipBob", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:29:17.926704+08:00", "kind": "documentation", "sha256": "3af04d12fb45eaa6b94495d07e7354a414c09305907924626701fdad05194d37", "snapshot_path": "sources/3af04d12fb45eaa6b94495d07e7354a414c09305907924626701fdad05194d37.txt", "url": "https://www.shipbob.com/wms/"}], "summary": "电商履约服务商，同时提供 ShipBob WMS：卖家在自有仓库中使用的云端仓库/履约软件，覆盖库存与订单管理、分批与单订单拣货、打包核对、承运商选择及销售渠道接入。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:veeqo','Veeqo','{"homepage": "https://www.veeqo.com/", "id": "commercial:veeqo", "leaf_matches": [{"reason": "官方功能页写明集中管理 Amazon、eBay、Shopify 等渠道订单且订单状态自动回写相应渠道；库存实时同步到所有销售渠道；拣货页写明把 ready-to-ship 订单分批、按优化路径拣货并在错误时告警、在打包台打印标签，发货页提供 21+ 承运商标签购买与打印。覆盖渠道订单→库存同步→拣选/打包→承运商发货→回传渠道。", "slug": "e-commerce-fulfillment-management", "source_urls": ["https://www.veeqo.com/shipping-software/shipping-features", "https://www.veeqo.com/picking-and-packing-software", "https://www.veeqo.com/"]}], "name": "Veeqo", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:25:17.202326+08:00", "kind": "homepage", "sha256": "c4bdebe41498699b0d30714e1b43655f10a55a718e8a117636c06196052a8949", "snapshot_path": "sources/c4bdebe41498699b0d30714e1b43655f10a55a718e8a117636c06196052a8949.txt", "url": "https://www.veeqo.com/"}, {"fetched_at": "2026-10-28T15:24:53.251221+08:00", "kind": "documentation", "sha256": "a7b422f6dd4513c7644dd90a30363ae03b35a2d4756b9bab7f2021f64647a1bb", "snapshot_path": "sources/a7b422f6dd4513c7644dd90a30363ae03b35a2d4756b9bab7f2021f64647a1bb.txt", "url": "https://www.veeqo.com/picking-and-packing-software"}, {"fetched_at": "2026-10-28T15:27:31.755750+08:00", "kind": "documentation", "sha256": "d083814d0883d7d27b70fc65c82e70edfa0d323a15bf1ebc2cf4bb1fafcd0799", "snapshot_path": "sources/d083814d0883d7d27b70fc65c82e70edfa0d323a15bf1ebc2cf4bb1fafcd0799.txt", "url": "https://www.veeqo.com/shipping-software/shipping-features"}], "summary": "面向多渠电商卖家的仓库与发货软件：集中接收各销售渠道订单，实时同步库存，支持分批拣货、扫描核对、打包与 21+ 承运商标签购买，并将订单状态回写渠道。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:522877749','aiku','{"deployment": ["README 提供源码自托管步骤：composer install、npm install、配置 .env、php artisan migrate --seed、npm run dev", "技术栈为 PHP 8.4 / Laravel、PostgreSQL、Redis、Typesense，前端 Vue 3 + Inertia，另提供 React Native 手持端"], "features": ["配送单（delivery note）按 to do、queued、handling（picking）、picked、packing、packed、finalised、dispatched 的状态队列推进，并记录拣货人、打包人与发货时间", "仓库与库位管理：区域、库位、库存数量与估值，拣货路径与拣货批次（picking session），打包台、箱型与包裹记录", "承运商 API 与发货：DPD、GLS、APC、CTT、Packeta、ITD，finalise 与 dispatch 合并完成并记录发货时间", "销售渠道接入：Shopify、WooCommerce、Magento、TikTok Shop、Amazon、eBay、Allegro 等，渠道订单进入同一仓库队列，产品、订单与 shipment 双向同步", "手持终端应用用于拣货、打包与扫描"], "github_repository_id": 522877749, "homepage": "https://aiku.io/", "id": "github:522877749", "leaf_matches": [{"reason": "官方文档逐段展示配送单从 to do、queued、handling（picking）、picked、packing、packed、finalised 到 dispatched 的状态队列，拣货批次、打包与包裹记录，以及 finalise+dispatch 时在每一行记录发货时间；README 与首页说明仓库/库位库存与估值、拣货路径与拣货批次、打包台、承运商 API（DPD/GLS/APC/CTT/Packeta/ITD），Shopify/WooCommerce/Amazon/eBay 等渠道订单进入同一仓库队列，且产品、订单与 shipment 双向同步。前三段（渠道订单、自有库存、拣选打包→承运商发货）有正文直接支撑；第四段“发回渠道”仅据 README 的 shipment 双向同步表述，未取得逐渠道回传的步骤正文，属证据缺口。", "slug": "e-commerce-fulfillment-management", "source_urls": ["https://aiku.io/docs/picking-and-packing-a-delivery-note", "https://aiku.io/", "https://raw.githubusercontent.com/Inikoo-Ltd/aiku/main/README.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/Inikoo-Ltd/aiku/license", "name": "aiku", "repository_url": "https://github.com/Inikoo-Ltd/aiku", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:25:15.688352+08:00", "kind": "repository_metadata", "sha256": "18cd9534553d651e9241236ef69ccdfe5b4aee445887aa9c8767f97ddcda0bee", "snapshot_path": "sources/18cd9534553d651e9241236ef69ccdfe5b4aee445887aa9c8767f97ddcda0bee.txt", "url": "https://api.github.com/repos/Inikoo-Ltd/aiku"}, {"fetched_at": "2026-10-28T15:25:40.433499+08:00", "kind": "license", "sha256": "84185963c418487a8988a663c0e7d8bc5eca656b2b652415960ab82ad883689c", "snapshot_path": "sources/84185963c418487a8988a663c0e7d8bc5eca656b2b652415960ab82ad883689c.txt", "url": "https://api.github.com/repos/Inikoo-Ltd/aiku/license"}, {"fetched_at": "2026-10-28T15:25:42.307743+08:00", "kind": "readme", "sha256": "684ddcb7e8cd76b57a7a259a91c2d33807573f3133d8f0494c29640acd9cf9e7", "snapshot_path": "sources/684ddcb7e8cd76b57a7a259a91c2d33807573f3133d8f0494c29640acd9cf9e7.txt", "url": "https://raw.githubusercontent.com/Inikoo-Ltd/aiku/main/README.md"}, {"fetched_at": "2026-10-28T15:27:29.816484+08:00", "kind": "homepage", "sha256": "b71a883f4884303c2d1112e3f7b63146ed72efe1c5c058ad2203964815355537", "snapshot_path": "sources/b71a883f4884303c2d1112e3f7b63146ed72efe1c5c058ad2203964815355537.txt", "url": "https://aiku.io/"}, {"fetched_at": "2026-10-28T15:26:19.146948+08:00", "kind": "documentation", "sha256": "bf9988f0e3d31fd14ae68e9017a8477b5a930c5b2e187ba7193a219dcd8293b3", "snapshot_path": "sources/bf9988f0e3d31fd14ae68e9017a8477b5a930c5b2e187ba7193a219dcd8293b3.txt", "url": "https://aiku.io/docs/picking-and-packing-a-delivery-note"}], "summary": "AGPL-3.0 的开源商务 ERP/Web 应用，内含自营仓库履约子模块：渠道订单进入同一仓库队列，按库位持有库存，配送单按状态推进拣选、打包、承运商发货并回传渠道。", "technology_stack": ["PHP 8.4 / Laravel 13（Octane、Horizon、Passport）", "PostgreSQL 18 + pgvector、Redis、Typesense", "Vue 3、Inertia v2、Tailwind、Vite、TypeScript", "React Native（仓库手持端与员工移动端）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zebra-workcloud-actionable-intelligence','Zebra Workcloud Actionable Intelligence','{"homepage": "https://www.zebra.com/", "id": "commercial:zebra-workcloud-actionable-intelligence", "leaf_matches": [{"reason": "官方正文把损耗表述为可估值的库存问题：对每项库存异常“assigns a proposed monetary value”，覆盖制造商、DC 与门店层级的库存不一致（虚高库存、盘点多计、幻影库存），并以“Total Retail Loss”逐类分析盗窃、欺诈、损坏、过期、退货等成因、揭示 root causes；随后自动派发并追踪纠正任务（盘点、降价、修价、补货），构成量化损耗视图→成因归因→减损导向的完整结构，且明确用于跨门店（“a thousand miles away”）运营。", "slug": "retail-shrink-management", "source_urls": ["https://www.zebra.com/us/en/software/workcloud-solutions/workcloud-inventory-optimization-suite/workcloud-actionable-intelligence.html"]}], "name": "Zebra Workcloud Actionable Intelligence", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:39:24.189834+08:00", "kind": "documentation", "sha256": "c59067273bf49f278d82cee7a6d8a656348de4104fe70a01de31f8d43d689405", "snapshot_path": "sources/c59067273bf49f278d82cee7a6d8a656348de4104fe70a01de31f8d43d689405.txt", "url": "https://www.zebra.com/us/en/software/workcloud-solutions/workcloud-inventory-optimization-suite/workcloud-actionable-intelligence.html"}], "summary": "零售库存与损耗分析应用（原 Zebra Prescriptive Analytics）：汇总门店、DC 与上游库存及交易数据，定位库存异常并为每项问题估算货币价值，按损失类别（盗窃、欺诈、虚高库存、盘点多计、损坏、过期、退货等）提示根因，自动派发并跟踪纠正任务，用于跨门店降低损耗。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1331444342','AI Native Call Center','{"deployment": ["自托管单机全栈：Docker Compose（PostgreSQL + FreeSWITCH + 应用）", "官方一键安装脚本（Linux 安装至 /opt/aicc，macOS 安装至 ~/.aicc）", "从源码构建（Go 应用 + 前端构建产物）"], "features": ["FreeSWITCH 承载 SIP/RTP 实时语音，外部号码呼入与坐席外呼共用同一呼叫账本", "mod_callcenter 队列接收转入通话，按层级/位置与策略（longest-idle-agent、round-robin、least-talk-time 等）分配坐席", "坐席状态机 LOGGED_OUT/NOT_READY/READY 与话后处理（ACW），READY 才可被分配，ACW 期间队列不下发新通话", "坐席浏览器工作台：来电弹屏、接听/保持/挂断、话后处置与本人 CDR；主管实时看板、队列与人员视图", "队列等待音乐、溢出（转机器人流程/转号/挂断）、RONA 与放弃通话原因计入 CDR", "每通通话一条 CDR，含队列等待时长、录音与转写，文件系统或 S3 兼容存储", "单二进制内含 Web 界面与 REST/SSE，附安装器与 Docker Compose 全栈部署"], "github_repository_id": 1331444342, "homepage": "https://github.com/rasonyang/ai-native-callcenter", "id": "github:1331444342", "leaf_matches": [{"reason": "定义三项核心均有正文支撑。电话为工作单元：README 与 01 文档说明 FreeSWITCH 以 SIP/RTP 吸收外部来电、由平台外呼，每条通话生成独立 call id 与 CDR，含队列等待、放弃原因与录音。系统管理分配：01 文档 §4 明确队列由 PG 渲染进 callcenter.conf，含 strategy（longest-idle-agent、round-robin、top-down、least-talk-time 等）、tier 层级/位置，坐席腿由 mod_callcenter 发起并经坐席接听桥接，另有 RONA、溢出与重分配。坐席为运营角色且可用性被系统跟踪：01 文档坐席 FSM 给出 LOGGED_OUT/NOT_READY(原因)/READY/ACW，READY 才参与分配，ACW 期间映射为 On Break 使队列不下发新通话，设备注册状态丢失自动转 NOT_READY。05 文档补充坐席工作台（弹屏、接听、保持、话后处置、本人 CDR）、主管实时看板与队列视图、/admin/cdr 与 /admin/reports 历史报表，故实时与历史度量亦在文内。形态为自托管完整应用服务（单二进制含 Web 界面与 REST/SSE，配 FreeSWITCH、PostgreSQL 与一键安装），非仅客户端或引擎；许可证 Apache-2.0 由 GitHub license API 全文校验。", "slug": "call-center-platform", "source_urls": ["https://api.github.com/repos/rasonyang/ai-native-callcenter", "https://api.github.com/repos/rasonyang/ai-native-callcenter/license", "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/README.md", "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/docs/design/01-telephony.md", "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/docs/design/05-frontend.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/rasonyang/ai-native-callcenter/license", "name": "AI Native Call Center", "repository_url": "https://github.com/rasonyang/ai-native-callcenter", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:44:57.930410+08:00", "kind": "repository_metadata", "sha256": "cae16238cc0dc6bf9d17a025b6f4405ca951393574ee2b69a2c8d77943d87904", "snapshot_path": "sources/cae16238cc0dc6bf9d17a025b6f4405ca951393574ee2b69a2c8d77943d87904.txt", "url": "https://api.github.com/repos/rasonyang/ai-native-callcenter"}, {"fetched_at": "2026-10-28T15:45:14.362777+08:00", "kind": "license", "sha256": "20009e3738e55a8a88979ce565937d9e7dffaabceb56432c837d1b54a18f62ad", "snapshot_path": "sources/20009e3738e55a8a88979ce565937d9e7dffaabceb56432c837d1b54a18f62ad.txt", "url": "https://api.github.com/repos/rasonyang/ai-native-callcenter/license"}, {"fetched_at": "2026-10-28T15:45:15.686800+08:00", "kind": "readme", "sha256": "e1ad89c25c54bbe3a28e2f70b6f6505e8d3c6ec20d8c780c28d02f16efef2303", "snapshot_path": "sources/e1ad89c25c54bbe3a28e2f70b6f6505e8d3c6ec20d8c780c28d02f16efef2303.txt", "url": "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/README.md"}, {"fetched_at": "2026-10-28T15:45:42.223228+08:00", "kind": "documentation", "sha256": "e21acbc60fffd1cc7f866d419454db31a9b119b3e2ef29e66e132dd3392d7818", "snapshot_path": "sources/e21acbc60fffd1cc7f866d419454db31a9b119b3e2ef29e66e132dd3392d7818.txt", "url": "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/docs/design/01-telephony.md"}, {"fetched_at": "2026-10-28T15:45:43.706592+08:00", "kind": "documentation", "sha256": "6451bf23ae4b0c30d099dc3ced11e5fda979e083a09380fd3f436c5034e39389", "snapshot_path": "sources/6451bf23ae4b0c30d099dc3ced11e5fda979e083a09380fd3f436c5034e39389.txt", "url": "https://raw.githubusercontent.com/rasonyang/ai-native-callcenter/main/docs/design/05-frontend.md"}], "summary": "自托管开源呼叫中心应用：FreeSWITCH 接入实时语音来电与去电，坐席按 mod_callcenter 队列、层级与分配策略接听，平台跟踪坐席登录/就绪/话后处理状态，并提供坐席工作台、主管实时看板与 CDR/报表。", "technology_stack": ["Go", "FreeSWITCH（mod_callcenter、mod_lua、ESL）", "PostgreSQL", "React 前端", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1218061070','humanplane terminal','{"deployment": ["自托管：Rust axum 后端 + SolidJS 静态前端", "后端单二进制部署，前端可置于任意静态托管"], "features": ["实时订单簿与成交明细（SSE 推送，单市场详情页）", "市价/限价订单构建并直接签名提交至 Polymarket CLOB", "未成交订单列表与撤单", "交易者视图：持仓、成交记录与实时 PnL", "收藏与钱包偏好本地持久化，键盘导航"], "github_repository_id": 1218061070, "homepage": "https://github.com/humanplane/terminal", "id": "github:1218061070", "leaf_matches": [{"reason": "README 说明这是自托管交易终端：侧栏市场/事件列表与收藏（localStorage 持久化）承载多品种实时状态，单市场详情页经 SSE 展示实时订单簿与逐笔成交；订单表单支持市价（按订单簿计算均价与可成交量）与限价并直接提交到 Polymarket CLOB，另有未成交订单列表与撤单；交易者视图显示持仓、成交与实时 PnL。交易仍由用户钱包逐单签名，属人工决策。未声称多窗口网格工作区。", "slug": "professional-trading-terminal", "source_urls": ["https://api.github.com/repos/humanplane/terminal", "https://raw.githubusercontent.com/humanplane/terminal/main/README.md", "https://api.github.com/repos/humanplane/terminal/license"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/humanplane/terminal/license", "name": "humanplane terminal", "repository_url": "https://github.com/humanplane/terminal", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T15:42:17.950940+08:00", "kind": "repository_metadata", "sha256": "1f1112c993323e8caf3c61e772ccd4194548e71a2f5d466480c36a9f1cef09e4", "snapshot_path": "sources/1f1112c993323e8caf3c61e772ccd4194548e71a2f5d466480c36a9f1cef09e4.txt", "url": "https://api.github.com/repos/humanplane/terminal"}, {"fetched_at": "2026-10-28T15:42:47.245602+08:00", "kind": "readme", "sha256": "e4a6bfd23964be3fe235ea2fbafef075adb457b3cd746066410ff0d1b6a01555", "snapshot_path": "sources/e4a6bfd23964be3fe235ea2fbafef075adb457b3cd746066410ff0d1b6a01555.txt", "url": "https://raw.githubusercontent.com/humanplane/terminal/main/README.md"}, {"fetched_at": "2026-10-28T15:42:48.994378+08:00", "kind": "license", "sha256": "a9e18aca1ae50ffc9552ef0b0c46bcfe4f84c64c08175e0ffe969ea51706741a", "snapshot_path": "sources/a9e18aca1ae50ffc9552ef0b0c46bcfe4f84c64c08175e0ffe969ea51706741a.txt", "url": "https://api.github.com/repos/humanplane/terminal/license"}], "summary": "自托管开源 Polymarket 交易终端 Web 应用：实时订单簿与成交明细、市价/限价订单构建并直接提交到 CLOB、未成交订单查询与撤单、交易者持仓与实时 PnL 视图，支持键盘导航和收藏持久化。", "technology_stack": ["Rust", "axum", "SolidJS", "TypeScript", "viem"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:9301414','hledger','{"deployment": ["单二进制安装（unix/mac/windows）", "hledger-web 可 --serve 常驻或 --serve-api 仅提供 API，默认仅监听 127.0.0.1，需自行以代理暴露"], "features": ["以纯文本日记账记录复式交易并按账户分类（README 示例使用 assets/liabilities/equity/expenses 等账户名）", "按账户与期间生成余额、收支等报表；支持多币种与 CSV 导入导出", "账簿为可版本控制、可长期保存的文本文件，跨会话持续累积", "hledger-web 网页界面可浏览、添加与编辑交易，并以 --serve 常驻提供 Web UI 与 JSON API"], "github_repository_id": 9301414, "homepage": "https://hledger.org", "id": "github:9301414", "leaf_matches": [{"reason": "README 说明其为复式记账软件，以纯文本 journal 逐笔记录并按账户分类（示例含资产/负债/权益/收入/费用账户），生成余额与报表；账簿文件由用户长期保存、可版本控制。本轮补证的 hledger-web 官方手册正文进一步说明其为可浏览与添加交易的 Web 应用，--serve 常驻提供 Web UI 与 JSON API，读写同一 journal 并在每次编辑后写编号备份，可多用户共享——原“网页界面仅有概述、持久使用边界不明”的缺口已由正文解决。边界如实收窄为本地优先的单 journal 工具，无访问控制、默认仅监听 127.0.0.1。", "slug": "bookkeeping-application", "source_urls": ["https://api.github.com/repos/hledgerorg/hledger", "https://api.github.com/repos/hledgerorg/hledger/license", "https://raw.githubusercontent.com/hledgerorg/hledger/HEAD/README.md", "https://hledger.org/", "https://hledger.org/hledger-web.html"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/hledgerorg/hledger/license", "name": "hledger", "repository_url": "https://github.com/hledgerorg/hledger", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T20:22:24.743558+08:00", "kind": "repository_metadata", "sha256": "75dd44bb66fa8233e1491c356d361e59b7cde50a0ee5a32a6045855488614734", "snapshot_path": "sources/75dd44bb66fa8233e1491c356d361e59b7cde50a0ee5a32a6045855488614734.txt", "url": "https://api.github.com/repos/hledgerorg/hledger"}, {"fetched_at": "2026-10-24T20:22:26.509700+08:00", "kind": "license", "sha256": "1eeccaa7b9ac081339d8c35f7320ffbc77278e473dfd9501600da647709265af", "snapshot_path": "sources/1eeccaa7b9ac081339d8c35f7320ffbc77278e473dfd9501600da647709265af.txt", "url": "https://api.github.com/repos/hledgerorg/hledger/license"}, {"fetched_at": "2026-10-24T20:22:27.644535+08:00", "kind": "readme", "sha256": "9b778a752530a74f20573da16b171039cf044cdcfb28984c8f8c87b81f198dd2", "snapshot_path": "sources/9b778a752530a74f20573da16b171039cf044cdcfb28984c8f8c87b81f198dd2.txt", "url": "https://raw.githubusercontent.com/hledgerorg/hledger/HEAD/README.md"}, {"fetched_at": "2026-10-24T20:22:29.271568+08:00", "kind": "homepage", "sha256": "79100b612846c968d16b44839085d4969ff1ed9db6bb3d0f901d2db02a3a0edf", "snapshot_path": "sources/79100b612846c968d16b44839085d4969ff1ed9db6bb3d0f901d2db02a3a0edf.txt", "url": "https://hledger.org/"}, {"fetched_at": "2026-10-28T16:00:23.506094+08:00", "kind": "documentation", "sha256": "2830e4d39cfdc57f8259d539f47315d7ab8a2389e96d57056a46ea6a1c37fb9b", "snapshot_path": "sources/2830e4d39cfdc57f8259d539f47315d7ab8a2389e96d57056a46ea6a1c37fb9b.txt", "url": "https://hledger.org/hledger-web.html"}], "summary": "纯文本复式记账工具，交易按账户分类保存在可长期保存、可版本控制的 journal 文件中，并生成余额与报表；附带 hledger-web 网页界面，可常驻提供服务化访问。", "technology_stack": ["Haskell", "纯文本日记账文件"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1211443189','HRPulsar','{"deployment": ["Docker Compose 自托管（PostgreSQL + Redis + 反向代理）", "官方云托管版本", "本地开发模式（FastAPI 后端 + Next.js 前端）"], "features": ["分层胜任力库：能力组/能力/行为指标，按等级组织指标与学习材料，支持自定义等级、发布与停用", "岗位与职级矩阵：岗位页展示所需能力及要求等级，职级矩阵按能力×职级配置每格所需熟练度", "员工胜任力档案：按岗位所需能力展示最近一次已完成评估的等级，未达标显示空缺，并保留高于/低于要求的结果", "差距与通过线：低于或等于通过线的能力统一标为 gap，目录、仪表盘与评估增长区复用同一规则", "评估：自评、180°、360°，参与者角色含自我、经理、同事、下属，可配置指标与加权量表", "由差距生成个人发展计划，并可与职级/职业阶梯关联"], "github_repository_id": 1211443189, "homepage": "https://hrpulsar.com", "id": "github:1211443189", "leaf_matches": [{"reason": "官方仓库文档显示：组织维护分层能力库（能力+指标+熟练度等级），岗位/职级矩阵为每格设定所需等级，员工档案按岗位所需能力记录最近评估等级并保留偏离项，低于通过线统一标为 gap 并可从差距生成发展计划；完整 Web 应用可自托管，社区版 AGPL-3.0。", "slug": "competency-management-platform", "source_urls": ["https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/docs/features.md", "https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/README.md", "https://api.github.com/repos/HRPulsar/hrpulsar", "https://api.github.com/repos/HRPulsar/hrpulsar/license", "https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/NOTICE", "https://hrpulsar.com"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/HRPulsar/hrpulsar/license", "license_review": {"rationale": "LICENSE 全文（34,523 字符）为 GNU Affero General Public License v3.0 完整文本；README 第 74–78 行写明 Community Edition 采用 AGPLv3（含 Section 7 组合许可）、Enterprise Edition 另行商业许可；NOTICE 正文同样声明 AGPLv3 与 Section 7 additional permission，故仅以社区版范围申报。", "reviewer": "unit-066 collector", "scope": "community_core", "source_url": "https://api.github.com/repos/HRPulsar/hrpulsar/license", "spdx_id": "AGPL-3.0"}, "name": "HRPulsar", "repository_url": "https://github.com/HRPulsar/hrpulsar", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:07:35.026368+08:00", "kind": "repository_metadata", "sha256": "3c6d1e528fad35164ff5b8fee4e34c7a9bb86a5b82158a90bb44d416a76d54d3", "snapshot_path": "sources/3c6d1e528fad35164ff5b8fee4e34c7a9bb86a5b82158a90bb44d416a76d54d3.txt", "url": "https://api.github.com/repos/HRPulsar/hrpulsar"}, {"fetched_at": "2026-10-28T16:07:38.205959+08:00", "kind": "license", "sha256": "e1c5ca7f4b24cc228904a0d824bf71088f1399e199820e07367049f766fdd583", "snapshot_path": "sources/e1c5ca7f4b24cc228904a0d824bf71088f1399e199820e07367049f766fdd583.txt", "url": "https://api.github.com/repos/HRPulsar/hrpulsar/license"}, {"fetched_at": "2026-10-28T16:07:36.013786+08:00", "kind": "readme", "sha256": "0d355ac215df01983052683b75074197d35f0e2b82beeab81aba980dc6fb9ab4", "snapshot_path": "sources/0d355ac215df01983052683b75074197d35f0e2b82beeab81aba980dc6fb9ab4.txt", "url": "https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/README.md"}, {"fetched_at": "2026-10-28T16:07:34.727952+08:00", "kind": "documentation", "sha256": "9f8b0cec476cab811899337dddf0d1a8537eedf63f52bd7fb89edb61ea89015c", "snapshot_path": "sources/9f8b0cec476cab811899337dddf0d1a8537eedf63f52bd7fb89edb61ea89015c.txt", "url": "https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/docs/features.md"}, {"fetched_at": "2026-10-28T16:09:12.749060+08:00", "kind": "homepage", "sha256": "4d1abe567056cf257bfcfa1123be7d8541636755f3da0dae3949ea0198d0abc9", "snapshot_path": "sources/4d1abe567056cf257bfcfa1123be7d8541636755f3da0dae3949ea0198d0abc9.txt", "url": "https://hrpulsar.com"}, {"fetched_at": "2026-10-28T16:26:16.643769+08:00", "kind": "documentation", "sha256": "df435f945cc4baf5b72be57c9327c345183a2726d7f28fb01dbc97a3e1376d31", "snapshot_path": "sources/df435f945cc4baf5b72be57c9327c345183a2726d7f28fb01dbc97a3e1376d31.txt", "url": "https://raw.githubusercontent.com/HRPulsar/hrpulsar/main/NOTICE"}], "summary": "开源人才与胜任力管理平台（社区版 AGPL-3.0，可 Docker Compose 自托管）：维护分层的组织胜任力模型（能力、指标、熟练度等级），在岗位/职级上配置所需等级，按自评、经理及 360° 评估记录员工能力档案，并按岗位要求计算差距与生成发展计划。", "technology_stack": ["Python / FastAPI", "Next.js / React / TypeScript", "PostgreSQL", "Redis"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:jaggaer-value-tracker','JAGGAER Value Tracker','{"homepage": "https://www.jaggaer.com/", "id": "commercial:jaggaer-value-tracker", "leaf_matches": [{"reason": "官方页正文描述集中式举措管线（从构想到关闭）、按业务单元/品类/供应商分配价值、定义基准与预期收益、经财务与利益相关方审批的预测，以及逐期记录实际值并与预测对账、按状态汇总管线；并说明举措可关联寻源事件与品类策略，形成从寻源行动到已验证节约的链路，符合计划管线+节约台账+关联三项核心。", "slug": "strategic-sourcing-platform", "source_urls": ["https://www.jaggaer.com/solutions/value-tracker"]}], "name": "JAGGAER Value Tracker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:15:27.088295+08:00", "kind": "documentation", "sha256": "5f2569a45cca6cb369433b9f094a9794863b9d8a6b46ecf5954d1452ce1d9408", "snapshot_path": "sources/5f2569a45cca6cb369433b9f094a9794863b9d8a6b46ecf5954d1452ce1d9408.txt", "url": "https://www.jaggaer.com/solutions/value-tracker"}], "summary": "采购价值/节约管理 SaaS：以举措管线贯穿构想、提案、计划、实现到关闭五个阶段，按基准预测并与实际节约对账、经财务审批后计入。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:simfoni-strategic-spend-hub','Simfoni Strategic Spend Hub','{"homepage": "https://simfoni.com/", "id": "commercial:simfoni-strategic-spend-hub", "leaf_matches": [{"reason": "官方页正文将平台拆为支出分析、寻源管线、电子寻源执行与节约跟踪四部分，说明管线用于规划、排序并跟踪寻源举措，Pipeline & PMO Management 跟踪每个举措的完整生命周期，节约跟踪自动计算并报告预测与实际节约、按品类/业务单元/举措负责人归属，可直接对接 CFO/CPO 报告，覆盖计划管线、节约台账与其执行关联。", "slug": "strategic-sourcing-platform", "source_urls": ["https://simfoni.com/strategic-spend-hub/"]}], "name": "Simfoni Strategic Spend Hub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:22:38.396809+08:00", "kind": "documentation", "sha256": "5e2392f916cc574a69fd1160201a474b67f5f189e0ce73717757b691c6e00d16", "snapshot_path": "sources/5e2392f916cc574a69fd1160201a474b67f5f189e0ce73717757b691c6e00d16.txt", "url": "https://simfoni.com/strategic-spend-hub/"}], "summary": "采购支出与寻源 SaaS：以寻源管线管理举措全生命周期，在同一平台执行电子寻源并跟踪预测与实际节约。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:vendorful','Vendorful','{"homepage": "https://vendorful.com/", "id": "commercial:vendorful", "leaf_matches": [{"reason": "官方管线页正文说明团队可在管线中登记并管理寻源项目、跟踪状态（规划中/进行中/已完成/已取消）与节约，向前规划机会、向后报告已实现节约，并可为团队设定节约目标；官方 e-Sourcing 页正文说明同一产品内规划并跟踪寻源活动与节约、运行 RFP/RFI/RFQ 及反向拍卖。计划管线、节约台账与寻源执行关联均有正文证据。", "slug": "strategic-sourcing-platform", "source_urls": ["https://vendorful.com/e-sourcing/sourcing-pipeline/", "https://vendorful.com/e-sourcing/"]}], "name": "Vendorful", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:14:43.006741+08:00", "kind": "documentation", "sha256": "68f44de07ae661126d12deb201881655df02abec62efa6ccd3c5446e62a1a7cb", "snapshot_path": "sources/68f44de07ae661126d12deb201881655df02abec62efa6ccd3c5446e62a1a7cb.txt", "url": "https://vendorful.com/e-sourcing/sourcing-pipeline/"}, {"fetched_at": "2026-10-28T16:16:38.176841+08:00", "kind": "documentation", "sha256": "6ef6da256f1ae07e3c82c704f7d6376c33cc68b6d5b82ea9da3aa43fd5c82b06", "snapshot_path": "sources/6ef6da256f1ae07e3c82c704f7d6376c33cc68b6d5b82ea9da3aa43fd5c82b06.txt", "url": "https://vendorful.com/e-sourcing/"}], "summary": "采购寻源与供应商管理 SaaS：以寻源管线跟踪项目状态和节约，并在同一产品内执行 RFP/RFI/RFQ 与反向拍卖。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:workday-strategic-sourcing','Workday Strategic Sourcing','{"homepage": "https://workday.com/", "id": "commercial:workday-strategic-sourcing", "leaf_matches": [{"reason": "官方产品页把寻源请求接入表单后形成寻源管线，并给出预计与实际节约的跟踪与报告；官方管理员指南进一步说明寻源项目在 Pipeline 中分阶段推进，项目财务明细登记预计/已确认节约、节约类型与确认日期，并按财年节约目标汇总计算差距与达成。管线、节约台账及二者关联均有正文证据。", "slug": "strategic-sourcing-platform", "source_urls": ["https://www.workday.com/en-us/products/spend-management/strategic-sourcing.html", "https://doc.workday.com/admin-guide/en-us/spend-management/strategic-sourcing/pipeline/npv1595945851205.html", "https://doc.workday.com/admin-guide/en-us/spend-management/strategic-sourcing/pipeline/tzb1595951755853.html"]}], "name": "Workday Strategic Sourcing", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:14:45.944454+08:00", "kind": "documentation", "sha256": "a5c0118c20e269a22c81874c3f02e8c45cb0faea3d5cda08d6ad651da5a5e951", "snapshot_path": "sources/a5c0118c20e269a22c81874c3f02e8c45cb0faea3d5cda08d6ad651da5a5e951.txt", "url": "https://www.workday.com/en-us/products/spend-management/strategic-sourcing.html"}, {"fetched_at": "2026-10-28T16:25:38.797750+08:00", "kind": "documentation", "sha256": "7c9e2116350733e51acf8f1b030144b5c1941c1d1eab9c3b5b82084651c7f971", "snapshot_path": "sources/7c9e2116350733e51acf8f1b030144b5c1941c1d1eab9c3b5b82084651c7f971.txt", "url": "https://doc.workday.com/admin-guide/en-us/spend-management/strategic-sourcing/pipeline/npv1595945851205.html"}, {"fetched_at": "2026-10-28T16:25:42.100747+08:00", "kind": "documentation", "sha256": "3602c49e92b9e2a1bc11488fc7fac773042a86bd19ac789ab86a1a80526def81", "snapshot_path": "sources/3602c49e92b9e2a1bc11488fc7fac773042a86bd19ac789ab86a1a80526def81.txt", "url": "https://doc.workday.com/admin-guide/en-us/spend-management/strategic-sourcing/pipeline/tzb1595951755853.html"}], "summary": "采购寻源 SaaS：以寻源项目组成管线并分阶段审批，项目内登记预计与已确认节约、按财年目标汇总。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:zycus','Zycus','{"homepage": "https://www.zycus.com/", "id": "commercial:zycus", "leaf_matches": [{"reason": "官方财务协作页正文说明其集中式节约跟踪平台做预测与跟踪、将支出机会转化为经审批验证的节约项目、可配置节约规划与审批管线，并按寻源策略/节约类型多维度分析、与财务指标映射；官方战略寻源套件页正文说明套件内含 eSourcing（RFx、反向拍卖）、类别管理与寻源分析。相较此前仅凭 eSourcing 页的旧判断，本次补证同时覆盖了节约台账与计划/审批管线，故恢复该关系。", "slug": "strategic-sourcing-platform", "source_urls": ["https://www.zycus.com/solution/procurement-finance-collaboration", "https://www.zycus.com/solution/strategic-sourcing-suite"]}], "name": "Zycus", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T16:25:03.927265+08:00", "kind": "documentation", "sha256": "0a90bbcaa3043abb34c57a1dfa68ad79f2ab036d91250a9fecf29d7b5d3a839c", "snapshot_path": "sources/0a90bbcaa3043abb34c57a1dfa68ad79f2ab036d91250a9fecf29d7b5d3a839c.txt", "url": "https://www.zycus.com/solution/procurement-finance-collaboration"}, {"fetched_at": "2026-10-28T16:25:41.379177+08:00", "kind": "documentation", "sha256": "8c1e54d7ee558755873391e5359208815dff17f267cc8577067bd617cf06f3f1", "snapshot_path": "sources/8c1e54d7ee558755873391e5359208815dff17f267cc8577067bd617cf06f3f1.txt", "url": "https://www.zycus.com/solution/strategic-sourcing-suite"}], "summary": "采购 Source-to-Pay 套件：以寻源项目与节约项目记录采购节约，经可配置审批管线验证后与财务指标对齐。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1306204230','OpenSourcingOS','{"deployment": ["自托管：克隆仓库后以 npm 安装依赖，Supabase CLI 启动本地 PostgreSQL 并执行迁移，npm run dev 启动 Web 应用", "托管演示：opensourcingos.com 提供 Google 登录的隔离示例工作区（public beta，自述非生产系统记录）"], "features": ["寻源项目组合：项目负责人、品类、业务单元、成本中心、截止日期与更新记录", "商业锚点：开标提案、基线、供应商报价与最终授标逐项留存，形成可追溯的节约来源", "节约排程：按月、按年或一次性记账，跨年期间归属正确财年", "状态分层：预计节约、已执行/合同节约与可选已实现节约分开记录", "节约方法论：成本降低 = 基线 − 最终报价，成本规避 = 开标提案 − 基线，总节约不可通过更换基线改写", "仪表盘与报表：项目、供应商、节约与财年报表，含逾期与临期项目队列", "供应商记录：联系人、寻源历史、授标、风险登记与绩效评审"], "github_repository_id": 1306204230, "homepage": "https://opensourcingos.com/", "id": "github:1306204230", "leaf_matches": [{"reason": "官方 README 正文列出：以组合方式管理寻源项目（负责人/品类/业务单元/截止日期/更新）、记录范围行/基线/供应商报价/最终授标、把节约按月度或年度排程并归属财年、把预计节约与合同及已实现结果分开、并输出项目/供应商/节约/财年报表；落地页正文亦称其为把寻源项目、基线、报价与实现连成组合的采购节约跟踪应用。计划管线、节约台账及二者关联三项在正文均有落地，且为可自托管的完整 Web 应用。README 与落地页同时自述为 MVP/public beta，落地页截图为产品方向示意，故按实际状态记录，未部署实测。", "slug": "strategic-sourcing-platform", "source_urls": ["https://raw.githubusercontent.com/gruvyo/opensourcingos/main/README.md", "https://opensourcingos.com/"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/gruvyo/opensourcingos/license", "name": "OpenSourcingOS", "repository_url": "https://github.com/gruvyo/opensourcingos", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T20:55:52.673783+08:00", "kind": "repository_metadata", "sha256": "d06de54e75509143967db0f311c9876a489801051a15b558362dfcd35f61ee33", "snapshot_path": "sources/d06de54e75509143967db0f311c9876a489801051a15b558362dfcd35f61ee33.txt", "url": "https://api.github.com/repos/gruvyo/opensourcingos"}, {"fetched_at": "2026-10-28T20:56:57.344797+08:00", "kind": "license", "sha256": "5126059c9be9809db663f0e82711e7d25d53c93f25c54f65b4fa7e9533e614d6", "snapshot_path": "sources/5126059c9be9809db663f0e82711e7d25d53c93f25c54f65b4fa7e9533e614d6.txt", "url": "https://api.github.com/repos/gruvyo/opensourcingos/license"}, {"fetched_at": "2026-10-28T20:56:58.444881+08:00", "kind": "readme", "sha256": "846806df954322f7dd28894e30251184a6770cbff60a9d16fb494a3a225afe30", "snapshot_path": "sources/846806df954322f7dd28894e30251184a6770cbff60a9d16fb494a3a225afe30.txt", "url": "https://raw.githubusercontent.com/gruvyo/opensourcingos/main/README.md"}, {"fetched_at": "2026-10-28T20:56:58.639881+08:00", "kind": "homepage", "sha256": "3dd0697d4d46fe02ec071c72d761393a96e00dde10c75346b610719a0b69a6b7", "snapshot_path": "sources/3dd0697d4d46fe02ec071c72d761393a96e00dde10c75346b610719a0b69a6b7.txt", "url": "https://opensourcingos.com/"}], "summary": "开源的采购价值跟踪 Web 应用（Apache-2.0，自述 MVP/public beta）：把寻源项目、开销基线、供应商报价与最终授标放在同一组合中，节约按月度/年度/一次性排程，区分预计、已执行、已实现并输出财年与组合报表。", "technology_stack": ["Next.js 16", "React 19", "TypeScript", "Supabase (PostgreSQL + Row Level Security)", "Tailwind CSS", "Recharts", "Vercel"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:athennian','Athennian','{"homepage": "https://www.athennian.com", "id": "commercial:athennian", "leaf_matches": [{"reason": "官网正文逐项说明 Entity & People Records（记录实体详情、任命、地址、KYC、注册与合规信息）、Appointments/D&O（记录并关联董事、高管、授权代表与签字权限）、Equity & Debt Structures（股权结构与交易）、Structure Charts（由受治理数据实时生成的所有权与层级图）、Document Management（存储模板、控制敏感文档访问）以及 Controls & Governance 中的 granular permissions 与 audit trails，覆盖主体记录、结构层、公司记录与带权限的变更留痕。", "slug": "legal-entity-management", "source_urls": ["https://www.athennian.com"]}], "name": "Athennian", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T20:49:13.179857+08:00", "kind": "homepage", "sha256": "d529452a09143e9b1b267fc60b1675912278e02ab7c177471786a2f38e70e875", "snapshot_path": "sources/d529452a09143e9b1b267fc60b1675912278e02ab7c177471786a2f38e70e875.txt", "url": "https://www.athennian.com"}], "summary": "面向法律、税务与财务团队的实体管理（Governance Ops）平台，维护实体与人员记录、任免与签字权限、股权与债务结构及结构图，并提供文档管理与审计轨迹。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:minutebox','MinuteBox','{"homepage": "https://www.minutebox.com", "id": "commercial:minutebox", "leaf_matches": [{"reason": "官网正文自述 MinuteBox 是追踪法律实体与合规的 entity management platform，并列出 Entity & Subsidiary Management（在一个平台管理法律实体与合规义务）、Corporate Minute Book、Registry Services（以自动化实时更新创建与维护法定登记册）与 Compliance Calendar Tracking，覆盖实体记录、公司记录簿与持续合规维护；结构图与股权比例明细未在该页正文出现，故不据此延伸。", "slug": "legal-entity-management", "source_urls": ["https://www.minutebox.com"]}], "name": "MinuteBox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T20:49:10.035495+08:00", "kind": "homepage", "sha256": "f55af0794ea180d14cc658209aa904e1993057180311bb8e6ad82b17bf6b3841", "snapshot_path": "sources/f55af0794ea180d14cc658209aa904e1993057180311bb8e6ad82b17bf6b3841.txt", "url": "https://www.minutebox.com"}], "summary": "面向律所与公司秘书团队的实体与子公司管理平台，集中维护法人实体、法定义务与合规日历，并提供公司会议记录簿、证券登记册与安全数据室。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1046293319','MinuteBooks','{"deployment": ["Django 本地运行（SQLite 开发 / PostgreSQL 生产）", "Docker Compose（PostgreSQL + Redis + MinIO）", "支持 S3/MinIO 对象存储作为文件后端"], "features": ["公司主体记录：法定名称、商号（d/b/a）、管辖地（CBCA/LSAQ）、注册编号、商业编号、注册办事处与记录办事处", "任职记录：董事与高管绑定自然人或法人主体，带 started_on/ended_on 生效与终止日期", "股权登记：股份类别、证书、发行/转让/赎回事件（occurred_on）与计算出的股权结构", "公司治理文件库：章程、会议记录、股东/董事会决议、证书等按公司归档，含 SHA-256 与内容类型", "按组织成员身份与角色授权，支持带过期时间的只读账簿共享链接"], "github_repository_id": 1046293319, "homepage": "https://github.com/vsaintloup/minutebooks", "id": "github:1046293319", "leaf_matches": [{"reason": "公开源码显示其以公司为主体记录：corps/models.py 的 Corporation 持有法定名称、d/b/a 商号、管辖地（CBCA/LSAQ）、注册编号、商业编号、注册办事处与记录办事处，符合“已识别且带管辖地的主体记录”。结构层以数据持有：Director/Officer 通过 Party（自然人或法人）绑定公司并带 started_on/ended_on 生效日期，股份发行/转让/赎回以 to_holder/from_holder 记录并可聚合出股权结构，股权持有人本身可为法人主体。公司记录文件库落为实体：documents/models.py 的 Document 按 corp 外键归档章程/会议记录/决议/证书等类别，保存实际文件与 SHA-256；documents/views.py 按组织成员身份与对象级权限过滤，并提供带到期时间的只读账簿共享链接（ShareLink），满足访问控制要求。已记录变更成立：任命与股权事件均以显式日期字段保留为独立记录而非覆盖快照。边界说明：该仓库为 README 自述的 MVP，实体状态（良好存续）与实体间持股比例字段未在已读源码中出现；README 提及 audit/历史，但已读模型未注册 auditlog/simple_history，故不据此声称完整审计轨迹。", "slug": "legal-entity-management", "source_urls": ["https://api.github.com/repos/vsaintloup/minutebooks", "https://api.github.com/repos/vsaintloup/minutebooks/license", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/README.md", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/corps/models.py", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/documents/models.py", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/documents/views.py", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/registers/models.py", "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/orgs/models.py"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/vsaintloup/minutebooks/license", "name": "MinuteBooks", "repository_url": "https://github.com/vsaintloup/minutebooks", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T20:48:31.256037+08:00", "kind": "repository_metadata", "sha256": "505f0dee74153ffa479aef801be54b5c8b688249092f4577ac3d88c1737cfa9c", "snapshot_path": "sources/505f0dee74153ffa479aef801be54b5c8b688249092f4577ac3d88c1737cfa9c.txt", "url": "https://api.github.com/repos/vsaintloup/minutebooks"}, {"fetched_at": "2026-10-28T20:48:37.175231+08:00", "kind": "license", "sha256": "35be30502c3717cabc908fef450c9c89bc48ac685f07447d23e91d30de3f1f37", "snapshot_path": "sources/35be30502c3717cabc908fef450c9c89bc48ac685f07447d23e91d30de3f1f37.txt", "url": "https://api.github.com/repos/vsaintloup/minutebooks/license"}, {"fetched_at": "2026-10-28T20:48:38.415851+08:00", "kind": "readme", "sha256": "0702f42e07ead3ae645f2c8ebb6559e2ef2e1ed53e2d7c4b09dc25600a57733f", "snapshot_path": "sources/0702f42e07ead3ae645f2c8ebb6559e2ef2e1ed53e2d7c4b09dc25600a57733f.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/README.md"}, {"fetched_at": "2026-10-28T20:48:46.355034+08:00", "kind": "documentation", "sha256": "eb739608762825a5c41b2fed3bb2998c22dc769b6129ff0bbb35fa89665639a8", "snapshot_path": "sources/eb739608762825a5c41b2fed3bb2998c22dc769b6129ff0bbb35fa89665639a8.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/corps/models.py"}, {"fetched_at": "2026-10-28T20:48:42.907850+08:00", "kind": "documentation", "sha256": "6bf47f78ad09ad20c83bf980ae8d1555dbae663b2a41be7e8b6450a80c93855d", "snapshot_path": "sources/6bf47f78ad09ad20c83bf980ae8d1555dbae663b2a41be7e8b6450a80c93855d.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/documents/models.py"}, {"fetched_at": "2026-10-28T20:48:44.253822+08:00", "kind": "documentation", "sha256": "8f0a3040ac3460ea68a79bb6efda6d00e5fd894af6c79de6f958a45488d553ee", "snapshot_path": "sources/8f0a3040ac3460ea68a79bb6efda6d00e5fd894af6c79de6f958a45488d553ee.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/documents/views.py"}, {"fetched_at": "2026-10-28T20:48:53.394539+08:00", "kind": "documentation", "sha256": "0833c205d7678c9cab3375c1ece0c412e4cb49c2da412e8396c81beb54b76834", "snapshot_path": "sources/0833c205d7678c9cab3375c1ece0c412e4cb49c2da412e8396c81beb54b76834.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/registers/models.py"}, {"fetched_at": "2026-10-28T20:48:55.503719+08:00", "kind": "documentation", "sha256": "7c3f860b3a2d2bd74bbd48ea479f444be5ed8508da5042cdf267a21ad2b2c388", "snapshot_path": "sources/7c3f860b3a2d2bd74bbd48ea479f444be5ed8508da5042cdf267a21ad2b2c388.txt", "url": "https://raw.githubusercontent.com/vsaintloup/minutebooks/main/orgs/models.py"}], "summary": "面向加拿大联邦（LCSA）与魁北克（LSAQ）公司的开源数字公司账簿平台：按组织与公司维护主体登记信息、董事/高管任命、股权登记与公司治理文件库，并提供带到期时间的只读账簿共享链接。", "technology_stack": ["Django 5 + Django REST Framework", "PostgreSQL / SQLite", "django-allauth + django-guardian", "MinIO / S3 + django-storages", "docxtpl 文书模板生成"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:litera-transact','Litera Transact','{"homepage": "https://www.litera.com/products/litera-transact", "id": "commercial:litera-transact", "leaf_matches": [{"reason": "官方产品页正文将 Litera Transact 定义为“整个交易运行其上的记录”，逐项描述动态检查清单集中任务、自动化签署管理与实时签署人跟踪、生成交割集与交割簿；5.0 官方公告进一步说明其覆盖从 M&A 到风险投资、房地产的交易检查清单、签署、审批与交割集，符合交易记录+检查清单+文档到执行流水线的定义核心。", "slug": "transaction-legal-management", "source_urls": ["https://www.litera.com/products/litera-transact", "https://www.litera.com/blog/litera-transact-5-new-features"]}], "name": "Litera Transact", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:23:03.139158+08:00", "kind": "homepage", "sha256": "b7b7c8e431da202df211b1d37051d5950de4b6f94ddeaa54c876cf1877ec5f03", "snapshot_path": "sources/b7b7c8e431da202df211b1d37051d5950de4b6f94ddeaa54c876cf1877ec5f03.txt", "url": "https://www.litera.com/products/litera-transact"}, {"fetched_at": "2026-10-28T20:52:33.838400+08:00", "kind": "documentation", "sha256": "42d4c3748af5c5f61a4d4ff86314d2dcdaae2f53af3f8dcbd38b13a9e7988f8b", "snapshot_path": "sources/42d4c3748af5c5f61a4d4ff86314d2dcdaae2f53af3f8dcbd38b13a9e7988f8b.txt", "url": "https://www.litera.com/products/litera-transact"}, {"fetched_at": "2026-10-28T20:55:32.182083+08:00", "kind": "documentation", "sha256": "4180b12103dc48c61c05c97909145266972044b3f59906c078d7d35abeb8d897", "snapshot_path": "sources/4180b12103dc48c61c05c97909145266972044b3f59906c078d7d35abeb8d897.txt", "url": "https://www.litera.com/blog/litera-transact-5-new-features"}], "summary": "面向律所与法律团队的交易管理平台：以单一交易的检查清单跟踪任务、文件、审批与签署状态，并生成交割集与交割簿。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:16085812','SimpleRisk','{"deployment": ["self-hosted", "Docker", "虚拟机"], "features": ["框架与控制登记册", "控制测试与审计", "证据留存与审计轨迹", "合规状态汇总与报告", "角色与权限"], "github_repository_id": 16085812, "homepage": "https://simplerisk.com/", "id": "github:16085812", "leaf_matches": [{"reason": "官方开源版页面与合规功能页说明 SimpleRisk Core 将框架/控制作为要求登记，针对控制定义可复用测试并在框架、控制或单测级别发起审计，留存证据与审计轨迹、按角色向外部审计员开放，并汇总各框架合规状态；仓库为发布源代码镜像，许可文件为完整 MPL-2.0。", "slug": "compliance-management-platform", "source_urls": ["https://www.simplerisk.com/deployment/open-source", "https://www.simplerisk.com/grc/compliance", "https://api.github.com/repos/simplerisk/code", "https://raw.githubusercontent.com/simplerisk/code/master/simplerisk/LICENSE"]}, {"reason": "官方 Core 页面将治理（框架与控制）、风险管理（风险登记册与缓解）、合规（跨框架与控制的无限测试）放在同一平台；首页说明 250+ 框架共用一套控制、一次评估服务多个框架，并有测试/审计、问题与政策例外、看板与董事会报告，对应 GRC 的共享记录核心、评估-问题闭环与综合报告三项。开源范围明确为 SimpleRisk Core。", "slug": "governance-risk-compliance-platform", "source_urls": ["https://www.simplerisk.com/deployment/open-source", "https://www.simplerisk.com/", "https://api.github.com/repos/simplerisk/code/contents/simplerisk"]}, {"reason": "SimpleRisk Core 提供组织级风险登记册并对风险指定负责人，以统一的 Likelihood×Impact 等评分方法评估，记录 Mitigate/Accept/Transfer/Avoid 缓解响应与独立验收，再通过仪表盘和报表汇总整个登记册；四项定义性核心均有官方正文与知识库页面佐证。", "slug": "enterprise-risk-management", "source_urls": ["https://www.simplerisk.com/deployment/open-source", "https://www.simplerisk.com/grc/risk-management", "https://support.simplerisk.com/kb/01-03-risk-scoring-methodologies", "https://support.simplerisk.com/kb/01-04-reviewing-and-approving-risks", "https://support.simplerisk.com/kb/01-05-mitigating-a-risk", "https://support.simplerisk.com/kb/01-07-the-risk-dashboard"]}], "license": "MPL-2.0", "license_evidence_url": "https://raw.githubusercontent.com/simplerisk/code/master/simplerisk/LICENSE", "license_review": {"rationale": "Raw license file in the repository contains the complete Mozilla Public License 2.0 text and covers the released SimpleRisk Core source; paid Extras are outside the free open-source edition.", "reviewer": "opencode-go/beam-free collection", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/simplerisk/code/master/simplerisk/LICENSE", "spdx_id": "MPL-2.0"}, "name": "SimpleRisk", "repository_url": "https://github.com/simplerisk/code", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:45.439098+08:00", "kind": "homepage", "sha256": "dcced6aba93a468a72b153470b43af101cb94cfc2f74b2c72f55020d3daf95b8", "snapshot_path": "sources/dcced6aba93a468a72b153470b43af101cb94cfc2f74b2c72f55020d3daf95b8.txt", "url": "https://www.simplerisk.com/"}, {"fetched_at": "2026-10-24T22:21:23.510887+08:00", "kind": "repository_metadata", "sha256": "0ee6bed1458925d53c0e25d240b92d33f104d3a6d7764fbe2b20be96d1bc374c", "snapshot_path": "sources/0ee6bed1458925d53c0e25d240b92d33f104d3a6d7764fbe2b20be96d1bc374c.txt", "url": "https://api.github.com/repos/simplerisk/code"}, {"fetched_at": "2026-10-24T22:22:50.143643+08:00", "kind": "license", "sha256": "bef1747eda88b9ed46e94830b0d978c3499dad5dfe38d364971760881901dadd", "snapshot_path": "sources/bef1747eda88b9ed46e94830b0d978c3499dad5dfe38d364971760881901dadd.txt", "url": "https://raw.githubusercontent.com/simplerisk/code/master/simplerisk/LICENSE"}, {"fetched_at": "2026-10-28T21:00:53.830902+08:00", "kind": "documentation", "sha256": "769f3f8b0969dd40a72c81a64bfed927dce7f0847026d609ddf449cde3cafd72", "snapshot_path": "sources/769f3f8b0969dd40a72c81a64bfed927dce7f0847026d609ddf449cde3cafd72.txt", "url": "https://www.simplerisk.com/deployment/open-source"}, {"fetched_at": "2026-10-28T21:01:08.299498+08:00", "kind": "documentation", "sha256": "9f5cf9a2cbdda9ad6a4986e86693575eb57c3bcd72ab8e024e93117e3cc86520", "snapshot_path": "sources/9f5cf9a2cbdda9ad6a4986e86693575eb57c3bcd72ab8e024e93117e3cc86520.txt", "url": "https://www.simplerisk.com/grc/compliance"}, {"fetched_at": "2026-10-28T21:00:53.098230+08:00", "kind": "readme", "sha256": "652d8fe0c45688d2a0506857b6339e95bf8167a61bd2104867e09e68ab8ebae2", "snapshot_path": "sources/652d8fe0c45688d2a0506857b6339e95bf8167a61bd2104867e09e68ab8ebae2.txt", "url": "https://raw.githubusercontent.com/simplerisk/code/master/README.md"}, {"fetched_at": "2026-10-28T21:34:21.712726+08:00", "kind": "readme", "sha256": "4e313bc412f0c1f34d7d831d084529be22d2aec01e9fe72404f0bac2b31a18a6", "snapshot_path": "sources/4e313bc412f0c1f34d7d831d084529be22d2aec01e9fe72404f0bac2b31a18a6.txt", "url": "https://github.com/simplerisk/code"}, {"fetched_at": "2026-10-28T21:35:36.898453+08:00", "kind": "readme", "sha256": "79beb27c3e4f74783f158e8faef8b118ccdb99b6c80ec2bcb432d89bd8f4659a", "snapshot_path": "sources/79beb27c3e4f74783f158e8faef8b118ccdb99b6c80ec2bcb432d89bd8f4659a.txt", "url": "https://raw.githubusercontent.com/simplerisk/code/master/simplerisk/README.md"}, {"fetched_at": "2026-10-28T21:35:20.815521+08:00", "kind": "repository_metadata", "sha256": "425e64d192873c74add6bb18cb1c93afb02be4b397c9b4de331682525401c721", "snapshot_path": "sources/425e64d192873c74add6bb18cb1c93afb02be4b397c9b4de331682525401c721.txt", "url": "https://api.github.com/repos/simplerisk/code/contents/simplerisk"}, {"fetched_at": "2026-10-28T21:34:52.987836+08:00", "kind": "homepage", "sha256": "ec014ea2b6e927f5ab2a7f4d3868d88a72eab7eff9331dd3570ddd29560a1611", "snapshot_path": "sources/ec014ea2b6e927f5ab2a7f4d3868d88a72eab7eff9331dd3570ddd29560a1611.txt", "url": "https://www.simplerisk.com/download"}, {"fetched_at": "2026-10-28T21:57:53.473208+08:00", "kind": "documentation", "sha256": "073aeba98e32a263eaa050d27cd4c15e4caba677b6726151bfa0db1beb9d8ed8", "snapshot_path": "sources/073aeba98e32a263eaa050d27cd4c15e4caba677b6726151bfa0db1beb9d8ed8.txt", "url": "https://www.simplerisk.com/grc/risk-management"}, {"fetched_at": "2026-10-28T22:00:29.906687+08:00", "kind": "documentation", "sha256": "cc88f67dc813d21c4bec00c639ae94f5606cc72c74b9ae59ae11ccc989ef0bfb", "snapshot_path": "sources/cc88f67dc813d21c4bec00c639ae94f5606cc72c74b9ae59ae11ccc989ef0bfb.txt", "url": "https://support.simplerisk.com/kb/01-03-risk-scoring-methodologies"}, {"fetched_at": "2026-10-28T22:00:30.471597+08:00", "kind": "documentation", "sha256": "c2964fed75137492d2b3199a8cde8bfd15592ec3998e55944fa0354022b503d2", "snapshot_path": "sources/c2964fed75137492d2b3199a8cde8bfd15592ec3998e55944fa0354022b503d2.txt", "url": "https://support.simplerisk.com/kb/01-04-reviewing-and-approving-risks"}, {"fetched_at": "2026-10-28T22:00:54.053744+08:00", "kind": "documentation", "sha256": "4786c68ada3a920cd47b34ae6d95efbe900ef65aa467ac0a579ba79bc8b3bc23", "snapshot_path": "sources/4786c68ada3a920cd47b34ae6d95efbe900ef65aa467ac0a579ba79bc8b3bc23.txt", "url": "https://support.simplerisk.com/kb/01-05-mitigating-a-risk"}, {"fetched_at": "2026-10-28T22:00:53.516589+08:00", "kind": "documentation", "sha256": "ab8237fc582d84af6c61a4bb5b4983d387d2840970ac4a0635d65424b5f1ccf3", "snapshot_path": "sources/ab8237fc582d84af6c61a4bb5b4983d387d2840970ac4a0635d65424b5f1ccf3.txt", "url": "https://support.simplerisk.com/kb/01-07-the-risk-dashboard"}, {"fetched_at": "2026-10-28T22:02:09.335831+08:00", "kind": "documentation", "sha256": "5ec641301b501f66d643604922ea759a8c378d5d1f75abbe1876eadec299b10f", "snapshot_path": "sources/5ec641301b501f66d643604922ea759a8c378d5d1f75abbe1876eadec299b10f.txt", "url": "https://www.simplerisk.com/extras"}, {"fetched_at": "2026-10-28T22:02:07.969306+08:00", "kind": "readme", "sha256": "4596428f9ba1b7cb4c7bab2cca6289ec917ac46201d8a77646c8881971ffa03a", "snapshot_path": "sources/4596428f9ba1b7cb4c7bab2cca6289ec917ac46201d8a77646c8881971ffa03a.txt", "url": "https://api.github.com/repos/simplerisk/code/contents/README.md?ref=master"}, {"fetched_at": "2026-10-28T22:02:08.149207+08:00", "kind": "readme", "sha256": "cbc84c4b6ccbd65763789edc034ee1d8d36521126dc956a14217c46c8ff24f35", "snapshot_path": "sources/cbc84c4b6ccbd65763789edc034ee1d8d36521126dc956a14217c46c8ff24f35.txt", "url": "https://api.github.com/repos/simplerisk/code/contents/simplerisk/README.md?ref=master"}], "summary": "开源核心版 SimpleRisk Core：自托管 GRC 平台，将监管框架与控制项映射为组织合规要求，针对控制项定义测试与审计、留存证据与审计轨迹并汇总合规状态；付费 Extras 不在开源版内。", "technology_stack": ["PHP", "MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:847006986','Openlane','{"deployment": ["Docker 自托管开发/运行栈", "GHCR 容器镜像自托管"], "features": ["policies、controls、evidence、programs 四类对象均有 editors、approvals、comments 与 full history", "政策与程序作为独立文档类型，支持模板/AI 起草、导入与 Drive/OneDrive 同步", "自动版本化、任意两版本对比、审批后发布，历史修订保留", "向人员发送政策签署请求，签署绑定所读修订版本并记录时间、邮箱、IP 与浏览器", "政策映射到控件与 SOC 2、ISO 27001、NIST 800-53 等框架，审计员只读访问"], "github_repository_id": 847006986, "homepage": "https://theopenlane.io/", "id": "github:847006986", "leaf_matches": [{"reason": "Openlane 平台文档把 policies 与 procedures 定义为独立文档类型，并给出完整生命周期：起草→审批→发布到员工可见处→员工阅读并确认→定期复审（3b278641…）；政策每次修改自动版本化、可对比任意两版本、审批后才上线（1d648ccd…）；政策签署请求以 PDF 发送给人员，签署绑定导出时的修订版本，发布新版本后既有签署仍对应原修订，需另发请求收集新版本确认（9634651d…）。README 说明 policies/controls/evidence/programs 每类对象均有 editors、approvals、comments 与 full history，并与 controls、evidence、框架组成合规记录（fbe17e3f…、6da3dea9…）；产品页提供控件/证据关联、框架导入与审计员只读访问（a33c177a…）。core 与 openlane-ui 的许可证正文均为 Apache-2.0（174c480c…、1a81a3ff…），SaaS/云服务与商标不在该许可内。三环齐备，匹配本叶核心。", "slug": "compliance-policy-management", "source_urls": ["https://api.github.com/repos/theopenlane/core/readme", "https://api.github.com/repos/theopenlane/core/license", "https://api.github.com/repos/theopenlane/openlane-ui/license", "https://docs.theopenlane.io/docs/platform/compliance-management/overview", "https://docs.theopenlane.io/docs/platform/compliance-management/policy-and-procedure-management/policies", "https://docs.theopenlane.io/docs/platform/compliance-management/policy-and-procedure-management/policy-sign-off", "https://www.theopenlane.io/product/compliance/policies-and-procedures", "https://www.theopenlane.io/product/compliance"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/theopenlane/core/license", "license_review": {"rationale": "core 仓库 LICENSE 快照 174c480c… 为 GitHub license API 返回的 Apache-2.0 完整正文（含 Definitions 与 Grant of Patent License 等条款）；控制台 openlane-ui 的 LICENSE 快照 1a81a3ff… 同为 Apache-2.0 完整正文。README Licensing 段声明 SaaS/云服务按商业条款、logo 与商标不在 Apache-2.0 内，故仅对开源核心范围作许可声明。", "reviewer": "opencode-collector-u074-correction-round", "scope": "community_core", "source_url": "https://api.github.com/repos/theopenlane/core/license", "spdx_id": "Apache-2.0"}, "name": "Openlane", "repository_url": "https://github.com/theopenlane/core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:02:27.258064+08:00", "kind": "repository_metadata", "sha256": "4ae947a73574aaca0d3a9cb278e6e2cd2d978bf30e107929900e7bf37d44e7ed", "snapshot_path": "sources/4ae947a73574aaca0d3a9cb278e6e2cd2d978bf30e107929900e7bf37d44e7ed.txt", "url": "https://api.github.com/repos/theopenlane/core"}, {"fetched_at": "2026-10-28T21:02:41.250401+08:00", "kind": "readme", "sha256": "fbe17e3f3efe03aa20830cabf8afa3b002559b65093dffdcf9725ac6e8e75ec3", "snapshot_path": "sources/fbe17e3f3efe03aa20830cabf8afa3b002559b65093dffdcf9725ac6e8e75ec3.txt", "url": "https://api.github.com/repos/theopenlane/core/readme"}, {"fetched_at": "2026-10-28T21:02:45.725882+08:00", "kind": "license", "sha256": "174c480c8cbed93cc223fe8701db8e2de473ef461ac133e2a6d88f76b031cf70", "snapshot_path": "sources/174c480c8cbed93cc223fe8701db8e2de473ef461ac133e2a6d88f76b031cf70.txt", "url": "https://api.github.com/repos/theopenlane/core/license"}, {"fetched_at": "2026-10-28T21:18:43.444799+08:00", "kind": "license", "sha256": "1a81a3ffbf5107ab6932b2ee55eb7d6c7a8d2775c8f160a0d757564aa85bcee3", "snapshot_path": "sources/1a81a3ffbf5107ab6932b2ee55eb7d6c7a8d2775c8f160a0d757564aa85bcee3.txt", "url": "https://api.github.com/repos/theopenlane/openlane-ui/license"}, {"fetched_at": "2026-10-28T21:18:43.113668+08:00", "kind": "documentation", "sha256": "6da3dea994fcb08488e36b95cf4076e48a1e0e791e3cebe4eafaf6274a31a4b8", "snapshot_path": "sources/6da3dea994fcb08488e36b95cf4076e48a1e0e791e3cebe4eafaf6274a31a4b8.txt", "url": "https://docs.theopenlane.io/docs/platform/compliance-management/overview"}, {"fetched_at": "2026-10-28T21:19:47.369951+08:00", "kind": "documentation", "sha256": "3b2786419c3d94e4eb41a03f31d43e84c108ecf375cfa628744212512008844f", "snapshot_path": "sources/3b2786419c3d94e4eb41a03f31d43e84c108ecf375cfa628744212512008844f.txt", "url": "https://docs.theopenlane.io/docs/platform/compliance-management/policy-and-procedure-management/policies"}, {"fetched_at": "2026-10-28T21:20:09.954122+08:00", "kind": "documentation", "sha256": "9634651d6d698cd0e0615e130c3619afc502f5619d3abff0eb6f25ce7061506c", "snapshot_path": "sources/9634651d6d698cd0e0615e130c3619afc502f5619d3abff0eb6f25ce7061506c.txt", "url": "https://docs.theopenlane.io/docs/platform/compliance-management/policy-and-procedure-management/policy-sign-off"}, {"fetched_at": "2026-10-28T21:18:46.578161+08:00", "kind": "documentation", "sha256": "1d648ccd581af0765a34582d62ccda305c59736a90de3fab2e82c02dbc905e73", "snapshot_path": "sources/1d648ccd581af0765a34582d62ccda305c59736a90de3fab2e82c02dbc905e73.txt", "url": "https://www.theopenlane.io/product/compliance/policies-and-procedures"}, {"fetched_at": "2026-10-28T21:06:22.723532+08:00", "kind": "documentation", "sha256": "a33c177a5046d933bb123f422315fd4bc32e0a3213d2c25c0b2ef0f24bfab8af", "snapshot_path": "sources/a33c177a5046d933bb123f422315fd4bc32e0a3213d2c25c0b2ef0f24bfab8af.txt", "url": "https://www.theopenlane.io/product/compliance"}], "summary": "开源（Apache-2.0）合规自动化平台：compliance management 下含 policies、controls、evidence、programs 四类对象，每类对象均有编辑、审批、评论与完整历史；政策与程序在平台文档中为独立文档类型，支持自动版本化、审批后发布、向人员发送签署请求（签署绑定所读修订版本）并留存签署时间与来源，另可映射 SOC 2、ISO 27001、NIST 800-53 等框架并授予审计员只读访问。开源核心包括 core 服务端/编排服务与 openlane-ui Web 控制台（均为 Apache-2.0）；SaaS/云服务按商业条款提供，logo 与商标不在 Apache-2.0 范围内。", "technology_stack": ["Go", "PostgreSQL", "Redis", "GraphQL", "React", "TypeScript", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:diligent','Diligent','{"homepage": "https://www.diligent.com/", "id": "commercial:diligent", "leaf_matches": [{"reason": "官方产品页正文可逐字核对：以董事会会议为单元，''Build agendas, compile board books, and generate minutes''（构建议程、汇编董事会资料包、生成纪要），''Role-based permissions, encryption, and audit trails''（成员/角色限定的机密分发与审计留痕），''Turn notes and minutes into clear, trackable action items''（纪要转行动项），以及 ''From D&O questionnaires to pre-reads and voting'' 与 ''Vote securely with e-signature and audit logs''（治理计划外围的问卷、预读与签署投票）。实体治理模块仅见于导航/页脚，未计入本条。", "slug": "corporate-governance-platform", "source_urls": ["https://www.diligent.com/products/boards"]}], "name": "Diligent", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:23:18.934652+08:00", "kind": "homepage", "sha256": "021890d9027247bc0d2e3e644b7df051e57871fa3b86f24af0def866f1de8be0", "snapshot_path": "sources/021890d9027247bc0d2e3e644b7df051e57871fa3b86f24af0def866f1de8be0.txt", "url": "https://www.diligent.com/"}, {"fetched_at": "2026-10-28T21:13:20.830700+08:00", "kind": "documentation", "sha256": "c8aac61a7557dd31562855cf75a0d936bc05d5423913bfff4c835a100537b42b", "snapshot_path": "sources/c8aac61a7557dd31562855cf75a0d936bc05d5423913bfff4c835a100537b42b.txt", "url": "https://www.diligent.com/products/boards"}], "summary": "董事会管理软件（board portal）：以 AI 辅助会议准备，构建议程、汇编董事会资料包并生成会议纪要与行动项；提供基于角色的权限、加密与审计留痕，以及 D&O 问卷、预读、投票与电子签署。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1203202128','LQGovernance — Board Management Portal','{"deployment": ["Docker Compose 自托管，应用与 PostgreSQL 由同一 Compose 编排", "提供 Dockerfile、Caddyfile 与生产部署文档，可置于自有 HTTPS 反向代理之后"], "features": ["董事会与成员范围：董事会、成员、治理档案与规则持久化为统一记录，操作按角色、董事会、回避与保密规则校验", "会议：带议程与出席记录的会议，出席数据被投票计票读取", "董事会材料：上传、分类、下载，按成员授权并支持显式拒绝（回避优先）的文档访问控制", "会议记录：纪要草稿、评论、签署，签署人持个人 Ed25519 密钥", "决议与投票：会议表决与传签，法定人数、通过门槛、回避、代理与加权投票，结束后生成签名证书", "治理义务：任务分派、证据提交与复核，截止期限触发提醒或失效", "审计：HMAC 审计链，写入失败即回滚；完整记录导出与留存快照"], "github_repository_id": 1203202128, "homepage": "https://github.com/LegalQuants/LQGovernance-OpenBoard", "id": "github:1203202128", "leaf_matches": [{"reason": "仓库 README 正文与仓库树显示其为持续运行的董事会治理 Web 应用（artifacts/easyboard 为 React 单页前端，artifacts/api-server 为 Express API，lib/ 含计票与访问模型）：带议程与出席的会议、按成员分发的董事会材料、纪要签署与决议投票构成定义性会议核心，任务与治理规则覆盖外围治理义务。", "slug": "corporate-governance-platform", "source_urls": ["https://github.com/LegalQuants/LQGovernance-OpenBoard", "https://api.github.com/repos/LegalQuants/LQGovernance-OpenBoard"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/LegalQuants/LQGovernance-OpenBoard/license", "name": "LQGovernance — Board Management Portal", "repository_url": "https://github.com/LegalQuants/LQGovernance-OpenBoard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:13:20.708341+08:00", "kind": "repository_metadata", "sha256": "d25bb0fa98c504cf26b9eaafb43d1d642f126ac7ddf2c6dbe6e55114760aa55f", "snapshot_path": "sources/d25bb0fa98c504cf26b9eaafb43d1d642f126ac7ddf2c6dbe6e55114760aa55f.txt", "url": "https://github.com/LegalQuants/LQGovernance-OpenBoard"}, {"fetched_at": "2026-10-28T21:14:17.865758+08:00", "kind": "repository_metadata", "sha256": "eb8bb731c88254dc5ca34cf198e40395c233d6e8ffcfa6128e34b545e4fd9a0a", "snapshot_path": "sources/eb8bb731c88254dc5ca34cf198e40395c233d6e8ffcfa6128e34b545e4fd9a0a.txt", "url": "https://api.github.com/repos/LegalQuants/LQGovernance-OpenBoard"}, {"fetched_at": "2026-10-28T21:14:18.290392+08:00", "kind": "license", "sha256": "995441e05746e209c02c07e254b9b39a0fba0ac512e6f6535d9a6a42baed1ead", "snapshot_path": "sources/995441e05746e209c02c07e254b9b39a0fba0ac512e6f6535d9a6a42baed1ead.txt", "url": "https://api.github.com/repos/LegalQuants/LQGovernance-OpenBoard/license"}], "summary": "自托管董事会治理门户：以会议为单元组织议程与出席、按成员权限分发董事会材料、起草并签署会议纪要，同时提供决议投票、任务与审计链。", "technology_stack": ["TypeScript", "React", "Express", "PostgreSQL", "Socket.IO", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:diligent-entities','Diligent Entities','{"homepage": "https://www.diligent.com/", "id": "commercial:diligent-entities", "leaf_matches": [{"reason": "官方 Entities 产品正文（非仅导航）说明：将每个实体的数据、所有权、授权与申报集中于受权限控制的企业记录，跟踪 100+ 管辖区的合规义务，自动化组织架构图与申报相关重复工作，并强调集中证据、可审计性与漏报截止日风险；对应本类型的实体登记、义务/到期跟踪与可审计合规状态三项核心。", "slug": "entity-compliance-management", "source_urls": ["https://www.diligent.com/products/entities"]}], "name": "Diligent Entities", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:23:18.934652+08:00", "kind": "homepage", "sha256": "021890d9027247bc0d2e3e644b7df051e57871fa3b86f24af0def866f1de8be0", "snapshot_path": "sources/021890d9027247bc0d2e3e644b7df051e57871fa3b86f24af0def866f1de8be0.txt", "url": "https://www.diligent.com/"}, {"fetched_at": "2026-10-28T21:24:44.822297+08:00", "kind": "documentation", "sha256": "fbaa3844c7a401b2ec333a952350e643ee04058c478f1b82a1c9e0947565ecd0", "snapshot_path": "sources/fbaa3844c7a401b2ec333a952350e643ee04058c478f1b82a1c9e0947565ecd0.txt", "url": "https://www.diligent.com/products/entities"}], "summary": "面向公司秘书与法务团队的实体与子公司管理产品：以受权限控制的企业记录集中实体数据、所有权、授权与申报，跟踪跨 100+ 管辖区的合规义务及截止日，并留存审计轨迹。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1172934784','Entity Compliance Tracker','{"deployment": ["本地一键脚本 start.sh / start.bat（FastAPI + Streamlit，默认 http://localhost:8501）", "Docker Compose 自托管（前端 8501、API 8000）", "README 提供 Railway 一键云部署路径；本次未部署或运行"], "features": ["实体登记册：名称、管辖地、实体类型、成立日期、注册代理、董事/高管、治理文件与良好存续状态", "合规日历：跨实体的申报截止日列表/日历视图，按逾期、临近、正常分级", "组合仪表盘：实体总数、即将到期、逾期项、良好存续比例及按管辖地/类型统计", "申报生命周期：pending → filed 状态、filed_date 记录、逾期状态自动置为 overdue", "到期提醒：SMTP 邮件与 Slack webhook，可按实体覆盖提醒间隔并去重", "股权结构图：D3.js 可折叠组织树，展示持股比例关系"], "github_repository_id": 1172934784, "homepage": "https://github.com/noamrazbuilds/entity-compliance-tracker", "id": "github:1172934784", "leaf_matches": [{"reason": "README 与源码显示以法律实体为记录单元：实体含管辖地、实体类型、注册代理、董事/高管与良好存续状态；义务以 FilingDeadline（filing_type、due_date、status=pending/filed/overdue、filed_date）挂在实体下，并有跨实体合规日历、到期提醒与组合级良好存续统计，构成“实体登记→义务与到期日→准备/申报/确认→留档”的核心闭环。文档未展示直接向登记机关提交或机构数据回读，故不据此扩展。", "slug": "entity-compliance-management", "source_urls": ["https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/README.md", "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/ect_app/services/filing_service.py", "https://github.com/noamrazbuilds/entity-compliance-tracker"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/LICENSE", "license_review": {"rationale": "快照为完整 MIT 许可证正文（Copyright (c) 2026 Noam Raz and Pleasant Secret Labs），含授权条款与免责声明，无附加限制或商业版拆分条款；仓库元数据与 LICENSE 文件一致标注 MIT。", "reviewer": "OpenDesign collector (DeepSeek V4.1 Flash), unit 077", "scope": "repository", "source_url": "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/LICENSE", "spdx_id": "MIT"}, "name": "Entity Compliance Tracker", "repository_url": "https://github.com/noamrazbuilds/entity-compliance-tracker", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:26:42.502841+08:00", "kind": "repository_metadata", "sha256": "53cf0ec6a4631001b9fd23449f398693dae8d50056253101bbb479510068a11d", "snapshot_path": "sources/53cf0ec6a4631001b9fd23449f398693dae8d50056253101bbb479510068a11d.txt", "url": "https://github.com/noamrazbuilds/entity-compliance-tracker"}, {"fetched_at": "2026-10-28T21:26:45.576926+08:00", "kind": "readme", "sha256": "67f62db57c9666009e03152220f98eb6881aaa708aa59e271f1bb5964202b0a5", "snapshot_path": "sources/67f62db57c9666009e03152220f98eb6881aaa708aa59e271f1bb5964202b0a5.txt", "url": "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/README.md"}, {"fetched_at": "2026-10-28T21:26:47.696436+08:00", "kind": "license", "sha256": "5c1168bd8375d8b508a280b7e72a42f219bc2ab9a7d2a134b2fcfabffb07b5dc", "snapshot_path": "sources/5c1168bd8375d8b508a280b7e72a42f219bc2ab9a7d2a134b2fcfabffb07b5dc.txt", "url": "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/LICENSE"}, {"fetched_at": "2026-10-28T21:30:01.092784+08:00", "kind": "documentation", "sha256": "d2d69acb6ea6537870c52632c5a8a5cf23ced89d553205a66cf4526c90024e5d", "snapshot_path": "sources/d2d69acb6ea6537870c52632c5a8a5cf23ced89d553205a66cf4526c90024e5d.txt", "url": "https://raw.githubusercontent.com/noamrazbuilds/entity-compliance-tracker/main/ect_app/services/filing_service.py"}], "summary": "自托管的法律实体合规管理 Web 应用：集中登记公司/子公司实体（管辖地、类型、注册代理、董事高管、良好存续状态），按实体维护申报类型、截止日与 pending/filed/overdue 状态，提供组合级合规日历、逾期提醒与实体文件归档，MIT 许可。", "technology_stack": ["Python / FastAPI", "SQLAlchemy", "Streamlit", "D3.js", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:navex','NAVEX','{"homepage": "https://www.navex.com/", "id": "commercial:navex", "leaf_matches": [{"reason": "官方 COI 披露管理产品页正文说明可按披露类型、政策需要和员工群体配置问卷，收集利益冲突及礼品、款待、差旅、家庭关系等事实，将每项披露路由至负责评估的人员或团队，支持附加支持文件、请求补充信息、升级未完成或延迟的审查，并保留年内修订与原披露的关联及审查状态、审查备注；可用于审计报告。披露、按规则审查、判定记录（审查状态与备注随披露保留）和持久登记册四项核心有对应正文；该页未展示可配置判定结果类型字段，故不就该细节作断言。", "slug": "ethics-conduct-management", "source_urls": ["https://www.navex.com/en-us/platform/coi-disclosure-management-software/"]}], "name": "NAVEX", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:23:25.847599+08:00", "kind": "homepage", "sha256": "895799b3b7321823e68296c8f10e7e3382cbe8c87c404d3ed38089d474d8680d", "snapshot_path": "sources/895799b3b7321823e68296c8f10e7e3382cbe8c87c404d3ed38089d474d8680d.txt", "url": "https://www.navex.com/"}, {"fetched_at": "2026-10-28T21:27:39.435177+08:00", "kind": "documentation", "sha256": "361144be0e938d55eb27340f587c2dc40d3b67cc258f4a0cb06643804c8d5597", "snapshot_path": "sources/361144be0e938d55eb27340f587c2dc40d3b67cc258f4a0cb06643804c8d5597.txt", "url": "https://www.navex.com/en-us/platform/coi-disclosure-management-software/"}], "summary": "NAVEX One 平台下的披露管理模块（Disclosure Management），用于收集和审查员工利益冲突披露，包括礼品、差旅与款待；支持可配置问卷、审查路由、年内更新与审计报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:45261230','Kuali Research COI','{"deployment": ["Node.js + npm 自托管运行，使用 Express 提供 Web 与 REST API", "MySQL 或 Oracle 数据库，通过 knex 迁移建表并可选用演示种子数据", "默认启用内置 mock 认证；接入官方 Kuali Core Auth Service 需单独配置 AUTH_URL 等变量"], "features": ["研究人员填写披露问卷，记录财务实体、关系类型、金额区间、差旅与支持文件", "支持年度披露、按项目触发的披露、修订与到期/需更新状态", "区分 COI 管理员与审查人角色，可将披露指派给审查人并请求补充", "审查产生处置结果（disposition）与状态，支持批量设置处置", "归档披露与最近归档版本可供管理员和本人检索，保留审查和修订轨迹", "项目与发起人关联、通知与披露汇总/过滤"], "github_repository_id": 45261230, "homepage": "https://github.com/kuali/research-coi", "id": "github:45261230", "leaf_matches": [{"reason": "该仓库是 Kuali Research 的 COI 模块，README 说明其管理受资助项目的合规披露并提供 COI 管理员/审查人角色；披露 API 文档显示披露含财务实体、关系、差旅、支持文件、修订日期、审查日期与处置类型，并提供年度披露和归档披露接口；CHANGELOG 记录审查人指派、处置（disposition）、管理计划、退回修订与归档检索。四项定义性核心（自我披露、按规则审查、记录判定、持久登记册）均有对应实现，属于可自托管的完整业务子模块。", "slug": "ethics-conduct-management", "source_urls": ["https://raw.githubusercontent.com/kuali/research-coi/master/README.md", "https://raw.githubusercontent.com/kuali/research-coi/master/doc/public-api/disclosures.md", "https://raw.githubusercontent.com/kuali/research-coi/master/CHANGELOG.md"]}], "license": "AGPL-3.0", "license_evidence_url": "https://raw.githubusercontent.com/kuali/research-coi/master/LICENSE", "license_review": {"rationale": "读取该仓库 master 分支 LICENSE 完整文本（约 34KB），含 GNU Affero General Public License 标题、Version 3 与完整条款，与该仓库元数据标注的 AGPL-3.0 一致。", "reviewer": "collection-agent", "scope": "repository", "source_url": "https://raw.githubusercontent.com/kuali/research-coi/master/LICENSE", "spdx_id": "AGPL-3.0"}, "name": "Kuali Research COI", "repository_url": "https://github.com/kuali/research-coi", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:31:05.843336+08:00", "kind": "repository_metadata", "sha256": "ace6d819fbdf8aa82d1525c1919d7d8a40bd2a703c950f23446d359ee829acc5", "snapshot_path": "sources/ace6d819fbdf8aa82d1525c1919d7d8a40bd2a703c950f23446d359ee829acc5.txt", "url": "https://github.com/kuali/research-coi"}, {"fetched_at": "2026-10-28T21:31:08.627427+08:00", "kind": "license", "sha256": "10ede613cce81dc5381ec9c1a08dcfdcd425d2a186a3efb25231ee3ba308585a", "snapshot_path": "sources/10ede613cce81dc5381ec9c1a08dcfdcd425d2a186a3efb25231ee3ba308585a.txt", "url": "https://raw.githubusercontent.com/kuali/research-coi/master/LICENSE"}, {"fetched_at": "2026-10-28T21:32:16.212564+08:00", "kind": "readme", "sha256": "7e0efbf11a768b39424661b20b9bb06c7b03c6b9ceee3478bef30bc7013dda90", "snapshot_path": "sources/7e0efbf11a768b39424661b20b9bb06c7b03c6b9ceee3478bef30bc7013dda90.txt", "url": "https://raw.githubusercontent.com/kuali/research-coi/master/README.md"}, {"fetched_at": "2026-10-28T21:32:18.013747+08:00", "kind": "documentation", "sha256": "3c70b474829230a999be48ddd9dcf059f2bc6cceee920d08040c3124540c7d22", "snapshot_path": "sources/3c70b474829230a999be48ddd9dcf059f2bc6cceee920d08040c3124540c7d22.txt", "url": "https://raw.githubusercontent.com/kuali/research-coi/master/CHANGELOG.md"}, {"fetched_at": "2026-10-28T21:33:10.137961+08:00", "kind": "documentation", "sha256": "57c180b617e92c1979914d60e92c92a2519012794d8b4af74155b6c0a8011657", "snapshot_path": "sources/57c180b617e92c1979914d60e92c92a2519012794d8b4af74155b6c0a8011657.txt", "url": "https://raw.githubusercontent.com/kuali/research-coi/master/doc/public-api/disclosures.md"}, {"fetched_at": "2026-10-28T21:36:50.366339+08:00", "kind": "documentation", "sha256": "2228de9434d839ac98b0145763541cb1841cd30505dddee2f1cbae0cacff1c83", "snapshot_path": "sources/2228de9434d839ac98b0145763541cb1841cd30505dddee2f1cbae0cacff1c83.txt", "url": "https://raw.githubusercontent.com/kuali/research-coi/master/package.json"}], "summary": "Kuali Research 的利益冲突（COI）管理模块，自托管 Web 应用：研究人员提交披露与财务实体/关系记录，管理员和审查人完成审查与处置，披露可修订并归档保留。仓库整体以 AGPL-3.0 发布；默认使用内置 mock 认证，官方参考认证服务需另行配置。", "technology_stack": ["Node.js / Express", "React 15 + Alt（前端）", "Knex（MySQL / Oracle）", "REST API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:intapp-conflicts','Intapp Conflicts','{"homepage": "https://www.intapp.com/conflicts/", "id": "commercial:intapp-conflicts", "leaf_matches": [{"reason": "Intapp Conflicts 官方产品页正文明确：集中统一客户、业务与关系数据为可检索系统；以统一实时数据执行冲突检索并提前筛查机会；记录每次检索与结果形成可审计记录；由决策者复核命中、添加备注并记录处置；报告可按 Walls 策略自动过滤机密信息。以上覆盖关系宇宙、结构化且留存的冲突检查以及命中复核与处置记录，符合定义性核心。注：entries.sources 中的 https://www.intapp.com/products/conflicts/ 快照实际为重定向后的 /products/ 总览页，正文仅导航、无 Conflicts 内容，仅作历史缺口留档，不作为本匹配的核心依据。", "slug": "legal-conflict-checking-platform", "source_urls": ["https://www.intapp.com/conflicts/"]}], "name": "Intapp Conflicts", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:36:57.458853+08:00", "kind": "documentation", "sha256": "5bedf73214106b2fb880f80f294a5eb30f78a41964e60046be93d1f53d332c0c", "snapshot_path": "sources/5bedf73214106b2fb880f80f294a5eb30f78a41964e60046be93d1f53d332c0c.txt", "url": "https://www.intapp.com/conflicts/"}, {"fetched_at": "2026-10-24T22:24:14.908210+08:00", "kind": "homepage", "sha256": "9e5d15ed2db9b5220436a3f7bb79ad06b13f88ae996ee8173692bbc8e59b8736", "snapshot_path": "sources/9e5d15ed2db9b5220436a3f7bb79ad06b13f88ae996ee8173692bbc8e59b8736.txt", "url": "https://www.intapp.com/products/conflicts/"}], "summary": "面向律所及专业服务机构的利益冲突审查平台：集中客户、业务与关系数据形成可检索的关系体系，执行冲突检索并留存检查，由决策者复核命中、记录处置并生成可审计报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:onetrust','OneTrust','{"homepage": "https://www.onetrust.com/", "id": "commercial:onetrust", "leaf_matches": [{"reason": "官方 Privacy Automation 解决方案页正文（非仅导航）写明：集中映射个人数据处理的数据、业务与监管背景，并提供资产/流程/供应商的数据清单以支撑 records of processing (ROPA)；自动化 PIA 等下游评估工作流；对 DSR 提供从受理到履行的自动化（含身份验证）。对应处理登记册、义务背景关联与带证据的履行闭环三项结构性核心。", "slug": "privacy-management-platform", "source_urls": ["https://www.onetrust.com/solutions/privacy-automation/", "https://www.onetrust.com/"]}], "name": "OneTrust", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:17.639659+08:00", "kind": "homepage", "sha256": "84379ba69dffba66efc999bcd66daf18e596331378c201440aaccbd402c441a5", "snapshot_path": "sources/84379ba69dffba66efc999bcd66daf18e596331378c201440aaccbd402c441a5.txt", "url": "https://www.onetrust.com/"}, {"fetched_at": "2026-10-28T21:55:29.056366+08:00", "kind": "documentation", "sha256": "a8bb3596acfd5e5e9d20ea26c571f7181947548cb659ff95822d10f38efae8de", "snapshot_path": "sources/a8bb3596acfd5e5e9d20ea26c571f7181947548cb659ff95822d10f38efae8de.txt", "url": "https://www.onetrust.com/solutions/privacy-automation/"}], "summary": "隐私合规平台：官方 Privacy Automation 页面说明其集中映射个人数据处理活动与监管背景（数据清单/ROPA），运行隐私风险与影响评估工作流，并自动化数据主体请求（DSR）的受理与履行。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:5618793','GlobaLeaks','{"deployment": ["self-hosted"], "features": ["匿名举报接收与持久报告记录", "举报人身份保密，可自行决定是否披露", "16 位回执登录与双向聊天", "多角色（举报人/接收人/管理员）与案件状态", "多渠道、多站点与 90+ 语言"], "github_repository_id": 5618793, "homepage": "https://globaleaks.org/", "id": "github:5618793", "leaf_matches": [{"reason": "官方首页与用户功能正文说明其提供安全的匿名举报渠道、持久报告、举报人可决定是否披露身份、16 位回执登录与双向聊天、接收人案件状态与分类，并由官方安装文档证明可自托管为完整 Web 应用，覆盖定义性核心。", "slug": "whistleblowing-speak-up-platform", "source_urls": ["https://globaleaks.org/", "https://globaleaks.org/features/user/", "https://docs.globaleaks.org/en/stable/setup/installation.html"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/globaleaks/globaleaks-whistleblowing-software/license", "name": "GlobaLeaks", "repository_url": "https://github.com/globaleaks/globaleaks-whistleblowing-software", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:43.483421+08:00", "kind": "homepage", "sha256": "c810f24cbacea6fb52d41bef6f48aff2da30a52a629ebe1ee9a6216206291894", "snapshot_path": "sources/c810f24cbacea6fb52d41bef6f48aff2da30a52a629ebe1ee9a6216206291894.txt", "url": "https://globaleaks.org/"}, {"fetched_at": "2026-10-24T22:21:28.404205+08:00", "kind": "repository_metadata", "sha256": "04f04aead04eb921fb855464409ca71fa26b56c3bf70fcc133755b34178d3bc8", "snapshot_path": "sources/04f04aead04eb921fb855464409ca71fa26b56c3bf70fcc133755b34178d3bc8.txt", "url": "https://api.github.com/repos/globaleaks/globaleaks-whistleblowing-software"}, {"fetched_at": "2026-10-24T22:22:34.714486+08:00", "kind": "license", "sha256": "44e93a5319a090633b39ade6a669a7a2287e63dc2cc6efab53cf66f846ae91c9", "snapshot_path": "sources/44e93a5319a090633b39ade6a669a7a2287e63dc2cc6efab53cf66f846ae91c9.txt", "url": "https://api.github.com/repos/globaleaks/globaleaks-whistleblowing-software/license"}, {"fetched_at": "2026-10-28T21:47:20.947114+08:00", "kind": "documentation", "sha256": "51fa94b2dd453cce0a7330820ee2b405eb7ae40f4aa7462a44264796e107236e", "snapshot_path": "sources/51fa94b2dd453cce0a7330820ee2b405eb7ae40f4aa7462a44264796e107236e.txt", "url": "https://globaleaks.org/features/user/"}, {"fetched_at": "2026-10-28T21:47:21.843366+08:00", "kind": "readme", "sha256": "15d79571d40c74272fa98130a60ffd94bc2b2455b7f83b9b92805f96d1ee78c1", "snapshot_path": "sources/15d79571d40c74272fa98130a60ffd94bc2b2455b7f83b9b92805f96d1ee78c1.txt", "url": "https://api.github.com/repos/globaleaks/globaleaks-whistleblowing-software/readme"}, {"fetched_at": "2026-10-28T21:50:11.848543+08:00", "kind": "documentation", "sha256": "7fe39ca411bc7806cd156bc9ee6c0a885df35998f784e1d6df7f8754124f2465", "snapshot_path": "sources/7fe39ca411bc7806cd156bc9ee6c0a885df35998f784e1d6df7f8754124f2465.txt", "url": "https://docs.globaleaks.org/en/stable/setup/installation.html"}], "summary": "开源举报/发声平台，提供常设匿名接收渠道、持久报告记录、举报人身份保护与受保护的双向后续沟通，可自托管为完整 Web 应用。", "technology_stack": ["Python", "TypeScript"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:620069905','Hush Line','{"deployment": ["self-hosted"], "features": ["无需账户的匿名举报提交", "PGP 端到端加密与双向加密会话", "消息状态管理、回复链接与通知", "Tor onion 支持与隐私默认设置", "Docker Compose 自托管"], "github_repository_id": 620069905, "homepage": "https://hushline.app", "id": "github:620069905", "leaf_matches": [{"reason": "README 与官网正文说明其面向记者、律师、雇主等提供开源匿名举报线索线：无需账户即可提交，PGP 端到端加密，接收人可接受/拒绝/归档并回复，举报人与接收人可进行受保护的加密双向沟通，覆盖常设保护渠道、报告记录、身份保护与后续循环；并有明确的自托管路径。", "slug": "whistleblowing-speak-up-platform", "source_urls": ["https://api.github.com/repos/scidsg/hushline/readme", "https://hushline.app"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/scidsg/hushline/license", "name": "Hush Line", "repository_url": "https://github.com/scidsg/hushline", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:48:21.331013+08:00", "kind": "repository_metadata", "sha256": "192aca834541141ea1d338559170df278cd9cf7f4c6a7e69f7a6b12fbbf81477", "snapshot_path": "sources/192aca834541141ea1d338559170df278cd9cf7f4c6a7e69f7a6b12fbbf81477.txt", "url": "https://api.github.com/repos/scidsg/hushline"}, {"fetched_at": "2026-10-28T21:48:24.537101+08:00", "kind": "license", "sha256": "0b1cb8345d5555d789f6dec7d384b06d968c9c1485b8ad3b29e57055b85b8c49", "snapshot_path": "sources/0b1cb8345d5555d789f6dec7d384b06d968c9c1485b8ad3b29e57055b85b8c49.txt", "url": "https://api.github.com/repos/scidsg/hushline/license"}, {"fetched_at": "2026-10-28T21:48:37.145572+08:00", "kind": "readme", "sha256": "22f5bee36205e5e822b7c178c365b177cc2caa1e29a6b6e863b225f1f4fa996a", "snapshot_path": "sources/22f5bee36205e5e822b7c178c365b177cc2caa1e29a6b6e863b225f1f4fa996a.txt", "url": "https://api.github.com/repos/scidsg/hushline/readme"}, {"fetched_at": "2026-10-28T21:49:01.974502+08:00", "kind": "homepage", "sha256": "d19432a53bb6ac238759fd6aa84f97a09865da6f5986b98cd138ee1402b6b765", "snapshot_path": "sources/d19432a53bb6ac238759fd6aa84f97a09865da6f5986b98cd138ee1402b6b765.txt", "url": "https://hushline.app"}], "summary": "开源匿名举报/线索平台，提供无需账户的加密提交、举报人与接收人之间的端到端加密双向沟通、消息状态管理与 Tor 接入；仓库支持 Docker Compose 自托管。", "technology_stack": ["Python", "Flask", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:831684951','OpenWhistle','{"deployment": ["self-hosted"], "features": ["举报人不记录 IP、无需账户", "案号 + UUID4 PIN 回访案件", "匿名或保密提交，姓名加密", "双向消息与附件、状态工作流", "HinSchG 7 天确认/3 个月反馈期限跟踪", "审计日志、角色与四眼删除"], "github_repository_id": 831684951, "homepage": "https://openwhistle.net", "id": "github:831684951", "leaf_matches": [{"reason": "README 与官网正文说明其为自托管内部举报渠道：举报人无账户、无 IP 记录，可匿名或保密提交；案号+PIN 形成持久报告并回访；双向消息、附件与状态工作流构成受保护后续循环；官方注明符合 EU 2019/1937 与 HinSchG 的确认/反馈期限。", "slug": "whistleblowing-speak-up-platform", "source_urls": ["https://api.github.com/repos/openwhistle/OpenWhistle/readme", "https://openwhistle.net/en/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/openwhistle/OpenWhistle/license", "name": "OpenWhistle", "repository_url": "https://github.com/openwhistle/OpenWhistle", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T21:48:48.879466+08:00", "kind": "repository_metadata", "sha256": "97ccbe0842621772ca4a7bafc3742a0256da16bf6e899daa33efe7872b7f0b36", "snapshot_path": "sources/97ccbe0842621772ca4a7bafc3742a0256da16bf6e899daa33efe7872b7f0b36.txt", "url": "https://api.github.com/repos/openwhistle/OpenWhistle"}, {"fetched_at": "2026-10-28T21:48:50.036763+08:00", "kind": "license", "sha256": "a3805cef8adf784fbc28657a8c12186ec2fda7af592be78ba976c832e8e04d8d", "snapshot_path": "sources/a3805cef8adf784fbc28657a8c12186ec2fda7af592be78ba976c832e8e04d8d.txt", "url": "https://api.github.com/repos/openwhistle/OpenWhistle/license"}, {"fetched_at": "2026-10-28T21:49:00.078409+08:00", "kind": "readme", "sha256": "4d2a5eb06c82497200842740cbd94b34a37147dd4ec59061e837a23b75980865", "snapshot_path": "sources/4d2a5eb06c82497200842740cbd94b34a37147dd4ec59061e837a23b75980865.txt", "url": "https://api.github.com/repos/openwhistle/OpenWhistle/readme"}, {"fetched_at": "2026-10-28T21:50:37.350416+08:00", "kind": "homepage", "sha256": "2ba52a69d01b52f4afb73348314574fef1ca6464586588e3b5b19b0226061fec", "snapshot_path": "sources/2ba52a69d01b52f4afb73348314574fef1ca6464586588e3b5b19b0226061fec.txt", "url": "https://openwhistle.net/en/"}], "summary": "面向欧盟举报指令与德国 HinSchG 的开源自托管内部举报平台，提供匿名或保密提交、案号+PIN 回访、双向消息、期限跟踪与审计日志。", "technology_stack": ["Python", "FastAPI", "PostgreSQL", "Redis", "Docker"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1325693726','AuditOne','{"deployment": ["self-hosted"], "features": ["审计范围：部门→流程→实体层级与业务背景画像", "风险评估：加权因子评分、冻结期间历史、带阈值的关键风险指标", "基于风险的年度计划：审批时快照版本化、修订差异、人力容量与分配", "审计项目：阶段、范围文档、风险与控制矩阵、模板化审计程序、证据工作底稿、编制/复核签字", "数据工作台：CSV/Excel 导入、DuckDB 沙箱 SQL、可复用测试挂接到工作底稿", "发现事项台账：条件/标准/原因/影响结构化记录，受控生命周期至验证关闭、风险接受、逾期老化", "被审计方门户：问题责任人回复、上传证据、申请延期、查看已签发报告", "报告：区块式构建、版本化签发、PDF 与 Word 输出", "产品内 IIA 2024 准则符合性映射"], "github_repository_id": 1325693726, "homepage": "https://github.com/daniellewisDL/auditone", "id": "github:1325693726", "leaf_matches": [{"reason": "官方 README 与符合性文档给出内审常设程序的核心结构：审计范围（部门→流程→实体）、风险评估与基于风险的年度计划及容量、审计项目执行（范围、RCM、审计程序、工作底稿、编制/复核签字）；问题台账 schema 以 condition/criteria/cause/effect、管理回应、责任人、截止日与 closed_verified/risk_accepted/reopened 状态实现跨项目跟踪至验证关闭，另有被审计方隔离门户与版本化报告。src/app 下独立的 (portal) 路由组与 src/modules 的 universe/risk/plan/engagements/issues/reports 模块表明为可运行的完整 Web 应用，非 SDK、桌面或仅文档仓库。", "slug": "internal-audit-management", "source_urls": ["https://raw.githubusercontent.com/daniellewisDL/auditone/main/README.md", "https://raw.githubusercontent.com/daniellewisDL/auditone/main/docs/conformance.md", "https://api.github.com/repos/daniellewisDL/auditone/contents/src/modules", "https://raw.githubusercontent.com/daniellewisDL/auditone/main/src/modules/issues/schema.ts", "https://api.github.com/repos/daniellewisDL/auditone/contents/src/app"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/daniellewisDL/auditone/license", "name": "AuditOne", "repository_url": "https://github.com/daniellewisDL/auditone", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:21:29.780602+08:00", "kind": "repository_metadata", "sha256": "65afff33ef4007d5e585435661ae2634565faf4b17c265442e1023144de75711", "snapshot_path": "sources/65afff33ef4007d5e585435661ae2634565faf4b17c265442e1023144de75711.txt", "url": "https://api.github.com/repos/daniellewisDL/auditone"}, {"fetched_at": "2026-10-24T22:22:37.043706+08:00", "kind": "license", "sha256": "036853a987665b619fd849960a66865432d37e3d58823ae5cde8f20fb1b581b7", "snapshot_path": "sources/036853a987665b619fd849960a66865432d37e3d58823ae5cde8f20fb1b581b7.txt", "url": "https://api.github.com/repos/daniellewisDL/auditone/license"}, {"fetched_at": "2026-10-28T22:04:14.079082+08:00", "kind": "readme", "sha256": "0972b6f32e00cfd5bcf3cbc1b3de8dbd23020fb8ffc436ce0ec086e46806c64f", "snapshot_path": "sources/0972b6f32e00cfd5bcf3cbc1b3de8dbd23020fb8ffc436ce0ec086e46806c64f.txt", "url": "https://raw.githubusercontent.com/daniellewisDL/auditone/main/README.md"}, {"fetched_at": "2026-10-28T22:05:25.903159+08:00", "kind": "documentation", "sha256": "a5c0a5a530e07fb5cba907efe57793971042a31a379787e21f8df1ea2e04ae0e", "snapshot_path": "sources/a5c0a5a530e07fb5cba907efe57793971042a31a379787e21f8df1ea2e04ae0e.txt", "url": "https://raw.githubusercontent.com/daniellewisDL/auditone/main/docs/conformance.md"}, {"fetched_at": "2026-10-28T22:04:26.951519+08:00", "kind": "repository_metadata", "sha256": "216e38bd1bf95d411989d7dfd4567e4e3d6a0704c7b777158bf6d08e19b5e273", "snapshot_path": "sources/216e38bd1bf95d411989d7dfd4567e4e3d6a0704c7b777158bf6d08e19b5e273.txt", "url": "https://api.github.com/repos/daniellewisDL/auditone/contents/src/modules"}, {"fetched_at": "2026-10-28T22:04:42.089333+08:00", "kind": "repository_metadata", "sha256": "3e0eccdd7658a289049d33769a6488fc7fe9c8cda57b325dfdfe976617a03161", "snapshot_path": "sources/3e0eccdd7658a289049d33769a6488fc7fe9c8cda57b325dfdfe976617a03161.txt", "url": "https://raw.githubusercontent.com/daniellewisDL/auditone/main/package.json"}, {"fetched_at": "2026-10-28T22:05:53.816483+08:00", "kind": "documentation", "sha256": "014b9c0c347c4b94051aa7beba0cf7c7ac529d2cccc6f415bb5397026f2bcde5", "snapshot_path": "sources/014b9c0c347c4b94051aa7beba0cf7c7ac529d2cccc6f415bb5397026f2bcde5.txt", "url": "https://raw.githubusercontent.com/daniellewisDL/auditone/main/src/modules/issues/schema.ts"}, {"fetched_at": "2026-10-28T22:06:58.370930+08:00", "kind": "repository_metadata", "sha256": "2519cb50daf93e35778494afd4cf071c7078e28a58ff97320dbcff5d727882c9", "snapshot_path": "sources/2519cb50daf93e35778494afd4cf071c7078e28a58ff97320dbcff5d727882c9.txt", "url": "https://api.github.com/repos/daniellewisDL/auditone/contents/src/app"}], "summary": "开源自托管的内部审计管理系统，覆盖审计范围（universe）、风险评估、基于风险的年度计划、审计项目执行与工作底稿、发现整改到验证关闭、被审计方门户与报告，并按 IIA 2024 全球内审准则组织工作流。", "technology_stack": ["Next.js", "TypeScript", "PostgreSQL", "DuckDB"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:metricstream','MetricStream','{"homepage": "https://www.metricstream.com/", "id": "commercial:metricstream", "leaf_matches": [{"reason": "官方 ORM 子产品页以 MetricStream ORM software 命名，正文给出该类型三项定义性结构：风险与控制关联到流程、业务单元、产品的统一视图；可计划排期并执行 top-down/bottom-up 的风险与控制自我评估（RCSA），评估方法与评分可配置；内部损失数据经表单与批量导入采集、外部损失库接入，并通过问题管理回溯根因、连接触发它的风险与控制。", "slug": "operational-risk-management", "source_urls": ["https://www.metricstream.com/products/operational-risk-management.htm"]}], "name": "MetricStream", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:18:35.900964+08:00", "kind": "documentation", "sha256": "b06571889d996fa66cdb7ea40c2b15c0de5cf9e086e27a61646824487b06dd1a", "snapshot_path": "sources/b06571889d996fa66cdb7ea40c2b15c0de5cf9e086e27a61646824487b06dd1a.txt", "url": "https://www.metricstream.com/products/operational-risk-management.htm"}, {"fetched_at": "2026-10-24T22:24:24.592327+08:00", "kind": "homepage", "sha256": "99d92deb86ec4d0285eaae9973c34907ada1550b4b717a6d0a2459636746a20a", "snapshot_path": "sources/99d92deb86ec4d0285eaae9973c34907ada1550b4b717a6d0a2459636746a20a.txt", "url": "https://www.metricstream.com/"}], "summary": "操作风险管理商业产品：以流程为中心维护风险、控制与业务单元的关系，支持风险与控制自我评估（RCSA）活动及内部/外部损失事件采集与根因分析。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:processunity','ProcessUnity','{"homepage": "https://www.processunity.com/", "id": "commercial:processunity", "leaf_matches": [{"reason": "官方 TPRM 平台页正文明确描述：在单一平台维护供应商组合并按风险评分（Risk Index）分级优先级，从 vendor intake、due diligence 到持续监控、服务评审与 offboarding 编排完整第三方生命周期，并以工作流承接整改与审批；三点对应关系清单、逐关系评估与决策响应闭环。", "slug": "third-party-risk-management", "source_urls": ["https://www.processunity.com/third-party-risk-management-platform/"]}], "name": "ProcessUnity", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:24:27.011714+08:00", "kind": "homepage", "sha256": "48cbf875033202ce6a18429875561de139565a0e258344d78c944e40d2ccb78d", "snapshot_path": "sources/48cbf875033202ce6a18429875561de139565a0e258344d78c944e40d2ccb78d.txt", "url": "https://www.processunity.com/"}, {"fetched_at": "2026-10-28T22:10:21.313398+08:00", "kind": "documentation", "sha256": "62ae5645b7eb817bf57f54d660816def323f0d5d9661f99d1d9ad2feecce409d", "snapshot_path": "sources/62ae5645b7eb817bf57f54d660816def323f0d5d9661f99d1d9ad2feecce409d.txt", "url": "https://www.processunity.com/third-party-risk-management-platform/"}], "summary": "第三方风险管理 SaaS：在统一平台上维护供应商清单，执行分级、评估与评分，并编排从引入到退出的监控与整改流程。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1274406965','LT-VRM','{"deployment": ["自托管于 XAMPP（Apache + PHP 8.1+ + MySQL/MariaDB），无 Composer/Node 构建步骤", "复制到 web 根目录后由内置安装器完成数据库与管理员初始化"], "features": ["供应商清单：分级（critical/high/medium/low）、生命周期阶段、固有风险与 0–1000 综合风险分", "评估：内置与自定义问卷模板、带令牌的供应商门户、逐题批准/拒绝/要求澄清、多轮与事件记录", "发现与整改：问题台账（来源含评估/泄露/足迹/舆情）、风险登记册与 SLA 到期跟踪", "关系全周期：合同与文件库、第四方映射、退出（offboarding）清单与到期提醒", "外部情报接入：泄露/暗网（HaveIBeenPwned）、负面舆情（NewsAPI）、被动数字足迹，均有离线演示模式"], "github_repository_id": 1274406965, "homepage": "https://learntprm.com", "id": "github:1274406965", "leaf_matches": [{"reason": "README 与数据库结构显示三个定义性结构均存在于完整 Web 应用内：vendors 表持久保存第三方关系（含 tier、lifecycle、inherent_risk、risk_score），评估模板与供应商门户按关系收集并评分证据，issues/risk_register/offboarding 构成带状态与到期日的决策与响应闭环；README 明确覆盖从引入、评估、整改到退出的全生命周期。MIT 许可，属自托管完整应用而非组件或模板。", "slug": "third-party-risk-management", "source_urls": ["https://api.github.com/repos/learntprm-design/lt-vrm", "https://raw.githubusercontent.com/learntprm-design/lt-vrm/main/README.md", "https://raw.githubusercontent.com/learntprm-design/lt-vrm/main/database/schema.sql"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/learntprm-design/lt-vrm/license", "name": "LT-VRM", "repository_url": "https://github.com/learntprm-design/lt-vrm", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:10:19.598994+08:00", "kind": "repository_metadata", "sha256": "50376cf8d9b46421f8b889ebe42acf8028027d9bc948b6fddaa9c6c89dde8b47", "snapshot_path": "sources/50376cf8d9b46421f8b889ebe42acf8028027d9bc948b6fddaa9c6c89dde8b47.txt", "url": "https://api.github.com/repos/learntprm-design/lt-vrm"}, {"fetched_at": "2026-10-28T22:10:30.549566+08:00", "kind": "readme", "sha256": "edf315ee05465c0775cd79ef93fac0cedfb8854e86fcdb453ae222f7d91dba19", "snapshot_path": "sources/edf315ee05465c0775cd79ef93fac0cedfb8854e86fcdb453ae222f7d91dba19.txt", "url": "https://raw.githubusercontent.com/learntprm-design/lt-vrm/main/README.md"}, {"fetched_at": "2026-10-28T22:10:35.065818+08:00", "kind": "license", "sha256": "6c0de4c8b8048e0bd2f12c5d9cd7492d4ec37df7d7738e8fe454dcd0912ea64a", "snapshot_path": "sources/6c0de4c8b8048e0bd2f12c5d9cd7492d4ec37df7d7738e8fe454dcd0912ea64a.txt", "url": "https://api.github.com/repos/learntprm-design/lt-vrm/license"}, {"fetched_at": "2026-10-28T22:11:10.417223+08:00", "kind": "documentation", "sha256": "a4632b552902085f1acffe3da2a1705871ac92a9d6bd1b35bef7d94e484b292c", "snapshot_path": "sources/a4632b552902085f1acffe3da2a1705871ac92a9d6bd1b35bef7d94e484b292c.txt", "url": "https://raw.githubusercontent.com/learntprm-design/lt-vrm/main/database/schema.sql"}], "summary": "LearnTPRM 开源的第三方/供应商风险管理 Web 应用：维护供应商清单（等级、生命周期、风险分），运行问卷评估与供应商门户，并把发现转入问题与整改跟踪。", "technology_stack": ["PHP 8.1+", "MySQL / MariaDB", "Apache（XAMPP）"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1286096557','Mitch-Risk','{"deployment": ["Docker Compose 自托管（使用预构建镜像或从源码构建）", "PostgreSQL 数据库，Prisma 迁移与种子数据"], "features": ["供应商清单：分级（tier）、数据敏感度、合同金额与地域风险驱动的固有风险评分，以及评估后的残余分", "评估：问卷模板（版本、发布、条件逻辑）、无登录令牌式供应商门户、逐题批准/拒绝/要求澄清与多轮退回", "评分与发现：加权 RAG 评分、按 ISO 27001/SOC 2/NIST CSF/Essential Eight 映射控制项，非合规答案自动生成发现", "响应闭环：跨供应商风险登记册（Open/Remediated/Risk Accepted）、整改状态、认证到期与审计日志", "报告与集成：PDF/CSV 报告、REST API 与 API key 权限范围、HMAC 签名 Webhook"], "github_repository_id": 1286096557, "homepage": "https://risk.mitchforge.com/", "id": "github:1286096557", "leaf_matches": [{"reason": "README 与 Prisma 结构证明其为完整应用服务：Vendor 模型带 tier 与固有风险，Assessment/Template/Response/Evidence 实现按关系的尽职调查与评分，Finding/Risk Register 与审批流构成带责任人的决策与响应闭环；门户与退回机制覆盖第三方参与面。AGPL-3.0 完整许可证文本，Docker 自托管。", "slug": "third-party-risk-management", "source_urls": ["https://api.github.com/repos/mitchelljfranklin/mitch-risk", "https://raw.githubusercontent.com/mitchelljfranklin/mitch-risk/master/README.md", "https://raw.githubusercontent.com/mitchelljfranklin/mitch-risk/master/prisma/schema.prisma"]}], "license": "AGPL-3.0", "license_evidence_url": "https://api.github.com/repos/mitchelljfranklin/mitch-risk/license", "name": "Mitch-Risk", "repository_url": "https://github.com/mitchelljfranklin/mitch-risk", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:10:34.030331+08:00", "kind": "repository_metadata", "sha256": "b06c14ccfd5ef25507477c6ba459176c6a4932f9aaff17fb1beb416bbff5fd8d", "snapshot_path": "sources/b06c14ccfd5ef25507477c6ba459176c6a4932f9aaff17fb1beb416bbff5fd8d.txt", "url": "https://api.github.com/repos/mitchelljfranklin/mitch-risk"}, {"fetched_at": "2026-10-28T22:10:36.558607+08:00", "kind": "readme", "sha256": "17d9af2dc693800f01e25e6224462b6a578c1747113b5dcca16f660ff4853f49", "snapshot_path": "sources/17d9af2dc693800f01e25e6224462b6a578c1747113b5dcca16f660ff4853f49.txt", "url": "https://raw.githubusercontent.com/mitchelljfranklin/mitch-risk/master/README.md"}, {"fetched_at": "2026-10-28T22:10:56.346138+08:00", "kind": "license", "sha256": "d0213c4c79a1a6adfa5e4c8dafee8214b819b85f4976a443fd836b3cd568536e", "snapshot_path": "sources/d0213c4c79a1a6adfa5e4c8dafee8214b819b85f4976a443fd836b3cd568536e.txt", "url": "https://api.github.com/repos/mitchelljfranklin/mitch-risk/license"}, {"fetched_at": "2026-10-28T22:11:09.877200+08:00", "kind": "documentation", "sha256": "06f117a868ef8f7bf1dfe01db2e92d16fd1812790021445cf82a30dee031404c", "snapshot_path": "sources/06f117a868ef8f7bf1dfe01db2e92d16fd1812790021445cf82a30dee031404c.txt", "url": "https://raw.githubusercontent.com/mitchelljfranklin/mitch-risk/master/prisma/schema.prisma"}], "summary": "自托管的第三方供应商风险管理 Web 应用（开源核心）：供应商清单与分级、可发送的评估问卷与无需登录的供应商门户、加权评分与发现台账，支持 Docker Compose 部署。", "technology_stack": ["Next.js 16 / React", "TypeScript", "PostgreSQL + Prisma", "Docker Compose"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:78779599','phpIP','{"deployment": ["self-hosted"], "features": ["Matter/IP 资产记录（案件编号、申请号、优先权、当事人、类别）", "期限与任务跟踪（due date / done date / done flag / assigned_to）", "事件与案卷历史（Filed/Published/Granted/Abandoned/Expiry 状态事件）", "续展流程管理（首函、提醒、缴费、收据、逾期与宽限期标记）", "EPO OPS / USPTO ODP 专利家族导入"], "github_repository_id": 78779599, "homepage": "https://github.com/jjdejong/phpip", "id": "github:78779599", "leaf_matches": [{"reason": "官方 wiki 正文显示：matter 为持久 IP 资产记录（编号/申请号/优先权/类别），期限以 task 的 due date 表示并可按人分配、标记完成，event 累积 Filed→Granted→Abandoned/Expiry 生命周期；README 自述为面向 IP 律所的组合与 docketing Web 工具，三项定义性核心齐备。", "slug": "intellectual-property-management", "source_urls": ["https://api.github.com/repos/jjdejong/phpip/readme", "https://github.com/jjdejong/phpip/wiki/Overview", "https://github.com/jjdejong/phpip/wiki/Events,-Deadlines-and-Tasks"]}, {"reason": "官方 README 自述为管理专利等 IP 组合的律所 Web 工具；wiki 说明以 matter 登记专利事项，并由事件经 task_rules 生成带截止日期、可指派负责人的任务，配合到期邮件提醒，覆盖资产登记、期限义务与提醒闭环。", "slug": "patent-management", "source_urls": ["https://api.github.com/repos/jjdejong/phpip/readme", "https://github.com/jjdejong/phpip/wiki", "https://github.com/jjdejong/phpip/wiki/Events,-Deadlines-and-Tasks"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/jjdejong/phpip/license", "name": "phpIP", "repository_url": "https://github.com/jjdejong/phpip", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:21:35.250772+08:00", "kind": "repository_metadata", "sha256": "f9adf9f9d0173ccb7cbfefd2284469c3db52ca62a6bd71ef93fb0babaac2ce71", "snapshot_path": "sources/f9adf9f9d0173ccb7cbfefd2284469c3db52ca62a6bd71ef93fb0babaac2ce71.txt", "url": "https://api.github.com/repos/jjdejong/phpip"}, {"fetched_at": "2026-10-24T22:22:41.501545+08:00", "kind": "license", "sha256": "f3955ee6a7ff735c7c81dc109325eeff31db6c04f0dcd1638f1cb9320855e088", "snapshot_path": "sources/f3955ee6a7ff735c7c81dc109325eeff31db6c04f0dcd1638f1cb9320855e088.txt", "url": "https://api.github.com/repos/jjdejong/phpip/license"}, {"fetched_at": "2026-10-28T22:10:03.771967+08:00", "kind": "readme", "sha256": "eeb5bfc9e27565b51b1909aa7f3f006bd4e42fbca1226454fc91b0a505b0536e", "snapshot_path": "sources/eeb5bfc9e27565b51b1909aa7f3f006bd4e42fbca1226454fc91b0a505b0536e.txt", "url": "https://api.github.com/repos/jjdejong/phpip/readme"}, {"fetched_at": "2026-10-28T22:10:49.615095+08:00", "kind": "documentation", "sha256": "fdf957bf46a922bdb1feff0602bf0a6ca6983d713da716dec7696aaf75db1755", "snapshot_path": "sources/fdf957bf46a922bdb1feff0602bf0a6ca6983d713da716dec7696aaf75db1755.txt", "url": "https://github.com/jjdejong/phpip/wiki/Overview"}, {"fetched_at": "2026-10-28T22:10:43.739561+08:00", "kind": "documentation", "sha256": "422f616bc43b7e75e4fd27f40ea51cdb46a20814ca7210f9749c9d3a732b29b7", "snapshot_path": "sources/422f616bc43b7e75e4fd27f40ea51cdb46a20814ca7210f9749c9d3a732b29b7.txt", "url": "https://github.com/jjdejong/phpip/wiki/Events,-Deadlines-and-Tasks"}, {"fetched_at": "2026-10-28T22:10:15.600821+08:00", "kind": "documentation", "sha256": "216964bc10045bfe7378f10750217e8155f6fa8c3445bb982bc3ef0331ee8a45", "snapshot_path": "sources/216964bc10045bfe7378f10750217e8155f6fa8c3445bb982bc3ef0331ee8a45.txt", "url": "https://github.com/jjdejong/phpip/wiki/Renewal-Management"}, {"fetched_at": "2026-10-28T22:16:22.571900+08:00", "kind": "documentation", "sha256": "3268105931200529b617e951a363790be50d4b616ecaf583b2d0dc06696a3007", "snapshot_path": "sources/3268105931200529b617e951a363790be50d4b616ecaf583b2d0dc06696a3007.txt", "url": "https://github.com/jjdejong/phpip/wiki"}, {"fetched_at": "2026-10-28T22:16:44.674770+08:00", "kind": "documentation", "sha256": "dfd19f55720354fbb4c3b713c0d3d290230772e59e90bfe851a8246b6ae66be9", "snapshot_path": "sources/dfd19f55720354fbb4c3b713c0d3d290230772e59e90bfe851a8246b6ae66be9.txt", "url": "https://github.com/jjdejong/phpip/wiki/Events,-Deadlines-and-Tasks"}], "summary": "开源知识产权组合管理与案卷（docketing）系统，面向专利律所维护 matter 资产记录、任务到期日与权利生命周期，并提供续展流程与官方数据导入。自托管 PHP/Laravel Web 应用。", "technology_stack": ["PHP", "Laravel", "MySQL"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:89721549','HappyPatent','{"deployment": ["self-hosted"], "features": ["专利/商标案件资产记录（case_id、申请号、申请日、优先权、发明人、代理人）", "案件状态生命周期（草稿/初审/答复/驳回/公告/复审/上诉/放弃等 14 态）", "ControlEvent 期限跟踪（control_date、deadline、complete_date）", "Work 承办事项与 control_deadline 分派", "Docker Compose 自托管（PostgreSQL、ElasticSearch、Tika 全文检索）"], "github_repository_id": 89721549, "homepage": "https://github.com/ktshen/happypatent", "id": "github:89721549", "leaf_matches": [{"reason": "proposals/models.py 正文定义 Patent 资产记录（case_id、申请/公告号、优先权、代理人、14 态 case_status）、ControlEvent（control_item + deadline + complete_date）与 Work（control_deadline），README 说明其为专利商标代理机构的自托管 Django 管理系统，覆盖资产记录/期限/生命周期三项核心。", "slug": "intellectual-property-management", "source_urls": ["https://api.github.com/repos/ktshen/happypatent/readme", "https://api.github.com/repos/ktshen/happypatent/contents/proposals/models.py"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/ktshen/happypatent/license", "name": "HappyPatent", "repository_url": "https://github.com/ktshen/happypatent", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:11:15.512789+08:00", "kind": "repository_metadata", "sha256": "fa4c8e168464d64046ff98dabca365d3b7c06bd3ef427d54a0110bb59d5be0b2", "snapshot_path": "sources/fa4c8e168464d64046ff98dabca365d3b7c06bd3ef427d54a0110bb59d5be0b2.txt", "url": "https://api.github.com/repos/ktshen/happypatent"}, {"fetched_at": "2026-10-28T22:11:18.085852+08:00", "kind": "readme", "sha256": "f94963e3356ce2a35fe8fbd20043d4f78a9e5aacf3ac5a996977027aad0b8793", "snapshot_path": "sources/f94963e3356ce2a35fe8fbd20043d4f78a9e5aacf3ac5a996977027aad0b8793.txt", "url": "https://api.github.com/repos/ktshen/happypatent/readme"}, {"fetched_at": "2026-10-28T22:11:34.112675+08:00", "kind": "license", "sha256": "8421cb87f7dc05c2f2adf68e111d3d7be7a53da1952c5b500670d0d9f5fbdca3", "snapshot_path": "sources/8421cb87f7dc05c2f2adf68e111d3d7be7a53da1952c5b500670d0d9f5fbdca3.txt", "url": "https://api.github.com/repos/ktshen/happypatent/license"}, {"fetched_at": "2026-10-28T22:12:10.418723+08:00", "kind": "documentation", "sha256": "8efbb10fd87c09afd18495e0ec167ae483d25d8fa032156300ae29c462b13648", "snapshot_path": "sources/8efbb10fd87c09afd18495e0ec167ae483d25d8fa032156300ae29c462b13648.txt", "url": "https://api.github.com/repos/ktshen/happypatent/contents/proposals/models.py"}, {"fetched_at": "2026-10-28T22:11:41.742821+08:00", "kind": "repository_metadata", "sha256": "e4b02919c357cfbe1ccb00c2a92e9adede0c82239c0ef2cf2a79e9ef1b9f0f22", "snapshot_path": "sources/e4b02919c357cfbe1ccb00c2a92e9adede0c82239c0ef2cf2a79e9ef1b9f0f22.txt", "url": "https://api.github.com/repos/ktshen/happypatent/git/trees/master?recursive=1"}], "summary": "开源的专利与商标代理机构管理系统，Django Web 应用：维护专利/商标案件档案（申请号、优先权、代理人、14 种案件状态），以 ControlEvent 记录控制事项的期限与完成日期，并以 Work 跟踪承办与截止日。", "technology_stack": ["Python", "Django", "PostgreSQL", "Elasticsearch"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1174128093','Legal Hold Manager','{"deployment": ["self-hosted", "docker", "railway"], "features": ["留置记录管理：创建、更新、暂停、解除，含事项名称、触发事件、范围、日期区间", "保管人数据库：联系方式、部门、职位、数据源映射", "留置通知生成与邮件发送（SMTP 或模拟模式）", "逐保管人确认跟踪：待处理、已通知、已确认、逾期", "对未响应保管人的自动重复提醒", "不可变审计日志", "管理员与保管人角色权限"], "github_repository_id": 1174128093, "homepage": "https://github.com/noamrazbuilds/legal-hold-manager", "id": "github:1174128093", "leaf_matches": [{"reason": "README 正文与仓库目录共同证明：按事项创建/签发/暂停/解除留置，管理保管人群体，向每人发送留置通知并记录送达-确认-逾期状态，对未确认者自动提醒，审计日志留存，属完整自托管 Web 应用而非 CLI/SDK/插件；MIT 全文本与仓库身份均由官方接口核对。", "slug": "legal-hold-management", "source_urls": ["https://api.github.com/repos/noamrazbuilds/legal-hold-manager", "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/license", "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/readme", "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/contents/lhm_app/routers"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/license", "name": "Legal Hold Manager", "repository_url": "https://github.com/noamrazbuilds/legal-hold-manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:21:31.798198+08:00", "kind": "repository_metadata", "sha256": "964a9d6293945aa2a84656d2b793be32883885747026109401183271e53c500f", "snapshot_path": "sources/964a9d6293945aa2a84656d2b793be32883885747026109401183271e53c500f.txt", "url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager"}, {"fetched_at": "2026-10-24T22:22:39.580810+08:00", "kind": "license", "sha256": "a0f010d70ebaff736da58170228bb5cec590a82df4842cf4bf86c58d824440f7", "snapshot_path": "sources/a0f010d70ebaff736da58170228bb5cec590a82df4842cf4bf86c58d824440f7.txt", "url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/license"}, {"fetched_at": "2026-10-28T22:11:33.284262+08:00", "kind": "readme", "sha256": "59d2ad2a9537e566abec6334bd3302bacca20e6444a189864b18704875fecc11", "snapshot_path": "sources/59d2ad2a9537e566abec6334bd3302bacca20e6444a189864b18704875fecc11.txt", "url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/readme"}, {"fetched_at": "2026-10-28T22:12:47.577862+08:00", "kind": "documentation", "sha256": "6e984ead2c664fdb12cf7dfb6af9166c4063e9597b50c0dcae2ad96ab74f49fe", "snapshot_path": "sources/6e984ead2c664fdb12cf7dfb6af9166c4063e9597b50c0dcae2ad96ab74f49fe.txt", "url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/contents/lhm_app"}, {"fetched_at": "2026-10-28T22:13:40.481225+08:00", "kind": "documentation", "sha256": "c726dab728cd4d4bf56002c951a7b2fccc07579f2992b50f9b90ed34a49544c2", "snapshot_path": "sources/c726dab728cd4d4bf56002c951a7b2fccc07579f2992b50f9b90ed34a49544c2.txt", "url": "https://api.github.com/repos/noamrazbuilds/legal-hold-manager/contents/lhm_app/routers"}], "summary": "面向法务与法务运营团队的自托管法律留置管理 Web 应用，按事项创建、签发、暂停与解除留置，管理保管人群体，发送留置通知并逐人跟踪送达/确认/逾期状态，含自动提醒、不可变审计日志与管理员/保管人角色。", "technology_stack": ["Python", "FastAPI", "SQLAlchemy", "Streamlit", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:55053239','CodeCompass','{"deployment": ["自托管：CodeCompass_parser 解析项目后由 CodeCompass_webserver 提供 Web UI，数据库可用 SQLite 或 PostgreSQL", "README 指向仓库内 Docker 指南；本轮未构建、部署或实测该镜像", "本轮未运行、构建或部署软件"], "features": ["CodeCompass_parser 依据编译数据库解析项目，把符号、引用与文本索引写入 SQLite/PostgreSQL 数据库", "C++ 与 metrics 解析器支持增量解析，可检测新增/删除/修改文件并更新既有 workspace", "Web UI 的 Definition search 可按定义类型与语言检索源码元素", "Info tree 列出函数/变量/宏在项目中的引用，点击可跳转到引用位置，右键可跳转到定义或查看文档", "调用路径、继承、聚合与 CodeBites 关系图；普通图可导出 SVG 或图片，CodeBites 不支持导出", "同一 Web 服务可切换多个已解析项目，认证与 HTTPS 为可选配置"], "github_repository_id": 55053239, "homepage": "https://codecompass.net", "id": "github:55053239", "leaf_matches": [{"reason": "官方 README 称 CodeCompass 为可插件的代码理解工具，提供 Web UI 与源码元素间快速导航；官网自述面向大型 C/C++/Java 软件，并列有已解析项目与演示入口。doc/usage.md 说明 CodeCompass_parser 依据编译数据库解析项目并把符号、引用与文本索引写入 workspace 关系数据库（SQLite/PostgreSQL，C++ 解析器支持增量解析），CodeCompass_webserver 启动 Web 服务并面向同一 workspace 提供只读浏览。doc/webgui.md 进一步给出 Definition search、Info tree 列出函数/变量/宏在项目中的引用并可跳转到引用位置、右键跳转到定义或查看文档，以及调用路径/继承/聚合/CodeBites 关系图，覆盖语义模型与定义/引用/关系导航两项核心；自托管单实例多项目，符合语料库规模下的读侧目的。", "slug": "code-intelligence-platform", "source_urls": ["https://raw.githubusercontent.com/Ericsson/CodeCompass/master/README.md", "https://raw.githubusercontent.com/Ericsson/CodeCompass/master/doc/usage.md", "https://raw.githubusercontent.com/Ericsson/CodeCompass/master/doc/webgui.md", "https://codecompass.net/"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/Ericsson/CodeCompass/license", "name": "CodeCompass", "repository_url": "https://github.com/Ericsson/CodeCompass", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:25:28.770734+08:00", "kind": "repository_metadata", "sha256": "333ff97950f704cbe3470a712197e83b0e6e81eb2ac1169993fa51cb1c3f9734", "snapshot_path": "sources/333ff97950f704cbe3470a712197e83b0e6e81eb2ac1169993fa51cb1c3f9734.txt", "url": "https://api.github.com/repos/Ericsson/CodeCompass"}, {"fetched_at": "2026-10-28T22:25:38.817872+08:00", "kind": "license", "sha256": "8fe52f40ef190337f22fc66dfc783058bd4fc2c9129838d4f4c69e4ce8764a5f", "snapshot_path": "sources/8fe52f40ef190337f22fc66dfc783058bd4fc2c9129838d4f4c69e4ce8764a5f.txt", "url": "https://api.github.com/repos/Ericsson/CodeCompass/license"}, {"fetched_at": "2026-10-28T22:25:43.418486+08:00", "kind": "readme", "sha256": "405e8374ac4b9a35854d34e5c3774d21b61caa4140f7976c29b3a6705f46bd70", "snapshot_path": "sources/405e8374ac4b9a35854d34e5c3774d21b61caa4140f7976c29b3a6705f46bd70.txt", "url": "https://raw.githubusercontent.com/Ericsson/CodeCompass/master/README.md"}, {"fetched_at": "2026-10-28T22:25:43.588892+08:00", "kind": "documentation", "sha256": "2afc36161fa779b51f4eaa0642ab89323885bfd8d4c54e3f387b5ac00efb710f", "snapshot_path": "sources/2afc36161fa779b51f4eaa0642ab89323885bfd8d4c54e3f387b5ac00efb710f.txt", "url": "https://raw.githubusercontent.com/Ericsson/CodeCompass/master/doc/webgui.md"}, {"fetched_at": "2026-10-28T22:26:29.322533+08:00", "kind": "documentation", "sha256": "6ad4f12722e461c7f0579746a38716728ab309b9c3aacdae0b75ea47cdb65e3b", "snapshot_path": "sources/6ad4f12722e461c7f0579746a38716728ab309b9c3aacdae0b75ea47cdb65e3b.txt", "url": "https://raw.githubusercontent.com/Ericsson/CodeCompass/master/doc/usage.md"}, {"fetched_at": "2026-10-28T22:27:03.760778+08:00", "kind": "homepage", "sha256": "9b365da8057e417764c094ed990e30023a72d11e9d3d5de69b90794f0880a1be", "snapshot_path": "sources/9b365da8057e417764c094ed990e30023a72d11e9d3d5de69b90794f0880a1be.txt", "url": "https://codecompass.net/"}], "summary": "开源代码理解平台：CodeCompass_parser 依据编译数据库为 C/C++ 项目建立符号与引用数据库并可增量解析，自托管 CodeCompass_webserver 提供 Web UI 的定义跳转、引用查看与调用/继承/聚合关系图。", "technology_stack": ["C++", "PostgreSQL", "SQLite"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:12470842','Cerberus Testing','{"deployment": ["INSTALL: self-hosted deployment with Tomcat 9, MySQL 5.6/MariaDB 10.1 and Java JDK 11, or via docker/compositions/cerberus-tomcat-mysql (Keycloak variant included).", "README: Docker images published for MySQL, Tomcat and Tomcat with Keycloak adapter; demo instance at demo.cerberus-testing.com. 本轮未运行或部署。"], "features": ["README: low-code test automation platform supporting Web, iOS, Android and API (REST, SOAP, Kafka) applications.", "README: automated testcases are created through an easy-to-use web interface and grouped into campaigns, scheduled or triggered from Jenkins/Gitlab/Bitbucket with email/Slack notifications.", "features page: low-code test library with modular reusable test steps, requirements management, campaign management and advanced campaign reporting.", "features page: scalable parallel execution across environments, browsers, devices, countries and locations through native execution robots.", "features page: reporting, traceability and replay covering steps, actions, controls, robots and network traffic; screenshots, replay and logging for failed runs.", "features page: network traffic data capture, dynamic test data management and native audit/logging."], "github_repository_id": 12470842, "homepage": "https://cerberus-testing.com", "id": "github:12470842", "leaf_matches": [{"reason": "README 与官网正文说明：以 Web 界面低代码创建自动化测试用例，支持 Web/iOS/Android/API 应用，把用例编入 campaign 后按计划或经 Jenkins/Gitlab/Bitbucket 在 CI/CD 触发，跨环境、浏览器、设备并行执行；features 页列出测试需求管理、可复用步骤模块、Reporting/Traceability/Replay（逐用例结果、失败重跑、截图、回放、日志）与网络流量采集。这对应“被测应用作为整体经真实用户界面驱动 + 持久可复用的测试资产 + 自动执行与逐测试判定及故障证据”。它是 GPL-3.0 完整自托管 Web 应用（INSTALL 要求 Tomcat + MySQL/MariaDB 或 Docker composition），不是纯库/CLI，也不是厂商托管测试云；关系限定于社区版自托管形态。", "slug": "end-to-end-testing-platform", "source_urls": ["https://raw.githubusercontent.com/cerberustesting/cerberus-core/master/README.md", "https://cerberus-testing.com/", "https://cerberus-testing.com/features/", "https://raw.githubusercontent.com/cerberustesting/cerberus-core/master/INSTALL"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/cerberustesting/cerberus-core/license", "name": "Cerberus Testing", "repository_url": "https://github.com/cerberustesting/cerberus-core", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:47:16.627176+08:00", "kind": "repository_metadata", "sha256": "f39fb64c5642c644d118053cdb497bd8d811e62bfd88c8224d4fa87ebc5dab30", "snapshot_path": "sources/f39fb64c5642c644d118053cdb497bd8d811e62bfd88c8224d4fa87ebc5dab30.txt", "url": "https://api.github.com/repos/cerberustesting/cerberus-core"}, {"fetched_at": "2026-10-28T22:47:16.626878+08:00", "kind": "license", "sha256": "9684ec7d6d703bdc6134f5f01df3cf90201e50d53855a84c3f74dac8d4155c9e", "snapshot_path": "sources/9684ec7d6d703bdc6134f5f01df3cf90201e50d53855a84c3f74dac8d4155c9e.txt", "url": "https://api.github.com/repos/cerberustesting/cerberus-core/license"}, {"fetched_at": "2026-10-28T22:47:25.972955+08:00", "kind": "readme", "sha256": "fbe66ca020daeb43c52150e751d15ec16ffa5f8c4a9281e586defb4ff4bbcbd4", "snapshot_path": "sources/fbe66ca020daeb43c52150e751d15ec16ffa5f8c4a9281e586defb4ff4bbcbd4.txt", "url": "https://raw.githubusercontent.com/cerberustesting/cerberus-core/master/README.md"}, {"fetched_at": "2026-10-28T22:49:01.371681+08:00", "kind": "documentation", "sha256": "2c8162110a954560085816213945bdcc13a68821bf4137879b0d0a1db2854f1a", "snapshot_path": "sources/2c8162110a954560085816213945bdcc13a68821bf4137879b0d0a1db2854f1a.txt", "url": "https://raw.githubusercontent.com/cerberustesting/cerberus-core/master/INSTALL"}, {"fetched_at": "2026-10-28T22:47:42.450452+08:00", "kind": "homepage", "sha256": "9b52567756fe3d56641b4e3ccd47279ca53aff291c6d976dfb10b224f93bd082", "snapshot_path": "sources/9b52567756fe3d56641b4e3ccd47279ca53aff291c6d976dfb10b224f93bd082.txt", "url": "https://cerberus-testing.com/"}, {"fetched_at": "2026-10-28T22:48:20.423364+08:00", "kind": "documentation", "sha256": "bf51d99f43b39b96241a8326e9c2b96419643c320e3efc6e030a77ed0f4fa27d", "snapshot_path": "sources/bf51d99f43b39b96241a8326e9c2b96419643c320e3efc6e030a77ed0f4fa27d.txt", "url": "https://cerberus-testing.com/features/"}], "summary": "开源低代码端到端测试平台（GPL-3.0），以 Web 界面创建可复用的自动化测试用例与 campaign，经执行机器人对 Web、移动、API 等应用自动执行，并汇总逐用例判定与失败证据；自托管 Web 应用，非厂商托管云。", "technology_stack": ["Java", "Tomcat", "MySQL / MariaDB", "Docker", "Selenium", "Appium"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:1377867','Locust','{"deployment": ["自托管：安装后执行 `locust` 即在本机 8089 端口启动 Web 界面，浏览器配置被测主机与负载参数。", "可 headless 运行（`locust --headless --users 10 --spawn-rate 1 -H http://your-server.com`）用于 CI/CD。", "分布式：一台 master 加若干 worker，master 承载 Web 界面并汇总统计。", "本轮未安装、未部署、未运行任何测试。"], "features": ["README：以普通 Python 代码（HttpUser 与 @task）编写负载测试，场景可复用、可模块化并纳入版本控制。", "README：可通过命令行或自带 Web UI 运行测试；Web UI 实时展示测试进度，且可在运行中调整负载。", "README：分布式运行，跨多台机器模拟大量并发用户；通过吞吐、响应时间和错误率查看结果并可导出分析。", "官方 Quickstart：在浏览器打开 http://localhost:8089，填写被测主机后以 50 并发用户、1 用户/秒的爬升速率运行；Charts 页展示 RPS、响应时间与运行用户数。", "官方 Distributed 文档：--master 实例运行 Web 界面并指挥用户启停，--worker 实例执行用户并把统计回传 master；亦可用 --processes 单机多进程。"], "github_repository_id": 1377867, "homepage": "https://locust.io/", "id": "github:1377867", "leaf_matches": [{"reason": "README 与官方文档证明三要素齐备并落在可持续使用的自托管应用服务形态上：场景为持久可重跑的 Python 类（HttpUser 与 @task，可版本控制），受控模拟群体由 Web UI 或命令行指定并发用户数与 spawn rate（爬升速率）并可持续调整，执行后实时输出请求数、吞吐（req/s）、响应时间与错误率并可导出分析；文档另述 master/worker 分布式加压，master 运行 Web 界面并指挥 worker 生成用户。与 k6 等本地 CLI 运行器不同，Locust 以常驻 Web 应用形式提供启动、调节与观测负载的完整界面，属于本叶“在线/应用服务”范围而非本地运行器。", "slug": "load-testing-platform", "source_urls": ["https://raw.githubusercontent.com/locustio/locust/master/README.md", "https://docs.locust.io/en/stable/quickstart.html", "https://docs.locust.io/en/stable/running-distributed.html", "https://locust.io/"]}, {"reason": "README 定位为开源性能/负载测试工具，并用 Python 的 HttpUser/task 定义每个模拟用户的行为；Web UI 可启动测试、运行中调整负载，实时显示吞吐、响应时间和错误，且可分布式扩展到多机——对应“负载场景 + 受控模拟群体 + 针对目标的测量结果”的自托管完整应用。", "slug": "performance-testing-application", "source_urls": ["https://raw.githubusercontent.com/locustio/locust/master/README.md", "https://api.github.com/repos/locustio/locust"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/locustio/locust/license", "name": "Locust", "repository_url": "https://github.com/locustio/locust", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:46:34.590031+08:00", "kind": "repository_metadata", "sha256": "4ce6ccb0606107a58a2b7f9daba1981c8af7c6bd80800869a4ff8ab34791049d", "snapshot_path": "sources/4ce6ccb0606107a58a2b7f9daba1981c8af7c6bd80800869a4ff8ab34791049d.txt", "url": "https://api.github.com/repos/locustio/locust"}, {"fetched_at": "2026-10-28T22:46:42.470157+08:00", "kind": "license", "sha256": "73d04221a27d2562ed01c17fc8b6a89eda335afff62dad0e5feea382aff584f1", "snapshot_path": "sources/73d04221a27d2562ed01c17fc8b6a89eda335afff62dad0e5feea382aff584f1.txt", "url": "https://api.github.com/repos/locustio/locust/license"}, {"fetched_at": "2026-10-28T22:46:43.949796+08:00", "kind": "readme", "sha256": "96b40d7ad1e168afc750cf820c5d2136202856e403af5214ce1f017eeebdd6bc", "snapshot_path": "sources/96b40d7ad1e168afc750cf820c5d2136202856e403af5214ce1f017eeebdd6bc.txt", "url": "https://raw.githubusercontent.com/locustio/locust/master/README.md"}, {"fetched_at": "2026-10-28T22:47:50.857139+08:00", "kind": "documentation", "sha256": "94ae443b0586cb9ca5d21e83359236e9f54b12ad094b99fe62ea03ed22ada5c3", "snapshot_path": "sources/94ae443b0586cb9ca5d21e83359236e9f54b12ad094b99fe62ea03ed22ada5c3.txt", "url": "https://docs.locust.io/en/stable/quickstart.html"}, {"fetched_at": "2026-10-28T22:48:07.845476+08:00", "kind": "documentation", "sha256": "5beb38e79b88512bbf8c3759db05b7a6d2567c7030d48e7707ccbadcaa83724b", "snapshot_path": "sources/5beb38e79b88512bbf8c3759db05b7a6d2567c7030d48e7707ccbadcaa83724b.txt", "url": "https://docs.locust.io/en/stable/running-distributed.html"}, {"fetched_at": "2026-10-28T22:47:00.376356+08:00", "kind": "homepage", "sha256": "9a5f73739a9b91d90cb52f2b2e5c2c1b571303ea943c18addba8c2e3b02de4f8", "snapshot_path": "sources/9a5f73739a9b91d90cb52f2b2e5c2c1b571303ea943c18addba8c2e3b02de4f8.txt", "url": "https://locust.io/"}], "summary": "开源自托管负载测试平台：用 Python 代码定义持久可重跑的用户场景，通过自带 Web UI 设置并发用户与爬升速率启动测试，实时查看吞吐、响应时间与错误，并支持 master/worker 分布式加压。", "technology_stack": ["Python", "gevent"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:blazemeter','BlazeMeter','{"homepage": "https://www.blazemeter.com/", "id": "commercial:blazemeter", "leaf_matches": [{"reason": "官方首页自述为性能测试平台，用户描述用户旅程、环境与性能目标后由平台生成并执行相应测试，并提供 CI/CD 性能门禁与统一报告，属于受控负载下的自有系统性能验证。", "slug": "performance-testing-application", "source_urls": ["https://www.blazemeter.com/"]}], "name": "BlazeMeter", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:54:03.631689+08:00", "kind": "homepage", "sha256": "6d7b187601792caa90d55c5dc980ab09a5e73de9c796baf6f036b8b0647dd14a", "snapshot_path": "sources/6d7b187601792caa90d55c5dc980ab09a5e73de9c796baf6f036b8b0647dd14a.txt", "url": "https://www.blazemeter.com/"}], "summary": "商业性能/负载测试服务：在托管平台上描述用户旅程与性能目标，自动生成并执行性能测试，并把性能门禁接入 CI/CD 流水线。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:tricentis-neoload','Tricentis NeoLoad','{"homepage": "https://www.tricentis.com/products/performance-testing-neoload", "id": "commercial:tricentis-neoload", "leaf_matches": [{"reason": "官方产品页描述其为性能与负载测试工具：支持可视化/YAML 设计测试、执行峰值负载测试并通过全球位置动态生成负载，随后做实时仪表盘、SLA 监控与跨版本趋势分析。", "slug": "performance-testing-application", "source_urls": ["https://www.tricentis.com/products/performance-testing-neoload"]}], "name": "Tricentis NeoLoad", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:54:04.393500+08:00", "kind": "homepage", "sha256": "3385d185882e6999af222736045754716d166b474fd930e670cc956a64f8836f", "snapshot_path": "sources/3385d185882e6999af222736045754716d166b474fd930e670cc956a64f8836f.txt", "url": "https://www.tricentis.com/products/performance-testing-neoload"}], "summary": "商业性能/负载测试平台：设计并执行 API、微服务与企业应用的负载测试，按需在全球位置生成峰值负载，并对结果与 SLA 进行分析报告。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:4709330','nGrinder','{"deployment": ["README: start the controller WAR (`java -jar ngrinder-controller-{version}.war`) and access it in a browser at localhost:8080; agents generate load. GitHub 元数据显示仓库已归档（最后推送 2024-10-10），本轮未部署。"], "features": ["README: nGrinder is a platform for stress tests that executes script creation, test execution, monitoring, and result report generation together.", "README: the controller is a web application for creating a test script and configuring a test run; agents are virtual user generators that create load.", "README: web-based interface for project, monitoring, result and report management; multiple tests concurrently; agents deployable across network regions."], "github_repository_id": 4709330, "homepage": "https://naver.github.io/ngrinder/", "id": "github:4709330", "leaf_matches": [{"reason": "README 与官网说明该平台把脚本创建、测试执行、监控和报告同时放在一个 Web 控制器中，由 agent 生成虚拟用户负载并在多区域部署——直接对应性能测试应用的场景、模拟群体与测量结果，且交付形态是完整自托管 Web 应用而非单一 CLI。", "slug": "performance-testing-application", "source_urls": ["https://raw.githubusercontent.com/naver/ngrinder/master/README.md", "https://naver.github.io/ngrinder/", "https://api.github.com/repos/naver/ngrinder"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/naver/ngrinder/license", "name": "nGrinder", "repository_url": "https://github.com/naver/ngrinder", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:52:37.371596+08:00", "kind": "repository_metadata", "sha256": "1041adef8da8247b7804863fa975bc7c1a0b227d89a39dae19ce1b6d61939be8", "snapshot_path": "sources/1041adef8da8247b7804863fa975bc7c1a0b227d89a39dae19ce1b6d61939be8.txt", "url": "https://api.github.com/repos/naver/ngrinder"}, {"fetched_at": "2026-10-28T22:52:44.728545+08:00", "kind": "license", "sha256": "5a00d2e75de437aed6d8cd197a6bbfaa89fa3f5f8652d54d5bfb62ec59b390ea", "snapshot_path": "sources/5a00d2e75de437aed6d8cd197a6bbfaa89fa3f5f8652d54d5bfb62ec59b390ea.txt", "url": "https://api.github.com/repos/naver/ngrinder/license"}, {"fetched_at": "2026-10-28T22:52:47.712507+08:00", "kind": "readme", "sha256": "a7e53a43257ad12342208772ebb3f65944cea7e079d1ac45a4a0106fcc2b9e5a", "snapshot_path": "sources/a7e53a43257ad12342208772ebb3f65944cea7e079d1ac45a4a0106fcc2b9e5a.txt", "url": "https://raw.githubusercontent.com/naver/ngrinder/master/README.md"}, {"fetched_at": "2026-10-28T22:53:15.377362+08:00", "kind": "homepage", "sha256": "cbe96d41f2998b7b035e759b3b26efa8f57dfb429136c3721c9aef830142a39f", "snapshot_path": "sources/cbe96d41f2998b7b035e759b3b26efa8f57dfb429136c3721c9aef830142a39f.txt", "url": "https://naver.github.io/ngrinder/"}], "summary": "开源性能/压力测试平台：Web 控制台创建测试脚本、配置并执行测试，代理节点生成虚拟用户负载，并提供运行监控与结果/报告管理；仓库已归档。", "technology_stack": ["Java", "Jython", "Groovy"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:53501749','DapperDox','{"deployment": ["下载发行版或从源码构建Go程序", "以-spec-dir指向OpenAPI规范目录启动，默认在3123端口提供服务"], "features": ["OpenAPI/Swagger参考文档生成", "内置文档服务器", "GitHub风格Markdown指南叠加", "多规范组合为交叉引用的文档套件", "内置API浏览器与主题定制"], "github_repository_id": 53501749, "homepage": "http://dapperdox.io", "id": "github:53501749", "leaf_matches": [{"reason": "README说明DapperDox是面向OpenAPI(Swagger)规范的文档生成器、服务器和API浏览器，运行后从规范目录构建并提供可浏览的参考文档，可叠加Markdown指南、组合多个规范；这证明其作为自托管持续运行的文档站点服务形态，而非单纯客户端渲染库。", "slug": "api-documentation-platform", "source_urls": ["https://raw.githubusercontent.com/DapperDox/dapperdox/master/README.md"]}], "license": "GPL-3.0", "license_evidence_url": "https://api.github.com/repos/DapperDox/dapperdox/license", "name": "DapperDox", "repository_url": "https://github.com/DapperDox/dapperdox", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:59:50.539116+08:00", "kind": "repository_metadata", "sha256": "7ab6728877e8529d505d0baa80c504ec6af20f6f45ab36467248624069d8a007", "snapshot_path": "sources/7ab6728877e8529d505d0baa80c504ec6af20f6f45ab36467248624069d8a007.txt", "url": "https://api.github.com/repos/DapperDox/dapperdox"}, {"fetched_at": "2026-10-28T23:00:04.643022+08:00", "kind": "license", "sha256": "db82b87113c9c1d856c56cc110cfa5ef2adb20890901c8d09ce6a8896926c287", "snapshot_path": "sources/db82b87113c9c1d856c56cc110cfa5ef2adb20890901c8d09ce6a8896926c287.txt", "url": "https://api.github.com/repos/DapperDox/dapperdox/license"}, {"fetched_at": "2026-10-28T23:00:02.325744+08:00", "kind": "readme", "sha256": "4d2e1825a828fd0dbbef9b8291fb509afea3e5010ee44cf34e74745076d5364b", "snapshot_path": "sources/4d2e1825a828fd0dbbef9b8291fb509afea3e5010ee44cf34e74745076d5364b.txt", "url": "https://raw.githubusercontent.com/DapperDox/dapperdox/master/README.md"}], "summary": "开源自托管的OpenAPI文档生成器与文档服务器：从OpenAPI/Swagger规范构建可浏览的接口参考，并提供Markdown指南叠加、多规范组合与内置API浏览器。", "technology_stack": ["Go", "OpenAPI"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:843437350','Zudoku','{"deployment": ["npm create zudoku@latest 创建项目，npm run build 生成静态产物", "可部署到自有服务器或 Vercel、Netlify、Cloudflare Pages、GitHub Pages 等托管服务"], "features": ["从单个或多个OpenAPI文档生成接口参考", "MDX指南页面", "开发者门户与用户鉴权", "集成API调试台", "静态站点构建与自托管部署"], "github_repository_id": 843437350, "homepage": "https://zudoku.dev", "id": "github:843437350", "leaf_matches": [{"reason": "README说明Zudoku从单个或多个OpenAPI schema生成文档，以可浏览参考文档为核心并支持MDX指南、鉴权与集成调试；部署文档说明构建静态产物后发布到自有服务器或托管服务，且可作独立文档站点或开发者门户，属于完整的自托管Web文档应用形态而非仅嵌入式渲染组件。", "slug": "api-documentation-platform", "source_urls": ["https://raw.githubusercontent.com/zuplo/zudoku/main/README.md", "https://zudoku.dev/docs/quickstart", "https://zudoku.dev/docs/deployment"]}], "license": "MIT", "license_evidence_url": "https://api.github.com/repos/zuplo/zudoku/license", "name": "Zudoku", "repository_url": "https://github.com/zuplo/zudoku", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T22:58:04.423081+08:00", "kind": "repository_metadata", "sha256": "42ead0c5b497abd2be56b17d3a65a41b89c474c8cc3d336fc26082fa37326f3c", "snapshot_path": "sources/42ead0c5b497abd2be56b17d3a65a41b89c474c8cc3d336fc26082fa37326f3c.txt", "url": "https://api.github.com/repos/zuplo/zudoku"}, {"fetched_at": "2026-10-28T22:58:25.533298+08:00", "kind": "license", "sha256": "1bcc879f9f5ca3b1dbb7a65b6f595df3cb2564c6ad377ab4cd710e9c7ae86969", "snapshot_path": "sources/1bcc879f9f5ca3b1dbb7a65b6f595df3cb2564c6ad377ab4cd710e9c7ae86969.txt", "url": "https://api.github.com/repos/zuplo/zudoku/license"}, {"fetched_at": "2026-10-28T22:58:23.115856+08:00", "kind": "readme", "sha256": "018470e12ecb760687d62ac2498f36511558b83edd2d23f57439f22c2a415c67", "snapshot_path": "sources/018470e12ecb760687d62ac2498f36511558b83edd2d23f57439f22c2a415c67.txt", "url": "https://raw.githubusercontent.com/zuplo/zudoku/main/README.md"}, {"fetched_at": "2026-10-28T22:58:53.105135+08:00", "kind": "documentation", "sha256": "fd46002716b65fa6b96d638053981052775c076686fa7c386070f4a577b0953b", "snapshot_path": "sources/fd46002716b65fa6b96d638053981052775c076686fa7c386070f4a577b0953b.txt", "url": "https://zudoku.dev/docs/quickstart"}, {"fetched_at": "2026-10-28T22:58:50.712333+08:00", "kind": "documentation", "sha256": "56f22665097cd604f1aa8cc9bcbe11c6006f95512532f4b9e315332d00bbec04", "snapshot_path": "sources/56f22665097cd604f1aa8cc9bcbe11c6006f95512532f4b9e315332d00bbec04.txt", "url": "https://zudoku.dev/docs/deployment"}], "summary": "开源的API文档站点/开发者门户框架：从单个或多个OpenAPI文档生成可浏览的接口参考，配合MDX页面、鉴权和在线调试，构建后发布到自有服务器或静态托管。", "technology_stack": ["TypeScript", "React", "OpenAPI", "MDX"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:194645908','Apache APISIX Dashboard','{"deployment": ["内嵌于 Apache APISIX，默认启用", "可独立构建部署，需配置 Admin API Key"], "features": ["图形化配置路由", "插件配置", "上游服务管理", "经 Admin API 操作 APISIX"], "github_repository_id": 194645908, "homepage": "https://apisix.apache.org/", "id": "github:194645908", "leaf_matches": [{"reason": "官方文档正文说明 APISIX Dashboard 是对 APISIX 的直观 Web 管理界面，可图形化配置 routes、plugins、upstream services，并通过 Admin API 与 APISIX 交互，符合网关控制面控制台核心。", "slug": "api-gateway-management-console", "source_urls": ["https://apisix.apache.org/docs/dashboard/USER_GUIDE/", "https://raw.githubusercontent.com/apache/apisix-dashboard/master/README.md", "https://api.github.com/repos/apache/apisix-dashboard"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/apache/apisix-dashboard/license", "name": "Apache APISIX Dashboard", "repository_url": "https://github.com/apache/apisix-dashboard", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:04:44.348861+08:00", "kind": "repository_metadata", "sha256": "b6dd38743126c488d4cf20d9418ce1c3bf0d3fb3b1722f9e46b1ef5e778e0f99", "snapshot_path": "sources/b6dd38743126c488d4cf20d9418ce1c3bf0d3fb3b1722f9e46b1ef5e778e0f99.txt", "url": "https://api.github.com/repos/apache/apisix-dashboard"}, {"fetched_at": "2026-10-28T23:04:53.986163+08:00", "kind": "readme", "sha256": "91ec051f55261d6b7298950ad559c14a1329e216b99067032099251e3d73320c", "snapshot_path": "sources/91ec051f55261d6b7298950ad559c14a1329e216b99067032099251e3d73320c.txt", "url": "https://raw.githubusercontent.com/apache/apisix-dashboard/master/README.md"}, {"fetched_at": "2026-10-28T23:04:57.112432+08:00", "kind": "license", "sha256": "c7c6943ab4e75e898ca4acc57c5ce1c46585fae89ca22a5c2fe391be8c3855f7", "snapshot_path": "sources/c7c6943ab4e75e898ca4acc57c5ce1c46585fae89ca22a5c2fe391be8c3855f7.txt", "url": "https://api.github.com/repos/apache/apisix-dashboard/license"}, {"fetched_at": "2026-10-28T23:05:13.608770+08:00", "kind": "documentation", "sha256": "8a88215b2ba5071d96f82394cecf7304b9e74bf26cfba2036afac8906ebd7bac", "snapshot_path": "sources/8a88215b2ba5071d96f82394cecf7304b9e74bf26cfba2036afac8906ebd7bac.txt", "url": "https://apisix.apache.org/docs/dashboard/USER_GUIDE/"}], "summary": "Apache APISIX 的开源 Web 管理控制台，通过图形界面配置路由、插件与上游服务，经 Admin API 作用于 APISIX 网关。", "technology_stack": ["TypeScript", "React", "Apache APISIX Admin API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:656052275','Kong Manager OSS','{"deployment": ["随 Kong Gateway 一起提供", "可本地或公网服务器部署（需限制 8001/8002 端口访问）"], "features": ["查看与编辑 Kong Gateway 对象", "Service 与 Route 配置", "插件配置界面", "经 Admin API 读写网关配置"], "github_repository_id": 656052275, "homepage": "https://github.com/Kong/kong-manager", "id": "github:656052275", "leaf_matches": [{"reason": "官方 README 明确其为 Kong Gateway 的免费开源 UI：通过 Admin API 查看和编辑全部 Kong 对象，可查看/编辑 service 上的 route 与 plugin 配置，属于作用于网关运行时的控制面控制台。", "slug": "api-gateway-management-console", "source_urls": ["https://raw.githubusercontent.com/Kong/kong-manager/main/README.md", "https://api.github.com/repos/Kong/kong-manager"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/Kong/kong-manager/license", "name": "Kong Manager OSS", "repository_url": "https://github.com/Kong/kong-manager", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:04:45.423934+08:00", "kind": "repository_metadata", "sha256": "fa1227c045db2e7eb0c270efe3dc1e494fbc2c75a245384176e6f2ff90640c0f", "snapshot_path": "sources/fa1227c045db2e7eb0c270efe3dc1e494fbc2c75a245384176e6f2ff90640c0f.txt", "url": "https://api.github.com/repos/Kong/kong-manager"}, {"fetched_at": "2026-10-28T23:05:13.312852+08:00", "kind": "readme", "sha256": "252bc90c07beb87e9a348d4ce211fb6eb8636ba2a62f2a36a5656e74a82a8347", "snapshot_path": "sources/252bc90c07beb87e9a348d4ce211fb6eb8636ba2a62f2a36a5656e74a82a8347.txt", "url": "https://raw.githubusercontent.com/Kong/kong-manager/main/README.md"}, {"fetched_at": "2026-10-28T23:05:15.325485+08:00", "kind": "license", "sha256": "c7b42782591b46b49a24140b51589d45bfb99bf9d451f232b6557562ab9aef3b", "snapshot_path": "sources/c7b42782591b46b49a24140b51589d45bfb99bf9d451f232b6557562ab9aef3b.txt", "url": "https://api.github.com/repos/Kong/kong-manager/license"}], "summary": "Kong Gateway 的官方开源管理控制台，通过 Admin API 查看与编辑网关的 service、route、plugin 等对象配置。", "technology_stack": ["JavaScript", "Vue", "Kong Admin API"], "track": "open_source", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('commercial:aws-transform','AWS Transform','{"homepage": "https://aws.amazon.com/transform/", "id": "commercial:aws-transform", "leaf_matches": [{"reason": "官方页面称其为覆盖“从迁移到持续现代化”全生命周期的转型工作台，自动化现有应用（Windows、大型机、自定义代码）的分析、规划、文档与转换任务，并持续分析修复技术债、批量转换数百个应用，对应定义核心中的评估、转换执行与跟踪。", "slug": "application-modernization-platform", "source_urls": ["https://aws.amazon.com/transform/"]}], "name": "AWS Transform", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:19:35.734837+08:00", "kind": "homepage", "sha256": "85a25f2be12f42736c960333f12781db5224f40ef9f1f16da10c9d021d17c135", "snapshot_path": "sources/85a25f2be12f42736c960333f12781db5224f40ef9f1f16da10c9d021d17c135.txt", "url": "https://aws.amazon.com/transform/"}], "summary": "AWS 的企业 IT 转型工作台：面向现有应用组合提供评估与规划、迁移及 Windows/大型机/自定义代码现代化，并持续分析、修复技术债，跟踪转换工作到交付结果。", "track": "commercial", "verification_status": "official_sources_reviewed"}');
INSERT INTO "application" VALUES('github:460571962','Konveyor Hub','{"deployment": ["Kubernetes/OpenShift 上通过 Konveyor Operator（OLM）自托管部署", "Hub 服务以容器镜像发布（quay.io/konveyor/tackle2-hub）", "Web UI 以容器化 Node.js 应用运行并代理 Hub API"], "features": ["现有应用清单、业务服务关联与依赖建模", "问卷式评估，输出迁移风险与采用计划", "源码/二进制静态分析（集成 Windup/analyzer）并生成问题清单与工作量估计", "迁移波次规划与迁移工作排序", "Hub task manager 编排分析任务并跟踪任务结果", "配合 Konveyor AI 按分析结果生成并应用代码修复建议"], "github_repository_id": 460571962, "homepage": "https://konveyor.io/", "id": "github:460571962", "leaf_matches": [{"reason": "官方站点自称开源项目，提供对既有传统应用 re-platform 与 refactor 的可见性、分析与转换工具；Hub 组件页与文档正文给出完整链条：应用清单/依赖与业务服务关联→问卷式评估输出风险与采用计划→源码/二进制静态分析（集成 Windup）给出问题清单与工作量估计→以 Migration waves 规划并排序迁移工作、由 task manager 编排分析任务→Kantra 与 Konveyor AI 依据分析结果产出并应用代码改动，人工审阅后接受，符合“现有资产—结构化评估—每应用路径—跟踪转换到改动交付物”的定义核心；Hub 为可自托管的核心应用服务（Operator/OLM 部署），UI 与 operator 同属该平台。", "slug": "application-modernization-platform", "source_urls": ["https://konveyor.io/", "https://konveyor.io/components/konveyor-hub", "https://konveyor.io/docs/konveyor/", "https://konveyor.io/docs/konveyor/assessanalyze/", "https://konveyor.io/docs/konveyor/installation/", "https://konveyor.io/docs/konveyor/kai/runanalysis/proc_apply-rag-resolution/", "https://raw.githubusercontent.com/konveyor/tackle2-hub/main/README.md", "https://raw.githubusercontent.com/konveyor/tackle2-ui/main/README.md"]}], "license": "Apache-2.0", "license_evidence_url": "https://api.github.com/repos/konveyor/tackle2-hub/license", "name": "Konveyor Hub", "repository_url": "https://github.com/konveyor/tackle2-hub", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-28T23:17:08.526301+08:00", "kind": "homepage", "sha256": "aaf44fcd67267a8bb774c41a1be7c3ee49d575013ad76f016121dc1b1dd5c513", "snapshot_path": "sources/aaf44fcd67267a8bb774c41a1be7c3ee49d575013ad76f016121dc1b1dd5c513.txt", "url": "https://konveyor.io/"}, {"fetched_at": "2026-10-28T23:17:51.995458+08:00", "kind": "documentation", "sha256": "3441810d93e994e55eae97250d197