INSERT INTO "application" VALUES('github:281073868','Baserow','{"deployment": ["官方 README 提供 Docker、Docker Compose、Helm 等自托管方式", "官方提供云托管版本"], "features": ["无代码数据库与表格/视图", "应用构建器：页面、元素、数据源与事件", "预览与发布到默认子域名或自定义域名", "用户源与元素级可见性控制", "自动化与 API"], "github_repository_id": 281073868, "homepage": "https://baserow.io", "id": "github:281073868", "leaf_matches": [{"reason": "官方文档说明 Application Builder 以数据库表为数据源，用页面、元素、事件组装应用，经预览/发布到子域名或自定义域名供指定受众使用；后端 backend/src/baserow/contrib/builder 与前端 web-frontend/modules/builder 均位于 MIT 核心目录，premium/ 仅含 AI、分组聚合数据源、去 logo 等附加付费项，故按社区核心收录应用构建器本体。", "slug": "no-code-application-builder", "source_urls": ["https://baserow.io/user-docs/application-builder-overview", "https://raw.githubusercontent.com/baserow/baserow/develop/backend/src/baserow/contrib/builder/application_types.py", "https://raw.githubusercontent.com/baserow/baserow/develop/premium/web-frontend/modules/baserow_premium/paidFeatures.js", "https://raw.githubusercontent.com/baserow/baserow/master/README.md"]}], "license": "MIT", "license_evidence_url": "https://raw.githubusercontent.com/baserow/baserow/develop/LICENSE", "license_review": {"rationale": "仓库 LICENSE 对 premium/ 与 enterprise/ 之外的内容授予 MIT Expat；本轮确认应用构建器后端 backend/src/baserow/contrib/builder 与前端 web-frontend/modules/builder 均在该 MIT 核心内，premium/LICENSE 只约束 premium/ 与 enterprise/ 目录，因此按社区核心（应用构建器本体）认定，不声称 premium 附加功能开源。", "reviewer": "collector", "scope": "community_core", "source_url": "https://raw.githubusercontent.com/baserow/baserow/develop/LICENSE", "spdx_id": "MIT"}, "name": "Baserow", "repository_url": "https://github.com/baserow/baserow", "runtime_tested": false, "sources": [{"fetched_at": "2026-10-24T22:33:36.338291+08:00", "kind": "repository_metadata", "sha256": "ab0b704a8a3594467ebe2ddb048e82f063eb706561ff37da415ee54b5b872a60", "snapshot_path": "sources/ab0b704a8a3594467ebe2ddb048e82f063eb706561ff37da415ee54b5b872a60.txt", "url": "https://api.github.com/repos/baserow/baserow"}, {"fetched_at": "2026-10-24T22: